INSERT INTO public.exercises VALUES ('6035f105-290e-4378-a4c9-5673a3e5b1b3', 'Curl V-Bar au Poulie Basse', NULL, NULL, 'Low Cable Curl V-Bar', 'Biceps', '[]', 'Biceps', 'Beginner', 4, '/videos/biceps/low-cable-curl-v-bar.mp4', NULL, NULL, NULL, '/videos/thumbnails/low-cable-curl-v-bar.jpg', NULL, '["Engagez bien votre ceinture abdominale, évitez de balancer ou d''utiliser l''élan pour soulever le poids", "Concentrez-vous sur la contraction de vos biceps au sommet du mouvement pour une activation musculaire maximale", "Gardez une tension constante sur le câble durant tout l''arc de mouvement", "Optez pour un tempo contrôlé avec 2 secondes pour lever et 3 secondes pour abaisser le poids", "Évitez de laisser vos coudes avancer ou reculer pendant le curl"]', '["Ne pas engager le tronc", "Utiliser l''élan pour soulever le poids"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "cable", "low cable curl v-bar"]', true, '2026-04-03 12:24:57.612152+00', '2026-04-03 12:24:57.612152+00', 'Position de départ : Face à un poulie basse avec un V-bar. Execution : Pliez les coudes pour ramener le V-bar vers vos épaules, puis redescendez de manière contrôlée.', '["Ne pas engager le tronc", "Utiliser l''élan pour soulever le poids"]', true, '["Attach the V-bar to the low pulley and select an appropriate weight", "Stand with feet shoulder-width apart, maintaining a slight bend in your knees for stability", "Grasp the V-bar with both hands using a neutral grip, keeping your wrists straight and strong", "Keep your elbows pinned to your sides throughout the entire movement", "Curl the weight up by contracting your biceps until your forearms are nearly vertical", "Lower the weight slowly and under control, maintaining tension in the biceps throughout the descent"]', '["Fixez le V-bar à la poulie basse et choisissez un poids adapté", "Positionnez-vous les pieds écartés à la largeur des épaules, avec une légère flexion des genoux pour la stabilité", "Saisissez le V-bar avec les deux mains en prise neutre, gardez les poignets droits et solides", "Gardez les coudes collés à vos côtés tout au long du mouvement", "Ramenez le poids vers le haut en contractant vos biceps jusqu''à ce que vos avant-bras soient presque verticaux", "Abaissez le poids lentement et sous contrôle, tout en maintenant la tension dans les biceps pendant la descente"]', '["Engagez bien votre ceinture abdominale, évitez de balancer ou d''utiliser l''élan pour soulever le poids", "Concentrez-vous sur la contraction de vos biceps au sommet du mouvement pour une activation musculaire maximale", "Gardez une tension constante sur le câble durant tout l''arc de mouvement", "Optez pour un tempo contrôlé avec 2 secondes pour lever et 3 secondes pour abaisser le poids", "Évitez de laisser vos coudes avancer ou reculer pendant le curl"]', '["Keep your core engaged and avoid swaying or using momentum to lift the weight", "Focus on squeezing your biceps at the top of the movement for maximum muscle activation", "Maintain constant tension on the cable throughout the entire range of motion", "Use a controlled tempo with a 2-second lift and 3-second lowering phase", "Avoid letting your elbows drift forward or backward during the curl"]', 'cf8eef3a-8539-410a-9dac-da29caf914d6', 'low-cable-curl-v-bar', NULL, NULL);
INSERT INTO public.exercises VALUES ('f673ba96-d63d-4679-b9f1-7b9072876f7e', 'Curl couché avec barre EZ', NULL, NULL, 'Lying EZ Bar Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 1, '/videos/biceps/lying-ez-bar-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-ez-bar-curl.jpg', NULL, '["Garde tes bras supérieurs immobiles pour bien isoler les biceps", "Utilise les prises inclinées de la barre EZ pour réduire la tension sur les poignets par rapport à une barre droite", "Contrôle la descente pour maximiser l''activation musculaire et éviter les blessures", "Ne descends pas la barre trop bas derrière ta tête pour prévenir les tensions aux épaules", "Commence avec des poids plus légers pour maîtriser la technique avant de passer à des charges plus lourdes"]', '["Ne pas isoler les biceps en bougeant les bras supérieurs", "Utiliser trop de poids et perdre le contrôle du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "barbell", "lying ez bar curl"]', true, '2026-04-03 12:24:57.712566+00', '2026-04-03 12:24:57.712566+00', 'Allonge-toi sur un banc plat, prend la barre EZ en main, bras tendus vers le haut. Fléchis tes coudes pour amener la barre vers ton front, puis tends à nouveau les bras pour revenir à la position de départ.', '["Ne pas isoler les biceps en bougeant les bras supérieurs", "Utiliser trop de poids et perdre le contrôle du mouvement"]', true, '["Lie flat on a bench with feet planted firmly on the floor for stability", "Grip the EZ bar with an underhand grip, hands positioned on the angled portions of the bar", "Extend arms overhead with the bar positioned above your chest, maintaining a slight bend in your elbows", "Slowly curl the bar toward your forehead by bending at the elbows while keeping upper arms still", "Squeeze your biceps at the top of the movement, then slowly lower the bar back to starting position", "Maintain control throughout the entire range of motion without using momentum"]', '["Allonge-toi sur un banc plat avec les pieds bien ancrés au sol pour plus de stabilité", "Prends la barre EZ avec une prise inversée, les mains sur les portions inclinées de la barre", "Tends les bras au-dessus de ta poitrine, en gardant une légère flexion au niveau des coudes", "Enroule lentement la barre vers ton front en fléchissant les coudes, sans bouger les bras supérieurs", "Contracte tes biceps au sommet du mouvement, puis abaisse lentement la barre jusqu''à la position de départ", "Garde le contrôle tout au long du mouvement, sans utiliser d''élan"]', '["Garde tes bras supérieurs immobiles pour bien isoler les biceps", "Utilise les prises inclinées de la barre EZ pour réduire la tension sur les poignets par rapport à une barre droite", "Contrôle la descente pour maximiser l''activation musculaire et éviter les blessures", "Ne descends pas la barre trop bas derrière ta tête pour prévenir les tensions aux épaules", "Commence avec des poids plus légers pour maîtriser la technique avant de passer à des charges plus lourdes"]', '["Keep your upper arms stationary throughout the movement to isolate the biceps effectively", "Use the angled grips of the EZ bar to reduce wrist strain compared to a straight barbell", "Control the eccentric lowering phase for maximum muscle activation and safety", "Avoid lowering the bar too far past your head to prevent shoulder strain", "Start with lighter weight to master the form before progressing to heavier loads"]', 'fd2a8e1f-3efb-4e11-89fb-a479b7bf4a06', 'lying-ez-bar-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('8b28b067-c809-4ad0-8367-94132cee3b59', 'Élévations de mollets avec barre', NULL, 'رفعات السمانة بالبار', 'Barbell calf raises', 'Calves', '[]', 'Calves', 'Beginner', 1, '/videos/calves/barbell-calf-raises.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-calf-raises.jpg', NULL, '["Utilise toute l''amplitude de mouvement pour un étirement profond en bas et une contraction maximale en haut.", "Réalise le mouvement lentement et de manière contrôlée pour maximiser la tension musculaire et éviter les blessures.", "Assure-toi que la plateforme soit stable et antidérapante pour garder l''équilibre avec la barre chargée.", "Commence par un poids plus léger pour maîtriser l''équilibre et la forme avant d''ajouter progressivement des charges."]', '["Ne pas garder le torse droit, ce qui peut causer des blessures au dos.", "Utiliser un poids trop lourd provoquant une mauvaise forme et un risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["calves", "barbell", "barbell calf raises"]', true, '2026-04-03 12:24:55.528646+00', '2026-04-03 12:24:55.528646+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, avec une barre fixée sur le haut de ton dos, comme pour un squat arrière. Place la plante de tes pieds sur une surface stable. Exécution : Monte sur la pointe des pieds en contractant tes mollets pour soulever tes talons au maximum. Fais une courte pause en sommet, puis abaisse lentement tes talons en dessous de la position de départ pour un étirement complet.', '["Ne pas garder le torse droit, ce qui peut causer des blessures au dos.", "Utiliser un poids trop lourd provoquant une mauvaise forme et un risque de blessure."]', true, '["Position the barbell securely on your upper back using proper rack positioning and ensure the safety bars are set at an appropriate height", "Maintain an upright torso with core engaged and knees slightly bent throughout the movement", "Rise up smoothly by pushing through the balls of your feet until you reach maximum heel height", "Hold the peak contraction briefly, then lower your heels slowly below the platform level for a full stretch", "Keep your weight balanced and avoid bouncing at the bottom of the movement"]', '["Assure-toi que la barre est bien positionnée sur le haut de ton dos et que les barres de sécurité sont réglées à la bonne hauteur.", "Garde le torse droit, le ventre engagé et les genoux légèrement fléchis pendant l''exercice.", "Pousse sur la plante des pieds jusqu''à atteindre la hauteur maximale des talons.", "Maintiens la contraction au sommet puis abaisse lentement tes talons en dessous du niveau de la plateforme pour un étirement complet.", "Équilibre ton poids et évite de rebondir en bas du mouvement."]', '["Utilise toute l''amplitude de mouvement pour un étirement profond en bas et une contraction maximale en haut.", "Réalise le mouvement lentement et de manière contrôlée pour maximiser la tension musculaire et éviter les blessures.", "Assure-toi que la plateforme soit stable et antidérapante pour garder l''équilibre avec la barre chargée.", "Commence par un poids plus léger pour maîtriser l''équilibre et la forme avant d''ajouter progressivement des charges."]', '["Use a full range of motion by getting a deep stretch at the bottom and maximum contraction at the top", "Keep the movement slow and controlled to maximize muscle tension and prevent injury", "Ensure the platform is stable and non-slip to maintain balance with the loaded barbell", "Start with lighter weight to master the balance and form before progressively adding load"]', 'b853fd08-4739-4239-a825-8c31826d54ba', 'barbell-calf-raises', NULL, NULL);
INSERT INTO public.exercises VALUES ('4ded82f2-07de-4a61-9a61-8e3264bbf520', 'Élévations Frontales avec Barre', NULL, 'رفع الجبهة بالبار', 'Barbell Front Raise', 'Shoulders', '[]', 'Shoulders', 'Beginner', 1, '/videos/shoulders/barbell-front-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-front-raise.jpg', NULL, '["Engage bien ton gainage pour éviter de creuser le dos.", "Choisis un poids qui te permet de garder le contrôle - n''utlise pas l''élan.", "Arrête à la hauteur des épaules pour éviter les douleurs.", "Garde une colonne vertébrale neutre, ne te penche pas en arrière lors de la montée.", "Concentre-toi sur un mouvement fluide et contrôlé, aussi bien à la montée qu''à la descente."]', '["Utiliser un poids trop lourd et se laisser aller au balancement.", "Ne pas engager son core, ce qui peut mener à un creux du dos."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "barbell", "barbell front raise"]', true, '2026-04-03 12:24:55.554909+00', '2026-04-03 12:24:55.554909+00', 'Cet exercice cible principalement les épaules et renforce ta partie supérieure du corps.', '["Utiliser un poids trop lourd et se laisser aller au balancement.", "Ne pas engager son core, ce qui peut mener à un creux du dos."]', true, '["Stand with feet hip-width apart, holding a barbell with an overhand grip, hands shoulder-width apart, arms extended down in front of your thighs", "Engage your core and maintain a slight bend in your knees with shoulders pulled back and down", "Keeping your arms straight with a slight elbow bend, slowly lift the barbell forward and up until it reaches shoulder height", "Pause briefly at the top position, then slowly lower the barbell back to the starting position with control", "Repeat for desired repetitions while maintaining proper form throughout the movement"]', '["Positionne-toi avec les pieds écartés à la largeur des hanches, prends la barre avec une prise pronée, mains à la largeur des épaules, bras tendus devant tes cuisses.", "Engage ton gainage et garde une légère flexion dans les genoux, en tirant les épaules vers l''arrière et vers le bas.", "Avec les bras droits et une légère flexion des coudes, soulève lentement la barre vers l''avant jusqu''à atteindre la hauteur des épaules.", "Fais une petite pause en haut puis abaisse la barre lentement et en contrôle jusqu''à la position de départ.", "Répète le mouvement pour le nombre de répétitions souhaité tout en gardant une bonne technique."]', '["Engage bien ton gainage pour éviter de creuser le dos.", "Choisis un poids qui te permet de garder le contrôle - n''utlise pas l''élan.", "Arrête à la hauteur des épaules pour éviter les douleurs.", "Garde une colonne vertébrale neutre, ne te penche pas en arrière lors de la montée.", "Concentre-toi sur un mouvement fluide et contrôlé, aussi bien à la montée qu''à la descente."]', '["Keep your core engaged throughout to prevent arching your back", "Use a weight that allows you to maintain control - avoid swinging or using momentum", "Stop at shoulder height to prevent shoulder impingement", "Maintain a neutral spine and avoid leaning backward during the lift", "Focus on smooth, controlled movement both up and down"]', '069c1e6b-05f4-4390-a1c7-9b740e0bec4a', 'barbell-front-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('d423301a-5b97-455b-b078-b4ab2b9abb8a', 'Développe ton haut de poitrine avec le développé couché incliné', NULL, NULL, 'Barbell Incline Bench Press - Medium Grip', 'Chest', '[]', 'Chest', 'Beginner', 1, '/videos/chest/barbell-incline-bench-press-medium-grip.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-incline-bench-press-medium-grip.jpg', NULL, '["Cible le haut de la poitrine", "Ne rends pas le banc trop incliné (sinon ça devient un développé épaule)", "Garde les épaules bien en arrière", "Touchez la poitrine sans rebondir", "Contrôle bien la descente"]', '["Ne pas maintenir une bonne posture", "Lâcher la barre trop rapidement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "barbell", "barbell incline bench press - medium grip"]', true, '2026-04-03 12:24:55.59098+00', '2026-04-03 12:24:55.59098+00', 'Position de départ : Allonge-toi sur un banc incliné à 30-45 degrés, les pieds bien à plat au sol. Prends la barre avec une prise légèrement plus large que les épaules. Exécution : Abaisse la barre de manière contrôlée jusqu''à ton haut de poitrine, puis pousse-la vers le haut pour revenir à la position de départ tout en maintenant une bonne posture.', '["Ne pas maintenir une bonne posture", "Lâcher la barre trop rapidement"]', true, '["Set bench to 30-45 degrees", "Lie back, grip bar slightly wider than shoulders", "Unrack, position bar over upper chest", "Lower to upper chest/clavicle area", "Press up with control"]', '["Règle le banc à 30-45 degrés", "Allonge-toi, prise de la barre légèrement plus large que les épaules", "Déplace la barre au-dessus de ton haut de poitrine", "Abaisse la barre jusqu''au haut de la poitrine/clavicule", "Pousse avec contrôle vers le haut"]', '["Cible le haut de la poitrine", "Ne rends pas le banc trop incliné (sinon ça devient un développé épaule)", "Garde les épaules bien en arrière", "Touchez la poitrine sans rebondir", "Contrôle bien la descente"]', '["Targets upper chest", "Don''t set bench too steep (becomes shoulder press)", "Keep shoulder blades retracted", "Touch chest, don''t bounce", "Control the negative"]', 'de7f1e4f-cb03-446d-b768-4a93baae1ab2', 'barbell-incline-bench-press-medium-grip', NULL, NULL);
INSERT INTO public.exercises VALUES ('003d61ca-5cd3-4bb6-8ccc-9d36f48ab34a', 'Curl EZ assis', NULL, NULL, 'Seated EZ Bar Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 1, '/videos/biceps/seated-ez-bar-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-ez-bar-curl.jpg', NULL, '["Garde les poignets droits et une prise ferme pendant tout le mouvement", "Évite de te balancer ou d''utiliser ton dos pour soulever le poids", "Contrôle la descente pour maximiser l''engagement musculaire", "Garde les coudes fixes et près des côtés tout au long de l''exercice"]', '["Se balancer pour soulever la barre", "Écarter les coudes loin du corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "barbell", "seated ez bar curl"]', true, '2026-04-03 12:24:58.822568+00', '2026-04-03 12:24:58.822568+00', 'Position de départ : Assis sur un banc, prends une barre EZ à deux mains, paumes vers le haut. Exécution : Fléchis les coudes pour lever la barre vers les épaules, puis redescends lentement.', '["Se balancer pour soulever la barre", "Écarter les coudes loin du corps"]', true, '["Sit on a bench with feet flat on the floor, holding an EZ bar with an underhand grip, hands shoulder-width apart", "Keep your back straight against the bench and let your arms hang naturally at your sides with elbows close to your torso", "Slowly curl the bar upward by contracting your biceps, keeping your upper arms stationary", "Squeeze your biceps at the top of the movement when the bar reaches chest level", "Lower the bar in a controlled manner back to the starting position", "Repeat for desired repetitions without swinging or using momentum"]', '["Assieds-toi sur un banc, les pieds bien à plat au sol, en tenant une barre EZ avec une prise en supination, mains espacées d''épaules", "Garde le dos droit contre le banc et laisse les bras pendre naturellement sur les côtés, coudes près du torse", "Cesse de contracter les biceps pour faire monter la barre, en maintenant les bras supérieurs fixes", "Squeeze tes biceps en haut du mouvement lorsque la barre atteint le niveau de la poitrine", "Reddresse la barre de manière contrôlée jusqu''à la position de départ", "Répète le mouvement pour le nombre de répétitions souhaité sans balancer ni utiliser d''élan"]', '["Garde les poignets droits et une prise ferme pendant tout le mouvement", "Évite de te balancer ou d''utiliser ton dos pour soulever le poids", "Contrôle la descente pour maximiser l''engagement musculaire", "Garde les coudes fixes et près des côtés tout au long de l''exercice"]', '["Keep your wrists straight and maintain a firm grip throughout the movement", "Avoid swinging your body or using your back to lift the weight", "Control the eccentric (lowering) portion of the lift for maximum muscle engagement", "Keep your elbows stationary and close to your sides throughout the entire range of motion"]', '0a095165-5eb4-4d96-a98e-d8374391f2cc', 'seated-ez-bar-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('ea17640a-95ca-4a4b-b297-4e9ec28a438e', 'Élévation d''épaules avec barre', NULL, 'رفعة كتف بالبار', 'Barbell Shrug', 'Shoulders', '[]', 'Shoulders', 'Beginner', 1, '/videos/shoulders/barbell-shrug.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-shrug.jpg', NULL, '["Ne fais pas rouler les épaules (garde un mouvement droit vers le haut et le bas)", "Garde les bras droits tout au long de l''exercice", "Maintiens la contraction 1-2 secondes", "Ne plie pas les coudes", "Permets aux trapèzes de s''étirer complètement en bas"]', '["Soulever les épaules en roulant", "Plier les coudes", "Ne pas contrôler la descente", "Ne pas maintenir la contraction en haut", "Tenir des poids trop lourds"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "barbell", "barbell shrug"]', true, '2026-04-03 12:24:55.61297+00', '2026-04-03 12:24:55.61297+00', 'Position de départ : Reste debout, les pieds écartés à la largeur des hanches, en tenant une barre à bout de bras devant tes cuisses. Exécution : Lève tes épaules droit vers tes oreilles aussi haut que possible, maintiens brièvement, puis redescends-les de manière contrôlée.', '["Soulever les épaules en roulant", "Plier les coudes", "Ne pas contrôler la descente", "Ne pas maintenir la contraction en haut", "Tenir des poids trop lourds"]', true, '["Hold bar at thighs, arms straight", "Feet shoulder-width apart", "Shrug shoulders straight up toward ears", "Hold at top briefly", "Lower with control"]', '["Tiens la barre devant tes cuisses, bras tendus", "Pieds à la largeur des épaules", "Lève les épaules droit vers les oreilles", "Maintiens en position haute un instant", "Redescends avec contrôle"]', '["Ne fais pas rouler les épaules (garde un mouvement droit vers le haut et le bas)", "Garde les bras droits tout au long de l''exercice", "Maintiens la contraction 1-2 secondes", "Ne plie pas les coudes", "Permets aux trapèzes de s''étirer complètement en bas"]', '["Don''t roll shoulders (straight up and down)", "Keep arms straight throughout", "Hold the squeeze 1-2 seconds", "Don''t bend elbows", "Let traps fully stretch at bottom"]', 'a363775e-2aa5-49cb-ac17-7aa137d5d47b', 'barbell-shrug', NULL, NULL);
INSERT INTO public.exercises VALUES ('a24991e7-17da-446d-b80c-febbda5fa005', 'Curl biceps debout avec haltères', NULL, NULL, 'Dumbbell Bicep Curl Standing', 'Biceps', '[]', 'Biceps', 'Beginner', 2, '/videos/biceps/dumbbell-bicep-curl-standing.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-bicep-curl-standing.jpg', NULL, '["Garde les coudes près du corps", "Ne balance pas et n’utilise pas d''élan", "Extension complète en bas", "Tu peux alterner les bras ou faire les deux ensemble", "Contrôle bien la descente"]', '["Lever les coudes trop loin du corps", "Utiliser trop d''élan pour soulever les haltères"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "dumbbell bicep curl standing"]', true, '2026-04-03 12:24:56.394929+00', '2026-04-03 12:24:56.394929+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des épaules, un haltère dans chaque main, bras complètement tendus sur les côtés, paumes tournées vers l’avant. Exécution : En contractant tes biceps, soulève lentement les poids jusqu’à ce que tes avant-bras touchent tes biceps, puis redescends avec contrôle à la position de départ.', '["Lever les coudes trop loin du corps", "Utiliser trop d''élan pour soulever les haltères"]', true, '["Stand holding dumbbells at sides", "Palms facing forward", "Curl both dumbbells toward shoulders", "Squeeze biceps at top", "Lower with control"]', '["Tiens les haltères sur les côtés", "Paumes tournées vers l''avant", "Curl les deux haltères vers les épaules", "Contracte bien les biceps en haut", "Redescends avec contrôle"]', '["Garde les coudes près du corps", "Ne balance pas et n’utilise pas d''élan", "Extension complète en bas", "Tu peux alterner les bras ou faire les deux ensemble", "Contrôle bien la descente"]', '["Keep elbows at sides", "Don''t swing or use momentum", "Full extension at bottom", "Can alternate arms or curl together", "Control the negative"]', 'f34b7615-bfcc-4cd4-88f7-d7c68e910fe9', 'dumbbell-bicep-curl-standing', NULL, NULL);
INSERT INTO public.exercises VALUES ('023860bf-ae2f-4492-9d72-750d2e79668c', 'Squat Sumot avec Barre', NULL, NULL, 'Barbell Sumo Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 1, '/videos/quadriceps/barbell-sumo-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-sumo-squat.jpg', NULL, '["Garde les genoux alignés avec tes orteils pendant tout le mouvement pour éviter une mauvaise posture et des blessures", "Maintiens une colonne vertébrale neutre en gardant ta poitrine haute et en évitant de te pencher trop en avant", "La position large cible davantage les cuisses intérieures et les fessiers par rapport à un squat conventionnel tout en engageant toujours les quadriceps", "Concentre-toi sur le fait de pousser avec tes talons plutôt qu''avec tes orteils pour maximiser l''activation des fessiers et maintenir l''équilibre"]', '["Ne pas garder le dos droit pendant le squat", "Ne pas descendre suffisamment bas au squat"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "barbell sumo squat"]', true, '2026-04-03 12:24:55.627982+00', '2026-04-03 12:24:55.627982+00', 'Position de départ : Place la barre sur le haut de ton dos, les pieds écartés au-delà de la largeur des épaules, orteils légèrement tournés vers l''extérieur. Exécution : Descends en squat profond en gardant le dos droit, puis pousse pour revenir à la position de départ.', '["Ne pas garder le dos droit pendant le squat", "Ne pas descendre suffisamment bas au squat"]', true, '["Position the barbell securely on your upper trapezius muscles and grip the bar with hands wider than shoulder-width", "Set your feet in a wide stance with toes turned out 30-45 degrees and engage your core", "Initiate the movement by pushing your hips back and bending your knees while keeping your chest upright", "Descend until your thighs are parallel to the floor or as low as your mobility allows", "Drive through your heels and push the floor away to return to the starting position", "Maintain tension in your glutes and core throughout the entire movement"]', '["Positionne la barre en toute sécurité sur tes trapèzes supérieurs et attrape la barre avec une prise plus large que tes épaules", "Écarte tes pieds en adoptant une position large, orteils tournés vers l''extérieur à 30-45 degrés et contracte ton ventre", "Initie le mouvement en poussant tes hanches en arrière et en pliant les genoux tout en gardant la poitrine relevée", "Descends jusqu''à ce que tes cuisses soient parallèles au sol ou aussi bas que ton amplitude de mouvement le permet", "Pousse à travers tes talons et repousse le sol pour revenir à la position initiale", "Garde la tension dans tes fessiers et ton ventre tout au long du mouvement"]', '["Garde les genoux alignés avec tes orteils pendant tout le mouvement pour éviter une mauvaise posture et des blessures", "Maintiens une colonne vertébrale neutre en gardant ta poitrine haute et en évitant de te pencher trop en avant", "La position large cible davantage les cuisses intérieures et les fessiers par rapport à un squat conventionnel tout en engageant toujours les quadriceps", "Concentre-toi sur le fait de pousser avec tes talons plutôt qu''avec tes orteils pour maximiser l''activation des fessiers et maintenir l''équilibre"]', '["Keep your knees aligned with your toes throughout the movement to prevent knee valgus and potential injury", "Maintain a neutral spine by keeping your chest up and avoiding excessive forward lean", "The wider stance targets the inner thighs and glutes more than a conventional squat while still engaging the quadriceps", "Focus on pushing through your heels rather than your toes to maximize glute activation and maintain balance"]', '1ffaf9e8-fe94-44e8-a20b-012ea58eba46', 'barbell-sumo-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('5c95b0ef-96cc-4ff6-8d48-c78eca8d4e13', 'Curl Marteau Assis', NULL, NULL, 'Seated Hammer Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 2, '/videos/biceps/seated-hammer-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-hammer-curl.jpg', NULL, '["Gardez votre sangle abdominale engagée et maintenez une bonne posture pendant l''exercice", "Évitez de donner des coups ou d''utiliser de l''élan - concentrez-vous sur des mouvements contrôlés et délibérés", "Ne laissez pas vos coudes s''écarter ou avancer vers l''avant", "Choisissez un poids qui vous permet de conserver une bonne forme pour toutes les répétitions", "Expirez en levant et inspirez en redescendant"]', '["Utiliser un poids trop lourd qui compromet la forme", "Négliger la contraction des biceps au sommet du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "seated hammer curl"]', true, '2026-04-03 12:24:58.851045+00', '2026-04-03 12:24:58.851045+00', 'Position de départ : assis sur un banc avec un haltère dans chaque main, paumes face à votre corps. Exécution : fléchissez vos coudes pour amener les haltères vers vos épaules en effectuant un mouvement de marteau, puis redescendez de manière contrôlée.', '["Utiliser un poids trop lourd qui compromet la forme", "Négliger la contraction des biceps au sommet du mouvement"]', true, '["Sit on a bench with back support, holding a dumbbell in each hand with arms hanging at your sides", "Keep your palms facing each other (neutral grip) throughout the entire movement", "Slowly curl the weights up by bending at the elbows, keeping your upper arms stationary", "Squeeze your biceps at the top of the movement when the dumbbells reach shoulder level", "Lower the weights back down in a controlled manner to the starting position", "Repeat for the desired number of repetitions"]', '["Asseyez-vous sur un banc avec un bon soutien, un haltère dans chaque main, bras pendants sur les côtés", "Gardez les paumes face à face tout au long du mouvement", "Fléchissez lentement les coudes pour soulever les haltères, en gardant les bras supérieurs immobiles", "Contractez vos biceps lorsque les haltères atteignent le niveau des épaules", "Redescendez les haltères de manière contrôlée vers la position de départ", "Répétez pour le nombre de répétitions souhaité"]', '["Gardez votre sangle abdominale engagée et maintenez une bonne posture pendant l''exercice", "Évitez de donner des coups ou d''utiliser de l''élan - concentrez-vous sur des mouvements contrôlés et délibérés", "Ne laissez pas vos coudes s''écarter ou avancer vers l''avant", "Choisissez un poids qui vous permet de conserver une bonne forme pour toutes les répétitions", "Expirez en levant et inspirez en redescendant"]', '["Keep your core engaged and maintain good posture throughout the exercise", "Avoid swinging or using momentum - focus on controlled, deliberate movements", "Don''t let your elbows drift forward or flare out to the sides", "Use a weight that allows you to maintain proper form for all repetitions", "Breathe out during the lifting phase and breathe in during the lowering phase"]', '0c46de9c-4a97-405c-9fa2-aec5f5da73f0', 'seated-hammer-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('a5421e51-6618-4016-835e-cb9f2d5d82f5', 'Crawls d''ours avec sauts explosifs', NULL, 'دَبْبَةٌ وَقَفْزَاتٌ مُنْفَجِرَةٌ', 'Bear crawl into explosive jumps', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/bear-crawl-into-explosive-jumps.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-crawl-into-explosive-jumps.jpg', NULL, '["Garde une colonne vertébrale neutre durant tout le crawl pour protéger ton bas du dos", "Maintiens tes genoux bas durant le crawl, mais n''oublie pas qu''ils ne doivent pas toucher le sol", "Concentre-toi sur un atterrissage contrôlé après le saut explosif pour éviter les blessures", "Active ton core tout au long du mouvement pour une meilleure stabilité", "Commence par des distances de crawl plus courtes et des sauts moins intenses jusqu''à ce que tu maîtrises la coordination."]', '["Laisser les genoux toucher le sol pendant le crawl", "Ne pas engager le core et arrondir le dos en avançant"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "bear crawl into explosive jumps"]', true, '2026-04-03 12:24:55.64139+00', '2026-04-03 12:24:55.64139+00', 'Mets-toi en position de bear crawl, les mains et les pieds au sol, les genoux juste au-dessus. Engage ton core. Avance de 3 à 4 pas en restant en position, puis fais un saut explosif en levant les bras au-dessus de ta tête avant de revenir au point de départ.', '["Laisser les genoux toucher le sol pendant le crawl", "Ne pas engager le core et arrondir le dos en avançant"]', true, '["Start in bear crawl position with hands shoulder-width apart, knees bent and hovering 2-3 inches off the ground", "Keep your core tight and back straight as you crawl forward 3-4 steps using opposite hand and foot coordination", "After completing the crawl steps, place both feet firmly on the ground and prepare for the explosive movement", "Drive through your heels and jump up explosively, extending your arms overhead", "Land softly with bent knees and immediately return to the bear crawl starting position", "Repeat the sequence for the desired number of repetitions"]', '["Commence en position de bear crawl, mains écartées à la largeur des épaules, genoux pliés et surélevés de 5 cm au-dessus du sol", "Garde ton core bien engagé et le dos droit en avançant de 3 à 4 pas en alternant bras et jambes", "Après les pas de crawl, place tes deux pieds fermement au sol et prépare-toi à sauter", "Pousse avec tes talons et fais un saut explosif en levant les bras au-dessus de la tête", "Atterrit doucement avec les genoux fléchis et retourne immédiatement à la position de départ en bear crawl", "Répète cette séquence autant de fois que souhaité."]', '["Garde une colonne vertébrale neutre durant tout le crawl pour protéger ton bas du dos", "Maintiens tes genoux bas durant le crawl, mais n''oublie pas qu''ils ne doivent pas toucher le sol", "Concentre-toi sur un atterrissage contrôlé après le saut explosif pour éviter les blessures", "Active ton core tout au long du mouvement pour une meilleure stabilité", "Commence par des distances de crawl plus courtes et des sauts moins intenses jusqu''à ce que tu maîtrises la coordination."]', '["Maintain a neutral spine throughout the bear crawl portion to protect your lower back", "Keep knees low during the crawl but avoid letting them touch the ground", "Focus on a controlled landing after the explosive jump to prevent injury", "Engage your core throughout the entire movement to maintain stability", "Start with shorter crawl distances and lower jump intensity until you master the coordination"]', '47ab9d26-7959-46bb-9744-1e48695f5e70', 'bear-crawl-into-explosive-jumps', NULL, NULL);
INSERT INTO public.exercises VALUES ('da129163-8e85-44c7-af40-c1cc2402487c', 'Curl derrière la tête avec câble', NULL, 'Curl l''khedma men wara l''rdh', 'Behind the Head Curl with Cable', 'Biceps', '[]', 'Biceps', 'Advanced', 4, '/videos/biceps/behind-the-head-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/behind-the-head-curl.jpg', NULL, '["Cet exercice sollicite fortement l''articulation de l''épaule, alors utilise un poids plus léger qu''avec les curls standard", "Maintiens un contrôle strict durant le mouvement pour éviter toute douleur à l''épaule", "Engage ton tronc et évite de cambrer excessivement le dos", "Arrête immédiatement si tu ressens une gêne ou une douleur à l''épaule", "Prends en compte tes limitations de mobilité de l''épaule avant d''essayer cet exercice"]', '["Utiliser un poids trop lourd, ce qui peut engendrer des blessures", "Ne pas garder les bras supérieurs stationnaires, ce qui diminue l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "cable", "behind the head curl with cable"]', true, '2026-04-03 12:24:55.698108+00', '2026-04-03 12:24:55.698108+00', 'Position de départ : Tiens-toi dos à la machine à câbles, en saisissant l''attache basse avec une prise en supination. Tes bras doivent être tendus derrière ta tête. Exécution : Ramène le câble vers l''avant et vers le haut en flexion tes biceps tout en maintenant tes bras supérieurs fixes derrière ta tête.', '["Utiliser un poids trop lourd, ce qui peut engendrer des blessures", "Ne pas garder les bras supérieurs stationnaires, ce qui diminue l''efficacité de l''exercice"]', true, '["Set the cable pulley to the lowest position and attach a straight bar or EZ-curl bar attachment", "Stand with your back to the cable machine, feet shoulder-width apart for stability", "Reach behind your head and grasp the attachment with an underhand grip, arms extended", "Keep your upper arms stationary and parallel to the floor throughout the movement", "Curl the weight forward and up by contracting your biceps until your forearms are vertical", "Slowly lower the weight back to the starting position with control"]', '["Règle la poulie du câble à la position la plus basse et attache une barre droite ou une barre EZ", "Tiens-toi dos à la machine, les pieds écartés à la largeur des épaules pour la stabilité", "Tends les bras derrière ta tête et saisis l''attache avec une prise en supination", "Garde tes bras supérieurs fixes et parallèles au sol durant tout le mouvement", "Enroule le poids vers l''avant et en haut en contractant tes biceps jusqu''à ce que tes avant-bras soient verticaux", "Abaisse lentement le poids vers la position de départ avec contrôle"]', '["Cet exercice sollicite fortement l''articulation de l''épaule, alors utilise un poids plus léger qu''avec les curls standard", "Maintiens un contrôle strict durant le mouvement pour éviter toute douleur à l''épaule", "Engage ton tronc et évite de cambrer excessivement le dos", "Arrête immédiatement si tu ressens une gêne ou une douleur à l''épaule", "Prends en compte tes limitations de mobilité de l''épaule avant d''essayer cet exercice"]', '["This exercise places significant stress on the shoulder joint, so use lighter weight than standard bicep curls", "Maintain strict control throughout the movement to avoid shoulder impingement", "Keep your core engaged and avoid arching your back excessively", "Stop immediately if you feel any shoulder discomfort or pain", "Consider shoulder mobility limitations before attempting this exercise"]', 'fc721ada-0004-40d7-9e1e-634dc9b34877', 'behind-the-head-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('87be04bb-f074-46ae-a87f-508030c31193', 'Taps d''Épaules en Position de Bear Plank', NULL, NULL, 'Bear plank Shoulder taps', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/bear-plank-shoulder-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-plank-shoulder-taps.jpg', NULL, '["Garde tes hanches immobiles pour maximiser l''engagement du core et éviter la rotation", "Assure une répartition du poids équilibrée sur tes pieds et ta main de soutien lors de chaque tap", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur la vitesse pour garantir une activation musculaire correcte", "Maintiens tes épaules directement au-dessus de tes poignets tout au long de l''exercice", "Si l''exercice est trop difficile, commence par maintenir la position de bear plank avant d''ajouter les taps d''épaules"]', '["Hanches qui bougent trop pendant les taps", "Poids mal réparti entre les mains et les pieds"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "bear plank shoulder taps"]', true, '2026-04-03 12:24:55.670417+00', '2026-04-03 12:24:55.670417+00', 'Commence en position de bear plank, les mains sous les épaules, les genoux pliés à 90 degrés, à 1-2 pouces du sol. Gardez une ligne droite de la tête aux hanches et préparez-vous à activer votre core !', '["Hanches qui bougent trop pendant les taps", "Poids mal réparti entre les mains et les pieds"]', true, '["Set up in a tabletop position with hands directly under shoulders and knees under hips", "Lift your knees 1-2 inches off the ground while keeping them bent at 90 degrees", "Engage your core and maintain a straight line from head to tailbone", "Slowly lift your right hand and tap your left shoulder, keeping hips level", "Return your right hand to the ground and repeat the movement with your left hand tapping your right shoulder", "Continue alternating sides while maintaining proper form and breathing steadily"]', '["Mets-toi en position à quatre pattes, mains sous les épaules et genoux sous les hanches", "Soulève tes genoux de 1-2 pouces du sol tout en les gardant pliés à 90 degrés", "Contracte ton core et garde une ligne droite de la tête à la base du dos", "Lève lentement ta main droite et tape ton épaule gauche, sans bouger les hanches", "Ramène ta main droite au sol et répète avec ta main gauche qui tape ton épaule droite", "Continue d''alterner les côtés en maintenant une bonne forme et en respirant régulièrement"]', '["Garde tes hanches immobiles pour maximiser l''engagement du core et éviter la rotation", "Assure une répartition du poids équilibrée sur tes pieds et ta main de soutien lors de chaque tap", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur la vitesse pour garantir une activation musculaire correcte", "Maintiens tes épaules directement au-dessus de tes poignets tout au long de l''exercice", "Si l''exercice est trop difficile, commence par maintenir la position de bear plank avant d''ajouter les taps d''épaules"]', '["Keep your hips as still as possible to maximize core engagement and avoid rotating", "Maintain equal weight distribution on your feet and supporting hand during each tap", "Focus on slow, controlled movements rather than speed to ensure proper muscle activation", "Keep your shoulders directly over your wrists throughout the entire movement", "If the exercise is too challenging, start by holding the bear plank position before adding shoulder taps"]', 'c2a135e7-1383-47c1-9757-4868ae9a8c55', 'bear-plank-shoulder-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('6c09de9a-d9b3-4016-928f-c7fefbb58628', 'Marche du fermier', NULL, NULL, 'Farmers walk', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/farmers-walk.mp4', NULL, NULL, NULL, '/videos/thumbnails/farmers-walk.jpg', NULL, '["Garde les épaules en arrière et évite qu''elles ne tombent quand tes avant-bras fatiguent", "Maintiens une prise solide pendant l''exercice pour bien travailler tes avant-bras", "Commence avec des poids plus légers et des distances plus courtes, puis augmente progressivement", "Arrête-toi immédiatement si ta prise devient instable pour éviter de faire tomber les objets", "Respire normalement, évite de retenir ta respiration pendant le mouvement"]', '["Ne pas engager le ventre et arrondir le dos", "Laisser les épaules rouler vers l''avant en fatigant"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["forearms", "dumbbell", "farmers walk"]', true, '2026-04-03 12:24:56.708158+00', '2026-04-03 12:24:56.708158+00', 'Prends des poids, tiens-les bien et prépare-toi à avancer tout en travaillant tes avant-bras !', '["Ne pas engager le ventre et arrondir le dos", "Laisser les épaules rouler vers l''avant en fatigant"]', true, '["Find two heavy household objects of equal weight such as water jugs, heavy bags, or suitcases", "Stand tall with the objects at your sides, arms straight and shoulders pulled back", "Engage your core and maintain neutral spine alignment before beginning movement", "Walk forward with normal stride length while gripping the objects tightly", "Focus on maintaining upright posture throughout the entire walking distance", "Set objects down safely by bending at hips and knees, not rounding your back"]', '["Trouve deux objets lourds de même poids comme des jugs d''eau, des sacs lourds ou des valises", "Tiens-toi droit avec les objets à tes côtés, les bras tendus et les épaules en arrière", "Engage ton ventre et garde le dos droit avant de commencer à marcher", "Avance avec un pas normal en tenant fermement les objets", "Concentre-toi sur ta posture droite pendant tout le trajet", "Pose les objets en toute sécurité en pliant les hanches et les genoux, sans arrondir le dos"]', '["Garde les épaules en arrière et évite qu''elles ne tombent quand tes avant-bras fatiguent", "Maintiens une prise solide pendant l''exercice pour bien travailler tes avant-bras", "Commence avec des poids plus légers et des distances plus courtes, puis augmente progressivement", "Arrête-toi immédiatement si ta prise devient instable pour éviter de faire tomber les objets", "Respire normalement, évite de retenir ta respiration pendant le mouvement"]', '["Keep shoulders back and avoid letting them roll forward as grip strength fatigues", "Maintain a firm grip throughout the exercise to maximize forearm engagement", "Start with lighter weights and shorter distances, gradually increasing as strength improves", "Stop immediately if you feel your grip failing to prevent dropping the objects", "Breathe normally and avoid holding your breath during the movement"]', '9ad86735-3149-48fa-add4-705598dc149e', 'farmers-walk', NULL, NULL);
INSERT INTO public.exercises VALUES ('d00a6c56-e3cf-4b2b-af85-ffd19cccee29', 'Tirage VerticAl avec Haltère', NULL, NULL, 'Upright Barbell Row', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/upright-barbell-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/upright-barbell-row.jpg', NULL, '["Garde tes coudes toujours plus hauts que les poignets pour bien cibler les muscles sollicités.", "Évite de tirer la barre trop haut pour prévenir les douleurs aux épaules.", "Utilise un rythme contrôlé tant à la montée qu''à la descente pour maximiser l''engagement musculaire.", "Garde les abdominaux serrés et la posture droite pour protéger ton bas du dos.", "Commence avec des poids légers pour maîtriser ta technique avant d''augmenter la charge."]', '["Ne pas garder les coudes élevés pendant le mouvement.", "Utiliser trop d''élan au lieu d''une contraction musculaire contrôlée."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "upright barbell row"]', true, '2026-04-03 12:24:59.820554+00', '2026-04-03 12:24:59.820554+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des épaules, avec une barre devant tes cuisses, les bras tendus. Exécution : Tire la barre vers ton torse en levant les coudes sur les côtés, puis redescends-la avec contrôle.', '["Ne pas garder les coudes élevés pendant le mouvement.", "Utiliser trop d''élan au lieu d''une contraction musculaire contrôlée."]', true, '["Stand with feet shoulder-width apart and grip the barbell with hands positioned closer than shoulder-width using an overhand grip", "Keep the barbell close to your body throughout the entire movement", "Pull the barbell straight up by leading with your elbows, lifting them up and out to the sides", "Raise the bar to about chest level, keeping your torso upright and core engaged", "Lower the barbell back down to the starting position with slow, controlled movement", "Maintain proper posture with shoulders back and avoid using momentum"]', '["Tiens-toi debout, pieds écartés à la largeur des épaules, saisis la barre avec les mains plus proches que la largeur des épaules et en prise pronation.", "Garde la barre près de ton corps pendant tout le mouvement.", "Tire la barre vers le haut en menant avec les coudes, en les levant et en les écartant sur les côtés.", "Lève la barre jusqu''à environ la hauteur de la poitrine, en gardant le torse droit et les abdominaux engagés.", "Redescends la barre lentement jusqu''à la position de départ. Fais-le avec contrôle.", "Maintiens une bonne posture, épaules en arrière, évite d''utiliser l''élan."]', '["Garde tes coudes toujours plus hauts que les poignets pour bien cibler les muscles sollicités.", "Évite de tirer la barre trop haut pour prévenir les douleurs aux épaules.", "Utilise un rythme contrôlé tant à la montée qu''à la descente pour maximiser l''engagement musculaire.", "Garde les abdominaux serrés et la posture droite pour protéger ton bas du dos.", "Commence avec des poids légers pour maîtriser ta technique avant d''augmenter la charge."]', '["Keep your elbows higher than your wrists throughout the movement to properly target the target muscles", "Avoid pulling the bar too high above chest level to prevent shoulder impingement", "Use a controlled tempo on both the lifting and lowering phases to maximize muscle engagement", "Keep your core tight and maintain an upright posture to protect your lower back", "Start with lighter weight to master the form before progressing to heavier loads"]', 'b0c07cf7-545e-4c74-8224-3355a2669fb2', 'upright-barbell-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('4a3f7cbf-13e7-432e-ad41-8aef6543dba2', 'Tirage Buste Penché à la Barre - 105', NULL, 'سحب باها بشي طيحة - 105', 'Bent Over Two-Arm Long Bar Row - 105', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/bent-over-two-arm-long-bar-row-105.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-over-two-arm-long-bar-row-105.jpg', NULL, '["Garde le dos droit et le tronc actif pendant tout le mouvement pour protéger ta région lombaire.", "Concentre-toi sur le travail de tes muscles du dos plutôt que sur tes bras en initiant le mouvement avec tes omoplates.", "Évite d’arrondir tes épaules vers l’avant ou de cambrer excessivement ton dos.", "Contrôle bien le poids lors des phases de montée et de descente pour maximiser l''engagement musculaire.", "Garde la tête dans une position neutre, alignée avec ta colonne vertébrale, sans regarder vers le haut ou vers le bas."]', '["Utiliser trop d''élan au lieu de l''engagement musculaire.", "Rondir les épaules au lieu de les garder en arrière."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "bent over two-arm long bar row - 105"]', true, '2026-04-03 12:24:55.761584+00', '2026-04-03 12:24:55.761584+00', 'Position de départ : Place-toi avec les pieds écartés à la largeur des hanches, en tenant la barre avec les mains en pronation légèrement plus larges que les épaules. Penche-toi en avant en pliant légèrement les genoux et en gardant le dos droit.', '["Utiliser trop d''élan au lieu de l''engagement musculaire.", "Rondir les épaules au lieu de les garder en arrière."]', true, '["Set up with feet hip-width apart and grip the barbell with hands slightly wider than shoulder-width using an overhand grip", "Hinge at the hips to lean forward approximately 45 degrees while maintaining a neutral spine and slight bend in the knees", "Engage your core and let the barbell hang at arm''s length with shoulders pulled back and down", "Pull the barbell toward your lower chest by driving your elbows back and squeezing your shoulder blades together", "Pause briefly at the top of the movement, then slowly lower the barbell back to the starting position", "Maintain proper posture throughout the entire range of motion and avoid using momentum"]', '["Positionne tes pieds à la largeur des hanches et saisis la barre avec une prise en pronation légèrement plus large que les épaules.", "Incline-toi au niveau des hanches jusqu''à environ 45 degrés en gardant le dos neutre et les genoux légèrement fléchis.", "Active ton tronc et laisse la barre pendre à bout de bras, les épaules tirées vers l''arrière et vers le bas.", "Tire la barre vers le bas de ta poitrine en ramenant les coudes vers l''arrière et en serrant les omoplates ensemble.", "Fais une pause courte en haut du mouvement, puis abaisse lentement la barre à la position de départ avec contrôle.", "Maintiens une posture correcte tout au long du mouvement et évite d''utiliser l''élan."]', '["Garde le dos droit et le tronc actif pendant tout le mouvement pour protéger ta région lombaire.", "Concentre-toi sur le travail de tes muscles du dos plutôt que sur tes bras en initiant le mouvement avec tes omoplates.", "Évite d’arrondir tes épaules vers l’avant ou de cambrer excessivement ton dos.", "Contrôle bien le poids lors des phases de montée et de descente pour maximiser l''engagement musculaire.", "Garde la tête dans une position neutre, alignée avec ta colonne vertébrale, sans regarder vers le haut ou vers le bas."]', '["Keep your back straight and core engaged throughout the movement to protect your lower back", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Avoid rounding your shoulders forward or allowing your back to arch excessively", "Control the weight on both the lifting and lowering phases to maximize muscle engagement", "Keep your head in a neutral position aligned with your spine rather than looking up or down"]', 'ad8e32a3-091a-4b10-a316-8984807ce817', 'bent-over-two-arm-long-bar-row-105', NULL, NULL);
INSERT INTO public.exercises VALUES ('dbdae336-5624-42e0-9628-b888ff4e9e63', 'Tirage Barre', NULL, 'تيراج بار', 'Barbell Rows', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/barbell-rows.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-rows.jpg', NULL, '["Garde ton ventre engagé pendant tout le mouvement pour protéger le bas du dos", "Concentre-toi sur le tirage avec les muscles du dos plutôt qu''avec les bras", "Maintiens un angle constant de ton torse durant l''exercice", "Évite d''utiliser l''élan ou de balancer le poids"]', '["Ne pas garder le dos droit, ce qui augmente le risque de blessure", "Utiliser uniquement les bras pour tirer sans impliquer les muscles du dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "barbell rows"]', true, '2026-04-03 12:24:55.605711+00', '2026-04-03 12:24:55.605711+00', 'Position de départ : Place-toi avec les pieds écartés largeur des hanches, tiens la barre avec une prise pronation légèrement plus large que la largeur des épaules, bras tendus, buste penché en avant au niveau des hanches. Exécution : Tire la barre vers ta poitrine en dirigeant tes coudes vers l''arrière et en serrant les omoplates, puis redescends la barre avec contrôle.', '["Ne pas garder le dos droit, ce qui augmente le risque de blessure", "Utiliser uniquement les bras pour tirer sans impliquer les muscles du dos"]', true, '["Set up with the barbell on the floor or rack at about mid-shin height", "Hinge at the hips to lean forward approximately 45 degrees while maintaining a neutral spine", "Grip the barbell with hands slightly wider than shoulder-width using an overhand grip", "Engage your core and pull the barbell toward your lower chest by driving elbows back", "Squeeze shoulder blades together at the top of the movement", "Lower the barbell slowly and under control to the starting position"]', '["Place la barre sur le sol ou un support à hauteur du milieu du tibia", "Penche-toi en avant à environ 45 degrés en gardant le dos neutre", "Saisis la barre avec les mains légèrement plus larges que la largeur des épaules, prise pronation", "Engage ton ventre et tire la barre vers ta poitrine inférieure en faisant reculer les coudes", "Serre bien les omoplates en haut du mouvement", "Redescends la barre lentement et avec contrôle jusqu''à la position de départ"]', '["Garde ton ventre engagé pendant tout le mouvement pour protéger le bas du dos", "Concentre-toi sur le tirage avec les muscles du dos plutôt qu''avec les bras", "Maintiens un angle constant de ton torse durant l''exercice", "Évite d''utiliser l''élan ou de balancer le poids"]', '["Keep your core engaged throughout the movement to protect your lower back", "Focus on pulling with your back muscles rather than just your arms", "Maintain a consistent torso angle throughout the exercise", "Avoid using momentum or swinging the weight up"]', 'dbf6a8e4-19dc-4d01-8014-f195a1eb817c', 'barbell-rows', NULL, NULL);
INSERT INTO public.exercises VALUES ('72b6d02c-b917-4bb2-b349-c7730ee54d2b', 'V-sit avec coups de poing', NULL, 'V-sit m3a darb', 'Bent leg v-sit into punches', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/bent-leg-v-sit-into-punches.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-leg-v-sit-into-punches.jpg', NULL, '["Gardez votre ventre constamment engagé pour maintenir l''équilibre et protéger votre bas du dos", "Concentrez-vous sur des mouvements de coups de poing contrôlés plutôt que sur la vitesse pour maintenir la bonne forme de V-sit", "Si vous ne pouvez pas maintenir la position des jambes, posez légèrement vos pieds au sol pour le soutien", "Gardez vos épaules détendues et évitez de vous recroqueviller en avant durant le mouvement des coups de poing", "Arrêtez immédiatement si vous ressentez une tension dans le bas du dos et réévaluez votre forme"]', '["Ne pas engager le tronc suffisamment, ce qui nuit à l''équilibre", "Pencher trop en avant, ce qui peut causer des douleurs au dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "bent leg v-sit into punches"]', true, '2026-04-03 12:24:55.722613+00', '2026-04-03 12:24:55.722613+00', 'Position de départ : Assieds-toi au sol, les genoux fléchis à 90 degrés, les pieds décollés du sol et penche-toi légèrement en arrière tout en te tenant sur tes fessiers, les bras le long du corps. Execution : Reste en position de V-sit tout en alternant des coups de poing rapides vers l''avant, en gardant le ventre engagé et les jambes stables tout au long du mouvement.', '["Ne pas engager le tronc suffisamment, ce qui nuit à l''équilibre", "Pencher trop en avant, ce qui peut causer des douleurs au dos"]', true, '["Sit on the floor and lift your feet off the ground with knees bent at 90 degrees", "Lean back slightly until you feel your core muscles engage and find your balance point", "Keep your chest up and shoulders back while maintaining the V-sit position", "Begin alternating punches forward with controlled speed, extending one arm fully while the other returns", "Maintain steady breathing and keep your legs stable throughout the punching motion", "Continue for the prescribed time or repetitions while focusing on form over speed"]', '["Asseyez-vous au sol et levez vos pieds off the ground avec les genoux fléchis à 90 degrés", "Pénétrez légèrement en arrière jusqu''à sentir vos muscles du tronc s''engager et trouver votre point d''équilibre", "Gardez votre poitrine relevée et vos épaules en arrière tout en maintenant la position de V-sit", "Commencez à alterner les coups de poing vers l''avant à une vitesse contrôlée, en étendant un bras complètement tandis que l''autre revient", "Maintenez une respiration régulière et gardez vos jambes stables pendant le mouvement des coups de poing", "Continuez pendant le temps ou les répétitions prescrites en vous concentrant sur la forme plutôt que sur la vitesse"]', '["Gardez votre ventre constamment engagé pour maintenir l''équilibre et protéger votre bas du dos", "Concentrez-vous sur des mouvements de coups de poing contrôlés plutôt que sur la vitesse pour maintenir la bonne forme de V-sit", "Si vous ne pouvez pas maintenir la position des jambes, posez légèrement vos pieds au sol pour le soutien", "Gardez vos épaules détendues et évitez de vous recroqueviller en avant durant le mouvement des coups de poing", "Arrêtez immédiatement si vous ressentez une tension dans le bas du dos et réévaluez votre forme"]', '["Keep your core constantly engaged to maintain balance and protect your lower back", "Focus on controlled punching movements rather than speed to maintain proper V-sit form", "If you cannot maintain the leg position, place your feet lightly on the ground for support", "Keep your shoulders relaxed and avoid hunching forward during the punching motion", "Stop immediately if you feel strain in your lower back and reassess your form"]', '53f37f4b-c486-4ebb-846b-953078455bfe', 'bent-leg-v-sit-into-punches', NULL, NULL);
INSERT INTO public.exercises VALUES ('a52acf58-c06a-42fc-91d9-4c5b0a614851', 'Tirage Mi-Machine', NULL, NULL, 'Mid Row Machine', 'Back', '[]', 'Back', 'Beginner', 8, '/videos/back/mid-row-machine.mp4', NULL, NULL, NULL, '/videos/thumbnails/mid-row-machine.jpg', NULL, '["Gardez les épaules basses et en arrière tout au long du mouvement pour éviter les blessures aux épaules", "Concentrez-vous sur le tirage avec vos muscles du dos plutôt qu''avec vos bras, en initiant le mouvement avec vos omoplates", "Évitez de laisser la pile de poids toucher entre les répétitions pour maintenir une tension constante sur les muscles ciblés", "Maintenez votre poitrine pressée contre le support pour empêcher votre torse de bouger et garantir une bonne forme", "Contrôlez les phases de tirage et de descente du mouvement pour une activation musculaire maximale"]', '["Laisser les épaules monter, ce qui peut provoquer des tensions", "Tirer uniquement avec les bras au lieu de faire appel aux muscles du dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "mid row machine"]', true, '2026-04-03 12:24:57.794963+00', '2026-04-03 12:24:57.794963+00', 'Position de départ : Asseyez-vous sur la machine à tirage mi, les mains en prise moyenne. Ajustez la hauteur du siège pour que les poignées soient à la hauteur de votre abdomen. Exécution : Tirez les poignées vers votre abdomen tout en gardant le torse droit, puis retournez lentement à la position de départ.', '["Laisser les épaules monter, ce qui peut provoquer des tensions", "Tirer uniquement avec les bras au lieu de faire appel aux muscles du dos"]', true, '["Adjust the seat height so your arms are parallel to the floor when gripping the handles", "Position your chest firmly against the pad and maintain an upright posture throughout the movement", "Grip the handles with a neutral grip, keeping your wrists straight and aligned", "Pull the handles back by driving your elbows behind your body and squeezing your shoulder blades together", "Hold the contracted position briefly, then slowly return to the starting position", "Maintain tension in your core and avoid using momentum or swinging motions"]', '["Ajustez la hauteur du siège pour que vos bras soient parallèles au sol en tenant les poignées", "Pressez fermement votre poitrine contre le support et gardez une posture droite durant tout le mouvement", "Prenez les poignées avec une prise neutre, en gardant les poignets droits et alignés", "Tirez les poignées vers l''arrière en poussant vos coudes derrière votre corps et en serrant les omoplates ensemble", "Maintenez la position contractée brièvement, puis revenez lentement à la position de départ", "Maintenez la tension dans votre sangle abdominale et évitez d''utiliser l''élan ou des mouvements de balancement"]', '["Gardez les épaules basses et en arrière tout au long du mouvement pour éviter les blessures aux épaules", "Concentrez-vous sur le tirage avec vos muscles du dos plutôt qu''avec vos bras, en initiant le mouvement avec vos omoplates", "Évitez de laisser la pile de poids toucher entre les répétitions pour maintenir une tension constante sur les muscles ciblés", "Maintenez votre poitrine pressée contre le support pour empêcher votre torse de bouger et garantir une bonne forme", "Contrôlez les phases de tirage et de descente du mouvement pour une activation musculaire maximale"]', '["Keep your shoulders down and back throughout the entire movement to avoid shoulder impingement", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Avoid letting the weight stack touch between repetitions to maintain constant tension on the target muscles", "Keep your chest pressed against the pad to prevent your torso from moving and ensure proper form", "Control both the pulling and lowering phases of the movement for maximum muscle activation"]', '94e2b3e2-d8e5-4f3b-8b77-5368023e25eb', 'mid-row-machine', NULL, NULL);
INSERT INTO public.exercises VALUES ('36248eb6-d500-4340-bf9f-2299987812ec', 'Rameur Incliné avec Deux Haltères Paumes Vers l''Intérieur', NULL, NULL, 'Bent Over Two-Dumbbell Row With Palms In', 'Back', '[]', 'Back', 'Intermediate', 2, '/videos/back/bent-over-two-dumbbell-row-with-palms-in.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-over-two-dumbbell-row-with-palms-in.jpg', NULL, '["Garde ton ventre bien serré et garde une colonne vertébrale neutre pour protéger ton bas du dos", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement par les omoplates", "Évite d''utiliser l''élan ou de balancer les poids - contrôle bien le mouvement dans les deux directions", "Garde la tête dans une position neutre alignée avec la colonne, sans tourner excessivement vers le haut ou le bas", "Commence avec des poids légers pour maîtriser la technique avant de passer à des charges plus lourdes."]', '["Arquer le dos lors du mouvement", "Ne pas tirer avec les muscles du dos mais uniquement avec les bras"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "bent over two-dumbbell row with palms in"]', true, '2026-04-03 12:24:55.764872+00', '2026-04-03 12:24:55.764872+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des hanches, un haltère dans chaque main, paumes face à vous. Penchez-vous en avant en pliant légèrement les genoux et en gardant le dos droit. Exécution : Tire les deux haltères vers tes côtes inférieures en rapprochant les coudes en arrière, serre les omoplates, puis redescends lentement les haltères vers la position de départ.', '["Arquer le dos lors du mouvement", "Ne pas tirer avec les muscles du dos mais uniquement avec les bras"]', true, '["Hinge at the hips and lean forward until your torso is at approximately 45 degrees, keeping your back straight and core engaged", "Hold dumbbells with a neutral grip, palms facing inward toward your body, arms hanging straight down", "Initiate the pull by driving your elbows back and up toward the ceiling, keeping them close to your sides", "Squeeze your shoulder blades together as you pull the dumbbells toward your lower rib cage", "Hold the contraction briefly at the top, then slowly lower the weights back to the starting position with control", "Maintain the hip-hinged position throughout the entire set"]', '["Penche-toi en avant jusqu''à ce que ton torse soit à environ 45 degrés, dos droit et gainage actif", "Tiens les haltères avec une prise neutre, les paumes tournées vers ton corps, les bras pendants", "Commence le tirage en ramenant les coudes vers le haut et vers l''arrière, en les gardant près du corps", "Serre les omoplates en tirant les haltères vers tes côtes inférieures", "Maintiens la contraction en haut un instant, puis redescends lentement les poids avec contrôle", "Reste en position de flexion des hanches tout au long de la série."]', '["Garde ton ventre bien serré et garde une colonne vertébrale neutre pour protéger ton bas du dos", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement par les omoplates", "Évite d''utiliser l''élan ou de balancer les poids - contrôle bien le mouvement dans les deux directions", "Garde la tête dans une position neutre alignée avec la colonne, sans tourner excessivement vers le haut ou le bas", "Commence avec des poids légers pour maîtriser la technique avant de passer à des charges plus lourdes."]', '["Keep your core tight and maintain a neutral spine throughout the movement to protect your lower back", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Avoid using momentum or swinging the weights - control the movement in both directions", "Keep your head in a neutral position aligned with your spine, avoiding looking up or down excessively", "Start with lighter weights to master the form before progressing to heavier loads"]', '7aaad2c1-c499-40dd-84e5-a66b910e6f8b', 'bent-over-two-dumbbell-row-with-palms-in', NULL, NULL);
INSERT INTO public.exercises VALUES ('2c19a14a-d357-4e7e-afff-80709e90d899', 'Rameur Unijambiste avec Haltère', NULL, NULL, 'One-Arm Dumbbell Row bench', 'Back', '[]', 'Back', 'Intermediate', 2, '/videos/back/one-arm-dumbbell-row-bench.mp4', NULL, NULL, NULL, '/videos/thumbnails/one-arm-dumbbell-row-bench.jpg', NULL, '["Garde ton core engagé et la colonne vertébrale neutre pendant toute l''exécution pour protéger ton bas du dos.", "Concentre-toi sur le tirage avec tes muscles du dos et non avec ton bras, en initiant le mouvement par ta scapula.", "Évite de faire pivoter ton torse ou d''utiliser l''élan pour soulever le poids.", "Maintiens ton poignet droit et une prise ferme sur l''haltère tout au long de l''exercice.", "Assure-toi d''avoir une amplitude complète en permettant un étirement complet en bas et une contraction maximale en haut."]', '["Ne pas engager le core, ce qui augmente le risque de blessure au bas du dos.", "Utiliser l''élan pour soulever l''haltère au lieu de se concentrer sur un contrôle musculaire."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "one-arm dumbbell row bench"]', true, '2026-04-03 12:24:58.177275+00', '2026-04-03 12:24:58.177275+00', 'Position de départ : Mets ton genou et ta main du même côté sur le banc pour le soutien. L''autre pied est bien ancré au sol, avec l''haltère dans la main libre, pendue vers le bas. Exécution : Tire l''haltère vers ta hanche en effectuant un mouvement de rame, en serrant ta scapula, puis redescends avec contrôle jusqu''à la position initiale.', '["Ne pas engager le core, ce qui augmente le risque de blessure au bas du dos.", "Utiliser l''élan pour soulever l''haltère au lieu de se concentrer sur un contrôle musculaire."]', true, '["Position yourself with one knee and matching hand on the bench, keeping your back straight and parallel to the floor", "Plant your opposite foot firmly on the ground for stability and hold the dumbbell with a neutral grip", "Initiate the movement by pulling your shoulder blade back and driving your elbow toward the ceiling", "Pull the dumbbell up toward your hip, keeping it close to your body throughout the movement", "Squeeze your back muscles at the top of the movement for a brief pause", "Lower the dumbbell slowly and with control back to the starting position"]', '["Place ton genou et ta main du même côté sur le banc, le dos droit et parallèle au sol.", "Ancre bien ton pied opposé au sol pour plus de stabilité et tiens l''haltère avec une prise neutre.", "Commence le mouvement en tirant ton épaule en arrière et en poussant ton coude vers le plafond.", "Tire l''haltère vers ta hanche, en la gardant proche de ton corps pendant tout le mouvement.", "Contracte tes muscles du dos en haut du mouvement, avec une pause brève.", "Redescends l''haltère lentement et de manière contrôlée à la position initiale."]', '["Garde ton core engagé et la colonne vertébrale neutre pendant toute l''exécution pour protéger ton bas du dos.", "Concentre-toi sur le tirage avec tes muscles du dos et non avec ton bras, en initiant le mouvement par ta scapula.", "Évite de faire pivoter ton torse ou d''utiliser l''élan pour soulever le poids.", "Maintiens ton poignet droit et une prise ferme sur l''haltère tout au long de l''exercice.", "Assure-toi d''avoir une amplitude complète en permettant un étirement complet en bas et une contraction maximale en haut."]', '["Keep your core engaged and spine neutral throughout the entire movement to protect your lower back", "Focus on pulling with your back muscles rather than your arm by initiating the movement with your shoulder blade", "Avoid rotating your torso or using momentum to lift the weight", "Keep your wrist straight and maintain a firm grip on the dumbbell throughout the exercise", "Ensure full range of motion by allowing a complete stretch at the bottom and full contraction at the top"]', 'c5a9becd-0051-47b0-9e75-ed52fedd6d44', 'one-arm-dumbbell-row-bench', NULL, NULL);
INSERT INTO public.exercises VALUES ('a3610dcb-203e-4558-8dcd-17d0507923b0', 'Tirage buste penché avec barre', NULL, NULL, 'Bent Over Barbell Row Overhand Grip', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/bent-over-barbell-row-overhand-grip.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-over-barbell-row-overhand-grip.jpg', NULL, '["Garde le dos droit et les abdos engagés pour protéger ta colonne vertébrale.", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras, en initiant le mouvement avec les omoplates.", "Reste dans ta position de flexion des hanches sans te redresser ou laisser tomber la poitrine pendant l''exercice.", "Contrôle la charge à la montée comme à la descente pour maximiser l''engagement musculaire et prévenir les blessures.", "Garde la tête dans une position neutre alignée avec ta colonne vertébrale, évite de regarder vers le haut ou vers le bas."]', '["Ne pas garder le dos droit peut entraîner des blessures au dos.", "Tirer avec les bras plutôt qu''avec les muscles du dos limite l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "bent over barbell row overhand grip"]', true, '2026-04-03 12:24:55.729528+00', '2026-04-03 12:24:55.729528+00', 'Position de départ : Tiens-toi droit, barre en main avec une prise en pronation (paumes vers le bas), les mains écartées à la largeur des épaules. Exécution : Tire la barre vers ton bas de poitrine, en gardant les coudes proches du corps, puis redescends lentement à la position initiale.', '["Ne pas garder le dos droit peut entraîner des blessures au dos.", "Tirer avec les bras plutôt qu''avec les muscles du dos limite l''efficacité de l''exercice."]', true, '["Set up with feet hip-width apart and grip the barbell with hands slightly wider than shoulders using an overhand grip", "Hinge at the hips and bend forward while keeping your back straight and core engaged, allowing the bar to hang at arm''s length", "Initiate the pull by squeezing your shoulder blades together and driving your elbows back toward your ribs", "Pull the barbell up toward your lower chest or upper abdomen while maintaining your bent-over position", "Pause briefly at the top of the movement, then slowly lower the bar back to the starting position with control", "Maintain tension in your back muscles throughout the entire range of motion"]', '["Place tes pieds à la largeur des hanches et saisis la barre avec les mains légèrement plus larges que les épaules en prise pronation", "Casse les hanches et penche-toi en avant tout en gardant le dos droit et les abdominaux contractés, la barre suspendue à bout de bras", "Lance le tirage en contractant les omoplates et en ramenant les coudes vers tes côtes", "Tire la barre vers ton bas de poitrine ou ton haut de l''abdomen tout en maintenant ta posture inclinée", "Fais une pause brève en haut du mouvement, puis redescends lentement la barre à la position de départ avec contrôle", "Maintiens la tension dans tes muscles du dos tout au long de l''exercice."]', '["Garde le dos droit et les abdos engagés pour protéger ta colonne vertébrale.", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras, en initiant le mouvement avec les omoplates.", "Reste dans ta position de flexion des hanches sans te redresser ou laisser tomber la poitrine pendant l''exercice.", "Contrôle la charge à la montée comme à la descente pour maximiser l''engagement musculaire et prévenir les blessures.", "Garde la tête dans une position neutre alignée avec ta colonne vertébrale, évite de regarder vers le haut ou vers le bas."]', '["Keep your back straight and core engaged throughout the movement to protect your spine", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Maintain a consistent hip-hinge position without standing up or dropping your chest during the exercise", "Control the weight on both the lifting and lowering phases to maximize muscle engagement and prevent injury", "Keep your head in a neutral position aligned with your spine rather than looking up or down"]', '6e4be416-7097-4301-bfb9-f62bc69f1fa7', 'bent-over-barbell-row-overhand-grip', NULL, NULL);
INSERT INTO public.exercises VALUES ('108df531-d27b-4110-9bc2-b38b8b5da233', 'Tirage Vertical Serré à la Taille', NULL, NULL, 'Close Grip Lat Pulldown to Waist', 'Back', '[]', 'Back', 'Intermediate', 4, '/videos/back/close-grip-lat-pulldown-to-waist.mp4', NULL, NULL, NULL, '/videos/thumbnails/close-grip-lat-pulldown-to-waist.jpg', NULL, '["Garde la poitrine relevée et évite d''arrondir les épaules tout au long du mouvement.", "Concentre-toi sur le travail de tes muscles du dos plutôt que sur tes bras en initiant le mouvement avec tes omoplates.", "Maintiens une légère inclinaison vers l''arrière pour optimiser l''angle de tirage et cibler la partie inférieure du latissimus dorsi.", "Contrôle le poids à chaque phase pour maximiser l''engagement musculaire et prévenir les blessures.", "Évite d''utiliser l''élan ou de balancer le torse pour terminer la répétition."]', '["Épaules arrondies pendant le mouvement.", "Utilisation de l''élan pour tirer la barre."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "close grip lat pulldown to waist"]', true, '2026-04-03 12:24:56.116633+00', '2026-04-03 12:24:56.116633+00', 'Commence assis sur la machine de tirage vertical avec les mains en prise serrée, paumes vers le haut. Tire la barre vers ta taille tout en gardant le torse bien droit, puis redescends lentement.', '["Épaules arrondies pendant le mouvement.", "Utilisation de l''élan pour tirer la barre."]', true, '["Adjust the knee pad to secure your legs and prevent your body from lifting during the exercise", "Grasp the bar with hands positioned closer than shoulder-width apart using an overhand grip", "Sit upright with your chest out and shoulders pulled back to establish proper posture", "Pull the bar down smoothly to your waist while leaning back slightly and squeezing your shoulder blades together", "Hold the contraction briefly at the bottom position", "Slowly return the bar to the starting position with control, allowing your arms to fully extend"]', '["Ajuste le coussin pour bloquer tes jambes et éviter que ton corps ne se soulève pendant l''exercice.", "Prends la barre avec les mains plus proches que la largeur des épaules en prise supinée.", "Reste bien droit, poitrine en avant et épaules en arrière pour une bonne posture.", "Tire la barre vers ta taille en te penchant légèrement en arrière et en serrant tes omoplates.", "Maintiens la contraction brièvement à la position inférieure.", "Redescends lentement la barre en contrôlant le mouvement, laisse tes bras s''étendre complètement."]', '["Garde la poitrine relevée et évite d''arrondir les épaules tout au long du mouvement.", "Concentre-toi sur le travail de tes muscles du dos plutôt que sur tes bras en initiant le mouvement avec tes omoplates.", "Maintiens une légère inclinaison vers l''arrière pour optimiser l''angle de tirage et cibler la partie inférieure du latissimus dorsi.", "Contrôle le poids à chaque phase pour maximiser l''engagement musculaire et prévenir les blessures.", "Évite d''utiliser l''élan ou de balancer le torse pour terminer la répétition."]', '["Keep your chest up and avoid rounding your shoulders forward throughout the entire movement", "Focus on pulling with your back muscles rather than just your arms by initiating the movement with your shoulder blades", "Maintain a slight backward lean to optimize the pulling angle and target the lower portion of the latissimus dorsi", "Control the weight on both the pulling and returning phases to maximize muscle engagement and prevent injury", "Avoid using momentum or swinging your torso to complete the repetition"]', '5ce18079-7df5-48e0-828e-63005b8eb3d1', 'close-grip-lat-pulldown-to-waist', NULL, NULL);
INSERT INTO public.exercises VALUES ('e02ebf85-d4f2-4627-bec9-d02e3c025e53', 'Fente Bulgare', NULL, 'تمرين القرفصاء البلغارية', 'Bulgarian split squat', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/bulgarian-split-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/bulgarian-split-squat.jpg', NULL, '["La majeure partie du poids sur la jambe avant", "Garde le torse droit", "Le genou avant doit suivre la direction des orteils", "Va en profondeur pour activer les fessiers", "L''équilibre peut être difficile au début"]', '["Pied arrière mal positionné", "Pencher le torse en avant", "Genou avant qui dépasse trop les orteils", "Ne pas descendre suffisamment", "Manque de contrôle lors du relevé"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "bulgarian split squat"]', true, '2026-04-03 12:24:55.80755+00', '2026-04-03 12:24:55.80755+00', 'Position de départ : Place-toi à 60-90 cm d''un banc, avec le pied arrière surélevé. Tes poids doivent être sur ta jambe avant. Exécution : Abaisse ton corps en fléchissant le genou avant jusqu''à ce que ta cuisse soit parallèle au sol, puis pousse avec le talon avant pour revenir à la position de départ.', '["Pied arrière mal positionné", "Pencher le torse en avant", "Genou avant qui dépasse trop les orteils", "Ne pas descendre suffisamment", "Manque de contrôle lors du relevé"]', true, '["Rear foot on bench behind you", "Front foot forward", "Lower until front thigh parallel", "Drive up through front heel", "Complete reps, switch legs"]', '["Pied arrière sur le banc derrière toi", "Pied avant en avant", "Abaisse jusqu''à ce que la cuisse avant soit parallèle", "Pousse avec le talon avant pour remonter", "Fais toutes les répétitions, puis change de jambe"]', '["La majeure partie du poids sur la jambe avant", "Garde le torse droit", "Le genou avant doit suivre la direction des orteils", "Va en profondeur pour activer les fessiers", "L''équilibre peut être difficile au début"]', '["Most weight on front leg", "Torso stays upright", "Front knee tracks over toes", "Go deep for glute activation", "Balance is challenging at first"]', 'cd6edab4-3f1e-477f-8a88-54f9c683c9de', 'bulgarian-split-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('a4a5ed9a-272d-4648-ba66-c1bd223d6a11', 'Élévations d''épaules avec haltères', NULL, NULL, 'Dumbbell Shrug', 'Back', '[]', 'Back', 'Beginner', 2, '/videos/back/dumbbell-shrug.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-shrug.jpg', NULL, '["Ne fais pas de rotations avec les épaules", "Garde la contraction en haut", "Permets aux trapèzes de s''étirer en bas", "Garde les bras droits", "N''hésite pas à augmenter le poids pour cet exercice"]', '["Ne pas lever les épaules assez haut", "Rouler les épaules au lieu de les hausser", "Tenir les bras pliés"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "dumbbell shrug"]', true, '2026-04-03 12:24:56.582545+00', '2026-04-03 12:24:56.582545+00', 'Position de départ : Tiens-toi bien droit, pieds écartés à la largeur des hanches, haltères dans chaque main, bras tendus le long du corps, paumes tournées vers toi. Exécution : Lève les épaules directement vers tes oreilles en contractant tes trapèzes, maintiens brièvement en haut, puis redescends lentement. Prêt à faire travailler ton dos ? C''est parti !', '["Ne pas lever les épaules assez haut", "Rouler les épaules au lieu de les hausser", "Tenir les bras pliés"]', true, '["Stand holding dumbbells at sides", "Arms straight, palms facing body", "Shrug shoulders straight up", "Hold at top", "Lower with control"]', '["Tiens les haltères sur les côtés", "Bras droits, paumes tournées vers toi", "Hausse les épaules vers le haut", "Maintiens en haut", "Redescends avec contrôle"]', '["Ne fais pas de rotations avec les épaules", "Garde la contraction en haut", "Permets aux trapèzes de s''étirer en bas", "Garde les bras droits", "N''hésite pas à augmenter le poids pour cet exercice"]', '["Don''t roll shoulders", "Hold the squeeze at top", "Let traps stretch at bottom", "Keep arms straight", "Heavier weight okay for this exercise"]', 'b150868d-c9c5-4f0f-a407-93d7e34b6ddc', 'dumbbell-shrug', NULL, NULL);
INSERT INTO public.exercises VALUES ('87dd318e-7d96-4c0c-aba2-a5ac4574ee51', 'Burpee sans saut', NULL, 'بوربي بلا القفز', 'Burpee (No jump)', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/burpee-no-jump.mp4', NULL, NULL, NULL, '/videos/thumbnails/burpee-no-jump.jpg', NULL, '["Gardez votre sangle abdominale engagée tout au long du mouvement pour protéger votre bas du dos", "Avancez et reculez un pied à la fois plutôt que de sauter pour réduire l''impact sur les articulations", "Maintenez une bonne forme lors des pompes avec une alignement droit du corps et un mouvement complet", "Contrôlez le rythme de chaque phase plutôt que de vous précipiter à travers le mouvement", "Concentrez-vous sur des transitions fluides entre chaque position pour maximiser l''engagement musculaire"]', '["Ne pas garder le dos droit pendant la pompe", "Faire des mouvements trop rapides et perdre le contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "burpee (no jump)"]', true, '2026-04-03 12:24:55.835545+00', '2026-04-03 12:24:55.835545+00', 'Position de départ : Tenez-vous droit, les pieds écartés à la largeur des hanches et les bras le long du corps. Exécution : Réalisez une séquence contrôlée en vous accroupissant, en marchant en position de planche, en effectuant une pompe, puis en revenant en position accroupie et en vous levant sans sauter.', '["Ne pas garder le dos droit pendant la pompe", "Faire des mouvements trop rapides et perdre le contrôle"]', true, '["Stand with feet hip-width apart, then squat down and place your hands on the floor in front of you", "Step your right foot back into plank position, then step your left foot back to join it", "Maintain a straight line from head to heels and perform one controlled push-up", "Step your right foot forward toward your hands, then step your left foot forward to return to squat position", "Stand up slowly and controlled, bringing your arms overhead to complete the movement", "Repeat the sequence maintaining steady breathing throughout"]', '["Tenez-vous avec les pieds écartés à la largeur des hanches, puis accroupissez-vous et placez vos mains au sol devant vous", "Avancez votre pied droit en position de planche, puis amenez votre pied gauche pour vous rejoindre", "Gardez une ligne droite de la tête aux talons et effectuez une pompe contrôlée", "Amenez votre pied droit vers vos mains, puis votre pied gauche pour retourner à la position accroupie", "Levez-vous lentement et de manière contrôlée, en levant les bras au-dessus de votre tête pour finir le mouvement", "Répétez la séquence en gardant une respiration régulière tout au long de l''exercice"]', '["Gardez votre sangle abdominale engagée tout au long du mouvement pour protéger votre bas du dos", "Avancez et reculez un pied à la fois plutôt que de sauter pour réduire l''impact sur les articulations", "Maintenez une bonne forme lors des pompes avec une alignement droit du corps et un mouvement complet", "Contrôlez le rythme de chaque phase plutôt que de vous précipiter à travers le mouvement", "Concentrez-vous sur des transitions fluides entre chaque position pour maximiser l''engagement musculaire"]', '["Keep your core engaged throughout the entire movement to protect your lower back", "Step back and forward one foot at a time rather than jumping to reduce impact on joints", "Maintain proper push-up form with straight body alignment and full range of motion", "Control the tempo of each phase rather than rushing through the movement", "Focus on smooth transitions between each position to maximize muscle engagement"]', 'b160ea44-725a-415f-919a-4edad64d3ce3', 'burpee-no-jump', NULL, NULL);
INSERT INTO public.exercises VALUES ('73fdddd9-3d51-4ebc-bb4a-df0be5b12d5f', 'Tirage Bent Over à la Barre, Prise Sous-Standard', NULL, 'تيراج بينت أوفير بار، grip تحتاني', 'Bent Over Barbell Row Underhand Grip', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/bent-over-barbell-row-underhand-grip.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-over-barbell-row-underhand-grip.jpg', NULL, '["Garde le dos droit tout au long du mouvement pour éviter les blessures et maximiser l''activation musculaire", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement avec les omoplates", "Maintiens une légère flexion des genoux et évite de te redresser complètement pendant l''exercice", "Contrôle la phase négative du mouvement pour augmenter le temps sous tension et améliorer le développement musculaire", "Garde la barre proche de ton corps tout au long du mouvement pour une biomécanique optimale"]', '["Se courber le dos pendant l''exercice", "Utiliser trop de poids et compromettre la forme"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "bent over barbell row underhand grip"]', true, '2026-04-03 12:24:55.732545+00', '2026-04-03 12:24:55.732545+00', 'Position de départ : Prends une barre avec les mains en prise sous-standard, paumes vers le haut, mains à la largeur des épaules. Exécution : Tire la barre vers le bas de ta poitrine, en gardant les coudes proches du corps, puis redescends lentement à la position initiale.', '["Se courber le dos pendant l''exercice", "Utiliser trop de poids et compromettre la forme"]', true, '["Set up with feet hip-width apart and grip the barbell with palms facing up, hands slightly wider than shoulders", "Hinge at the hips and lean forward maintaining a neutral spine with knees slightly bent", "Keep your core engaged and chest up as you initiate the pull by driving your elbows back", "Pull the barbell toward your lower chest while squeezing your shoulder blades together", "Pause briefly at the top of the movement feeling the contraction in your back muscles", "Lower the barbell slowly and under control back to the starting position"]', '["Place tes pieds à la largeur des hanches et saisis la barre avec les paumes vers le haut, mains légèrement plus larges que les épaules", "Incline-toi en avant en fléchissant les hanches, le dos droit et les genoux légèrement fléchis", "Active ton core et garde la poitrine relevée en tirant tes coudes vers l''arrière", "Tire la barre vers le bas de ta poitrine en serrant les omoplates", "Fais une pause en haut du mouvement en ressentant la contraction de ton dos", "Abaisse la barre lentement et de manière contrôlée jusqu''à la position de départ"]', '["Garde le dos droit tout au long du mouvement pour éviter les blessures et maximiser l''activation musculaire", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement avec les omoplates", "Maintiens une légère flexion des genoux et évite de te redresser complètement pendant l''exercice", "Contrôle la phase négative du mouvement pour augmenter le temps sous tension et améliorer le développement musculaire", "Garde la barre proche de ton corps tout au long du mouvement pour une biomécanique optimale"]', '["Keep your back straight throughout the entire movement to prevent injury and maximize muscle activation", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Maintain a slight bend in your knees and avoid standing completely upright during the exercise", "Control the negative portion of the lift to increase time under tension and improve muscle development", "Keep the barbell close to your body throughout the movement path for optimal biomechanics"]', '716ba91e-0ab4-4f1f-bbd9-dd06e25e0da6', 'bent-over-barbell-row-underhand-grip', NULL, NULL);
INSERT INTO public.exercises VALUES ('16d07938-fd92-4e02-957b-1d0f962dfb39', 'Posture du Arc', NULL, 'وضعية القوس', 'Bow pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/bow-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/bow-pose.jpg', NULL, '["Garde les genoux à la largeur des hanches tout au long de l''exercice.", "Pousse tes chevilles dans tes mains pour te soulever davantage.", "Active ton cœur pour éviter de comprimer le bas du dos."]', '["Ne pas engager le centre du corps.", "Saisir les chevilles avec une tension excessive."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "bow pose"]', true, '2026-04-03 12:24:55.781076+00', '2026-04-03 12:24:55.781076+00', 'Prends position sur le ventre, les bras le long du corps et les jambes tendues à l''arrière. En soulevant simultanément le torse et les jambes, saisis tes chevilles pour former une belle courbe avec ta colonne vertébrale.', '["Ne pas engager le centre du corps.", "Saisir les chevilles avec une tension excessive."]', true, '["Lie face down on your mat with arms alongside your body.", "Bend your knees and reach back to grab your ankles.", "Inhale and lift your chest and thighs off the floor simultaneously.", "Hold the pose, breathing steadily, then release on an exhale."]', '["Allonge-toi sur le ventre sur ton tapis, les bras le long du corps.", "Plie les genoux et attrape tes chevilles.", "Inspire et soulève simultanément ta poitrine et tes cuisses du sol.", "Maintiens la posture en respirant régulièrement, puis relâche en expirant."]', '["Garde les genoux à la largeur des hanches tout au long de l''exercice.", "Pousse tes chevilles dans tes mains pour te soulever davantage.", "Active ton cœur pour éviter de comprimer le bas du dos."]', '["Keep knees hip-width apart throughout.", "Press your ankles into your hands to lift higher.", "Avoid compressing the lower back by engaging your core."]', '4c799907-a832-42b2-b9b3-bfb75a68c840', 'bow-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('6a79a421-9338-4faa-baa4-77e43cd5785f', 'Coup de pied avant avec câble', NULL, NULL, 'Cable Front Kick', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 4, '/videos/quadriceps/cable-front-kick.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-front-kick.jpg', NULL, '["Garde ton torse droit et évite de te pencher en arrière pendant le mouvement de coup de pied", "Mets l''accent sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement musculaire et prévenir les blessures", "Vérifie que le strap de cheville est bien fixé pour éviter qu''il ne glisse pendant l''exercice", "Commence par un poids léger pour maîtriser le mouvement avant de passer à une résistance plus lourde", "Maintiens une tension constante dans ton tronc pour protéger ton bas du dos tout au long du mouvement"]', '["Ne pas engager le tronc peut provoquer des douleurs au dos", "Pencher le dos en arrière pendant l''exercice", "Effectuer le mouvement trop rapidement peut entraîner une mauvaise exécution"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "cable", "cable front kick"]', true, '2026-04-03 12:24:55.880764+00', '2026-04-03 12:24:55.880764+00', 'Position de départ : Tiens-toi en face d''une poulie basse, le strap autour de ta cheville et le pied légèrement en avant. Exécution : Étends ta jambe vers l''avant en la gardant droite, puis redescends lentement à la position de départ et répète avec l''autre jambe.', '["Ne pas engager le tronc peut provoquer des douleurs au dos", "Pencher le dos en arrière pendant l''exercice", "Effectuer le mouvement trop rapidement peut entraîner une mauvaise exécution"]', true, '["Attach the ankle strap to the low cable pulley and secure it firmly around your ankle", "Stand feet hip-width apart, holding the machine frame for balance", "Engage your core and maintain an upright posture with slight bend in your supporting leg", "Drive your attached leg forward in a smooth kicking motion, focusing on using your quadriceps", "Pause briefly at the top of the movement when your leg is fully extended", "Slowly lower your leg back to the starting position with control, resisting the weight"]', '["Fixe le strap de cheville à la poulie basse et assure-toi qu''il est bien attaché autour de ta cheville", "Positionne-toi les pieds à la largeur des hanches, en t''appuyant sur le cadre de la machine pour l''équilibre", "Engage ton tronc et garde une posture droite avec une légère flexion de ta jambe d''appui", "Mène ta jambe attachée vers l''avant dans un mouvement de coup de pied fluide, en te concentrant sur l''utilisation des quadriceps", "Marque une pause quelques instants en haut du mouvement quand ta jambe est complètement allongée", "Redescends ta jambe lentement à la position de départ avec contrôle en résistant au poids"]', '["Garde ton torse droit et évite de te pencher en arrière pendant le mouvement de coup de pied", "Mets l''accent sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement musculaire et prévenir les blessures", "Vérifie que le strap de cheville est bien fixé pour éviter qu''il ne glisse pendant l''exercice", "Commence par un poids léger pour maîtriser le mouvement avant de passer à une résistance plus lourde", "Maintiens une tension constante dans ton tronc pour protéger ton bas du dos tout au long du mouvement"]', '["Keep your torso upright and avoid leaning backward during the kicking motion", "Focus on controlled movement rather than speed to maximize muscle engagement and prevent injury", "Ensure the ankle strap is securely fastened to prevent it from slipping during the exercise", "Start with lighter weight to master the movement pattern before progressing to heavier resistance", "Maintain constant tension in your core to protect your lower back throughout the movement"]', '20500648-961e-4344-bb9b-c775ffc1fe71', 'cable-front-kick', NULL, NULL);
INSERT INTO public.exercises VALUES ('2fe47ae3-e760-455d-b853-cb138fc0bbcb', 'Tirage Bent-Over à la Smith Machine', NULL, NULL, 'Smith Machine Bent Over Row Overhand Grip', 'Back', '[]', 'Back', 'Intermediate', 8, '/videos/back/smith-machine-bent-over-row-overhand-grip.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-bent-over-row-overhand-grip.jpg', NULL, '["Garde les abdos serrés et le dos neutre durant tout l''exercice pour protéger ta région lombaire.", "Concentre-toi sur le tirage avec les muscles du dos plutôt qu''avec les bras, en commençant chaque répétition par la rétraction des omoplates.", "Évite l''utilisation d''élan ou de balancement pour rester fluide et contrôler le mouvement dans les deux sens.", "Garde les coudes proches du corps, sans les écarter, pour maximiser l''activation des muscles du dos.", "Assure-toi de fléchir les hanches plutôt que d''arrondir le dos pour adopter la position incliné."]', '["Ne pas tirer avec les bras au lieu du dos.", "Arrondir le dos pendant l''inclinaison."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "smith machine bent over row overhand grip"]', true, '2026-04-03 12:24:59.281653+00', '2026-04-03 12:24:59.281653+00', 'Positionne-toi devant la machine Smith avec les paumes vers le bas, les mains à la largeur des épaules. Tire la barre vers le bas de la poitrine tout en gardant le dos droit, puis abaisse-la lentement à la position de départ.', '["Ne pas tirer avec les bras au lieu du dos.", "Arrondir le dos pendant l''inclinaison."]', true, '["Set the Smith machine bar at an appropriate height where you can maintain proper hip hinge position with the bar at mid-shin level", "Position feet hip-width apart and grip the bar with an overhand grip slightly wider than shoulders", "Hinge at the hips while maintaining a neutral spine, keeping your chest up and core engaged throughout the movement", "Initiate the pull by retracting your shoulder blades first, then drive your elbows back toward your ribs", "Squeeze your back muscles at the top of the movement, then slowly lower the bar back to starting position", "Maintain the hip-hinged position throughout all repetitions without allowing your torso to rise up"]', '["Régle la barre de la Smith machine à une hauteur adaptée pour garder le dos droit à mi-mollet.", "Positionne tes pieds à la largeur des hanches et saisis la barre avec une prise pronation légèrement plus large que les épaules.", "Incline-toi en gardant le dos neutre, avec la poitrine haute et les abdos engagés tout au long de l''exercice.", "Commence le tirage en rétractant d''abord les omoplates, puis en dirigeant les coudes vers tes côtes.", "Contracte tes muscles du dos en haut du mouvement, puis redescends lentement la barre à la position de départ.", "Maintiens la position inclinée pendant toutes les répétitions, sans laisser ton torse remonter."]', '["Garde les abdos serrés et le dos neutre durant tout l''exercice pour protéger ta région lombaire.", "Concentre-toi sur le tirage avec les muscles du dos plutôt qu''avec les bras, en commençant chaque répétition par la rétraction des omoplates.", "Évite l''utilisation d''élan ou de balancement pour rester fluide et contrôler le mouvement dans les deux sens.", "Garde les coudes proches du corps, sans les écarter, pour maximiser l''activation des muscles du dos.", "Assure-toi de fléchir les hanches plutôt que d''arrondir le dos pour adopter la position incliné."]', '["Keep your core tight and maintain a neutral spine throughout the entire movement to protect your lower back", "Focus on pulling with your back muscles rather than your arms by initiating each rep with shoulder blade retraction", "Avoid using momentum or swinging the weight, maintaining smooth and controlled movement in both directions", "Keep your elbows close to your body rather than flaring them out wide to maximize back muscle activation", "Ensure you''re hinging at the hips rather than rounding your back to achieve the bent-over position"]', 'aeea2f3a-bcd5-44a0-9ca7-57977001e382', 'smith-machine-bent-over-row-overhand-grip', NULL, NULL);
INSERT INTO public.exercises VALUES ('0ac1657f-ff57-444c-9a35-cdcb1b72526f', 'Curl Prêcheur avec Câble', NULL, 'كرو ليلي بكابل', 'Cable Preacher Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 4, '/videos/biceps/cable-preacher-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-preacher-curl.jpg', NULL, '["Garde tes bras supérieurs totalement immobiles contre le coussin tout au long de l''exercice.", "Évite de laisser le poids tirer tes bras en extension complète en bas pour prévenir tout hyperextension du coude.", "Utilise un tempo contrôlé avec 2 secondes de montée et 3 secondes de descente pour un engagement musculaire optimal.", "Choisis un poids qui te permet de maintenir une bonne forme pendant toute la série, sans utiliser d''élan ou de balancement du corps.", "Interromps l''exercice immédiatement si tu ressens des douleurs aigües au niveau des coudes ou des épaules."]', '["Ne pas ajuster correctement le banc de prêcheur.", "Laisser le mouvement être trop dynamique avec des balancements."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "cable", "cable preacher curl"]', true, '2026-04-03 12:24:55.939053+00', '2026-04-03 12:24:55.939053+00', 'Position de départ : Fais face à une poulie basse avec une barre droite fixée, les bras reposant sur un banc de prêcheur. Exécution : Plie les coudes pour soulever la barre vers tes épaules, puis redescends de manière contrôlée.', '["Ne pas ajuster correctement le banc de prêcheur.", "Laisser le mouvement être trop dynamique avec des balancements."]', true, '["Adjust the preacher bench so your chest is firmly against the pad and your armpits align with the top edge", "Set the cable pulley to the lowest position and attach a straight bar or EZ-curl bar handle", "Grasp the handle with an underhand grip, hands shoulder-width apart, and position your upper arms flat against the angled pad", "Keep your feet planted firmly on the floor and maintain a straight back throughout the movement", "Curl the weight up using only your biceps while keeping your wrists straight and upper arms pressed against the pad", "Lower the weight slowly and under control, stopping just short of full arm extension to maintain tension"]', '["Ajuste le banc de prêcheur pour que ta poitrine soit bien contre le coussin et que tes aisselles soient alignées avec le bord supérieur.", "Positionne la poulie à la plus basse option et fixe une barre droite ou une barre EZ à la poignée.", "Saisis la poignée avec une prise en supination, les mains à la largeur des épaules, et positionne tes bras supérieurs à plat contre le coussin incliné.", "Garde tes pieds fermement ancrés au sol et maintiens le dos droit pendant toute l''exécution.", "Enroule le poids vers le haut en utilisant uniquement tes biceps, tout en gardant les poignets droits et les bras supérieurs pressés contre le coussin.", "Abaisse le poids lentement et de manière contrôlée, en t''arrêtant juste avant l''extension complète des bras pour conserver la tension."]', '["Garde tes bras supérieurs totalement immobiles contre le coussin tout au long de l''exercice.", "Évite de laisser le poids tirer tes bras en extension complète en bas pour prévenir tout hyperextension du coude.", "Utilise un tempo contrôlé avec 2 secondes de montée et 3 secondes de descente pour un engagement musculaire optimal.", "Choisis un poids qui te permet de maintenir une bonne forme pendant toute la série, sans utiliser d''élan ou de balancement du corps.", "Interromps l''exercice immédiatement si tu ressens des douleurs aigües au niveau des coudes ou des épaules."]', '["Keep your upper arms completely stationary against the preacher pad throughout the entire range of motion", "Avoid letting the weight pull your arms into full extension at the bottom to prevent elbow hyperextension", "Use a controlled tempo with a 2-second lift and 3-second lowering phase for optimal muscle engagement", "Select a weight that allows you to maintain proper form for the entire set without using momentum or body swing", "Stop the exercise immediately if you feel any sharp pain in your elbows or shoulders"]', 'ca7a2f9d-3af1-40cd-a33f-431f437a2902', 'cable-preacher-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('de9d4a7a-26c2-4332-9429-dca8e7957fc2', 'Tirage à la corde au câble', NULL, NULL, 'Cable Rope Face Pull', 'Shoulders', '[]', 'Shoulders', 'Beginner', 4, '/videos/shoulders/cable-rope-face-pull.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-rope-face-pull.jpg', NULL, '["Garde tes coudes plus hauts que tes poignets durant tout le mouvement pour cibler correctement les deltoïdes arrière", "Concentre-toi sur la contraction de tes omoplates plutôt que sur un simple tirage avec les bras", "Utilise un poids qui te permet de conserver une forme parfaite - l''activation prime sur le poids lourd dans cet exercice", "Tire la corde jusqu''au niveau de ton visage, pas au niveau de ta poitrine ou de ton cou, pour maximiser l''engagement du deltoïde postérieur", "Maintiens une légère inclinaison en avant et un core engagé pour éviter d''utiliser l''élan"]', '["Ne pas garder les coudes suffisamment hauts", "Utiliser trop de poids et perdre la forme de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "cable", "cable rope face pull"]', true, '2026-04-03 12:24:55.949887+00', '2026-04-03 12:24:55.949887+00', 'Position de départ : Fais face à un poulie haute avec une corde attachée. Exécution : Tire la corde vers ta poitrine en gardant les coudes hauts, puis retourne lentement à la position initiale.', '["Ne pas garder les coudes suffisamment hauts", "Utiliser trop de poids et perdre la forme de l''exercice"]', true, '["Set the cable machine to upper chest height and attach a rope handle", "Stand arm''s length from the machine with feet shoulder-width apart for stability", "Grasp the rope handles with palms facing down and step back until there is tension in the cable", "Pull the rope straight toward your face while squeezing your shoulder blades together", "Separate the rope handles as they reach your face, leading with your elbows", "Slowly return to the starting position with control, maintaining tension throughout the movement"]', '["Règle la machine à câble à hauteur de poitrine supérieure et attache une poignée en corde", "Place-toi à une longueur de bras de la machine, les pieds écartés à la largeur des épaules pour la stabilité", "Saisis les poignées de corde avec les paumes vers le bas et recule jusqu''à ce qu''il y ait une tension dans le câble", "Tire la corde directement vers ton visage tout en contractant les omoplates", "Sépare les poignées au moment où elles atteignent ton visage, en menant avec les coudes", "Retoure lentement à la position initiale en contrôlant le mouvement, en maintenant la tension tout au long de l''exercice"]', '["Garde tes coudes plus hauts que tes poignets durant tout le mouvement pour cibler correctement les deltoïdes arrière", "Concentre-toi sur la contraction de tes omoplates plutôt que sur un simple tirage avec les bras", "Utilise un poids qui te permet de conserver une forme parfaite - l''activation prime sur le poids lourd dans cet exercice", "Tire la corde jusqu''au niveau de ton visage, pas au niveau de ta poitrine ou de ton cou, pour maximiser l''engagement du deltoïde postérieur", "Maintiens une légère inclinaison en avant et un core engagé pour éviter d''utiliser l''élan"]', '["Keep your elbows higher than your wrists throughout the entire movement to properly target the rear delts", "Focus on squeezing your shoulder blades together rather than just pulling with your arms", "Use a weight that allows you to maintain perfect form - this exercise is about activation, not heavy loading", "Pull the rope to your face level, not to your chest or neck, to maximize rear deltoid engagement", "Maintain a slight forward lean and engaged core to prevent using momentum"]', '7665b7ae-4cea-4591-bafe-e73cdaa5beac', 'cable-rope-face-pull', NULL, NULL);
INSERT INTO public.exercises VALUES ('1dce0b69-8446-41af-8c73-17149654e3df', 'Tirage Horizontal Assis avec Prise Neutre', NULL, NULL, 'Seated Cable Row Neutral Grip', 'Back', '[]', 'Back', 'Beginner', 4, '/videos/back/seated-cable-row-neutral-grip.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-cable-row-neutral-grip.jpg', NULL, '["Garde les abdominaux contractés tout au long du mouvement pour protéger le bas du dos et maintenir une bonne posture", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec les bras, en menant le mouvement avec les coudes", "Évite d''utiliser l''élan ou de te pencher trop en arrière pendant la phase de tirage", "Maintiens une colonne vertébrale neutre et évite d''arrondir les épaules vers l''avant", "Contrôle le poids à la fois lors du tirage et du retour pour un engagement musculaire maximum"]', '["Ne pas ajuster la hauteur du siège, ce qui peut nuire à la posture", "Utiliser trop de poids, ce qui entraîne une mauvaise exécution du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "seated cable row neutral grip"]', true, '2026-04-03 12:24:58.771934+00', '2026-04-03 12:24:58.771934+00', 'Ouvre bien les épaules et prépare-toi à travailler ton dos. Assieds-toi sur la machine à câble, prends les poignées avec les paumes face à face et reste concentré. Tu es prêt ? C''est parti !', '["Ne pas ajuster la hauteur du siège, ce qui peut nuire à la posture", "Utiliser trop de poids, ce qui entraîne une mauvaise exécution du mouvement"]', true, '["Adjust the seat height so your arms are parallel to the floor when grasping the handle", "Sit with your chest up, shoulders back, and maintain a slight forward lean from your hips", "Initiate the pull by retracting your shoulder blades first, then pull your elbows back close to your sides", "Pull the handle to your lower ribcage while keeping your torso stable", "Squeeze your shoulder blades together at the end of the movement", "Slowly extend your arms back to the starting position while maintaining tension"]', '["Ajuste la hauteur du siège pour que tes bras soient parallèles au sol lors de la prise en main des poignées", "Assieds-toi avec la poitrine en avant, les épaules en arrière, et penche-toi légèrement vers l''avant depuis les hanches", "Commence le tirage en rétractant d''abord tes omoplates, puis tire tes coudes près de ton corps", "Tire la poignée vers le bas de ta cage thoracique tout en gardant le torse stable", "Ramène tes omoplates ensemble à la fin du mouvement", "Étends lentement tes bras pour revenir à la position de départ tout en maintenant la tension"]', '["Garde les abdominaux contractés tout au long du mouvement pour protéger le bas du dos et maintenir une bonne posture", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec les bras, en menant le mouvement avec les coudes", "Évite d''utiliser l''élan ou de te pencher trop en arrière pendant la phase de tirage", "Maintiens une colonne vertébrale neutre et évite d''arrondir les épaules vers l''avant", "Contrôle le poids à la fois lors du tirage et du retour pour un engagement musculaire maximum"]', '["Keep your core engaged throughout the movement to protect your lower back and maintain proper posture", "Focus on pulling with your back muscles rather than your arms by leading with your elbows", "Avoid using momentum or leaning too far back during the pulling phase", "Maintain a neutral spine position and avoid rounding your shoulders forward", "Control the weight on both the pulling and returning phases for maximum muscle engagement"]', '5025051b-e58e-42aa-ae78-5a9b11ef129c', 'seated-cable-row-neutral-grip', NULL, NULL);
INSERT INTO public.exercises VALUES ('f9c699f2-682f-4192-ba34-9c60c0e9707c', 'Superman Crunches', NULL, 'ركلات سوبرمان', 'Superman crunches', 'Back', '[]', 'Back', 'Intermediate', 16, '/videos/back/superman-crunches.mp4', NULL, NULL, NULL, '/videos/thumbnails/superman-crunches.jpg', NULL, '["Effectuez des mouvements lents et contrôlés pour maximiser l''activation musculaire et éviter les blessures", "Concentrez-vous sur la contraction des fessiers et des muscles du bas du dos au lieu de forcer le cou", "Ne soulevez que ce qui est confortable - un mouvement excessif peut causer des douleurs au bas du dos", "Expirez lors de la phase de levée et inspirez en redescendant", "Arrêtez immédiatement si vous ressentez une douleur aiguë dans le bas du dos"]', '["Lever trop haut et forcer le bas du dos", "Oublier de garder le cou dans l''alignement neutre", "Se précipiter dans le mouvement plutôt que de contrôler chaque répétition", "Ne pas utiliser suffisamment les fessiers et les muscles du dos pour soulever"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "superman crunches"]', true, '2026-04-03 12:24:59.67177+00', '2026-04-03 12:24:59.67177+00', 'Position de départ : Allongez-vous sur le ventre, bras tendus devant vous et jambes droites, en gardant le dos droit. Action : Soulevez simultanément votre poitrine, vos bras et vos jambes du sol en contractant le bas du dos et les fessiers, puis redescendez avec contrôle.', '["Lever trop haut et forcer le bas du dos", "Oublier de garder le cou dans l''alignement neutre", "Se précipiter dans le mouvement plutôt que de contrôler chaque répétition", "Ne pas utiliser suffisamment les fessiers et les muscles du dos pour soulever"]', true, '["Lie face down on a mat with arms extended overhead and legs straight", "Keep your neck in neutral alignment by looking down at the floor throughout the movement", "Simultaneously lift your chest, arms, and legs off the ground by squeezing your glutes and lower back muscles", "Hold the top position for 1-2 seconds while maintaining tension", "Slowly lower your chest, arms, and legs back to the starting position with control", "Repeat for the desired number of repetitions while maintaining proper form"]', '["Allongez-vous sur un tapis, bras tendus devant et jambes droites", "Maintenez votre cou dans l''alignement en regardant le sol durant tout le mouvement", "Soulevez simultanément votre poitrine, vos bras et vos jambes en contractant les fessiers et les muscles du bas du dos", "Maintenez la position haute pendant 1 à 2 secondes tout en gardant la tension", "Redescendez lentement votre poitrine, bras et jambes à la position de départ avec contrôle", "Répétez pour le nombre désiré de répétitions en gardant la forme correcte"]', '["Effectuez des mouvements lents et contrôlés pour maximiser l''activation musculaire et éviter les blessures", "Concentrez-vous sur la contraction des fessiers et des muscles du bas du dos au lieu de forcer le cou", "Ne soulevez que ce qui est confortable - un mouvement excessif peut causer des douleurs au bas du dos", "Expirez lors de la phase de levée et inspirez en redescendant", "Arrêtez immédiatement si vous ressentez une douleur aiguë dans le bas du dos"]', '["Keep movements slow and controlled to maximize muscle activation and prevent injury", "Focus on squeezing your glutes and lower back muscles rather than straining your neck", "Only lift as high as comfortable - excessive range of motion can cause lower back strain", "Breathe out during the lifting phase and breathe in while lowering back down", "Stop immediately if you experience any sharp pain in your lower back"]', 'b627fc87-cf16-443b-b87d-d1ba39ed8ca9', 'superman-crunches', NULL, NULL);
INSERT INTO public.exercises VALUES ('d1ebdd35-69eb-41eb-9c68-4c703e6d15ca', 'Étirement des mollets (gauche)', NULL, 'تمارين لتمديد الساق (اليسار)', 'Calf stretch (left)', 'Calves', '[]', 'Calves', 'Beginner', 16, '/videos/calves/calf-stretch-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/calf-stretch-left.jpg', NULL, '["Assure-toi que tes mains sont bien ancrées et tes épaules directement au-dessus de tes poignets pour plus de stabilité", "Concentre-toi sur la pression du talon de la jambe arrière vers le bas pour maximiser l''étirement du mollet", "Maintiens ton tronc engagé pour éviter que les hanches ne s''affaissent ou que le dos ne se cambre", "Respire profondément et n''oublie pas de ne pas retenir ta respiration pendant l''étirement", "Si l''étirement est trop intense, plie légèrement le genou arrière pour réduire la tension"]', '["Ne pas aligner les épaules au-dessus des poignets", "Relâcher la tension dans le tronc"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["calves", "bodyweight", "calf stretch (left)"]', true, '2026-04-03 12:24:56.021633+00', '2026-04-03 12:24:56.021633+00', 'Position de départ : Mets-toi en position de planche, les mains bien ancrées au sol, le corps bien droit et un pied légèrement en avant. Exécution : Reste dans cette position statique pour étirer intensément le muscle du mollet de la jambe arrière tout en gardant la forme de planche correcte.', '["Ne pas aligner les épaules au-dessus des poignets", "Relâcher la tension dans le tronc"]', true, '["Start in a high plank position with hands shoulder-width apart and arms straight", "Step your left foot slightly forward while keeping your right leg extended behind you", "Press your right heel down toward the ground to intensify the calf stretch", "Keep your core engaged and maintain a straight line from head to heels", "Hold the position for 20-30 seconds while breathing steadily", "Switch sides to stretch the opposite calf"]', '["Adopte une position de planche haute avec les mains écartées à la largeur des épaules et les bras tendus", "Avance ton pied gauche légèrement en avant tout en gardant ta jambe droite étendue derrière toi", "Abaisse ton talon droit vers le sol pour intensifier l''étirement du mollet", "Engage ton tronc et assure-toi de maintenir une ligne droite de la tête aux talons", "Reste dans cette position pendant 20 à 30 secondes en respirant régulièrement", "Change de côté pour étirer l''autre mollet"]', '["Assure-toi que tes mains sont bien ancrées et tes épaules directement au-dessus de tes poignets pour plus de stabilité", "Concentre-toi sur la pression du talon de la jambe arrière vers le bas pour maximiser l''étirement du mollet", "Maintiens ton tronc engagé pour éviter que les hanches ne s''affaissent ou que le dos ne se cambre", "Respire profondément et n''oublie pas de ne pas retenir ta respiration pendant l''étirement", "Si l''étirement est trop intense, plie légèrement le genou arrière pour réduire la tension"]', '["Keep your hands firmly planted and shoulders directly over your wrists for stability", "Focus on pressing the heel of the back leg down to maximize the calf stretch", "Maintain core engagement throughout to prevent sagging hips or arching back", "Breathe deeply and avoid holding your breath during the stretch", "If the stretch feels too intense, slightly bend the back knee to reduce tension"]', '90924318-0ca7-46ec-9e87-36b80e02196f', 'calf-stretch-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('214f91cd-2446-4fa6-b2c0-fa8682199c9b', 'Posture du Chameau', NULL, NULL, 'Camel pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/camel-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/camel-pose.jpg', NULL, '["Poussez vos hanches vers l''avant pour protéger votre bas du dos.", "Gardez le cou neutre ou inclinez-le doucement en arrière.", "Activez votre sangle abdominale tout au long du mouvement."]', '["Ne pas pousser les hanches vers l''avant.", "Incliner la tête trop loin en arrière."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "camel pose"]', true, '2026-04-03 12:24:56.037501+00', '2026-04-03 12:24:56.037501+00', 'Position de départ : À genoux, avec les tibias parallèles, les hanches au-dessus des genoux, et les mains sur le bas du dos pour le soutien. Exécution : Inclinez-vous lentement en arrière, une main à la fois vers vos talons, tout en soulevant la poitrine et en ouvrant votre cœur.', '["Ne pas pousser les hanches vers l''avant.", "Incliner la tête trop loin en arrière."]', true, '["Kneel on the mat with knees hip-width apart and thighs perpendicular to the floor.", "Place your hands on your lower back with fingers pointing down.", "Inhale, lift your chest, and slowly lean back.", "If comfortable, reach your hands back to your heels."]', '["À genoux sur le tapis, écartez les genoux à la largeur des hanches et gardez les cuisses perpendiculaires au sol.", "Posez vos mains sur le bas du dos, les doigts dirigés vers le bas.", "Inspirez, soulevez la poitrine et inclinez-vous doucement en arrière.", "Si vous vous sentez à l''aise, atteignez vos mains vers vos talons."]', '["Poussez vos hanches vers l''avant pour protéger votre bas du dos.", "Gardez le cou neutre ou inclinez-le doucement en arrière.", "Activez votre sangle abdominale tout au long du mouvement."]', '["Press your hips forward to protect your lower back.", "Keep your neck neutral or gently extend it back.", "Engage your core throughout the backbend."]', 'cb06c2a3-ef02-4e60-b9ab-7d692fa97bc4', 'camel-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('56ca2692-e9f8-441e-a4df-59f9c9ff0689', 'Écarté assis large', NULL, NULL, 'Seated wide angle straddle', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/seated-wide-angle-straddle.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-wide-angle-straddle.jpg', NULL, '["Ne courbez pas le dos, ouvrez le torse !", "Gardez vos jambes actives et les pieds flexibles.", "Avancez seulement jusqu''où vous pouvez tout en gardant le dos plat."]', '["Ne pas engager les muscles des jambes lors de l''étirement.", "Oublier de garder le dos droit en avançant."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "seated wide angle straddle"]', true, '2026-04-03 12:24:58.941239+00', '2026-04-03 12:24:58.941239+00', 'Travaille intensément tes ischio-jambiers tout en améliorant ta flexibilité !', '["Ne pas engager les muscles des jambes lors de l''étirement.", "Oublier de garder le dos droit en avançant."]', true, '["Sit on the floor and open your legs wide to the sides.", "Keep your toes and kneecaps pointing up.", "Inhale to lengthen your spine, then fold forward from the hips.", "Walk your hands forward on the floor in front of you."]', '["Asseyez-vous sur le sol et écartez largement vos jambes.", "Gardez les orteils et les genoux dirigés vers le haut.", "Inspirez pour allonger votre colonne vertébrale, puis pliez-vous en avant depuis les hanches.", "Avancez vos mains sur le sol devant vous."]', '["Ne courbez pas le dos, ouvrez le torse !", "Gardez vos jambes actives et les pieds flexibles.", "Avancez seulement jusqu''où vous pouvez tout en gardant le dos plat."]', '["Do not round your back — lead with your chest.", "Keep your legs active and feet flexed.", "Only go as far as you can with a flat back."]', 'f749ef2b-7e02-4c5b-94fd-abc1c876b0ee', 'seated-wide-angle-straddle', NULL, NULL);
INSERT INTO public.exercises VALUES ('c0967964-d6c6-428f-b4a2-3bc6da9e5b32', 'Chair Sit Ups', NULL, 'Sit Ups fi l-Qa3da', 'Chair sit ups', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/chair-sit-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/chair-sit-ups.jpg', NULL, '["Garde le bas de ton dos bien plaqué contre le tapis pour protéger ta colonne vertébrale", "Concentre-toi sur le soulèvement avec tes muscles abdominaux plutôt que de tirer sur ton cou", "Maintiens le pli à 90 degrés dans tes genoux durant tout l''exercice", "Contrôle les phases ascendante et descendante du mouvement pour une efficacité maximale", "Expire en montant et inspire en redescendant"]', '["Ne pas maintenir le bas du dos au sol", "Tirer sur le cou au lieu de se concentrer sur les abdominaux"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "chair sit ups"]', true, '2026-04-03 12:24:56.064054+00', '2026-04-03 12:24:56.064054+00', 'Position de départ : Allonge-toi sur le dos, les genoux pliés à 90 degrés, les pieds en l''air comme si tu étais assis sur une chaise invisible.', '["Ne pas maintenir le bas du dos au sol", "Tirer sur le cou au lieu de se concentrer sur les abdominaux"]', true, '["Lie flat on your back on a mat with your arms positioned alongside your head for support", "Bend your knees to 90 degrees and lift your feet off the ground, positioning your legs as if sitting in an invisible chair", "Engage your core muscles and slowly lift your shoulders and upper back off the ground", "Crunch upward while keeping your lower back pressed against the mat and maintaining the chair leg position", "Lower your shoulders back down with control, maintaining tension in your core throughout", "Keep your legs stable in the elevated position throughout all repetitions"]', '["Allonge-toi à plat sur le dos sur un tapis, les bras positionnés le long de ta tête pour le soutien", "Plie tes genoux à 90 degrés et soulève tes pieds du sol, en gardant tes jambes comme si tu étais assis sur une chaise invisible", "Engage tes muscles abdominaux et soulève lentement tes épaules et le haut de ton dos du sol", "Effectue un mouvement de crunch en montant, tout en gardant le bas de ton dos collé au tapis et la position des jambes maintenue", "Redescends tes épaules avec contrôle, gardant la tension dans tes abdominaux tout au long de l''exercice", "Maintiens tes jambes stables en position élevée pendant toutes les répétitions"]', '["Garde le bas de ton dos bien plaqué contre le tapis pour protéger ta colonne vertébrale", "Concentre-toi sur le soulèvement avec tes muscles abdominaux plutôt que de tirer sur ton cou", "Maintiens le pli à 90 degrés dans tes genoux durant tout l''exercice", "Contrôle les phases ascendante et descendante du mouvement pour une efficacité maximale", "Expire en montant et inspire en redescendant"]', '["Keep your lower back pressed firmly against the mat to protect your spine", "Focus on lifting with your abdominal muscles rather than pulling on your neck", "Maintain the 90-degree bend in your knees throughout the entire exercise", "Control both the upward and downward phases of the movement for maximum effectiveness", "Breathe out as you crunch up and breathe in as you lower down"]', '89b62000-867f-4f98-b24c-ad9b5708d015', 'chair-sit-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('7cd376ba-f5c2-44ee-b5fc-5cdea7ea1ed2', 'Étirement debout des ischio-jambiers (G)', NULL, NULL, 'Standing Hamstring Stretch (L)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/standing-hamstring-stretch-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-hamstring-stretch-l.jpg', NULL, '["Garde le dos droit pendant tout le mouvement pour éviter d''arrondir la colonne vertébrale", "Concentre-toi sur l''inclinaison au niveau des hanches plutôt que de plier la taille", "Tu devrais ressentir l''étirement à l''arrière de ta cuisse gauche, pas dans le bas du dos", "Respire profondément et évite de rebondir ou de forcer l''étirement"]', '["Arrondir le dos pendant l''étirement", "Pencher le torse sans passer par les hanches"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "standing hamstring stretch (l)"]', true, '2026-04-03 12:24:59.548267+00', '2026-04-03 12:24:59.548267+00', 'Position initiale : Tiens-toi debout, les pieds écartés à la largeur des hanches, puis avance le pied gauche d''environ 60-90 cm avec le talon au sol et les orteils dirigés vers le haut. Exécution : Incline-toi au niveau des hanches et penche-toi en avant en gardant le dos droit, en visant tes orteils gauches jusqu''à sentir l''étirement à l''arrière de ta cuisse gauche.', '["Arrondir le dos pendant l''étirement", "Pencher le torse sans passer par les hanches"]', true, '["Stand with feet hip-width apart and step your left foot forward 2-3 feet", "Keep your left heel on the ground and flex your left toes up toward your shin", "Place hands on your right thigh for support and keep your back straight", "Slowly hinge at the hips and lean forward over your left leg", "Reach toward your left toes while maintaining a neutral spine", "Hold the stretch for 15-30 seconds then slowly return to starting position"]', '["Tiens-toi debout, les pieds éloignés de la largeur des hanches et avance le pied gauche de 60-90 cm", "Garde le talon gauche au sol et fléchis les orteils vers ton tibia", "Pose tes mains sur ta cuisse droite pour le soutien et maintiens le dos droit", "Incline-toi lentement au niveau des hanches et penche-toi en avant sur ta jambe gauche", "Atteins tes orteils gauches tout en maintenant une colonne vertébrale neutre", "Tiens l''étirement pendant 15-30 secondes, puis retourne lentement à la position de départ"]', '["Garde le dos droit pendant tout le mouvement pour éviter d''arrondir la colonne vertébrale", "Concentre-toi sur l''inclinaison au niveau des hanches plutôt que de plier la taille", "Tu devrais ressentir l''étirement à l''arrière de ta cuisse gauche, pas dans le bas du dos", "Respire profondément et évite de rebondir ou de forcer l''étirement"]', '["Keep your back straight throughout the movement to avoid rounding your spine", "Focus on hinging at the hips rather than bending at the waist", "You should feel the stretch in the back of your left thigh, not your lower back", "Breathe deeply and avoid bouncing or forcing the stretch"]', '8b749c78-6f8d-46d7-ab75-bb42ed161ae1', 'standing-hamstring-stretch-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('3ac86e13-cf33-4acc-8855-0a9896a3bb85', 'Tirage vertical prise rapprochée', NULL, 'تيراج عمودي قبضة قريبة', 'Close Grip Lat Pulldown', 'Back', '[]', 'Back', 'Beginner', 4, '/videos/back/close-grip-lat-pulldown-1e99855d.mp4', NULL, NULL, NULL, '/videos/thumbnails/close-grip-lat-pulldown-1e99855d.jpg', NULL, '["Garde ton buste droit et évite de pencher ton dos en arrière pour prévenir les douleurs lombaires", "Pense à initier le mouvement avec tes lats, en te concentant sur la descente de tes coudes", "Maintiens un tempo contrôlé, surtout lors du phase excentrique (retour) du mouvement", "Évite de tirer la barre derrière ta nuque pour ne pas risquer d''impacter tes épaules", "Arrête la barre au niveau de ta poitrine au lieu de la tirer jusqu''aux cuisses pour garder une bonne activation des lats."]', '["Ne pas rester droit et trop se pencher en arrière", "Tirer la barre derrière la nuque", "Lâcher la tension dans les lats entre les répétitions", "Utiliser des bras plutôt que de se concentrer sur les coudes.", "Ne pas effectuer un retour contrôlé à la position de départ."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "close grip lat pulldown"]', true, '2026-04-03 12:24:56.111786+00', '2026-04-03 12:24:56.111786+00', 'Position de départ : Assieds-toi sur la machine de tirage vertical avec une prise rapprochée et les paumes tournées vers le haut. Exécution : Tire la barre vers ta poitrine en gardant le buste droit, puis retourne lentement à la position de départ.', '["Ne pas rester droit et trop se pencher en arrière", "Tirer la barre derrière la nuque", "Lâcher la tension dans les lats entre les répétitions", "Utiliser des bras plutôt que de se concentrer sur les coudes.", "Ne pas effectuer un retour contrôlé à la position de départ."]', true, '["Adjust the knee pad to secure your thighs and prevent your body from lifting during the movement", "Grasp the bar with an overhand grip, hands positioned slightly closer than shoulder-width apart", "Sit tall with your chest up, shoulders back, and core engaged throughout the exercise", "Pull the bar down smoothly toward your upper chest while squeezing your shoulder blades together", "Focus on driving your elbows down and back rather than just pulling with your arms", "Control the weight back to the starting position, maintaining tension in your lats"]', '["Ajuste le coussin de genoux pour sécuriser tes cuisses et éviter que ton corps ne se lève durant le mouvement", "Saisis la barre avec une prise en supination, les mains légèrement plus rapprochées que la largeur des épaules", "Tiens-toi droit, poitrine relevée, épaules en arrière et muscle ton tronc tout au long de l''exercice", "Tire la barre vers ton haut de la poitrine en serrant les omoplates ensemble", "Concentre-toi sur le mouvement des coudes vers le bas et l''arrière plutôt que sur tes bras", "Contrôle le poids en revenant à la position de départ, tout en maintenant la tension dans tes lats."]', '["Garde ton buste droit et évite de pencher ton dos en arrière pour prévenir les douleurs lombaires", "Pense à initier le mouvement avec tes lats, en te concentant sur la descente de tes coudes", "Maintiens un tempo contrôlé, surtout lors du phase excentrique (retour) du mouvement", "Évite de tirer la barre derrière ta nuque pour ne pas risquer d''impacter tes épaules", "Arrête la barre au niveau de ta poitrine au lieu de la tirer jusqu''aux cuisses pour garder une bonne activation des lats."]', '["Keep your torso upright and avoid leaning back excessively to prevent lower back strain", "Focus on initiating the movement with your lats rather than your biceps by thinking about pulling your elbows down", "Maintain a controlled tempo, especially during the eccentric (returning) phase of the movement", "Avoid pulling the bar behind your neck as this can cause shoulder impingement", "Stop the bar at chest level rather than pulling it to your lap to maintain proper lat engagement"]', '1e99855d-fbf5-433e-9273-6f4e318a6ffe', 'close-grip-lat-pulldown-1e99855d', NULL, NULL);
INSERT INTO public.exercises VALUES ('d53b0acb-88f9-416e-90a1-aec23047bd18', 'Tirage Vertical Prise Serrée', NULL, NULL, 'Close Grip Lat Pulldown', 'Back', '[]', 'Back', 'Beginner', 4, '/videos/back/close-grip-lat-pulldown.mp4', NULL, NULL, NULL, '/videos/thumbnails/close-grip-lat-pulldown.jpg', NULL, '["Maintiens ton centre engagé tout au long du mouvement pour garder la bonne posture", "Évite d''utiliser l''élan ou de balancer ton torse pour tirer le poids", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras", "Ne laisse pas le poids retomber brutalement entre les répétitions"]', '["Balancer le torse pendant le mouvement", "Laisser les coudes s''écarter du corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "close grip lat pulldown"]', true, '2026-04-03 12:24:56.100145+00', '2026-04-03 12:24:56.100145+00', 'Position de départ : Assieds-toi sur la machine de tirage vertical, avec une prise en pronation et les mains écartées à la largeur des épaules. Exécution : Tire la barre vers ta poitrine en gardant les coudes près du corps, puis retourne lentement à la position de départ.', '["Balancer le torse pendant le mouvement", "Laisser les coudes s''écarter du corps"]', true, '["Sit at the lat pulldown machine with your thighs secured under the pads and feet flat on the floor", "Grasp the bar with an overhand grip, hands positioned about shoulder-width apart or slightly narrower", "Lean back slightly and pull your shoulder blades down and together to engage your lats", "Pull the bar down smoothly toward your upper chest while keeping your elbows close to your body", "Squeeze your back muscles at the bottom of the movement, then slowly return the bar to the starting position with control"]', '["Installe-toi sur la machine de tirage avec les cuisses bien calées sous les coussins et les pieds à plat au sol", "Saisis la barre avec une prise en pronation, les mains à peu près à la largeur des épaules ou légèrement plus étroites", "Incline-toi légèrement en arrière et tire tes omoplates vers le bas et vers l''intérieur pour activer tes dorsaux", "Tire la barre vers ta partie supérieure du torse tout en maintenant les coudes près du corps", "Contracte les muscles du dos en bas du mouvement, puis ramène lentement la barre à la position de départ avec contrôle"]', '["Maintiens ton centre engagé tout au long du mouvement pour garder la bonne posture", "Évite d''utiliser l''élan ou de balancer ton torse pour tirer le poids", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras", "Ne laisse pas le poids retomber brutalement entre les répétitions"]', '["Keep your core engaged throughout the movement to maintain proper posture", "Avoid using momentum or swinging your torso to pull the weight", "Focus on pulling with your back muscles rather than your arms", "Don''t allow the weight to slam back up between repetitions"]', '10a31695-e218-4819-b7d3-b67b1b5ac79d', 'close-grip-lat-pulldown', NULL, NULL);
INSERT INTO public.exercises VALUES ('135c3692-a101-488a-aaa1-f37963d673ce', 'Curl de Concentration', NULL, 'تمارين التركيز', 'Concentration Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 2, '/videos/biceps/concentration-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/concentration-curl.jpg', NULL, '["Garde ton bras supérieur pressé contre ta cuisse pendant tout le mouvement pour cibler efficacement le biceps", "Concentre-toi sur des mouvements lents et maîtrisés plutôt que de te laisser emporter par l''élan", "Évite de verrouiller complètement ton coude en bas pour maintenir une tension constante sur le muscle", "Expire pendant la phase de levée et inspire en baissant l''haltère", "Choisis un poids qui te permet de garder une bonne forme tout au long des répétitions"]', '["Utiliser l''élan pour soulever le poids", "Ne pas maintenir le bras supérieur collé à la cuisse"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "concentration curl"]', true, '2026-04-03 12:24:56.143787+00', '2026-04-03 12:24:56.143787+00', 'Position de départ : Assis sur un banc, porte un haltère dans une main et repose ton bras contre l''intérieur de ta cuisse. Exécution : Plie le coude et monte l''haltère vers ton épaule, puis redresse-le doucement en arrière.', '["Utiliser l''élan pour soulever le poids", "Ne pas maintenir le bras supérieur collé à la cuisse"]', true, '["Sit on the edge of a bench with your feet planted firmly on the floor about shoulder-width apart", "Hold a dumbbell in your working hand with an underhand grip and let your arm hang straight down", "Place the back of your upper arm against the inside of your thigh on the same side, just above the knee", "Slowly curl the weight up by contracting your bicep, focusing on squeezing at the top of the movement", "Lower the dumbbell back down in a controlled manner until your arm is nearly straight", "Complete all repetitions on one arm before switching to the other side"]', '["Assieds-toi sur le bord d''un banc, les pieds bien ancrés au sol écartés à la largeur des épaules", "Prends un haltère dans ta main de travail avec une prise en supination et laisse ton bras pendre droit vers le bas", "Place l''arrière de ton bras supérieur contre l''intérieur de ta cuisse, juste au-dessus du genou", "Lève lentement le poids en contractant ton biceps, en te concentrant sur la contraction en haut du mouvement", "Redescends l''haltère de manière contrôlée jusqu''à ce que ton bras soit presque droit", "Effectue toutes les répétitions d''un côté avant de passer à l''autre bras"]', '["Garde ton bras supérieur pressé contre ta cuisse pendant tout le mouvement pour cibler efficacement le biceps", "Concentre-toi sur des mouvements lents et maîtrisés plutôt que de te laisser emporter par l''élan", "Évite de verrouiller complètement ton coude en bas pour maintenir une tension constante sur le muscle", "Expire pendant la phase de levée et inspire en baissant l''haltère", "Choisis un poids qui te permet de garder une bonne forme tout au long des répétitions"]', '["Keep your upper arm pressed firmly against your thigh throughout the entire movement to isolate the bicep", "Focus on slow, controlled movements rather than using momentum to lift the weight", "Avoid fully locking out your elbow at the bottom to maintain constant tension on the muscle", "Breathe out during the lifting phase and breathe in during the lowering phase", "Choose a weight that allows you to maintain proper form for all repetitions"]', '22880d49-67f2-4f14-9510-046c32da166b', 'concentration-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('e32037b1-95f3-425b-8510-4fac33421eca', 'Posture du Cordonnier', NULL, NULL, 'Cobbler''s pose', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/cobblers-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/cobblers-pose.jpg', NULL, '["Ne force pas tes genoux vers le bas.", "Utilise un coussin si tes hanches sont tendues.", "Garde la colonne longue et les épaules relâchées."]', '["Enrouler le dos au lieu de le garder droit.", "Ne pas respirer profondément pendant l''étirement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "cobbler''s pose"]', true, '2026-04-03 12:24:56.131447+00', '2026-04-03 12:24:56.131447+00', 'Installe-toi au sol, les genoux pliés et les plantes des pieds l''une contre l''autre. Laisse tes genoux s''ouvrir sur les côtés. Cette posture est idéale pour assouplir les hanches et travailler les fessiers.', '["Enrouler le dos au lieu de le garder droit.", "Ne pas respirer profondément pendant l''étirement."]', true, '["Sit on the floor with the soles of your feet together.", "Let your knees drop open to the sides.", "Hold your feet or ankles with your hands.", "Sit tall, lengthening your spine."]', '["Assieds-toi sur le sol avec les plantes de tes pieds jointes.", "Laisse tes genoux tomber sur les côtés.", "Attrape tes pieds ou tes chevilles avec tes mains.", "Garde le dos droit et étire ta colonne. "]', '["Ne force pas tes genoux vers le bas.", "Utilise un coussin si tes hanches sont tendues.", "Garde la colonne longue et les épaules relâchées."]', '["Do not force your knees down.", "Sit on a cushion if your hips are tight.", "Keep your spine long and shoulders relaxed."]', 'bb30b96e-da77-44d7-aabe-d02a7bdcaa23', 'cobblers-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('4ebba833-b98e-4e55-9796-92d5e4a4a07e', 'Extensions des triceps avec barre au poids du corps', NULL, 'تمارين الذراعين مع البار', 'Bodyweight Triceps Extension (with bar)', 'Triceps', '[]', 'Triceps', 'Intermediate', 16, '/videos/triceps/barbell-triceps-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-triceps-extension.jpg', NULL, '["Maintiens ton corps en position de planche pour protéger le bas du dos", "Concentre-toi sur le mouvement des coudes, en gardant les épaules fixes pour cibler efficacement les triceps", "Pour moduler la difficulté, ajuste la position de tes pieds - les rapprocher rend l''exercice plus facile, les éloigner l''augmente", "Vérifie que la barre est bien fixée et ne peut pas rouler ou bouger pendant l''exercice", "Arrête immédiatement si tu ressens une douleur à l''épaule et réévalue ta posture et ta position"]', '["Ne pas conserver une posture droite ce qui peut nuire au bas du dos", "Plier les épaules au lieu des coudes, ce qui diminue l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "bodyweight", "bodyweight triceps extension (with bar)"]', true, '2026-04-03 12:24:55.777801+00', '2026-04-03 12:24:55.777801+00', 'Position de départ : Place-toi à un bras de distance d''un support à barbell, mains sur la barre à largeur d''épaules, corps penché en avant avec les pieds bien ancrés derrière. Exécution : Descends ton corps en pliant uniquement au niveau des coudes tout en gardant le corps droit, puis pousse sur les bras pour revenir à la position de départ.', '["Ne pas conserver une posture droite ce qui peut nuire au bas du dos", "Plier les épaules au lieu des coudes, ce qui diminue l''efficacité de l''exercice"]', true, '["Position yourself arm''s length from a bar or secured barbell at about chest height with hands shoulder-width apart", "Lean forward keeping your body in a straight line from head to heels with arms fully extended", "Lower your body slowly by bending only at the elbows until your forehead nearly touches the bar", "Keep your core engaged and body rigid throughout the entire movement", "Push yourself back up to the starting position by straightening your arms", "Maintain control on both the lowering and lifting phases of the exercise"]', '["Positionne-toi à un bras de distance d''une barre bien fixée à hauteur de poitrine, mains écartées à largeur d''épaules", "Incline-toi en gardant le corps bien droit de la tête aux talons avec les bras complètement tendus", "Descends lentement en pliant uniquement les coudes jusqu''à ce que ton front frôle la barre", "Engage bien ton ventre et maintiens le corps rigide durant tout le mouvement", "Remonte en poussant sur les bras pour retrouver la position initiale", "Garde le contrôle pendant la descente et la montée de l''exercice"]', '["Maintiens ton corps en position de planche pour protéger le bas du dos", "Concentre-toi sur le mouvement des coudes, en gardant les épaules fixes pour cibler efficacement les triceps", "Pour moduler la difficulté, ajuste la position de tes pieds - les rapprocher rend l''exercice plus facile, les éloigner l''augmente", "Vérifie que la barre est bien fixée et ne peut pas rouler ou bouger pendant l''exercice", "Arrête immédiatement si tu ressens une douleur à l''épaule et réévalue ta posture et ta position"]', '["Keep your body in a straight plank position throughout the movement to protect your lower back", "Focus on bending only at the elbows while keeping your shoulders stationary to properly target the triceps", "Adjust the difficulty by changing your foot position - closer feet make it easier, further feet increase difficulty", "Ensure the barbell is securely positioned and cannot roll or move during the exercise", "Stop immediately if you feel any shoulder pain and reassess your form and positioning"]', '33869887-32ab-4c66-b033-3bef9e5de372', 'barbell-triceps-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('153270b8-5f76-4a09-8365-6bb4970a17be', 'Pose du Cadavre', NULL, NULL, 'Corpse pose', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/corpse-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/corpse-pose.jpg', NULL, '["Lâche prise et n''active pas tes muscles.", "Laisse ta respiration revenir à son rythme naturel.", "Cette pose est essentielle pour l''intégration et la relaxation."]', '["Trop d''agitation dans le corps.", "Se concentrer sur des pensées stressantes au lieu de se détendre."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "corpse pose"]', true, '2026-04-03 12:24:56.152555+00', '2026-04-03 12:24:56.152555+00', 'Allonge-toi sur le dos, les jambes légèrement écartées, les bras le long du corps, paumes vers le ciel et les yeux fermés. Concentre-toi sur ta respiration profonde et fais disparaître toute tension musculaire. C''est le moment idéal pour laisser ton corps se reposer et se régénérer.', '["Trop d''agitation dans le corps.", "Se concentrer sur des pensées stressantes au lieu de se détendre."]', true, '["Lie flat on your back with legs extended and arms at your sides.", "Let your feet fall open naturally.", "Close your eyes and relax every part of your body.", "Breathe naturally and stay for 5-10 minutes."]', '["Allonge-toi sur le dos, jambes tendues, bras le long du corps.", "Laisse tes pieds s''ouvrir naturellement.", "Ferme les yeux et détends chaque partie de ton corps.", "Respire naturellement et reste dans cette position pendant 5 à 10 minutes."]', '["Lâche prise et n''active pas tes muscles.", "Laisse ta respiration revenir à son rythme naturel.", "Cette pose est essentielle pour l''intégration et la relaxation."]', '["Release all muscular effort.", "Let your breath return to its natural rhythm.", "This is the most important pose for integration and relaxation."]', '658fa4e6-8b1d-48f4-b97d-7c576783ad73', 'corpse-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('3e187738-79a0-48b5-9513-eb72274482ab', 'Tirez le meilleur de vos triceps !', NULL, 'حسن أداء عضلات الترايسبس ديالك!', 'Cable Tricep Pushdown', 'Triceps', '[]', 'Triceps', 'Beginner', 4, '/videos/triceps/cable-tricep-pushdown-ab522399.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-tricep-pushdown-ab522399.jpg', NULL, '["Garde les coudes fixes et près du corps pour cibler efficacement les triceps", "Concentre-toi sur le contrôle du poids pendant les phases descendante et ascendante pour maximiser l''engagement musculaire", "Évite de faire appel à tes épaules ou de balancer ton corps pour déplacer le poids", "Commence avec un poids léger pour maîtriser la forme avant de progresser vers des résistances plus lourdes", "Garde la colonne vertébrale neutre et évite d''arquer le dos pendant l''exercice."]', '["Une mauvaise position des coudes qui réduit l''engagement des triceps", "Un mouvement brusque qui peut entraîner des blessures."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "cable", "cable tricep pushdown"]', true, '2026-04-03 12:24:56.005833+00', '2026-04-03 12:24:56.005833+00', 'Position de départ : Place-toi face à un poulie haute avec une barre droite. Execution : Étends les coudes pour pousser la barre vers le bas, en maintenant les coudes fixes.', '["Une mauvaise position des coudes qui réduit l''engagement des triceps", "Un mouvement brusque qui peut entraîner des blessures."]', true, '["Set the cable pulley to the highest position and attach your chosen handle", "Stand with feet hip-width apart, core engaged, and maintain a slight forward lean", "Grip the attachment with palms facing down, keeping elbows close to your ribcage", "Push the weight down by extending your forearms until your arms are fully straight", "Squeeze your triceps at the bottom of the movement for one second", "Slowly return to starting position, maintaining control throughout the entire range of motion"]', '["Régle la poulie à la position la plus haute et fixe l''accessoire de ton choix", "Positionne-toi les pieds écartés de la largeur des hanches, engager le centre et penche-toi légèrement en avant", "Prends la prise avec les paumes vers le bas, en gardant les coudes proches des côtes", "Pousse le poids vers le bas en étendant les avant-bras jusqu''à ce que tes bras soient bien droits", "Contracte tes triceps en bas du mouvement pendant une seconde", "Retourne lentement à la position de départ, tout en contrôlant le mouvement sur toute l''amplitude."]', '["Garde les coudes fixes et près du corps pour cibler efficacement les triceps", "Concentre-toi sur le contrôle du poids pendant les phases descendante et ascendante pour maximiser l''engagement musculaire", "Évite de faire appel à tes épaules ou de balancer ton corps pour déplacer le poids", "Commence avec un poids léger pour maîtriser la forme avant de progresser vers des résistances plus lourdes", "Garde la colonne vertébrale neutre et évite d''arquer le dos pendant l''exercice."]', '["Keep your elbows stationary and close to your body throughout the entire movement to properly isolate the triceps", "Focus on controlling the weight on both the downward and upward phases to maximize muscle engagement", "Avoid using your shoulders or swinging your body to move the weight", "Start with lighter weight to master proper form before progressing to heavier resistance", "Maintain a neutral spine and avoid arching your back during the exercise"]', 'ab522399-6b5e-4a37-aa7a-47d2ec862631', 'cable-tricep-pushdown-ab522399', NULL, NULL);
INSERT INTO public.exercises VALUES ('d492fc93-5cc6-4a93-bc7f-3126e45870b7', 'Skull Crusher à Prise Inversée', NULL, NULL, 'Reverse Grip Skull Crusher', 'Triceps', '[]', 'Triceps', 'Intermediate', 1, '/videos/triceps/reverse-grip-skull-crusher.mp4', NULL, NULL, NULL, '/videos/thumbnails/reverse-grip-skull-crusher.jpg', NULL, '["Maintiens tes bras supérieurs perpendiculaires au sol et évite de les laisser reculer pendant l''exercice", "Adopte un tempo contrôlé pour maximiser la tension musculaire et minimiser le risque de blessure", "Commence avec un poids plus léger qu''avec les skull crushers traditionnels, car la prise inversée peut paraître différente au début", "Garde les poignets droits et une prise ferme pour empêcher la barre de rouler", "Concentre-toi sur l''étirement de tes triceps en bas sans descendre trop bas"]', '["Laisser les bras supérieurs se déplacer vers l''arrière", "Ne pas contrôler la descente et la montée de la barre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "barbell", "reverse grip skull crusher"]', true, '2026-04-03 12:24:58.589987+00', '2026-04-03 12:24:58.589987+00', 'Allonge-toi sur un banc plat avec une barre en mains, prise inversée (paumes vers le haut). Tu vas abaisser la barre vers ton front en pliant les coudes, puis étendre les bras pour revenir à la position de départ.', '["Laisser les bras supérieurs se déplacer vers l''arrière", "Ne pas contrôler la descente et la montée de la barre"]', true, '["Lie flat on a bench with feet firmly planted on the floor for stability", "Grip the barbell with an underhand grip, hands positioned shoulder-width apart", "Start with arms fully extended above your chest, keeping your upper arms stationary throughout the movement", "Slowly lower the barbell by bending at the elbows until it nearly touches your forehead", "Press the weight back up by extending your elbows to return to the starting position", "Maintain control of the weight throughout both the lowering and lifting phases"]', '["Allonge-toi bien sur le banc, les pieds ancrés au sol pour plus de stabilité", "Saisis la barre avec une prise en supination, écartement des mains à la largeur des épaules", "Commence avec les bras complètement tendus au-dessus de ta poitrine, en gardant les bras supérieurs immobiles pendant tout le mouvement", "Abaisse lentement la barre en pliant les coudes jusqu''à ce qu''elle frôle ton front", "Pousse la charge vers le haut en extension des coudes pour revenir à la position initiale", "Reste maître de ton poids tout au long de la descente et de la montée"]', '["Maintiens tes bras supérieurs perpendiculaires au sol et évite de les laisser reculer pendant l''exercice", "Adopte un tempo contrôlé pour maximiser la tension musculaire et minimiser le risque de blessure", "Commence avec un poids plus léger qu''avec les skull crushers traditionnels, car la prise inversée peut paraître différente au début", "Garde les poignets droits et une prise ferme pour empêcher la barre de rouler", "Concentre-toi sur l''étirement de tes triceps en bas sans descendre trop bas"]', '["Keep your upper arms perpendicular to the floor and avoid letting them drift backward during the movement", "Use a controlled tempo to maximize muscle tension and reduce risk of injury", "Start with lighter weight than regular skull crushers as the reverse grip can feel awkward initially", "Keep your wrists straight and maintain a firm grip to prevent the barbell from rolling", "Focus on feeling the stretch in your triceps at the bottom position without going too low"]', '6b58c0da-6795-4103-bbed-6c3e540c1c16', 'reverse-grip-skull-crusher', NULL, NULL);
INSERT INTO public.exercises VALUES ('b46313c6-086d-465b-b198-e90a7e03ad8c', 'Marche en Crab avec Squat', NULL, NULL, 'Crab walk to squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/crab-walk-to-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/crab-walk-to-squat.jpg', NULL, '["Garde les poignets sous les épaules et évite que les hanches ne s''affaissent pendant la marche en crab.", "Contrôle ta transition entre la marche en crab et le squat pour éviter les blessures.", "Concentre-toi sur la profondeur du squat avec les cuisses parallèles au sol tout en gardant les genoux alignés avec les orteils.", "Contracte tes fessiers et tes quadriceps pendant les deux mouvements pour une activation musculaire maximale.", "Commence avec des distances courtes et moins de répétitions jusqu''à ce que tu développes force et coordination."]', '["Ne pas engager les abdominaux pendant l''exercice.", "Soulever les hanches trop bas pendant la marche en crab."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "crab walk to squat"]', true, '2026-04-03 12:24:56.194354+00', '2026-04-03 12:24:56.194354+00', 'Positionne-toi en marche en crab. Les mains derrière toi, les genoux fléchis et les hanches relevées. Prêt à renforcer tes quadriceps ? C''est parti !', '["Ne pas engager les abdominaux pendant l''exercice.", "Soulever les hanches trop bas pendant la marche en crab."]', true, '["Start in crab position with hands behind you, fingers pointing toward your feet, knees bent and hips elevated", "Keep your core engaged and maintain a straight line from knees to shoulders throughout the crab walk", "Take 3-4 steps laterally while maintaining proper crab form and keeping hips up", "Transition smoothly by bringing feet together and rotating to face forward", "Lower into a deep squat with chest up, knees tracking over toes, and weight in your heels", "Return to crab position and repeat the sequence in the opposite direction"]', '["Commence en position crab avec les mains derrière toi, les doigts orientés vers tes pieds, les genoux fléchis et les hanches élevées.", "Engage ton cœur et garde une ligne droite des genoux aux épaules pendant la marche en crab.", "Fais 3 à 4 pas latéraux tout en maintenant la forme correcte du crab et garde les hanches hautes.", "Transitionne doucement en rapprochant les pieds et en te tournant vers l''avant.", "Descends en squat profond avec la poitrine haute, les genoux au-dessus des orteils, et le poids sur les talons.", "Retourne en position crab et répète la séquence dans l''autre direction."]', '["Garde les poignets sous les épaules et évite que les hanches ne s''affaissent pendant la marche en crab.", "Contrôle ta transition entre la marche en crab et le squat pour éviter les blessures.", "Concentre-toi sur la profondeur du squat avec les cuisses parallèles au sol tout en gardant les genoux alignés avec les orteils.", "Contracte tes fessiers et tes quadriceps pendant les deux mouvements pour une activation musculaire maximale.", "Commence avec des distances courtes et moins de répétitions jusqu''à ce que tu développes force et coordination."]', '["Keep wrists directly under shoulders and avoid letting hips sag during the crab walk portion", "Maintain control during the transition between crab walk and squat to prevent injury", "Focus on proper squat depth with thighs parallel to the ground while keeping knees aligned with toes", "Engage your glutes and quads throughout both movements for maximum muscle activation", "Start with shorter distances and fewer repetitions until you build strength and coordination"]', '85a71ed6-caf0-4b0c-aa70-0419d8f81157', 'crab-walk-to-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('b1fa3825-5d81-40e0-8871-cc75cd1cede4', 'Extension de triceps genoux en mouvement', NULL, NULL, 'Tricep extension knee ins', 'Triceps', '[]', 'Triceps', 'Intermediate', 16, '/videos/triceps/tricep-extension-knee-ins.mp4', NULL, NULL, NULL, '/videos/thumbnails/tricep-extension-knee-ins.jpg', NULL, '["Garde les hanches à niveau, évite de faire tourner ton torse en amenant les genoux", "Maintiens ton cœur engagé pour éviter que ta lombaire ne se vienne affaisser", "Contrôle le mouvement - évite de te précipiter ou d''utiliser l''élan", "Garde les avant-bras bien ancrés et les épaules stables tout au long de l''exercice", "Respire régulièrement et évite de retenir ton souffle pendant le mouvement"]', '["Baisse des hanches qui compromet la position de planche", "Rotation du torse pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "bodyweight", "tricep extension knee ins"]', true, '2026-04-03 12:24:59.777243+00', '2026-04-03 12:24:59.777243+00', 'Position de départ : Commence en position de planche avec les avant-bras au sol, les coudes sous les épaules et le corps en ligne droite de la tête aux talons. Exécution : Tout en maintenant la position de planche, amène alternativement chaque genou vers la poitrine de manière contrôlée, puis retourne à la position de départ.', '["Baisse des hanches qui compromet la position de planche", "Rotation du torse pendant l''exercice"]', true, '["Start in a forearm plank position with elbows directly under your shoulders", "Keep your core engaged and maintain a straight line from head to heels", "Bring one knee toward your chest while keeping the other leg extended", "Return the working leg to the starting position with control", "Alternate legs in a smooth, controlled rhythm", "Maintain the plank position throughout the entire movement"]', '["Commence en position de planche sur les avant-bras, les coudes bien sous les épaules", "Engage ton cœur et garde une ligne droite de la tête aux talons", "Amène un genou vers ta poitrine tout en gardant l''autre jambe tendue", "Ramène la jambe travaillante à la position initiale avec contrôle", "Alterne les jambes dans un rythme fluide et maîtrisé", "Maintiens la position de planche pendant tout l''exercice"]', '["Garde les hanches à niveau, évite de faire tourner ton torse en amenant les genoux", "Maintiens ton cœur engagé pour éviter que ta lombaire ne se vienne affaisser", "Contrôle le mouvement - évite de te précipiter ou d''utiliser l''élan", "Garde les avant-bras bien ancrés et les épaules stables tout au long de l''exercice", "Respire régulièrement et évite de retenir ton souffle pendant le mouvement"]', '["Keep your hips level and avoid rotating your torso as you bring each knee in", "Maintain strong core engagement to prevent your lower back from sagging", "Control the movement - avoid rushing or using momentum", "Keep your forearms firmly planted and shoulders stable throughout the exercise", "Breathe steadily and avoid holding your breath during the movement"]', '10014d85-339e-4573-876d-87b003c28671', 'tricep-extension-knee-ins', NULL, NULL);
INSERT INTO public.exercises VALUES ('e9e140b2-2049-4ad1-89cb-4a7a5ff837d8', 'Tirs croisés avec coups de talons', NULL, NULL, 'Cross body pulls to hamstring kicks', 'Hamstrings', '[]', 'Hamstrings', 'Intermediate', 16, '/videos/hamstrings/cross-body-pulls-to-hamstring-kicks.mp4', NULL, NULL, NULL, '/videos/thumbnails/cross-body-pulls-to-hamstring-kicks.jpg', NULL, '["Contractez vos abdominaux tout au long du mouvement pour maintenir votre équilibre et votre stabilité", "Concentrez-vous sur des mouvements contrôlés plutôt que sur la vitesse pour activer vos ischio-jambiers", "Gardez le buste droit et évitez de vous pencher en avant lors du coup de talon", "Gardez la jambe d''appui légèrement fléchie pour améliorer l''équilibre et réduire la pression sur le genou", "Squeezez vos fessiers en haut de chaque coup de talon pour une activation musculaire supplémentaire"]', '["Ne pas croiser suffisamment le bras", "Pencher le torse en avant pendant le coup de talon"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "cross body pulls to hamstring kicks"]', true, '2026-04-03 12:24:56.232728+00', '2026-04-03 12:24:56.232728+00', 'Mettez-vous debout, jambes écartées à la largeur des hanches, bras tendus sur les côtés à hauteur des épaules. En croisant un bras, levez la jambe opposée en un coup de talon vers l''arrière, puis revenez à la position de départ et changez de côté.', '["Ne pas croiser suffisamment le bras", "Pencher le torse en avant pendant le coup de talon"]', true, '["Stand with feet hip-width apart and extend both arms out to the sides at shoulder height", "Cross your right arm across your body toward your left side while keeping it straight", "Simultaneously kick your left leg back behind you, bending at the knee to bring your heel toward your glutes", "Return your arm and leg to the starting position in a controlled manner", "Repeat the movement on the opposite side, crossing your left arm while kicking back with your right leg", "Continue alternating sides for the desired number of repetitions"]', '["Mettez-vous debout, jambes écartées à la largeur des hanches, bras tendus sur les côtés à hauteur des épaules", "Croisez votre bras droit devant vous vers le côté gauche tout en le gardant tendu", "En même temps, donnez un coup de talon avec votre jambe gauche en arrière, en fléchissant le genou pour amener votre talon vers vos fessiers", "Ramenez votre bras et votre jambe à la position de départ de manière contrôlée", "Répétez le mouvement de l''autre côté, en croisant votre bras gauche tout en donnant un coup de talon avec votre jambe droite", "Alternez les côtés pour le nombre de répétitions souhaité"]', '["Contractez vos abdominaux tout au long du mouvement pour maintenir votre équilibre et votre stabilité", "Concentrez-vous sur des mouvements contrôlés plutôt que sur la vitesse pour activer vos ischio-jambiers", "Gardez le buste droit et évitez de vous pencher en avant lors du coup de talon", "Gardez la jambe d''appui légèrement fléchie pour améliorer l''équilibre et réduire la pression sur le genou", "Squeezez vos fessiers en haut de chaque coup de talon pour une activation musculaire supplémentaire"]', '["Keep your core engaged throughout the movement to maintain balance and stability", "Focus on controlled movements rather than speed to maximize hamstring activation", "Maintain an upright torso and avoid leaning forward when performing the hamstring kick", "Keep the standing leg slightly bent to improve balance and reduce knee stress", "Squeeze your glutes at the top of each hamstring kick for additional muscle activation"]', '6362bdab-a7d7-49e8-85ab-fe1eb610cb4e', 'cross-body-pulls-to-hamstring-kicks', NULL, NULL);
INSERT INTO public.exercises VALUES ('67710d50-68a1-4f7d-b282-d11247ae65a2', 'Crunches', NULL, 'تمارين الكرنش', 'Crunches', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/crunches.mp4', NULL, NULL, NULL, '/videos/thumbnails/crunches.jpg', NULL, '["Garde le bas de ton dos bien collé au sol pendant tout le mouvement.", "Ne tire pas sur ton cou avec tes mains, laisse tes abdos faire le travail.", "Privilégie la qualité à la quantité : des mouvements lents et contrôlés sont plus efficaces.", "Garde le menton légèrement rentré et laisse un petit espace entre ton menton et ta poitrine.", "Arrête si tu ressens une douleur au niveau du cou ou du bas du dos."]', '["Tirer sur le cou avec les mains.", "Laisser le bas du dos se soulever du sol."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "crunches"]', true, '2026-04-03 12:24:56.242604+00', '2026-04-03 12:24:56.242604+00', 'Position de départ : Allonge-toi sur le dos, genoux pliés à 90 degrés, pieds à plat sur le sol. Positionne tes mains derrière la tête ou croise-les sur ta poitrine. Exécution : Soulève tes omoplates en contractant tes abdos, puis redescends lentement en contrôlant le mouvement.', '["Tirer sur le cou avec les mains.", "Laisser le bas du dos se soulever du sol."]', true, '["Lie on your back with knees bent at 90 degrees, feet flat on the floor hip-width apart", "Place your hands lightly behind your head with elbows wide, or cross arms over your chest", "Engage your core and slowly lift your shoulder blades off the ground, curling your upper body toward your knees", "Hold briefly at the top, feeling the contraction in your abs", "Slowly lower back down with control until your shoulder blades lightly touch the floor", "Repeat for desired repetitions while maintaining steady breathing"]', '["Allonge-toi sur le dos, genoux pliés à 90 degrés, pieds à plat, largeur des hanches.", "Mets tes mains derrière la tête avec les coudes ouverts, ou croise tes bras sur la poitrine.", "Engage ton abdomen et soulève lentement tes omoplates en courbant le haut de ton corps vers tes genoux.", "Maintiens la position en haut un instant, ressens la contraction de tes abdos.", "Redescends doucement jusqu''à ce que tes omoplates effleurent le sol.", "Répète pour le nombre de répétitions souhaité, en gardant une respiration régulière."]', '["Garde le bas de ton dos bien collé au sol pendant tout le mouvement.", "Ne tire pas sur ton cou avec tes mains, laisse tes abdos faire le travail.", "Privilégie la qualité à la quantité : des mouvements lents et contrôlés sont plus efficaces.", "Garde le menton légèrement rentré et laisse un petit espace entre ton menton et ta poitrine.", "Arrête si tu ressens une douleur au niveau du cou ou du bas du dos."]', '["Keep your lower back pressed into the floor throughout the movement", "Avoid pulling on your neck with your hands - let your abs do the work", "Focus on quality over quantity - slow, controlled movements are more effective", "Keep your chin slightly tucked and maintain a small gap between chin and chest", "Stop if you feel any neck or lower back pain"]', '068d316f-52b0-4438-a7c9-ee21ceca2c2f', 'crunches', NULL, NULL);
INSERT INTO public.exercises VALUES ('343651d6-f196-4e3e-b6c7-4a3e39e93836', 'Extension Triceps avec Haltère Allongé', NULL, NULL, 'Lying Dumbbell Tricep Extension', 'Triceps', '[]', 'Triceps', 'Beginner', 2, '/videos/triceps/lying-dumbbell-tricep-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-dumbbell-tricep-extension.jpg', NULL, '["Gardez les coudes proches de votre tête", "Évitez de flairer les coudes", "Assurez-vous d''un étirement complet en bas", "Réalisez un verrouillage total en haut", "Cet exercice cible le long chef des triceps"]', '["Coudes trop éloignés du corps", "Mouvement trop rapide", "Ne pas contrôler la descente", "Absence d''étirement complet au bas", "Verrouillage partiel en haut"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "dumbbell", "lying dumbbell tricep extension"]', true, '2026-04-03 12:24:57.692045+00', '2026-04-03 12:24:57.692045+00', 'Renforcez vos triceps avec cet exercice ciblé pour gagner en puissance et en définition !', '["Coudes trop éloignés du corps", "Mouvement trop rapide", "Ne pas contrôler la descente", "Absence d''étirement complet au bas", "Verrouillage partiel en haut"]', true, '["Stand or sit, hold one dumbbell with both hands", "Raise overhead, arms extended", "Lower behind head by bending elbows", "Keep upper arms vertical", "Extend back to start"]', '["Tenez-vous debout ou assis, un haltère à deux mains en position haute", "Levez-le au-dessus de votre tête, bras tendus", "Abaissez-le derrière votre tête en pliant les coudes", "Gardez les bras supérieurs bien verticaux", "Récupérez en étendant les bras jusqu''à la position de départ"]', '["Gardez les coudes proches de votre tête", "Évitez de flairer les coudes", "Assurez-vous d''un étirement complet en bas", "Réalisez un verrouillage total en haut", "Cet exercice cible le long chef des triceps"]', '["Keep elbows close to head", "Don''t flare elbows", "Full stretch at bottom", "Full lockout at top", "Targets long head of triceps"]', 'ff106b50-02bd-4962-b9f0-ddbe247b8b3e', 'lying-dumbbell-tricep-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('d650b9c6-988c-4bfc-89f9-2adcdb8603ce', 'Pompes Deadstop suivies de Crunch Superman', NULL, NULL, 'Deadstop pushup to superman crunch', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/deadstop-pushup-to-superman-crunch.mp4', NULL, NULL, NULL, '/videos/thumbnails/deadstop-pushup-to-superman-crunch.jpg', NULL, '["Garde ton cœur engagé tout au long des deux mouvements pour protéger ton bas du dos", "Le dead stop élimine l''élan, rendant la pompe plus difficile et efficace", "Concentre-toi sur le mouvement contrôlé lors de la transition entre la pompe et le crunch Superman", "Maintiens une respiration correcte en expirant pendant les phases d''effort des deux exercices", "Commence par moins de répétitions jusqu''à maîtriser la coordination entre les deux mouvements"]', '["Ne pas garder le corps en ligne droite pendant la pompe", "Oublier de faire la pause au bas du mouvement, perdant ainsi l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "deadstop pushup to superman crunch"]', true, '2026-04-03 12:24:56.268163+00', '2026-04-03 12:24:56.268163+00', 'Position de départ : mets-toi en position de pompe standard, mains écartées à la largeur des épaules, corps en ligne droite de la tête aux talons. Exécution : réalise une pompe, fais une pause lorsque ta poitrine touche le sol, pousse ensuite vers le haut et roule immédiatement sur le dos pour effectuer un crunch Superman en ramenant les genoux vers la poitrine tout en soulevant les épaules.', '["Ne pas garder le corps en ligne droite pendant la pompe", "Oublier de faire la pause au bas du mouvement, perdant ainsi l''efficacité de l''exercice"]', true, '["Start in a plank position with hands directly under shoulders and engage your core", "Lower your body slowly until your chest touches the ground, maintaining a straight body line", "Pause for one second at the bottom position with complete body contact to the floor", "Push explosively back up to the starting plank position", "Carefully roll onto your back and immediately bring your knees toward your chest while lifting your shoulders off the ground", "Return to the starting push-up position and repeat the sequence"]', '["Place-toi en planche avec les mains directement sous les épaules et engage ton cœur", "Abaisse ton corps lentement jusqu''à ce que ta poitrine touche le sol, en maintenant une ligne droite", "Fais une pause d''une seconde à cette position avec tout le corps en contact avec le sol", "Pousse explosivement pour revenir à la position de planche", "Roulez soigneusement sur le dos et ramène immédiatement tes genoux vers ta poitrine tout en soulevant tes épaules du sol", "Retourne à la position de pompe initiale et répète la séquence"]', '["Garde ton cœur engagé tout au long des deux mouvements pour protéger ton bas du dos", "Le dead stop élimine l''élan, rendant la pompe plus difficile et efficace", "Concentre-toi sur le mouvement contrôlé lors de la transition entre la pompe et le crunch Superman", "Maintiens une respiration correcte en expirant pendant les phases d''effort des deux exercices", "Commence par moins de répétitions jusqu''à maîtriser la coordination entre les deux mouvements"]', '["Keep your core engaged throughout both movements to protect your lower back", "The dead stop eliminates momentum, making the push-up more challenging and effective", "Focus on controlled movement during the transition from push-up to superman crunch", "Maintain proper breathing by exhaling during the exertion phases of both exercises", "Start with fewer repetitions until you master the coordination between both movements"]', 'b9e7733d-fbba-413a-98d9-71803ae1edb4', 'deadstop-pushup-to-superman-crunch', NULL, NULL);
INSERT INTO public.exercises VALUES ('f713d645-aec1-49ac-88b9-9c6b8006a9ec', 'Développé couché', NULL, NULL, 'Bench Press', 'Chest', '[]', 'Chest', 'Beginner', 1, '/videos/chest/bench-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/bench-press.jpg', NULL, '["Le chemin de la barre est fixe - positionne le banc correctement", "Garde les pieds à plat sur le sol", "Contracte les scapulas", "Contrôle la descente", "Idéal pour l''entraînement jusqu''à l''échec (peut être racké à tout moment)"]', '["Ne pas bien positionner le banc", "Laisser les pieds décoller du sol"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "barbell", "bench press"]', true, '2026-04-03 12:24:55.719208+00', '2026-04-03 12:24:55.719208+00', 'Position de départ : Allonge-toi sur un banc plat, prends la barre avec les mains en position pronation, bras tendus vers le haut. Exécution : Abaisse la barre jusqu''à ta poitrine, puis pousse-la vers le haut pour revenir à la position de départ.', '["Ne pas bien positionner le banc", "Laisser les pieds décoller du sol"]', true, '["Position bench under bar", "Align bar over mid-chest", "Unrack, lower bar to chest", "Press up to full extension (don''t lock)", "Repeat for reps, rack safely"]', '["Place le banc sous la barre", "Aligne la barre avec le milieu de ta poitrine", "Décharge la barre, abaisse-la vers ta poitrine", "Pousse vers le haut jusqu''à l''extension complète (ne bloque pas)", "Répète pour des répétitions, sécurise en rackant"]', '["Le chemin de la barre est fixe - positionne le banc correctement", "Garde les pieds à plat sur le sol", "Contracte les scapulas", "Contrôle la descente", "Idéal pour l''entraînement jusqu''à l''échec (peut être racké à tout moment)"]', '["Bar path is fixed - position bench properly", "Keep feet flat on floor", "Shoulder blades squeezed", "Control the descent", "Good for training to failure (can rack anytime)"]', '58d0fe05-1a66-4b80-a6d8-2dc2f0d73169', 'bench-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('b2ae8cb2-79f8-4aa7-9617-3f7586f2001a', 'Pompes Déclinées - 56 Répétitions', NULL, NULL, 'Declined Push up - 56', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/declined-push-up-56.mp4', NULL, NULL, NULL, '/videos/thumbnails/declined-push-up-56.jpg', NULL, '["Vérifiez que la surface élevée est stable et sécurisée avant de commencer l''exercice.", "Gardez le ventre bien engagé tout au long du mouvement pour éviter que vos hanches ne s''affaissent.", "L''angle déclin renforce la difficulté et cible davantage les muscles supérieurs de la poitrine.", "Commencez avec une élévation plus basse si vous débutez avec les pompes déclinées, puis augmentez progressivement la hauteur.", "Arrêtez-vous immédiatement si vous ressentez une douleur au niveau des poignets, des épaules ou du bas du dos."]', '["Ne pas maintenir une ligne droite du corps.", "Élever les hanches trop haut ou trop bas pendant l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "declined push up - 56"]', true, '2026-04-03 12:24:56.282163+00', '2026-04-03 12:24:56.282163+00', 'Mettez vos pieds sur une surface élevée (banque, marche ou chaise) et vos mains au sol, en position plank, pour créer un angle déclin. Descendez votre poitrine vers le sol en pliant les coudes, puis poussez vers le haut tout en gardant l''angle déclin du corps.', '["Ne pas maintenir une ligne droite du corps.", "Élever les hanches trop haut ou trop bas pendant l''exercice."]', true, '["Position your feet on a stable elevated surface that is 12-24 inches high", "Place your hands on the ground slightly wider than shoulder-width apart with fingers spread", "Create a straight line from your head to your heels in the declined plank position", "Lower your chest toward the ground by bending your elbows at a 45-degree angle from your body", "Push through your palms to return to the starting position while maintaining body alignment", "Perform the movement in a controlled manner throughout the full range of motion"]', '["Positionnez vos pieds sur une surface stable élevée de 30 à 60 cm.", "Mettez vos mains au sol, légèrement plus larges que la largeur des épaules, les doigts bien écartés.", "Assurez une ligne droite de la tête aux talons en position plank déclinée.", "Abaissez votre poitrine vers le sol en pliant les coudes à un angle de 45 degrés par rapport au corps.", "Poussez sur vos paumes pour revenir à la position initiale en maintenant l''alignement du corps.", "Effectuez le mouvement de manière contrôlée sur toute l''amplitude de mouvement."]', '["Vérifiez que la surface élevée est stable et sécurisée avant de commencer l''exercice.", "Gardez le ventre bien engagé tout au long du mouvement pour éviter que vos hanches ne s''affaissent.", "L''angle déclin renforce la difficulté et cible davantage les muscles supérieurs de la poitrine.", "Commencez avec une élévation plus basse si vous débutez avec les pompes déclinées, puis augmentez progressivement la hauteur.", "Arrêtez-vous immédiatement si vous ressentez une douleur au niveau des poignets, des épaules ou du bas du dos."]', '["Ensure the elevated surface is stable and secure before beginning the exercise", "Keep your core engaged throughout the movement to prevent your hips from sagging", "The declined angle increases the difficulty and places greater emphasis on the upper chest muscles", "Start with a lower elevation if you''re new to declined push-ups and gradually increase the height", "Stop immediately if you experience any wrist, shoulder, or lower back discomfort"]', '8bbcc469-9283-4776-a12c-882060dd396c', 'declined-push-up-56', NULL, NULL);
INSERT INTO public.exercises VALUES ('9267bf4b-8c36-4f86-881b-ceb50f3ea794', 'Dips sur banc', NULL, 'دبس فوق البنكة', 'Dips on bench', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/dips-on-bench.mp4', NULL, NULL, NULL, '/videos/thumbnails/dips-on-bench.jpg', NULL, '["Plus facile que les dips sur barres parallèles", "Garde le dos près du banc", "Ne descends pas trop bas", "Pieds plus proches = plus facile, plus loin = plus dur", "Mouvement axé sur les triceps"]', '["Ne pas maintenir le dos droit", "Descendre trop bas et forcer sur les épaules"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "dips on bench"]', true, '2026-04-03 12:24:56.326679+00', '2026-04-03 12:24:56.326679+00', 'Position de départ : Assieds-toi sur le bord d''un banc, les mains agrippant le bord à côté de tes hanches, jambes tendues en avant avec les talons au sol. Exécution : Abaisse ton corps en fléchissant les coudes jusqu''à ce que tes bras soient parallèles au sol, puis pousse pour revenir à la position de départ.', '["Ne pas maintenir le dos droit", "Descendre trop bas et forcer sur les épaules"]', true, '["Hands on bench behind you, legs extended", "Lower body by bending elbows", "Go until upper arms parallel to floor", "Push up to start"]', '["Mains sur le banc derrière toi, jambes tendues", "Abaisse ton corps en fléchissant les coudes", "Descends jusqu''à ce que les bras soient parallèles au sol", "Pousse vers le haut pour revenir à la position de départ"]', '["Plus facile que les dips sur barres parallèles", "Garde le dos près du banc", "Ne descends pas trop bas", "Pieds plus proches = plus facile, plus loin = plus dur", "Mouvement axé sur les triceps"]', '["Easier than parallel bar dips", "Keep back close to bench", "Don''t go too deep", "Feet closer = easier, farther = harder", "Tricep-focused movement"]', 'fcc15585-b472-487f-8367-7459ee909832', 'dips-on-bench', NULL, NULL);
INSERT INTO public.exercises VALUES ('dfbb81c7-514d-49ac-b120-073a21411dc7', 'Presse inclinée assise à la machine', NULL, NULL, 'Seated Incline Press with Machine', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/seated-incline-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-incline-press.jpg', NULL, '["Garde ton ventre engagé et assure-toi que ton dos touche le dossier durant tout le mouvement", "Évite de pousser les poignées trop haut ou trop bas - maintiens l''angle naturel de ta poitrine", "Contrôle aussi bien la phase de poussée que celle de redescente pour maximiser l''engagement musculaire", "Garde tes poignets droits et alignés avec tes avant-bras pour prévenir les blessures", "Expire pendant la phase de poussée et inspire en redescendant le poids"]', '["Ne pas ajuster le siège correctement, ce qui nuit à la posture", "Verrouiller complètement les coudes en haut du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "seated incline press with machine"]', true, '2026-04-03 12:24:58.886982+00', '2026-04-03 12:24:58.886982+00', 'Position de départ : Installe-toi sur la machine de presse inclinée, le dos bien plaqué contre le dossier, les pieds à plat au sol, et saisis les poignées à hauteur de poitrine. Exécution : Pousse les poignées vers l''avant et légèrement vers le haut de manière contrôlée jusqu''à presque étendre tes bras, puis redescends doucement à la position de départ.', '["Ne pas ajuster le siège correctement, ce qui nuit à la posture", "Verrouiller complètement les coudes en haut du mouvement"]', true, '["Adjust the seat height so the handles align with your mid-chest level", "Sit with your back flat against the backrest and feet planted firmly on the floor", "Grip the handles with a firm, overhand grip and position your hands slightly wider than shoulder-width", "Press the handles forward and slightly upward in a smooth, controlled motion", "Extend your arms until they are nearly straight but avoid locking out your elbows completely", "Slowly lower the handles back to the starting position with control"]', '["Ajuste la hauteur du siège pour que les poignées soient au niveau de ton milieu de poitrine", "Assieds-toi avec le dos bien plaqué contre le dossier et les pieds fermement ancrés au sol", "Saisis les poignées avec une prise ferme, légèrement plus large que tes épaules", "Pousse les poignées vers l''avant et légèrement vers le haut de manière fluide et contrôlée", "Étends tes bras jusqu''à presque les verrouiller sans bloquer complètement tes coudes", "Redescends lentement les poignées à la position de départ avec contrôle"]', '["Garde ton ventre engagé et assure-toi que ton dos touche le dossier durant tout le mouvement", "Évite de pousser les poignées trop haut ou trop bas - maintiens l''angle naturel de ta poitrine", "Contrôle aussi bien la phase de poussée que celle de redescente pour maximiser l''engagement musculaire", "Garde tes poignets droits et alignés avec tes avant-bras pour prévenir les blessures", "Expire pendant la phase de poussée et inspire en redescendant le poids"]', '["Keep your core engaged and maintain contact between your back and the pad throughout the movement", "Avoid pressing the handles too high or too low - maintain the natural pressing angle of your chest", "Control both the pressing and lowering phases of the movement to maximize muscle engagement", "Keep your wrists straight and aligned with your forearms to prevent injury", "Breathe out during the pressing phase and breathe in as you lower the weight"]', '6f5b8c08-2853-477c-875b-b459d4f98fa9', 'seated-incline-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('57d28b45-1b89-4a84-84a1-879997ebd9a2', 'Pompes sautées en planche avec touches de pieds', NULL, NULL, 'Push up jack plank into toe touches', 'Chest', '[]', 'Chest', 'Beginner', 16, '/videos/chest/push-up-jack-plank-into-toe-touches.mp4', NULL, NULL, NULL, '/videos/thumbnails/push-up-jack-plank-into-toe-touches.jpg', NULL, '["Garde ton core engagé pour éviter les tensions dans le bas du dos", "Atterris doucement sur la pointe des pieds pour réduire l''impact", "Préserve la forme de la planche même pendant le saut", "Maintiens tes épaules stables et évite de déplacer ton poids en avant ou en arrière", "Commence lentement et augmente la vitesse seulement quand tu peux garder une bonne forme"]', '["Se laisser aller avec les hanches", "Ne pas maintenir la tête alignée avec le corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "push up jack plank into toe touches"]', true, '2026-04-03 12:24:58.492345+00', '2026-04-03 12:24:58.492345+00', 'Position de départ : Commence en position de planche haute, mains placées sous les épaules, corps droit des pieds à la tête. Exécution : Saute les pieds écartés tout en maintenant la position de planche, puis ramène-les ensemble, créant ainsi un mouvement de jumping jack avec les jambes tout en gardant le haut du corps stable.', '["Se laisser aller avec les hanches", "Ne pas maintenir la tête alignée avec le corps"]', true, '["Start in a high plank position with hands directly under shoulders and body in a straight line", "Engage your core and keep your back flat throughout the entire movement", "Jump both feet out wide to the sides while maintaining the plank position", "Immediately jump both feet back to the starting position", "Keep your hands firmly planted and avoid letting your hips sag or pike up", "Maintain steady breathing and controlled movements throughout the exercise"]', '["Commence en position de planche haute, mains sous les épaules et corps en ligne droite", "Active ton core et garde ton dos plat durant tout le mouvement", "Saute les deux pieds largement sur les côtés tout en maintenant la position de planche", "Ramène immédiatement les deux pieds à la position de départ", "Garde tes mains bien ancrées et évite que tes hanches ne s''affaissent ou ne se relèvent", "Respire de manière régulière et contrôle tes mouvements tout au long de l''exercice"]', '["Garde ton core engagé pour éviter les tensions dans le bas du dos", "Atterris doucement sur la pointe des pieds pour réduire l''impact", "Préserve la forme de la planche même pendant le saut", "Maintiens tes épaules stables et évite de déplacer ton poids en avant ou en arrière", "Commence lentement et augmente la vitesse seulement quand tu peux garder une bonne forme"]', '["Keep your core engaged throughout to prevent lower back strain", "Land softly on the balls of your feet to reduce impact", "Maintain proper plank form even during the jumping motion", "Keep your shoulders stable and avoid shifting weight forward or backward", "Start slowly and increase speed only when you can maintain proper form"]', 'e6348f43-b8ab-4e91-a211-0d766e35c9fe', 'push-up-jack-plank-into-toe-touches', NULL, NULL);
INSERT INTO public.exercises VALUES ('f4294892-5453-4434-a4d3-1b8dbb6d2124', 'Bear crawl avec tapotement d''épaule et pompe pike', NULL, NULL, 'Bear crawl shoulder tap to pike push up', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/bear-crawl-shoulder-tap-to-pike-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-crawl-shoulder-tap-to-pike-push-up.jpg', NULL, '["Garde le core bien serré pendant tout le mouvement pour maintenir la stabilité et protéger le bas du dos", "Minimise la rotation des hanches lors des tapotements d''épaule en engageant les fessiers et en maintenant une position de planche solide", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement musculaire et réduire le risque de blessure", "Assure-toi de bien réaliser la pompe pike en gardant les jambes droites et en ciblant les épaules sans laisser les hanches s''affaisser", "Commence par moins de répétitions et augmente progressivement, car cet exercice demande une solide force du haut du corps et du core"]', '["Ne pas engager le core, ce qui peut provoquer des douleurs lombaires", "Effectuer les tapotements d''épaule trop rapidement, entraînant une perte d''équilibre et de contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "bear crawl shoulder tap to pike push up"]', true, '2026-04-03 12:24:55.650343+00', '2026-04-03 12:24:55.650343+00', 'Position de départ : Commence en position de bear crawl, mains à la largeur des épaules, genoux juste au-dessus du sol et le core engagé. Exécution : Effectue un tapotement d''épaule en levant une main pour toucher l''épaule opposée, puis passe en position pike pour réaliser une pompe avant de revenir à la position de bear crawl.', '["Ne pas engager le core, ce qui peut provoquer des douleurs lombaires", "Effectuer les tapotements d''épaule trop rapidement, entraînant une perte d''équilibre et de contrôle"]', true, '["Start in bear crawl position with hands shoulder-width apart and knees hovering 2-3 inches off the ground", "Lift your right hand and tap your left shoulder while maintaining balance on three points of contact", "Return your right hand to the ground, then repeat the shoulder tap with your left hand to right shoulder", "While keeping legs straight to transition into a downward dog or pike position", "Perform one pike push-up by lowering your head toward the ground between your hands and pressing back up", "Walk your feet back out to return to the starting bear crawl position and repeat the sequence"]', '["Commence en position de bear crawl avec les mains à la largeur des épaules et les genoux à 5-8 cm du sol", "Lève ta main droite et touche ton épaule gauche tout en maintenant l''équilibre sur trois points de contact", "Ramène ta main droite au sol, puis répète le tapotement avec ta main gauche vers ton épaule droite", "En gardant les jambes droites, passe en position de chien tête en bas ou pike", "Effectue une pompe pike en abaissant ta tête vers le sol entre tes mains et en te relevant", "Ramène tes pieds en arrière pour revenir à la position initiale de bear crawl et répète la séquence"]', '["Garde le core bien serré pendant tout le mouvement pour maintenir la stabilité et protéger le bas du dos", "Minimise la rotation des hanches lors des tapotements d''épaule en engageant les fessiers et en maintenant une position de planche solide", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement musculaire et réduire le risque de blessure", "Assure-toi de bien réaliser la pompe pike en gardant les jambes droites et en ciblant les épaules sans laisser les hanches s''affaisser", "Commence par moins de répétitions et augmente progressivement, car cet exercice demande une solide force du haut du corps et du core"]', '["Keep your core tight throughout the entire movement to maintain stability and protect your lower back", "Minimize hip rotation during shoulder taps by engaging your glutes and maintaining a strong plank position", "Focus on controlled movements rather than speed to maximize muscle engagement and reduce injury risk", "Ensure proper pike push-up form by keeping your legs straight and targeting the shoulders rather than letting your hips sag", "Start with fewer repetitions and build up gradually as this exercise requires significant upper body and core strength"]', 'c4d91f02-e796-4992-a08d-531b1d4bb16b', 'bear-crawl-shoulder-tap-to-pike-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('74d392aa-15e2-4559-b54c-432fb6e4eaee', 'Pompes sur un bras (Gauche)', NULL, NULL, 'Singel arm push up (L)', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/singel-arm-push-up-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/singel-arm-push-up-l.jpg', NULL, '["Élargis ta base pour plus de stabilité et d''équilibre durant l''exercice sur un bras.", "Contracte ton tronc pour éviter le mouvement des hanches pendant l''effort.", "Commence par une amplitude réduite si tu ne peux pas faire de vraies pompes sur un bras.", "Assure-toi que ton bras en action reste près de ton corps pour éviter qu''il ne s''ouvre trop.", "Progresse étape par étape, maîtrise d''abord les pompes classiques puis passe aux variantes surélevées avant de tenter ce mouvement avancé."]', '["Ne pas garder le tronc contracté, ce qui peut entraîner une mauvaise posture.", "Laisser le bras de travail s''écarter trop du corps."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "singel arm push up (l)"]', true, '2026-04-03 12:24:59.170791+00', '2026-04-03 12:24:59.170791+00', 'Position de départ : En position de planche, les pieds légèrement plus écartés que la largeur des épaules, main gauche sur le sol et bras droit derrière le dos ou sur le côté. Exécution : Abaisse ton corps en pliant le bras gauche jusqu''à ce que ta poitrine frôle le sol, puis pousse avec le bras gauche pour revenir à la position de départ.', '["Ne pas garder le tronc contracté, ce qui peut entraîner une mauvaise posture.", "Laisser le bras de travail s''écarter trop du corps."]', true, '["Start in a standard plank position then remove your right hand and place it behind your back or out to the side", "Position your feet wider than normal to create a stable base of support", "Keep your core engaged and body in a straight line from head to heels", "Lower your body slowly by bending your left elbow until your chest nearly touches the ground", "Push through your left hand to return to the starting plank position", "Maintain control throughout the entire range of motion"]', '["Établis une position de planche classique puis enlève ta main droite pour la placer derrière ton dos ou sur le côté.", "Écarte bien tes pieds pour créer une base stable.", "Engage ton tronc et maintiens ton corps en ligne droite de la tête aux talons.", "Abaisse-toi lentement en pliant le coude gauche jusqu''à ce que ta poitrine soit proche du sol.", "Pousse avec ta main gauche pour revenir en position de planche.", "Garde le contrôle sur toute l amplitude du mouvement."]', '["Élargis ta base pour plus de stabilité et d''équilibre durant l''exercice sur un bras.", "Contracte ton tronc pour éviter le mouvement des hanches pendant l''effort.", "Commence par une amplitude réduite si tu ne peux pas faire de vraies pompes sur un bras.", "Assure-toi que ton bras en action reste près de ton corps pour éviter qu''il ne s''ouvre trop.", "Progresse étape par étape, maîtrise d''abord les pompes classiques puis passe aux variantes surélevées avant de tenter ce mouvement avancé."]', '["Widen your foot stance significantly to provide better stability and balance during the single-arm movement", "Keep your core extremely tight to prevent your hips from rotating or dropping during the exercise", "Start with partial range of motion if you cannot complete a full single-arm push-up", "Ensure your working arm stays close to your body rather than flaring out excessively", "Progress gradually by first mastering regular push-ups and then elevated single-arm variations before attempting this advanced movement"]', 'b92cf13a-2241-45c5-b2ba-d5043c9b3ea0', 'singel-arm-push-up-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('5b9ce2ed-ef9b-4858-939b-a2614cbc2026', 'Disque avec haltère (L)', NULL, NULL, 'Dumbbell Discus (L)', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/dumbbell-discus-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-discus-l.jpg', NULL, '["Garde toujours les muscles du tronc engagés pour protéger ta colonne vertébrale et générer de la puissance", "Choisis un poids qui te permet de garder le contrôle sur toute la durée du mouvement", "Concentre-toi sur des mouvements fluides et maîtrisés plutôt que sur la vitesse pour éviter les blessures", "Assure-toi d''avoir suffisamment d''espace autour de toi avant de réaliser cet exercice dynamique", "Expire lors de la phase explosive et inspire lors du retour"]', '["Ne pas engager le tronc peut entraîner des tensions lombaires", "Se précipiter dans le mouvement réduit le contrôle et augmente le risque de blessure"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "dumbbell discus (l)"]', true, '2026-04-03 12:24:56.414156+00', '2026-04-03 12:24:56.414156+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des épaules, un haltère tenu à deux mains au niveau de la poitrine, bras étendus. Exécution : Fais pivoter ton torse vers la droite, puis balance explosivement l''haltère en arc vers le gauche, comme si tu lançais un disque.', '["Ne pas engager le tronc peut entraîner des tensions lombaires", "Se précipiter dans le mouvement réduit le contrôle et augmente le risque de blessure"]', true, '["Hold the dumbbell securely with both hands using an overhand grip at chest height", "Plant your feet firmly shoulder-width apart and engage your core muscles", "Rotate your torso to the right side while keeping the dumbbell close to your body", "Explosively swing the dumbbell in a smooth arc across your body toward the left side", "Control the movement as you return to the starting position", "Maintain proper posture throughout the entire range of motion"]', '["Tiens fermement l''haltère avec les deux mains en prise pronation à hauteur de la poitrine", "Ancre tes pieds bien à plat à la largeur des épaules et contracte les muscles de ton corps", "Fais pivoter ton torse vers la droite tout en gardant l''haltère près de ton corps", "Balance explosivement l''haltère dans un arc fluide vers la gauche", "Contrôle le mouvement en revenant à la position initiale", "Garde une posture correcte tout au long du mouvement"]', '["Garde toujours les muscles du tronc engagés pour protéger ta colonne vertébrale et générer de la puissance", "Choisis un poids qui te permet de garder le contrôle sur toute la durée du mouvement", "Concentre-toi sur des mouvements fluides et maîtrisés plutôt que sur la vitesse pour éviter les blessures", "Assure-toi d''avoir suffisamment d''espace autour de toi avant de réaliser cet exercice dynamique", "Expire lors de la phase explosive et inspire lors du retour"]', '["Keep your core engaged throughout the movement to protect your spine and generate power", "Use a weight that allows you to maintain control throughout the full range of motion", "Focus on smooth, controlled movements rather than speed to prevent injury", "Ensure adequate space around you before performing this dynamic exercise", "Breathe out during the explosive phase and breathe in during the return movement"]', 'a46c036e-f0f6-4c03-8216-cc80da58ee3d', 'dumbbell-discus-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('4d696ec7-5510-4556-b9ed-68508253adbc', 'Développez votre poitrine avec le Floor Press', NULL, 'ضغط على الأرض', 'Floor Press', 'Chest', '[]', 'Chest', 'Intermediate', 1, '/videos/chest/floor-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/floor-press.jpg', NULL, '["Gardez votre sangle abdominale engagée et le bas du dos bien plaqué contre le sol tout au long de l''exercice", "Concentrez-vous sur l''étirement de vos muscles pectoraux en position basse sans forcer", "Maintenez le contrôle pendant les phases de descente et de montée - évitez de rebondir sur le sol", "Gardez les épaules tirées vers l''arrière et vers le bas pour une bonne position des homoplate", "Commencez avec une amplitude confortable et augmentez progressivement à mesure que votre flexibilité s''améliore"]', '["Ne pas garder le bas du dos collé au sol", "Bousel les bras au lieu de descendre de manière contrôlée"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "barbell", "floor press"]', true, '2026-04-03 12:24:56.753903+00', '2026-04-03 12:24:56.753903+00', 'Position de départ : Allongez-vous sur le dos, genoux fléchis, pieds bien ancrés au sol, bras tendus vers le plafond, paumes face à vous. Exécution : Abaissez vos bras sur les côtés jusqu''à ce que vos bras supérieurs touchent le sol, puis remontez en contractant vos muscles pectoraux.', '["Ne pas garder le bas du dos collé au sol", "Bousel les bras au lieu de descendre de manière contrôlée"]', true, '["Lie on your back with knees bent and feet planted firmly on the floor for stability", "Extend your arms straight up toward the ceiling with palms facing forward and hands positioned slightly wider than shoulder-width", "Slowly lower your arms out to the sides in a controlled arc motion until your upper arms gently touch the floor", "Keep a slight bend in your elbows throughout the entire movement to protect your joints", "Press your arms back up to the starting position by squeezing your chest muscles together", "Maintain steady breathing, exhaling as you press up and inhaling as you lower down"]', '["Allongez-vous sur le dos avec les genoux fléchis et les pieds bien ancrés au sol pour plus de stabilité", "Etendez vos bras droite vers le plafond, paumes orientées vers l''avant et mains légèrement plus larges que les épaules", "Abaissez lentement vos bras sur les côtés dans un mouvement contrôlé jusqu''à ce que vos bras supérieurs touchent délicatement le sol", "Gardez une légère flexion des coudes tout au long du mouvement pour protéger vos articulations", "Remontez vos bras à la position de départ en contractant vos pectoraux", "Maintenez une respiration régulière, expirez en montant et inspirez en descendant"]', '["Gardez votre sangle abdominale engagée et le bas du dos bien plaqué contre le sol tout au long de l''exercice", "Concentrez-vous sur l''étirement de vos muscles pectoraux en position basse sans forcer", "Maintenez le contrôle pendant les phases de descente et de montée - évitez de rebondir sur le sol", "Gardez les épaules tirées vers l''arrière et vers le bas pour une bonne position des homoplate", "Commencez avec une amplitude confortable et augmentez progressivement à mesure que votre flexibilité s''améliore"]', '["Keep your core engaged and lower back pressed against the floor throughout the movement", "Focus on feeling the stretch in your chest muscles at the bottom position without forcing the range of motion", "Maintain control during both the lowering and pressing phases - avoid bouncing off the floor", "Keep your shoulders pulled back and down to maintain proper shoulder blade position", "Start with a comfortable range of motion and gradually increase as flexibility improves"]', 'd536723e-7e3f-460d-a6c5-e9993bfbec4c', 'floor-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('2b6b14e1-4eb1-4241-9936-c4c1dd228ba1', 'Développé incliné à la machine', NULL, 'الصحافة المائلة على الجهاز', 'Incline Machine Press', 'Chest', '[]', 'Chest', 'Beginner', 8, '/videos/chest/incline-machine-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-machine-press.jpg', NULL, '["Engage ton ventre et garde le contact entre ton dos et le banc tout au long du mouvement", "Concentre-toi sur la contraction de tes muscles pectoraux au sommet du mouvement pour une activation maximale", "Contrôle la phase de descente - ne laisse pas le poids tomber rapidement", "Expire pendant la phase de poussée et inspire en abaissant le poids", "Commence avec des poids légers pour maîtriser la forme avant de passer à des charges plus lourdes."]', '["Ne pas ajuster la hauteur du siège correctement", "Fléchir les coudes complètement à la fin du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "machine", "incline machine press"]', true, '2026-04-03 12:24:57.31122+00', '2026-04-03 12:24:57.31122+00', 'Position de départ : Assieds-toi sur la machine de développé incliné, ajuste la hauteur du siège pour que les poignées soient à la hauteur de ta poitrine. Exécution : Pousse les poignées en avant jusqu''à ce que tes bras soient complètement étendus, puis redescends lentement à la position de départ.', '["Ne pas ajuster la hauteur du siège correctement", "Fléchir les coudes complètement à la fin du mouvement"]', true, '["Adjust the incline bench to 30-45 degrees and set the appropriate weight on the machine", "Sit on the bench with your back flat against the pad and feet firmly planted on the floor", "Grip the handles with hands slightly wider than shoulder-width apart, palms facing forward", "Press the handles up and slightly forward in a smooth arc until your arms are fully extended", "Slowly lower the weight back to the starting position with control, feeling a stretch in your chest", "Repeat for desired number of repetitions without locking out your elbows completely"]', '["Régle la résistance et incline le banc à 30-45 degrés", "Assieds-toi sur le banc, le dos plaqué contre le coussin et les pieds bien ancrés au sol", "Prends les poignées avec les mains légèrement plus larges que la largeur des épaules, paumes orientées vers l''avant", "Pousse les poignées vers le haut et légèrement en avant dans un arc fluide jusqu''à ce que tes bras soient complètement tendus", "Descends lentement le poids jusqu''à la position de départ en contrôlant le mouvement, en sentant l''étirement dans ta poitrine", "Répète pour le nombre de répétitions souhaité sans bloquer complètement tes coudes."]', '["Engage ton ventre et garde le contact entre ton dos et le banc tout au long du mouvement", "Concentre-toi sur la contraction de tes muscles pectoraux au sommet du mouvement pour une activation maximale", "Contrôle la phase de descente - ne laisse pas le poids tomber rapidement", "Expire pendant la phase de poussée et inspire en abaissant le poids", "Commence avec des poids légers pour maîtriser la forme avant de passer à des charges plus lourdes."]', '["Keep your core engaged and maintain contact between your back and the bench throughout the movement", "Focus on squeezing your chest muscles at the top of the movement for maximum muscle activation", "Control the negative (lowering) portion of the lift - don''t let the weight drop quickly", "Breathe out during the pressing phase and breathe in while lowering the weight", "Start with lighter weight to master the form before progressing to heavier loads"]', '00a92c05-9865-489d-8495-a8f72af802a6', 'incline-machine-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('52847bc8-5d5f-49de-b226-0911b2816c58', 'Pompes Triceps en Diamant', NULL, NULL, 'Push-Ups - Close Triceps Position (Diamond push ups)', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/push-ups-close-triceps-position-diamond-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/push-ups-close-triceps-position-diamond-push-ups.jpg', NULL, '["Cette variante cible principalement les triceps, tout en engageant aussi la poitrine et les épaules", "Garde tes coudes collés à tes côtés au lieu de les écarter", "Si c''est trop difficile, modifie l''exercice en le faisant sur les genoux ou en surélevant tes mains sur un banc", "Maintiens une position de planche rigide pour protéger ton bas du dos", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour une activation musculaire maximale"]', '["Coudes écartés au lieu de rester proches du corps", "Ne pas garder le core engagé, ce qui peut entraîner une mauvaise posture"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "push-ups - close triceps position (diamond push ups)"]', true, '2026-04-03 12:24:58.533166+00', '2026-04-03 12:24:58.533166+00', 'Position de départ : Place-toi en position de planche, les mains serrées sous ta poitrine, formant un diamant avec tes pouces et index. Execution : Abaisse ton corps jusqu''à ce que ta poitrine frôle tes mains, puis remonte en gardant la même position de mains.', '["Coudes écartés au lieu de rester proches du corps", "Ne pas garder le core engagé, ce qui peut entraîner une mauvaise posture"]', true, '["Position hands directly under your chest with thumbs and index fingers touching to form a diamond shape", "Keep your body in a straight line from head to heels, engaging your core throughout the movement", "Lower your body slowly and controlled until your chest nearly touches your hands", "Press through your palms to push your body back to the starting position", "Maintain the diamond hand position throughout the entire range of motion", "Keep your elbows close to your body as you move up and down"]', '["Positionne tes mains directement sous ta poitrine avec les pouces et index qui se touchent pour former un diamant", "Maintiens ton corps en ligne droite de la tête aux talons, engage bien ton core pendant tout le mouvement", "Descends lentement et de façon contrôlée jusqu''à ce que ta poitrine touche presque tes mains", "Presse avec tes paumes pour remonter à la position de départ", "Garde la position des mains en diamant tout au long du mouvement", "Rapproche tes coudes de ton corps pendant que tu descends et remontes"]', '["Cette variante cible principalement les triceps, tout en engageant aussi la poitrine et les épaules", "Garde tes coudes collés à tes côtés au lieu de les écarter", "Si c''est trop difficile, modifie l''exercice en le faisant sur les genoux ou en surélevant tes mains sur un banc", "Maintiens une position de planche rigide pour protéger ton bas du dos", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour une activation musculaire maximale"]', '["This variation primarily targets the triceps while still engaging the chest and shoulders", "Keep elbows tucked close to your sides rather than flaring them out wide", "If too difficult, modify by performing on your knees or elevating your hands on a bench", "Maintain a rigid plank position throughout to protect your lower back", "Focus on controlled movement rather than speed for maximum muscle activation"]', '9d46942e-53df-455c-a996-8936145ab8d2', 'push-ups-close-triceps-position-diamond-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('8f25bf61-4757-4ebf-b8f3-89008d775b69', 'Dumbbell Get Ups (R)', NULL, 'تيبش ديال راجال (R)', 'Dumbbell get ups (R)', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/dumbbell-get-ups-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-get-ups-r.jpg', NULL, '["Garde ton bras portant l''haltère bien tendu et vertical pour éviter les blessures à l''épaule", "Déplace-toi lentement et avec précision à chaque étape pour conserver une bonne forme", "Engage ton core tout au long du mouvement pour assurer stabilité et soutien", "Commence avec un poids léger pour maîtriser le mouvement avant d''augmenter la charge", "Garde toujours un œil sur l''haltère pour t''aider à rester équilibré et en contrôle"]', '["Ne pas garder le bras avec l''haltère tendu, ce qui peut causer des blessures", "Bouger trop vite et perdre en contrôle, cela affecte la qualité du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "dumbbell get ups (r)"]', true, '2026-04-03 12:24:56.474784+00', '2026-04-03 12:24:56.474784+00', 'Allonge-toi sur le dos, un haltère dans la main droite, bras tendu vers le plafond. Prêt pour l''action ? C''est parti !', '["Ne pas garder le bras avec l''haltère tendu, ce qui peut causer des blessures", "Bouger trop vite et perdre en contrôle, cela affecte la qualité du mouvement"]', true, '["Lie flat on your back holding the dumbbell in your right hand with arm fully extended overhead", "Keep your eyes on the dumbbell throughout the entire movement to maintain balance and control", "Roll onto your left side and use your left hand to push yourself up to a seated position", "Bring your left leg forward and plant your left foot firmly on the ground", "Push through your left heel to stand up while maintaining the dumbbell overhead", "Reverse the movement to return to the starting position with control"]', '["Allonge-toi sur le dos avec l''haltère dans la main droite, bras tendu vers le haut", "Concentre-toi sur l''haltère pour garder l''équilibre et le contrôle", "Roulez sur le côté gauche et utilise ta main gauche pour te redresser en position assise", "Amène ta jambe gauche vers l''avant et pose le pied gauche fermement au sol", "Pousse avec ton talon gauche pour te lever tout en maintenant l''haltère au-dessus de ta tête", "Inverse le mouvement avec contrôle pour revenir à la position de départ"]', '["Garde ton bras portant l''haltère bien tendu et vertical pour éviter les blessures à l''épaule", "Déplace-toi lentement et avec précision à chaque étape pour conserver une bonne forme", "Engage ton core tout au long du mouvement pour assurer stabilité et soutien", "Commence avec un poids léger pour maîtriser le mouvement avant d''augmenter la charge", "Garde toujours un œil sur l''haltère pour t''aider à rester équilibré et en contrôle"]', '["Keep the dumbbell arm locked out and vertical throughout the entire exercise to prevent shoulder injury", "Move slowly and deliberately through each phase to maintain proper form and control", "Keep your core engaged throughout the movement to provide stability and support", "Start with a lighter weight to master the movement pattern before progressing to heavier loads", "Maintain visual contact with the dumbbell to help with balance and proprioception"]', 'beee4955-3dbc-4aa1-be35-d01666713f72', 'dumbbell-get-ups-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('b4970449-3474-4616-befc-984fd13417f6', 'Burpees avec pompes', NULL, 'برابس مع الضغط', 'Push up burpees', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/push-up-burpees.mp4', NULL, NULL, NULL, '/videos/thumbnails/push-up-burpees.jpg', NULL, '["Garde une ligne droite entre la tête et les pieds durant la planche et la pompe", "Contracte bien tes abdos pendant tout le mouvement pour protéger ton bas du dos", "Atterris en douceur lors des sauts en arrière et des sauts en hauteur pour diminuer l''impact sur les articulations", "Si tu es débutant, n''hésite pas à faire des pas au lieu de sauter pour réduire l’intensité", "Concentre-toi sur la forme correcte des pompes plutôt que sur la vitesse - la poitrine doit toucher le sol et les bras doivent s''étendre complètement."]', '["Ne pas garder le corps droit pendant les pompes", "Oublier de se plier aux genoux lors de l''atterrissage, ce qui augmente le risque de blessures"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "push up burpees"]', true, '2026-04-03 12:24:58.476142+00', '2026-04-03 12:24:58.476142+00', 'Mets-toi debout, les pieds écartés à la largeur des épaules et les bras le long du corps. C''est parti pour une série de burpees avec pompes qui va muscler ta poitrine et faire battre ton cœur !', '["Ne pas garder le corps droit pendant les pompes", "Oublier de se plier aux genoux lors de l''atterrissage, ce qui augmente le risque de blessures"]', true, '["Begin standing with feet shoulder-width apart and core engaged", "Drop into a deep squat and place both hands firmly on the floor in front of you", "Jump or step both feet back simultaneously into a high plank position", "Lower your chest to the floor in a controlled push-up, keeping your body in a straight line", "Push back up to plank position, then jump or step feet back toward your hands", "Explosively jump straight up with arms reaching overhead, then land softly to complete one rep"]', '["Débute en te tenant debout, pieds écartés à la largeur des épaules et abdos contractés", "Descends en profondeur dans un squat et pose tes mains fermement au sol devant toi", "Saute ou fais un pas en arrière pour te mettre en position de planche haute", "Abaisse ta poitrine vers le sol en effectuant une pompe, en gardant ton corps bien droit", "Remonte en position de planche, puis ramène rapidement tes pieds vers tes mains", "Saute explosivement vers le haut en levant les bras au-dessus de ta tête, puis atterris doucement pour compléter une répétition."]', '["Garde une ligne droite entre la tête et les pieds durant la planche et la pompe", "Contracte bien tes abdos pendant tout le mouvement pour protéger ton bas du dos", "Atterris en douceur lors des sauts en arrière et des sauts en hauteur pour diminuer l''impact sur les articulations", "Si tu es débutant, n''hésite pas à faire des pas au lieu de sauter pour réduire l’intensité", "Concentre-toi sur la forme correcte des pompes plutôt que sur la vitesse - la poitrine doit toucher le sol et les bras doivent s''étendre complètement."]', '["Maintain a straight line from head to heels during the plank and push-up phases", "Keep your core tight throughout the entire movement to protect your lower back", "Land softly on both the jump back and jump up portions to reduce impact on joints", "If you''re a beginner, step back and forward instead of jumping to reduce intensity", "Focus on proper push-up form rather than speed - chest should touch the ground and arms should fully extend"]', 'c2410e7d-79c4-4593-82df-c42e8fd3450e', 'push-up-burpees', NULL, NULL);
INSERT INTO public.exercises VALUES ('9413e1fb-422a-47af-898d-72eacd666194', 'Inchworm avec Pompes Pike', NULL, NULL, 'Inchworm to pike push ups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/inchworm-to-pike-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/inchworm-to-pike-push-ups.jpg', NULL, '["Engage bien ton core tout au long du mouvement pour protéger ton bas du dos.", "Garde les jambes bien droites pendant les phases de marche et en position pike pour un étirement maximal des ischio-jambiers et des mollets.", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour activer les muscles au maximum et éviter les blessures.", "Assure-toi que tes épaules sont directement au-dessus de tes poignets en position de planche pour éviter toute tension au niveau des poignets.", "Si la pompe pike complète est trop difficile, reste simplement en position pike sans abaisser la tête."]', '["Ne pas engager le core, ce qui peut mettre en danger le bas du dos.", "Laisser les jambes se plier pendant les phases de marche ou en position pike, diminuant ainsi l''efficacité du mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "inchworm to pike push ups"]', true, '2026-04-03 12:24:57.211788+00', '2026-04-03 12:24:57.211788+00', 'Position de départ : Tiens-toi bien droit, les pieds écartés à la largeur des hanches et les bras le long du corps. Exécution : Marche avec tes mains vers l''avant jusqu''à obtenir une position de planche, fais une pompe pike en levant les hanches et en abaissant ta tête vers le sol, puis marche à nouveau avec tes mains vers ta position debout.', '["Ne pas engager le core, ce qui peut mettre en danger le bas du dos.", "Laisser les jambes se plier pendant les phases de marche ou en position pike, diminuant ainsi l''efficacité du mouvement."]', true, '["Stand with feet hip-width apart and hinge forward at the hips to place your hands on the ground", "Walk your hands forward one at a time until you reach a high plank position with straight arms", "Lift your hips up and back into a downward dog position while keeping your hands planted", "Lower your head toward the ground by bending your elbows, creating a pike push-up movement", "Press back up to the pike position, then walk your hands back toward your feet", "Return to standing by lifting your torso and bringing your arms back to your sides"]', '["Tiens-toi debout, pieds écartés à la largeur des hanches, plie-toi en avant pour poser tes mains au sol.", "Marche avec tes mains une à une jusqu''à atteindre une position de planche haute avec les bras bien droits.", "Lève tes hanches vers le haut et vers l''arrière en position de chien tête en bas tout en gardant les mains au sol.", "Abaisse ta tête vers le sol en pliant les coudes pour réaliser le mouvement de pompe pike.", "Reviens à la position pikée, puis marche avec tes mains vers tes pieds.", "Relève-toi en soulevant le torse et en ramenant les bras le long du corps."]', '["Engage bien ton core tout au long du mouvement pour protéger ton bas du dos.", "Garde les jambes bien droites pendant les phases de marche et en position pike pour un étirement maximal des ischio-jambiers et des mollets.", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour activer les muscles au maximum et éviter les blessures.", "Assure-toi que tes épaules sont directement au-dessus de tes poignets en position de planche pour éviter toute tension au niveau des poignets.", "Si la pompe pike complète est trop difficile, reste simplement en position pike sans abaisser la tête."]', '["Keep your core engaged throughout the entire movement to protect your lower back", "Maintain straight legs during the walking phases and pike position for maximum hamstring and calf stretch", "Focus on controlled movement rather than speed to maximize muscle activation and prevent injury", "Keep your shoulders directly over your wrists in the plank position to avoid wrist strain", "If the full pike push-up is too challenging, simply hold the pike position without lowering your head"]', 'e7fa2b6f-4d2b-478a-a1c0-8bca51b04a13', 'inchworm-to-pike-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('3e9d8abf-17d6-4ad9-badc-446090287afd', 'Rowing Unilatéral avec Haltère (Bras Droit)', NULL, NULL, 'Dumbbell One-Arm Upright Row (R)', 'Back', '[]', 'Back', 'Intermediate', 2, '/videos/back/dumbbell-one-arm-upright-row-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-one-arm-upright-row-r.jpg', NULL, '["Garde l''haltère près de ton corps pour maintenir une forme correcte et éviter les blessures à l''épaule", "Mène avec le coude plutôt qu''avec la main pour activer correctement les deltoïdes arrière et les trapèzes supérieurs", "Évite de lever le poids trop haut au-dessus de l''épaule pour prévenir le stress sur l''articulation de l''épaule", "Contrôle bien la phase de descente pour maximiser l''engagement musculaire et éviter les blessures", "Maintiens une colonne vertébrale neutre et évite de te pencher ou de te balancer pour compenser la charge unilatérale"]', '["Ne pas garder le coude près du corps, ce qui peut limiter l''activation musculaire", "Lever l''haltère trop haut, ce qui peut engendrer des douleurs à l''épaule"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "dumbbell one-arm upright row (r)"]', true, '2026-04-03 12:24:56.533803+00', '2026-04-03 12:24:56.533803+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, un haltère en main droite, bras pendu le long du corps. Exécution : Tire l''haltère le long de ton corps en levant le coude haut et sur le côté jusqu''à la hauteur de la poitrine, puis redescends lentement à la position de départ.', '["Ne pas garder le coude près du corps, ce qui peut limiter l''activation musculaire", "Lever l''haltère trop haut, ce qui peut engendrer des douleurs à l''épaule"]', true, '["Stand with feet hip-width apart and core engaged, holding the dumbbell in your right hand with palm facing your body", "Keep your torso upright and shoulders back throughout the entire movement", "Pull the dumbbell up by leading with your elbow, keeping it close to your body as it travels upward", "Lift until your elbow reaches shoulder height and the dumbbell is at chest level", "Pause briefly at the top position, then slowly lower the weight back to starting position with control", "Complete all repetitions on the right side before switching to the left arm"]', '["Tiens-toi bien droit, les pieds écartés à la largeur des hanches et le ventre contracté, l''haltère dans la main droite paume vers ton corps", "Garde ton buste droit et tes épaules en arrière tout au long du mouvement", "Tire l''haltère vers le haut en menant avec le coude, garde-le près de ton corps pendant qu''il monte", "Continue jusqu''à ce que ton coude atteigne la hauteur de l''épaule et que l''haltère soit à la hauteur de la poitrine", "Fais une pause en haut du mouvement, puis redescends lentement le poids avec contrôle à la position de départ", "Termine toutes les répétitions sur le côté droit avant de passer au bras gauche"]', '["Garde l''haltère près de ton corps pour maintenir une forme correcte et éviter les blessures à l''épaule", "Mène avec le coude plutôt qu''avec la main pour activer correctement les deltoïdes arrière et les trapèzes supérieurs", "Évite de lever le poids trop haut au-dessus de l''épaule pour prévenir le stress sur l''articulation de l''épaule", "Contrôle bien la phase de descente pour maximiser l''engagement musculaire et éviter les blessures", "Maintiens une colonne vertébrale neutre et évite de te pencher ou de te balancer pour compenser la charge unilatérale"]', '["Keep the dumbbell close to your body throughout the movement to maintain proper form and prevent shoulder impingement", "Lead with your elbow rather than your hand to ensure proper muscle activation in the rear deltoids and upper traps", "Avoid lifting the weight too high above shoulder level as this can cause shoulder joint stress", "Control the lowering phase of the movement to maximize muscle engagement and prevent injury", "Maintain a neutral spine and avoid leaning or swaying to compensate for the unilateral load"]', 'bda6ae04-2619-43a7-8261-490d85444eb2', 'dumbbell-one-arm-upright-row-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('3dc5ce8d-28e7-4b83-943c-d43ce0cca7ec', 'Rangée de haltères en planche', NULL, NULL, 'Dumbbell plank row', 'Back', '[]', 'Back', 'Beginner', 2, '/videos/back/dumbbell-plank-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-plank-row.jpg', NULL, '["Serre les fessiers", "Garde le cou neutre", "Respire normalement", "Ne lève pas les hanches trop haut", "Augmente le temps progressivement"]', '["Ne pas contracter les abdos", "Laisser les hanches tomber", "Lever les hanches trop haut", "Ne pas maintenir un bon alignement du corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "dumbbell plank row"]', true, '2026-04-03 12:24:56.542669+00', '2026-04-03 12:24:56.542669+00', 'Position de départ : Mets-toi en position de planche avec les mains qui tiennent les haltères juste sous les épaules, les pieds légèrement plus larges que la largeur des hanches pour plus de stabilité. Exécution : Tout en maintenant ta position de planche, tire un haltère vers ta cage thoracique en repliant le coude, puis abaisse-le avec contrôle et répète de l''autre côté.', '["Ne pas contracter les abdos", "Laisser les hanches tomber", "Lever les hanches trop haut", "Ne pas maintenir un bon alignement du corps"]', true, '["Forearms on floor, elbows under shoulders", "Body straight from head to heels", "Hold position", "Keep core tight, don''t let hips sag"]', '["Avant-bras au sol, coudes sous les épaules", "Corps straight des pieds à la tête", "Maintiens la position", "Contracte bien les abdos, évite de laisser les hanches s''affaisser"]', '["Serre les fessiers", "Garde le cou neutre", "Respire normalement", "Ne lève pas les hanches trop haut", "Augmente le temps progressivement"]', '["Squeeze glutes", "Keep neck neutral", "Breathe normally", "Don''t raise hips too high", "Build time gradually"]', 'b5869e95-3109-43ad-b7b5-34e6dad882f0', 'dumbbell-plank-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('6e7d95b5-e9c1-439a-80b8-e447a2836c64', 'Pompes Archer', NULL, NULL, 'Archer push up', 'Chest', '[]', 'Chest', 'Advanced', 16, '/videos/chest/archer-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/archer-push-up.jpg', NULL, '["- Garde ton ventre engagé et ton corps en ligne droite tout au long du mouvement", "- Le bras droit doit rester verrouillé et servir de soutien, sans contribuer à la poussée", "- Commence par des pompes classiques et des variantes assistées avant de te lancer dans les pompes archer", "- Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement musculaire et prévenir les blessures", "- Si c''est trop difficile, surélève tes mains sur une surface stable ou fais-le sur les genoux"]', '["- Négliger l''engagement du core", "- Ne pas garder le corps en ligne droite pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "archer push up"]', true, '2026-04-03 12:24:55.499235+00', '2026-04-03 12:24:55.499235+00', 'Position de départ : Mets-toi en position de pompe large, les mains largement écartées, bras complètement tendus. Exécution : Descends en pliant un bras tout en gardant l''autre bras droit, en transférant ton poids vers le côté du bras fléchi. Ensuite, pousse-toi pour revenir à la position de départ et alterne les côtés.', '["- Négliger l''engagement du core", "- Ne pas garder le corps en ligne droite pendant l''exercice"]', true, '["1. Start in a wide push-up position with hands placed significantly wider than shoulder-width apart and feet hip-width apart", "2. Lower your body by shifting your weight to one side, bending that arm while keeping the opposite arm straight", "3. Descend until your chest nearly touches the ground near your bent arm, with the straight arm extended to the side", "4. Push back up by driving through your bent arm while maintaining the straight arm position", "5. Return to the starting position and repeat on the opposite side", "6. Alternate sides for each repetition or complete all reps on one side before switching"]', '["1. Commence en position de pompe large, les mains bien au-delà de la largeur des épaules et les pieds écartés à la largeur des hanches", "2. Plie un bras en déplaçant ton poids d''un côté, tout en gardant l''autre bras droit", "3. Descends jusqu''à ce que ta poitrine frôle le sol près de ton bras plié, bras droit allongé sur le côté", "4. Pousse vers le haut en te concentrant sur ton bras plié, maintiens l''autre bras en position droite", "5. Retourne à la position de départ et répète de l''autre côté", "6. Alterne les côtés pour chaque répétition ou fais toutes les répétitions d''un côté avant de changer"]', '["- Garde ton ventre engagé et ton corps en ligne droite tout au long du mouvement", "- Le bras droit doit rester verrouillé et servir de soutien, sans contribuer à la poussée", "- Commence par des pompes classiques et des variantes assistées avant de te lancer dans les pompes archer", "- Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement musculaire et prévenir les blessures", "- Si c''est trop difficile, surélève tes mains sur une surface stable ou fais-le sur les genoux"]', '["- Keep your core engaged and body in a straight line throughout the movement", "- The straight arm should remain locked out and act as a support, not assist with pushing", "- Start with regular push-ups and single-arm assisted variations before attempting archer push-ups", "- Focus on controlled movement rather than speed to maximize muscle engagement and prevent injury", "- If too difficult, elevate your hands on a sturdy surface or perform on your knees"]', 'd06c3d04-aeb4-4b94-9a43-24e95201239c', 'archer-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('8a2b84d8-c36b-4b85-9c5b-16076576a30b', 'Coups de poing avec haltères', NULL, 'ضربات بالأثقال', 'Dumbbell shoulder punches', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/dumbbell-shoulder-punches.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-shoulder-punches.jpg', NULL, '["Garde ton ventre bien contracté pour éviter l''arc du dos et maintenir ta stabilité.", "Ne tends pas trop les coudes pour éviter le stress sur les articulations. Reste en contrôle !", "Maîtrise le mouvement et le poids lors du coup de poing et du retour.", "Commence avec des poids légers pour bien apprendre le mouvement avant d''augmenter la résistance.", "Penses à ta posture : épaules en arrière et poitrine en avant tout au long de l''exercice."]', '["Ne pas contrôler le mouvement, ce qui peut causer des blessures.", "Oublier de s''engager au niveau du tronc, ce qui impacte la stabilité."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "dumbbell shoulder punches"]', true, '2026-04-03 12:24:56.57556+00', '2026-04-03 12:24:56.57556+00', 'Prends tes haltères et prépare-toi à travailler tes épaules avec des coups de poing dynamiques ! Positionne-toi bien, les pieds écartés à la largeur des épaules et les haltères à hauteur d''épaules. C''est parti !', '["Ne pas contrôler le mouvement, ce qui peut causer des blessures.", "Oublier de s''engager au niveau du tronc, ce qui impacte la stabilité."]', true, '["Stand with feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with palms facing forward", "Engage your core and maintain a slight bend in your knees throughout the movement", "Punch one arm straight forward, fully extending the arm while keeping the dumbbell controlled", "Return the punching arm back to starting position at shoulder height", "Immediately punch forward with the opposite arm in an alternating pattern", "Continue alternating arms at a controlled, rhythmic pace"]', '["Place-toi avec les pieds écartés à la largeur des épaules, un haltère dans chaque main à hauteur des épaules, paumes vers l''avant.", "Contracte ton ventre et garde une légère flexion dans les genoux pendant tout l''exercice.", "Fais un coup de poing avec un bras, en tendant entièrement le bras tout en contrôlant l''haltère.", "Ramène le bras en position de départ à hauteur d''épaules.", "Punch immédiatement avec l''autre bras dans un rythme alterné.", "Continue d''alterner les bras à un rythme contrôlé et cadencé."]', '["Garde ton ventre bien contracté pour éviter l''arc du dos et maintenir ta stabilité.", "Ne tends pas trop les coudes pour éviter le stress sur les articulations. Reste en contrôle !", "Maîtrise le mouvement et le poids lors du coup de poing et du retour.", "Commence avec des poids légers pour bien apprendre le mouvement avant d''augmenter la résistance.", "Penses à ta posture : épaules en arrière et poitrine en avant tout au long de l''exercice."]', '["Keep your core tight to prevent back arching and maintain stability", "Don''t overextend or lock out your elbows completely to avoid joint stress", "Control the weight on both the punch forward and the return movement", "Start with lighter weights to master the form before increasing resistance", "Maintain proper posture with shoulders back and chest up throughout"]', '0af648a1-1d2e-438b-b687-b522c9eaa8bd', 'dumbbell-shoulder-punches', NULL, NULL);
INSERT INTO public.exercises VALUES ('fc9d92b0-cbe6-44bd-8124-00e62a9440e7', 'Pompes Deadstop et Crunch Superman', NULL, NULL, 'Deadstop push up into superman crunches', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/deadstop-push-up-into-superman-crunches.mp4', NULL, NULL, NULL, '/videos/thumbnails/deadstop-push-up-into-superman-crunches.jpg', NULL, '["Garde les abdos bien serrés pendant tout le mouvement pour protéger le bas du dos.", "Assure-toi d''avoir une bonne technique de pompe avec les coudes à 45 degrés par rapport au corps.", "Contrôle la transition entre les exercices pour éviter les blessures et maintenir la bonne posture.", "Privilégie la qualité à la quantité : fais moins de répétitions mais avec une technique parfaite plutôt que beaucoup avec une mauvaise forme.", "Expire au moment de l''effort pendant les pompes et les crunchs Superman."]', '["Ne pas maintenir le corps droit pendant les pompes.", "Ne pas faire la pause en bas, ce qui réduit l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "deadstop push up into superman crunches"]', true, '2026-04-03 12:24:56.257694+00', '2026-04-03 12:24:56.257694+00', 'Mets-toi en position de pompes classique, mains légèrement plus larges que les épaules, corps bien droit. Fais une pompe, fais une pause en bas avec la poitrine touchant le sol, puis remonte et bascule immédiatement sur le dos pour faire un crunch Superman en levant épaules et jambes ensemble.', '["Ne pas maintenir le corps droit pendant les pompes.", "Ne pas faire la pause en bas, ce qui réduit l''efficacité de l''exercice."]', true, '["Start in a plank position with hands planted firmly on the ground and core engaged", "Lower your body slowly until your chest touches the floor, maintaining a straight body line", "Pause for 1-2 seconds at the bottom position with your chest on the ground", "Push explosively back up to the starting position", "Immediately roll onto your back and perform a superman crunch by lifting your shoulders and legs off the ground simultaneously", "Return to the starting push-up position and repeat the sequence"]', '["Prends une position de planche, mains bien ancrées au sol et abdominaux contractés.", "Descends lentement jusqu''à ce que ta poitrine touche le sol tout en gardant le corps droit.", "Fais une pause de 1 à 2 secondes en bas, poitrine sur le sol.", "Pousse explosivement pour revenir à la position de départ.", "Retourne immédiatement sur le dos et fais un crunch Superman en levant épaules et jambes simultanément.", "Reviens à la position de pompe et répète la séquence."]', '["Garde les abdos bien serrés pendant tout le mouvement pour protéger le bas du dos.", "Assure-toi d''avoir une bonne technique de pompe avec les coudes à 45 degrés par rapport au corps.", "Contrôle la transition entre les exercices pour éviter les blessures et maintenir la bonne posture.", "Privilégie la qualité à la quantité : fais moins de répétitions mais avec une technique parfaite plutôt que beaucoup avec une mauvaise forme.", "Expire au moment de l''effort pendant les pompes et les crunchs Superman."]', '["Keep your core tight throughout the entire movement to protect your lower back", "Maintain proper push-up form with elbows at a 45-degree angle to your body", "Control the transition between exercises to avoid injury and maintain proper form", "Focus on quality over quantity - perform fewer reps with perfect technique rather than many with poor form", "Breathe out during the exertion phase of both the push-up and the superman crunch"]', 'e8a79472-7809-42d4-89cc-c3c351d86982', 'deadstop-push-up-into-superman-crunches', NULL, NULL);
INSERT INTO public.exercises VALUES ('6610ee22-c7be-4f58-a7b4-8148b404cbe2', 'Flexion latérale avec haltère (L)', NULL, 'الانحناء الجانبي مع الدمبل (L)', 'Dumbbell Side Bend (L)', 'Abs', '[]', 'Abs', 'Beginner', 2, '/videos/abs/dumbbell-side-bend-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-side-bend-l.jpg', NULL, '["Garde le mouvement strictement latéral, évite de tourner ou de te pencher en avant", "Maintiens une colonne vertébrale neutre tout au long de l''exercice et évite de trop te plier", "Contrôle le poids lors des phases de descente et de montée pour une efficacité maximale", "Incline-toi uniquement jusqu''à la limite de ta flexibilité sans compromettre la forme", "Concentre-toi sur la sensation d''étirement et de contraction dans tes muscles obliques"]', '["Pencher le torse en avant ou en arrière", "Laisser l''haltère descendre trop bas sans contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "dumbbell", "dumbbell side bend (l)"]', true, '2026-04-03 12:24:56.586524+00', '2026-04-03 12:24:56.586524+00', 'Position de départ : Tiens-toi droit, pieds écartés à la largeur des hanches, un haltère dans ta main droite et la main gauche sur ta hanche. Exécution : Incline-toi lentement sur le côté droit, fais descendre l''haltère vers ton genou droit, puis reviens à la position de départ.', '["Pencher le torse en avant ou en arrière", "Laisser l''haltère descendre trop bas sans contrôle"]', true, '["Stand with feet hip-width apart and hold a dumbbell in your right hand at your side", "Place your left hand on your hip for stability and maintain an upright posture", "Slowly bend your torso to the right side, letting the dumbbell lower toward your right knee", "Keep your core engaged and avoid leaning forward or backward during the movement", "Return to the starting position by contracting your left side obliques", "Complete all repetitions on one side before switching the dumbbell to the other hand"]', '["Tiens-toi debout, pieds écartés à la largeur des hanches, un haltère dans ta main droite à ton côté", "Place ta main gauche sur ta hanche pour plus de stabilité et garde une posture droite", "Incline lentement ton torse vers la droite, fais descendre l''haltère vers ton genou droit", "Engage ton core et évite de te pencher en avant ou en arrière pendant le mouvement", "Reviens à la position de départ en contractant les obliques du côté gauche", "Effectue toutes les répétitions d''un côté avant de changer l''haltère de main"]', '["Garde le mouvement strictement latéral, évite de tourner ou de te pencher en avant", "Maintiens une colonne vertébrale neutre tout au long de l''exercice et évite de trop te plier", "Contrôle le poids lors des phases de descente et de montée pour une efficacité maximale", "Incline-toi uniquement jusqu''à la limite de ta flexibilité sans compromettre la forme", "Concentre-toi sur la sensation d''étirement et de contraction dans tes muscles obliques"]', '["Keep the movement strictly in the lateral plane - avoid rotating or leaning forward", "Maintain a neutral spine throughout the exercise and avoid excessive bending", "Control the weight on both the lowering and lifting phases for maximum effectiveness", "Only bend as far as your flexibility allows without compromising form", "Focus on feeling the stretch and contraction in your oblique muscles"]', 'f66596ba-3a70-406c-8ffa-ed6641a10e19', 'dumbbell-side-bend-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('0d84c16a-d262-4d73-9c83-3ab39b9ecd8d', 'Soulevé de terre jambe seule avec haltère', NULL, 'Soulevé de terre jambe seule avec haltère', 'Dumbbell Single leg deadlift', 'Back', '[]', 'Back', 'Intermediate', 2, '/videos/back/dumbbell-single-leg-deadlift.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-single-leg-deadlift.jpg', NULL, '["Garde tes hanches bien carrées et évite de faire pivoter ton bassin durant le mouvement", "Maintiens une colonne vertébrale neutre tout au long du mouvement", "Concentre-toi sur le mouvement de basculement des hanches plutôt que de te pencher simplement en avant", "Commence avec un poids léger pour maîtriser l''équilibre et le mouvement avant de progresser", "Garde l''haltère près de ton corps durant l''exercice"]', '["Baisser le dos au lieu de pousser les hanches en arrière", "Ne pas garder l''équilibre pendant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "dumbbell single leg deadlift"]', true, '2026-04-03 12:24:56.608628+00', '2026-04-03 12:24:56.608628+00', 'Position de départ : Tiens-toi droit en tenant un haltère dans une main, les pieds écartés à la largeur des hanches et le ventre engagé. Exécution : Pousse les hanches vers l''arrière tout en levant une jambe derrière toi, baisse l''haltère vers le sol en gardant le dos droit, puis reviens à la position de départ.', '["Baisser le dos au lieu de pousser les hanches en arrière", "Ne pas garder l''équilibre pendant le mouvement"]', true, '["Hold a dumbbell in the hand opposite to the leg you will be lifting", "Stand tall with feet hip-width apart and engage your core", "Begin the movement by hinging at the hips, pushing your hips back while lifting one leg straight behind you", "Lower the dumbbell toward the ground while keeping your back straight and chest up", "Keep the standing leg slightly bent and maintain balance throughout the movement", "Return to starting position by driving through the standing heel and bringing the lifted leg back down"]', '["Tiens un haltère dans la main opposée à la jambe que tu vas lever", "Tiens-toi bien droit avec les pieds écartés à la largeur des hanches et engage ton ventre", "Commence le mouvement en poussant les hanches vers l''arrière, en levant une jambe droite derrière toi", "Abaisse l''haltère vers le sol tout en gardant le dos droit et la poitrine en avant", "Garde la jambe de soutien légèrement fléchie et maintiens ton équilibre pendant tout le mouvement", "Reviens à la position de départ en poussant avec le talon de la jambe de soutien et en rabaissant la jambe levée"]', '["Garde tes hanches bien carrées et évite de faire pivoter ton bassin durant le mouvement", "Maintiens une colonne vertébrale neutre tout au long du mouvement", "Concentre-toi sur le mouvement de basculement des hanches plutôt que de te pencher simplement en avant", "Commence avec un poids léger pour maîtriser l''équilibre et le mouvement avant de progresser", "Garde l''haltère près de ton corps durant l''exercice"]', '["Keep your hips square and avoid rotating your pelvis during the movement", "Maintain a neutral spine throughout the entire range of motion", "Focus on the hip hinge movement rather than just bending forward", "Start with lighter weight to master the balance and movement pattern before progressing", "Keep the dumbbell close to your body throughout the exercise"]', 'fef72790-359f-4f3f-9fcd-a80fb2c63b5f', 'dumbbell-single-leg-deadlift', NULL, NULL);
INSERT INTO public.exercises VALUES ('c929c97d-83bc-4ffa-9455-a6a3d10aaedc', 'Knees Pseudo Pompes', NULL, 'كُعوب خداير', 'Knee pseudo pushups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/knee-pseudo-pushups.mp4', NULL, NULL, NULL, '/videos/thumbnails/knee-pseudo-pushups.jpg', NULL, '["Ressens bien tes muscles, engage ton gainage pour éviter que tes hanches ne s''affaissent", "Adopte un tempo contrôlé plutôt que rapide pour maximiser l''engagement musculaire", "Positionne tes mains directement sous tes épaules afin d''optimiser la répartition de la force", "Évite de trop écarter les coudes pour prévenir des tensions au niveau des épaules", "Progresse progressivement en augmentant les répétitions avant de tenter des pompes classiques"]', '["Ne pas garder le dos droit", "Oublier d''engager les abdominaux"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "knee pseudo pushups"]', true, '2026-04-03 12:24:57.458035+00', '2026-04-03 12:24:57.458035+00', 'Position de départ : Commence en position de pompe classique, puis abaisse tes genoux au sol en gardant les mains bien ancrées au sol, écartées à la largeur des épaules. Exécution : Descends ta poitrine vers le sol en pliant les coudes, puis repousse vers la position de départ en maintenant une ligne droite entre tes genoux et ta tête.', '["Ne pas garder le dos droit", "Oublier d''engager les abdominaux"]', true, '["Position your hands on the floor shoulder-width apart with fingers spread wide for stability", "Lower your knees to the ground and cross your ankles behind you", "Create a straight line from your knees through your hips to the top of your head", "Lower your chest toward the floor by bending your elbows at a 45-degree angle from your body", "Push through your palms to return to the starting position", "Maintain control throughout both the lowering and pushing phases"]', '["Positionne tes mains au sol, écartées à la largeur des épaules avec les doigts bien écartés pour plus de stabilité", "Abaisse tes genoux au sol et croise tes chevilles derrière toi", "Crée une ligne droite de tes genoux à tes hanches en passant par le haut de ta tête", "Abaisse ta poitrine vers le sol en pliant les coudes à un angle de 45 degrés par rapport à ton corps", "Pousse avec tes paumes pour revenir à la position de départ", "Garde le contrôle durant toutes les phases de descente et de poussée"]', '["Ressens bien tes muscles, engage ton gainage pour éviter que tes hanches ne s''affaissent", "Adopte un tempo contrôlé plutôt que rapide pour maximiser l''engagement musculaire", "Positionne tes mains directement sous tes épaules afin d''optimiser la répartition de la force", "Évite de trop écarter les coudes pour prévenir des tensions au niveau des épaules", "Progresse progressivement en augmentant les répétitions avant de tenter des pompes classiques"]', '["Keep your core engaged throughout the entire movement to prevent your hips from sagging", "Focus on a controlled tempo rather than speed to maximize muscle engagement", "Position your hands directly under your shoulders to optimize force distribution", "Avoid flaring your elbows too wide as this can strain the shoulder joints", "Progress gradually by increasing repetitions before attempting standard push-ups"]', '9b0e714f-6b42-40d9-941c-71bca4da5eef', 'knee-pseudo-pushups', NULL, NULL);
INSERT INTO public.exercises VALUES ('4dc9d990-401a-43df-8c18-05a1ee77468d', 'Développé Couché Prise Serrée avec Haltères', NULL, 'خدمة الصدر بالأثقال', 'Close Grip Dumbbell Press', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/close-grip-dumbbell-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/close-grip-dumbbell-press.jpg', NULL, '["Garde tes coudes plus près de ton corps par rapport à un développé classique pour solliciter les triceps et la partie interne de la poitrine", "Maintiens une tension constante en gardant les haltères proches l''un de l''autre durant tout le mouvement", "Utilise un tempo contrôlé avec une phase de descente de 2 à 3 secondes pour une activation musculaire optimale", "Commence avec un poids plus léger que pour ton développé habituel car cette variante est plus difficile", "Évite de laisser les haltères s''écarter durant le mouvement pour garder une bonne forme"]', '["Ne pas engager le tronc, ce qui peut entraîner des blessures", "Abaisser trop rapidement les haltères, ce qui réduit l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "close grip dumbbell press"]', true, '2026-04-03 12:24:56.083647+00', '2026-04-03 12:24:56.083647+00', 'Position de départ : Allonge-toi sur un banc plat, un haltère dans chaque main, paumes face à face. Exécution : Pousse les haltères depuis ta poitrine jusqu''à ce que tes bras soient complètement tendus, puis redescends lentement à la position de départ.', '["Ne pas engager le tronc, ce qui peut entraîner des blessures", "Abaisser trop rapidement les haltères, ce qui réduit l''efficacité de l''exercice"]', true, '["Lie flat on a bench with feet firmly planted on the floor", "Hold dumbbells with a neutral grip, positioning them close together above your chest with arms fully extended", "Keep your core engaged and maintain a slight arch in your lower back", "Lower the dumbbells slowly toward the center of your chest, keeping elbows tucked close to your sides", "Press the dumbbells back up to starting position following the same path", "Maintain control throughout the entire range of motion"]', '["Allonge-toi sur le banc avec les pieds bien ancrés au sol", "Tiens les haltères avec une prise neutre, les positionnant proches l''un de l''autre au-dessus de ta poitrine avec les bras tendus", "Engage ton tronc et maintiens une légère cambrure dans le bas du dos", "Abaisse les haltères lentement vers le centre de ta poitrine, en gardant les coudes près de ton corps", "Presse les haltères vers la position de départ en suivant le même chemin", "Garde le contrôle tout au long du mouvement"]', '["Garde tes coudes plus près de ton corps par rapport à un développé classique pour solliciter les triceps et la partie interne de la poitrine", "Maintiens une tension constante en gardant les haltères proches l''un de l''autre durant tout le mouvement", "Utilise un tempo contrôlé avec une phase de descente de 2 à 3 secondes pour une activation musculaire optimale", "Commence avec un poids plus léger que pour ton développé habituel car cette variante est plus difficile", "Évite de laisser les haltères s''écarter durant le mouvement pour garder une bonne forme"]', '["Keep elbows closer to your body compared to regular dumbbell press to emphasize triceps and inner chest", "Maintain constant tension by keeping the dumbbells close together throughout the movement", "Use a controlled tempo with a 2-3 second lowering phase for optimal muscle activation", "Start with lighter weight than your regular dumbbell press as this variation is more challenging", "Avoid letting the dumbbells drift apart during the movement to maintain proper form"]', '4668a912-ef55-4b3e-8d9c-53359d6aba29', 'close-grip-dumbbell-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('9dc3b05e-9ac5-425f-a344-68e1e04c4605', 'Curls de maître avec haltère', NULL, NULL, 'Dumbbell waiter curls', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/dumbbell-waiter-curls.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-waiter-curls.jpg', NULL, '["Gardez l''haltère en position verticale pour assurer une bonne prise et sécurité", "Concentrez-vous sur un mouvement contrôlé plutôt que sur la rapidité pour maximiser l''engagement musculaire", "Évitez de balancer ou d''utiliser l''élan - le mouvement doit provenir uniquement de vos biceps", "Maintenez vos poignets droits et une prise sécurisée pour éviter que l''haltère ne glisse", "Adoptez une bonne posture avec les épaules en arrière et le cœur serré durant tout l''exercice"]', '["Utiliser trop de poids et compromettre la forme", "Ne pas garder les coudes coller aux flancs pendant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "dumbbell waiter curls"]', true, '2026-04-03 12:24:56.642084+00', '2026-04-03 12:24:56.642084+00', 'Position de départ : Tenez-vous droit, un haltère à la verticale, les deux mains sous le poids supérieur, bras tendus devant vous. Exécution : Fléchissez vos biceps pour soulever l''haltère, en gardant les coudes stationnaires, puis redescendez lentement à la position de départ.', '["Utiliser trop de poids et compromettre la forme", "Ne pas garder les coudes coller aux flancs pendant le mouvement"]', true, '["Stand with feet shoulder-width apart and core engaged for stability", "Grip the dumbbell with both hands under the top weight plate, palms facing up", "Keep your elbows close to your sides and stationary throughout the movement", "Curl the weight up by contracting your biceps until your forearms are vertical", "Slowly lower the dumbbell back to the starting position with control", "Maintain the vertical position of the dumbbell throughout the entire movement"]', '["Positionnez-vous avec les pieds écartés à la largeur des épaules et le cœur engagé pour la stabilité", "Prenez l''haltère avec les deux mains sous le poids supérieur, paumes vers le haut", "Gardez vos coudes près des côtés et immobiles pendant le mouvement", "Soulevez le poids en contractant vos biceps jusqu''à ce que vos avant-bras soient verticaux", "Redescendez lentement l''haltère à la position de départ avec contrôle", "Maintenez la position verticale de l''haltère tout au long de l''exercice"]', '["Gardez l''haltère en position verticale pour assurer une bonne prise et sécurité", "Concentrez-vous sur un mouvement contrôlé plutôt que sur la rapidité pour maximiser l''engagement musculaire", "Évitez de balancer ou d''utiliser l''élan - le mouvement doit provenir uniquement de vos biceps", "Maintenez vos poignets droits et une prise sécurisée pour éviter que l''haltère ne glisse", "Adoptez une bonne posture avec les épaules en arrière et le cœur serré durant tout l''exercice"]', '["Keep the dumbbell in a vertical position at all times to maintain proper grip and safety", "Focus on controlled movement rather than speed to maximize muscle engagement", "Avoid swinging or using momentum - the movement should come from your biceps only", "Keep your wrists straight and grip secure to prevent the dumbbell from slipping", "Maintain good posture with shoulders back and core tight throughout the exercise"]', '3175c898-09fe-4d02-82c2-de2a3834fdd4', 'dumbbell-waiter-curls', NULL, NULL);
INSERT INTO public.exercises VALUES ('96e9ff70-6242-4c34-9ef9-6431d53ba25d', 'Dive Bombers', NULL, 'Dive Bombers', 'Dive bombers', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/dive-bombers.mp4', NULL, NULL, NULL, '/videos/thumbnails/dive-bombers.jpg', NULL, '["Engage ton core tout au long de l''exercice pour protéger ton bas du dos.", "Mouvement lent et contrôlé, surtout au début pour éviter les blessures.", "Assure-toi d''avoir une bonne mobilité et force des poignets, car l''exercice sollicite cette zone.", "Concentre-toi sur la fluidité de la transition entre les positions, évite de te précipiter.", "Arrête immédiatement en cas de douleur au bas du dos et envisages de modifier l''amplitude."]', '["Ne pas engager le core, ce qui peut entraîner des douleurs lombaires.", "Se précipiter dans le mouvement au lieu de le faire de manière contrôlée."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "dive bombers"]', true, '2026-04-03 12:24:56.337902+00', '2026-04-03 12:24:56.337902+00', 'Prends un départ en position chien tête en bas, mains et pieds écartés à la largeur des épaules et des hanches. Plonge vers l’avant et vers le bas en un mouvement fluide, passe par une position de pompes basses, puis lève bien le torse en position cobra avant de revenir à la position initiale.', '["Ne pas engager le core, ce qui peut entraîner des douleurs lombaires.", "Se précipiter dans le mouvement au lieu de le faire de manière contrôlée."]', true, '["Start in downward dog with straight arms and legs, creating a strong inverted V-shape with your body", "Initiate the dive by shifting your weight forward and lowering your head toward the ground between your hands", "Continue the swooping motion by bringing your chest low to the ground, similar to the bottom of a push-up", "Push through your hands and arch your back to lift your chest and head up into upward dog position", "Reverse the movement by tucking your chin and pushing your hips back up to return to the starting downward dog position", "Maintain control throughout the entire fluid movement sequence"]', '["Commence en position chien tête en bas avec les bras et les jambes droits, formant un V inversé solide.", "Déplace ton poids vers l’avant en abaissant la tête entre les mains.", "Poursuis le mouvement en abaissant la poitrine vers le sol, comme dans une pompe.", "Pousse avec tes mains et fais un arc avec ton dos pour relever ton torse en position cobra.", "Inverse le mouvement en rentrant le menton et en relevant les hanches pour revenir en chien tête en bas.", "Reste en contrôle pendant tout le mouvement fluide."]', '["Engage ton core tout au long de l''exercice pour protéger ton bas du dos.", "Mouvement lent et contrôlé, surtout au début pour éviter les blessures.", "Assure-toi d''avoir une bonne mobilité et force des poignets, car l''exercice sollicite cette zone.", "Concentre-toi sur la fluidité de la transition entre les positions, évite de te précipiter.", "Arrête immédiatement en cas de douleur au bas du dos et envisages de modifier l''amplitude."]', '["Keep your core engaged throughout the entire movement to protect your lower back from hyperextension", "Move slowly and controlled, especially when learning the movement pattern to avoid injury", "Ensure adequate wrist mobility and strength before attempting, as this exercise places significant load on the wrists", "Focus on the smooth, flowing transition between positions rather than rushing through the movement", "Stop immediately if you experience any lower back pain and consider modifying the range of motion"]', 'b219f35b-9bca-4eb5-a010-e0ded6208942', 'dive-bombers', NULL, NULL);
INSERT INTO public.exercises VALUES ('50ba35fd-f04e-491f-b6a8-03d53f5ef5e7', 'Élevez votre poitrine avec les Dumbbell Flys', NULL, NULL, 'Dumbbell fly', 'Chest', '[]', 'Chest', 'Beginner', 2, '/videos/chest/dumbbell-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-fly.jpg', NULL, '["Gardez une légère flexion au niveau des coudes tout au long de l''exercice", "Ne descendez pas trop bas (risque de blessure à l''épaule)", "Le mouvement est un arc, pas une pression", "Ressentez l''étirement en bas, contractez en haut", "Contrôlez le poids à chaque répétition"]', '["Laisser les coudes trop droits", "Descendre trop bas, ce qui peut blesser les épaules"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "dumbbell fly"]', true, '2026-04-03 12:24:56.448596+00', '2026-04-03 12:24:56.448596+00', 'Position de départ : Allongez-vous sur un banc incliné avec un haltère dans chaque main, les bras tendus vers le haut. Exécution : Écartez les bras sur le côté jusqu''à ce qu''ils soient parallèles au sol, puis revenez à la position de départ.', '["Laisser les coudes trop droits", "Descendre trop bas, ce qui peut blesser les épaules"]', true, '["Lie on bench, dumbbells above chest", "Slight bend in elbows", "Lower dumbbells out to sides in arc", "Stop when you feel chest stretch", "Squeeze chest to bring dumbbells back up"]', '["Allongez-vous sur le banc, haltères au-dessus de la poitrine", "Légère flexion des coudes", "Abaissez les haltères sur les côtés en arc", "Arrêtez-vous quand vous sentez l''étirement de la poitrine", "Contractez votre poitrine pour remonter les haltères"]', '["Gardez une légère flexion au niveau des coudes tout au long de l''exercice", "Ne descendez pas trop bas (risque de blessure à l''épaule)", "Le mouvement est un arc, pas une pression", "Ressentez l''étirement en bas, contractez en haut", "Contrôlez le poids à chaque répétition"]', '["Keep slight elbow bend throughout", "Don''t go too deep (shoulder strain)", "Movement is an arc, not a press", "Feel stretch at bottom, squeeze at top", "Control the weight"]', '97f48a58-e7a9-4179-88e2-f1a16feb68ca', 'dumbbell-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('bea80ffa-2035-466f-874e-eabe755d2b39', 'Drive de genou explosif', NULL, 'درايف دي جينو إكسلوسيف', 'Explosive knee drive', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/explosive-knee-drive.mp4', NULL, NULL, NULL, '/videos/thumbnails/explosive-knee-drive.jpg', NULL, '["Garde ton ventre bien serré tout au long du mouvement pour maintenir l''équilibre et la bonne posture", "Concentre-toi sur la puissance explosive plutôt que la vitesse - chaque drive de genou doit être effectué avec un maximum d''effort", "Atterris doucement sur la plante de ton pied au sol pour réduire l''impact et garder le contrôle", "Fais pomper tes bras en opposition pour créer de l''élan et améliorer ta coordination", "Commence par des séries plus courtes et augmente progressivement les répétitions au fur et à mesure que ta condition physique et ta force des jambes s''améliorent"]', '["Ne pas engager le core, ce qui peut nuire à l''équilibre", "Atterrir trop fort, ce qui augmente le risque de blessure"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "explosive knee drive"]', true, '2026-04-03 12:24:56.674578+00', '2026-04-03 12:24:56.674578+00', 'Position de départ : Tiens-toi debout, les pieds à la largeur des hanches, bras le long du corps, avec un pied légèrement en arrière dans une position décalée. Exécution : Tire explosivement le genou arrière vers ta poitrine tout en pompes tes bras, puis reviens à la position de départ et répète avant de changer de jambe.', '["Ne pas engager le core, ce qui peut nuire à l''équilibre", "Atterrir trop fort, ce qui augmente le risque de blessure"]', true, '["Begin in a staggered stance with your right foot forward and left foot back, maintaining good posture with core engaged", "Explosively drive your left knee up toward your chest as high as possible while pumping your right arm forward and left arm back", "Land softly on the ball of your standing foot while controlling the descent of the driving leg", "Immediately repeat the explosive knee drive for the prescribed repetitions on one side", "Switch leg positions and perform the same number of repetitions with the opposite knee driving up", "Maintain a steady rhythm while focusing on maximum height and speed with each knee drive"]', '["Commence en position décalée, pied droit devant, pied gauche en arrière, posture droite avec les abdos engagés", "Envoie explosivement ton genou gauche vers ta poitrine tout en pompes ton bras droit en avant et ton bras gauche en arrière", "Atterris doucement sur la plante de ton pied au sol tout en contrôlant la redescente de ta jambe", "Répète immédiatement le drive de genou explosif pour le nombre de répétitions prescrites sur un côté", "Change de jambe et réalise le même nombre de répétitions avec le genou opposé", "Maintiens un rythme régulier tout en te concentrant sur la hauteur et la vitesse maximales de chaque drive de genou"]', '["Garde ton ventre bien serré tout au long du mouvement pour maintenir l''équilibre et la bonne posture", "Concentre-toi sur la puissance explosive plutôt que la vitesse - chaque drive de genou doit être effectué avec un maximum d''effort", "Atterris doucement sur la plante de ton pied au sol pour réduire l''impact et garder le contrôle", "Fais pomper tes bras en opposition pour créer de l''élan et améliorer ta coordination", "Commence par des séries plus courtes et augmente progressivement les répétitions au fur et à mesure que ta condition physique et ta force des jambes s''améliorent"]', '["Keep your core tight throughout the movement to maintain balance and proper posture", "Focus on explosive power rather than speed - each knee drive should be performed with maximum effort", "Land softly on the ball of your standing foot to reduce impact and maintain control", "Pump your arms in opposition to create momentum and improve coordination", "Start with shorter sets and gradually increase repetitions as your cardiovascular fitness and leg strength improve"]', '4c22f102-513b-4fe4-a271-389c006fbb9f', 'explosive-knee-drive', NULL, NULL);
INSERT INTO public.exercises VALUES ('bb143578-e07a-4a0b-9ea8-44026f90b852', 'Pompes explosif latérales', NULL, NULL, 'Explosive side to side push up', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/explosive-side-to-side-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/explosive-side-to-side-push-up.jpg', NULL, '["Engage ton corps en gardant les abdos contractés pour maintenir l''alignement", "Atterris en douceur pour réduire l''impact sur poignets et épaules", "Commence par de petits déplacements latéraux, puis augmente l''amplitude à mesure que tu gagnes en force", "Assure-toi d''avoir assez d''espace des deux côtés avant de commencer l''exercice", "Concentre-toi sur la puissance explosive en phase de poussée tout en gardant le contrôle lors de l''atterrissage"]', '["Ne pas engager les abdominaux, ce qui peut entraîner une mauvaise posture", "Atterrir trop brusquement, ce qui augmente le risque de blessure"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "explosive side to side push up"]', true, '2026-04-03 12:24:56.685014+00', '2026-04-03 12:24:56.685014+00', 'Position de départ : mets-toi en position de pompe standard, mains plus larges que les épaules, corps bien droit de la tête aux talons. Exécution : pousse explosivement depuis le bas en déplaçant ton corps sur le côté, atterris en douceur, puis bascule immédiatement de l''autre côté à chaque répétition.', '["Ne pas engager les abdominaux, ce qui peut entraîner une mauvaise posture", "Atterrir trop brusquement, ce qui augmente le risque de blessure"]', true, '["Start in a wide push-up position with hands placed wider than shoulder-width apart", "Lower your chest toward the ground while maintaining a straight body line", "Explosively push up from the bottom position, generating enough force to shift your body to one side", "Land softly with control, absorbing the impact through your arms and core", "Immediately transition into the next push-up, shifting to the opposite side", "Maintain proper push-up form throughout the lateral movement"]', '["Commence en position de pompe large, mains plus larges que les épaules", "Abaisse ta poitrine vers le sol tout en gardant le corps droit", "Pousse explosivement depuis le bas pour déplacer ton corps sur un côté", "Atterris en douceur pour contrôler l''impact ce qui protège tes bras et tes abdos", "Bascule immédiatement vers le côté opposé pour la répétition suivante", "Veille à garder la bonne forme de pompe tout au long du mouvement latéral"]', '["Engage ton corps en gardant les abdos contractés pour maintenir l''alignement", "Atterris en douceur pour réduire l''impact sur poignets et épaules", "Commence par de petits déplacements latéraux, puis augmente l''amplitude à mesure que tu gagnes en force", "Assure-toi d''avoir assez d''espace des deux côtés avant de commencer l''exercice", "Concentre-toi sur la puissance explosive en phase de poussée tout en gardant le contrôle lors de l''atterrissage"]', '["Keep your core engaged throughout the entire movement to maintain body alignment", "Land softly to reduce impact on wrists and shoulders", "Start with smaller lateral movements and progress to larger shifts as you build strength", "Ensure you have adequate space on both sides before beginning the exercise", "Focus on explosive power during the push phase while maintaining control during the landing"]', 'd9df1e94-1051-407d-9c34-87720d1557a9', 'explosive-side-to-side-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('d08c0ffa-d155-4999-9ca4-4b0e44a999d9', 'Pompes pike', NULL, NULL, 'Pike push ups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/pike-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/pike-push-ups.jpg', NULL, '["Cet exercice cible principalement les deltoïdes antérieurs et le haut de la poitrine, pas l''ensemble de la poitrine comme les pompes classiques", "Commence avec les pieds sur une surface plus basse et augmente progressivement la hauteur au fur et à mesure que tu renforces ta force et ta mobilité", "Maintiens une bonne stabilité des épaules en les tirant vers le bas et vers l''arrière pendant tout le mouvement", "Arrête immédiatement si tu ressens des douleurs au cou ou des vertiges en position inversée", "Progresse lentement, car cet exercice exerce une pression importante sur les épaules et nécessite une bonne flexibilité des épaules"]', '["Ne pas garder le core engagé", "Laisser les hanches descendre pendant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "pike push ups"]', true, '2026-04-03 12:24:58.267781+00', '2026-04-03 12:24:58.267781+00', 'Position de départ : Commence en position de chien tête en bas, avec les mains écartées à la largeur des épaules et les pieds surélevés sur un banc ou une boîte, formant un V inversé. Exécution : Abaisse ta tête vers le sol en fléchissant les coudes, puis remonte jusqu''à la position de départ en mettant l''accent sur les épaules et le haut de la poitrine.', '["Ne pas garder le core engagé", "Laisser les hanches descendre pendant le mouvement"]', true, '["Position your hands shoulder-width apart on the floor with fingers spread wide for stability", "Elevate your feet on a sturdy bench or box, walking your hands closer to create a steep downward angle", "Keep your core engaged and maintain a straight line from your hips to your head throughout the movement", "Lower your head toward the floor by bending your elbows until your head nearly touches the ground", "Press through your palms to return to the starting position, maintaining control throughout the entire range of motion", "Keep your legs straight and avoid sagging at the hips during the exercise"]', '["Place tes mains à la largeur des épaules sur le sol, les doigts bien écartés pour plus de stabilité", "Surélève tes pieds sur un banc ou une boîte solide, en avançant tes mains pour créer un angle raide vers le bas", "Engage ton core et garde une ligne droite des hanches à la tête pendant tout le mouvement", "Abaisse ta tête vers le sol en fléchissant les coudes jusqu''à ce qu''elle approche du sol", "Pousse avec tes paumes pour revenir à la position de départ, en gardant le contrôle sur toute l''amplitude du mouvement", "Garde les jambes tendues et évite de laisser tomber les hanches pendant l''exercice"]', '["Cet exercice cible principalement les deltoïdes antérieurs et le haut de la poitrine, pas l''ensemble de la poitrine comme les pompes classiques", "Commence avec les pieds sur une surface plus basse et augmente progressivement la hauteur au fur et à mesure que tu renforces ta force et ta mobilité", "Maintiens une bonne stabilité des épaules en les tirant vers le bas et vers l''arrière pendant tout le mouvement", "Arrête immédiatement si tu ressens des douleurs au cou ou des vertiges en position inversée", "Progresse lentement, car cet exercice exerce une pression importante sur les épaules et nécessite une bonne flexibilité des épaules"]', '["This exercise primarily targets the anterior deltoids and upper chest rather than the full chest like traditional push-ups", "Start with feet on a lower surface and gradually increase height as you build strength and mobility", "Maintain proper shoulder blade stability by keeping them pulled down and back throughout the movement", "Stop immediately if you experience any neck pain or dizziness from the inverted position", "Progress slowly as this exercise places significant load on the shoulders and requires good shoulder flexibility"]', '3882e700-1ad7-4b71-932a-6ee8983e50b2', 'pike-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('2f21069a-53ce-4669-8c66-be28203e7f39', 'Machine à adduction de la hanche', NULL, 'جهاز إدخال الفخذ', 'Hip Adduction Machine', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/hip-adduction-machine.mp4', NULL, NULL, NULL, '/videos/thumbnails/hip-adduction-machine.jpg', NULL, '["Gardez le dos bien appuyé contre le coussin pendant tout le mouvement pour maintenir un alignement spinal correct", "Évitez les mouvements d''élan ou de rebond - concentrez-vous sur des mouvements lents et contrôlés pour maximiser l''engagement musculaire", "Ne commencez pas avec une amplitude trop large si vous ressentez un étirement excessif dans l''intérieur des cuisses", "Choisissez un poids qui vous permet de compléter toute la gamme de mouvement sans compensation", "Expirez pendant la phase de contraction et inspirez pendant la phase de retour."]', '["Ne pas ajuster la hauteur du siège correctement", "Utiliser trop de poids et compromettre la forme."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "hip adduction machine"]', true, '2026-04-03 12:24:57.158687+00', '2026-04-03 12:24:57.158687+00', 'Position de départ : Asseyez-vous sur la machine à adduction de la hanche, les jambes légèrement écartées, les genoux reposant sur les coussins. Exécution : Rapprochez vos jambes contre la résistance, puis revenez lentement à la position de départ.', '["Ne pas ajuster la hauteur du siège correctement", "Utiliser trop de poids et compromettre la forme."]', true, '["Adjust the seat height so your thighs are parallel to the floor when seated", "Set the leg pads to a comfortable starting width that provides a gentle stretch in your inner thighs", "Sit with your back firmly pressed against the backrest and grip the side handles for stability", "Engage your core and squeeze your inner thighs to bring your legs together in a smooth, controlled motion", "Pause briefly at the peak contraction when your legs are together", "Slowly return to the starting position, resisting the weight on the way back"]', '["Ajustez la hauteur du siège de manière à ce que vos cuisses soient parallèles au sol lorsque vous êtes assis", "Réglez les coussins de jambes à une largeur confortable pour sentir un léger étirement dans l''intérieur des cuisses", "Asseyez-vous en pressant fermement votre dos contre le dossier et saisissez les poignées latérales pour plus de stabilité", "Contractez votre sangle abdominale et serrez vos cuisses internes pour rapprocher vos jambes de manière fluide et contrôlée", "Faites une pause briève lorsque vos jambes sont ensemble", "Revenez lentement à la position de départ en résistant au poids pendant le retour."]', '["Gardez le dos bien appuyé contre le coussin pendant tout le mouvement pour maintenir un alignement spinal correct", "Évitez les mouvements d''élan ou de rebond - concentrez-vous sur des mouvements lents et contrôlés pour maximiser l''engagement musculaire", "Ne commencez pas avec une amplitude trop large si vous ressentez un étirement excessif dans l''intérieur des cuisses", "Choisissez un poids qui vous permet de compléter toute la gamme de mouvement sans compensation", "Expirez pendant la phase de contraction et inspirez pendant la phase de retour."]', '["Keep your back pressed against the pad throughout the entire movement to maintain proper spinal alignment", "Avoid using momentum or bouncing motions - focus on slow, controlled movements to maximize muscle engagement", "Don''t start with too wide of a range of motion if you feel excessive stretching in your inner thighs", "Select a weight that allows you to complete the full range of motion without compensation patterns", "Breathe out during the squeezing phase and breathe in during the return phase"]', 'af606d87-c83f-46cd-b72f-e554708eb94e', 'hip-adduction-machine', NULL, NULL);
INSERT INTO public.exercises VALUES ('30f86afc-167c-4b0d-8893-45a619955577', 'Squat Presse Pieds Serrés', NULL, NULL, 'Leg Press Close Stance', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/leg-press-close-stance.mp4', NULL, NULL, NULL, '/videos/thumbnails/leg-press-close-stance.jpg', NULL, '["Gardez les genoux alignés avec les orteils durant tout le mouvement pour éviter qu''ils ne s''effondrent vers l''intérieur", "Maintenez une tension constante en ne verrouillant pas complètement vos genoux au sommet du mouvement", "Contrôlez la phase excentrique en abaissant doucement le poids au lieu de le laisser tomber", "Concentrez-vous sur la poussée à partir des talons plutôt que des orteils pour maximiser l''activation des quadriceps", "Ne laissez jamais les genoux s''effondrer vers l''intérieur, cela pourrait entraîner des blessures et réduire l''efficacité de l''exercice"]', '["Ne pas ajuster le siège correctement", "Ne pas contrôler le poids lors de la descente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "leg press close stance"]', true, '2026-04-03 12:24:57.55992+00', '2026-04-03 12:24:57.55992+00', 'Position de départ : Asseyez-vous sur la presse à jambes horizontale, les pieds proches l''un de l''autre sur la plateforme et les genoux fléchis. Exécution : Poussez la plateforme vers l''avant en étendant entièrement vos jambes, puis abaissez lentement jusqu''à la position de départ.', '["Ne pas ajuster le siège correctement", "Ne pas contrôler le poids lors de la descente"]', true, '["Adjust the seat and back pad to ensure proper alignment with knees tracking over toes", "Place feet close together on the footplate with toes pointing slightly outward", "Grip the side handles firmly and maintain a neutral spine against the back pad", "Release the safety handles and slowly lower the weight until knees reach approximately 90 degrees", "Press through your heels to extend legs fully without locking knees completely", "Re-engage safety handles before exiting the machine"]', '["Ajustez le siège et le dossier pour aligner correctement vos genoux au-dessus de vos orteils", "Placez vos pieds proches l''un de l''autre sur la plateforme avec les orteils légèrement déviés vers l''extérieur", "Tenez fermement les poignées latérales et gardez le dos neutre contre le dossier", "Relâchez les poignées de sécurité et abaissez lentement le poids jusqu''à ce que vos genoux atteignent environ 90 degrés", "Poussez avec vos talons pour étendre complètement vos jambes sans verrouiller les genoux", "Réengagez les poignées de sécurité avant de quitter la machine"]', '["Gardez les genoux alignés avec les orteils durant tout le mouvement pour éviter qu''ils ne s''effondrent vers l''intérieur", "Maintenez une tension constante en ne verrouillant pas complètement vos genoux au sommet du mouvement", "Contrôlez la phase excentrique en abaissant doucement le poids au lieu de le laisser tomber", "Concentrez-vous sur la poussée à partir des talons plutôt que des orteils pour maximiser l''activation des quadriceps", "Ne laissez jamais les genoux s''effondrer vers l''intérieur, cela pourrait entraîner des blessures et réduire l''efficacité de l''exercice"]', '["Keep knees aligned with toes throughout the entire movement to prevent inward collapse", "Maintain constant tension by not fully locking out knees at the top of the movement", "Control the eccentric phase by lowering weight slowly rather than letting it drop", "Focus on pressing through heels rather than toes to maximize quadriceps activation", "Never allow knees to cave inward as this can cause injury and reduces exercise effectiveness"]', 'bbc9368f-e232-4081-bd5c-235c928eccb3', 'leg-press-close-stance', NULL, NULL);
INSERT INTO public.exercises VALUES ('657ae41e-8ff1-4541-8e8a-3c5862f2ee1d', 'Écartés inclinés avec câbles', NULL, NULL, 'Incline Cable Fly', 'Chest', '[]', 'Chest', 'Intermediate', 4, '/videos/chest/incline-cable-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-cable-fly.jpg', NULL, '["Maintiens une légère flexion dans les coudes tout au long du mouvement pour protéger les articulations des épaules.", "Concentre-toi sur l''étirement de tes muscles pectoraux en position basse sans descendre trop loin.", "Garde la tension dans les câbles sur toute l''amplitude du mouvement et évite que les poids ne touchent la pile.", "Choisis un poids qui te permet de contrôler le mouvement dans les deux directions sans utiliser d''élan.", "Engage ton ventre et évite de cambrer excessivement le dos pendant l''exercice."]', '["Laisser les poids toucher la pile, ce qui interrompt la tension musculaire.", "Oublier de maintenir la flexion des coudes, ce qui peut accroître le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "cable", "incline cable fly"]', true, '2026-04-03 12:24:57.251243+00', '2026-04-03 12:24:57.251243+00', 'Positionne-toi sur un banc incliné face à une poulie à câbles réglée à hauteur de poitrine. Ouvre les bras sur les côtés avec une légère flexion des coudes, puis reviens à la position de départ.', '["Laisser les poids toucher la pile, ce qui interrompt la tension musculaire.", "Oublier de maintenir la flexion des coudes, ce qui peut accroître le risque de blessure."]', true, '["Position incline bench at 30-45 degree angle between low cable pulleys and select appropriate weight", "Lie back on bench and grasp cable handles with palms facing up, arms extended to sides with slight elbow bend", "Plant feet firmly on floor and maintain neutral spine against the bench pad", "Bring handles together in smooth arc motion above upper chest while maintaining elbow position", "Squeeze chest muscles at the top for one second, then slowly lower handles back to starting position", "Complete all repetitions with controlled tempo before releasing handles"]', '["Installe le banc incliné à un angle de 30 à 45 degrés entre les poulies de basse tension et choisis un poids adapté.", "Allonge-toi sur le banc et saisis les poignées des câbles avec les paumes vers le haut, bras étendus sur les côtés avec une légère flexion des coudes.", "Pose fermement tes pieds au sol et garde la colonne vertébrale droite contre le rembourrage du banc.", "Ramène les poignées vers le haut de la poitrine en effectuant un mouvement fluide d''arc tout en maintenant la position des coudes.", "Contracte les muscles de la poitrine au sommet pendant une seconde, puis abaisse lentement les poignées à la position de départ.", "Effectue toutes les répétitions avec un rythme contrôlé avant de relâcher les poignées."]', '["Maintiens une légère flexion dans les coudes tout au long du mouvement pour protéger les articulations des épaules.", "Concentre-toi sur l''étirement de tes muscles pectoraux en position basse sans descendre trop loin.", "Garde la tension dans les câbles sur toute l''amplitude du mouvement et évite que les poids ne touchent la pile.", "Choisis un poids qui te permet de contrôler le mouvement dans les deux directions sans utiliser d''élan.", "Engage ton ventre et évite de cambrer excessivement le dos pendant l''exercice."]', '["Keep a slight bend in your elbows throughout the entire movement to protect shoulder joints", "Focus on feeling the stretch in your chest muscles at the bottom position without going too deep", "Maintain tension in the cables throughout the full range of motion and avoid letting weights touch the stack", "Use a weight that allows you to control the movement in both directions without momentum", "Keep your core engaged and avoid arching your back excessively during the exercise"]', '4a608293-5863-4517-b03d-a46398066e32', 'incline-cable-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('39e5303a-7eb3-4335-9534-257e98049734', 'Écartés Câble Couché', NULL, NULL, 'Flat Cable Fly', 'Chest', '[]', 'Chest', 'Beginner', 4, '/videos/chest/flat-cable-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/flat-cable-fly.jpg', NULL, '["Garde une légère flexion dans les coudes tout au long du mouvement pour protéger tes articulations", "Contrôle le poids lors des phases de descente et de montée - évite que les câbles ne reviennent à la vitesse de la lumière", "Concentre-toi sur la contraction de tes muscles pectoraux en ramènant les poignées ensemble en haut", "Ne descends pas le poids trop bas - arrête-toi quand tu sens un étirement confortable dans ta poitrine", "Maintiens une bonne position des omoplates en les tirant vers l''arrière contre le banc"]', '["Laisser les coudes se verrouiller à l''extension", "Ne pas contrôler le mouvement et laisser les câbles revenir trop rapidement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "cable", "flat cable fly"]', true, '2026-04-03 12:24:56.741904+00', '2026-04-03 12:24:56.741904+00', 'Position de départ : Allonge-toi sur un banc entre deux tours de câbles, en tenant les poignées de câble avec les bras tendus au-dessus de ta poitrine. Exécution : Abaisse les poignées en arc large sur les côtés jusqu''à sentir un étirement dans ta poitrine, puis ramène-les ensemble au-dessus de ta poitrine dans un mouvement contrôlé.', '["Laisser les coudes se verrouiller à l''extension", "Ne pas contrôler le mouvement et laisser les câbles revenir trop rapidement"]', true, '["Position the bench centered between two cable towers and set the cables at chest height", "Lie flat on the bench and grasp both cable handles with a neutral grip", "Start with arms extended above your chest, maintaining a slight bend in your elbows", "Lower the handles out to your sides in a wide arc, keeping the elbow bend constant", "Stop when you feel a good stretch in your chest muscles", "Bring the handles back together above your chest using your chest muscles"]', '["Centre le banc entre les deux tours de câbles et règle les câbles à hauteur de poitrine", "Allonge-toi sur le banc et saisis les poignées de câble avec une prise neutre", "Commence avec les bras tendus au-dessus de ta poitrine, en gardant une légère flexion dans les coudes", "Abaisse les poignées sur les côtés en arc large, en maintenant la flexion du coude constante", "Arrête-toi quand tu sens un bon étirement dans tes muscles pectoraux", "Ramène les poignées ensemble au-dessus de ta poitrine en utilisant tes muscles pectoraux"]', '["Garde une légère flexion dans les coudes tout au long du mouvement pour protéger tes articulations", "Contrôle le poids lors des phases de descente et de montée - évite que les câbles ne reviennent à la vitesse de la lumière", "Concentre-toi sur la contraction de tes muscles pectoraux en ramènant les poignées ensemble en haut", "Ne descends pas le poids trop bas - arrête-toi quand tu sens un étirement confortable dans ta poitrine", "Maintiens une bonne position des omoplates en les tirant vers l''arrière contre le banc"]', '["Keep a slight bend in your elbows throughout the entire movement to protect your joints", "Control the weight on both the lowering and lifting phases - avoid letting the cables snap back", "Focus on squeezing your chest muscles as you bring the handles together at the top", "Don''t lower the weight too far - stop when you feel a comfortable stretch in your chest", "Maintain proper shoulder blade positioning by keeping them pulled back against the bench"]', '3b45e42a-963f-4b79-ae1d-b1b5e8eb9add', 'flat-cable-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('a1320380-2124-4319-92f9-42d807c4ef6b', 'Pose du bûcheron (gauche)', NULL, NULL, 'Fire log pose (left)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/fire-log-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/fire-log-pose-left.jpg', NULL, '["Garde les pieds fléchis tout au long de la pose pour éviter la tension au niveau des genoux", "Si tes hanches sont serrées, assieds-toi sur un coussin ou une couverture pliée pour élever ton bassin", "Ne force jamais tes genoux vers le bas - laisse la gravité et le temps créer l''ouverture", "Stoppe immédiatement si tu ressens une douleur aiguë aux genoux ou aux hanches", "Concentre-toi sur le maintien d''une position droite plutôt que de te pencher en avant pour garder un bon alignement"]', '["Oublier de fléchir les pieds, ce qui peut engendrer des douleurs aux genoux", "Se pencher trop en avant au lieu de garder la colonne droite"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "fire log pose (left)"]', true, '2026-04-03 12:24:56.732247+00', '2026-04-03 12:24:56.732247+00', 'Position de départ : Assieds-toi sur le mat, les jambes fléchies et parallèles, formant une forme de ''bûcheron'' avec tes tibias empilés. Exécution : Maintiens cette position d''ouverture de hanches statique, le torse droit, et respire profondément.', '["Oublier de fléchir les pieds, ce qui peut engendrer des douleurs aux genoux", "Se pencher trop en avant au lieu de garder la colonne droite"]', true, '["Sit on your mat with your left leg in front, knee bent at 90 degrees with the shin parallel to the front edge of your mat", "Place your right leg on top, stacking the right shin directly over the left shin with both knees bent", "Keep both feet flexed to protect your knee joints", "Sit tall with your spine straight and hands resting on your shins or the floor", "Hold the position for 30-60 seconds while breathing deeply", "To release, carefully lift the top leg and extend both legs forward"]', '["Assieds-toi sur ton tapis avec ta jambe gauche devant, genou fléchi à 90 degrés, le tibia parallèle au bord avant de ton tapis", "Place ta jambe droite au-dessus, empilant le tibia droit directement sur le tibia gauche avec les deux genoux fléchis", "Garde les pieds fléchis pour protéger tes articulations", "Reste droit avec ta colonne, mains reposant sur tes tibias ou au sol", "Maintiens la position pendant 30 à 60 secondes en respirant profondément", "Pour relâcher, soulève doucement la jambe du dessus et étends les deux jambes vers l''avant"]', '["Garde les pieds fléchis tout au long de la pose pour éviter la tension au niveau des genoux", "Si tes hanches sont serrées, assieds-toi sur un coussin ou une couverture pliée pour élever ton bassin", "Ne force jamais tes genoux vers le bas - laisse la gravité et le temps créer l''ouverture", "Stoppe immédiatement si tu ressens une douleur aiguë aux genoux ou aux hanches", "Concentre-toi sur le maintien d''une position droite plutôt que de te pencher en avant pour garder un bon alignement"]', '["Keep both feet flexed throughout the pose to protect your knees from strain", "If your hips are tight, sit on a bolster or folded blanket to elevate your pelvis", "Never force your knees down - let gravity and time create the opening", "Stop immediately if you feel any sharp pain in your knees or hips", "Focus on sitting tall rather than folding forward to maintain proper alignment"]', '623b2443-bc73-4c61-986c-412545c33aed', 'fire-log-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('adb3ab21-9cfc-4fbc-bbb8-e6053f3a3e78', 'Fente avant avec flexion latérale', NULL, NULL, 'Forward lunge with lateral flexion', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/forward-lunge-with-lateral-flexion.mp4', NULL, NULL, NULL, '/videos/thumbnails/forward-lunge-with-lateral-flexion.jpg', NULL, '["Gardez votre genou avant aligné avec votre cheville sans qu''il s''affaisse vers l''intérieur", "Contrôlez le mouvement de flexion latérale pour éviter un étirement excessif", "Engagez vos abdominaux tout au long du mouvement pour protéger votre dos", "Assurez-vous que votre jambe arrière reste droite et forte pendant la phase de fente", "Commencez par de petits mouvements latéraux et augmentez progressivement l''amplitude au fur et à mesure que votre flexibilité s''améliore"]', '["Laisser le genou avant dépasser les orteils", "Ne pas maintenir l''équilibre lorsque l''on incline le torse"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "forward lunge with lateral flexion"]', true, '2026-04-03 12:24:56.764336+00', '2026-04-03 12:24:56.764336+00', 'Position de départ: Tenez-vous droit, les pieds écartés à la largeur des hanches, les mains sur les hanches ou sur les côtés pour l''équilibre. Exécution: Faites un pas en avant en vous abaissant en fente tout en inclinant votre torse latéralement vers la jambe avant, puis revenez à la position de départ et répétez de l''autre côté.', '["Laisser le genou avant dépasser les orteils", "Ne pas maintenir l''équilibre lorsque l''on incline le torse"]', true, '["Stand with feet hip-width apart and engage your core muscles", "Step forward with your right foot approximately 2-3 feet, keeping your torso upright initially", "Lower your body by bending both knees to 90 degrees while simultaneously leaning your torso to the right side", "Keep your weight evenly distributed between both feet and maintain balance", "Push through your right heel to return to starting position while straightening your torso", "Repeat the movement stepping forward with your left foot and leaning left"]', '["Tenez-vous avec les pieds écartés à la largeur des hanches et engagez vos muscles abdominaux", "Faites un pas en avant avec votre pied droit d''environ 60 à 90 cm, en gardant votre torse droit au début", "Abaissez votre corps en pliant les deux genoux à 90 degrés tout en inclinant votre torse vers la droite", "Conservez votre poids équilibré entre les deux pieds et maintenez votre équilibre", "Poussez avec votre talon droit pour revenir à la position de départ en redressant votre torse", "Répétez le mouvement en faisant un pas en avant avec votre pied gauche et en vous penchant à gauche"]', '["Gardez votre genou avant aligné avec votre cheville sans qu''il s''affaisse vers l''intérieur", "Contrôlez le mouvement de flexion latérale pour éviter un étirement excessif", "Engagez vos abdominaux tout au long du mouvement pour protéger votre dos", "Assurez-vous que votre jambe arrière reste droite et forte pendant la phase de fente", "Commencez par de petits mouvements latéraux et augmentez progressivement l''amplitude au fur et à mesure que votre flexibilité s''améliore"]', '["Keep your front knee aligned over your ankle and avoid letting it cave inward", "Maintain control during the lateral flexion movement to avoid overstretching", "Keep your core engaged throughout the entire movement to protect your spine", "Ensure your back leg remains straight and strong during the lunge phase", "Start with small lateral movements and gradually increase range of motion as flexibility improves"]', '706ac77a-70f7-4532-a3c5-f1ce1bd2f079', 'forward-lunge-with-lateral-flexion', NULL, NULL);
INSERT INTO public.exercises VALUES ('eb1b016c-e124-461a-bda6-fc25ed9c70c3', 'Élévation de la hanche au câble', NULL, NULL, 'Cable Hip Abduction', 'Glutes', '[]', 'Glutes', 'Beginner', 4, '/videos/glutes/cable-hip-abduction.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-hip-abduction.jpg', NULL, '["Garde ton torse droit et évite de pencher loin de la machine pendant le mouvement", "Concentre-toi sur le soulèvement depuis ta hanche plutôt que de balancer ta jambe pour assurer une activation correcte des fessiers", "Contrôle la phase de descente en abaissant lentement ta jambe au lieu de laisser le câble la ramener", "Maintiens la tension dans tes fessiers tout au long du mouvement", "Commence avec une résistance légère pour maîtriser le mouvement avant d''augmenter le poids"]', '["Ne pas engager les fessiers correctement", "Pencher le torse en s''écartant de la machine"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "cable", "cable hip abduction"]', true, '2026-04-03 12:24:55.897027+00', '2026-04-03 12:24:55.897027+00', 'Position de départ : Fais face à une poulie basse avec une courroie autour de ta cheville et avance légèrement ton pied. Exécution : Écarte ta jambe vers l''extérieur tout en contractant tes fessiers, puis redescend lentement à la position de départ et répète avec l’autre jambe.', '["Ne pas engager les fessiers correctement", "Pencher le torse en s''écartant de la machine"]', true, '["Attach the ankle cuff to your outer leg and position yourself sideways to the cable machine", "Stand tall with your inner hand holding the machine for support and your feet hip-width apart", "Engage your core and maintain a straight posture throughout the movement", "Lift your outer leg straight out to the side until you feel tension in your outer glute", "Hold briefly at the top position then slowly lower your leg back to starting position", "Complete all repetitions on one side before switching to the other leg"]', '["Fixe la courroie à ta cheville externe et place-toi de côté par rapport à la machine à câbles", "Reste droit avec la main intérieure tenant la machine pour le soutien et les pieds écartés à la largeur des hanches", "Engage ton ventre et maintiens une posture droite tout au long du mouvement", "Lève ta jambe externe directement sur le côté jusqu''à sentir la tension dans ton fessier externe", "Maintiens la position en haut un instant, puis abaisse lentement ta jambe à la position de départ", "Effectue toutes les répétitions d''un côté avant de passer à l''autre jambe"]', '["Garde ton torse droit et évite de pencher loin de la machine pendant le mouvement", "Concentre-toi sur le soulèvement depuis ta hanche plutôt que de balancer ta jambe pour assurer une activation correcte des fessiers", "Contrôle la phase de descente en abaissant lentement ta jambe au lieu de laisser le câble la ramener", "Maintiens la tension dans tes fessiers tout au long du mouvement", "Commence avec une résistance légère pour maîtriser le mouvement avant d''augmenter le poids"]', '["Keep your torso upright and avoid leaning away from the machine during the movement", "Focus on lifting from your hip rather than swinging your leg to ensure proper glute activation", "Control the eccentric portion by slowly lowering your leg rather than letting the cable pull it back", "Maintain tension in your glutes throughout the entire range of motion", "Start with lighter resistance to master the movement pattern before increasing weight"]', '8503592c-a179-456b-9417-5fb5e84fad1a', 'cable-hip-abduction', NULL, NULL);
INSERT INTO public.exercises VALUES ('3ba339b1-c349-4d5e-9cb5-c38a72b9899a', 'Pompes Complètes', NULL, 'بوش أب الكامل', 'Full range push ups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/full-range-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/full-range-push-ups.jpg', NULL, '["Maintiens une bonne alignement corporel en gardant les hanches à niveau, évite de laisser tomber ou de soulever les fesses", "Concentre-toi sur l''amplitude du mouvement en allant aussi bas que possible tout en gardant une bonne forme", "Garde ton tronc engagé tout au long de l''exercice pour protéger le bas du dos et maintenir la stabilité", "Contrôle le rythme avec une descente lente et une poussée puissante pour revenir à la position de départ", "Si tu n''arrives pas à le faire avec une bonne forme, modifie en élevant tes mains sur un banc ou en le faisant sur les genoux"]', '["Ne pas maintenir une bonne alignement du corps", "Écarter les coudes trop largement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "full range push ups"]', true, '2026-04-03 12:24:56.805079+00', '2026-04-03 12:24:56.805079+00', 'Position de départ : Mets-toi en position de planche, mains un peu plus larges que la largeur des épaules, bras tendus, corps en ligne droite de la tête aux talons. Exécution : Abaisse ta poitrine vers le sol jusqu''à ce qu''elle frôle le sol, puis pousse-toi vers le haut jusqu''à la position de départ avec les bras complètement étendus.', '["Ne pas maintenir une bonne alignement du corps", "Écarter les coudes trop largement"]', true, '["Position hands flat on the floor slightly wider than shoulder-width with fingers spread for stability", "Engage your core and maintain a straight line from head to heels throughout the entire movement", "Lower your body slowly and controlled until your chest nearly touches the ground", "Keep your elbows at a 45-degree angle to your torso rather than flaring them straight out", "Push through your palms to return to starting position with full arm extension", "Breathe in on the way down and exhale as you push back up"]', '["Positionne tes mains à plat sur le sol, légèrement plus larges que la largeur des épaules, avec les doigts écartés pour plus de stabilité", "Engage ton tronc et maintiens une ligne droite de la tête aux talons pendant tout le mouvement", "Abaisse ton corps lentement et de manière contrôlée jusqu''à ce que ta poitrine frôle le sol", "Garde tes coudes à un angle de 45 degrés par rapport à ton torse au lieu de les écarter", "Pousse avec tes paumes pour revenir à la position de départ avec les bras complètement étendus", "Inspire en descendant et expire en poussant vers le haut"]', '["Maintiens une bonne alignement corporel en gardant les hanches à niveau, évite de laisser tomber ou de soulever les fesses", "Concentre-toi sur l''amplitude du mouvement en allant aussi bas que possible tout en gardant une bonne forme", "Garde ton tronc engagé tout au long de l''exercice pour protéger le bas du dos et maintenir la stabilité", "Contrôle le rythme avec une descente lente et une poussée puissante pour revenir à la position de départ", "Si tu n''arrives pas à le faire avec une bonne forme, modifie en élevant tes mains sur un banc ou en le faisant sur les genoux"]', '["Maintain proper body alignment by keeping hips level and avoiding sagging or piking", "Focus on the full range of motion by going as low as possible while maintaining good form", "Keep your core engaged throughout to protect your lower back and maintain stability", "Control the tempo with a slow descent and powerful push back to starting position", "If unable to perform with proper form, modify by elevating hands on a bench or performing on knees"]', 'fb48eccb-7f51-4de3-97f0-dc5ef75a6cee', 'full-range-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('af846d07-7949-4ebd-b75a-ee4c782a0e79', 'Élévation latérale à la poulie', NULL, NULL, 'Cable Hip Abduction', 'Glutes', '[]', 'Glutes', 'Beginner', 4, '/videos/glutes/cable-hip-abduction-86a5f361.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-hip-abduction-86a5f361.jpg', NULL, '["Maintiens ton torse stable et évite de pencher en arrière pendant le mouvement.", "Concentre-toi sur le mouvement de la hanche plutôt que de simplement déplacer le pied vers l''extérieur.", "Contrôle la phase descendante pour maximiser l''activation des fessiers.", "Garde une légère inclinaison vers l''avant pour mieux cibler le moyen fessier.", "Commence avec un poids léger pour maîtriser le mouvement avant d''augmenter la charge."]', '["Pencher le torse en arrière lors de l''élévation.", "Lâcher la tension du câble en redescendant.", "Élever la jambe trop haut et perdre le contrôle."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "cable", "cable hip abduction"]', true, '2026-04-03 12:24:55.907843+00', '2026-04-03 12:24:55.907843+00', 'Position de départ : Tiens-toi face à la poulie basse avec une sangle autour de ta cheville, le pied légèrement tourné vers l''intérieur. Exécution : Écarte ta jambe sur le côté en la maintenant droite, puis redescend lentement à la position de départ. Répète avec l''autre jambe.', '["Pencher le torse en arrière lors de l''élévation.", "Lâcher la tension du câble en redescendant.", "Élever la jambe trop haut et perdre le contrôle."]', true, '["Attach the ankle cuff to your outside leg and position yourself arm''s length from the cable machine", "Stand with feet hip-width apart, slight knee bend, and hold the machine for stability with your inside hand", "Engage your core and keep your torso upright throughout the entire movement", "Lift your outside leg directly to the side until you feel a strong contraction in your glutes", "Slowly lower your leg back to the starting position, maintaining tension in the cable", "Perform all repetitions on one side before switching to the other leg"]', '["Fixe la sangle à ta cheville externe et place-toi à une distance d''un bras de la machine à câbles.", "Les pieds à largeur des hanches, genoux légèrement fléchis, maintiens la machine avec ta main interne pour l''équilibre.", "Engage ton abdominal pour garder le torse droit pendant tout le mouvement.", "Lève ta jambe externe directement sur le côté jusqu''à sentir une forte contraction dans tes fessiers.", "Descends lentement ta jambe jusqu''à la position de départ, en maintenant la tension dans le câble.", "Réalise toutes les répétitions d''un côté avant de passer à l''autre jambe."]', '["Maintiens ton torse stable et évite de pencher en arrière pendant le mouvement.", "Concentre-toi sur le mouvement de la hanche plutôt que de simplement déplacer le pied vers l''extérieur.", "Contrôle la phase descendante pour maximiser l''activation des fessiers.", "Garde une légère inclinaison vers l''avant pour mieux cibler le moyen fessier.", "Commence avec un poids léger pour maîtriser le mouvement avant d''augmenter la charge."]', '["Keep your torso stable and avoid leaning away from the machine during the movement", "Focus on lifting the leg from the hip rather than just moving the foot outward", "Control the eccentric portion of the movement to maximize glute activation", "Maintain a slight forward lean of the torso to better target the gluteus medius", "Start with lighter weight to master the movement pattern before progressing"]', '86a5f361-6b81-4ab7-a769-c32ca56d5ae4', 'cable-hip-abduction-86a5f361', NULL, NULL);
INSERT INTO public.exercises VALUES ('a8758c0d-63dd-4919-a375-1073b9afe7c4', 'Étirement Papillon', NULL, 'Stretch Bater', 'Butterfly Stretch', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/butterfly-stretch.mp4', NULL, NULL, NULL, '/videos/thumbnails/butterfly-stretch.jpg', NULL, '["Garde le dos droit tout au long de l''exercice pour éviter de te courber", "Ne force jamais tes genoux vers le bas et évite de rebondir", "L''étirement doit être doux et confortable, pas douloureux", "Concentre-toi sur une respiration profonde pour aider tes muscles à se détendre et approfondir l''étirement", "Si tu as des problèmes de genoux, place des coussins sous tes cuisses pour le soutien"]', '["Ne pas garder le dos droit pendant l''étirement", "Forcer la descente des genoux au lieu de laisser le corps se détendre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "butterfly stretch"]', true, '2026-04-03 12:24:55.870967+00', '2026-04-03 12:24:55.870967+00', 'Position de départ : Assieds-toi sur le sol, les plantes de pieds jointes et les genoux écartés sur les côtés. Tiens tes chevilles ou pieds avec tes mains. Exécution : Basculer doucement en avant depuis tes hanches, le dos droit, et laisse tes genoux s''approcher du sol pour étirer les fléchisseurs de la hanche et l''intérieur des cuisses.', '["Ne pas garder le dos droit pendant l''étirement", "Forcer la descente des genoux au lieu de laisser le corps se détendre"]', true, '["Sit tall with your spine straight and shoulders relaxed", "Press the soles of your feet together and pull them comfortably close to your body", "Hold your ankles or feet with both hands for support", "Slowly hinge forward from your hips while maintaining a straight back", "Breathe deeply and hold the stretch for 15-30 seconds", "Return to the starting position slowly and controlled"]', '["Assieds-toi bien droit, la colonne vertébrale alignée et les épaules relâchées", "Colle les plantes de pieds et rapproche-les confortablement de ton corps", "Maintiens tes chevilles ou pieds avec les deux mains pour le soutien", "Incline lentement ton buste en avant depuis les hanches tout en gardant le dos droit", "Respire profondément et maintiens l''étirement pendant 15-30 secondes", "Reviens à la position de départ lentement et de manière contrôlée"]', '["Garde le dos droit tout au long de l''exercice pour éviter de te courber", "Ne force jamais tes genoux vers le bas et évite de rebondir", "L''étirement doit être doux et confortable, pas douloureux", "Concentre-toi sur une respiration profonde pour aider tes muscles à se détendre et approfondir l''étirement", "Si tu as des problèmes de genoux, place des coussins sous tes cuisses pour le soutien"]', '["Keep your back straight throughout the movement to avoid rounding your spine", "Never force your knees down or bounce during the stretch", "The stretch should feel gentle and comfortable, not painful", "Focus on breathing deeply to help your muscles relax and deepen the stretch", "If you have knee issues, place cushions under your thighs for support"]', 'f96ea3ee-fb2f-4a0f-bc3b-7e63959450c5', 'butterfly-stretch', NULL, NULL);
INSERT INTO public.exercises VALUES ('358d485c-1180-435e-aa6d-5437698a756b', 'Lève-toi et avance !', NULL, NULL, 'Get ups (no jump)', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/get-ups-no-jump.mp4', NULL, NULL, NULL, '/videos/thumbnails/get-ups-no-jump.jpg', NULL, '["Répartis bien ton poids sur tes pieds, en insistant sur la poussée avec les talons", "Maintiens un bon alignement des genoux en veillant à ce qu''ils suivent la direction des orteils", "Engage ton cœur tout au long du mouvement pour assurer ta stabilité et protéger ton bas du dos", "Contrôle bien la descente vers la position de squat au lieu de tomber brusquement", "Garde la poitrine haute et les épaules en arrière pour maintenir une bonne posture pendant l''exercice"]', '["Ne pas garder le dos droit en se levant", "Sauter au lieu de se lever doucement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "get ups (no jump)"]', true, '2026-04-03 12:24:56.823168+00', '2026-04-03 12:24:56.823168+00', 'Position de départ : Commence en position de squat profond avec les pieds écartés à la largeur des épaules, bras devant pour l''équilibre. Exécution : Remonte du squat en poussant sur tes talons et en étendant les hanches et les genoux, puis redescends en contrôlé dans la position de squat.', '["Ne pas garder le dos droit en se levant", "Sauter au lieu de se lever doucement"]', true, '["Start in a deep squat with your thighs parallel to the floor and arms extended forward for balance", "Keep your feet firmly planted shoulder-width apart with toes slightly turned out", "Drive through your heels to stand up, extending your hips and knees simultaneously", "Maintain an upright torso throughout the movement, avoiding excessive forward lean", "Lower back down to the starting squat position with control", "Repeat the movement for the desired number of repetitions"]', '["Commence en squat profond avec les cuisses parallèles au sol et les bras tendus devant pour l''équilibre", "Assure-toi que tes pieds sont bien ancrés à la largeur des épaules, orteils légèrement tournés vers l''extérieur", "Pousse sur tes talons pour te lever, en étendant hanches et genoux en même temps", "Garde le torse droit pendant tout le mouvement, évite de te pencher en avant", "Redescends avec contrôle dans la position de squat de départ", "Répète le mouvement pour le nombre de répétitions souhaité"]', '["Répartis bien ton poids sur tes pieds, en insistant sur la poussée avec les talons", "Maintiens un bon alignement des genoux en veillant à ce qu''ils suivent la direction des orteils", "Engage ton cœur tout au long du mouvement pour assurer ta stabilité et protéger ton bas du dos", "Contrôle bien la descente vers la position de squat au lieu de tomber brusquement", "Garde la poitrine haute et les épaules en arrière pour maintenir une bonne posture pendant l''exercice"]', '["Keep your weight distributed evenly across your feet, focusing on pushing through your heels", "Maintain proper knee alignment by ensuring your knees track over your toes", "Engage your core throughout the entire movement to maintain stability and protect your lower back", "Control the descent back to the squat position rather than dropping down quickly", "Keep your chest up and shoulders back to maintain good posture throughout the exercise"]', 'b2eabe7f-7b04-456e-95b2-7aa3eaa88b9d', 'get-ups-no-jump', NULL, NULL);
INSERT INTO public.exercises VALUES ('d10f744f-2df8-4795-9000-9828bd229564', 'Good Mornings', NULL, 'صباح الخير', 'Good mornings', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/good-mornings.mp4', NULL, NULL, NULL, '/videos/thumbnails/good-mornings.jpg', NULL, '["Gardez le dos plat, évitez de le courber", "Ce mouvement est une flexion des hanches, pas un squat", "Ressentez l''étirement dans vos ischio-jambiers", "Ne mettez pas trop lourd - la technique est primordiale", "Excellent pour la chaîne postérieure"]', '["Courber le dos au lieu de le garder plat", "Ne pas engager le ventre pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "good mornings"]', true, '2026-04-03 12:24:56.857+00', '2026-04-03 12:24:56.857+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des hanches, les mains derrière la tête, les coudes écartés. Gardez le dos droit et le ventre engagé. Exécution : Poussez vos hanches en arrière, inclinez votre torse vers l''avant en gardant le dos droit, puis revenez à la position de départ en avançant vos hanches.', '["Courber le dos au lieu de le garder plat", "Ne pas engager le ventre pendant l''exercice"]', true, '["Bar on upper back like squat", "Feet hip to shoulder-width", "Soft knee bend", "Hinge at hips, pushing butt back", "Lower torso until parallel or comfortable stretch", "Drive hips forward to stand"]', '["Barre sur le haut du dos comme pour un squat", "Pieds écartés de la largeur des hanches aux épaules", "Genoux légèrement fléchis", "Inclinez-vous aux hanches en poussant les fesses en arrière", "Abaissez votre torse jusqu''à ce qu''il soit parallèle ou dans une étirable confortable", "Ramenez vos hanches en avant pour vous redresser"]', '["Gardez le dos plat, évitez de le courber", "Ce mouvement est une flexion des hanches, pas un squat", "Ressentez l''étirement dans vos ischio-jambiers", "Ne mettez pas trop lourd - la technique est primordiale", "Excellent pour la chaîne postérieure"]', '["Keep back flat, not rounded", "Movement is hip hinge, not squat", "Feel stretch in hamstrings", "Don''t go too heavy - technique is key", "Great for posterior chain"]', '89fffd4f-96b2-4833-8b3c-817a0aadb507', 'good-mornings', NULL, NULL);
INSERT INTO public.exercises VALUES ('f232ca07-3dc8-4082-90e2-48944c66176b', 'Kickback Diagonal au câble', NULL, NULL, 'Cable Diagonal Kickback', 'Glutes', '[]', 'Glutes', 'Beginner', 4, '/videos/glutes/cable-diagonal-kickback.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-diagonal-kickback.jpg', NULL, '["Concentrez-vous sur l''activation de vos fessiers plutôt que sur le bas de votre dos pour éviter les blessures.", "Gardez vos hanches carrées et évitez de faire pivoter votre bassin durant le mouvement de kickback.", "Maintenez une tension constante sur le câble sur toute la portée du mouvement.", "Choisissez une charge qui vous permet de réaliser l''ensemble du mouvement avec une technique appropriée.", "Gardez votre jambe de travail droite mais pas verrouillée pour maximiser l''activation des fessiers."]', '["Négliger d''engager les fessiers et se concentrer sur le bas du dos, ce qui peut entraîner des douleurs.", "Ne pas contrôler le mouvement de retour, ce qui réduit l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "cable", "cable diagonal kickback"]', true, '2026-04-03 12:24:55.877735+00', '2026-04-03 12:24:55.877735+00', 'Position de départ : Face à une machine à câbles avec une sangle autour de votre cheville, le pied légèrement en avant. Exécution : Étendez votre jambe en arrière de manière diagonale tout en gardant la jambe droite, puis revenez lentement à la position de départ et reproduisez avec l''autre jambe.', '["Négliger d''engager les fessiers et se concentrer sur le bas du dos, ce qui peut entraîner des douleurs.", "Ne pas contrôler le mouvement de retour, ce qui réduit l''efficacité de l''exercice."]', true, '["Attach the ankle cuff to your working leg and position yourself facing the cable machine with the pulley set to the lowest position", "Stand with your supporting leg slightly bent and lean forward slightly, gripping the machine frame for stability", "Keep your core engaged and maintain a neutral spine throughout the movement", "Initiate the movement by contracting your glutes and kicking your working leg back and diagonally across your body", "Squeeze your glutes firmly at the peak of the movement and hold for one second", "Slowly control the weight back to the starting position without letting the weight stack touch"]', '["Fixez la sangle à votre cheville et positionnez-vous face à la machine à câbles, le poulie réglée au niveau le plus bas.", "Tenez-vous avec la jambe de soutien légèrement fléchie et penchez-vous légèrement en avant en vous agrippant au cadre de la machine pour vous stabiliser.", "Activez votre sangle abdominale et gardez la colonne vertébrale neutre tout au long du mouvement.", "Commencez le mouvement en contractant vos fessiers et en poussant votre jambe de travail en arrière et en diagonale à travers votre corps.", "Contractez fermement vos fessiers au sommet du mouvement et maintenez la contraction pendant une seconde.", "Retournez lentement à la position de départ sans laisser le poids toucher le tas."]', '["Concentrez-vous sur l''activation de vos fessiers plutôt que sur le bas de votre dos pour éviter les blessures.", "Gardez vos hanches carrées et évitez de faire pivoter votre bassin durant le mouvement de kickback.", "Maintenez une tension constante sur le câble sur toute la portée du mouvement.", "Choisissez une charge qui vous permet de réaliser l''ensemble du mouvement avec une technique appropriée.", "Gardez votre jambe de travail droite mais pas verrouillée pour maximiser l''activation des fessiers."]', '["Focus on initiating the movement from your glutes rather than your lower back to avoid injury", "Keep your hips square and avoid rotating your pelvis during the kickback motion", "Maintain constant tension on the cable throughout the entire range of motion", "Use a weight that allows you to complete the full range of motion with proper form", "Keep your working leg straight but not locked to maximize glute activation"]', 'f6fa126f-2811-454f-a542-39780209c9ec', 'cable-diagonal-kickback', NULL, NULL);
INSERT INTO public.exercises VALUES ('ce7412e4-57a2-4b46-9bc2-4c9e97939560', 'Posture du demi-grillon (droite)', NULL, NULL, 'Half frog pose (right)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/half-frog-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-frog-pose-right.jpg', NULL, '["Assure-toi que tes deux os des hanches restent en contact avec le sol.", "Ne force pas le stretch.", "Engage ton ventre pour protéger ton bas du dos."]', '["Négliger la position des hanches.", "Trop forcer le mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "half frog pose (right)"]', true, '2026-04-03 12:24:56.904631+00', '2026-04-03 12:24:56.904631+00', 'Position de départ : Allonge-toi sur le ventre avec la jambe gauche droite et le genou droit plié à 90 degrés, en ramenant le talon droit vers la fesse droite. Exécution : Pousse ton talon droit vers ta fesse tout en soulevant légèrement ta hanche droite du sol pour étirer le fléchisseur de la hanche droite et activer les fessiers droits.', '["Négliger la position des hanches.", "Trop forcer le mouvement."]', true, '["Lie on your stomach and prop yourself up on your forearms.", "Bend one knee and reach back with the same-side hand to hold your foot.", "Gently press your foot toward your hip.", "Hold and breathe, then switch sides."]', '["Allonge-toi sur le ventre et appuie-toi sur tes avant-bras.", "Plie un genou et attrape ton pied avec la main du même côté.", "Pousse doucement ton pied vers ta hanche.", "Tiens la position et respire, puis change de côté."]', '["Assure-toi que tes deux os des hanches restent en contact avec le sol.", "Ne force pas le stretch.", "Engage ton ventre pour protéger ton bas du dos."]', '["Keep both hip bones pressing into the floor.", "Do not force the stretch.", "Engage your core to protect your lower back."]', '39e71f53-4d30-4cb0-a6dc-16411d33bff0', 'half-frog-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('30dc2e49-a612-4eaf-ae91-0ce4aad558e2', 'Ponts de fessiers', NULL, NULL, 'Butt bridges', 'Glutes', '[]', 'Glutes', 'Intermediate', 16, '/videos/glutes/butt-bridges.mp4', NULL, NULL, NULL, '/videos/thumbnails/butt-bridges.jpg', NULL, '["Concentre-toi sur l''appui avec tes talons plutôt que de pousser avec les orteils.", "Évite de cambrer le bas de ton dos en gardant ton ventre engagé.", "Sers bien tes fessiers au sommet de chaque répétition pour un maximum d''activation musculaire.", "Garde les genoux face à l''avant, ne les laisse pas s''écrouler vers l''intérieur.", "Respire régulièrement tout au long de l''exercice, expire en soulevant."]', '["Ne pas engager les muscles du ventre, ce qui peut causer des douleurs au bas du dos.", "Trop se cambrer au sommet, ce qui diminue l’efficacité de l’exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "butt bridges"]', true, '2026-04-03 12:24:55.846071+00', '2026-04-03 12:24:55.846071+00', 'Allonge-toi sur le dos, les genoux fléchis et les pieds à plat au sol, écartés à la largeur des hanches. Les bras reposent sur les côtés pour plus de stabilité. Prêt à flamboyer tes fessiers ? C''est parti !', '["Ne pas engager les muscles du ventre, ce qui peut causer des douleurs au bas du dos.", "Trop se cambrer au sommet, ce qui diminue l’efficacité de l’exercice."]', true, '["Lie on your back with knees bent at 90 degrees and feet flat on the floor", "Place your arms at your sides with palms down for stability", "Engage your core and squeeze your glutes as you drive through your heels", "Lift your hips up until your body forms a straight line from knees to shoulders", "Hold the top position briefly while maintaining the glute squeeze", "Lower your hips back down slowly and with control, stopping just before touching the ground"]', '["Allonge-toi sur le dos avec les genoux pliés à 90 degrés et les pieds à plat au sol.", "Place tes bras sur les côtés, paumes vers le bas pour la stabilité.", "Engage ton ventre et serre les fessiers en appuyant sur tes talons.", "Soulève tes hanches jusqu''à former une ligne droite entre les genoux et les épaules.", "Maintiens brièvement la position en haut en gardant les fessiers bien serrés.", "Abaisse tes hanches lentement et avec contrôle, en te stoppant juste avant de toucher le sol."]', '["Concentre-toi sur l''appui avec tes talons plutôt que de pousser avec les orteils.", "Évite de cambrer le bas de ton dos en gardant ton ventre engagé.", "Sers bien tes fessiers au sommet de chaque répétition pour un maximum d''activation musculaire.", "Garde les genoux face à l''avant, ne les laisse pas s''écrouler vers l''intérieur.", "Respire régulièrement tout au long de l''exercice, expire en soulevant."]', '["Focus on driving the movement through your heels rather than pushing with your toes", "Avoid overarching your lower back at the top position by keeping your core engaged", "Squeeze your glutes at the top of each repetition to maximize muscle activation", "Keep your knees pointing forward and avoid letting them cave inward", "Maintain steady breathing throughout the exercise, exhaling as you lift up"]', 'c424ec91-5260-4a23-800d-1a5e140f8320', 'butt-bridges', NULL, NULL);
INSERT INTO public.exercises VALUES ('b2305a4b-362b-4749-9e74-eaedb77737cf', 'Fente arrière - Étirement de la cuisse droite', NULL, 'فنتة خلفية - إمتداد الفخذ الأيمن', 'Half split (right)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/half-split-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-split-right.jpg', NULL, '["Garde un léger pli dans le genou tendu pour protéger l''articulation.", "Incline-toi des hanches, pas de la taille.", "Respire profondément dans l''étirement des ischio-jambiers."]', '["Ne pas plier le genou arrière, ce qui peut causer de la tension.", "Avoir le dos rond au lieu de rester droit.", "Ne pas respirer et retenir sa respiration pendant l''étirement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "half split (right)"]', true, '2026-04-03 12:24:57.013222+00', '2026-04-03 12:24:57.013222+00', 'Position de départ : Mets-toi en position de fente basse, la jambe droite tendue devant toi, le genou gauche au sol derrière. Place tes mains de chaque côté de ta jambe droite pour te soutenir. Execution : Penche-toi lentement vers l''avant en gardant le dos droit, et ressens l''étirement à l''arrière de ta cuisse droite.', '["Ne pas plier le genou arrière, ce qui peut causer de la tension.", "Avoir le dos rond au lieu de rester droit.", "Ne pas respirer et retenir sa respiration pendant l''étirement."]', true, '["From a low lunge, straighten your front leg and flex your front foot.", "Shift your hips back over your back knee.", "Fold forward over the straight leg with a flat back.", "Place your hands on the floor or on blocks."]', '["À partir de la fente basse, tends ta jambe avant et fléchis le pied vers toi.", "Déplace tes hanches en arrière au-dessus de ton genou arrière.", "Incline-toi vers l''avant en gardant le dos plat sur la jambe tendue.", "Pose tes mains au sol ou sur des blocs."]', '["Garde un léger pli dans le genou tendu pour protéger l''articulation.", "Incline-toi des hanches, pas de la taille.", "Respire profondément dans l''étirement des ischio-jambiers."]', '["Keep a micro-bend in the straight knee to protect the joint.", "Hinge from the hips, not the waist.", "Breathe deeply into the hamstring stretch."]', 'b1b1d4cd-c4eb-47cc-a3f8-478eb474999f', 'half-split-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('8c21311d-d651-4f01-b3e4-3b55e9cb6c92', 'Curls Marteau', NULL, NULL, 'Hammer Curls', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/hammer-curls.mp4', NULL, NULL, NULL, '/videos/thumbnails/hammer-curls.jpg', NULL, '["Garde les coudes près du corps, évite de les balancer vers l''avant ou vers l''arrière.", "La prise neutre cible différemment les muscles, accroît l''efficacité de l''exercice.", "Concentre-toi sur un mouvement contrôlé pour maximiser l''engagement musculaire.", "N''utilise pas d''élan, reste concentré sur la force des biceps.", "Assure-toi que tes poignets sont droits et alignés tout au long de l''exercice."]', '["Balancer les coudes des deux côtés, ce qui réduit l''efficacité de l''exercice.", "Se pencher en avant ou relâcher la posture, entraînant des douleurs lors de l''exécution."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "hammer curls"]', true, '2026-04-03 12:24:57.031831+00', '2026-04-03 12:24:57.031831+00', 'Exécution des Curls Marteau pour cibler tes biceps avec une prise neutre, pour un développement optimal !', '["Balancer les coudes des deux côtés, ce qui réduit l''efficacité de l''exercice.", "Se pencher en avant ou relâcher la posture, entraînant des douleurs lors de l''exécution."]', true, '["Stand with feet shoulder-width apart and hold a dumbbell in each hand with arms at your sides", "Keep your palms facing inward toward your body throughout the entire movement", "Engage your core and maintain an upright posture with shoulders back", "Curl the weights up by bending at the elbows, lifting until your forearms are nearly vertical", "Squeeze your biceps at the top of the movement", "Slowly lower the weights back to the starting position with control"]', '["Tiens-toi droit, les pieds écartés à la largeur des épaules, un haltère dans chaque main le long du corps.", "Veille à maintenir les paumes tournées vers toi pendant tout l''exercice.", "Active ton tronc et garde une posture droite, les épaules en arrière.", "Flexe les coudes pour soulever les haltères jusqu''à ce que tes avant-bras soient presque verticaux.", "Ressens la contraction de tes biceps en haut du mouvement.", "Redescends lentement les haltères à la position de départ avec maîtrise."]', '["Garde les coudes près du corps, évite de les balancer vers l''avant ou vers l''arrière.", "La prise neutre cible différemment les muscles, accroît l''efficacité de l''exercice.", "Concentre-toi sur un mouvement contrôlé pour maximiser l''engagement musculaire.", "N''utilise pas d''élan, reste concentré sur la force des biceps.", "Assure-toi que tes poignets sont droits et alignés tout au long de l''exercice."]', '["Keep your elbows close to your sides and avoid swinging them forward or backward", "Maintain the neutral grip with palms facing inward - this targets the brachialis muscle differently than regular bicep curls", "Focus on controlled movement both up and down to maximize muscle engagement", "Avoid using momentum or swinging your body to lift the weights", "Keep your wrists straight and aligned throughout the exercise"]', '3901065d-a926-4d63-9306-0f14eb731d7c', 'hammer-curls', NULL, NULL);
INSERT INTO public.exercises VALUES ('733e615b-8e0d-4894-b904-ce9c2333f462', 'Garland Pose - Renforce tes fessiers !', NULL, NULL, 'Garland pose', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/garland-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/garland-pose.jpg', NULL, '["Garde les talons au sol (place un tapis roulé en dessous si nécessaire).", "Allonge ta colonne et relève la poitrine.", "Active ton centre pour l''équilibre."]', '["Ne pas maintenir les talons au sol.", "Ne pas garder la colonne droite."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "garland pose"]', true, '2026-04-03 12:24:56.8079+00', '2026-04-03 12:24:56.8079+00', 'Position de départ : Écarte les pieds légèrement plus larges que la largeur des hanches, avec les orteils tournés vers l''extérieur à 45 degrés. Exécution : Descends en position accroupie profonde, en rapprochant tes hanches le plus près possible du sol tout en gardant le torse droit et en pressant tes coudes contre tes cuisses intérieures.', '["Ne pas maintenir les talons au sol.", "Ne pas garder la colonne droite."]', true, '["Stand with feet slightly wider than hip-width, toes turned out.", "Bend your knees and lower into a deep squat.", "Bring your palms together at your chest.", "Press your elbows against your inner knees to open the hips."]', '["Écarte les pieds légèrement plus larges que la largeur des hanches, orteils tournés vers l''extérieur.", "Plie les genoux et descends en squat profond.", "Rassemble tes paumes au niveau de la poitrine.", "Presse tes coudes contre tes genoux intérieurs pour ouvrir les hanches."]', '["Garde les talons au sol (place un tapis roulé en dessous si nécessaire).", "Allonge ta colonne et relève la poitrine.", "Active ton centre pour l''équilibre."]', '["Keep your heels on the floor (place a rolled mat under them if needed).", "Lengthen your spine and lift your chest.", "Engage your core for balance."]', '928d2978-b0a4-4619-858d-106a5c99e507', 'garland-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('e429d8e6-e3c9-41ae-ab05-2ef86008500f', 'Élévations de mollets assis', NULL, 'رفع العجل بوجوج', 'Seated Calf Raises', 'Calves', '[]', 'Calves', 'Beginner', 1, '/videos/calves/seated-calf-raises.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-calf-raises.jpg', NULL, '["Garde tes genoux stables et évite de rebondir pendant le mouvement", "Concentre-toi sur un tempo lent et contrôlé avec une brève pause en haut de chaque répétition", "Expire en élevant tes talons et inspire en les abaissant", "Commence par un nombre élevé de répétitions car c''est un exercice avec le poids du corps, vise 15 à 25 répétitions par série", "Assure-toi d''un mouvement complet en élevant tes talons le plus haut possible et en les abaissant complètement"]', '["Ne pas stabiliser les genoux durant l''exercice", "Rebondir au lieu de contrôler le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["calves", "barbell", "seated calf raises"]', true, '2026-04-03 12:24:58.794083+00', '2026-04-03 12:24:58.794083+00', 'Position de départ : Assieds-toi sur une machine à élévations de mollets, pieds sur la plateforme et genoux fléchis. Exécution : Élève tes talons en contractant les mollets, puis redescends lentement à la position de départ.', '["Ne pas stabiliser les genoux durant l''exercice", "Rebondir au lieu de contrôler le mouvement"]', true, '["Sit upright on a sturdy chair or bench with your back straight and core engaged", "Place feet flat on the floor with your knees directly above your ankles", "Position your hands on your thighs to provide light resistance or support", "Slowly lift your heels as high as possible while keeping your toes and balls of feet on the ground", "Hold the top position for 1-2 seconds while squeezing your calf muscles", "Lower your heels back down slowly and with control to complete one repetition"]', '["Assieds-toi droit sur une chaise ou un banc solide, le dos droit et le ventre engagé", "Place les pieds à plat sur le sol, les genoux directement au-dessus des chevilles", "Positionne tes mains sur tes cuisses pour apporter un léger soutien", "Soulève lentement tes talons aussi haut que possible en gardant les orteils et la plante des pieds au sol", "Maintiens la position haute pendant 1 à 2 secondes en contractant tes mollets", "Redescends tes talons lentement et avec contrôle pour compléter une répétition"]', '["Garde tes genoux stables et évite de rebondir pendant le mouvement", "Concentre-toi sur un tempo lent et contrôlé avec une brève pause en haut de chaque répétition", "Expire en élevant tes talons et inspire en les abaissant", "Commence par un nombre élevé de répétitions car c''est un exercice avec le poids du corps, vise 15 à 25 répétitions par série", "Assure-toi d''un mouvement complet en élevant tes talons le plus haut possible et en les abaissant complètement"]', '["Keep your knees stable and avoid bouncing during the movement", "Focus on a slow, controlled tempo with a brief pause at the top of each rep", "Breathe out as you lift your heels and breathe in as you lower them", "Start with higher repetitions since this is a bodyweight exercise, aiming for 15-25 reps per set", "Ensure full range of motion by lifting heels as high as possible and lowering them completely"]', '2bdda28c-3fe2-4ecb-9a71-945a051d5bbd', 'seated-calf-raises', NULL, NULL);
INSERT INTO public.exercises VALUES ('4751963c-ebee-4ea0-bf18-17871ed4bdd6', 'Marche Talon-Pointe', NULL, NULL, 'Heel to toe walk', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/heel-to-toe-walk.mp4', NULL, NULL, NULL, '/videos/thumbnails/heel-to-toe-walk.jpg', NULL, '["Fais des pas petits et contrôlés, sans précipitation", "Concentre-toi sur une ligne droite, évite de dévier sur les côtés", "Respire normalement et évite de retenir ton souffle pendant l''exercice", "Commence près d''un mur ou d''une surface solide si tu es novice dans l''entraînement à l''équilibre", "Cet exercice améliore la proprioception, la coordination et l''équilibre dynamique"]', '["Ne pas garder une position droite et relâchée", "Prendre des pas trop larges et déséquilibrés"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "heel to toe walk"]', true, '2026-04-03 12:24:57.068514+00', '2026-04-03 12:24:57.068514+00', 'Position de départ : Tiens-toi droit, les pieds joints, les bras le long du corps ou étendus pour t''équilibrer. Exécution : Avance en ligne droite en posant le talon d''un pied juste devant les orteils de l''autre à chaque pas.', '["Ne pas garder une position droite et relâchée", "Prendre des pas trop larges et déséquilibrés"]', true, '["Stand tall with good posture and engage your core muscles", "Take a small step forward, placing your heel directly against the toes of your back foot", "Maintain contact between heel and toes for a moment before transferring weight", "Continue walking forward heel-to-toe for the desired distance or number of steps", "Keep your eyes focused on a fixed point ahead to help maintain balance", "If you feel unsteady, extend your arms out to the sides for additional stability"]', '["Tiens-toi bien droit avec une bonne posture et engage tes muscles du tronc", "Fais un petit pas en avant, en plaçant ton talon directement contre les orteils de ton pied arrière", "Garde le contact entre le talon et les orteils un moment avant de transférer ton poids", "Continue d''avancer talon-pointe sur la distance ou le nombre de pas souhaités", "Fixe un point devant toi pour t''aider à maintenir ton équilibre", "Si tu te sens instable, tends les bras sur les côtés pour davantage de stabilité"]', '["Fais des pas petits et contrôlés, sans précipitation", "Concentre-toi sur une ligne droite, évite de dévier sur les côtés", "Respire normalement et évite de retenir ton souffle pendant l''exercice", "Commence près d''un mur ou d''une surface solide si tu es novice dans l''entraînement à l''équilibre", "Cet exercice améliore la proprioception, la coordination et l''équilibre dynamique"]', '["Keep steps small and controlled rather than rushing through the movement", "Focus on maintaining a straight line of travel rather than veering side to side", "Breathe normally throughout the exercise and avoid holding your breath", "Start near a wall or sturdy surface for support if you''re new to balance training", "This exercise improves proprioception, coordination, and dynamic balance"]', '649d45cb-6e06-4b5b-890a-9ea4043ed7d9', 'heel-to-toe-walk', NULL, NULL);
INSERT INTO public.exercises VALUES ('fe7475ea-990e-4817-b5d9-92f5525feb70', 'Squats avec tapotements des orteils', NULL, 'السكوات مع ضغوط على الأصابع', 'Squat to toe taps', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/squat-to-toe-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/squat-to-toe-taps.jpg', NULL, '["Assure-toi que tes genoux suivent la ligne de tes orteils durant tout le mouvement", "Garde une colonne vertébrale neutre, évite de courber ton dos en touchant tes orteils", "Descends aussi bas que ta mobilité te le permet tout en gardant la bonne posture", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse", "Si tu ne peux pas atteindre tes orteils, touche aussi loin que c''est confortable sans perdre ta forme"]', '["Les genoux qui s''écartent vers l''intérieur", "Le dos arrondi lorsque tu te penches pour toucher tes orteils"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "squat to toe taps"]', true, '2026-04-03 12:24:59.475319+00', '2026-04-03 12:24:59.475319+00', 'Un exercice simple mais puissant pour renforcer vos quadriceps tout en améliorant la mobilité de vos hanches !', '["Les genoux qui s''écartent vers l''intérieur", "Le dos arrondi lorsque tu te penches pour toucher tes orteils"]', true, '["Stand with feet hip-width apart, toes pointing slightly outward, arms at your sides", "Lower into a squat by pushing your hips back and bending your knees, keeping your chest up and weight in your heels", "From the squat position, reach down and lightly tap your toes with your fingertips while maintaining the squat", "Return your arms to starting position while staying in the squat", "Drive through your heels to return to standing position", "Repeat for desired repetitions"]', '["Place-toi debout, pieds écartés à la largeur des hanches, orteils légèrement vers l''extérieur, bras le long du corps", "Descends en squat en poussant les hanches vers l''arrière et en fléchissant les genoux, garde la poitrine relevée et le poids sur tes talons", "Depuis la position de squat, penche-toi légèrement pour toucher tes orteils avec tes doigts tout en maintenant la position de squat", "Ramène tes bras à la position de départ tout en restant en squat", "Pousse à travers tes talons pour revenir en position debout", "Répète pour le nombre de répétitions souhaité"]', '["Assure-toi que tes genoux suivent la ligne de tes orteils durant tout le mouvement", "Garde une colonne vertébrale neutre, évite de courber ton dos en touchant tes orteils", "Descends aussi bas que ta mobilité te le permet tout en gardant la bonne posture", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse", "Si tu ne peux pas atteindre tes orteils, touche aussi loin que c''est confortable sans perdre ta forme"]', '["Keep your knees tracking over your toes throughout the movement", "Maintain a neutral spine and avoid rounding your back when reaching for your toes", "Only lower as deep as your mobility allows while keeping proper form", "Focus on controlled movement rather than speed", "If you cannot reach your toes, reach as far as comfortable without compromising form"]', '0b7c9826-2501-4938-a921-a6f62e66e890', 'squat-to-toe-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('38d5b48e-6a65-4b3b-9f4d-87187157a94b', 'Fente Sprinteuse Explosive (Droite)', NULL, NULL, 'Explosive sprinter lunge (right)', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/explosive-sprinter-lunge-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/explosive-sprinter-lunge-right.jpg', NULL, '["Concentre-toi sur un atterrissage doux avec les genoux fléchis pour absorber l''impact et protéger tes articulations", "Garde ton genou avant aligné au-dessus de ta cheville, ne le laisse jamais s''effondrer vers l''intérieur", "Maintiens un torse droit tout au long du mouvement pour éviter de trop pencher en avant", "Génère de la puissance avec tes fessiers et tes quadriceps lors du retour à la position de départ", "Commence par des sauts plus petits et augmente progressivement la distance à mesure que tu maîtrises le mouvement"]', '["Atterrissage trop lourd, ce qui peut blesser les articulations", "Pied avant qui dépasse trop la ligne des orteils, créant une tension excessive"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "explosive sprinter lunge (right)"]', true, '2026-04-03 12:24:56.697571+00', '2026-04-03 12:24:56.697571+00', 'Prends ta position : Tiens-toi droit, les pieds écartés à la largeur des hanches, les mains le long du corps ou devant la poitrine. Pas d''hésitation ! Saute explosivement en avant dans une fente profonde avec le pied droit, atterrit en douceur tout en gardant le contrôle, puis propulse-toi puissamment pour revenir à la position de départ.', '["Atterrissage trop lourd, ce qui peut blesser les articulations", "Pied avant qui dépasse trop la ligne des orteils, créant une tension excessive"]', true, '["Stand with feet hip-width apart and engage your core for stability", "Take a large explosive jump forward, landing with your right foot ahead and left foot behind", "Land in a deep lunge position with your right thigh parallel to the ground and left knee hovering just above the floor", "Keep your torso upright and weight evenly distributed between both legs", "Push explosively off your right foot to return to the starting position", "Land softly on both feet before repeating the movement"]', '["Tiens-toi avec les pieds écartés à la largeur des hanches et engage ton gainage pour la stabilité", "Fais un grand saut explosif en avant, atterrissant avec le pied droit devant et le gauche derrière", "Atteins une position de fente profonde avec la cuisse droite parallèle au sol et le genou gauche juste au-dessus du sol", "Garde le torse droit et le poids réparti de manière égale sur les deux jambes", "Pousse de manière explosive avec ton pied droit pour revenir à la position initiale", "Atterris en douceur sur les deux pieds avant de répéter le mouvement"]', '["Concentre-toi sur un atterrissage doux avec les genoux fléchis pour absorber l''impact et protéger tes articulations", "Garde ton genou avant aligné au-dessus de ta cheville, ne le laisse jamais s''effondrer vers l''intérieur", "Maintiens un torse droit tout au long du mouvement pour éviter de trop pencher en avant", "Génère de la puissance avec tes fessiers et tes quadriceps lors du retour à la position de départ", "Commence par des sauts plus petits et augmente progressivement la distance à mesure que tu maîtrises le mouvement"]', '["Focus on landing softly with bent knees to absorb impact and protect your joints", "Keep your front knee aligned over your ankle, never allowing it to cave inward", "Maintain an upright torso throughout the movement to prevent excessive forward lean", "Generate power from your glutes and quads when exploding back to the starting position", "Start with smaller jumps and gradually increase distance as you master the movement pattern"]', 'd5dff683-d9a5-42ca-b325-47f7275f7def', 'explosive-sprinter-lunge-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('c87fb10d-60dc-4122-bc8f-b68245b26f6e', 'Machine Row Haut', NULL, NULL, 'High Row Machine', 'Back', '[]', 'Back', 'Beginner', 8, '/videos/back/high-row-machine.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-row-machine.jpg', NULL, '["Gardez la poitrine en avant et évitez de courber les épaules vers l''avant pendant le mouvement", "Concentrez-vous sur le tirage avec les muscles du dos plutôt qu''avec les bras en initiant le mouvement avec vos omoplates", "Maintenez une légère courbure dans le bas du dos et évitez de vous pencher trop en avant ou en arrière", "Utilisez une amplitude complète mais ne laissez pas la pile de poids s''écraser entre les répétitions", "Expirez en tirant le poids vers vous, inspirez en revenant à la position de départ"]', '["Ne pas ajuster la hauteur du siège correctement", "Tirer uniquement avec les bras au lieu d''utiliser le dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "high row machine"]', true, '2026-04-03 12:24:57.139468+00', '2026-04-03 12:24:57.139468+00', 'Position de départ : Installez-vous sur la machine à ramer, prise haute, et réglez la hauteur du siège pour que les poignées soient à la hauteur de votre poitrine. Exécution : Tirez les poignées vers votre poitrine en gardant le torse droit, puis revenez lentement à la position de départ.', '["Ne pas ajuster la hauteur du siège correctement", "Tirer uniquement avec les bras au lieu d''utiliser le dos"]', true, '["Adjust the seat height so your arms are parallel to the floor when gripping the handles", "Sit with your chest up, shoulders back, and feet firmly planted on the floor or footrests", "Grip the handles with an overhand grip, arms fully extended forward", "Pull the handles back toward your lower chest/upper abdomen by squeezing your shoulder blades together", "Pause briefly at the peak contraction, feeling the squeeze in your mid-back", "Slowly return to the starting position with control, maintaining tension throughout"]', '["Ajustez la hauteur du siège pour que vos bras soient parallèles au sol en tenant les poignées", "Asseyez-vous, poitrine en avant, épaules en arrière, pieds bien ancrés au sol ou sur les repose-pieds", "Prenez les poignées en prise pronation, bras complètement tendus vers l''avant", "Tirez les poignées vers votre bas de poitrine/haut de l''abdomen en serrant vos omoplates ensemble", "Faites une pause brève à la contraction maximale, ressentez la tension dans votre milieu du dos", "Retournez lentement à la position de départ avec contrôle, en maintenant la tension tout au long du mouvement"]', '["Gardez la poitrine en avant et évitez de courber les épaules vers l''avant pendant le mouvement", "Concentrez-vous sur le tirage avec les muscles du dos plutôt qu''avec les bras en initiant le mouvement avec vos omoplates", "Maintenez une légère courbure dans le bas du dos et évitez de vous pencher trop en avant ou en arrière", "Utilisez une amplitude complète mais ne laissez pas la pile de poids s''écraser entre les répétitions", "Expirez en tirant le poids vers vous, inspirez en revenant à la position de départ"]', '["Keep your chest up and avoid rounding your shoulders forward during the movement", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Maintain a slight arch in your lower back and avoid leaning too far forward or backward", "Use a full range of motion but don''t allow the weight stack to crash down between reps", "Exhale as you pull the weight toward you, inhale as you return to the starting position"]', '0d3505ae-ce8d-4ad5-b8d0-8c172dd08969', 'high-row-machine', NULL, NULL);
INSERT INTO public.exercises VALUES ('1f0705ad-76e6-45cf-806a-99feff832b78', 'Machine à Abduction Hanche', NULL, 'آلة رفع الفخذ', 'Hip Abduction Machine', 'Glutes', '[]', 'Glutes', 'Beginner', 8, '/videos/glutes/hip-abduction-machine.mp4', NULL, NULL, NULL, '/videos/thumbnails/hip-abduction-machine.jpg', NULL, '["Garde ton tronc engagé et évite de cambrer le dos pendant le mouvement", "Concentre-toi sur le fait d''initier le mouvement avec tes fessiers plutôt que de juste pousser avec tes jambes", "Contrôle la phase de retour - ne laisse pas le poids retomber brutalement à la position de départ", "Évite de te pencher en avant ou d''utiliser l''élan pour réaliser la répétition", "Commence avec un poids léger pour maîtriser la forme avant de passer à une résistance plus lourde"]', '["Laisser les poids toucher entre les répétitions", "Utiliser l''élan au lieu de la force musculaire"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "machine", "hip abduction machine"]', true, '2026-04-03 12:24:57.154892+00', '2026-04-03 12:24:57.154892+00', 'Position de départ : Assieds-toi sur la machine à abduction de la hanche, les jambes légèrement fléchies et les genoux reposant sur les coussins. Exécution : Écarte tes jambes contre la résistance, puis reviens lentement à la position de départ.', '["Laisser les poids toucher entre les répétitions", "Utiliser l''élan au lieu de la force musculaire"]', true, '["Adjust the machine so the leg pads rest comfortably against your outer thighs just above the knees", "Sit with your back flat against the backrest and grip the handles for stability", "Set your feet flat on the footrests with knees slightly bent", "Push your legs apart by squeezing your glutes and driving through your outer thighs", "Hold the peak contraction briefly then slowly return to starting position", "Complete the full range of motion without letting the weight stack touch between repetitions"]', '["Règle la machine pour que les coussins reposent confortablement sur l''extérieur de tes cuisses, juste au-dessus des genoux", "Assieds-toi avec le dos bien plaqué contre le dossier et mets les mains sur les poignées pour plus de stabilité", "Pose bien tes pieds à plat sur les repose-pieds avec les genoux légèrement fléchis", "Écarte tes jambes en contractant tes fessiers et en poussant à travers tes cuisses extérieures", "Maintiens la contraction à son maximum un bref instant puis redescends lentement à la position de départ", "Effectue l''amplitude complète du mouvement sans laisser les poids toucher entre les répétitions"]', '["Garde ton tronc engagé et évite de cambrer le dos pendant le mouvement", "Concentre-toi sur le fait d''initier le mouvement avec tes fessiers plutôt que de juste pousser avec tes jambes", "Contrôle la phase de retour - ne laisse pas le poids retomber brutalement à la position de départ", "Évite de te pencher en avant ou d''utiliser l''élan pour réaliser la répétition", "Commence avec un poids léger pour maîtriser la forme avant de passer à une résistance plus lourde"]', '["Keep your core engaged and avoid arching your back during the movement", "Focus on initiating the movement with your glutes rather than just pushing with your legs", "Control the return phase - don''t let the weight slam back to the starting position", "Avoid leaning forward or using momentum to complete the repetition", "Start with lighter weight to master the form before progressing to heavier resistance"]', '6426c762-dd1d-4e44-b9c0-89875c81553a', 'hip-abduction-machine', NULL, NULL);
INSERT INTO public.exercises VALUES ('d2c5e848-ef95-4e72-b37e-c14a371bee63', 'Squat Complet avec Barre', NULL, NULL, 'Barbell Full Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 1, '/videos/quadriceps/barbell-full-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-full-squat.jpg', NULL, '["Utilise toujours un rack à squat avec des barres de sécurité réglées juste en dessous de ta position de squat la plus basse.", "Assure-toi que tes genoux restent alignés avec tes orteils - évite de les laisser s''affaisser vers l''intérieur.", "Maintiens une colonne vertébrale neutre tout au long du mouvement - évite d''arrondir ton dos.", "Contrôle la descente et évite de rebondir au fond du squat.", "Commence avec le poids du corps ou une barre vide pour maîtriser le mouvement avant d''ajouter du poids."]', '["Les genoux qui s''affaissent vers l''intérieur.", "Le dos arrondi pendant le mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "barbell full squat"]', true, '2026-04-03 12:24:55.57273+00', '2026-04-03 12:24:55.57273+00', 'Position de départ : Place-toi avec les pieds écartés à la largeur des épaules, la barre reposant sur tes trapèzes supérieurs (position haute), le tronc gainé et la poitrine relevée. Exécution : Abaisse ton corps en poussant les hanches vers l''arrière et en fléchissant les genoux jusqu''à ce que tes cuisses soient parallèles au sol ou en dessous, puis pousse à travers tes talons pour revenir à la position de départ.', '["Les genoux qui s''affaissent vers l''intérieur.", "Le dos arrondi pendant le mouvement."]', true, '["Position the barbell on your upper trapezius muscles (high bar) or rear deltoids (low bar), step back from the rack, and set feet shoulder-width apart with toes slightly turned out.", "Engage your core, keep your chest up and spine neutral, then initiate the movement by pushing your hips back and bending at the knees.", "Lower your body until your hip crease drops just below your knee caps, maintaining weight distributed evenly across your feet.", "Drive through your heels and push the floor away to return to starting position, keeping your knees tracking over your toes throughout the movement.", "Complete the rep by fully extending your hips and knees while maintaining proper posture."]', '["Positionne la barre sur tes trapèzes supérieurs (haute) ou sur tes deltoïdes arrières (basse), recule du rack, et place tes pieds à la largeur des épaules avec les orteils légèrement tournés vers l''extérieur.", "Gaine ton tronc, garde la poitrine haute et la colonne vertébrale neutre, puis commence le mouvement en poussant tes hanches en arrière et en fléchissant les genoux.", "Abaisse ton corps jusqu''à ce que le pli de ta hanche passe juste en dessous de tes genoux, tout en maintenant le poids bien réparti sur tes pieds.", "Pousse à travers tes talons et éloigne le sol de toi pour revenir à la position de départ, en gardant les genoux alignés avec tes orteils pendant tout le mouvement.", "Termine le mouvement en étendant complètement tes hanches et tes genoux tout en maintenant une bonne posture."]', '["Utilise toujours un rack à squat avec des barres de sécurité réglées juste en dessous de ta position de squat la plus basse.", "Assure-toi que tes genoux restent alignés avec tes orteils - évite de les laisser s''affaisser vers l''intérieur.", "Maintiens une colonne vertébrale neutre tout au long du mouvement - évite d''arrondir ton dos.", "Contrôle la descente et évite de rebondir au fond du squat.", "Commence avec le poids du corps ou une barre vide pour maîtriser le mouvement avant d''ajouter du poids."]', '["Always use a squat rack with safety bars set just below your lowest squat position", "Keep your knees aligned with your toes - avoid letting them cave inward", "Maintain a neutral spine throughout the entire movement - avoid rounding your back", "Control the descent and avoid bouncing at the bottom of the squat", "Start with bodyweight or an empty barbell to master the movement pattern before adding weight"]', '0e5f29cd-ff79-428a-bb1c-1753a9047f32', 'barbell-full-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('833a51cf-14f3-445c-9a82-2c1ac39b4634', 'Pose de l''angle latéral étendu (droite)', NULL, NULL, 'Extended side angle pose (right)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/extended-side-angle-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/extended-side-angle-pose-right.jpg', NULL, '["Gardez votre genou avant aligné avec votre cheville.", "Appuyez fermement sur le bord extérieur de votre pied arrière.", "Ne vous affaissez pas sur votre cuisse avant."]', '["Ne pas aligner le genou avec la cheville.", "S''effondrer sur la cuisse avant."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "extended side angle pose (right)"]', true, '2026-04-03 12:24:56.70508+00', '2026-04-03 12:24:56.70508+00', 'Position de départ : Écartez les pieds, tournez le pied droit à 90 degrés vers l''extérieur et légèrement l''inverse pour le gauche. Fléchissez le genou droit en effectuant un fente latérale tout en gardant la jambe gauche tendue. Pour l''exécution : Abaissez l''avant-bras droit sur la cuisse droite et étirez votre bras gauche au-dessus de la tête, formant une ligne droite des doigts gauche au talon gauche tout en maintenant la position. Ne lâchez rien !', '["Ne pas aligner le genou avec la cheville.", "S''effondrer sur la cuisse avant."]', true, '["From Warrior II, bring your front forearm to rest on your front thigh.", "Extend your top arm overhead, creating a line from back foot to fingertips.", "Turn your chest toward the ceiling.", "Hold and breathe deeply."]', '["Depuis la posture du Guerrier II, reposez votre avant-bras sur votre cuisse avant.", "Étirez votre bras supérieur au-dessus de votre tête pour former une ligne de votre pied arrière à vos doigts.", "Tournez votre poitrine vers le plafond.", "Restez dans cette position et respirez profondément."]', '["Gardez votre genou avant aligné avec votre cheville.", "Appuyez fermement sur le bord extérieur de votre pied arrière.", "Ne vous affaissez pas sur votre cuisse avant."]', '["Keep your front knee over the ankle.", "Press firmly through the outer edge of your back foot.", "Do not collapse onto the front thigh."]', '5f8e2c01-66eb-4f23-b3ad-c87c631e257f', 'extended-side-angle-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('f47f980f-0586-4118-b421-2fdcdc06fa90', 'Fente arrière avec montée de genou', NULL, NULL, 'Reverse lunge to knee drive', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/reverse-lunge-to-knee-drive.mp4', NULL, NULL, NULL, '/videos/thumbnails/reverse-lunge-to-knee-drive.jpg', NULL, '["Concentre ton poids sur ta jambe avant pendant la fente pour activer tes quadriceps au maximum.", "Monte le genou avec contrôle plutôt qu''avec élan pour maintenir ton équilibre et ta forme correcte.", "Assure-toi que ton genou avant suit la ligne de tes orteils et ne s''écroule pas pendant la fente.", "Travaille sur une transition fluide entre la fente et la montée de genou sans pause.", "Atterris en douceur lors de la fente pour réduire l''impact sur tes articulations."]', '["Ne pas engager le ventre pour la stabilité.", "Laisser le genou avant s''incliner vers l''intérieur."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "reverse lunge to knee drive"]', true, '2026-04-03 12:24:58.603546+00', '2026-04-03 12:24:58.603546+00', 'Mets-toi en position debout, les pieds écartés à la largeur des hanches. Effectue une fente arrière, puis monte le genou vers la poitrine en revenant à la position debout. Alterne les jambes à chaque répétition.', '["Ne pas engager le ventre pour la stabilité.", "Laisser le genou avant s''incliner vers l''intérieur."]', true, '["Stand with feet hip-width apart and engage your core for stability", "Step your right foot back 2-3 feet, lowering your hips until both knees are bent at approximately 90 degrees", "Keep your front knee aligned over your ankle and avoid letting it drift inward", "Push through your front heel to return to standing while simultaneously driving your back knee up toward your chest", "Lower the raised leg back to starting position and repeat the movement with the opposite leg", "Maintain an upright torso throughout the entire movement sequence"]', '["Tiens-toi droit avec les pieds écartés à la largeur des hanches et engage ton ventre pour plus de stabilité.", "Recule ton pied droit de 60 à 90 cm, en fléchissant les deux genoux à environ 90 degrés.", "Veille à ce que ton genou avant soit aligné avec ta cheville et évite qu''il ne s''incline vers l''intérieur.", "Pousse à travers ton talon avant pour revenir en position debout tout en montant le genou arrière vers ta poitrine.", "Ramène la jambe levée à la position de départ et répète avec l''autre jambe.", "Garde le torse droit tout au long du mouvement."]', '["Concentre ton poids sur ta jambe avant pendant la fente pour activer tes quadriceps au maximum.", "Monte le genou avec contrôle plutôt qu''avec élan pour maintenir ton équilibre et ta forme correcte.", "Assure-toi que ton genou avant suit la ligne de tes orteils et ne s''écroule pas pendant la fente.", "Travaille sur une transition fluide entre la fente et la montée de genou sans pause.", "Atterris en douceur lors de la fente pour réduire l''impact sur tes articulations."]', '["Keep most of your weight on your front leg during the lunge portion to maximize quad activation", "Drive the knee up with control rather than momentum to maintain balance and proper form", "Ensure your front knee tracks in line with your toes and doesn''t cave inward during the lunge", "Focus on a smooth transition from the lunge to the knee drive without pausing between movements", "Land softly when stepping back into the lunge to reduce impact on your joints"]', '808799af-013a-4f71-94e7-3fdea59b9ecf', 'reverse-lunge-to-knee-drive', NULL, NULL);
INSERT INTO public.exercises VALUES ('f3317a32-3e6b-4f3d-9115-886dc0c9642e', 'Skullcrushers en position hollow body', NULL, NULL, 'Hollow body skullcrushers', 'Abs', '[]', 'Abs', 'Advanced', 16, '/videos/abs/hollow-body-skullcrushers.mp4', NULL, NULL, NULL, '/videos/thumbnails/hollow-body-skullcrushers.jpg', NULL, '["Presser ton bas du dos contre le sol à tout moment pour éviter les blessures et maximiser l''engagement du core", "Déplace tes bras lentement et avec contrôle pour maintenir la bonne forme et augmenter le temps sous tension", "Maintenir la position hollow body durant l''ensemble de l''exercice sans laisser tes épaules ou tes pieds toucher le sol", "Si tu ressens une tension dans le cou, garde ta tête dans une position neutre au lieu de la soulever vers tes genoux", "Commence par des temps de maintien plus courts et moins de répétitions, et augmente progressivement au fur et à mesure que ta force au core s''améliore"]', '["Ne pas maintenir le bas du dos collé au sol", "Cambrer le dos pendant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "hollow body skullcrushers"]', true, '2026-04-03 12:24:57.179737+00', '2026-04-03 12:24:57.179737+00', 'Allonge-toi sur le dos, les bras étendus au-dessus de ta tête, le bas du dos bien collé au sol, et les jambes relevées avec les genoux fléchis à 90 degrés. Crée une position hollow body pour renforcer ton centre.', '["Ne pas maintenir le bas du dos collé au sol", "Cambrer le dos pendant le mouvement"]', true, '["Lie flat on your back and press your lower back firmly into the floor", "Extend your arms straight overhead and lift your legs with knees bent at 90 degrees", "Engage your core to create a hollow body position with shoulders and feet off the ground", "Bring your arms forward in a controlled arc motion toward your knees without letting your back arch", "Slowly return your arms overhead while maintaining the hollow body position", "Keep your core tight and breathing steady throughout the entire movement"]', '["Allonge-toi à plat sur le dos et presse ton bas du dos contre le sol", "Étends tes bras droits au-dessus de ta tête et lève tes jambes, en gardant les genoux fléchis à 90 degrés", "Engage ton core pour maintenir la position hollow body, avec les épaules et les pieds décollés du sol", "Amène tes bras en avant dans un mouvement contrôlé vers tes genoux sans cambrer le dos", "Ramène lentement tes bras au-dessus de ta tête tout en maintenant la position hollow", "Garde ton core bien engagé et ta respiration régulière pendant tout l''exercice"]', '["Presser ton bas du dos contre le sol à tout moment pour éviter les blessures et maximiser l''engagement du core", "Déplace tes bras lentement et avec contrôle pour maintenir la bonne forme et augmenter le temps sous tension", "Maintenir la position hollow body durant l''ensemble de l''exercice sans laisser tes épaules ou tes pieds toucher le sol", "Si tu ressens une tension dans le cou, garde ta tête dans une position neutre au lieu de la soulever vers tes genoux", "Commence par des temps de maintien plus courts et moins de répétitions, et augmente progressivement au fur et à mesure que ta force au core s''améliore"]', '["Keep your lower back pressed to the floor at all times to prevent injury and maximize core engagement", "Move your arms slowly and with control to maintain proper form and increase time under tension", "Maintain the hollow body position throughout the entire exercise without letting your shoulders or feet touch the ground", "If you experience neck strain, focus on keeping your head in a neutral position rather than lifting it toward your knees", "Start with shorter holds and fewer repetitions, gradually increasing as your core strength improves"]', '7829eabb-e6e5-467a-807a-0c5c65ebf49e', 'hollow-body-skullcrushers', NULL, NULL);
INSERT INTO public.exercises VALUES ('9a2504ee-20e5-4133-933d-8ac88f094194', 'Inchworms avec pompes et pompes pike', NULL, NULL, 'Inchworms to push ups to pike push up', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/inchworms-to-push-ups-to-pike-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/inchworms-to-push-ups-to-pike-push-up.jpg', NULL, '["Garde ton cœur contracté tout au long de l''exercice pour protéger ton bas du dos.", "Assure-toi que tes mains sont légèrement plus larges que tes épaules pour un bon alignement pendant les pompes.", "Dans la position de pike, concentre-toi sur le fait de pousser tes hanches vers le haut et vers l''arrière pour former un V inversé.", "Commence par des mouvements lents et contrôlés, puis augmente progressivement la vitesse au fur et à mesure que tu construis ta force et ta coordination.", "Si les pompes classiques sont trop difficiles, n''hésite pas à poser les genoux au sol pendant l''exercice."]', '["Ne pas garder le dos droit pendant les mouvements which can lead to injuries.", "Ne pas contracter le cœur, ce qui favorise une mauvaise posture."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "inchworms to push ups to pike push up"]', true, '2026-04-03 12:24:57.221508+00', '2026-04-03 12:24:57.221508+00', 'Prépare-toi à faire travailler ta poitrine tout en te renforçant. Commence debout, pieds à la largeur des hanches, et suis ces étapes.', '["Ne pas garder le dos droit pendant les mouvements which can lead to injuries.", "Ne pas contracter le cœur, ce qui favorise une mauvaise posture."]', true, '["Begin standing with feet hip-width apart, then hinge at the hips and place your hands on the floor", "Walk your hands forward into a high plank position, keeping your core engaged and body in a straight line", "Perform one standard push-up by lowering your chest to the floor and pressing back up", "Walk your feet forward toward your hands while keeping your legs straight until you reach a pike position", "Perform one pike push-up by lowering the top of your head toward the floor and pressing back up", "Walk your hands back out to plank, then walk your feet back to return to standing position"]', '["Commence debout, les pieds à la largeur des hanches, puis penche-toi en avant et pose tes mains au sol.", "Marche tes mains vers l''avant jusqu''à atteindre une position de planche, le corps bien droit et le cœur engagé.", "Effectue une pompe classique en abaissant ta poitrine vers le sol, puis remonte.", "Marche tes pieds vers tes mains en gardant les jambes droites jusqu''à adopter une position de pike.", "Effectue une pompe pike en abaissant le sommet de ta tête vers le sol, puis remonte.", "Marche à nouveau tes mains vers la planche, puis ramène tes pieds pour revenir en position debout."]', '["Garde ton cœur contracté tout au long de l''exercice pour protéger ton bas du dos.", "Assure-toi que tes mains sont légèrement plus larges que tes épaules pour un bon alignement pendant les pompes.", "Dans la position de pike, concentre-toi sur le fait de pousser tes hanches vers le haut et vers l''arrière pour former un V inversé.", "Commence par des mouvements lents et contrôlés, puis augmente progressivement la vitesse au fur et à mesure que tu construis ta force et ta coordination.", "Si les pompes classiques sont trop difficiles, n''hésite pas à poser les genoux au sol pendant l''exercice."]', '["Keep your core tight throughout the entire movement to protect your lower back", "Maintain proper push-up form with hands positioned slightly wider than shoulder-width", "In the pike position, focus on pressing your hips up and back to create an inverted V shape", "Start with slower, controlled movements and gradually increase pace as you build strength and coordination", "If standard push-ups are too challenging, drop to your knees during the push-up portions"]', '21ce1e16-e426-466b-b8cf-9d4b1fce7227', 'inchworms-to-push-ups-to-pike-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('2f78fc22-2601-41a4-a57d-3add67e030ef', 'Squat avec haltère', NULL, 'غسقة مع الدمبل', 'Dumbbell Squat', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 2, '/videos/quadriceps/dumbbell-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-squat.jpg', NULL, '["Assurez-vous que vos genoux suivent la ligne de vos orteils pour éviter qu''ils ne s''effondrent vers l''intérieur.", "Maintenez une colonne vertébrale neutre et évitez d''arrondir le dos.", "Concentrez-vous à garder le poids sur vos talons plutôt que sur vos orteils.", "Contrôlez la descente et évitez de rebondir au fond du mouvement.", "Gardez l''haltère près de votre corps pour maintenir un bon équilibre."]', '["Ne pas tenir l''haltère suffisamment près du corps.", "Descendre trop bas et perdre le contrôle ou la forme."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell squat"]', true, '2026-04-03 12:24:56.612059+00', '2026-04-03 12:24:56.612059+00', 'Position de départ : Écartez les pieds à la largeur des épaules, un haltère en main de chaque côté. Exécution : Baissez-vous en pliant les hanches et les genoux jusqu''à ce que vos cuisses soient parallèles au sol, puis poussez sur vos talons pour revenir à la position de départ.', '["Ne pas tenir l''haltère suffisamment près du corps.", "Descendre trop bas et perdre le contrôle ou la forme."]', true, '["Stand with feet shoulder-width apart and hold a dumbbell securely with both hands at your sides.", "Keep your chest up, shoulders back, and core engaged throughout the movement", "Initiate the squat by pushing your hips back and bending your knees", "Lower your body until your thighs are parallel to the floor or as low as your mobility allows", "Drive through your heels and squeeze your glutes to return to the starting position", "Maintain control of the dumbbell throughout the entire movement"]', '["Écartez les pieds à la largeur des épaules et tenez fermement un haltère de chaque côté.", "Gardez le torse droit, les épaules en arrière et les abdominaux contractés tout au long de l''exercice.", "Commencez le squat en poussant les hanches vers l''arrière et en pliant les genoux.", "Descendez jusqu''à ce que vos cuisses soient parallèles au sol ou selon votre mobilité.", "Poussez sur vos talons et serrez les fessiers pour revenir à la position de départ.", "Contrôlez l''haltère durant tout le mouvement."]', '["Assurez-vous que vos genoux suivent la ligne de vos orteils pour éviter qu''ils ne s''effondrent vers l''intérieur.", "Maintenez une colonne vertébrale neutre et évitez d''arrondir le dos.", "Concentrez-vous à garder le poids sur vos talons plutôt que sur vos orteils.", "Contrôlez la descente et évitez de rebondir au fond du mouvement.", "Gardez l''haltère près de votre corps pour maintenir un bon équilibre."]', '["Keep your knees tracking in line with your toes to prevent inward collapse", "Maintain a neutral spine and avoid rounding your back", "Keep most of your weight on your heels rather than your toes", "Control the descent and avoid bouncing at the bottom of the movement", "Keep the dumbbell close to your body to maintain proper balance"]', '0de79ddc-e829-4543-942c-e385cc76ac5e', 'dumbbell-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('0830eb33-21df-4b7b-a952-000466b7b795', 'Soulevé de terre avec barre', NULL, NULL, 'Barbell Good Morning', 'Hamstrings', '[]', 'Hamstrings', 'Intermediate', 1, '/videos/hamstrings/barbell-good-morning.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-good-morning.jpg', NULL, '["Gardez vos genoux légèrement fléchis durant tout le mouvement pour protéger vos articulations du genou", "Concentrez-vous sur le mouvement de basculement des hanches plutôt que sur une flexion au niveau de la taille pour cibler correctement les ischio-jambiers", "Gardez une colonne vertébrale neutre et évitez de courber le dos, surtout en bas du mouvement", "Commencez avec un poids léger pour maîtriser le mouvement avant de passer à des charges plus lourdes", "Arrêtez la descente lorsque vous sentez un bon étirement dans vos ischio-jambiers plutôt que de forcer un excès d''amplitude"]', '["Ne pas garder le dos droit pendant le mouvement", "Forcer un étirement excessif sans respecter l''amplitude sécuritaire"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "barbell", "barbell good morning"]', true, '2026-04-03 12:24:55.581374+00', '2026-04-03 12:24:55.581374+00', 'Position de départ : Tenez-vous debout avec la barre reposant sur le haut de votre dos, les pieds écartés à la largeur des épaules. Exécution : Inclinez-vous en avant au niveau des hanches tout en gardant le dos droit et les genoux légèrement fléchis, puis revenez lentement à la position de départ.', '["Ne pas garder le dos droit pendant le mouvement", "Forcer un étirement excessif sans respecter l''amplitude sécuritaire"]', true, '["Position the barbell across your upper traps and grip it with hands wider than shoulder-width apart", "Stand with feet hip-width apart, knees slightly bent, and core engaged", "Initiate the movement by pushing your hips back while keeping your chest up and spine neutral", "Lower your torso forward until you feel a good stretch in your hamstrings, typically to about 45-degree angle", "Drive your hips forward and squeeze your glutes to return to the upright starting position", "Maintain control throughout the entire range of motion"]', '["Placez la barre sur vos trapèzes supérieurs et saisissez-la avec des mains plus larges que la largeur des épaules", "Positionnez-vous avec les pieds écartés à la largeur des hanches, genoux légèrement fléchis et le core engagé", "Initiez le mouvement en poussant vos hanches en arrière tout en gardant la poitrine haute et la colonne vertébrale neutre", "Abaissez votre torse en avant jusqu''à sentir un bon étirement dans vos ischio-jambiers, généralement jusqu''à un angle de 45 degrés", "Ramenez vos hanches en avant et contractez vos fessiers pour revenir à la position droite de départ", "Maintenez le contrôle tout au long du mouvement"]', '["Gardez vos genoux légèrement fléchis durant tout le mouvement pour protéger vos articulations du genou", "Concentrez-vous sur le mouvement de basculement des hanches plutôt que sur une flexion au niveau de la taille pour cibler correctement les ischio-jambiers", "Gardez une colonne vertébrale neutre et évitez de courber le dos, surtout en bas du mouvement", "Commencez avec un poids léger pour maîtriser le mouvement avant de passer à des charges plus lourdes", "Arrêtez la descente lorsque vous sentez un bon étirement dans vos ischio-jambiers plutôt que de forcer un excès d''amplitude"]', '["Keep your knees slightly bent throughout the movement to protect your knee joints", "Focus on the hip hinge movement pattern rather than bending at the waist to properly target the hamstrings", "Maintain a neutral spine and avoid rounding your back, especially at the bottom of the movement", "Start with lighter weight to master the movement pattern before progressing to heavier loads", "Stop the descent when you feel a good stretch in your hamstrings rather than forcing excessive range of motion"]', '74c36be0-d1e4-4703-8c54-612c2da1dcc1', 'barbell-good-morning', NULL, NULL);
INSERT INTO public.exercises VALUES ('cd66ea18-2728-4600-a4d8-5f87822d3dce', 'Développé couché incliné avec barre', NULL, 'الضغط المائل بالبار', 'Incline Barbell Press', 'Chest', '[]', 'Chest', 'Intermediate', 1, '/videos/chest/incline-barbell-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-barbell-press.jpg', NULL, '["Gardez vos épaules en arrière et vers le bas durant tout le mouvement pour assurer la stabilité", "Concentrez-vous sur le contrôle du poids pendant la phase de descente, ne laissez pas tomber rapidement", "Poussez la barre dans un mouvement légèrement arc de cercle pour suivre le schéma de mouvement naturel", "Maintenez la tension dans votre tronc et gardez vos pieds bien ancrés au sol pour la stabilité", "Évitez de rebondir la barre sur votre poitrine ou d''utiliser un élan excessif pour effectuer les répétitions"]', '["Ne pas stabiliser les épaules", "Élever les fesses du banc pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "barbell", "incline barbell press"]', true, '2026-04-03 12:24:57.24374+00', '2026-04-03 12:24:57.24374+00', 'Position de départ : Allongez-vous sur un banc incliné avec la barre en mains, bras tendus vers le haut en prise pronation. Exécution : Descendez la barre jusqu''à votre poitrine, puis poussez-la vers le haut pour revenir à la position de départ.', '["Ne pas stabiliser les épaules", "Élever les fesses du banc pendant l''exercice"]', true, '["Set the incline bench to a 30-45 degree angle and position yourself with your back flat against the pad", "Grip the barbell with hands slightly wider than shoulder-width apart using an overhand grip", "Unrack the barbell and position it directly above your upper chest with arms extended", "Lower the barbell slowly and under control until it lightly touches your upper chest near the collarbone", "Press the barbell back up to the starting position by driving through your chest and shoulders", "Re-rack the barbell safely when your set is complete"]', '["Réglez le banc incliné à un angle de 30 à 45 degrés et positionnez-vous avec le dos bien à plat contre le rembourrage", "Saisissez la barre avec une prise légèrement plus large que la largeur des épaules", "Déchargez la barre et placez-la directement au-dessus de votre poitrine supérieure, bras tendus", "Abaissez la barre lentement et sous contrôle jusqu''à ce qu''elle touche légèrement votre poitrine supérieure près de la clavicule", "Poussez la barre vers le haut en appuyant à travers votre poitrine et vos épaules", "Ranger la barre en toute sécurité une fois votre série terminée"]', '["Gardez vos épaules en arrière et vers le bas durant tout le mouvement pour assurer la stabilité", "Concentrez-vous sur le contrôle du poids pendant la phase de descente, ne laissez pas tomber rapidement", "Poussez la barre dans un mouvement légèrement arc de cercle pour suivre le schéma de mouvement naturel", "Maintenez la tension dans votre tronc et gardez vos pieds bien ancrés au sol pour la stabilité", "Évitez de rebondir la barre sur votre poitrine ou d''utiliser un élan excessif pour effectuer les répétitions"]', '["Keep your shoulder blades pulled back and down throughout the entire movement to maintain stability", "Focus on controlling the weight during the lowering phase rather than letting it drop quickly", "Press the barbell in a slight arc motion rather than straight up and down to follow the natural movement pattern", "Maintain tension in your core and keep your feet planted firmly on the ground for stability", "Avoid bouncing the barbell off your chest or using excessive momentum to complete repetitions"]', '25be107f-a9ec-4007-bb9f-c0a5088e19b5', 'incline-barbell-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('cb28c1ea-15bc-4df4-b876-ff620abc41a9', 'Crossover haltères incliné', NULL, 'Crossover des haltères en inclinaison', 'Incline Dumbbell Crossover', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/incline-dumbbell-crossover.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-dumbbell-crossover.jpg', NULL, '["Garde une légère flexion au niveau des coudes pendant tout le mouvement pour protéger tes articulations et maintenir la tension sur les pectoraux", "Concentre-toi sur le ressenti de l''étirement dans ta poitrine en bas du mouvement plutôt que d''essayer de toucher les haltères avec tes épaules", "Contrôle le poids durant les phases de descente et de montée pour maximiser l''engagement musculaire et éviter les blessures", "Maintiens tes épaules tirées en arrière et vers le bas contre le banc pour préserver une bonne posture et éviter les douleurs aux épaules", "Choisis un poids qui te permet de conserver une bonne forme pendant toutes les répétitions, plutôt que de prendre trop lourd."]', '["Ne pas contrôler le mouvement lors de la descente", "Trop cambrer le dos au lieu de garder une posture neutre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "incline dumbbell crossover"]', true, '2026-04-03 12:24:57.265115+00', '2026-04-03 12:24:57.265115+00', 'Position de départ : Allonge-toi sur un banc incliné avec un haltère dans chaque main. Exécution : Croise les haltères devant ta poitrine en contractant tes muscles pectoraux, puis reviens à la position de départ.', '["Ne pas contrôler le mouvement lors de la descente", "Trop cambrer le dos au lieu de garder une posture neutre"]', true, '["Set the incline bench to a 30-45 degree angle and select appropriate weight dumbbells", "Lie back on the bench with your feet firmly planted on the floor and core engaged", "Hold dumbbells above your chest with arms extended and palms facing each other, maintaining a slight bend in your elbows", "Lower the weights in a controlled arc motion by opening your arms wide until you feel a good stretch in your chest muscles", "Squeeze your chest muscles to bring the dumbbells back together in a hugging motion above your chest", "Complete the desired number of repetitions while maintaining control throughout the entire range of motion"]', '["Régle le banc incliné à un angle de 30 à 45 degrés et choisis des haltères à un poids adapté", "Allonge-toi sur le banc, les pieds bien ancrés au sol, le gainage actif", "Tiens les haltères au-dessus de ta poitrine, bras tendus et paumes face à face, en gardant une légère flexion au niveau des coudes", "Abaisse les poids de manière contrôlée en écartant les bras jusqu''à sentir un bon étirement des pectoraux", "Contracte tes muscles pectoraux pour ramener les haltères ensemble en un mouvement d''enlacement au-dessus de ta poitrine", "Effectue le nombre de répétitions souhaité tout en maintenant le contrôle tout au long du mouvement"]', '["Garde une légère flexion au niveau des coudes pendant tout le mouvement pour protéger tes articulations et maintenir la tension sur les pectoraux", "Concentre-toi sur le ressenti de l''étirement dans ta poitrine en bas du mouvement plutôt que d''essayer de toucher les haltères avec tes épaules", "Contrôle le poids durant les phases de descente et de montée pour maximiser l''engagement musculaire et éviter les blessures", "Maintiens tes épaules tirées en arrière et vers le bas contre le banc pour préserver une bonne posture et éviter les douleurs aux épaules", "Choisis un poids qui te permet de conserver une bonne forme pendant toutes les répétitions, plutôt que de prendre trop lourd."]', '["Keep a slight bend in your elbows throughout the movement to protect your joints and maintain tension on the chest muscles", "Focus on feeling the stretch in your chest at the bottom of the movement rather than trying to touch the dumbbells to your shoulders", "Control the weight on both the lowering and lifting phases to maximize muscle engagement and prevent injury", "Keep your shoulders pulled back and down against the bench to maintain proper positioning and prevent shoulder impingement", "Use a weight that allows you to maintain proper form throughout all repetitions rather than going too heavy"]', '6a3ac67c-fa0f-4ef1-91c7-aa2503d11844', 'incline-dumbbell-crossover', NULL, NULL);
INSERT INTO public.exercises VALUES ('018dfbaa-70bc-4a4b-bd2e-a74aadc8a603', 'Développé couché incliné avec haltères', NULL, 'Pression d''inclinaison avec haltères', 'Incline Dumbbell Press', 'Chest', '[]', 'Chest', 'Beginner', 2, '/videos/chest/incline-dumbbell-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-dumbbell-press.jpg', NULL, '["Maintenez vos homoplates rétractées et pressées contre le banc durant tout le mouvement", "Évitez de rebondir avec les poids en bas pour prévenir les blessures et maintenir la tension musculaire", "Utilisez une amplitude complète sans descendre les poids au-delà d''un étirement confortable dans votre poitrine", "Gardez une légère flexion au niveau des coudes en haut, sans les verrouiller complètement", "Choisissez un poids qui vous permet de réaliser toutes les répétitions avec la bonne forme plutôt que d''utiliser le poids maximum"]', '["S''éloigner du dossier du banc pendant l''exercice", "Descendre les haltères trop bas en négligeant la technique"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "incline dumbbell press"]', true, '2026-04-03 12:24:57.286883+00', '2026-04-03 12:24:57.286883+00', 'Position de départ : Allongez-vous sur un banc incliné avec un haltère dans chaque main, bras tendus vers le haut et paumes face à vous. Exécution : Abaissez les haltères vers votre poitrine, puis poussez vers le haut pour revenir à la position de départ.', '["S''éloigner du dossier du banc pendant l''exercice", "Descendre les haltères trop bas en négligeant la technique"]', true, '["Set the incline bench to a 30-45 degree angle and sit with your back firmly pressed against the pad", "Hold a dumbbell in each hand and position them at chest level with palms facing forward", "Plant your feet firmly on the floor and engage your core for stability", "Lower the dumbbells slowly in an arc motion until they reach chest level, feeling a stretch in your chest", "Press the weights back up along the same path, focusing on squeezing your chest muscles", "Complete the desired number of repetitions while maintaining controlled movement throughout"]', '["Réglez le banc incliné à un angle de 30 à 45 degrés et installez-vous avec le dos bien appuyé contre le dossier", "Tenez un haltère dans chaque main, positionnez-les au niveau de la poitrine avec les paumes face à vous", "Ancrez vos pieds fermement au sol et engagez votre sangle abdominale pour la stabilité", "Abaissez les haltères lentement en arc jusqu''à la hauteur de la poitrine, en ressentant l''étirement dans votre poitrine", "Poussez les poids vers le haut en suivant le même chemin, en vous concentrant sur la contraction de vos muscles pectoraux", "Effectuez le nombre de répétitions désiré tout en maintenant un mouvement contrôlé tout au long de l''exercice"]', '["Maintenez vos homoplates rétractées et pressées contre le banc durant tout le mouvement", "Évitez de rebondir avec les poids en bas pour prévenir les blessures et maintenir la tension musculaire", "Utilisez une amplitude complète sans descendre les poids au-delà d''un étirement confortable dans votre poitrine", "Gardez une légère flexion au niveau des coudes en haut, sans les verrouiller complètement", "Choisissez un poids qui vous permet de réaliser toutes les répétitions avec la bonne forme plutôt que d''utiliser le poids maximum"]', '["Keep your shoulder blades retracted and pressed against the bench throughout the entire movement", "Avoid bouncing the weights at the bottom position to prevent injury and maintain muscle tension", "Use a full range of motion but don''t lower the weights beyond a comfortable stretch in your chest", "Maintain a slight bend in your elbows at the top position rather than locking them out completely", "Choose a weight that allows you to complete all repetitions with proper form rather than using maximum weight"]', '8ef75730-0d30-4063-b6ff-242725cf8c29', 'incline-dumbbell-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('55aabbf3-aae0-4721-a42e-23e0f6bbdf38', 'Tirage Incliné avec Haltères', NULL, NULL, 'Incline Dumbbell Row', 'Back', '[]', 'Back', 'Intermediate', 2, '/videos/back/incline-dumbbell-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-dumbbell-row.jpg', NULL, '["Gardez votre poitrine en contact avec le banc durant tout le mouvement pour une bonne alignement de la colonne vertébrale.", "Concentrez-vous sur le tirage avec vos muscles du dos plutôt qu''avec vos bras en commençant le mouvement avec vos omoplates.", "Évitez d''utiliser l''élan ou de balancer les poids - contrôlez le tempo dans les deux phases, la montée et la descente.", "Gardez vos épaules abaissées et reculer, évitez de hausser les épaules pendant l''exercice.", "Choisissez un poids qui vous permet de maintenir une bonne forme sur toutes les répétitions."]', '["Ne pas garder le dos droit.", "Utiliser trop de poids, ce qui entraîne une mauvaise forme."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "incline dumbbell row"]', true, '2026-04-03 12:24:57.307599+00', '2026-04-03 12:24:57.307599+00', 'Position de départ : allongez-vous face contre la banquette inclinée avec un haltère dans chaque main, les bras suspendus vers le bas. Exécution : tirez les haltères vers les côtés de votre poitrine en gardant le dos droit, puis baissez-les lentement jusqu''à la position de départ.', '["Ne pas garder le dos droit.", "Utiliser trop de poids, ce qui entraîne une mauvaise forme."]', true, '["Set an adjustable bench to a 30-45 degree incline and lie face down with your chest supported against the pad", "Hold a dumbbell in each hand with a neutral grip, allowing your arms to hang straight down", "Plant your feet firmly on the floor for stability and engage your core", "Pull the dumbbells up by driving your elbows back and squeezing your shoulder blades together", "Hold the contraction briefly at the top, then slowly lower the weights back to the starting position", "Maintain control throughout the entire range of motion"]', '["Réglez un banc réglable à une inclinaison de 30 à 45 degrés et allongez-vous face contre la banquette avec la poitrine soutenue par le rembourrage.", "Tenez un haltère dans chaque main avec une prise neutre, les bras pendants.", "Ancrez vos pieds fermement au sol pour la stabilité et engagez votre sangle abdominale.", "Tirez les haltères en poussant vos coudes vers l''arrière et en serrant vos omoplates ensemble.", "Maintenez la contraction brièvement au sommet, puis abaissez lentement les poids jusqu''à la position de départ.", "Gardez le contrôle tout au long de l''exercice."]', '["Gardez votre poitrine en contact avec le banc durant tout le mouvement pour une bonne alignement de la colonne vertébrale.", "Concentrez-vous sur le tirage avec vos muscles du dos plutôt qu''avec vos bras en commençant le mouvement avec vos omoplates.", "Évitez d''utiliser l''élan ou de balancer les poids - contrôlez le tempo dans les deux phases, la montée et la descente.", "Gardez vos épaules abaissées et reculer, évitez de hausser les épaules pendant l''exercice.", "Choisissez un poids qui vous permet de maintenir une bonne forme sur toutes les répétitions."]', '["Keep your chest pressed against the bench throughout the movement to maintain proper spinal alignment", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Avoid using momentum or swinging the weights - control the tempo on both the lifting and lowering phases", "Keep your shoulders down and back, avoiding any shrugging motion during the exercise", "Choose a weight that allows you to maintain proper form for all repetitions"]', '812f7c37-8718-4fa6-8ad2-9c1080da9873', 'incline-dumbbell-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('6d40d1d0-e051-4c37-9431-c70a43102754', 'Fente avant et arrière', NULL, NULL, 'Forward and backward lunge', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/forward-and-backward-lunge.mp4', NULL, NULL, NULL, '/videos/thumbnails/forward-and-backward-lunge.jpg', NULL, '["Assure-toi que ton genou avant reste aligné avec ta cheville, sans dépasser les orteils.", "Garde le torse bien droit tout au long du mouvement pour éviter de pencher en avant.", "Répartis bien ton poids entre les deux jambes pendant la descente.", "Contrôle bien la descente, évite de rebondir en bas du mouvement.", "Commence par des pas plus courts et augmente progressivement l''amplitude de mouvement au fur et à mesure que ta souplesse s''améliore."]', '["Pencher le torse en avant pendant l''exercice.", "Laisser le genou avant dépasser les orteils."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "forward and backward lunge"]', true, '2026-04-03 12:24:56.760894+00', '2026-04-03 12:24:56.760894+00', 'Exercice idéal pour renforcer les quadriceps et améliorer la stabilité !', '["Pencher le torse en avant pendant l''exercice.", "Laisser le genou avant dépasser les orteils."]', true, '["Stand tall with feet hip-width apart and engage your core for stability", "For forward lunge, step one foot forward 2-3 feet, keeping your torso upright", "Lower your body by bending both knees until your front thigh is parallel to the floor and back knee nearly touches the ground", "Push through your front heel to return to the starting position", "For backward lunge, step one foot back 2-3 feet and follow the same lowering and rising motion", "Alternate legs or complete all reps on one side before switching"]', '["Tiens-toi droit, pieds écartés à la largeur des hanches, engage ton tronc pour la stabilité.", "Pour la fente avant, fais un pas de 60 à 90 cm en gardant le torse droit.", "Descends en pliant les deux genoux jusqu''à ce que la cuisse avant soit parallèle au sol et que le genou arrière frôle le sol.", "Pousse avec le talon avant pour revenir à la position de départ.", "Pour la fente arrière, fais un pas de 60 à 90 cm en arrière et suis le même mouvement de descente et de remontée.", "Alterne les jambes ou fais toutes les répétitions d''un côté avant de changer."]', '["Assure-toi que ton genou avant reste aligné avec ta cheville, sans dépasser les orteils.", "Garde le torse bien droit tout au long du mouvement pour éviter de pencher en avant.", "Répartis bien ton poids entre les deux jambes pendant la descente.", "Contrôle bien la descente, évite de rebondir en bas du mouvement.", "Commence par des pas plus courts et augmente progressivement l''amplitude de mouvement au fur et à mesure que ta souplesse s''améliore."]', '["Keep your front knee aligned over your ankle, never allowing it to push forward past your toes", "Maintain an upright torso throughout the movement to avoid leaning forward", "Distribute weight evenly between both legs during the lowering phase", "Control the descent and avoid bouncing at the bottom of the movement", "Start with shorter steps and gradually increase range of motion as flexibility improves"]', 'b3fdc5d4-1225-4f12-8b42-86fc0617aeb6', 'forward-and-backward-lunge', NULL, NULL);
INSERT INTO public.exercises VALUES ('bde31c96-e4b2-40ce-887a-e7197cd7029c', 'Presse à jambes horizontale', NULL, NULL, 'Horizontal Leg Press', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/horizontal-leg-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/horizontal-leg-press.jpg', NULL, '["Garde tes genoux alignés avec tes orteils durant tout le mouvement pour éviter de forcer sur les genoux.", "Évite de placer tes pieds trop haut ou trop bas sur la plateforme, sinon l''accent sera mis ailleurs que sur les quadriceps.", "Ne laisse jamais ton bas du dos se cambrer ou se soulever du dossier pendant l''exercice.", "Contrôle la descente du poids plutôt que de le laisser tomber rapidement.", "Commence avec un poids léger pour maîtriser la forme avant d''augmenter progressivement le charge."]', '["Ne pas engager le core, ce qui peut entraîner une mauvaise posture.", "Bloquer complètement les genoux à l''extension, risquant ainsi des blessures."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "horizontal leg press"]', true, '2026-04-03 12:24:57.194162+00', '2026-04-03 12:24:57.194162+00', 'Position de départ : Installe-toi sur la machine de presse à jambes horizontale avec les pieds sur la plateforme et les genoux fléchis. Exécution : Pousse la plateforme vers le haut en étendant complètement les jambes, puis redescends lentement à la position de départ.', '["Ne pas engager le core, ce qui peut entraîner une mauvaise posture.", "Bloquer complètement les genoux à l''extension, risquant ainsi des blessures."]', true, '["Adjust the seat and backrest so your knees form a 90-degree angle when feet are positioned on the footplate", "Place feet shoulder-width apart on the footplate with toes pointing slightly outward", "Grip the side handles for stability and keep your core engaged throughout the movement", "Push through your heels to extend your legs, avoiding locking your knees completely at the top", "Lower the weight slowly and under control until your knees return to the 90-degree starting position", "Maintain steady breathing, exhaling during the push phase and inhaling during the return"]', '["Régle le siège et le dossier pour que tes genoux forment un angle de 90 degrés lorsque tes pieds sont sur la plateforme.", "Positionne tes pieds à largeur d''épaules sur la plateforme, avec les orteils légèrement vers l''extérieur.", "Saisis les poignées sur les côtés pour plus de stabilité et engage ton corps durant le mouvement.", "Pousse avec les talons pour étendre les jambes, en évitant de bloquer complètement les genoux en haut.", "Abaisse le poids lentement et de manière contrôlée jusqu''à ramener tes genoux à la position de départ à 90 degrés.", "Respire régulièrement, en expirant durant la phase de poussée et en inspirant lors du retour."]', '["Garde tes genoux alignés avec tes orteils durant tout le mouvement pour éviter de forcer sur les genoux.", "Évite de placer tes pieds trop haut ou trop bas sur la plateforme, sinon l''accent sera mis ailleurs que sur les quadriceps.", "Ne laisse jamais ton bas du dos se cambrer ou se soulever du dossier pendant l''exercice.", "Contrôle la descente du poids plutôt que de le laisser tomber rapidement.", "Commence avec un poids léger pour maîtriser la forme avant d''augmenter progressivement le charge."]', '["Keep your knees aligned with your toes throughout the entire range of motion to prevent knee strain", "Avoid placing your feet too high or too low on the footplate as this can shift emphasis away from the quadriceps", "Never allow your lower back to round or lift off the backrest during the movement", "Control the negative portion of the lift rather than allowing the weight to drop quickly", "Start with lighter weight to master proper form before progressively increasing the load"]', 'bc8a31d3-6f32-4f5d-a0c9-9935e76b2071', 'horizontal-leg-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('ab8f7f7c-acac-48b2-9649-b79a601856b8', 'Squat Goblet avec Kettlebell', NULL, 'سكوات غوبليه بالكيتلبيل', 'Goblet Squat with Kettlebell', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 128, '/videos/quadriceps/goblet-squat-with-kettlebell.mp4', NULL, NULL, NULL, '/videos/thumbnails/goblet-squat-with-kettlebell.jpg', NULL, '["Comme pour le squat goblet avec haltères", "Le contrebalancement aide à la profondeur", "Les coudes peuvent pousser les genoux vers l''extérieur", "Garde la poitrine fière", "Excellent pour les débutants"]', '["Ne pas baisser suffisamment", "Les genoux qui se déplacent vers l''intérieur", "Le tronc affaissé", "Les talons qui se soulèvent", "Regard vers le bas"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "kettlebell", "goblet squat with kettlebell"]', true, '2026-04-03 12:24:56.846133+00', '2026-04-03 12:24:56.846133+00', 'Position de départ : Tiens-toi debout, les pieds un peu plus larges que la largeur des épaules, en tenant le kettlebell par les cornes, à hauteur de poitrine, les coudes dirigés vers le bas. Exécution : Abaisse ton corps en poussant les hanches en arrière et en fléchissant les genoux jusqu''à ce que tes cuisses soient parallèles au sol, puis pousse sur tes talons pour revenir à la position de départ.', '["Ne pas baisser suffisamment", "Les genoux qui se déplacent vers l''intérieur", "Le tronc affaissé", "Les talons qui se soulèvent", "Regard vers le bas"]', true, '["Hold kettlebell at chest by horns", "Feet shoulder-width or wider", "Squat down between legs", "Keep chest up, elbows inside knees", "Drive up through heels"]', '["Tiens le kettlebell à la poitrine par les cornes", "Pieds à la largeur des épaules ou plus", "Accroupis-toi entre les jambes", "Garde la poitrine bien droite, coudes à l''intérieur des genoux", "Pousse avec les talons pour remonter"]', '["Comme pour le squat goblet avec haltères", "Le contrebalancement aide à la profondeur", "Les coudes peuvent pousser les genoux vers l''extérieur", "Garde la poitrine fière", "Excellent pour les débutants"]', '["Same as dumbbell goblet squat", "Counterbalance helps depth", "Elbows can push knees out", "Keep chest proud", "Great for beginners"]', '54df7bb8-18f9-4b69-8561-f369f06632ee', 'goblet-squat-with-kettlebell', NULL, NULL);
INSERT INTO public.exercises VALUES ('e5c40524-fe64-4ef0-af2a-3a80af5a6e8d', 'Fentes Alternées Dynamique', NULL, NULL, 'Switching Lunges', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/switching-lunges.mp4', NULL, NULL, NULL, '/videos/thumbnails/switching-lunges.jpg', NULL, '["Atterris doucement sur la plante des pieds pour réduire l''impact sur tes articulations et garder le contrôle", "Garde le torse droit tout au long du mouvement, évite de pencher en avant ou en arrière", "Assure-toi que ton genou avant reste aligné avec ta cheville et ne s''effondre pas vers l''intérieur pendant la fente", "Commence par des mouvements lents et contrôlés avant de passer à une vitesse de changement plus rapide", "Maintiens une forte contraction des abdominaux pour stabiliser ton corps lors des transitions explosives"]', '["Ne pas garder le dos droit pendant l''exercice", "Laisser le genou avant dépasser la cheville"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "switching lunges"]', true, '2026-04-03 12:24:59.685267+00', '2026-04-03 12:24:59.685267+00', 'Placement initial : Tiens-toi droit, les pieds à la largeur des hanches, mains sur les hanches ou sur les côtés pour l''équilibre. Exécution : Fais un pas en avant avec un pied en position de fente, puis saute explosivement et change de jambe en restant en l''air, atterrissant avec l''autre pied en avant dans une position de fente.', '["Ne pas garder le dos droit pendant l''exercice", "Laisser le genou avant dépasser la cheville"]', true, '["Begin in a standing position with your core engaged and shoulders back", "Step your right foot forward into a lunge, lowering your body until both knees form 90-degree angles", "Push explosively through both feet to jump straight up into the air", "While airborne, quickly switch your leg positions so your left foot moves forward and right foot moves back", "Land softly with your left foot forward in a lunge position, immediately absorbing the impact by bending both knees", "Continue alternating legs with each jump, maintaining proper lunge form throughout the movement"]', '["Commence en position debout, le ventre serré et les épaules en arrière", "Fais un pas en avant avec ton pied droit en fente, en abaissant ton corps jusqu''à ce que tes deux genoux forment des angles de 90 degrés", "Pousse de manière explosive avec les deux pieds pour sauter directement dans les airs", "En l''air, change rapidement la position de tes jambes, le pied gauche va en avant et le pied droit recule", "Atterris doucement avec ton pied gauche en avant dans une position de fente, en absorbant immédiatement l''impact en pliant les deux genoux", "Continue à alterner les jambes à chaque saut, en maintenant la bonne forme de fente tout au long du mouvement"]', '["Atterris doucement sur la plante des pieds pour réduire l''impact sur tes articulations et garder le contrôle", "Garde le torse droit tout au long du mouvement, évite de pencher en avant ou en arrière", "Assure-toi que ton genou avant reste aligné avec ta cheville et ne s''effondre pas vers l''intérieur pendant la fente", "Commence par des mouvements lents et contrôlés avant de passer à une vitesse de changement plus rapide", "Maintiens une forte contraction des abdominaux pour stabiliser ton corps lors des transitions explosives"]', '["Land softly on the balls of your feet to reduce impact on your joints and maintain control", "Keep your torso upright throughout the movement and avoid leaning forward or backward", "Ensure your front knee tracks over your ankle and doesn''t cave inward during the lunge", "Start with slower, controlled movements before progressing to faster switching speeds", "Maintain a strong core engagement to stabilize your body during the explosive transitions"]', 'fa9f64d1-12a1-43be-a15d-45609a706c9c', 'switching-lunges', NULL, NULL);
INSERT INTO public.exercises VALUES ('b126f6c4-af81-4caf-b6a1-08c3a6affb0e', 'Plie Dumbbell Squat', NULL, 'Squat avec haltère en position écartée', 'Plie Dumbbell Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 2, '/videos/quadriceps/plie-dumbbell-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/plie-dumbbell-squat.jpg', NULL, '["Veille à ce que tes genoux suivent la direction de tes orteils tout au long du mouvement pour éviter les blessures", "Garde le torse droit et évite de trop pencher en avant pour protéger ta colonne lombaire", "Pense à pousser tes genoux vers l''extérieur et engage tes cuisses intérieures grâce à la stance large", "Contrôle la descente et évite de rebondir au fond du squat pour maximiser l''engagement musculaire"]', '["Ne pas descendre suffisamment pour activer les muscles", "Pencher trop le torse en avant, ce qui peut fatiguer le bas du dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "plie dumbbell squat"]', true, '2026-04-03 12:24:58.372143+00', '2026-04-03 12:24:58.372143+00', 'Prends de la puissance avec le Plie Dumbbell Squat ! Position de départ : Écarte tes pieds au-delà de la largeur des épaules, les orteils tournés à 45 degrés. Tiens un haltère à deux mains au niveau de la poitrine. Tu es prêt ? Exécution : Descends en squat en pliant les hanches et les genoux tout en gardant l’haltère proche de ton corps. Puis, pousse sur tes talons pour remonter en position initiale. Let''s go !', '["Ne pas descendre suffisamment pour activer les muscles", "Pencher trop le torse en avant, ce qui peut fatiguer le bas du dos"]', true, '["Stand with feet wider than shoulder-width apart and turn your toes out at approximately 45-degree angles", "Hold a dumbbell vertically with both hands at chest level, gripping the top weight plate securely", "Keep your chest up and core engaged as you begin to lower by pushing your hips back and bending your knees", "Descend until your thighs are parallel to the floor or as low as your mobility allows while maintaining proper form", "Drive through your heels and squeeze your glutes to return to the starting position", "Maintain the wide stance and turned-out toe position throughout the entire movement"]', '["Écarte les pieds au-delà de la largeur des épaules et tourne les orteils à environ 45 degrés", "Tiens l''haltère verticalement avec les deux mains à hauteur de poitrine, en serrant bien le poids en haut", "Garde la poitrine relevée et le gainage actif, puis commence à descendre en poussant les hanches en arrière et en fléchissant les genoux", "Descends jusqu''à ce que tes cuisses soient parallèles au sol ou aussi bas que ta mobilité le permet tout en gardant la bonne posture", "Pousse sur tes talons et contracte tes fessiers pour revenir à la position de départ", "Maintiens la stance large et les orteils tournés pendant tout le mouvement"]', '["Veille à ce que tes genoux suivent la direction de tes orteils tout au long du mouvement pour éviter les blessures", "Garde le torse droit et évite de trop pencher en avant pour protéger ta colonne lombaire", "Pense à pousser tes genoux vers l''extérieur et engage tes cuisses intérieures grâce à la stance large", "Contrôle la descente et évite de rebondir au fond du squat pour maximiser l''engagement musculaire"]', '["Keep your knees tracking in line with your toes throughout the movement to prevent knee valgus", "Maintain an upright torso and avoid leaning forward excessively to protect your lower back", "Focus on pushing your knees out and engaging your inner thighs due to the wide stance", "Control the descent and avoid bouncing at the bottom of the squat to maximize muscle engagement"]', '6d78b4e0-d8b4-4cd2-8e0b-ab6d559b717d', 'plie-dumbbell-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('248f246b-e918-443d-aea9-08d105779592', 'Sauts à la corde', NULL, 'قفز على الحبل', 'Jumping Ropes  skips', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/jumping-ropes-skips.mp4', NULL, NULL, NULL, '/videos/thumbnails/jumping-ropes-skips.jpg', NULL, '["Gardez les sauts bas et contrôlés - levez les pieds de 1 à 2 pouces du sol pour réduire l''impact sur les articulations", "Concentrez-vous sur la rotation des poignets plutôt que d''utiliser vos bras pour faire tourner la corde pour plus d''efficacité et moins de fatigue", "Maintenez une posture droite avec les épaules détendues et regardez droit devant vous, pas vers le bas", "Commencez lentement pour développer votre rythme et votre coordination avant d''augmenter la vitesse ou d''essayer des figures de saut avancées", "Choisissez une longueur de corde appropriée en vous tenant au centre - les poignées doivent atteindre environ la hauteur de vos aisselles."]', '["Sauter trop haut faisant chuter le rythme", "Oublier de garder les poignets actifs et de relâcher les bras"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "jumping ropes  skips"]', true, '2026-04-03 12:24:57.397278+00', '2026-04-03 12:24:57.397278+00', 'Position de départ : Tenez-vous droit, les pieds joints, avec les poignées de la corde à sauter de chaque côté, les coudes proches du corps. Exécution : Faites tourner la corde au-dessus de votre tête en utilisant vos poignets tout en sautant légèrement sur les deux pieds, en atterrissant doucement sur les pointes de vos pieds lorsque la corde passe dessous.', '["Sauter trop haut faisant chuter le rythme", "Oublier de garder les poignets actifs et de relâcher les bras"]', true, '["Hold rope handles with a relaxed grip, positioning hands at hip level with elbows bent at your sides", "Start with the rope behind your heels and swing it overhead using primarily wrist rotation rather than arm movement", "Jump only high enough for the rope to pass under your feet, maintaining a slight bend in your knees", "Land softly on the balls of your feet with each jump, keeping your core engaged and posture upright", "Begin with short intervals of 30-60 seconds and gradually increase duration as coordination improves", "If you miss or trip, simply restart the rhythm without stopping your workout momentum"]', '["Maintenez les poignées de la corde avec une prise détendue, mains au niveau des hanches et coudes pliés le long du corps", "Commencez avec la corde derrière vos talons et balancez-la au-dessus de votre tête en utilisant principalement la rotation des poignets", "Sautez juste assez haut pour que la corde passe sous vos pieds, en gardant les genoux légèrement fléchis", "Atterrissez doucement sur les pointes de vos pieds à chaque saut, en gardant le centre engagé et la posture droite", "Débutez avec des intervalles courts de 30 à 60 secondes et augmentez progressivement la durée au fur et à mesure que votre coordination s''améliore", "Si vous ratez ou trébuchez, reprenez simplement le rythme sans stopper votre entraînement."]', '["Gardez les sauts bas et contrôlés - levez les pieds de 1 à 2 pouces du sol pour réduire l''impact sur les articulations", "Concentrez-vous sur la rotation des poignets plutôt que d''utiliser vos bras pour faire tourner la corde pour plus d''efficacité et moins de fatigue", "Maintenez une posture droite avec les épaules détendues et regardez droit devant vous, pas vers le bas", "Commencez lentement pour développer votre rythme et votre coordination avant d''augmenter la vitesse ou d''essayer des figures de saut avancées", "Choisissez une longueur de corde appropriée en vous tenant au centre - les poignées doivent atteindre environ la hauteur de vos aisselles."]', '["Keep jumps low and controlled - only lift feet 1-2 inches off the ground to reduce impact on joints", "Focus on wrist rotation rather than using your entire arms to turn the rope for better efficiency and less fatigue", "Maintain an upright posture with shoulders relaxed and eyes looking forward, not down at your feet", "Start slowly to develop rhythm and coordination before increasing speed or attempting advanced footwork patterns", "Choose appropriate rope length by standing on the center - handles should reach approximately armpit height"]', 'ba7727ee-e0bb-402c-99fb-c27eadd440f7', 'jumping-ropes-skips', NULL, NULL);
INSERT INTO public.exercises VALUES ('53b5dae6-6acc-4d70-8611-3921baf3992d', 'Extension des Jambes', NULL, 'تمارين تمديد الأرجل', 'Leg Extension', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/leg-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/leg-extension.jpg', NULL, '["Garde ton ventre engagé et évite d''arquer ton dos pendant le mouvement", "Ne verrouille pas complètement tes genoux en haut pour éviter le stress sur l''articulation", "Contrôle la descente plutôt que de laisser le poids tomber rapidement", "Commence avec un poids léger pour maîtriser la forme avant d''augmenter la charge", "Évite d''utiliser l''élan ou de balancer tes jambes pour soulever le poids"]', '["Ne pas ajuster correctement la machine", "Ne pas contrôler la descente du poids"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "leg extension"]', true, '2026-04-03 12:24:57.546683+00', '2026-04-03 12:24:57.546683+00', 'Position de départ : Assieds-toi sur la machine d''extension des jambes, les genoux fléchis et les chevilles bien maintenues sous les coussinets. Exécution : Étends tes jambes vers le haut jusqu''à ce qu''elles soient complètement droites, puis redescends lentement à la position de départ.', '["Ne pas ajuster correctement la machine", "Ne pas contrôler la descente du poids"]', true, '["Adjust the machine so the pivot point aligns with your knee joint and the ankle pad sits comfortably above your feet", "Sit with your back flat against the backrest and grip the side handles for stability", "Set your feet hip-width apart with toes pointing forward", "Extend your legs in a smooth, controlled motion until knees are almost fully straight", "Pause briefly at the top position while squeezing your quadriceps", "Lower the weight slowly taking 2-3 seconds to return to starting position"]', '["Ajuste la machine pour que le point de pivot soit aligné avec ton articulation du genou et que le coussinet de cheville soit bien placé au-dessus de tes pieds", "Assieds-toi avec le dos bien plaqué contre le dossier et tiens les poignées latérales pour plus de stabilité", "Place tes pieds à la largeur des hanches avec les orteils pointant vers l''avant", "Étends tes jambes de manière fluide et contrôlée jusqu''à ce que tes genoux soient presque complètement droits", "Fais une pause brièvement en haut en contractant tes quadriceps", "Redescends lentement en prenant 2-3 secondes pour revenir à la position de départ"]', '["Garde ton ventre engagé et évite d''arquer ton dos pendant le mouvement", "Ne verrouille pas complètement tes genoux en haut pour éviter le stress sur l''articulation", "Contrôle la descente plutôt que de laisser le poids tomber rapidement", "Commence avec un poids léger pour maîtriser la forme avant d''augmenter la charge", "Évite d''utiliser l''élan ou de balancer tes jambes pour soulever le poids"]', '["Keep your core engaged and avoid arching your back during the movement", "Don''t lock your knees completely at the top to prevent joint stress", "Control the eccentric portion of the lift rather than letting the weight drop quickly", "Start with lighter weight to master the form before progressing to heavier loads", "Avoid using momentum or swinging your legs to lift the weight"]', '3941270c-ad35-40bf-9906-e9c6d24ba777', 'leg-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('627b6305-9ae9-4a4c-81c7-e061351f4d23', 'Pompes sur les genoux', NULL, NULL, 'Knee push ups', 'Chest', '[]', 'Chest', 'Beginner', 16, '/videos/chest/knee-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/knee-push-ups.jpg', NULL, '["Évite de laisser tes hanches s''affaisser ou se lever pour conserver la bonne forme.", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement musculaire et prévenir les blessures.", "Maintiens ta tête dans une position neutre en regardant légèrement devant toi.", "Commence avec moins de répétitions et augmente progressivement à mesure que tu deviens plus fort.", "Si besoin, mets une serviette sous tes genoux pour plus de confort."]', '["Ne pas garder les hanches alignées avec le reste du corps.", "Écarter les coudes trop largement pendant le mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "knee push ups"]', true, '2026-04-03 12:24:57.464323+00', '2026-04-03 12:24:57.464323+00', 'Position de départ : Mets-toi à genoux avec les mains placées à la largeur des épaules sur le sol. Ton corps doit former une ligne droite de la tête aux genoux. Exécution : Abaisse ta poitrine vers le sol en pliant les coudes, puis pousse sur tes mains pour revenir à la position de départ en gardant ton alignment corporel.', '["Ne pas garder les hanches alignées avec le reste du corps.", "Écarter les coudes trop largement pendant le mouvement."]', true, '["Position yourself on your knees with hands flat on the floor directly under your shoulders", "Keep your core engaged and maintain a straight line from your head to your knees throughout the movement", "Lower your body slowly by bending your elbows until your chest nearly touches the floor", "Push through your palms to return to the starting position with control", "Keep your elbows at roughly a 45-degree angle from your torso rather than flaring them straight out", "Breathe in as you lower down and exhale as you push up"]', '["Positionne-toi à genoux, les mains à plat sur le sol juste sous les épaules.", "Engage ton ventre et garde une ligne droite entre ta tête et tes genoux pendant tout le mouvement.", "Abaisse lentement ton corps en pliant les coudes jusqu''à ce que ta poitrine frôle le sol.", "Pousse avec contrôle pour revenir à la position de départ.", "Garde tes coudes à environ 45 degrés de ton torse, sans les écarter trop.", "Inspire en descendant et expire en poussant vers le haut."]', '["Évite de laisser tes hanches s''affaisser ou se lever pour conserver la bonne forme.", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement musculaire et prévenir les blessures.", "Maintiens ta tête dans une position neutre en regardant légèrement devant toi.", "Commence avec moins de répétitions et augmente progressivement à mesure que tu deviens plus fort.", "Si besoin, mets une serviette sous tes genoux pour plus de confort."]', '["Avoid letting your hips sag or pike up during the movement to maintain proper form", "Focus on controlled movement rather than speed to maximize muscle engagement and prevent injury", "Keep your head in a neutral position by looking slightly ahead rather than straight down", "Start with fewer repetitions and gradually increase as your strength improves", "Place a towel under your knees for comfort if needed"]', 'd33da8f6-37a9-4730-8399-c4c5be3a7f00', 'knee-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('69431532-3c61-49be-a4a4-0fe44c743481', 'Squat Avant avec Barre', NULL, 'خدعة السكوات بالأمامية', 'Front Barbell Squat', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 1, '/videos/quadriceps/front-barbell-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/front-barbell-squat.jpg', NULL, '["Nécessite plus de mobilité que le squat arrière", "Garde les coudes hauts tout au long de l''exercice", "Plus axé sur les quadriceps", "Le torse reste plus vertical", "Si la barre roule vers l''avant, les coudes sont trop bas"]', '["Ne pas descendre assez bas", "S''affaisser dans le dos", "Laisser les coudes descendre", "Plier les genoux vers l''intérieur"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "front barbell squat"]', true, '2026-04-03 12:24:56.799005+00', '2026-04-03 12:24:56.799005+00', 'Position de départ : Place la barre sur le devant de tes épaules, en la tenant avec les bras croisés ou en prise propre, les pieds écartés à la largeur des épaules. Exécution : Plie les genoux pour descendre en squat profond tout en gardant le dos droit, puis pousse sur tes pieds pour revenir à la position de départ.', '["Ne pas descendre assez bas", "S''affaisser dans le dos", "Laisser les coudes descendre", "Plier les genoux vers l''intérieur"]', true, '["Bar on front delts, elbows high", "Cross-arm or clean grip", "Feet shoulder-width", "Squat down, keeping torso upright", "Drive up through whole foot"]', '["Barre sur les épaules avant, coudes hauts", "Prise croisée ou prise propre", "Pieds à la largeur des épaules", "Descends en squat, garde le torse droit", "Pousse avec l''ensemble du pied"]', '["Nécessite plus de mobilité que le squat arrière", "Garde les coudes hauts tout au long de l''exercice", "Plus axé sur les quadriceps", "Le torse reste plus vertical", "Si la barre roule vers l''avant, les coudes sont trop bas"]', '["Requires more mobility than back squat", "Keep elbows high throughout", "More quad-dominant", "Torso stays more vertical", "If bar rolls forward, elbows are too low"]', 'e75d29c0-7af3-4e83-a351-6fff23443379', 'front-barbell-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('064de30c-35ae-4269-a8a5-00302cdff832', 'Fente Arrière avec Haltères', NULL, NULL, 'Dumbbell Rear Lunge', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 2, '/videos/quadriceps/dumbbell-rear-lunge.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-rear-lunge.jpg', NULL, '["Garde la majorité de ton poids sur ta jambe avant pendant tout le mouvement", "Maintiens un torse droit et évite de te pencher en avant pour ne pas solliciter ton bas du dos", "Contrôle ta descente lentement et évite de te laisser tomber rapidement dans la position de fente", "Veille à ce que ton genou avant suive la ligne de tes orteils afin d''éviter les tensions au niveau du genou", "Commence avec des poids plus légers pour maîtriser le mouvement avant de passer à des haltères plus lourds"]', '["Pencher le torse en avant", "Ne pas aligner le genou avant avec la cheville"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell rear lunge"]', true, '2026-04-03 12:24:56.546695+00', '2026-04-03 12:24:56.546695+00', 'Position de départ : Tiens-toi droit avec un haltère dans chaque main, les pieds écartés à la largeur des hanches et les abdos contractés. Exécution : Fais un pas en arrière avec un pied, descends tes hanches jusqu''à ce que les deux genoux soient fléchis à environ 90 degrés, puis pousse avec le talon avant pour revenir à la position de départ.', '["Pencher le torse en avant", "Ne pas aligner le genou avant avec la cheville"]', true, '["Hold dumbbells with a secure grip at your sides, maintaining neutral wrists throughout the movement", "Step backward with one leg, landing on the ball of your foot while keeping your torso upright", "Lower your body until your front thigh is parallel to the floor and your rear knee nearly touches the ground", "Keep your front knee aligned over your ankle, not pushing forward past your toes", "Push through your front heel to drive back to the starting position", "Complete all repetitions on one leg before switching to the other side"]', '["Tiens les haltères fermement à tes côtés, en gardant les poignets neutres tout au long du mouvement", "Fais un pas en arrière avec une jambe, en atterrissant sur la plante de ton pied tout en gardant le dos droit", "Abaisse ton corps jusqu''à ce que ta cuisse avant soit parallèle au sol et que ton genou arrière frôle le sol", "Assure-toi que ton genou avant s''aligne sur ta cheville, sans dépasser tes orteils", "Pousse avec ton talon avant pour revenir à la position de départ", "Termine toutes les répétitions d''un côté avant de changer de jambe"]', '["Garde la majorité de ton poids sur ta jambe avant pendant tout le mouvement", "Maintiens un torse droit et évite de te pencher en avant pour ne pas solliciter ton bas du dos", "Contrôle ta descente lentement et évite de te laisser tomber rapidement dans la position de fente", "Veille à ce que ton genou avant suive la ligne de tes orteils afin d''éviter les tensions au niveau du genou", "Commence avec des poids plus légers pour maîtriser le mouvement avant de passer à des haltères plus lourds"]', '["Keep most of your weight on your front leg throughout the entire movement", "Maintain an upright torso and avoid leaning forward, which can strain your lower back", "Control the descent slowly rather than dropping quickly into the lunge position", "Ensure your front knee tracks in line with your toes to prevent knee strain", "Start with lighter weights to master the movement pattern before progressing to heavier dumbbells"]', '9690f31a-ed99-446e-88db-2934b832f497', 'dumbbell-rear-lunge', NULL, NULL);
INSERT INTO public.exercises VALUES ('ee79c207-d82f-487d-89e5-ce91dae07b53', 'Fentes avec haltères', NULL, NULL, 'Dumbbell Lunges', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 2, '/videos/quadriceps/dumbbell-lunges.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-lunges.jpg', NULL, '["Garde le buste droit", "Le genou avant doit suivre la ligne des orteils", "Contrôle la descente", "Ne laisse pas le genou avant dépasser les orteils", "Laisse les bras pendre naturellement"]', '["Genou avant qui dépasse les orteils", "Buste penché en avant", "Descente trop rapide sans contrôle", "Jambes qui ne s''alternent pas correctement", "Mains qui ne tiennent pas les haltères correctement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell lunges"]', true, '2026-04-03 12:24:56.482764+00', '2026-04-03 12:24:56.482764+00', 'Position de départ : Tiens-toi droit avec un haltère dans chaque main, les bras le long du corps, les pieds écartés à la largeur des hanches. Exécution : Fais un pas en avant en te mettant en position de fente, abaisse les hanches jusqu''à ce que les deux genoux soient pliés à environ 90 degrés, puis pousse avec le talon de la jambe avant pour revenir à la position de départ.', '["Genou avant qui dépasse les orteils", "Buste penché en avant", "Descente trop rapide sans contrôle", "Jambes qui ne s''alternent pas correctement", "Mains qui ne tiennent pas les haltères correctement"]', true, '["Hold dumbbells at sides", "Step forward into lunge", "Lower until back knee near floor", "Push back to start", "Alternate legs or complete one side"]', '["Tiens les haltères sur les côtés", "Fais un pas en avant en fente", "Abaisse jusqu''à ce que le genou arrière soit proche du sol", "Pousse pour revenir à la position de départ", "Alterne les jambes ou completes un côté"]', '["Garde le buste droit", "Le genou avant doit suivre la ligne des orteils", "Contrôle la descente", "Ne laisse pas le genou avant dépasser les orteils", "Laisse les bras pendre naturellement"]', '["Keep torso upright", "Front knee tracks over toes", "Control the descent", "Don''t let front knee shoot forward", "Arms hang naturally"]', '57c55853-176e-4bad-aced-1032c63f4652', 'dumbbell-lunges', NULL, NULL);
INSERT INTO public.exercises VALUES ('a0e2cb3c-a19d-453a-b5ff-2615fa7eee9c', 'Dumbbell Thruster', NULL, 'تدريب الرفع مع الدمبل', 'Dumbbell Thruster', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 2, '/videos/quadriceps/dumbbell-thruster.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-thruster.jpg', NULL, '["Maintiens une colonne vertébrale neutre tout au long du mouvement pour éviter les blessures au dos", "Utilise la puissance de tes jambes pour le press au-dessus de la tête au lieu de te fier uniquement à tes épaules", "Garde les haltères près du corps lors de la transition du squat au press", "Assure-toi une extension complète des hanches en haut avant de presser les poids au-dessus de ta tête", "Contrôle la descente du squat et le retour des poids pour maintenir une bonne forme"]', '["Ne pas garder le dos droit durant le mouvement", "Relâcher les abdominaux en bas du squat"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell thruster"]', true, '2026-04-03 12:24:56.61599+00', '2026-04-03 12:24:56.61599+00', 'Position de départ : Prends un haltère dans chaque main à hauteur d''épaules, les coudes pliés, les pieds écartés à la largeur des épaules et le centre engagé. Exécution : Réalise un squat en abaissant tes hanches vers l''arrière et vers le bas, puis propulse-toi avec tes talons pour te relever tout en pressant les haltères au-dessus de ta tête dans un mouvement fluide.', '["Ne pas garder le dos droit durant le mouvement", "Relâcher les abdominaux en bas du squat"]', true, '["Hold dumbbells at shoulder height with palms facing forward and elbows slightly in front of your body", "Position feet shoulder-width apart with toes slightly turned out", "Lower into a squat by pushing hips back and bending knees until thighs are parallel to the floor", "Keep your chest up and weight distributed evenly across your feet throughout the squat", "Drive explosively through your heels to stand while simultaneously pressing dumbbells straight overhead", "Lower dumbbells back to shoulder height as you prepare for the next repetition"]', '["Tiens les haltères à hauteur des épaules, paumes vers l''avant et coudes légèrement devant le corps", "Positionne tes pieds écartés à la largeur des épaules avec les orteils légèrement tournés vers l''extérieur", "Descends en squat en poussant tes hanches vers l''arrière et en pliant les genoux jusqu''à ce que tes cuisses soient parallèles au sol", "Garde ta poitrine haute et le poids bien réparti sur tes pieds durant tout le squat", "Pousse de manière explosive avec tes talons pour te redresser tout en pressant les haltères au-dessus de la tête", "Redescends les haltères jusqu''à hauteur d''épaules en te préparant pour la prochaine répétition"]', '["Maintiens une colonne vertébrale neutre tout au long du mouvement pour éviter les blessures au dos", "Utilise la puissance de tes jambes pour le press au-dessus de la tête au lieu de te fier uniquement à tes épaules", "Garde les haltères près du corps lors de la transition du squat au press", "Assure-toi une extension complète des hanches en haut avant de presser les poids au-dessus de ta tête", "Contrôle la descente du squat et le retour des poids pour maintenir une bonne forme"]', '["Maintain a neutral spine throughout the entire movement to prevent back injury", "Use your legs to generate power for the overhead press rather than relying solely on your shoulders", "Keep the dumbbells close to your body during the transition from squat to press", "Ensure full hip extension at the top before pressing the weights overhead", "Control the descent of both the squat and the weight return to maintain proper form"]', 'c3d00969-0a33-4a3f-b603-938c1014ca9f', 'dumbbell-thruster', NULL, NULL);
INSERT INTO public.exercises VALUES ('7ebe05ec-e3a0-4cf9-817d-38556860e8ac', 'Relevés en L avec haltères', NULL, NULL, 'L dumbbell raises', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/l-dumbbell-raises.mp4', NULL, NULL, NULL, '/videos/thumbnails/l-dumbbell-raises.jpg', NULL, '["Garde une légère flexion dans tes coudes durant tout le mouvement pour protéger tes articulations", "Évite d''utiliser l''élan ou de balancer les poids - concentre-toi sur des mouvements contrôlés et précis", "Maintiens une bonne posture avec la poitrine haute, sans te pencher en avant ou en arrière pendant l''exercice", "Commence avec des poids plus légers que pour les relevés unilatéraux en raison des exigences accrues en coordination et en stabilité", "Arrête immédiatement si tu ressens une douleur ou une gêne à l''épaule"]', '["Ne pas maintenir la posture correcte en s''affaissant vers l''avant", "Utiliser trop de poids et perdre le contrôle pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "l dumbbell raises"]', true, '2026-04-03 12:24:57.510505+00', '2026-04-03 12:24:57.510505+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, un haltère dans chaque main le long du corps, les bras tendus et les paumes dirigées vers toi. Exécution : Lève simultanément un bras sur le côté et l’autre vers l’avant à hauteur d’épaule, formant un ‘L’, puis redescends les bras à la position de départ et répète en inversant les positions des bras.', '["Ne pas maintenir la posture correcte en s''affaissant vers l''avant", "Utiliser trop de poids et perdre le contrôle pendant l''exercice"]', true, '["Stand tall with core engaged and shoulders pulled back, holding dumbbells with a neutral grip", "Begin with lighter weights to master the coordination of the dual-plane movement", "Raise one arm laterally to the side while simultaneously raising the other arm forward, both to shoulder height", "Hold briefly at the top position while maintaining control of both dumbbells", "Lower both arms slowly and with control back to the starting position", "Alternate which arm goes forward and which goes lateral with each repetition"]', '["Tiens-toi bien droit, engage ton core et garde les épaules en arrière, haltères en prise neutre", "Commence avec des poids légers pour maîtriser la coordination du mouvement dans les deux plans", "Lève un bras latéralement sur le côté tout en levant l''autre bras vers l''avant, les deux à hauteur d''épaule", "Maintiens brièvement la position haute en contrôlant les haltères", "Redescends lentement et avec contrôle à la position de départ", "Alterne le bras qui va vers l''avant et celui qui va sur le côté à chaque répétition"]', '["Garde une légère flexion dans tes coudes durant tout le mouvement pour protéger tes articulations", "Évite d''utiliser l''élan ou de balancer les poids - concentre-toi sur des mouvements contrôlés et précis", "Maintiens une bonne posture avec la poitrine haute, sans te pencher en avant ou en arrière pendant l''exercice", "Commence avec des poids plus légers que pour les relevés unilatéraux en raison des exigences accrues en coordination et en stabilité", "Arrête immédiatement si tu ressens une douleur ou une gêne à l''épaule"]', '["Keep a slight bend in your elbows throughout the entire movement to protect the joints", "Avoid using momentum or swinging the weights - focus on controlled, deliberate movements", "Maintain proper posture with chest up and avoid leaning forward or backward during the exercise", "Start with lighter weights than you would use for single-arm raises due to the increased coordination and stability demands", "Stop immediately if you experience any shoulder pain or discomfort"]', '7f8e01f5-2b17-487f-aa3a-5614b629ade2', 'l-dumbbell-raises', NULL, NULL);
INSERT INTO public.exercises VALUES ('c13b89c4-4d76-42d5-9099-7397c7e49e04', 'Tirage de Lat', NULL, 'سحب لات', 'Lat Pulldown', 'Back', '[]', 'Back', 'Beginner', 4, '/videos/back/lat-pulldown.mp4', NULL, NULL, NULL, '/videos/thumbnails/lat-pulldown.jpg', NULL, '["Ne tire pas la barre derrière ta nuque, cela peut entraîner des douleurs à l''épaule.", "Concentre-toi sur tes muscles du dos plutôt que sur tes bras. Pense à tirer tes coudes vers le bas et l''arrière.", "Ne te penche pas trop en arrière et n''utilise pas d''élan, cela diminue l''efficacité et augmente les risques de blessure.", "Maintiens un rythme contrôlé : 2 secondes pour tirer et 3 secondes pour revenir afin de maximiser l''engagement musculaire.", "Garde les épaules basses et éloignées de tes oreilles pour cibler correctement le grand dorsal."]', '["Tirer la barre derrière la nuque.", "Utiliser l''élan au lieu d''une technique correcte."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "lat pulldown"]', true, '2026-04-03 12:24:57.523359+00', '2026-04-03 12:24:57.523359+00', 'Prêt à renforcer ton dos ? Installe-toi à la machine à tirage latéral, saisis les poignées en haut et tire vers ta poitrine en gardant les coudes près du corps. Puis, repousse doucement les poignées pour revenir à la position initiale. C''est parti !', '["Tirer la barre derrière la nuque.", "Utiliser l''élan au lieu d''une technique correcte."]', true, '["Adjust the thigh pads so they rest comfortably on your legs to prevent your body from lifting during the movement", "Sit upright with your chest out and maintain a slight lean back of about 15-20 degrees throughout the exercise", "Grip the bar with your hands positioned wider than your shoulders using an overhand grip", "Initiate the pull by drawing your shoulder blades down and back, then pull the bar toward your upper chest", "Control the weight on the way up, allowing your arms to fully extend while maintaining tension in your lats", "Keep your core engaged throughout the entire movement to maintain proper posture"]', '["Ajuste les coussins de cuisse pour qu''ils reposent confortablement sur tes jambes et évite de soulever ton corps pendant l''exercice.", "Assieds-toi bien droit, poitrine en avant et incline-toi légèrement en arrière de 15 à 20 degrés durant tout le mouvement.", "Prends la barre avec une prise plus large que tes épaules, en posant tes mains en prise pronation.", "Commence le mouvement en tirant tes omoplates vers le bas et l''arrière, puis tire la barre vers le haut de ta poitrine.", "Contrôle le poids au retour en laissant tes bras s''étendre complètement tout en maintenant la tension dans tes lats.", "Engage ton tronc tout au long de l''exercice pour garder une bonne posture."]', '["Ne tire pas la barre derrière ta nuque, cela peut entraîner des douleurs à l''épaule.", "Concentre-toi sur tes muscles du dos plutôt que sur tes bras. Pense à tirer tes coudes vers le bas et l''arrière.", "Ne te penche pas trop en arrière et n''utilise pas d''élan, cela diminue l''efficacité et augmente les risques de blessure.", "Maintiens un rythme contrôlé : 2 secondes pour tirer et 3 secondes pour revenir afin de maximiser l''engagement musculaire.", "Garde les épaules basses et éloignées de tes oreilles pour cibler correctement le grand dorsal."]', '["Avoid pulling the bar behind your neck as this can cause shoulder impingement and injury", "Focus on using your back muscles rather than your arms by thinking about pulling your elbows down and back", "Don''t lean too far back or use momentum to complete the movement - this reduces effectiveness and increases injury risk", "Maintain a controlled tempo with a 2-second pull down and 3-second return to maximize muscle engagement", "Keep your shoulders down and away from your ears throughout the exercise to properly target the latissimus dorsi"]', '920d96cd-7857-4720-9bea-21b23b124b64', 'lat-pulldown', NULL, NULL);
INSERT INTO public.exercises VALUES ('7b25b5ad-6c21-4bfc-88d8-ffc4a9870b10', 'Élévations latérales bras unique (G)', NULL, NULL, 'One-Arm Side Laterals (L)', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/one-arm-side-laterals-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/one-arm-side-laterals-l.jpg', NULL, '["Garde ton torse bien droit, évite de te pencher loin du bras qui travaille", "Contrôle la descente pour maximiser l''engagement musculaire et éviter l''élan", "Ne lève pas ton bras au-dessus de la hauteur de l''épaule pour prévenir le syndrome d''accrochage", "Concentre-toi sur le mouvement depuis l''épaule sans balancer le bras avec le dos", "Respire régulièrement, expire en levant le bras et inspire en le redescendant"]', '["Pencher le torse pendant l''exercice", "Utiliser l''élan plutôt que la force musculaire pour lever le bras"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "one-arm side laterals (l)"]', true, '2026-04-03 12:24:58.202403+00', '2026-04-03 12:24:58.202403+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des épaules, le ventre engagé. Laisse ton bras gauche pendre naturellement sur le côté, main droite sur la hanche ou dans le dos. Exécution : Lève ton bras gauche sur le côté jusqu''à la hauteur de l''épaule, puis redescends-le lentement avec contrôle.', '["Pencher le torse pendant l''exercice", "Utiliser l''élan plutôt que la force musculaire pour lever le bras"]', true, '["Stand tall with feet shoulder-width apart and engage your core muscles", "Place your right hand on your hip or behind your back for stability", "Keep your left arm straight but not locked, with a slight bend in the elbow", "Raise your left arm out to the side until it reaches shoulder height, leading with your pinky finger", "Hold briefly at the top position, then slowly lower your arm back to starting position", "Complete all repetitions on the left side before switching to the right arm"]', '["Tiens-toi bien droit avec les pieds écartés à la largeur des épaules et active ton gainage", "Place ta main droite sur ta hanche ou dans le dos pour plus de stabilité", "Garde ton bras gauche légèrement plié au coude, mais pas verrouillé", "Lève ton bras gauche sur le côté jusqu''à la hauteur de l''épaule, en dirigeant avec le petit doigt", "Maintiens brièvement en haut, puis redescends lentement au point de départ", "Fais toutes les répétitions du côté gauche avant de passer au bras droit"]', '["Garde ton torse bien droit, évite de te pencher loin du bras qui travaille", "Contrôle la descente pour maximiser l''engagement musculaire et éviter l''élan", "Ne lève pas ton bras au-dessus de la hauteur de l''épaule pour prévenir le syndrome d''accrochage", "Concentre-toi sur le mouvement depuis l''épaule sans balancer le bras avec le dos", "Respire régulièrement, expire en levant le bras et inspire en le redescendant"]', '["Keep your torso upright and avoid leaning away from the working arm during the movement", "Control the descent phase of the movement to maximize muscle engagement and prevent momentum", "Avoid raising your arm above shoulder height to prevent shoulder impingement", "Focus on initiating the movement from your shoulder rather than using your back or torso to swing the arm", "Maintain steady breathing throughout the exercise, exhaling as you raise your arm and inhaling as you lower it"]', '2e6e0a8a-ab5d-4f00-a6b4-c1f025190b79', 'one-arm-side-laterals-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('01056af8-3ecf-47c3-ba4c-712348749e2f', 'Soulevé de terre avec haltères', NULL, 'مرفوع بالأثقال', 'Dumbbell deadlift', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 2, '/videos/quadriceps/dumbbell-deadlift.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-deadlift.jpg', NULL, '["Utilisez le même enchaînement que le soulevé de terre barre", "Gardez les haltères près des jambes", "Ne courbez pas le bas du dos", "Ressentez l''étirement des ischio-jambiers", "Contractez les fessiers en haut du mouvement"]', '["Inclinaison excessive du dos", "Haltères trop éloignés du corps", "Ne pas engager les hanches correctement", "Genoux trop fléchis pendant le mouvement", "Oublier de respirer clairement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell deadlift"]', true, '2026-04-03 12:24:56.400247+00', '2026-04-03 12:24:56.400247+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des épaules, un haltère dans chaque main devant vos cuisses. Exécution : Inclinez-vous doucement en avant au niveau des hanches, en abaissant les haltères vers le sol tout en gardant le dos droit et les genoux légèrement fléchis. Remontez lentement à la position de départ.', '["Inclinaison excessive du dos", "Haltères trop éloignés du corps", "Ne pas engager les hanches correctement", "Genoux trop fléchis pendant le mouvement", "Oublier de respirer clairement"]', true, '["Hold dumbbells in front of thighs", "Feet hip-width, soft knee bend", "Push hips back, lowering dumbbells down legs", "Feel hamstring stretch", "Drive hips forward to stand"]', '["Tenez les haltères devant vos cuisses", "Pieds écartés à la largeur des hanches, genoux légèrement fléchis", "Repoussez les hanches en arrière tout en baissant les haltères le long des jambes", "Sentez l''étirement des ischio-jambiers", "Poussez les hanches vers l''avant pour vous redresser"]', '["Utilisez le même enchaînement que le soulevé de terre barre", "Gardez les haltères près des jambes", "Ne courbez pas le bas du dos", "Ressentez l''étirement des ischio-jambiers", "Contractez les fessiers en haut du mouvement"]', '["Same pattern as barbell RDL", "Keep dumbbells close to legs", "Don''t round lower back", "Feel hamstring stretch", "Squeeze glutes at top"]', 'bbac448a-df15-415e-a391-8b1d400df2bf', 'dumbbell-deadlift', NULL, NULL);
INSERT INTO public.exercises VALUES ('6f7427cc-de3f-4dcd-bc6f-7aa80033ef64', 'Sauts de fente explosifs', NULL, NULL, 'Jumping lunges', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/jumping-lunges.mp4', NULL, NULL, NULL, '/videos/thumbnails/jumping-lunges.jpg', NULL, '["Atterris doucement avec les genoux fléchis pour absorber l''impact et protéger tes articulations.", "Garde le torse droit et le cœur engagé pendant tout le mouvement pour maintenir un bon alignement.", "Assure-toi que ton genou avant suit la direction de tes orteils et ne se dérobe pas vers l''intérieur lors de l''atterrissage.", "Commence avec des sauts plus bas et concentre-toi sur la forme avant de progresser vers des sauts plus explosifs.", "Permets-toi des temps de repos suffisants entre les séries car cet exercice de plyométrie haute intensité nécessite une récupération complète."]', '["Ne pas sauter assez haut, ce qui limite l''efficacité de l''exercice.", "L''atterrissage sur des jambes tendues, augmentant le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "jumping lunges"]', true, '2026-04-03 12:24:57.392084+00', '2026-04-03 12:24:57.392084+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches. Recule une jambe pour entrer dans la position de fente, avec les deux genoux fléchis à 90 degrés. Exécution : Saute avec force tout en changeant la position des jambes en l''air, et atterrisse doucement en fente avec l''autre jambe devant.', '["Ne pas sauter assez haut, ce qui limite l''efficacité de l''exercice.", "L''atterrissage sur des jambes tendues, augmentant le risque de blessure."]', true, '["Begin in a standard lunge position with your front knee directly over your ankle and back knee hovering just above the ground", "Engage your core and prepare for an explosive upward movement by loading through both legs", "Jump straight up powerfully, driving through your front heel and back toe simultaneously", "While airborne, quickly switch your leg positions so the back leg moves forward and the front leg moves back", "Land softly on the balls of your feet, immediately sinking into the lunge position with the opposite leg now forward", "Maintain control throughout the movement and pause briefly before repeating the jump"]', '["Commence en position de fente standard avec le genou avant au-dessus de la cheville et le genou arrière juste au-dessus du sol.", "Engage ton cœur et prépare-toi à un mouvement explosif en chargeant les deux jambes.", "Saute puissamment en poussant sur le talon avant et l''orteil arrière en même temps.", "En l''air, permute rapidement les positions des jambes, la jambe arrière allant vers l''avant et la jambe avant vers l''arrière.", "Atterris doucement sur l''avant de tes pieds, en te replaçant immédiatement en position de fente avec l''autre jambe devant.", "Garde le contrôle tout au long du mouvement et fais une pause brève avant de répéter le saut."]', '["Atterris doucement avec les genoux fléchis pour absorber l''impact et protéger tes articulations.", "Garde le torse droit et le cœur engagé pendant tout le mouvement pour maintenir un bon alignement.", "Assure-toi que ton genou avant suit la direction de tes orteils et ne se dérobe pas vers l''intérieur lors de l''atterrissage.", "Commence avec des sauts plus bas et concentre-toi sur la forme avant de progresser vers des sauts plus explosifs.", "Permets-toi des temps de repos suffisants entre les séries car cet exercice de plyométrie haute intensité nécessite une récupération complète."]', '["Land softly with bent knees to absorb impact and protect your joints from excessive stress", "Keep your torso upright and core engaged throughout the entire movement to maintain proper alignment", "Ensure your front knee tracks over your toes and doesn''t cave inward during landing", "Start with smaller jumps and focus on form before progressing to higher, more explosive movements", "Allow adequate rest between sets as this is a high-intensity plyometric exercise that requires full recovery"]', '55ce943e-c8ad-479b-bd92-10ba1d01889e', 'jumping-lunges', NULL, NULL);
INSERT INTO public.exercises VALUES ('09dedefc-0cf4-47e1-89c4-5d9420e52655', 'Exercice Câble Croisé Bas', NULL, 'تمارين الكابل المتقاطع السفلية', 'Low Cable Crossover', 'Chest', '[]', 'Chest', 'Intermediate', 4, '/videos/chest/low-cable-crossover.mp4', NULL, NULL, NULL, '/videos/thumbnails/low-cable-crossover.jpg', NULL, '["Garde toujours un léger pli dans les coudes pour protéger tes articulations", "Concentre-toi sur la contraction des muscles de la poitrine plutôt que d''utiliser l''élan", "Maintiens une bonne posture avec la poitrine en avant et les épaules en arrière", "Contrôle le poids à la montée comme à la descente", "Commence avec un poids léger pour bien maîtriser le mouvement avant de progresser"]', '["Utiliser trop de poids et perdre le contrôle", "Oublier de contracter les muscles de la poitrine", "Ne pas maintenir une bonne posture", "Effectuer le mouvement trop rapidement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "cable", "low cable crossover"]', true, '2026-04-03 12:24:57.608537+00', '2026-04-03 12:24:57.608537+00', 'Position de départ : Tiens-toi face aux poulies basses, les poignées ajustées à la hauteur des hanches. Exécution : Croise les câbles devant ta poitrine en gardant un léger pli dans les coudes, puis retourne à la position initiale.', '["Utiliser trop de poids et perdre le contrôle", "Oublier de contracter les muscles de la poitrine", "Ne pas maintenir une bonne posture", "Effectuer le mouvement trop rapidement"]', true, '["Set cable pulleys to the lowest position and select appropriate weight", "Stand in the center with one foot slightly forward for stability", "Grasp handles with palms facing up and arms extended down at your sides", "Pull cables up and inward in a smooth arc until hands meet at chest height", "Squeeze chest muscles at the top of the movement", "Lower cables slowly back to starting position with control"]', '["Place les poulies de câble au niveau le plus bas et choisis un poids adapté", "Positionne-toi au centre avec un pied légèrement en avant pour plus de stabilité", "Saisis les poignées avec les paumes vers le haut, bras étendus le long du corps", "Tire les câbles vers le haut et à l''intérieur dans une arc lisse jusqu''à ce que les mains se rejoignent à hauteur de poitrine", "Contracte les muscles de la poitrine en haut du mouvement", "Redescends lentement les câbles à la position initiale avec contrôle"]', '["Garde toujours un léger pli dans les coudes pour protéger tes articulations", "Concentre-toi sur la contraction des muscles de la poitrine plutôt que d''utiliser l''élan", "Maintiens une bonne posture avec la poitrine en avant et les épaules en arrière", "Contrôle le poids à la montée comme à la descente", "Commence avec un poids léger pour bien maîtriser le mouvement avant de progresser"]', '["Keep a slight bend in your elbows throughout the entire movement to protect your joints", "Focus on squeezing your chest muscles rather than using momentum", "Maintain good posture with chest up and shoulders back", "Control the weight on both the lifting and lowering phases", "Start with lighter weight to master the movement pattern before progressing"]', '8f181782-a135-49c5-91df-de5985c69ac7', 'low-cable-crossover', NULL, NULL);
INSERT INTO public.exercises VALUES ('aab6b843-12d6-47bc-8aaf-c5d1355bda4a', 'Lever Squat (Position Moyenne)', NULL, NULL, 'Lever Squat (Medium Stance)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/lever-squat-medium-stance.mp4', NULL, NULL, NULL, '/videos/thumbnails/lever-squat-medium-stance.jpg', NULL, '["Garde ton tronc engagé et le dos contre le coussin pendant tout le mouvement.", "Assure-toi que tes genoux suivent la ligne de tes orteils sans s''affaisser vers l''intérieur.", "Contrôle la descente et évite de rebondir au fond du mouvement.", "Concentre-toi sur le fait de pousser avec tes talons plutôt qu''avec le devant de tes pieds lors de la montée.", "Maintiens une respiration régulière en inspirant en descendant et expirant en montant."]', '["Ne pas maintenir le dos droit pendant la descente.", "Laisser les genoux s''affaisser vers l''intérieur."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "lever squat (medium stance)"]', true, '2026-04-03 12:24:57.583333+00', '2026-04-03 12:24:57.583333+00', 'Position de départ : Installe-toi sur la machine de lever squat, les pieds écartés à la largeur des épaules. Exécution : Abaisse ton corps en effectuant un squat profond tout en gardant le dos droit, puis pousse vers le haut pour revenir à la position de départ.', '["Ne pas maintenir le dos droit pendant la descente.", "Laisser les genoux s''affaisser vers l''intérieur."]', true, '["Position yourself on the machine with your back flat against the pad and shoulders securely under the shoulder pads", "Place feet shoulder-width apart on the platform with toes slightly pointed outward", "Release the safety handles and slowly lower yourself by bending at the knees and hips", "Descend until your thighs are parallel to the platform or as low as your mobility allows", "Drive through your heels and push the platform away to return to starting position", "Re-engage safety handles when finished with your set"]', '["Installe-toi sur la machine avec le dos bien plaqué contre le coussin et les épaules sous les patins.", "Place tes pieds à la largeur des épaules sur la plateforme, les orteils légèrement tournés vers l''extérieur.", "Libère les poignées de sécurité et abaisse-toi lentement en pliant les genoux et les hanches.", "Descends jusqu''à ce que tes cuisses soient parallèles à la plateforme ou aussi bas que ta mobilité le permet.", "Pousse à travers tes talons pour éloigner la plateforme et revenir à la position de départ.", "Re-engage les poignées de sécurité à la fin de ta série."]', '["Garde ton tronc engagé et le dos contre le coussin pendant tout le mouvement.", "Assure-toi que tes genoux suivent la ligne de tes orteils sans s''affaisser vers l''intérieur.", "Contrôle la descente et évite de rebondir au fond du mouvement.", "Concentre-toi sur le fait de pousser avec tes talons plutôt qu''avec le devant de tes pieds lors de la montée.", "Maintiens une respiration régulière en inspirant en descendant et expirant en montant."]', '["Keep your core engaged and back pressed against the pad throughout the entire movement", "Ensure knees track in line with your toes and don''t cave inward during the movement", "Control the descent and avoid bouncing at the bottom of the movement", "Focus on driving through your heels rather than the balls of your feet during the ascent", "Maintain steady breathing by inhaling on the way down and exhaling on the way up"]', 'b7c0fca8-8f01-4c48-bea3-b691939e92bc', 'lever-squat-medium-stance', NULL, NULL);
INSERT INTO public.exercises VALUES ('dc2863c4-f514-4074-bb94-e794ec9acffd', 'Kettlebell Swing - Style Américain', NULL, 'سوينغ كيتل بل - بطريقة أمريكية', 'Kettlebell swing - American style', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 128, '/videos/bodyweight/kettlebell-swing-american-style.mp4', NULL, NULL, NULL, '/videos/thumbnails/kettlebell-swing-american-style.jpg', NULL, '["La puissance vient de tes hanches et de tes fessiers, pas de tes bras - concentre-toi sur le mouvement de flexion des hanches", "Maintiens ton gainage actif sur toute l''amplitude pour protéger le bas du dos", "Contrôle la descente, mais sois explosif lors de la montée pour garder le bon élan", "Veille à ce que le kettlebell atteigne une pleine extension au-dessus de la tête avec les bras droits à chaque répétition", "Commence avec un poids léger pour maîtriser la technique avant de passer à des kettlebells plus lourds"]', '["Ne pas maintenir une posture correcte du dos et de la poitrine", "Ne pas engager le gainage, ce qui pourrait entraîner des douleurs lombaires"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "kettlebell", "kettlebell swing - american style"]', true, '2026-04-03 12:24:57.419851+00', '2026-04-03 12:24:57.419851+00', 'Cet exercice sollicite l''ensemble du corps. Prépare-toi à allier force et explosivité !', '["Ne pas maintenir une posture correcte du dos et de la poitrine", "Ne pas engager le gainage, ce qui pourrait entraîner des douleurs lombaires"]', true, '["Stand with feet hip-width apart and grip the kettlebell handle with both hands using an overhand grip", "Begin with the kettlebell overhead with arms fully extended and core engaged", "Initiate the downswing by hinging at the hips and allowing the kettlebell to swing down between your legs in a controlled manner", "Keep your back straight and chest up throughout the entire movement", "Explosively drive your hips forward and squeeze your glutes to propel the kettlebell back up to the overhead position", "Allow the kettlebell to swing back down naturally and repeat the movement in a smooth rhythm"]', '["Place-toi debout avec les pieds écartés à la largeur des hanches et tiens la poignée du kettlebell avec les deux mains en prise pronation", "Commence avec le kettlebell au-dessus de ta tête, les bras complètement tendus et le gainage actif", "Lance le kettlebell vers le bas en fléchissant les hanches, en le laissant descendre entre tes jambes de manière contrôlée", "Maintiens le dos droit et la poitrine en avant tout au long du mouvement", "Pousse explosivement avec tes hanches et serre les fessiers pour ramener le kettlebell au-dessus de ta tête en une seule fluidité", "Laisse le kettlebell redescendre naturellement et répète le mouvement en gardant un rythme smooth"]', '["La puissance vient de tes hanches et de tes fessiers, pas de tes bras - concentre-toi sur le mouvement de flexion des hanches", "Maintiens ton gainage actif sur toute l''amplitude pour protéger le bas du dos", "Contrôle la descente, mais sois explosif lors de la montée pour garder le bon élan", "Veille à ce que le kettlebell atteigne une pleine extension au-dessus de la tête avec les bras droits à chaque répétition", "Commence avec un poids léger pour maîtriser la technique avant de passer à des kettlebells plus lourds"]', '["The power comes from your hips and glutes, not your arms - focus on the hip hinge movement", "Keep your core tight throughout the entire range of motion to protect your lower back", "Control the descent but be explosive on the upward drive to maintain proper momentum", "Ensure the kettlebell reaches full overhead extension with arms straight at the top of each rep", "Start with a lighter weight to master the technique before progressing to heavier kettlebells"]', '1a3c2a1d-eb55-4199-8f9c-6d332c824c5d', 'kettlebell-swing-american-style', NULL, NULL);
INSERT INTO public.exercises VALUES ('04ad1652-2154-4c7d-bbbf-15c4f92f8805', 'Lunge Matrix', NULL, 'مصفوفة الانخفاضات', 'Lunge matrix', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/lunge-matrix.mp4', NULL, NULL, NULL, '/videos/thumbnails/lunge-matrix.jpg', NULL, '["Gardez votre torse droit pendant toutes les variétés de fentes pour maintenir un bon alignement de la colonne vertébrale.", "Assurez-vous que votre genou avant reste au-dessus de votre cheville et ne s''affaisse pas vers l''intérieur pendant les mouvements.", "Atterrissez doucement sur l''avant de vos pieds lors des pas pour réduire l''impact sur les articulations.", "Maintenez le contrôle lors des transitions entre les différentes directions de fentes, ne vous précipitez pas.", "Portez le plus de poids possible sur votre jambe avant lors des fentes avant et diagonales pour maximiser l''activation des quadriceps."]', '["Ne pas plier suffisamment les genoux, ce qui réduit l''efficacité de l''exercice.", "Se pencher en avant, ce qui peut entraîner des tensions lombaires."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "lunge matrix"]', true, '2026-04-03 12:24:57.627019+00', '2026-04-03 12:24:57.627019+00', 'Position de départ : Tenez-vous droit, pieds écartés à la largeur des hanches, mains sur les hanches ou sur les côtés pour assurer l''équilibre. Exécution : Opérez des fentes dans plusieurs directions, y compris vers l''avant, vers l''arrière, latérales et en diagonale, pour un mouvement complet.', '["Ne pas plier suffisamment les genoux, ce qui réduit l''efficacité de l''exercice.", "Se pencher en avant, ce qui peut entraîner des tensions lombaires."]', true, '["Stand with feet hip-width apart and engage your core muscles", "Step forward into a lunge, lowering your hips until both knees are bent at 90 degrees", "Return to starting position and immediately step backward into a reverse lunge", "Step laterally to one side, sitting back into the hip while keeping the other leg straight", "Perform diagonal lunges by stepping at 45-degree angles forward and backward", "Complete the full sequence on one leg before switching to the other side"]', '["Tenez-vous droit, pieds écartés à la largeur des hanches et engagez vos muscles centraux.", "Faites un pas en avant dans une fente, en abaissant vos hanches jusqu''à ce que vos deux genoux soient pliés à 90 degrés.", "Retournez à la position de départ et immédiatement, faites un pas en arrière dans une fente inverse.", "Faites un pas sur le côté, en vous asseyant sur la hanche tout en gardant l''autre jambe droite.", "Effectuez des fentes diagonales en mettant le pied à 45 degrés, vers l''avant et vers l''arrière.", "Complétez toute la séquence d''un côté avant de passer à l''autre."]', '["Gardez votre torse droit pendant toutes les variétés de fentes pour maintenir un bon alignement de la colonne vertébrale.", "Assurez-vous que votre genou avant reste au-dessus de votre cheville et ne s''affaisse pas vers l''intérieur pendant les mouvements.", "Atterrissez doucement sur l''avant de vos pieds lors des pas pour réduire l''impact sur les articulations.", "Maintenez le contrôle lors des transitions entre les différentes directions de fentes, ne vous précipitez pas.", "Portez le plus de poids possible sur votre jambe avant lors des fentes avant et diagonales pour maximiser l''activation des quadriceps."]', '["Keep your torso upright throughout all lunge variations to maintain proper spine alignment", "Ensure your front knee tracks over your ankle and doesn''t collapse inward during any movement", "Land softly on the balls of your feet when stepping to reduce impact on joints", "Maintain control during transitions between different lunge directions rather than rushing through the movements", "Keep most of your weight on your front leg during forward and diagonal lunges for maximum quad activation"]', '51f8b5e9-3c10-4727-820a-ba77857a46b2', 'lunge-matrix', NULL, NULL);
INSERT INTO public.exercises VALUES ('f36f36f2-2902-410f-9b09-f9e9ffa10374', 'Curl à la corde avec câble bas', NULL, NULL, 'Low Cable Rope Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 4, '/videos/biceps/low-cable-rope-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/low-cable-rope-curl.jpg', NULL, '["Garde les bras supérieurs collés à tes côtés tout au long du mouvement", "Concentre-toi sur la contraction de tes biceps en haut du curl pour une activation maximale", "Utilise un rythme lent et contrôlé, surtout lors de la phase de descente", "Évite de balancer ton corps ou d''utiliser l''élan pour soulever le poids", "Maintiens la tension dans le câble tout au long du mouvement"]', '["Ne pas garder les coudes collés au corps", "Utiliser un poids trop lourd qui amène à balancer le corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "cable", "low cable rope curl"]', true, '2026-04-03 12:24:57.615576+00', '2026-04-03 12:24:57.615576+00', 'Position de départ : Tiens-toi face à un appareil à câble bas avec une corde. Exécution : Plie les coudes pour ramener la corde vers les épaules, en écartant les extrémités de la corde en haut du mouvement.', '["Ne pas garder les coudes collés au corps", "Utiliser un poids trop lourd qui amène à balancer le corps"]', true, '["Set the cable pulley to the lowest position and attach a rope handle", "Stand 2-3 feet from the machine with feet hip-width apart for stable base", "Grasp the rope with both hands using an underhand grip, palms facing up", "Keep your core engaged and shoulders back throughout the movement", "Curl the rope up by bending your elbows, stopping when your forearms are vertical", "Lower the weight slowly and under control back to the starting position"]', '["Place le câble au plus bas et fixe la poignée en corde", "Positionne-toi à 60-90 cm de la machine, les pieds écartés à la largeur des hanches pour une bonne stabilité", "Saisis la corde avec les deux mains en prise inversée, paumes vers le haut", "Garde les muscles du ventre engagés et les épaules en arrière durant tout le mouvement", "Fais monter la corde en pliant les coudes, arrêtant lorsque tes avant-bras sont verticaux", "Abaisse le poids lentement et de manière contrôlée jusqu''à la position de départ"]', '["Garde les bras supérieurs collés à tes côtés tout au long du mouvement", "Concentre-toi sur la contraction de tes biceps en haut du curl pour une activation maximale", "Utilise un rythme lent et contrôlé, surtout lors de la phase de descente", "Évite de balancer ton corps ou d''utiliser l''élan pour soulever le poids", "Maintiens la tension dans le câble tout au long du mouvement"]', '["Keep your upper arms pressed against your sides throughout the entire movement", "Focus on squeezing your biceps at the top of the curl for maximum muscle activation", "Use a slow and controlled tempo, especially during the lowering phase", "Avoid swinging your body or using momentum to lift the weight", "Maintain tension in the cable throughout the full range of motion"]', '40811c61-7369-4803-afc0-fa7b90f90522', 'low-cable-rope-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('22eeb91c-b4f6-4695-b59b-1f43e5e30c47', 'Leg Press : Renforce tes quadriceps !', NULL, NULL, 'Leg Press', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/leg-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/leg-press.jpg', NULL, '["Garde tes genoux alignés avec tes orteils pendant tout le mouvement pour éviter les blessures.", "Évite de mettre tes mains sur tes genoux, cela peut perturber la mécanique de mouvement.", "Ne laisse pas ton bas du dos s''arrondir en ramenant trop tes genoux vers ta poitrine.", "Concentre-toi sur la poussée par les talons plutôt que par les orteils pour maximiser l''activation des quadriceps.", "Commence avec un poids léger pour maîtriser la technique avant d''augmenter la charge."]', '["Genoux qui s''écartent des orteils, ce qui peut entraîner des blessures.", "Verrouillage complet des genoux en haut du mouvement, ce qui crée trop de pression sur les articulations."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "leg press"]', true, '2026-04-03 12:24:57.551194+00', '2026-04-03 12:24:57.551194+00', 'Position de départ : Assieds-toi sur la presse à cuisse, les pieds sur la plateforme et les genoux fléchis. Exécution : Pousse la plateforme vers l''avant en étendant complètement les jambes, puis redescends lentement à la position de départ.', '["Genoux qui s''écartent des orteils, ce qui peut entraîner des blessures.", "Verrouillage complet des genoux en haut du mouvement, ce qui crée trop de pression sur les articulations."]', true, '["Adjust the seat and backrest so your knees form a 90-degree angle when feet are placed on the footplate", "Position feet shoulder-width apart in the middle of the footplate with toes pointing slightly outward", "Grip the side handles for stability and keep your core engaged throughout the movement", "Push through your heels to extend your legs, avoiding locking your knees completely at the top", "Lower the weight slowly and under control until your knees return to the 90-degree starting position", "Maintain steady breathing, exhaling during the push phase and inhaling during the lowering phase"]', '["Ajuste le siège et le dossier pour que tes genoux forment un angle de 90 degrés lorsque tes pieds sont sur la plateforme.", "Positionne tes pieds à la largeur des épaules au centre de la plateforme, avec les orteils légèrement tournés vers l''extérieur.", "Saisis les poignées latérales pour la stabilité et garde ton ventre bien engagé durant tout le mouvement.", "Pousse avec tes talons pour étendre tes jambes, en évitant de verrouiller complètement tes genoux en haut.", "Descends le poids lentement et sous contrôle jusqu''à ce que tes genoux reviennent à la position de départ à 90 degrés.", "Respire régulièrement : expire pendant la phase de poussée et inspire lors de la phase de descente."]', '["Garde tes genoux alignés avec tes orteils pendant tout le mouvement pour éviter les blessures.", "Évite de mettre tes mains sur tes genoux, cela peut perturber la mécanique de mouvement.", "Ne laisse pas ton bas du dos s''arrondir en ramenant trop tes genoux vers ta poitrine.", "Concentre-toi sur la poussée par les talons plutôt que par les orteils pour maximiser l''activation des quadriceps.", "Commence avec un poids léger pour maîtriser la technique avant d''augmenter la charge."]', '["Keep your knees aligned with your toes throughout the entire range of motion to prevent injury", "Avoid placing your hands on your knees as this can interfere with proper movement mechanics", "Never allow your lower back to round by letting your knees come too close to your chest", "Focus on pushing through your heels rather than your toes to maximize quadriceps activation", "Start with lighter weight to master the form before progressively increasing the load"]', 'bcd8c3d9-5c9b-4a97-8b30-0e85de2488ff', 'leg-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('3243843c-0b67-45a4-8719-a15a3a4b032a', 'Fente avec torsion du tronc', NULL, NULL, 'Lunge With Spinal Twist', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/lunge-with-spinal-twist.mp4', NULL, NULL, NULL, '/videos/thumbnails/lunge-with-spinal-twist.jpg', NULL, '["Assure-toi que ton genou avant reste aligné au-dessus de ta cheville pour éviter toute tension", "Garde le torse droit tout au long du mouvement, évite de pencher en avant", "Ressens la rotation depuis ta sangle abdominale et le milieu du dos, évite de forcer la torsion depuis le bas du dos", "Veille à ce que ton genou arrière pointe vers le sol sans s’affaisser vers l''intérieur", "Contrôle les phases de descente et de montée de la fente pour maximiser l''engagement des quadriceps"]', '["Ne laisse pas ton genou avant dépasser ta cheville", "Ne tourne pas la taille sans engager le reste du corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "lunge with spinal twist"]', true, '2026-04-03 12:24:57.63219+00', '2026-04-03 12:24:57.63219+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, les mains jointes au niveau de la poitrine. Exécution : Fais un grand pas en avant avec un pied en position de fente tout en tournant ton torse vers la jambe avant, puis reviens à la position de départ et répète de l’autre côté.', '["Ne laisse pas ton genou avant dépasser ta cheville", "Ne tourne pas la taille sans engager le reste du corps"]', true, '["Step forward with your right foot into a deep lunge, ensuring your front knee tracks over your ankle", "Lower your body until both knees are bent at approximately 90 degrees", "Keep your torso upright and rotate your upper body toward your front leg while keeping your hips square", "Hold the twisted position briefly, then rotate back to center", "Push through your front heel to return to starting position", "Repeat the movement stepping forward with your left foot and twisting in the opposite direction"]', '["Fais un pas en avant avec ton pied droit en effectuant une fente profonde, en veillant à ce que ton genou avant soit au-dessus de ta cheville", "Abaisse ton corps jusqu''à ce que les deux genoux soient fléchis à environ 90 degrés", "Garde ton torse droit et fais une rotation de ton haut du corps vers ta jambe avant tout en maintenant les hanches carrées", "Tiens brièvement la position tordue, puis reviens au centre", "Pousse avec ton talon avant pour revenir à la position de départ", "Répète le mouvement en avançant avec ton pied gauche et en te tournant dans la direction opposée"]', '["Assure-toi que ton genou avant reste aligné au-dessus de ta cheville pour éviter toute tension", "Garde le torse droit tout au long du mouvement, évite de pencher en avant", "Ressens la rotation depuis ta sangle abdominale et le milieu du dos, évite de forcer la torsion depuis le bas du dos", "Veille à ce que ton genou arrière pointe vers le sol sans s’affaisser vers l''intérieur", "Contrôle les phases de descente et de montée de la fente pour maximiser l''engagement des quadriceps"]', '["Keep your front knee aligned over your ankle to prevent knee strain", "Maintain an upright torso throughout the movement and avoid leaning forward", "Rotate from your core and mid-spine rather than forcing the twist from your lower back", "Ensure your back knee points toward the ground and doesn''t cave inward", "Control the descent and ascent phases of the lunge to maximize quad engagement"]', 'e6286746-6da7-492e-9dc2-0688edeff3a9', 'lunge-with-spinal-twist', NULL, NULL);
INSERT INTO public.exercises VALUES ('88f55373-4567-4691-9c66-f33a45350859', 'Développé couché triceps avec barre', NULL, NULL, 'Lying Barbell Skull Crusher', 'Triceps', '[]', 'Triceps', 'Intermediate', 1, '/videos/triceps/lying-barbell-skull-crusher.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-barbell-skull-crusher.jpg', NULL, '["Garde tes bras supérieurs perpendiculaires au sol et évite de les laisser reculer", "Adopte un rythme contrôlé, surtout lors de la descente, pour maintenir la tension musculaire", "Commence avec un poids léger pour maîtriser la technique avant de passer à des charges plus lourdes", "Engage bien ton cœur et conserve une courbure naturelle dans le bas du dos", "Arrête la descente lorsque tu sens un bon étirement dans tes triceps, généralement quand la barre est près de ton front"]', '["Ne pas contrôler le mouvement lors de la descente", "Laisser les bras supérieurs bouger vers l''arrière"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "barbell", "lying barbell skull crusher"]', true, '2026-04-03 12:24:57.676474+00', '2026-04-03 12:24:57.676474+00', 'Position de départ : Allonge-toi sur un banc plat, barre en mains, bras tendus vers le haut, paumes tournées vers l''avant. Exécution : Abaisse la barre vers ton front en pliant les coudes, puis étends les bras pour revenir à la position de départ.', '["Ne pas contrôler le mouvement lors de la descente", "Laisser les bras supérieurs bouger vers l''arrière"]', true, '["Lie flat on a bench with feet firmly planted on the floor for stability", "Grip the barbell with hands about shoulder-width apart using an overhand grip", "Start with arms fully extended above your chest, keeping your shoulders stable", "Lower the weight slowly by bending only at the elbows until the bar approaches your forehead", "Keep your upper arms stationary throughout the entire movement", "Press the weight back up by extending your elbows to return to starting position"]', '["Allonge-toi sur le banc, pieds bien ancrés au sol pour la stabilité", "Saisis la barre avec les mains écartées à la largeur des épaules en prise pronation", "Commence avec les bras complètement étendus au-dessus de ta poitrine, épaules stables", "Abaisse lentement le poids en pliant uniquement les coudes jusqu''à ce que la barre approches de ton front", "Garde tes bras supérieurs immobiles durant tout le mouvement", "Pousse le poids vers le haut en étendant les coudes pour revenir à la position initiale"]', '["Garde tes bras supérieurs perpendiculaires au sol et évite de les laisser reculer", "Adopte un rythme contrôlé, surtout lors de la descente, pour maintenir la tension musculaire", "Commence avec un poids léger pour maîtriser la technique avant de passer à des charges plus lourdes", "Engage bien ton cœur et conserve une courbure naturelle dans le bas du dos", "Arrête la descente lorsque tu sens un bon étirement dans tes triceps, généralement quand la barre est près de ton front"]', '["Keep your upper arms perpendicular to the floor and avoid letting them drift backward", "Use a controlled tempo, especially on the lowering phase, to maintain muscle tension", "Start with lighter weight to master the form before progressing to heavier loads", "Keep your core engaged and maintain natural arch in your lower back", "Stop the descent when you feel a good stretch in your triceps, typically when the bar is near your forehead"]', 'babede27-efe6-473b-85a8-6ef01ce3fab7', 'lying-barbell-skull-crusher', NULL, NULL);
INSERT INTO public.exercises VALUES ('7047128f-9982-49c7-b4f6-44c55dde6083', 'Fentes au poids du corps', NULL, NULL, 'Lunges body weight', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/lunges-body-weight.mp4', NULL, NULL, NULL, '/videos/thumbnails/lunges-body-weight.jpg', NULL, '["Garde le torse droit tout au long du mouvement pour éviter de pencher en avant", "Conserve la majorité de ton poids sur la jambe avant et utilise la jambe arrière principalement pour l''équilibre", "Contrôle la descente lentement au lieu de tomber rapidement pour maximiser l''engagement musculaire", "Assure-toi que le genou avant suit la ligne de tes orteils pour éviter de solliciter le genou", "Fais un pas assez en avant pour que ton tibia avant reste vertical en position basse"]', '["Ne pas garder le torse droit", "Laisser le genou avant dépasser les orteils"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "lunges body weight"]', true, '2026-04-03 12:24:57.663227+00', '2026-04-03 12:24:57.663227+00', 'Position de départ : Tiens-toi droit, pieds écartés à la largeur des hanches, mains sur les hanches ou sur les côtés pour l''équilibre. Exécution : Avance un pied dans une position de fente, abaisse ton corps jusqu''à ce que tes deux genoux soient fléchis à environ 90 degrés, puis pousse à travers le talon avant pour revenir à la position de départ.', '["Ne pas garder le torse droit", "Laisser le genou avant dépasser les orteils"]', true, '["Stand with feet hip-width apart and engage your core for stability", "Take a large step forward with one leg, keeping your torso upright", "Lower your body by bending both knees until your front thigh is parallel to the floor and back knee nearly touches the ground", "Keep your front knee aligned over your ankle, not pushing forward past your toes", "Push through your front heel to return to the starting position", "Complete all repetitions on one leg before switching to the other leg"]', '["Tiens-toi avec les pieds écartés à la largeur des hanches et engage ton corps pour rester stable", "Fais un grand pas en avant avec une jambe, en gardant le torse droit", "Abaisse ton corps en fléchissant les deux genoux jusqu''à ce que ta cuisse avant soit parallèle au sol et que le genou arrière touche presque le sol", "Assure-toi que ton genou avant est aligné avec ta cheville, sans dépasser les orteils", "Pousse sur ton talon avant pour revenir à la position de départ", "Fais toutes tes répétitions sur une jambe avant de changer à l''autre jambe"]', '["Garde le torse droit tout au long du mouvement pour éviter de pencher en avant", "Conserve la majorité de ton poids sur la jambe avant et utilise la jambe arrière principalement pour l''équilibre", "Contrôle la descente lentement au lieu de tomber rapidement pour maximiser l''engagement musculaire", "Assure-toi que le genou avant suit la ligne de tes orteils pour éviter de solliciter le genou", "Fais un pas assez en avant pour que ton tibia avant reste vertical en position basse"]', '["Maintain an upright torso throughout the movement to avoid leaning forward", "Keep most of your weight on your front leg and use your back leg primarily for balance", "Control the descent slowly rather than dropping down quickly to maximize muscle engagement", "Ensure your front knee tracks in line with your toes to prevent knee strain", "Step far enough forward so your front shin remains vertical when in the bottom position"]', '5aea090d-1bca-427b-8960-c01f7a6f0211', 'lunges-body-weight', NULL, NULL);
INSERT INTO public.exercises VALUES ('88038b50-49aa-4724-a077-934734989be3', 'Boxe avec haltères en ombre', NULL, NULL, 'Dumbbell shadow box', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/dumbbell-shadow-box.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-shadow-box.jpg', NULL, '["Utilise des poids légers car il s''agit d''un mouvement cardio.", "Garde toujours ton abdomen engagé pour protéger le bas du dos.", "Contrôle toujours les haltères pour éviter les blessures.", "Concentre-toi sur des mouvements fluides et contrôlés au lieu de frapper de manière agressive.", "Reste en mouvement et léger sur tes pieds comme un vrai boxeur."]', '["Ne pas maintenir une posture adéquate", "Utiliser des poids trop lourds"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "dumbbell shadow box"]', true, '2026-04-03 12:24:56.566945+00', '2026-04-03 12:24:56.566945+00', 'Position de départ : Tiens-toi debout, pieds écartés à la largeur des épaules, en tenant des haltères légers à hauteur de poitrine, en posture de garde de boxe. Exécution : Effectue des mouvements de frappe alternés (jabs, crochets, uppercuts) tout en maintenant une bonne posture de boxeur et en bougeant sur tes pieds.', '["Ne pas maintenir une posture adéquate", "Utiliser des poids trop lourds"]', true, '["Stand with feet shoulder-width apart, holding a light dumbbell in each hand at chest level", "Bend your knees slightly and engage your core while maintaining an upright posture", "Begin throwing alternating punches forward, extending one arm fully while keeping the other at chest level", "Add in hooks by punching across your body, rotating your torso with each movement", "Incorporate uppercuts by punching upward in an arcing motion from your hip level", "Continue alternating between jabs, hooks, and uppercuts for the desired duration"]', '["Tiens-toi debout, pieds écartés à la largeur des épaules, avec un haltère léger dans chaque main à hauteur de poitrine.", "Fléchis légèrement les genoux et engage ton abdomen tout en gardant une posture droite.", "Commence par lancer des coups de poing alternés vers l''avant, en étendant un bras complètement tout en gardant l''autre à hauteur de poitrine.", "Ajoute des crochets en frappant à travers ton corps, en tournant le torse à chaque mouvement.", "Incorpore des uppercuts en frappant vers le haut dans un mouvement en arc depuis le niveau de la hanche.", "Continue d''alterner entre jabs, crochets et uppercuts pendant la durée souhaitée."]', '["Utilise des poids légers car il s''agit d''un mouvement cardio.", "Garde toujours ton abdomen engagé pour protéger le bas du dos.", "Contrôle toujours les haltères pour éviter les blessures.", "Concentre-toi sur des mouvements fluides et contrôlés au lieu de frapper de manière agressive.", "Reste en mouvement et léger sur tes pieds comme un vrai boxeur."]', '["Use lighter weights than usual since this is a cardio-focused movement", "Keep your core engaged throughout to protect your lower back", "Maintain control of the dumbbells at all times to prevent injury", "Focus on smooth, controlled movements rather than aggressive punching", "Keep your feet moving and stay light on your toes like a real boxer"]', '0ff5e9fe-9d15-426a-8c06-fd62a198dc47', 'dumbbell-shadow-box', NULL, NULL);
INSERT INTO public.exercises VALUES ('b1c667b2-c839-4747-b398-e6566d1c6a72', 'Extension Triceps avec Haltère Sur Le Dos - Un Bras', NULL, 'Extension Triceps بحال واحد', 'Lying Dumbbell Tricep Extension - One arm', 'Triceps', '[]', 'Triceps', 'Intermediate', 2, '/videos/triceps/lying-dumbbell-tricep-extension-one-arm.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-dumbbell-tricep-extension-one-arm.jpg', NULL, '["Maintiens ton bras supérieur complètement immobile durant tout le mouvement pour isoler le triceps.", "Utilise ta main libre pour soutenir et stabiliser ton bras de travail si nécessaire.", "Contrôle le poids lors des phases de descente et de montée pour maximiser l''engagement musculaire.", "Commence avec un poids plus léger que celui que tu utiliserais avec les deux bras pour garantir une bonne forme.", "Interromps l''exercice si tu ressens une douleur ou une gêne au coude."]', '["Laisser le bras supérieur bouger pendant l''exercice.", "Ne pas descendre assez bas pour sentir le triceps travailler."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "dumbbell", "lying dumbbell tricep extension - one arm"]', true, '2026-04-03 12:24:57.695565+00', '2026-04-03 12:24:57.695565+00', 'Position de départ : Allonge-toi sur un banc, un haltère dans une main, bras tendu au-dessus de ton épaule, paume vers l''intérieur. Exécution : Abaisse l''haltère en pliant uniquement au niveau du coude jusqu''à ce que ton avant-bras soit parallèle au sol, puis remonte à la position de départ.', '["Laisser le bras supérieur bouger pendant l''exercice.", "Ne pas descendre assez bas pour sentir le triceps travailler."]', true, '["Lie flat on a bench with your feet planted firmly on the floor", "Hold a dumbbell in one hand and extend your arm straight up above your shoulder", "Keep your upper arm stationary and slowly lower the weight by bending only at the elbow", "Lower until your forearm is parallel to the floor or you feel a stretch in your tricep", "Press the weight back up to the starting position by straightening your elbow", "Complete all repetitions on one arm before switching to the other side"]', '["Allonge-toi sur un banc, les pieds bien ancrés au sol.", "Tiens un haltère dans une main, bras tendu au-dessus de l''épaule.", "Garde le bras supérieur immobile et abaisse lentement le poids en pliant seulement le coude.", "Descends jusqu''à ce que ton avant-bras soit parallèle au sol ou que tu ressentes une tension dans le triceps.", "Pousse le poids vers le haut pour retourner à la position de départ.", "Effectue toutes les répétitions d''un côté avant de passer à l''autre bras."]', '["Maintiens ton bras supérieur complètement immobile durant tout le mouvement pour isoler le triceps.", "Utilise ta main libre pour soutenir et stabiliser ton bras de travail si nécessaire.", "Contrôle le poids lors des phases de descente et de montée pour maximiser l''engagement musculaire.", "Commence avec un poids plus léger que celui que tu utiliserais avec les deux bras pour garantir une bonne forme.", "Interromps l''exercice si tu ressens une douleur ou une gêne au coude."]', '["Keep your upper arm completely still throughout the movement to isolate the tricep", "Use your free hand to support and stabilize your working arm if needed", "Control the weight on both the lowering and lifting phases to maximize muscle engagement", "Start with lighter weight than you would use for both arms to ensure proper form", "Stop the movement if you feel any elbow pain or discomfort"]', 'a1b684f7-6cf3-41a7-9c1f-2321a8e0847a', 'lying-dumbbell-tricep-extension-one-arm', NULL, NULL);
INSERT INTO public.exercises VALUES ('76fed872-44b5-451b-996f-dc93859ac7f4', 'Half Squat Get Up', NULL, 'Half Squat Get Up', 'Half squat get up )', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/half-squat-get-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-squat-get-up.jpg', NULL, '["Garde tes genoux alignés avec tes orteils et évite de les laisser s''écrouler vers l''intérieur", "Concentre-toi sur l''utilisation de tes muscles des jambes, pas sur l''élan pour te relever", "Maintiens le contrôle pendant la phase de descente pour maximiser l''engagement musculaire et éviter de retomber sur le siège", "Commence par une surface plus haute si tu as des difficultés, puis descends progressivement à des surfaces plus basses au fur et à mesure que tu deviens plus fort", "Tiens bien ta poitrine droite et évite d''arrondir ton dos tout au long de l''exercice"]', '["Ne pas utiliser les jambes pour se relever", "Laisser les genoux s''éloigner des orteils"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "half squat get up )"]', true, '2026-04-03 12:24:57.01744+00', '2026-04-03 12:24:57.01744+00', 'Position de départ : Assis sur une chaise ou un banc, les pieds à plat au sol, écartés à la largeur des hanches, bras croisés sur la poitrine ou tendus vers l''avant pour l''équilibre. Exécution : Lève-toi en poussant sur tes talons et en engageant tes quadriceps, en t''arrêtant à mi-hauteur dans une position de squat, puis redescends lentement à la position assise.', '["Ne pas utiliser les jambes pour se relever", "Laisser les genoux s''éloigner des orteils"]', true, '["Sit on a sturdy chair or bench with your back straight and feet planted firmly on the ground", "Cross your arms over your chest or extend them forward for balance", "Engage your core and shift your weight slightly forward over your feet", "Drive through your heels and push up using your leg muscles until you reach a half-standing squat position", "Hold the position briefly, then slowly control the descent back to the seated position", "Repeat the movement maintaining proper form throughout"]', '["Assieds-toi sur une chaise ou un banc solide, dos droit et pieds bien ancrés au sol", "Croise les bras sur ta poitrine ou tends-les vers l''avant pour équilibrer", "Engage ton cœur et incline légèrement ton poids vers l''avant", "Pousse avec tes talons et relève-toi en utilisant tes muscles des jambes jusqu''à atteindre une position de squat à mi-hauteur", "Maintiens la position brièvement, puis contrôle ta descente vers la position assise", "Répète le mouvement en gardant une bonne posture tout au long de l''exercice"]', '["Garde tes genoux alignés avec tes orteils et évite de les laisser s''écrouler vers l''intérieur", "Concentre-toi sur l''utilisation de tes muscles des jambes, pas sur l''élan pour te relever", "Maintiens le contrôle pendant la phase de descente pour maximiser l''engagement musculaire et éviter de retomber sur le siège", "Commence par une surface plus haute si tu as des difficultés, puis descends progressivement à des surfaces plus basses au fur et à mesure que tu deviens plus fort", "Tiens bien ta poitrine droite et évite d''arrondir ton dos tout au long de l''exercice"]', '["Keep your knees aligned with your toes and avoid letting them cave inward during the movement", "Focus on using your leg muscles rather than momentum to rise up from the seated position", "Maintain control during the lowering phase to maximize muscle engagement and prevent dropping back onto the seat", "Start with a higher surface if you have difficulty with the movement and progress to lower surfaces as you get stronger", "Keep your chest up and avoid rounding your back throughout the entire exercise"]', 'c0386f57-3cd2-42e9-9c19-d2d3dc9aa3cb', 'half-squat-get-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('f7f2ff09-c08b-4c5f-a8db-edd6100b79d6', 'Squat au Poids du Corps', NULL, 'القرفصاء بوزن الجسم', 'Bodyweight Squat (air squat)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/bodyweight-squat-air-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/bodyweight-squat-air-squat.jpg', NULL, '["Gardez le torse droit, dos plat", "Les genoux suivent la direction des orteils", "Allez en profondeur si vous avez la mobilité", "Ne laissez pas les genoux s''affaisser", "C''est la base de tous les squats"]', '["Genoux qui s''écartent vers l''intérieur", "Absence de profondeur dans le squat"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "bodyweight squat (air squat)"]', true, '2026-04-03 12:24:55.774389+00', '2026-04-03 12:24:55.774389+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des épaules, les orteils légèrement tournés vers l''extérieur, bras le long du corps ou tendus devant vous pour l''équilibre. Exécution : Abaissez votre corps en poussant les hanches vers l''arrière et en fléchissant les genoux jusqu''à ce que vos cuisses soient parallèles au sol, puis poussez à travers vos talons pour revenir à la position de départ.', '["Genoux qui s''écartent vers l''intérieur", "Absence de profondeur dans le squat"]', true, '["Feet shoulder-width, toes slightly out", "Arms forward for balance", "Squat down until thighs parallel or below", "Drive up through heels"]', '["Pieds à la largeur des épaules, orteils légèrement dehors", "Bras tendus devant pour l''équilibre", "Descendez jusqu''à ce que les cuisses soient parallèles ou en dessous", "Poussez avec les talons pour remonter"]', '["Gardez le torse droit, dos plat", "Les genoux suivent la direction des orteils", "Allez en profondeur si vous avez la mobilité", "Ne laissez pas les genoux s''affaisser", "C''est la base de tous les squats"]', '["Keep chest up, back flat", "Knees track over toes", "Full depth if mobility allows", "Don''t let knees cave", "Foundation for all squats"]', 'f28e1faf-4677-453e-9007-8329d7a67e2d', 'bodyweight-squat-air-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('4f68b391-9f62-4c13-baf0-e3426c328da4', 'Flexion des biceps à la machine', NULL, NULL, 'Machine Bicep Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 8, '/videos/biceps/machine-bicep-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/machine-bicep-curl.jpg', NULL, '["Gardez les poignets droits, évitez de les plier pendant la flexion", "Ne laissez pas vos coudes s''écarter sur les côtés – gardez-les immobiles", "Concentrez-vous sur un mouvement contrôlé plutôt que sur le poids pour éviter les blessures", "Ne bloquez pas complètement vos coudes en bas pour maintenir la tension sur les biceps", "Expirez pendant la phase de montée et inspirez durant la descente"]', '["Tendre les bras complètement au bas du mouvement", "Utiliser trop de poids, ce qui provoque des mouvements brusques ou non contrôlés"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "machine", "machine bicep curl"]', true, '2026-04-03 12:24:57.744447+00', '2026-04-03 12:24:57.744447+00', 'Position de départ : Asseyez-vous sur la machine de flexion des biceps, les bras posés sur les coussins, mains agrippant les poignées. Exécution : Fléchissez vos coudes pour soulever le poids vers vos épaules, puis redescendez lentement.', '["Tendre les bras complètement au bas du mouvement", "Utiliser trop de poids, ce qui provoque des mouvements brusques ou non contrôlés"]', true, '["Adjust the seat height so your arms are parallel to the floor when extended", "Grip the handles with palms facing up, hands shoulder-width apart", "Keep your back pressed firmly against the pad throughout the movement", "Curl the weight up smoothly without using momentum or swinging", "Squeeze your biceps at the top of the movement for one second", "Lower the weight slowly taking 2-3 seconds to return to starting position"]', '["Réglez la hauteur du siège pour que vos bras soient parallèles au sol en position étendue", "Prenez les poignées avec les paumes vers le haut, les mains à la largeur des épaules", "Maintenez votre dos bien appuyé contre le coussin tout au long du mouvement", "Soulevez le poids en douceur sans élan ni balancement", "Contractez vos biceps en haut du mouvement pendant une seconde", "Descendez le poids lentement, en prenant 2-3 secondes pour retourner à la position de départ"]', '["Gardez les poignets droits, évitez de les plier pendant la flexion", "Ne laissez pas vos coudes s''écarter sur les côtés – gardez-les immobiles", "Concentrez-vous sur un mouvement contrôlé plutôt que sur le poids pour éviter les blessures", "Ne bloquez pas complètement vos coudes en bas pour maintenir la tension sur les biceps", "Expirez pendant la phase de montée et inspirez durant la descente"]', '["Keep your wrists straight and avoid bending them during the curl", "Don''t let your elbows flare out to the sides - keep them stationary", "Focus on controlled movement rather than heavy weight to prevent injury", "Avoid fully locking out your elbows at the bottom to maintain tension on the biceps", "Breathe out during the lifting phase and breathe in during the lowering phase"]', '2dbfdf97-301b-423d-a27c-7485137e50f4', 'machine-bicep-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('9d9e16b8-15f1-40da-9566-4a2514547fd9', 'Kickback de Fessiers à Une Jambe', NULL, NULL, 'Machine Glute Kickback Single Leg', 'Glutes', '[]', 'Glutes', 'Beginner', 8, '/videos/glutes/machine-glute-kickback-single-leg.mp4', NULL, NULL, NULL, '/videos/thumbnails/machine-glute-kickback-single-leg.jpg', NULL, '["Engage ton gainage tout au long de l''exercice pour protéger ton bas du dos", "Ne te laisse pas entraîner par l''élan, concentre-toi sur une contraction musculaire contrôlée", "Garde la colonne vertébrale neutre, évite de cambrer excessivement le bas du dos", "Commence avec des poids légers pour bien maîtriser la technique avant d''augmenter les charges", "Assure-toi d''effectuer le même nombre de répétitions de chaque côté pour un équilibre musculaire"]', '["Ne pas engager suffisamment les fessiers pendant l''exercice", "Utiliser trop d''élan au lieu de faire une contraction contrôlée"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "machine", "machine glute kickback single leg"]', true, '2026-04-03 12:24:57.75764+00', '2026-04-03 12:24:57.75764+00', 'Positionne-toi sur la machine de kickback en s’assurant qu’un pied est bien fixé sur la plateforme. Tire ta jambe vers l’arrière en serrant les fessiers, puis redescends lentement à la position initiale. Répète avec l’autre jambe.', '["Ne pas engager suffisamment les fessiers pendant l''exercice", "Utiliser trop d''élan au lieu de faire une contraction contrôlée"]', true, '["Adjust the machine height so the footplate aligns with your ankle when standing upright", "Position your non-working leg firmly on the ground with a slight bend in the knee for stability", "Grip the handles with both hands and lean your torso slightly forward to maintain balance", "Place your working foot securely on the footplate with your knee slightly bent", "Drive your leg back in a smooth arc motion, focusing on squeezing your glute at the peak contraction", "Lower your leg back to the starting position with control, maintaining tension throughout the movement"]', '["Règle la hauteur de la machine pour que la plateforme soit au niveau de ta cheville quand tu es debout", "Assure-toi que ta jambe non active est bien posée au sol, légèrement fléchie pour la stabilité", "Prends les poignées avec les deux mains et penche-toi légèrement en avant pour garder l’équilibre", "Place ton pied en action sur la plateforme avec le genou légèrement fléchi", "Pousse ta jambe vers l’arrière en un mouvement fluide, en concentrant sur la contraction des fessiers au sommet du mouvement", "Redescends ta jambe à la position de départ avec contrôle, en maintenant la tension tout au long du mouvement"]', '["Engage ton gainage tout au long de l''exercice pour protéger ton bas du dos", "Ne te laisse pas entraîner par l''élan, concentre-toi sur une contraction musculaire contrôlée", "Garde la colonne vertébrale neutre, évite de cambrer excessivement le bas du dos", "Commence avec des poids légers pour bien maîtriser la technique avant d''augmenter les charges", "Assure-toi d''effectuer le même nombre de répétitions de chaque côté pour un équilibre musculaire"]', '["Keep your core engaged throughout the entire movement to prevent lower back compensation", "Avoid using momentum or swinging your leg - focus on controlled muscle contraction", "Maintain a neutral spine position and avoid excessive arching of the lower back", "Start with lighter weight to master the movement pattern before progressing to heavier loads", "Ensure equal repetitions on both legs to maintain muscular balance"]', '7c8e22b4-159b-4f19-8100-e05428bf1b1f', 'machine-glute-kickback-single-leg', NULL, NULL);
INSERT INTO public.exercises VALUES ('90a0618f-6ab0-43cb-8cf2-b8628a098682', 'Jump Squats', NULL, 'قفزات سكوات', 'Jump squats', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/jump-squats.mp4', NULL, NULL, NULL, '/videos/thumbnails/jump-squats.jpg', NULL, '["Atterris en douceur pour minimiser l''impact.", "Absorbe l''impact grâce à tes jambes.", "Ne verrouille pas les genoux en atterrissant.", "Utilise la puissance de tes jambes et de tes hanches.", "Idéal pour améliorer la puissance explosive."]', '["Ne pas plier les genoux à l''atterrissage.", "Sauter sans contrôle.", "Adopter une mauvaise position de squat."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "jump squats"]', true, '2026-04-03 12:24:57.372099+00', '2026-04-03 12:24:57.372099+00', 'Renforce tes quadriceps tout en développant ton explosivité !', '["Ne pas plier les genoux à l''atterrissage.", "Sauter sans contrôle.", "Adopter une mauvaise position de squat."]', true, '["Start in squat position", "Explode up, jumping off floor", "Land softly with bent knees", "Immediately descend into next squat"]', '["Adopte une position de squat, pieds écartés à la largeur des épaules.", "Saute aussi haut que possible en explosant à partir du squat.", "Atterris en douceur sur les jambes fléchies.", "Descends immédiatement dans le squat suivant."]', '["Atterris en douceur pour minimiser l''impact.", "Absorbe l''impact grâce à tes jambes.", "Ne verrouille pas les genoux en atterrissant.", "Utilise la puissance de tes jambes et de tes hanches.", "Idéal pour améliorer la puissance explosive."]', '["Land softly (quiet landings)", "Absorb impact with legs", "Don''t lock knees on landing", "Power comes from legs and hips", "Great for explosive power"]', '8a0a9a9f-ff9b-449f-ba4a-d30bfbc9ca2d', 'jump-squats', NULL, NULL);
INSERT INTO public.exercises VALUES ('cea9794d-edff-443d-be27-b11a31d2d3f5', 'Fente latérale avec haltère', NULL, NULL, 'Dumbbell Side lunge', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 2, '/videos/quadriceps/dumbbell-side-lunge.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-side-lunge.jpg', NULL, '["Gardez la poitrine levée et évitez de vous pencher en avant pour maintenir un bon alignement de la colonne vertébrale", "Assurez-vous que le genou de la jambe qui effectue la fente est bien aligné avec les orteils et ne s''effondre pas vers l''intérieur", "Contrôlez la descente et évitez de rebondir au bas du mouvement", "Concentrez-vous sur le talon de la jambe de travail plutôt que sur les orteils", "Commencez avec des poids légers pour maîtriser le mouvement avant de passer à des charges plus lourdes"]', '["Pencher le torse vers l''avant", "Laisser le genou aller trop à l''intérieur pendant la descente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell side lunge"]', true, '2026-04-03 12:24:56.594045+00', '2026-04-03 12:24:56.594045+00', 'Position de départ : Tenez-vous droit, les pieds écartés à la largeur des hanches, en tenant un haltère à deux mains au niveau de la poitrine ou un dans chaque main sur les côtés. Exécution : Faites un grand pas sur le côté, abaissez votre corps en pliant la jambe qui se déplace tout en gardant l’autre jambe droite, puis poussez pour revenir à la position de départ.', '["Pencher le torse vers l''avant", "Laisser le genou aller trop à l''intérieur pendant la descente"]', true, '["Stand with feet hip-width apart and hold dumbbells securely with a firm grip", "Take a large step to one side, keeping your torso upright and core engaged", "Lower your body by bending the knee of the stepping leg while keeping the opposite leg straight", "Descend until your thigh is parallel to the floor or as low as comfortable", "Push through the heel of the bent leg to return to the starting position", "Repeat for desired reps then switch to the other side"]', '["Tenez-vous avec les pieds écartés à la largeur des hanches et saisissez fermement les haltères", "Faites un grand pas sur le côté en gardant le torse droit et le gainage actif", "Abaissez votre corps en pliant le genou de la jambe qui se déplace tout en gardant l''autre jambe droite", "Descendez jusqu''à ce que votre cuisse soit parallèle au sol ou aussi bas que vous vous sentez à l''aise", "Poussez sur le talon de la jambe fléchie pour revenir à la position de départ", "Répétez le mouvement pour le nombre de répétitions souhaité, puis changez de côté"]', '["Gardez la poitrine levée et évitez de vous pencher en avant pour maintenir un bon alignement de la colonne vertébrale", "Assurez-vous que le genou de la jambe qui effectue la fente est bien aligné avec les orteils et ne s''effondre pas vers l''intérieur", "Contrôlez la descente et évitez de rebondir au bas du mouvement", "Concentrez-vous sur le talon de la jambe de travail plutôt que sur les orteils", "Commencez avec des poids légers pour maîtriser le mouvement avant de passer à des charges plus lourdes"]', '["Keep your chest up and avoid leaning forward excessively to maintain proper spinal alignment", "Ensure the knee of the lunging leg tracks in line with your toes and doesn''t cave inward", "Control the descent and avoid bouncing at the bottom of the movement", "Keep most of your weight on the heel of the working leg rather than the toes", "Start with lighter weight to master the movement pattern before progressing to heavier loads"]', 'af494781-9fba-41df-b403-79d04db6deae', 'dumbbell-side-lunge', NULL, NULL);
INSERT INTO public.exercises VALUES ('c016ae2a-0f9e-47f5-a96e-3d348b8a938d', 'Mountain Climbers Croisé', NULL, 'تسلق الجبال المتقاطع', 'Mountain climber cross body tuck', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/mountain-climber-cross-body-tuck.mp4', NULL, NULL, NULL, '/videos/thumbnails/mountain-climber-cross-body-tuck.jpg', NULL, '["Garde tes hanches stables, évite de les faire tourner excessivement pendant le mouvement croisé", "Assure-toi que tes poignets et épaules sont solides en poussant fermement avec tes paumes", "Privilégie le contrôle du mouvement plutôt que la vitesse pour maximiser l''engagement du tronc", "Évite que tes hanches ne montent ou ne descendent pendant l''exercice", "Arrête-toi si tu ressens une douleur dans le bas du dos et vérifie ta forme"]', '["Hanches trop hautes ou basses", "Mouvement trop rapide sans contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "mountain climber cross body tuck"]', true, '2026-04-03 12:24:57.80081+00', '2026-04-03 12:24:57.80081+00', 'Position de départ : Commence en position de planche haute, les mains sous les épaules, le corps aligné de la tête aux talons. Exécution : Alterne en amenant chaque genou vers le coude opposé tout en gardant la position de planche, en créant une rotation dans le tronc.', '["Hanches trop hautes ou basses", "Mouvement trop rapide sans contrôle"]', true, '["Start in a high plank position with hands flat on the ground directly under your shoulders", "Keep your core engaged and maintain a straight line from head to heels throughout the movement", "Bring your right knee across your body toward your left elbow, then return to plank position", "Immediately bring your left knee across your body toward your right elbow, then return to plank position", "Continue alternating sides in a controlled, rhythmic motion", "Maintain steady breathing throughout the exercise"]', '["Commence en position de planche haute, mains à plat sous les épaules", "Garde le tronc engagé et le corps aligné de la tête aux talons pendant tout le mouvement", "Amène ton genou droit vers ton coude gauche, puis retourne en position de planche", "Aussitôt, amène ton genou gauche vers ton coude droit, puis retourne en position de planche", " Continue à alterner les côtés avec un mouvement contrôlé et rythmique", "Reste concentré sur ta respiration tout au long de l''exercice"]', '["Garde tes hanches stables, évite de les faire tourner excessivement pendant le mouvement croisé", "Assure-toi que tes poignets et épaules sont solides en poussant fermement avec tes paumes", "Privilégie le contrôle du mouvement plutôt que la vitesse pour maximiser l''engagement du tronc", "Évite que tes hanches ne montent ou ne descendent pendant l''exercice", "Arrête-toi si tu ressens une douleur dans le bas du dos et vérifie ta forme"]', '["Keep your hips level and avoid rotating them excessively during the cross-body movement", "Maintain strong wrist and shoulder stability by pressing firmly through your palms", "Focus on controlled movement rather than speed to maximize core engagement", "Avoid letting your hips pike up or sag down during the exercise", "Stop if you feel strain in your lower back and reassess your form"]', '7ade83ba-d8c1-4947-aab0-8a15506c70e5', 'mountain-climber-cross-body-tuck', NULL, NULL);
INSERT INTO public.exercises VALUES ('aa5ad22b-f8d3-4fc8-8abb-3d47447d0153', 'Squats jusqu''aux genoux', NULL, NULL, 'Squats to knee', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/squats-to-knee.mp4', NULL, NULL, NULL, '/videos/thumbnails/squats-to-knee.jpg', NULL, '["Assure-toi que tes genoux sont alignés avec tes orteils et évite qu''ils ne s''effondrent vers l''intérieur.", "Garde le dos droit en maintenant le torse relevé, sans arrondir le bas du dos.", "Répartis bien ton poids sur l''ensemble des pieds, en mettant l''accent sur la poussée des talons.", "Contrôle ta descente pour maximiser l''engagement musculaire et prévenir les blessures.", "Arrête-toi à une profondeur qui permet un bon maintien de la forme plutôt que de forcer une amplitude excessive."]', '["Pencher le torse trop en avant.", "Laisser les genoux s''effondrer vers l''intérieur."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "squats to knee"]', true, '2026-04-03 12:24:59.487432+00', '2026-04-03 12:24:59.487432+00', 'Commence avec les pieds à la largeur des épaules, les orteils légèrement tournés vers l''extérieur. Abaisse ton corps en pliant les hanches et les genoux jusqu''à ce que tes cuisses soient parallèles au sol, puis pousse sur tes talons pour revenir à la position de départ.', '["Pencher le torse trop en avant.", "Laisser les genoux s''effondrer vers l''intérieur."]', true, '["Stand with feet shoulder-width apart and engage your core muscles", "Keep your chest up and shoulders back throughout the entire movement", "Lower your body by pushing your hips back and bending your knees as if sitting in a chair", "Descend until your thighs are parallel to the floor or as low as your mobility allows", "Push through your heels and squeeze your glutes to return to the starting position", "Maintain control throughout both the lowering and rising phases"]', '["Adopte une position debout avec les pieds à la largeur des épaules et engage ton ventre.", "Garde le torse relevé et les épaules tirées en arrière pendant tout le mouvement.", "Abaisse ton corps en poussant les hanches en arrière et en pliant les genoux comme si tu allais t''asseoir sur une chaise.", "Descends jusqu''à ce que tes cuisses soient parallèles au sol ou aussi bas que tes capacités le permettent.", "Pousse sur tes talons et contracte les fessiers pour revenir à la position initiale.", "Reste contrôlé tout au long de la descente et de la montée."]', '["Assure-toi que tes genoux sont alignés avec tes orteils et évite qu''ils ne s''effondrent vers l''intérieur.", "Garde le dos droit en maintenant le torse relevé, sans arrondir le bas du dos.", "Répartis bien ton poids sur l''ensemble des pieds, en mettant l''accent sur la poussée des talons.", "Contrôle ta descente pour maximiser l''engagement musculaire et prévenir les blessures.", "Arrête-toi à une profondeur qui permet un bon maintien de la forme plutôt que de forcer une amplitude excessive."]', '["Keep your knees aligned with your toes and avoid letting them cave inward", "Maintain a neutral spine by keeping your chest up and avoiding rounding your back", "Distribute your weight evenly across your feet, focusing on pushing through your heels", "Control the descent to maximize muscle engagement and prevent injury", "Stop at a depth that maintains proper form rather than forcing excessive range of motion"]', '83a25d92-34c9-43cd-aeac-6af796aa9c6b', 'squats-to-knee', NULL, NULL);
INSERT INTO public.exercises VALUES ('10b0aa65-7f46-4477-af84-210523a07b35', 'Tirage Vertical Prise Neutre', NULL, 'سيطرة على ظهر بكفاءة', 'Neutral Grip Lat Pulldown', 'Back', '[]', 'Back', 'Beginner', 4, '/videos/back/neutral-grip-lat-pulldown.mp4', NULL, NULL, NULL, '/videos/thumbnails/neutral-grip-lat-pulldown.jpg', NULL, '["Garde tes épaules basses et en arrière tout au long du mouvement pour éviter de te blesser", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en pensant à tirer tes coudes derrière ton corps", "Maintiens un tempo contrôlé, surtout pendant la phase de retour, pour maximiser l''engagement musculaire et prévenir les blessures", "Évite de te pencher excessivement en arrière ou d''utiliser de l''élan pour finir le mouvement", "Garde tes poignets droits et alignés avec tes avant-bras pour éviter les tensions."]', '["Ne pas garder le dos droit en tirant", "Utiliser trop de poids et perdre le contrôle du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "neutral grip lat pulldown"]', true, '2026-04-03 12:24:57.855668+00', '2026-04-03 12:24:57.855668+00', 'Position de départ : Assieds-toi à la machine à tirage vertical avec une prise neutre (paumes face à face). Exécution : Tire la barre vers ta poitrine en gardant les coudes près du corps, puis redescends lentement à la position de départ.', '["Ne pas garder le dos droit en tirant", "Utiliser trop de poids et perdre le contrôle du mouvement"]', true, '["Adjust the knee pad to secure your legs and prevent your body from lifting during the movement", "Grasp the neutral grip handles with arms fully extended overhead, maintaining a slight forward lean of your torso", "Initiate the pull by depressing your shoulder blades and drawing your elbows down and back toward your sides", "Pull the handles to your upper chest level while keeping your chest up and shoulders back", "Squeeze your lat muscles at the bottom of the movement for a brief pause", "Slowly return the weight to the starting position, maintaining tension throughout the eccentric phase"]', '["Ajuste le coussin de genoux pour sécuriser tes jambes et éviter que ton corps ne se soulève pendant le mouvement", "Prends les poignées en prise neutre avec les bras tendus au-dessus de ta tête, en te penchant légèrement en avant", "Commence le tirage en abaissant tes omoplates et en tirant tes coudes vers le bas et l''arrière, près de tes côtés", "Tire les poignées jusqu''à la hauteur de ta poitrine tout en gardant le torse relevé et les épaules en arrière", "Contracte tes muscles du dos au bas du mouvement pendant une brève pause", "Redescends lentement le poids à la position de départ en maintenant la tension pendant l''excentrique."]', '["Garde tes épaules basses et en arrière tout au long du mouvement pour éviter de te blesser", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en pensant à tirer tes coudes derrière ton corps", "Maintiens un tempo contrôlé, surtout pendant la phase de retour, pour maximiser l''engagement musculaire et prévenir les blessures", "Évite de te pencher excessivement en arrière ou d''utiliser de l''élan pour finir le mouvement", "Garde tes poignets droits et alignés avec tes avant-bras pour éviter les tensions."]', '["Keep your shoulders down and back throughout the entire movement to prevent shoulder impingement", "Focus on pulling with your back muscles rather than your arms by thinking about driving your elbows behind your body", "Maintain a controlled tempo, especially during the return phase, to maximize muscle engagement and prevent injury", "Avoid leaning back excessively or using momentum to complete the movement", "Keep your wrists straight and in line with your forearms to prevent strain"]', 'b93996af-6946-4cf8-88e0-792b1f545750', 'neutral-grip-lat-pulldown', NULL, NULL);
INSERT INTO public.exercises VALUES ('88aef276-da20-47f8-a953-295cbb5e2afb', 'Levez-vous en un seul mouvement vers l''avant !', NULL, 'حركة النهوض على رجل واحدة !', 'Single leg get up into lunge', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/single-leg-get-up-into-lunge.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-leg-get-up-into-lunge.jpg', NULL, '["Gardez vos abdominaux engagés pendant tout le mouvement pour protéger votre bas du dos.", "Contrôlez le mouvement de roulade plutôt que d''utiliser l''élan pour éviter de fatiguer votre colonne vertébrale.", "Veillez à ce que votre genou avant reste aligné au-dessus de votre cheville pendant la fente.", "Commencez lentement pour maîtriser la coordination avant d''augmenter la vitesse.", "Concentrez-vous sur des transitions fluides entre chaque phase de l''exercice."]', '["Ne pas garder le ventre bien engagé, ce qui peut provoquer des douleurs lombaires.", "Laisser le genou avant dépasser les orteils pendant la fente."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "single leg get up into lunge"]', true, '2026-04-03 12:24:59.234769+00', '2026-04-03 12:24:59.234769+00', 'Position de départ : Allongez-vous sur le dos, bras le long du corps, une jambe tendue vers le plafond. Passons à l''action : relevez-vous en utilisant votre force, puis faites le pas en arrière dans une fente !', '["Ne pas garder le ventre bien engagé, ce qui peut provoquer des douleurs lombaires.", "Laisser le genou avant dépasser les orteils pendant la fente."]', true, '["Lie on your back with one leg extended toward the ceiling and the other leg bent with foot flat on the floor", "Engage your core and use your arms to help roll up to a sitting position while keeping the raised leg elevated", "Continue the movement by rolling forward and placing the raised leg down to stand on both feet", "Once standing, immediately step the opposite leg back into a reverse lunge position", "Lower your back knee toward the ground while keeping your front knee aligned over your ankle", "Return to standing position to complete one repetition"]', '["Allongez-vous sur le dos avec une jambe tendue vers le plafond et l''autre jambe pliée, pied à plat au sol.", "Serrez votre ceinture abdominale et utilisez vos bras pour vous aider à vous redresser tout en maintenant la jambe levée.", "Poursuivez en vous retournant et en posant la jambe levée pour vous retrouver sur vos deux pieds.", "Dès que vous êtes debout, faites immédiatement un pas en arrière avec l''autre jambe dans une position de fente.", "Abaissez votre genou arrière vers le sol tout en gardant votre genou avant aligné au-dessus de votre cheville.", "Revenez à la position debout pour terminer une répétition."]', '["Gardez vos abdominaux engagés pendant tout le mouvement pour protéger votre bas du dos.", "Contrôlez le mouvement de roulade plutôt que d''utiliser l''élan pour éviter de fatiguer votre colonne vertébrale.", "Veillez à ce que votre genou avant reste aligné au-dessus de votre cheville pendant la fente.", "Commencez lentement pour maîtriser la coordination avant d''augmenter la vitesse.", "Concentrez-vous sur des transitions fluides entre chaque phase de l''exercice."]', '["Keep your core engaged throughout the entire movement to protect your lower back", "Control the rolling motion rather than using momentum to avoid straining your spine", "Ensure your front knee stays aligned over your ankle during the lunge portion", "Start with the movement slowly to master the coordination before increasing speed", "Focus on smooth transitions between each phase of the exercise"]', 'f3b5098c-a02d-44ce-941e-2afca2f7329f', 'single-leg-get-up-into-lunge', NULL, NULL);
INSERT INTO public.exercises VALUES ('139293bf-4719-4f24-bff9-8e7382ba8c39', 'Fente Sprinter Explosive (Gauche)', NULL, NULL, 'Explosive sprinter lunge (left)', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/explosive-sprinter-lunge-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/explosive-sprinter-lunge-left.jpg', NULL, '["Assure-toi que ton genou avant ne dépasse pas tes orteils pour protéger l''articulation du genou", "Engage ton core tout au long du mouvement pour maintenir ton équilibre et ta stabilité", "Concentre-toi sur l''élévation explosive tout en contrôlant ton retour", "Assure-toi que le fléchisseur de ta jambe arrière bénéficie d''un bon étirement durant la phase d''extension", "Atterris doucement en revenant à la position de départ pour minimiser l''impact sur les articulations"]', '["Mauvaise alignement du genou avec la cheville", "Ne pas engager le core suffisamment pour maintenir l''équilibre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "explosive sprinter lunge (left)"]', true, '2026-04-03 12:24:56.694318+00', '2026-04-03 12:24:56.694318+00', 'Position de départ : commence dans une fente basse avec le pied gauche devant, le genou droit au sol, et les mains posées au sol pour le soutien. Exécution : propulse-toi de manière explosive avec ta jambe gauche tout en levant ton bras droit vers le haut et vers l''arrière, créant ainsi un mouvement dynamique d''étirement au niveau des fléchisseurs de la hanche et engageant ton corps.', '["Mauvaise alignement du genou avec la cheville", "Ne pas engager le core suffisamment pour maintenir l''équilibre"]', true, '["Start in a low lunge with left foot forward, right knee on the ground, and both hands placed on the mat for stability", "Keep your left knee aligned over your ankle and maintain a straight back throughout the movement", "Explosively drive up through your left leg while simultaneously reaching your right arm up and back", "Feel the stretch through your right hip flexor as you extend upward", "Control the movement back to the starting position", "Repeat for desired repetitions before switching sides"]', '["Commence en fente basse avec le pied gauche devant, le genou droit au sol, et les mains sur le tapis pour la stabilité", "Veille à ce que ton genou gauche soit aligné avec ta cheville et garde le dos droit durant l''exercice", "Propulse-toi explosivement avec ta jambe gauche tout en levant ton bras droit vers le haut et l''arrière", "Sens l''étirement au niveau de ton fléchisseur de la hanche droit en t''élevant", "Contrôle le mouvement pour revenir à la position de départ", "Répète pour le nombre de répétitions souhaité avant de changer de côté"]', '["Assure-toi que ton genou avant ne dépasse pas tes orteils pour protéger l''articulation du genou", "Engage ton core tout au long du mouvement pour maintenir ton équilibre et ta stabilité", "Concentre-toi sur l''élévation explosive tout en contrôlant ton retour", "Assure-toi que le fléchisseur de ta jambe arrière bénéficie d''un bon étirement durant la phase d''extension", "Atterris doucement en revenant à la position de départ pour minimiser l''impact sur les articulations"]', '["Keep your front knee tracking over your toes to protect the knee joint", "Engage your core throughout the movement to maintain balance and stability", "Focus on the explosive upward drive while maintaining control on the return", "Ensure your back leg''s hip flexor gets a good stretch during the extension phase", "Land softly when returning to the starting position to minimize impact on the joints"]', '022ea5f2-88f3-4d42-b99d-c1026d6bc343', 'explosive-sprinter-lunge-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('7e362f22-c646-4392-bcc5-db69166bcc08', 'Écarté un bras avec haltère', NULL, NULL, 'One arm dumbbell fly', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/one-arm-dumbbell-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/one-arm-dumbbell-fly.jpg', NULL, '["Maintiens le même angle de coude durant tout le mouvement pour ne pas transformer cela en un mouvement de poussée.", "Choisis un poids que tu peux contrôler ; cette position met l’épaule dans une situation délicate.", "Concentre-toi sur l''étirement et la contraction de ta poitrine, pas seulement sur le déplacement du poids.", "Engage ton tronc et garde le contact entre ton dos et le banc tout au long de l''exercice.", "Ne baisse jamais le poids en dessous du niveau de ton torse afin d''éviter de solliciter excessivement l’épaule."]', '["Ne pas contrôler la descente de l''haltère, ce qui peut augmenter le risque de blessure.", "Abaisser l’haltère trop bas, ce qui met une pression inutile sur l’épaule."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "one arm dumbbell fly"]', true, '2026-04-03 12:24:58.171005+00', '2026-04-03 12:24:58.171005+00', 'Allonge-toi sur un banc plat, un haltère dans une main, bras tendu au-dessus de ta poitrine, paume vers l''intérieur. Utilise l''autre main pour te stabiliser sur le banc. Dans cet exercice, tu vas faire un arc large avec l''haltère pour étirer ta poitrine, puis le ramener à la position de départ.', '["Ne pas contrôler la descente de l''haltère, ce qui peut augmenter le risque de blessure.", "Abaisser l’haltère trop bas, ce qui met une pression inutile sur l’épaule."]', true, '["Lie flat on a bench with feet planted firmly on the floor for stability", "Hold one dumbbell with a neutral grip, arm extended directly above your chest", "Keep a slight bend in your elbow throughout the entire movement to protect the joint", "Lower the weight slowly in a wide arc until you feel a deep stretch in your chest muscle", "Squeeze your chest muscle as you bring the dumbbell back up along the same curved path", "Complete all repetitions on one side before switching to the other arm"]', '["Allonge-toi sur le banc en gardant les pieds bien ancrés au sol pour plus de stabilité.", "Prends un haltère en main avec une prise neutre, bras tendu directement au-dessus de ta poitrine.", "Garde une légère flexion au niveau du coude tout au long du mouvement pour protéger l’articulation.", "Descends lentement l''haltère en effectuant un arc large jusqu''à ressentir un étirement profond dans ta poitrine.", "Contracte bien tes pectoraux en ramenant l''haltère le long du même chemin arc-en-ciel.", "Fais toutes les répétitions d''un côté avant de changer de bras."]', '["Maintiens le même angle de coude durant tout le mouvement pour ne pas transformer cela en un mouvement de poussée.", "Choisis un poids que tu peux contrôler ; cette position met l’épaule dans une situation délicate.", "Concentre-toi sur l''étirement et la contraction de ta poitrine, pas seulement sur le déplacement du poids.", "Engage ton tronc et garde le contact entre ton dos et le banc tout au long de l''exercice.", "Ne baisse jamais le poids en dessous du niveau de ton torse afin d''éviter de solliciter excessivement l’épaule."]', '["Maintain the same elbow angle throughout the movement to avoid turning this into a pressing motion", "Use a weight that allows you to control the movement completely, as this exercise puts the shoulder in a vulnerable position", "Focus on feeling the stretch and contraction in your chest rather than simply moving the weight from point A to point B", "Keep your core engaged and maintain contact between your back and the bench throughout the exercise", "Never lower the weight below the level of your torso to prevent excessive shoulder strain"]', 'd30b1013-b7ae-47da-847e-e58e9ea770cc', 'one-arm-dumbbell-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('33e78f06-6248-4022-aad1-cf47508ab753', 'Squat bulgare avec haltères', NULL, NULL, 'Bulgarian split squat with Dumbbell', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 2, '/videos/quadriceps/bulgarian-split-squat-with-dumbbell.mp4', NULL, NULL, NULL, '/videos/thumbnails/bulgarian-split-squat-with-dumbbell.jpg', NULL, '["Concentre le poids sur la jambe avant", "Garde le torse droit", "Assure-toi que ton genou avant suit la direction de tes orteils", "Descends profondément pour activer les fessiers", "L''équilibre peut être difficile au début"]', '["Ne pas descendre assez bas", "Incliner le torse en avant", "Lâcher la tension dans le pied avant"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "bulgarian split squat with dumbbell"]', true, '2026-04-03 12:24:55.824708+00', '2026-04-03 12:24:55.824708+00', 'Position de départ : Place-toi à 60-90 cm d''une banc, un haltère dans chaque main, en gardant ton pied arrière sur le banc derrière toi. Exécution : Descends en fléchissant ton genou avant jusqu''à ce que ta cuisse soit parallèle au sol, puis pousse avec ton talon avant pour revenir à la position de départ.', '["Ne pas descendre assez bas", "Incliner le torse en avant", "Lâcher la tension dans le pied avant"]', true, '["Rear foot on bench behind you", "Front foot forward, dumbbells at sides", "Lower until front thigh parallel", "Drive up through front heel", "Complete reps, switch legs"]', '["Pied arrière sur le banc derrière toi", "Pied avant en avant, haltères à tes côtés", "Descends jusqu''à ce que ta cuisse avant soit parallèle", "Pousse avec le talon avant pour remonter", "Fais un nombre de répétitions puis change de jambe"]', '["Concentre le poids sur la jambe avant", "Garde le torse droit", "Assure-toi que ton genou avant suit la direction de tes orteils", "Descends profondément pour activer les fessiers", "L''équilibre peut être difficile au début"]', '["Most weight on front leg", "Torso stays upright", "Front knee tracks over toes", "Go deep for glute activation", "Balance is challenging at first"]', 'd81d953b-b29d-438a-aeee-610523bca09d', 'bulgarian-split-squat-with-dumbbell', NULL, NULL);
INSERT INTO public.exercises VALUES ('8645165b-ac24-4e20-bb81-76e90d1699d4', 'Kettlebell Snatch à Un Bras depuis le Sol', NULL, 'الرفعة من الأرض بكيتلبل في يد وحدة', 'One-Arm Kettlebell Snatch from ground', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 128, '/videos/bodyweight/one-arm-kettlebell-snatch-from-ground-4fcd55ed.mp4', NULL, NULL, NULL, '/videos/thumbnails/one-arm-kettlebell-snatch-from-ground-4fcd55ed.jpg', NULL, '["Mouvement avancé - apprenez d''abord le swing et le clean", "Ne retournez pas le kettlebell sur votre poignet", "Réalisez un mouvement fluide du sol à au-dessus de la tête", "Verrouillez vos bras complètement en haut", "Contrôlez la descente"]', '["Ne pas réaliser la montée en une seule exécution", "Oublier de verrouiller les bras en haut"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "kettlebell", "one-arm kettlebell snatch from ground"]', true, '2026-04-03 12:24:58.197667+00', '2026-04-03 12:24:58.197667+00', 'Un exercice explosif pour tout le corps qui développe puissance et coordination.', '["Ne pas réaliser la montée en une seule exécution", "Oublier de verrouiller les bras en haut"]', true, '["Kettlebell between feet", "Hinge, grip with one hand", "Swing back, then explosively drive hips", "Pull kettlebell overhead in one motion", "Punch through at top, catch overhead"]', '["Placez le kettlebell entre vos pieds", "Penchez-vous, saisissez avec une main", "Balancez le kettlebell en arrière, puis poussez les hanches vers l''avant avec explosivité", "Tirez le kettlebell au-dessus de votre tête en un seul mouvement", "Pointez vers le haut au sommet, attrapez-le à l''horizontale"]', '["Mouvement avancé - apprenez d''abord le swing et le clean", "Ne retournez pas le kettlebell sur votre poignet", "Réalisez un mouvement fluide du sol à au-dessus de la tête", "Verrouillez vos bras complètement en haut", "Contrôlez la descente"]', '["Advanced movement - learn swing and clean first", "Don''t flip kettlebell onto wrist", "One smooth motion from floor to overhead", "Lock out completely at top", "Control the descent"]', '4fcd55ed-a563-4f9f-b43c-4b4ea35e5cc4', 'one-arm-kettlebell-snatch-from-ground-4fcd55ed', NULL, NULL);
INSERT INTO public.exercises VALUES ('0e2dc839-2b72-44b1-9e77-ae445bd008e7', 'Press de jambes en position médiane', NULL, 'ضغط الساقين بصفة متوسطة', 'Leg Press Medium Stance', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/leg-press-medium-stance.mp4', NULL, NULL, NULL, '/videos/thumbnails/leg-press-medium-stance.jpg', NULL, '["Veillez à ce que vos genoux soient alignés avec vos orteils pour éviter tout effondrement vers l''intérieur", "Évitez de poser les mains sur les genoux, cela peut causer des blessures si le poids se déplace de manière imprévue", "Contrôlez la descente lentement au lieu de laisser le poids tomber rapidement", "Arrêtez-vous à un angle de 90 degrés pour protéger votre bas du dos d''une flexion excessive", "Inspirez pendant la phase de descente et expirez en poussant le poids vers le haut"]', '["Ne pas ajuster correctement le siège", "Oublier de maintenir le dos contre le dossier"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "leg press medium stance"]', true, '2026-04-03 12:24:57.56817+00', '2026-04-03 12:24:57.56817+00', 'Position de départ : Asseyez-vous sur la presse à jambes horizontale avec les pieds en position médiane, écartés à la largeur des épaules et les genoux fléchis. Exécution : Poussez la plateforme en avant en étendant complètement vos jambes, puis abaissez lentement jusqu''à la position de départ.', '["Ne pas ajuster correctement le siège", "Oublier de maintenir le dos contre le dossier"]', true, '["Adjust the seat and back pad so your knees align with your chest when lowered", "Place feet shoulder-width apart on the footplate with toes pointing slightly outward", "Release the safety handles and slowly lower the weight until your knees reach 90 degrees", "Press through your heels to return to starting position without locking knees completely", "Keep your core engaged and back pressed firmly against the pad throughout the movement", "Re-engage safety handles when completing your set"]', '["Ajustez le siège et le dossier pour que vos genoux soient alignés avec votre poitrine lorsque vous êtes abaissé", "Positionnez vos pieds à la largeur des épaules sur la plateforme, orteils légèrement tournés vers l''extérieur", "Libérez les poignées de sécurité et abaissez lentement le poids jusqu''à ce que vos genoux atteignent 90 degrés", "Poussez avec vos talons pour revenir à la position de départ sans bloquer complètement les genoux", "Gardez votre sangle abdominale engagée et votre dos bien appuyé contre le dossier pendant tout le mouvement", "Réengagez les poignées de sécurité une fois votre série terminée"]', '["Veillez à ce que vos genoux soient alignés avec vos orteils pour éviter tout effondrement vers l''intérieur", "Évitez de poser les mains sur les genoux, cela peut causer des blessures si le poids se déplace de manière imprévue", "Contrôlez la descente lentement au lieu de laisser le poids tomber rapidement", "Arrêtez-vous à un angle de 90 degrés pour protéger votre bas du dos d''une flexion excessive", "Inspirez pendant la phase de descente et expirez en poussant le poids vers le haut"]', '["Keep your knees aligned with your toes to prevent inward collapse", "Avoid placing hands on knees as this can cause injury if the weight shifts unexpectedly", "Control the descent slowly rather than letting the weight drop quickly", "Stop at 90 degrees knee bend to protect your lower back from excessive flexion", "Breathe in during the lowering phase and exhale while pressing the weight up"]', '639e71b2-5c79-4125-ad31-1c073b8b073f', 'leg-press-medium-stance', NULL, NULL);
INSERT INTO public.exercises VALUES ('1a6348a1-dbb6-4d80-a7f2-09407b27abb4', 'Développé Militaire Kettlebell à Un Bras', NULL, NULL, 'One-Arm Kettlebell Military Press', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 128, '/videos/shoulders/one-arm-kettlebell-military-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/one-arm-kettlebell-military-press.jpg', NULL, '["Garde ton bras non actif détendu le long de ton corps ou place-le derrière ton dos pour une meilleure stabilité et engagement du core", "Évite de te pencher du côté de travail - maintiens le torse droit tout au long du mouvement", "Concentre-toi sur un chemin de pressage fluide qui va légèrement vers l''arrière au-dessus de ta tête plutôt que tout droit pour maintenir une bonne mécanique d''épaule", "Expire vigoureusement durant la phase de poussée et inspire durant la phase de descente", "Commence avec un poids léger pour maîtriser le mouvement avant de passer à des kettlebells plus lourds"]', '["Pencher le torse vers l''avant", "Ne pas garder le poignet droit et stable"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "kettlebell", "one-arm kettlebell military press"]', true, '2026-04-03 12:24:58.18278+00', '2026-04-03 12:24:58.18278+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des épaules, avec un kettlebell à hauteur d''épaule dans une main, le poids reposant sur l''arrière de ton poignet et ton avant-bras. Exécution : Pousse le kettlebell directement au-dessus de ta tête dans un mouvement contrôlé jusqu''à ce que ton bras soit entièrement tendu, puis redescends-le lentement à la position de départ.', '["Pencher le torse vers l''avant", "Ne pas garder le poignet droit et stable"]', true, '["Clean the kettlebell to shoulder height with the bell resting on the back of your wrist and your elbow tucked close to your ribs", "Engage your core and maintain a neutral spine with feet planted firmly shoulder-width apart", "Press the kettlebell straight up overhead following a slight arc path, keeping your wrist straight and strong", "Fully extend your arm at the top while keeping your shoulder packed down and back", "Lower the kettlebell with control back to the starting position at shoulder height", "Complete all repetitions on one side before switching to the other arm"]', '["Amène le kettlebell à hauteur d''épaule, le poids reposant sur l''arrière de ton poignet et ton coude près de tes côtes", "Engage ton core et garde le dos droit, les pieds bien ancrés à la largeur des épaules", "Pousse le kettlebell directement vers le haut en suivant un léger arc, avec un poignet droit et solide", "Étends complètement ton bras en haut tout en gardant ton épaule abaissée et en arrière", "Redescends le kettlebell avec contrôle à hauteur d''épaule", "Fais toutes les répétitions d''un côté avant de changer de bras"]', '["Garde ton bras non actif détendu le long de ton corps ou place-le derrière ton dos pour une meilleure stabilité et engagement du core", "Évite de te pencher du côté de travail - maintiens le torse droit tout au long du mouvement", "Concentre-toi sur un chemin de pressage fluide qui va légèrement vers l''arrière au-dessus de ta tête plutôt que tout droit pour maintenir une bonne mécanique d''épaule", "Expire vigoureusement durant la phase de poussée et inspire durant la phase de descente", "Commence avec un poids léger pour maîtriser le mouvement avant de passer à des kettlebells plus lourds"]', '["Keep the non-working arm relaxed at your side or place it behind your back for better stability and core engagement", "Avoid leaning away from the working side - maintain an upright torso throughout the entire movement", "Focus on a smooth pressing path that moves slightly back over your head rather than straight up to maintain proper shoulder mechanics", "Breathe out forcefully during the pressing phase and inhale during the lowering phase", "Start with lighter weight to master the movement pattern before progressing to heavier kettlebells"]', 'eff7ae70-1117-4d71-a35f-15db81a16242', 'one-arm-kettlebell-military-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('f01283bb-5283-4df4-88b3-3549afc8e499', 'Extension des triceps à la corde haute', NULL, 'تمديد ثلاثي الرؤوس بالحبل العالي', 'Overhead Cable Rope Extension', 'Triceps', '[]', 'Triceps', 'Intermediate', 4, '/videos/triceps/overhead-cable-rope-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/overhead-cable-rope-extension.jpg', NULL, '["Gardez vos bras supérieurs complètement immobiles pendant tout le mouvement pour cibler les triceps", "Maintenez une légère inclinaison en avant et engagez votre sangle abdominale pour éviter une cambrure excessive du dos", "Contrôlez le poids à la fois pendant l''extension et le retour pour maximiser l''engagement musculaire", "Évitez d''utiliser l''élan ou de balancer le poids pour prévenir les blessures et garantir une activation musculaire correcte", "Gardez vos poignets droits et maintenez une bonne prise sur la corde tout au long de l''exercice"]', '["Baissez les coudes pendant l''exécution", "Utiliser trop de poids sans contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "cable", "overhead cable rope extension"]', true, '2026-04-03 12:24:58.233699+00', '2026-04-03 12:24:58.233699+00', 'Position de départ : Tenez-vous dos à une machine à câbles avec un accessoire en corde, les coudes pliés au-dessus de la tête. Exécution : Tendez vos coudes pour faire avancer la corde, en gardant vos coudes fixes.', '["Baissez les coudes pendant l''exécution", "Utiliser trop de poids sans contrôle"]', true, '["Set the cable machine to the highest pulley position and attach a rope handle", "Stand facing away from the machine with feet shoulder-width apart for stability", "Grasp the rope with both hands using a neutral grip, positioning your hands at the end knots", "Lean slightly forward at the hips and position your upper arms parallel to the floor", "Extend your forearms forward and down in a controlled arc until your arms are fully straight", "Slowly return to the starting position by allowing your forearms to bend back overhead"]', '["Réglez la machine à câble sur la position de poulie la plus haute et attachez une poignée en corde", "Positionnez-vous face à l''arrière de la machine, les pieds écartés à la largeur des épaules pour une bonne stabilité", "Saisissez la corde avec les deux mains en utilisant une prise neutre, plaçant vos mains aux nœuds aux extrémités", "Inclinez-vous légèrement vers l''avant au niveau des hanches, en maintenant vos bras supérieurs parallèles au sol", "Étendez vos avant-bras vers l''avant et vers le bas dans un mouvement contrôlé jusqu''à ce que vos bras soient complètement droits", "Retournez lentement à la position de départ en permettant à vos avant-bras de revenir au-dessus de la tête"]', '["Gardez vos bras supérieurs complètement immobiles pendant tout le mouvement pour cibler les triceps", "Maintenez une légère inclinaison en avant et engagez votre sangle abdominale pour éviter une cambrure excessive du dos", "Contrôlez le poids à la fois pendant l''extension et le retour pour maximiser l''engagement musculaire", "Évitez d''utiliser l''élan ou de balancer le poids pour prévenir les blessures et garantir une activation musculaire correcte", "Gardez vos poignets droits et maintenez une bonne prise sur la corde tout au long de l''exercice"]', '["Keep your upper arms completely stationary throughout the movement to isolate the triceps", "Maintain a slight forward lean and engage your core to prevent excessive back arching", "Control the weight on both the extending and returning phases to maximize muscle engagement", "Avoid using momentum or swinging the weight to prevent injury and ensure proper muscle activation", "Keep your wrists straight and maintain a firm grip on the rope throughout the entire exercise"]', '26098d10-600c-4876-ac19-e9fcac2ef835', 'overhead-cable-rope-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('8ad35de3-15e5-4815-a536-ee2e88ec9317', 'Développe tes épaules avec la Machine Shoulder Press', NULL, NULL, 'Machine Shoulder Press Neutral Grip', 'Shoulders', '[]', 'Shoulders', 'Beginner', 8, '/videos/shoulders/machine-shoulder-press-neutral-grip.mp4', NULL, NULL, NULL, '/videos/thumbnails/machine-shoulder-press-neutral-grip.jpg', NULL, '["Évitez de pousser le poids derrière la tête pour ne pas solliciter l''articulation de l''épaule.", "Maintenez vos abdominaux engagés pour garder une bonne posture de la colonne vertébrale.", "Utilisez un mouvement complet, mais arrêtez-vous au niveau des épaules lors de la descente pour éviter un étirement excessif.", "Expirez pendant la phase de poussée et inhalez lors de la descente.", "Commencez avec un poids léger pour maîtriser la technique avant de passer à des charges plus lourdes."]', '["Ne pas ajuster correctement la hauteur du siège.", "Oublier de garder le dos bien plaqué contre le dossier pendant l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "machine shoulder press neutral grip"]', true, '2026-04-03 12:24:57.789803+00', '2026-04-03 12:24:57.789803+00', 'Position de départ : Asseyez-vous sur la machine Shoulder Press avec une prise neutre (paumes face à face). Ajustez la hauteur du siège pour que les poignées soient au niveau des épaules.', '["Ne pas ajuster correctement la hauteur du siège.", "Oublier de garder le dos bien plaqué contre le dossier pendant l''exercice."]', true, '["Adjust the seat height so the handles align with your shoulders when seated", "Position your back flat against the backrest and engage your core muscles", "Grasp the handles with a neutral grip, keeping your wrists straight and aligned", "Press the weight up in a smooth, controlled motion without locking out your elbows completely", "Lower the weight slowly back to shoulder level, maintaining control throughout the descent", "Keep your feet firmly planted on the ground throughout the entire movement"]', '["Ajustez la hauteur du siège pour que les poignées soient alignées avec vos épaules en position assise.", "Maintenez le dos plaqué contre le dossier et activez vos muscles abdominaux.", "Saisissez les poignées avec une prise neutre, les poignets droits et alignés.", "Poussez les poignées vers le haut en un mouvement fluide et contrôlé sans verrouiller complètement vos coudes.", "Redescendez le poids lentement jusqu''au niveau des épaules, en gardant le contrôle tout au long de la descente.", "Gardez vos pieds fermement ancrés au sol pendant tout l''exercice."]', '["Évitez de pousser le poids derrière la tête pour ne pas solliciter l''articulation de l''épaule.", "Maintenez vos abdominaux engagés pour garder une bonne posture de la colonne vertébrale.", "Utilisez un mouvement complet, mais arrêtez-vous au niveau des épaules lors de la descente pour éviter un étirement excessif.", "Expirez pendant la phase de poussée et inhalez lors de la descente.", "Commencez avec un poids léger pour maîtriser la technique avant de passer à des charges plus lourdes."]', '["Avoid pressing the weight behind your head as this can strain the shoulder joint", "Keep your core engaged throughout the movement to maintain proper spinal alignment", "Use a full range of motion but stop at shoulder level on the descent to prevent overstretching", "Breathe out during the pressing phase and breathe in during the lowering phase", "Start with lighter weight to master the form before progressing to heavier loads"]', '6f402009-67c2-484f-bc92-6090cc9a7ed4', 'machine-shoulder-press-neutral-grip', NULL, NULL);
INSERT INTO public.exercises VALUES ('9033d533-49fe-450e-9be7-d1dc645213a8', 'Développé militaire', NULL, NULL, 'Shoulder press - Overhead press - Military press', 'Shoulders', '[]', 'Shoulders', 'Beginner', 8, '/videos/shoulders/shoulder-press-overhead-press-military-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/shoulder-press-overhead-press-military-press.jpg', NULL, '["Garde ton tronc bien contracté pendant toute la durée de l''exercice pour protéger ta lombaire", "Maintiens tes poignets droits et agrippe fermement la barre pour éviter qu''elle ne roule", "Pousse la barre en ligne droite, sans l''incliner vers l''avant ou l''arrière", "Évite de bloquer tes coudes trop brutalement au sommet du mouvement", "Contrôle la descente, ne laisse pas le poids tomber rapidement sur tes épaules"]', '["Ne pas engager le tronc, ce qui peut mettre en danger le bas du dos", "Pencher le torse en arrière, ce qui crée une pression excessive sur la colonne vertébrale"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "shoulder press - overhead press - military press"]', true, '2026-04-03 12:24:58.960413+00', '2026-04-03 12:24:58.960413+00', 'Position de départ : Mets-toi debout, les pieds écartés à la largeur des épaules, une barre au niveau des épaules, les mains en prise pronation. Exécution : Pousse la barre droit au-dessus de ta tête jusqu''à ce que tes bras soient complètement étendus, puis redescends lentement à la hauteur des épaules.', '["Ne pas engager le tronc, ce qui peut mettre en danger le bas du dos", "Pencher le torse en arrière, ce qui crée une pression excessive sur la colonne vertébrale"]', true, '["Stand with feet shoulder-width apart for a stable base, holding the barbell with hands slightly wider than shoulder-width", "Position the barbell at shoulder level with elbows directly under the bar", "Engage your core and maintain a neutral spine throughout the movement", "Press the barbell straight up overhead in a controlled motion until arms are fully extended", "Slowly lower the barbell back to shoulder level, maintaining control throughout the descent", "Keep the barbell path vertical and avoid arching your back excessively"]', '["Tiens-toi debout avec les pieds écartés à la largeur des épaules pour une base stable, la barre en prise un peu plus large que les épaules", "Positionne la barre au niveau des épaules avec les coudes directement sous la barre", "Engage ton tronc et garde une colonne vertébrale neutre tout au long du mouvement", "Pousse la barre droit au-dessus de ta tête de manière contrôlée jusqu''à ce que tes bras soient tendus", "Redescends lentement la barre à la hauteur des épaules en gardant le contrôle pendant la descente", "Assure-toi que la trajectoire de la barre soit verticale et évite d''exagérer la cambrure de ton dos"]', '["Garde ton tronc bien contracté pendant toute la durée de l''exercice pour protéger ta lombaire", "Maintiens tes poignets droits et agrippe fermement la barre pour éviter qu''elle ne roule", "Pousse la barre en ligne droite, sans l''incliner vers l''avant ou l''arrière", "Évite de bloquer tes coudes trop brutalement au sommet du mouvement", "Contrôle la descente, ne laisse pas le poids tomber rapidement sur tes épaules"]', '["Maintain a tight core throughout the entire movement to protect your lower back", "Keep your wrists straight and grip the bar firmly to prevent it from rolling", "Press the bar in a straight vertical line rather than forward or backward", "Avoid locking out your elbows too aggressively at the top of the movement", "Control the descent - don''t let the weight drop quickly to your shoulders"]', 'a9db8a1f-87ac-45a6-876f-7c76bc4d5d8f', 'shoulder-press-overhead-press-military-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('9ada4b46-3815-452a-a237-772a52f51b67', 'Scaption avec haltères', NULL, '', 'Dumbbell Scaption', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/dumbbell-scaption.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-scaption.jpg', NULL, '["Garde toujours tes pouces pointés vers le haut pour cibler correctement le muscle supraspinatus", "Utilise des poids plus légers que pour des exercices d''épaules classiques, car cela sollicite des muscles stabilisateurs plus petits", "Maintiens une légère flexion au niveau des coudes et évite de bloquer complètement tes bras", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''activation musculaire et éviter les blessures", "Arrête immédiatement si tu ressens une douleur ou un pincement au niveau de l''épaule"]', '["Utiliser des poids trop lourds, ce qui peut nuire à la technique et augmenter le risque de blessure", "Ne pas garder les pouces vers le haut, ce qui empêche un bon ciblage des muscles stabilisateurs"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "dumbbell scaption"]', true, '2026-04-03 12:24:56.552076+00', '2026-04-03 12:24:56.552076+00', 'Position de départ : Tiens-toi debout, les pieds à la largeur des hanches, un haltère dans chaque main le long du corps, bras tendus et paumes face à toi. Exécution : Lève simultanément les deux bras en formant un Y (environ 30-45 degrés devant toi) jusqu''à la hauteur des épaules, puis redescends lentement à la position de départ.', '["Utiliser des poids trop lourds, ce qui peut nuire à la technique et augmenter le risque de blessure", "Ne pas garder les pouces vers le haut, ce qui empêche un bon ciblage des muscles stabilisateurs"]', true, '["Stand with feet hip-width apart and core engaged, holding dumbbells with arms at your sides", "Position your thumbs pointing upward and arms slightly forward from your body at about a 30-45 degree angle", "Raise both arms simultaneously in a smooth Y-pattern until dumbbells reach shoulder height", "Pause briefly at the top while maintaining control of the weights", "Slowly lower the dumbbells back to starting position with the same controlled motion", "Keep your torso upright and avoid using momentum throughout the movement"]', '["Tiens-toi debout, les pieds à la largeur des hanches, engage le ventre et prends les haltères en tenant les bras le long du corps", "Positionne tes pouces vers le haut et les bras légèrement en avant du corps, à un angle d''environ 30-45 degrés", "Lève les deux bras en même temps en formant un Y jusqu''à ce que les haltères atteignent la hauteur des épaules", "Reste en haut un instant tout en gardant le contrôle des poids", "Redescends lentement les haltères à la position de départ avec le même mouvement contrôlé", "Garde le torse bien droit et évite de te servir d''élan durant l''exercice"]', '["Garde toujours tes pouces pointés vers le haut pour cibler correctement le muscle supraspinatus", "Utilise des poids plus légers que pour des exercices d''épaules classiques, car cela sollicite des muscles stabilisateurs plus petits", "Maintiens une légère flexion au niveau des coudes et évite de bloquer complètement tes bras", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''activation musculaire et éviter les blessures", "Arrête immédiatement si tu ressens une douleur ou un pincement au niveau de l''épaule"]', '["Keep your thumbs pointing up throughout the movement to properly target the supraspinatus muscle", "Use lighter weights than typical shoulder exercises as this targets smaller stabilizing muscles", "Maintain a slight bend in your elbows and avoid locking out your arms completely", "Focus on controlled movement rather than speed to maximize muscle activation and prevent injury", "Stop immediately if you feel any pinching or pain in the shoulder joint"]', 'd4210b5a-f583-4039-8566-ed5a20e46eab', 'dumbbell-scaption', NULL, NULL);
INSERT INTO public.exercises VALUES ('358b5e1f-cd7d-4a0f-b246-74754ef84ff5', 'Planches avec tirage des genoux', NULL, NULL, 'Plank in and outs', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-in-and-outs.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-in-and-outs.jpg', NULL, '["Appuie fermement tes mains et évite de déplacer ton poids pendant le tirage des genoux", "Garde la colonne vertébrale neutre, sans relever ni abaisser les hanches", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement du core", "Stabilise bien tes épaules, elles doivent rester au-dessus des poignets durant l''exercice", "Respire normalement, n''oublie pas d''expirer pendant le mouvement"]', '["Ne pas maintenir la position du corps bien droite", "Tirer les genoux sans contrôler la posture du haut du corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank in and outs"]', true, '2026-04-03 12:24:58.284529+00', '2026-04-03 12:24:58.284529+00', 'Position de départ : place-toi en position de planche, les mains bien ancrées au sol, le corps aligné de la tête aux talons. Exécution : tire simultanément les deux genoux vers ta poitrine, puis étends-les pour revenir à la position de planche de départ.', '["Ne pas maintenir la position du corps bien droite", "Tirer les genoux sans contrôler la posture du haut du corps"]', true, '["Start in a high plank position with hands directly under shoulders and body forming a straight line", "Engage your core and keep your back flat throughout the movement", "Pull both knees toward your chest simultaneously while maintaining upper body stability", "Pause briefly when knees are pulled in toward your torso", "Extend both legs back out to return to the starting plank position", "Maintain control throughout the entire range of motion"]', '["Adopte une position de planche haute, les mains sous les épaules et le corps en ligne droite", "Contracte ton ventre et garde le dos bien plat durant tout le mouvement", "Tire les deux genoux vers ta poitrine tout en stabilisant le haut du corps", "Fais une courte pause lorsque les genoux sont tirés vers ton torse", "Étends les jambes à l''arrière pour revenir à la position initiale de planche", "Garde le contrôle durant toute l''amplitude du mouvement"]', '["Appuie fermement tes mains et évite de déplacer ton poids pendant le tirage des genoux", "Garde la colonne vertébrale neutre, sans relever ni abaisser les hanches", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement du core", "Stabilise bien tes épaules, elles doivent rester au-dessus des poignets durant l''exercice", "Respire normalement, n''oublie pas d''expirer pendant le mouvement"]', '["Keep your hands firmly planted and avoid shifting weight during the knee pull", "Maintain a neutral spine and avoid letting your hips pike up or sag down", "Focus on controlled movement rather than speed to maximize core engagement", "Keep your shoulders stable and directly over your wrists throughout the exercise", "Breathe steadily and avoid holding your breath during the movement"]', '364dc379-ca4e-4fe2-9d95-684619a8b693', 'plank-in-and-outs', NULL, NULL);
INSERT INTO public.exercises VALUES ('b706400c-d4b4-4421-ada3-215cf5c7a5c9', 'Développé Arnold à la Smith', NULL, NULL, 'Smith Machine Behind the Neck Press', 'Shoulders', '[]', 'Shoulders', 'Advanced', 8, '/videos/shoulders/smith-machine-behind-the-neck-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-behind-the-neck-press.jpg', NULL, '["N''effectue cet exercice que si tu as une excellente flexibilité d''épaules et pas d''antécédents de blessures aux épaules ou au cou.", "Garde le centre du corps engagé et conserve la courbure naturelle de ton bas du dos pendant le mouvement.", "Utilise un poids beaucoup plus léger que pour des développés classiques à cause de la position d''épaule compromise.", "Stoppe immédiatement si tu ressens une douleur ou une gêne dans les épaules ou le cou.", "Considère le développé militaire frontal comme une alternative plus sûre qui cible les mêmes groupes musculaires."]', '["Ne pas verrouiller le dos contre le banc, ce qui peut entraîner des tensions.", "Utiliser un poids trop lourd, ce qui accroît le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "smith machine behind the neck press"]', true, '2026-04-03 12:24:59.260717+00', '2026-04-03 12:24:59.260717+00', 'Commence avec la barre positionnée derrière ton cou, les pieds bien ancrés au sol. Pousse la barre vers le haut jusqu''à avoir les bras complètement tendus, puis redescends-la doucement à la position de départ.', '["Ne pas verrouiller le dos contre le banc, ce qui peut entraîner des tensions.", "Utiliser un poids trop lourd, ce qui accroît le risque de blessure."]', true, '["Set the Smith machine bar at shoulder height and position a bench with back support directly underneath", "Sit with your back firmly against the pad and grip the bar with palms facing forward, hands wider than shoulder-width", "Position the bar at the base of your neck, ensuring your head is in a neutral position looking straight ahead", "Unlock the bar and press it straight up by extending your arms fully overhead", "Slowly lower the bar back to the starting position behind your neck with control", "Re-rack the bar safely when completing your set"]', '["Ajuste la barre de la Smith machine à la hauteur des épaules puis installe un banc avec dossier directement en dessous.", "Assieds-toi avec le dos bien plaqué contre le dossier et saisis la barre avec les paumes vers l''avant, les mains un peu plus larges que les épaules.", "Place la barre à la base de ton cou, en gardant la tête droite et regardant devant toi.", "Déverrouille la barre et pousse-la directement vers le haut en étendant complètement tes bras au-dessus de ta tête.", "Redescends lentement la barre en contrôlant le mouvement jusqu''à la position de départ derrière ton cou.", "Ranger la barre en toute sécurité à la fin de ta série."]', '["N''effectue cet exercice que si tu as une excellente flexibilité d''épaules et pas d''antécédents de blessures aux épaules ou au cou.", "Garde le centre du corps engagé et conserve la courbure naturelle de ton bas du dos pendant le mouvement.", "Utilise un poids beaucoup plus léger que pour des développés classiques à cause de la position d''épaule compromise.", "Stoppe immédiatement si tu ressens une douleur ou une gêne dans les épaules ou le cou.", "Considère le développé militaire frontal comme une alternative plus sûre qui cible les mêmes groupes musculaires."]', '["Only perform this exercise if you have excellent shoulder flexibility and no history of shoulder or neck injuries", "Keep your core engaged and maintain the natural arch in your lower back throughout the movement", "Use a much lighter weight than you would for standard overhead pressing movements due to the compromised shoulder position", "Stop immediately if you feel any pain or discomfort in your shoulders or neck", "Consider front military press as a safer alternative that targets the same muscle groups"]', 'd2122541-4c46-460f-be6a-7ea35e2d0624', 'smith-machine-behind-the-neck-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('8969ae62-ecc3-41d6-bbab-960fd17b6e6b', 'Planche sur les coudes', NULL, 'بلاك على الكوعين', 'Plank on elbows', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-on-elbows.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-on-elbows.jpg', NULL, '["Serrez les fessiers", "Gardez le cou dans une position neutre", "Respirez normalement", "Ne levez pas les hanches trop haut", "Augmentez progressivement la durée"]', '["Hanches qui s''affaissent", "Tête qui dépasse vers l''avant", "Respiration bloquée"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank on elbows"]', true, '2026-04-03 12:24:58.322923+00', '2026-04-03 12:24:58.322923+00', 'Un exercice essentiel pour renforcer votre sangle abdominale et améliorer votre stabilité.', '["Hanches qui s''affaissent", "Tête qui dépasse vers l''avant", "Respiration bloquée"]', true, '["Forearms on floor, elbows under shoulders", "Body straight from head to heels", "Hold position", "Keep core tight, don''t let hips sag"]', '["Placez vos avant-bras au sol, coudes alignés sous les épaules", "Gardez le corps droit des pieds à la tête", "Maintenez la position", "Contractez bien votre sangle abdominale, évitez que les hanches ne s''affaissent"]', '["Serrez les fessiers", "Gardez le cou dans une position neutre", "Respirez normalement", "Ne levez pas les hanches trop haut", "Augmentez progressivement la durée"]', '["Squeeze glutes", "Keep neck neutral", "Breathe normally", "Don''t raise hips too high", "Build time gradually"]', '49739b94-19b6-4ec3-aa93-53e7c4824918', 'plank-on-elbows', NULL, NULL);
INSERT INTO public.exercises VALUES ('3d8bb3b1-011f-404d-b769-9a71143221dd', 'Élévation Latérale Incliné avec Haltères', NULL, 'رفع جانبي مائل بالأثقال', 'Incline Dumbbell Lateral Raise', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/incline-dumbbell-lateral-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-dumbbell-lateral-raise.jpg', NULL, '["Garde toujours une légère flexion dans tes coudes pour protéger tes articulations", "Concentre-toi sur le soulèvement avec les épaules, évite de te balancer avec élan", "La position inclinée isole mieux les deltoïdes moyens et réduit la pression sur le bas du dos", "Commence avec des poids plus légers, cet exercice est plus exigeant que les élévations latérales standard en raison de l''inclinaison", "Ne soulève pas les haltères plus haut que le niveau des épaules pour éviter le pincement de l''épaule"]', '["Balancer les poids au lieu de soulever avec contrôle", "Lever les haltères au-dessus de la hauteur des épaules"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "incline dumbbell lateral raise"]', true, '2026-04-03 12:24:57.28236+00', '2026-04-03 12:24:57.28236+00', 'Position de départ : Allonge-toi sur le côté d''un banc incliné, un haltère dans la main du haut. Exécution : Soulève l''haltère sur le côté jusqu''à la hauteur des épaules, puis redescends lentement.', '["Balancer les poids au lieu de soulever avec contrôle", "Lever les haltères au-dessus de la hauteur des épaules"]', true, '["Set the incline bench to a 45-60 degree angle and sit with your back pressed firmly against the pad", "Hold a dumbbell in each hand with a neutral grip, arms hanging at your sides with a slight bend in your elbows", "Engage your core and maintain a straight spine throughout the movement", "Lift the dumbbells out to your sides in a controlled arc motion until your arms are parallel to the floor", "Pause briefly at the top position while squeezing your shoulder blades", "Slowly lower the weights back to the starting position with control"]', '["Régle le banc incliné à 45-60 degrés et allonge-toi avec le dos bien calé contre le dossier", "Prends un haltère dans chaque main en prise neutre, bras pendant sur les côtés avec une légère flexion des coudes", "Engage ton tronc et garde la colonne vertébrale droite durant tout le mouvement", "Lève les haltères sur les côtés en arc contrôlé jusqu''à ce que tes bras soient parallèles au sol", "Fais une pause en haut en serrant les omoplates", "Redescends lentement les poids à la position de départ avec contrôle"]', '["Garde toujours une légère flexion dans tes coudes pour protéger tes articulations", "Concentre-toi sur le soulèvement avec les épaules, évite de te balancer avec élan", "La position inclinée isole mieux les deltoïdes moyens et réduit la pression sur le bas du dos", "Commence avec des poids plus légers, cet exercice est plus exigeant que les élévations latérales standard en raison de l''inclinaison", "Ne soulève pas les haltères plus haut que le niveau des épaules pour éviter le pincement de l''épaule"]', '["Keep a slight bend in your elbows throughout the entire movement to protect your joints", "Focus on lifting with your shoulders rather than swinging the weights with momentum", "The incline position helps isolate the middle deltoids while reducing strain on the lower back", "Start with lighter weights as this exercise can be more challenging than standard lateral raises due to the inclined position", "Avoid raising the dumbbells higher than shoulder level to prevent shoulder impingement"]', 'a9ab8609-e40c-44e1-9e0f-a86c3794662c', 'incline-dumbbell-lateral-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('002ccafa-fd46-4a8a-869e-21c86f5892a8', 'Élévations de Jambes', NULL, 'رفعات الساقين', 'Leg raises', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/leg-raises.mp4', NULL, NULL, NULL, '/videos/thumbnails/leg-raises.jpg', NULL, '["Garde toujours le bas du dos à plat contre le sol pour éviter les tensions et maintenir un bon engagement du core", "Contrôle la descente, c''est cette phase qui met le plus au défi tes muscles abdominaux", "Si tu ressens une gêne dans le bas du dos, plie légèrement les genoux ou place tes mains sous ton bas du dos pour plus de soutien", "Concentre-toi sur l''utilisation de tes muscles abdominaux plutôt que sur l''élan pour lever et abaisser tes jambes", "Commence avec moins de répétitions et augmente progressivement à mesure que ta force de core s''améliore"]', '["Lever les jambes trop vite sans contrôle", "Ne pas maintenir le bas du dos collé au sol"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "leg raises"]', true, '2026-04-03 12:24:57.577514+00', '2026-04-03 12:24:57.577514+00', 'Position de départ : Allonge-toi sur le dos, les jambes tendues, bras le long du corps pour plus de stabilité. Exécution : Lève les deux jambes simultanément de manière contrôlée jusqu''à former un angle de 90 degrés avec ton torse, puis redescends-les lentement sans toucher le sol.', '["Lever les jambes trop vite sans contrôle", "Ne pas maintenir le bas du dos collé au sol"]', true, '["Lie flat on your back on a mat with your legs extended straight and arms placed at your sides or under your lower back for support", "Keep your lower back pressed against the floor throughout the entire movement to protect your spine", "Lift both legs together in a slow, controlled motion until they reach approximately 90 degrees with your torso", "Pause briefly at the top position while maintaining tension in your core muscles", "Slowly lower your legs back down in a controlled manner, stopping just before your heels touch the floor", "Repeat the movement while maintaining proper form and breathing rhythm"]', '["Allonge-toi sur le dos sur un tapis, les jambes tendues et les bras le long du corps ou sous le bas du dos pour plus de soutien", "Maintiens le bas de ton dos appuyé contre le sol tout au long de l''exercice pour protéger ta colonne vertébrale", "Lève les deux jambes ensemble de manière lente et contrôlée jusqu''à atteindre environ 90 degrés par rapport à ton torse", "Fais une pause brève en haut en gardant une tension dans tes muscles abdominaux", "Redescends tes jambes lentement, en t''arrêtant juste avant que tes talons touchent le sol", "Répète le mouvement en gardant une bonne forme et un rythme de respiration adéquat"]', '["Garde toujours le bas du dos à plat contre le sol pour éviter les tensions et maintenir un bon engagement du core", "Contrôle la descente, c''est cette phase qui met le plus au défi tes muscles abdominaux", "Si tu ressens une gêne dans le bas du dos, plie légèrement les genoux ou place tes mains sous ton bas du dos pour plus de soutien", "Concentre-toi sur l''utilisation de tes muscles abdominaux plutôt que sur l''élan pour lever et abaisser tes jambes", "Commence avec moins de répétitions et augmente progressivement à mesure que ta force de core s''améliore"]', '["Keep your lower back flat against the floor at all times to prevent strain and maintain proper core engagement", "Control the descent phase of the movement as this provides the greatest challenge and benefit to your core muscles", "If you experience lower back discomfort, bend your knees slightly or place your hands under your lower back for additional support", "Focus on using your abdominal muscles rather than momentum to lift and lower your legs", "Start with fewer repetitions and gradually increase as your core strength improves"]', 'a97548ad-e559-4380-a6b0-50cc210031b2', 'leg-raises', NULL, NULL);
INSERT INTO public.exercises VALUES ('9b548e55-e4a7-48b3-8d35-d0f36b588734', 'Fentes Dynamique', NULL, 'تمارين الاندفاع', 'Lunges', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/lunges.mp4', NULL, NULL, NULL, '/videos/thumbnails/lunges.jpg', NULL, '["Garde le torse bien droit", "Assure-toi que ton genou avant suit la ligne de tes orteils", "Ne laisse pas ton genou arrière toucher le sol avec force", "Contrôle ta descente", "Idéal pour ceux qui apprennent le mouvement de la fente"]', '["Ne pas garder le dos droit", "Laisser le genou avant dépasser les orteils"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "lunges"]', true, '2026-04-03 12:24:57.637901+00', '2026-04-03 12:24:57.637901+00', 'Place-toi en position de départ et prépare-toi à faire des fentes qui engagent tout ton corps.', '["Ne pas garder le dos droit", "Laisser le genou avant dépasser les orteils"]', true, '["Set bar at shoulder height", "Position bar on upper back", "Step one foot forward, one back", "Unrack and lower into lunge", "Front thigh parallel, then push up", "Complete reps, switch legs"]', '["Place la barre à hauteur d''épaules", "Positionne la barre sur le haut de ton dos", "Fais un pas en avant avec un pied et recule l''autre", "Dégage la barre et descends en fente", "Assure-toi que ta cuisse avant est parallèle, puis pousse pour remonter", "Effectue toutes les répétitions, puis change de jambe"]', '["Garde le torse bien droit", "Assure-toi que ton genou avant suit la ligne de tes orteils", "Ne laisse pas ton genou arrière toucher le sol avec force", "Contrôle ta descente", "Idéal pour ceux qui apprennent le mouvement de la fente"]', '["Keep torso upright", "Front knee tracks over toes", "Don''t let back knee slam floor", "Control the descent", "Good for beginners learning lunge pattern"]', 'bcfe96da-42de-445b-85bc-44afa2789f77', 'lunges', NULL, NULL);
INSERT INTO public.exercises VALUES ('205c4739-c5db-4bdd-b33b-dd9ba7008cb4', 'Posture de la charrue', NULL, NULL, 'Plow pose', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/plow-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/plow-pose.jpg', NULL, '["Ne tourne pas la tête en restant dans cette position.", "Concentre ton poids sur tes épaules, pas sur ton cou.", "Si tu as des problèmes de cou, passe cette posture."]', '["Ne pas soutenir correctement le dos, ce qui peut entraîner des douleurs.", "Oublier de respirer correctement et de se détendre."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "plow pose"]', true, '2026-04-03 12:24:58.378397+00', '2026-04-03 12:24:58.378397+00', 'Travaille intensément tes ischio-jambiers tout en améliorant ta flexibilité. Prépare-toi à ressentir l''étirement !', '["Ne pas soutenir correctement le dos, ce qui peut entraîner des douleurs.", "Oublier de respirer correctement et de se détendre."]', true, '["Lie on your back and lift your legs over your head.", "Lower your toes to the floor behind your head.", "Support your back with your hands or extend arms on the floor.", "Hold for several breaths, then roll down slowly."]', '["Allonge-toi sur le dos et lève les jambes au-dessus de ta tête.", "Abaisse doucement tes orteils vers le sol derrière ta tête.", "Soutiens ton dos avec tes mains ou allonge tes bras au sol.", "Maintiens la position plusieurs respirations, puis redescends progressivement."]', '["Ne tourne pas la tête en restant dans cette position.", "Concentre ton poids sur tes épaules, pas sur ton cou.", "Si tu as des problèmes de cou, passe cette posture."]', '["Do not turn your head while in this pose.", "Keep your weight on your shoulders, not your neck.", "Skip this pose if you have neck issues."]', '8e7c3c00-5f0b-40b1-b64d-84b78fa6ec93', 'plow-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('f7d8fe39-b325-44c5-832e-61f423842b5f', 'Pompes Plyométriques', NULL, NULL, 'Plyo Push-up', 'Chest', '[]', 'Chest', 'Advanced', 16, '/videos/chest/plyo-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/plyo-push-up.jpg', NULL, '["Atterris en douceur sur tes paumes pour réduire l''impact sur les poignets et les épaules", "Maintiens une bonne forme de pompe tout au long du mouvement pour prévenir les blessures", "Commence par de petits mouvements explosifs et augmente progressivement la hauteur en construisant ta force", "Évite cet exercice si tu as des problèmes aux poignets, aux épaules ou aux coudes", "Concentre-toi sur la qualité plutôt que sur la quantité - quelques répétitions parfaites valent mieux que des dizaines de mauvaises"]', '["Ne pas garder le corps droit pendant l''exercice", "Atterrir trop fortement, ce qui représente un risque pour les articulations"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "plyo push-up"]', true, '2026-04-03 12:24:58.391105+00', '2026-04-03 12:24:58.391105+00', 'Position de départ : mets-toi en position de pompes classique, les mains un peu plus larges que les épaules, le corps droit des pieds à la tête. Exécution : descends en pompe, puis propulse-toi explosivement vers le haut pour décoller les mains du sol. Atterrit en douceur et enchaîne immédiatement avec la prochaine répétition.', '["Ne pas garder le corps droit pendant l''exercice", "Atterrir trop fortement, ce qui représente un risque pour les articulations"]', true, '["Start in a standard push-up position with proper alignment and engage your core", "Lower your body slowly and controlled until your chest nearly touches the floor", "Explosively push up through your palms with maximum force to propel your hands off the ground", "Keep your body rigid during the airborne phase and prepare for landing", "Land softly with hands returning to starting position and absorb the impact through your arms", "Immediately transition into the next repetition or rest briefly if needed"]', '["Adopte la position de pompe standard avec le bon alignement et engage ton core", "Descends lentement et de façon contrôlée jusqu''à ce que ta poitrine frôle le sol", "Pousse avec force sur tes paumes pour décoller tes mains du sol", "Reste rigide pendant la phase aérienne et prépare-toi à atterrir", "Atterris en douceur avec les mains revenue à la position de départ et absorbe l''impact à travers tes bras", "Enchaîne immédiatement avec la prochaine répétition ou prends une courte pause si nécessaire"]', '["Atterris en douceur sur tes paumes pour réduire l''impact sur les poignets et les épaules", "Maintiens une bonne forme de pompe tout au long du mouvement pour prévenir les blessures", "Commence par de petits mouvements explosifs et augmente progressivement la hauteur en construisant ta force", "Évite cet exercice si tu as des problèmes aux poignets, aux épaules ou aux coudes", "Concentre-toi sur la qualité plutôt que sur la quantité - quelques répétitions parfaites valent mieux que des dizaines de mauvaises"]', '["Land softly on your palms to reduce impact on wrists and shoulders", "Maintain proper push-up form throughout the entire movement to prevent injury", "Start with small explosive movements and gradually increase the height as you build strength", "Avoid this exercise if you have wrist, shoulder, or elbow issues", "Focus on quality over quantity - fewer perfect reps are better than many poor ones"]', 'cbe360e8-fa98-4793-b327-c2769ac69943', 'plyo-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('b9f9c40a-02cb-4868-912a-a97bcc254bb1', 'Curl au banc preacher', NULL, 'كرل على بانك بریکر', 'Preacher Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 8, '/videos/biceps/preacher-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/preacher-curl.jpg', NULL, '["Garde les épaules basses et en arrière durant tout le mouvement pour éviter les compensations", "Évite d''utiliser l''élan ou de balancer le poids - concentre-toi sur des mouvements lents et contrôlés", "Ne fully extends pas tes bras en bas, cela peut mettre une pression excessive sur les articulations du coude", "Maintiens une tension constante sur les biceps, ne repose pas le poids en bas du mouvement", "Utilise un poids qui te permet de compléter toute l''amplitude du mouvement avec une bonne forme."]', '["Utiliser trop de poids et compenser avec d''autres muscles", "Laisser tomber les épaules vers l''avant pendant le mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "machine", "preacher curl"]', true, '2026-04-03 12:24:58.431794+00', '2026-04-03 12:24:58.431794+00', 'Position de départ : Assieds-toi sur le banc preacher, la poitrine contre le coussin incliné, les bras tendus au-dessus. Prends une barre (ou des haltères) avec une prise supinée (paumes vers le haut). Exécution : Plie les coudes pour soulever le poids vers tes épaules, garde les bras en contact avec le banc, puis redescends lentement en contrôlant le mouvement.', '["Utiliser trop de poids et compenser avec d''autres muscles", "Laisser tomber les épaules vers l''avant pendant le mouvement."]', true, '["Adjust the preacher bench height so the angled pad sits comfortably under your armpits when seated", "Grip the barbell with an underhand grip, hands positioned shoulder-width apart", "Press your chest firmly against the pad and plant your feet flat on the floor for stability", "Keep your wrists straight and avoid locking out your elbows completely at the bottom of the movement", "Curl the weight up smoothly by squeezing your biceps, pausing briefly at the top", "Lower the barbell slowly and with control, maintaining tension throughout the descent"]', '["Ajuste la hauteur du banc pour que le coussin soit confortable sous tes aisselles en étant assis", "Prends la barre avec une prise en supination, les mains écartées à la largeur des épaules", "Presse bien ta poitrine contre le coussin et pose tes pieds à plat au sol pour être stable", "Garde les poignets droits et évite de bloquer complètement les coudes en bas du mouvement", "Souligne bien et courbe le poids en contractant tes biceps, fais une pause en haut", "Abaisse le poids lentement et avec contrôle, en maintenant la tension pendant la descente."]', '["Garde les épaules basses et en arrière durant tout le mouvement pour éviter les compensations", "Évite d''utiliser l''élan ou de balancer le poids - concentre-toi sur des mouvements lents et contrôlés", "Ne fully extends pas tes bras en bas, cela peut mettre une pression excessive sur les articulations du coude", "Maintiens une tension constante sur les biceps, ne repose pas le poids en bas du mouvement", "Utilise un poids qui te permet de compléter toute l''amplitude du mouvement avec une bonne forme."]', '["Keep your shoulders down and back throughout the movement to prevent compensation", "Avoid using momentum or swinging the weight - focus on slow, controlled movements", "Don''t fully extend your arms at the bottom as this can put excessive stress on the elbow joint", "Maintain constant tension on the biceps by not resting the weight at the bottom of the movement", "Use a weight that allows you to complete the full range of motion with proper form"]', '8d3afa33-7191-4f69-a9f6-81b20f55dd38', 'preacher-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('17ec6e97-9539-4abf-a227-b4b28d888dd0', 'Curls au Banc Préacher avec Haltères', NULL, 'تمارين للبكت و قفاز', 'Preacher Hammer Curl Dumbbells', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/preacher-hammer-curl-dumbbells.mp4', NULL, NULL, NULL, '/videos/thumbnails/preacher-hammer-curl-dumbbells.jpg', NULL, '["Garde les poignets droits et alignés avec les avant-bras pour prévenir les blessures", "Concentre-toi sur la contraction de tes biceps en haut du mouvement pour une activation musculaire maximale", "Évite d''utiliser l''élan ou de balancer les poids - maintiens une forme stricte tout au long de l''exercice", "La prise neutre cible davantage le muscle brachial par rapport aux curls traditionnels", "Contrôle la phase excentrique (descente) du mouvement pour maximiser la croissance musculaire"]', '["Ne pas ajuster le banc correctement", "Utiliser trop d''élan lors des mouvements"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "preacher hammer curl dumbbells"]', true, '2026-04-03 12:24:58.46+00', '2026-04-03 12:24:58.46+00', 'Position de départ : Assieds-toi sur le banc préacher avec un haltère dans chaque main, en position marteau (paumes face au corps). Exécution : Fléchis les coudes pour soulever les haltères vers les épaules, puis redescends lentement.', '["Ne pas ajuster le banc correctement", "Utiliser trop d''élan lors des mouvements"]', true, '["Adjust the preacher bench seat height so your armpits align with the top of the angled pad", "Hold dumbbells with a neutral grip, palms facing each other throughout the entire movement", "Press your chest firmly against the pad and keep your feet flat on the floor for stability", "Curl the weights up smoothly by contracting your biceps, stopping just short of full contraction", "Lower the dumbbells slowly and under control, taking twice as long as the lifting phase", "Maintain slight bend in your elbows at the bottom position to avoid hyperextension"]', '["Ajuste la hauteur du siège du banc préacher pour que tes aisselles soient alignées avec le haut du pad incliné", "Tiens les haltères avec une prise neutre, paumes se faisant face tout au long du mouvement", "Presse bien ta poitrine contre le pad et garde les pieds à plat sur le sol pour plus de stabilité", "Curl les poids doucement en contractant tes biceps, arrête-toi juste avant la contraction complète", "Lower les haltères lentement et de manière contrôlée, en prenant deux fois plus de temps que la phase de levée", "Garde un léger pli dans tes coudes en position basse pour éviter l''hyperextension"]', '["Garde les poignets droits et alignés avec les avant-bras pour prévenir les blessures", "Concentre-toi sur la contraction de tes biceps en haut du mouvement pour une activation musculaire maximale", "Évite d''utiliser l''élan ou de balancer les poids - maintiens une forme stricte tout au long de l''exercice", "La prise neutre cible davantage le muscle brachial par rapport aux curls traditionnels", "Contrôle la phase excentrique (descente) du mouvement pour maximiser la croissance musculaire"]', '["Keep your wrists straight and aligned with your forearms to prevent injury", "Focus on squeezing your biceps at the top of the movement for maximum muscle activation", "Avoid using momentum or swinging the weights - maintain strict form throughout", "The neutral grip targets the brachialis muscle more effectively than traditional curls", "Control the eccentric (lowering) portion of the movement to maximize muscle growth"]', '430ce933-5f38-44b9-8b43-810da4ec536e', 'preacher-hammer-curl-dumbbells', NULL, NULL);
INSERT INTO public.exercises VALUES ('5ab96164-dc4f-4b62-994c-b64337845f74', 'Développé Épaules Unilatéral avec Haltère (Gauche)', NULL, NULL, 'Dumbbell One-Arm Shoulder Press (L)', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/dumbbell-one-arm-shoulder-press-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-one-arm-shoulder-press-l.jpg', NULL, '["Engage ton ventre tout au long de l''exercice pour éviter un creux dans le dos", "Ne pousse pas le poids vers l''avant ou vers l''arrière - garde une trajectoire verticale", "Utilise ton bras non actif pour t''aider à garder l''équilibre sans te pencher sur le côté", "Contrôle bien la phase de descente autant que celle de la poussée pour maximiser l''engagement musculaire", "Arrête immédiatement si tu ressens une douleur aiguë dans l''articulation de l''épaule"]', '["Ne pas engager le ventre, ce qui peut entraîner une mauvaise posture", "Pousser l''haltère de travers, réduisant l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "dumbbell one-arm shoulder press (l)"]', true, '2026-04-03 12:24:56.505753+00', '2026-04-03 12:24:56.505753+00', 'Place-toi debout, les pieds écartés à la largeur des épaules, un haltère dans la main gauche à hauteur d''épaule, paume face à l''avant et coude fléchi à 90 degrés. Prêt ? C''est parti !', '["Ne pas engager le ventre, ce qui peut entraîner une mauvaise posture", "Pousser l''haltère de travers, réduisant l''efficacité de l''exercice"]', true, '["Stand with feet shoulder-width apart and engage your core for stability", "Hold the dumbbell in your left hand at shoulder height with palm facing forward", "Keep your elbow directly under the dumbbell and maintain a neutral wrist position", "Press the weight straight up overhead in a controlled motion until your arm is fully extended", "Slowly lower the dumbbell back to shoulder height, maintaining control throughout the descent", "Complete all repetitions on the left side before switching to the right arm"]', '["Tiens-toi droit, engage ton ventre pour la stabilité", "Prends l''haltère dans ta main gauche, à hauteur d''épaule, paume vers l''avant", "Garde ton coude juste sous l''haltère et le poignet dans une position neutre", "Pousse l''haltère directement au-dessus de ta tête de manière contrôlée jusqu''à ce que ton bras soit complètement tendu", "Redescends lentement l''haltère jusqu''à la hauteur de l''épaule, en gardant le contrôle sur toute la descente", "Fais toutes les répétitions du côté gauche avant de passer au bras droit"]', '["Engage ton ventre tout au long de l''exercice pour éviter un creux dans le dos", "Ne pousse pas le poids vers l''avant ou vers l''arrière - garde une trajectoire verticale", "Utilise ton bras non actif pour t''aider à garder l''équilibre sans te pencher sur le côté", "Contrôle bien la phase de descente autant que celle de la poussée pour maximiser l''engagement musculaire", "Arrête immédiatement si tu ressens une douleur aiguë dans l''articulation de l''épaule"]', '["Keep your core engaged throughout the movement to prevent arching your back", "Avoid pressing the weight forward or backward - maintain a straight vertical path", "Use your non-working arm for balance but avoid leaning to one side", "Control the descent phase as much as the pressing phase to maximize muscle engagement", "Stop immediately if you feel any sharp pain in your shoulder joint"]', 'af545111-e56a-4731-ba48-2d4ce750bc8e', 'dumbbell-one-arm-shoulder-press-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('ec32d6b6-3fd8-41c7-ad71-17f0c28f5cb2', 'Machine Reverse Fly', NULL, 'آلة الطيران العكسي', 'Machine Reverse Fly', 'Shoulders', '[]', 'Shoulders', 'Beginner', 8, '/videos/shoulders/machine-reverse-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/machine-reverse-fly.jpg', NULL, '["Maintiens ta poitrine pressée contre le coussin durant tout le mouvement pour assurer stabilité et alignement", "Concentre-toi sur l''initiation du mouvement à partir de tes deltoïdes arrière plutôt qu''avec tes bras ou tes muscles du dos", "Évite d''utiliser l''élan ou de rebondir en bas du mouvement pour prévenir les blessures", "Garde un léger pli dans tes coudes tout au long de l''exercice pour protéger tes articulations", "Serre tes omoplates ensemble à la contraction maximale pour une activation musculaire optimale"]', '["Sauter sur le poids trop lourd dès le départ", "Ne pas maintenir une bonne posture en se penchant en avant"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "machine reverse fly"]', true, '2026-04-03 12:24:57.77926+00', '2026-04-03 12:24:57.77926+00', 'Position de départ : assieds-toi sur la machine de vol inversé, les bras le long du corps et les mains sur les poignées. Exécution : élève tes bras en arrière jusqu''à la hauteur des épaules, puis redescends lentement.', '["Sauter sur le poids trop lourd dès le départ", "Ne pas maintenir une bonne posture en se penchant en avant"]', true, '["Adjust the seat height so your arms are parallel to the floor when grasping the handles", "Set your chest firmly against the pad and maintain good posture throughout the movement", "Select an appropriate weight that allows you to complete the full range of motion with proper form", "Grip the handles with a neutral wrist position and keep a slight bend in your elbows", "Pull your arms back in a smooth arc until you feel a strong contraction in your rear delts", "Lower the weight slowly and under control, taking twice as long as the pulling phase"]', '["Ajuste la hauteur du siège pour que tes bras soient parallèles au sol lorsque tu saisis les poignées", "Appuie ta poitrine contre le coussin et garde une bonne posture pendant tout l''exercice", "Choisis un poids approprié qui te permet de compléter l''amplitude totale du mouvement avec la bonne forme", "Saisis les poignées avec des poignets neutres et garde un léger pli dans les coudes", "Tire tes bras en arrière dans un arc fluide jusqu''à ressentir une forte contraction dans tes deltoïdes postérieurs", "Abaisse le poids lentement et sous contrôle, en prenant deux fois plus de temps que lors de la phase de tirage"]', '["Maintiens ta poitrine pressée contre le coussin durant tout le mouvement pour assurer stabilité et alignement", "Concentre-toi sur l''initiation du mouvement à partir de tes deltoïdes arrière plutôt qu''avec tes bras ou tes muscles du dos", "Évite d''utiliser l''élan ou de rebondir en bas du mouvement pour prévenir les blessures", "Garde un léger pli dans tes coudes tout au long de l''exercice pour protéger tes articulations", "Serre tes omoplates ensemble à la contraction maximale pour une activation musculaire optimale"]', '["Keep your chest pressed against the pad throughout the entire movement to maintain stability and proper alignment", "Focus on initiating the movement from your rear deltoids rather than using your arms or back muscles", "Avoid using momentum or bouncing at the bottom of the movement to prevent injury", "Maintain a slight bend in your elbows throughout the exercise to protect your joints", "Squeeze your shoulder blades together at the peak contraction for maximum muscle activation"]', '23781248-d4d6-418e-a5a0-932abb0ca32b', 'machine-reverse-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('b66eb4ae-f753-4c46-9f7b-0bed945e0073', 'Maintien en Flexion Des Bras', NULL, 'تثبيت في ضغط الذراعين', 'Push up hold', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/push-up-hold.mp4', NULL, NULL, NULL, '/videos/thumbnails/push-up-hold.jpg', NULL, '["Garde ton corps dans une ligne droite pendant le maintien - évite les hanches qui s''affaissent ou les fesses qui se relèvent", "Répartis le poids de manière homogène entre tes mains et évite que tes poignets ne s''affaissent vers l''intérieur", "Engage tes muscles pectoraux en appuyant légèrement le sol pendant le maintien", "Arrête l''exercice immédiatement si tu ressens une douleur au poignet ou si tu ne peux pas maintenir la bonne forme", "Commence par de courtes durées de maintien et augmente progressivement le temps à mesure que ta force s''améliore"]', '["Ne pas maintenir une ligne droite du corps", "Trop de poids sur les poignets au lieu de les répartir correctement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "push up hold"]', true, '2026-04-03 12:24:58.480013+00', '2026-04-03 12:24:58.480013+00', 'Position de départ : Place-toi en position de planche haute, mains écartées légèrement plus que la largeur des épaules, bras tendus, corps formant une ligne droite de la tête aux talons. Exécution : Maintiens cette position statique tout en gardant une bonne forme de planche et en engageant les muscles de la poitrine, des épaules et du tronc durant tout l''exercice.', '["Ne pas maintenir une ligne droite du corps", "Trop de poids sur les poignets au lieu de les répartir correctement"]', true, '["Position hands flat on the ground slightly wider than shoulder-width apart with fingers spread for stability", "Extend legs behind you and balance on your toes, creating a straight line from head to heels", "Engage your core muscles and squeeze your glutes to maintain proper body alignment", "Keep your arms fully extended and locked out at the elbows", "Hold the position for the prescribed time while breathing steadily", "Lower to your knees when you can no longer maintain proper form"]', '["Place tes mains à plat sur le sol, légèrement plus larges que la largeur des épaules, avec les doigts écartés pour plus de stabilité", "Étends tes jambes derrière toi et équilibre-toi sur tes orteils, créant une ligne droite de la tête aux talons", "Engage tes muscles abdominaux et contracte tes fessiers pour maintenir un bon alignement corporel", "Garde les bras pleinement tendus et verrouillés au niveau des coudes", "Tiens cette position durant le temps imparti tout en respirant régulièrement", "Descends sur les genoux si tu ne peux plus maintenir la bonne forme"]', '["Garde ton corps dans une ligne droite pendant le maintien - évite les hanches qui s''affaissent ou les fesses qui se relèvent", "Répartis le poids de manière homogène entre tes mains et évite que tes poignets ne s''affaissent vers l''intérieur", "Engage tes muscles pectoraux en appuyant légèrement le sol pendant le maintien", "Arrête l''exercice immédiatement si tu ressens une douleur au poignet ou si tu ne peux pas maintenir la bonne forme", "Commence par de courtes durées de maintien et augmente progressivement le temps à mesure que ta force s''améliore"]', '["Keep your body in a straight line throughout the hold - avoid sagging hips or raised buttocks", "Distribute weight evenly between your hands and avoid letting wrists collapse inward", "Engage your chest muscles by slightly pressing the ground away from you during the hold", "Stop the exercise immediately if you experience wrist pain or cannot maintain proper form", "Start with shorter hold times and gradually increase duration as strength improves"]', '9c454a78-ff62-49a9-9879-127b48d6f2ea', 'push-up-hold', NULL, NULL);
INSERT INTO public.exercises VALUES ('6a6a66bd-4a70-489e-9422-ff5e3dcad7f3', 'Pompes avec toucher de pieds', NULL, NULL, 'Push up to toe touches', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/push-up-to-toe-touches.mp4', NULL, NULL, NULL, '/videos/thumbnails/push-up-to-toe-touches.jpg', NULL, '["Gardez votre ventre bien serré tout au long de l''exercice pour protéger le bas du dos", "Maintenez une bonne forme de pompes avant d''ajouter le mouvement de toucher de pied", "Contrôlez la transition entre la position de pompe et la position pike pour éviter l''élan", "Si vous ne pouvez pas toucher vos pieds, visez vos tibias ou chevilles", "Concentrez-vous sur la qualité du mouvement plutôt que sur la vitesse pour maximiser l''engagement musculaire"]', '["Ne pas garder le corps en ligne droite pendant la pompe", "Utiliser l''élan au lieu du contrôle lors de la transition entre les mouvements"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "push up to toe touches"]', true, '2026-04-03 12:24:58.503295+00', '2026-04-03 12:24:58.503295+00', 'Position de départ : Adoptez la position de pompes classique, mains plus larges que les épaules, corps bien droit de la tête aux talons. Exécution : Effectuez une pompe, puis en haut du mouvement, levez les hanches vers le plafond et touchez un pied avec la main opposée. Revenez à la position de pompes et répétez de l''autre côté.', '["Ne pas garder le corps en ligne droite pendant la pompe", "Utiliser l''élan au lieu du contrôle lors de la transition entre les mouvements"]', true, '["Start in a plank position with hands firmly planted and core engaged", "Lower your chest toward the floor while maintaining a straight body line", "Press back up to the starting push-up position with control", "Pike your hips up toward the ceiling while keeping legs straight", "Reach your right hand toward your left toe, then return to push-up position", "Alternate reaching your left hand toward your right toe on the next repetition"]', '["Commencez en position de planche avec les mains bien ancrées et le ventre contracté", "Abaissez votre poitrine vers le sol tout en gardant le corps bien droit", "Remontez en position de pompes avec contrôle", "Levez vos hanches vers le plafond tout en gardant les jambes tendues", "Tendez votre main droite vers votre pied gauche, puis revenez en position de pompes", "Alternez en tendant votre main gauche vers votre pied droit au prochain mouvement"]', '["Gardez votre ventre bien serré tout au long de l''exercice pour protéger le bas du dos", "Maintenez une bonne forme de pompes avant d''ajouter le mouvement de toucher de pied", "Contrôlez la transition entre la position de pompe et la position pike pour éviter l''élan", "Si vous ne pouvez pas toucher vos pieds, visez vos tibias ou chevilles", "Concentrez-vous sur la qualité du mouvement plutôt que sur la vitesse pour maximiser l''engagement musculaire"]', '["Keep your core tight throughout the entire movement to protect your lower back", "Maintain proper push-up form before adding the toe touch component", "Control the transition between push-up and pike positions to avoid momentum", "If you cannot reach your toes, reach toward your shins or ankles instead", "Focus on the quality of movement rather than speed to maximize muscle engagement"]', 'c809dc45-6a40-4060-a8ac-24f3c62358f7', 'push-up-to-toe-touches', NULL, NULL);
INSERT INTO public.exercises VALUES ('8fcdd14f-23a4-4d50-828e-7848da328028', 'Burpee Shot Caller', NULL, NULL, 'Shot Caller Burpee', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/shot-caller-burpee.mp4', NULL, NULL, NULL, '/videos/thumbnails/shot-caller-burpee.jpg', NULL, '["Maintiens une ligne droite de la tête aux talons pendant la planche et le push-up.", "Garde les abdos serrés durant tout le mouvement pour protéger le bas du dos.", "Atterris doucement sur la plante des pieds pour réduire l''impact sur les articulations.", "Pour les personnes ayant des soucis de genoux ou d''articulations, opte pour une variante en marchant au lieu de sauter.", "Priorise la qualité des mouvements sur la vitesse, surtout lors de l''apprentissage de l''exercice."]', '["Ne pas maintenir une bonne posture en planche et en push-up.", "Ne pas engager les abdos, ce qui peut entraîner des douleurs lombaires."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "shot caller burpee"]', true, '2026-04-03 12:24:58.954253+00', '2026-04-03 12:24:58.954253+00', 'Prépare-toi à un défi pour tout le corps ! Le burpee shot caller combine puissance et explosivité. Prêt à donner le meilleur de toi-même ?', '["Ne pas maintenir une bonne posture en planche et en push-up.", "Ne pas engager les abdos, ce qui peut entraîner des douleurs lombaires."]', true, '["Start standing with feet hip-width apart, then squat down and place hands on the floor in front of you", "Jump or step both feet back into a high plank position, keeping your core engaged", "Perform a push-up, lowering your chest to the floor and pressing back up", "Jump or step feet back toward your hands, returning to the squat position", "Explosively jump up with arms overhead, reaching as high as possible", "Land softly and immediately transition into the next repetition"]', '["Commence en te tenant debout, les pieds écartés à la largeur des hanches. Plie-toi en squat et pose tes mains au sol devant toi.", "Saute ou fais un pas en arrière avec les deux pieds en position de planche haute, en gardant les abdos bien engagés.", "Fais un push-up en abaissant la poitrine vers le sol et en te relevant.", "Ramène tes pieds vers tes mains en sautant ou en marchant, retourne en position de squat.", "Saute de façon explosive en levant les bras au-dessus de ta tête, atteignant la hauteur maximale possible.", "Atterris en douceur et enchaîne immédiatement avec la répétition suivante."]', '["Maintiens une ligne droite de la tête aux talons pendant la planche et le push-up.", "Garde les abdos serrés durant tout le mouvement pour protéger le bas du dos.", "Atterris doucement sur la plante des pieds pour réduire l''impact sur les articulations.", "Pour les personnes ayant des soucis de genoux ou d''articulations, opte pour une variante en marchant au lieu de sauter.", "Priorise la qualité des mouvements sur la vitesse, surtout lors de l''apprentissage de l''exercice."]', '["Maintain a straight line from head to heels during the plank and push-up phases", "Keep your core tight throughout the entire movement to protect your lower back", "Land softly on the balls of your feet when jumping to reduce impact on joints", "Modify by stepping instead of jumping if you have knee or joint concerns", "Focus on controlled movement quality over speed, especially when learning the exercise"]', '0a7821b6-c36b-4b5f-82b0-5c8ba765baae', 'shot-caller-burpee', NULL, NULL);
INSERT INTO public.exercises VALUES ('17fc85cb-6b91-4a6e-9061-567a9591d210', 'Inverser la Course de L''ours', NULL, NULL, 'Forward to Reverse Bear Crawl', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/forward-to-reverse-bear-crawl.mp4', NULL, NULL, NULL, '/videos/thumbnails/forward-to-reverse-bear-crawl.jpg', NULL, '["Gardez les genoux juste au-dessus du sol tout au long du mouvement pour maintenir la tension.", "Maintenez un dos neutre en engageant votre ventre, sans affaisser les hanches ni relever le postérieur.", "Déplacez-vous avec contrôle et coordination, en vous assurant que la main et le pied opposés se déplacent ensemble.", "Répartissez votre poids uniformément entre les mains et les pieds pour éviter une surcharge des poignets.", "Commencez par des distances plus courtes et augmentez progressivement à mesure que vous gagnez en force et en coordination."]', '["Ne pas garder les genoux au-dessus du sol, ce qui diminue l''efficacité de l''exercice.", "S''affaisser au niveau des hanches, ce qui peut causer des douleurs au dos."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "forward to reverse bear crawl"]', true, '2026-04-03 12:24:56.767474+00', '2026-04-03 12:24:56.767474+00', 'Commence en position quadrupède, mains sous les épaules, genoux sous les hanches, orteils repliés pour le soutien. Soulève tes genoux de 2-3 cm du sol et prépare-toi à avancer !', '["Ne pas garder les genoux au-dessus du sol, ce qui diminue l''efficacité de l''exercice.", "S''affaisser au niveau des hanches, ce qui peut causer des douleurs au dos."]', true, '["Start in a bear crawl position with hands under shoulders, knees under hips hovering 2-3 inches off the ground, and core engaged.", "Move forward by stepping your right hand and left foot forward simultaneously, followed by your left hand and right foot.", "Take 3-4 steps forward maintaining the low bear crawl position throughout the movement.", "Reverse the movement by stepping your right hand and left foot backward simultaneously, followed by your left hand and right foot.", "Take 3-4 steps backward to return to your starting position.", "Repeat the forward-to-reverse sequence for the desired number of repetitions."]', '["Adoptez la position de l''ours avec les mains sous les épaules, genoux sous les hanches à 2-3 cm du sol, et le ventre bien engagé.", "Avancez en déplaçant simultanément votre main droite et votre pied gauche, puis votre main gauche et votre pied droit.", "Faites 3-4 pas en avant en maintenant cette position basse d''ours.", "Inverser le mouvement en déplaçant votre main droite et votre pied gauche vers l''arrière, suivis de votre main gauche et de votre pied droit.", "Faites 3-4 pas en arrière pour revenir à la position de départ.", "Répétez la séquence avant-arrière pour le nombre de répétitions souhaité."]', '["Gardez les genoux juste au-dessus du sol tout au long du mouvement pour maintenir la tension.", "Maintenez un dos neutre en engageant votre ventre, sans affaisser les hanches ni relever le postérieur.", "Déplacez-vous avec contrôle et coordination, en vous assurant que la main et le pied opposés se déplacent ensemble.", "Répartissez votre poids uniformément entre les mains et les pieds pour éviter une surcharge des poignets.", "Commencez par des distances plus courtes et augmentez progressivement à mesure que vous gagnez en force et en coordination."]', '["Keep your knees hovering just above the ground throughout the entire movement to maintain tension", "Maintain a neutral spine by engaging your core and avoiding sagging hips or raised buttocks", "Move with control and coordination, ensuring opposite hand and foot move together", "Keep your weight evenly distributed between hands and feet to prevent excessive strain on wrists", "Start with shorter distances and gradually increase range as you build strength and coordination"]', '0df165d9-3c63-4506-a2f1-6f64544fda5d', 'forward-to-reverse-bear-crawl', NULL, NULL);
INSERT INTO public.exercises VALUES ('6bacf84c-4e71-46dd-9cb6-2772802b5f94', 'Pompes', NULL, 'Pushups', 'Pushups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/pushups.mp4', NULL, NULL, NULL, '/videos/thumbnails/pushups.jpg', NULL, '["Garde ton ventre bien serré et évite que tes hanches ne s''affaissent ou ne se relèvent pendant l''exercice", "Adopte une position neutre pour ton cou, regarde le sol environ 15 cm devant tes mains", "Si les pompes classiques te paraissent trop difficiles, fais-les sur les genoux ou contre une surface élevée", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse, cela maximisera l''engagement musculaire et préviendra les blessures", "Veille à effectuer l''amplitude complète en descendant jusqu''à ce que ta poitrine frôle le sol et en repoussant jusqu'' à l''extension complète des bras."]', '["Ne pas garder le corps en ligne droite en laissant les hanches s''affaisser ou se relever", "Oublier de bien contrôler le mouvement en descendant ou en remontant."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "pushups"]', true, '2026-04-03 12:24:58.53758+00', '2026-04-03 12:24:58.53758+00', 'Position de départ : Mets-toi en position de planche, mains légèrement plus larges que la largeur des épaules, bras tendus, corps droit de la tête aux talons. Exécution : Abaisse ton corps en fléchissant les coudes jusqu''à ce que ta poitrine frôle le sol, puis pousse avec force pour revenir à la position initiale en tendant les bras.', '["Ne pas garder le corps en ligne droite en laissant les hanches s''affaisser ou se relever", "Oublier de bien contrôler le mouvement en descendant ou en remontant."]', true, '["Position hands flat on the floor slightly wider than shoulder-width with fingers pointing forward", "Keep your body in a straight line from head to heels, engaging your core throughout the movement", "Lower your body slowly and controlled until your chest is about 2-3 inches from the floor", "Keep your elbows at a 45-degree angle from your torso as you descend", "Push through your palms to return to the starting position with full arm extension", "Maintain steady breathing, inhaling on the way down and exhaling as you push up"]', '["Positionne les mains à plat sur le sol, un peu plus larges que la largeur des épaules, doigts tournés vers l''avant", "Garde ton corps bien aligné de la tête aux pieds, en engageant ton ventre tout au long du mouvement", "Abaisse-toi lentement jusqu''à ce que ta poitrine soit à environ 5-7 cm du sol", "Garde tes coudes à environ 45 degrés de ton torse en descendant", "Pousse avec la paume des mains pour revenir à la position de départ en tendant complètement les bras", "Respire régulièrement, inhale en descendant et expire en remontant."]', '["Garde ton ventre bien serré et évite que tes hanches ne s''affaissent ou ne se relèvent pendant l''exercice", "Adopte une position neutre pour ton cou, regarde le sol environ 15 cm devant tes mains", "Si les pompes classiques te paraissent trop difficiles, fais-les sur les genoux ou contre une surface élevée", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse, cela maximisera l''engagement musculaire et préviendra les blessures", "Veille à effectuer l''amplitude complète en descendant jusqu''à ce que ta poitrine frôle le sol et en repoussant jusqu'' à l''extension complète des bras."]', '["Keep your core tight and avoid letting your hips sag or pike up during the movement", "Maintain a neutral neck position by looking at the floor about 6 inches in front of your hands", "If standard pushups are too difficult, modify by performing them on your knees or against an elevated surface", "Focus on controlled movement rather than speed to maximize muscle engagement and prevent injury", "Ensure full range of motion by going down until your chest nearly touches the floor and pushing up to complete arm extension"]', 'f860eed0-1645-401e-bfe0-ddbc4ba2df90', 'pushups', NULL, NULL);
INSERT INTO public.exercises VALUES ('278e48a0-9f60-4cd3-8bcd-ada071402a99', 'Pose de la pyramide (droite)', NULL, 'وضعية الاهرام (يمنى)', 'Pyramid pose (right)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/pyramid-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/pyramid-pose-right.jpg', NULL, '["Garde les deux jambes droites avec une légère flexion au genou avant.", "Incline-toi à partir des hanches.", "Presse uniformément sur les deux pieds."]', '["Ne pas maintenir le dos plat lors de l''inclinaison.", "Oublier d''aligner les hanches correctement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "pyramid pose (right)"]', true, '2026-04-03 12:24:58.544756+00', '2026-04-03 12:24:58.544756+00', 'Renforce tes ischio-jambiers avec cette pose profonde et bénéfique. Prépare-toi à t''étirer et à te recentrer !', '["Ne pas maintenir le dos plat lors de l''inclinaison.", "Oublier d''aligner les hanches correctement."]', true, '["Stand with one foot stepped back about 3 feet.", "Square your hips toward the front of the mat.", "Fold forward over your front leg with a flat back.", "Place your hands on the floor or on blocks beside your front foot."]', '["Positionne un pied à environ un mètre de distance derrière toi.", "Aligne tes hanches vers l''avant du tapis.", "Incline-toi en avant sur ta jambe avant en gardant le dos plat.", "Place tes mains au sol ou sur des blocs à côté de ton pied avant."]', '["Garde les deux jambes droites avec une légère flexion au genou avant.", "Incline-toi à partir des hanches.", "Presse uniformément sur les deux pieds."]', '["Keep both legs straight with a micro-bend in the front knee.", "Hinge from the hips.", "Press evenly through both feet."]', '88d0a597-e95d-4c1a-a296-aa7315c3a53b', 'pyramid-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('141978ce-4b1b-47d1-aaf4-cfc18ce490c8', 'Papillon allongé', NULL, NULL, 'Reclined butterfly', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/reclined-butterfly.mp4', NULL, NULL, NULL, '/videos/thumbnails/reclined-butterfly.jpg', NULL, '["Utilise des coussins ou des blocs pour soutenir tes genoux.", "Laisse la gravité faire le travail, évite de forcer l''étirement.", "Cette posture est réparatrice — concentre-toi sur ta respiration profonde."]', '["Forcer l''ouverture des genoux, ce qui peut créer des tensions inutiles.", "Oublier de respirer profondément, ce qui diminue les benefits de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "reclined butterfly"]', true, '2026-04-03 12:24:58.558358+00', '2026-04-03 12:24:58.558358+00', 'Cet exercice est idéal pour assouplir les hanches et détendre les fessiers. Parfait pour récupérer après une session intense !', '["Forcer l''ouverture des genoux, ce qui peut créer des tensions inutiles.", "Oublier de respirer profondément, ce qui diminue les benefits de l''exercice."]', true, '["Lie on your back and bring the soles of your feet together.", "Let your knees fall open to the sides.", "Rest your arms at your sides with palms up.", "Close your eyes and relax for several minutes."]', '["Allonge-toi sur le dos et joins les plantes de tes pieds.", "Laisse tes genoux s''écarter sur les côtés.", "Pose tes bras le long du corps, paumes vers le haut.", "Ferme les yeux et laisse-toi aller pendant plusieurs minutes."]', '["Utilise des coussins ou des blocs pour soutenir tes genoux.", "Laisse la gravité faire le travail, évite de forcer l''étirement.", "Cette posture est réparatrice — concentre-toi sur ta respiration profonde."]', '["Place pillows or blocks under your knees for support.", "Let gravity do the work — do not force the stretch.", "This is a restorative pose — focus on deep breathing."]', '843c04e2-6344-48ad-8641-0321a60dbb63', 'reclined-butterfly', NULL, NULL);
INSERT INTO public.exercises VALUES ('a7fea9aa-0027-434c-8987-e480406ed63e', 'Posture de la vache (côté droit)', NULL, 'وضعية وجه البقرة (الجانب الأيمن)', 'Cow face pose (right)', 'Shoulders', '[]', 'Shoulders', 'Beginner', 16, '/videos/shoulders/cow-face-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/cow-face-pose-right.jpg', NULL, '["Garde ta colonne vertébrale droite et évite de pencher en avant pendant l''étirement", "Ne force pas tes mains à se toucher si ta souplesse ne le permet pas - utilise une serviette ou une sangle si nécessaire", "Concentre-toi sur l''élévation du sommet de ta tête pour maintenir une bonne posture", "Respire profondément tout au long de la position pour intensifier l''étirement des épaules", "Change de côté pour assurer un développement équilibré de ta flexibilité"]', '["Pencher le torse en avant", "Ne pas respirer profondément pendant l''étirement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "bodyweight", "cow face pose (right)"]', true, '2026-04-03 12:24:56.161024+00', '2026-04-03 12:24:56.161024+00', 'Position de départ : Mets-toi à genoux sur le tapis, les jambes positionnées sur un côté, assis sur tes talons. Exécution : Lève ton bras droit vers le ciel, plie le coude pour le ramener derrière ta tête, puis amène ton bras gauche derrière ton dos en essayant de relier tes mains ensemble.', '["Pencher le torse en avant", "Ne pas respirer profondément pendant l''étirement"]', true, '["Kneel on your mat and position your legs to one side, sitting back comfortably", "Raise your right arm straight up toward the ceiling", "Bend your right elbow and reach your right hand down behind your head toward your upper back", "Bring your left arm behind your back and reach your left hand up toward your right hand", "Attempt to clasp your hands together behind your back, or use a strap if needed", "Hold the position while breathing steadily, then slowly release"]', '["À genoux sur ton tapis, positionne tes jambes sur le côté, repose-toi confortablement sur tes talons", "Lève ton bras droit vers le plafond", "Plie ton coude droit et fais descendre ta main vers le haut de ton dos", "Amène ton bras gauche derrière ton dos et tends-le vers ta main droite", "Tente de relier tes mains derrière ton dos, ou utilise une sangle si besoin", "Reste dans la position en respirant calmement, puis relâche lentement"]', '["Garde ta colonne vertébrale droite et évite de pencher en avant pendant l''étirement", "Ne force pas tes mains à se toucher si ta souplesse ne le permet pas - utilise une serviette ou une sangle si nécessaire", "Concentre-toi sur l''élévation du sommet de ta tête pour maintenir une bonne posture", "Respire profondément tout au long de la position pour intensifier l''étirement des épaules", "Change de côté pour assurer un développement équilibré de ta flexibilité"]', '["Keep your spine straight and avoid leaning forward during the stretch", "Don''t force your hands to touch if flexibility doesn''t allow it - use a towel or strap as assistance", "Focus on lifting through the crown of your head to maintain good posture", "Breathe deeply throughout the hold to help deepen the shoulder stretch", "Switch sides to ensure balanced flexibility development"]', '4d433881-e521-45e3-a36e-8672953714c0', 'cow-face-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('9eac0bee-9e5d-485d-95e8-dc60be78a9e9', 'Flexion Inversée à la Câble', NULL, NULL, 'Reverse Cable Preacher Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 4, '/videos/biceps/reverse-cable-preacher-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/reverse-cable-preacher-curl.jpg', NULL, '["Utilise un poids léger à modéré car les avant-bras sont des muscles plus petits qui se fatiguent rapidement.", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement musculaire et éviter les blessures.", "Garde tes poignets en position neutre pendant tout l''exercice pour éviter les tensions.", "Maintiens une tension constante sur les avant-bras en empêchant la pile de poids de reposer entre les répétitions.", "Arrête l''exercice si tu ressens une douleur aiguë dans tes poignets ou coudes."]', '["Ne pas maintenir le contact entre les bras et le coussin.", "Utiliser un poids trop lourd qui compromet l''exécution."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["forearms", "cable", "reverse cable preacher curl"]', true, '2026-04-03 12:24:58.572951+00', '2026-04-03 12:24:58.572951+00', 'Départ : Tiens-toi debout face à un poulie basse avec une prise en pronation. Exécution : Plie les coudes pour amener la barre vers tes épaules, puis redescends doucement.', '["Ne pas maintenir le contact entre les bras et le coussin.", "Utiliser un poids trop lourd qui compromet l''exécution."]', true, '["Set the cable pulley to its lowest position and attach a straight bar or EZ-curl bar", "Adjust the preacher bench so the angled pad supports your forearms comfortably when seated", "Grip the bar with an overhand grip, hands shoulder-width apart, and rest your forearms flat against the pad", "Keep your chest up and core engaged while maintaining contact between your upper arms and the pad throughout the movement", "Curl the weight up by contracting your forearms and wrists, focusing on the squeeze at the top", "Lower the weight slowly and under control, feeling the stretch in your forearms at the bottom"]', '["Fixe la poulie à sa position la plus basse et attache une barre droite ou une barre EZ.", "Ajuste le banc incliné pour que le coussin soutienne confortablement tes avant-bras quand tu es assis.", "Saisis la barre avec une prise en pronation, les mains écartées de la largeur des épaules, et repose tes avant-bras à plat sur le coussin.", "Garde la poitrine relevée et le ventre engagé tout en maintenant le contact entre tes bras supérieurs et le coussin pendant le mouvement.", "Fais monter le poids en contractant tes avant-bras et tes poignets, focalise-toi sur la contraction en haut.", "Redescends lentement et de manière contrôlée, ressens l''étirement dans tes avant-bras en bas."]', '["Utilise un poids léger à modéré car les avant-bras sont des muscles plus petits qui se fatiguent rapidement.", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement musculaire et éviter les blessures.", "Garde tes poignets en position neutre pendant tout l''exercice pour éviter les tensions.", "Maintiens une tension constante sur les avant-bras en empêchant la pile de poids de reposer entre les répétitions.", "Arrête l''exercice si tu ressens une douleur aiguë dans tes poignets ou coudes."]', '["Use a light to moderate weight as forearms are smaller muscles that fatigue quickly", "Focus on controlled movements rather than speed to maximize muscle engagement and prevent injury", "Keep your wrists in a neutral position throughout the exercise to avoid strain", "Maintain constant tension on the forearms by not allowing the weight stack to rest between repetitions", "Stop the exercise if you experience any sharp pain in your wrists or elbows"]', '7cfe78ab-8d77-4142-8199-51d3f48b9430', 'reverse-cable-preacher-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('ee07c337-5f09-4360-b76d-2a67e93d30c4', 'Tirer avec puissance : Rowing inversé', NULL, NULL, 'Reverse grip bent over rows', 'Back', '[]', 'Back', 'Intermediate', 2, '/videos/back/reverse-grip-bent-over-rows.mp4', NULL, NULL, NULL, '/videos/thumbnails/reverse-grip-bent-over-rows.jpg', NULL, '["Ramène ton ventre pour protéger ton bas du dos tout en gardant une bonne posture.", "Concentre-toi sur la contraction de tes omoplates, pas seulement sur le mouvement des bras, pour activer au max tes muscles du dos.", "Prends ton temps avec une descente contrôlée vers la position de départ pour un meilleur développement musculaire.", "Évite de balancer le corps ou d’utiliser l’élan, ça diminue l’efficacité et augmente le risque de blessure.", "Garde toujours ton cou aligné avec ta colonne vertébrale, ne le relève pas. "]', '["Arrondi du dos lors de l’exercice.", "Utilisation de l’élan au lieu de la force musculaire."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "reverse grip bent over rows"]', true, '2026-04-03 12:24:58.586142+00', '2026-04-03 12:24:58.586142+00', 'Plante-toi bien, pieds écartés à la largeur des hanches. Penche-toi vers l’avant en gardant le dos droit, les bras tendus vers le bas avec les paumes vers l’avant, en prise inversée. Prépare-toi à activer ton dos !', '["Arrondi du dos lors de l’exercice.", "Utilisation de l’élan au lieu de la force musculaire."]', true, '["Hinge at your hips and lean forward approximately 45 degrees while keeping your chest up and core engaged", "Position your arms straight down with palms facing forward, creating the reverse grip hand position", "Initiate the movement by pulling your elbows back toward your ribs while squeezing your shoulder blades together", "Focus on lifting your chest and pulling your shoulder blades down and back throughout the movement", "Hold the top position briefly before slowly returning to the starting position", "Maintain the hip hinge position and avoid rounding your back throughout the entire exercise"]', '["Penche-toi en avant à environ 45 degrés, avec la poitrine haute et le ventre contracté.", "Laisse tes bras pendre vers le bas, paumes vers l’avant en prise inversée.", "Tire tes coudes vers l’arrière en direction de tes côtes tout en serrant tes omoplates.", "Maintiens la poitrine relevée et tire les omoplates vers le bas et en arrière durant tout le mouvement.", "Reste en haut un instant avant de contrôler le retour à la position de départ.", "Ne dors pas sur tes lauriers, garde la position de flexion des hanches pour éviter d’arrondir le dos. "]', '["Ramène ton ventre pour protéger ton bas du dos tout en gardant une bonne posture.", "Concentre-toi sur la contraction de tes omoplates, pas seulement sur le mouvement des bras, pour activer au max tes muscles du dos.", "Prends ton temps avec une descente contrôlée vers la position de départ pour un meilleur développement musculaire.", "Évite de balancer le corps ou d’utiliser l’élan, ça diminue l’efficacité et augmente le risque de blessure.", "Garde toujours ton cou aligné avec ta colonne vertébrale, ne le relève pas. "]', '["Keep your core engaged throughout the movement to protect your lower back and maintain proper posture", "Focus on squeezing your shoulder blades together rather than just moving your arms to maximize back muscle activation", "Control the tempo with a slower eccentric phase when returning to starting position for better muscle development", "Avoid using momentum or swinging motions as this reduces effectiveness and increases injury risk", "Ensure your neck remains in neutral alignment with your spine rather than craning it upward"]', 'e27c74a9-69aa-4b0f-aa5f-1c675d5fe26e', 'reverse-grip-bent-over-rows', NULL, NULL);
INSERT INTO public.exercises VALUES ('ec8c0064-68c5-462a-9079-d18755eecc86', 'Curl inverse sur banc à prêcheur', NULL, NULL, 'Reverse Preacher Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 1, '/videos/biceps/reverse-preacher-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/reverse-preacher-curl.jpg', NULL, '["Assure-toi que tes avant-bras restent en contact avec le coussin pour plus de stabilité.", "Adopte un tempo contrôlé, surtout en phase de descente pour maximiser l''engagement musculaire.", "Commence avec un poids léger, cet exercice cible intensément les muscles des avant-bras.", "Garde une bonne alignement des poignets pour éviter les douleurs ou blessures.", "Concentre-toi sur la contraction à la fin du mouvement pour un maximum d''efficacité."]', '["Ne pas garder les avant-bras en contact avec le coussin.", "Utiliser un poids trop lourd, ce qui peut entraîner une mauvaise technique."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["forearms", "barbell", "reverse preacher curl"]', true, '2026-04-03 12:24:58.607842+00', '2026-04-03 12:24:58.607842+00', 'Prends position derrière le banc à prêcheur, une barre à la main. Contracte tes avant-bras en soulevant la barre, puis redescends lentement. C''est ça, on travaille les avant-bras !', '["Ne pas garder les avant-bras en contact avec le coussin.", "Utiliser un poids trop lourd, ce qui peut entraîner une mauvaise technique."]', true, '["Position yourself standing behind the preacher bench with your chest against the back pad", "Place your forearms flat on the angled pad with your wrists just over the edge", "Grip the barbell with an overhand grip, hands shoulder-width apart", "Keep your forearms pressed against the pad throughout the entire movement", "Curl the weight up by flexing your wrists and squeezing your forearms", "Lower the weight slowly and under control back to the starting position"]', '["Place-toi derrière le banc à prêcheur, la poitrine contre le dossier.", "Pose tes avant-bras à plat sur le coussin incliné, les poignets juste au bord.", "Prends la barre avec une prise en pronation, les mains écartées à la largeur des épaules.", "Garde tes avant-bras en contact avec le coussin durant tout le mouvement.", "Souleve la barre en fléchissant les poignets, serre bien les avant-bras.", "Abaisse la barre lentement et sous contrôle jusqu''à revenir à la position de départ."]', '["Assure-toi que tes avant-bras restent en contact avec le coussin pour plus de stabilité.", "Adopte un tempo contrôlé, surtout en phase de descente pour maximiser l''engagement musculaire.", "Commence avec un poids léger, cet exercice cible intensément les muscles des avant-bras.", "Garde une bonne alignement des poignets pour éviter les douleurs ou blessures.", "Concentre-toi sur la contraction à la fin du mouvement pour un maximum d''efficacité."]', '["Keep your forearms in constant contact with the preacher pad for stability", "Use a controlled tempo, especially on the lowering phase to maximize muscle engagement", "Start with lighter weight as this exercise intensely targets the smaller forearm muscles", "Maintain proper wrist alignment to avoid strain or injury", "Focus on the squeeze at the top of the movement for maximum contraction"]', '90a03a51-07e2-4acd-b893-d5c58a273587', 'reverse-preacher-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('e6c43ee0-b810-4fde-b645-bc2010ba4a90', 'Élévation Frontale avec Haltères', NULL, '', 'Dumbbell Front Raise', 'Shoulders', '[]', 'Shoulders', 'Beginner', 2, '/videos/shoulders/dumbbell-front-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-front-raise.jpg', NULL, '["Choisissez un poids qui vous permet de maintenir une bonne forme durant toutes les répétitions.", "Gardez les poignets droits et ne soulevez pas les haltères plus haut que le niveau des épaules pour éviter les douleurs.", "Concentrez-vous sur l''initiation du mouvement avec vos épaules, pas avec votre dos ou vos jambes.", "Maintenez la tension dans votre sangle abdominale pour protéger le bas du dos et améliorer la stabilité.", "Contrôlez la phase de descente pour maximiser l''engagement musculaire et prévenir les blessures."]', '["Ne pas engager les abdominaux, ce qui peut créer des tensions dans le bas du dos.", "Utiliser des poids trop lourds, entraînant des mouvements précipités et un risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "dumbbell front raise"]', true, '2026-04-03 12:24:56.46799+00', '2026-04-03 12:24:56.46799+00', 'Position de départ : Tenez un haltère dans chaque main, paumes tournées vers vous. Exécution : Levez un haltère devant vous jusqu''à la hauteur des épaules, en alternant à chaque répétition.', '["Ne pas engager les abdominaux, ce qui peut créer des tensions dans le bas du dos.", "Utiliser des poids trop lourds, entraînant des mouvements précipités et un risque de blessure."]', true, '["Stand with feet shoulder-width apart and maintain a slight bend in your knees throughout the movement", "Hold dumbbells with a neutral grip, arms straight but not locked, positioned in front of your thighs", "Engage your core and keep your back straight with shoulders pulled back", "Lift the weights forward and up in a smooth arc until your arms reach shoulder height", "Pause briefly at the top position, then slowly lower the dumbbells back to the starting position", "Keep the movement controlled and avoid using momentum or swinging the weights"]', '["Tenez-vous debout, pieds écartés à la largeur des épaules et genoux légèrement fléchis, tout au long du mouvement.", "Maintenez les haltères avec une prise neutre, bras tendus mais pas verrouillés, devant vos cuisses.", "Engagez votre sangle abdominale, gardez le dos droit et les épaules en arrière.", "Soulevez les poids vers l''avant en un arc fluide jusqu''à ce que vos bras atteignent la hauteur des épaules.", "Marquez une pause brève en haut du mouvement, puis abaissez lentement les haltères à la position de départ.", "Contrôlez le mouvement et évitez de vous servir de l''élan ou de balancer les poids."]', '["Choisissez un poids qui vous permet de maintenir une bonne forme durant toutes les répétitions.", "Gardez les poignets droits et ne soulevez pas les haltères plus haut que le niveau des épaules pour éviter les douleurs.", "Concentrez-vous sur l''initiation du mouvement avec vos épaules, pas avec votre dos ou vos jambes.", "Maintenez la tension dans votre sangle abdominale pour protéger le bas du dos et améliorer la stabilité.", "Contrôlez la phase de descente pour maximiser l''engagement musculaire et prévenir les blessures."]', '["Use a weight that allows you to maintain proper form throughout all repetitions", "Keep your wrists straight and avoid lifting the dumbbells higher than shoulder level to prevent shoulder impingement", "Focus on initiating the movement from your shoulders rather than using your back or legs for momentum", "Maintain tension in your core to protect your lower back and improve stability", "Control the eccentric (lowering) portion of the movement to maximize muscle engagement and prevent injury"]', '3e668a4f-2aac-42ae-b8db-58fc179d20d2', 'dumbbell-front-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('fbf5169b-2f82-45e8-bb54-af49643b6873', 'Pompes Cheval Balançant avec Saut Explosif', NULL, NULL, 'Rocking horse push up into explosive jump', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/rocking-horse-push-up-into-explosive-jump.mp4', NULL, NULL, NULL, '/videos/thumbnails/rocking-horse-push-up-into-explosive-jump.jpg', NULL, '["Maintiens tes abdos serrés pendant tout le mouvement pour protéger ton dos et garder une bonne forme", "Concentre-toi sur la partie explosive de la pompe pour générer suffisamment de puissance pour le saut", "Atterris doucement sur l''avant de tes pieds en sautant pour réduire l''impact sur les articulations", "Assure-toi que tes mains restent bien en place pendant le mouvement de balancement pour garder la stabilité", "Commence doucement puis augmente la vitesse et l''explosivité au fur et à mesure que tu maîtrises la technique."]', '["Ne pas engager les abdominaux, ce qui peut provoquer une courbure du dos", "Sauter sans contrôle, ce qui peut entraîner des blessures aux articulations"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "rocking horse push up into explosive jump"]', true, '2026-04-03 12:24:58.639033+00', '2026-04-03 12:24:58.639033+00', 'Position de départ : Place-toi en position classique de pompes, mains écartées légèrement plus larges que les épaules, corps en ligne droite de la tête aux talons. Exécution : Réalise une pompe tout en balançant ton poids d''avant en arrière, puis pousse explosivement vers le haut et saute en ramenant tes pieds vers tes mains avant de revenir à la position de départ.', '["Ne pas engager les abdominaux, ce qui peut provoquer une courbure du dos", "Sauter sans contrôle, ce qui peut entraîner des blessures aux articulations"]', true, '["Start in a strong plank position with core engaged and hands firmly planted on the ground", "Lower into a push-up while shifting your weight slightly forward and backward in a rocking motion", "At the bottom of the push-up, explosively press through your hands to lift your upper body", "As you push up, simultaneously jump both feet forward toward your hands in one fluid motion", "Step or jump your feet back to the starting push-up position", "Maintain control throughout the entire movement and reset your form before the next repetition"]', '["Commence en planche solide, les abdos engagés et les mains bien ancrées au sol", "Descends en pompe en déplaçant ton poids légèrement d''avant en arrière", "Au fond de la pompe, pousse fortement avec tes mains pour soulever ton torse", "En te relevant, saute en même temps avec les deux pieds vers tes mains dans un seul mouvement fluide", "Ramène ou saute tes pieds en arrière pour retrouver la position de pompe", "Garde le contrôle pendant tout le mouvement et rétablis ta position avant chaque répétition."]', '["Maintiens tes abdos serrés pendant tout le mouvement pour protéger ton dos et garder une bonne forme", "Concentre-toi sur la partie explosive de la pompe pour générer suffisamment de puissance pour le saut", "Atterris doucement sur l''avant de tes pieds en sautant pour réduire l''impact sur les articulations", "Assure-toi que tes mains restent bien en place pendant le mouvement de balancement pour garder la stabilité", "Commence doucement puis augmente la vitesse et l''explosivité au fur et à mesure que tu maîtrises la technique."]', '["Keep your core tight throughout the entire movement to protect your lower back and maintain proper form", "Focus on the explosive push-up portion to generate enough power for the jump transition", "Land softly on the balls of your feet when jumping forward to reduce impact on joints", "Ensure your hands remain firmly planted during the rocking motion to maintain stability", "Start with slower movements and build up speed and explosiveness as you master the technique"]', '73097e75-dc6b-4be4-bf4a-b3f176d8ff10', 'rocking-horse-push-up-into-explosive-jump', NULL, NULL);
INSERT INTO public.exercises VALUES ('3f155edc-29b0-420b-bb6b-cb530bc20868', 'Escaladeurs alternés', NULL, 'تسلقين بالتناوب', 'Switching mountain climbers', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/switching-mountain-climbers.mp4', NULL, NULL, NULL, '/videos/thumbnails/switching-mountain-climbers.jpg', NULL, '["Garde les hanches basses (ne fais pas de fouetté)", "Engage ton tronc à chaque mouvement", "Accélère pour un effet cardio maximum", "Ralentis pour plus de contrôle", "Exercice complet pour tout le corps"]', '["Lever les hanches trop haut", "Ne pas engager le tronc", "Effectuer un mouvement saccadé instead of fluide", "Oublier de respirer correctement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "switching mountain climbers"]', true, '2026-04-03 12:24:59.708597+00', '2026-04-03 12:24:59.708597+00', 'Renforce ton tronc avec cet exercice dynamique qui fait travailler tout le corps en un temps record ! Prépare-toi à transpirer et à te dépasser !', '["Lever les hanches trop haut", "Ne pas engager le tronc", "Effectuer un mouvement saccadé instead of fluide", "Oublier de respirer correctement"]', true, '["Start in push-up position", "Drive one knee toward chest", "Quickly switch legs", "Continue alternating at pace"]', '["Adopte la position de pompe", "Ramène un genou vers ta poitrine", "Change de jambe rapidement", "Alterne à un rythme soutenu"]', '["Garde les hanches basses (ne fais pas de fouetté)", "Engage ton tronc à chaque mouvement", "Accélère pour un effet cardio maximum", "Ralentis pour plus de contrôle", "Exercice complet pour tout le corps"]', '["Keep hips down (don''t pike)", "Core stays engaged", "Speed up for more cardio", "Slow down for more control", "Full body exercise"]', '8735c2a0-5c44-4a2d-ba45-932ba4d372cd', 'switching-mountain-climbers', NULL, NULL);
INSERT INTO public.exercises VALUES ('490de7e6-9aad-4086-ac5e-70798122d188', 'Crunch Abdominal', NULL, 'كرانش بطن', 'Run', 'Abs', '[]', 'Abs', 'Beginner', 16, NULL, NULL, NULL, NULL, NULL, NULL, '["Ne tire pas avec les bras", "Concentre-toi sur la contraction des abdos", "Évite de prendre trop lourd (risque de tension au cou)", "Effectue des mouvements contrôlés à chaque répétition", "Expire en te crispant"]', '["Tirer avec les bras au lieu d''utiliser les abdos", "Faire des mouvements trop rapides", "Ne pas contrôler le retour au départ", "Se pencher trop en arrière", "Choisir un poids trop lourd"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "run"]', true, '2026-04-03 12:24:58.656219+00', '2026-04-03 12:24:58.656219+00', 'Renforce ton cœur avec cet exercice de crunch ! Mobilise tes abdos pour sculpter ton ventre et améliorer ta stabilité.', '["Tirer avec les bras au lieu d''utiliser les abdos", "Faire des mouvements trop rapides", "Ne pas contrôler le retour au départ", "Se pencher trop en arrière", "Choisir un poids trop lourd"]', false, '["Sit in machine, select appropriate weight", "Grip handles, position pads against chest/shoulders", "Contract abs to crunch forward", "Squeeze at bottom", "Return slowly with control"]', '["Installe-toi sur la machine, choisis le poids approprié", "Prends les poignées, ajuste les coussinets contre ta poitrine/épaules", "Contracte tes abdominaux pour te crisper vers l''avant", "Sers bien à la fin du mouvement", "Reviens lentement à la position de départ en contrôlant ton mouvement"]', '["Ne tire pas avec les bras", "Concentre-toi sur la contraction des abdos", "Évite de prendre trop lourd (risque de tension au cou)", "Effectue des mouvements contrôlés à chaque répétition", "Expire en te crispant"]', '["Don''t pull with arms", "Focus on ab contraction", "Don''t go too heavy (neck strain risk)", "Controlled movement throughout", "Exhale as you crunch"]', '3ed1db96-1767-4ce2-a245-56b4a2967419', 'run', NULL, NULL);
INSERT INTO public.exercises VALUES ('b59cba8b-dd4e-4bb5-ad66-89679622a377', 'Coure sur place', NULL, NULL, 'Run in place', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/run-in-place.mp4', NULL, NULL, NULL, '/videos/thumbnails/run-in-place.jpg', NULL, '["Lève tes genoux au moins à la hauteur des hanches pour un maximum d''efficacité", "Atterris doucement sur l''avant de tes pieds et non sur les talons pour réduire l''impact sur les articulations", "Maintiens un rythme respiratoire régulier et évite de retenir ta respiration pendant l''exercice", "Engage tes abdos et évite de pencher trop en avant ou en arrière", "Commence à un rythme modéré et augmente progressivement l''intensité à mesure que ton endurance s''améliore"]', '["Ne pas lever les genoux suffisamment haut", "Atterrir sur les talons au lieu de l''avant du pied"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "run in place"]', true, '2026-04-03 12:24:58.662614+00', '2026-04-03 12:24:58.662614+00', 'Commence en te tenant droit, les pieds écartés à la largeur des hanches, les bras le long du corps et les abdos engagés. Lève alternativement les genoux tout en balançant les bras comme si tu courais, sans avancer.', '["Ne pas lever les genoux suffisamment haut", "Atterrir sur les talons au lieu de l''avant du pied"]', true, '["Stand tall with your feet hip-width apart and arms relaxed at your sides", "Begin by lifting your right knee up toward your chest while simultaneously swinging your left arm forward", "Lower your right foot back down while lifting your left knee up and swinging your right arm forward", "Continue alternating legs in a smooth, rhythmic motion while pumping your arms naturally", "Land softly on the balls of your feet with each step to minimize impact", "Maintain an upright posture throughout the movement with your core engaged"]', '["Tiens-toi droit avec les pieds écartés à la largeur des hanches et les bras détendus", "Lève ton genou droit vers ta poitrine tout en poussant ton bras gauche vers l''avant", "Ramène ton pied droit au sol et lève ton genou gauche tout en balançant ton bras droit vers l''avant", "Continue d''alterner les jambes dans un mouvement fluide et rythmique en balançant les bras naturellement", "Atterris doucement sur l''avant de tes pieds à chaque pas pour minimiser l''impact", "Garde une posture droite pendant tout l''exercice avec les abdos engagés"]', '["Lève tes genoux au moins à la hauteur des hanches pour un maximum d''efficacité", "Atterris doucement sur l''avant de tes pieds et non sur les talons pour réduire l''impact sur les articulations", "Maintiens un rythme respiratoire régulier et évite de retenir ta respiration pendant l''exercice", "Engage tes abdos et évite de pencher trop en avant ou en arrière", "Commence à un rythme modéré et augmente progressivement l''intensité à mesure que ton endurance s''améliore"]', '["Keep your knees lifting to at least hip height for maximum effectiveness", "Land softly on the balls of your feet rather than your heels to reduce joint impact", "Maintain a steady breathing pattern and avoid holding your breath during the exercise", "Keep your core engaged and avoid leaning too far forward or backward", "Start at a moderate pace and gradually increase intensity as your endurance improves"]', '4c257ac2-d310-40aa-8797-33d138519135', 'run-in-place', NULL, NULL);
INSERT INTO public.exercises VALUES ('44da783f-165e-4290-b189-8fd42b43d60b', 'Russian Twists avec battements de jambes', NULL, NULL, 'Russian twists with flutter kicks', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/russian-twists-with-flutter-kicks.mp4', NULL, NULL, NULL, '/videos/thumbnails/russian-twists-with-flutter-kicks.jpg', NULL, '["Mouvements petits et contrôlés", "Le bas du dos doit rester plaqué au sol", "Garde les jambes bien tendues", "Respire tout au long de l''exercice", "Cible particulièrement les abdominaux inférieurs"]', '["Laisser le bas du dos se décoller du sol", "Battements trop amples", "Manque de contrôle lors des mouvements", "Ne pas respirer correctement", "Fléchir les jambes pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "russian twists with flutter kicks"]', true, '2026-04-03 12:24:58.70471+00', '2026-04-03 12:24:58.70471+00', 'Renforce ton gainage et travaille tes abdominaux inférieurs avec cet exercice dynamique !', '["Laisser le bas du dos se décoller du sol", "Battements trop amples", "Manque de contrôle lors des mouvements", "Ne pas respirer correctement", "Fléchir les jambes pendant l''exercice"]', true, '["Lie on back, hands under hips", "Legs straight, slightly off floor", "Kick legs up and down alternately", "Keep lower back pressed to floor"]', '["Allonge-toi sur le dos, mains sous les hanches", "Garde les jambes tendues, légèrement surélevées", "Fais des battements alternés avec les jambes", "Maintiens le bas du dos bien collé au sol"]', '["Mouvements petits et contrôlés", "Le bas du dos doit rester plaqué au sol", "Garde les jambes bien tendues", "Respire tout au long de l''exercice", "Cible particulièrement les abdominaux inférieurs"]', '["Small controlled movements", "Lower back stays down", "Keep legs straight", "Breathe throughout", "Targets lower abs"]', 'ebb04889-8d61-4172-9c51-65ebe6c73c75', 'russian-twists-with-flutter-kicks', NULL, NULL);
INSERT INTO public.exercises VALUES ('4030bbe6-af13-4ef3-8f1b-bacef6ed8392', 'Sage Marichi I Pose (Droite)', NULL, NULL, 'Sage marichi I pose (right)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/sage-marichi-i-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/sage-marichi-i-pose-right.jpg', NULL, '["Garde le dos droit avant de te pencher en avant.", "Active bien la jambe étendue en flexant le pied.", "Évite de cambrer excessivement le dos."]', '["Ne pas plier le dos correctement.", "Laisser la jambe étendue se relâcher."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "sage marichi i pose (right)"]', true, '2026-04-03 12:24:58.725538+00', '2026-04-03 12:24:58.725538+00', 'Renforce tes ischio-jambiers tout en développant ta souplesse et ton équilibre.', '["Ne pas plier le dos correctement.", "Laisser la jambe étendue se relâcher."]', true, '["Sit with legs extended. Bend one knee and place the foot flat on the floor.", "Wrap the same-side arm around the bent knee and reach behind your back.", "Clasp hands behind your back or use a strap.", "Fold forward over the extended leg."]', '["Assieds-toi avec les jambes tendues devant toi.", "Plie un genou et pose le pied à plat sur le sol.", "Enveloppe le bras du même côté autour du genou plié et avance ton autre bras derrière ton dos.", "Attrape tes mains derrière le dos ou utilise une sangle.", "Penche-toi en avant en te dirigeant vers la jambe étendue."]', '["Garde le dos droit avant de te pencher en avant.", "Active bien la jambe étendue en flexant le pied.", "Évite de cambrer excessivement le dos."]', '["Sit tall before folding forward.", "Keep the extended leg active with the foot flexed.", "Do not round your spine excessively."]', '6d518c05-cac2-4215-b71d-0b564ced5900', 'sage-marichi-i-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('f01592ae-3495-4e4f-be6c-50439cebfa20', 'Pompes scapulaires', NULL, NULL, 'Scapula push ups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/scapula-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/scapula-push-ups.jpg', NULL, '["Gardez les bras verrouillés en extension - cet exercice cible la mobilité scapulaire, pas la force des bras", "L''amplitude de mouvement est petite, généralement seulement de 5 à 7 cm de déplacement vertical", "Maintenez l''alignement neutre de la colonne vertébrale pour protéger le bas du dos", "Concentrez-vous sur des mouvements lents et contrôlés plutôt que sur la vitesse pour maximiser l''engagement scapulaire", "Cet exercice est un excellent échauffement avant des mouvements de poussée plus intenses"]', '["Ne pas engager le tronc, ce qui mène à une mauvaise posture", "Fléchir les bras au lieu de garder les bras droits"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "scapula push ups"]', true, '2026-04-03 12:24:58.743556+00', '2026-04-03 12:24:58.743556+00', 'Position de départ : Adoptez la position de planche haute, mains à la largeur des épaules, bras tendus, corps formant une ligne droite de la tête aux talons. Exécution : Retirez et protractez vos omoplates tout en gardant vos bras droits, créant ainsi un petit mouvement de va-et-vient de votre torse.', '["Ne pas engager le tronc, ce qui mène à une mauvaise posture", "Fléchir les bras au lieu de garder les bras droits"]', true, '["Position yourself in a high plank with hands directly under shoulders and core engaged", "Keep your arms completely straight throughout the entire movement", "Squeeze your shoulder blades together to lower your chest slightly toward the floor", "Push your shoulder blades apart to press your upper back toward the ceiling", "Focus on the movement coming from your shoulder blades, not your arms", "Maintain a rigid body position without allowing hips to sag or pike up"]', '["Positionnez-vous en planche haute avec les mains sous les épaules et les abdominaux engagés", "Gardez les bras complètement droits durant tout le mouvement", "Serrez vos omoplates ensemble pour abaisser légèrement votre poitrine vers le sol", "Repoussez vos omoplates pour pousser votre haut du dos vers le plafond", "Concentrez-vous sur le mouvement venant de vos omoplates, pas de vos bras", "Maintenez une position rigide sans laisser vos hanches s''affaisser ou remonter"]', '["Gardez les bras verrouillés en extension - cet exercice cible la mobilité scapulaire, pas la force des bras", "L''amplitude de mouvement est petite, généralement seulement de 5 à 7 cm de déplacement vertical", "Maintenez l''alignement neutre de la colonne vertébrale pour protéger le bas du dos", "Concentrez-vous sur des mouvements lents et contrôlés plutôt que sur la vitesse pour maximiser l''engagement scapulaire", "Cet exercice est un excellent échauffement avant des mouvements de poussée plus intenses"]', '["Keep arms locked in extension - this exercise targets scapular mobility, not arm strength", "The range of motion is small, typically only 2-3 inches of vertical movement", "Maintain neutral spine alignment throughout the movement to protect your lower back", "Focus on slow, controlled movements rather than speed to maximize scapular engagement", "This exercise serves as an excellent warm-up before more intensive pushing movements"]', '16a76541-f17e-49fe-832c-27776a9ec2e3', 'scapula-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('9daeb532-8030-4c76-b6ea-d8c5f18a6c99', 'Tirage horizontal à la machine, prise neutre rapprochée', NULL, NULL, 'Seated Cable Row Close Neutral Grip', 'Back', '[]', 'Back', 'Beginner', 4, '/videos/back/seated-cable-row-close-neutral-grip.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-cable-row-close-neutral-grip.jpg', NULL, '["Garde le torse droit durant tout le mouvement pour éviter d''utiliser l''élan et garantir une activation correcte du dos", "Concentre-toi sur l''initiation du tirage avec tes omoplates plutôt qu''avec tes bras pour maximiser l''engagement des dorsaux et des rhomboïdes", "Maintiens une colonne vertébrale neutre et évite de courber le dos, surtout lors de la phase de retour", "Utilise un poids qui te permet de contrôler le mouvement totalement, sans laisser le poids te tirer vers l''avant"]', '["Élever les épaules en tirant", "Lâcher la tension sur les muscles entre les répétitions"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "seated cable row close neutral grip"]', true, '2026-04-03 12:24:58.767709+00', '2026-04-03 12:24:58.767709+00', 'Position de départ : Assieds-toi sur la machine de tirage à câble, en prenant une prise neutre rapprochée. Exécution : Tire la poignée vers ton abdomen en gardant le torse droit, puis retourne lentement à la position de départ.', '["Élever les épaules en tirant", "Lâcher la tension sur les muscles entre les répétitions"]', true, '["Adjust the cable machine to chest height and attach a close neutral grip handle", "Sit with your back straight, core engaged, and feet securely placed on the footrests", "Begin with arms extended, feeling a stretch in your lats while maintaining proper posture", "Pull the handle toward your lower chest by driving your elbows back and squeezing your shoulder blades", "Hold the contraction briefly at the peak of the movement", "Slowly return to the starting position with control, maintaining tension throughout the entire range of motion"]', '["Règle la machine à la hauteur de la poitrine et fixe une poignée à prise neutre rapprochée", "Assois-toi avec le dos droit, le cœur engagé, et les pieds bien placés sur les repose-pieds", "Commence avec les bras étendus, en ressentant un étirement dans tes dorsaux tout en maintenant une bonne posture", "Tire la poignée vers le bas de ta poitrine en ramenant les coudes vers l''arrière et en contractant tes omoplates", "Maintiens la contraction brièvement au sommet du mouvement", "Retourne lentement à la position de départ avec contrôle, tout en maintenant la tension sur toute l''amplitude du mouvement"]', '["Garde le torse droit durant tout le mouvement pour éviter d''utiliser l''élan et garantir une activation correcte du dos", "Concentre-toi sur l''initiation du tirage avec tes omoplates plutôt qu''avec tes bras pour maximiser l''engagement des dorsaux et des rhomboïdes", "Maintiens une colonne vertébrale neutre et évite de courber le dos, surtout lors de la phase de retour", "Utilise un poids qui te permet de contrôler le mouvement totalement, sans laisser le poids te tirer vers l''avant"]', '["Keep your torso upright throughout the movement to avoid using momentum and ensure proper back activation", "Focus on initiating the pull with your shoulder blades rather than your arms to maximize lat and rhomboid engagement", "Maintain a neutral spine position and avoid rounding your back, especially during the return phase", "Use a weight that allows you to control the movement completely rather than letting the weight pull you forward"]', '60fa33db-7a56-4a6d-88a5-22f98a252ae1', 'seated-cable-row-close-neutral-grip', NULL, NULL);
INSERT INTO public.exercises VALUES ('7c6538a9-8f95-4edf-913d-4b1593555af0', 'Curl assis avec haltères', NULL, NULL, 'Seated Dumbbell Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 2, '/videos/biceps/seated-dumbbell-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-dumbbell-curl.jpg', NULL, '["Garde le dos droit contre le banc pour éviter de balancer ou d''utiliser l''élan", "Ne laisse pas tes coudes s''éloigner de ton corps - assure-toi qu''ils restent fixes", "Contrôle bien la descente pour maximiser l''activation musculaire", "Choisis un poids qui te permet de garder une bonne forme sur toutes les répétitions", "N''essaie pas de balancer les poids ni d''utiliser tes épaules pour aider le mouvement"]', '["Ne pas garder le dos plaqué contre le banc", "Laisser les coudes s''éloigner du corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "seated dumbbell curl"]', true, '2026-04-03 12:24:58.798452+00', '2026-04-03 12:24:58.798452+00', 'Commence en t''installant sur un banc avec un bon soutien pour le dos. Prends un haltère dans chaque main, bras tendus sur les côtés et paumes vers l''avant. En avant !', '["Ne pas garder le dos plaqué contre le banc", "Laisser les coudes s''éloigner du corps"]', true, '["Sit upright on a bench with your back firmly supported and feet flat on the floor", "Hold a dumbbell in each hand with arms hanging at your sides and palms facing forward", "Keep your elbows close to your torso throughout the entire movement", "Curl the weights up by contracting your biceps until the dumbbells reach shoulder level", "Squeeze your biceps at the top of the movement for a brief pause", "Slowly lower the dumbbells back to the starting position with control"]', '["Assieds-toi bien droit sur le banc, le dos soutenu et les pieds à plat au sol", "Prends un haltère dans chaque main, bras le long du corps et paumes face à toi", "Maintiens tes coudes près de ton torse durant tout l''exercice", "Enroule les poids vers tes épaules en contractant tes biceps", "Squeeze bien tes biceps au sommet et fais une petite pause", "Redescends les haltères lentement vers la position de départ en contrôlant le mouvement"]', '["Garde le dos droit contre le banc pour éviter de balancer ou d''utiliser l''élan", "Ne laisse pas tes coudes s''éloigner de ton corps - assure-toi qu''ils restent fixes", "Contrôle bien la descente pour maximiser l''activation musculaire", "Choisis un poids qui te permet de garder une bonne forme sur toutes les répétitions", "N''essaie pas de balancer les poids ni d''utiliser tes épaules pour aider le mouvement"]', '["Maintain a straight back against the bench support to prevent swaying or using momentum", "Keep your elbows stationary at your sides - avoid letting them drift forward or backward", "Control the lowering phase of the movement to maximize muscle engagement", "Use a weight that allows you to maintain proper form throughout all repetitions", "Avoid swinging the weights or using your shoulders to assist the movement"]', 'f5aa2b23-405b-48a1-9538-302a41160cbd', 'seated-dumbbell-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('486e52ec-de34-4632-a168-ccdcd4154da2', 'Extension Triceps Assis avec Haltère', NULL, 'دفع ثلاثي  بوزن بسيط', 'Seated Dumbbell Triceps Extension', 'Triceps', '[]', 'Triceps', 'Intermediate', 2, '/videos/triceps/seated-dumbbell-triceps-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-dumbbell-triceps-extension.jpg', NULL, '["Garde tes coudes fixes et dirigés vers l''avant durant tout le mouvement pour bien cibler tes triceps.", "Utilise un tempo contrôlé, surtout lors de la phase de descente, pour maximiser l''engagement musculaire et éviter les blessures.", "Commence avec un poids léger pour maîtriser la forme car cet exercice peut solliciter l''épaule en position vulnérable au-dessus.", "Évite d''arquer ton dos de manière excessive en maintenant ton tronc engagé et en gardant ton dos droit.", "Si tu ressens une douleur à l''épaule, diminue l''amplitude du mouvement et privilégie un mouvement plus restreint."]', '["Laisser les coudes s''écarter durant le mouvement, ce qui diminue l''efficacité.", "Ne pas contrôler la descente du poids, ce qui augmente le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "dumbbell", "seated dumbbell triceps extension"]', true, '2026-04-03 12:24:58.813013+00', '2026-04-03 12:24:58.813013+00', 'Position de départ : Assieds-toi droit sur un banc ou une chaise, les pieds bien à plat sur le sol. Tiens un haltère avec les deux mains derrière ta tête, les coudes portés vers l''avant et les bras supérieurs verticaux. Execution : Étends tes avant-bras vers le haut en redressant tes coudes pour soulever l''haltère au-dessus de ta tête, puis abaisse-le lentement jusqu''à la position de départ derrière ta tête.', '["Laisser les coudes s''écarter durant le mouvement, ce qui diminue l''efficacité.", "Ne pas contrôler la descente du poids, ce qui augmente le risque de blessure."]', true, '["Sit with your back straight and core engaged, feet firmly planted on the floor", "Grip the dumbbell with both hands around the top weight plate or handle, keeping wrists neutral", "Position the dumbbell behind your head with elbows pointing forward and upper arms close to your ears", "Slowly extend your forearms upward until your arms are fully extended overhead", "Lower the weight back down with control until you feel a stretch in your triceps", "Repeat for desired repetitions while maintaining proper elbow position throughout"]', '["Assois-toi avec le dos droit et les abdominaux engagés, pieds bien ancrés au sol.", "Prends l''haltère en l''attrapant par la partie supérieure ou par la poignée, en gardant les poignets neutres.", "Place l''haltère derrière ta tête avec les coudes pointant vers l''avant et les bras supérieurs proches de tes oreilles.", "Élève lentement tes avant-bras jusqu''à ce que tes bras soient complètement étendus au-dessus de ta tête.", "Abaisse le poids de manière contrôlée jusqu''à ce que tu sentes un étirement dans tes triceps.", "Répète pour le nombre de répétitions souhaité tout en maintenant la bonne position des coudes."]', '["Garde tes coudes fixes et dirigés vers l''avant durant tout le mouvement pour bien cibler tes triceps.", "Utilise un tempo contrôlé, surtout lors de la phase de descente, pour maximiser l''engagement musculaire et éviter les blessures.", "Commence avec un poids léger pour maîtriser la forme car cet exercice peut solliciter l''épaule en position vulnérable au-dessus.", "Évite d''arquer ton dos de manière excessive en maintenant ton tronc engagé et en gardant ton dos droit.", "Si tu ressens une douleur à l''épaule, diminue l''amplitude du mouvement et privilégie un mouvement plus restreint."]', '["Keep your elbows stationary and pointing forward throughout the entire movement to properly isolate the triceps", "Use a controlled tempo, especially on the lowering phase, to maximize muscle engagement and prevent injury", "Start with lighter weight to master the form since this exercise places the shoulder in a vulnerable overhead position", "Avoid arching your back excessively by keeping your core tight and maintaining neutral spine alignment", "Stop the range of motion if you feel any shoulder discomfort and consider using a smaller range of motion"]', 'de5de9a5-08ca-462b-b704-eab3f48ab7b5', 'seated-dumbbell-triceps-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('a9c113e3-6852-49ec-bec2-8f38a52a5421', 'Tirage assis avec prise neutre', NULL, 'تيراج جالس بقبضة محايدة', 'Seated Neutral Grip Row Machine', 'Back', '[]', 'Back', 'Beginner', 8, '/videos/back/seated-neutral-grip-row-machine.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-neutral-grip-row-machine.jpg', NULL, '["Garde toujours ta poitrine contre le rembourrage pour maintenir un bon alignement de la colonne vertébrale", "Concentre-toi sur le travail de tes muscles du dos, pas de tes bras, en démarrant le mouvement avec la rétraction des omoplates", "Évite d''utiliser l''élan ou de rebondir au bas du mouvement pour prévenir les blessures et maximiser l''engagement musculaire", "Maintiens un rythme contrôlé : 2 secondes pour tirer et 3 secondes pour revenir afin de bien travailler la phase excentrique", "Garde tes épaules basses et en arrière pour éviter qu''elles ne basculent en avant et compromettent ta posture."]', '["Utiliser l''élan au lieu de la force musculaire", "Ne pas maintenir le dos droit pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "seated neutral grip row machine"]', true, '2026-04-03 12:24:58.919869+00', '2026-04-03 12:24:58.919869+00', 'Position de départ : Assieds-toi sur la machine à ramer avec une prise neutre, ajuste la hauteur du siège pour que les poignées soient au niveau de l''abdomen. Exécution : Tire les poignées vers ton abdomen en gardant le torse droit, puis retourne lentement à la position de départ.', '["Utiliser l''élan au lieu de la force musculaire", "Ne pas maintenir le dos droit pendant l''exercice"]', true, '["Adjust the chest pad height so it aligns with your mid-chest when seated", "Sit with your chest firmly against the pad and maintain a neutral spine throughout the movement", "Grasp the neutral grip handles with your arms fully extended and shoulders slightly stretched forward", "Initiate the pull by retracting your shoulder blades, then drive your elbows back toward your ribs", "Squeeze your shoulder blades together at the end of the movement and pause briefly", "Slowly return to the starting position, allowing your shoulders to stretch forward while maintaining control"]', '["Ajuste la hauteur du rembourrage de poitrine pour qu''il soit aligné avec le milieu de ta poitrine quand tu es assis", "Reste bien appuyé contre le rembourrage et garde une colonne vertébrale neutre pendant le mouvement", "Saisis les poignées neutres avec les bras complètement étendus et les épaules légèrement en avant", "Commence le tirage en rétractant les omoplates, puis pousse tes coudes vers tes côtes", "Squeeze tes omoplates ensemble à la fin du mouvement et marque une courte pause", "Retourne lentement à la position de départ, en laissant tes épaules s''étirer vers l''avant tout en gardant le contrôle."]', '["Garde toujours ta poitrine contre le rembourrage pour maintenir un bon alignement de la colonne vertébrale", "Concentre-toi sur le travail de tes muscles du dos, pas de tes bras, en démarrant le mouvement avec la rétraction des omoplates", "Évite d''utiliser l''élan ou de rebondir au bas du mouvement pour prévenir les blessures et maximiser l''engagement musculaire", "Maintiens un rythme contrôlé : 2 secondes pour tirer et 3 secondes pour revenir afin de bien travailler la phase excentrique", "Garde tes épaules basses et en arrière pour éviter qu''elles ne basculent en avant et compromettent ta posture."]', '["Keep your chest pressed against the pad throughout the entire movement to maintain proper spinal alignment", "Focus on pulling with your back muscles rather than your arms by initiating the movement with shoulder blade retraction", "Avoid using momentum or bouncing at the bottom of the movement to prevent injury and maximize muscle engagement", "Maintain a controlled tempo with a 2-second pull and 3-second return to emphasize the eccentric portion", "Keep your shoulders down and back to prevent them from rolling forward and compromising your posture"]', '7a9bc5bf-e817-4819-a41b-44a2aee5fb67', 'seated-neutral-grip-row-machine', NULL, NULL);
INSERT INTO public.exercises VALUES ('c11daf0c-951d-4cee-ba5f-ba1347a7b2f0', 'Curl des Jambes Assis', NULL, NULL, 'Seated Leg Curl', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 8, '/videos/hamstrings/seated-leg-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-leg-curl.jpg', NULL, '["Engage ton tronc et évite d''archer ton dos lors du mouvement.", "Concentre-toi sur une phase excentrique lente et contrôlée, d''une durée de 2 à 3 secondes pour un développement musculaire maximal.", "Évite d''utiliser l''élan ou de balancer ton torse pour t''aider.", "Assure-toi d''avoir une amplitude complète tout en t''arrêtant juste avant l''extension complète des genoux pour maintenir la tension musculaire.", "Expire pendant la phase de flexion et inspire durant le retour."]', '[]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "machine", "seated leg curl"]', true, '2026-04-03 12:24:58.894687+00', '2026-04-03 12:24:58.894687+00', 'Position de départ : Assieds-toi sur la machine à curl des jambes, jambes tendues et chevilles bien maintenues sous les coussinets. Exécution : Plie les genoux pour rapprocher les coussinets des fesses, puis redescends lentement à la position de départ.', '[]', true, '["Adjust the machine so your knees align with the pivot point and your back is fully supported against the pad", "Position the lower pad just above your ankles and secure the thigh pad snugly against your legs", "Grip the side handles and maintain an upright posture throughout the movement", "Curl your heels toward your glutes by contracting your hamstrings, avoiding any jerky movements", "Pause briefly when your knees reach approximately 90 degrees of flexion", "Slowly return to the starting position, maintaining tension in your hamstrings throughout the eccentric phase"]', '["Ajuste la machine pour que tes genoux soient alignés avec le point de pivot et que ton dos soit bien soutenu contre le coussinet.", "Place le coussinet inférieur juste au-dessus de tes chevilles et ajuste le coussinet de cuisse de manière à ce qu''il soit bien en place contre tes jambes.", "Tiens les poignées latérales et garde une posture droite pendant tout le mouvement.", "Plie tes talons vers tes fesses en contractant tes ischio-jambiers, sans mouvements brusques.", "Fais une pause briève quand tes genoux atteignent environ 90 degrés de flexion.", "Retourne lentement à la position de départ, en gardant la tension dans tes ischio-jambiers tout au long de la phase excentrique."]', '["Engage ton tronc et évite d''archer ton dos lors du mouvement.", "Concentre-toi sur une phase excentrique lente et contrôlée, d''une durée de 2 à 3 secondes pour un développement musculaire maximal.", "Évite d''utiliser l''élan ou de balancer ton torse pour t''aider.", "Assure-toi d''avoir une amplitude complète tout en t''arrêtant juste avant l''extension complète des genoux pour maintenir la tension musculaire.", "Expire pendant la phase de flexion et inspire durant le retour."]', '["Keep your core engaged and avoid arching your back during the movement", "Focus on a slow, controlled eccentric portion lasting 2-3 seconds for maximum muscle development", "Avoid using momentum or swinging your torso to assist the movement", "Ensure full range of motion while stopping just short of complete knee extension to maintain muscle tension", "Breathe out during the curling phase and breathe in during the return phase"]', 'a097abc2-16ac-413a-86e4-444a7ce1fa43', 'seated-leg-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('e0037e96-57e5-429f-899a-bc41d83e592f', 'Squat Sumo à la Smith Machine', NULL, 'ضغطة سمو فوق آلة سميث', 'Smith Machine Sumo Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 8, '/videos/quadriceps/smith-machine-sumo-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-sumo-squat.jpg', NULL, '["Garde tes genoux alignés avec tes orteils tout au long du mouvement pour éviter les blessures", "Maintiens une colonne vertébrale neutre en gardant le torse relevé et en évitant d''incliner excessivement vers l''avant", "Concentre-toi sur la poussée avec tes talons plutôt qu''avec les orteils pour activer au maximum les quadriceps et les fessiers", "Contrôle la descente et évite de rebondir au bas du mouvement", "Contracte ton abdomen durant tout l''exercice pour rester stable et protéger ton bas du dos"]', '["Ne pas garder les genoux alignés avec les orteils", "Incliner le torse trop en avant"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "smith machine sumo squat"]', true, '2026-04-03 12:24:59.386913+00', '2026-04-03 12:24:59.386913+00', 'Placement de départ : Positionne-toi sous la barre de la Smith machine, le barreau reposant sur le haut de ton dos, les pieds écartés plus que la largeur des épaules, les orteils légèrement tournés vers l''extérieur. Exécution : Abaisse ton corps en effectuant un squat profond tout en gardant le dos droit, puis pousse à nouveau pour revenir à la position de départ.', '["Ne pas garder les genoux alignés avec les orteils", "Incliner le torse trop en avant"]', true, '["Set the Smith machine bar at shoulder height and add appropriate weight plates", "Position yourself under the bar with feet in a wide sumo stance, toes pointed outward", "Unrack the bar by lifting slightly and rotating the hooks forward", "Lower your body by sitting back into your hips while keeping your chest up and knees tracking over your toes", "Descend until your thighs are parallel to the floor or as low as your mobility allows", "Drive through your heels and squeeze your glutes to return to the starting position"]', '["Ajuste la barre de la Smith machine à hauteur d''épaules et ajoute les disques de poids adéquats", "Place-toi sous la barre avec une posture de sumo, les orteils orientés vers l''extérieur", "Détache la barre en soulevant légèrement et en tournant les crochets vers l''avant", "Abaisse ton corps en déplaçant les hanches en arrière, le torse relevé et les genoux alignés avec les orteils", "Descends jusqu''à ce que tes cuisses soient parallèles au sol ou aussi bas que ta mobilité le permet", "Pousse avec tes talons et contracte tes fessiers pour revenir à la position de départ"]', '["Garde tes genoux alignés avec tes orteils tout au long du mouvement pour éviter les blessures", "Maintiens une colonne vertébrale neutre en gardant le torse relevé et en évitant d''incliner excessivement vers l''avant", "Concentre-toi sur la poussée avec tes talons plutôt qu''avec les orteils pour activer au maximum les quadriceps et les fessiers", "Contrôle la descente et évite de rebondir au bas du mouvement", "Contracte ton abdomen durant tout l''exercice pour rester stable et protéger ton bas du dos"]', '["Keep your knees aligned with your toes throughout the entire movement to prevent knee injury", "Maintain a neutral spine by keeping your chest up and avoiding excessive forward lean", "Focus on pushing through your heels rather than your toes to maximize quad and glute activation", "Control the descent and avoid bouncing at the bottom of the movement", "Engage your core throughout the exercise to maintain stability and protect your lower back"]', '252e37ea-e936-42a4-ba76-d7ce35e1baa6', 'smith-machine-sumo-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('dfadfadd-ae16-4545-bc18-41ff5a5a6a42', 'Curl à la poulie basse assis', NULL, NULL, 'Seated Low Cable Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 4, '/videos/biceps/seated-low-cable-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-low-cable-curl.jpg', NULL, '["Gardez les bras supérieurs contre vos côtés pour isoler les biceps et éviter l''implication des épaules", "Adoptez un tempo contrôlé avec une montée de 2 secondes et une descente de 3 secondes pour maximiser la tension musculaire", "Évitez de balancer ou d''utiliser l''élan ; gardez le torse stable et le tronc engagé", "Arrêtez juste avant l''extension complète des bras en bas pour maintenir une tension constante sur les biceps", "Choisissez un poids qui vous permet de réaliser toutes les répétitions avec une bonne forme tout en vous challengeant sur les 2-3 dernières répétitions."]', '["Balançage du corps au lieu de contrôler le mouvement", "Tension relâchée au bas du mouvement, perdant ainsi l''activation des biceps."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "cable", "seated low cable curl"]', true, '2026-04-03 12:24:58.90795+00', '2026-04-03 12:24:58.90795+00', 'Position de départ : Assieds-toi sur un banc face à une poulie basse avec une poignée fixée. Exécution : Fléchis les coudes pour amener la poignée vers les épaules, en gardant les coudes immobiles.', '["Balançage du corps au lieu de contrôler le mouvement", "Tension relâchée au bas du mouvement, perdant ainsi l''activation des biceps."]', true, '["Sit upright on a bench positioned about 2-3 feet from the low cable pulley with feet planted firmly on the floor", "Grasp the cable handle or bar with an underhand grip, hands shoulder-width apart", "Keep your upper arms stationary against your sides and maintain a straight back throughout the movement", "Curl the weight up by contracting your biceps until your forearms are vertical and you feel a strong contraction", "Slowly lower the weight back to the starting position with control, maintaining tension on the biceps", "Breathe out during the curl up and breathe in during the lowering phase"]', '["Asseyez-vous bien droit sur un banc à environ 60-90 cm de la poulie basse, les pieds bien ancrés au sol", "Saisissez la poignée avec une prise en supination, les mains écartées à la largeur des épaules", "Gardez les bras supérieurs collés à vos côtés et le dos droit tout au long du mouvement", "Contractez vos biceps pour soulever le poids jusqu''à ce que vos avant-bras soient verticaux et que vous ressentiez une forte contraction", "Abaissez lentement le poids vers la position de départ avec contrôle, en maintenant la tension sur les biceps", "Expirez en soulevant et inspirez en abaissant le poids."]', '["Gardez les bras supérieurs contre vos côtés pour isoler les biceps et éviter l''implication des épaules", "Adoptez un tempo contrôlé avec une montée de 2 secondes et une descente de 3 secondes pour maximiser la tension musculaire", "Évitez de balancer ou d''utiliser l''élan ; gardez le torse stable et le tronc engagé", "Arrêtez juste avant l''extension complète des bras en bas pour maintenir une tension constante sur les biceps", "Choisissez un poids qui vous permet de réaliser toutes les répétitions avec une bonne forme tout en vous challengeant sur les 2-3 dernières répétitions."]', '["Keep your upper arms pressed against your sides to isolate the biceps and prevent shoulder involvement", "Use a controlled tempo with a 2-second lift and 3-second lower to maximize muscle tension", "Avoid swinging or using momentum by keeping your torso stable and core engaged", "Stop just short of full arm extension at the bottom to maintain constant tension on the biceps", "Select a weight that allows you to complete all repetitions with proper form while feeling challenged on the last 2-3 reps"]', '9f3f94f9-275b-4c5c-bc97-0e5826023599', 'seated-low-cable-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('cbf0a5b1-9e10-4461-91d4-629242f555e0', 'Presse de Poitrine Assise', NULL, 'ضغط الصدر جالسا', 'Seated Machine Chest Press', 'Chest', '[]', 'Chest', 'Beginner', 8, '/videos/chest/seated-machine-chest-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-machine-chest-press.jpg', NULL, '["Garde tes poignets droits et alignés avec tes avant-bras pendant tout le mouvement", "Évite de presser trop vite ou d''utiliser l''élan pour prévenir les blessures et maximiser l''engagement musculaire", "Ne laisse pas les plaques de poids toucher entre les répétitions pour maintenir une tension constante sur les muscles pectoraux", "Concentre-toi sur la contraction des muscles pectoraux au sommet de la pression pour une activation maximale"]', '["Oublier d''engager le ventre, ce qui peut entraîner une mauvaise posture", "Verrouiller les coudes à la fin du mouvement, ce qui peut provoquer des blessures"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "machine", "seated machine chest press"]', true, '2026-04-03 12:24:58.91116+00', '2026-04-03 12:24:58.91116+00', 'Position de départ : Installe-toi sur la machine à presse de poitrine en réglant la hauteur du siège afin que les poignées soient à niveau de la poitrine. Execution : Pousse les poignées vers l''avant jusqu''à ce que tes bras soient complètement tendus, puis reviens lentement à la position de départ.', '["Oublier d''engager le ventre, ce qui peut entraîner une mauvaise posture", "Verrouiller les coudes à la fin du mouvement, ce qui peut provoquer des blessures"]', true, '["Adjust the seat height so the handles align with your mid-chest when seated", "Position your back flat against the backrest and plant your feet firmly on the floor", "Grip the handles with a firm, even grip using your palms", "Press the handles forward smoothly while exhaling, extending your arms fully without locking your elbows", "Return to the starting position slowly while inhaling, maintaining control throughout the movement", "Keep your core engaged and avoid arching your back during the entire exercise"]', '["Ajuste la hauteur du siège pour que les poignées soient alignées avec le milieu de ta poitrine en position assise", "Garde ton dos bien plaqué contre le dossier et tes pieds fermement ancrés au sol", "Saisis les poignées avec une prise ferme et régulière de tes paumes", "Pousse les poignées vers l''avant de manière fluide en expirant, en tendant tes bras sans verrouiller les coudes", "Reviens lentement à la position initiale en inhalant, en gardant le contrôle tout au long du mouvement", "Engage ton tronc et évite d''arquer le dos pendant tout l''exercice"]', '["Garde tes poignets droits et alignés avec tes avant-bras pendant tout le mouvement", "Évite de presser trop vite ou d''utiliser l''élan pour prévenir les blessures et maximiser l''engagement musculaire", "Ne laisse pas les plaques de poids toucher entre les répétitions pour maintenir une tension constante sur les muscles pectoraux", "Concentre-toi sur la contraction des muscles pectoraux au sommet de la pression pour une activation maximale"]', '["Keep your wrists straight and aligned with your forearms throughout the movement", "Avoid pressing too fast or using momentum to prevent injury and maximize muscle engagement", "Don''t allow the weight plates to touch between repetitions to maintain constant tension on the chest muscles", "Focus on squeezing your chest muscles at the peak of the press for maximum activation"]', '3e96fcc6-7397-4387-ac5b-92569bd670e5', 'seated-machine-chest-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('7e79507a-fceb-4131-8051-974c74ea5e20', 'Plank genoux au coude', NULL, NULL, 'Elbow to knee plank', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/elbow-to-knee-plank.mp4', NULL, NULL, NULL, '/videos/thumbnails/elbow-to-knee-plank.jpg', NULL, '["Garde tes hanches au niveau et évite de faire pivoter ton torse pendant le mouvement genou-coude", "Reste en position de planche robuste et ne laisse pas tes hanches s''affaisser ou se lever", "Privilégie des mouvements contrôlés plutôt que la vitesse pour maximiser l''engagement de ton core", "Maintiens ta jambe d''appui droite et engagée pendant le mouvement", "Respire régulièrement et évite de retenir ta respiration durant l''exercice"]', '["Laisser les hanches s''affaisser", "Ne pas engager suffisamment le core"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "elbow to knee plank"]', true, '2026-04-03 12:24:56.659845+00', '2026-04-03 12:24:56.659845+00', 'Commence en position de planche sur les avant-bras, avec les coudes directement sous les épaules et le corps en ligne droite de la tête aux talons. Alterne en amenant chaque genou vers le même coude tout en maintenant la position de planche.', '["Laisser les hanches s''affaisser", "Ne pas engager suffisamment le core"]', true, '["Start in a forearm plank with elbows under shoulders and body in a straight line", "Engage your core and maintain neutral spine alignment", "Bring your right knee toward your right elbow in a controlled motion", "Return your right leg to starting position maintaining stability", "Alternate by bringing your left knee toward your left elbow", "Continue alternating sides while keeping your core engaged throughout"]', '["Positionne-toi en planche sur avant-bras, coudes sous les épaules et corps droit", "Engage ton core et garde une colonne vertébrale neutre", "Amène ton genou droit vers ton coude droit de manière contrôlée", "Ramène ton genou droit à la position de départ tout en maintenant ta stabilité", "Alterne avec le genou gauche et ramène-le vers le coude gauche", "Continue d''alterner les côtés tout en gardant ton core engagé tout au long de l''exercice"]', '["Garde tes hanches au niveau et évite de faire pivoter ton torse pendant le mouvement genou-coude", "Reste en position de planche robuste et ne laisse pas tes hanches s''affaisser ou se lever", "Privilégie des mouvements contrôlés plutôt que la vitesse pour maximiser l''engagement de ton core", "Maintiens ta jambe d''appui droite et engagée pendant le mouvement", "Respire régulièrement et évite de retenir ta respiration durant l''exercice"]', '["Keep your hips level and avoid rotating your torso during the knee-to-elbow movement", "Maintain a strong plank position throughout - don''t let your hips sag or pike up", "Focus on controlled movements rather than speed to maximize core engagement", "Keep your supporting leg straight and engaged while performing the knee drive", "Breathe steadily and avoid holding your breath during the exercise"]', 'f2224eab-4368-4bab-80a3-e0bddbed5a23', 'elbow-to-knee-plank', NULL, NULL);
INSERT INTO public.exercises VALUES ('b79afb28-a7bd-496b-a110-ef12f97ac0a1', 'Squeeze des Épaules Assis', NULL, NULL, 'Seated Shoulder Squeeze', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/seated-shoulder-squeeze.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-shoulder-squeeze.jpg', NULL, '["Garde la poitrine bien haute et évite de cambrer le bas du dos pendant la contraction.", "Concentre-toi sur l''initiation du mouvement avec les omoplates plutôt qu''uniquement avec les bras.", "Respire régulièrement tout au long de l''exercice, ne retiens pas ta respiration.", "Garde les épaules basses et éloignées des oreilles pour prévenir la tension au cou.", "Si tu es débutant, commence par des contractions courtes avec moins de répétitions."]', '["Négliger la posture, ce qui peut entraîner des douleurs au dos.", "Tirer les coudes trop vers le haut au lieu de les ramener vers l''arrière."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "seated shoulder squeeze"]', true, '2026-04-03 12:24:58.932291+00', '2026-04-03 12:24:58.932291+00', 'Prends place sur une chaise solide, le dos droit et les pieds bien ancrés au sol. Serre les omoplates en tirant les coudes vers l''arrière, puis relâche doucement. C''est un excellent exercice pour renforcer le haut du corps et améliorer ta posture.', '["Négliger la posture, ce qui peut entraîner des douleurs au dos.", "Tirer les coudes trop vers le haut au lieu de les ramener vers l''arrière."]', true, '["Sit upright in a sturdy chair with your back straight and feet planted firmly on the floor", "Position your arms at your sides with elbows bent at 90 degrees and palms facing forward", "Initiate the movement by pulling your shoulder blades together and drawing your elbows backward", "Hold the squeeze for 2-3 seconds while maintaining proper posture", "Slowly return your arms to the starting position with control", "Repeat the movement in a smooth, controlled manner without rushing"]', '["Assieds-toi bien droit sur une chaise solide, le dos bien droit et les pieds à plat sur le sol.", "Positionne tes bras le long du corps avec les coudes fléchis à 90 degrés et les paumes tournées vers l''avant.", "Commence le mouvement en rassemblant tes omoplates et en tirant tes coudes vers l''arrière.", "Maintiens la contraction pendant 2 à 3 secondes tout en gardant une bonne posture.", "Ramène lentement tes bras à la position de départ avec contrôle.", "Répète le mouvement de manière fluide et contrôlée sans te précipiter."]', '["Garde la poitrine bien haute et évite de cambrer le bas du dos pendant la contraction.", "Concentre-toi sur l''initiation du mouvement avec les omoplates plutôt qu''uniquement avec les bras.", "Respire régulièrement tout au long de l''exercice, ne retiens pas ta respiration.", "Garde les épaules basses et éloignées des oreilles pour prévenir la tension au cou.", "Si tu es débutant, commence par des contractions courtes avec moins de répétitions."]', '["Keep your chest up and avoid arching your lower back excessively during the squeeze", "Focus on initiating the movement from your shoulder blades rather than just moving your arms", "Maintain steady breathing throughout the exercise and avoid holding your breath", "Keep your shoulders down and away from your ears to prevent neck tension", "Start with shorter holds and fewer repetitions if you''re new to the exercise"]', '8540be69-f287-4af1-918b-01968b7a48a8', 'seated-shoulder-squeeze', NULL, NULL);
INSERT INTO public.exercises VALUES ('20a318ee-35fa-4740-a1b9-cfa6c82acb41', 'Planche genou au coude', NULL, NULL, 'Plank elbow to knee', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-elbow-to-knee.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-elbow-to-knee.jpg', NULL, '["Maintiens une colonne vertébrale neutre et évite de laisser tes hanches s''affaisser ou remonter", "Garde tes épaules stables, directement au-dessus de tes poignets", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement du core", "Respire régulièrement et évite de retenir ta respiration pendant le mouvement", "Stoppe si tu ressens une tension dans le bas du dos et vérifie ta forme"]', '["Ne pas garder le corps en ligne droite", "Laisser les hanches s''affaisser ou remonter"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank elbow to knee"]', true, '2026-04-03 12:24:58.279199+00', '2026-04-03 12:24:58.279199+00', 'Position de départ : Mets-toi en position de planche, les mains bien ancrées au sol, le corps formant une ligne droite de la tête aux talons. Exécution : Amène un genou vers le coude correspondant tout en maintenant la position de planche, puis reviens à la position de départ et répète de l''autre côté.', '["Ne pas garder le corps en ligne droite", "Laisser les hanches s''affaisser ou remonter"]', true, '["Start in a high plank position with hands directly under shoulders and body forming a straight line", "Keep your core engaged and hips level throughout the movement", "Draw one knee forward toward the same-side elbow in a controlled motion", "Return the leg back to plank position without letting the foot touch the ground", "Alternate legs and maintain steady breathing throughout the exercise", "Keep your weight evenly distributed between your hands and supporting leg"]', '["Commence en position de planche haute, les mains directement sous les épaules et le corps en ligne droite", "Engage ton core et garde les hanches à niveau pendant tout le mouvement", "Tire un genou vers le coude du même côté de manière contrôlée", "Ramène la jambe en position de planche sans toucher le sol avec le pied", "Alterne les jambes tout en maintenant une respiration régulière durant l''exercice", "Répartis ton poids uniformément entre les mains et la jambe d''appui"]', '["Maintiens une colonne vertébrale neutre et évite de laisser tes hanches s''affaisser ou remonter", "Garde tes épaules stables, directement au-dessus de tes poignets", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement du core", "Respire régulièrement et évite de retenir ta respiration pendant le mouvement", "Stoppe si tu ressens une tension dans le bas du dos et vérifie ta forme"]', '["Maintain a neutral spine and avoid letting your hips sag or pike up", "Keep your shoulders stable and directly over your wrists", "Focus on controlled movements rather than speed to maximize core engagement", "Breathe steadily and avoid holding your breath during the movement", "Stop if you feel strain in your lower back and check your form"]', '2640441e-fc3e-46e7-87ee-77f25ed81d32', 'plank-elbow-to-knee', NULL, NULL);
INSERT INTO public.exercises VALUES ('31c4229c-66b3-48ad-8f68-838b48858db5', 'Inclinaison latérale droite', NULL, NULL, 'Side bend (right)', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/side-bend-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-bend-right.jpg', NULL, '["Réalise le mouvement lentement et de manière contrôlée pour éviter de forcer sur la colonne.", "Maintiens une bonne posture, garde tes épaules carrées sans te pencher en avant.", "Concentre-toi sur l''étirement sur le côté gauche de ton torse et tes obliques.", "Respire régulièrement durant l''exercice, ne retiens pas ta respiration.", "Arrête immédiatement si tu ressens une douleur aiguë au dos ou sur les côtés."]', '["Se pencher trop rapidement, ce qui peut entraîner des blessures", "Tourner le torse au lieu de le fléchir latéralement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side bend (right)"]', true, '2026-04-03 12:24:58.995919+00', '2026-04-03 12:24:58.995919+00', 'Position de départ : Tiens-toi droit avec les pieds écartés à la largeur des hanches, les bras le long du corps ou une main sur la hanche. Exécution : Penche lentement ton torse sur le côté droit en fléchissant la taille, puis reviens à la position de départ de manière contrôlée.', '["Se pencher trop rapidement, ce qui peut entraîner des blessures", "Tourner le torse au lieu de le fléchir latéralement"]', true, '["Stand with feet hip-width apart and engage your core muscles", "Place your left hand on your hip or let it hang naturally at your side", "Slowly bend your torso to the right side, sliding your right hand down your leg", "Keep your back straight and avoid twisting or rotating your spine", "Hold the stretch briefly at the bottom of the movement", "Return to the starting position using your core muscles to pull yourself back up"]', '["Tiens-toi debout, pieds écartés à la largeur des hanches et engage tes muscles du core.", "Place ta main gauche sur ta hanche ou laisse-la pendre naturellement à tes côtés.", "Incline lentement ton torse vers la droite, en glissant ta main droite le long de ta jambe.", "Garde le dos droit et évite de tordre ou de faire pivoter ta colonne vertébrale.", "Fais une pause brève en bas du mouvement.", "Reviens à la position de départ en utilisant tes muscles du core pour te redresser."]', '["Réalise le mouvement lentement et de manière contrôlée pour éviter de forcer sur la colonne.", "Maintiens une bonne posture, garde tes épaules carrées sans te pencher en avant.", "Concentre-toi sur l''étirement sur le côté gauche de ton torse et tes obliques.", "Respire régulièrement durant l''exercice, ne retiens pas ta respiration.", "Arrête immédiatement si tu ressens une douleur aiguë au dos ou sur les côtés."]', '["Keep the movement slow and controlled to avoid straining the spine", "Maintain proper posture by keeping your shoulders square and avoiding forward lean", "Focus on feeling the stretch along the left side of your torso and obliques", "Breathe steadily throughout the movement and avoid holding your breath", "Stop immediately if you feel any sharp pain in your back or sides"]', '63f5e230-17a6-40df-a2a6-f296bd816501', 'side-bend-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('28e39bb9-b3fc-484e-b296-90c56b3cb60e', 'Toucher les orteils en position Bear Plank', NULL, NULL, 'Bear plank toe taps', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/bear-plank-toe-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-plank-toe-taps.jpg', NULL, '["Maintiens les genoux à la même hauteur tout au long du mouvement", "Garde ton ventre bien contracté pour éviter que le bas du dos ne s''affaisse ou que les hanches ne se soulèvent", "Déplace-toi avec contrôle, pas à pas, pour stimuler l''engagement du tronc et la stabilité", "Regarde vers le bas pour conserver un bon alignement de la colonne vertébrale", "Respire normalement pendant le mouvement, ne retiens pas ta respiration"]', '["Laisser les hanches se soulever ou se baisser trop bas", "Ne pas garder le dos droit pendant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "bear plank toe taps"]', true, '2026-04-03 12:24:55.686604+00', '2026-04-03 12:24:55.686604+00', 'Position de départ : Mets-toi en position de Bear Plank, les mains sous les épaules, les genoux fléchis à 90 degrés, flottant à 1-2 pouces du sol, le dos bien droit. Exécution : Alterne en soulevant un pied pour tapoter le sol devant, tout en maintenant l''autre genou en l''air, puis reviens à la position de départ et répète de l''autre côté.', '["Laisser les hanches se soulever ou se baisser trop bas", "Ne pas garder le dos droit pendant le mouvement"]', true, '["Start in a tabletop position with hands under shoulders and knees under hips", "Lift knees 2-3 inches off the ground while keeping core engaged and back straight", "Engage your core and maintain neutral spine alignment throughout the movement", "Lift your right foot and tap it out to the right side, keeping the knee low", "Return right foot to starting position and immediately repeat with left foot to the left side", "Continue alternating toe taps while maintaining the bear plank position"]', '["Commence en position de table, mains sous les épaules, genoux sous les hanches", "Lève les genoux de 5-8 cm du sol tout en gardant le ventre engagé et le dos droit", "Engage ton abdomen et maintiens une bonne posture du dos pendant tout le mouvement", "Soulève ton pied droit et tapote sur le côté droit, en gardant le genou bas", "Ramène le pied droit à la position de départ et répète immédiatement avec le pied gauche vers la gauche", "Poursuis avec des tapotements alternés tout en conservant la position de Bear Plank"]', '["Maintiens les genoux à la même hauteur tout au long du mouvement", "Garde ton ventre bien contracté pour éviter que le bas du dos ne s''affaisse ou que les hanches ne se soulèvent", "Déplace-toi avec contrôle, pas à pas, pour stimuler l''engagement du tronc et la stabilité", "Regarde vers le bas pour conserver un bon alignement de la colonne vertébrale", "Respire normalement pendant le mouvement, ne retiens pas ta respiration"]', '["Keep knees hovering consistently at the same height throughout the entire movement", "Maintain a strong core contraction to prevent lower back sagging or hip hiking", "Move with control rather than speed to maximize core engagement and stability", "Keep your head in neutral position looking down at the floor to maintain proper spine alignment", "Breathe steadily throughout the movement and avoid holding your breath"]', 'c794e5f9-f603-4f1a-a108-1989ff2b8215', 'bear-plank-toe-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('0f108228-b5d2-40d2-9c0f-58b5e5326846', 'Posture du demi-seigneur des poissons (droite)', NULL, NULL, 'Half lord of the fishes pose (right)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/half-lord-of-the-fishes-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-lord-of-the-fishes-pose-right.jpg', NULL, '["Reste droit avant de te tourner — allonge d''abord ta colonne vertébrale.", "Effectue la torsion depuis le milieu du dos, pas uniquement avec les épaules.", "Garde les deux os du bassin bien ancrés au sol."]', '["Ne pas garder le dos droit pendant la torsion.", "Oublier de renforcer le contact entre le coude et le genou pour un meilleur soutien."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "half lord of the fishes pose (right)"]', true, '2026-04-03 12:24:56.955035+00', '2026-04-03 12:24:56.955035+00', 'Position de départ : Assieds-toi sur le sol, jambes étendues devant toi, dos droit et épaules détendues. Exécution : Plie ton genou droit et croise ton pied droit au-dessus de ta jambe gauche, en le plaçant à plat au sol à côté de ton genou gauche, puis tourne ton torse vers la droite tout en gardant ta jambe gauche droite, en utilisant ton coude gauche contre ton genou droit pour te soutenir.', '["Ne pas garder le dos droit pendant la torsion.", "Oublier de renforcer le contact entre le coude et le genou pour un meilleur soutien."]', true, '["Sit with legs extended. Bend one knee and place the foot outside the opposite thigh.", "Bend the bottom leg and bring the foot near the opposite hip.", "Twist your torso toward the bent knee.", "Use the opposite elbow against the outside of the bent knee for leverage."]', '["Assieds-toi avec les jambes étendues. Plie un genou et place le pied à l''extérieur de la cuisse opposée.", "Plie la jambe inférieure et rapproche le pied de la hanche opposée.", "Torsionne ton torse vers le genou plié.", "Utilise l''autre coude contre l''extérieur du genou plié pour gagner en stabilité."]', '["Reste droit avant de te tourner — allonge d''abord ta colonne vertébrale.", "Effectue la torsion depuis le milieu du dos, pas uniquement avec les épaules.", "Garde les deux os du bassin bien ancrés au sol."]', '["Sit tall before you twist — lengthen your spine first.", "Twist from your mid-back, not just your shoulders.", "Keep both sit bones grounded."]', '58178205-37e9-489c-8322-f40b15d7b992', 'half-lord-of-the-fishes-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('33849307-fab7-4724-872e-59f002e6d597', 'Élévation latérale avec haltères', NULL, NULL, 'Side Lateral Raise with Dumbbells', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/side-lateral-raise-with-dumbbells.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-lateral-raise-with-dumbbells.jpg', NULL, '["Évite d''utiliser l''élan ou de balancer les poids - concentre-toi sur un mouvement contrôlé en utilisant uniquement tes muscles d''épaule", "Garde les épaules basses et en arrière pour prévenir les hausses d''épaules et réduire le risque d''impingement", "Commence avec des poids légers pour maîtriser la forme avant de passer à des haltères plus lourds", "Arrête le mouvement vers le haut à la hauteur des épaules pour éviter de soumettre l''articulation de l''épaule à un stress excessif", "Incline légèrement le torse en avant pour mieux cibler les deltoïdes latéraux"]', '["Utiliser trop de poids et sacrifier la forme", "Ne pas contrôler la descente des haltères"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "side lateral raise with dumbbells"]', true, '2026-04-03 12:24:59.053257+00', '2026-04-03 12:24:59.053257+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des hanches, un haltère dans chaque main, les bras légèrement fléchis et les paumes vers ton corps. Exécution : Élève les haltères sur les côtés jusqu''à ce que tes bras soient parallèles au sol, puis redescends-les lentement à la position de départ.', '["Utiliser trop de poids et sacrifier la forme", "Ne pas contrôler la descente des haltères"]', true, '["Stand with feet hip-width apart and hold a dumbbell in each hand at your sides with a slight bend in your elbows", "Keep your core engaged and maintain a neutral spine throughout the movement", "Lift the dumbbells out to your sides, leading with your elbows rather than your hands", "Raise the weights until your arms are parallel to the floor, forming a T-shape with your body", "Pause briefly at the top of the movement, then slowly lower the dumbbells back to the starting position with control", "Maintain the slight bend in your elbows throughout the entire range of motion"]', '["Tiens-toi avec les pieds écartés à la largeur des hanches et un haltère dans chaque main sur les côtés, les coudes légèrement fléchis", "Garde ton ventre engagé et maintiens une colonne vertébrale neutre tout au long du mouvement", "Lève les haltères sur les côtés, en menant avec les coudes plutôt qu''avec les mains", "Élève les poids jusqu''à ce que tes bras soient parallèles au sol, formant un ''T'' avec ton corps", "Fais une pause brève en haut du mouvement, puis redescends lentement les haltères à la position de départ avec contrôle", "Maintiens la légère flexion des coudes durant toute l''amplitude du mouvement"]', '["Évite d''utiliser l''élan ou de balancer les poids - concentre-toi sur un mouvement contrôlé en utilisant uniquement tes muscles d''épaule", "Garde les épaules basses et en arrière pour prévenir les hausses d''épaules et réduire le risque d''impingement", "Commence avec des poids légers pour maîtriser la forme avant de passer à des haltères plus lourds", "Arrête le mouvement vers le haut à la hauteur des épaules pour éviter de soumettre l''articulation de l''épaule à un stress excessif", "Incline légèrement le torse en avant pour mieux cibler les deltoïdes latéraux"]', '["Avoid using momentum or swinging the weights - focus on controlled movement using only your shoulder muscles", "Keep your shoulders down and back to prevent shrugging and reduce risk of impingement", "Start with lighter weights to master the form before progressing to heavier dumbbells", "Stop the upward motion at shoulder height to avoid placing excessive stress on the shoulder joint", "Maintain a slight forward lean of the torso to better target the lateral deltoids"]', '7384d39b-613f-4c8e-a980-42e2d3bd8a83', 'side-lateral-raise-with-dumbbells', NULL, NULL);
INSERT INTO public.exercises VALUES ('1d259b74-023a-43a5-b364-5c19a082404f', 'Sauts latéraux suivi de grimpeurs de montagne', NULL, NULL, 'Side hurdel jumps to mountain climbers', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-hurdel-jumps-to-mountain-climbers-061b3246.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-hurdel-jumps-to-mountain-climbers-061b3246.jpg', NULL, '["Maintenez une solide position de planche durant tout l''exercice pour protéger votre bas du dos", "Atterrissez doucement sur la plante des pieds lors des sauts latéraux pour réduire l''impact sur vos articulations", "Garder les abdos serrés et éviter de laisser les hanches s''affaisser ou se soulever durant les transitions", "Contrôlez le rythme des montées de genoux pour maintenir une bonne forme plutôt que de vous précipiter", "Assurez-vous d''avoir suffisamment d''espace autour de vous avant de commencer, car cet exercice nécessite des mouvements latéraux"]', '["Ne pas stabiliser le corps en position de planche pendant l''exercice", "Sauter trop haut ou trop vite et perdre le contrôle sur les mouvements"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side hurdel jumps to mountain climbers"]', true, '2026-04-03 12:24:59.009325+00', '2026-04-03 12:24:59.009325+00', 'Position de départ : Adoptez la position de planche haute avec les mains bien ancrées au sol, les épaules directement au-dessus des poignets et le corps formant une ligne droite de la tête aux talons. Exécution : Réalisez des sauts latéraux en amenant les deux pieds d''un côté, puis sautez de l''autre côté. Ensuite, alternez avec des montées de genoux en position de planche.', '["Ne pas stabiliser le corps en position de planche pendant l''exercice", "Sauter trop haut ou trop vite et perdre le contrôle sur les mouvements"]', true, '["Start in a high plank position with core engaged and shoulders stable over your wrists", "Jump both feet laterally to the right side, landing outside your right hand with knees bent", "Immediately jump both feet to the left side, landing outside your left hand", "Return to center plank position and perform 4-6 alternating mountain climber knee drives", "Keep hips level throughout the lateral jumps and avoid excessive bouncing", "Complete the desired number of repetitions maintaining proper form throughout"]', '["Commencez en position de planche haute, les abdos engagés et les épaules stables au-dessus des poignets", "Sautez les deux pieds vers la droite, atterrissant à l''extérieur de votre main droite avec les genoux fléchis", "Sautez immédiatement vers la gauche, atterrissant à l''extérieur de votre main gauche", "Retournez à la position de planche centrale et effectuez 4 à 6 montées de genoux alternées", "Gardez vos hanches nivelées pendant les sauts latéraux et évitez de rebondir excessivement", "Réalisez le nombre de répétitions désiré en maintenant une bonne forme tout au long de l''exercice"]', '["Maintenez une solide position de planche durant tout l''exercice pour protéger votre bas du dos", "Atterrissez doucement sur la plante des pieds lors des sauts latéraux pour réduire l''impact sur vos articulations", "Garder les abdos serrés et éviter de laisser les hanches s''affaisser ou se soulever durant les transitions", "Contrôlez le rythme des montées de genoux pour maintenir une bonne forme plutôt que de vous précipiter", "Assurez-vous d''avoir suffisamment d''espace autour de vous avant de commencer, car cet exercice nécessite des mouvements latéraux"]', '["Maintain a strong plank position throughout the entire exercise to protect your lower back", "Land softly on the balls of your feet during lateral jumps to reduce impact on joints", "Keep your core tight and avoid letting hips sag or pike up during transitions", "Control the mountain climber tempo to maintain proper form rather than rushing through the movement", "Ensure adequate space around you before beginning as this exercise requires lateral movement"]', '061b3246-322a-41ed-a589-73fb9478651c', 'side-hurdel-jumps-to-mountain-climbers-061b3246', NULL, NULL);
INSERT INTO public.exercises VALUES ('719bd5a3-af76-4a9c-aa7c-1e2beb21f4af', 'Pompes latérales', NULL, 'بوشات جانبية', 'Side to side push up', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/side-to-side-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-to-side-push-up.jpg', NULL, '["Garde ton ventre serré et tes hanches à niveau pour éviter de cambrer le dos ou de creuser le ventre pendant le mouvement", "Concentre le déplacement de poids sur tes bras et épaules, ne tord pas ton torse", "Commence avec un petit mouvement latéral et augmente progressivement à mesure que tu gagnes en force", "Assure-toi que tes mains restent bien à plat sur le sol pour maintenir la stabilité de tes poignets", "Contrôle le rythme aussi bien à la descente qu''à la remontée pour maximiser l''engagement musculaire"]', '["Ne pas maintenir le corps en ligne droite, ce qui peut entraîner des blessures", "Oublier de garder le ventre engagé, ce qui affaiblit la posture"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "side to side push up"]', true, '2026-04-03 12:24:59.141729+00', '2026-04-03 12:24:59.141729+00', 'Mets-toi en position de pompe classique, les mains écartées au-delà des épaules, ton corps doit former une ligne droite de la tête aux talons. Descends ton torse vers une main en déplaçant ton poids sur ce côté, puis pousse pour revenir au centre et fais de même de l''autre côté.', '["Ne pas maintenir le corps en ligne droite, ce qui peut entraîner des blessures", "Oublier de garder le ventre engagé, ce qui affaiblit la posture"]', true, '["Position hands wider than shoulder-width apart in a plank position with core engaged", "Lower your body toward your right hand while shifting weight to the right side", "Push back up to the starting center position with control", "Lower your body toward your left hand while shifting weight to the left side", "Return to center and continue alternating sides for the desired number of repetitions", "Maintain proper plank form throughout the entire movement"]', '["Positionne tes mains plus larges que les épaules en planche, engage ton cœur", "Descends ton corps vers ta main droite en déplaçant ton poids à droite", "Pousse pour revenir au centre avec contrôle", "Descends ton corps vers ta main gauche en déplaçant ton poids à gauche", "Reviens au centre et continue d''alterner les côtés pour le nombre de répétitions souhaité", "Garde une bonne posture de planche tout au long du mouvement"]', '["Garde ton ventre serré et tes hanches à niveau pour éviter de cambrer le dos ou de creuser le ventre pendant le mouvement", "Concentre le déplacement de poids sur tes bras et épaules, ne tord pas ton torse", "Commence avec un petit mouvement latéral et augmente progressivement à mesure que tu gagnes en force", "Assure-toi que tes mains restent bien à plat sur le sol pour maintenir la stabilité de tes poignets", "Contrôle le rythme aussi bien à la descente qu''à la remontée pour maximiser l''engagement musculaire"]', '["Keep your core tight and hips level to prevent sagging or piking during the lateral movement", "Focus the weight shift through your arms and shoulders rather than twisting your torso", "Start with a smaller range of motion and gradually increase the lateral distance as you build strength", "Ensure both hands remain flat on the ground throughout the movement to maintain wrist stability", "Control the tempo on both the lowering and pushing phases to maximize muscle engagement"]', '2c525222-75e1-4c05-b8ee-f4d2c7d1799e', 'side-to-side-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('8a0f2279-0a36-46ec-8ea8-cf24bd57d9cc', 'Marche latérale en planche', NULL, 'مشية جانبية في وضعية البلانك', 'Side to side plank walk', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-to-side-plank-walk.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-to-side-plank-walk.jpg', NULL, '["Garde les abdominaux contractés et évite que tes hanches ne s''affaissent ou ne se soulèvent pendant le mouvement", "Déplace-toi avec contrôle plutôt qu''avec rapidité pour maintenir une bonne forme et stabilité", "Assure-toi que tes mains sont bien sous tes épaules en position de planche", "Évite de croiser les mains ou les pieds pendant les pas latéraux", "Respire régulièrement tout au long de l''exercice, ne retiens pas ta respiration"]', '["Ne pas maintenir le corps en ligne droite", "S''agiter trop rapidement et perdre la forme"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side to side plank walk"]', true, '2026-04-03 12:24:59.10853+00', '2026-04-03 12:24:59.10853+00', 'Position de départ : Place-toi en position de planche, les mains sur le tapis, le corps en ligne droite de la tête aux talons. Execution : Écarte une main du tapis suivie du pied correspondant, puis fais de même avec l''autre main et pied pour te déplacer latéralement tout en conservant la position de planche.', '["Ne pas maintenir le corps en ligne droite", "S''agiter trop rapidement et perdre la forme"]', true, '["Start in a strong plank position with hands shoulder-width apart on the mat and feet hip-width apart", "Step your right hand off the mat to the right, followed immediately by your right foot", "Bring your left hand and left foot toward the center to return to plank position", "Continue stepping laterally in the same direction for the desired number of steps", "Reverse the movement to return to your starting position", "Maintain a straight line from head to heels throughout the entire movement"]', '["Commence en position de planche solide, les mains à la largeur des épaules sur le tapis et les pieds à la largeur des hanches", "Déplace ta main droite à droite, suivie immédiatement de ton pied droit", "Ramène ta main gauche et ton pied gauche vers le centre pour revenir en position de planche", "Continue à avancer latéralement dans la même direction pour le nombre de pas souhaité", "Inverse le mouvement pour revenir à ta position de départ", "Garde une ligne droite de la tête aux talons tout au long de l''exercice"]', '["Garde les abdominaux contractés et évite que tes hanches ne s''affaissent ou ne se soulèvent pendant le mouvement", "Déplace-toi avec contrôle plutôt qu''avec rapidité pour maintenir une bonne forme et stabilité", "Assure-toi que tes mains sont bien sous tes épaules en position de planche", "Évite de croiser les mains ou les pieds pendant les pas latéraux", "Respire régulièrement tout au long de l''exercice, ne retiens pas ta respiration"]', '["Keep your core engaged and avoid letting your hips sag or pike up during the movement", "Move with control rather than speed to maintain proper form and stability", "Keep your hands directly under your shoulders when in the plank position", "Avoid crossing your hands or feet over each other during the lateral steps", "Breathe steadily throughout the exercise and don''t hold your breath"]', 'c811aaa0-7aa9-41c3-89f1-647feb729069', 'side-to-side-plank-walk', NULL, NULL);
INSERT INTO public.exercises VALUES ('f80fb39a-c85c-4849-ad0d-c76d2d85562e', 'Crunch Oblique', NULL, NULL, 'Oblique Crunches', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/oblique-crunches.mp4', NULL, NULL, NULL, '/videos/thumbnails/oblique-crunches.jpg', NULL, '["Garde le bas de ton dos bien collé au sol pendant l''exercice pour protéger ta colonne vertébrale", "Concentre-toi sur la rotation de ton torse, pas seulement sur le mouvement de tes bras", "N''essaie pas de tirer sur ton cou avec tes mains, laisse tes abdominaux travailler", "Expire en te contractant et inspire en redescendant pour un bon rythme respiratoire", "Exécute le mouvement lentement et avec contrôle pour maximiser l''engagement musculaire et éviter les blessures"]', '["Ne pas garder le bas du dos au sol", "Tirer sur le cou au lieu d''utiliser les muscles abdominaux"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "oblique crunches"]', true, '2026-04-03 12:24:57.98155+00', '2026-04-03 12:24:57.98155+00', 'Allonge-toi sur le dos, genoux pliés et pieds bien ancrés au sol. Place tes mains derrière la tête ou croise-les sur ta poitrine. Prépare-toi à travailler ton gainage !', '["Ne pas garder le bas du dos au sol", "Tirer sur le cou au lieu d''utiliser les muscles abdominaux"]', true, '["Lie on your back with knees bent at 90 degrees and feet flat on the floor", "Place hands lightly behind your head without interlacing fingers, or cross arms over your chest", "Engage your core and lift your shoulder blades slightly off the ground", "Crunch up and rotate to one side, bringing your right elbow toward your left knee", "Lower back down to the starting position with control", "Complete all repetitions on one side before switching to the other side"]', '["Allonge-toi sur le dos, genoux à 90 degrés et pieds à plat sur le sol", "Mets tes mains derrière ta tête sans entrelacer les doigts ou croise-les sur ta poitrine", "Active ton ventre et soulève légèrement tes omoplates du sol", "Crunch en tournant sur un côté, amène ton coude droit vers ton genou gauche", "Redescends doucement à la position de départ", "Fais toutes les répétitions d''un côté avant de passer à l''autre côté"]', '["Garde le bas de ton dos bien collé au sol pendant l''exercice pour protéger ta colonne vertébrale", "Concentre-toi sur la rotation de ton torse, pas seulement sur le mouvement de tes bras", "N''essaie pas de tirer sur ton cou avec tes mains, laisse tes abdominaux travailler", "Expire en te contractant et inspire en redescendant pour un bon rythme respiratoire", "Exécute le mouvement lentement et avec contrôle pour maximiser l''engagement musculaire et éviter les blessures"]', '["Keep your lower back pressed against the floor throughout the movement to protect your spine", "Focus on rotating through your torso rather than just moving your arms", "Avoid pulling on your neck with your hands - let your core muscles do the work", "Exhale as you crunch up and inhale as you lower down to maintain proper breathing", "Move slowly and controlled to maximize muscle engagement and prevent injury"]', '85d78505-04b8-4cf6-b277-c215eeb462a7', 'oblique-crunches', NULL, NULL);
INSERT INTO public.exercises VALUES ('a5029df4-f5f4-4a3d-8a6a-10d9f42fb6c6', 'Tirage Unilatéral au Poulie Haute', NULL, NULL, 'Single Arm Lat Pulldown', 'Back', '[]', 'Back', 'Intermediate', 4, '/videos/back/single-arm-lat-pulldown.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-lat-pulldown.jpg', NULL, '["Garde le torse droit et évite de trop te pencher sur un côté pendant le mouvement", "Concentre-toi sur le tirage avec ton muscle dorsal plutôt que de laisser tes biceps ou ta main dominer le mouvement", "Maintiens une tension constante sur le câble et évite que le poids ne vienne s''écraser entre les répétitions", "Utilise ta main non active pour te maintenir légèrement sur la machine si besoin", "Contrôle la phase excentrique du mouvement pour maximiser l''engagement musculaire et prévenir les blessures."]', '["Biaisser le torse en tirant", "Laisser le poids retomber sans contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "single arm lat pulldown"]', true, '2026-04-03 12:24:59.187993+00', '2026-04-03 12:24:59.187993+00', 'Position de départ : Face à une poulie haute avec la poignée dans une main. Execution : Tire la poignée vers le côté de ta poitrine en gardant ton coude près du corps, puis retourne lentement à la position initiale.', '["Biaisser le torse en tirant", "Laisser le poids retomber sans contrôle"]', true, '["Adjust the knee pad to secure your legs and prevent your body from lifting during the movement", "Grasp the handle with one hand using an overhand grip, keeping your arm fully extended overhead", "Engage your core and maintain a straight spine throughout the entire exercise", "Pull the handle down in a smooth arc toward your side, focusing on squeezing your shoulder blade down and back", "Hold the contracted position briefly, then slowly return the handle to the starting position with control", "Complete all repetitions on one side before switching to the other arm"]', '["Ajuste le coussin des genoux pour sécuriser tes jambes et éviter que ton corps ne se soulève pendant le mouvement", "Prends la poignée avec une main en prise pronation, bras tendu au-dessus de ta tête", "Sers bien ton ventre et garde un dos droit durant tout l''exercice", "Tire la poignée vers le bas en arc vers ton côté, concentre-toi sur la contraction de ton omoplate vers le bas et vers l''arrière", "Maintiens la position contractée brièvement, puis retourne lentement la poignée à la position de départ avec contrôle", "Termine toutes les répétitions d''un côté avant de changer de bras."]', '["Garde le torse droit et évite de trop te pencher sur un côté pendant le mouvement", "Concentre-toi sur le tirage avec ton muscle dorsal plutôt que de laisser tes biceps ou ta main dominer le mouvement", "Maintiens une tension constante sur le câble et évite que le poids ne vienne s''écraser entre les répétitions", "Utilise ta main non active pour te maintenir légèrement sur la machine si besoin", "Contrôle la phase excentrique du mouvement pour maximiser l''engagement musculaire et prévenir les blessures."]', '["Keep your torso upright and avoid leaning excessively to one side during the movement", "Focus on pulling with your lat muscle rather than using your bicep or hand to dominate the movement", "Maintain constant tension on the cable and avoid letting the weight stack slam between repetitions", "Use your non-working hand to lightly hold onto the machine for stability if needed", "Control the eccentric portion of the movement to maximize muscle engagement and prevent injury"]', 'fc11f2e5-3fcd-4682-bb4b-10c33951335a', 'single-arm-lat-pulldown', NULL, NULL);
INSERT INTO public.exercises VALUES ('172cfe28-ac88-4ec8-8988-894a48acbb4f', 'Planche latérale avec genoux repliés', NULL, NULL, 'Knee tucked Side plank up and downs (right', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/knee-tucked-side-plank-up-and-downs-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/knee-tucked-side-plank-up-and-downs-right.jpg', NULL, '["Gardez votre coude sous l''épaule pour éviter les tensions et maintenir un bon alignement.", "Cette variante avec les genoux pliés rend l''exercice plus accessible tout en ciblant efficacement les obliques.", "Concentrez-vous sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement du core.", "Maintenez votre core bien contracté sur toute l''amplitude de mouvement pour protéger votre bas du dos.", "Assurez-vous que vos hanches se déplacent de haut en bas sans rouler vers l''avant ou l''arrière."]', '["Ne pas garder le coude sous l''épaule peut entraîner une blessure.", "Descendre trop rapidement sans contrôle peut nuire à l''engagement du core."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "knee tucked side plank up and downs (right"]', true, '2026-04-03 12:24:57.50349+00', '2026-04-03 12:24:57.50349+00', 'Boostez votre force au niveau du core avec cet exercice de planche latérale. Positionnez-vous correctement et engagez-vous !', '["Ne pas garder le coude sous l''épaule peut entraîner une blessure.", "Descendre trop rapidement sans contrôle peut nuire à l''engagement du core."]', true, '["Lie on your right side with your right forearm planted firmly on the mat, elbow positioned directly under your shoulder", "Bend both knees and keep them in contact with the mat for stability throughout the exercise", "Engage your core and lift your hips up into a side plank position while keeping your knees bent", "Slowly lower your hips down to touch the mat while maintaining control", "Press back up to the starting side plank position by engaging your obliques and core muscles", "Maintain the knee-bent position throughout all repetitions for consistent support"]', '["Allongez-vous sur le côté droit avec votre avant-bras droit ancré au sol, le coude juste en dessous de l''épaule.", "Pliez les deux genoux et maintenez-les au contact du sol pour plus de stabilité.", "Activez votre core et soulevez vos hanches en position de planche latérale tout en gardant les genoux pliés.", "Descendez lentement vos hanches vers le sol en contrôlant le mouvement.", "Repoussez-vous vers la position de planche latérale en contractant vos obliques et vos muscles du core.", "Gardez la position des genoux pliés pendant toutes les répétitions pour un soutien constant."]', '["Gardez votre coude sous l''épaule pour éviter les tensions et maintenir un bon alignement.", "Cette variante avec les genoux pliés rend l''exercice plus accessible tout en ciblant efficacement les obliques.", "Concentrez-vous sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement du core.", "Maintenez votre core bien contracté sur toute l''amplitude de mouvement pour protéger votre bas du dos.", "Assurez-vous que vos hanches se déplacent de haut en bas sans rouler vers l''avant ou l''arrière."]', '["Keep your supporting elbow directly under your shoulder to prevent strain and maintain proper alignment", "The bent-knee modification makes this exercise more accessible while still effectively targeting the obliques", "Focus on controlled movement rather than speed to maximize core engagement", "Keep your core tight throughout the entire range of motion to protect your lower back", "Ensure your hips move in a straight up and down pattern rather than rolling forward or backward"]', 'c9d2b9a8-7f3e-4b5f-9012-e8c17b80de07', 'knee-tucked-side-plank-up-and-downs-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('191b5bf7-5a75-4c97-bde1-629935e5e5e2', 'Curl Scott avec un bras', NULL, 'Curl Scott d''un bras', 'Single Arm Preacher Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/single-arm-preacher-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-preacher-curl.jpg', NULL, '["Garde ton poignet droit et aligné avec ton avant-bras pendant le mouvement.", "Évite de verrouiller complètement ton coude en bas pour prévenir le stress articulaire.", "Contrôle la descente pour maximiser l''engagement musculaire et éviter les blessures.", "Maintiens ton gainage actif et ne te laisse pas entraîner dans un mouvement de balancement. "]', '["Ne pas avoir une prise stable sur l''haltère.", "Trop utiliser l''élan pour soulever le poids."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "single arm preacher curl"]', true, '2026-04-03 12:24:59.211646+00', '2026-04-03 12:24:59.211646+00', 'Position de départ : Assieds-toi sur un banc Scott avec un haltère dans une main, en laissant ton bras reposer sur le coussin. Exécution : Plie le coude pour soulever l''haltère vers ton épaule, puis redescends lentement.', '["Ne pas avoir une prise stable sur l''haltère.", "Trop utiliser l''élan pour soulever le poids."]', true, '["Sit at a preacher bench with your chest pressed against the angled pad and feet flat on the floor", "Hold a dumbbell in one hand with an underhand grip, extending your arm over the pad with a slight bend in your elbow", "Keep your working arm''s armpit at the top edge of the pad and your shoulder pulled back", "Slowly curl the dumbbell up by contracting your bicep until your forearm is nearly vertical", "Lower the weight in a controlled manner back to the starting position with a slight bend in your elbow", "Complete all repetitions on one arm before switching to the other side"]', '["Assieds-toi sur un banc Scott, poitrine contre le coussin incliné, pieds à plat au sol.", "Tiens un haltère dans une main avec une prise en supination, bras tendu au-dessus du coussin avec un léger angle au coude.", "Garde l''aisselle de ton bras actif contre le haut du coussin et tire ton épaule en arrière.", "Fais un curl lentement en contractant ton biceps jusqu''à ce que ton avant-bras soit presque vertical.", "Descends le poids de manière contrôlée jusqu''à la position de départ avec une légère flexion au coude.", "Termine toutes les répétitions d''un bras avant de passer à l''autre. "]', '["Garde ton poignet droit et aligné avec ton avant-bras pendant le mouvement.", "Évite de verrouiller complètement ton coude en bas pour prévenir le stress articulaire.", "Contrôle la descente pour maximiser l''engagement musculaire et éviter les blessures.", "Maintiens ton gainage actif et ne te laisse pas entraîner dans un mouvement de balancement. "]', '["Keep your wrist straight and in line with your forearm throughout the movement", "Avoid letting your elbow fully lock out at the bottom to prevent joint stress", "Control the negative portion of the lift to maximize muscle engagement and prevent injury", "Keep your core engaged and avoid using momentum or swinging the weight"]', '0fed480a-62f6-44d9-a457-787ebcd1395f', 'single-arm-preacher-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('0967db2a-a062-4a55-b99b-12df11032c0b', 'Tirage T-Bar à un bras', NULL, NULL, 'Single Arm T-Bar Row', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/single-arm-t-bar-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-t-bar-row.jpg', NULL, '["Garde ton gainage actif et ton dos neutre durant tout le mouvement pour protéger ta bas du dos", "Concentre-toi sur le tirage avec tes muscles du dos et non avec ton bras, commence le mouvement avec ton omoplate", "Utilise une amplitude complète, laisse le poids étirer ton dorsal en bas et tire jusqu''à ce que ton coude soit derrière ton torse", "Évite d''utiliser l''élan ou de balancer le poids, maintiens des mouvements lisses et contrôlés", "Garde ton bras non actif libre pour l''équilibre ou place-le sur ta cuisse pour plus de stabilité"]', '["Ne pas maintenir une bonne posture du dos pendant l''exercice.", "Utiliser trop de poids, ce qui peut compromettre la technique."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "single arm t-bar row"]', true, '2026-04-03 12:24:59.229704+00', '2026-04-03 12:24:59.229704+00', 'Position de départ : Place-toi devant une barre T avec une prise à une main. Exécution : Tire la barre vers le côté de ta poitrine en gardant le dos droit, puis redescends lentement à la position de départ. Fais-le ensuite avec l''autre bras.', '["Ne pas maintenir une bonne posture du dos pendant l''exercice.", "Utiliser trop de poids, ce qui peut compromettre la technique."]', true, '["Secure one end of the barbell in a corner or landmine attachment and load the opposite end with appropriate weight", "Stand with feet shoulder-width apart, straddling the barbell, and hinge forward at the hips while maintaining a neutral spine", "Grasp the barbell with one hand using an overhand grip, keeping your arm extended and the weight hanging freely", "Pull the weight up by driving your elbow back and squeezing your shoulder blade toward your spine", "Slowly lower the weight back to the starting position with control, maintaining tension throughout the movement", "Complete all repetitions on one side before switching to the opposite arm"]', '["Fixe une extrémité de la barre dans un coin ou avec une attache landmine et charge l''autre extrémité avec un poids approprié", "Positionne tes pieds à la largeur des épaules, straddling la barre, et penche-toi en avant en gardant le dos neutre", "Saisis la barre avec une main en prise pronation, bras étendu et poids suspendu librement", "Tire le poids vers le haut en poussant ton coude vers l''arrière et en serrant ton omoplate vers ta colonne vertébrale", "Redescends lentement le poids à la position de départ en contrôlant le mouvement, en gardant la tension tout au long", "Effectue toutes les répétitions d''un côté avant de passer à l''autre bras."]', '["Garde ton gainage actif et ton dos neutre durant tout le mouvement pour protéger ta bas du dos", "Concentre-toi sur le tirage avec tes muscles du dos et non avec ton bras, commence le mouvement avec ton omoplate", "Utilise une amplitude complète, laisse le poids étirer ton dorsal en bas et tire jusqu''à ce que ton coude soit derrière ton torse", "Évite d''utiliser l''élan ou de balancer le poids, maintiens des mouvements lisses et contrôlés", "Garde ton bras non actif libre pour l''équilibre ou place-le sur ta cuisse pour plus de stabilité"]', '["Keep your core engaged and maintain a neutral spine throughout the entire movement to protect your lower back", "Focus on pulling with your back muscles rather than your arm by initiating the movement with your shoulder blade", "Use a full range of motion by allowing the weight to stretch your lat at the bottom and pulling until your elbow is behind your torso", "Avoid using momentum or swinging the weight, instead maintaining smooth and controlled movement patterns", "Keep your non-working arm free for balance or place it on your thigh for additional stability"]', '63ca895d-601f-4155-b654-1682690d7f1c', 'single-arm-t-bar-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('02dac52d-b0f6-4593-831a-642461e352dd', 'Sit-ups : Renforce ton core !', NULL, 'الجلوس : قوة قلبك!', 'Sit ups', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/sit-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/sit-ups.jpg', NULL, '["Garde le cou dans une position neutre et évite de tirer sur ta tête pour ne pas te blesser", "Concentre-toi sur tes abdos pour initier le mouvement, pas sur l''élan ou les fléchisseurs de hanches", "Adopte un rythme lent et contrôlé : 2-3 secondes pour monter et 2-3 secondes pour descendre", "Garde les pieds bien à plat au sol pour maintenir ta stabilité et la bonne forme", "Il n''est pas nécessaire de se relever complètement, soulève uniquement les épaules pour travailler efficacement ton core."]', '["Tirer sur la tête au lieu de se concentrer sur les abdos", "Percer trop haut : soulever uniquement les épaules, pas plus"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "sit ups"]', true, '2026-04-03 12:24:59.239645+00', '2026-04-03 12:24:59.239645+00', 'Allonge-toi sur le dos, genoux pliés à 90 degrés, pieds bien à plat sur le sol, mains derrière la tête ou croisées sur la poitrine. C''est parti ! Utilise tes abdos pour soulever tes épaules, amène ton torse vers tes genoux, puis redescends doucement en contrôlant le mouvement.', '["Tirer sur la tête au lieu de se concentrer sur les abdos", "Percer trop haut : soulever uniquement les épaules, pas plus"]', true, '["Lie flat on your back with knees bent and feet planted firmly on the floor hip-width apart", "Place your hands lightly behind your head without interlacing fingers, or cross arms over your chest", "Engage your core muscles and press your lower back into the floor", "Slowly curl your upper body forward, lifting your shoulder blades off the ground while keeping your neck neutral", "Hold briefly at the top position, then slowly lower back down until your shoulder blades touch the floor", "Maintain controlled breathing throughout the movement, exhaling on the way up and inhaling on the way down"]', '["Allonge-toi sur le dos, genoux pliés et pieds ancrés au sol, largeur des hanches", "Pose tes mains derrière la tête sans entrelacer les doigts, ou croise-les sur ta poitrine", "Contracte tes abdominaux et presse ton bas du dos contre le sol", "Curle lentement ton haut du corps vers l''avant, soulève tes épaules tout en gardant le cou neutre", "Maintiens brièvement la position haute, puis redescends lentement jusqu''à ce que tes épaules touchent le sol", "Reste attentif à ta respiration, expire en montant et inspire en redescendant"]', '["Garde le cou dans une position neutre et évite de tirer sur ta tête pour ne pas te blesser", "Concentre-toi sur tes abdos pour initier le mouvement, pas sur l''élan ou les fléchisseurs de hanches", "Adopte un rythme lent et contrôlé : 2-3 secondes pour monter et 2-3 secondes pour descendre", "Garde les pieds bien à plat au sol pour maintenir ta stabilité et la bonne forme", "Il n''est pas nécessaire de se relever complètement, soulève uniquement les épaules pour travailler efficacement ton core."]', '["Keep your neck in a neutral position and avoid pulling on your head with your hands to prevent neck strain", "Focus on using your abdominal muscles to initiate the movement rather than momentum or hip flexors", "Maintain a slow and controlled tempo, taking 2-3 seconds to lift up and 2-3 seconds to lower down", "Keep your feet flat on the floor throughout the entire movement to maintain stability and proper form", "Only lift your shoulder blades off the ground - you don''t need to sit all the way up to effectively work your core muscles"]', '65ea17e1-f8ce-465a-ae0c-481bddb4714a', 'sit-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('506586e5-1a89-4fa0-8ea7-21aac18408ab', 'Twists Russes', NULL, 'تويست روسي', 'Russian twists', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/russian-twists.mp4', NULL, NULL, NULL, '/videos/thumbnails/russian-twists.jpg', NULL, '["Garde ton core engagé pendant toute la durée de l''exercice pour protéger ton bas du dos.", "Maintiens une colonne vertébrale droite, évite d''arrondir tes épaules vers l''avant.", "Concentre-toi sur la rotation de ton torse plutôt que sur le mouvement de tes bras.", "Maîtrise le mouvement, évite d''utiliser l''élan pour balancer de gauche à droite.", "Garde tes pieds surélevés pendant l''exercice pour maintenir une tension constante dans ton core."]', '["Ne pas engager le core, ce qui peut entraîner des douleurs dorsales.", "Arrondir le dos au lieu de garder une posture droite."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "russian twists"]', true, '2026-04-03 12:24:58.687307+00', '2026-04-03 12:24:58.687307+00', 'Renforce ton core avec cet exercice dynamique qui stimule tes abdominaux durant chaque rotation !', '["Ne pas engager le core, ce qui peut entraîner des douleurs dorsales.", "Arrondir le dos au lieu de garder une posture droite."]', true, '["Sit on the floor with knees bent and feet flat on the ground", "Lean back slightly to engage your core while keeping your back straight", "Lift your feet off the ground so your shins are parallel to the floor", "Clasp your hands together and rotate your torso to the right, bringing your hands toward the floor beside your hip", "Return to center then rotate to the left side, bringing your hands toward the floor beside your left hip", "Continue alternating sides in a controlled manner"]', '["Assieds-toi par terre, genoux fléchis et pieds à plat au sol.", "Incline-toi légèrement en arrière pour activer ton core tout en gardant le dos droit.", "Lève tes pieds du sol pour que tes tibias soient parallèles au sol.", "Croise tes mains et fais pivoter ton torse vers la droite, amenant tes mains vers le sol à côté de ta hanche droite.", "Reviens au centre, puis pivote vers la gauche, amenant tes mains vers le sol à côté de ta hanche gauche.", "Alterne lentement d''un côté à l''autre en contrôlant le mouvement."]', '["Garde ton core engagé pendant toute la durée de l''exercice pour protéger ton bas du dos.", "Maintiens une colonne vertébrale droite, évite d''arrondir tes épaules vers l''avant.", "Concentre-toi sur la rotation de ton torse plutôt que sur le mouvement de tes bras.", "Maîtrise le mouvement, évite d''utiliser l''élan pour balancer de gauche à droite.", "Garde tes pieds surélevés pendant l''exercice pour maintenir une tension constante dans ton core."]', '["Keep your core engaged throughout the entire movement to protect your lower back", "Maintain a straight spine and avoid rounding your shoulders forward", "Focus on rotating from your torso rather than just moving your arms", "Control the movement and avoid using momentum to swing side to side", "Keep your feet elevated throughout the exercise to maintain constant core tension"]', '10affa59-53b8-40a9-a06c-36b70d2bb005', 'russian-twists', NULL, NULL);
INSERT INTO public.exercises VALUES ('bdda8cbe-bc76-44f7-97dc-2a8d945d0396', 'Élévations d''épaules au Smith Machine', NULL, 'رفعات الكتفين بواسطة آلة سميث', 'Smith Machine Behind the Back Shrug', 'Back', '[]', 'Back', 'Intermediate', 8, '/videos/back/smith-machine-behind-the-back-shrug.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-behind-the-back-shrug.jpg', NULL, '["Garde les bras tendus pendant tout le mouvement pour bien travailler les trapèzes.", "Lève les épaules directement vers le haut, sans les faire rouler vers l''avant ou vers l''arrière.", "Contrôle bien le mouvement lors de la montée et de la descente de tes épaules.", "Garde le ventre engagé pour une posture correcte et protège ton bas du dos.", "Choisis une largeur de prise qui te semble confortable et facilite ton amplitude de mouvement."]', '["Fléchir les bras, ce qui diminue l''activation des trapèzes.", "Ne pas contrôler la descente, risquant des blessures ou un travail musculaire inapproprié."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "smith machine behind the back shrug"]', true, '2026-04-03 12:24:59.248023+00', '2026-04-03 12:24:59.248023+00', 'Prêt à sculpter ton dos et renforcer tes trapèzes ? Avec cet exercice, tu vas te concentrer sur l''élévation des épaules tout en contrôlant parfaitement le mouvement. C''est le moment de briller !', '["Fléchir les bras, ce qui diminue l''activation des trapèzes.", "Ne pas contrôler la descente, risquant des blessures ou un travail musculaire inapproprié."]', true, '["Position yourself in the Smith machine with the bar behind your back and grip it with both hands using an overhand grip", "Stand with feet shoulder-width apart and maintain a straight, upright posture throughout the movement", "Engage your core and keep your arms straight as you lift your shoulders directly upward", "Squeeze your trapezius muscles at the top of the movement and hold for a brief pause", "Lower your shoulders back down to the starting position in a controlled manner", "Complete the desired number of repetitions while maintaining proper form"]', '["Positionne-toi devant la machine Smith avec la barre derrière ton dos, en la tenant avec les deux mains en prise pronation légèrement plus large que les épaules.", "Écarte les pieds à largeur des épaules et reste bien droit tout au long de l''exercice.", "Engage ton ventre et garde les bras tendus pendant que tu relèves les épaules vers tes oreilles.", "Concentre-toi pour contracter tes trapèzes en haut du mouvement et fais une courte pause.", "Redescends doucement les épaules jusqu''à la position de départ.", "Effectue le nombre de répétitions souhaité tout en gardant une bonne posture."]', '["Garde les bras tendus pendant tout le mouvement pour bien travailler les trapèzes.", "Lève les épaules directement vers le haut, sans les faire rouler vers l''avant ou vers l''arrière.", "Contrôle bien le mouvement lors de la montée et de la descente de tes épaules.", "Garde le ventre engagé pour une posture correcte et protège ton bas du dos.", "Choisis une largeur de prise qui te semble confortable et facilite ton amplitude de mouvement."]', '["Keep your arms straight throughout the entire movement to isolate the trapezius muscles", "Focus on lifting your shoulders straight up rather than rolling them forward or backward", "Maintain control during both the lifting and lowering phases of the exercise", "Keep your core engaged to maintain proper posture and protect your lower back", "Use a grip width that feels comfortable and allows for full range of motion"]', '3e923378-4af0-4d61-9ce7-263fb0ed3b04', 'smith-machine-behind-the-back-shrug', NULL, NULL);
INSERT INTO public.exercises VALUES ('52e032e7-a109-41cc-b31e-e5af49e1600a', 'Tirage avec barre au Smith en prise inversée', NULL, NULL, 'Smith Machine Bent Over Row Underhand Grip', 'Back', '[]', 'Back', 'Intermediate', 8, '/videos/back/smith-machine-bent-over-row-underhand-grip.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-bent-over-row-underhand-grip.jpg', NULL, '["Gardez le dos droit pendant tout le mouvement pour éviter les blessures", "Concentrez-vous sur l''activation des muscles du dos plutôt que des bras, commencez le mouvement avec vos omoplates", "Maintenez une légère flexion des genoux et serrez votre sangle abdominale pour assurer la stabilité", "Évitez d''utiliser l''élan et contrôlez les phases de montée et de descente", "Gardez la tête dans une position neutre, ne regardez pas excessivement vers le haut ou le bas"]', '["Ne pas garder le dos droit peut entraîner des blessures", "Utiliser trop de poids et compromettre la forme", "Tirer avec les bras au lieu de se concentrer sur le dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "smith machine bent over row underhand grip"]', true, '2026-04-03 12:24:59.288437+00', '2026-04-03 12:24:59.288437+00', 'Préparez-vous à renforcer votre dos avec ce mouvement puissant ! Placez-vous sous la barre au Smith, en prise inversée, les mains écartées à la largeur des épaules. C’est le moment de briller !', '["Ne pas garder le dos droit peut entraîner des blessures", "Utiliser trop de poids et compromettre la forme", "Tirer avec les bras au lieu de se concentrer sur le dos"]', true, '["Set the Smith machine bar at about mid-thigh height and add appropriate weight", "Stand with feet shoulder-width apart and grasp the bar with an underhand grip, hands slightly wider than shoulders", "Hinge at the hips and lean forward while keeping your back straight and core engaged", "Pull the bar towards your lower chest by driving your elbows back and squeezing your shoulder blades together", "Hold the contraction briefly at the top of the movement", "Slowly lower the bar back to the starting position with control"]', '["Réglez la barre du Smith à hauteur de mi-cuisse et ajoutez le poids adapté", "Positionnez vos pieds à la largeur des épaules et saisissez la barre en prise inversée, mains légèrement plus larges que les épaules", "Fléchissez les hanches, penchez-vous en avant en maintenant le dos droit et le gainage engagé", "Tirez la barre vers votre bas du torse en ramenant les coudes vers l''arrière et en serrant les omoplates ensemble", "Maintenez la contraction au sommet du mouvement", "Redescendez lentement la barre vers la position de départ en contrôlant le mouvement"]', '["Gardez le dos droit pendant tout le mouvement pour éviter les blessures", "Concentrez-vous sur l''activation des muscles du dos plutôt que des bras, commencez le mouvement avec vos omoplates", "Maintenez une légère flexion des genoux et serrez votre sangle abdominale pour assurer la stabilité", "Évitez d''utiliser l''élan et contrôlez les phases de montée et de descente", "Gardez la tête dans une position neutre, ne regardez pas excessivement vers le haut ou le bas"]', '["Keep your back straight throughout the entire movement to prevent injury", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Maintain a slight bend in your knees and keep your core tight for stability", "Avoid using momentum and control both the lifting and lowering phases of the movement", "Keep your head in a neutral position and avoid looking up or down excessively"]', 'b66b9294-0bfe-494f-b0aa-09602a7b5e41', 'smith-machine-bent-over-row-underhand-grip', NULL, NULL);
INSERT INTO public.exercises VALUES ('53dfa630-0807-4761-a275-a5c0f6d36d4f', 'Hip Thrust à la Smith Machine', NULL, NULL, 'Smith Machine Hip Thrust', 'Glutes', '[]', 'Glutes', 'Intermediate', 8, '/videos/glutes/smith-machine-hip-thrust.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-hip-thrust.jpg', NULL, '["Garde ton ventre engagé tout au long du mouvement pour éviter les extensions excessives du bas du dos", "Concentre-toi sur le mouvement à travers tes fessiers plutôt que de pousser avec le bas du dos", "Maintiens une colonne vertébrale neutre et évite que tes genoux ne s''inclinent vers l''intérieur lors du mouvement", "Utilise un bon rembourrage sur tes hanches pour prévenir l''inconfort causé par la barre", "Assure-toi que le banc est stable et bien positionné pour soutenir ton dos en toute sécurité"]', '["Ne pas engager son core, ce qui peut mener à des douleurs au dos", "Ne pas contrôler la descente, ce qui peut diminuer les gains"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "machine", "smith machine hip thrust"]', true, '2026-04-03 12:24:59.309666+00', '2026-04-03 12:24:59.309666+00', 'Commence avec le dos contre la Smith machine, la barre reposant sur le haut de ton dos et les pieds bien ancrés au sol. Élève les hanches tout en contractant les fessiers, puis redescends lentement.', '["Ne pas engager son core, ce qui peut mener à des douleurs au dos", "Ne pas contrôler la descente, ce qui peut diminuer les gains"]', true, '["Set the Smith machine bar to an appropriate height and add desired weight plates", "Position a bench perpendicular to the Smith machine and sit with your upper back against it", "Place the barbell across your hips with a pad or towel for comfort and plant feet firmly on the floor", "Unrack the bar by lifting slightly and rotating the hooks away from the catches", "Drive through your heels and squeeze glutes to lift hips up until your body forms a straight line from knees to shoulders", "Lower the weight slowly and under control back to starting position, maintaining tension in the glutes"]', '["Ajuste la barre de la Smith machine à la bonne hauteur et ajoute les poids souhaités", "Positionne un banc perpendiculairement à la machine et assieds-toi avec le haut du dos contre", "Place la barre sur tes hanches avec un coussin ou une serviette pour plus de confort et assure-toi que tes pieds sont bien ancrés au sol", "Détache la barre en soulevant légèrement et en faisant pivoter les crochets", "Pousse avec tes talons et contracte tes fessiers pour lever les hanches jusqu''à ce que ton corps forme une ligne droite entre les genoux et les épaules", "Redescends lentement et de manière contrôlée à la position de départ en gardant la tension dans les fessiers"]', '["Garde ton ventre engagé tout au long du mouvement pour éviter les extensions excessives du bas du dos", "Concentre-toi sur le mouvement à travers tes fessiers plutôt que de pousser avec le bas du dos", "Maintiens une colonne vertébrale neutre et évite que tes genoux ne s''inclinent vers l''intérieur lors du mouvement", "Utilise un bon rembourrage sur tes hanches pour prévenir l''inconfort causé par la barre", "Assure-toi que le banc est stable et bien positionné pour soutenir ton dos en toute sécurité"]', '["Keep your core engaged throughout the movement to prevent lower back hyperextension", "Focus on driving the movement through your glutes rather than pushing with your lower back", "Maintain a neutral spine position and avoid letting your knees cave inward during the thrust", "Use adequate padding across your hips to prevent discomfort from the barbell", "Ensure the bench is stable and positioned correctly to support your upper back safely"]', 'ea856b4b-ef97-4fa6-81a1-269f060df9c5', 'smith-machine-hip-thrust', NULL, NULL);
INSERT INTO public.exercises VALUES ('ca87b403-30ab-49b5-abd2-258bf58bf8d2', 'Élévations d''épaules à la Smith Machine', NULL, 'تمارين رفع الكتفين على آلة سميث', 'Smith Machine Shrug', 'Back', '[]', 'Back', 'Beginner', 8, '/videos/back/smith-machine-shrug.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-shrug.jpg', NULL, '["Garde la tête neutre, évite de rouler les épaules en avant ou en arrière pendant l''exercice.", "Concentre-toi sur l''élévation des épaules vers le haut plutôt que de tirer avec les bras pour cibler correctement les muscles trapèzes.", "Utilise un mouvement complet en soulevant aussi haut que possible et en étirant complètement en bas.", "Maintiens une bonne posture en gardant la poitrine haute et le ventre contracté tout au long de l''exercice.", "Commence avec des poids légers pour maîtriser la technique avant d''augmenter les charges."]', '["Ne pas utiliser une amplitude de mouvement complète.", "Rouler les épaules au lieu de les élever verticalement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "smith machine shrug"]', true, '2026-04-03 12:24:59.348783+00', '2026-04-03 12:24:59.348783+00', 'Positionne-toi sous la barre de la Smith machine, repose-la sur le haut de ton dos. Prépare-toi à faire travailler tes trapèzes en soulevant tes épaules !', '["Ne pas utiliser une amplitude de mouvement complète.", "Rouler les épaules au lieu de les élever verticalement."]', true, '["Set the Smith machine bar at mid-thigh height and add appropriate weight plates", "Stand with feet shoulder-width apart and grip the bar with both hands using an overhand grip", "Keep your arms straight and let the bar hang at arm''s length against your thighs", "Lift your shoulders straight up as high as possible while keeping your arms extended", "Hold the contracted position for 1-2 seconds at the top of the movement", "Slowly lower your shoulders back to the starting position in a controlled manner"]', '["Régle la barre de la Smith machine à hauteur de mi-cuisse et ajoute des poids adaptés.", "Place tes pieds à la largeur des épaules et prends la barre avec les deux mains en prise pronation.", "Garde les bras tendus et laisse la barre pendre contre tes cuisses.", "Soulève tes épaules vers le haut aussi haut que possible tout en maintenant les bras étendus.", "Maintiens la contraction en haut du mouvement pendant 1 à 2 secondes.", "Redescends lentement les épaules à la position de départ de manière contrôlée."]', '["Garde la tête neutre, évite de rouler les épaules en avant ou en arrière pendant l''exercice.", "Concentre-toi sur l''élévation des épaules vers le haut plutôt que de tirer avec les bras pour cibler correctement les muscles trapèzes.", "Utilise un mouvement complet en soulevant aussi haut que possible et en étirant complètement en bas.", "Maintiens une bonne posture en gardant la poitrine haute et le ventre contracté tout au long de l''exercice.", "Commence avec des poids légers pour maîtriser la technique avant d''augmenter les charges."]', '["Keep your head in a neutral position and avoid rolling your shoulders forward or backward during the movement", "Focus on lifting your shoulders straight up rather than pulling with your arms to properly target the trapezius muscles", "Use a full range of motion by lifting as high as possible and allowing a complete stretch at the bottom", "Maintain proper posture throughout the exercise by keeping your chest up and core engaged", "Start with lighter weight to master the form before progressing to heavier loads"]', 'b3d09e97-408c-4eb9-8900-ddc99a9a4218', 'smith-machine-shrug', NULL, NULL);
INSERT INTO public.exercises VALUES ('51dbcd97-49ef-4868-ad4d-b4124ffda787', 'Squat Serré à la Smith', NULL, NULL, 'Smith Machine Narrow Stance Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 8, '/videos/quadriceps/smith-machine-narrow-stance-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-narrow-stance-squat.jpg', NULL, '["Veille à garder tes genoux alignés avec tes orteils tout au long du mouvement pour éviter les valgis des genoux.", "Maintiens une colonne vertébrale neutre en gardant la poitrine en avant et en évitant de pencher le torse en avant.", "La position serrée met davantage l''accent sur les quadriceps que lors d''une position plus large.", "Contrôle la vitesse de la descente et évite de rebondir au fond du mouvement.", "Assure-toi d''achever l''extension des hanches en haut sans verrouiller trop agressivement."]', '["Les genoux qui s''écartent des orteils pendant le squat.", "Un dos arrondi au lieu d''une colonne droite lors de la descente."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "smith machine narrow stance squat"]', true, '2026-04-03 12:24:59.338034+00', '2026-04-03 12:24:59.338034+00', 'Place-toi sous la Smith machine, barre reposant sur le haut de ton dos et pieds joints. Descends en squat profond et remonte en poussant sur tes talons.', '["Les genoux qui s''écartent des orteils pendant le squat.", "Un dos arrondi au lieu d''une colonne droite lors de la descente."]', true, '["Position the bar at chest height on the Smith machine and step underneath it, placing the bar on your upper traps", "Take a narrow stance with feet about hip-width apart and toes slightly turned out", "Unrack the bar by lifting slightly and rotating the hooks, then brace your core", "Initiate the descent by pushing your hips back and bending your knees while keeping your chest up", "Lower until your thighs are parallel to the floor or as deep as your mobility allows", "Drive through your heels and push the floor away to return to the starting position"]', '["Positionne la barre à hauteur de poitrine sur la Smith machine et place-toi en dessous, barre sur tes trapèzes supérieurs.", "Adopte une position serrée avec les pieds à la largeur des hanches et les orteils légèrement tournés vers l''extérieur.", "Décharge la barre en soulevant légèrement et en faisant pivoter les crochets, puis contracte ton ventre.", "Commence la descente en poussant les hanches en arrière et en fléchissant les genoux tout en gardant la poitrine bien droite.", "Descends jusqu''à ce que tes cuisses soient parallèles au sol ou aussi bas que ta mobilité te le permet.", "Pousse à travers tes talons pour revenir à la position de départ."]', '["Veille à garder tes genoux alignés avec tes orteils tout au long du mouvement pour éviter les valgis des genoux.", "Maintiens une colonne vertébrale neutre en gardant la poitrine en avant et en évitant de pencher le torse en avant.", "La position serrée met davantage l''accent sur les quadriceps que lors d''une position plus large.", "Contrôle la vitesse de la descente et évite de rebondir au fond du mouvement.", "Assure-toi d''achever l''extension des hanches en haut sans verrouiller trop agressivement."]', '["Keep your knees tracking in line with your toes throughout the entire movement to prevent knee valgus", "Maintain a neutral spine by keeping your chest up and avoiding excessive forward lean", "The narrow stance emphasizes the quadriceps more than a wider stance would", "Control the descent speed and avoid bouncing at the bottom of the movement", "Ensure full hip extension at the top without locking out aggressively"]', '74545eb6-14ac-4017-b275-d1776516419d', 'smith-machine-narrow-stance-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('6efcf03b-cfb8-436f-8623-3a5dc0fd66fb', 'Toucher les orteils en levant les jambes', NULL, NULL, 'High toe touches', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/high-toe-touches.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-toe-touches.jpg', NULL, '["Garde ton bas du dos collé au sol pour protéger ta colonne vertébrale", "Concentre-toi sur l''utilisation de tes abdos plutôt que sur l''élan pour te relever", "Respire régulièrement, ne retiens pas ton souffle durant l''exercice", "Maintiens tes jambes stables en position de table sans les laisser tomber ou balancer", "Privilégie la qualité des mouvements - fais des répétitions contrôlées plutôt que de foncer à travers l''exercice"]', '["Soulever le cou au lieu des omoplates", "Lâcher les jambes en position de table", "Utiliser l''élan au lieu de la force abdominale pour se relever", "Ne pas contrôler la descente et laisser le corps s''affaisser"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "high toe touches"]', true, '2026-04-03 12:24:57.150304+00', '2026-04-03 12:24:57.150304+00', 'Position de départ : Allonge-toi sur le dos, bras tendus vers le plafond et jambes levées, genoux pliés à 90 degrés. Exécution : Crunch en soulevant les omoplates du sol tout en atteignant tes mains vers tes orteils, puis redescends lentement à la position de départ.', '["Soulever le cou au lieu des omoplates", "Lâcher les jambes en position de table", "Utiliser l''élan au lieu de la force abdominale pour se relever", "Ne pas contrôler la descente et laisser le corps s''affaisser"]', true, '["Lie on your back with arms straight up and legs in tabletop position with knees at 90 degrees", "Press your lower back into the floor and engage your core muscles", "Exhale as you crunch up, lifting your shoulder blades off the ground while reaching hands toward toes", "Keep your neck in neutral position and avoid pulling on your head", "Slowly lower back down with control, keeping your core engaged throughout", "Maintain the tabletop leg position throughout the entire movement"]', '["Allonge-toi sur le dos, bras tendus vers le haut et jambes en position de table avec les genoux à 90 degrés", "Presse ton bas du dos contre le sol et contracte tes muscles abdominaux", "Expulse l''air en te relevant, en soulevant les omoplates du sol tout en atteignant les mains vers les orteils", "Garde ton cou dans une position neutre, sans tirer sur ta tête", "Reddescends lentement en contrôle, en gardant les abdos engagés tout au long du mouvement", "Maintiens la position de table des jambes pendant tout l''exercice"]', '["Garde ton bas du dos collé au sol pour protéger ta colonne vertébrale", "Concentre-toi sur l''utilisation de tes abdos plutôt que sur l''élan pour te relever", "Respire régulièrement, ne retiens pas ton souffle durant l''exercice", "Maintiens tes jambes stables en position de table sans les laisser tomber ou balancer", "Privilégie la qualité des mouvements - fais des répétitions contrôlées plutôt que de foncer à travers l''exercice"]', '["Keep your lower back pressed against the floor to protect your spine", "Focus on using your abdominal muscles rather than momentum to lift up", "Maintain steady breathing and avoid holding your breath during the movement", "Keep your legs stable in tabletop position rather than letting them drop or swing", "Quality over quantity - perform controlled repetitions rather than rushing through the exercise"]', '95334bcd-2aa9-4c42-a846-4944c08b9a66', 'high-toe-touches', NULL, NULL);
INSERT INTO public.exercises VALUES ('54d9a7e3-f2ec-493b-ba8b-e6218adb1b84', 'Pose du demi-seigneur des poissons (gauche)', NULL, NULL, 'Half lord of the fishes pose (left)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/half-lord-of-the-fishes-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-lord-of-the-fishes-pose-left.jpg', NULL, '["Reste droit avant de te tordre – allonge ta colonne vertébrale d''abord.", "Torsionne depuis le milieu du dos, pas juste les épaules.", "Assure-toi que les deux os assis sont ancrés au sol."]', '["Ne pas garder la colonne vertébrale alignée avant de torsionner.", "Torsionner uniquement avec les épaules sans utiliser le dos.", "Lever un os assis du sol au lieu de les garder ancrés."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "half lord of the fishes pose (left)"]', true, '2026-04-03 12:24:56.921277+00', '2026-04-03 12:24:56.921277+00', 'Position de départ : Assieds-toi avec les jambes étendues, plie ton genou gauche et place ton pied gauche à l''extérieur de ta cuisse droite, en gardant ta jambe droite bien droite. Exécution : Torsionne ton torse vers la gauche, place ton coude droit contre ton genou gauche pour t''aider, tout en posant ta main gauche derrière le dos pour le soutien.', '["Ne pas garder la colonne vertébrale alignée avant de torsionner.", "Torsionner uniquement avec les épaules sans utiliser le dos.", "Lever un os assis du sol au lieu de les garder ancrés."]', true, '["Sit with legs extended. Bend one knee and place the foot outside the opposite thigh.", "Bend the bottom leg and bring the foot near the opposite hip.", "Twist your torso toward the bent knee.", "Use the opposite elbow against the outside of the bent knee for leverage."]', '["Assieds-toi avec les jambes étendues.", "Plie un genou et place le pied à l''extérieur de la cuisse opposée.", "Torsionne ton torse en direction du genou plié.", "Utilise le coude opposé contre l''extérieur du genou plié pour mieux te soutenir."]', '["Reste droit avant de te tordre – allonge ta colonne vertébrale d''abord.", "Torsionne depuis le milieu du dos, pas juste les épaules.", "Assure-toi que les deux os assis sont ancrés au sol."]', '["Sit tall before you twist — lengthen your spine first.", "Twist from your mid-back, not just your shoulders.", "Keep both sit bones grounded."]', '3f916ec5-151e-4b3c-bdd2-011621f259fe', 'half-lord-of-the-fishes-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('f83f7b02-56a1-477a-ad4d-eb6cb7ab65c2', 'Squat Sumo à la Smith Machine', NULL, 'Squat Sumo avec Smith Machine', 'Smith Machine Sumo Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 8, '/videos/quadriceps/smith-machine-sumo-squat-f7c6095d.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-sumo-squat-f7c6095d.jpg', NULL, '["Veille à ce que tes genoux restent alignés avec tes orteils pour éviter les blessures", "Garde le torse droit et n''incline pas trop en avant pour protéger le bas du dos", "Concentre-toi sur la poussée avec tes talons plutôt qu''avec les orteils pour maximiser l''activation des quadriceps et des fessiers", "Contrôle la descente et évite de rebondir au fond du mouvement", "Maintiens ton ventre serré pendant tout le mouvement pour plus de stabilité"]', '["Ne pas aligner les genoux avec les orteils", "S''incliner trop en avant pendant le squat"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "smith machine sumo squat"]', true, '2026-04-03 12:24:59.376174+00', '2026-04-03 12:24:59.376174+00', 'Position de départ : Installe-toi sous la Smith machine avec la barre sur le haut du dos, les pieds écartés au-delà de la largeur des épaules, les orteils légèrement tournés vers l''extérieur. Exécution : Descends en squat profond en gardant le dos droit, puis pousse vers le haut pour revenir à la position de départ.', '["Ne pas aligner les genoux avec les orteils", "S''incliner trop en avant pendant le squat"]', true, '["Set the Smith machine bar at about chest height and add appropriate weight plates", "Position yourself under the bar with feet wider than shoulder-width apart and toes angled outward", "Grip the bar with hands wider than shoulder-width and unrack by lifting and rotating the bar", "Keep your core engaged and chest up as you lower down until your thighs are parallel to the floor", "Drive through your heels and inner thighs to push back up to starting position", "Re-rack the bar by rotating it back into the safety catches when finished"]', '["Règle la barre de la Smith machine à hauteur de poitrine et ajoute des poids appropriés", "Positionne-toi sous la barre, les pieds plus larges que la largeur des épaules et les orteils orientés vers l''extérieur", "Prends la barre avec des mains plus larges que la largeur des épaules et dégage-la en levant et en tournant la barre", "Engage ton ventre et garde la poitrine haute en descendant jusqu''à ce que tes cuisses soient parallèles au sol", "Pousse avec tes talons et l''intérieur des cuisses pour revenir à la position de départ", "Remets la barre en place en la tournant dans les mesures de sécurité à la fin de l''exercice"]', '["Veille à ce que tes genoux restent alignés avec tes orteils pour éviter les blessures", "Garde le torse droit et n''incline pas trop en avant pour protéger le bas du dos", "Concentre-toi sur la poussée avec tes talons plutôt qu''avec les orteils pour maximiser l''activation des quadriceps et des fessiers", "Contrôle la descente et évite de rebondir au fond du mouvement", "Maintiens ton ventre serré pendant tout le mouvement pour plus de stabilité"]', '["Keep your knees aligned with your toes throughout the movement to prevent knee injury", "Maintain an upright torso and avoid leaning too far forward to protect your lower back", "Focus on pushing through your heels rather than your toes to maximize quad and glute activation", "Control the descent and avoid bouncing at the bottom of the movement", "Keep your core tight throughout the entire range of motion for stability"]', 'f7c6095d-b060-48e6-81be-461e81a578a7', 'smith-machine-sumo-squat-f7c6095d', NULL, NULL);
INSERT INTO public.exercises VALUES ('a5e3d1f5-599f-4d13-8169-4bb3f538206b', 'Tirage vertical à la barre Smith', NULL, NULL, 'Smith Machine Upright Row', 'Shoulders', '[]', 'Shoulders', 'Beginner', 8, '/videos/shoulders/smith-machine-upright-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-upright-row.jpg', NULL, '["Garde une prise plus étroite que la largeur des épaules pour cibler correctement les deltoïdes et éviter l''impingement", "Soulève toujours tes coudes plus haut que tes poignets durant le mouvement pour maximiser l''activation des épaules", "Évite de tirer la barre trop haut au-dessus du niveau de la poitrine pour prévenir les blessures", "Maintiens le contrôle pendant la phase de descente pour maximiser l''engagement musculaire et prévenir les blessures", "Garde le chemin de la barre droit et près de ton corps durant toute l''amplitude du mouvement"]', '["Ne pas maintenir une prise suffisamment étroite, ce qui peut limiter l''efficacité de l''exercice", "Élever la barre trop haut au-dessus du niveau de la poitrine, ce qui peut causer des douleurs à l''épaule"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "smith machine upright row"]', true, '2026-04-03 12:24:59.392731+00', '2026-04-03 12:24:59.392731+00', 'Positionne-toi sous la machine Smith avec une prise pronation, les mains à la largeur des épaules. Tire la barre vers le bas de ta poitrine en gardant les coudes près du corps, puis abaisse-la lentement à la position de départ.', '["Ne pas maintenir une prise suffisamment étroite, ce qui peut limiter l''efficacité de l''exercice", "Élever la barre trop haut au-dessus du niveau de la poitrine, ce qui peut causer des douleurs à l''épaule"]', true, '["Set the Smith machine bar to a height where your arms are fully extended when grasping it at thigh level", "Position yourself with feet shoulder-width apart and grip the bar with hands closer than shoulder-width using an overhand grip", "Engage your core and maintain an upright posture with shoulders back and chest up", "Pull the bar straight up by lifting your elbows high and out to the sides, keeping the bar close to your body", "Stop when the bar reaches upper chest level with elbows higher than your wrists", "Lower the bar slowly and controlled back to the starting position at thigh level"]', '["Règle la barre Smith à une hauteur où tes bras sont complètement étendus en la saisissant à la hauteur des cuisses", "Positionne tes pieds à la largeur des épaules et saisis la barre avec une prise plus étroite que la largeur des épaules", "Engage ton tronc et garde une posture droite avec les épaules en arrière et la poitrine en avant", "Tire la barre directement vers le haut en élevant tes coudes haut et sur les côtés, en maintenant la barre près de ton corps", "Arrête-toi lorsque la barre atteint le niveau supérieur de la poitrine, avec les coudes plus hauts que les poignets", "Redescends la barre lentement et de manière contrôlée jusqu''à la position de départ, à hauteur des cuisses"]', '["Garde une prise plus étroite que la largeur des épaules pour cibler correctement les deltoïdes et éviter l''impingement", "Soulève toujours tes coudes plus haut que tes poignets durant le mouvement pour maximiser l''activation des épaules", "Évite de tirer la barre trop haut au-dessus du niveau de la poitrine pour prévenir les blessures", "Maintiens le contrôle pendant la phase de descente pour maximiser l''engagement musculaire et prévenir les blessures", "Garde le chemin de la barre droit et près de ton corps durant toute l''amplitude du mouvement"]', '["Keep your grip narrower than shoulder-width to properly target the deltoids and avoid impingement", "Lift your elbows higher than your wrists throughout the movement to maximize shoulder activation", "Avoid pulling the bar too high above chest level as this can cause shoulder impingement", "Maintain control during the lowering phase to maximize muscle engagement and prevent injury", "Keep the bar path straight and close to your body throughout the entire range of motion"]', '95b3c40f-4a12-44e6-ac2e-cd7ce4a3cc3c', 'smith-machine-upright-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('e101850b-e275-4dad-b510-ef56f6e75021', 'Fente Avant (Split Squat)', NULL, 'فنت أمود (Split Squat)', 'Split squat (L)', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/split-squat-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/split-squat-l.jpg', NULL, '["Concentre-toi sur ton pied avant, ne pousse pas avec le pied arrière", "Maintiens ton torse droit, évite de te pencher en avant", "Contrôle ta descente pour ne pas tomber trop vite en bas", "Assure-toi que ton genou avant reste aligné avec tes orteils et ne s''affaisse pas vers l''intérieur", "Pousse à travers ton talon avant lors du retour à la position initiale"]', '["Ne pas descendre assez bas pour que la cuisse soit parallèle au sol", "Laisser le genou avant s''affaisser vers l''intérieur"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "split squat (l)"]', true, '2026-04-03 12:24:59.422272+00', '2026-04-03 12:24:59.422272+00', 'Position de départ : Place-toi en fente avec le pied gauche en avant et le pied droit en arrière, le torse droit et les mains le long du corps. Exécution : Abaisse ton corps en fléchissant les deux genoux jusqu''à ce que ta cuisse avant soit parallèle au sol, puis pousse avec le talon avant pour revenir à la position de départ.', '["Ne pas descendre assez bas pour que la cuisse soit parallèle au sol", "Laisser le genou avant s''affaisser vers l''intérieur"]', true, '["Position your left foot forward and right foot back in a wide staggered stance", "Keep your torso upright with your core engaged throughout the movement", "Lower your body by bending both knees, dropping your back knee toward the ground", "Descend until your front thigh is parallel to the floor", "Push through your front heel to drive back up to the starting position", "Maintain your weight primarily on your front leg throughout the exercise"]', '["Positionne ton pied gauche en avant et le droit en arrière dans une large fente", "Maintiens ton torse droit avec les abdominaux engagés tout au long de l''exercice", "Abaisse ton corps en fléchissant les deux genoux, en descendant ton genou arrière vers le sol", "Descends jusqu''à ce que ta cuisse avant soit parallèle au sol", "Pousse avec ton talon avant pour revenir à la position de départ", "Conserve la majorité de ton poids sur ta jambe avant durant tout l''exercice"]', '["Concentre-toi sur ton pied avant, ne pousse pas avec le pied arrière", "Maintiens ton torse droit, évite de te pencher en avant", "Contrôle ta descente pour ne pas tomber trop vite en bas", "Assure-toi que ton genou avant reste aligné avec tes orteils et ne s''affaisse pas vers l''intérieur", "Pousse à travers ton talon avant lors du retour à la position initiale"]', '["Keep most of your weight on your front leg rather than pushing off the back foot", "Maintain an upright torso position and avoid leaning forward during the movement", "Control the descent to avoid dropping too quickly into the bottom position", "Ensure your front knee tracks in line with your toes and doesn''t cave inward", "Focus on pushing through your front heel when returning to the starting position"]', 'd26ca6be-632d-4674-a520-6a2144d76137', 'split-squat-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('538644eb-aeff-49fe-bd82-f574af0f1c4c', 'Hang Snatch', NULL, 'جذب بالأثقال', 'Hang Snatch', 'Bodyweight', '[]', 'Bodyweight', 'Advanced', 1, '/videos/bodyweight/hang-snatch.mp4', NULL, NULL, NULL, '/videos/thumbnails/hang-snatch.jpg', NULL, '["Concentrez-vous sur l''extension explosive des hanches et des genoux pendant la phase de saut", "Gardez votre sangle abdominale engagée tout au long du mouvement pour maintenir la stabilité", "Atterrissez doucement sur la plante des pieds pour réduire l''impact sur les articulations", "Pratiquez la position de squat séparément avant d''essayer le mouvement complet", "Commencez par des mouvements lents et contrôlés avant de progresser vers une vitesse explosive complète"]', '["Ne pas garder le torse relevé lors de la montée", "Sauter sans synchroniser le mouvement des bras", "Atterrir brutalement sur les jambes"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "barbell", "hang snatch"]', true, '2026-04-03 12:24:57.044531+00', '2026-04-03 12:24:57.044531+00', 'Position de départ : Tenez-vous debout, pieds écartés à la largeur des hanches, bras détendus le long du corps. Execution : Sautez explosivement tout en tirant vos bras au-dessus de votre tête et en vous abaissant dans une position de squat profond, puis relevez-vous pour terminer le mouvement.', '["Ne pas garder le torse relevé lors de la montée", "Sauter sans synchroniser le mouvement des bras", "Atterrir brutalement sur les jambes"]', true, '["Begin in a standing position with feet hip-width apart and arms relaxed at your sides", "Initiate the movement by bending at the hips and knees while swinging your arms back", "Explosively extend your hips and knees while jumping upward", "As you reach peak height, quickly pull your arms overhead and drop your body into a deep squat position", "Land softly in the squat position with arms extended overhead", "Stand up from the squat position to return to the starting stance"]', '["Commencez en position debout avec les pieds écartés à la largeur des hanches et les bras détendus à vos côtés", "Initiez le mouvement en fléchissant les hanches et les genoux tout en balançant vos bras en arrière", "Étendez explosivement vos hanches et vos genoux tout en sautant vers le haut", "À la hauteur maximale, tirez rapidement vos bras au-dessus de votre tête et descendez en position de squat profond", "Atterrissez doucement en position de squat avec les bras étendus au-dessus de la tête", "Relevez-vous à partir de la position de squat pour retourner à la position de départ"]', '["Concentrez-vous sur l''extension explosive des hanches et des genoux pendant la phase de saut", "Gardez votre sangle abdominale engagée tout au long du mouvement pour maintenir la stabilité", "Atterrissez doucement sur la plante des pieds pour réduire l''impact sur les articulations", "Pratiquez la position de squat séparément avant d''essayer le mouvement complet", "Commencez par des mouvements lents et contrôlés avant de progresser vers une vitesse explosive complète"]', '["Focus on explosive hip and knee extension during the jumping phase", "Keep your core engaged throughout the entire movement to maintain stability", "Land softly on the balls of your feet to reduce impact on joints", "Practice the squat position separately before attempting the full movement", "Start with slower, controlled movements before progressing to full explosive speed"]', '8180c05c-73e5-4de1-bb90-0b5e0d80c4c9', 'hang-snatch', NULL, NULL);
INSERT INTO public.exercises VALUES ('afe9945a-1a27-43bc-88cf-d42659cbb3a6', 'Jumping Jacks', NULL, 'المخالفات', 'Jumping jacks', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/jumping-jacks.mp4', NULL, NULL, NULL, '/videos/thumbnails/jumping-jacks.jpg', NULL, '["Atterris en douceur sur l''avant de tes pieds pour réduire l''impact sur les articulations", "Garde ton ventre engagé pour maintenir ta stabilité", "Commence à un rythme confortable et augmente progressivement ta vitesse à mesure que ton endurance s''améliore", "Évite de bloquer tes genoux en atterrissant pour prévenir le stress articulaire", "Respire de manière rythmée - expire en sautant et inhale en revenant"]', '["Oublier d''engager le ventre, ce qui peut nuire à la stabilité", "Ne pas atterrir en douceur, ce qui augmente le risque de blessure", "Sauter trop haut, ce qui peut mener à une fatigue rapide", "Perdre le rythme, ce qui diminue l''efficacité de l''exercice", "Bloquer les genoux en atterrissant, ce qui provoque une pression inutile sur les articulations"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "jumping jacks"]', true, '2026-04-03 12:24:57.38673+00', '2026-04-03 12:24:57.38673+00', 'Position de départ : Tiens-toi droit, les pieds joints, les bras le long du corps et le ventre engagé. Effectue un saut en écartant les pieds à la largeur des épaules tout en levant les bras au-dessus de ta tête. Saute à nouveau pour revenir à la position de départ, le tout en un seul mouvement fluide.', '["Oublier d''engager le ventre, ce qui peut nuire à la stabilité", "Ne pas atterrir en douceur, ce qui augmente le risque de blessure", "Sauter trop haut, ce qui peut mener à une fatigue rapide", "Perdre le rythme, ce qui diminue l''efficacité de l''exercice", "Bloquer les genoux en atterrissant, ce qui provoque une pression inutile sur les articulations"]', true, '["Stand tall with feet together and arms relaxed at your sides", "Jump up while spreading your feet wider than shoulder-width apart", "Simultaneously raise both arms out to the sides and overhead in an arc motion", "Land softly on the balls of your feet with knees slightly bent", "Jump again while bringing feet back together and lowering arms to starting position", "Maintain a steady rhythm throughout the exercise"]', '["Tiens-toi bien droit, les pieds joints, les bras détendus sur les côtés", "Saute en écartant les pieds plus larges que les épaules", "Lève les deux bras sur les côtés et au-dessus de ta tête en arc", "Atterris doucement sur l''avant des pieds, les genoux légèrement fléchis", "Saute à nouveau pour rassembler les pieds et abaisser les bras à la position de départ", "Maintiens un rythme constant tout au long de l''exercice"]', '["Atterris en douceur sur l''avant de tes pieds pour réduire l''impact sur les articulations", "Garde ton ventre engagé pour maintenir ta stabilité", "Commence à un rythme confortable et augmente progressivement ta vitesse à mesure que ton endurance s''améliore", "Évite de bloquer tes genoux en atterrissant pour prévenir le stress articulaire", "Respire de manière rythmée - expire en sautant et inhale en revenant"]', '["Land softly on the balls of your feet to reduce impact on joints", "Keep your core engaged throughout the movement to maintain stability", "Start at a comfortable pace and gradually increase speed as you build endurance", "Avoid locking your knees when landing to prevent joint stress", "Breathe rhythmically - exhale on the jump out, inhale on the jump in"]', '8bc22d59-cc73-483b-b12c-515e974f39a6', 'jumping-jacks', NULL, NULL);
INSERT INTO public.exercises VALUES ('e6e73c86-78ca-4dbf-b2cf-bb0c29041506', 'Squats avec Fly Jacks', NULL, 'Squats m3a Fly Jacks', 'Squats into fly jacks', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/squats-into-fly-jacks.mp4', NULL, NULL, NULL, '/videos/thumbnails/squats-into-fly-jacks.jpg', NULL, '["Garde ta poitrine relevée pour ne pas arrondir le dos en squat.", "Atterris doucement sur la pointe des pieds pour diminuer l''impact sur les articulations.", "Le mouvement des bras active principalement les muscles de la poitrine pendant le saut.", "Maintiens un rythme régulier, mais privilégie la bonne forme à la vitesse.", "Commence par des sessions plus courtes et augmente l''intensité progressivement en fonction de ton amélioration."]', '["Ne pas garder le dos droit pendant le squat.", "Sauter trop haut sans contrôler l''atterrissage."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "squats into fly jacks"]', true, '2026-04-03 12:24:59.481466+00', '2026-04-03 12:24:59.481466+00', 'Position de départ : Tiens-toi bien droit, les pieds écartés à la largeur des épaules, bras le long du corps. Exécution : Descends en squat en poussant tes hanches vers l''arrière, puis en te relevant, sautes en écartant tes jambes tout en étendant les bras sur les côtés comme pour voler. Retombe doucement en posture de squat.', '["Ne pas garder le dos droit pendant le squat.", "Sauter trop haut sans contrôler l''atterrissage."]', true, '["Stand with feet shoulder-width apart and engage your core muscles", "Lower into a squat by pushing your hips back and bending your knees while keeping your chest up", "Drive through your heels to explosively stand up and immediately jump into the air", "While airborne, spread your legs wide and extend your arms out to the sides at shoulder height", "Land softly with feet wide apart and arms extended, then quickly jump back to the starting squat position", "Maintain control throughout the movement and land with bent knees to absorb impact"]', '["Tiens-toi bien droit, pieds écartés à la largeur des épaules et engage ton ventre.", "Descends en squat en poussant les hanches vers l''arrière, genoux fléchis, tout en gardant la poitrine relevée.", "Pousse sur tes talons pour te relever rapidement et saute en l''air.", "En plein saut, écarte tes jambes et étends tes bras à hauteur des épaules.", "Atterris doucement avec les pieds écartés et les bras tendus, puis retourne rapidement à la position de squat initiale.", "Garde le contrôle pendant tout le mouvement et atterris avec les genoux fléchis pour amortir l''impact."]', '["Garde ta poitrine relevée pour ne pas arrondir le dos en squat.", "Atterris doucement sur la pointe des pieds pour diminuer l''impact sur les articulations.", "Le mouvement des bras active principalement les muscles de la poitrine pendant le saut.", "Maintiens un rythme régulier, mais privilégie la bonne forme à la vitesse.", "Commence par des sessions plus courtes et augmente l''intensité progressivement en fonction de ton amélioration."]', '["Keep your chest up and avoid rounding your back during the squat portion", "Land softly on the balls of your feet to reduce impact on joints", "The arm movement during the jump primarily engages the chest muscles through the fly motion", "Maintain a steady rhythm but prioritize proper form over speed", "Start with shorter sessions and gradually increase intensity as your conditioning improves"]', 'd9836ac9-8688-41b0-a99c-e03370f53c2c', 'squats-into-fly-jacks', NULL, NULL);
INSERT INTO public.exercises VALUES ('99ddf4b3-29b7-4c0d-a108-0b48a098848b', 'Squats jusqu''aux genoux', NULL, 'سكرات حتى الركب', 'Squats to knee(1)', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/squats-to-knee1.mp4', NULL, NULL, NULL, '/videos/thumbnails/squats-to-knee1.jpg', NULL, '["Répartis ton poids sur l''ensemble de tes pieds, en te concentrant sur la poussée des talons", "Veille à ce que tes genoux soient alignés avec tes orteils sans se déformer vers l''intérieur", "Garde la colonne vertébrale neutre en maintenant ton torse levé et en évitant d''arrondir le dos", "Contrôle la descente pour maximiser l''engagement musculaire et prévenir les blessures", "Arrête-toi à hauteur parallèle pour protéger tes genoux et maintenir une bonne forme"]', '["Les genoux qui se déplacent vers l''intérieur", "Le dos arrondi durant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "squats to knee(1)"]', true, '2026-04-03 12:24:59.499851+00', '2026-04-03 12:24:59.499851+00', 'Position de départ : Tiens-toi debout, pieds écartés à la largeur des hanches, bras le long du corps ou croisés sur la poitrine. Exécution : Abaisse ton corps en pliant les hanches et les genoux jusqu''à ce que tes cuisses soient parallèles au sol (niveau des genoux), puis remonte pour revenir à la position de départ.', '["Les genoux qui se déplacent vers l''intérieur", "Le dos arrondi durant l''exercice"]', true, '["Stand with feet hip-width apart, toes pointing slightly outward", "Keep your chest up and core engaged throughout the movement", "Initiate the movement by pushing your hips back and bending your knees", "Lower your body until your thighs are parallel to the floor, ensuring knees track over your toes", "Push through your heels to return to the starting position", "Maintain control throughout both the lowering and rising phases"]', '["Tiens-toi avec les pieds à la largeur des hanches, les orteils légèrement tournés vers l''extérieur", "Garde le torse droit et le ventre engagé durant tout le mouvement", "Commence le mouvement en poussant tes hanches en arrière et en fléchissant les genoux", "Abaisse ton corps jusqu''à ce que tes cuisses soient parallèles au sol, en veillant à ce que tes genoux suivent la direction de tes orteils", "Pousse à travers tes talons pour revenir à la position de départ", "Reste maître de ton mouvement dans les phases de descente et de montée"]', '["Répartis ton poids sur l''ensemble de tes pieds, en te concentrant sur la poussée des talons", "Veille à ce que tes genoux soient alignés avec tes orteils sans se déformer vers l''intérieur", "Garde la colonne vertébrale neutre en maintenant ton torse levé et en évitant d''arrondir le dos", "Contrôle la descente pour maximiser l''engagement musculaire et prévenir les blessures", "Arrête-toi à hauteur parallèle pour protéger tes genoux et maintenir une bonne forme"]', '["Keep your weight distributed evenly across your feet, focusing on pushing through your heels", "Ensure your knees stay aligned with your toes and don''t cave inward", "Maintain a neutral spine by keeping your chest up and avoiding rounding your back", "Control the descent to maximize muscle engagement and prevent injury", "Stop at parallel depth to protect your knees and maintain proper form"]', '5efb3847-ecf2-4dba-9bc0-cce91af31eac', 'squats-to-knee1', NULL, NULL);
INSERT INTO public.exercises VALUES ('0e8819c5-a846-4fb2-8a50-4739eb277f8a', 'Pose du Tigre (gauche)', NULL, NULL, 'Tiger pose (left)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/tiger-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/tiger-pose-left.jpg', NULL, '["Garde ton bras de soutien solide et droit pour maintenir l''équilibre", "Active tes muscles abdominaux pendant tout le mouvement pour protéger ton bas du dos", "Tire doucement ton pied vers ton corps pour un étirement confortable sans forcer", "Concentre-toi sur le fait de soulever ta poitrine et d''ouvrir l''avant de ton corps", "Respire profondément et évite de retenir ta respiration durant la pose"]', '["S''accrêter de relâcher le bras de soutien", "Ne pas activer le ventre, ce qui peut nuire au bas du dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "tiger pose (left)"]', true, '2026-04-03 12:24:59.727325+00', '2026-04-03 12:24:59.727325+00', 'Position de départ : mets-toi à genoux, sur les mains et les genoux. Une jambe est étendue derrière toi tandis que l''autre main atteint l''arrière pour saisir ton pied. Execution : maintiens cette pose équilibrée en gardant la connexion entre ta main et ton pied, créant ainsi un arc dans ta colonne.', '["S''accrêter de relâcher le bras de soutien", "Ne pas activer le ventre, ce qui peut nuire au bas du dos"]', true, '["Start on hands and knees in a tabletop position on your yoga mat", "Extend your left leg straight back behind you, keeping it lifted", "Reach your right hand back to grasp the top of your left foot", "Pull your foot toward your glutes while lifting your chest", "Hold the position while breathing steadily", "Release slowly and return to starting position before switching sides"]', '["Commence à quatre pattes sur ton tapis de yoga", "Étends ta jambe gauche en arrière, bien droite et relevée", "Tends ta main droite pour saisir le dessus de ton pied gauche", "Tire ton pied vers tes fessiers tout en levant la poitrine", "Tiens la position en respirant calmement", "Relâche doucement et retourne à la position de départ avant de changer de côté"]', '["Garde ton bras de soutien solide et droit pour maintenir l''équilibre", "Active tes muscles abdominaux pendant tout le mouvement pour protéger ton bas du dos", "Tire doucement ton pied vers ton corps pour un étirement confortable sans forcer", "Concentre-toi sur le fait de soulever ta poitrine et d''ouvrir l''avant de ton corps", "Respire profondément et évite de retenir ta respiration durant la pose"]', '["Keep your supporting arm strong and straight to maintain balance", "Engage your core muscles throughout the movement to protect your lower back", "Pull your foot gently toward your body to create a comfortable stretch without forcing the position", "Focus on lifting your chest and opening through the front of your body", "Breathe deeply and avoid holding your breath during the pose"]', '38c0d9e4-7f97-4e8f-8d26-650ca542e1c2', 'tiger-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('af9535dc-a220-4dbf-ade7-96d511675a58', 'Développé avec haltères en position debout pour les épaules', NULL, 'ديفيلوب مع هالتير في ديركت لاستعمال الكتاف', 'Standing Dumbbell Straight-Arm Front Delt', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/standing-dumbbell-straight-arm-front-delt.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-dumbbell-straight-arm-front-delt.jpg', NULL, '["Contractez votre ceinture abdominale pour éviter de balancer ou d''utiliser l''élan", "Arrêtez-vous à hauteur d''épaule pour éviter l''impingement et préserver la forme", "Choisissez un poids qui vous permet de contrôler le mouvement sans balancer", "Concentrez-vous sur les deltoïdes antérieurs qui travaillent, sans impliquer le dos ou les jambes", "Ayez légèrement les genoux fléchis et évitez de bloquer complètement les coudes"]', '["Utiliser un poids trop lourd qui complique le contrôle du mouvement", "Balancer le corps au lieu de garder une position stable", "Négliger la posture, ce qui peut entraîner des blessures"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "standing dumbbell straight-arm front delt"]', true, '2026-04-03 12:24:59.515124+00', '2026-04-03 12:24:59.515124+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des hanches, un haltère dans chaque main, les bras tendus devant vos cuisses, paumes vers votre corps. Exécution : En gardant les bras droits, levez les haltères devant vous jusqu''à hauteur d''épaule, puis redescendez lentement à la position initiale.', '["Utiliser un poids trop lourd qui complique le contrôle du mouvement", "Balancer le corps au lieu de garder une position stable", "Négliger la posture, ce qui peut entraîner des blessures"]', true, '["Stand with feet hip-width apart and engage your core for stability", "Hold dumbbells with a neutral grip, arms fully extended in front of your thighs", "Keep your shoulders down and back, maintaining good posture throughout the movement", "Raise the dumbbells in a controlled arc directly in front of you until they reach shoulder height", "Pause briefly at the top, then slowly lower the weights back to starting position", "Maintain straight arms throughout the entire range of motion"]', '["Positionnez-vous debout, les pieds à la largeur des hanches, et activez votre ceinture abdominale pour la stabilité", "Tenez les haltères avec une prise neutre, les bras tendus devant les cuisses", "Gardez les épaules basses et le dos droit, maintenez une bonne posture tout au long de l''exercice", "Soulevez les haltères en arc contrôlé directement devant vous jusqu''à hauteur d''épaule", "Faites une pause en haut, puis redescendez lentement les poids à la position de départ", "Maintenez les bras droits pendant toute la montée et la descente"]', '["Contractez votre ceinture abdominale pour éviter de balancer ou d''utiliser l''élan", "Arrêtez-vous à hauteur d''épaule pour éviter l''impingement et préserver la forme", "Choisissez un poids qui vous permet de contrôler le mouvement sans balancer", "Concentrez-vous sur les deltoïdes antérieurs qui travaillent, sans impliquer le dos ou les jambes", "Ayez légèrement les genoux fléchis et évitez de bloquer complètement les coudes"]', '["Keep your core engaged to prevent swaying or using momentum", "Stop at shoulder height to avoid impingement and maintain proper form", "Use a weight that allows you to control the movement without swinging", "Focus on the front deltoids doing the work rather than using your back or legs", "Maintain a slight bend in your knees and avoid locking out your elbows completely"]', 'e42e2ca3-664b-48bd-8cf7-e8a4313618bb', 'standing-dumbbell-straight-arm-front-delt', NULL, NULL);
INSERT INTO public.exercises VALUES ('b6d80515-8f5b-41ad-a6c8-6909e132de22', 'Planche', NULL, NULL, 'Plank', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank.jpg', NULL, '["Garde les hanches niveau et évite de les laisser s''affaisser ou de trop les lever", "Contracte bien les muscles du tronc tout au long de l''exercice", "Répartis le poids de manière uniforme entre les mains pour éviter de fatiguer les poignets", "Arrête l''exercice si tu ressens une douleur dans le bas du dos ou si tu ne peux plus maintenir la bonne posture", "Commence par des maintiens plus courts et augmente progressivement la durée à mesure que ta force s''améliore"]', '["Mains mal placées, pas sous les épaules", "Hanches trop hautes ou trop basses"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank"]', true, '2026-04-03 12:24:58.274384+00', '2026-04-03 12:24:58.274384+00', 'Position de départ : Mets-toi en position de planche, mains sous les épaules, corps bien droit des pieds à la tête, et pieds écartés à la largeur des hanches. Execution : Tiens cette position statique en gardant une bonne alignement et en engageant les muscles du tronc pendant tout l''exercice.', '["Mains mal placées, pas sous les épaules", "Hanches trop hautes ou trop basses"]', true, '["Place hands directly under shoulders with fingers spread wide for stability", "Position feet hip-width apart with toes tucked under", "Create a straight line from head to heels by engaging your core and glutes", "Keep your neck in neutral position by looking down at the mat", "Breathe steadily while holding the position for the desired duration", "Lower to knees when you can no longer maintain proper form"]', '["Positionne tes mains directement sous les épaules en écartant bien les doigts pour plus de stabilité", "Place tes pieds à la largeur des hanches avec les orteils repliés sous", "Crée une ligne droite de la tête aux talons en engageant ton tronc et tes fessiers", "Garde le cou dans une position neutre en regardant vers le sol", "Respire régulièrement tout en maintenant la position pour la durée souhaitée", "Abaisse-toi sur les genoux si tu ne peux plus garder une bonne forme"]', '["Garde les hanches niveau et évite de les laisser s''affaisser ou de trop les lever", "Contracte bien les muscles du tronc tout au long de l''exercice", "Répartis le poids de manière uniforme entre les mains pour éviter de fatiguer les poignets", "Arrête l''exercice si tu ressens une douleur dans le bas du dos ou si tu ne peux plus maintenir la bonne posture", "Commence par des maintiens plus courts et augmente progressivement la durée à mesure que ta force s''améliore"]', '["Keep hips level and avoid sagging or piking up", "Engage your core muscles throughout the entire hold", "Distribute weight evenly between hands to avoid wrist strain", "Stop the exercise if you feel lower back pain or cannot maintain proper form", "Start with shorter holds and gradually increase duration as strength improves"]', '61410917-4fb1-41f8-86d5-16dc88fe380b', 'plank', NULL, NULL);
INSERT INTO public.exercises VALUES ('a145a48b-dd8b-4b55-b324-11e63fe4b547', 'Étirement des Ischio-jambiers Debout', NULL, 'تمارين إطالة عضلات الفخذ الخلفي', 'Standing Hamstring Stretch (R)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/standing-hamstring-stretch-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-hamstring-stretch-r.jpg', NULL, '["Garde la jambe étirée complètement droite pour cibler efficacement les ischio-jambiers.", "Incline-toi depuis les hanches pour éviter de courber le dos et de solliciter le bas du dos.", "Étirer seulement jusqu''à ressentir une tension légère, jamais jusqu''à la douleur.", "Maintiens une respiration régulière pendant l''étirement et évite les mouvements de balancement.", "Concentre ton poids sur ta jambe de soutien pour une meilleure équilibre et contrôle."]', '["Ne pas garder la jambe droite, ce qui réduit l''efficacité de l''étirement.", "Courber le dos au lieu de pivoter depuis les hanches, ce qui peut causer des douleurs lombaires."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "standing hamstring stretch (r)"]', true, '2026-04-03 12:24:59.552554+00', '2026-04-03 12:24:59.552554+00', 'Position de départ : Tiens-toi bien droit, les pieds écartés à la largeur des hanches, puis avance ton pied droit d''environ 60 à 90 cm. Fléchis ton pied droit pour que seul le talon touche le sol. Exécution : Garde ta jambe droite et penche-toi en avant depuis les hanches en gardant le dos droit jusqu''à ressentir une tension à l''arrière de ta cuisse droite.', '["Ne pas garder la jambe droite, ce qui réduit l''efficacité de l''étirement.", "Courber le dos au lieu de pivoter depuis les hanches, ce qui peut causer des douleurs lombaires."]', true, '["Stand with feet hip-width apart and step your right foot forward 2-3 feet", "Flex your right foot upward so only the heel remains on the ground", "Keep your right leg completely straight and your left leg slightly bent for support", "Hinge forward at the hips while keeping your back straight and chest up", "Lower your torso until you feel a moderate stretch in your right hamstring", "Hold the stretch for 20-30 seconds while breathing normally"]', '["Tiens-toi droit, les pieds à la largeur des hanches, et avance ton pied droit de 60 à 90 cm.", "Fléchis ton pied droit vers le haut pour que seul le talon soit en contact avec le sol.", "Garde ta jambe droite complètement tendue et plie légèrement la jambe gauche pour le soutien.", "Incline-toi en avant depuis les hanches tout en gardant le dos droit et la poitrine en avant.", "Abaisse ton torse jusqu''à sentir un étirement modéré dans ton ischio-jambier droit.", "Reste dans cette position pendant 20 à 30 secondes en respirant normalement."]', '["Garde la jambe étirée complètement droite pour cibler efficacement les ischio-jambiers.", "Incline-toi depuis les hanches pour éviter de courber le dos et de solliciter le bas du dos.", "Étirer seulement jusqu''à ressentir une tension légère, jamais jusqu''à la douleur.", "Maintiens une respiration régulière pendant l''étirement et évite les mouvements de balancement.", "Concentre ton poids sur ta jambe de soutien pour une meilleure équilibre et contrôle."]', '["Keep the stretched leg completely straight to effectively target the hamstring muscles", "Hinge from your hips rather than rounding your back to prevent lower back strain", "Only stretch to the point of mild tension, never to the point of pain", "Maintain steady breathing throughout the stretch and avoid bouncing movements", "Keep most of your weight on your supporting leg for better balance and control"]', '75593cee-6a28-4842-8222-150647b2157b', 'standing-hamstring-stretch-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('5ebb0cec-0819-47a7-bb3d-456a46111f3e', 'Tirage bas avec câble debout', NULL, 'تيراج عادي بالكابل', 'Standing Low Cable Row', 'Back', '[]', 'Back', 'Intermediate', 4, '/videos/back/standing-low-cable-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-low-cable-row.jpg', NULL, '["Garde les épaules basses et en arrière tout au long du mouvement pour éviter les douleurs d''épaule", "Concentre-toi sur le fait de tirer avec les muscles du dos avant les bras : pense à serrer les omoplates d''abord", "Maintiens une colonne vertébrale neutre, évite de arrondir le dos ou de te pencher trop en avant pendant l''exercice", "Contrôle la phase négative du mouvement pour maximiser l''engagement musculaire et éviter que le poids ne chute brusquement"]', '["Tirer les coudes trop loin des hanches", "Avoir le dos arrondi au lieu de garder une posture neutre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "standing low cable row"]', true, '2026-04-03 12:24:59.575248+00', '2026-04-03 12:24:59.575248+00', 'Position de départ : Tiens-toi face à un treuil bas avec une prise pronation (paumes vers le bas). Exécution : Tire la poignée vers le bas-ventre en gardant les coudes près du corps, puis retourne lentement à la position de départ.', '["Tirer les coudes trop loin des hanches", "Avoir le dos arrondi au lieu de garder une posture neutre"]', true, '["Set the cable pulley to the lowest position and attach a straight bar or V-handle", "Stand 2-3 feet away from the machine with feet hip-width apart and knees slightly bent", "Grasp the handle with both hands using an overhand grip, arms extended but not locked out", "Keep your core engaged and maintain a slight forward lean from your hips throughout the movement", "Pull the handle toward your lower chest by driving your elbows back and squeezing your shoulder blades together", "Slowly return to the starting position with control, maintaining tension in the cable"]', '["Régle le treuil à la position la plus basse et attache une barre droite ou une poignée en V", "Place-toi à 60-90 cm de la machine, les pieds à la largeur des hanches et les genoux légèrement fléchis", "Saisis la poignée avec les deux mains en prise pronation, bras tendus sans verrouiller les coudes", "Engage ton cœur et penche-toi légèrement en avant depuis les hanches durant tout le mouvement", "Tire la poignée vers ton bas-poitrine en poussant les coudes vers l''arrière et en serrant les omoplates", "Retourne lentement à la position de départ avec contrôle, en maintenant la tension dans le câble"]', '["Garde les épaules basses et en arrière tout au long du mouvement pour éviter les douleurs d''épaule", "Concentre-toi sur le fait de tirer avec les muscles du dos avant les bras : pense à serrer les omoplates d''abord", "Maintiens une colonne vertébrale neutre, évite de arrondir le dos ou de te pencher trop en avant pendant l''exercice", "Contrôle la phase négative du mouvement pour maximiser l''engagement musculaire et éviter que le poids ne chute brusquement"]', '["Keep your shoulders down and back throughout the entire movement to avoid shoulder impingement", "Focus on initiating the pull with your back muscles rather than your arms by thinking about squeezing your shoulder blades together first", "Maintain a neutral spine and avoid rounding your back or leaning too far forward during the exercise", "Control the negative portion of the movement to maximize muscle engagement and prevent the weight stack from slamming"]', '94b012da-2a8d-449c-8a25-80cc1b0a1ba7', 'standing-low-cable-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('f7878547-1d46-46dd-8f34-ff204cf2dc9d', 'Élévation Triceps Unilatérale Debout (Gauche)', NULL, NULL, 'Standing One-Arm DB Triceps ExtensioN (L)', 'Triceps', '[]', 'Triceps', 'Intermediate', 2, '/videos/triceps/standing-one-arm-db-triceps-extension-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-one-arm-db-triceps-extension-l.jpg', NULL, '["Garde ton bras supérieur vertical et évite qu''il ne bouge vers l''avant pendant le mouvement", "Si besoin, utilise ta main libre pour soutenir ton bras de travail au niveau du coude pour plus de stabilité", "Contrôle le poids lors de la phase de descente pour éviter toute blessure au niveau du coude", "Commence avec un poids léger pour maîtriser la forme avant d''augmenter la charge", "Maintiens une colonne vertébrale neutre et évite de cambrer excessivement le dos."]', '["Ne pas garder le coude près de la tête, ce qui peut réduire l''efficacité de l''exercice", "Se pencher en arrière ou cambrer le dos, entraînant un risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "dumbbell", "standing one-arm db triceps extension (l)"]', true, '2026-04-03 12:24:59.585121+00', '2026-04-03 12:24:59.585121+00', 'Prépare-toi à sculpter tes triceps ! Tiens-toi bien droit, les pieds écartés à la largeur des épaules, un haltère dans la main gauche, le bras tendu au-dessus de ta tête. Garde ton bras supérieur proche de ta tête, et prépare-toi à descendre.', '["Ne pas garder le coude près de la tête, ce qui peut réduire l''efficacité de l''exercice", "Se pencher en arrière ou cambrer le dos, entraînant un risque de blessure."]', true, '["Stand with feet shoulder-width apart and engage your core for stability", "Hold the dumbbell in your left hand and extend your arm straight overhead", "Keep your upper arm stationary and close to your head throughout the movement", "Slowly lower the dumbbell behind your head by bending only at the elbow until you feel a stretch in your triceps", "Press the dumbbell back up to the starting position by extending your elbow", "Complete all repetitions on the left arm before switching to the right"]', '["Tiens-toi droit, les pieds écartés à la largeur des épaules et active ton tronc pour la stabilité", "Prends l''haltère avec la main gauche et étends ton bras bien droit au-dessus de ta tête", "Maintiens ton bras supérieur immobile et proche de ta tête pendant tout le mouvement", "Descends lentement l''haltère derrière ta tête en pliant uniquement au niveau du coude jusqu''à sentir une étirement dans tes triceps", "Remonte l''haltère à la position de départ en tendant le coude", "Réalise toutes les répétitions avec le bras gauche avant de passer au droit."]', '["Garde ton bras supérieur vertical et évite qu''il ne bouge vers l''avant pendant le mouvement", "Si besoin, utilise ta main libre pour soutenir ton bras de travail au niveau du coude pour plus de stabilité", "Contrôle le poids lors de la phase de descente pour éviter toute blessure au niveau du coude", "Commence avec un poids léger pour maîtriser la forme avant d''augmenter la charge", "Maintiens une colonne vertébrale neutre et évite de cambrer excessivement le dos."]', '["Keep your upper arm vertical and avoid letting it drift forward during the movement", "Use your free hand to support your working arm at the elbow if needed for stability", "Control the weight during the lowering phase to prevent injury to the elbow joint", "Start with lighter weight to master the form before progressing to heavier loads", "Maintain neutral spine and avoid arching your back excessively"]', '6744d5a4-41a7-42b5-9383-f7f6eccf43cb', 'standing-one-arm-db-triceps-extension-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('245bbb27-d803-4de6-8d9f-4aaad866ff05', 'Curl inversé debout', NULL, 'Curl m3aks', 'Standing Reverse Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 1, '/videos/biceps/standing-reverse-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-reverse-curl.jpg', NULL, '["Utilise une prise en pronation pour cibler les extenseurs des avant-bras, contrairement aux curls biceps habituels.", "Garde les bras supérieurs complètement immobiles - seuls tes avant-bras et poignets doivent bouger.", "Commence avec un poids plus léger que pour les curls classiques, car cet exercice cible spécifiquement les petits muscles des avant-bras.", "Contrôle la descente pour maximiser l''engagement musculaire.", "Évite d''utiliser l''élan ou de balancer le poids."]', '["Ne pas garder les bras supérieurs fixes, ce qui peut réduire l''efficacité de l''exercice.", "Utiliser un poids trop lourd, ce qui peut compromettre la forme et augmenter le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["forearms", "barbell", "standing reverse curl"]', true, '2026-04-03 12:24:59.619481+00', '2026-04-03 12:24:59.619481+00', 'Position de départ : Tiens-toi debout, barre en main avec une prise pronation, bras tendus devant toi et la barre reposant sur tes cuisses. Exécution : Fléchis les poignets et les avant-bras pour soulever la barre, sans bouger tes bras supérieurs. Redescends lentement à la position de départ.', '["Ne pas garder les bras supérieurs fixes, ce qui peut réduire l''efficacité de l''exercice.", "Utiliser un poids trop lourd, ce qui peut compromettre la forme et augmenter le risque de blessure."]', true, '["Stand with feet shoulder-width apart and grip the barbell with an overhand grip, hands about shoulder-width apart", "Keep your upper arms pressed against your sides throughout the entire movement", "Slowly curl the barbell up by flexing your wrists and contracting your forearms", "Pause briefly at the top of the movement when your wrists are fully flexed", "Lower the barbell back down in a controlled manner to the starting position", "Maintain tension in your forearms throughout the entire range of motion"]', '["Place tes pieds à la largeur des épaules et prends la barre avec une prise en pronation, mains à la largeur des épaules.", "Garde les bras supérieurs pressés contre tes flancs tout au long du mouvement.", "Relevez lentement la barre en fléchissant les poignets et en contractant les avant-bras.", "Marque une courte pause en haut, lorsque tes poignets sont complètement fléchis.", "Redescends la barre de manière contrôlée jusqu''à la position de départ.", "Maintiens la tension dans tes avant-bras pendant tout le mouvement."]', '["Utilise une prise en pronation pour cibler les extenseurs des avant-bras, contrairement aux curls biceps habituels.", "Garde les bras supérieurs complètement immobiles - seuls tes avant-bras et poignets doivent bouger.", "Commence avec un poids plus léger que pour les curls classiques, car cet exercice cible spécifiquement les petits muscles des avant-bras.", "Contrôle la descente pour maximiser l''engagement musculaire.", "Évite d''utiliser l''élan ou de balancer le poids."]', '["Use an overhand grip which is opposite to regular bicep curls to target the forearm extensors", "Keep your upper arms completely stationary - only your forearms and wrists should move", "Start with lighter weight than you would use for regular curls as this exercise specifically targets smaller forearm muscles", "Control the negative portion of the movement to maximize muscle engagement", "Avoid using momentum or swinging the weight"]', 'ec29a267-b5bc-406d-ae9a-043887d1dc06', 'standing-reverse-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('70da232d-ddfe-490e-9afb-2e0c1bbd80e0', 'Fente Statique sur Machine', NULL, 'فنت ستاتيكي على الماكينة', 'Static Lunge on Machine', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/static-lunge-on-machine.mp4', NULL, NULL, NULL, '/videos/thumbnails/static-lunge-on-machine.jpg', NULL, '["Garde l''essentiel de ton poids sur la jambe avant pendant tout le mouvement.", "Évite que ton genou avant ne dépasse tes orteils en descendant.", "Maintiens le dos droit sans te pencher en avant ou en arrière pendant l''exercice.", "Descends de manière contrôlée, sans rebondir en bas du mouvement.", "Assure-toi que ton genou avant est aligné avec tes orteils pour prévenir les douleurs au genou."]', '["Ne pas garder le dos droit et se pencher en avant.", "Ne pas porter assez de poids sur la jambe avant, ce qui peut réduire l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "static lunge on machine"]', true, '2026-04-03 12:24:59.648629+00', '2026-04-03 12:24:59.648629+00', 'Position de départ : Installe-toi sur la machine de fente statique avec un pied devant et l''autre derrière. Exécution : Descends ton corps vers le sol en pliant les deux genoux, puis pousse vers le haut pour revenir à la position de départ. Change de jambe et recommence !', '["Ne pas garder le dos droit et se pencher en avant.", "Ne pas porter assez de poids sur la jambe avant, ce qui peut réduire l''efficacité de l''exercice."]', true, '["Position yourself on the machine platform with feet hip-width apart in a split stance", "Place your front foot flat on the platform and your back foot on the ball of the foot", "Engage your core and maintain an upright torso throughout the movement", "Lower your body by bending both knees simultaneously until your front thigh reaches parallel", "Push through your front heel to drive back up to the starting position", "Complete all repetitions on one leg before switching to the other side"]', '["Positionne-toi sur la plateforme de la machine, pieds écartés à la largeur des hanches dans une position écartée.", "Place ton pied avant à plat sur la plateforme et l''arrière sur la pointe des pieds.", "Contracte ton ventre et garde le torse droit tout au long de l''exercice.", "Descends en pliant les deux genoux en même temps jusqu''à ce que ta cuisse avant soit parallèle au sol.", "Pousse avec ton talon avant pour revenir à la position de départ.", "Termine toutes les répétitions sur une jambe avant de changer de côté."]', '["Garde l''essentiel de ton poids sur la jambe avant pendant tout le mouvement.", "Évite que ton genou avant ne dépasse tes orteils en descendant.", "Maintiens le dos droit sans te pencher en avant ou en arrière pendant l''exercice.", "Descends de manière contrôlée, sans rebondir en bas du mouvement.", "Assure-toi que ton genou avant est aligné avec tes orteils pour prévenir les douleurs au genou."]', '["Keep most of your weight on your front leg throughout the entire movement", "Avoid allowing your front knee to drift forward past your toes during the descent", "Maintain a straight back and avoid leaning forward or backward during the exercise", "Lower yourself in a controlled manner and avoid bouncing at the bottom of the movement", "Ensure your front knee tracks in line with your toes to prevent knee strain"]', 'da74be26-d3ba-403a-a16d-28ff3cf12396', 'static-lunge-on-machine', NULL, NULL);
INSERT INTO public.exercises VALUES ('0454199a-53c0-4f90-b556-a974d0d10d02', 'Crunch étoile et demi V-ups', NULL, NULL, 'Star crunch into Half V- ups', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/star-crunch-into-half-v-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/star-crunch-into-half-v-ups.jpg', NULL, '["Maintiens le bas du dos collé au sol pendant le crunch pour protéger ta colonne vertébrale.", "Concentre-toi sur l''activation de tes muscles abdominaux, pas sur l''élan, pour les deux mouvements.", "Expire pendant les phases d''effort et inhale en redescendant.", "Garde le contrôle pendant l''exécution des mouvements, évite de te précipiter.", "Si tu ressens une tension au cou, mets une main derrière ta tête pour te soutenir pendant les crunchs."]', '["Ne pas activer correctement le ventre, ce qui peut entraîner des douleurs lombaires.", "Ne pas descendre complètement à chaque répétition, réduisant ainsi l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "star crunch into half v- ups"]', true, '2026-04-03 12:24:59.640609+00', '2026-04-03 12:24:59.640609+00', 'Commence en te couchant sur le dos, bras et jambes écartés en forme d''étoile. Exécute le mouvement en ramenant simultanément les genoux vers ta poitrine tout en soulevant le torse et en atteignant les bras vers l''avant. Redescends ensuite en position étoile puis enchaîne avec un demi V-up en levant les jambes et le torse pour former un V.', '["Ne pas activer correctement le ventre, ce qui peut entraîner des douleurs lombaires.", "Ne pas descendre complètement à chaque répétition, réduisant ainsi l''efficacité de l''exercice."]', true, '["Lie flat on your back with arms extended overhead and legs spread wide in a star formation", "Engage your core and simultaneously bring your knees toward your chest while lifting your shoulders off the ground", "Reach your arms forward toward your knees as you crunch up, then slowly lower back to the star position", "Immediately transition into a half V-up by keeping your legs straight and lifting them while raising your torso", "Reach your arms toward your feet at the top of the V position", "Lower with control back to the starting star position and repeat the sequence"]', '["Allonge-toi sur le dos, bras tendus vers le plafond et jambes écartées en forme d''étoile.", "Active ton ventre et ramène tes genoux vers ta poitrine tout en soulevant tes épaules du sol.", "Tends les bras vers tes genoux en te courbant, puis redescends à la position étoile.", "Transitionne immédiatement en demi V-up en gardant les jambes droites et en soulevant le torse.", "Pointe les bras vers tes pieds en haut de la position V.", "Redescends avec contrôle à la position étoile et répète la séquence."]', '["Maintiens le bas du dos collé au sol pendant le crunch pour protéger ta colonne vertébrale.", "Concentre-toi sur l''activation de tes muscles abdominaux, pas sur l''élan, pour les deux mouvements.", "Expire pendant les phases d''effort et inhale en redescendant.", "Garde le contrôle pendant l''exécution des mouvements, évite de te précipiter.", "Si tu ressens une tension au cou, mets une main derrière ta tête pour te soutenir pendant les crunchs."]', '["Keep your lower back pressed against the floor during the star crunch portion to protect your spine", "Focus on using your core muscles rather than momentum to perform both movements", "Breathe out during the exertion phases and inhale as you lower back down", "Maintain control throughout both movements rather than rushing through the exercise", "If you experience neck strain, place one hand behind your head for support during the crunching motions"]', '3bf0aada-8142-418e-8f7b-f506ecc63afb', 'star-crunch-into-half-v-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('48fcb07c-63e7-42f1-a705-0ba8455446bf', 'Superman Extensions', NULL, 'تمارين سوبرمان', 'Superman extensions', 'Back', '[]', 'Back', 'Intermediate', 16, '/videos/back/superman-extensions.mp4', NULL, NULL, NULL, '/videos/thumbnails/superman-extensions.jpg', NULL, '["Réalise les mouvements lentement et de manière contrôlée pour éviter les tensions dans le bas du dos", "Ne soulève que jusqu''à la hauteur où tu te sens à l''aise - un mouvement excessif peut entraîner des blessures", "Active tes muscles abdominaux tout au long de l''exercice pour protéger ta colonne vertébrale", "Évite de retenir ta respiration durant la phase de maintien", "Concentre-toi sur la qualité des mouvements plutôt que sur la quantité, en gardant une bonne forme à chaque répétition"]', '["Soulever le torse trop haut peut causer des douleurs", "Retenir sa respiration durant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "superman extensions"]', true, '2026-04-03 12:24:59.675785+00', '2026-04-03 12:24:59.675785+00', 'Allonge-toi face contre terre, bras tendus en avant et jambes droites. La tête repose sur le sol. Prêt à renforcer ton dos ? Simule le vol du Superman en soulevant simultanément ton torse, tes bras et tes jambes. Tiens la position quelques secondes, puis redescends lentement.', '["Soulever le torse trop haut peut causer des douleurs", "Retenir sa respiration durant l''exercice"]', true, '["Lie face down on a mat with arms extended overhead and legs straight", "Keep your forehead down and maintain a neutral neck position throughout the movement", "Simultaneously lift your chest, arms, and legs off the ground by squeezing your glutes and back muscles", "Hold the lifted position for 2-3 seconds while breathing normally", "Slowly lower your chest, arms, and legs back to the starting position with control", "Rest briefly between repetitions to maintain proper form"]', '["Allonge-toi face contre terre sur un tapis avec bras tendus et jambes droites", "Garde le front au sol et maintiens une position neutre de la tête tout au long de l''exercice", "Soulève simultanément ton torse, tes bras et tes jambes en contractant tes muscles du dos et des fessiers", "Maintiens la position relevée pendant 2-3 secondes tout en respirant normalement", "Redescends lentement ton torse, bras et jambes au sol de manière contrôlée", "Fais une courte pause entre les répétitions pour assurer une bonne forme"]', '["Réalise les mouvements lentement et de manière contrôlée pour éviter les tensions dans le bas du dos", "Ne soulève que jusqu''à la hauteur où tu te sens à l''aise - un mouvement excessif peut entraîner des blessures", "Active tes muscles abdominaux tout au long de l''exercice pour protéger ta colonne vertébrale", "Évite de retenir ta respiration durant la phase de maintien", "Concentre-toi sur la qualité des mouvements plutôt que sur la quantité, en gardant une bonne forme à chaque répétition"]', '["Keep movements slow and controlled to avoid straining the lower back", "Only lift as high as comfortable - excessive range of motion can cause injury", "Engage your core muscles throughout the exercise to support your spine", "Avoid holding your breath during the hold phase", "Focus on quality over quantity, maintaining proper form throughout all repetitions"]', '2a4df469-77c8-4468-92cb-2003c90602dd', 'superman-extensions', NULL, NULL);
INSERT INTO public.exercises VALUES ('c65f1546-6c95-46ae-bae0-71df34f09127', 'Pulsations en planche latérale', NULL, NULL, 'Side plank pulses', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-plank-pulses.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-plank-pulses.jpg', NULL, '["Assure-toi que ton coude reste sous ton épaule pour protéger ton articulation.", "Maintiens une ligne droite dans ton corps, sans laisser tes hanches s''enfoncer ou remonter.", "Active tes muscles du core tout au long de l''exercice pour protéger le bas de ton dos.", "Effectue de petites pulsations contrôlées, évite les mouvements amples et saccadés.", "N''oublie pas de respirer régulièrement, ne bloque pas ta respiration."]', '["Laisser les hanches s''affaisser.", "Ne pas engager le centre durant l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side plank pulses"]', true, '2026-04-03 12:24:59.08098+00', '2026-04-03 12:24:59.08098+00', 'Mets-toi sur le côté, ton avant-bras au sol, coude sous l''épaule, en ligne droite de la tête aux pieds. Lève les hanches pour entrer en position de planche latérale et fais des petites pulsations tout en maintenant cette position stable.', '["Laisser les hanches s''affaisser.", "Ne pas engager le centre durant l''exercice."]', true, '["Lie on your side with your bottom forearm flat on the mat, elbow positioned directly under your shoulder", "Stack your feet on top of each other or stagger them for better stability", "Engage your core and lift your hips off the ground to create a straight line from your head to your feet", "Perform small controlled pulses by slightly lowering and raising your hips while maintaining the side plank position", "Keep your top hand placed on your hip or extended toward the ceiling for balance", "Hold the side plank position throughout the pulsing movement without letting your hips drop to the floor"]', '["Allonge-toi sur le côté, l''avant-bras à plat sur le tapis, le coude bien sous l''épaule.", "Place tes pieds l''un sur l''autre ou décalés pour plus de stabilité.", "Engage ton centre et soulève tes hanches du sol pour aligner ta tête et tes pieds.", "Effectue des pulsations contrôlées en abaissant et en relevant légèrement les hanches sans perdre la position de planche.", "Garde ta main supérieure sur la hanche ou tendue vers le plafond pour l''équilibre.", "Maintiens la position de planche latérale pendant tout le mouvement, sans laisser les hanches retomber. C''est essentiel !"]', '["Assure-toi que ton coude reste sous ton épaule pour protéger ton articulation.", "Maintiens une ligne droite dans ton corps, sans laisser tes hanches s''enfoncer ou remonter.", "Active tes muscles du core tout au long de l''exercice pour protéger le bas de ton dos.", "Effectue de petites pulsations contrôlées, évite les mouvements amples et saccadés.", "N''oublie pas de respirer régulièrement, ne bloque pas ta respiration."]', '["Keep your elbow directly under your shoulder to avoid strain on the shoulder joint", "Maintain a straight line through your body - avoid letting your hips sag or pike up", "Engage your core muscles throughout the entire movement to protect your lower back", "Keep the pulsing movements small and controlled rather than large bouncing motions", "Breathe steadily throughout the exercise and avoid holding your breath"]', '516a33ee-e1e1-459d-9417-a313b313e1a6', 'side-plank-pulses', NULL, NULL);
INSERT INTO public.exercises VALUES ('a8267958-3b8b-4894-ac03-41701c327453', 'Fente Alternée et Burpees', NULL, NULL, 'Switching Lunges into Burpees', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/switching-lunges-into-burpees.mp4', NULL, NULL, NULL, '/videos/thumbnails/switching-lunges-into-burpees.jpg', NULL, '["Garde ton genou avant aligné au-dessus de ta cheville pendant les fentes pour éviter les douleurs au genou", "Atterris doucement sur les orteils lors des transitions de saut pour réduire l''impact sur les articulations", "Maintiens ton ventre engagé tout au long des mouvements pour protéger le bas de ton dos", "Commence par moins de répétitions et augmente progressivement ton endurance, car c''est un exercice à haute intensité", "Assure-toi d''avoir une bonne forme plutôt que d''aller vite - un mouvement de qualité prévient les blessures"]', '["Ne pas plier correctement le genou avant lors des fentes", "Sauter trop fortement et atterrir de manière brutale sur les articulations"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "switching lunges into burpees"]', true, '2026-04-03 12:24:59.696989+00', '2026-04-03 12:24:59.696989+00', 'Position de départ : reste debout, les pieds écartés à la largeur des hanches, le ventre engagé, les mains sur les côtés. Exécution : alterne des fentes sautées pendant un certain nombre de répétitions, puis descends directement dans une séquence de burpees avant de revenir au schéma des fentes.', '["Ne pas plier correctement le genou avant lors des fentes", "Sauter trop fortement et atterrir de manière brutale sur les articulations"]', true, '["Begin with alternating jump lunges, landing softly with your front knee at 90 degrees and back knee hovering above the ground", "After completing your desired lunge reps, immediately place both hands on the ground and jump your feet back into plank position", "Perform a push-up while maintaining a straight body line from head to heels", "Jump your feet back toward your hands and explosively jump up with arms overhead to complete the burpee", "Return to the starting standing position and repeat the entire sequence", "Maintain controlled breathing throughout the entire movement pattern"]', '["Commence par des fentes sautées alternées, en atterrissant doucement avec le genou avant à 90 degrés et le genou arrière juste au-dessus du sol", "Après avoir terminé le nombre de répétitions souhaité, pose les mains au sol et saute en position de planche", "Effectue une pompe en gardant une ligne droite du sommet de la tête aux talons", "Ramène tes pieds vers tes mains et saute explosivement en levant les bras au-dessus de la tête pour terminer le burpee", "Retourne à la position debout et répète toute la séquence", "Maintiens une respiration contrôlée tout au long du mouvement"]', '["Garde ton genou avant aligné au-dessus de ta cheville pendant les fentes pour éviter les douleurs au genou", "Atterris doucement sur les orteils lors des transitions de saut pour réduire l''impact sur les articulations", "Maintiens ton ventre engagé tout au long des mouvements pour protéger le bas de ton dos", "Commence par moins de répétitions et augmente progressivement ton endurance, car c''est un exercice à haute intensité", "Assure-toi d''avoir une bonne forme plutôt que d''aller vite - un mouvement de qualité prévient les blessures"]', '["Keep your front knee aligned over your ankle during lunges to prevent knee strain", "Land softly on the balls of your feet during jump transitions to reduce impact on joints", "Maintain core engagement throughout both movements to protect your lower back", "Start with fewer reps and build endurance gradually as this is a high-intensity combination exercise", "Ensure proper form over speed - quality movement patterns prevent injury"]', 'c7dead12-7c46-4533-a0e9-dbc882cc498b', 'switching-lunges-into-burpees', NULL, NULL);
INSERT INTO public.exercises VALUES ('aeec7391-7385-4e24-9ecf-d0bdfda8beec', 'Planche haute avec genou serré alterné', NULL, NULL, 'High plank alternating single leg knee tuck', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/high-plank-alternating-single-leg-knee-tuc.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-plank-alternating-single-leg-knee-tuc.jpg', NULL, '["Garde ton gainage actif pour éviter que tes hanches ne s''affaissent ou que ton dos ne se cambrent.", "Assure-toi de maintenir une ligne droite des pieds à la tête tout au long du mouvement.", "Contrôle le mouvement, évite de te précipiter pour ne pas perdre ta forme.", "Garde les mains bien ancrées et les épaules stables au-dessus des poignets.", "Évite que tes hanches ne montent ou ne descendent pendant les serrés de genoux."]', '["Ne pas maintenir un gainage solide, ce qui peut entraîner un affaissement des hanches.", "Accélérer le mouvement et perdre en contrôle, ce qui risque de nuire à ta forme."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "high plank alternating single leg knee tuck"]', true, '2026-04-03 12:24:57.114921+00', '2026-04-03 12:24:57.114921+00', 'Position de départ : Commence en position de planche haute, mains sous les épaules, corps en ligne droite des pieds à la tête. Exécution : Alterne en ramenant un genou vers la poitrine tout en maintenant la position de planche, puis ramène la jambe à la position de départ avant de changer de côté.', '["Ne pas maintenir un gainage solide, ce qui peut entraîner un affaissement des hanches.", "Accélérer le mouvement et perdre en contrôle, ce qui risque de nuire à ta forme."]', true, '["Start in a high plank position with hands directly under shoulders and body in a straight line", "Engage your core and keep hips level throughout the movement", "Bring one knee toward your chest in a controlled motion", "Return the leg to starting position with control", "Alternate legs, bringing the opposite knee toward chest", "Maintain steady breathing throughout the exercise"]', '["Commence en position de planche haute, mains sous les épaules et corps en ligne droite.", "Active ton gainage et garde les hanches au niveau pendant tout le mouvement.", "Rapproche un genou de ta poitrine de manière contrôlée.", "Ramène la jambe à la position de départ avec contrôle.", "Alterne les jambes en ramenant l''autre genou vers ta poitrine.", "Respire de manière régulière tout au long de l''exercice."]', '["Garde ton gainage actif pour éviter que tes hanches ne s''affaissent ou que ton dos ne se cambrent.", "Assure-toi de maintenir une ligne droite des pieds à la tête tout au long du mouvement.", "Contrôle le mouvement, évite de te précipiter pour ne pas perdre ta forme.", "Garde les mains bien ancrées et les épaules stables au-dessus des poignets.", "Évite que tes hanches ne montent ou ne descendent pendant les serrés de genoux."]', '["Keep your core engaged to prevent sagging hips or arching your back", "Maintain a straight line from head to heels throughout the movement", "Control the movement rather than rushing to prevent losing form", "Keep hands firmly planted and shoulders stable over wrists", "Avoid letting hips pike up or drop down during the knee tucks"]', '8be51cd5-3ed1-489e-9975-5d9141880055', 'high-plank-alternating-single-leg-knee-tuc', NULL, NULL);
INSERT INTO public.exercises VALUES ('d5b4b3b6-43e5-4c66-bd66-00abb71d192e', 'T-Bar Row', NULL, 'تار بار رَو', 'T-Bar Row', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/t-bar-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/t-bar-row.jpg', NULL, '["Garde la poitrine haute et les épaules en arrière pour maintenir un bon alignement de la colonne vertébrale et éviter d''arrondir le haut du dos", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement avec tes omoplates", "Évite d''utiliser de l''élan ou de balancer le poids, cela réduit l''activation musculaire et augmente le risque de blessure", "Maintiens la tension dans ton cœur tout au long du mouvement pour protéger ton bas du dos"]', '["Resserrer les épaules et arrondir le dos pendant le tirage", "Utiliser trop de poids, ce qui compromet la technique et augmente le risque de blessure"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "t-bar row"]', true, '2026-04-03 12:24:59.723256+00', '2026-04-03 12:24:59.723256+00', 'Position de départ : Prends la barre T avec une prise en pronation (paumes vers le bas). Exécution : Tire la barre vers ta poitrine en gardant le dos droit, puis redescends lentement à la position de départ.', '["Resserrer les épaules et arrondir le dos pendant le tirage", "Utiliser trop de poids, ce qui compromet la technique et augmente le risque de blessure"]', true, '["Position feet firmly on either side of the barbell with knees slightly bent and maintain a neutral spine throughout the movement", "Hinge forward at the hips until your torso is at approximately a 45-degree angle to the floor", "Grip the barbell with both hands using an overhand grip, hands positioned close together near the weighted end", "Engage your core and pull the barbell up toward your lower chest by driving your elbows straight back", "Squeeze your shoulder blades together at the top of the movement and pause briefly", "Lower the weight slowly and under control back to the starting position"]', '["Place tes pieds fermement de chaque côté de la barre avec les genoux légèrement fléchis et maintiens une colonne vertébrale neutre pendant tout le mouvement", "Incline-toi en avant au niveau des hanches jusqu''à ce que ton torse soit à environ 45 degrés par rapport au sol", "Prends la barre avec les deux mains en utilisant une prise en pronation, les mains proches de l’extrémité lestée", "Engage ton cœur et tire la barre vers ta partie inférieure de la poitrine en poussant tes coudes vers l''arrière", "Contracte tes omoplates en haut du mouvement et fais une légère pause", "Abaisse le poids lentement et sous contrôle jusqu''à la position de départ"]', '["Garde la poitrine haute et les épaules en arrière pour maintenir un bon alignement de la colonne vertébrale et éviter d''arrondir le haut du dos", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement avec tes omoplates", "Évite d''utiliser de l''élan ou de balancer le poids, cela réduit l''activation musculaire et augmente le risque de blessure", "Maintiens la tension dans ton cœur tout au long du mouvement pour protéger ton bas du dos"]', '["Keep your chest up and shoulders back to maintain proper spinal alignment and prevent rounding of the upper back", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Avoid using momentum or swinging the weight as this reduces muscle activation and increases injury risk", "Maintain tension in your core throughout the entire range of motion to protect your lower back"]', '700ff55b-baeb-41fe-9b1d-b2e046a45de6', 't-bar-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('1ee2b740-a400-493e-a4e9-e9a7797ea848', 'Étapes et Sauts en Plank Ours', NULL, NULL, 'Bear plank steps and hops', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/bear-plank-steps-and-hops.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-plank-steps-and-hops.jpg', NULL, '["Garde les genoux près du sol tout au long du mouvement pour maintenir la bonne forme de plank ours", "Concentre-toi sur le fait de garder les hanches carrées, évite de t''incliner ou de te torsader", "Commence par des pas avant de passer aux sauts pour renforcer ta force et ta stabilité", "Assure-toi d''avoir une répartition du poids équilibrée entre tes mains pour éviter de fatiguer les poignets", "Arrête immédiatement si tu ne peux pas maintenir la bonne forme ou si tes genoux touchent le sol"]', '["Ne pas maintenir le dos droit et la position neutre", "Faire pivoter les hanches ou le torse pendant les mouvements lateraux"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "bear plank steps and hops"]', true, '2026-04-03 12:24:55.683726+00', '2026-04-03 12:24:55.683726+00', 'Commence en position de plank ours : mains sous les épaules, genoux flottant juste au-dessus du sol, et le corps bien gainé. Alterne entre des pas latéraux et des petits sauts explosifs tout en maintenant la position de plank ours.', '["Ne pas maintenir le dos droit et la position neutre", "Faire pivoter les hanches ou le torse pendant les mouvements lateraux"]', true, '["Start in bear plank with wrists aligned under shoulders and knees hovering just above the ground", "Engage your core and maintain a neutral spine throughout the entire movement", "Step or hop your right foot out to the side while keeping your left foot planted", "Return your right foot to starting position, then repeat with your left foot", "Keep your hips level and avoid rotating your torso during the lateral movements", "Breathe steadily and maintain control rather than rushing through the repetitions"]', '["Place-toi en plank ours avec les poignets sous les épaules et les genoux juste au-dessus du sol", "Contracte bien ton abdomen et garde le dos neutre pendant tout le mouvement", "Fais un pas ou un saut avec ton pied droit sur le côté tout en gardant le pied gauche ancré", "Ramène ton pied droit à la position de départ, puis fais de même avec le pied gauche", "Garde les hanches à niveau et évite de faire pivoter ton torse durant les mouvements latéraux", "Respire calmement et reste en contrôle, pas de précipitation dans les répétitions"]', '["Garde les genoux près du sol tout au long du mouvement pour maintenir la bonne forme de plank ours", "Concentre-toi sur le fait de garder les hanches carrées, évite de t''incliner ou de te torsader", "Commence par des pas avant de passer aux sauts pour renforcer ta force et ta stabilité", "Assure-toi d''avoir une répartition du poids équilibrée entre tes mains pour éviter de fatiguer les poignets", "Arrête immédiatement si tu ne peux pas maintenir la bonne forme ou si tes genoux touchent le sol"]', '["Keep your knees close to the ground throughout the movement to maintain proper bear plank form", "Focus on keeping your hips square and avoiding any twisting or tilting", "Start with stepping motions before progressing to hopping to build strength and stability", "Maintain even weight distribution between your hands to prevent wrist strain", "Stop immediately if you cannot maintain proper form or if your knees touch the ground"]', '638616d3-100b-4b14-8516-ff9e4b3e80f2', 'bear-plank-steps-and-hops', NULL, NULL);
INSERT INTO public.exercises VALUES ('d14059f2-2865-4b73-b9b7-a1ca4a3a8abf', 'Plank Kick Out - Renforce ton Tronc !', NULL, 'ضربة الساق في وضعية البدلاء', 'Plank kick out', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-kick-out.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-kick-out.jpg', NULL, '["Garde les hanches au niveau et évite de faire pivoter le bassin pendant le mouvement du genou", "Maintiens une forme de planche solide - ne laisse pas les hanches s''affaisser ou se soulever", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''activation musculaire du tronc", "Assure-toi que tes mains sont bien ancrées et que tes épaules restent stables au-dessus des poignets", "Engage continuellement tes muscles abdominaux pour protéger le bas du dos"]', '["Ne pas garder une ligne droite entre la tête et les talons", "S''affaisser ou lever les hanches au lieu de maintenir la position stable"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank kick out"]', true, '2026-04-03 12:24:58.317267+00', '2026-04-03 12:24:58.317267+00', 'Place-toi en position de planche, les mains sous les épaules, le corps bien droit de la tête aux talons et les pieds écartés à la largeur des hanches. Puis, sans perdre ton équilibre, fais un mouvement contrôlé de genoux vers la poitrine, en alternant les jambes.', '["Ne pas garder une ligne droite entre la tête et les talons", "S''affaisser ou lever les hanches au lieu de maintenir la position stable"]', true, '["Start in a high plank position with hands directly under shoulders and body in a straight line", "Engage your core and maintain neutral spine alignment throughout the movement", "Bring one knee toward your chest in a controlled motion while keeping the other leg extended", "Return the working leg back to starting position with control", "Alternate legs, bringing the opposite knee toward chest", "Maintain steady breathing and avoid rushing the movement"]', '["Commence en position de planche haute, les mains sous les épaules et le corps aligné", "Active ton tronc et garde une colonne vertébrale neutre pendant le mouvement", "Ramène un genou vers ta poitrine tout en maintenant l''autre jambe tendue", "Ramène la jambe en position initiale avec contrôle", "Alterne les jambes en amenant le genou opposé vers la poitrine", "Respire régulièrement et prends ton temps, évite de précipiter les mouvements"]', '["Garde les hanches au niveau et évite de faire pivoter le bassin pendant le mouvement du genou", "Maintiens une forme de planche solide - ne laisse pas les hanches s''affaisser ou se soulever", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''activation musculaire du tronc", "Assure-toi que tes mains sont bien ancrées et que tes épaules restent stables au-dessus des poignets", "Engage continuellement tes muscles abdominaux pour protéger le bas du dos"]', '["Keep hips level and avoid rotating the pelvis during the knee drive", "Maintain strong plank form throughout - don''t let hips sag or pike up", "Focus on controlled movement rather than speed to maximize core engagement", "Keep hands firmly planted and shoulders stable over wrists", "Engage core muscles continuously to protect the lower back"]', 'f93fa069-3b1d-41f0-bb26-2322bc4ea1c1', 'plank-kick-out', NULL, NULL);
INSERT INTO public.exercises VALUES ('4346830c-aa1e-475e-8d36-0326e8c72632', 'Posture du Bateau', NULL, NULL, 'Boat pose', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/boat-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/boat-pose.jpg', NULL, '["Gardez votre colonne vertébrale droite, ne courbez pas le dos.", "Contractez votre sangle abdominale pour maintenir l''équilibre.", "Respirez régulièrement et maintenez la position pendant 5 à 10 respirations."]', '["Dos arrondi au lieu de droit.", "Ne pas maintenir la contraction des abdos."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "boat pose"]', true, '2026-04-03 12:24:55.771311+00', '2026-04-03 12:24:55.771311+00', 'Asseyez-vous par terre, les genoux fléchis et les pieds à plat. En équilibre sur vos os du siège, levez vos pieds du sol et formez un V avec votre corps en étendant les jambes et les bras.', '["Dos arrondi au lieu de droit.", "Ne pas maintenir la contraction des abdos."]', true, '["Sit on the floor with knees bent and feet flat.", "Lean back slightly and lift your feet off the floor.", "Extend your arms forward, parallel to the floor.", "Straighten your legs to form a V-shape with your body."]', '["Asseyez-vous sur le sol, genoux fléchis et pieds à plat.", "Poussez légèrement votre dos en arrière et décollez vos pieds du sol.", "Étirez vos bras en avant, parallèles au sol.", "Redressez vos jambes pour former un V avec votre corps."]', '["Gardez votre colonne vertébrale droite, ne courbez pas le dos.", "Contractez votre sangle abdominale pour maintenir l''équilibre.", "Respirez régulièrement et maintenez la position pendant 5 à 10 respirations."]', '["Keep your spine straight, avoid rounding the back.", "Engage your core to maintain balance.", "Breathe steadily and hold for 5-10 breaths."]', 'e396f5be-9c22-44ff-b825-d754d807f5fd', 'boat-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('a9e64ae8-e316-4b4b-98e9-87df8e6b7bc0', 'Pose du Triangle (gauche)', NULL, NULL, 'Triangle pose (left)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/triangle-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/triangle-pose-left.jpg', NULL, '["Gardez les jambes droites.", "Ouvrez votre poitrine vers le ciel.", "Activez vos abdominaux pour soutenir cette inclinaison."]', '["Plier les jambes au lieu de les garder droites.", "Ne pas aligner le buste et le bras supérieur."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "triangle pose (left)"]', true, '2026-04-03 12:24:59.77097+00', '2026-04-03 12:24:59.77097+00', 'Renforcez vos ischio-jambiers tout en améliorant votre flexibilité avec la pose du triangle. Une posture qui élargit votre champ d’action et stabilise votre corps.', '["Plier les jambes au lieu de les garder droites.", "Ne pas aligner le buste et le bras supérieur."]', true, '["Stand with feet wide apart, front foot pointing forward, back foot at 90 degrees.", "Extend your arms out to the sides at shoulder height.", "Hinge at the hip and reach your front hand toward the floor or a block.", "Extend your top arm toward the ceiling."]', '["Tenez-vous avec les pieds écartés, le pied avant tourné vers l''avant et le pied arrière à 90 degrés.", "Étendez vos bras de chaque côté à hauteur d''épaules.", "Inclinez votre buste en avant et poussez votre main avant vers le sol ou un bloc.", "Levez votre bras supérieur vers le plafond."]', '["Gardez les jambes droites.", "Ouvrez votre poitrine vers le ciel.", "Activez vos abdominaux pour soutenir cette inclinaison."]', '["Keep both legs straight.", "Open your chest toward the ceiling.", "Engage your core to support the side bend."]', '4513eebe-8fee-42e0-9d60-3101601bdc0a', 'triangle-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('4ca7ceeb-0ebe-42c6-a7da-65d48d3d7c26', 'Maintien en L-sit Tuck', NULL, NULL, 'Tucked L-sit hold', 'Abs', '[]', 'Abs', 'Advanced', 16, '/videos/abs/tucked-l-sit-hold.mp4', NULL, NULL, NULL, '/videos/thumbnails/tucked-l-sit-hold.jpg', NULL, '["Garde tes épaules basses et éloignées de tes oreilles pour éviter les tensions cervicales", "Maintiens une prise solide sur les barres durant tout le mouvement", "Concentre-toi sur la pression de tes paumes plutôt que de simplement suspendre ton corps", "Commence par des maintiens courts et augmente progressivement la durée au fur et à mesure que ta force s''améliore", "Garde ton core contracté pour contrôler la position des jambes repliées."]', '["Brevement courber les épaules en haute position", "Relâcher les bras en soutenant le poids."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "tucked l-sit hold"]', true, '2026-04-03 12:24:59.780584+00', '2026-04-03 12:24:59.780584+00', 'Position de départ : assieds-toi sur des barres parallèles ou une station de dips, les mains agrippant les barres à côté de tes hanches, bras droit. Exécution : soulève ton corps en pressant vers le bas avec tes mains tout en ramenant tes genoux vers ta poitrine, maintiens cette position élevée.', '["Brevement courber les épaules en haute position", "Relâcher les bras en soutenant le poids."]', true, '["Grip the parallel bars firmly with hands positioned directly beside your hips", "Press down through your palms to lift your entire body weight off the bars", "Tuck your knees up toward your chest while maintaining the lifted position", "Keep your arms straight and shoulders stable throughout the hold", "Engage your core muscles to maintain the tucked position", "Hold for the desired duration then slowly lower back down"]', '["Agrippe fermement les barres parallèles avec les mains à côté de tes hanches", "Appuie sur tes paumes pour soulever ton poids entier hors des barres", "Ramène tes genoux vers ta poitrine tout en gardant la position surélevée", "Garde les bras droits et les épaules stables durant tout le maintien", "Engage tes muscles du core pour conserver la position de tuck", "Tiens cette position aussi longtemps que souhaité puis redescends lentement."]', '["Garde tes épaules basses et éloignées de tes oreilles pour éviter les tensions cervicales", "Maintiens une prise solide sur les barres durant tout le mouvement", "Concentre-toi sur la pression de tes paumes plutôt que de simplement suspendre ton corps", "Commence par des maintiens courts et augmente progressivement la durée au fur et à mesure que ta force s''améliore", "Garde ton core contracté pour contrôler la position des jambes repliées."]', '["Keep shoulders down and away from your ears to prevent neck strain", "Maintain a strong grip on the bars throughout the entire movement", "Focus on pushing down through your palms rather than just hanging", "Start with shorter holds and gradually increase duration as strength improves", "Keep your core tight to control the tucked leg position"]', '044f938a-5772-4a0e-b39a-8a85393830e7', 'tucked-l-sit-hold', NULL, NULL);
INSERT INTO public.exercises VALUES ('04c471ec-5720-43b4-a833-38d675d4fc1d', 'Tirage Vertical Sous-Proné', NULL, NULL, 'Underhand Lat Pulldown', 'Back', '[]', 'Back', 'Beginner', 4, '/videos/back/underhand-lat-pulldown.mp4', NULL, NULL, NULL, '/videos/thumbnails/underhand-lat-pulldown.jpg', NULL, '["Garde tes épaules en bas et en arrière pour éviter d''utiliser tes trapèzes supérieurs et pour assurer une activation correcte des lats", "Évite de trop pencher en arrière ou d''utiliser l''élan pour tirer le poids vers le bas", "Concentre-toi sur l''utilisation de tes muscles du dos, en initiant le mouvement avec tes lats", "Contrôle la phase excentrique du mouvement pour maximiser l''engagement musculaire et éviter les blessures", "Engage ton tronc tout au long de l''exercice pour maintenir une bonne posture et stabilité"]', '["Ne pas ajuster le coussin de cuisse, ce qui peut entraîner un mouvement du corps", "Tirer avec les bras au lieu de focaliser l''effort sur le dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "underhand lat pulldown"]', true, '2026-04-03 12:24:59.800167+00', '2026-04-03 12:24:59.800167+00', 'Position de départ : Assieds-toi sur la machine de tirage vertical avec une prise sous-pronée (paumes vers le haut). Exécution : Tire la barre vers ta poitrine, les coudes près du corps, puis redescends lentement à la position de départ.', '["Ne pas ajuster le coussin de cuisse, ce qui peut entraîner un mouvement du corps", "Tirer avec les bras au lieu de focaliser l''effort sur le dos"]', true, '["Adjust the thigh pad so it sits snugly against your legs to prevent your body from lifting during the movement", "Grip the bar with palms facing you, hands positioned slightly wider than shoulder-width apart", "Keep your chest up, shoulders back, and maintain a slight backward lean throughout the exercise", "Pull the bar down smoothly to your upper chest, focusing on squeezing your shoulder blades together", "Hold the contraction briefly at the bottom, then slowly return the bar to the starting position with control", "Maintain tension in your lats throughout the entire range of motion"]', '["Ajuste le coussin de cuisse pour qu''il soit bien en place contre tes jambes afin d''éviter que ton corps ne bouge pendant l''exercice", "Saisis la barre avec les paumes vers toi, les mains légèrement plus écartées que la largeur des épaules", "Garde le torse droit, les épaules en arrière, avec une légère inclinaison vers l''arrière tout au long de l''exercice", "Tire la barre vers ta poitrine supérieure, en te concentrant sur le rapprochement de tes omoplates", "Maintiens la contraction brièvement en bas, puis redescends lentement la barre à la position de départ en gardant le contrôle", "Garde une tension dans tes lats pendant toute l''amplitude du mouvement"]', '["Garde tes épaules en bas et en arrière pour éviter d''utiliser tes trapèzes supérieurs et pour assurer une activation correcte des lats", "Évite de trop pencher en arrière ou d''utiliser l''élan pour tirer le poids vers le bas", "Concentre-toi sur l''utilisation de tes muscles du dos, en initiant le mouvement avec tes lats", "Contrôle la phase excentrique du mouvement pour maximiser l''engagement musculaire et éviter les blessures", "Engage ton tronc tout au long de l''exercice pour maintenir une bonne posture et stabilité"]', '["Keep your shoulders down and back to avoid using your upper traps and ensure proper lat activation", "Avoid leaning too far back or using momentum to pull the weight down", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your lats", "Control the eccentric portion of the movement to maximize muscle engagement and prevent injury", "Keep your core engaged throughout the exercise to maintain proper posture and stability"]', 'dca87d2f-84de-4a2d-b0d8-2adcf68c10a8', 'underhand-lat-pulldown', NULL, NULL);
INSERT INTO public.exercises VALUES ('c56bb821-971e-4b61-b363-dee33719f5be', 'Posture du cobra', NULL, NULL, 'Upward facing dog pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/upward-facing-dog-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/upward-facing-dog-pose.jpg', NULL, '["Seules tes mains et le dessus de tes pieds touchent le sol.", "Contracte tes jambes et engage bien tes cuisses.", "Évite de comprimer ton bas du dos."]', '["Lever trop haut la poitrine et les épaules, provoquant une tension dans le bas du dos.", "Ne pas activer les jambes, ce qui peut déséquilibrer la posture."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "upward facing dog pose"]', true, '2026-04-03 12:24:59.825413+00', '2026-04-03 12:24:59.825413+00', 'Renforce ton dos et améliore ta souplesse avec cette posture qui éveille ton énergie.', '["Lever trop haut la poitrine et les épaules, provoquant une tension dans le bas du dos.", "Ne pas activer les jambes, ce qui peut déséquilibrer la posture."]', true, '["Lie face down with hands beside your lower ribs.", "Press through your hands to lift your chest and thighs off the floor.", "Straighten your arms and roll your shoulders back.", "Keep the tops of your feet pressing into the mat."]', '["Allonge-toi sur le ventre, les mains proches de tes côtes.", "Pousse avec tes mains pour soulever ta poitrine et tes cuisses du sol.", "Redresse tes bras et recule tes épaules.", "Garde le dessus de tes pieds en contact avec le sol."]', '["Seules tes mains et le dessus de tes pieds touchent le sol.", "Contracte tes jambes et engage bien tes cuisses.", "Évite de comprimer ton bas du dos."]', '["Only your hands and tops of feet touch the floor.", "Engage your legs and firm your thighs.", "Do not compress your lower back."]', '292b7c17-cc1f-4753-a690-8caad6e28879', 'upward-facing-dog-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('f63a4de3-f074-478f-9c12-15da07e49ae0', 'Guerrier I (droite)', NULL, 'المحارب I (اليمين)', 'Warrior I (right)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/warrior-i-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/warrior-i-right.jpg', NULL, '["Alignez vos hanches vers l''avant du tapis.", "Assurez-vous que votre genou avant reste au-dessus de la cheville, sans dépasser les orteils.", "Redressez votre buste et regardez devant vous ou vers le ciel."]', '["Ne pas aligner les hanches correctement.", "Genou avant trop avancé par rapport aux orteils."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "warrior i (right)"]', true, '2026-04-03 12:24:59.867794+00', '2026-04-03 12:24:59.867794+00', 'Un exercice puissant pour activer vos fessiers et renforcer votre corps !', '["Ne pas aligner les hanches correctement.", "Genou avant trop avancé par rapport aux orteils."]', true, '["From standing, step one foot back about 4 feet.", "Bend your front knee to 90 degrees over the ankle.", "Turn your back foot out at 45 degrees and press the heel down.", "Raise your arms overhead with palms facing each other."]', '["Debout, reculez un pied d''environ 1,20 mètre.", "Fléchissez votre genou avant à 90 degrés au-dessus de la cheville.", "Tournez votre pied arrière de 45 degrés et enfoncez le talon au sol.", "Levez les bras au-dessus de votre tête en gardant les paumes l''une face à l''autre."]', '["Alignez vos hanches vers l''avant du tapis.", "Assurez-vous que votre genou avant reste au-dessus de la cheville, sans dépasser les orteils.", "Redressez votre buste et regardez devant vous ou vers le ciel."]', '["Square your hips toward the front of the mat.", "Keep your front knee over the ankle, not past the toes.", "Lift your chest and gaze forward or up."]', '53c6b923-dcdb-44f6-a57f-150dc1d1e547', 'warrior-i-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('6dcae718-456d-4687-803b-7cac16cd3944', 'Fentes arrière marchées', NULL, NULL, 'Walking lunges - backward', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/walking-lunges-backward.mp4', NULL, NULL, NULL, '/videos/thumbnails/walking-lunges-backward.jpg', NULL, '["Garde ton genou avant aligné au-dessus de ta cheville et évite qu''il ne s''affaisse vers l''intérieur", "Adopte une posture droite avec la poitrine levée et les épaules en arrière", "Contrôle ta descente - ne laisse pas tomber ton genou arrière sur le sol", "Concentre la majorité de ton poids sur la jambe avant tout au long du mouvement", "Axé sur des transitions fluides et contrôlées entre chaque position de fente"]', '["Laisser le genou avant dépasser les orteils", "Se pencher en avant au lieu de garder le torse droit"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "walking lunges - backward"]', true, '2026-04-03 12:24:59.847+00', '2026-04-03 12:24:59.847+00', 'Position de départ : Commence dans une position de fente basse avec ton pied droit devant et ton genou gauche au sol, garde le torse droit. Exécution : Amène ton pied arrière vers l''avant pour te redresser, puis redescends en fente de l''autre côté, alterne les jambes à chaque répétition.', '["Laisser le genou avant dépasser les orteils", "Se pencher en avant au lieu de garder le torse droit"]', true, '["Start in a low lunge position with one foot forward and the opposite knee touching the ground", "Keep your torso upright and engage your core throughout the movement", "Step the back foot forward to bring yourself to a brief standing position", "Step back down into a lunge position with the opposite leg now forward", "Lower the back knee to lightly touch the mat while keeping most weight on the front leg", "Continue alternating legs with each repetition, maintaining control throughout"]', '["Prends une position de fente basse avec un pied en avant et l''autre genou touchant le sol", "Garde le torse droit et engage ton corps tout au long du mouvement", "Ramène le pied arrière vers l''avant pour te mettre brièvement en position debout", "Redescends en fente avec l''autre jambe devant", "Abaisse le genou arrière pour toucher légèrement le sol tout en gardant le poids sur la jambe avant", "Continue d''alterner les jambes à chaque répétition en gardant le contrôle sur chaque mouvement"]', '["Garde ton genou avant aligné au-dessus de ta cheville et évite qu''il ne s''affaisse vers l''intérieur", "Adopte une posture droite avec la poitrine levée et les épaules en arrière", "Contrôle ta descente - ne laisse pas tomber ton genou arrière sur le sol", "Concentre la majorité de ton poids sur la jambe avant tout au long du mouvement", "Axé sur des transitions fluides et contrôlées entre chaque position de fente"]', '["Keep your front knee aligned over your ankle and avoid letting it cave inward", "Maintain an upright posture with your chest up and shoulders back", "Control the descent - don''t drop or slam the back knee onto the mat", "Keep most of your weight distributed on your front leg throughout the movement", "Focus on smooth, controlled transitions between each lunge position"]', '21beb247-bf6f-41a7-b2d3-58c58d103ba0', 'walking-lunges-backward', NULL, NULL);
INSERT INTO public.exercises VALUES ('753f0ffc-a49b-4bad-9ab1-8d92b4556d93', 'Posture du Guerrier III (droit)', NULL, 'وضعية المحارب III (الأيمن)', 'Warrior III (right)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/warrior-iii-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/warrior-iii-right.jpg', NULL, '["Garde ta jambe d''appui solide avec un léger fléchissement.", "Oriente tes hanches vers le sol.", "Active ta ceinture abdominale pour maintenir l''équilibre."]', '["Pencher le tronc trop en avant.", "Ne pas activer les muscles du tronc.", "Jambe d''appui trop rigide."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "warrior iii (right)"]', true, '2026-04-03 12:24:59.902947+00', '2026-04-03 12:24:59.902947+00', 'Renforce tes fessiers avec cette position qui allie équilibre et force.', '["Pencher le tronc trop en avant.", "Ne pas activer les muscles du tronc.", "Jambe d''appui trop rigide."]', true, '["From standing, shift your weight onto one foot.", "Hinge forward at the hips while lifting your back leg behind you.", "Extend your arms forward or alongside your body.", "Create a straight line from fingertips to the lifted foot."]', '["À partir de la position debout, transfère ton poids sur une jambe.", "Penche-toi en avant en avançant la jambe arrière derrière toi.", "Étends les bras soit vers l''avant, soit le long de ton corps.", "Crée une ligne droite de tes doigts jusqu''à ton pied levé."]', '["Garde ta jambe d''appui solide avec un léger fléchissement.", "Oriente tes hanches vers le sol.", "Active ta ceinture abdominale pour maintenir l''équilibre."]', '["Keep your standing leg strong with a micro-bend.", "Square your hips toward the floor.", "Engage your core for balance."]', 'f570def7-a724-48f5-87b7-66dfad7cc993', 'warrior-iii-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('27c06cb8-a2d6-4231-8a50-46c88a78a5e6', 'Guerrier II (droit)', NULL, 'محارب II (اليمنى)', 'Warrior II (right)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/warrior-ii-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/warrior-ii-right.jpg', NULL, '["Assure-toi que ton genou avant reste aligné avec ta cheville.", "Pousse bien à travers les deux pieds pour une stabilité optimale.", "Garde tes épaules bien au-dessus de tes hanches pour une posture solide."]', '["Genou avant qui dépasse trop la cheville.", "Pieds mal positionnés ou déséquilibrés.", "Hanches tournées au lieu d''être face à l''avant."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "warrior ii (right)"]', true, '2026-04-03 12:24:59.883739+00', '2026-04-03 12:24:59.883739+00', 'Renforce tes fessiers tout en développant ton enracinement et ta concentration.', '["Genou avant qui dépasse trop la cheville.", "Pieds mal positionnés ou déséquilibrés.", "Hanches tournées au lieu d''être face à l''avant."]', true, '["Stand with feet wide apart, front foot pointing forward.", "Turn your back foot to 90 degrees.", "Bend your front knee to 90 degrees over the ankle.", "Extend your arms out to the sides at shoulder height and gaze over your front hand."]', '["Écarte bien les pieds, le pied avant dirigé vers l''avant.", "Pivote ton pied arrière à 90 degrés.", "Plie ton genou avant à 90 degrés au-dessus de la cheville.", "Étends tes bras sur les côtés à hauteur d''épaules et regarde au-delà de ta main avant."]', '["Assure-toi que ton genou avant reste aligné avec ta cheville.", "Pousse bien à travers les deux pieds pour une stabilité optimale.", "Garde tes épaules bien au-dessus de tes hanches pour une posture solide."]', '["Keep your front knee tracking over the ankle.", "Press evenly through both feet.", "Stack your shoulders over your hips."]', '2b536297-c5de-4994-b67d-d1adac5f29c0', 'warrior-ii-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('2743628e-6ea5-4aad-85da-060742b09acc', 'Curl Large avec Haltere', NULL, NULL, 'Wide Grip Barbell Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 1, '/videos/biceps/wide-grip-barbell-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/wide-grip-barbell-curl.jpg', NULL, '["Une prise plus large cible mieux la tête interne des biceps que la prise standard", "Garde tes poignets droits et alignés avec tes avant-bras pour éviter les blessures", "Évite de balancer ou d''utiliser l''élan - le mouvement doit être contrôlé et délibéré", "Ne laisse pas tes coudes s''avancer pendant le curl pour activer correctement les biceps", "Concentre-toi sur la phase négative (descente) pour maximiser l''engagement musculaire"]', '["Utiliser trop d''élan pour lever la barre", "Déplacer les coudes en avant pendant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "barbell", "wide grip barbell curl"]', true, '2026-04-03 12:24:59.91503+00', '2026-04-03 12:24:59.91503+00', 'Position de départ : Tiens-toi bien droit en tenant une barre avec les mains en prise pronation plus large que la largeur des épaules, les bras complètement tendus et la barre reposant contre tes cuisses. Exécution : Enflamme tes biceps en levant la barre tout en gardant les coudes fixes sur tes côtés, puis redescends lentement à la position de départ.', '["Utiliser trop d''élan pour lever la barre", "Déplacer les coudes en avant pendant le mouvement"]', true, '["Stand with feet shoulder-width apart and grip the barbell with hands positioned wider than shoulder-width using an overhand grip", "Keep your core engaged and maintain an upright posture with slight bend in your knees", "Keep your elbows close to your sides and stationary throughout the entire movement", "Curl the barbell up by contracting your biceps until your forearms are vertical", "Slowly lower the barbell back to the starting position with control", "Maintain tension in your biceps throughout the entire range of motion"]', '["Positionne tes pieds à la largeur des épaules avec une prise large sur la barre en prise pronation", "Engage ton ventre et garde le dos droit, légèrement fléchi au niveau des genoux", "Maintiens les coudes près de tes côtés et immobiles pendant tout l''exercice", "Lève la barre en contractant tes biceps jusqu''à ce que tes avant-bras soient verticaux", "Descends lentement la barre en gardant le contrôle total", "Maintiens la tension dans tes biceps tout au long du mouvement"]', '["Une prise plus large cible mieux la tête interne des biceps que la prise standard", "Garde tes poignets droits et alignés avec tes avant-bras pour éviter les blessures", "Évite de balancer ou d''utiliser l''élan - le mouvement doit être contrôlé et délibéré", "Ne laisse pas tes coudes s''avancer pendant le curl pour activer correctement les biceps", "Concentre-toi sur la phase négative (descente) pour maximiser l''engagement musculaire"]', '["The wider grip targets the inner head of the biceps more than a standard grip", "Keep your wrists straight and aligned with your forearms to prevent injury", "Avoid swinging or using momentum - the movement should be controlled and deliberate", "Don''t let your elbows drift forward during the curl to maintain proper bicep activation", "Focus on the eccentric (lowering) portion of the movement for maximum muscle engagement"]', '1267bc89-80f9-46ad-9f94-e7e542854042', 'wide-grip-barbell-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('407687ad-c952-40ea-9b42-b481c015fca8', 'Curl Alterné avec Haltères', NULL, NULL, 'Alternating Dumbbell Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 2, '/videos/biceps/alternating-dumbbell-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/alternating-dumbbell-curl.jpg', NULL, '["Garde ton ventre contracté et évite de balancer ou d''utiliser l''élan pour soulever les poids.", "Reste contrôlé sur toute l''amplitude de movement, surtout lors de la descente.", "Maintiens tes coudes près de ton torse, sans les laisser dériver vers l''avant ou l''arrière.", "Concentre-toi sur la contraction du biceps au sommet de chaque curl pour une activation maximale.", "Choisis un poids qui te permet de garder une bonne posture pendant toutes les répétitions."]', '["Balancement du corps pour soulever les haltères.", "Coudes qui s''éloignent du torse."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "alternating dumbbell curl"]', true, '2026-04-03 12:24:55.40451+00', '2026-04-03 12:24:55.40451+00', 'Prends position, assis ou debout, avec un haltère dans chaque main, les paumes tournées vers l''avant. Alterne le mouvement en soulevant un haltère vers ton épaule, puis l''autre à chaque répétition.', '["Balancement du corps pour soulever les haltères.", "Coudes qui s''éloignent du torse."]', true, '["Sit or stand and maintain a straight posture with core engaged", "Hold dumbbells with arms fully extended at your sides, palms facing forward", "Curl one dumbbell up by bending at the elbow, keeping your upper arm stationary against your torso", "Squeeze your bicep at the top of the movement, then slowly lower the weight back to starting position", "Repeat the same motion with the opposite arm while keeping the rested arm still", "Continue alternating arms for the desired number of repetitions"]', '["Tiens-toi droit, le dos bien aligné et le ventre contracté.", "Les bras doivent être étendus sur les côtés, haltères en mains, paumes vers l''avant.", "Plie un coude pour ramener un haltère vers ton épaule, en gardant le bras supérieur collé au torse.", "Contracte ton biceps en haut du mouvement, puis redescends lentement l''haltère à la position de départ.", "Répète le mouvement avec l''autre bras sans bouger le premier.", "Continue à alterner les bras pour le nombre de répétitions souhaité."]', '["Garde ton ventre contracté et évite de balancer ou d''utiliser l''élan pour soulever les poids.", "Reste contrôlé sur toute l''amplitude de movement, surtout lors de la descente.", "Maintiens tes coudes près de ton torse, sans les laisser dériver vers l''avant ou l''arrière.", "Concentre-toi sur la contraction du biceps au sommet de chaque curl pour une activation maximale.", "Choisis un poids qui te permet de garder une bonne posture pendant toutes les répétitions."]', '["Keep your core tight and avoid swinging or using momentum to lift the weights", "Maintain control throughout the entire range of motion, especially during the lowering phase", "Keep your elbows close to your torso and avoid letting them drift forward or backward", "Focus on squeezing the bicep at the top of each curl for maximum muscle activation", "Choose a weight that allows you to maintain proper form throughout all repetitions"]', '5058baec-15c8-4278-afa5-9621bb4e15b5', 'alternating-dumbbell-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('a6430981-16d7-4dbd-a649-a4de4efc5cab', 'Y-Superman Crunch', NULL, 'تمارين ي سوبرمان كرانش', 'Y-superman crunch', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/y-superman-crunch.mp4', NULL, NULL, NULL, '/videos/thumbnails/y-superman-crunch.jpg', NULL, '["Garde le cou aligné en regardant le sol au lieu de relever la tête", "Concentre-toi sur la levée par la poitrine et le haut du dos, sans forcer le bas du dos", "Maintiens la position en Y tout au long du mouvement pour cibler les deltoïdes postérieurs", "Commence par de courtes maintiens et moins de répétitions pour construire ta force progressivement", "Respire régulièrement pendant l''exercice et évite de retenir ta respiration"]', '["Ne pas contracter suffisamment le ventre", "Soulever la tête trop haut, ce qui peut blesser le cou"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "y-superman crunch"]', true, '2026-04-03 12:24:59.960991+00', '2026-04-03 12:24:59.960991+00', 'Position de départ : allonge-toi sur le ventre, bras étendus en avant en formant un Y large au-dessus de ta tête et jambes bien droites. Exécution : soulève simultanément ta poitrine, tes bras et tes jambes du sol tout en contractant ton ventre, pour adopter une position de super-héros.', '["Ne pas contracter suffisamment le ventre", "Soulever la tête trop haut, ce qui peut blesser le cou"]', true, '["Lie face down with your forehead resting on the ground and arms extended overhead in a wide Y-shape", "Keep your legs straight and together, with toes pointed", "Engage your core and glutes before initiating the movement", "Simultaneously lift your chest, arms, and legs off the ground while squeezing your shoulder blades together", "Hold the top position briefly while maintaining the Y-arm position", "Lower back down to starting position with control"]', '["Allonge-toi sur le ventre, front au sol, bras étendus en Y large", "Garde les jambes droites et serrées, orteils pointés", "Engage ton ventre et tes fessiers avant de commencer", "Soulève en même temps ta poitrine, tes bras et tes jambes, en serrant les omoplates", "Maintiens la position en haut un instant tout en gardant les bras en Y", "Redescends en contrôlant ton mouvement pour revenir à la position de départ"]', '["Garde le cou aligné en regardant le sol au lieu de relever la tête", "Concentre-toi sur la levée par la poitrine et le haut du dos, sans forcer le bas du dos", "Maintiens la position en Y tout au long du mouvement pour cibler les deltoïdes postérieurs", "Commence par de courtes maintiens et moins de répétitions pour construire ta force progressivement", "Respire régulièrement pendant l''exercice et évite de retenir ta respiration"]', '["Keep your neck in neutral alignment by looking down at the floor rather than lifting your head", "Focus on lifting through your chest and upper back rather than straining your lower back", "Maintain the wide Y-arm position throughout the entire movement to target the posterior deltoids", "Start with shorter holds and fewer repetitions to build strength gradually", "Breathe steadily throughout the exercise and avoid holding your breath"]', '592c2408-5da3-4cca-9453-9dc9cfec6d9f', 'y-superman-crunch', NULL, NULL);
INSERT INTO public.exercises VALUES ('d139f2a2-2cd1-401e-ba31-df8b599af02b', 'Soulevé de hanches avec barre', NULL, NULL, 'Barbell Glute Bridge', 'Glutes', '[]', 'Glutes', 'Beginner', 1, '/videos/glutes/barbell-glute-bridge.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-glute-bridge.jpg', NULL, '["Contracte bien les fessiers en haut", "Évite d''hyperétendre le bas du dos", "Pousse fort avec les talons", "Maintiens la position en haut quelques secondes", "C''est la base pour le hip thrust"]', '["Ne pas contracter les fessiers", "Hyperextension du bas du dos", "Ne pas maintenir les talons au sol", "Descendre trop vite"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "barbell", "barbell glute bridge"]', true, '2026-04-03 12:24:55.577186+00', '2026-04-03 12:24:55.577186+00', 'Allonge-toi sur le dos, genoux pliés et pieds à plat. Positionne une barre au niveau de tes hanches et maintiens-la pour la stabilité. Prêt à travailler tes fessiers ? C''est parti !', '["Ne pas contracter les fessiers", "Hyperextension du bas du dos", "Ne pas maintenir les talons au sol", "Descendre trop vite"]', true, '["Lie on back, knees bent, feet flat", "Drive hips up by squeezing glutes", "Form straight line from shoulders to knees", "Lower with control"]', '["Allonge-toi sur le dos, genoux pliés, pieds à plat", "Pousse sur les talons et soulève les hanches en contractant les fessiers", "Forme une ligne droite des épaules aux genoux", "Redescends doucement tout en gardant le contrôle"]', '["Contracte bien les fessiers en haut", "Évite d''hyperétendre le bas du dos", "Pousse fort avec les talons", "Maintiens la position en haut quelques secondes", "C''est la base pour le hip thrust"]', '["Squeeze glutes hard at top", "Don''t hyperextend lower back", "Drive through heels", "Hold at top briefly", "Foundation for hip thrusts"]', 'b43b051d-cd66-41c7-8772-f81797ce872c', 'barbell-glute-bridge', NULL, NULL);
INSERT INTO public.exercises VALUES ('90a387ce-7877-4afb-af86-1ddc30162fa3', 'Fente avec barre', NULL, NULL, 'Barbell Lunge', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 1, '/videos/quadriceps/barbell-lunge.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-lunge.jpg', NULL, '["Garde le torse droit", "Le genou avant doit suivre la ligne des orteils", "Évite de laisser le genou avant dépasser les orteils", "Contrôle ta descente", "Fais un pas en arrière si tu as du mal à garder l''équilibre"]', '["Ne pas garder le dos droit", "Trop pencher en avant", "Genou avant qui dépasse les orteils"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "barbell lunge"]', true, '2026-04-03 12:24:55.601215+00', '2026-04-03 12:24:55.601215+00', 'Position de départ : Place la barre sur le haut de ton dos et avance une jambe en position de fente, l''autre jambe reste en arrière. Exécution : Abaisse ton corps en pliant les deux genoux, puis pousse sur ta jambe avant pour revenir à la position de départ. Alterne les jambes ou fais une série complète sur un côté.', '["Ne pas garder le dos droit", "Trop pencher en avant", "Genou avant qui dépasse les orteils"]', true, '["Bar on upper back", "Stand with feet together", "Step forward into lunge", "Lower until back knee near floor", "Push back to starting position", "Alternate legs or complete one side"]', '["Barre sur le haut du dos", "Positionne-toi avec les pieds ensemble", "Fais un pas en avant en fente", "Abaisse jusqu''à ce que le genou arrière soit proche du sol", "Repousse pour revenir à la position de départ", "Alterne les jambes ou complète une seule côté"]', '["Garde le torse droit", "Le genou avant doit suivre la ligne des orteils", "Évite de laisser le genou avant dépasser les orteils", "Contrôle ta descente", "Fais un pas en arrière si tu as du mal à garder l''équilibre"]', '["Keep torso upright", "Front knee tracks over toes", "Don''t let front knee shoot past toes", "Control the descent", "Step back, not forward if balance is hard"]', '714b176e-2963-43f0-ae0f-c71643cbe426', 'barbell-lunge', NULL, NULL);
INSERT INTO public.exercises VALUES ('6c2d59ca-c43b-4d9d-844b-0116c8ffe8b1', 'Sit-Up avec barre', NULL, 'Sit-Up b barre', 'Barbell Sit-Up', 'Abs', '[]', 'Abs', 'Intermediate', 1, '/videos/abs/barbell-sit-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-sit-up.jpg', NULL, '["Garde le bas du dos bien plaqué au sol lors de la descente pour éviter les blessures", "Concentre-toi sur l''utilisation de tes muscles abdominaux, évite de tirer avec le cou ou de te balancer", "Commence avec une barre légère pour maîtriser la technique avant d''augmenter les poids", "Garde toujours les pieds au sol pour maintenir la stabilité", "Contrôle bien la descente, cela active puissamment tes muscles."]', '["Ne pas engager le core, ce qui peut mener à des blessures", "Pousser avec le cou au lieu d''utiliser les abdos."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "barbell", "barbell sit-up"]', true, '2026-04-03 12:24:55.623213+00', '2026-04-03 12:24:55.623213+00', 'Allonge-toi sur le dos, barre en main, et prépare-toi à sculpter ton core !', '["Ne pas engager le core, ce qui peut mener à des blessures", "Pousser avec le cou au lieu d''utiliser les abdos."]', true, '["Lie down with knees bent at 90 degrees and feet firmly planted on the ground", "Hold the barbell with both hands across your upper chest, keeping your grip secure", "Engage your core and slowly curl your torso up, leading with your chest rather than your neck", "Rise up until your torso is at approximately 45 degrees from the floor", "Slowly lower yourself back down to the starting position with control", "Maintain steady breathing throughout the movement, exhaling on the way up"]', '["Allonge-toi sur le dos, les genoux fléchis à 90 degrés et les pieds bien ancrés au sol", "Saisis la barre avec les deux mains, juste au-dessus de ta poitrine, en maintenant une prise ferme", "Engage ton abdominal et fais une flexion du torse en levant la barre vers tes cuisses, en gardant la tête droite", "Lève-toi jusqu''à ce que ton torse soit à environ 45 degrés du sol", "Redescends lentement et avec contrôle jusqu''à la position de départ", "Respire régulièrement, expire en montant."]', '["Garde le bas du dos bien plaqué au sol lors de la descente pour éviter les blessures", "Concentre-toi sur l''utilisation de tes muscles abdominaux, évite de tirer avec le cou ou de te balancer", "Commence avec une barre légère pour maîtriser la technique avant d''augmenter les poids", "Garde toujours les pieds au sol pour maintenir la stabilité", "Contrôle bien la descente, cela active puissamment tes muscles."]', '["Keep your lower back pressed against the floor during the lowering phase to prevent injury", "Focus on using your abdominal muscles rather than pulling with your neck or using momentum", "Start with a lighter weight barbell to master the form before progressing to heavier loads", "Keep your feet planted throughout the entire movement to maintain stability", "Control the descent portion of the movement as this provides significant muscle activation"]', '709f2fe5-f590-401b-aa94-d5f6dc67165b', 'barbell-sit-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('8efb07d8-eb82-45e9-acfe-af6dc5239e6c', 'Rampé de l''ours', NULL, 'تسلق الدب', 'Bear crawls', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/bear-crawls.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-crawls.jpg', NULL, '["Garde le ventre bien serré et le dos plat pour éviter que les hanches s''affaissent ou que la colonne vertébrale ne s''arque", "Respire calmement pendant l''exercice, ne retiens pas ta respiration", "Avance par petits pas pour mieux contrôler le mouvement et réduire la tension sur les poignets et les épaules", "Garde la tête neutre, regarde légèrement devant toi plutôt qu''en haut ou en bas", "Commence par de courtes distances et augmente progressivement à mesure que ta force et ta coordination s''améliorent"]', '["Ne pas garder le dos plat, ce qui mène à une mauvaise posture", "Avancer trop rapidement, ce qui diminue la précision et augmente le risque de blessures"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "bear crawls"]', true, '2026-04-03 12:24:55.659225+00', '2026-04-03 12:24:55.659225+00', 'Position de départ : Mets-toi à quatre pattes, poignets sous les épaules, genoux sous les hanches. Soulève tes genoux de 5 à 8 cm du sol. Execution : Avance en déplaçant simultanément ta main droite et ton pied gauche, puis alterne avec ta main gauche et ton pied droit tout en maintenant cette position basse.', '["Ne pas garder le dos plat, ce qui mène à une mauvaise posture", "Avancer trop rapidement, ce qui diminue la précision et augmente le risque de blessures"]', true, '["Start on hands and knees with wrists directly under shoulders and knees under hips", "Lift your knees 2-3 inches off the ground while keeping your back flat and core engaged", "Move your right hand forward while simultaneously stepping your left foot forward", "Follow with your left hand and right foot, maintaining the opposite arm-leg pattern", "Keep your knees close to the ground throughout the entire movement", "Move slowly and controlled, focusing on coordination rather than speed"]', '["Commence à quatre pattes, poignets sous les épaules et genoux sous les hanches", "Soulève tes genoux de 5 à 8 cm du sol, garde le dos plat et le ventre engagé", "Avance ta main droite tout en déplaçant simultanément ton pied gauche en avant", "Alterne avec ta main gauche et ton pied droit, en maintenant le schéma opposé bras-jambe", "Garde tes genoux près du sol pendant tout le mouvement", "Déplace-toi lentement et de manière contrôlée, en te concentrant sur la coordination plutôt que sur la vitesse"]', '["Garde le ventre bien serré et le dos plat pour éviter que les hanches s''affaissent ou que la colonne vertébrale ne s''arque", "Respire calmement pendant l''exercice, ne retiens pas ta respiration", "Avance par petits pas pour mieux contrôler le mouvement et réduire la tension sur les poignets et les épaules", "Garde la tête neutre, regarde légèrement devant toi plutôt qu''en haut ou en bas", "Commence par de courtes distances et augmente progressivement à mesure que ta force et ta coordination s''améliorent"]', '["Keep your core tight and back flat to avoid sagging hips or arching your spine", "Maintain steady breathing throughout the movement and avoid holding your breath", "Move in small steps to maintain better control and reduce strain on wrists and shoulders", "Keep your head in a neutral position looking slightly ahead rather than up or down", "Start with short distances and gradually increase as your strength and coordination improve"]', '214c3916-f02f-456f-9750-70fd0679295a', 'bear-crawls', NULL, NULL);
INSERT INTO public.exercises VALUES ('d23cfe14-3176-4fe0-b30e-d8f230995d12', 'Développé Épaules à la Machine derrière la Nuque', NULL, 'تمرين دفع الكتفين على الآلة من خلف الرقبة', 'Behind the Neck Shoulder Press Machine', 'Shoulders', '[]', 'Shoulders', 'Advanced', 8, '/videos/shoulders/behind-the-neck-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/behind-the-neck-press.jpg', NULL, '["Garde tes abdos engagés et maintiens une colonne vertébrale neutre pendant tout l''exercice.", "Évite de descendre la barre trop loin derrière ta nuque pour ne pas stresser les articulations des épaules.", "Adopte un tempo contrôlé durant les phases de poussée et de descente.", "Assure-toi d''avoir une bonne mobilité des épaules et fais un échauffement avant de réaliser cet exercice.", "Stoppe le mouvement si tu ressens une gêne ou un pincement au niveau de l''épaule."]', '["Ne pas ajuster la hauteur du siège correctement.", "Cambrer le dos excessivement pendant l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "behind the neck shoulder press machine"]', true, '2026-04-03 12:24:55.705187+00', '2026-04-03 12:24:55.705187+00', 'Position de départ : Assieds-toi droit sur la machine, le dos bien calé contre le dossier, les mains sur les poignées derrière ta nuque, les bras pliés à 90 degrés. Exécution : Pousse les poignées vers le haut jusqu''à ce que tes bras soient complètement tendus, puis redescends lentement à la position de départ derrière ta nuque.', '["Ne pas ajuster la hauteur du siège correctement.", "Cambrer le dos excessivement pendant l''exercice."]', true, '["Adjust the seat height so the handles align properly with your shoulder level", "Sit with your back firmly against the pad and engage your core for stability", "Grasp the handles with an overhand grip, positioning your hands slightly wider than shoulder-width", "Press the weight straight up in a controlled motion until your arms are fully extended overhead", "Lower the weight slowly back to the starting position, stopping when your upper arms are parallel to the floor", "Maintain proper posture throughout the entire movement without arching your back excessively"]', '["Ajuste la hauteur du siège pour que les poignées soient au niveau de tes épaules.", "Assieds-toi avec le dos bien plaqué contre le dossier et engage ton abdominal pour la stabilité.", "Prends les poignées avec une prise pronation, les mains légèrement plus larges que la largeur des épaules.", "Pousse le poids directement vers le haut de manière contrôlée jusqu''à ce que tes bras soient complètement étendus au-dessus de ta tête.", "Redescends le poids lentement à la position de départ, en t''arrêtant lorsque tes bras supérieurs sont parallèles au sol.", "Maintiens une posture correcte tout au long du mouvement sans trop cambrer le dos."]', '["Garde tes abdos engagés et maintiens une colonne vertébrale neutre pendant tout l''exercice.", "Évite de descendre la barre trop loin derrière ta nuque pour ne pas stresser les articulations des épaules.", "Adopte un tempo contrôlé durant les phases de poussée et de descente.", "Assure-toi d''avoir une bonne mobilité des épaules et fais un échauffement avant de réaliser cet exercice.", "Stoppe le mouvement si tu ressens une gêne ou un pincement au niveau de l''épaule."]', '["Keep your core engaged and maintain a neutral spine throughout the exercise", "Avoid lowering the bar too far behind your neck as this can stress the shoulder joints", "Use a controlled tempo on both the lifting and lowering phases", "Ensure adequate shoulder mobility and warm-up before performing this exercise", "Stop the movement if you feel any shoulder discomfort or impingement"]', '051a5802-da89-415d-a912-93162c89a4bf', 'behind-the-neck-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('614298bd-99ba-4ca1-a6bd-71e0ad9638c3', 'Bear Plank avec Pas Latéraux', NULL, 'Bear Plank avec Pas Latéraux', 'Bear plank side tap sidewalks', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/bear-plank-side-tap-sidewalks.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-plank-side-tap-sidewalks.jpg', NULL, '["Garde tes genoux constamment flottants à 5-8 cm du sol durant tout le mouvement", "Maintiens une forme de planche solide sans laisser tes hanches s''avachir ou se lever vers le ciel", "Avance lentement et de manière contrôlée pour renforcer l''engagement du centre et maintenir la bonne forme", "Garde ta tête en position neutre en regardant vers le sol pour protéger ton cou", "Assure-toi que tes mains restent sous tes épaules pendant que tu bouges latéralement"]', '["Laisser les hanches s''écarter trop haut ou trop bas", "Bouger trop rapidement, ce qui réduit l''engagement du core"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "bear plank side tap sidewalks"]', true, '2026-04-03 12:24:55.68025+00', '2026-04-03 12:24:55.68025+00', 'Position de départ : Mets-toi en position de bear plank, mains alignées sous les épaules, genoux flottant à 5-8 cm du sol, et le ventre bien contracté. Exécution : Fais un pas latéral en déplaçant simultanément ta main et ton pied opposés, puis reviens au centre et répète de l''autre côté dans un mouvement contrôlé.', '["Laisser les hanches s''écarter trop haut ou trop bas", "Bouger trop rapidement, ce qui réduit l''engagement du core"]', true, '["Start in bear plank with hands directly under shoulders and knees hovering just off the ground", "Engage your core and maintain a neutral spine throughout the movement", "Step your right hand and right foot simultaneously to the right about 12 inches", "Follow with your left hand and left foot to return to starting width", "Reverse the pattern by stepping left hand and left foot to the left, followed by right hand and foot", "Continue alternating directions for the prescribed number of repetitions or time"]', '["Commence en bear plank avec les mains sous les épaules et les genoux flottants juste au-dessus du sol", "Contracte ton ventre et garde une colonne vertébrale neutre durant tout le mouvement", "Fais un pas de 30 cm vers la droite avec ta main droite et ton pied droit en même temps", "Ramène ta position de départ en suivant avec ta main gauche et ton pied gauche", "Inverse le mouvement en déplaçant ta main gauche et ton pied gauche vers la gauche, suivi de la droite", "Continue à alterner les côtés pour le nombre de répétitions ou la durée prescrite"]', '["Garde tes genoux constamment flottants à 5-8 cm du sol durant tout le mouvement", "Maintiens une forme de planche solide sans laisser tes hanches s''avachir ou se lever vers le ciel", "Avance lentement et de manière contrôlée pour renforcer l''engagement du centre et maintenir la bonne forme", "Garde ta tête en position neutre en regardant vers le sol pour protéger ton cou", "Assure-toi que tes mains restent sous tes épaules pendant que tu bouges latéralement"]', '["Keep your knees consistently hovering 2-3 inches off the ground throughout the entire movement", "Maintain a strong plank position without letting your hips sag or pike upward", "Move slowly and controlled to maximize core engagement and maintain proper form", "Keep your head in neutral position looking down at the ground to protect your neck", "Ensure hands stay directly under shoulders as you move laterally"]', '63603235-6df6-4c55-b0fe-c417fee626b8', 'bear-plank-side-tap-sidewalks', NULL, NULL);
INSERT INTO public.exercises VALUES ('7a8d2ed1-d774-4f1b-92bf-aec9ddee86b7', 'Élévation Latérale Incliné avec Haltères', NULL, 'رفيعة الظهر سطحيّة مع الأثقال', 'Bent Over Dumbbell Rear Delt Raise', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/bent-over-dumbbell-rear-delt-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-over-dumbbell-rear-delt-raise.jpg', NULL, '["Utilise des haltères plus légers que pour d''autres exercices d''épaules, car les deltoïdes arrière sont des muscles plus petits", "Garde une légère flexion dans tes coudes tout au long du mouvement pour protéger tes articulations", "Concentre-toi sur la contraction de tes omoplates plutôt que simplement sur le fait de lever tes bras", "Maintiens la position inclinée tout au long de la série sans te redresser entre les répétitions", "Contrôle la phase de descente autant que celle de montée pour maximiser l''engagement musculaire"]', '["Ne pas plier suffisamment les hanches, ce qui entraîne une mauvaise posture", "Lever les haltères trop haut, ce qui réduit l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "bent over dumbbell rear delt raise"]', true, '2026-04-03 12:24:55.736437+00', '2026-04-03 12:24:55.736437+00', 'Position de départ : Penche-toi en avant avec le tronc, un haltère dans chaque main, paumes tournées vers l''intérieur. Exécution : Élève les haltères sur le côté jusqu''à la hauteur des épaules, puis abaisse-les lentement.', '["Ne pas plier suffisamment les hanches, ce qui entraîne une mauvaise posture", "Lever les haltères trop haut, ce qui réduit l''efficacité de l''exercice"]', true, '["Hold light dumbbells with a neutral grip and stand with feet hip-width apart", "Hinge at the hips and bend forward 45-60 degrees while keeping your back straight and core engaged", "Let the dumbbells hang straight down with arms slightly bent and palms facing each other", "Raise the weights out to the sides in a controlled arc until your arms are parallel to the floor", "Squeeze your shoulder blades together at the top of the movement", "Slowly lower the dumbbells back to the starting position with control"]', '["Tiens des haltères légers avec une prise neutre et place tes pieds à largeur des hanches", "Incline-toi au niveau des hanches et penche-toi de 45 à 60 degrés en gardant le dos droit et les abdominaux serrés", "Laisse les haltères pendre droit vers le bas avec les bras légèrement pliés et les paumes l''une en face de l''autre", "Lève les poids sur les côtés en arc contrôlé jusqu''à ce que tes bras soient parallèles au sol", "Contracte tes omoplates au sommet du mouvement", "Abaisse lentement les haltères en contrôlant le mouvement pour revenir à la position de départ"]', '["Utilise des haltères plus légers que pour d''autres exercices d''épaules, car les deltoïdes arrière sont des muscles plus petits", "Garde une légère flexion dans tes coudes tout au long du mouvement pour protéger tes articulations", "Concentre-toi sur la contraction de tes omoplates plutôt que simplement sur le fait de lever tes bras", "Maintiens la position inclinée tout au long de la série sans te redresser entre les répétitions", "Contrôle la phase de descente autant que celle de montée pour maximiser l''engagement musculaire"]', '["Use lighter weights than other shoulder exercises as the rear delts are smaller muscles", "Keep a slight bend in your elbows throughout the entire movement to protect your joints", "Focus on squeezing your shoulder blades together rather than just lifting your arms", "Maintain the hip-hinged position throughout the set without standing up between reps", "Control the lowering phase as much as the lifting phase to maximize muscle engagement"]', 'de70b78c-7dec-4a91-acc7-d75ae27eb765', 'bent-over-dumbbell-rear-delt-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('38f36336-3501-41dc-89ab-d9a3553d9cf1', 'Coups de pédale', NULL, 'ضربات الدراجة', 'Bicycle punches', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/bicycle-punches.mp4', NULL, NULL, NULL, '/videos/thumbnails/bicycle-punches.jpg', NULL, '["Garde le bas de ton dos bien plaqué au sol pour protéger ta colonne vertébrale", "Concentre-toi sur la rotation de ton ventre et ne tire pas sur ton cou avec tes mains", "Effectue des mouvements contrôlés sans précipitation pour une meilleure activation musculaire", "Maintiens ta jambe étendue juste au-dessus du sol sans toucher", "Respire régulièrement, en expirant pendant que tu crunches et frappes de l''autre côté."]', '["Ne pas maintenir le bas du dos au sol.", "Tirer sur le cou au lieu d''utiliser les muscles du ventre."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "bicycle punches"]', true, '2026-04-03 12:24:55.768172+00', '2026-04-03 12:24:55.768172+00', 'Position de départ : Allonge-toi sur le dos, mains derrière la tête, coudes écartés, jambes levées avec les genoux pliés à 90 degrés. Exécution : Alterne en ramenant un coude vers le genou opposé tout en étendant l''autre jambe, en ajoutant des mouvements de coup de poing avec tes bras pendant que tu fais pivoter ton torse.', '["Ne pas maintenir le bas du dos au sol.", "Tirer sur le cou au lieu d''utiliser les muscles du ventre."]', true, '["Lie flat on your back with hands lightly placed behind your head, avoiding interlacing fingers", "Lift your shoulders off the ground and raise both legs with knees bent at 90-degree angles", "Bring your right elbow toward your left knee while extending your right leg straight out", "As you rotate, punch across your body with the working arm while bring your other arm back", "Continue alternating sides in a controlled, rhythmic motion while maintaining core engagement"]', '["Allonge-toi sur le dos avec les mains légères derrière la tête, sans entrelacer les doigts", "Soulève les épaules du sol et lève les deux jambes avec les genoux pliés à 90 degrés", "Rapproche ton coude droit de ton genou gauche tout en étendant ta jambe droite", "En tournant, frappe avec le bras de travail tout en ramenant l''autre bras en arrière", "Continue d''alterner les côtés dans un mouvement contrôlé et rythmique tout en maintenant ton ventre engagé."]', '["Garde le bas de ton dos bien plaqué au sol pour protéger ta colonne vertébrale", "Concentre-toi sur la rotation de ton ventre et ne tire pas sur ton cou avec tes mains", "Effectue des mouvements contrôlés sans précipitation pour une meilleure activation musculaire", "Maintiens ta jambe étendue juste au-dessus du sol sans toucher", "Respire régulièrement, en expirant pendant que tu crunches et frappes de l''autre côté."]', '["Keep your lower back pressed against the floor throughout the movement to protect your spine", "Focus on rotating from your core rather than pulling on your neck with your hands", "Maintain controlled movements rather than rushing through the exercise for better muscle activation", "Keep your extended leg hovering just above the ground without touching down", "Breathe steadily, exhaling as you crunch and punch across your body"]', '87a9f879-77ef-4dbe-8e8e-b15fea5052a7', 'bicycle-punches', NULL, NULL);
INSERT INTO public.exercises VALUES ('6cbe5b16-84d8-4c92-bcfe-ab18bcd6fe97', 'Burpee', NULL, 'بوربي', 'Burpee', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/burpee.mp4', NULL, NULL, NULL, '/videos/thumbnails/burpee.jpg', NULL, '["Garde une bonne alignement pendant la pompe pour protéger ton dos.", "Atterris doucement sur la pointe des pieds lors des sauts pour réduire l''impact sur les articulations.", "Maintiens ton gainage engagé pendant tout le mouvement.", "Si besoin, modifie en sautant moins ou en supprimant la pompe.", "Concentre-toi sur la qualité des mouvements plutôt que sur la vitesse, surtout au début."]', '["Ne pas garder le dos droit lors de la pompe.", "Atterrir trop lourdement en sautant, ce qui peut blesser les articulations."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "burpee"]', true, '2026-04-03 12:24:55.830224+00', '2026-04-03 12:24:55.830224+00', 'Position de départ : Tiens-toi droit, pieds écartés à la largeur des épaules, bras le long du corps. Exécution : Descends en squat, pose les mains au sol, saute en position de planche, fais une pompe, ramène les pieds en squat, puis saute explosivement avec les bras au-dessus de la tête.', '["Ne pas garder le dos droit lors de la pompe.", "Atterrir trop lourdement en sautant, ce qui peut blesser les articulations."]', true, '["Begin standing with feet shoulder-width apart and engage your core", "Drop down into a deep squat position and place both hands flat on the floor in front of you", "Jump or step both feet back simultaneously to assume a plank position with straight body alignment", "Perform one push-up by lowering chest to the floor and pressing back up", "Jump or step both feet forward back to the squat position under your torso", "Explosively jump straight up reaching both arms overhead, then land softly to complete one repetition"]', '["Commence debout, pieds écartés à la largeur des épaules et engage ton gainage.", "Descends en squat profond et place tes deux mains à plat sur le sol devant toi.", "Saute ou fais un pas en arrière pour te mettre en position de planche avec le corps bien aligné.", "Effectue une pompe en abaissant ta poitrine vers le sol puis pousse pour remonter.", "Sautes ou fais un pas en avant pour revenir en position de squat sous ton corps.", "Saute explosivement vers le haut en levant les deux bras au-dessus de ta tête, puis atterris doucement pour compléter une répétition."]', '["Garde une bonne alignement pendant la pompe pour protéger ton dos.", "Atterris doucement sur la pointe des pieds lors des sauts pour réduire l''impact sur les articulations.", "Maintiens ton gainage engagé pendant tout le mouvement.", "Si besoin, modifie en sautant moins ou en supprimant la pompe.", "Concentre-toi sur la qualité des mouvements plutôt que sur la vitesse, surtout au début."]', '["Maintain proper plank alignment during the push-up phase to protect your lower back", "Land softly on the balls of your feet when jumping back and forward to reduce joint impact", "Keep your core engaged throughout the entire movement sequence", "Modify by stepping instead of jumping or eliminating the push-up component if needed", "Focus on controlled movement quality over speed, especially when learning the exercise"]', '24030adc-de07-4547-a916-24acee3d5a3e', 'burpee', NULL, NULL);
INSERT INTO public.exercises VALUES ('efa01543-b6de-4828-9bfd-a592a718f73a', 'Butt Kickers', NULL, 'ركلات المؤخرة', 'Butt kickers', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/butt-kickers.mp4', NULL, NULL, NULL, '/videos/thumbnails/butt-kickers.jpg', NULL, '["Concentre-toi sur le fait de ramener tes talons plutôt que de lever tes genoux pour cibler efficacement les ischio-jambiers.", "Maintiens un torse droit et évite de te pencher en avant pendant l''exercice.", "Commence à un rythme modéré et augmente progressivement la vitesse à mesure que tu te sens plus à l''aise avec la coordination.", "Garde le mouvement contrôlé pour éviter de trop étirer tes quadriceps et maintenir une bonne forme.", "Cet exercice est un excellent échauffement dynamique et un outil de conditionnement cardiovasculaire."]', '["Se pencher en avant au lieu de rester droit pendant l''exécution.", "Ne pas activer suffisamment le ventre, ce qui peut affecter l''équilibre."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "butt kickers"]', true, '2026-04-03 12:24:55.853138+00', '2026-04-03 12:24:55.853138+00', 'Position de départ : Tiens-toi bien droit, pieds écartés à la largeur des hanches, bras le long du corps ou pliés à 90 degrés. Exécution : Cours sur place en relevant les talons vers les fesses, en alternant rapidement les jambes.', '["Se pencher en avant au lieu de rester droit pendant l''exécution.", "Ne pas activer suffisamment le ventre, ce qui peut affecter l''équilibre."]', true, '["Stand tall with your core engaged and maintain good posture throughout the movement", "Begin by lifting one heel toward your glute while staying on the ball of your opposite foot", "Alternate legs quickly, focusing on bringing your heels as close to your glutes as possible", "Keep your thighs pointing toward the ground and avoid bringing your knees up high", "Pump your arms naturally as if you were running to maintain rhythm and balance", "Land softly on the balls of your feet to minimize impact on your joints"]', '["Tiens-toi droit avec ton ventre engagé et garde une bonne posture tout au long du mouvement.", "Commence par lever un talon vers tes fesses en te tenant sur la pointe de ton pied opposé.", "Alterne rapidement les jambes en visant à amener tes talons aussi près que possible de tes fesses.", "Garde les cuisses dirigées vers le sol et évite de trop lever tes genoux.", "Balance tes bras naturellement comme si tu courais pour maintenir ton rythme et ton équilibre.", "Atterris doucement sur la pointe de tes pieds pour minimiser l''impact sur tes articulations."]', '["Concentre-toi sur le fait de ramener tes talons plutôt que de lever tes genoux pour cibler efficacement les ischio-jambiers.", "Maintiens un torse droit et évite de te pencher en avant pendant l''exercice.", "Commence à un rythme modéré et augmente progressivement la vitesse à mesure que tu te sens plus à l''aise avec la coordination.", "Garde le mouvement contrôlé pour éviter de trop étirer tes quadriceps et maintenir une bonne forme.", "Cet exercice est un excellent échauffement dynamique et un outil de conditionnement cardiovasculaire."]', '["Focus on kicking your heels back rather than lifting your knees forward to properly target the hamstrings", "Maintain an upright torso and avoid leaning forward as you perform the movement", "Start at a moderate pace and gradually increase speed as you become more comfortable with the coordination", "Keep the movement controlled to prevent overstretching your quadriceps and maintain proper form", "This exercise serves as an excellent dynamic warm-up and cardiovascular conditioning tool"]', '1effe46b-4944-4308-b0d3-dd87a0c71bc2', 'butt-kickers', NULL, NULL);
INSERT INTO public.exercises VALUES ('6b6faae5-69d4-4c5d-a9e2-4e18c844e41e', 'Élévation de Hanches à la Corde', NULL, NULL, 'Cable Hip Extension', 'Glutes', '[]', 'Glutes', 'Beginner', 4, '/videos/glutes/cable-hip-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-hip-extension.jpg', NULL, '["Garde ton ventre bien engagé tout au long du mouvement pour éviter d''arquer le bas du dos", "Concentre-toi sur le mouvement au niveau de la hanche tout en gardant le genou relativement droit", "Évite de te pencher en avant ou d''utiliser l''élan pour balancer ta jambe vers l''arrière", "Contrôle le poids aussi bien en montant qu''en descendant", "Commence avec un poids léger pour maîtriser la technique avant de progresser"]', '["Bâcler le mouvement en utilisant l''élan", "Ne pas angle adéquat du genou ce qui peut entraîner une tension dans le bas du dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "cable", "cable hip extension"]', true, '2026-04-03 12:24:55.911739+00', '2026-04-03 12:24:55.911739+00', 'Position de départ : Fais face à une poulie basse avec une sangle autour de ta cheville, en plaçant ton pied légèrement derrière toi. Exécution : Étends ta jambe vers l''arrière tout en contractant tes fessiers, puis retourne lentement à la position de départ. Répète avec l''autre jambe.', '["Bâcler le mouvement en utilisant l''élan", "Ne pas angle adéquat du genou ce qui peut entraîner une tension dans le bas du dos"]', true, '["Attach the ankle cuff to your working leg and face the cable machine", "Hold onto the machine with both hands for stability and stand tall", "Position your working leg slightly forward with a soft knee", "Drive your leg straight back by contracting your glutes, keeping your torso upright", "Squeeze your glutes at the top of the movement for one second", "Slowly return your leg to the starting position with control"]', '["Attache la sangle à ta cheville sur la jambe active et fais face à la machine à câbles", "Tiens-toi à la machine avec les deux mains pour plus de stabilité et reste bien droit", "Positionne ta jambe active légèrement en avant, avec un genou légèrement fléchi", "Pousse ta jambe droit vers l''arrière en contractant tes fessiers, en gardant le torse droit", "Contracte tes fessiers au sommet du mouvement pendant une seconde", "Retourne lentement ta jambe à la position de départ avec contrôle"]', '["Garde ton ventre bien engagé tout au long du mouvement pour éviter d''arquer le bas du dos", "Concentre-toi sur le mouvement au niveau de la hanche tout en gardant le genou relativement droit", "Évite de te pencher en avant ou d''utiliser l''élan pour balancer ta jambe vers l''arrière", "Contrôle le poids aussi bien en montant qu''en descendant", "Commence avec un poids léger pour maîtriser la technique avant de progresser"]', '["Keep your core engaged throughout the movement to prevent lower back arching", "Focus on moving only at the hip joint while keeping your knee relatively straight", "Avoid leaning forward or using momentum to swing your leg back", "Control the weight on both the lifting and lowering phases of the movement", "Start with lighter weight to master the form before progressing"]', 'db7c0708-ea39-47cb-89c8-73e749abcfa6', 'cable-hip-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('223e82aa-9c3d-4581-ace4-2796278b8506', 'Élévation Frontale au Poulie', NULL, 'رفع أمامي بكابل', 'Cable Front Raise', 'Shoulders', '[]', 'Shoulders', 'Beginner', 4, '/videos/shoulders/cable-front-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-front-raise.jpg', NULL, '["Garde ton tronc engagé et évite d''utiliser l''élan ou de balancer le poids", "Maintiens une légère flexion des coudes tout au long du mouvement pour préserver l''articulation", "Arrête le mouvement ascendant quand tes bras sont parallèles au sol pour éviter les douleurs d''épaule", "Concentre-toi sur un mouvement lent et contrôlé autant à la montée qu''à la descente pour maximiser l''activation musculaire", "Commence avec un poids léger pour maîtriser la forme avant de progresser vers des résistances plus lourdes."]', '["Utiliser trop de poids et sacrifier la forme", "Ne pas faire attention à la posture du dos et des épaules", "Ne pas contrôler correctement la descente du poids", "Ecartement des pieds inapproprié, ce qui peut entraîner une instabilité"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "cable", "cable front raise"]', true, '2026-04-03 12:24:55.884216+00', '2026-04-03 12:24:55.884216+00', 'Position de départ : Tiens-toi face à la poulie avec les deux poignées en main, bras tendus vers le bas. Exécution : Élève les poignées vers l''avant jusqu''à atteindre la hauteur des épaules, puis redescends lentement.', '["Utiliser trop de poids et sacrifier la forme", "Ne pas faire attention à la posture du dos et des épaules", "Ne pas contrôler correctement la descente du poids", "Ecartement des pieds inapproprié, ce qui peut entraîner une instabilité"]', true, '["Set the cable pulley to the lowest position and attach a straight bar or rope handle", "Stand 2-3 feet away from the machine with feet shoulder-width apart for stability", "Grasp the handle with an overhand grip, keeping a slight bend in your elbows throughout the movement", "Engage your core and maintain upright posture with shoulders back", "Raise the handle forward and up until your arms reach shoulder height, focusing on controlled movement", "Lower the weight slowly back to starting position, maintaining tension throughout the entire range of motion"]', '["Place la poulie à la position la plus basse et fixe une barre droite ou une poignée en corde", "Positionne-toi à 60-90 cm de la machine, pieds écartés à la largeur des épaules pour plus de stabilité", "Saisis la poignée avec une prise en pronation, avec une légère flexion des coudes durant tout le mouvement", "Active ton tronc et garde une posture droite avec les épaules en arrière", "Lève la poignée vers l''avant et vers le haut jusqu''à ce que tes bras atteignent la hauteur des épaules, en te concentrant sur un mouvement contrôlé", "Redescends lentement le poids à la position de départ, en maintenant la tension tout au long de l''amplitude de mouvement."]', '["Garde ton tronc engagé et évite d''utiliser l''élan ou de balancer le poids", "Maintiens une légère flexion des coudes tout au long du mouvement pour préserver l''articulation", "Arrête le mouvement ascendant quand tes bras sont parallèles au sol pour éviter les douleurs d''épaule", "Concentre-toi sur un mouvement lent et contrôlé autant à la montée qu''à la descente pour maximiser l''activation musculaire", "Commence avec un poids léger pour maîtriser la forme avant de progresser vers des résistances plus lourdes."]', '["Keep your core engaged and avoid using momentum or swinging the weight up", "Maintain a slight bend in your elbows throughout the entire movement to protect the joint", "Stop the upward motion when your arms reach parallel to the floor to avoid shoulder impingement", "Focus on slow, controlled movement both on the way up and down to maximize muscle activation", "Start with lighter weight to master the form before progressing to heavier resistance"]', '697ec8a9-34fe-419e-a1b8-825456a3b335', 'cable-front-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('5a4ef4d8-d0cb-4cf6-82d5-3366b9d343ee', 'Élévation des Deltoïdes Postérieurs avec Câble', NULL, NULL, 'Cable Rear Delt Fly', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 4, '/videos/shoulders/cable-rear-delt-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-rear-delt-fly.jpg', NULL, '["Engage ton core et penche-toi légèrement en avant pour éviter d''utiliser l''élan", "Concentre-toi sur le mouvement initié par tes deltoïdes arrières, pense à rapprocher tes omoplates", "Utilise un poids qui te permet de contrôler la phase excentrique pour une activation musculaire maximale", "Évite de laisser tes épaules s''affaisser à la position de départ pour maintenir une bonne posture", "Garde tes poignets neutres et mène le tirage avec tes petits doigts pour mieux cibler les deltoïdes arrières"]', '["Laisser les coudes trop écartés durant le mouvement", "Ne pas contrôler le retour à la position de départ, ce qui réduit l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "cable", "cable rear delt fly"]', true, '2026-04-03 12:24:55.943908+00', '2026-04-03 12:24:55.943908+00', 'Position de départ : Fais face à une poulie basse avec un câble dans chaque main, paumes vers le bas. Exécution : Élève les câbles vers l''arrière tout en gardant les coudes légèrement fléchis, puis redescends lentement à la position de départ.', '["Laisser les coudes trop écartés durant le mouvement", "Ne pas contrôler le retour à la position de départ, ce qui réduit l''efficacité de l''exercice"]', true, '["Set both cable pulleys to shoulder height and attach single handles to each side", "Stand in the center with feet shoulder-width apart, grab the left handle with your right hand and right handle with your left hand", "Step back until there is tension in the cables with your arms extended forward at shoulder height", "Pull both handles back simultaneously in a wide arc, leading with your pinkies and keeping a slight bend in your elbows", "Squeeze your shoulder blades together at the end range of motion, feeling the contraction in your rear delts", "Slowly return to the starting position with control, maintaining tension throughout the entire range of motion"]', '["Régle les poulies à hauteur d''épaules et fixe des poignées uniques de chaque côté", "Positionne-toi au centre, les pieds écartés à la largeur des épaules, prends la poignée gauche avec ta main droite et celle de droite avec ta main gauche", "Recule jusqu''à ressentir la tension dans les câbles, bras tendus vers l''avant à hauteur d''épaules", "Tire les deux poignées vers l''arrière en arc large, en menant avec les petits doigts et en gardant une légère flexion des coudes", "Squeeze tes omoplates à la fin du mouvement pour ressentir la contraction dans tes deltoïdes arrières", "Redescends lentement à la position de départ avec contrôle, en maintenant la tension durant tout le mouvement"]', '["Engage ton core et penche-toi légèrement en avant pour éviter d''utiliser l''élan", "Concentre-toi sur le mouvement initié par tes deltoïdes arrières, pense à rapprocher tes omoplates", "Utilise un poids qui te permet de contrôler la phase excentrique pour une activation musculaire maximale", "Évite de laisser tes épaules s''affaisser à la position de départ pour maintenir une bonne posture", "Garde tes poignets neutres et mène le tirage avec tes petits doigts pour mieux cibler les deltoïdes arrières"]', '["Keep your core engaged and maintain a slight forward lean to prevent using momentum", "Focus on initiating the movement from your rear delts rather than your arms by thinking about pulling your shoulder blades together", "Use a weight that allows you to control the eccentric portion of the movement for maximum muscle activation", "Avoid letting your shoulders roll forward at the starting position to maintain proper posture", "Keep your wrists neutral and lead the pull with your pinkies to better target the rear deltoids"]', 'd237c00f-e6f3-44f0-953b-5db4c970f873', 'cable-rear-delt-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('a257482d-28db-47fa-9c0d-1ec3d831fd77', 'Étirer les mollets (droit)', NULL, 'تمارين إطالة عضلات الساق (اليمنى)', 'Calf stretch (right)', 'Calves', '[]', 'Calves', 'Beginner', 16, '/videos/calves/calf-stretch-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/calf-stretch-right.jpg', NULL, '["Garde tes mains bien ancrées et les bras droits pour un meilleur soutien.", "Engage ton cœur tout au long de l''étirement pour éviter les douleurs lombaires.", "La jambe de soutien doit rester au sol avec le genou légèrement fléchi pour plus d''équilibre.", "Concentre-toi sur la sensation d''étirement dans le mollet de la jambe surélevée, ne force pas la position.", "Commence par des temps de maintien plus courts et augmente progressivement à mesure que ta flexibilité s''améliore."]', '["Ne pas engager les abdominaux, ce qui peut causer des douleurs.", "Forcer l''étirement au lieu de se concentrer sur la sensation."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["calves", "bodyweight", "calf stretch (right)"]', true, '2026-04-03 12:24:56.03033+00', '2026-04-03 12:24:56.03033+00', 'Position de départ : Accroupis-toi en position de bear crawl avec les mains au sol, un pied posé sur une balle de massage ou un rouleau, et l''autre pied bien ancré au sol. Action : Reste dans cette position pour étirer le muscle du mollet de la jambe surélevée, tout en maintenant la stabilité avec tes bras et ta jambe de soutien.', '["Ne pas engager les abdominaux, ce qui peut causer des douleurs.", "Forcer l''étirement au lieu de se concentrer sur la sensation."]', true, '["Start in a bear crawl position with hands planted firmly on the ground shoulder-width apart", "Place one foot on top of a massage ball or foam roller while keeping the other foot flat on the ground", "Keep your arms straight and core engaged to maintain stability", "Hold the stretch position, allowing the elevated leg''s calf to lengthen over the ball", "Breathe deeply and maintain the position for the desired duration", "Switch legs to stretch the opposite calf"]', '["Commence en position de bear crawl, les mains fermement posées au sol à la largeur des épaules.", "Place un pied sur une balle de massage ou un rouleau tout en gardant l''autre pied plat au sol.", "Garde les bras droits et engage ton cœur pour assurer la stabilité.", "Maintiens la position d''étirement pour allonger le mollet de la jambe surélevée.", "Respire profondément et reste dans la position le temps souhaité.", "Change de jambe pour étirer l''autre mollet."]', '["Garde tes mains bien ancrées et les bras droits pour un meilleur soutien.", "Engage ton cœur tout au long de l''étirement pour éviter les douleurs lombaires.", "La jambe de soutien doit rester au sol avec le genou légèrement fléchi pour plus d''équilibre.", "Concentre-toi sur la sensation d''étirement dans le mollet de la jambe surélevée, ne force pas la position.", "Commence par des temps de maintien plus courts et augmente progressivement à mesure que ta flexibilité s''améliore."]', '["Keep your hands firmly planted and arms straight to provide stable support", "Maintain core engagement throughout the stretch to prevent lower back strain", "The supporting leg should remain planted with knee slightly bent for balance", "Focus on feeling the stretch in the calf of the elevated leg rather than forcing the position", "Start with shorter hold times and gradually increase as flexibility improves"]', '5ce9ef64-7527-4321-997b-1d1bc071f91a', 'calf-stretch-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('6ac028e6-d686-4897-b47b-5b53814de653', 'Développé Incliné Prise Serrée avec Haltères', NULL, NULL, 'Close Grip Incline Dumbbell Press', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/close-grip-incline-dumbbell-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/close-grip-incline-dumbbell-press.jpg', NULL, '["Garde les haltères proches l''un de l''autre pendant tout le mouvement pour maximiser l''activation de la partie intérieure des pectoraux", "Maintiens une colonne vertébrale neutre et évite de cambrer excessivement le dos lors du développé", "Contrôle la phase excentrique (descente) pour maximiser la tension musculaire et éviter les blessures", "Concentre-toi sur la contraction de tes muscles pectoraux en haut de chaque répétition pour un engagement musculaire optimal", "Garde les pieds à plat sur le sol et le core engagé pour la stabilité durant l''exercice"]', '["Ne pas descendre assez bas, ce qui limite l''étirement des pectoraux", "Laisser les haltères s''éloigner l''un de l''autre, ce qui réduit l''activation musculaire"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "close grip incline dumbbell press"]', true, '2026-04-03 12:24:56.08893+00', '2026-04-03 12:24:56.08893+00', 'Position de départ : Allonge-toi sur un banc incliné avec un haltère dans chaque main, bras tendus vers le haut, paumes face à face. Exécution : Descends les haltères jusqu''à la poitrine en gardant les coudes près du corps, puis pousse vers le haut pour revenir à la position de départ.', '["Ne pas descendre assez bas, ce qui limite l''étirement des pectoraux", "Laisser les haltères s''éloigner l''un de l''autre, ce qui réduit l''activation musculaire"]', true, '["Set the incline bench to a 30-45 degree angle and lie back with your head, shoulders, and glutes firmly pressed against the pad", "Hold dumbbells with a neutral grip, positioning them close together above your chest with arms fully extended", "Slowly lower the dumbbells toward the center of your chest, keeping them close together throughout the descent", "Pause briefly when the dumbbells reach chest level, feeling a stretch in your chest muscles", "Press the dumbbells back up along the same path, focusing on squeezing your chest muscles at the top", "Maintain control throughout the entire range of motion and avoid letting the dumbbells drift apart"]', '["Régle le banc incliné à un angle de 30 à 45 degrés et allonge-toi en gardant la tête, les épaules et les fessiers bien en contact avec le banc", "Tiens les haltères avec une prise neutre, en les plaçant proches l''un de l''autre au-dessus de ta poitrine avec les bras complètement étendus", "Descends lentement les haltères vers le centre de ta poitrine, en les gardant proches l''un de l''autre durant toute la descente", "Fais une pause brève lorsque les haltères atteignent le niveau de ta poitrine, en ressentant un étirement dans tes muscles pectoraux", "Pousse les haltères vers le haut le long du même chemin, en te concentrant sur la contraction de tes muscles pectoraux en haut", "Maintiens le contrôle pendant toute l''amplitude du mouvement et évite que les haltères s''écartent"]', '["Garde les haltères proches l''un de l''autre pendant tout le mouvement pour maximiser l''activation de la partie intérieure des pectoraux", "Maintiens une colonne vertébrale neutre et évite de cambrer excessivement le dos lors du développé", "Contrôle la phase excentrique (descente) pour maximiser la tension musculaire et éviter les blessures", "Concentre-toi sur la contraction de tes muscles pectoraux en haut de chaque répétition pour un engagement musculaire optimal", "Garde les pieds à plat sur le sol et le core engagé pour la stabilité durant l''exercice"]', '["Keep the dumbbells close together throughout the entire movement to maximize inner chest activation", "Maintain a neutral spine and avoid arching your back excessively during the press", "Control the eccentric (lowering) portion of the lift to maximize muscle tension and prevent injury", "Focus on squeezing your chest muscles at the top of each repetition for optimal muscle engagement", "Keep your feet flat on the floor and core engaged for stability throughout the exercise"]', 'd18679b0-3ce0-409b-9955-584976544f45', 'close-grip-incline-dumbbell-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('6000586a-66c7-4309-82ca-565881706884', 'Développé couché serré avec disque', NULL, NULL, 'Close Grip Plate Press', 'Chest', '[]', 'Chest', 'Intermediate', 1, '/videos/chest/close-grip-plate-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/close-grip-plate-press.jpg', NULL, '["Engage ton core et maintiens une bonne posture pendant toute l''exercice.", "Assure-toi d''avoir une prise solide sur le disque pour éviter qu''il ne glisse.", "Concentre-toi sur la contraction de tes muscles pectoraux en poussant le poids vers le haut.", "Garde tes coudes à un angle contrôlé et évite de les écarter trop.", "Commence avec un poids léger pour maîtriser la forme avant de progresser."]', '["Laisser les coudes s''écarter trop largement pendant le mouvement.", "Ne pas contrôler la descente du disque et aller trop vite."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "barbell", "close grip plate press"]', true, '2026-04-03 12:24:56.121134+00', '2026-04-03 12:24:56.121134+00', 'Position de départ : Assieds-toi sur un banc en tenant un disque avec les deux mains, les bras tendus devant ta poitrine. Exécution : Abaisse le disque vers ta poitrine en pliant les coudes, puis pousse-le vers le haut en redressant les bras.', '["Laisser les coudes s''écarter trop largement pendant le mouvement.", "Ne pas contrôler la descente du disque et aller trop vite."]', true, '["Sit upright on a bench with your back supported and feet planted firmly on the floor", "Grip the weight plate with both hands using your palms, keeping your hands close together", "Start with arms extended in front of your chest, holding the plate securely", "Lower the plate slowly toward your chest by bending your elbows outward", "Press the plate back up to the starting position by straightening your arms", "Maintain control throughout the entire range of motion"]', '["Assieds-toi droit sur un banc, le dos bien soutenu et les pieds bien ancrés au sol.", "Prends le disque avec les deux mains, les paumes serrées l''une contre l''autre.", "Commence avec les bras tendus devant ta poitrine, en tenant fermement le disque.", "Abaisse le disque lentement vers ta poitrine en pliant les coudes vers l''extérieur.", "Repousse le disque vers la position de départ en redressant les bras.", "Garde toujours le contrôle tout au long du mouvement."]', '["Engage ton core et maintiens une bonne posture pendant toute l''exercice.", "Assure-toi d''avoir une prise solide sur le disque pour éviter qu''il ne glisse.", "Concentre-toi sur la contraction de tes muscles pectoraux en poussant le poids vers le haut.", "Garde tes coudes à un angle contrôlé et évite de les écarter trop.", "Commence avec un poids léger pour maîtriser la forme avant de progresser."]', '["Keep your core engaged and maintain good posture throughout the movement", "Use a secure grip on the plate to prevent it from slipping", "Focus on squeezing your chest muscles as you press the weight up", "Keep your elbows at a controlled angle rather than flaring them too wide", "Start with a lighter weight to master the form before progressing"]', '10d2c91e-60e8-416d-8c91-def45954009c', 'close-grip-plate-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('5bd74aa3-fbbd-47b0-8adb-79aa4dc54421', 'Posture de la vache', NULL, 'وضعية البقرة', 'Cow pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/cow-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/cow-pose.jpg', NULL, '["Garde les bras droits tout au long de l''exercice.", "Ouvre bien la poitrine et les clavicules.", "Engage le mouvement en partant du bassin."]', '["Ne pas maintenir les poignets alignés sous les épaules.", "Laisser tomber la tête vers le sol."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "cow pose"]', true, '2026-04-03 12:24:56.171525+00', '2026-04-03 12:24:56.171525+00', 'Position de départ : Place-toi à quatre pattes, poignets sous les épaules et genoux sous les hanches. Exécution : Creuse doucement le dos en laissant ton ventre tomber vers le sol tout en levant la poitrine et le coccyx vers le plafond.', '["Ne pas maintenir les poignets alignés sous les épaules.", "Laisser tomber la tête vers le sol."]', true, '["Start on all fours with wrists under shoulders and knees under hips.", "Inhale, drop your belly toward the mat.", "Lift your chest and tailbone toward the ceiling.", "Hold for a few breaths, then release."]', '["Commence à quatre pattes, poignets sous les épaules et genoux sous les hanches.", "Inspire et fais descendre ton ventre vers le tapis.", "Lève ta poitrine et ton coccyx vers le plafond.", "Maintiens la position quelques respirations, puis relâche."]', '["Garde les bras droits tout au long de l''exercice.", "Ouvre bien la poitrine et les clavicules.", "Engage le mouvement en partant du bassin."]', '["Keep arms straight throughout.", "Broaden your chest and collarbones.", "Initiate the movement from your pelvis."]', '3d8fe08e-93ba-49ac-b5f9-92dbac0d39b2', 'cow-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('aa7c45b6-3c54-4744-8f60-cce789d103c0', 'Pompes Deadstop', NULL, 'كماشة ميتة', 'Deadstop push ups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/deadstop-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/deadstop-push-ups.jpg', NULL, '["La pause avec les mains relevées annihile l''élan et vous oblige à développer la puissance depuis un arrêt total", "Gardez votre sangle abdominale engagée pour éviter que vos hanches ne s''affaissent ou que votre dos ne se cambre excessivement", "Cette variante est nettement plus difficile que les pompes classiques, ajustez donc le nombre de répétitions en conséquence", "Concentrez-vous sur un mouvement explosif vers le haut tout en gardant le contrôle pendant la descente", "Assurez-vous de toucher réellement votre poitrine au sol à chaque répétition pour un mouvement complet"]', '["Ne pas toucher le sol avec la poitrine", "Ne pas maintenir un corps aligné et rigide pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "deadstop push ups"]', true, '2026-04-03 12:24:56.262371+00', '2026-04-03 12:24:56.262371+00', 'Position de départ : Adoptez une position standard de pompes avec les mains légèrement plus larges que les épaules, votre corps formant une ligne droite de la tête aux talons. Exécution : Abaissez votre poitrine jusqu''au sol, marquez une pause brève tout en relâchant légèrement vos mains et en les soulevant du sol, puis appuyez vos mains fermement et poussez explosivement pour revenir à la position de départ.', '["Ne pas toucher le sol avec la poitrine", "Ne pas maintenir un corps aligné et rigide pendant l''exercice"]', true, '["Set up in a standard push-up position with hands slightly wider than shoulders and body forming a straight line", "Lower your body slowly and under control until your chest touches the floor", "Once at the bottom, briefly lift your hands 1-2 inches off the ground while keeping your body rigid", "Press your hands firmly back to the floor and push up explosively to return to starting position", "Maintain proper body alignment throughout the entire movement", "Rest briefly between repetitions to maintain form quality"]', '["Installez-vous en position de pompes standard avec les mains légèrement plus larges que les épaules et le corps bien aligné", "Abaissez votre corps lentement et avec contrôle jusqu''à ce que votre poitrine touche le sol", "Lorsque vous êtes en bas, relevez brièvement vos mains de 2 à 5 centimètres du sol tout en maintenant votre corps rigide", "Enfoncez vos mains dans le sol et poussez explosivement pour revenir à la position de départ", "Gardez un bon alignement du corps pendant tout le mouvement", "Repos court entre les répétitions pour préserver la qualité de l''exécution"]', '["La pause avec les mains relevées annihile l''élan et vous oblige à développer la puissance depuis un arrêt total", "Gardez votre sangle abdominale engagée pour éviter que vos hanches ne s''affaissent ou que votre dos ne se cambre excessivement", "Cette variante est nettement plus difficile que les pompes classiques, ajustez donc le nombre de répétitions en conséquence", "Concentrez-vous sur un mouvement explosif vers le haut tout en gardant le contrôle pendant la descente", "Assurez-vous de toucher réellement votre poitrine au sol à chaque répétition pour un mouvement complet"]', '["The brief pause with hands lifted eliminates momentum and forces you to generate power from a complete stop", "Keep your core engaged throughout to prevent sagging hips or arching your back excessively", "This variation is significantly more challenging than regular push-ups, so reduce repetitions accordingly", "Focus on explosive upward movement while maintaining control during the descent", "Ensure full range of motion by actually touching your chest to the floor each repetition"]', '76741ca2-8960-4323-a495-c595291e3c56', 'deadstop-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('6d1b4c0c-1224-49dd-b1de-7a63f0695b83', 'Dips - Triceps Version', NULL, 'Dips - Version Triceps', 'Dips - Triceps Version', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/dips-triceps-version.mp4', NULL, NULL, NULL, '/videos/thumbnails/dips-triceps-version.jpg', NULL, '["Contracte bien ton core durant tout l''exercice pour garder une bonne posture", "Contrôle la descente - évite de tomber trop vite", "Garde les épaules basses et en arrière, ne te penche pas en avant", "Concentre-toi sur l''utilisation de tes triceps et de tes muscles pectoraux, pas sur l''élan", "Si c''est trop difficile, plie les genoux ou pose tes pieds au sol pour t''aider"]', '["Ne pas descendre suffisamment et ne pas ressentir d’étirement", "Laisser les épaules se soulever et se tendre au lieu de rester détendues"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "dips - triceps version"]', true, '2026-04-03 12:24:56.321059+00', '2026-04-03 12:24:56.321059+00', 'Position de départ : Assieds-toi au sol, les jambes tendues devant toi. Place tes mains sur le sol ou sur des poignées à côté de tes hanches, en t’appuyant sur tes bras. Exécution : Abaisse ton corps en fléchissant les coudes, puis pousse-toi vers le haut pour revenir à la position de départ en tendant les bras.', '["Ne pas descendre suffisamment et ne pas ressentir d’étirement", "Laisser les épaules se soulever et se tendre au lieu de rester détendues"]', true, '["Position yourself sitting on the floor with legs extended straight in front of you", "Place your hands on the ground or grip handles beside your hips, fingers pointing forward", "Support your body weight on your arms with shoulders directly over your hands", "Lower your body by bending your elbows, keeping them close to your sides", "Descend until you feel a stretch in your triceps or chest", "Press through your palms to straighten your arms and return to starting position"]', '["Asseyez-vous sur le sol avec les jambes tendues devant vous", "Placez vos mains sur le sol ou sur des poignées à côté de vos hanches, les doigts pointant vers l''avant", "Supportez votre poids sur vos bras, les épaules directement au-dessus des mains", "Abaissez votre corps en fléchissant les coudes, en les gardant près du corps", "Descendez jusqu''à ressentir une légère tension dans vos triceps ou votre poitrine", "Poussez avec vos paumes pour redresser vos bras et revenir à la position de départ"]', '["Contracte bien ton core durant tout l''exercice pour garder une bonne posture", "Contrôle la descente - évite de tomber trop vite", "Garde les épaules basses et en arrière, ne te penche pas en avant", "Concentre-toi sur l''utilisation de tes triceps et de tes muscles pectoraux, pas sur l''élan", "Si c''est trop difficile, plie les genoux ou pose tes pieds au sol pour t''aider"]', '["Keep your core engaged throughout the movement to maintain proper posture", "Control the descent - avoid dropping down too quickly", "Keep your shoulders down and back, avoiding hunching forward", "Focus on using your triceps and chest muscles rather than momentum", "If too difficult, bend your knees or place feet on the ground for assistance"]', '60ec7728-577b-4dea-a5e9-4b8ac16b6038', 'dips-triceps-version', NULL, NULL);
INSERT INTO public.exercises VALUES ('57146eb2-25bc-4f51-82fe-16b474d32e9f', 'Donkey Kick avec Haltère', NULL, 'Donkey Kick avec Haltère', 'Donkey Kick with Dumbbell', 'Glutes', '[]', 'Glutes', 'Intermediate', 2, '/videos/glutes/donkey-kick-with-dumbbell.mp4', NULL, NULL, NULL, '/videos/thumbnails/donkey-kick-with-dumbbell.jpg', NULL, '["Garde les hanches carrées et évite de faire pivoter ton bassin durant le mouvement", "Concentre-toi sur l''utilisation de tes muscles fessiers plutôt que sur l''élan pour soulever le poids", "Respire régulièrement, évite de retenir ta respiration pendant l''exercice", "Commence avec un poids léger pour maîtriser la technique avant de passer à des haltères plus lourds", "Garde ton bras de soutien droit et évite de creuser le bas du dos"]', '["Ne pas garder les hanches alignées.", "Utiliser de l''élan au lieu de contracter les muscles fessiers."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "dumbbell", "donkey kick with dumbbell"]', true, '2026-04-03 12:24:56.34491+00', '2026-04-03 12:24:56.34491+00', 'Mets-toi en position à quatre pattes, un haltère placé derrière un de tes genoux. Enlève-toi la tête, engage ton tronc et lève ta jambe en poussant l''haltère vers le ciel, puis redescends doucement. Répète avec l''autre jambe.', '["Ne pas garder les hanches alignées.", "Utiliser de l''élan au lieu de contracter les muscles fessiers."]', true, '["Position yourself on hands and knees with wrists under shoulders and knees under hips", "Secure a light dumbbell behind one knee by bending your leg and gripping the weight between your hamstring and calf", "Engage your core and maintain a neutral spine throughout the movement", "Lift the leg with the dumbbell up and back, driving through your heel while keeping the knee bent", "Squeeze your glute at the top of the movement, then slowly lower back to starting position", "Complete all reps on one side before switching to the other leg"]', '["Positionne-toi sur les mains et les genoux, poignets sous les épaules, genoux sous les hanches", "Place un haltère léger derrière un de tes genoux en fléchissant ta jambe pour maintenir le poids entre ta cuisse et ton mollet", "Engage ton cœur et garde le dos bien droit durant tout le mouvement", "Lève la jambe avec l''haltère vers le haut et l''arrière, en poussant avec ton talon tout en gardant le genou fléchi", "Contracte ton fessier en haut du mouvement, puis redescends lentement à la position de départ", "Effectue toutes les répétitions d''un côté avant de changer de jambe"]', '["Garde les hanches carrées et évite de faire pivoter ton bassin durant le mouvement", "Concentre-toi sur l''utilisation de tes muscles fessiers plutôt que sur l''élan pour soulever le poids", "Respire régulièrement, évite de retenir ta respiration pendant l''exercice", "Commence avec un poids léger pour maîtriser la technique avant de passer à des haltères plus lourds", "Garde ton bras de soutien droit et évite de creuser le bas du dos"]', '["Keep your hips square and avoid rotating your pelvis during the movement", "Focus on using your glute muscles rather than momentum to lift the weight", "Maintain steady breathing and avoid holding your breath during the exercise", "Start with a lighter weight to master the form before progressing to heavier dumbbells", "Keep your supporting arm straight and avoid sagging through your lower back"]', 'fbffd9c1-bffd-4fb0-ae4c-258834c5fcd2', 'donkey-kick-with-dumbbell', NULL, NULL);
INSERT INTO public.exercises VALUES ('ebd32b8e-7f86-4594-b048-25694338282c', 'Pompes explosif avec genou vers le poitrine', NULL, NULL, 'Drop dead push up into knee in', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/drop-dead-push-up-into-knee-in.mp4', NULL, NULL, NULL, '/videos/thumbnails/drop-dead-push-up-into-knee-in.jpg', NULL, '["Garde le ventre bien serré tout au long du mouvement pour rester stable", "Atterris doucement en descendant et en remontant pour protéger tes articulations", "Maintiens une bonne forme de pompe avec une ligne droite de la tête aux talons", "Alterner le genou que tu amènes vers ta poitrine à chaque répétition", "Contrôle la vitesse lors de la partie pompe tout en permettant un mouvement explosif lors des transitions"]', '["Ne pas garder le ventre engagé, ce qui destabilise", "Descendre trop rapidement en pompe, ce qui entraîne une mauvaise forme"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "drop dead push up into knee in"]', true, '2026-04-03 12:24:56.374519+00', '2026-04-03 12:24:56.374519+00', 'Position de départ : Debout, les pieds écartés à la largeur des hanches et les bras le long du corps. Exécution : Descends en position de pompes, fais une pompe, puis ramène énergiquement un genou vers ta poitrine avant de revenir en position debout.', '["Ne pas garder le ventre engagé, ce qui destabilise", "Descendre trop rapidement en pompe, ce qui entraîne une mauvaise forme"]', true, '["Start in a standing position with feet hip-width apart", "Drop down by placing hands on the ground and jumping feet back into plank position", "Perform one controlled push-up with proper form", "After pushing up, explosively drive one knee toward your chest while in plank position", "Return the knee back to plank position", "Jump feet forward toward hands and return to standing position"]', '["Commence debout, pieds écartés à la largeur des hanches", "Descends en plaçant les mains au sol et saute les pieds en arrière en position de planche", "Réalise une pompe contrôlée en gardant une bonne forme", "Après avoir poussé, ramène explosivement un genou vers ta poitrine en position de planche", "Ramène le genou en arrière vers la position de planche", "Saute les pieds vers les mains et reviens en position debout"]', '["Garde le ventre bien serré tout au long du mouvement pour rester stable", "Atterris doucement en descendant et en remontant pour protéger tes articulations", "Maintiens une bonne forme de pompe avec une ligne droite de la tête aux talons", "Alterner le genou que tu amènes vers ta poitrine à chaque répétition", "Contrôle la vitesse lors de la partie pompe tout en permettant un mouvement explosif lors des transitions"]', '["Keep your core engaged throughout the entire movement to maintain stability", "Land softly when dropping down and jumping back up to protect your joints", "Maintain proper push-up form with straight line from head to heels", "Alternate which knee you bring to chest with each repetition", "Control the tempo during the push-up portion while allowing explosive movement during transitions"]', 'cfa3229b-10a2-42cd-bdf0-4fa80ce51fd3', 'drop-dead-push-up-into-knee-in', NULL, NULL);
INSERT INTO public.exercises VALUES ('055043de-d1ca-40d2-adbd-458b821092eb', 'Développé couché avec haltères au sol', NULL, NULL, 'Dumbbell floor chest press', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/dumbbell-floor-chest-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-floor-chest-press.jpg', NULL, '["Gardez votre sangle abdominale engagée et votre colonne vertébrale neutre pendant l''exercice", "Le sol sert de butée de sécurité naturelle, évitant ainsi une hyperextension de l''articulation de l''épaule", "Concentrez-vous sur la contraction de vos muscles pectoraux plutôt que sur le simple mouvement du poids", "Adoptez un tempo contrôlé avec une phase de descente de 2 à 3 secondes pour un maximum d''engagement musculaire", "Commencez avec des poids plus légers que pour un développé couché traditionnel, car le sol limite votre amplitude de mouvement."]', '["Ne pas maintenir la stabilité des pieds sur le sol", "Utiliser des poids trop lourds qui compromettent la technique"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "dumbbell floor chest press"]', true, '2026-04-03 12:24:56.436047+00', '2026-04-03 12:24:56.436047+00', 'Position de départ : Allongez-vous sur le dos, les genoux fléchis et les pieds bien à plat sur le sol. Attrapez des haltères à niveau de la poitrine, les bras tendus vers le haut, paumes face à vous. Exécution : Abaissez les haltères jusqu''à ce que vos bras supérieurs touchent le sol, puis poussez les poids vers le haut en contractant les muscles de votre poitrine.', '["Ne pas maintenir la stabilité des pieds sur le sol", "Utiliser des poids trop lourds qui compromettent la technique"]', true, '["Lie on your back with knees bent and feet flat on the floor for stability", "Hold dumbbells with an overhand grip, arms extended above your chest with a slight bend in your elbows", "Slowly lower the dumbbells out to the sides in a wide arc until your upper arms gently touch the floor", "Pause briefly when your arms reach the floor, feeling a stretch in your chest", "Press the dumbbells back up along the same arc path, squeezing your chest muscles at the top", "Maintain control throughout the entire range of motion, avoiding bouncing off the floor"]', '["Allongez-vous sur le dos, genoux fléchis et pieds à plat au sol pour plus de stabilité", "Tenez des haltères avec une prise pronation, bras tendus au-dessus de votre poitrine avec un léger pli au niveau des coudes", "Abaissez lentement les haltères sur les côtés en arc large jusqu''à ce que vos bras supérieurs touchent délicatement le sol", "Marquez une pause lorsque vos bras atteignent le sol, en ressentant un étirement dans votre poitrine", "Poussez les haltères vers le haut en suivant le même arc, en contractant vos muscles pectoraux en haut", "Maintenez le contrôle pendant tout le mouvement, sans rebondir sur le sol."]', '["Gardez votre sangle abdominale engagée et votre colonne vertébrale neutre pendant l''exercice", "Le sol sert de butée de sécurité naturelle, évitant ainsi une hyperextension de l''articulation de l''épaule", "Concentrez-vous sur la contraction de vos muscles pectoraux plutôt que sur le simple mouvement du poids", "Adoptez un tempo contrôlé avec une phase de descente de 2 à 3 secondes pour un maximum d''engagement musculaire", "Commencez avec des poids plus légers que pour un développé couché traditionnel, car le sol limite votre amplitude de mouvement."]', '["Keep your core engaged and maintain a neutral spine throughout the movement", "The floor acts as a natural safety stop, preventing overstretching of the shoulder joint", "Focus on squeezing your chest muscles rather than just moving the weight", "Use a controlled tempo with a 2-3 second lowering phase for maximum muscle engagement", "Start with lighter weights than you would use for bench press since the floor limits your range of motion"]', '9696321a-6d49-4d1b-a42d-08fb34bb8323', 'dumbbell-floor-chest-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('3a39062a-9953-4843-809e-532019c70e29', 'Pont fessier avec haltère', NULL, NULL, 'Dumbbell glute bridge', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 2, '/videos/quadriceps/dumbbell-glute-bridge.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-glute-bridge.jpg', NULL, '["Contracte bien les fessiers en haut", "Ne casse pas le bas du dos", "Pousse à travers les talons", "Marque une pause en haut pour mieux sentir le travail", "C''est une base solide pour les thrusts de hanches"]', '["Ne pas soulever les hanches suffisamment haut", "Ne pas contrôler la descente", "Laisser le bas du dos se cambrer trop"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell glute bridge"]', true, '2026-04-03 12:24:56.479016+00', '2026-04-03 12:24:56.479016+00', 'Allonge-toi sur le dos, les genoux fléchis et les pieds à plat sur le sol, écartés à la largeur des hanches. Tiens un haltère fermement sur tes hanches avec les deux mains. Pousse avec tes talons pour élever tes hanches, en formant une ligne droite entre les genoux et les épaules, puis redescends avec contrôle.', '["Ne pas soulever les hanches suffisamment haut", "Ne pas contrôler la descente", "Laisser le bas du dos se cambrer trop"]', true, '["Lie on back, knees bent, feet flat", "Drive hips up by squeezing glutes", "Form straight line from shoulders to knees", "Lower with control"]', '["Allonge-toi sur le dos, genoux fléchis, pieds à plat", "Pousse les hanches vers le haut en contractant les fessiers", "Maintiens une ligne droite des épaules aux genoux", "Redescends avec contrôle"]', '["Contracte bien les fessiers en haut", "Ne casse pas le bas du dos", "Pousse à travers les talons", "Marque une pause en haut pour mieux sentir le travail", "C''est une base solide pour les thrusts de hanches"]', '["Squeeze glutes hard at top", "Don''t hyperextend lower back", "Drive through heels", "Hold at top briefly", "Foundation for hip thrusts"]', 'dadea1de-c228-4e36-99de-db68578de515', 'dumbbell-glute-bridge', NULL, NULL);
INSERT INTO public.exercises VALUES ('56bf40e1-60c7-43fd-954f-8b73f377749a', 'Squats pistol avec haltère', NULL, 'Squats Pistol avec Halteres', 'Dumbbell pistol squats', 'Quadriceps', '[]', 'Quadriceps', 'Advanced', 2, '/videos/quadriceps/dumbbell-pistol-squats.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-pistol-squats.jpg', NULL, '["C''est un exercice avancé qui nécessite une grande force des jambes, de l''équilibre et de la mobilité de la cheville", "Utilise une boîte ou un banc derrière toi au début pour limiter ton amplitude et te donner confiance", "Garde ton torse aussi droit que possible et évite de trop pencher en avant", "Concentre-toi sur le contrôle de la descente plutôt que de te précipiter dans le mouvement", "Pense à te tenir à une surface stable avec ta main libre si l''équilibre est difficile"]', '["Ne pas maintenir la jambe étendue correctement", "Pencher le torse trop en avant lors de la descente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell pistol squats"]', true, '2026-04-03 12:24:56.53881+00', '2026-04-03 12:24:56.53881+00', 'Position de départ : Tiens-toi sur une jambe, un haltère à hauteur de poitrine avec les deux mains, la jambe non sollicitée tendue devant toi. Execution : Abaisse ton corps en pliant la jambe de soutien jusqu''à ce que tes fessiers frôlent ton talon, puis pousse avec ton talon pour revenir à la position initiale, la jambe étendue restant en l''air pendant tout le mouvement.', '["Ne pas maintenir la jambe étendue correctement", "Pencher le torse trop en avant lors de la descente"]', true, '["Start with bodyweight only until you can perform 5-8 clean repetitions per leg", "Hold a light dumbbell (5-10 lbs) at chest level with both hands once you''ve mastered the bodyweight version", "Keep your extended leg straight and parallel to the floor throughout the entire movement", "Lower down slowly and controlled, aiming to get your glutes as close to your heel as possible", "Drive through your heel and engage your glutes to push back up to the starting position", "Complete all repetitions on one leg before switching to the other leg"]', '["Commence par des squats sans poids jusqu''à ce que tu puisses faire 5-8 répétitions propres par jambe", "Une fois que tu maîtrises la version sans poids, prends un haltère léger (2-5 kg) à hauteur de poitrine avec les deux mains", "Garde ta jambe étendue droite et parallèle au sol durant tout le mouvement", "Descends lentement et de manière contrôlée, vise à rapprocher tes fessiers de ton talon autant que possible", "Pousse avec ton talon et engage tes fessiers pour revenir à la position de départ", "Fais toutes les répétitions d''un côté avant de passer à l''autre jambe"]', '["C''est un exercice avancé qui nécessite une grande force des jambes, de l''équilibre et de la mobilité de la cheville", "Utilise une boîte ou un banc derrière toi au début pour limiter ton amplitude et te donner confiance", "Garde ton torse aussi droit que possible et évite de trop pencher en avant", "Concentre-toi sur le contrôle de la descente plutôt que de te précipiter dans le mouvement", "Pense à te tenir à une surface stable avec ta main libre si l''équilibre est difficile"]', '["This is an advanced exercise that requires significant leg strength, balance, and ankle mobility", "Use a box or bench behind you initially to limit your range of motion and build confidence", "Keep your torso as upright as possible and avoid leaning forward excessively", "Focus on controlling the descent rather than rushing through the movement", "Consider holding onto a stable surface with your free hand if balance is challenging"]', '35b16467-8817-4c28-b84c-a1f47b1734cd', 'dumbbell-pistol-squats', NULL, NULL);
INSERT INTO public.exercises VALUES ('0263fc86-d103-4513-8221-b278523e9113', 'Fente Latérale avec Haltère (G)', NULL, NULL, 'Dumbbell Side lunge (L)', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 2, '/videos/quadriceps/dumbbell-side-lunge-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-side-lunge-l.jpg', NULL, '["Conservez votre poids sur le talon de la jambe qui effectue la fente pour activer correctement les quadriceps et les fessiers.", "Gardez le dos droit durant tout le mouvement sans laisser le genou s''incliner vers l''intérieur.", "Descendez seulement jusqu''à ce que votre mobilité le permette tout en maintenant une forme correcte.", "Gardez la jambe non impliquée droite et bien ancrée au sol pour plus de stabilité.", "Contrôlez le mouvement à la fois dans la descente et la remontée pour maximiser l''engagement musculaire et éviter les blessures."]', '["Ne pas garder le dos droit", "Laisser le genou s''incliner vers l''intérieur"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell side lunge (l)"]', true, '2026-04-03 12:24:56.597841+00', '2026-04-03 12:24:56.597841+00', 'Position de départ : Restez debout, les pieds écartés à la largeur des hanches, en tenant un haltère à deux mains au niveau de la poitrine ou un haltère dans chaque main le long du corps. Exécution : Écartez votre pied gauche sur le côté dans une grande posture, pliez le genou gauche et poussez vos hanches en arrière pour descendre en fente latérale, puis poussez sur votre talon gauche pour revenir à la position de départ.', '["Ne pas garder le dos droit", "Laisser le genou s''incliner vers l''intérieur"]', true, '["Stand with feet hip-width apart, holding dumbbells securely with a firm grip", "Step your left foot out to the side approximately 2-3 feet, keeping your right leg straight", "Lower your body by bending your left knee and pushing your hips back, keeping your chest up and core engaged", "Descend until your left thigh is parallel to the floor or as low as your mobility allows", "Push through your left heel to return to the starting position", "Complete all repetitions on the left side before switching to the right"]', '["Tenez-vous debout, les pieds écartés à la largeur des hanches, en tenant les haltères fermement.", "Faites un pas sur le côté gauche d''environ 60 à 90 cm, en gardant la jambe droite.", "Abaissez votre corps en pliant le genou gauche et en poussant les hanches en arrière, le torse droit et le ventre engagé.", "Descendez jusqu''à ce que votre cuisse gauche soit parallèle au sol ou aussi bas que votre mobilité le permet.", "Poussez sur votre talon gauche pour revenir à la position de départ.", "Complétez toutes les répétitions du côté gauche avant de passer au droit."]', '["Conservez votre poids sur le talon de la jambe qui effectue la fente pour activer correctement les quadriceps et les fessiers.", "Gardez le dos droit durant tout le mouvement sans laisser le genou s''incliner vers l''intérieur.", "Descendez seulement jusqu''à ce que votre mobilité le permette tout en maintenant une forme correcte.", "Gardez la jambe non impliquée droite et bien ancrée au sol pour plus de stabilité.", "Contrôlez le mouvement à la fois dans la descente et la remontée pour maximiser l''engagement musculaire et éviter les blessures."]', '["Keep your weight on the heel of your lunging leg to properly activate the quadriceps and glutes", "Maintain a straight back throughout the movement and avoid letting your knee cave inward", "Only descend as far as your hip mobility allows while maintaining proper form", "Keep the non-lunging leg straight and planted firmly on the ground for stability", "Control the movement on both the descent and ascent to maximize muscle engagement and prevent injury"]', 'bfce2271-bf6b-4a45-9038-5c9fa1935990', 'dumbbell-side-lunge-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('e4bfd675-2b67-46bf-ae11-958951bea267', 'Pompes Explosives', NULL, 'تمارين الدفع الانفجاري', 'Explosive push ups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/explosive-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/explosive-push-ups.jpg', NULL, '["Atterris en douceur avec les coudes légèrement fléchis pour amortir l''impact", "Concentre-toi sur la puissance générée à la base plutôt que de précipiter les répétitions", "Maîtrise d''abord les pompes classiques avant de tenter les variations explosives", "Stoppe immédiatement si tu ressens une douleur au poignet, à l''épaule ou à la poitrine", "Progresse progressivement en commençant par de petits mouvements explosifs avant de viser le décollage complet"]', '["Ne pas garder le corps aligné pendant l''exercice", "Atterrir trop brusquement sans maîtrise"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "explosive push ups"]', true, '2026-04-03 12:24:56.681532+00', '2026-04-03 12:24:56.681532+00', 'Mets-toi en position de pompe classique : mains un peu plus larges que les épaules, corps bien droit de la tête aux talons. Abaisse-toi vers le sol, puis pousse de toutes tes forces pour décoller les mains du sol avant de te rattraper et revenir à la position de départ.', '["Ne pas garder le corps aligné pendant l''exercice", "Atterrir trop brusquement sans maîtrise"]', true, '["Start in a standard push-up position with proper form and engage your core", "Lower your body slowly and under control until your chest nearly touches the ground", "Explosively push up through your hands with maximum force to propel your upper body off the ground", "Keep your hands ready to catch yourself as you land softly back in the starting position", "Maintain straight body alignment throughout the entire movement", "Rest adequately between repetitions to maintain explosive power"]', '["Place-toi en position de pompe avec le bon alignement et engage ton ventre", "Descends lentement jusqu''à ce que ta poitrine frôle le sol", "Pousse explosivement avec force pour décoller ton corps du sol", "Prépare tes mains pour atterrir en douceur et revenir à la position initiale", "Garde le corps bien aligné pendant tout le mouvement", "Accorde-toi une bonne pause entre les répétitions pour conserver ta puissance explosive"]', '["Atterris en douceur avec les coudes légèrement fléchis pour amortir l''impact", "Concentre-toi sur la puissance générée à la base plutôt que de précipiter les répétitions", "Maîtrise d''abord les pompes classiques avant de tenter les variations explosives", "Stoppe immédiatement si tu ressens une douleur au poignet, à l''épaule ou à la poitrine", "Progresse progressivement en commençant par de petits mouvements explosifs avant de viser le décollage complet"]', '["Land softly with slightly bent elbows to absorb impact and protect your joints", "Focus on generating maximum power from the bottom position rather than rushing through repetitions", "Master regular push-ups with perfect form before attempting explosive variations", "Stop immediately if you experience any wrist, shoulder, or chest discomfort", "Progress gradually by starting with smaller explosive movements before attempting full airtime"]', '67b6f81b-3bca-4b91-8cd8-4c4dd6194d6e', 'explosive-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('e9f96d3d-48a9-45e0-bbad-2537e60a9593', 'Pose de l''angle latéral étendu (gauche)', NULL, NULL, 'Extended side angle pose (left)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/extended-side-angle-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/extended-side-angle-pose-left.jpg', NULL, '["Assure-toi que ton genou avant est au-dessus de la cheville.", "Presse fermement le bord extérieur de ton pied arrière.", "Ne t''affaisse pas sur ta cuisse avant."]', '["Genou avant qui dépasse la cheville.", "Pied arrière trop souple.", "Épaules affaissées au lieu de s''ouvrir."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "extended side angle pose (left)"]', true, '2026-04-03 12:24:56.701124+00', '2026-04-03 12:24:56.701124+00', 'Position de départ : Place-toi en position debout les jambes écartées, pied gauche tourné à 90 degrés et pied droit légèrement tourné vers l''intérieur. Plie le genou gauche en position de fente sur le côté. Exécution : Abaisse ton avant-bras gauche sur ta cuisse gauche tout en étirant ton bras droit au-dessus de ta tête, créant une ligne droite de tes doigts droit jusqu''à ton talon droit.', '["Genou avant qui dépasse la cheville.", "Pied arrière trop souple.", "Épaules affaissées au lieu de s''ouvrir."]', true, '["From Warrior II, bring your front forearm to rest on your front thigh.", "Extend your top arm overhead, creating a line from back foot to fingertips.", "Turn your chest toward the ceiling.", "Hold and breathe deeply."]', '["Depuis la posture du guerrier II, dépose ton avant-bras avant sur ta cuisse avant.", "Étends ton bras supérieur au-dessus de ta tête, formant une ligne de ton pied arrière jusqu''à tes doigts.", "Tourne ta poitrine vers le plafond.", "Maintiens la position et respire profondément."]', '["Assure-toi que ton genou avant est au-dessus de la cheville.", "Presse fermement le bord extérieur de ton pied arrière.", "Ne t''affaisse pas sur ta cuisse avant."]', '["Keep your front knee over the ankle.", "Press firmly through the outer edge of your back foot.", "Do not collapse onto the front thigh."]', '61ef551f-2db3-4ab9-978d-9e5712b873de', 'extended-side-angle-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('269e7db7-7e7f-44a4-b8d8-25b885c44197', 'Pose du bûcheron (droite)', NULL, NULL, 'Fire log pose (right)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/fire-log-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/fire-log-pose-right.jpg', NULL, '["Gardez les deux os assis bien ancrés au sol pendant toute la pose.", "Ne forcez pas l''étirement - laissez la gravité approfondir naturellement l''ouverture des hanches.", "Si vous ressentez de l''inconfort au niveau des genoux, placez un coussin ou un bloc sous la hanche surélevée.", "Maintenez une posture droite plutôt que de vous affaisser vers l''avant.", "Cette pose cible les fléchisseurs de hanche profonds et les rotateurs externes pour améliorer la mobilité."]', '["Se pencher en avant au lieu de maintenir une posture droite.", "Ne pas respecter les limites de votre corps, ce qui peut causer des tensions."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "fire log pose (right)"]', true, '2026-04-03 12:24:56.737025+00', '2026-04-03 12:24:56.737025+00', 'Position de départ : Assis sur le tapis, pliez les deux jambes. La jambe droite est parallèle au bord avant du tapis et la jambe gauche est parallèle au côté gauche, formant une position de bûches superposées. Exécution : Restez dans cette position assise tout en respirant profondément et en permettant à vos hanches de se détendre et de s''ouvrir.', '["Se pencher en avant au lieu de maintenir une posture droite.", "Ne pas respecter les limites de votre corps, ce qui peut causer des tensions."]', true, '["Sit on your mat and bend both knees, positioning your right shin parallel to the front edge of the mat", "Place your left leg so the shin is parallel to the left side of your mat, creating two parallel lines like stacked logs", "Rest your hands on the mat in front of you for support", "Keep your spine tall and shoulders relaxed", "Hold the position while taking slow, deep breaths", "Focus on allowing your hips to gradually release and open"]', '["Assis sur le tapis, pliez les deux genoux en plaçant votre tibia droit parallèle au bord avant.", "Positionnez votre jambe gauche de manière à ce que le tibia soit parallèle au côté gauche du tapis, formant deux lignes parallèles.", "Posez vos mains sur le tapis devant vous pour vous soutenir.", "Gardez la colonne vertébrale droite et les épaules détendues.", "Maintenez la pose en prenant des respirations lentes et profondes.", "Concentrez-vous sur le relâchement progressif de vos hanches."]', '["Gardez les deux os assis bien ancrés au sol pendant toute la pose.", "Ne forcez pas l''étirement - laissez la gravité approfondir naturellement l''ouverture des hanches.", "Si vous ressentez de l''inconfort au niveau des genoux, placez un coussin ou un bloc sous la hanche surélevée.", "Maintenez une posture droite plutôt que de vous affaisser vers l''avant.", "Cette pose cible les fléchisseurs de hanche profonds et les rotateurs externes pour améliorer la mobilité."]', '["Keep both sitting bones grounded on the mat throughout the pose", "Avoid forcing the stretch - let gravity naturally deepen the hip opening", "If you feel discomfort in the knees, place a cushion or block under the elevated hip", "Maintain an upright posture rather than collapsing forward", "This pose targets deep hip flexors and external rotators for improved mobility"]', 'e0a7528b-5d24-4ddf-9d4c-d61958dc504c', 'fire-log-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('e1cff099-7d74-402f-93cf-7970d5867092', 'Froggers', NULL, 'فروغرز', 'Froggers', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/froggers.mp4', NULL, NULL, NULL, '/videos/thumbnails/froggers.jpg', NULL, '["Garde ton ventre bien serré tout au long du mouvement pour protéger ton bas du dos", "Atterris doucement sur la plante de tes pieds pour réduire l''impact sur les articulations", "Respire steady et évite de retenir ta respiration pendant l''exercice", "Commence lentement pour maîtriser la forme avant d''accélérer", "Si tu ressens une gêne au niveau des poignets, fais l''exercice sur les poings ou utilise des poignées de pompes"]', '["Ne pas garder le corps en ligne pendant la planche", "Atterrir brusquement, ce qui peut nuire aux articulations"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "froggers"]', true, '2026-04-03 12:24:56.792848+00', '2026-04-03 12:24:56.792848+00', 'Position de départ : commence en position de planche, mains bien ancrées au sol, bras tendus, corps aligné de la tête aux talons. Exécution : saute avec les deux pieds vers l’avant en atterrissant en squat profond, puis redémarre immédiatement à la position de planche dans un mouvement fluide.', '["Ne pas garder le corps en ligne pendant la planche", "Atterrir brusquement, ce qui peut nuire aux articulations"]', true, '["Start in a strong plank position with hands shoulder-width apart and core engaged", "Keep your hands planted firmly on the ground throughout the entire movement", "Jump both feet forward simultaneously, landing in a low squat position with feet outside your hands", "Pause briefly in the squat position to maintain control", "Jump both feet back to the starting plank position, landing softly on the balls of your feet", "Maintain a neutral spine and avoid letting your hips sag during the plank phases"]', '["Commence dans une planche solide avec les mains à la largeur des épaules et le ventre engagé", "Garde les mains bien ancrées au sol pendant tout le mouvement", "Saute avec les deux pieds vers l’avant en te plaçant en position de squat bas, les pieds à l’extérieur des mains", "Fais une courte pause en position de squat pour garder le contrôle", "Reviens en sautant les deux pieds à la position de planche, atterrissant doucement sur la plante des pieds", "Garde la colonne vertébrale neutre et évite de laisser tes hanches s''affaisser pendant les phases de planche"]', '["Garde ton ventre bien serré tout au long du mouvement pour protéger ton bas du dos", "Atterris doucement sur la plante de tes pieds pour réduire l''impact sur les articulations", "Respire steady et évite de retenir ta respiration pendant l''exercice", "Commence lentement pour maîtriser la forme avant d''accélérer", "Si tu ressens une gêne au niveau des poignets, fais l''exercice sur les poings ou utilise des poignées de pompes"]', '["Keep your core tight throughout the movement to protect your lower back", "Land softly on the balls of your feet to reduce impact on joints", "Maintain steady breathing and avoid holding your breath during the exercise", "Start with slower movements to master the form before increasing speed", "If you experience wrist discomfort, perform the exercise on your fists or use push-up handles"]', 'df37b949-000b-4b09-90a3-482d868ee55a', 'froggers', NULL, NULL);
INSERT INTO public.exercises VALUES ('dcc0cf06-6864-4dd7-b600-64cd9a94a92e', 'Posture de la porte (côté droit)', NULL, 'وضعية الباب (الجانب الأيمن)', 'Gate pose (right)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/gate-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/gate-pose-right.jpg', NULL, '["Garde les hanches bien positionnées au-dessus du genou au sol.", "Ouvre ta poitrine vers le plafond.", "Évite de te pencher en avant."]', '["Ne pas maintenir l''alignement des hanches.", "Écraser la poitrine en avant au lieu de l''ouvrir."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "gate pose (right)"]', true, '2026-04-03 12:24:56.813837+00', '2026-04-03 12:24:56.813837+00', 'Mets-toi à genoux avec les jambes écartées à la largeur des hanches. Étends ta jambe droite sur le côté, le pied plat au sol. Penche ton torse vers la droite tout en glissant ta main droite le long de ta jambe étendue, l''autre bras au-dessus de la tête pour étirer sur le côté.', '["Ne pas maintenir l''alignement des hanches.", "Écraser la poitrine en avant au lieu de l''ouvrir."]', true, '["Kneel on the mat and extend one leg out to the side.", "Place the extended foot flat on the floor, toes pointing sideways.", "Inhale and raise the arm on the kneeling side overhead.", "Exhale and lean toward the extended leg, sliding the other hand down the leg."]', '["À genoux sur le tapis, étends une jambe sur le côté.", "Pose le pied étendu à plat sur le sol, les orteils pointant sur le côté.", "Inspire et lève le bras du côté où tu es à genoux au-dessus de ta tête.", "Expire et penche-toi vers la jambe étendue, glissant l''autre main le long de cette jambe."]', '["Garde les hanches bien positionnées au-dessus du genou au sol.", "Ouvre ta poitrine vers le plafond.", "Évite de te pencher en avant."]', '["Keep your hips stacked over the kneeling knee.", "Open your chest toward the ceiling.", "Do not collapse forward."]', 'ad7e4bc7-a8d8-4aa7-978f-e130aeb49e8b', 'gate-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('e8e4056c-14bf-45ae-acfd-24aeb625e3c4', 'Squat Goblet', NULL, 'Squat Goblet', 'Goblet squat', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 2, '/videos/quadriceps/goblet-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/goblet-squat.jpg', NULL, '["Idéal pour apprendre le mouvement du squat", "La contrepoids aide à aller plus bas", "Garde le buste droit tout au long de l''exercice", "Les coudes peuvent pousser les genoux vers l''extérieur en bas", "Bon pour la mobilité"]', '["Pencher le buste en avant", "Ne pas descendre suffisamment bas", "Les genoux s''effondrent vers l''intérieur", "Ne pas garder les talons au sol", "Oublier de respirer correctement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "goblet squat"]', true, '2026-04-03 12:24:56.835131+00', '2026-04-03 12:24:56.835131+00', 'Position initiale : Debout, les pieds légèrement plus larges que la largeur des épaules, les mains à hauteur de poitrine comme si tu tenais une coupe. Exécution : Abaisse ton corps en fléchissant les hanches et les genoux jusqu''à ce que tes cuisses soient parallèles au sol, puis pousse sur tes talons pour revenir à la position de départ.', '["Pencher le buste en avant", "Ne pas descendre suffisamment bas", "Les genoux s''effondrent vers l''intérieur", "Ne pas garder les talons au sol", "Oublier de respirer correctement"]', true, '["Hold one dumbbell vertically at chest", "Feet shoulder-width or wider", "Squat down between legs", "Keep chest up, elbows inside knees", "Drive up through heels"]', '["Tiens un haltère verticalement au niveau de ta poitrine", "Pieds à la largeur des épaules ou plus", "Descends entre les jambes", "Garde le buste droit, coudes à l''intérieur des genoux", "Remonte en poussant sur les talons"]', '["Idéal pour apprendre le mouvement du squat", "La contrepoids aide à aller plus bas", "Garde le buste droit tout au long de l''exercice", "Les coudes peuvent pousser les genoux vers l''extérieur en bas", "Bon pour la mobilité"]', '["Great for learning squat pattern", "Counterbalance helps depth", "Keep chest up throughout", "Elbows can push knees out at bottom", "Good for mobility"]', 'b1c0e80d-329c-4910-8b23-37daa8ea17da', 'goblet-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('db26b4af-c395-432e-a0b8-20bd23e8ba1a', 'Good Mornings avec barre', NULL, 'صباح الخير مع البار', 'Good Mornings with barbell', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 1, '/videos/bodyweight/good-mornings-with-barbell.mp4', NULL, NULL, NULL, '/videos/thumbnails/good-mornings-with-barbell.jpg', NULL, '["Garde le dos plat, ne le courbe pas", "Le mouvement est une flexion des hanches, pas un squat", "Ressens l''étirement dans les ischio-jambiers", "Ne charges pas trop lourd - la technique est essentielle", "Excellent pour la chaîne postérieure"]', '["Courber le dos pendant l''exercice", "Ne pas fléchir suffisamment les hanches", "Aller trop lourd et sacrifier la technique", "Ne pas ressentir l''étirement des ischio-jambiers", "Oublier de serrer le core au début du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "barbell", "good mornings with barbell"]', true, '2026-04-03 12:24:56.86112+00', '2026-04-03 12:24:56.86112+00', 'Position de départ : Place-toi debout, les pieds écartés à la largeur des épaules, la barre reposant sur tes trapèzes supérieurs (position haute), engage ton core et garde la poitrine haute. Exécution : Fait une flexion au niveau des hanches en poussant tes fesses en arrière, tout en gardant le dos neutre. Abaisse ton buste jusqu''à ressentir un étirement dans tes ischio-jambiers, puis ramène tes hanches en avant pour revenir à la position initiale.', '["Courber le dos pendant l''exercice", "Ne pas fléchir suffisamment les hanches", "Aller trop lourd et sacrifier la technique", "Ne pas ressentir l''étirement des ischio-jambiers", "Oublier de serrer le core au début du mouvement"]', true, '["Bar on upper back like squat", "Feet hip to shoulder-width", "Soft knee bend", "Hinge at hips, pushing butt back", "Lower torso until parallel or comfortable stretch", "Drive hips forward to stand"]', '["Barre sur la partie supérieure du dos comme pour un squat", "Pieds écartés de la largeur des hanches aux épaules", "Légère flexion des genoux", "Fléchis au niveau des hanches, en poussant les fesses en arrière", "Abaisse le buste jusqu''à être parallèle ou ressentir un étirement confortable", "Pousse les hanches vers l''avant pour te redresser"]', '["Garde le dos plat, ne le courbe pas", "Le mouvement est une flexion des hanches, pas un squat", "Ressens l''étirement dans les ischio-jambiers", "Ne charges pas trop lourd - la technique est essentielle", "Excellent pour la chaîne postérieure"]', '["Keep back flat, not rounded", "Movement is hip hinge, not squat", "Feel stretch in hamstrings", "Don''t go too heavy - technique is key", "Great for posterior chain"]', '88116de4-0c5d-4985-8905-156fd03d7eb9', 'good-mornings-with-barbell', NULL, NULL);
INSERT INTO public.exercises VALUES ('47bd3f0a-c8b4-4872-92df-8927d4b3236e', 'Halo avec haltère', NULL, 'Halo avec haltère', 'Halo with dumbbell (R)', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/halo-with-dumbbell-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/halo-with-dumbbell-r.jpg', NULL, '["Engagez votre sangle abdominale et gardez une bonne posture durant tout l''exercice", "Commencez avec un poids léger pour maîtriser le mouvement avant de progresser", "Exécutez le mouvement lentement et avec contrôle - il ne s''agit pas d''un exercice basé sur l''élan", "Gardez l''haltère proche de votre tête pour un bon alignement des épaules", "Arrêtez-vous immédiatement si vous ressentez une douleur au niveau de l''épaule ou un inconfort."]', '["Faire le mouvement trop rapidement sans contrôle", "Utiliser un poids trop lourd dès le début", "Ne pas garder l''haltère assez proche de la tête", "Oublier d''engager les abdominaux et de maintenir une bonne posture"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "halo with dumbbell (r)"]', true, '2026-04-03 12:24:57.026621+00', '2026-04-03 12:24:57.026621+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des épaules, un haltère en vertical dans les mains au niveau de la poitrine. Exécution : Faites tourner l''haltère autour de votre tête dans le sens des aiguilles d''une montre, en gardant votre sangle abdominale engagée et le contrôle du mouvement.', '["Faire le mouvement trop rapidement sans contrôle", "Utiliser un poids trop lourd dès le début", "Ne pas garder l''haltère assez proche de la tête", "Oublier d''engager les abdominaux et de maintenir une bonne posture"]', true, '["Stand with feet shoulder-width apart, holding one dumbbell by one end with both hands at chest level", "Lift the dumbbell overhead and slowly circle it around your head in a clockwise direction, keeping the weight close to your head", "Pass the dumbbell behind your head, then around to the left side, maintaining control throughout the movement", "Continue the circular motion, bringing the dumbbell around to the front and back to starting position", "Complete the desired repetitions in one direction, then reverse to counterclockwise for equal repetitions"]', '["Positionnez-vous debout, les pieds écartés à la largeur des épaules, avec un haltère tenu verticalement par une extrémité au niveau de la poitrine", "Soulevez l''haltère au-dessus de votre tête et faites-le doucement circuler autour de votre tête dans le sens des aiguilles d''une montre, en le gardant proche de votre tête", "Passez l''haltère derrière votre tête, puis autour du côté gauche, tout en maintenant le contrôle du mouvement", "Continuez le mouvement circulaire, ramenant l''haltère à l''avant et de retour à la position de départ", "Réalisez le nombre de répétitions désiré dans un sens, puis inversez le mouvement pour effectuer le même nombre de répétitions dans le sens inverse."]', '["Engagez votre sangle abdominale et gardez une bonne posture durant tout l''exercice", "Commencez avec un poids léger pour maîtriser le mouvement avant de progresser", "Exécutez le mouvement lentement et avec contrôle - il ne s''agit pas d''un exercice basé sur l''élan", "Gardez l''haltère proche de votre tête pour un bon alignement des épaules", "Arrêtez-vous immédiatement si vous ressentez une douleur au niveau de l''épaule ou un inconfort."]', '["Keep your core engaged and maintain good posture throughout the entire movement", "Start with a lighter weight to master the movement pattern before progressing", "Move slowly and controlled - this is not a momentum-based exercise", "Keep the dumbbell close to your head to maintain proper shoulder positioning", "Stop immediately if you feel any shoulder impingement or discomfort"]', '05c60c96-4b0d-4e83-8797-9e3eb9a9cab0', 'halo-with-dumbbell-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('bad345e4-f23a-4dd3-9d21-93629b945b4b', 'Touches de talons', NULL, NULL, 'Heel touches', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/heel-touches.mp4', NULL, NULL, NULL, '/videos/thumbnails/heel-touches.jpg', NULL, '["Garde le bas du dos collé au sol pendant tout l''exercice", "Concentre-toi sur les muscles obliques pour réaliser le mouvement, ne te contente pas de bouger les bras", "Reste en tension dans ton ventre et évite de laisser tes épaules reposées au sol entre les répétitions", "Garde ton cou dans une position neutre, sans tirer sur ta tête ni forcer ton cou", "Effectue le mouvement lentement et de manière contrôlée pour maximiser l''engagement musculaire et éviter que l''élan prenne le dessus."]', '["Ne pas engager le ventre, ce qui diminue l''efficacité de l''exercice", "Avoir une position du cou incorrecte, entraînant des douleurs ou des tensions."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "heel touches"]', true, '2026-04-03 12:24:57.076456+00', '2026-04-03 12:24:57.076456+00', 'Allonge-toi sur le dos, genoux fléchis, pieds au sol à la largeur des hanches. Les bras tendus le long du corps, paumes vers le sol. Prêt à te dépasser ? C''est parti !', '["Ne pas engager le ventre, ce qui diminue l''efficacité de l''exercice", "Avoir une position du cou incorrecte, entraînant des douleurs ou des tensions."]', true, '["Lie flat on your back with knees bent at 90 degrees and feet planted firmly on the floor", "Place your arms straight down by your sides with palms facing the floor", "Engage your core and lift your shoulder blades slightly off the ground", "Crunch to your right side and reach your right hand toward your right heel", "Return to center then crunch to your left side reaching your left hand toward your left heel", "Continue alternating sides in a controlled manner while keeping your core engaged"]', '["Allonge-toi à plat sur le dos, genoux à 90 degrés et pieds bien ancrés au sol", "Place tes bras le long du corps, paumes vers le sol", "Engage ton ventre et souviens-toi de soulever légèrement les omoplates du sol", "Incline-toi sur le côté droit et touche ton talon droit avec ta main", "Reviens au centre et incline-toi sur le côté gauche pour atteindre ton talon gauche", "Alterne ces mouvements de manière contrôlée tout en maintenant ton abdominal actif."]', '["Garde le bas du dos collé au sol pendant tout l''exercice", "Concentre-toi sur les muscles obliques pour réaliser le mouvement, ne te contente pas de bouger les bras", "Reste en tension dans ton ventre et évite de laisser tes épaules reposées au sol entre les répétitions", "Garde ton cou dans une position neutre, sans tirer sur ta tête ni forcer ton cou", "Effectue le mouvement lentement et de manière contrôlée pour maximiser l''engagement musculaire et éviter que l''élan prenne le dessus."]', '["Keep your lower back pressed against the floor throughout the entire movement", "Focus on using your oblique muscles to create the side-to-side crunching motion rather than just moving your arms", "Maintain tension in your core and avoid letting your shoulders completely rest on the ground between reps", "Keep your neck in a neutral position and avoid pulling on your head or straining your neck", "Perform the movement slowly and controlled to maximize muscle engagement and prevent momentum from taking over"]', '44067253-a8d5-4b0f-9008-02c2e56624b1', 'heel-touches', NULL, NULL);
INSERT INTO public.exercises VALUES ('4bb701fc-3808-40a9-97b4-e7bfb3837351', 'Hang Clean', NULL, 'تكنيك الهانغ كلين', 'Hang clean', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/hang-clean.mp4', NULL, NULL, NULL, '/videos/thumbnails/hang-clean.jpg', NULL, '["Rapproche la barre de ton corps durant tout le mouvement pour maintenir un bon levier", "Concentre-toi sur l''extension explosive des hanches plutôt que de tirer avec les bras pour un maximum de puissance", "Entraîne-toi à la position d''attrapage seule pour améliorer la flexibilité de tes coudes et poignets", "Commence avec des poids légers pour maîtriser la technique avant de passer à des charges plus lourdes", "Garde toujours une colonne vertébrale neutre pour éviter les blessures au bas du dos."]', '["Ne pas garder la barre près du corps", "Tirer avec les bras au lieu de se concentrer sur le mouvement des hanches"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "hang clean"]', true, '2026-04-03 12:24:57.038998+00', '2026-04-03 12:24:57.038998+00', 'Prépare-toi à travailler l''ensemble du corps avec cet exercice explosif qui demande puissance et précision. Positionne-toi bien pour maximiser tes performances et atteindre tes objectifs !', '["Ne pas garder la barre près du corps", "Tirer avec les bras au lieu de se concentrer sur le mouvement des hanches"]', true, '["Set up with the barbell over mid-foot, maintaining a straight back and engaged core", "Initiate the lift by driving through your heels and extending your hips and knees simultaneously", "As the bar passes your knees, explosively extend your hips and shrug your shoulders upward", "Pull yourself under the bar by dropping into a partial squat while rotating your elbows forward", "Catch the bar at shoulder level with elbows pointing forward and stand up to complete the movement", "Lower the bar back to the starting position with control"]', '["Positionne la barre au-dessus de ton pied moyen avec les pieds écartés à la largeur des hanches et dos droit", "Commence le mouvement en poussant avec tes talons tout en étendant hanches et genoux en même temps", "Quand la barre dépasse tes genoux, explose vers le haut en étendant tes hanches et en haussant les épaules", "Lâche-toi sous la barre et plie légèrement les genoux en tournant tes coudes vers l''avant", "Attrape la barre à la hauteur des épaules avec les coudes dirigés vers l''avant, puis redresse-toi pour finir le mouvement", "Redescends la barre de manière contrôlée à la position de départ."]', '["Rapproche la barre de ton corps durant tout le mouvement pour maintenir un bon levier", "Concentre-toi sur l''extension explosive des hanches plutôt que de tirer avec les bras pour un maximum de puissance", "Entraîne-toi à la position d''attrapage seule pour améliorer la flexibilité de tes coudes et poignets", "Commence avec des poids légers pour maîtriser la technique avant de passer à des charges plus lourdes", "Garde toujours une colonne vertébrale neutre pour éviter les blessures au bas du dos."]', '["Keep the bar close to your body throughout the entire movement to maintain proper leverage", "Focus on explosive hip extension rather than pulling with your arms to generate maximum power", "Practice the catching position separately to develop proper elbow and wrist flexibility", "Start with lighter weights to master the technique before progressing to heavier loads", "Maintain a neutral spine throughout the movement to prevent lower back injury"]', '71ea41d9-e931-46dc-8a6c-731a7ee3e742', 'hang-clean', NULL, NULL);
INSERT INTO public.exercises VALUES ('784e05b9-33e4-49e5-92c7-921024eae88c', 'Talons aux Fesses', NULL, NULL, 'Heels to Butt', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/heels-to-butt.mp4', NULL, NULL, NULL, '/videos/thumbnails/heels-to-butt.jpg', NULL, '["Engage ton cœur et évite de pencher en avant ou en arrière durant le mouvement", "Concentre-toi sur l’élévation de tes talons vers tes fesses plutôt que sur un simple lever de genoux", "Maintiens un tempo rapide mais contrôlé pour maximiser les bénéfices cardiovasculaires", "Atterris doucement pour réduire l’impact sur les articulations et prévenir les blessures", "Cet exercice est parfait en tant qu''échauffement dynamique ou mouvement d''intervalle cardio"]', '["Ne pas garder le dos droit", "Pencher trop facilement en avant ou en arrière durant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "heels to butt"]', true, '2026-04-03 12:24:57.084822+00', '2026-04-03 12:24:57.084822+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, bras le long du corps ou mains sur les hanches pour l''équilibre. Exécution : Alterne en levant tes talons vers tes fesses en pliant les genoux tout en gardant une posture droite et en pompant tes bras.', '["Ne pas garder le dos droit", "Pencher trop facilement en avant ou en arrière durant l''exercice"]', true, '["Stand with feet hip-width apart and maintain good posture throughout the movement", "Begin by lifting one heel toward your glutes by bending the knee, keeping thighs parallel", "Quickly alternate legs in a running motion while staying in place", "Pump your arms naturally as if running to maintain balance and rhythm", "Land softly on the balls of your feet with each step", "Continue for the desired duration while maintaining proper form"]', '["Tiens-toi avec les pieds écartés à la largeur des hanches en maintenant une bonne posture tout au long du mouvement", "Commence par lever un talon vers tes fesses en pliant le genou, en gardant les cuisses parallèles", "Alterne rapidement les jambes dans un mouvement de course tout en restant sur place", "Pomp tes bras naturellement comme si tu courais pour maintenir l''équilibre et le rythme", "Atterris doucement sur la pointe des pieds à chaque étape", "Continue pendant la durée souhaitée en maintenant la bonne forme"]', '["Engage ton cœur et évite de pencher en avant ou en arrière durant le mouvement", "Concentre-toi sur l’élévation de tes talons vers tes fesses plutôt que sur un simple lever de genoux", "Maintiens un tempo rapide mais contrôlé pour maximiser les bénéfices cardiovasculaires", "Atterris doucement pour réduire l’impact sur les articulations et prévenir les blessures", "Cet exercice est parfait en tant qu''échauffement dynamique ou mouvement d''intervalle cardio"]', '["Keep your core engaged and avoid leaning forward or backward during the movement", "Focus on bringing heels close to glutes rather than just lifting knees up", "Maintain a quick but controlled tempo to maximize cardiovascular benefits", "Land softly to reduce impact on joints and prevent injury", "This exercise serves as an excellent dynamic warm-up or cardio interval movement"]', 'a16a574a-28bd-4010-bcda-b9f066b381e4', 'heels-to-butt', NULL, NULL);
INSERT INTO public.exercises VALUES ('cb396372-d404-4cd3-9d1c-fe3d7515fcc2', 'Touché de pied en planche haute', NULL, 'لمسة القدم في وضعية البلانك العالية', 'High plank toe touches', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/high-plank-toe-touches.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-plank-toe-touches.jpg', NULL, '["Resserre les fessiers", "Garde le cou neutre", "Respire normalement", "Évite de soulever trop les hanches", "Augmente le temps progressivement"]', '["Ne pas aligner les épaules avec les poignets", "Laisser les hanches s''affaisser"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "high plank toe touches"]', true, '2026-04-03 12:24:57.133487+00', '2026-04-03 12:24:57.133487+00', 'Position de départ : mets-toi en position de planche haute, les mains sous les épaules, les bras tendus et le corps bien aligné de la tête aux talons. Exécution : soulève un pied et essaie de toucher ta main du même côté, puis retourne en planche et répète de l''autre côté.', '["Ne pas aligner les épaules avec les poignets", "Laisser les hanches s''affaisser"]', true, '["Forearms on floor, elbows under shoulders", "Body straight from head to heels", "Hold position", "Keep core tight, don''t let hips sag"]', '["Avant-bras au sol, coudes sous les épaules", "Corps droit des pieds à la tête", "Maintiens la position", "Garde ton ventre bien tendu, ne laisse pas les hanches s''affaisser"]', '["Resserre les fessiers", "Garde le cou neutre", "Respire normalement", "Évite de soulever trop les hanches", "Augmente le temps progressivement"]', '["Squeeze glutes", "Keep neck neutral", "Breathe normally", "Don''t raise hips too high", "Build time gradually"]', '0f14071c-279d-4926-b41a-cb4dc900bb1d', 'high-plank-toe-touches', NULL, NULL);
INSERT INTO public.exercises VALUES ('bb24770c-ecf8-4ee9-8de1-1fd3fbdc75f0', 'Étirement de la hanche (gauche)', NULL, 'Stretch de l''hip (gauche)', 'Hip stretch (left)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/hip-stretch-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/hip-stretch-left.jpg', NULL, '["Assure-toi que ton genou avant est aligné au-dessus de ta cheville pour éviter les blessures.", "Garde le torse droit pendant l''étirement, ne te penche pas en avant.", "Ressens l''étirement principalement à l''avant de ta hanche et de ta cuisse gauche.", "Progressivement, entre dans l''étirement sans forcer la position.", "Arrête immédiatement si tu ressens une douleur aiguë ou un inconfort."]', '["Pencher le torse en avant au lieu de rester droit.", "Laisser le genou dépasser les orteils, ce qui peut entraîner des blessures."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "hip stretch (left)"]', true, '2026-04-03 12:24:57.172449+00', '2026-04-03 12:24:57.172449+00', 'Position de départ : Place-toi debout, pieds écartés à la largeur des hanches. Avance ton pied droit dans une position de fente, tout en gardant ta jambe gauche bien tendue derrière toi. Exécution : Abaisse tes hanches vers le sol tout en gardant le torse droit, et ressens l''étirement dans le fléchisseur de la hanche gauche et les muscles environnants.', '["Pencher le torse en avant au lieu de rester droit.", "Laisser le genou dépasser les orteils, ce qui peut entraîner des blessures."]', true, '["Step your right foot forward approximately 2-3 feet while keeping your left foot planted behind you", "Lower your body into a lunge position by bending your right knee to 90 degrees", "Keep your left leg straight and press your left heel toward the ground", "Place your hands on your right thigh or on the ground for support and balance", "Gently push your hips forward and down to deepen the stretch in your left hip", "Hold the position for 20-30 seconds while breathing deeply"]', '["Fais un grand pas en avant avec ton pied droit d''environ 60-90 cm tout en gardant le pied gauche ancré derrière.", "Abaisse ton corps en fléchissant ton genou droit à 90 degrés.", "Garde ta jambe gauche droite et enfonce ton talon gauche vers le sol.", "Place tes mains sur ta cuisse droite ou au sol pour le soutien et l''équilibre.", "Pousse doucement tes hanches vers l''avant et vers le bas pour intensifier l''étirement dans ta hanche gauche.", "Maintiens la position pendant 20-30 secondes tout en respirant profondément."]', '["Assure-toi que ton genou avant est aligné au-dessus de ta cheville pour éviter les blessures.", "Garde le torse droit pendant l''étirement, ne te penche pas en avant.", "Ressens l''étirement principalement à l''avant de ta hanche et de ta cuisse gauche.", "Progressivement, entre dans l''étirement sans forcer la position.", "Arrête immédiatement si tu ressens une douleur aiguë ou un inconfort."]', '["Keep your front knee aligned over your ankle to prevent injury", "Maintain an upright torso throughout the stretch rather than leaning forward", "Feel the stretch primarily in the front of your left hip and thigh", "Gradually ease into the stretch rather than forcing the position", "Stop immediately if you experience any sharp pain or discomfort"]', '610855b2-2eb1-440a-9645-9598f0a46766', 'hip-stretch-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('c95ce440-0170-4791-9c0e-c642a08739d2', 'Élévation Frontale avec Barbell Incliné', NULL, 'رفع أمامي بالبار على منحدر', 'Incline Barbell Front Raise', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 1, '/videos/shoulders/incline-barbell-front-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-barbell-front-raise.jpg', NULL, '["Utilise un poids plus léger que pour d''autres exercices d''épaules car ce mouvement sollicite beaucoup l''articulation de l''épaule dans une position vulnérable.", "Maintiens une légère flexion des coudes tout au long du mouvement pour réduire la pression sur les articulations et améliorer le contrôle.", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur l''élan pour maximiser l''engagement musculaire et minimiser le risque de blessure.", "Garde les épaules tirées vers l''arrière et vers le bas contre le banc pour maintenir une bonne position de la scapula et éviter les douleurs."]', '["Lever le barbell trop haut, ce qui peut causer des blessures à l''épaule.", "Utiliser trop de poids, ce qui compromet la forme et augmente le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "barbell", "incline barbell front raise"]', true, '2026-04-03 12:24:57.235578+00', '2026-04-03 12:24:57.235578+00', 'Position de départ : Allonge-toi sur un banc incliné avec un barbell dans les mains, bras tendus vers le bas. Exécution : Soulève le bar vers l''avant jusqu''à la hauteur des épaules, puis redescends lentement.', '["Lever le barbell trop haut, ce qui peut causer des blessures à l''épaule.", "Utiliser trop de poids, ce qui compromet la forme et augmente le risque de blessure."]', true, '["Set an incline bench to a 30-45 degree angle and lie back with your feet firmly planted on the floor", "Grasp the barbell with both hands using an overhand grip, hands positioned slightly wider than shoulder-width apart", "Begin with arms extended and the barbell positioned above your lower chest with a slight bend in your elbows", "Raise the barbell in a smooth arc upward until it reaches shoulder height, maintaining the slight elbow bend throughout", "Pause briefly at the top position, then slowly lower the barbell back to the starting position with control", "Keep your core engaged and maintain contact between your back and the bench throughout the entire movement"]', '["Régle un banc incliné à un angle de 30 à 45 degrés et allonge-toi en plaçant tes pieds bien à plat au sol.", "Saisis le barbell avec les deux mains en prise pronation, les mains légèrement plus larges que la largeur des épaules.", "Commence avec les bras tendus et le barbell au-dessus de ta poitrine basse, les coudes légèrement fléchis.", "Soulève le barbell en arc jusqu''à atteindre la hauteur des épaules, en gardant la légère flexion des coudes tout au long du mouvement.", "Fais une courte pause en haut, puis redescends lentement le barbell à la position de départ avec contrôle.", "Garde ton ventre engagé et assure-toi que ton dos reste en contact avec le banc pendant tout le mouvement."]', '["Utilise un poids plus léger que pour d''autres exercices d''épaules car ce mouvement sollicite beaucoup l''articulation de l''épaule dans une position vulnérable.", "Maintiens une légère flexion des coudes tout au long du mouvement pour réduire la pression sur les articulations et améliorer le contrôle.", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur l''élan pour maximiser l''engagement musculaire et minimiser le risque de blessure.", "Garde les épaules tirées vers l''arrière et vers le bas contre le banc pour maintenir une bonne position de la scapula et éviter les douleurs."]', '["Use a lighter weight than you would for other shoulder exercises as this movement places significant stress on the shoulder joint in a vulnerable position", "Maintain a slight bend in your elbows throughout the movement to reduce stress on the elbow joints and maintain better control", "Focus on slow, controlled movements rather than momentum to maximize muscle engagement and minimize injury risk", "Keep your shoulders pulled back and down against the bench to maintain proper shoulder blade positioning and prevent impingement"]', 'ac256206-2279-44dc-ab5e-94d6e7d9e8a6', 'incline-barbell-front-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('b26a2563-1d26-4ac5-b855-3c939231d948', 'Curl Incliné avec Haltères', NULL, NULL, 'Incline Dumbbell Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/incline-dumbbell-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-dumbbell-curl.jpg', NULL, '["Maintiens tes bras supérieurs immobiles et appuyés contre le banc pour isoler efficacement les biceps", "Évite de balancer ou d''utiliser l''élan - concentre-toi sur des mouvements lents et contrôlés", "Ne laisse pas tes épaules rouler vers l''avant ou se décoller du banc pendant l''exercice", "La position inclinée permet un meilleur étirement des biceps par rapport aux curls standards", "Commence avec des poids plus légers car cette position rend l''exercice plus difficile que les curls classiques"]', '["Utiliser trop de poids et sacrifier la technique", "Balancer les haltères au lieu de les lever de manière contrôlée"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "incline dumbbell curl"]', true, '2026-04-03 12:24:57.273103+00', '2026-04-03 12:24:57.273103+00', 'Position de départ : assieds-toi sur un banc incliné avec un haltère dans chaque main, bras pendus vers le bas. Exécution : fléchis les coudes pour soulever les haltères vers tes épaules, puis redescends de manière contrôlée.', '["Utiliser trop de poids et sacrifier la technique", "Balancer les haltères au lieu de les lever de manière contrôlée"]', true, '["Set the incline bench to a 45-60 degree angle and sit with your back firmly pressed against the pad", "Hold a dumbbell in each hand with arms hanging straight down and palms facing forward", "Keep your shoulders back and core engaged throughout the movement", "Curl the weights up by contracting your biceps while keeping your upper arms pressed against the bench", "Squeeze your biceps at the top of the movement for a brief pause", "Slowly lower the dumbbells back to the starting position with control"]', '["Régle le banc inclinable à un angle de 45 à 60 degrés et assieds-toi en maintenant ton dos fermement contre le dossier", "Prends un haltère dans chaque main, bras pendus droit et paumes tournées vers l''avant", "Garde les épaules en arrière et le ventre engagé tout au long du mouvement", "Fléchis les coudes pour faire monter les poids en contractant tes biceps, en gardant les bras supérieurs pressés contre le banc", "Ressens la contraction en haut du mouvement avec une courte pause", "Descends lentement les haltères jusqu''à la position de départ en contrôlant le mouvement"]', '["Maintiens tes bras supérieurs immobiles et appuyés contre le banc pour isoler efficacement les biceps", "Évite de balancer ou d''utiliser l''élan - concentre-toi sur des mouvements lents et contrôlés", "Ne laisse pas tes épaules rouler vers l''avant ou se décoller du banc pendant l''exercice", "La position inclinée permet un meilleur étirement des biceps par rapport aux curls standards", "Commence avec des poids plus légers car cette position rend l''exercice plus difficile que les curls classiques"]', '["Keep your upper arms stationary and pressed against the bench to isolate the biceps effectively", "Avoid swinging or using momentum - focus on slow, controlled movements", "Don''t let your shoulders roll forward or come off the bench during the exercise", "The incline position provides a greater stretch on the biceps compared to standard curls", "Start with lighter weights as this position makes the exercise more challenging than regular curls"]', 'd1faa0c0-7eac-4a49-8b40-9b3fa923d091', 'incline-dumbbell-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('97bfb372-c7a4-4bfa-a2ba-1d14aaeb1ee2', 'Pompes diamant inclinées', NULL, NULL, 'Inclined diamond push up', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/inclined-diamond-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/inclined-diamond-push-up.jpg', NULL, '["Garde tes abdos serrés et ton corps bien droit pour éviter que tes hanches ne s''affaissent", "La position des mains en diamant cible davantage les triceps tout en sollicitant le pectoral", "Commence avec un angle d''inclinaison plus élevé et descends progressivement au fur et à mesure que tu gagnes en force", "Évite d''écarter les coudes trop largement - garde-les à environ 45 degrés de ton torse", "Contrôle la descente pour maximiser l''engagement musculaire et éviter les blessures"]', '["Ne pas descendre suffisamment", "Hanches qui s''affaissent pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "inclined diamond push up"]', true, '2026-04-03 12:24:57.31995+00', '2026-04-03 12:24:57.31995+00', 'Position de départ : trouve une surface inclinée (banc, marche ou plateforme solide) et place tes mains en formant un diamant en touchant avec tes pouces et index, le corps bien droit en planche avec les pieds au sol. Exécution : abaisse ta poitrine vers le diamant formé par tes mains, puis pousse pour revenir à la position de départ en gardant une bonne alignement du corps.', '["Ne pas descendre suffisamment", "Hanches qui s''affaissent pendant l''exercice"]', true, '["Find a stable inclined surface at an appropriate height for your fitness level", "Place hands on the surface forming a diamond shape with thumbs and index fingers touching", "Step feet back until your body forms a straight line from head to heels", "Lower your chest slowly toward the diamond formed by your hands until chest nearly touches", "Press through your palms to return to starting position while keeping core engaged", "Maintain controlled movement throughout the entire range of motion"]', '["Choisis une surface inclinée stable à la bonne hauteur pour toi", "Place tes mains dessus pour former un diamant avec les pouces et les index", "Recule les pieds jusqu''à ce que ton corps soit en ligne droite de la tête aux talons", "Abaisse ta poitrine doucement vers le diamant formé par tes mains jusqu''à ce qu''elle frôle", "Pousse avec tes paumes pour revenir à la position de départ tout en gardant les abdos engagés", "Garde un mouvement contrôlé durant tout l''exercice"]', '["Garde tes abdos serrés et ton corps bien droit pour éviter que tes hanches ne s''affaissent", "La position des mains en diamant cible davantage les triceps tout en sollicitant le pectoral", "Commence avec un angle d''inclinaison plus élevé et descends progressivement au fur et à mesure que tu gagnes en force", "Évite d''écarter les coudes trop largement - garde-les à environ 45 degrés de ton torse", "Contrôle la descente pour maximiser l''engagement musculaire et éviter les blessures"]', '["Keep your core tight and body in a straight line throughout the movement to prevent sagging hips", "The diamond hand position targets the triceps more than regular push-ups while still working the chest", "Start with a higher incline and progress to lower angles as you build strength", "Avoid flaring elbows too wide - keep them at roughly 45 degrees from your torso", "Control the descent to maximize muscle engagement and prevent injury"]', '95a95a22-308a-4804-af36-7190b48b1ae5', 'inclined-diamond-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('72ad80fa-bfb2-4073-bedc-705902f45379', 'Élévations latérales inversées sur banc incliné', NULL, NULL, 'Incline Dumbbell Reverse Fly', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/incline-dumbbell-reverse-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-dumbbell-reverse-fly.jpg', NULL, '["Activez votre sangle abdominale et gardez le contact entre votre poitrine et le banc tout au long de l''exercice.", "Concentrez-vous sur un mouvement des deltoïdes arrière sans utiliser d''élan.", "Choisissez des poids plus légers que ceux que vous pensez nécessiter, car cet exercice cible des groupes musculaires plus petits.", "Évitez de relever la tête ou d''accentuer la cambrure du dos durant le mouvement.", "Contrôlez la phase de descente pour maximiser l''activation musculaire."]', '["Lever les poids avec élan au lieu d''un mouvement contrôlé.", "Quand la tête est relevée ou le dos trop cambré pendant l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "incline dumbbell reverse fly"]', true, '2026-04-03 12:24:57.296073+00', '2026-04-03 12:24:57.296073+00', 'Adoptez la position de départ : allongez-vous face contre le banc incliné, un haltère dans chaque main, bras pendants. Exécution : élevez les haltères sur les côtés jusqu''à la hauteur des épaules, puis redescendez lentement.', '["Lever les poids avec élan au lieu d''un mouvement contrôlé.", "Quand la tête est relevée ou le dos trop cambré pendant l''exercice."]', true, '["Set an incline bench to 30-45 degrees and lie face down with your chest pressed against the pad", "Hold a dumbbell in each hand with a neutral grip, allowing your arms to hang straight down", "Keep a slight bend in your elbows throughout the entire movement", "Raise the dumbbells out to your sides in a controlled arc motion until your arms are parallel to the floor", "Squeeze your shoulder blades together at the top of the movement", "Slowly lower the weights back to the starting position with control"]', '["Réglez un banc incliné à 30-45 degrés et allongez-vous face contre la surface, la poitrine en contact avec le coussin.", "Tenez un haltère dans chaque main avec une prise neutre, les bras pendant vers le bas.", "Gardez une légère flexion dans les coudes durant tout le mouvement.", "Élevez les haltères sur les côtés en effectuant un mouvement contrôlé jusqu''à ce que vos bras soient parallèles au sol.", "Serrez les omoplates en haut du mouvement.", "Redescendez les poids lentement vers la position de départ en contrôlant le mouvement."]', '["Activez votre sangle abdominale et gardez le contact entre votre poitrine et le banc tout au long de l''exercice.", "Concentrez-vous sur un mouvement des deltoïdes arrière sans utiliser d''élan.", "Choisissez des poids plus légers que ceux que vous pensez nécessiter, car cet exercice cible des groupes musculaires plus petits.", "Évitez de relever la tête ou d''accentuer la cambrure du dos durant le mouvement.", "Contrôlez la phase de descente pour maximiser l''activation musculaire."]', '["Keep your core engaged and maintain contact between your chest and the bench throughout the exercise", "Focus on initiating the movement from your rear deltoids rather than using momentum", "Use lighter weights than you think you need as this exercise targets smaller muscle groups", "Avoid lifting your head or arching your back excessively during the movement", "Control the eccentric portion of the lift to maximize muscle activation"]', 'e60ce7d6-d899-4620-ac42-faa079614220', 'incline-dumbbell-reverse-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('b2ad00d6-ecdb-4731-8fb4-cf62caa3fa5b', 'Jump Get Ups', NULL, 'قفزات سريعة', 'Jump get ups', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/jump-get-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/jump-get-ups.jpg', NULL, '["Garde toujours ton gainage actif pour protéger le bas de ton dos", "Atterris en douceur sur la plante des pieds, les genoux légèrement fléchis pour absorber le choc", "Assure des transitions douces et contrôlées entre chaque phase du mouvement", "Commence doucement pour maîtriser la coordination avant d''accélérer", "Stoppe immédiatement si tu ressens une douleur au dos ou des vertiges."]', '["Ne pas activer le gainage pendant l''exercice", "Atterrir trop lourdement, ce qui peut causer des tensions"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "jump get ups"]', true, '2026-04-03 12:24:57.346624+00', '2026-04-03 12:24:57.346624+00', 'Allonge-toi sur le dos, bras le long du corps, jambes tendues. Prépare-toi à exploser !', '["Ne pas activer le gainage pendant l''exercice", "Atterrir trop lourdement, ce qui peut causer des tensions"]', true, '["Lie flat on your back with arms relaxed at your sides and legs fully extended", "Engage your core and explosively sit up while pulling your knees toward your chest", "Plant your feet firmly on the ground shoulder-width apart as you transition to a squat position", "Drive through your heels and jump straight up, reaching your arms overhead", "Land softly with bent knees and immediately lower back down to the starting lying position", "Control the descent to avoid jarring your back against the floor"]', '["Allonge-toi sur le dos, bras détendus, jambes complètement tendues", "Active ton gainage et lève-toi rapidement en ramenant les genoux vers ta poitrine", "Pose tes pieds sur le sol, écartés à la largeur des épaules, en te préparant à faire un squat", "Pousse sur tes talons et saute haut en levant les bras au-dessus de ta tête", "Atterris en douceur, les genoux fléchis, puis redescends lentement à la position de départ", "Contrôle ta descente pour éviter de heurter le sol avec le dos."]', '["Garde toujours ton gainage actif pour protéger le bas de ton dos", "Atterris en douceur sur la plante des pieds, les genoux légèrement fléchis pour absorber le choc", "Assure des transitions douces et contrôlées entre chaque phase du mouvement", "Commence doucement pour maîtriser la coordination avant d''accélérer", "Stoppe immédiatement si tu ressens une douleur au dos ou des vertiges."]', '["Keep your core engaged throughout the entire movement to protect your lower back", "Land softly on the balls of your feet with knees slightly bent to absorb impact", "Maintain smooth, controlled transitions between each phase of the movement", "Start slowly to master the coordination before increasing speed or intensity", "Stop immediately if you experience any back pain or dizziness"]', '703cabb7-a8d3-4fe8-a4e0-a5f931c7ddde', 'jump-get-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('1c3c52aa-12c6-40d6-aa47-5568c8dee9f6', 'Kettlebell Thruster', NULL, 'ثراستر د الكاتلبل', 'Kettlebell Thruster', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 128, '/videos/bodyweight/kettlebell-thruster.mp4', NULL, NULL, NULL, '/videos/thumbnails/kettlebell-thruster.jpg', NULL, '["Combine le squat et la presse pour un travail efficace", "Maintiens un mouvement continu pour maximiser les résultats", "Un excellent exercice pour le conditionnement physique", "Garde ton core bien engagé", "Expire lors de la poussée"]', '["Ne pas garder le dos droit pendant le squat", "Oublier d''utiliser l''élan pour la presse"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "kettlebell", "kettlebell thruster"]', true, '2026-04-03 12:24:57.424704+00', '2026-04-03 12:24:57.424704+00', 'Un exercice complet pour travailler l''ensemble du corps, alliant force et explosivité. Prépare-toi à faire monter ton cœur et à brûler des calories !', '["Ne pas garder le dos droit pendant le squat", "Oublier d''utiliser l''élan pour la presse"]', true, '["Hold kettlebells in rack position", "Squat down", "Drive up explosively", "Use momentum to press overhead", "Lower to rack and repeat"]', '["Prends les kettlebells en position de rack", "Fais un squat", "Propulse-toi vers le haut de manière explosive", "Utilise l''élan pour pousser au-dessus de la tête", "Redescends en position de rack et répète"]', '["Combine le squat et la presse pour un travail efficace", "Maintiens un mouvement continu pour maximiser les résultats", "Un excellent exercice pour le conditionnement physique", "Garde ton core bien engagé", "Expire lors de la poussée"]', '["Combines squat and press", "Continuous movement", "Great conditioning exercise", "Keep core tight", "Breathe out on the press"]', 'd8fcf6e7-3746-4f01-a943-fe45aed0fd31', 'kettlebell-thruster', NULL, NULL);
INSERT INTO public.exercises VALUES ('2d779730-d867-489a-a6f4-dd0e6e693f6f', 'Élévations de genoux (Suspendu)', NULL, NULL, 'Knee raises (Hanging)', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/knee-raises-hanging.mp4', NULL, NULL, NULL, '/videos/thumbnails/knee-raises-hanging.jpg', NULL, '["Maintiens une prise solide et évite de balancer ton corps ou d''utiliser l''élan pour lever tes jambes.", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement de ton core.", "Si tu n''arrives pas à garder la bonne forme, essaie les élévations de genoux pliés ou utilise des sangles pour t''aider à maintenir ta prise.", "Garde les épaules engagées et évite de rester suspendu passivement pour protéger tes articulations d''épaules.", "Commence par des temps de maintien plus courts et des répétitions moins nombreuses, et progresse progressivement au fur et à mesure que ta force abdominale augmente."]', '["Ne pas activer le core et laisser les épaules se relâcher.", "Utiliser l''élan au lieu de la force abdominale pour soulever les jambes."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "knee raises (hanging)"]', true, '2026-04-03 12:24:57.484065+00', '2026-04-03 12:24:57.484065+00', 'Cet exercice vise à renforcer ton core tout en améliorant ton équilibre et ta stabilité.', '["Ne pas activer le core et laisser les épaules se relâcher.", "Utiliser l''élan au lieu de la force abdominale pour soulever les jambes."]', true, '["Hang from a pull-up bar with an overhand grip, arms fully extended and feet off the ground", "Engage your core and keep your shoulders pulled down and back to maintain stability", "Slowly lift your knees toward your chest by flexing your hip and abdominal muscles", "Pause briefly when your thighs reach parallel to the ground or higher", "Lower your legs back to the starting position with control, avoiding swinging", "Repeat for desired repetitions while maintaining proper form throughout"]', '["Suspends-toi à une barre de traction avec les bras tendus et les pieds décollés du sol.", "Active ton core, tire bien tes épaules vers le bas et en arrière pour rester stable.", "Lève lentement tes genoux vers ta poitrine en fléchissant les hanches et les muscles abdominaux.", "Fais une pause quand tes cuisses atteignent la hauteur parallèle au sol ou plus haut.", "Ramène tes jambes à la position de départ avec contrôle, évite de balancer.", "Répète pour le nombre de répétitions souhaité tout en gardant une bonne technique."]', '["Maintiens une prise solide et évite de balancer ton corps ou d''utiliser l''élan pour lever tes jambes.", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement de ton core.", "Si tu n''arrives pas à garder la bonne forme, essaie les élévations de genoux pliés ou utilise des sangles pour t''aider à maintenir ta prise.", "Garde les épaules engagées et évite de rester suspendu passivement pour protéger tes articulations d''épaules.", "Commence par des temps de maintien plus courts et des répétitions moins nombreuses, et progresse progressivement au fur et à mesure que ta force abdominale augmente."]', '["Keep your grip secure and avoid swinging or using momentum to lift your legs", "Focus on controlled movements rather than speed to maximize core engagement", "If you can''t maintain proper form, try bent-knee raises or use straps to assist your grip", "Keep your shoulders engaged and avoid hanging passively to protect your shoulder joints", "Start with shorter holds and fewer reps, progressing gradually as your core strength improves"]', '0b7f1b84-6cb0-4875-824b-e86272668a2a', 'knee-raises-hanging', NULL, NULL);
INSERT INTO public.exercises VALUES ('26d819b1-8451-4b56-b86f-f94321e8f0e0', 'Marche en Élévation de Genoux', NULL, NULL, 'Knee raise marches', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/knee-raise-marches.mp4', NULL, NULL, NULL, '/videos/thumbnails/knee-raise-marches.jpg', NULL, '["Garde les muscles du ventre serrés pendant tout l''exercice pour maximiser l''engagement abdominal.", "Évite de te pencher en arrière ou en avant en levant chaque genou.", "Lève les genoux à hauteur de hanche ou aussi haut que tu te sens à l''aise tout en gardant une bonne posture.", "Contrôle bien la descente de chaque jambe au lieu de la laisser tomber rapidement.", "Commence par des séries plus courtes et augmente progressivement la durée à mesure que ta force au niveau des abdos s''améliore."]', '["Avoir une mauvaise posture en se penchant en arrière ou en avant.", "Ne pas lever suffisamment le genou, ce qui réduit l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "knee raise marches"]', true, '2026-04-03 12:24:57.468497+00', '2026-04-03 12:24:57.468497+00', 'Position de départ : Reste debout, les pieds écartés à la largeur des hanches, les bras le long du corps et le ventre bien contracté. Exécution : Alterne l''élévation de chaque genou vers ta poitrine tout en gardant une posture droite, comme si tu marchais de manière contrôlée.', '["Avoir une mauvaise posture en se penchant en arrière ou en avant.", "Ne pas lever suffisamment le genou, ce qui réduit l''efficacité de l''exercice."]', true, '["Stand with feet hip-width apart and engage your core muscles", "Lift your right knee up toward your chest to about hip level while keeping your torso upright", "Lower your right foot back to the starting position with control", "Immediately lift your left knee up toward your chest to the same height", "Continue alternating legs in a smooth, controlled marching pattern", "Maintain steady breathing throughout the movement"]', '["Tiens-toi droit, les pieds écartés à la largeur des hanches et le ventre engagé.", "Lève ton genou droit vers ta poitrine, à hauteur de hanche, en gardant le torse droit.", "Descends ton pied droit lentement à la position de départ.", "Lève immédiatement ton genou gauche vers ta poitrine à la même hauteur.", "Continue à alterner les jambes avec un mouvement fluide et contrôlé.", "Respire normalement tout au long de l''exercice."]', '["Garde les muscles du ventre serrés pendant tout l''exercice pour maximiser l''engagement abdominal.", "Évite de te pencher en arrière ou en avant en levant chaque genou.", "Lève les genoux à hauteur de hanche ou aussi haut que tu te sens à l''aise tout en gardant une bonne posture.", "Contrôle bien la descente de chaque jambe au lieu de la laisser tomber rapidement.", "Commence par des séries plus courtes et augmente progressivement la durée à mesure que ta force au niveau des abdos s''améliore."]', '["Keep your core tight throughout the entire movement to maximize abdominal engagement", "Avoid leaning backward or forward as you lift each knee", "Lift knees to hip level or as high as comfortable while maintaining good form", "Control the descent of each leg rather than letting it drop down quickly", "Start with shorter duration sets and gradually increase time as your core strength improves"]', '36034a77-8bbc-46c9-bf91-1c310704bf3b', 'knee-raise-marches', NULL, NULL);
INSERT INTO public.exercises VALUES ('518adc30-fa2a-4efe-b06e-2d8c31361652', 'Étirement latéral du cou (droite)', NULL, 'تمارين تمديد جانب الرقبة (اليمين)', 'Lateral neck stretch (right)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/lateral-neck-stretch-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/lateral-neck-stretch-right.jpg', NULL, '["Ne force jamais l''étirement et n''exerce pas de pression excessive avec ta main.", "Veille à garder l''épaule opposée baissée pour maximiser l''étirement du cou.", "Mouvement lent et fluide, évite les mouvements brusques du cou.", "Arrête immédiatement si tu ressens une douleur aiguë ou des vertiges.", "Concentre-toi sur la sensation d''étirement sur le côté gauche de ton cou et sur le trapèze supérieur."]', '["Forcer l''étirement au-delà des limites du confort.", "Lever l''épaule opposée, ce qui réduit l''efficacité de l''étirement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "lateral neck stretch (right)"]', true, '2026-04-03 12:24:57.537702+00', '2026-04-03 12:24:57.537702+00', 'Mets-toi debout ou assis dans une position droite. Garde les épaules relâchées et la tête bien droite. Incline doucement ta tête sur la droite, amenant ton oreille droite vers ton épaule droite tout en maintenant ton épaule gauche bien basse.', '["Forcer l''étirement au-delà des limites du confort.", "Lever l''épaule opposée, ce qui réduit l''efficacité de l''étirement."]', true, '["Stand or sit with good posture, keeping your spine straight and shoulders relaxed", "Place your right hand gently on the left side of your head above your ear", "Slowly tilt your head to the right, using light pressure from your hand to deepen the stretch", "Keep your left shoulder pressed down and avoid lifting it toward your ear", "Hold the stretch for 15-30 seconds while breathing normally", "Return to starting position slowly and repeat as needed"]', '["Tiens-toi droit, que ce soit debout ou assis, avec un dos bien droit et des épaules détendues.", "Pose ta main droite doucement sur le côté gauche de ta tête, au-dessus de l''oreille.", "Incline lentement ta tête à droite, en exerçant une légère pression avec ta main pour approfondir l''étirement.", "Garde ton épaule gauche bien abaissée et évite de la soulever vers ton oreille.", "Maintiens l''étirement pendant 15 à 30 secondes en respirant normalement.", "Retourne lentement à la position de départ et répète si nécessaire."]', '["Ne force jamais l''étirement et n''exerce pas de pression excessive avec ta main.", "Veille à garder l''épaule opposée baissée pour maximiser l''étirement du cou.", "Mouvement lent et fluide, évite les mouvements brusques du cou.", "Arrête immédiatement si tu ressens une douleur aiguë ou des vertiges.", "Concentre-toi sur la sensation d''étirement sur le côté gauche de ton cou et sur le trapèze supérieur."]', '["Never force the stretch or use excessive pressure with your hand", "Keep the opposite shoulder down to maximize the stretch along the neck", "Move slowly and smoothly to avoid sudden neck movements", "Stop immediately if you experience any sharp pain or dizziness", "Focus on feeling the stretch along the left side of your neck and upper trapezius"]', 'dfbfc890-af85-4be4-a8c6-782f666f538d', 'lateral-neck-stretch-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('9476e432-2242-4c6f-96f6-372c4b8aaa74', 'Étirement latéral du cou (gauche)', NULL, 'تمديد جانبي للعنق (الجهة اليسرى)', 'Lateral neck stretch (left)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/lateral-neck-stretch-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/lateral-neck-stretch-left.jpg', NULL, '["Ne force jamais l''étirement ni ne tire agressivement sur ta tête avec ta main", "Maintiens un mouvement lent et contrôlé pour éviter les blessures au cou", "Garde une bonne posture en gardant les épaules en bas et le dos droit", "Arrête immédiatement si tu ressens une douleur aiguë ou un inconfort", "Concentre-toi sur une sensation de léger étirement sur le côté droit de ton cou"]', '["Lever l''épaule droite au lieu de la maintenir en bas", "Forcer l''étirement et tirer trop fort sur la tête"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "lateral neck stretch (left)"]', true, '2026-04-03 12:24:57.533007+00', '2026-04-03 12:24:57.533007+00', 'Position de départ : Reste bien droit, que tu sois debout ou assis, avec les épaules détendues et la colonne vertébrale alignée. Exécution : Penche doucement la tête vers la gauche, amenant ton oreille gauche vers ton épaule gauche, tout en maintenant ton épaule droite en bas.', '["Lever l''épaule droite au lieu de la maintenir en bas", "Forcer l''étirement et tirer trop fort sur la tête"]', true, '["Stand or sit with your back straight and shoulders relaxed", "Place your left hand gently on the left side of your head above your ear", "Slowly tilt your head to the left, bringing your left ear toward your left shoulder", "Keep your right shoulder pressed down and avoid lifting it toward your ear", "Hold the stretch for 15-30 seconds while breathing normally", "Return to the starting position slowly and controlled"]', '["Tiens-toi bien droit, épaules relâchées", "Place doucement ta main gauche sur le côté gauche de ta tête au-dessus de l''oreille", "Incline lentement ta tête vers la gauche, amenant ton oreille gauche vers ton épaule gauche", "Garde ton épaule droite bien en bas, ne la soulève pas vers ton oreille", "Maintiens l''étirement pendant 15 à 30 secondes en respirant normalement", "Reviens à la position de départ lentement et en contrôle"]', '["Ne force jamais l''étirement ni ne tire agressivement sur ta tête avec ta main", "Maintiens un mouvement lent et contrôlé pour éviter les blessures au cou", "Garde une bonne posture en gardant les épaules en bas et le dos droit", "Arrête immédiatement si tu ressens une douleur aiguë ou un inconfort", "Concentre-toi sur une sensation de léger étirement sur le côté droit de ton cou"]', '["Never force the stretch or pull aggressively on your head with your hand", "Keep the movement slow and controlled to avoid neck injury", "Maintain proper posture by keeping your shoulders down and back straight", "Stop immediately if you feel any sharp pain or discomfort", "Focus on feeling a gentle stretch along the right side of your neck"]', '50f6c403-a7eb-4c43-9723-c9c4ee7defc7', 'lateral-neck-stretch-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('7e206e5c-da27-4ccd-9dce-5104575507d3', 'Posture du Lotus', NULL, 'وضعيه اللوتس', 'Lotus pose', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/lotus-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/lotus-pose.jpg', NULL, '["Ne tentez pas si vous n''avez pas une flexibilité suffisante.", "Ne forcez jamais sur les genoux, cela peut causer des blessures.", "Utilisez la demi-posture du lotus si nécessaire."]', '["Forcer les genoux dans la posture.", "Ne pas maintenir une bonne posture du dos.", "Rester trop longtemps dans une position inconfortable."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "lotus pose"]', true, '2026-04-03 12:24:57.597474+00', '2026-04-03 12:24:57.597474+00', 'Renforcez vos fessiers tout en cultivant la flexibilité et la sérénité.', '["Forcer les genoux dans la posture.", "Ne pas maintenir une bonne posture du dos.", "Rester trop longtemps dans une position inconfortable."]', true, '["Sit on the floor with legs extended.", "Bend one knee and place the foot on top of the opposite thigh.", "Bend the other knee and place that foot on top of the first thigh.", "Rest your hands on your knees and sit tall."]', '["Asseyez-vous sur le sol, jambes étendues.", "Pliez un genou et placez le pied sur la cuisse opposée.", "Pliez l''autre genou et placez ce pied sur la première cuisse.", "Reposnez vos mains sur vos genoux et tenez-vous bien droit."]', '["Ne tentez pas si vous n''avez pas une flexibilité suffisante.", "Ne forcez jamais sur les genoux, cela peut causer des blessures.", "Utilisez la demi-posture du lotus si nécessaire."]', '["Only attempt if you have sufficient hip flexibility.", "Never force the knees — this can cause injury.", "Use Half Lotus as a modification if needed."]', '2b82f2db-8edd-4904-af32-6fcf4c0d24d9', 'lotus-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('0f9667e2-d015-44de-9935-f6b1ea0efdc4', 'Fente basse (gauche)', NULL, NULL, 'Low lunge (left)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/low-lunge-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/low-lunge-left.jpg', NULL, '["Utilise une serviette ou un coussin sous le genou arrière si besoin.", "Pousse tes hanches vers l''avant pour un étirement plus profond.", "Garde ton ventre engagé et ton dos droit."]', '["Ne pas aligner le genou avant avec la cheville.", "Laisser le dos s''arrondir au lieu de le garder droit."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "low lunge (left)"]', true, '2026-04-03 12:24:57.620014+00', '2026-04-03 12:24:57.620014+00', 'Un excellent exercice pour travailler tes quadriceps tout en améliorant ta flexibilité.', '["Ne pas aligner le genou avant avec la cheville.", "Laisser le dos s''arrondir au lieu de le garder droit."]', true, '["From Downward Dog, step one foot forward between your hands.", "Lower your back knee to the mat.", "Stack your front knee over the ankle.", "Raise your arms overhead or keep hands on the floor."]', '["Depuis la posture du Chien tête en bas, avance un pied entre tes mains.", "Abaisse ton genou arrière sur le sol.", "Aligne ton genou avant avec ta cheville.", "Lève les bras au-dessus de ta tête ou garde les mains au sol."]', '["Utilise une serviette ou un coussin sous le genou arrière si besoin.", "Pousse tes hanches vers l''avant pour un étirement plus profond.", "Garde ton ventre engagé et ton dos droit."]', '["Pad your back knee with a blanket if needed.", "Sink your hips forward and down for a deeper stretch.", "Keep your core engaged and spine tall."]', 'b0cc57d7-7d6b-48ad-a9bc-a3dc309ea72b', 'low-lunge-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('7c69c6ce-4f00-4e01-a9b2-5f169c5e82de', 'Curl des jambes allongé', NULL, NULL, 'Lying Leg Curl', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 8, '/videos/hamstrings/lying-leg-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-leg-curl.jpg', NULL, '["Évite d''utiliser l''élan ou de balancer le poids - concentre-toi sur des mouvements lents et contrôlés", "Garde tes hanches bien plaquées contre le banc pour éviter de solliciter le bas du dos", "Ne soulève pas tes genoux du coussin pendant l''exercice", "Contrôle la phase de descente pour maximiser l''activation musculaire", "Arrête juste avant l''extension complète du genou pour garder une tension constante sur les ischio-jambiers"]', '["Ne pas garder le dos neutre", "Utiliser trop d''élan pour monter le poids"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "machine", "lying leg curl"]', true, '2026-04-03 12:24:57.727292+00', '2026-04-03 12:24:57.727292+00', 'Position de départ : Allonge-toi sur la machine à curl des jambes avec les chevilles bien maintenues sous les coussins. Exécution : Plie les genoux pour rapprocher les coussins de tes fessiers, puis redescends lentement à la position de départ.', '["Ne pas garder le dos neutre", "Utiliser trop d''élan pour monter le poids"]', true, '["Adjust the machine so the pad sits comfortably above your ankles and your knees align with the pivot point", "Lie face down on the bench with your hips pressed firmly against the pad and grip the side handles", "Keep your core engaged and maintain a neutral spine throughout the movement", "Curl your heels toward your glutes in a smooth, controlled motion while exhaling", "Squeeze your hamstrings at the top of the movement for a brief pause", "Lower the weight slowly back to starting position while inhaling, maintaining tension in your hamstrings"]', '["Règle la machine pour que le coussin soit confortablement au-dessus de tes chevilles et que tes genoux soient alignés avec le point de pivot", "Allonge-toi sur le banc en plaquant bien tes hanches contre le coussin et en tenant les poignées latérales", "Garde tes abdos contractés et le dos neutre tout au long de l''exercice", "Plie tes talons vers tes fessiers de manière fluide et contrôlée tout en expirant", "Serre bien tes ischio-jambiers en haut du mouvement et fais une courte pause", "Redescends le poids lentement à la position de départ en inspirant, tout en maintenant la tension dans tes ischio-jambiers"]', '["Évite d''utiliser l''élan ou de balancer le poids - concentre-toi sur des mouvements lents et contrôlés", "Garde tes hanches bien plaquées contre le banc pour éviter de solliciter le bas du dos", "Ne soulève pas tes genoux du coussin pendant l''exercice", "Contrôle la phase de descente pour maximiser l''activation musculaire", "Arrête juste avant l''extension complète du genou pour garder une tension constante sur les ischio-jambiers"]', '["Avoid using momentum or swinging the weight - focus on slow, controlled movements", "Keep your hips pressed down against the bench to prevent lower back compensation", "Don''t allow your knees to lift off the pad during the exercise", "Control the eccentric (lowering) portion of the movement to maximize muscle activation", "Stop just short of full knee extension to maintain constant tension on the hamstrings"]', '23b96196-f154-4450-a2cd-fdc35af2e60c', 'lying-leg-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('a7ef58d5-01a1-4c3f-b425-e9866a3797a3', 'Machine Kickback Fessiers Deux Jambes', NULL, NULL, 'Machine Glute Kickback Both Legs', 'Glutes', '[]', 'Glutes', 'Beginner', 8, '/videos/glutes/machine-glute-kickback-both-legs.mp4', NULL, NULL, NULL, '/videos/thumbnails/machine-glute-kickback-both-legs.jpg', NULL, '["Engagez votre sangle abdominale pour éviter d''arquer excessivement le bas du dos", "Concentrez-vous sur l''utilisation de vos muscles fessiers plutôt que sur l''élan pour réaliser le mouvement", "Maintenez un tempo contrôlé à la fois lors de la poussée et du retour", "Gardez votre poitrine pressée contre le coussinet pour la stabilité et la bonne forme", "Évitez d''utiliser le bas de votre dos pour initier le mouvement"]', '["Ne pas activer correctement les fessiers, ce qui diminue l''efficacité de l''exercice", "Pousser avec le bas du dos au lieu de se concentrer sur les muscles fessiers"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "machine", "machine glute kickback both legs"]', true, '2026-04-03 12:24:57.752845+00', '2026-04-03 12:24:57.752845+00', 'Position de départ : Asseyez-vous sur la machine de kickback fessiers avec le torse incliné en avant contre le coussinet, en tenant fermement les poignées pour la stabilité et avec les jambes placées derrière vous contre les coussinets des jambes. Exécution : Poussez les deux jambes en arrière en même temps dans un mouvement contrôlé, en contractant vos fessiers au sommet du mouvement avant de revenir lentement à la position de départ.', '["Ne pas activer correctement les fessiers, ce qui diminue l''efficacité de l''exercice", "Pousser avec le bas du dos au lieu de se concentrer sur les muscles fessiers"]', true, '["Position yourself on the machine with your chest against the pad and grip the handles firmly", "Place both legs against the leg pads with your knees slightly bent", "Lean your torso forward and maintain a stable core throughout the movement", "Push both legs back simultaneously using your glutes, not your lower back", "Squeeze your glutes at the top of the movement and hold briefly", "Slowly return your legs to the starting position with control"]', '["Installez-vous sur la machine avec la poitrine contre le coussinet et saisissez les poignées fermement", "Placez les deux jambes contre les coussinets avec les genoux légèrement fléchis", "Inclinez votre torse en avant et gardez votre sangle abdominale stable durant l''exercice", "Poussez les deux jambes en arrière simultanément en utilisant vos fessiers, pas votre bas du dos", "Contractez vos fessiers au sommet du mouvement et maintenez brièvement", "Renvoyez lentement vos jambes à la position de départ avec contrôle"]', '["Engagez votre sangle abdominale pour éviter d''arquer excessivement le bas du dos", "Concentrez-vous sur l''utilisation de vos muscles fessiers plutôt que sur l''élan pour réaliser le mouvement", "Maintenez un tempo contrôlé à la fois lors de la poussée et du retour", "Gardez votre poitrine pressée contre le coussinet pour la stabilité et la bonne forme", "Évitez d''utiliser le bas de votre dos pour initier le mouvement"]', '["Keep your core engaged to prevent excessive arching of the lower back", "Focus on using your glute muscles rather than momentum to power the movement", "Maintain a controlled tempo on both the pushing and returning phases", "Keep your chest pressed against the pad for stability and proper form", "Avoid using your lower back to initiate the movement"]', 'ae4a7149-9cfb-481e-bece-49ec526c8487', 'machine-glute-kickback-both-legs', NULL, NULL);
INSERT INTO public.exercises VALUES ('1854493e-b467-4086-aa67-8fab3503d10f', 'Presse Épaule sur Machine', NULL, 'آلة ضغط الكتفين', 'Machine Shoulder Press', 'Shoulders', '[]', 'Shoulders', 'Beginner', 8, '/videos/shoulders/machine-shoulder-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/machine-shoulder-press.jpg', NULL, '["Garde toujours tes abdominaux engagés pour protéger ton bas du dos", "Évite de pousser le poids derrière ta tête ou de descendre trop bas sous la hauteur des épaules", "Utilise une amplitude complète mais arrête-toi quand tes bras supérieurs atteignent le parallèle pour éviter les douleurs à l''épaule", "Concentre-toi sur une poussée verticale plutôt que vers l''avant pour maximiser l''activation des muscles des épaules", "Commence avec un poids léger pour maîtriser la forme correcte avant de passer à des charges plus lourdes"]', '["Ne pas ajuster la hauteur du siège correctement", "Cambrer le dos en poussant le poids vers le haut"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "machine shoulder press"]', true, '2026-04-03 12:24:57.784597+00', '2026-04-03 12:24:57.784597+00', 'Position de départ : Assieds-toi sur la machine de presse épaule, ajuste la hauteur du siège pour que les poignées soient à la hauteur de tes épaules. Exécution : Pousse les poignées vers le haut jusqu''à ce que tes bras soient complètement étendus, puis redescends lentement à la position de départ.', '["Ne pas ajuster la hauteur du siège correctement", "Cambrer le dos en poussant le poids vers le haut"]', true, '["Adjust the seat height so the handles align with your shoulders when seated", "Sit with your back flat against the pad and engage your core muscles", "Grasp the handles with a firm grip, keeping your wrists straight and neutral", "Press the weight up in a straight line overhead without arching your back excessively", "Lower the weight slowly and under control until your upper arms are parallel to the floor", "Maintain steady breathing throughout the movement, exhaling on the press up"]', '["Ajuste la hauteur du siège pour que les poignées soient alignées avec tes épaules en position assise", "Assieds-toi bien contre le dossier en engageant tes muscles abdominaux", "Saisis les poignées avec une prise ferme, en gardant les poignets droits et neutres", "Pousse le poids vers le haut en ligne droite sans cambrer excessivement le dos", "Redescends le poids lentement et de manière contrôlée jusqu''à ce que tes bras supérieurs soient parallèles au sol", "Respire régulièrement pendant le mouvement, expire lors de la poussée vers le haut"]', '["Garde toujours tes abdominaux engagés pour protéger ton bas du dos", "Évite de pousser le poids derrière ta tête ou de descendre trop bas sous la hauteur des épaules", "Utilise une amplitude complète mais arrête-toi quand tes bras supérieurs atteignent le parallèle pour éviter les douleurs à l''épaule", "Concentre-toi sur une poussée verticale plutôt que vers l''avant pour maximiser l''activation des muscles des épaules", "Commence avec un poids léger pour maîtriser la forme correcte avant de passer à des charges plus lourdes"]', '["Keep your core engaged throughout the entire movement to protect your lower back", "Avoid pressing the weight behind your head or lowering too far below shoulder level", "Use a full range of motion but stop when your upper arms reach parallel to prevent shoulder impingement", "Focus on pressing straight up rather than forward to maximize shoulder muscle activation", "Start with lighter weight to master proper form before progressing to heavier loads"]', 'd93f6d37-76e1-4cdc-a39e-d39beabf97d5', 'machine-shoulder-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('9a1eb9cd-5bf1-4e0e-a129-9a91d7f604ad', 'Grimpeurs de montagne', NULL, NULL, 'Mountain climbers', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/mountain-climbers-6c8af30b.mp4', NULL, NULL, NULL, '/videos/thumbnails/mountain-climbers-6c8af30b.jpg', NULL, '["Garde tes hanches basses (ne les soulève pas)", "Garde le gainage actif", "Accélère pour un boost cardio", "Ralentis pour plus de contrôle", "Exercice full body incroyable"]', '["Hanches trop hautes", "Manque de contrôle sur le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "mountain climbers"]', true, '2026-04-03 12:24:57.806161+00', '2026-04-03 12:24:57.806161+00', 'Un exercice explosif qui fait travailler ton cœur et renforce ton gainage !', '["Hanches trop hautes", "Manque de contrôle sur le mouvement"]', true, '["Start in push-up position", "Drive one knee toward chest", "Quickly switch legs", "Continue alternating at pace"]', '["Prends position en pompe", "Ramène un genou vers ta poitrine", "Change rapidement de jambe", "Alterne les jambes à un bon rythme"]', '["Garde tes hanches basses (ne les soulève pas)", "Garde le gainage actif", "Accélère pour un boost cardio", "Ralentis pour plus de contrôle", "Exercice full body incroyable"]', '["Keep hips down (don''t pike)", "Core stays engaged", "Speed up for more cardio", "Slow down for more control", "Full body exercise"]', '6c8af30b-31f1-4c84-b394-b4293607cf4f', 'mountain-climbers-6c8af30b', NULL, NULL);
INSERT INTO public.exercises VALUES ('5b7cb383-1d79-4ab4-8062-45997cdd2022', 'Escalade de Montagne', NULL, 'تسلق الجبال', 'Mountain Climbers', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/mountain-climbers.mp4', NULL, NULL, NULL, '/videos/thumbnails/mountain-climbers.jpg', NULL, '["Garde les hanches basses (évite de piker)", "Engage bien ton core", "Accélère pour un cardio intense", "Ralentis pour plus de contrôle", "Un exercice complet pour tout le corps"]', '["Se cambrer le dos", "Ne pas garder le rythme", "Oublier d''engager le ventre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "mountain climbers"]', true, '2026-04-03 12:24:57.815302+00', '2026-04-03 12:24:57.815302+00', 'Un exercice dynamique qui engage ton core tout en boostant ton cardio ! Prépare-toi à brûler des calories et renforcer ton corps.', '["Se cambrer le dos", "Ne pas garder le rythme", "Oublier d''engager le ventre"]', true, '["Start in push-up position", "Drive one knee toward chest", "Quickly switch legs", "Continue alternating at pace"]', '["Positionne-toi en planche sur les mains", "Ramène un genou vers ta poitrine", "Change rapidement de jambe", "Alterne les jambes à un rythme soutenu"]', '["Garde les hanches basses (évite de piker)", "Engage bien ton core", "Accélère pour un cardio intense", "Ralentis pour plus de contrôle", "Un exercice complet pour tout le corps"]', '["Keep hips down (don''t pike)", "Core stays engaged", "Speed up for more cardio", "Slow down for more control", "Full body exercise"]', '7a21c59b-ee5d-4f55-867f-31ca24c8003b', 'mountain-climbers', NULL, NULL);
INSERT INTO public.exercises VALUES ('9900de40-9655-4374-b40e-c5efa951ca6f', 'Tractions Négatives', NULL, 'سحب سلبي', 'Negative pull ups', 'Back', '[]', 'Back', 'Intermediate', 16, '/videos/back/negative-pull-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/negative-pull-ups.jpg', NULL, '["Concentre-toi sur le contrôle de la descente plutôt que de tomber rapidement", "Maintiens les épaules tirées vers l''arrière et vers le bas pour engager correctement le grand dorsal", "Garde une tension dans ton tronc pour éviter les mouvements excessifs ou le kipping", "Commence avec des durées plus courtes et augmente progressivement le temps de descente au fur et à mesure que tu deviens plus fort", "Cet exercice est excellent pour développer la force nécessaire afin de réaliser des tractions complètes"]', '["Laisser tomber rapidement sans contrôle", "Ne pas engager pleinement le dos et perdre la posture"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "negative pull ups"]', true, '2026-04-03 12:24:57.849436+00', '2026-04-03 12:24:57.849436+00', 'Position de départ : Commence dans la position haute d''une traction, le menton au-dessus de la barre, que ce soit en sautant ou en utilisant de l''aide pour y arriver. Exécution : Descends lentement de manière contrôlée jusqu''à avoir les bras complètement tendus, en te concentrant sur la phase excentrique du mouvement.', '["Laisser tomber rapidement sans contrôle", "Ne pas engager pleinement le dos et perdre la posture"]', true, '["Jump or use assistance to reach the top position with chin above the bar and arms fully contracted", "Grip the bar with hands shoulder-width apart using an overhand grip", "Engage your core and maintain a straight body line throughout the movement", "Slowly lower yourself down taking 3-5 seconds to reach full arm extension", "Control the descent by actively engaging your back muscles and biceps", "Once arms are fully extended, either drop safely to the ground or jump back up to repeat"]', '["Saute ou utilise de l''aide pour te placer au-dessus de la barre avec le menton au-dessus et les bras contractés", "Saisis la barre avec une prise en pronation, les mains à la largeur des épaules", "Engage ton tronc et garde le corps bien droit pendant tout le mouvement", "Descends lentement en prenant 3 à 5 secondes pour atteindre l''extension complète des bras", "Contrôle la descente en activant tes muscles du dos et tes biceps", "Une fois les bras entièrement tendus, tombe en toute sécurité au sol ou saute de nouveau pour répéter"]', '["Concentre-toi sur le contrôle de la descente plutôt que de tomber rapidement", "Maintiens les épaules tirées vers l''arrière et vers le bas pour engager correctement le grand dorsal", "Garde une tension dans ton tronc pour éviter les mouvements excessifs ou le kipping", "Commence avec des durées plus courtes et augmente progressivement le temps de descente au fur et à mesure que tu deviens plus fort", "Cet exercice est excellent pour développer la force nécessaire afin de réaliser des tractions complètes"]', '["Focus on controlling the lowering phase rather than just dropping down quickly", "Keep your shoulders pulled back and down to properly engage the latissimus dorsi", "Maintain tension in your core to prevent excessive swaying or kipping", "Start with shorter time periods and gradually increase the lowering duration as strength improves", "This exercise is excellent for building strength to eventually perform full pull-ups"]', 'fa6a3579-8bbe-47ab-b0dc-4d0545f16a34', 'negative-pull-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('ff3f2561-2ff3-4a06-9ba9-daafadb2c8dd', 'Posture de la Montagne', NULL, 'Position de jbel', 'Mountain pose', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/mountain-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/mountain-pose.jpg', NULL, '["Reste droit, fais grandir ta posture depuis le sommet de ta tête.", "Relaxe tes épaules, éloigne-les de tes oreilles.", "Cette posture est la base de toutes les poses debout !"]', '["Ne pas engager les cuisses et le tronc.", "Être penché en avant ou en arrière."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "mountain pose"]', true, '2026-04-03 12:24:57.840756+00', '2026-04-03 12:24:57.840756+00', 'Une posture fondamentale pour établir une base solide dans toutes les positions debout. Prépare-toi à ancrer ton corps et à te tenir avec assurance !', '["Ne pas engager les cuisses et le tronc.", "Être penché en avant ou en arrière."]', true, '["Stand with feet together or hip-width apart.", "Distribute your weight evenly across both feet.", "Engage your thighs, tuck your tailbone slightly, and lift your chest.", "Let your arms hang naturally with palms facing forward."]', '["Tiens-toi droit, les pieds joints ou écartés à la largeur des hanches.", "Répartis ton poids de manière égale sur tes deux pieds.", "Engage tes cuisses, rentre légèrement le bassin et relève la poitrine.", "Laisse tes bras pendre naturellement avec les paumes tournées vers l''avant."]', '["Reste droit, fais grandir ta posture depuis le sommet de ta tête.", "Relaxe tes épaules, éloigne-les de tes oreilles.", "Cette posture est la base de toutes les poses debout !"]', '["Stand tall through the crown of your head.", "Relax your shoulders away from your ears.", "This is the foundation for all standing poses."]', 'be5fae80-4b05-4196-8f3f-61d2c106ab32', 'mountain-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('bfc2d2eb-d68a-49b2-95dd-c3b5055daaae', 'Développé couché avec haltère à un bras alterné', NULL, NULL, 'One arm Dumbbell Floor Press alternating', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/one-arm-dumbbell-floor-press-alternating.mp4', NULL, NULL, NULL, '/videos/thumbnails/one-arm-dumbbell-floor-press-alternating.jpg', NULL, '["Maintiens les omoplates bien en arrière et au sol pour protéger tes épaules", "Contrôle la descente pour maximiser l''activation musculaire et réduire les risques de blessure", "Ne fais pas rebondir ton bras sur le sol - touche légèrement et remonte immédiatement", "Garde le ventre engagé et évite de cambrer le bas du dos", "Concentre-toi sur l''étirement de ta poitrine en bas avant de pousser vers le haut"]', '["Ne pas contrôler le mouvement lors de la descente", "Laisser le bas du dos se cambrer excessivement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "one arm dumbbell floor press alternating"]', true, '2026-04-03 12:24:58.157862+00', '2026-04-03 12:24:58.157862+00', 'Allonge-toi sur le dos, les genoux fléchis et les pieds à plat sur le sol. Tiens un haltère dans une main, bras tendu au-dessus de ta poitrine, pendant que l''autre main repose sur le sol.', '["Ne pas contrôler le mouvement lors de la descente", "Laisser le bas du dos se cambrer excessivement"]', true, '["Lie flat on the floor with your back pressed against the ground and knees bent at 90 degrees", "Hold one dumbbell with a firm grip, arm fully extended above your chest while keeping your shoulder blade pulled back", "Lower the weight in a controlled motion until your upper arm gently touches the floor", "Press the dumbbell back up to the starting position using your chest muscles", "Switch the dumbbell to the opposite hand and repeat the movement", "Maintain constant tension in your core throughout the entire exercise"]', '["Allonge-toi sur le sol, dos bien plaqué, genoux pliés à 90 degrés", "Prends un haltère solidement, bras complètement tendu au-dessus de ta poitrine tout en gardant l''omoplate en arrière", "Abaisse l''haltère doucement jusqu''à ce que ton bras supérieur frôle le sol", "Remonte l''haltère à la position de départ en utilisant tes muscles pectoraux", "Change l''haltère de main et répète le mouvement", "Garde ton gainage actif pendant tout l''exercice"]', '["Maintiens les omoplates bien en arrière et au sol pour protéger tes épaules", "Contrôle la descente pour maximiser l''activation musculaire et réduire les risques de blessure", "Ne fais pas rebondir ton bras sur le sol - touche légèrement et remonte immédiatement", "Garde le ventre engagé et évite de cambrer le bas du dos", "Concentre-toi sur l''étirement de ta poitrine en bas avant de pousser vers le haut"]', '["Keep your shoulder blades pulled back and down against the floor to maintain proper shoulder positioning", "Control the descent phase slowly to maximize muscle activation and prevent injury", "Avoid bouncing your arm off the floor - just lightly touch and immediately press back up", "Keep your core engaged and avoid arching your lower back excessively", "Focus on feeling the stretch in your chest at the bottom position before pressing up"]', '4e6181e0-c20f-4449-91e7-48d1eef1f268', 'one-arm-dumbbell-floor-press-alternating', NULL, NULL);
INSERT INTO public.exercises VALUES ('a27a2ed3-ddfe-46c4-9bff-bdafecb9300d', 'Pec Deck Fly - Éprouve la puissance de ta poitrine !', NULL, NULL, 'Pec Deck Fly', 'Chest', '[]', 'Chest', 'Beginner', 8, '/videos/chest/pec-deck-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/pec-deck-fly.jpg', NULL, '["Maintiens tes épaules en arrière et vers le bas contre le dossier pour éviter les douleurs", "Concentre-toi sur le serrage de tes muscles pectoraux plutôt que sur le simple déplacement du poids", "Assure une tension constante sur toute l''amplitude du mouvement sans verrouiller complètement les articulations", "Utilise un poids que tu maîtrises pour contrôler le mouvement dans les deux sens", "Garde ton ventre engagé pour maintenir une bonne posture pendant l''exercice"]', '["Ne pas ajuster la hauteur du siège correctement", "Oublier de garder le dos plaqué contre le dossier pendant l''exécution"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "machine", "pec deck fly"]', true, '2026-04-03 12:24:58.255796+00', '2026-04-03 12:24:58.255796+00', 'Position de départ : Installe-toi sur la machine Pec Deck avec le dos bien soutenu et prends les poignées avec les coudes légèrement fléchis. Exécution : Rassemble les poignées devant ta poitrine, puis ramène-les lentement à la position de départ.', '["Ne pas ajuster la hauteur du siège correctement", "Oublier de garder le dos plaqué contre le dossier pendant l''exécution"]', true, '["Adjust the seat height so your upper arms are parallel to the floor when grasping the handles", "Sit with your back flat against the pad and plant both feet firmly on the ground", "Grasp the vertical handles with a neutral grip or position your forearms against the arm pads", "Keep a slight bend in your elbows throughout the entire movement", "Bring your arms together by squeezing your chest muscles, not pulling with your arms", "Control the weight on the return phase, resisting the machine''s pull back to starting position"]', '["Ajuste la hauteur du siège pour que tes bras supérieurs soient parallèles au sol en tenant les poignées", "Assieds-toi avec le dos bien plaqué contre le dossier et pose fermement les deux pieds au sol", "Saisis les poignées verticales avec une prise neutre ou place tes avant-bras contre les coussins", "Garde une légère flexion dans les coudes pendant tout le mouvement", "Rassemble tes bras en serrant les muscles de ta poitrine, sans tirer avec les bras", "Contrôle le poids lors de la phase de retour, en résistant au tirage de la machine vers la position initiale"]', '["Maintiens tes épaules en arrière et vers le bas contre le dossier pour éviter les douleurs", "Concentre-toi sur le serrage de tes muscles pectoraux plutôt que sur le simple déplacement du poids", "Assure une tension constante sur toute l''amplitude du mouvement sans verrouiller complètement les articulations", "Utilise un poids que tu maîtrises pour contrôler le mouvement dans les deux sens", "Garde ton ventre engagé pour maintenir une bonne posture pendant l''exercice"]', '["Keep your shoulders back and down against the pad to prevent shoulder impingement", "Focus on squeezing your chest muscles rather than just moving the weight", "Maintain consistent tension throughout the full range of motion without locking out completely", "Use a weight that allows you to control the movement in both directions", "Keep your core engaged to maintain proper posture throughout the exercise"]', '371215cb-72ef-4039-8192-472234289504', 'pec-deck-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('97ee6855-2153-41e3-af06-2f7ca92249e4', 'Fente Arrière avec Élévation des Bras', NULL, NULL, 'Overhead Lunge', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/overhead-lunge.mp4', NULL, NULL, NULL, '/videos/thumbnails/overhead-lunge.jpg', NULL, '["Garde ton torse bien droit et évite de pencher en avant pendant la fente.", "Maintiens tes bras tendus au-dessus de la tête pour travailler ta stabilité de tronc et la mobilité des épaules.", "Atterris doucement sur ton pied avant et contrôle ta descente au lieu de tomber rapidement.", "Concentre la majorité de ton poids sur ta jambe avant durant la phase de fente.", "Si l''équilibre est difficile, commence sans lever les bras au-dessus de la tête jusqu''à maîtriser le mouvement."]', '["Laisser le genou avant s''écarter de la cheville.", "Pencher le torse en avant pendant la descente."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "overhead lunge"]', true, '2026-04-03 12:24:58.239286+00', '2026-04-03 12:24:58.239286+00', 'Position de départ : Tiens-toi bien droit, pieds à la largeur des hanches, bras tendus au-dessus de la tête. Exécution : Avance avec un pied en position de fente tout en gardant les bras en l''air, puis reviens à la position de départ en alternant les jambes.', '["Laisser le genou avant s''écarter de la cheville.", "Pencher le torse en avant pendant la descente."]', true, '["Stand with feet hip-width apart and extend both arms straight up toward the ceiling", "Keep your core engaged and shoulders pulled back throughout the entire movement", "Step forward with one leg, lowering your body until both knees are bent at approximately 90-degree angles", "Keep your front knee aligned over your ankle and avoid letting it drift inward", "Push through your front heel to return to the starting position with arms still overhead", "Alternate legs with each repetition, maintaining controlled movement"]', '["Tiens-toi debout, pieds à la largeur des hanches et bras tendus vers le plafond.", "Garde ton ventre engagé et tes épaules tirées en arrière tout au long de l''exercice.", "Fais un grand pas en avant avec une jambe, en fléchissant les deux genoux jusqu''à atteindre un angle d''environ 90 degrés.", "Veille à ce que ton genou avant soit bien aligné avec ta cheville et ne laisse pas ton genou partir vers l''intérieur.", "Pousse avec ton talon avant pour revenir à la position initiale, les bras toujours au-dessus de la tête.", "Alterne les jambes à chaque répétition, en gardant un mouvement contrôlé."]', '["Garde ton torse bien droit et évite de pencher en avant pendant la fente.", "Maintiens tes bras tendus au-dessus de la tête pour travailler ta stabilité de tronc et la mobilité des épaules.", "Atterris doucement sur ton pied avant et contrôle ta descente au lieu de tomber rapidement.", "Concentre la majorité de ton poids sur ta jambe avant durant la phase de fente.", "Si l''équilibre est difficile, commence sans lever les bras au-dessus de la tête jusqu''à maîtriser le mouvement."]', '["Keep your torso upright and avoid leaning forward as you lunge", "Maintain straight arms overhead to challenge your core stability and shoulder mobility", "Land softly on your front foot and control the descent rather than dropping quickly", "Keep most of your weight on your front leg during the lunge phase", "If balance is challenging, start without the overhead arm position until you master the movement pattern"]', '36aec113-771d-4ec9-854f-81f29e00cdd2', 'overhead-lunge', NULL, NULL);
INSERT INTO public.exercises VALUES ('3b4450e1-3982-4bb2-9de8-cf68f4f404e0', 'Over and Under (Gauche)', NULL, NULL, 'Over and under (Left)', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/over-and-under-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/over-and-under-left.jpg', NULL, '["Concentre-toi sur des transitions fluides entre les mouvements de passage et de plongeon pour maximiser les bénéfices de coordination", "Engage bien ton core pendant tout l''exercice pour maintenir la stabilité et protéger le bas du dos", "Commence doucement pour maîtriser le mouvement avant d''augmenter la vitesse ou l''intensité", "Assure-toi d''avoir une bonne marge de manœuvre en te déplaçant pour éviter les pertes d''équilibre", "Garde ton poids centré sur tes pieds pendant le mouvement de plongeon."]', '["Ne pas fléchir assez les hanches et les genoux lors de la plongée", "Oublier de maintenir le dos droit, ce qui peut engendrer des douleurs"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "over and under (left)"]', true, '2026-04-03 12:24:58.228302+00', '2026-04-03 12:24:58.228302+00', 'Position de départ : Place-toi debout, les pieds écartés à la largeur des épaules, face à un obstacle imaginaire ou réel à hauteur de taille. Exécution : Passe par-dessus l''obstacle avec la jambe gauche en premier, puis baisse-toi immédiatement en fléchissant les hanches et les genoux, en alternant entre franchir et passer en dessous dans un mouvement fluide et continu.', '["Ne pas fléchir assez les hanches et les genoux lors de la plongée", "Oublier de maintenir le dos droit, ce qui peut engendrer des douleurs"]', true, '["Begin in an athletic stance with knees slightly bent and core engaged", "Step over the imaginary obstacle by lifting your left knee high toward your chest, then step through", "Immediately transition to ducking under by bending at your hips and knees while keeping your back straight", "Return to standing position and repeat the over-under sequence", "Maintain a steady rhythm throughout the movement", "Keep your head up and eyes forward to maintain balance and coordination"]', '["Adopte une posture athlétique avec les genoux légèrement fléchis et le core engagé", "Saute par-dessus l''obstacle imaginaire en levant bien le genou gauche vers ta poitrine, puis avance", "Immédiatement, plonge en bas en fléchissant les hanches et les genoux tout en gardant le dos droit", "Remonte en position debout et répète la séquence par-dessus et en-dessous", "Maintiens un rythme régulier pendant tout l''exercice", "Garde la tête haute et les yeux devant toi pour maintenir équilibre et coordination."]', '["Concentre-toi sur des transitions fluides entre les mouvements de passage et de plongeon pour maximiser les bénéfices de coordination", "Engage bien ton core pendant tout l''exercice pour maintenir la stabilité et protéger le bas du dos", "Commence doucement pour maîtriser le mouvement avant d''augmenter la vitesse ou l''intensité", "Assure-toi d''avoir une bonne marge de manœuvre en te déplaçant pour éviter les pertes d''équilibre", "Garde ton poids centré sur tes pieds pendant le mouvement de plongeon."]', '["Focus on smooth transitions between the over and under movements to maximize coordination benefits", "Engage your core throughout the entire exercise to maintain stability and protect your lower back", "Start slowly to master the movement pattern before increasing speed or intensity", "Ensure adequate clearance when stepping over to avoid losing balance", "Keep your weight centered over your feet during the ducking motion"]', 'acaa8104-8a71-43bb-83ca-6a5c8085a3d8', 'over-and-under-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('c9b57310-404c-40b8-a74c-dd4f70cb90a0', 'Plank jack suivi de jumping jacks', NULL, 'Plank jack m3a jumping jacks', 'Plank jack into jumping jacks', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-jack-into-jumping-jacks.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-jack-into-jumping-jacks.jpg', NULL, '["Atterris doucement sur les plantes de pieds pour minimiser l''impact sur les articulations", "Fléchis légèrement les genoux à l''atterrissage pour absorber le choc", "Maintiens une posture droite, poitrine en avant et épaules en arrière", "Coordonne bien tes mouvements de bras et de jambes pour une fluidité optimale", "Commence à un rythme confortable et augmente progressivement l''intensité pendant l''échauffement"]', '["Atterrir trop fort, ce qui peut blesser les articulations", "Ne pas fléchir les genoux, ce qui peut causer des chocs dans les jambes", "Avoir une posture voûtée au lieu de garder le dos droit", "Ne pas coordonner les mouvements des bras et des jambes, l''exercice devient alors moins efficace", "Lâcher le gainage du ventre, ce qui peut diminuer l''impact sur le core"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank jack into jumping jacks"]', true, '2026-04-03 12:24:58.297623+00', '2026-04-03 12:24:58.297623+00', 'Prêt à cibler ton gainage tout en bougeant? Commence par te tenir droit, les pieds serrés. On y va!', '["Atterrir trop fort, ce qui peut blesser les articulations", "Ne pas fléchir les genoux, ce qui peut causer des chocs dans les jambes", "Avoir une posture voûtée au lieu de garder le dos droit", "Ne pas coordonner les mouvements des bras et des jambes, l''exercice devient alors moins efficace", "Lâcher le gainage du ventre, ce qui peut diminuer l''impact sur le core"]', true, '["Stand with feet together and arms relaxed at your sides", "Jump both feet out to shoulder-width apart while simultaneously raising both arms overhead", "Land softly on the balls of your feet with knees slightly bent", "Immediately jump feet back together while lowering arms to your sides", "Maintain a steady rhythm and continue the jumping motion", "Keep your core engaged throughout the entire movement"]', '["Tiens-toi bien droit, pieds ensemble, bras relâchés sur les côtés", "Saute en écartant les pieds à la largeur des épaules tout en levant les bras au-dessus de ta tête", "Atterris doucement sur la plante des pieds, genoux légèrement fléchis", "Saute de nouveau pour ramener les pieds ensemble tout en baissant les bras", "Reste dans le rythme et continue le mouvement", "Garde bien le gainage actif tout au long de l''exercice"]', '["Atterris doucement sur les plantes de pieds pour minimiser l''impact sur les articulations", "Fléchis légèrement les genoux à l''atterrissage pour absorber le choc", "Maintiens une posture droite, poitrine en avant et épaules en arrière", "Coordonne bien tes mouvements de bras et de jambes pour une fluidité optimale", "Commence à un rythme confortable et augmente progressivement l''intensité pendant l''échauffement"]', '["Land softly on the balls of your feet to reduce impact on joints", "Keep knees slightly bent when landing to absorb shock", "Maintain an upright posture with chest up and shoulders back", "Coordinate arm and leg movements in a smooth, rhythmic pattern", "Start at a comfortable pace and gradually increase intensity as you warm up"]', 'ac0cb7cb-0988-4591-9d99-716502691f26', 'plank-jack-into-jumping-jacks', NULL, NULL);
INSERT INTO public.exercises VALUES ('45807cb3-ccbf-428c-b953-22154091a3f4', 'Élévation Frontale avec Disque', NULL, 'رفع أمامي بالقرص', 'Plate Front Raise', 'Shoulders', '[]', 'Shoulders', 'Beginner', 1, '/videos/shoulders/plate-front-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/plate-front-raise.jpg', NULL, '["Réalisez le mouvement lentement et avec contrôle pour maximiser l''engagement musculaire et prévenir les blessures", "Évitez d''utiliser l''élan ou de balancer le disque, car cela réduit l''efficacité et augmente le risque de blessure", "Arrêtez le mouvement vers le haut à la hauteur des épaules pour éviter les douleurs à l''épaule", "Choisissez un poids adapté pour maintenir une bonne forme durant toutes les répétitions", "Gardez le ventre serré et évitez de cambrer le dos pendant la phase de levée"]', '["Utiliser trop de poids et perdre la forme correcte", "Balancer le disque au lieu de faire un mouvement contrôlé"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "barbell", "plate front raise"]', true, '2026-04-03 12:24:58.365906+00', '2026-04-03 12:24:58.365906+00', 'Position de départ : Tenez un disque avec les deux mains devant les cuisses. Exécution : Élevez le disque devant vous jusqu''à la hauteur des épaules, puis redescendez-le lentement.', '["Utiliser trop de poids et perdre la forme correcte", "Balancer le disque au lieu de faire un mouvement contrôlé"]', true, '["Stand with feet shoulder-width apart and core engaged, holding the weight plate with both hands using an overhand grip", "Keep your arms slightly bent throughout the movement to reduce stress on the elbow joints", "Raise the plate smoothly in front of your body until it reaches shoulder height, maintaining control", "Pause briefly at the top position without swinging or using momentum", "Lower the plate back to the starting position in a slow, controlled manner", "Maintain proper posture with shoulders back and chest up throughout the entire movement"]', '["Tenez-vous debout, les pieds écartés à la largeur des épaules et le ventre engagé, en tenant le disque avec les deux mains en prise pronation", "Gardez les bras légèrement fléchis pendant tout le mouvement pour réduire la pression sur les coudes", "Soulevez le disque lentement devant votre corps jusqu''à la hauteur des épaules, tout en gardant le contrôle", "Faites une courte pause en haut sans balancer ni utiliser d''élan", "Abaissez le disque lentement à la position de départ de manière contrôlée", "Maintenez une bonne posture avec les épaules en arrière et la poitrine en avant durant tout le mouvement"]', '["Réalisez le mouvement lentement et avec contrôle pour maximiser l''engagement musculaire et prévenir les blessures", "Évitez d''utiliser l''élan ou de balancer le disque, car cela réduit l''efficacité et augmente le risque de blessure", "Arrêtez le mouvement vers le haut à la hauteur des épaules pour éviter les douleurs à l''épaule", "Choisissez un poids adapté pour maintenir une bonne forme durant toutes les répétitions", "Gardez le ventre serré et évitez de cambrer le dos pendant la phase de levée"]', '["Keep the movement slow and controlled to maximize muscle engagement and prevent injury", "Avoid using momentum or swinging the plate, as this reduces effectiveness and increases injury risk", "Stop the upward motion at shoulder height to prevent impingement of the shoulder joint", "Choose an appropriate weight that allows you to maintain proper form throughout all repetitions", "Keep your core tight and avoid arching your back during the lifting phase"]', '980a6af6-f72f-4e21-bfcf-4253622d507d', 'plate-front-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('8ab85785-c28b-482a-9a4d-ff49957a4146', 'Taps d''épaules en planche', NULL, 'ضربات الكتف في وضعية البلانك', 'Plank shoulder taps', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-shoulder-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-shoulder-taps.jpg', NULL, '["Garde les hanches à niveau, évite de faire pivoter ou osciller ton corps pendant les taps.", "Maintiens une bonne position de planche avec les muscles du tronc engagés durant tout l''exercice.", "Place tes mains directement sous les épaules pour une bonne alignement et stabilité.", "Contrôle le mouvement ; ne te précipite pas dans les taps.", "Répartis ton poids de manière équilibrée lorsque tu lèves une main pour éviter de stresser l''autre bras."]', '["Ouvrir les hanches lors des taps, entraînant instabilité.", "Ne pas maintenir la ligne droite du corps durant l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank shoulder taps"]', true, '2026-04-03 12:24:58.340987+00', '2026-04-03 12:24:58.340987+00', 'Commence par une position de planche haute, avec les bras tendus et les mains sous les épaules. Garde ton corps bien aligné, de la tête aux talons. Alterne en levant une main pour toucher l''épaule opposée tout en maintenant la stabilité de ton tronc.', '["Ouvrir les hanches lors des taps, entraînant instabilité.", "Ne pas maintenir la ligne droite du corps durant l''exercice."]', true, '["Start in a high plank position with hands placed directly under your shoulders and feet hip-width apart", "Engage your core and maintain a straight line from your head to your heels", "Shift your weight slightly to one side and lift the opposite hand to tap the opposite shoulder", "Return the hand to the starting position and repeat the movement with the other hand", "Continue alternating shoulder taps while keeping your hips as stable as possible", "Maintain steady breathing throughout the entire movement"]', '["Prends position en planche haute, mains sous les épaules, pieds écartés à la largeur des hanches.", "Active ton core et assure-toi d''avoir une ligne droite entre la tête et les talons.", "Déplace légèrement ton poids d''un côté et lève l''autre main pour toucher l''épaule opposée.", "Ramène la main à la position de départ et répète de l''autre côté.", "Continue d''alterner les taps en maintenant les hanches aussi stables que possible.", "Respire régulièrement tout au long de l''exercice."]', '["Garde les hanches à niveau, évite de faire pivoter ou osciller ton corps pendant les taps.", "Maintiens une bonne position de planche avec les muscles du tronc engagés durant tout l''exercice.", "Place tes mains directement sous les épaules pour une bonne alignement et stabilité.", "Contrôle le mouvement ; ne te précipite pas dans les taps.", "Répartis ton poids de manière équilibrée lorsque tu lèves une main pour éviter de stresser l''autre bras."]', '["Keep your hips level and avoid rotating or swaying from side to side during the shoulder taps", "Maintain a strong plank position with engaged core muscles throughout the entire exercise", "Place hands directly under shoulders to maintain proper alignment and stability", "Keep the movement controlled and deliberate rather than rushing through the taps", "Distribute weight evenly when lifting one hand to prevent excessive stress on the supporting arm"]', '2c7167fd-5e7e-444f-b7a8-291e362e638c', 'plank-shoulder-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('4889cce1-2dca-46ba-993c-493f620bde1f', 'Pompes', NULL, NULL, 'Push ups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/push-ups.jpg', NULL, '["Assure-toi de garder un bon alignement corporel en maintenant la tête en position neutre et en évitant que les hanches ne s''affaissent ou que les fesses ne soient trop hautes", "Commence par des versions modifiées comme les pompes sur les genoux ou les pompes inclinées si tu ne peux pas faire de pompes complètes avec la bonne forme", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement musculaire et réduire le risque de blessure", "Arrête l''exercice si tu ressens des douleurs aux poignets et envisage d''utiliser des poignées de pompes ou de faire des poings au lieu des paumes à plat", "Progresse progressivement en augmentant les répétitions ou en essayant des variations plus difficiles une fois que tu peux faire 15-20 pompes parfaites"]', '["Laisser traîner les hanches trop bas ou trop haut", "Ecarter trop les coudes lors de la descente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "push ups"]', true, '2026-04-03 12:24:58.507719+00', '2026-04-03 12:24:58.507719+00', 'Position de départ : Mets-toi en position de planche, les mains légèrement plus larges que la largeur des épaules, bras bien tendus, corps aligné de la tête aux talons. Exécution : Abaisse ton corps en pliant les coudes jusqu''à ce que ta poitrine frôle le sol, puis pousse avec force pour revenir à la position de départ en redressant les bras.', '["Laisser traîner les hanches trop bas ou trop haut", "Ecarter trop les coudes lors de la descente"]', true, '["Position hands flat on the floor slightly wider than shoulder-width with fingers spread for stability", "Keep your core engaged and maintain a straight line from head to heels throughout the movement", "Lower your body slowly and controlled until your chest is about 1-2 inches from the floor", "Keep your elbows at a 45-degree angle to your body rather than flaring them straight out", "Push through your palms to return to the starting position with full arm extension", "Breathe in as you lower down and exhale as you push back up"]', '["Place tes mains à plat au sol légèrement plus larges que la largeur des épaules et écarte les doigts pour plus de stabilité", "Engage ton core et maintiens une ligne droite de la tête aux talons tout au long de l''exercice", "Abaisse ton corps de manière lente et contrôlée jusqu''à ce que ta poitrine soit à environ 1-2 pouces du sol", "Garde tes coudes à un angle de 45 degrés par rapport à ton corps au lieu de les écarter", "Pousse sur tes paumes pour revenir à la position de départ avec les bras complètement étendus", "Inspire en descendant et expire en te relevant"]', '["Assure-toi de garder un bon alignement corporel en maintenant la tête en position neutre et en évitant que les hanches ne s''affaissent ou que les fesses ne soient trop hautes", "Commence par des versions modifiées comme les pompes sur les genoux ou les pompes inclinées si tu ne peux pas faire de pompes complètes avec la bonne forme", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour maximiser l''engagement musculaire et réduire le risque de blessure", "Arrête l''exercice si tu ressens des douleurs aux poignets et envisage d''utiliser des poignées de pompes ou de faire des poings au lieu des paumes à plat", "Progresse progressivement en augmentant les répétitions ou en essayant des variations plus difficiles une fois que tu peux faire 15-20 pompes parfaites"]', '["Maintain proper body alignment by keeping your head in neutral position and avoiding sagging hips or raised buttocks", "Start with modified versions like knee push-ups or incline push-ups if you cannot perform full push-ups with proper form", "Focus on controlled movement rather than speed to maximize muscle engagement and reduce injury risk", "Stop the exercise if you experience wrist pain and consider using push-up handles or making fists instead of flat palms", "Progress gradually by increasing repetitions or trying more challenging variations once you can perform 15-20 perfect push-ups"]', 'b41a30a8-8a02-4101-a0a9-589efdbf786b', 'push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('3136dc1c-3516-43cd-b42f-479e0a388a67', 'Posture de la pyramide (gauche)', NULL, 'وضعية الهرم (يسار)', 'Pyramid pose (left)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/pyramid-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/pyramid-pose-left.jpg', NULL, '["Garde les jambes droites avec un léger pli dans le genou avant.", "Incline-toi à partir des hanches, pas du dos.", "Enfonce bien les deux pieds dans le sol pour un équilibre optimal."]', '["Ne pas aligner les hanches correctement vers l''avant.", "Plier les genoux trop profondément au lieu de garder les jambes droites."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "pyramid pose (left)"]', true, '2026-04-03 12:24:58.541749+00', '2026-04-03 12:24:58.541749+00', 'Renforce tes ischio-jambiers et améliore ta flexibilité avec cette posture dynamique. Prépare-toi à te concentrer et à ressentir chaque étirement !', '["Ne pas aligner les hanches correctement vers l''avant.", "Plier les genoux trop profondément au lieu de garder les jambes droites."]', true, '["Stand with one foot stepped back about 3 feet.", "Square your hips toward the front of the mat.", "Fold forward over your front leg with a flat back.", "Place your hands on the floor or on blocks beside your front foot."]', '["Relève-toi en plaçant un pied en arrière d''environ 1 mètre.", "Aligne tes hanches vers l''avant du tapis.", "Penche-toi en avant sur ta jambe de devant avec le dos bien droit.", "Pose tes mains au sol ou sur des briques à côté de ton pied avant."]', '["Garde les jambes droites avec un léger pli dans le genou avant.", "Incline-toi à partir des hanches, pas du dos.", "Enfonce bien les deux pieds dans le sol pour un équilibre optimal."]', '["Keep both legs straight with a micro-bend in the front knee.", "Hinge from the hips.", "Press evenly through both feet."]', '396dee3e-b0b6-409b-a331-47d3bd121ac8', 'pyramid-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('7b542f41-c33a-4efe-8d93-37def8afbc49', 'Pose du pigeon allongé (gauche)', NULL, NULL, 'Reclined pigeon pose (left)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/reclined-pigeon-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/reclined-pigeon-pose-left.jpg', NULL, '["Garde la tête et les épaules au sol.", "Fléchis le pied croisé pour protéger ton genou.", "Respire profondément pour intensifier l''étirement des hanches."]', '["Arquer le dos au sol.", "Tirer trop fort sur la cuisse.", "Retenir sa respiration."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "reclined pigeon pose (left)"]', true, '2026-04-03 12:24:58.561638+00', '2026-04-03 12:24:58.561638+00', 'Un exercice puissant pour assouplir les fessiers et relâcher les tensions dans les hanches.', '["Arquer le dos au sol.", "Tirer trop fort sur la cuisse.", "Retenir sa respiration."]', true, '["Lie on your back with knees bent and feet flat.", "Cross one ankle over the opposite knee.", "Thread your hands behind the supporting thigh.", "Gently pull the thigh toward your chest."]', '["Allonge-toi sur le dos, genoux fléchis et pieds ancrés au sol.", "Croise une cheville sur le genou opposé.", "Enlace ta cuisse de soutien avec tes mains.", "Tire doucement la cuisse vers ta poitrine."]', '["Garde la tête et les épaules au sol.", "Fléchis le pied croisé pour protéger ton genou.", "Respire profondément pour intensifier l''étirement des hanches."]', '["Keep your head and shoulders on the floor.", "Flex the crossed foot to protect the knee.", "Breathe deeply into the hip stretch."]', '1523b6fd-d8b9-4406-b188-5d1545dd0cb2', 'reclined-pigeon-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('a92e32a3-dddb-46fe-ae25-610b0b81cdcc', 'Guerrier Inversé (Gauche)', NULL, 'محارب مقلوب (يسار)', 'Reverse warrior (left)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/reverse-warrior-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/reverse-warrior-left.jpg', NULL, '["Maintiens ton genou avant fléchi à 90 degrés.", "Ne transfère pas ton poids sur ta main arrière.", "Crée une longue étire de côté."]', '["Genou avant qui dépasse les orteils.", "Poids trop lourd sur la main arrière.", "Absence d''ouverture de la poitrine."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "reverse warrior (left)"]', true, '2026-04-03 12:24:58.612248+00', '2026-04-03 12:24:58.612248+00', 'Un excellent exercice pour travailler vos quadriceps et améliorer votre flexibilité tout en renforçant votre concentration.', '["Genou avant qui dépasse les orteils.", "Poids trop lourd sur la main arrière.", "Absence d''ouverture de la poitrine."]', true, '["From Warrior II, flip your front palm up.", "Inhale and reach your front arm up and back overhead.", "Let your back hand slide down the back leg.", "Open your chest toward the ceiling."]', '["À partir du Guerrier II, retourne ta paume avant vers le haut.", "Inspire et étire ton bras avant vers le haut et vers l''arrière au-dessus de ta tête.", "Laisse ta main arrière glisser le long de ta jambe arrière.", "Ouvre ta poitrine vers le plafond."]', '["Maintiens ton genou avant fléchi à 90 degrés.", "Ne transfère pas ton poids sur ta main arrière.", "Crée une longue étire de côté."]', '["Keep your front knee bent at 90 degrees.", "Do not dump weight into the back hand.", "Create a long side-body stretch."]', '87cb06b9-6563-4676-b796-b02f68af48b5', 'reverse-warrior-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('2610e388-61ff-4b1a-b45b-c740d2cfa53a', 'Posture de la Chaise Tournée (gauche)', NULL, 'وضعية الكرسي المحور (يسر)', 'Revolved chair pose (left)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/revolved-chair-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/revolved-chair-pose-left.jpg', NULL, '["Descends encore plus pour intensifier la posture.", "Effectue la torsion à partir du milieu du dos, pas seulement des épaules.", "Maintiens ton poids sur les talons."]', '["Ne pas garder les genoux alignés, ce qui peut causer une tension.", "Torsion uniquement avec les épaules, laisse le dos travailler."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "revolved chair pose (left)"]', true, '2026-04-03 12:24:58.622497+00', '2026-04-03 12:24:58.622497+00', 'Renforce ton tronc tout en améliorant ta flexibilité avec cette pose dynamique !', '["Ne pas garder les genoux alignés, ce qui peut causer une tension.", "Torsion uniquement avec les épaules, laisse le dos travailler."]', true, '["Start in Chair Pose with palms together at your chest.", "Twist your torso and hook one elbow outside the opposite knee.", "Press your palms together to deepen the twist.", "Keep your knees even and hips level."]', '["Commence en position de la chaise avec les paumes jointes devant la poitrine.", "Torche ton torse et croise un coude à l''extérieur du genou opposé.", "Appuie tes paumes ensemble pour approfondir la torsion.", "Garde les genoux alignés et les hanches à niveau."]', '["Descends encore plus pour intensifier la posture.", "Effectue la torsion à partir du milieu du dos, pas seulement des épaules.", "Maintiens ton poids sur les talons."]', '["Sit deeper to intensify the pose.", "Twist from your mid-back, not just your shoulders.", "Keep your weight in your heels."]', 'db3c3c60-a406-45e8-a477-8c5c1bf41870', 'revolved-chair-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('d06028f4-a594-409e-b9ec-fc57130c5e38', 'Twist Russe avec Poids', NULL, NULL, 'Russian Twist - Weighted', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/russian-twist-weighted.mp4', NULL, NULL, NULL, '/videos/thumbnails/russian-twist-weighted.jpg', NULL, '["Garde le dos droit et évite d''arrondir la colonne vertébrale pendant la rotation", "Concentre-toi sur la rotation depuis tes muscles du core plutôt que de déplacer uniquement tes bras", "Commence avec un poids léger pour maîtriser le mouvement avant de passer à des charges plus lourdes", "Rappelle-toi de respirer régulièrement pendant l''exercice, en expirant à chaque rotation", "Tiens ton buste droit et tes épaules en arrière pour éviter de te voûter vers l''avant"]', '["Ne pas engager le core, ce qui peut entraîner une mauvaise posture", "Bouger uniquement les bras sans faire de rotation du torse"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "russian twist - weighted"]', true, '2026-04-03 12:24:58.675658+00', '2026-04-03 12:24:58.675658+00', 'Position de départ : Assis sur le sol, genoux fléchis, pieds à plat. Penche-toi légèrement en arrière pour équilibrer ton corps sur les os du siège, en tenant un poids ou un medicine ball contre ta poitrine. Exécution : Fais pivoter ton torse de gauche à droite, en touchant le poids au sol à côté de chaque hanche tout en maintenant ton équilibre.', '["Ne pas engager le core, ce qui peut entraîner une mauvaise posture", "Bouger uniquement les bras sans faire de rotation du torse"]', true, '["Sit with knees bent and feet flat on the floor, holding your chosen weight with both hands at chest level", "Lean back slightly to balance on your sit bones, engaging your core muscles to maintain stability", "Lift your feet off the ground if comfortable, or keep them planted for additional stability", "Rotate your torso to the right, bringing the weight toward the floor beside your right hip", "Return to center, then rotate to the left, touching the weight beside your left hip", "Continue alternating sides in a controlled, rhythmic motion while maintaining your balanced position"]', '["Assieds-toi avec les genoux fléchis et les pieds à plat, tenant ton poids avec les deux mains au niveau de la poitrine", "Penche-toi légèrement en arrière pour équilibrer ton corps sur les os du siège, en engageant tes muscles abdominaux pour maintenir la stabilité", "Soulève les pieds du sol si tu te sens à l''aise, sinon, garde-les au sol pour plus de stabilité", "Fais pivoter ton torse vers la droite, en amenant le poids vers le sol à côté de ta hanche droite", "Ramène au centre, puis pivote vers la gauche, en touchant le poids à côté de ta hanche gauche", "Alterne les côtés de manière contrôlée et rythmée tout en maintenant ta position équilibrée"]', '["Garde le dos droit et évite d''arrondir la colonne vertébrale pendant la rotation", "Concentre-toi sur la rotation depuis tes muscles du core plutôt que de déplacer uniquement tes bras", "Commence avec un poids léger pour maîtriser le mouvement avant de passer à des charges plus lourdes", "Rappelle-toi de respirer régulièrement pendant l''exercice, en expirant à chaque rotation", "Tiens ton buste droit et tes épaules en arrière pour éviter de te voûter vers l''avant"]', '["Keep your back straight and avoid rounding your spine during the rotation", "Focus on rotating from your core rather than just moving your arms", "Start with a lighter weight to master the movement pattern before progressing to heavier loads", "Maintain steady breathing throughout the exercise, exhaling during each twist", "Keep your chest up and shoulders back to prevent hunching forward"]', '75649a91-b901-4140-ab80-3052a3afed27', 'russian-twist-weighted', NULL, NULL);
INSERT INTO public.exercises VALUES ('2506e3a9-2711-4e69-b6a2-8014f63a32b6', 'Développez votre force avec le Développé Militaire Assis', NULL, 'خدم القوة ديالك مع الضغط العسكرى الجالس', 'Seated Barbell Military Press', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 1, '/videos/shoulders/seated-barbell-military-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-barbell-military-press.jpg', NULL, '["Maintenez votre core engagé et évitez de cambrer le dos de manière excessive lors de la poussée.", "Utilisez une prise complète sur la barre plutôt qu''une prise sans pouce pour un meilleur contrôle et sécurité.", "Abaissez la barre uniquement jusqu''au niveau des épaules pour protéger vos articulations des épaules d''une hyperextension.", "Commencez avec un poids léger pour maîtriser la forme avant de progresser vers des charges plus lourdes.", "Expirez pendant la phase de poussage et inspirez lors de la descente."]', '["Ne pas stabiliser le dos, ce qui peut entraîner des blessures.", "Pousser la barre vers l''avant ou l''arrière au lieu de la garder droite."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "barbell", "seated barbell military press"]', true, '2026-04-03 12:24:58.752098+00', '2026-04-03 12:24:58.752098+00', 'Position de départ : Asseyez-vous sur un banc avec une barre dans les mains, bras tendus au-dessus de votre tête avec une prise pronation. Exécution : Abaissez la barre vers vos épaules, puis poussez-la vers le haut pour revenir à la position de départ.', '["Ne pas stabiliser le dos, ce qui peut entraîner des blessures.", "Pousser la barre vers l''avant ou l''arrière au lieu de la garder droite."]', true, '["Sit with your back firmly against the bench pad and feet planted flat on the floor for stability", "Grip the barbell with hands slightly wider than shoulder-width apart, positioning it at shoulder level across your upper chest", "Engage your core and maintain a neutral spine throughout the entire movement", "Press the barbell straight up overhead in a controlled motion, avoiding pressing forward or backward", "Lower the weight slowly back to shoulder level, maintaining control and stopping when the bar reaches chin height", "Keep your wrists straight and elbows slightly forward throughout the movement"]', '["Asseyez-vous avec le dos bien plaqué contre le banc et les pieds à plat sur le sol pour une meilleure stabilité.", "Attrapez la barre avec les mains légèrement plus larges que la largeur des épaules, en la plaçant au niveau des épaules sur la partie supérieure de votre poitrine.", "Engagez votre sangle abdominale et gardez une colonne vertébrale neutre tout au long du mouvement.", "Poussez la barre droit vers le haut en contrôlant le mouvement, sans projeter vers l’avant ou l’arrière.", "Abaissez la barre lentement jusqu''au niveau des épaules, en gardant le contrôle, et arrêtez-vous lorsque la barre atteint la hauteur du menton.", "Gardez les poignets droits et les coudes légèrement en avant tout au long du mouvement."]', '["Maintenez votre core engagé et évitez de cambrer le dos de manière excessive lors de la poussée.", "Utilisez une prise complète sur la barre plutôt qu''une prise sans pouce pour un meilleur contrôle et sécurité.", "Abaissez la barre uniquement jusqu''au niveau des épaules pour protéger vos articulations des épaules d''une hyperextension.", "Commencez avec un poids léger pour maîtriser la forme avant de progresser vers des charges plus lourdes.", "Expirez pendant la phase de poussage et inspirez lors de la descente."]', '["Keep your core engaged and avoid arching your back excessively during the press", "Use a full grip on the barbell rather than a thumbless grip for better control and safety", "Lower the weight only to shoulder level to protect your shoulder joints from overextension", "Start with lighter weight to master the form before progressing to heavier loads", "Breathe out during the pressing phase and inhale while lowering the weight"]', 'ef55de8d-6d24-4983-99e0-0f50286c7a1e', 'seated-barbell-military-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('164f6a4c-7cf2-4906-a1b0-551d1cb24c6f', 'Eagle arms assis (gauche)', NULL, 'ذراع النسر جالسا (اليسار)', 'Seated eagle arms (left)', 'Shoulders', '[]', 'Shoulders', 'Beginner', 16, '/videos/shoulders/seated-eagle-arms-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-eagle-arms-left.jpg', NULL, '["Si les paumes ne se touchent pas, pressez le dos de vos mains l''un contre l''autre.", "Gardez les épaules détendues, loin de vos oreilles.", "Respirez profondément dans l''étirement entre vos omoplates."]', '["Ne pas croiser correctement les bras.", "Tendre les épaules vers le haut au lieu de les relâcher."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "bodyweight", "seated eagle arms (left)"]', true, '2026-04-03 12:24:58.817321+00', '2026-04-03 12:24:58.817321+00', 'Renforcez vos épaules tout en assouplissant votre dos avec cet exercice.', '["Ne pas croiser correctement les bras.", "Tendre les épaules vers le haut au lieu de les relâcher."]', true, '["Sit in a comfortable cross-legged position.", "Extend your arms forward and cross one arm under the other.", "Bend your elbows and try to bring your palms together.", "Lift your elbows to shoulder height and hold."]', '["Asseyez-vous confortablement en position de lotus.", "Étendez vos bras devant vous en croisant un bras sous l''autre.", "Pliez les coudes et essayez de faire toucher vos paumes.", "Levez les coudes à la hauteur des épaules et maintenez la position."]', '["Si les paumes ne se touchent pas, pressez le dos de vos mains l''un contre l''autre.", "Gardez les épaules détendues, loin de vos oreilles.", "Respirez profondément dans l''étirement entre vos omoplates."]', '["If palms do not touch, press the backs of your hands together.", "Keep your shoulders relaxed and away from your ears.", "Breathe into the stretch between your shoulder blades."]', 'ef8b7a4f-a209-425b-90dd-d20c402c5b0d', 'seated-eagle-arms-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('8a2dc431-df24-46de-ae41-c2dc909d3fd9', 'Presse à cuisse en position large', NULL, NULL, 'Leg Press Wide Stance', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/leg-press-wide-stance.mp4', NULL, NULL, NULL, '/videos/thumbnails/leg-press-wide-stance.jpg', NULL, '["Assure-toi que tes genoux restent alignés avec tes orteils pour éviter qu''ils ne s''effondrent vers l''intérieur.", "Maintiens une tension constante sur tes quadriceps sans verrouiller complètement tes genoux en haut.", "La position large cible la partie interne de tes quadriceps et sollicite davantage tes fessiers qu''une position étroite.", "Engage ton corps et assure que ton dos reste bien contre le dossier pour garder une bonne posture.", "Contrôle la descente pour maximiser l''engagement musculaire et éviter les blessures en lâchant le poids trop rapidement."]', '["Genoux qui s''effondrent vers l''intérieur.", "Verrouillage des genoux en haut du mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "leg press wide stance"]', true, '2026-04-03 12:24:57.572265+00', '2026-04-03 12:24:57.572265+00', 'Mets-toi sur la machine de presse à cuisse, avec les pieds plus larges que les épaules, les genoux fléchis. Pousse la plateforme en étendant complètement les jambes, puis redescends lentement à la position de départ.', '["Genoux qui s''effondrent vers l''intérieur.", "Verrouillage des genoux en haut du mouvement."]', true, '["Position yourself in the leg press machine with your back completely flat against the backrest", "Place your feet on the platform wider than shoulder-width apart with toes pointing slightly outward", "Release the safety handles and slowly lower the weight by bending your knees toward your chest", "Stop when your knees reach approximately 90 degrees or when you feel a stretch in your glutes", "Press through your heels to push the weight back up to the starting position", "Maintain control throughout the entire range of motion and avoid locking your knees at the top"]', '["Installe-toi sur la machine, le dos bien plaqué contre le dossier.", "Positionne tes pieds sur la plateforme, écartés au-delà des épaules, les orteils légèrement tournés vers l''extérieur.", "Lâche les poignées de sécurité et abaisse le poids en fléchissant les genoux vers ta poitrine.", "Arrête-toi lorsque tes genoux atteignent environ 90 degrés ou quand tu sens un étirement dans tes fessiers.", "Pousse sur tes talons pour ramener le poids à la position de départ.", "Garde le contrôle tout au long du mouvement et évite de bloquer tes genoux en haut."]', '["Assure-toi que tes genoux restent alignés avec tes orteils pour éviter qu''ils ne s''effondrent vers l''intérieur.", "Maintiens une tension constante sur tes quadriceps sans verrouiller complètement tes genoux en haut.", "La position large cible la partie interne de tes quadriceps et sollicite davantage tes fessiers qu''une position étroite.", "Engage ton corps et assure que ton dos reste bien contre le dossier pour garder une bonne posture.", "Contrôle la descente pour maximiser l''engagement musculaire et éviter les blessures en lâchant le poids trop rapidement."]', '["Keep your knees aligned with your toes throughout the movement to prevent inward collapse", "Maintain constant tension on your quads by not fully locking out your knees at the top", "The wide stance targets the inner portion of your quadriceps and engages your glutes more than a narrow stance", "Keep your core engaged and back pressed firmly against the pad to maintain proper spinal alignment", "Control the descent to maximize muscle engagement and prevent injury from dropping the weight too quickly"]', '5894b913-11b8-47b6-8f0f-63b8ad0bd469', 'leg-press-wide-stance', NULL, NULL);
INSERT INTO public.exercises VALUES ('6e61709d-5cf0-4ac8-a072-d97767e12da7', 'Presse assise avec prise neutre', NULL, 'Presse Assis Beda', 'Seated Neutral Grip Cable Press', 'Chest', '[]', 'Chest', 'Intermediate', 4, '/videos/chest/seated-neutral-grip-cable-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-neutral-grip-cable-press.jpg', NULL, '["Garde les épaules tirées vers l''arrière et vers le bas tout au long du mouvement pour protéger les articulations", "Concentre-toi sur la contraction de tes muscles pectoraux au moment où les bras sont entièrement étendus", "Contrôle la phase excentrique pour maximiser l''engagement musculaire et prévenir les blessures", "Évite de pousser les poignées trop haut ou trop bas - maintiens un angle de presse horizontal", "Garde ton core engagé pour maintenir une bonne posture et prévenir une tension dans le bas du dos"]', '["Ne pas contrôler le mouvement", "Tenir une mauvaise posture pendant l''exécution"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "cable", "seated neutral grip cable press"]', true, '2026-04-03 12:24:58.914536+00', '2026-04-03 12:24:58.914536+00', 'Position de départ : Assieds-toi sur un banc avec les câbles réglés à hauteur de poitrine dans chaque main. Exécution : Pousse les câbles vers l''avant en effectuant un mouvement de presse jusqu''à ce que les bras soient complètement étendus, puis reviens lentement à la position de départ.', '["Ne pas contrôler le mouvement", "Tenir une mauvaise posture pendant l''exécution"]', true, '["Adjust the cable pulleys to chest height and attach neutral grip handles", "Sit with your back firmly against the pad, core engaged, and feet planted on the floor", "Grasp the handles with palms facing each other, starting with hands at chest level", "Press the handles forward in a smooth arc until arms are fully extended", "Slowly return to starting position, controlling the weight throughout the entire range of motion", "Maintain consistent tension on the cables and avoid letting the weight stack touch between repetitions"]', '["Régle les poulies à la hauteur de la poitrine et fixe des poignées à prise neutre", "Assieds-toi avec le dos bien plaqué contre le dossier, le core engagé et les pieds fermement ancrés au sol", "Saisis les poignées avec les paumes face à face, les mains à hauteur de poitrine", "Presse les poignées vers l''avant dans un arc fluide jusqu''à l''extension complète des bras", "Reviens lentement à la position de départ, en contrôlant le poids sur toute l''amplitude de mouvement", "Maintiens une tension constante sur les câbles et évite de laisser les poids toucher entre les répétitions"]', '["Garde les épaules tirées vers l''arrière et vers le bas tout au long du mouvement pour protéger les articulations", "Concentre-toi sur la contraction de tes muscles pectoraux au moment où les bras sont entièrement étendus", "Contrôle la phase excentrique pour maximiser l''engagement musculaire et prévenir les blessures", "Évite de pousser les poignées trop haut ou trop bas - maintiens un angle de presse horizontal", "Garde ton core engagé pour maintenir une bonne posture et prévenir une tension dans le bas du dos"]', '["Keep your shoulders pulled back and down throughout the movement to protect the shoulder joint", "Focus on squeezing your chest muscles at the peak contraction when arms are fully extended", "Control the eccentric portion of the movement to maximize muscle engagement and prevent injury", "Avoid pressing the handles too high or too low - maintain a horizontal pressing angle", "Keep your core engaged to maintain proper posture and prevent lower back strain"]', '16916d8d-2bce-459a-a87f-fa511936260c', 'seated-neutral-grip-cable-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('6bf04897-a18c-45e2-b30c-050552f47da5', 'Élévations des épaules assises', NULL, NULL, 'Seated shoulder push downs', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/seated-shoulder-push-downs.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-shoulder-push-downs.jpg', NULL, '["Garde tes épaules tirées vers le bas et en arrière pour éviter de te voûter pendant l''élévation.", "Maintiens une colonne vertébrale neutre tout au long du mouvement pour protéger ton bas du dos.", "Pousse fermement avec l''ensemble de ta paume, pas seulement tes doigts, pour répartir le poids de manière équilibrée.", "Si tu ne peux pas lever complètement tes hanches, concentre-toi sur la pression vers le bas et l''engagement des muscles sans nécessiter une élévation complète."]', '["Ne pas engager suffisamment le tronc pendant le mouvement.", "Laisser les épaules s''affaisser vers l''avant au lieu de les maintenir en retrait."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "seated shoulder push downs"]', true, '2026-04-03 12:24:58.923896+00', '2026-04-03 12:24:58.923896+00', 'Position de départ : Assieds-toi droit sur le sol ou sur un tapis, les jambes tendues devant toi, les mains placées à côté des hanches avec les doigts pointant vers l''avant. Exécution : Pousse fortement avec tes paumes pour lever tes hanches et ton corps du sol, engageant tes épaules, ton tronc et tes jambes pour maintenir une ligne droite de la tête aux talons.', '["Ne pas engager suffisamment le tronc pendant le mouvement.", "Laisser les épaules s''affaisser vers l''avant au lieu de les maintenir en retrait."]', true, '["Sit on the ground with legs straight and hands placed firmly beside your hips, fingers pointing forward", "Engage your core and press down through your palms while lifting your hips off the ground", "Keep your shoulders directly over your wrists and maintain straight arms throughout the movement", "Hold the elevated position for 2-3 seconds while keeping your body in a straight line", "Lower your hips back down to the starting position with control", "Repeat for the desired number of repetitions, focusing on smooth controlled movements"]', '["Assieds-toi au sol avec les jambes droites et les mains bien placées à côté de tes hanches, doigts pointés vers l''avant.", "Engage ton tronc et presse avec tes paumes tout en levant tes hanches du sol.", "Garde tes épaules directement au-dessus de tes poignets et maintiens les bras droits tout au long du mouvement.", "Tiens la position élevée pendant 2 à 3 secondes en gardant ton corps en ligne droite.", "Redescends lentement tes hanches à la position de départ en contrôlant le mouvement.", "Répète pour le nombre de séries souhaité en te concentrant sur des mouvements fluides et maîtrisés."]', '["Garde tes épaules tirées vers le bas et en arrière pour éviter de te voûter pendant l''élévation.", "Maintiens une colonne vertébrale neutre tout au long du mouvement pour protéger ton bas du dos.", "Pousse fermement avec l''ensemble de ta paume, pas seulement tes doigts, pour répartir le poids de manière équilibrée.", "Si tu ne peux pas lever complètement tes hanches, concentre-toi sur la pression vers le bas et l''engagement des muscles sans nécessiter une élévation complète."]', '["Keep your shoulders pulled down and back to avoid hunching forward during the lift", "Maintain a neutral spine throughout the movement to protect your lower back", "Press firmly through your entire palm, not just your fingertips, to distribute weight evenly", "If you cannot lift your hips completely off the ground, focus on pressing down and engaging the muscles without full elevation"]', '72748704-e649-4df7-9e6b-747dd4d225a2', 'seated-shoulder-push-downs', NULL, NULL);
INSERT INTO public.exercises VALUES ('8f407b61-50dd-46ae-b07a-7188adcf2b42', 'Flexion latérale (gauche)', NULL, 'انحناء جانبي (يسار)', 'Side bend (left)', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/side-bend-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-bend-left.jpg', NULL, '["Restez concentré sur le plan frontal - évitez de twister ou de faire pivoter votre torse.", "Gardez la colonne vertébrale neutre et évitez de vous pencher en avant ou en arrière lors de l''inclinaison.", "Privilégiez un mouvement contrôlé plutôt que d''essayer d''aller le plus bas possible.", "Maintenez votre tête en alignement neutre avec votre colonne tout au long de l''exercice.", "Respirez régulièrement et évitez de retenir votre souffle pendant le mouvement."]', '["Ne pas maintenir la posture droite et les épaules en arrière.", "Incliner le torse trop loin sans contrôle."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side bend (left)"]', true, '2026-04-03 12:24:58.989561+00', '2026-04-03 12:24:58.989561+00', 'Position de départ : Tenez-vous droit, les pieds écartés à la largeur des épaules, les bras le long du corps ou une main sur la hanche. Exécution : Penchez lentement le torse sur le côté gauche, glissez votre main gauche le long de votre jambe tout en gardant votre sangle abdominale engagée et revenez à la position de départ.', '["Ne pas maintenir la posture droite et les épaules en arrière.", "Incliner le torse trop loin sans contrôle."]', true, '["Stand with feet shoulder-width apart and maintain good posture with shoulders back", "Place your right hand on your hip or let it rest at your side for balance", "Engage your core muscles and keep your hips facing forward throughout the movement", "Slowly bend laterally to the left, sliding your left hand down the outside of your left leg", "Lower only as far as comfortable while maintaining control and proper form", "Return to the starting position by engaging your right obliques to pull your torso back upright"]', '["Tenez-vous avec les pieds écartés à la largeur des épaules en gardant une bonne posture, épaules en arrière.", "Placez votre main droite sur votre hanche ou laissez-la reposer à vos côtés pour l''équilibre.", "Engagez vos muscles abdominaux et gardez vos hanches face à l''avant tout au long du mouvement.", "Inclinez lentement votre corps vers la gauche, glissant votre main gauche le long de l''extérieur de votre jambe gauche.", "Descendez seulement jusqu''à ce que cela soit confortable tout en maintenant le contrôle et la bonne forme.", "Revenez à la position de départ en engageant vos obliques droits pour ramener votre torse à la verticale."]', '["Restez concentré sur le plan frontal - évitez de twister ou de faire pivoter votre torse.", "Gardez la colonne vertébrale neutre et évitez de vous pencher en avant ou en arrière lors de l''inclinaison.", "Privilégiez un mouvement contrôlé plutôt que d''essayer d''aller le plus bas possible.", "Maintenez votre tête en alignement neutre avec votre colonne tout au long de l''exercice.", "Respirez régulièrement et évitez de retenir votre souffle pendant le mouvement."]', '["Keep the movement strictly in the frontal plane - avoid twisting or rotating your torso", "Maintain a neutral spine and avoid collapsing forward or backward during the bend", "Focus on controlled movement rather than trying to reach as far down as possible", "Keep your head in neutral alignment with your spine throughout the exercise", "Breathe steadily and avoid holding your breath during the movement"]', 'f324d8f5-3c64-4a97-b4de-2fd60907e7d5', 'side-bend-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('8a21afca-14ca-4469-b2bf-105e91fb8032', 'Taps des Épaules', NULL, 'طرقات الكتفين', 'Shoulder taps', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/shoulder-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/shoulder-taps.jpg', NULL, '["Garde tes hanches à niveau et évite de faire pivoter ton torse ou de laisser tes hanches s''affaisser pendant le mouvement.", "Respire de manière régulière et évite de retenir ta respiration durant l''exercice.", "Commence avec des mouvements lents et contrôlés avant de passer à des tempos plus rapides.", "Élargis l''écartement de tes pieds si tu as besoin de plus de stabilité en apprenant le mouvement."]', '["Rotations excessives du torse pendant l''exercice.", "Hanches affaissées au lieu de rester bien alignées."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "shoulder taps"]', true, '2026-04-03 12:24:58.978084+00', '2026-04-03 12:24:58.978084+00', 'Position de départ : Commence en position de planche haute, les mains sous les épaules, bras tendus, et corps formant une ligne droite entre la tête et les talons. Exécution : Soulève une main pour taper l''épaule opposée, puis retourne en planche et répète avec l''autre main, en alternant les côtés tout en maintenant la stabilité du tronc.', '["Rotations excessives du torse pendant l''exercice.", "Hanches affaissées au lieu de rester bien alignées."]', true, '["Start in a high plank position with hands shoulder-width apart and feet hip-width apart for stability", "Engage your core muscles and maintain a straight line from head to heels throughout the movement", "Lift your right hand and gently tap your left shoulder, keeping your hips square and minimizing rotation", "Return your right hand to the starting position with control", "Repeat the movement with your left hand tapping your right shoulder", "Continue alternating sides for the desired number of repetitions or time duration"]', '["Partir en position de planche haute, mains écartées à la largeur des épaules et pieds à la largeur des hanches pour une meilleure stabilité.", "Active tes muscles abdominaux et garde une ligne droite entre la tête et les talons tout au long de l''exercice.", "Soulève ta main droite et tape doucement ton épaule gauche, en gardant les hanches carrées et en minimisant la rotation.", "Ramène ta main droite à la position de départ avec contrôle.", "Répète le mouvement avec ta main gauche pour taper ton épaule droite.", "Continue à alterner les côtés pour le nombre de répétitions ou la durée souhaitée."]', '["Garde tes hanches à niveau et évite de faire pivoter ton torse ou de laisser tes hanches s''affaisser pendant le mouvement.", "Respire de manière régulière et évite de retenir ta respiration durant l''exercice.", "Commence avec des mouvements lents et contrôlés avant de passer à des tempos plus rapides.", "Élargis l''écartement de tes pieds si tu as besoin de plus de stabilité en apprenant le mouvement."]', '["Keep your hips level and avoid rotating your torso or letting your hips sag during the movement", "Maintain steady breathing and avoid holding your breath while performing the exercise", "Start with slower, controlled movements before progressing to faster tempos", "Widen your foot stance if you need additional stability while learning the movement"]', 'c847178d-3b29-4a76-b8c6-da12de207bbf', 'shoulder-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('b593cbd7-098c-4ae7-9b4d-75ebbfd50079', 'Sauts de haies latéraux aux grimpeurs de montagne', NULL, 'القفزات الجانبية مع تسلق الجبال', 'Side hurdel jumps to mountain climbers', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-hurdel-jumps-to-mountain-climbers.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-hurdel-jumps-to-mountain-climbers.jpg', NULL, '["Garde tes hanches basses (ne te cambre pas)", "Maintiens ton core contracté", "Accélère pour un boost cardio", "Ralentis pour un meilleur contrôle", "Exercice complet pour tout le corps"]', '["Ne pas garder les hanches correctement alignées", "Oublier de contracter le core"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side hurdel jumps to mountain climbers"]', true, '2026-04-03 12:24:59.021242+00', '2026-04-03 12:24:59.021242+00', 'Un exercice dynamique qui engage ton cœur tout en favorisant la coordination et l''endurance !', '["Ne pas garder les hanches correctement alignées", "Oublier de contracter le core"]', true, '["Start in push-up position", "Drive one knee toward chest", "Quickly switch legs", "Continue alternating at pace"]', '["Commence en position de push-up", "Amène un genou vers ta poitrine", "Change rapidement de jambe", "Continue d''alterner à un bon rythme"]', '["Garde tes hanches basses (ne te cambre pas)", "Maintiens ton core contracté", "Accélère pour un boost cardio", "Ralentis pour un meilleur contrôle", "Exercice complet pour tout le corps"]', '["Keep hips down (don''t pike)", "Core stays engaged", "Speed up for more cardio", "Slow down for more control", "Full body exercise"]', '3798bfae-4ad3-404c-969d-0eeb2fcbdd56', 'side-hurdel-jumps-to-mountain-climbers', NULL, NULL);
INSERT INTO public.exercises VALUES ('aa765355-d4ac-493d-9ff6-d758ee32fa43', 'Pulsations en planche latérale (côté droit)', NULL, NULL, 'Side plank pulses (Right side)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-plank-pulses-right-side.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-plank-pulses-right-side.jpg', NULL, '["Contracte bien les fessiers", "Garde le cou dans le prolongement de ta colonne", "Respire normalement", "Ne soulève pas les hanches trop haut", "Augmente la durée progressivement"]', '["Laisser les hanches s''affaisser", "Ne pas garder le corps aligné", "Oublier de respirer correctement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side plank pulses (right side)"]', true, '2026-04-03 12:24:59.089013+00', '2026-04-03 12:24:59.089013+00', 'Renforce ton tronc et améliore ta stabilité avec cet exercice dynamique !', '["Laisser les hanches s''affaisser", "Ne pas garder le corps aligné", "Oublier de respirer correctement"]', true, '["Forearms on floor, elbows under shoulders", "Body straight from head to heels", "Hold position", "Keep core tight, don''t let hips sag"]', '["Place tes avant-bras au sol, les coudes sous les épaules", "Maintiens ton corps droit de la tête aux talons", "Reste en position", "Contracte ton tronc pour éviter que les hanches ne s''affalent"]', '["Contracte bien les fessiers", "Garde le cou dans le prolongement de ta colonne", "Respire normalement", "Ne soulève pas les hanches trop haut", "Augmente la durée progressivement"]', '["Squeeze glutes", "Keep neck neutral", "Breathe normally", "Don''t raise hips too high", "Build time gradually"]', '71213402-bffc-41ab-9425-736789fca561', 'side-plank-pulses-right-side', NULL, NULL);
INSERT INTO public.exercises VALUES ('ddb2d6db-3854-4bb2-9bd9-3282b89f94dd', 'Extension des triceps avec haltère à un bras', NULL, NULL, 'Single Arm Lying Dumbbell Extension', 'Triceps', '[]', 'Triceps', 'Intermediate', 2, '/videos/triceps/single-arm-lying-dumbbell-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-lying-dumbbell-extension.jpg', NULL, '["Garde ton bras supérieur perpendiculaire au sol pendant tout le mouvement", "Utilise ta main de soutien pour stabiliser le bras qui travaille et empêcher tout mouvement de l''épaule", "Contrôle le poids lors des phases de descente et de montée pour maximiser l''activation musculaire", "Commence avec un poids plus léger que ce que tu utiliserais pour des variations à deux bras, car le travail à un bras nécessite plus de stabilité", "Stoppe le mouvement si tu ressens une douleur ou une instabilité au niveau de l''épaule"]', '["Utiliser un poids trop lourd", "Ne pas contrôler le mouvement en descente", "Laisser le bras supérieur bouger pendant l''exercice", "Ne pas maintenir une position stable sur le banc"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "dumbbell", "single arm lying dumbbell extension"]', true, '2026-04-03 12:24:59.204518+00', '2026-04-03 12:24:59.204518+00', 'Allonge-toi sur un banc plat, un haltère dans une main, le bras tendu vers le plafond. Ensuite, fléchis le coude pour abaisser l’haltère vers ton épaule, puis redresse ton bras pour revenir à la position de départ. Répète avec l’autre bras.', '["Utiliser un poids trop lourd", "Ne pas contrôler le mouvement en descente", "Laisser le bras supérieur bouger pendant l''exercice", "Ne pas maintenir une position stable sur le banc"]', true, '["Lie flat on a bench with feet planted firmly on the floor and core engaged", "Hold the dumbbell with one hand and extend that arm straight up above your shoulder", "Place your opposite hand on your working arm''s elbow to provide support and stability", "Slowly lower the weight behind your head by bending only at the elbow joint while keeping your upper arm stationary", "Lower until you feel a stretch in your tricep, then press the weight back to the starting position", "Complete all reps on one arm before switching to the other side"]', '["Allonge-toi à plat sur le banc, les pieds bien ancrés au sol et le cœur engagé", "Prends l''haltère dans une main et tends ce bras droit au-dessus de ton épaule", "Pose ta main libre sur le coude de ton bras travailleur pour apporter soutien et stabilité", "Abaisse lentement le poids derrière ta tête en fléchissant uniquement au niveau du coude, tout en maintenant ton bras supérieur immobile", "Descends jusqu''à sentir un étirement dans ton triceps, puis repousse le poids jusqu''à la position de départ", "Termine toutes les répétitions d''un bras avant de passer à l''autre côté"]', '["Garde ton bras supérieur perpendiculaire au sol pendant tout le mouvement", "Utilise ta main de soutien pour stabiliser le bras qui travaille et empêcher tout mouvement de l''épaule", "Contrôle le poids lors des phases de descente et de montée pour maximiser l''activation musculaire", "Commence avec un poids plus léger que ce que tu utiliserais pour des variations à deux bras, car le travail à un bras nécessite plus de stabilité", "Stoppe le mouvement si tu ressens une douleur ou une instabilité au niveau de l''épaule"]', '["Keep your upper arm perpendicular to the floor throughout the entire movement", "Use your supporting hand to stabilize the working arm and prevent shoulder movement", "Control the weight during both the lowering and lifting phases to maximize muscle activation", "Start with lighter weight than you would use for two-arm variations since single arm work requires more stability", "Stop the range of motion if you feel any shoulder discomfort or instability"]', 'fee193c5-ec61-4e7f-aca8-a0ab268f6e26', 'single-arm-lying-dumbbell-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('fc8188b5-3905-4669-a046-831de114ec10', 'Tirage Unilatéral à la Machine Smith', NULL, 'سحب وحيد بآلة سميث', 'Single Arm Smith Machine Row', 'Back', '[]', 'Back', 'Intermediate', 8, '/videos/back/single-arm-smith-machine-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-smith-machine-row.jpg', NULL, '["Garde le dos droit et le centre engagé pendant tout le mouvement", "Concentre-toi sur le tirage avec les muscles du dos plutôt qu''uniquement avec le bras", "Évite de faire tourner ton torse - reste bien aligné", "Contrôle le poids à la montée comme à la descente", "Commence avec un poids léger pour maîtriser la forme avant de progresser"]', '["Ne pas garder le dos droit et les épaules alignées", "Tirer trop avec les bras au lieu du dos", "Rotations du torse qui nuisent à l''efficacité du mouvement", "Ne pas contrôler le mouvement lors de la descente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "single arm smith machine row"]', true, '2026-04-03 12:24:59.225518+00', '2026-04-03 12:24:59.225518+00', 'Position de départ : Place-toi devant la machine Smith, une main agrippant la barre, l''autre reposant sur ta cuisse ou un banc. Exécution : Tire la barre vers le côté de ta poitrine, en gardant le torse bien aligné, puis redescends lentement à la position de départ.', '["Ne pas garder le dos droit et les épaules alignées", "Tirer trop avec les bras au lieu du dos", "Rotations du torse qui nuisent à l''efficacité du mouvement", "Ne pas contrôler le mouvement lors de la descente"]', true, '["Set the Smith machine bar to about waist height and position a bench perpendicular to the bar", "Place your inside knee and hand on the bench for support, with your outside foot planted firmly on the ground", "Grip the bar with your outside hand using an overhand grip, allowing your arm to fully extend", "Pull the bar up toward your lower ribcage by driving your elbow back and squeezing your shoulder blade toward your spine", "Pause briefly at the top, then slowly lower the bar back to the starting position with control", "Complete all reps on one side before switching to the other arm"]', '["Règle la barre de la machine Smith à hauteur de taille et positionne un banc perpendiculairement à la barre", "Place ton genou et ta main intérieure sur le banc pour le soutien, avec ton pied extérieur bien ancré au sol", "Saisis la barre avec ta main extérieure en prise pronation, en laissant ton bras complètement s''étendre", "Tire la barre vers ton bas de la cage thoracique en poussant ton coude en arrière et en pressant ton scapula vers ta colonne vertébrale", "Marque une pause en haut, puis redescends lentement la barre à la position de départ en contrôlant le mouvement", "Effectue toutes les répétitions d''un côté avant de passer à l''autre bras"]', '["Garde le dos droit et le centre engagé pendant tout le mouvement", "Concentre-toi sur le tirage avec les muscles du dos plutôt qu''uniquement avec le bras", "Évite de faire tourner ton torse - reste bien aligné", "Contrôle le poids à la montée comme à la descente", "Commence avec un poids léger pour maîtriser la forme avant de progresser"]', '["Keep your back straight and core engaged throughout the movement", "Focus on pulling with your back muscles rather than just your arm", "Avoid rotating your torso - keep your shoulders square", "Control the weight on both the lifting and lowering phases", "Start with lighter weight to master the form before progressing"]', '0b51bca9-c72f-4fc3-affd-0904de3cf8b4', 'single-arm-smith-machine-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('16749e65-3888-4c43-af4e-8f98b4976264', 'Rotation T-Spine avec Slingshot', NULL, NULL, 'Slingshot into T-Spine rotation', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/slingshot-into-t-spine-rotation.mp4', NULL, NULL, NULL, '/videos/thumbnails/slingshot-into-t-spine-rotation.jpg', NULL, '["Maintenez une position de planche latérale solide pour protéger votre colonne vertébrale", "Effectuez le mouvement lentement et de manière contrôlée pour maximiser la mobilité de la colonne thoracique", "Gardez votre épaule soutenue stable et évitez de vous affaisser sur votre bras d''appui", "Concentrez-vous sur la rotation de votre partie supérieure du dos plutôt que sur le simple mouvement de votre bras", "Respirez profondément pendant le mouvement pour améliorer l''étirement et les gains de mobilité"]', '["Se laisser tomber sur l''épaule d''appui", "Ne pas engager le tronc suffisamment pour maintenir la stabilité"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "slingshot into t-spine rotation"]', true, '2026-04-03 12:24:59.243817+00', '2026-04-03 12:24:59.243817+00', 'Position de départ : Adoptez une position de planche latérale, une main au sol, le corps bien aligné, l''autre bras tendu vers le plafond. Exécution : Faites tourner le bras étendu vers le bas et passez-le sous votre épaule soutenue, puis revenez à la position de départ avec le bras tendu au-dessus.', '["Se laisser tomber sur l''épaule d''appui", "Ne pas engager le tronc suffisamment pour maintenir la stabilité"]', true, '["Start in a side plank position with your supporting hand planted firmly on the ground", "Extend your top arm straight up toward the ceiling", "Slowly rotate your extended arm down and thread it under your supporting side", "Keep your hips elevated and core engaged throughout the movement", "Return your arm back to the starting position overhead", "Repeat for the desired number of repetitions before switching sides"]', '["Commencez en position de planche latérale avec votre main d''appui bien ancrée au sol", "Tendez votre bras du dessus droit vers le plafond", "Faites tourner lentement votre bras étendu vers le bas et passez-le sous votre côté soutenu", "Gardez vos hanches élevées et votre sangle abdominale sollicitée durant tout le mouvement", "Ramenez votre bras à la position de départ au-dessus de votre tête", "Répétez pour le nombre de répétitions souhaité avant de changer de côté"]', '["Maintenez une position de planche latérale solide pour protéger votre colonne vertébrale", "Effectuez le mouvement lentement et de manière contrôlée pour maximiser la mobilité de la colonne thoracique", "Gardez votre épaule soutenue stable et évitez de vous affaisser sur votre bras d''appui", "Concentrez-vous sur la rotation de votre partie supérieure du dos plutôt que sur le simple mouvement de votre bras", "Respirez profondément pendant le mouvement pour améliorer l''étirement et les gains de mobilité"]', '["Maintain a strong side plank position throughout the entire movement to protect your spine", "Move slowly and controlled to maximize the thoracic spine mobility benefits", "Keep your supporting shoulder stable and avoid collapsing onto your supporting arm", "Focus on rotating through your upper back rather than just moving your arm", "Breathe deeply during the movement to enhance the stretch and mobility gains"]', '1c9646ea-e5d6-4aaf-8892-12b331fcc8d2', 'slingshot-into-t-spine-rotation', NULL, NULL);
INSERT INTO public.exercises VALUES ('e816aed1-baac-45d6-b95e-0e59650d5ec7', 'Good Morning à la Smith Machine', NULL, 'صباح الخير بجهاز سميث', 'Smith Machine Good Morning', 'Hamstrings', '[]', 'Hamstrings', 'Intermediate', 8, '/videos/hamstrings/smith-machine-good-morning.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-good-morning.jpg', NULL, '["Garde ton gainage actif tout au long du mouvement pour protéger ton bas du dos", "Concentre-toi sur le mouvement des hanches plutôt que sur une flexion des genoux excessive - ces derniers doivent seulement se plier légèrement", "Maintiens une colonne vertébrale neutre en gardant ta poitrine levée et tes épaules en arrière", "Contrôle la descente et évite de rebondir en bas du mouvement", "Commence avec un poids léger pour maîtriser le geste avant de progresser vers des charges plus lourdes"]', '["Ne pas maintenir le dos droit pendant l''exercice", "Ne pas engager les abdominaux, ce qui peut nuire à la posture"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "machine", "smith machine good morning"]', true, '2026-04-03 12:24:59.305742+00', '2026-04-03 12:24:59.305742+00', 'Position de départ : Place-toi sous la Smith machine avec la barre reposant sur le haut de ton dos et les pieds écartés à la largeur des épaules. Exécution : Incline-toi en avant au niveau des hanches en gardant ton dos droit et les jambes légèrement fléchies, puis retourne lentement à la position de départ.', '["Ne pas maintenir le dos droit pendant l''exercice", "Ne pas engager les abdominaux, ce qui peut nuire à la posture"]', true, '["Set the Smith machine bar at shoulder height and add appropriate weight plates", "Position yourself under the bar with it resting on your upper traps, not your neck", "Unlock the bar and step back slightly, placing feet shoulder-width apart with a slight knee bend", "Initiate the movement by pushing your hips back and lowering your torso while keeping your back straight", "Lower until you feel a good stretch in your hamstrings, typically when your torso is parallel to the floor", "Drive your hips forward to return to the starting position and re-engage the safety locks when finished"]', '["Règle la barre de la Smith machine à hauteur d''épaules et ajoute des poids adaptés", "Positionne-toi sous la barre avec celle-ci reposant sur tes trapèzes, pas sur ton cou", "Déverrouille la barre et recule légèrement, les pieds écartés à la largeur des épaules avec un léger plier des genoux", "Initie le mouvement en repoussant tes hanches en arrière et en abaissant ton torse tout en gardant le dos droit", "Abaisse-toi jusqu''à sentir un bon étirement dans tes ischio-jambiers, généralement quand ton torse est parallèle au sol", "Pousse tes hanches vers l''avant pour revenir à la position de départ et réengage les verrous de sécurité une fois terminé"]', '["Garde ton gainage actif tout au long du mouvement pour protéger ton bas du dos", "Concentre-toi sur le mouvement des hanches plutôt que sur une flexion des genoux excessive - ces derniers doivent seulement se plier légèrement", "Maintiens une colonne vertébrale neutre en gardant ta poitrine levée et tes épaules en arrière", "Contrôle la descente et évite de rebondir en bas du mouvement", "Commence avec un poids léger pour maîtriser le geste avant de progresser vers des charges plus lourdes"]', '["Keep your core engaged throughout the entire movement to protect your lower back", "Focus on the hip hinge movement rather than squatting down - the knees should only bend slightly", "Maintain a neutral spine by keeping your chest up and shoulders pulled back", "Control the descent and avoid bouncing at the bottom of the movement", "Start with lighter weight to master the movement pattern before progressing to heavier loads"]', '2291338b-1445-4b35-8ebe-d92d7af522e0', 'smith-machine-good-morning', NULL, NULL);
INSERT INTO public.exercises VALUES ('5a511ae9-5658-4f7b-b54d-6ccc202d37e2', 'Développé couché à la haltère pour triceps', NULL, NULL, 'Lying Dumbbell Skull Crusher', 'Triceps', '[]', 'Triceps', 'Intermediate', 2, '/videos/triceps/lying-dumbbell-skull-crusher.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-dumbbell-skull-crusher.jpg', NULL, '["Garde tes bras supérieurs complètement fixes et perpendiculaires au sol - seuls les avant-bras doivent bouger", "Abaisse le poids lentement et avec contrôle pour éviter de te blesser au visage", "Assure-toi d''avoir une prise sécurisée avec les deux mains à la même extrémité de l''haltère pour éviter qu''il ne glisse", "Maintiens ton ventre engagé et évite de cambrer excessivement le dos pendant le mouvement", "Commence avec un poids léger pour maîtriser la forme avant de passer à des charges plus lourdes."]', '["Ne pas stabiliser les bras supérieurs pendant l''exercice", "Trop de charge qui entraîne un manque de contrôle et de mauvaise forme"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "dumbbell", "lying dumbbell skull crusher"]', true, '2026-04-03 12:24:57.687231+00', '2026-04-03 12:24:57.687231+00', 'Position de départ : Allonge-toi sur un banc plat avec une haltère dans chaque main, bras tendus vers le haut, paumes face à face. Exécution : Abaisse les haltères vers ton front en fléchissant les coudes, puis tends les bras pour revenir à la position de départ.', '["Ne pas stabiliser les bras supérieurs pendant l''exercice", "Trop de charge qui entraîne un manque de contrôle et de mauvaise forme"]', true, '["Lie flat on a bench with feet planted firmly on the floor and maintain a neutral spine throughout the movement", "Grip both dumbbells.", "Start with arms fully extended directly over your chest, keeping your upper arms stationary throughout the exercise", "Lower the dumbbell slowly by bending only at the elbows until the weight nearly touches your forehead", "Press the dumbbell back up to the starting position by extending your elbows while keeping your upper arms vertical", "Control the weight on both the lowering and lifting phases to maintain proper form"]', '["Allonge-toi sur un banc avec les pieds bien ancrés au sol et maintiens une colonne vertébrale neutre pendant tout le mouvement", "Prends les deux haltères en main.", "Commence avec les bras complètement tendus au-dessus de ta poitrine, en maintenant tes bras supérieurs fixes durant l''exercice", "Abaisse lentement les haltères en fléchissant uniquement les coudes jusqu''à ce que le poids frôle ton front", "Pousse les haltères vers le haut pour revenir à la position de départ en tendant les coudes tout en gardant les bras supérieurs verticaux", "Contrôle le poids lors des phases de descente et de montée pour maintenir une bonne forme."]', '["Garde tes bras supérieurs complètement fixes et perpendiculaires au sol - seuls les avant-bras doivent bouger", "Abaisse le poids lentement et avec contrôle pour éviter de te blesser au visage", "Assure-toi d''avoir une prise sécurisée avec les deux mains à la même extrémité de l''haltère pour éviter qu''il ne glisse", "Maintiens ton ventre engagé et évite de cambrer excessivement le dos pendant le mouvement", "Commence avec un poids léger pour maîtriser la forme avant de passer à des charges plus lourdes."]', '["Keep your upper arms completely stationary and perpendicular to the floor - only your forearms should move", "Lower the weight slowly and under control to avoid hitting yourself in the face", "Use a secure grip with both hands on the same end of the dumbbell to prevent it from slipping", "Keep your core engaged and avoid arching your back excessively during the movement", "Start with lighter weight to master the form before progressing to heavier loads"]', 'cfa05b32-b753-4e84-a73f-1c2a92606930', 'lying-dumbbell-skull-crusher', NULL, NULL);
INSERT INTO public.exercises VALUES ('f3fb2101-6f6e-4102-bac7-1d1119e6b51a', 'Squat Sumo avec Machine Smith', NULL, 'Smith Machine Sumo Squat', 'Smith Machine Sumo Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 8, '/videos/quadriceps/smith-machine-sumo-squat-e656576b.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-sumo-squat-e656576b.jpg', NULL, '["Garde les genoux alignés avec les orteils pendant tout le mouvement pour éviter le valgus du genou", "Maintiens une posture droite avec la poitrine levée et les épaules en arrière pour protéger le bas du dos", "Concentre-toi sur la poussée avec les talons plutôt qu''avec les orteils pour maximiser l''activation des quadriceps et des fessiers", "Contrôle la descente et évite de rebondir au fond du mouvement", "Engage ton tronc tout au long du mouvement pour assurer la stabilité de la colonne vertébrale"]', '["Ne pas garder les genoux alignés avec les orteils", "Baisser le torse trop en avant pendant le squat"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "smith machine sumo squat"]', true, '2026-04-03 12:24:59.370441+00', '2026-04-03 12:24:59.370441+00', 'Positionne-toi sous la machine Smith, la barre reposant sur ta partie supérieure du dos, pieds écartés plus que la largeur des épaules, orteils légèrement tournés vers l''extérieur. Descends en squat profond en maintenant le dos droit, puis pousse pour revenir à la position de départ.', '["Ne pas garder les genoux alignés avec les orteils", "Baisser le torse trop en avant pendant le squat"]', true, '["Adjust the Smith machine bar to upper chest height and add appropriate weight plates", "Position yourself under the bar with feet in a wide sumo stance, toes turned out 45 degrees", "Unrack the bar by lifting and rotating the safety hooks, keeping your core engaged", "Lower your body by sitting back into your hips while keeping knees tracking over toes", "Descend until your thighs are parallel to the floor or as low as mobility allows", "Drive through your heels and push the floor away to return to starting position"]', '["Ajuste la barre de la machine Smith à hauteur de poitrine et ajoute des poids appropriés", "Positionne-toi sous la barre avec les pieds en stance large de sumo, orteils tournés à 45 degrés", "Dégage la barre en soulevant et en tournant les crochets de sécurité, en gardant le ventre engagé", "Descends ton corps en poussant les hanches en arrière tout en gardant les genoux alignés avec les orteils", "Descends jusqu’à ce que tes cuisses soient parallèles au sol ou aussi bas que ta mobilité le permet", "Pousse avec les talons pour repousser le sol et revenir à la position de départ"]', '["Garde les genoux alignés avec les orteils pendant tout le mouvement pour éviter le valgus du genou", "Maintiens une posture droite avec la poitrine levée et les épaules en arrière pour protéger le bas du dos", "Concentre-toi sur la poussée avec les talons plutôt qu''avec les orteils pour maximiser l''activation des quadriceps et des fessiers", "Contrôle la descente et évite de rebondir au fond du mouvement", "Engage ton tronc tout au long du mouvement pour assurer la stabilité de la colonne vertébrale"]', '["Keep your knees aligned with your toes throughout the movement to prevent knee valgus", "Maintain an upright torso with chest up and shoulders back to protect your lower back", "Focus on pushing through your heels rather than your toes to maximize quad and glute activation", "Control the descent and avoid bouncing at the bottom of the movement", "Engage your core throughout the entire range of motion for spinal stability"]', 'e656576b-39d4-4623-a93d-c455bd640b01', 'smith-machine-sumo-squat-e656576b', NULL, NULL);
INSERT INTO public.exercises VALUES ('18e31257-29c9-403f-9db1-3e00d146abf2', 'Développé Épaules Machine Smith', NULL, 'تطوير الأكتاف على آلة سميث', 'Smith Machine Shoulder Press', 'Shoulders', '[]', 'Shoulders', 'Beginner', 8, '/videos/shoulders/smith-machine-shoulder-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-shoulder-press.jpg', NULL, '["Garde tes poignets droits et alignés avec tes avant-bras pour éviter les blessures", "Évite de presser la barre derrière ta nuque, cela peut mettre en tension l''articulation de l''épaule", "Maintiens une légère inclinaison vers l''avant du torse pour suivre le chemin naturel de la barre sur la machine Smith", "Expire pendant la poussée et inspire en abaissant le poids", "Arrête la descente quand la barre atteint le niveau des oreilles ou lorsque tu ressens un étirement confortable dans les épaules"]', '["Ne pas ajuster la hauteur du banc, ce qui peut causer des déséquilibres", "Ne pas contrôler la descente, entraînant un mouvement brusque et dangereux"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "smith machine shoulder press"]', true, '2026-04-03 12:24:59.34322+00', '2026-04-03 12:24:59.34322+00', 'Position de départ : Assieds-toi sur la machine Smith avec la barre en haut. Exécution : Descends la barre jusqu''à tes épaules, puis pousse vers le haut pour revenir à la position de départ.', '["Ne pas ajuster la hauteur du banc, ce qui peut causer des déséquilibres", "Ne pas contrôler la descente, entraînant un mouvement brusque et dangereux"]', true, '["Adjust the bench so the bar aligns with your shoulders when seated", "Set the safety stops just below shoulder level as a precaution", "Grip the bar with palms facing forward, hands slightly wider than shoulders", "Keep your core engaged and back pressed firmly against the pad throughout the movement", "Press the bar straight up in a controlled motion until arms are fully extended", "Lower the bar slowly back to shoulder level, maintaining control throughout the descent"]', '["Ajuste le banc pour que la barre soit alignée avec tes épaules lorsque tu es assis", "Place les tampons de sécurité juste en dessous du niveau des épaules par précaution", "Saisis la barre avec les paumes vers l''avant, les mains légèrement plus larges que les épaules", "Garde le ventre engagé et le dos bien en contact avec le dossier tout au long du mouvement", "Presse la barre verticalement de manière contrôlée jusqu''à ce que tes bras soient complètement tendus", "Abaisse la barre lentement jusqu''au niveau des épaules, en gardant le contrôle durant la descente"]', '["Garde tes poignets droits et alignés avec tes avant-bras pour éviter les blessures", "Évite de presser la barre derrière ta nuque, cela peut mettre en tension l''articulation de l''épaule", "Maintiens une légère inclinaison vers l''avant du torse pour suivre le chemin naturel de la barre sur la machine Smith", "Expire pendant la poussée et inspire en abaissant le poids", "Arrête la descente quand la barre atteint le niveau des oreilles ou lorsque tu ressens un étirement confortable dans les épaules"]', '["Keep your wrists straight and aligned with your forearms to prevent injury", "Avoid pressing the bar behind your neck as this can strain the shoulder joint", "Maintain a slight forward lean of the torso to follow the natural bar path of the Smith machine", "Breathe out during the pressing motion and breathe in while lowering the weight", "Stop the descent when the bar reaches ear level or when you feel a comfortable stretch in the shoulders"]', '691ad2e7-b9f9-4921-8831-4da317451a2c', 'smith-machine-shoulder-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('d3dbeb60-fe32-4a84-93ad-c52c80fd8610', 'Pompes Spiderman', NULL, 'Pompes Spiderman', 'Spiderman push up', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/spiderman-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/spiderman-push-up.jpg', NULL, '["Contracte bien ton ventre durant tout le mouvement pour éviter que tes hanches ne s''affaissent ou ne tournent trop", "Garde ta jambe de soutien droite et forte pendant que l''autre jambe effectue le mouvement de genou", "Concentre-toi sur des mouvements contrôlés plutôt que sur la rapidité pour maximiser l''engagement musculaire et maintenir une bonne forme", "Assure-toi que ton genou se dirige vers l''extérieur de ton coude et non pas à travers ton corps", "Si le mouvement complet est trop difficile, modifie en réalisant d''abord la pompe et ensuite en ajoutant le mouvement de jambe séparément"]', '["Laisser les hanches s''affaisser pendant l''exercice", "Ne pas contrôler le mouvement et aller trop vite"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "spiderman push up"]', true, '2026-04-03 12:24:59.415385+00', '2026-04-03 12:24:59.415385+00', 'Position de départ : Commence dans une position de pompe standard, avec les mains placées à la largeur des épaules et le corps bien aligné de la tête aux talons. Exécution : Descends en pompe en amenant simultanément un genou vers le coude du même côté, puis pousse sur tes mains pour revenir à la position de départ avant de changer de côté.', '["Laisser les hanches s''affaisser pendant l''exercice", "Ne pas contrôler le mouvement et aller trop vite"]', true, '["Start in a plank position with hands directly under shoulders and core engaged", "Lower your chest toward the ground while bringing your right knee toward your right elbow", "Keep your hips level and avoid rotating your torso as you bring the knee forward", "Push through your palms to return to the starting position while extending your leg back", "Repeat the movement on the opposite side, bringing your left knee to your left elbow", "Continue alternating sides for the desired number of repetitions"]', '["Commence en position de planche, mains directement sous les épaules et le ventre bien contracté", "Descends ta poitrine vers le sol tout en amenant ton genou droit vers ton coude droit", "Garde les hanches nivelées et évite de faire pivoter ton torse en amenant le genou vers l''avant", "Pousse avec tes paumes pour revenir à la position de départ tout en étendant ta jambe vers l''arrière", "Répète le mouvement de l''autre côté, en amenant ton genou gauche vers ton coude gauche", "Continue à alterner les côtés pour le nombre de répétitions souhaité"]', '["Contracte bien ton ventre durant tout le mouvement pour éviter que tes hanches ne s''affaissent ou ne tournent trop", "Garde ta jambe de soutien droite et forte pendant que l''autre jambe effectue le mouvement de genou", "Concentre-toi sur des mouvements contrôlés plutôt que sur la rapidité pour maximiser l''engagement musculaire et maintenir une bonne forme", "Assure-toi que ton genou se dirige vers l''extérieur de ton coude et non pas à travers ton corps", "Si le mouvement complet est trop difficile, modifie en réalisant d''abord la pompe et ensuite en ajoutant le mouvement de jambe séparément"]', '["Maintain a tight core throughout the entire movement to prevent hip sagging or excessive rotation", "Keep your supporting leg straight and strong while the other leg performs the knee drive", "Focus on controlled movement rather than speed to maximize muscle engagement and maintain proper form", "Ensure your knee tracks toward the outside of your elbow rather than across your body", "If the full movement is too challenging, modify by performing the push-up and leg movement separately"]', '2fc3cb39-6cf3-4133-89fd-6b140c96110f', 'spiderman-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('a274253e-7375-47a1-886b-22d2603b5d21', 'Squats explosifs : de la position à la puissance', NULL, NULL, 'Squat taps into jump squats', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/squat-taps-into-jump-squats.mp4', NULL, NULL, NULL, '/videos/thumbnails/squat-taps-into-jump-squats.jpg', NULL, '["Atterris en douceur (atterrissages silencieux)", "Absorbe l''impact avec tes jambes", "Ne verrouille pas tes genoux à l''atterrissage", "La puissance vient de tes jambes et de tes hanches", "Idéal pour développer ta puissance explosive"]', '["Atterrir trop brusquement", "Ne pas fléchir les genoux à l''atterrissage", "Sauter trop haut sans contrôle", "Oublier de maintenir le dos droit pendant l''exercice", "Ne pas activer les abdominaux lors du saut"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "squat taps into jump squats"]', true, '2026-04-03 12:24:59.439488+00', '2026-04-03 12:24:59.439488+00', 'Renforce tes cuisses et développe ton explosivité avec cet exercice dynamique de squat avec saut !', '["Atterrir trop brusquement", "Ne pas fléchir les genoux à l''atterrissage", "Sauter trop haut sans contrôle", "Oublier de maintenir le dos droit pendant l''exercice", "Ne pas activer les abdominaux lors du saut"]', true, '["Start in squat position", "Explode up, jumping off floor", "Land softly with bent knees", "Immediately descend into next squat"]', '["Commence en position de squat", "Explose vers le haut en sautant", "Atterris doucement avec les genoux fléchis", "Descends immédiatement dans le prochain squat"]', '["Atterris en douceur (atterrissages silencieux)", "Absorbe l''impact avec tes jambes", "Ne verrouille pas tes genoux à l''atterrissage", "La puissance vient de tes jambes et de tes hanches", "Idéal pour développer ta puissance explosive"]', '["Land softly (quiet landings)", "Absorb impact with legs", "Don''t lock knees on landing", "Power comes from legs and hips", "Great for explosive power"]', '2cb2c89f-5ea0-49f4-8ee3-a24beb2fa192', 'squat-taps-into-jump-squats', NULL, NULL);
INSERT INTO public.exercises VALUES ('8f8a533e-8782-40e3-9ff9-95033bb2496c', 'Squat avec tapotement de pieds alternés', NULL, NULL, 'Squat to alternating toe taps', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/squat-to-alternating-toe-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/squat-to-alternating-toe-taps.jpg', NULL, '["Conservez votre poids sur la jambe de soutien lors des tapotements, sans transférer tout le poids sur le pied qui tapote.", "Maintenez une bonne forme de squat, en veillant à ce que les genoux restent alignés avec les orteils et la poitrine lever tout au long du mouvement.", "Contrôlez le rythme et évitez de précipiter les tapotements pour maintenir votre équilibre.", "Gardez votre gainage engagé durant toute la séquence pour stabiliser votre torse."]', '["Ne pas garder les genoux alignés avec les orteils pendant le squat.", "Transférer trop de poids sur le pied qui tapote."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "squat to alternating toe taps"]', true, '2026-04-03 12:24:59.457259+00', '2026-04-03 12:24:59.457259+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des épaules, les bras le long du corps ou croisés sur la poitrine. Effectuez un squat, puis en remontant, levez une jambe et tapotez votre orteil sur le côté, revenez au centre, refaites un squat et alternez les tapotements.', '["Ne pas garder les genoux alignés avec les orteils pendant le squat.", "Transférer trop de poids sur le pied qui tapote."]', true, '["Stand with feet shoulder-width apart and engage your core", "Lower into a squat by pushing your hips back and bending your knees while keeping your chest up", "Drive through your heels to return to standing position", "Lift one leg out to the side and tap your toe on the ground", "Return the leg to center and immediately lower into another squat", "Rise up and perform a toe tap with the opposite leg, continuing to alternate"]', '["Tenez-vous debout, les pieds à la largeur des épaules et contractez votre gainage.", "Descendez en squat en poussant vos hanches en arrière et en pliant les genoux tout en gardant votre poitrine relevée.", "Poussez sur vos talons pour revenir en position debout.", "Levez une jambe sur le côté et tapotez votre orteil au sol.", "Ramenez la jambe au centre et descendez immédiatement dans un nouveau squat.", "Remontez et effectuez un tapotement avec l''autre jambe, continuez à alterner."]', '["Conservez votre poids sur la jambe de soutien lors des tapotements, sans transférer tout le poids sur le pied qui tapote.", "Maintenez une bonne forme de squat, en veillant à ce que les genoux restent alignés avec les orteils et la poitrine lever tout au long du mouvement.", "Contrôlez le rythme et évitez de précipiter les tapotements pour maintenir votre équilibre.", "Gardez votre gainage engagé durant toute la séquence pour stabiliser votre torse."]', '["Keep your weight on your standing leg during toe taps and avoid shifting all weight to the tapping foot", "Maintain proper squat form with knees tracking over toes and chest lifted throughout the movement", "Control the tempo and avoid rushing through the toe taps to maintain balance", "Keep your core engaged throughout the entire sequence to stabilize your torso"]', '89fc3afb-7650-4bcd-9f82-726dd15e6600', 'squat-to-alternating-toe-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('afbccccd-44d4-4318-9a71-783859302701', 'Flexion avant debout', NULL, 'انحناءة امامية وقوفا', 'Standing forward bend', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/standing-forward-bend.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-forward-bend.jpg', NULL, '["Pliez les genoux autant que nécessaire pour préserver votre confort.", "Déplacez légèrement votre poids vers l''avant des pieds.", "Relâchez totalement votre haut du corps pour maximiser l''étirement."]', '["Ne pas plier les genoux quand c''est nécessaire.", "Hésiter à laisser la tête se détendre."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "standing forward bend"]', true, '2026-04-03 12:24:59.544466+00', '2026-04-03 12:24:59.544466+00', 'Renforcez vos ischio-jambiers tout en améliorant votre flexibilité et votre posture. Cet exercice est essentiel pour équilibrer votre corps et relâcher les tensions.', '["Ne pas plier les genoux quand c''est nécessaire.", "Hésiter à laisser la tête se détendre."]', true, '["Stand with feet hip-width apart.", "Inhale to lengthen your spine.", "Exhale and fold forward from the hips, bringing your hands toward the floor.", "Let your head hang heavy and relax your neck."]', '["Placez vos pieds à la largeur des hanches.", "Inspirez en allongeant votre colonne vertébrale.", "Expirez et pliez-vous en avant au niveau des hanches, en dirigeant vos mains vers le sol.", "Laissez votre tête pendre lourdement et détendez votre cou."]', '["Pliez les genoux autant que nécessaire pour préserver votre confort.", "Déplacez légèrement votre poids vers l''avant des pieds.", "Relâchez totalement votre haut du corps pour maximiser l''étirement."]', '["Bend your knees as much as needed.", "Shift your weight slightly toward the balls of your feet.", "Relax your upper body completely."]', 'cca9d3bf-daf9-421b-93ca-9e626d682807', 'standing-forward-bend', NULL, NULL);
INSERT INTO public.exercises VALUES ('d177d3f0-fa70-41c5-95d9-63e6c3a7e8d0', 'Curl Debout sur Une Jambe', NULL, NULL, 'Standing Single Leg Curl', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 8, '/videos/hamstrings/standing-single-leg-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-single-leg-curl.jpg', NULL, '["Garde ton ventre engagé et maintiens une posture droite tout au long du mouvement", "Concentre-toi sur le contrôle de la phase excentrique pour maximiser le développement musculaire", "Évite de balancer ou d''utiliser l''élan pour soulever le poids", "Garde ta cuisse de la jambe de travail immobile et perpendiculaire au sol", "Complète toutes les répétitions d''une jambe avant de passer à l''autre."]', '["Ne pas ajuster la machine correctement avant de commencer", "Oublier d''engager le tronc, ce qui peut entraîner une mauvaise posture."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "machine", "standing single leg curl"]', true, '2026-04-03 12:24:59.631996+00', '2026-04-03 12:24:59.631996+00', 'Position de départ : Tiens-toi sur la machine à curl avec une jambe fixée et l''autre légèrement soulevée. Exécution : Plie ton genou pour amener le coussin vers tes fessiers, puis redescends lentement à la position de départ. Répète avec l''autre jambe.', '["Ne pas ajuster la machine correctement avant de commencer", "Oublier d''engager le tronc, ce qui peut entraîner une mauvaise posture."]', true, '["Adjust the machine height so the padded lever sits comfortably against the back of your ankle just above the heel", "Stand with your non-working leg firmly planted and grip the support handles for stability", "Position your working leg straight with the ankle pad resting against the back of your lower leg", "Slowly curl your heel toward your glutes by bending your knee while keeping your thigh stationary", "Hold the contraction briefly at the top of the movement", "Lower the weight slowly and under control back to the starting position without letting the weight stack touch"]', '["Ajuste la hauteur de la machine pour que le levier rembourré soit confortablement contre l''arrière de ta cheville, juste au-dessus du talon", "Tiens-toi bien avec ta jambe non travaillante et agrippe les poignées de soutien pour plus de stabilité", "Positionne ta jambe active droite avec le coussin sur l''arrière de ta jambe inférieure", "Curle lentement ton talon vers tes fessiers en pliant le genou tout en maintenant ta cuisse immobile", "Maintiens la contraction brièvement en haut du mouvement", "Redescends lentement et contrôlément vers la position de départ sans laisser le poids toucher le sol."]', '["Garde ton ventre engagé et maintiens une posture droite tout au long du mouvement", "Concentre-toi sur le contrôle de la phase excentrique pour maximiser le développement musculaire", "Évite de balancer ou d''utiliser l''élan pour soulever le poids", "Garde ta cuisse de la jambe de travail immobile et perpendiculaire au sol", "Complète toutes les répétitions d''une jambe avant de passer à l''autre."]', '["Keep your core engaged and maintain an upright posture throughout the entire movement", "Focus on controlling the eccentric portion of the lift to maximize muscle development", "Avoid swinging or using momentum to lift the weight", "Keep your thigh of the working leg stationary and perpendicular to the floor", "Complete all repetitions on one leg before switching to the other leg"]', 'ef04d753-d34b-4457-bcdb-0ec447d55101', 'standing-single-leg-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('161a2590-2e31-44c5-ab7e-40c23bf9fc3f', 'Développé debout avec prise neutre', NULL, NULL, 'Standing Neutral Grip Cable Press', 'Chest', '[]', 'Chest', 'Intermediate', 4, '/videos/chest/standing-neutral-grip-cable-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-neutral-grip-cable-press.jpg', NULL, '["Maintiens ton ventre engagé et adopte une position stable pour éviter d''être tiré en arrière par les câbles", "Concentre-toi sur la contraction de tes muscles pectoraux au point de contraction maximale lorsque les bras sont complètement étendus", "Contrôle la phase négative du mouvement pour maximiser l''engagement musculaire et éviter les blessures", "Ne laisse pas tes épaules s''enrouler vers l''avant et évite que les câbles ne tirent tes bras trop en arrière", "Garde la prise neutre tout au long de l''exercice pour réduire la tension sur les poignets et cibler efficacement les pectoraux"]', '["Oublier de garder le ventre engagé", "Ne pas contrôler la descente du poids"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "cable", "standing neutral grip cable press"]', true, '2026-04-03 12:24:59.580638+00', '2026-04-03 12:24:59.580638+00', 'Position de départ : Tiens-toi face à une poulie avec des poignées à hauteur de poitrine. Exécution : Pousse les câbles vers l''avant jusqu''à ce que tes bras soient tendus, puis retourne lentement à la position de départ.', '["Oublier de garder le ventre engagé", "Ne pas contrôler la descente du poids"]', true, '["Set the cable pulleys to chest height and attach handles to each cable", "Stand in the center with one foot slightly forward for stability, grasping handles with neutral grip", "Position your body so there is tension in the cables when your hands are at chest level", "Press the handles forward and slightly inward until your arms are fully extended", "Slowly return to starting position, controlling the weight on the eccentric portion", "Maintain a slight forward lean throughout the entire movement"]', '["Ajuste les poulies à hauteur de poitrine et fixe les poignées sur chaque câble", "Place-toi au centre avec un pied légèrement en avant pour la stabilité, en tenant les poignées avec une prise neutre", "Assure-toi qu''il y a de la tension dans les câbles lorsque tes mains sont au niveau de la poitrine", "Pousse les poignées vers l''avant et légèrement vers l''intérieur jusqu''à ce que tes bras soient entièrement tendus", "Retourne lentement à la position de départ, en contrôlant le poids lors de la phase excentrique", "Garde une légère inclinaison vers l''avant tout au long du mouvement"]', '["Maintiens ton ventre engagé et adopte une position stable pour éviter d''être tiré en arrière par les câbles", "Concentre-toi sur la contraction de tes muscles pectoraux au point de contraction maximale lorsque les bras sont complètement étendus", "Contrôle la phase négative du mouvement pour maximiser l''engagement musculaire et éviter les blessures", "Ne laisse pas tes épaules s''enrouler vers l''avant et évite que les câbles ne tirent tes bras trop en arrière", "Garde la prise neutre tout au long de l''exercice pour réduire la tension sur les poignets et cibler efficacement les pectoraux"]', '["Keep your core engaged and maintain a stable stance to prevent being pulled backward by the cables", "Focus on squeezing your chest muscles at the peak contraction when arms are fully extended", "Control the negative portion of the movement to maximize muscle engagement and prevent injury", "Avoid letting your shoulders roll forward or allowing the cables to pull your arms too far back beyond your torso", "Maintain the neutral grip throughout the exercise to reduce wrist strain and target the chest effectively"]', '3d0e9420-3d5f-4c9d-a002-7ad83f43bbde', 'standing-neutral-grip-cable-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('67cbc520-8c8b-4f76-a17a-26ed51fbccf4', 'Développé à un bras avec haltère en position debout', NULL, 'ضغط واحد ذراع مع دمبل', 'Standing Palm-In One-Arm Dumbbell Press (R', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/standing-palm-in-one-arm-dumbbell-press-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-palm-in-one-arm-dumbbell-press-r.jpg', NULL, '["Engage bien tes abdos pendant tout le mouvement pour éviter les douleurs dans le bas du dos", "Ne te penche pas sur un côté et ne fais pas de mouvement de balancement pour soulever le poids", "Garde la prise en paume tournée vers l’intérieur pendant tout le mouvement", "Choisis un poids qui te permet de garder une bonne forme pour toutes les répétitions", "Tire ton homoplate vers le bas et vers l’arrière pour stabiliser ton épaule"]', '["Pencher le corps sur le côté pendant l’exécution", "Utiliser trop de poids et perdre la forme correcte"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "standing palm-in one-arm dumbbell press (r"]', true, '2026-04-03 12:24:59.605535+00', '2026-04-03 12:24:59.605535+00', 'Position de départ : Mets-toi debout, pieds écartés à la largeur des épaules, haltère dans la main droite à hauteur d’épaule, paume vers toi. Exécution : Pousse l’haltère droit au-dessus de ta tête, contrôle bien le mouvement tout en restant équilibré, puis redescends-le doucement à la position de départ.', '["Pencher le corps sur le côté pendant l’exécution", "Utiliser trop de poids et perdre la forme correcte"]', true, '["Stand with feet shoulder-width apart and engage your core muscles for stability", "Hold the dumbbell in your right hand at shoulder height with palm facing inward toward your body", "Keep your wrist straight and maintain a neutral spine throughout the movement", "Press the dumbbell straight up overhead until your arm is fully extended", "Lower the weight back to shoulder height in a controlled manner", "Complete all repetitions on the right side before switching to the left arm"]', '["Tiens-toi debout, pieds écartés à la largeur des épaules et engage tes muscles abdominaux pour la stabilité", "Prends l’haltère dans ta main droite à hauteur d’épaule avec la paume tournée vers ton corps", "Garde le poignet droit et une colonne vertébrale neutre pendant tout le mouvement", "Pousse l’haltère droite au-dessus de ta tête jusqu''à ce que ton bras soit complètement tendu", "Abaisse le poids à hauteur d’épaule avec contrôle", "Finish toutes les répétitions à droite avant de passer à la gauche"]', '["Engage bien tes abdos pendant tout le mouvement pour éviter les douleurs dans le bas du dos", "Ne te penche pas sur un côté et ne fais pas de mouvement de balancement pour soulever le poids", "Garde la prise en paume tournée vers l’intérieur pendant tout le mouvement", "Choisis un poids qui te permet de garder une bonne forme pour toutes les répétitions", "Tire ton homoplate vers le bas et vers l’arrière pour stabiliser ton épaule"]', '["Keep your core engaged throughout the entire movement to prevent lower back strain", "Avoid leaning to one side or using momentum to press the weight overhead", "Maintain the palm-in grip position throughout the entire range of motion", "Use a weight that allows you to maintain proper form for all repetitions", "Keep your shoulder blade pulled down and back to maintain shoulder stability"]', 'f8e77b58-2e1b-4695-ae24-17249ec2ad74', 'standing-palm-in-one-arm-dumbbell-press-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('7074fae4-19b1-44c9-a515-481d85b104c5', 'Pas Sumo', NULL, 'خطوات سمو', 'Sumo walk', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/sumo-walk.mp4', NULL, NULL, NULL, '/videos/thumbnails/sumo-walk.jpg', NULL, '["Veille à ce que tes genoux suivent la ligne de tes orteils pour éviter les blessures", "Garde un torse droit et fort tout au long de l''exercice", "Concentre-toi sur le fait de garder ton poids sur tes talons plutôt que sur tes orteils", "Effectue des pas petits et contrôlés pour maintenir la bonne profondeur et la forme du squat", "Engage continuellement tes fessiers et tes muscles abdominaux pendant l''exercice"]', '["Laisser les genoux s''affaisser vers l''intérieur", "Élever les talons du sol pendant le squat"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "sumo walk"]', true, '2026-04-03 12:24:59.656238+00', '2026-04-03 12:24:59.656238+00', 'Un exercice complet pour renforcer l''ensemble de votre corps tout en améliorant votre mobilité et votre stabilité. Parfait pour tonifier vos jambes et activer vos muscles centraux !', '["Laisser les genoux s''affaisser vers l''intérieur", "Élever les talons du sol pendant le squat"]', true, '["Stand with feet wider than shoulder-width apart and toes pointed slightly outward", "Lower into a deep squat position by bending at the hips and knees, keeping your chest up and back straight", "Maintain the squat position and take a small step to the right with your right foot", "Bring your left foot to meet your right foot, maintaining the wide sumo squat stance", "Continue stepping sideways for the desired number of steps, then reverse direction", "Keep your core engaged and weight evenly distributed throughout the movement"]', '["Place-toi avec les pieds plus larges que les épaules et les orteils légèrement tournés vers l''extérieur", "Descends en position de squat profond en fléchissant les hanches et les genoux, en gardant le torse droit et le dos aligné", "Maintiens la position de squat et fais un petit pas sur le côté droit avec ton pied droit", "Ramène ton pied gauche vers le pied droit tout en gardant une posture de squat large", "Continue à faire des pas sur le côté pour le nombre de pas souhaité, puis inverse la direction", "Reste bien stable en engageant ton abdomen et en répartissant ton poids uniformément pendant le mouvement"]', '["Veille à ce que tes genoux suivent la ligne de tes orteils pour éviter les blessures", "Garde un torse droit et fort tout au long de l''exercice", "Concentre-toi sur le fait de garder ton poids sur tes talons plutôt que sur tes orteils", "Effectue des pas petits et contrôlés pour maintenir la bonne profondeur et la forme du squat", "Engage continuellement tes fessiers et tes muscles abdominaux pendant l''exercice"]', '["Keep your knees tracking in line with your toes to prevent knee strain", "Maintain a strong upright torso throughout the entire movement", "Focus on keeping your weight in your heels rather than your toes", "Take small controlled steps to maintain proper squat depth and form", "Engage your glutes and core muscles continuously during the exercise"]', '0ed37189-d6ea-48c0-83cb-587b44a7b546', 'sumo-walk', NULL, NULL);
INSERT INTO public.exercises VALUES ('91fb97c0-8a9a-4d6c-be81-feff163b73f2', 'Toes to bar - L''intégralité de votre corps en action !', NULL, 'Toes to bar - الجسد كامل ف الحركة!', 'Toes to bar', 'Bodyweight', '[]', 'Bodyweight', 'Advanced', 16, '/videos/bodyweight/toes-to-bar.mp4', NULL, NULL, NULL, '/videos/thumbnails/toes-to-bar.jpg', NULL, '["Gardez vos épaules engagées, n''hésitez pas à solliciter les muscles pour garder le contrôle et éviter les blessures", "Utilisez un élan contrôlé, pas une balançante agressive, pour soulever vos jambes tout en restant en bonne posture", "Concentrez-vous sur l''engagement du tronc pendant toute la plage de mouvement, pas seulement lors de la montée", "Commencez par des variantes avec les genoux fléchis, comme les levées de genoux suspendues, si vous ne maîtrisez pas encore le mouvement complet", "Vérifiez votre force de préhension et pensez à utiliser des sangles si votre prise devient un obstacle"]', '["Relâcher complètement les épaules au bas du mouvement", "Utiliser un élan excessif et déséquilibré pour tenter de soulever les jambes"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "toes to bar"]', true, '2026-04-03 12:24:59.750468+00', '2026-04-03 12:24:59.750468+00', 'Position de départ : Suspendez-vous à une barre de traction, bras tendus, mains écartées à la largeur des épaules, jambes droites vers le bas. Exécution : Engagez votre sangle abdominale et levez vos jambes devant vous jusqu''à ce que vos orteils touchent la barre ou s''en approchent, puis redescendez en contrôlant le mouvement jusqu''à la position de départ.', '["Relâcher complètement les épaules au bas du mouvement", "Utiliser un élan excessif et déséquilibré pour tenter de soulever les jambes"]', true, '["Grip the pull-up bar with an overhand grip, hands positioned shoulder-width apart", "Hang with arms fully extended and engage your shoulder blades to create stability", "Initiate the movement by contracting your core and hip flexors to lift your knees toward your chest", "Continue lifting until your legs are straight and toes reach toward or touch the bar", "Control the descent by slowly lowering your legs back to the starting position", "Maintain grip strength throughout the entire movement to prevent dropping"]', '["Saisissez la barre de traction avec une prise en pronation, mains à la largeur des épaules", "Suspendez-vous bras tendus, engagez vos omoplates pour stabiliser votre corps", "Commencez le mouvement en contractant vos abdominaux et vos fléchisseurs de la hanche pour lever vos genoux vers votre poitrine", "Continuez à lever jusqu''à ce que vos jambes soient droites et que vos orteils atteignent ou touchent la barre", "Contrôlez la descente en abaissant lentement vos jambes jusqu''à la position de départ", "Maintenez votre prise de force tout au long du mouvement pour éviter de lâcher prise"]', '["Gardez vos épaules engagées, n''hésitez pas à solliciter les muscles pour garder le contrôle et éviter les blessures", "Utilisez un élan contrôlé, pas une balançante agressive, pour soulever vos jambes tout en restant en bonne posture", "Concentrez-vous sur l''engagement du tronc pendant toute la plage de mouvement, pas seulement lors de la montée", "Commencez par des variantes avec les genoux fléchis, comme les levées de genoux suspendues, si vous ne maîtrisez pas encore le mouvement complet", "Vérifiez votre force de préhension et pensez à utiliser des sangles si votre prise devient un obstacle"]', '["Keep your shoulders engaged and avoid completely relaxing at the bottom to maintain control and prevent injury", "Use controlled momentum rather than aggressive swinging to help lift your legs while maintaining proper form", "Focus on core engagement throughout the entire range of motion, not just during the lifting phase", "Start with bent-knee variations like hanging knee raises if you cannot yet perform the full toes-to-bar movement", "Ensure adequate grip strength and consider using lifting straps if grip becomes the limiting factor"]', 'beb4aef0-332a-4be7-9839-d51e65772e33', 'toes-to-bar', NULL, NULL);
INSERT INTO public.exercises VALUES ('4b4a47d9-c063-4f87-86cd-eb8ffa8eb366', 'Posture de l''arbre (à droite)', NULL, 'وضعية الشجرة (على اليمين)', 'Tree pose (right)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/tree-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/tree-pose-right.jpg', NULL, '["Presse ton pied et ta cuisse l''un contre l''autre pour plus de stabilité.", "Garde ta jambe de soutien solide avec un léger fléchissement.", "Engage ton ventre pour renforcer ta stabilité."]', '["Ne pas maintenir la posture longtemps.", "Se pencher ou se déporter sur le côté."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "tree pose (right)"]', true, '2026-04-03 12:24:59.764722+00', '2026-04-03 12:24:59.764722+00', 'Améliore ton équilibre et ton renforcement musculaire avec la posture de l''arbre. Cette position engage tout le corps tout en développant ta concentration et ta stabilité.', '["Ne pas maintenir la posture longtemps.", "Se pencher ou se déporter sur le côté."]', true, '["Stand on one leg and place the other foot on your inner thigh or calf.", "Avoid placing your foot on the knee.", "Bring your palms together at your chest or raise them overhead.", "Focus on a fixed point for balance."]', '["Tiens-toi sur une jambe et place l''autre pied sur ta cuisse intérieure ou ton mollet.", "Évite de poser ton pied sur le genou.", "Rapproche tes paumes à la poitrine ou lève-les au-dessus de la tête.", "Concentre-toi sur un point fixe pour maintenir ton équilibre."]', '["Presse ton pied et ta cuisse l''un contre l''autre pour plus de stabilité.", "Garde ta jambe de soutien solide avec un léger fléchissement.", "Engage ton ventre pour renforcer ta stabilité."]', '["Press your foot and thigh into each other.", "Keep your standing leg strong with a micro-bend.", "Engage your core for stability."]', '1d684533-244d-42e9-a085-843e40965805', 'tree-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('4d926363-2a60-41e6-b536-0bae2cba7a2d', 'Guerrier I (gauche)', NULL, 'محارب ١ (يسار)', 'Warrior I (left)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/warrior-i-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/warrior-i-left.jpg', NULL, '["Aligne tes hanches vers l''avant du tapis.", "Veille à ce que ton genou avant reste au-dessus de la cheville et ne dépasse pas les orteils.", "Redresse ta poitrine et fixe le regard devant toi ou vers le haut."]', '["Ne pas bien aligner les hanches.", "Laisser le genou avant dépasser les orteils."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "warrior i (left)"]', true, '2026-04-03 12:24:59.862552+00', '2026-04-03 12:24:59.862552+00', 'Renforce tes fessiers et améliore ta concentration avec cet exercice puissant !', '["Ne pas bien aligner les hanches.", "Laisser le genou avant dépasser les orteils."]', true, '["From standing, step one foot back about 4 feet.", "Bend your front knee to 90 degrees over the ankle.", "Turn your back foot out at 45 degrees and press the heel down.", "Raise your arms overhead with palms facing each other."]', '["Depuis la position debout, fais un pas en arrière d''environ 1,2 mètre.", "Fléchis ton genou avant à 90 degrés, en le gardant au-dessus de la cheville.", "Oriente ton pied arrière à 45 degrés et appuie le talon au sol.", "Lève tes bras au-dessus de la tête, les paumes face à face."]', '["Aligne tes hanches vers l''avant du tapis.", "Veille à ce que ton genou avant reste au-dessus de la cheville et ne dépasse pas les orteils.", "Redresse ta poitrine et fixe le regard devant toi ou vers le haut."]', '["Square your hips toward the front of the mat.", "Keep your front knee over the ankle, not past the toes.", "Lift your chest and gaze forward or up."]', '865864f7-f65e-4ea1-9e43-47fc0881fc00', 'warrior-i-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('b883518b-0c8f-4ef9-a694-3b5b3f52d01c', 'Posture de la Roue', NULL, 'وضعية العجلة', 'Wheel pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/wheel-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/wheel-pose.jpg', NULL, '["Échauffe bien ta colonne vertébrale avec la posture du pont avant.", "Garde les pieds parallèles et à la largeur des hanches.", "Pousse uniformément avec tous tes membres."]', '["Ne pas échauffer la colonne vertébrale avant l''exercice.", "Les pieds trop écartés ou mal positionnés."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "wheel pose"]', true, '2026-04-03 12:24:59.908388+00', '2026-04-03 12:24:59.908388+00', 'La posture de la roue est un excellent moyen de renforcer votre dos tout en améliorant votre flexibilité.', '["Ne pas échauffer la colonne vertébrale avant l''exercice.", "Les pieds trop écartés ou mal positionnés."]', true, '["Lie on your back with knees bent and feet flat on the floor.", "Place your hands beside your ears with fingers pointing toward your shoulders.", "Press into your hands and feet to lift your body off the floor.", "Straighten your arms and legs as much as possible."]', '["Allonge-toi sur le dos, les genoux pliés et les pieds bien à plat sur le sol.", "Place tes mains à côté de tes oreilles, les doigts orientés vers tes épaules.", "Pousse avec tes mains et tes pieds pour soulever ton corps du sol.", "Redresse tes bras et tes jambes au maximum."]', '["Échauffe bien ta colonne vertébrale avec la posture du pont avant.", "Garde les pieds parallèles et à la largeur des hanches.", "Pousse uniformément avec tous tes membres."]', '["Warm up your spine with Bridge Pose first.", "Keep your feet parallel and hip-width apart.", "Press evenly through all four limbs."]', '4e5467d4-898b-4c22-98d0-5000f9b2c1ed', 'wheel-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('f2427be4-8225-4c13-8903-ef8474126b3a', 'Guerrier III (gauche)', NULL, 'محارب الثالث (يسار)', 'Warrior III (left)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/warrior-iii-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/warrior-iii-left.jpg', NULL, '["Gardez votre jambe d''appui solide avec un léger pli.", "Alignez vos hanches vers le sol.", "Engagez votre core pour maintenir l''équilibre."]', '["Pencher trop en avant sans garder le dos droit.", "Ne pas aligner les hanches, ce qui déséquilibre la position."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "warrior iii (left)"]', true, '2026-04-03 12:24:59.890438+00', '2026-04-03 12:24:59.890438+00', 'Un exercice complet qui renforce tout le corps tout en améliorant l''équilibre et la concentration.', '["Pencher trop en avant sans garder le dos droit.", "Ne pas aligner les hanches, ce qui déséquilibre la position."]', true, '["From standing, shift your weight onto one foot.", "Hinge forward at the hips while lifting your back leg behind you.", "Extend your arms forward or alongside your body.", "Create a straight line from fingertips to the lifted foot."]', '["À partir de la position debout, transférez votre poids sur un pied.", "Inclinez-vous en avant en fléchissant les hanches tout en levant votre jambe arrière.", "Étendez vos bras devant vous ou le long de votre corps.", "Créez une ligne droite de vos doigts jusqu''à votre pied levé."]', '["Gardez votre jambe d''appui solide avec un léger pli.", "Alignez vos hanches vers le sol.", "Engagez votre core pour maintenir l''équilibre."]', '["Keep your standing leg strong with a micro-bend.", "Square your hips toward the floor.", "Engage your core for balance."]', '1e43a5c6-7d2f-4c45-a87d-28eec849221c', 'warrior-iii-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('e86b1940-d658-4165-9942-986349f3b6fa', 'Squats Zercher', NULL, 'Squats Zercher', 'Zercher Squats', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 1, '/videos/quadriceps/zercher-squats.mp4', NULL, NULL, NULL, '/videos/thumbnails/zercher-squats.jpg', NULL, '["Gardez vos coudes hauts et vos avant-bras parallèles au sol pour maintenir une bonne posture", "Concentrez-vous sur le fait de descendre dans vos hanches plutôt que de simplement plier les genoux vers l''avant", "Maintenez une colonne vertébrale neutre et évitez d''arrondir le dos pendant la descente", "Contrôlez le tempo avec une descente lente et une poussée puissante vers le haut", "Vos genoux doivent suivre la ligne de vos orteils sans s''affaisser vers l''intérieur"]', '["Ne pas garder le dos droit pendant l''exercice", "Des coudes tombant trop bas, ce qui entraîne une mauvaise posture"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "zercher squats"]', true, '2026-04-03 12:24:59.97824+00', '2026-04-03 12:24:59.97824+00', 'Position de départ : Écartez vos pieds à la largeur des épaules, les bras croisés devant la poitrine, les coudes fléchis à 90 degrés, formant une étagère avec vos avant-bras. Exécution : Plongez dans une squats profond en poussant vos hanches en arrière et en fléchissant vos genoux tout en maintenant votre torse droit, puis poussez avec vos talons pour revenir à la position de départ.', '["Ne pas garder le dos droit pendant l''exercice", "Des coudes tombant trop bas, ce qui entraîne une mauvaise posture"]', true, '["Stand with feet shoulder-width apart and toes slightly turned out", "Cross your arms in front of your chest, creating a stable shelf with your forearms", "Initiate the movement by pushing your hips back and bending at the knees", "Lower your body until your thighs are parallel to the floor or as deep as mobility allows", "Keep your chest up and core engaged throughout the entire movement", "Drive through your heels and push the floor away to return to standing position"]', '["Écartez les pieds à la largeur des épaules, les orteils légèrement tournés vers l''extérieur", "Croisez vos bras devant votre poitrine, formant une étagère stable avec vos avant-bras", "Initiez le mouvement en poussant vos hanches en arrière et en fléchissant les genoux", "Descendez jusqu''à ce que vos cuisses soient parallèles au sol ou aussi bas que votre mobilité le permet", "Gardez la poitrine relevée et le ventre engagé tout au long du mouvement", "Poussez avec vos talons pour revenir à la position debout"]', '["Gardez vos coudes hauts et vos avant-bras parallèles au sol pour maintenir une bonne posture", "Concentrez-vous sur le fait de descendre dans vos hanches plutôt que de simplement plier les genoux vers l''avant", "Maintenez une colonne vertébrale neutre et évitez d''arrondir le dos pendant la descente", "Contrôlez le tempo avec une descente lente et une poussée puissante vers le haut", "Vos genoux doivent suivre la ligne de vos orteils sans s''affaisser vers l''intérieur"]', '["Keep your elbows high and forearms parallel to the floor to maintain proper posture", "Focus on sitting back into your hips rather than just bending your knees forward", "Maintain a neutral spine and avoid rounding your back during the descent", "Control the tempo with a slow descent and powerful upward drive", "Your knees should track over your toes without caving inward"]', '16b4d2da-13c2-419b-aa1a-14a443294762', 'zercher-squats', NULL, NULL);
INSERT INTO public.exercises VALUES ('af3c94ba-7128-4bca-9a7c-f49e39c5d5be', 'Toucher les Orteils', NULL, NULL, 'Toe Touchers', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/toe-touchers.mp4', NULL, NULL, NULL, '/videos/thumbnails/toe-touchers.jpg', NULL, '["Garde le bas du dos bien plat contre le sol tout au long de l''exercice", "Concentre-toi sur le travail des abdominaux, évite de tirer avec le cou ou de te balancer", "Garde les jambes droites durant tout l''exercice, mais un léger pli au niveau des genoux est acceptable si tu es tendu aux ischio-jambiers", "Contrôle la descente pour maximiser l''engagement musculaire et éviter les blessures", "Expire en montant et inspire en redescendant"]', '["Ne pas garder le bas du dos plaqué au sol", "Se balancer avec le dos au lieu d''activer les abdos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "toe touchers"]', true, '2026-04-03 12:24:59.73609+00', '2026-04-03 12:24:59.73609+00', 'Commence à plat sur le dos, jambes tendues vers le plafond, bras tendus vers tes pieds. Prépare-toi à activer ton corps!', '["Ne pas garder le bas du dos plaqué au sol", "Se balancer avec le dos au lieu d''activer les abdos"]', true, '["Lie flat on your back on a mat with your lower back pressed into the floor", "Extend both legs straight up toward the ceiling, keeping them as vertical as possible", "Reach your arms straight up toward your feet with palms facing your legs", "Engage your core and lift your shoulder blades off the ground while reaching toward your toes", "Hold the contraction briefly at the top of the movement", "Slowly lower your shoulders back to the starting position while maintaining leg position"]', '["Allonge-toi sur le dos, le bas du dos bien collé au sol", "Lève les deux jambes à la verticale, bien droites vers le ciel", "Allonge tes bras vers tes pieds, paumes face aux jambes", "Active tes abdos et soulève les épaules du sol tout en atteignant tes orteils", "Reste une seconde en haut, contracte bien les muscles", "Redescends lentement en contrôlant le mouvement tout en gardant tes jambes en l''air"]', '["Garde le bas du dos bien plat contre le sol tout au long de l''exercice", "Concentre-toi sur le travail des abdominaux, évite de tirer avec le cou ou de te balancer", "Garde les jambes droites durant tout l''exercice, mais un léger pli au niveau des genoux est acceptable si tu es tendu aux ischio-jambiers", "Contrôle la descente pour maximiser l''engagement musculaire et éviter les blessures", "Expire en montant et inspire en redescendant"]', '["Keep your lower back pressed firmly against the floor throughout the entire movement", "Focus on lifting with your abdominal muscles rather than pulling with your neck or using momentum", "Maintain straight legs throughout the exercise - slight bend in knees is acceptable if hamstrings are tight", "Control the lowering phase to maximize muscle engagement and prevent injury", "Breathe out during the lifting phase and breathe in as you lower back down"]', '7f2664b3-8108-458d-9535-7d14af3cf955', 'toe-touchers', NULL, NULL);
INSERT INTO public.exercises VALUES ('9741cc56-768b-46a1-bf37-5f5cd424304e', 'Élévations de genoux en marchant', NULL, 'رفعات الركبة في المشي', 'Walking knee raises', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/walking-knee-raises.mp4', NULL, NULL, NULL, '/videos/thumbnails/walking-knee-raises.jpg', NULL, '["Gardez les abdominaux engagés pendant tout le mouvement pour maximiser l''activation des muscles du ventre.", "Évitez de pencher en arrière ou en avant - restez bien droit avec les épaules au-dessus des hanches.", "Levez les genoux jusqu''à la hauteur de la hanche ou aussi haut que cela reste confortable, tout en conservant le contrôle.", "Concentrez-vous sur des mouvements contrôlés plutôt que sur la vitesse pour garantir une bonne forme et un engagement musculaire optimal.", "Gardez la jambe de support légèrement fléchie pour maintenir l''équilibre et réduire la tension sur l''articulation du genou."]', '["Pencher le torse en avant ou en arrière lors de l''exécution de l''exercice.", "Ne pas lever les genoux assez haut, ce qui réduit l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "walking knee raises"]', true, '2026-04-03 12:24:59.830609+00', '2026-04-03 12:24:59.830609+00', 'Positionnez-vous debout, les pieds écartés à la largeur des hanches, les bras le long du corps et les abdominaux engagés. L''action consiste à lever un genou vers votre poitrine en gardant le dos droit, puis à redescendre le pied avant de répéter avec l''autre jambe en marchant de manière contrôlée.', '["Pencher le torse en avant ou en arrière lors de l''exécution de l''exercice.", "Ne pas lever les genoux assez haut, ce qui réduit l''efficacité de l''exercice."]', true, '["Stand with feet hip-width apart and engage your core muscles", "Lift your right knee up toward your chest to about hip level while keeping your torso upright", "Lower your right foot back to the ground in a controlled manner", "Immediately lift your left knee up toward your chest to the same height", "Continue alternating legs in a smooth, rhythmic pattern", "Maintain steady breathing throughout the movement"]', '["Positionnez-vous debout, les pieds écartés à la largeur des hanches, et activez vos muscles abdominaux.", "Levez votre genou droit vers votre poitrine, à la hauteur de la hanche, tout en gardant votre torse bien droit.", "Descendez votre pied droit au sol de manière contrôlée.", "Levez immédiatement votre genou gauche à la même hauteur.", "Continuez à alterner les jambes dans un mouvement fluide et rythmique.", "Respirez régulièrement tout au long de l''exercice."]', '["Gardez les abdominaux engagés pendant tout le mouvement pour maximiser l''activation des muscles du ventre.", "Évitez de pencher en arrière ou en avant - restez bien droit avec les épaules au-dessus des hanches.", "Levez les genoux jusqu''à la hauteur de la hanche ou aussi haut que cela reste confortable, tout en conservant le contrôle.", "Concentrez-vous sur des mouvements contrôlés plutôt que sur la vitesse pour garantir une bonne forme et un engagement musculaire optimal.", "Gardez la jambe de support légèrement fléchie pour maintenir l''équilibre et réduire la tension sur l''articulation du genou."]', '["Keep your core engaged throughout the entire movement to maximize abdominal activation", "Avoid leaning backward or forward - maintain an upright posture with shoulders over hips", "Lift knees to hip level or as high as comfortable while maintaining control", "Focus on controlled movements rather than speed to ensure proper form and muscle engagement", "Keep your supporting leg slightly bent to maintain balance and reduce strain on the knee joint"]', '14044ef0-8d9d-4d65-9365-0f1bc2dd3c11', 'walking-knee-raises', NULL, NULL);
INSERT INTO public.exercises VALUES ('28a16373-f842-4295-b6c3-33f7c93cc440', 'Étirement du Quadriceps Debout', NULL, 'تمارين لتمديد عضلات الفخذين', 'Standing Quad Stretch (R)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/standing-quad-stretch-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-quad-stretch-r.jpg', NULL, '["Garde la jambe qui se tient légèrement fléchie pour mieux équilibrer et réduire la pression sur le genou.", "Engage ton tronc pour ne pas cambrer le dos et garde le bassin neutre.", "Si tu ne peux pas atteindre ta cheville, utilise une serviette ou une sangle autour de ton pied.", "Arrête immédiatement si tu ressens une douleur aiguë au genou ou à la hanche.", "Concentre-toi sur le fait de tirer ton talon droit vers l''arrière, sans forcer ton genou dans une flexion extrême."]', '["Ne pas garder le buste droit, ce qui peut entraîner des tensions dans le dos.", "Laisser la jambe se déplacer sur le côté au lieu de rester alignée."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "standing quad stretch (r)"]', true, '2026-04-03 12:24:59.614789+00', '2026-04-03 12:24:59.614789+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches. Utilise un mur ou une chaise pour t''équilibrer si nécessaire. Exécution : Plie ton genou droit et ramène ton talon droit vers tes fesses en tenant ta cheville ou ton pied avec ta main droite, tout en gardant le torse droit.', '["Ne pas garder le buste droit, ce qui peut entraîner des tensions dans le dos.", "Laisser la jambe se déplacer sur le côté au lieu de rester alignée."]', true, '["Stand near a wall or sturdy surface for balance support", "Bend your right knee and bring your right heel toward your glutes", "Grasp your right ankle or top of your foot with your right hand", "Keep your knees close together and avoid pulling your leg out to the side", "Hold the stretch for 20-30 seconds while breathing normally", "Slowly release and repeat on the left leg"]', '["Tiens-toi près d''un mur ou d''une surface solide pour t''assurer un bon équilibre.", "Plie ton genou droit et amène ton talon droit vers tes fesses.", "Saisis ta cheville ou le dessus de ton pied avec ta main droite.", "Garde tes genoux proches l''un de l''autre, évite de tirer ta jambe sur le côté.", "Maintiens l''étirement pendant 20-30 secondes tout en respirant normalement.", "Relâche doucement et répète avec la jambe gauche."]', '["Garde la jambe qui se tient légèrement fléchie pour mieux équilibrer et réduire la pression sur le genou.", "Engage ton tronc pour ne pas cambrer le dos et garde le bassin neutre.", "Si tu ne peux pas atteindre ta cheville, utilise une serviette ou une sangle autour de ton pied.", "Arrête immédiatement si tu ressens une douleur aiguë au genou ou à la hanche.", "Concentre-toi sur le fait de tirer ton talon droit vers l''arrière, sans forcer ton genou dans une flexion extrême."]', '["Keep your standing leg slightly bent to maintain balance and reduce stress on the knee", "Avoid arching your back by engaging your core and keeping your pelvis neutral", "If you cannot reach your ankle, use a towel or strap around your foot", "Stop immediately if you feel any sharp pain in your knee or hip", "Focus on pulling your heel straight back rather than forcing your knee into extreme flexion"]', 'ff71c077-37d0-4819-9336-14d4946755f2', 'standing-quad-stretch-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('c579b1ee-cbab-46e1-b99f-79318a4e826b', 'Inchworm', NULL, 'Inchworm', 'Inchworm', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/inchworm.mp4', NULL, NULL, NULL, '/videos/thumbnails/inchworm.jpg', NULL, '["Garde bien le ventre serré tout au long du mouvement pour protéger tes lombaires", "Si tu n''arrives pas à toucher le sol avec les jambes droites, plie légèrement les genoux en te penchant", "Assure-toi d''avoir une bonne posture en planche : épaules au-dessus des poignets, ne laisse pas les hanches s''affaisser", "Bouge lentement et de manière contrôlée - ce n''est pas une course, concentre-toi sur ta forme plutôt que sur la vitesse", "Arrête si tu ressens une douleur au bas du dos ou aux épaules."]', '["Ne pas garder le ventre engagé, ce qui peut causer des douleurs lombaires", "Avancer trop vite et négliger la forme, ce qui peut entraîner des blessures"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "inchworm"]', true, '2026-04-03 12:24:57.203946+00', '2026-04-03 12:24:57.203946+00', 'Un exercice complet qui fait travailler tout le corps ! Démarre en position debout, les pieds écartés à la largeur des hanches, prêt à te lancer.', '["Ne pas garder le ventre engagé, ce qui peut causer des douleurs lombaires", "Avancer trop vite et négliger la forme, ce qui peut entraîner des blessures"]', true, '["Stand tall with feet hip-width apart and arms at your sides", "Hinge at the hips and bend forward, placing your hands flat on the floor in front of your feet", "Walk your hands forward one at a time until you reach a high plank position with straight arms", "Hold the plank briefly, keeping your body in a straight line from head to heels", "Walk your hands back toward your feet, maintaining straight legs as much as possible", "Return to standing position and repeat"]', '["Tiens-toi bien droit, pieds à la largeur des hanches, bras le long du corps", "Incline-toi au niveau des hanches et pose tes mains à plat sur le sol devant tes pieds", "Avance tes mains une par une jusqu''à arriver en position de planche avec les bras tendus", "Maintiens la planche brièvement, corps aligné de la tête aux talons", "Ramène tes mains vers tes pieds, en gardant les jambes aussi droites que possible", "Retourne en position debout et répète l''exercice."]', '["Garde bien le ventre serré tout au long du mouvement pour protéger tes lombaires", "Si tu n''arrives pas à toucher le sol avec les jambes droites, plie légèrement les genoux en te penchant", "Assure-toi d''avoir une bonne posture en planche : épaules au-dessus des poignets, ne laisse pas les hanches s''affaisser", "Bouge lentement et de manière contrôlée - ce n''est pas une course, concentre-toi sur ta forme plutôt que sur la vitesse", "Arrête si tu ressens une douleur au bas du dos ou aux épaules."]', '["Keep your core engaged throughout the entire movement to protect your lower back", "If you can''t touch the floor with straight legs, bend your knees slightly when reaching down", "Maintain proper plank form with shoulders directly over wrists and avoid sagging hips", "Move slowly and controlled - this isn''t a race, focus on form over speed", "Stop if you feel any pain in your lower back or shoulders"]', '0bc5f89b-dec0-483a-b98d-655998f8849d', 'inchworm', NULL, NULL);
INSERT INTO public.exercises VALUES ('db67e493-b150-4be3-be8f-28e806009f14', 'Soulevé de terre avec kettlebell', NULL, 'Deadlift avec Kettlebell', 'Deadlift with Kettlebell', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 128, '/videos/bodyweight/deadlift-with-kettlebell.mp4', NULL, NULL, NULL, '/videos/thumbnails/deadlift-with-kettlebell.jpg', NULL, '["Garde le kettlebell près de ton corps pendant tout l''exercice", "Commence le mouvement avec les hanches, pas avec les genoux ou le dos", "Maintiens une colonne vertébrale neutre et évite de courber le dos lors du soulevé", "Concentre-toi sur l''extension des hanches et l''activation des fessiers en haut du mouvement", "Contrôle la descente - ne laisse pas simplement le poids tomber"]', '["Courber le dos pendant le lift", "Ne pas engager les fessiers au sommet du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "kettlebell", "deadlift with kettlebell"]', true, '2026-04-03 12:24:56.252516+00', '2026-04-03 12:24:56.252516+00', 'Prends position avec les pieds écartés à la largeur des hanches, le kettlebell posé au sol entre tes pieds. Plie légèrement les genoux et pousse tes hanches en arrière pour atteindre le kettlebell. Prépare-toi à soulever !', '["Courber le dos pendant le lift", "Ne pas engager les fessiers au sommet du mouvement"]', true, '["Position feet hip-width apart with the kettlebell centered between your feet", "Hinge at the hips by pushing your hips back and bending your knees to reach the kettlebell", "Grip the kettlebell handle firmly with both hands using an overhand grip", "Keep your chest up, shoulders back, and maintain a neutral spine throughout the movement", "Drive through your heels and squeeze your glutes to return to standing position", "Lower the kettlebell back down by reversing the hip hinge movement with control"]', '["Positionne tes pieds à la largeur des hanches avec le kettlebell centré entre eux", "Pousse tes hanches vers l''arrière en pliant les genoux pour atteindre le kettlebell", "Prends fermement le kettlebell avec les deux mains en grip pronation", "Garde le torse droit, les épaules en arrière et la colonne bien alignée tout au long du mouvement", "Pousse sur tes talons et contracte les fessiers pour te redresser en position debout", "Redescends le kettlebell en inversant le mouvement avec contrôle"]', '["Garde le kettlebell près de ton corps pendant tout l''exercice", "Commence le mouvement avec les hanches, pas avec les genoux ou le dos", "Maintiens une colonne vertébrale neutre et évite de courber le dos lors du soulevé", "Concentre-toi sur l''extension des hanches et l''activation des fessiers en haut du mouvement", "Contrôle la descente - ne laisse pas simplement le poids tomber"]', '["Keep the kettlebell close to your body throughout the entire movement", "Initiate the movement from your hips, not your knees or back", "Maintain a neutral spine and avoid rounding your back during the lift", "Focus on hip extension and glute activation at the top of the movement", "Control the descent - don''t just drop the weight down"]', '8f2f2d63-4e39-408b-b450-f88c27d8ae1a', 'deadlift-with-kettlebell', NULL, NULL);
INSERT INTO public.exercises VALUES ('2b50865e-33e1-44f9-b6d8-ebd029a1d806', 'Star Jump Burpees', NULL, NULL, 'Star Jump Burpees', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/star-jump-burpees.mp4', NULL, NULL, NULL, '/videos/thumbnails/star-jump-burpees.jpg', NULL, '["Garde toujours ton gainage serré pour protéger ton dos et assurer une bonne forme.", "Atterris doucement sur l''avant des pieds pour minimiser l''impact sur les articulations.", "Maintiens une ligne droite de la tête aux talons pendant les phases de planche et de pompe.", "Contrôle ton rythme et privilégie la qualité du mouvement plutôt que la rapidité, surtout au début.", "Respire régulièrement, expire lors du saut explosif."]', '["Ne pas garder le gainage, ce qui peut entraîner des blessures.", "Atterrissage brusque, ce qui augmente le risque de chocs articulaires."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "star jump burpees"]', true, '2026-04-03 12:24:59.645124+00', '2026-04-03 12:24:59.645124+00', 'Débute debout, pieds écartés à la largeur des hanches, bras le long du corps et gainage actif. Passe à l''action avec de l''énergie !', '["Ne pas garder le gainage, ce qui peut entraîner des blessures.", "Atterrissage brusque, ce qui augmente le risque de chocs articulaires."]', true, '["Begin standing tall, then squat down and place both hands firmly on the ground shoulder-width apart", "Jump or step both feet back simultaneously into a high plank position with straight arms", "Perform a push-up by lowering your chest to the ground, then press back up to plank position", "Jump or step both feet forward back into the squat position near your hands", "Explosively jump straight up while simultaneously spreading your arms overhead and legs wide apart into a star shape", "Land softly with feet hip-width apart and immediately begin the next repetition"]', '["Tiens-toi bien droit puis fléchis en squat, mains au sol, à la largeur des épaules.", "Saute ou fais un pas en arrière pour te retrouver en position de planche, bras tendus.", "Effectue une pompe en abaissant ta poitrine vers le sol, puis remonte en position de planche.", "Saute ou fais un pas en avant pour revenir en squat près de tes mains.", "Saute explosivement vers le haut en écartant bras et jambes pour former une étoile.", "Atterris doucement, pieds écartés à la largeur des hanches et enchaîne avec la prochaine répétition."]', '["Garde toujours ton gainage serré pour protéger ton dos et assurer une bonne forme.", "Atterris doucement sur l''avant des pieds pour minimiser l''impact sur les articulations.", "Maintiens une ligne droite de la tête aux talons pendant les phases de planche et de pompe.", "Contrôle ton rythme et privilégie la qualité du mouvement plutôt que la rapidité, surtout au début.", "Respire régulièrement, expire lors du saut explosif."]', '["Keep your core tight throughout the entire movement to protect your lower back and maintain proper form", "Land softly on the balls of your feet when jumping back to starting position to reduce impact on joints", "Maintain a straight line from head to heels during the plank and push-up phases", "Control the tempo and focus on quality movement rather than speed, especially when learning the exercise", "Breathe consistently throughout the movement, exhaling during the explosive jump phase"]', 'aa60f379-a493-46d2-8e03-3ba2277f3e78', 'star-jump-burpees', NULL, NULL);
INSERT INTO public.exercises VALUES ('f976571c-9374-49f4-8c60-8ed8fa9580bf', 'Étirement du bras supérieur droit', NULL, 'Stretch dyal l''dir3a l''aluya laiman', 'Posterior upper arm stretch (right)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/posterior-upper-arm-stretch-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/posterior-upper-arm-stretch-right.jpg', NULL, '["Gardez votre tête en position neutre sans la pousser en avant", "N''appliquez qu''une pression légère, ne forcez pas l''étirement", "Tenez votre torse droit, évitez de vous pencher", "Concentrez-vous sur l''étirement des triceps à l''arrière de votre bras", "Arrêtez immédiatement si vous ressentez des douleurs au niveau de l''épaule"]', '["Pencher le corps en avant ou sur le côté", "Forcer l''étirement en ressentant une douleur aiguë"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "posterior upper arm stretch (right)"]', true, '2026-04-03 12:24:58.419722+00', '2026-04-03 12:24:58.419722+00', 'Adoptez une posture droite, pieds écartés à la largeur des hanches. Levez votre bras droit au-dessus de votre tête et pliez le coude pour amener votre main droite vers le haut de votre dos, entre vos omoplates. Utilisez votre main gauche pour tirer délicatement votre coude droit vers le centre de votre tête, en accentuant l''étirement à l''arrière de votre bras.', '["Pencher le corps en avant ou sur le côté", "Forcer l''étirement en ressentant une douleur aiguë"]', true, '["Stand with good posture and engage your core muscles", "Raise your right arm straight up overhead", "Bend your right elbow and let your right hand drop down behind your head toward your upper back", "Reach your left hand over and gently grasp your right elbow", "Apply gentle, steady pressure pulling the right elbow toward your head''s center", "Hold the stretch for 15-30 seconds while breathing normally"]', '["Adoptez une posture droite et engagez vos muscles abdominaux", "Levez votre bras droit bien au-dessus de votre tête", "Pliez votre coude droit et laissez votre main descendre derrière votre tête", "Prenez votre coude droit avec votre main gauche", "Appliquez une pression douce en tirant votre coude droit vers le haut", "Maintenez l''étirement pendant 15 à 30 secondes tout en respirant normalement"]', '["Gardez votre tête en position neutre sans la pousser en avant", "N''appliquez qu''une pression légère, ne forcez pas l''étirement", "Tenez votre torse droit, évitez de vous pencher", "Concentrez-vous sur l''étirement des triceps à l''arrière de votre bras", "Arrêtez immédiatement si vous ressentez des douleurs au niveau de l''épaule"]', '["Keep your head in neutral position and avoid pushing it forward during the stretch", "Apply only gentle pressure - never force the stretch or cause sharp pain", "Keep your torso upright and avoid leaning to compensate for tight muscles", "Focus on feeling the stretch along the triceps muscle at the back of your upper arm", "Stop immediately if you experience any shoulder joint discomfort"]', 'ded0fb25-cb67-47a2-9a29-23e7f14ae6ac', 'posterior-upper-arm-stretch-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('e6695ebe-bbc3-44a6-a9d5-6dc3c0120c68', 'Étirement du dos supérieur et des épaules (droite)', NULL, 'تمديد الظهر العلوي والأكتاف (الجانب الأيمن)', 'Upper back and shoulder stretch (right)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/upper-back-and-shoulder-stretch-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/upper-back-and-shoulder-stretch-right.jpg', NULL, '["Garde tes épaules au même niveau et évite de soulever celle du bras qui s''étire", "Applique une pression douce et constante, sans rebondissement ni forcer l''étirement", "Concentre-toi sur l''étirement des muscles du haut du dos et de l''épaule arrière", "Respire profondément tout au long de l''étirement pour aider les muscles à se détendre", "Arrête immédiatement si tu ressens une douleur aiguë ou une gêne"]', '["Ne pas relâcher complètement les épaules", "Forcer l''étirement au lieu de maintenir une pression douce"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "upper back and shoulder stretch (right)"]', true, '2026-04-03 12:24:59.810263+00', '2026-04-03 12:24:59.810263+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, et tends ton bras droit à hauteur d''épaule à travers ta poitrine. Exécution : Avec ta main gauche, tire doucement ton bras droit vers ton torse en gardant les épaules détendues, tout en ressentant l''étirement dans le haut de ton dos et ton épaule droite.', '["Ne pas relâcher complètement les épaules", "Forcer l''étirement au lieu de maintenir une pression douce"]', true, '["Stand with feet hip-width apart and maintain good posture with shoulders back", "Extend your right arm straight across your chest at shoulder height", "Place your left hand on your right elbow or forearm", "Gently pull your right arm toward your chest until you feel a comfortable stretch", "Hold the stretch while breathing normally and keeping your torso upright", "Release slowly and repeat on the opposite side"]', '["Tiens-toi avec les pieds écartés à la largeur des hanches et garde une bonne posture, les épaules en arrière", "Tends ton bras droit directement à travers ta poitrine à hauteur des épaules", "Place ta main gauche sur le coude ou l''avant-bras droit", "Tire doucement ton bras droit vers ta poitrine jusqu''à ressentir un étirement confortable", "Maintiens l''étirement en respirant normalement et en gardant le torse droit", "Relâche lentement et répète de l''autre côté"]', '["Garde tes épaules au même niveau et évite de soulever celle du bras qui s''étire", "Applique une pression douce et constante, sans rebondissement ni forcer l''étirement", "Concentre-toi sur l''étirement des muscles du haut du dos et de l''épaule arrière", "Respire profondément tout au long de l''étirement pour aider les muscles à se détendre", "Arrête immédiatement si tu ressens une douleur aiguë ou une gêne"]', '["Keep your shoulders level and avoid lifting the shoulder of the arm being stretched", "Apply gentle, steady pressure rather than bouncing or forcing the stretch", "Focus the stretch on your upper back and posterior shoulder muscles", "Breathe deeply throughout the stretch to help muscles relax", "Stop immediately if you feel any sharp pain or discomfort"]', '55a30378-1a97-47fd-9f63-0609de03e0b9', 'upper-back-and-shoulder-stretch-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('12ccedd7-05b6-4131-8c48-a45a595e626d', 'Get Ups avec Saut', NULL, 'Get Ups avec Saut', 'Get ups with Jump', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/get-ups-with-jump.mp4', NULL, NULL, NULL, '/videos/thumbnails/get-ups-with-jump.jpg', NULL, '["Contrôlez vos mouvements et évitez d''utiliser trop d''élan pour ne pas perdre l''équilibre.", "Atterrissez doucement du saut avec les genoux fléchis pour amortir l''impact et protéger vos articulations.", "Gardez votre sangle abdominale engagée tout au long du mouvement pour protéger votre bas du dos.", "Commencez lentement et concentrez-vous sur des transitions fluides entre chaque phase avant d''augmenter la vitesse.", "Arrêtez-vous immédiatement si vous ressentez des vertiges ou un inconfort pendant la phase de montée."]', '["Ne pas utiliser les mains quand vous vous levez.", "Oublier de garder le tronc engagé et la poitrine haute."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "get ups with jump"]', true, '2026-04-03 12:24:56.826614+00', '2026-04-03 12:24:56.826614+00', 'Allongez-vous sur le dos, bras le long du corps, jambes tendues. Puis, levez-vous sans vous servir des mains et réalisez immédiatement un saut vertical avec les bras au-dessus de la tête avant de revenir à la position de départ.', '["Ne pas utiliser les mains quand vous vous levez.", "Oublier de garder le tronc engagé et la poitrine haute."]', true, '["Lie flat on your back with arms relaxed at your sides and legs straight", "Engage your core and sit up by bringing your knees toward your chest while swinging your arms forward for momentum", "Rock forward and plant your feet firmly on the ground while maintaining balance", "Stand up completely without using your hands for assistance, keeping your chest up and core engaged", "Immediately perform a vertical jump, driving through your heels and reaching your arms overhead", "Land softly with bent knees and controlled descent back to the lying position"]', '["Allongez-vous sur le dos, bras détendus et jambes droites.", "Engagez votre sangle abdominale et levez-vous en amenant vos genoux vers la poitrine tout en balançant vos bras vers l''avant pour l''élan.", "Inclinez-vous en avant et plantez vos pieds fermement au sol tout en gardant l''équilibre.", "Levez-vous complètement sans utiliser vos mains, en gardant la poitrine haute et le tronc engagé.", "Réalisez immédiatement un saut vertical en poussant à travers vos talons et en levant les bras au-dessus de la tête.", "Atterrissez doucement avec les genoux fléchis et descendez de manière contrôlée jusqu''à la position allongée."]', '["Contrôlez vos mouvements et évitez d''utiliser trop d''élan pour ne pas perdre l''équilibre.", "Atterrissez doucement du saut avec les genoux fléchis pour amortir l''impact et protéger vos articulations.", "Gardez votre sangle abdominale engagée tout au long du mouvement pour protéger votre bas du dos.", "Commencez lentement et concentrez-vous sur des transitions fluides entre chaque phase avant d''augmenter la vitesse.", "Arrêtez-vous immédiatement si vous ressentez des vertiges ou un inconfort pendant la phase de montée."]', '["Keep movements controlled and avoid using excessive momentum that could cause you to lose balance", "Land softly from the jump with bent knees to absorb impact and protect your joints", "Maintain core engagement throughout the entire movement to protect your lower back", "Start slowly and focus on smooth transitions between each phase of the movement before increasing speed", "Stop immediately if you experience dizziness or discomfort during the getting up phase"]', '38530004-f20d-4895-8deb-ab02ebac1edf', 'get-ups-with-jump', NULL, NULL);
INSERT INTO public.exercises VALUES ('67453793-1903-43c2-850d-a56a1af63cd2', 'Demi-Lune (Côté Droit)', NULL, NULL, 'Half moon (right)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/half-moon-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-moon-right.jpg', NULL, '["Utilise un bloc sous ta main inférieure si nécessaire.", "Garde ta jambe de soutien solide avec un léger fléchissement au niveau du genou.", "Superpose tes hanches et tes épaules."]', '["Ne pas garder l''équilibre sur la jambe de soutien.", "Ne pas aligner les hanches et les épaules."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "half moon (right)"]', true, '2026-04-03 12:24:56.97178+00', '2026-04-03 12:24:56.97178+00', 'Position de départ : Tiens-toi droit, les pieds joints, les bras le long du corps. Fais un grand pas en arrière avec ton pied gauche, environ 1-1,5 mètre, en levant les bras au-dessus de ta tête. Exécution : Incline ton buste vers la droite tout en levant ta jambe gauche du sol, formant ainsi une ligne courbe partant de tes doigts de la main gauche jusqu''à ta jambe gauche, tout en gardant l''équilibre sur ta jambe droite.', '["Ne pas garder l''équilibre sur la jambe de soutien.", "Ne pas aligner les hanches et les épaules."]', true, '["From Triangle Pose, bend your front knee and place your front hand on the floor.", "Shift your weight onto your front foot and lift your back leg parallel to the floor.", "Open your top hip and extend your top arm toward the ceiling.", "Gaze up at your top hand if your balance allows."]', '["À partir de la position Triangle, plie ton genou avant et place ta main avant au sol.", "Transfère ton poids sur ton pied avant et lève ta jambe arrière à l''horizontale.", "Ouvre ta hanche supérieure et tends ton bras supérieur vers le plafond.", "Regarde ta main supérieure si ton équilibre le permet."]', '["Utilise un bloc sous ta main inférieure si nécessaire.", "Garde ta jambe de soutien solide avec un léger fléchissement au niveau du genou.", "Superpose tes hanches et tes épaules."]', '["Use a block under your bottom hand if needed.", "Keep your standing leg strong with a micro-bend in the knee.", "Stack your hips and shoulders."]', '0852e58d-42d4-4e7a-b612-a6d79e93e895', 'half-moon-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('db23e2ec-23b4-47a1-96f7-00b5bba28548', 'Soulevé de Terre avec Barbell', NULL, 'رفع الحديد', 'Barbell Deadlift', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 1, '/videos/bodyweight/barbell-deadlift.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-deadlift.jpg', NULL, '["Maintiens une colonne vertébrale neutre pendant tout le mouvement pour éviter les blessures au dos", "Garde la barre le plus près possible de ton corps durant les phases de levée et de descente", "Engage tes muscles abdominaux et garde les épaules tirées en arrière et vers le bas", "Commence avec un poids léger pour maîtriser la forme avant de progresser vers des charges plus lourdes", "Évite de courber le dos ou de laisser les genoux s''effondrer pendant le levé."]', '["Ne pas garder le dos droit", "Laisser les genoux s''écarter pendant la montée"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "barbell", "barbell deadlift"]', true, '2026-04-03 12:24:55.54686+00', '2026-04-03 12:24:55.54686+00', 'Mets-toi en position, les pieds écartés à la largeur des épaules, la barre devant tes cuisses. En avant, incline ton corps en gardant le dos droit et les genoux légèrement fléchis. Remonte lentement à la position de départ.', '["Ne pas garder le dos droit", "Laisser les genoux s''écarter pendant la montée"]', true, '["Position your feet hip-width apart with the barbell over the middle of your feet", "Hinge at the hips and bend your knees to grip the bar with hands just outside your legs", "Keep your chest up, shoulders back, and maintain a neutral spine throughout the movement", "Drive through your heels and push the floor away as you stand up, extending hips and knees together", "Keep the bar close to your body as it travels up your shins and thighs", "Lower the weight by pushing your hips back first, then bending your knees once the bar passes them"]', '["Place tes pieds à la largeur des hanches, la barre au-dessus du milieu de tes pieds", "Incline-toi au niveau des hanches et plie les genoux pour saisir la barre avec les mains juste à l''extérieur de tes jambes", "Garde la poitrine haute, les épaules en arrière et maintiens une colonne vertébrale neutre durant tout le mouvement", "Pousse à travers tes talons et repousse le sol pour te lever, en étendant simultanément les hanches et les genoux", "Garde la barre proche de ton corps pendant qu''elle remonte le long de tes tibias et cuisses", "Redescends la barre en déplaçant d''abord tes hanches en arrière, puis plie les genoux une fois que la barre les a franchis."]', '["Maintiens une colonne vertébrale neutre pendant tout le mouvement pour éviter les blessures au dos", "Garde la barre le plus près possible de ton corps durant les phases de levée et de descente", "Engage tes muscles abdominaux et garde les épaules tirées en arrière et vers le bas", "Commence avec un poids léger pour maîtriser la forme avant de progresser vers des charges plus lourdes", "Évite de courber le dos ou de laisser les genoux s''effondrer pendant le levé."]', '["Maintain a neutral spine throughout the entire movement to prevent back injury", "Keep the barbell as close to your body as possible during both the lifting and lowering phases", "Engage your core muscles and keep your shoulders pulled back and down", "Start with lighter weight to master proper form before progressing to heavier loads", "Avoid rounding your back or letting your knees cave inward during the lift"]', '7d31d648-432b-4edd-97bc-afc2a3e9e59a', 'barbell-deadlift', NULL, NULL);
INSERT INTO public.exercises VALUES ('eda12f41-9c0b-416b-9f29-a44805d273ad', 'Renforce ton torse et tes épaules !', NULL, NULL, 'Chest and shoulder', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/chest-and-shoulder.mp4', NULL, NULL, NULL, '/videos/thumbnails/chest-and-shoulder.jpg', NULL, '["Éloigne tes épaules de tes oreilles pour éviter les tensions", "Engage ton core durant tout l''exercice pour protéger ton bas du dos", "Respire régulièrement sans bloquer ta respiration", "Garde la poitrine ouverte et évite d''arrondir tes épaules", "Place tes mains confortablement pour une bonne alignement des poignets"]', '["Ne pas engager le core, ce qui peut causer des douleurs lombaires", "Arquer le dos au lieu de garder une posture droite"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "chest and shoulder"]', true, '2026-04-03 12:24:56.074415+00', '2026-04-03 12:24:56.074415+00', 'Position de départ : Assieds-toi sur un tapis, les genoux fléchis et les pieds bien à plat. Incline-toi légèrement en arrière, les mains posées derrière toi pour te soutenir. Maintiens cette position tout en gardant une bonne posture et respire calmement.', '["Ne pas engager le core, ce qui peut causer des douleurs lombaires", "Arquer le dos au lieu de garder une posture droite"]', true, '["Sit on a mat with your knees bent and feet flat on the floor", "Place your hands behind you on the mat with fingers pointing away from your body", "Lean back slightly while keeping your chest open and shoulders down", "Engage your core muscles to maintain stability", "Keep your feet firmly planted on the ground", "Breathe steadily while holding the position"]', '["Assieds-toi sur un tapis avec les genoux fléchis et les pieds à plat au sol", "Place tes mains derrière toi sur le tapis, les doigts tournés vers l''extérieur", "Incline-toi légèrement en arrière en gardant la poitrine ouverte et les épaules basses", "Engage tes muscles du ventre pour maintenir la stabilité", "Garde tes pieds bien ancrés au sol", "Respire calmement tout en maintenant la position"]', '["Éloigne tes épaules de tes oreilles pour éviter les tensions", "Engage ton core durant tout l''exercice pour protéger ton bas du dos", "Respire régulièrement sans bloquer ta respiration", "Garde la poitrine ouverte et évite d''arrondir tes épaules", "Place tes mains confortablement pour une bonne alignement des poignets"]', '["Keep your shoulders away from your ears to avoid tension", "Engage your core throughout the exercise to protect your lower back", "Maintain steady breathing rather than holding your breath", "Keep your chest open and avoid rounding your shoulders forward", "Place hands in a comfortable position that allows proper wrist alignment"]', '9225c7c5-66a0-42c5-8de4-866389741736', 'chest-and-shoulder', NULL, NULL);
INSERT INTO public.exercises VALUES ('bc84e26e-40d2-47db-9187-b7332e74ec9d', 'Curl avec Barre', NULL, 'باريبل كيرلز', 'Barbell Curls', 'Biceps', '[]', 'Biceps', 'Beginner', 1, NULL, NULL, NULL, NULL, NULL, NULL, '["Garde les coudes près du corps", "Ne balance pas et n''utilise pas d''élan", "Assure-toi d''une extension complète en bas", "Concentre-toi sur la contraction maximale en haut", "Maintiens les poignets droits"]', '["Balançage du corps pour soulever la barre", "Ne pas contrôler la descente", "Utilisation d''une prise trop large ou trop étroite"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "barbell", "barbell curls"]', true, '2026-04-03 12:24:55.539713+00', '2026-04-03 12:24:55.539713+00', 'Position de départ : Tiens-toi bien droit, les pieds à la largeur des épaules, la barre à bout de bras devant tes cuisses. Execution : Enfléchis les biceps pour amener la barre vers tes épaules, jusqu''à ce que tes avant-bras touchent tes biceps. Redescends lentement à la position de départ. Fais-le avec puissance et contrôle !', '["Balançage du corps pour soulever la barre", "Ne pas contrôler la descente", "Utilisation d''une prise trop large ou trop étroite"]', true, '["Stand holding bar with underhand grip", "Arms at sides, shoulder-width grip", "Curl bar toward shoulders", "Squeeze biceps at top", "Lower with control"]', '["Tire la barre avec une prise en supination", "Les bras le long du corps, prise à la largeur des épaules", "Amène la barre vers tes épaules", "Contracte bien les biceps en haut du mouvement", "Redescends doucement et contrôlé"]', '["Garde les coudes près du corps", "Ne balance pas et n''utilise pas d''élan", "Assure-toi d''une extension complète en bas", "Concentre-toi sur la contraction maximale en haut", "Maintiens les poignets droits"]', '["Keep elbows at sides", "Don''t swing or use momentum", "Full extension at bottom", "Full contraction at top", "Keep wrists straight"]', '1158c681-55e9-4db0-bb73-3dab32d99aa5', 'barbell-curls', NULL, NULL);
INSERT INTO public.exercises VALUES ('f6ac467b-81cc-44ca-9815-cef329543b23', 'Tirage assis à un bras avec câble', NULL, NULL, 'Single Arm Seated Cable Row', 'Back', '[]', 'Back', 'Intermediate', 4, '/videos/back/single-arm-seated-cable-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-seated-cable-row.jpg', NULL, '["Garde le torse droit tout au long du mouvement pour éviter les douleurs lombaires", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec ton bras en menant avec le coude", "Évite de faire pivoter ton torse ou d''utiliser l''élan pour finir la répétition", "Maintiens une position neutre pour ton poignet et une prise ferme sur la poigne", "Termine toutes les répétitions d''un côté avant de passer à l''autre pour garantir une bonne forme et une activation musculaire."]', '["Rotations du torse lors du tirage", "Utilisation de l''élan au lieu de muscle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "single arm seated cable row"]', true, '2026-04-03 12:24:59.220851+00', '2026-04-03 12:24:59.220851+00', 'Position de départ : Assis au bas d''une machine à câble avec une poigne dans une main. Exécution : Tire la poigne vers le côté de ton abdomen, garde le torse droit, puis retourne lentement à la position de départ et répète avec l''autre bras.', '["Rotations du torse lors du tirage", "Utilisation de l''élan au lieu de muscle"]', true, '["Adjust the cable height to chest level and select an appropriate weight", "Sit with feet flat on the platform and knees slightly bent for stability", "Grasp the handle with your working arm while keeping your non-working hand on your thigh for support", "Initiate the pull by retracting your shoulder blade first, then drive your elbow straight back", "Squeeze your back muscles at the peak contraction when the handle reaches your ribs", "Control the weight back to the starting position, allowing a full stretch in your lat"]', '["Régle la hauteur du câble au niveau de ta poitrine et choisis un poids approprié", "Assieds-toi avec les pieds bien à plat sur la plateforme et les genoux légèrement fléchis pour la stabilité", "Saisis la poigne avec ton bras actif tout en gardant l''autre main sur ta cuisse pour le support", "Commence le tirage en rétractant d''abord ton scapula, puis pousse ton coude vers l''arrière", "Contracte bien les muscles du dos au maximum quand la poigne atteint tes côtes", "Contrôle la descente du poids jusqu''à la position de départ, en permettant à ton lat de s''étirer complètement."]', '["Garde le torse droit tout au long du mouvement pour éviter les douleurs lombaires", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec ton bras en menant avec le coude", "Évite de faire pivoter ton torse ou d''utiliser l''élan pour finir la répétition", "Maintiens une position neutre pour ton poignet et une prise ferme sur la poigne", "Termine toutes les répétitions d''un côté avant de passer à l''autre pour garantir une bonne forme et une activation musculaire."]', '["Keep your torso upright throughout the movement to prevent lower back strain", "Focus on pulling with your back muscles rather than your arm by leading with your elbow", "Avoid rotating your torso or using momentum to complete the repetition", "Maintain a neutral wrist position and firm grip on the handle", "Complete all repetitions on one side before switching to maintain proper form and muscle activation"]', '7dd83ed0-59e0-4339-a54a-d3319bdf00ab', 'single-arm-seated-cable-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('bf4b4e6e-da7c-4980-960e-0234117f4e22', 'Élévations Arrière avec Haltères', NULL, NULL, 'Bent Over Dumbbell Reverse Fly', 'Shoulders', '[]', 'Shoulders', 'Beginner', 2, '/videos/shoulders/bent-over-dumbbell-reverse-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-over-dumbbell-reverse-fly.jpg', NULL, '["Garde ton ventre engagé pendant tout le mouvement pour protéger ton bas du dos.", "Concentre-toi sur la contraction de tes omoplates plutôt que de simplement lever les poids.", "Utilise un rythme contrôlé avec une levée de 2 secondes et une descente de 3 secondes.", "Évite d''utiliser l''élan ou de balancer les poids.", "Commence avec des poids légers pour maîtriser la technique avant de passer à des charges plus lourdes."]', '["Ne pas garder le dos droit pendant l''exercice.", "Levée des poids avec les bras au lieu de contracter les omoplates."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "bent over dumbbell reverse fly"]', true, '2026-04-03 12:24:55.745074+00', '2026-04-03 12:24:55.745074+00', 'Position de départ : Tiens-toi debout, penche le torse en avant et prends un haltère dans chaque main, paumes tournées vers l’intérieur. Exécution : Élève les haltères sur les côtés jusqu''à atteindre la hauteur des épaules, puis redescends lentement.', '["Ne pas garder le dos droit pendant l''exercice.", "Levée des poids avec les bras au lieu de contracter les omoplates."]', true, '["Stand with feet hip-width apart holding a dumbbell in each hand with palms facing each other", "Hinge forward at the hips about 45 degrees while maintaining a neutral spine and slight bend in the knees", "Allow the dumbbells to hang naturally below your chest with arms slightly bent", "Raise the dumbbells out to the sides in a wide arc until your arms are parallel to the floor", "Squeeze your shoulder blades together at the top of the movement", "Slowly lower the weights back to the starting position with control"]', '["Tiens-toi debout, pieds écartés à la largeur des hanches, un haltère dans chaque main, paumes face à face.", "Incline-toi en avant à 45 degrés au niveau des hanches tout en gardant une colonne vertébrale neutre et les genoux légèrement fléchis.", "Laisse les haltères pendre naturellement sous ta poitrine avec les bras légèrement fléchis.", "Lève les haltères sur les côtés en un arc large jusqu''à ce que tes bras soient parallèles au sol.", "Contracte les omoplates au sommet du mouvement.", "Redescends lentement les poids à la position de départ en contrôlant le mouvement."]', '["Garde ton ventre engagé pendant tout le mouvement pour protéger ton bas du dos.", "Concentre-toi sur la contraction de tes omoplates plutôt que de simplement lever les poids.", "Utilise un rythme contrôlé avec une levée de 2 secondes et une descente de 3 secondes.", "Évite d''utiliser l''élan ou de balancer les poids.", "Commence avec des poids légers pour maîtriser la technique avant de passer à des charges plus lourdes."]', '["Keep your core engaged throughout the movement to protect your lower back", "Focus on squeezing your shoulder blades together rather than just lifting the weights", "Use a controlled tempo with a 2-second lift and 3-second lowering phase", "Avoid using momentum or swinging the weights up", "Start with lighter weights to master the form before progressing to heavier loads"]', '7ab0bece-90eb-45f1-9b22-3fd86c376aa1', 'bent-over-dumbbell-reverse-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('f233f670-f2d6-47bf-b1ef-7f7f9a389885', 'Superman Crunch', NULL, 'سوبر مان كرانش', 'Super man crunches', 'Abs', '[]', 'Abs', 'Intermediate', 16, NULL, NULL, NULL, NULL, '/videos/thumbnails/super-man-crunches.jpg', NULL, '["Garde ton cou dans l''alignement neutre en regardant vers le sol plutôt qu''en relevant la tête", "Concentre-toi sur la contraction de tes fessiers et l''engagement de l''ensemble de ton cœur pendant le mouvement", "Évite d''utiliser l''élan - exécute l''exercice avec des mouvements lents et contrôlés", "Commence par des amplitudes de mouvement plus petites et augmente graduellement à mesure que ta force s''améliore", "Arrête-toi immédiatement si tu ressens des douleurs ou un inconfort dans le bas du dos"]', '["Soulever la tête trop haut et compromettre l''alignement du cou", "Utiliser l''élan au lieu de la force musculaire pour exécuter le mouvement", "Ne pas activer les fessiers et le core pour maintenir une bonne posture"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "super man crunches"]', true, '2026-04-03 12:24:59.667071+00', '2026-04-03 12:24:59.667071+00', 'Position de départ : Allonge-toi sur le ventre, bras tendus devant toi et jambes droites, formant une ligne droite des doigts de la main jusqu''aux orteils. Exécution : Soulève simultanément ta poitrine, tes bras et tes jambes du sol tout en ramenant tes genoux vers tes coudes dans un mouvement de crunch, puis retourne à la position de départ.', '["Soulever la tête trop haut et compromettre l''alignement du cou", "Utiliser l''élan au lieu de la force musculaire pour exécuter le mouvement", "Ne pas activer les fessiers et le core pour maintenir une bonne posture"]', true, '["Lie face down on a mat with arms fully extended overhead and legs straight", "Engage your core and glutes before beginning the movement", "Simultaneously lift your chest, arms, and legs off the ground as high as comfortably possible", "Draw your knees toward your elbows while crunching your torso", "Hold the contracted position briefly, then slowly lower back to the starting position", "Repeat for the desired number of repetitions while maintaining control throughout"]', '["Allonge-toi sur un tapis face contre terre, les bras bien tendus en avant et les jambes droites", "Active ton cœur et tes fessiers avant de commencer le mouvement", "Soulève ton torse, tes bras et tes jambes du sol aussi haut que possible", "Rapproche tes genoux de tes coudes tout en crunchant ton torse", "Maintiens la position contractée brièvement, puis redescends lentement à la position de départ", "Répète pour le nombre de répétitions désiré en gardant le contrôle tout au long de l''exercice"]', '["Garde ton cou dans l''alignement neutre en regardant vers le sol plutôt qu''en relevant la tête", "Concentre-toi sur la contraction de tes fessiers et l''engagement de l''ensemble de ton cœur pendant le mouvement", "Évite d''utiliser l''élan - exécute l''exercice avec des mouvements lents et contrôlés", "Commence par des amplitudes de mouvement plus petites et augmente graduellement à mesure que ta force s''améliore", "Arrête-toi immédiatement si tu ressens des douleurs ou un inconfort dans le bas du dos"]', '["Keep your neck in neutral alignment by looking down at the floor rather than lifting your head", "Focus on squeezing your glutes and engaging your entire core throughout the movement", "Avoid using momentum - perform the exercise with slow, controlled movements", "Start with smaller ranges of motion and gradually increase as your strength improves", "Stop immediately if you experience any lower back pain or discomfort"]', '4aa2b90d-e5da-47d6-abd5-4e1932324ed2', 'super-man-crunches', NULL, NULL);
INSERT INTO public.exercises VALUES ('749cadf8-c328-4c42-82d9-bb53b9185787', 'Curl Biceps à la Câble Bas', NULL, 'تدوير العضلات', 'Standing Low Cable Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 4, '/videos/biceps/standing-low-cable-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-low-cable-curl.jpg', NULL, '["Gardez vos coudes fixes durant tout le mouvement pour bien cibler les biceps", "Maintenez une tension constante sur le câble sans laisser le poids reposer entre les répétitions", "Utilisez un tempo contrôlé : 2 secondes pour soulever, 3 secondes pour abaisser", "Évitez de balancer votre corps ou d''utiliser l''élan pour soulever la charge", "Gardez les poignets droits et alignés avec vos avant-bras pour éviter les blessures"]', '["Balançage du corps pendant l''exercice", "Laisser le poids reposer entre les répétitions"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "cable", "standing low cable curl"]', true, '2026-04-03 12:24:59.565771+00', '2026-04-03 12:24:59.565771+00', 'Position de départ : Tenez-vous face à un câble bas avec une barre droite attachée. Exécution : Pliez les coudes pour soulever la barre vers vos épaules, puis abaissez-la lentement.', '["Balançage du corps pendant l''exercice", "Laisser le poids reposer entre les répétitions"]', true, '["Set the cable pulley to the lowest position and attach a straight bar or EZ-curl bar", "Stand 2-3 feet away from the machine with feet shoulder-width apart and core engaged", "Grasp the attachment with an underhand grip, hands about shoulder-width apart", "Keep your elbows close to your sides and curl the weight up until your biceps are fully contracted", "Squeeze your biceps at the top of the movement for a brief pause", "Slowly lower the weight back to the starting position with control"]', '["Ajustez le câble à la position la plus basse et attachez une barre droite ou une barre EZ-go", "Tenez-vous à 60-90 cm de la machine, les pieds écartés à la largeur des épaules et le tronc engagé", "Saisissez la barre avec une prise en supination, les mains à la largeur des épaules", "Gardez les coudes près des flancs et faites monter le poids jusqu''à contraction maximale des biceps", "Contractez vos biceps en haut du mouvement et marquez une courte pause", "Abaissez lentement le poids jusqu''à la position de départ en contrôlant le mouvement"]', '["Gardez vos coudes fixes durant tout le mouvement pour bien cibler les biceps", "Maintenez une tension constante sur le câble sans laisser le poids reposer entre les répétitions", "Utilisez un tempo contrôlé : 2 secondes pour soulever, 3 secondes pour abaisser", "Évitez de balancer votre corps ou d''utiliser l''élan pour soulever la charge", "Gardez les poignets droits et alignés avec vos avant-bras pour éviter les blessures"]', '["Keep your elbows stationary throughout the entire movement to isolate the biceps effectively", "Maintain constant tension on the cable by not allowing the weight stack to rest between repetitions", "Use a controlled tempo with a 2-second lift and 3-second lowering phase", "Avoid swinging your body or using momentum to lift the weight", "Keep your wrists straight and in line with your forearms to prevent strain"]', 'bfa76dd0-298b-4c70-b1fa-e662289d2ebe', 'standing-low-cable-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('1469d1be-f34c-4957-862c-d793be9cef49', 'Roll-out avec barre à genoux', NULL, NULL, 'Barbell Ab Rollout - On Knees', 'Abs', '[]', 'Abs', 'Intermediate', 1, '/videos/abs/barbell-ab-rollout-on-knees.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-ab-rollout-on-knees.jpg', NULL, '["Garde ton cœur engagé pendant tout le mouvement pour éviter une hyperextension du bas du dos", "N’allez pas trop loin si tu ne peux pas maintenir une bonne forme et un contrôle", "Évite que tes hanches ne s’affaissent ou ne se relèvent pendant l’exercice", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur la vitesse ou l''amplitude", "Arrête immédiatement si tu ressens une douleur ou une gêne dans le bas du dos"]', '["Laisser le dos s''affaisser pendant le mouvement", "Ne pas contracter suffisamment les abdos pour contrôler le retour"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "barbell", "barbell ab rollout - on knees"]', true, '2026-04-03 12:24:55.511433+00', '2026-04-03 12:24:55.511433+00', 'Position de départ : À genoux sur le sol, le barbell devant toi. Prends la barre avec les deux mains, les bras tendus, écartement des épaules. Exécution : Fais rouler la barre vers l''avant en étendant les hanches et les épaules, garde une ligne droite des genoux à la tête. Reviens à la position initiale en utilisant tes muscles abdominaux.', '["Laisser le dos s''affaisser pendant le mouvement", "Ne pas contracter suffisamment les abdos pour contrôler le retour"]', true, '["Kneel on a mat or soft surface with the barbell positioned directly in front of your knees", "Grip the barbell with both hands using an overhand grip, hands placed shoulder-width apart", "Engage your core and maintain a neutral spine before beginning the movement", "Roll the barbell forward slowly by extending at the hips and shoulders, keeping arms straight", "Lower your body until you feel a strong stretch in your abs, stopping before your hips sag", "Pull the barbell back toward your knees by contracting your core muscles and reversing the movement"]', '["À genoux sur un tapis ou une surface douce, place la barre à roulettes directement devant tes genoux", "Saisis la barre avec les deux mains en prise pronation, les mains à la largeur des épaules", "Active ton cœur et maintiens une colonne vertébrale neutre avant de commencer le mouvement", "Fais rouler la barre lentement vers l''avant en fléchissant les hanches et les épaules, les bras restent droits", "Abaisse ton corps jusqu''à sentir un bon étirement dans tes abdos, en t''arrêtant avant que tes hanches ne s''affaissent", "Tire la barre vers tes genoux en contractant tes muscles du tronc et en inversant le mouvement"]', '["Garde ton cœur engagé pendant tout le mouvement pour éviter une hyperextension du bas du dos", "N’allez pas trop loin si tu ne peux pas maintenir une bonne forme et un contrôle", "Évite que tes hanches ne s’affaissent ou ne se relèvent pendant l’exercice", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur la vitesse ou l''amplitude", "Arrête immédiatement si tu ressens une douleur ou une gêne dans le bas du dos"]', '["Keep your core tight throughout the entire movement to prevent lower back hyperextension", "Only roll out as far as you can while maintaining proper form and control", "Avoid letting your hips sag or pike up during the exercise", "Focus on slow, controlled movements rather than speed or range of motion", "Stop immediately if you feel any lower back pain or discomfort"]', '31a0d4f4-2ad8-4f51-b47f-e7dc05e787f3', 'barbell-ab-rollout-on-knees', NULL, NULL);
INSERT INTO public.exercises VALUES ('3518be34-3fde-4e2c-a136-611f90ecf2d8', 'Curl Marteau au Pupitre', NULL, 'Curl Marteau', 'Preacher Hammer Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/preacher-hammer-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/preacher-hammer-curl.jpg', NULL, '["Garde ton poignet dans une position neutre pendant tout le mouvement pour éviter les tensions", "Assure-toi que ta poitrine reste en contact avec le coussin du pupitre pour garantir un bon positionnement et un soutien adéquat", "Contrôle la phase descendante du mouvement pour maximiser l''engagement musculaire et prévenir les blessures", "Évite de verrouiller complètement ton coude en bas pour garder une tension continue sur le biceps", "Choisis un poids qui te permet de maintenir la bonne forme sur l''ensemble du mouvement"]', '["Lâcher le contact entre la poitrine et le coussin", "Avancer le coude au lieu de le maintenir stationnaire"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "preacher hammer curl"]', true, '2026-04-03 12:24:58.451382+00', '2026-04-03 12:24:58.451382+00', 'Position initiale : Assieds-toi sur un banc à pupitre, poitrine contre le coussin, avec un haltère en prise neutre, bras tendu vers le bas sur le coussin incliné. Exécution : Enroule l''haltère vers le haut en fléchissant ton biceps tout en gardant la prise neutre, puis baisse-le lentement à la position de départ.', '["Lâcher le contact entre la poitrine et le coussin", "Avancer le coude au lieu de le maintenir stationnaire"]', true, '["Position yourself at the preacher bench with your chest firmly against the pad and feet flat on the floor", "Hold the dumbbell with a neutral grip (thumb up) and place your arm against the angled pad with a slight bend in your elbow", "Slowly curl the weight up by contracting your bicep, keeping your wrist straight and grip neutral throughout", "Squeeze your bicep at the top of the movement for a brief pause", "Lower the dumbbell back down in a controlled manner, maintaining tension in the muscle", "Stop just short of full arm extension to keep constant tension on the bicep"]', '["Installe-toi sur le banc à pupitre, poitrine bien maintenue contre le coussin, pieds à plat au sol", "Saisis l''haltère avec une prise neutre (pouce vers le haut) et place ton bras sur le coussin incliné avec une légère flexion au niveau du coude", "Enroule lentement le poids vers le haut en contractant ton biceps, garde le poignet droit et la prise neutre", "Sers ton biceps au sommet du mouvement en marquant une courte pause", "Redescends l''haltère de manière contrôlée, en maintenant la tension dans le muscle", "Stoppe juste avant l''extension totale du bras pour conserver la tension sur le biceps"]', '["Garde ton poignet dans une position neutre pendant tout le mouvement pour éviter les tensions", "Assure-toi que ta poitrine reste en contact avec le coussin du pupitre pour garantir un bon positionnement et un soutien adéquat", "Contrôle la phase descendante du mouvement pour maximiser l''engagement musculaire et prévenir les blessures", "Évite de verrouiller complètement ton coude en bas pour garder une tension continue sur le biceps", "Choisis un poids qui te permet de maintenir la bonne forme sur l''ensemble du mouvement"]', '["Keep your wrist in a neutral position throughout the entire movement to prevent strain", "Maintain contact between your chest and the preacher pad to ensure proper positioning and support", "Control the eccentric (lowering) portion of the movement to maximize muscle engagement and prevent injury", "Avoid letting your elbow completely lock out at the bottom to maintain continuous tension on the bicep", "Use a weight that allows you to maintain proper form throughout the entire range of motion"]', '554adc08-afea-40c8-bf33-d4276e2d73d9', 'preacher-hammer-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('86ac7ecc-066c-4be5-b723-b93bd610ee1a', 'Barbell Curl 21s', NULL, 'بربل كيرل 21', 'Barbell Curl 21s', 'Biceps', '[]', 'Biceps', 'Intermediate', 1, '/videos/biceps/barbell-curl-21s.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-curl-21s.jpg', NULL, '["Garde les poignets droits et une prise ferme pour éviter que la barre ne glisse dans tes mains.", "Concentre-toi sur la contraction des biceps en haut de chaque répétition, surtout durant les contractions partielles et complètes.", "Évite de te pencher en arrière ou de bouger ton corps pour soulever le poids, cela réduira l''activation de tes biceps.", "Contrôle bien la phase négative de chaque répétition au lieu de laisser tomber rapidement le poids.", "C''est une technique avancée qui crée une fatigue musculaire significative, n''hésite pas à réduire le poids comparé aux curls barbell standards."]', '["Laisser les coudes s''écarter des côtés, ce qui diminue l''efficacité de l''exercice.", "Se balancer ou utiliser l''élan pour soulever la barre, ce qui réduit l''activation musculaire."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "barbell", "barbell curl 21s"]', true, '2026-04-03 12:24:55.53532+00', '2026-04-03 12:24:55.53532+00', 'Prépare-toi à sculpter tes biceps avec cet exercice ciblé. Le Barbell Curl 21s est une méthode puissante pour intensifier ton entraînement et bâtir du muscle !', '["Laisser les coudes s''écarter des côtés, ce qui diminue l''efficacité de l''exercice.", "Se balancer ou utiliser l''élan pour soulever la barre, ce qui réduit l''activation musculaire."]', true, '["Stand upright with core engaged and shoulders back, gripping the barbell with palms facing forward", "Keep elbows close to your sides throughout all three phases of the exercise", "First, perform 7 reps curling only from full extension to 90 degrees (bottom half)", "Immediately perform 7 reps curling from 90 degrees to full contraction (top half)", "Finish with 7 complete full range-of-motion reps from bottom to top", "Maintain controlled tempo and avoid swinging or using momentum throughout all 21 repetitions"]', '["Tiens-toi bien droit, engage ton tronc et ramène les épaules en arrière tout en tenant la barre EZ avec les paumes vers l''avant.", "Garde les coudes près des côtes tout au long des trois phases de l''exercice.", "D''abord, fais 7 reps en curlant uniquement de l''extension complète à 90 degrés (la moitié inférieure).", "Ensuite, effectue immédiatement 7 reps en curlant de 90 degrés jusqu''à la contraction complète (la moitié supérieure).", "Termine avec 7 répétitions en pleine amplitude, du bas vers le haut.", "Maintiens un tempo contrôlé, évite de balancer ou d''utiliser l''élan durant toutes les 21 répétitions."]', '["Garde les poignets droits et une prise ferme pour éviter que la barre ne glisse dans tes mains.", "Concentre-toi sur la contraction des biceps en haut de chaque répétition, surtout durant les contractions partielles et complètes.", "Évite de te pencher en arrière ou de bouger ton corps pour soulever le poids, cela réduira l''activation de tes biceps.", "Contrôle bien la phase négative de chaque répétition au lieu de laisser tomber rapidement le poids.", "C''est une technique avancée qui crée une fatigue musculaire significative, n''hésite pas à réduire le poids comparé aux curls barbell standards."]', '["Keep wrists straight and maintain a firm grip to prevent the barbell from rolling in your hands", "Focus on squeezing the biceps at the top of each rep, especially during the partial and full contractions", "Avoid leaning back or swaying your body to lift the weight as this reduces bicep activation", "Control the negative portion of each rep rather than letting the weight drop quickly", "This is an advanced technique that creates significant muscle fatigue, so reduce weight compared to standard barbell curls"]', '71cd3500-6a12-4ad9-b9c4-5b4c20f33deb', 'barbell-curl-21s', NULL, NULL);
INSERT INTO public.exercises VALUES ('3631aee7-fe41-4114-9c91-98e22c2b6fd8', 'Hip Thrust avec Barre', NULL, NULL, 'Barbell Hip Thrust', 'Glutes', '[]', 'Glutes', 'Beginner', 1, '/videos/glutes/barbell-hip-thrust.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-hip-thrust.jpg', NULL, '["Mets un coussin sur la barre pour plus de confort", "En garde le menton légèrement rentré", "Pousse avec les talons", "Extension complète des hanches en haut", "Ne cambrer pas le bas du dos"]', '["Ne pas contracter les fessiers", "Soulever trop haut en cambrant le dos", "Ne pas contrôler la descente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "barbell", "barbell hip thrust"]', true, '2026-04-03 12:24:55.586488+00', '2026-04-03 12:24:55.586488+00', 'Allonge-toi sur le dos en posant ta nuque sur le banc, les pieds bien à plat au sol. Prêt ? Bosse tes fessiers ! Remonte tes hanches en contractant tes muscles, puis redescends lentement. Répète et sens la brûlure !', '["Ne pas contracter les fessiers", "Soulever trop haut en cambrant le dos", "Ne pas contrôler la descente"]', true, '["Upper back on bench, bar over hips", "Feet flat on floor, knees bent", "Drive hips up by squeezing glutes", "Form straight line from shoulders to knees", "Lower with control"]', '["Haut du dos sur le banc, barre au-dessus des hanches", "Pieds à plat sur le sol, genoux pliés", "Pousse les hanches vers le haut en contractant les fessiers", "Ligne droite des épaules aux genoux", "Descends avec contrôle"]', '["Mets un coussin sur la barre pour plus de confort", "En garde le menton légèrement rentré", "Pousse avec les talons", "Extension complète des hanches en haut", "Ne cambrer pas le bas du dos"]', '["Pad the bar for comfort", "Chin slightly tucked", "Drive through heels", "Full hip extension at top", "Don''t hyperextend lower back"]', '5990deac-a91d-4531-8c2f-a708fc95fd1f', 'barbell-hip-thrust', NULL, NULL);
INSERT INTO public.exercises VALUES ('c1cf66d3-12e0-4b8c-a2b9-5ec484c75a80', 'Curl Concentré avec Haltère', NULL, NULL, 'Concentration Hammer Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 2, '/videos/biceps/concentration-hammer-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/concentration-hammer-curl.jpg', NULL, '["Garde ton poignet dans une position neutre pour éviter les tensions", "Concentre-toi sur des mouvements lents et contrôlés au lieu d''utiliser l''élan pour soulever le poids", "Maintiens la position de ton coude contre ta cuisse pour isoler le bicep et éviter de balancer", "Ne laisse pas ton épaule rouler vers l''avant pendant le curl - garde la poitrine haute et les épaules en arrière", "Expire pendant la phase de levée et inspire pendant la phase de descente."]', '["Utiliser l''élan au lieu d''une contraction contrôlée", "Laisser le coude s''éloigner de la cuisse durant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "concentration hammer curl"]', true, '2026-04-03 12:24:56.148333+00', '2026-04-03 12:24:56.148333+00', 'Position de départ : Assieds-toi au bord d''un banc avec un haltère dans une main, ton bras reposant sur ta cuisse. Exécution : Fléchis ton coude pour soulever l’haltère vers ton épaule, puis redescends-le de manière contrôlée.', '["Utiliser l''élan au lieu d''une contraction contrôlée", "Laisser le coude s''éloigner de la cuisse durant le mouvement"]', true, '["Sit on the edge of a bench with your feet firmly planted on the floor about shoulder-width apart", "Hold a dumbbell in one hand with a neutral grip, palm facing inward", "Rest your working arm''s elbow against the inside of your same-side thigh for support", "Curl the weight up in a controlled motion, focusing on contracting the bicep", "Squeeze at the top of the movement, then slowly lower the dumbbell back to the starting position", "Complete all repetitions on one arm before switching to the other side"]', '["Assieds-toi au bord d''un banc, les pieds bien à plat sur le sol, écartés à la largeur des épaules", "Tiens un haltère dans une main avec une prise neutre, paume dirigée vers l''intérieur", "Appuie le coude de ton bras actif contre l''intérieur de ta cuisse du même côté pour avoir du soutien", "Soulève le poids en effectuant un mouvement contrôlé, en te concentrant sur la contraction du bicep", "Contracte au sommet du mouvement, puis redescends lentement l’haltère à la position initiale", "Complète toutes les répétitions d''un côté avant de passer à l''autre bras."]', '["Garde ton poignet dans une position neutre pour éviter les tensions", "Concentre-toi sur des mouvements lents et contrôlés au lieu d''utiliser l''élan pour soulever le poids", "Maintiens la position de ton coude contre ta cuisse pour isoler le bicep et éviter de balancer", "Ne laisse pas ton épaule rouler vers l''avant pendant le curl - garde la poitrine haute et les épaules en arrière", "Expire pendant la phase de levée et inspire pendant la phase de descente."]', '["Keep your wrist in a neutral position throughout the entire movement to avoid strain", "Focus on slow, controlled movements rather than using momentum to lift the weight", "Maintain the elbow position against your thigh to isolate the bicep and prevent swinging", "Don''t allow your shoulder to roll forward during the curl - keep your chest up and shoulders back", "Breathe out during the lifting phase and breathe in during the lowering phase"]', '372da9df-3ee6-450c-ae97-743968d27d71', 'concentration-hammer-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('7c234bd3-7b13-4969-93dc-7886964eb236', 'Flexions des poignets avec haltères', NULL, NULL, 'Dumbbell wrist curls', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/dumbbell-wrist-curls1.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-wrist-curls1.jpg', NULL, '["Isoler le mouvement uniquement aux poignets et aux avant-bras - évite d''utiliser les biceps ou les épaules.", "Adopte un tempo contrôlé, en particulier lors de la phase de descente pour maximiser le développement musculaire.", "Commence avec des poids plus légers, car les muscles des avant-bras se fatiguent rapidement et la bonne forme est cruciale.", "Garde une prise ferme sur les haltères pendant tout le mouvement.", "Assure-toi que tes poignets restent en position neutre en bas pour éviter l''hyperextension."]', '["Utiliser l''élan au lieu de la force musculaire.", "Fléchir les coudes, ce qui réduit l''engagement des avant-bras."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["forearms", "dumbbell", "dumbbell wrist curls"]', true, '2026-04-03 12:24:56.655308+00', '2026-04-03 12:24:56.655308+00', 'Position de départ : Tiens-toi droit avec des haltères à tes côtés, bras tendus vers le bas et paumes tournées vers l''avant. Exécution : Garde tes bras supérieurs et ton corps immobiles tout en fléchissant les poignets vers le haut pour soulever les poids, puis abaisse-les lentement vers la position de départ.', '["Utiliser l''élan au lieu de la force musculaire.", "Fléchir les coudes, ce qui réduit l''engagement des avant-bras."]', true, '["Stand with feet shoulder-width apart, holding a dumbbell in each hand with arms hanging naturally at your sides", "Keep your upper arms pressed against your torso and avoid swinging or using momentum", "Flex your wrists upward by curling the dumbbells as high as possible while keeping your forearms stationary", "Hold the contracted position briefly to maximize muscle engagement", "Slowly lower the weights back to the starting position with control", "Maintain proper posture throughout the movement with shoulders back and core engaged"]', '["Tiens-toi debout, les pieds à la largeur des épaules, avec un haltère dans chaque main, bras pendants naturellement sur les côtés.", "Maintiens tes bras supérieurs contre ton torse, évite de balancer ou d''utiliser l''élan.", "Fléchis tes poignets vers le haut en curling les haltères le plus haut possible tout en gardant tes avant-bras immobiles.", "Maintiens la position contractée brièvement pour maximiser l''engagement musculaire.", "Abaisse lentement les poids vers la position de départ avec contrôle.", "Garde une bonne posture pendant tout le mouvement, avec les épaules en arrière et le core engagé."]', '["Isoler le mouvement uniquement aux poignets et aux avant-bras - évite d''utiliser les biceps ou les épaules.", "Adopte un tempo contrôlé, en particulier lors de la phase de descente pour maximiser le développement musculaire.", "Commence avec des poids plus légers, car les muscles des avant-bras se fatiguent rapidement et la bonne forme est cruciale.", "Garde une prise ferme sur les haltères pendant tout le mouvement.", "Assure-toi que tes poignets restent en position neutre en bas pour éviter l''hyperextension."]', '["Keep all movement isolated to the wrists and forearms - avoid using your biceps or shoulders", "Use a controlled tempo, especially on the lowering phase to maximize muscle development", "Start with lighter weights as forearm muscles fatigue quickly and proper form is crucial", "Maintain a firm grip on the dumbbells throughout the entire range of motion", "Keep your wrists in a neutral position at the bottom to avoid hyperextension"]', '6891aa71-6e1f-4ea4-b9ac-f38ea207216a', 'dumbbell-wrist-curls1', NULL, NULL);
INSERT INTO public.exercises VALUES ('5639b270-f683-4a8b-84bc-f92f0ed782df', 'T Press Up', NULL, 'ضغط T', 'T press up', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/t-press-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/t-press-up.jpg', NULL, '["Garde le core bien contracté pendant tout le mouvement pour éviter que tes hanches ne s''affaissent ou ne tournent", "Assure-toi que ton corps forme une ligne droite de la tête aux talons pendant toute la pompe et la rotation", "Contrôle le mouvement de rotation - ne te précipite pas lors de la position T", "Place ta main d''appui directement sous ton épaule pour plus de stabilité et de sécurité pour les articulations", "Si les pompes complètes sont trop difficiles, effectue l''exercice sur les genoux tout en maintenant une bonne forme"]', '["Laisser les hanches s''affaisser lors de la descente", "Ne pas contrôler la rotation, ce qui peut entraîner une perte d''équilibre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "t press up"]', true, '2026-04-03 12:24:59.718884+00', '2026-04-03 12:24:59.718884+00', 'Place-toi en position de pompe standard, les mains légèrement plus larges que les épaules, le corps bien droit des pieds à la tête. Descends en faisant une pompe classique puis, en position haute, lève une main et pivote ton torse en tendant ce bras vers le plafond en formant un T. Retourne à la position de départ et répète de l''autre côté.', '["Laisser les hanches s''affaisser lors de la descente", "Ne pas contrôler la rotation, ce qui peut entraîner une perte d''équilibre"]', true, '["Start in a high plank position with hands firmly planted and core engaged", "Lower your body in a controlled push-up motion until chest nearly touches the floor", "Push back up to the starting position with full arm extension", "Lift your right hand and rotate your torso, reaching that arm toward the ceiling", "Return the right hand to the ground and repeat the sequence with your left arm", "Continue alternating sides for the desired number of repetitions"]', '["Commence en position de planche haute avec les mains bien ancrées et le core engagé", "Descends ton corps de manière maîtrisée jusqu''à ce que ta poitrine frôle le sol", "Remonte à la position de départ en tendant complètement les bras", "Lève ta main droite et pivote ton torse, en tendant ce bras vers le plafond", "Remets ta main droite au sol et répète avec ton bras gauche", "Alterne les côtés pour le nombre de répétitions souhaité"]', '["Garde le core bien contracté pendant tout le mouvement pour éviter que tes hanches ne s''affaissent ou ne tournent", "Assure-toi que ton corps forme une ligne droite de la tête aux talons pendant toute la pompe et la rotation", "Contrôle le mouvement de rotation - ne te précipite pas lors de la position T", "Place ta main d''appui directement sous ton épaule pour plus de stabilité et de sécurité pour les articulations", "Si les pompes complètes sont trop difficiles, effectue l''exercice sur les genoux tout en maintenant une bonne forme"]', '["Keep your core tight throughout the entire movement to prevent hip sagging or rotation", "Maintain a straight line from head to heels during both the push-up and rotation phases", "Control the rotational movement - avoid rushing through the T-position", "Place your supporting hand directly under your shoulder for optimal stability and joint safety", "If full push-ups are too challenging, perform the exercise from your knees while maintaining proper form"]', '1c13173b-006e-4bfb-8f57-6c9403915e4d', 't-press-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('db3caec7-296f-42ca-92a2-7893cda63cb1', 'Thruster avec Barre', NULL, NULL, 'Barbell Thruster - Straight Bar Thruster', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 1, '/videos/quadriceps/barbell-thruster-straight-bar-thruster.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-thruster-straight-bar-thruster.jpg', NULL, '["Assure une bonne position de rack frontal tout au long du squat pour éviter que la barre ne glisse.", "Veille à ce que tes genoux suivent la direction de tes orteils pour protéger tes articulations.", "Utilise l''élan de tes jambes pour t''aider à pousser la barre en overhead.", "Assure-toi d''une extension complète des hanches et des genoux avant la presse pour transmettre un maximum de puissance.", "Commence avec des poids légers pour maîtriser la coordination entre le squat et la presse."]', '["Laisser la barre glisser en avant durant le squat.", "Fléchir le dos au lieu de garder une posture droite."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "barbell thruster - straight bar thruster"]', true, '2026-04-03 12:24:55.634651+00', '2026-04-03 12:24:55.634651+00', 'Prépare-toi à forger des jambes en acier ! Positionne-toi debout, pieds écartés à la largeur des épaules, la barre au niveau des épaules, prête à exploser. C''est le moment de performer avec puissance !', '["Laisser la barre glisser en avant durant le squat.", "Fléchir le dos au lieu de garder une posture droite."]', true, '["Set up with the barbell in a front rack position, resting on your front deltoids with elbows pointing forward", "Keep your core tight and chest up as you initiate the movement by sitting back into a squat", "Descend until your hip crease is below your knee caps while maintaining an upright torso", "Drive explosively through your heels to stand up while beginning to press the barbell overhead", "Complete the movement by fully extending your arms overhead with the barbell directly above your shoulders", "Lower the barbell back to the front rack position with control to complete one repetition"]', '["Place la barre sur tes deltoïdes, les coudes orientés vers l''avant.", "Contracte ton ventre et garde le dos droit en amorçant le mouvement par une flexion des hanches.", "Descends en position de squat profond, les hanches sous les genoux, tout en maintenant un torse droit.", "Pousse avec force à travers tes talons pour te redresser, en pressant simultanément la barre au-dessus de ta tête.", "Termine le mouvement avec les bras complètement tendus au-dessus de tes épaules, la barre bien centrée.", "Ramène la barre avec contrôle à la position frontale pour valider la répétition."]', '["Assure une bonne position de rack frontal tout au long du squat pour éviter que la barre ne glisse.", "Veille à ce que tes genoux suivent la direction de tes orteils pour protéger tes articulations.", "Utilise l''élan de tes jambes pour t''aider à pousser la barre en overhead.", "Assure-toi d''une extension complète des hanches et des genoux avant la presse pour transmettre un maximum de puissance.", "Commence avec des poids légers pour maîtriser la coordination entre le squat et la presse."]', '["Maintain a strong front rack position throughout the squat portion to prevent the bar from rolling forward", "Keep your knees tracking over your toes during the squat to protect your knee joints", "Use the momentum from your leg drive to assist with the overhead press portion of the movement", "Ensure full hip and knee extension at the top before pressing the weight overhead for maximum power transfer", "Start with lighter weight to master the coordination between the squat and press movements"]', '6e9512fe-74b9-4c8a-bae2-a54361937b0e', 'barbell-thruster-straight-bar-thruster', NULL, NULL);
INSERT INTO public.exercises VALUES ('04674852-bd96-4af4-bbca-23c269ef20ad', 'Curl Prêcheur avec Haltère', NULL, NULL, 'Preacher Curl Dumbbell', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/preacher-curl-dumbbell.mp4', NULL, NULL, NULL, '/videos/thumbnails/preacher-curl-dumbbell.jpg', NULL, '["N''étends jamais complètement ton coude en bas du mouvement pour éviter une hyperextension et du stress sur l''articulation.", "Concentre-toi sur la phase excentrique (descente) du mouvement, elle est cruciale pour développer tes muscles.", "Garde ton poignet droit et solide pendant l''exercice pour éviter les tensions et maximiser l''engagement du biceps.", "Choisis un poids qui te permet de garder une technique irréprochable plutôt que de prendre lourd et de compromettre ta forme.", "Positionne-toi pour que ton aisselle soit alignée avec le bord supérieur du coussin pour une biomécanique optimale."]', '["Trop basculer le dos au lieu de garder la poitrine collée au coussin.", "Utiliser un poids trop lourd entraînant des mouvements de balancement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "preacher curl dumbbell"]', true, '2026-04-03 12:24:58.436276+00', '2026-04-03 12:24:58.436276+00', 'Prends place sur le banc prêcheur avec un haltère dans une main, bras reposant sur le coussin. Fléchis ton coude pour amener l’haltère vers ton épaule, puis redescends lentement.', '["Trop basculer le dos au lieu de garder la poitrine collée au coussin.", "Utiliser un poids trop lourd entraînant des mouvements de balancement."]', true, '["Adjust the preacher bench height so the pad sits comfortably under your armpits when seated", "Hold the dumbbell with an underhand grip, allowing your working arm to extend naturally over the angled pad", "Keep your chest firmly pressed against the pad throughout the entire movement", "Curl the weight up smoothly by squeezing your bicep, avoiding any jerking or swinging motions", "Lower the dumbbell slowly and with control, stopping just short of full arm extension", "Complete all repetitions on one arm before switching to the other side"]', '["Ajuste la hauteur du banc pour que le coussin repose confortablement sous tes aisselles lorsque tu es assis.", "Saisis l''haltère avec une prise en supination, en laissant ton bras s''étendre naturellement sur le coussin incliné.", "Maintiens ta poitrine bien appuyée contre le coussin tout au long du mouvement.", "Fais monter l''haltère en contractant bien ton biceps, sans mouvements brusques ou balancements.", "Abaisse l''haltère lentement et de manière contrôlée, en te stoppant juste avant l''extension complète du bras.", "Effectue toutes les répétitions d''un côté avant de changer de bras."]', '["N''étends jamais complètement ton coude en bas du mouvement pour éviter une hyperextension et du stress sur l''articulation.", "Concentre-toi sur la phase excentrique (descente) du mouvement, elle est cruciale pour développer tes muscles.", "Garde ton poignet droit et solide pendant l''exercice pour éviter les tensions et maximiser l''engagement du biceps.", "Choisis un poids qui te permet de garder une technique irréprochable plutôt que de prendre lourd et de compromettre ta forme.", "Positionne-toi pour que ton aisselle soit alignée avec le bord supérieur du coussin pour une biomécanique optimale."]', '["Never fully lock out your elbow at the bottom of the movement to avoid hyperextension and joint stress", "Focus on the eccentric (lowering) portion of the movement as this provides significant muscle-building benefits", "Keep your wrist straight and strong throughout the exercise to prevent strain and maximize bicep engagement", "Use a weight that allows you to maintain strict form rather than going too heavy and compromising technique", "Position yourself so your armpit aligns with the top edge of the preacher pad for optimal biomechanics"]', '339d8f8f-18e3-452a-ae66-f2b098382a84', 'preacher-curl-dumbbell', NULL, NULL);
INSERT INTO public.exercises VALUES ('afc53a48-82af-4b01-9ae2-79684000bf93', 'Curl Biceps Debout Intérieur', NULL, NULL, 'Standing Inner-Biceps Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/standing-inner-biceps-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-inner-biceps-curl.jpg', NULL, '["Garde tes poignets droits et conserve la prise en supination durant tout le mouvement", "Évite de balancer ou d''utiliser l''élan - chaque mouvement doit être contrôlé et isolé sur les biceps", "Maintiens une bonne posture avec les épaules en arrière et la poitrine en avant tout au long de l''exercice", "Concentre-toi sur la phase excentrique (descente) pour maximiser l''engagement musculaire", "Garde tes coudes fixes et proches de ton corps pour maximiser l''activation des biceps"]', '["Ne pas garder les poignets droits", "Utiliser l''élan pour soulever les haltères"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "standing inner-biceps curl"]', true, '2026-04-03 12:24:59.559596+00', '2026-04-03 12:24:59.559596+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des épaules, avec des haltères à tes côtés, bras complètement tendus et paumes vers l''extérieur avec une prise en supination. Exécution : Fléchis les coudes pour relever les haltères tout en gardant les bras supérieurs immobiles, puis redescends lentement à la position de départ.', '["Ne pas garder les poignets droits", "Utiliser l''élan pour soulever les haltères"]', true, '["Stand with feet shoulder-width apart and core engaged for stability", "Hold dumbbells with palms facing forward and arms fully extended at your sides", "Keep your upper arms pressed against your torso throughout the movement", "Curl the weights up by contracting your biceps until your forearms are vertical", "Squeeze your biceps at the top of the movement", "Slowly lower the dumbbells back to the starting position with control"]', '["Tiens-toi debout, pieds à la largeur des épaules et le centre du corps engagé pour plus de stabilité", "Tiens les haltères avec les paumes tournées vers l''avant et bras complètement tendus sur les côtés", "Garde tes bras supérieurs collés contre ton torse pendant tout le mouvement", "Soulève les poids en contractant tes biceps jusqu''à ce que tes avant-bras soient verticaux", "Contracte tes biceps en haut du mouvement", "Abaisse lentement les haltères à la position de départ en maîtrisant le mouvement"]', '["Garde tes poignets droits et conserve la prise en supination durant tout le mouvement", "Évite de balancer ou d''utiliser l''élan - chaque mouvement doit être contrôlé et isolé sur les biceps", "Maintiens une bonne posture avec les épaules en arrière et la poitrine en avant tout au long de l''exercice", "Concentre-toi sur la phase excentrique (descente) pour maximiser l''engagement musculaire", "Garde tes coudes fixes et proches de ton corps pour maximiser l''activation des biceps"]', '["Keep your wrists straight and maintain the supinated grip throughout the entire movement", "Avoid swinging or using momentum - the movement should be controlled and isolated to the biceps", "Maintain proper posture with shoulders back and chest up throughout the exercise", "Focus on the eccentric (lowering) portion of the movement for maximum muscle engagement", "Keep your elbows stationary and close to your body to maximize bicep activation"]', 'bba8482e-3ddd-4c44-9b2a-90af81d040e9', 'standing-inner-biceps-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('3806b470-72d7-4f1f-bf36-4ec78749ae05', 'Curl Croisé avec Poids', NULL, NULL, 'Cross Body Hammer Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/cross-body-hammer-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/cross-body-hammer-curl.jpg', NULL, '["Garde le ventre engagé et évite de faire du balancement ou d''utiliser de l''élan pour finir le mouvement.", "Maintiens la prise marteau neutre pendant toute l''exécution.", "Concentre-toi sur le mouvement croisé pour solliciter les biceps sous un angle différent des curls traditionnels.", "Contrôle bien les phases de montée et de descente pour un engagement maximal des muscles.", "Stabilise tes épaules et évite de les faire rouler vers l''avant tout au long de l''exercice."]', '["Utiliser l''élan au lieu de la force musculaire.", "Oublier de serrer le biceps au sommet du curl."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "cross body hammer curl"]', true, '2026-04-03 12:24:56.220619+00', '2026-04-03 12:24:56.220619+00', 'Position de départ : Tiens-toi debout, pieds écartés à la largeur des épaules, bras le long du corps en prise neutre comme si tu tenais des haltères. Exécution : Fais un curl avec un bras en travers de ton corps vers l''épaule opposée en gardant une prise marteau, puis redescends avec contrôle et répète de l''autre côté.', '["Utiliser l''élan au lieu de la force musculaire.", "Oublier de serrer le biceps au sommet du curl."]', true, '["Stand with feet shoulder-width apart, core engaged, and maintain good posture throughout", "Position your arms at your sides with palms facing your body in a neutral hammer grip position", "Curl your right arm up and across your body toward your left shoulder, keeping your elbow close to your torso", "Squeeze your bicep at the top of the movement and hold for a brief pause", "Lower your arm slowly back to the starting position with control", "Repeat the movement with your left arm crossing toward your right shoulder"]', '["Tiens-toi bien droit, pieds écartés à la largeur des épaules, engage ton ventre et maintiens une bonne posture pendant tout l''exercice.", "Positionne tes bras le long du corps avec les paumes tournées vers toi en prise neutre.", "Fais un curl de ton bras droit vers ton épaule gauche, en gardant ton coude proche de ton corps.", "Contracte bien ton biceps en haut du mouvement et fais une pause rapide.", "Redescends doucement ton bras à la position de départ avec contrôle.", "Répète le mouvement avec ton bras gauche vers ton épaule droite."]', '["Garde le ventre engagé et évite de faire du balancement ou d''utiliser de l''élan pour finir le mouvement.", "Maintiens la prise marteau neutre pendant toute l''exécution.", "Concentre-toi sur le mouvement croisé pour solliciter les biceps sous un angle différent des curls traditionnels.", "Contrôle bien les phases de montée et de descente pour un engagement maximal des muscles.", "Stabilise tes épaules et évite de les faire rouler vers l''avant tout au long de l''exercice."]', '["Keep your core tight and avoid swaying or using momentum to complete the movement", "Maintain the neutral hammer grip position throughout the entire range of motion", "Focus on the cross-body motion to engage the biceps from a different angle than traditional curls", "Control both the lifting and lowering phases of the movement for maximum muscle engagement", "Keep your shoulders stable and avoid rolling them forward during the exercise"]', 'b8fb88dc-d819-4e65-86c8-7ea13703afdb', 'cross-body-hammer-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('11c5fc16-3c7f-4a3c-9f0e-e5a56b396542', 'Taps des orteils en position ours', NULL, NULL, 'Bear toe taps', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/bear-toe-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-toe-taps.jpg', NULL, '["Garde les hanches carrées et évite de tourner ou de pencher d''un côté pendant les taps des orteils", "Respire régulièrement et évite de retenir ta respiration durant le mouvement", "Commence par des séries plus courtes et augmente ton endurance progressivement car cet exercice est très exigeant pour le core", "Concentre-toi sur la qualité plutôt que sur la quantité - la forme correcte est plus importante que la vitesse ou le nombre de répétitions", "Maintiens les épaules stables et évite de déplacer ton poids de façon excessive d''un côté à l''autre"]', '["Laisser les genoux toucher le sol", "Bouger les hanches de manière excessives pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "bear toe taps"]', true, '2026-04-03 12:24:55.689298+00', '2026-04-03 12:24:55.689298+00', 'Mets-toi en position de rampement ours, les mains sous les épaules, les genoux sous les hanches, flottant à quelques centimètres du sol et engages ton core. Ensuite, alterne pour taper un pied avec la main opposée tout en maintenant ta stabilité.', '["Laisser les genoux toucher le sol", "Bouger les hanches de manière excessives pendant l''exercice"]', true, '["Start in bear crawl position with hands planted firmly under shoulders and knees hovering just off the ground", "Engage your core and maintain a neutral spine throughout the movement", "Lift your right hand and reach across to tap your left foot while keeping hips level", "Return right hand to starting position and immediately switch to tap left hand to right foot", "Keep knees hovering throughout the entire exercise without letting them touch the ground", "Perform taps in a controlled manner focusing on stability rather than speed"]', '["Commence en position de rampement ours avec les mains fermement ancrées sous les épaules et les genoux flottants juste au-dessus du sol", "Engage ton core et garde une colonne vertébrale neutre pendant tout le mouvement", "Lève ta main droite et tends-la vers ton pied gauche tout en gardant les hanches de niveau", "Ramène ta main droite à la position de départ et passe immédiatement à la main gauche pour taper le pied droit", "Garde les genoux flottants pendant tout l''exercice sans les laisser toucher le sol", "Effectue les taps de manière contrôlée, en te concentrant sur la stabilité plutôt que sur la vitesse"]', '["Garde les hanches carrées et évite de tourner ou de pencher d''un côté pendant les taps des orteils", "Respire régulièrement et évite de retenir ta respiration durant le mouvement", "Commence par des séries plus courtes et augmente ton endurance progressivement car cet exercice est très exigeant pour le core", "Concentre-toi sur la qualité plutôt que sur la quantité - la forme correcte est plus importante que la vitesse ou le nombre de répétitions", "Maintiens les épaules stables et évite de déplacer ton poids de façon excessive d''un côté à l''autre"]', '["Keep hips square and avoid rotating or tilting to one side during the toe taps", "Maintain steady breathing and avoid holding your breath during the movement", "Start with shorter sets and build endurance gradually as this exercise is very demanding on the core", "Focus on quality over quantity - proper form is more important than speed or number of repetitions", "Keep shoulders stable and avoid shifting weight dramatically from side to side"]', '59887212-af71-41e1-9b3f-afe352ba1979', 'bear-toe-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('76c4b06c-8c38-4b3f-9b1a-0d3b8045608d', 'Tirage horizontal prise normale', NULL, 'تجرى منوز', 'Normal grip pull ups (Full range of motion', 'Back', '[]', 'Back', 'Intermediate', 16, '/videos/back/normal-grip-pull-ups-full-range-of-motion.mp4', NULL, NULL, NULL, '/videos/thumbnails/normal-grip-pull-ups-full-range-of-motion.jpg', NULL, '["Évite de te balancer ou d''utiliser l''élan - conserve une forme stricte pendant tout le mouvement", "Assure-toi d''une amplitude complète en atteignant l''extension totale des bras en bas et le menton au-dessus de la barre en haut", "Garde ton core engagé et penche-toi légèrement en avant pour optimiser l''activation des dorsaux", "Concentre-toi sur une descente contrôlée, cela renforce et prévient les blessures", "Progresser progressivement en utilisant des bandes d''assistance ou des répétitions négatives si tu n''arrives pas encore à faire des tractions complètes."]', '["Ne pas engager le core durant l''exercice.", "Balancer le corps au lieu d''utiliser les muscles du dos."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "normal grip pull ups (full range of motion"]', true, '2026-04-03 12:24:57.861281+00', '2026-04-03 12:24:57.861281+00', 'Position de départ : Suspendez-vous à une barre de traction avec les mains écartées à la largeur des épaules, prise en pronation, bras pleinement étendus et pieds décollés du sol. Exécution : Tire ton corps vers le haut jusqu''à ce que ton menton dépasse la barre, puis redescends de manière contrôlée à la position de suspension complète.', '["Ne pas engager le core durant l''exercice.", "Balancer le corps au lieu d''utiliser les muscles du dos."]', true, '["Grip the bar with hands shoulder-width apart using an overhand grip, ensuring a secure hold", "Hang with arms fully extended in a dead hang position, engaging your core and keeping shoulders active", "Pull yourself up by driving your elbows down and back, leading with your chest", "Continue pulling until your chin clears the bar completely", "Lower yourself slowly and under control back to the starting dead hang position", "Maintain tension throughout your body during both the ascending and descending phases"]', '["Saisis la barre avec les mains écartées à la largeur des épaules en prise pronation, assure-toi d''une bonne prise", "Suspends-toi avec les bras bien étendus, engage le core et garde les épaules actives", "Tire-toi vers le haut en utilisant tes coudes, dirige-les vers le bas et vers l''arrière, la poitrine en avant", "Poursuis le mouvement jusqu''à ce que ton menton dépasse complètement la barre", "Redescends lentement et sous contrôle vers la position de suspension complète", "Maintiens la tension dans tout le corps pendant les phases montante et descendante."]', '["Évite de te balancer ou d''utiliser l''élan - conserve une forme stricte pendant tout le mouvement", "Assure-toi d''une amplitude complète en atteignant l''extension totale des bras en bas et le menton au-dessus de la barre en haut", "Garde ton core engagé et penche-toi légèrement en avant pour optimiser l''activation des dorsaux", "Concentre-toi sur une descente contrôlée, cela renforce et prévient les blessures", "Progresser progressivement en utilisant des bandes d''assistance ou des répétitions négatives si tu n''arrives pas encore à faire des tractions complètes."]', '["Avoid swinging or using momentum - maintain strict form throughout the entire movement", "Achieve full range of motion by reaching complete arm extension at the bottom and chin over bar at the top", "Keep your core engaged and maintain a slight forward lean to optimize lat activation", "Focus on controlled eccentric lowering as this builds strength and prevents injury", "Progress gradually by using assistance bands or negatives if unable to perform full bodyweight repetitions"]', '3b69631f-65b9-4af3-9c65-5739375e3dfb', 'normal-grip-pull-ups-full-range-of-motion', NULL, NULL);
INSERT INTO public.exercises VALUES ('ec78ec67-3afa-44e1-9891-83d66a8e840c', 'Saute sur le banc !', NULL, 'قفز على الطاولة!', 'Bench Jump', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/bench-jump.mp4', NULL, NULL, NULL, '/videos/thumbnails/bench-jump.jpg', NULL, '["Concentre-toi sur un atterrissage doux avec les genoux fléchis pour protéger tes articulations.", "Maintiens ton centre engagé tout au long du mouvement pour rester équilibré et stable.", "Choisis un banc d''une hauteur qui te met au défi sans compromettre ta forme ou ta sécurité.", "Privilégie toujours la descente en marchant plutôt qu''en sautant pour minimiser le risque de blessure.", "Assure-toi d''avoir un espace suffisant autour du banc pour te déplacer en toute sécurité dans toutes les directions."]', '["Atterrir trop lourdement, ce qui peut provoquer des blessures articulaires.", "Ne pas marquer de pause sur le banc, ce qui nuit à l''équilibre et à la concentration."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "bench jump"]', true, '2026-04-03 12:24:55.71548+00', '2026-04-03 12:24:55.71548+00', 'Départ : Tiens-toi face à un banc ou une plateforme solide, à hauteur de genoux, les pieds écartés à la largeur des hanches et les bras le long du corps. Exécution : Saute explosivement sur le banc en atterrissant doucement avec les deux pieds, puis redescends en marchant ou en sautant pour revenir à la position de départ.', '["Atterrir trop lourdement, ce qui peut provoquer des blessures articulaires.", "Ne pas marquer de pause sur le banc, ce qui nuit à l''équilibre et à la concentration."]', true, '["Ensure the bench or platform is stable and can support your body weight before beginning", "Bend your knees and swing your arms back to generate momentum before jumping", "Land softly on the balls of your feet with knees bent to absorb impact", "Step down backwards one foot at a time rather than jumping down to reduce joint stress", "Maintain control throughout the entire movement and pause briefly on top of the bench"]', '["Assure-toi que le banc ou la plateforme est stable et capable de supporter ton poids avant de commencer.", "Plie les genoux et balance les bras en arrière pour gagner de l''élan avant de sauter.", "Atterris doucement sur la plante des pieds avec les genoux fléchis pour absorber l''impact.", "Descends en marchant un pied à la fois plutôt que de sauter pour réduire le stress sur les articulations.", "Garde le contrôle durant tout le mouvement et marque une courte pause sur le banc."]', '["Concentre-toi sur un atterrissage doux avec les genoux fléchis pour protéger tes articulations.", "Maintiens ton centre engagé tout au long du mouvement pour rester équilibré et stable.", "Choisis un banc d''une hauteur qui te met au défi sans compromettre ta forme ou ta sécurité.", "Privilégie toujours la descente en marchant plutôt qu''en sautant pour minimiser le risque de blessure.", "Assure-toi d''avoir un espace suffisant autour du banc pour te déplacer en toute sécurité dans toutes les directions."]', '["Focus on landing softly with bent knees to protect your joints from impact", "Keep your core engaged throughout the movement to maintain balance and stability", "Choose an appropriate bench height that challenges you without compromising form or safety", "Always step down rather than jump down to minimize risk of injury", "Ensure adequate space around the bench for safe movement in all directions"]', '4402c7a1-0845-4da2-882d-4e06fc275b8b', 'bench-jump', NULL, NULL);
INSERT INTO public.exercises VALUES ('12795db6-ff3e-4745-ab66-9441e325717f', 'Tirage Large au Poulie', NULL, NULL, 'Wide Grip Lat Pulldown', 'Back', '[]', 'Back', 'Beginner', 4, '/videos/back/wide-grip-lat-pulldown.mp4', NULL, NULL, NULL, '/videos/thumbnails/wide-grip-lat-pulldown.jpg', NULL, '["Garde le torse droit avec une légère inclinaison vers l''arrière pour éviter de transformer cela en un mouvement de ramer.", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement avec tes dorsaux et en serrant les omoplates.", "Évite de tirer la barre derrière ton cou pour prévenir les blessures à l''épaule.", "Maintiens le contrôle durant toute l''amplitude de mouvement, surtout pendant la phase excentrique au retour à la position de départ.", "Garde les poignets droits et évite de serrer trop fort la barre pour ne pas fatiguer tes avant-bras à l’origine d''une limitation de tes performances. "]', '["S''incliner trop en avant pendant l''exercice.", "Tirer la barre derrière la nuque plutôt qu''à la poitrine."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "wide grip lat pulldown"]', true, '2026-04-03 12:24:59.920293+00', '2026-04-03 12:24:59.920293+00', 'Position de départ : Assieds-toi sur la machine à tirage vertical avec une prise pronation (paumes vers le bas) et les mains plus larges que la largeur des épaules. Exécution : Tire la barre vers ta poitrine tout en gardant les coudes près de ton corps, puis retourne lentement à la position de départ.', '["S''incliner trop en avant pendant l''exercice.", "Tirer la barre derrière la nuque plutôt qu''à la poitrine."]', true, '["Adjust the seat height so your thighs fit snugly under the leg pads to prevent your body from lifting during the exercise", "Grasp the bar with both hands using an overhand grip, positioning your hands wider than shoulder-width apart", "Lean back slightly from your hips while maintaining a straight spine and engaged core", "Pull the bar down smoothly toward your upper chest, leading with your elbows and focusing on squeezing your shoulder blades together", "Hold the bottom position briefly, feeling the contraction in your back muscles", "Slowly return the bar to the starting position with control, allowing your arms to fully extend without letting the weight stack slam down"]', '["Ajuste la hauteur du siège pour que tes cuisses soient bien en place sous les coussinets afin d''empêcher ton corps de se soulever durant l''exercice.", "Saisis la barre avec les deux mains en prise pronation, en plaçant tes mains plus larges que tes épaules.", "Incline-toi légèrement en arrière au niveau des hanches tout en gardant la colonne droite et le tronc engagé.", "Tire la barre vers le haut de ta poitrine, en menant avec les coudes et en concentrant sur la contraction des muscles du dos.", "Maintiens brièvement la position basse pour ressentir la contraction dans tes muscles du dos.", "Retourne lentement la barre à la position de départ avec contrôle, en laissant tes bras s''étendre complètement sans que la pile de poids ne claque. "]', '["Garde le torse droit avec une légère inclinaison vers l''arrière pour éviter de transformer cela en un mouvement de ramer.", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement avec tes dorsaux et en serrant les omoplates.", "Évite de tirer la barre derrière ton cou pour prévenir les blessures à l''épaule.", "Maintiens le contrôle durant toute l''amplitude de mouvement, surtout pendant la phase excentrique au retour à la position de départ.", "Garde les poignets droits et évite de serrer trop fort la barre pour ne pas fatiguer tes avant-bras à l’origine d''une limitation de tes performances. "]', '["Keep your torso upright with only a slight backward lean to avoid turning this into a rowing movement", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your lats and squeezing your shoulder blades", "Avoid pulling the bar behind your neck as this can cause shoulder impingement and injury", "Maintain control throughout the entire range of motion, especially during the eccentric phase when returning to the starting position", "Keep your wrists straight and avoid gripping the bar too tightly to prevent forearm fatigue from limiting your back workout"]', 'c9ff47ce-69d3-4b32-8eb4-6fdac8d8a9f2', 'wide-grip-lat-pulldown', NULL, NULL);
INSERT INTO public.exercises VALUES ('c1b11bf0-4298-44f5-88b0-bcae04dbd50c', 'Soulevé de terre avec barre', NULL, NULL, 'Barbell Deadlift', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/deadlift-88.mp4', NULL, NULL, NULL, '/videos/thumbnails/deadlift-88.jpg', NULL, '["Commence le mouvement par les hanches, pas par les genoux ou le dos", "Maintiens un dos neutre durant tout le mouvement", "Concentre-toi sur l''étirement de tes ischio-jambiers pendant la phase de descente", "Évite d''arrondir le dos ou de laisser tes genoux s''effondrer vers l''intérieur", "Contrôle la descente et utilise les muscles de la chaîne postérieure pour propulser le mouvement de retour"]', '["Arrondir le dos pendant l''exécution", "Relâcher la tension dans les jambes au lieu de les activer"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "barbell deadlift"]', true, '2026-04-03 12:24:55.543455+00', '2026-04-03 12:24:55.543455+00', 'Position de départ : Place-toi avec les pieds écartés à la largeur des hanches, fléchis légèrement les genoux et penche-toi en avant en gardant le dos droit et la poitrine en avant. Exécution : Pousse sur tes talons et propulse tes hanches vers l’avant pour revenir à la position debout, en serrant les fessiers en haut du mouvement.', '["Arrondir le dos pendant l''exécution", "Relâcher la tension dans les jambes au lieu de les activer"]', true, '["Position feet hip-width apart with toes pointing slightly outward", "Hinge at the hips by pushing your buttocks back while keeping knees slightly bent", "Lower your torso by continuing the hip hinge movement until you feel a stretch in your hamstrings", "Keep your chest up and maintain a neutral spine throughout the movement", "Drive through your heels and push your hips forward to return to the starting position", "Squeeze your glutes at the top and stand tall with shoulders back"]', '["Positionne tes pieds à la largeur des hanches avec les orteils légèrement tournés vers l''extérieur", "Fléchis les hanches en poussant tes fesses en arrière tout en gardant les genoux légèrement pliés", "Abaisse ton torse en poursuivant le mouvement de hanches jusqu''à ressentir un étirement dans tes ischio-jambiers", "Garde ta poitrine bien haute et ton dos neutre tout au long du mouvement", "Pousse sur tes talons et propulse tes hanches vers l''avant pour revenir à la position de départ", "Sers bien tes fessiers en haut et redresse-toi en gardant les épaules en arrière"]', '["Commence le mouvement par les hanches, pas par les genoux ou le dos", "Maintiens un dos neutre durant tout le mouvement", "Concentre-toi sur l''étirement de tes ischio-jambiers pendant la phase de descente", "Évite d''arrondir le dos ou de laisser tes genoux s''effondrer vers l''intérieur", "Contrôle la descente et utilise les muscles de la chaîne postérieure pour propulser le mouvement de retour"]', '["Keep the movement initiated from your hips, not your knees or back", "Maintain a neutral spine throughout the entire range of motion", "Focus on feeling the stretch in your hamstrings during the lowering phase", "Avoid rounding your back or letting your knees cave inward", "Control the descent and use your posterior chain muscles to power the return movement"]', '2fb79823-a759-4ceb-8b16-a26ab3cfb440', 'deadlift-88', NULL, NULL);
INSERT INTO public.exercises VALUES ('c710ed68-0c77-467d-8f5f-230777c0eeb7', 'Tirage buste penché avec barre un bras', NULL, 'ترياج بار بجسد مائل بيد وحدة', 'Bent Over One-Arm Long Bar Row', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/bent-over-one-arm-long-bar-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-over-one-arm-long-bar-row.jpg', NULL, '["Garde le ventre bien serré tout au long du mouvement pour protéger le bas du dos et maintenir la stabilité", "Concentre-toi sur le travail de ton dos plutôt que de simplement tirer avec ton bras en initiant le mouvement avec ton homoplate", "Maintiens une position neutre de la colonne vertébrale et évite de courber le dos pendant le mouvement de tirage", "Maîtrise la phase négative du mouvement pour maximiser l''engagement musculaire et prévenir les blessures", "Garde ton coude près de ton corps plutôt que de l''écarter pour cibler correctement le grand dorsal et les rhomboïdes"]', '["Courber le dos pendant l''exercice", "Tirer principalement avec le bras sans utiliser les muscles du dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "bent over one-arm long bar row"]', true, '2026-04-03 12:24:55.752025+00', '2026-04-03 12:24:55.752025+00', 'Position de départ : Mets-toi debout, les pieds écartés à la largeur des hanches. Prends une extrémité de la barre avec une main, l’autre extrémité doit être sécurisé contre un mur ou un rack. Penche-toi en avant au niveau des hanches, genoux légèrement fléchis et le dos bien droit. Exécution : Tire l’extrémité de la barre vers ton cage thoracique en ramenant ton coude en arrière et en contractant ton homoplate, puis redescends lentement à la position de départ.', '["Courber le dos pendant l''exercice", "Tirer principalement avec le bras sans utiliser les muscles du dos"]', true, '["Secure one end of the barbell against a wall corner or in a landmine attachment to prevent movement", "Grip the free end with one hand using an overhand grip, step back to create tension", "Hinge at the hips while keeping your back straight and core engaged, allowing a slight bend in your knees", "Pull the barbell toward your lower ribcage by driving your elbow back along your side", "Squeeze your shoulder blade at the top of the movement and hold briefly", "Lower the weight slowly and under control back to the starting position"]', '["Fixe une extrémité de la barre contre un coin de mur ou dans un support pour éviter qu''elle ne bouge", "Saisis l''extrémité libre avec une main en position pronation, recule pour créer de la tension", "Penche-toi en avant en gardant le dos droit et ton centre actif, avec une légère flexion des genoux", "Tire la barre vers ton bas-ventre en ramenant le coude le long de ton corps", "Contracte ton homoplate en haut du mouvement et maintiens brièvement", "Redescends l’haltère lentement et de manière contrôlée jusqu’à la position initiale"]', '["Garde le ventre bien serré tout au long du mouvement pour protéger le bas du dos et maintenir la stabilité", "Concentre-toi sur le travail de ton dos plutôt que de simplement tirer avec ton bras en initiant le mouvement avec ton homoplate", "Maintiens une position neutre de la colonne vertébrale et évite de courber le dos pendant le mouvement de tirage", "Maîtrise la phase négative du mouvement pour maximiser l''engagement musculaire et prévenir les blessures", "Garde ton coude près de ton corps plutôt que de l''écarter pour cibler correctement le grand dorsal et les rhomboïdes"]', '["Keep your core tight throughout the movement to protect your lower back and maintain stability", "Focus on pulling with your back muscles rather than just your arm by initiating the movement with your shoulder blade", "Maintain a neutral spine position and avoid rounding your back during the rowing motion", "Control the eccentric portion of the lift to maximize muscle engagement and prevent injury", "Keep your elbow close to your body rather than flaring it out to properly target the latissimus dorsi and rhomboids"]', '43c81170-5fc1-46dd-92b0-6a308c22cec1', 'bent-over-one-arm-long-bar-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('452673e4-c490-4fd2-b772-a3c2c2121873', 'Pose du Pont', NULL, NULL, 'Bridge pose', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/bridge-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/bridge-pose.jpg', NULL, '["Garde les genoux alignés au-dessus des chevilles.", "Active tes fessiers et ton ventre pour soutenir le mouvement.", "Évite de tourner la tête pendant l''exercice."]', '["Ne pas soulever assez les hanches.", "Laisser les genoux s''écarter."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "bridge pose"]', true, '2026-04-03 12:24:55.789268+00', '2026-04-03 12:24:55.789268+00', 'Allonge-toi sur le dos, les genoux pliés et les pieds à plat sur le sol, écartés à la largeur des hanches. En serre bien les fessiers pour lever les hanches et créer une ligne droite entre les genoux et les épaules. Descends lentement avec contrôle.', '["Ne pas soulever assez les hanches.", "Laisser les genoux s''écarter."]', true, '["Lie on your back with knees bent and feet flat on the floor, hip-width apart.", "Place arms alongside your body with palms facing down.", "Press your feet into the floor and lift your hips toward the ceiling.", "Hold at the top, then slowly lower back down."]', '["Allonge-toi sur le dos, genoux pliés et pieds à plat au sol, écartés à la largeur des hanches.", "Place tes bras le long du corps, paumes vers le bas.", "Presse tes pieds dans le sol et soulève les hanches vers le plafond.", "Maintiens la position en haut, puis redescends lentement. Malin."]', '["Garde les genoux alignés au-dessus des chevilles.", "Active tes fessiers et ton ventre pour soutenir le mouvement.", "Évite de tourner la tête pendant l''exercice."]', '["Keep knees aligned over ankles.", "Engage your glutes and core to support the lift.", "Avoid turning your head while in the pose."]', '31f0a2a6-2d44-4c33-bf3a-2d0687b748a4', 'bridge-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('4c1d78a2-cf61-47f1-9806-7e97c756192b', 'Tirage Rameur au Cou avec Corde', NULL, NULL, 'Behind the Neck Rope Pulldown', 'Back', '[]', 'Back', 'Advanced', 4, '/videos/back/behind-the-neck-rope-pulldown.mp4', NULL, NULL, NULL, '/videos/thumbnails/behind-the-neck-rope-pulldown.jpg', NULL, '["Ne réalise cet exercice que si tu as une bonne mobilité des épaules et aucune blessure au cou ou aux épaules", "Engage ton abdomen et garde un torse droit pendant tout le mouvement pour protéger ton bas du dos", "Concentre-toi sur la connexion esprit-muscle avec tes rhomboïdes et le trapèze moyen plutôt que d''utiliser un poids excessif", "Arrête immédiatement si tu ressens une gêne dans le cou ou les épaules pendant le mouvement"]', '["Pousser le dos en arrière au lieu de rester droit", "Utiliser un poids trop lourd qui empêche une bonne technique"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "behind the neck rope pulldown"]', true, '2026-04-03 12:24:55.701816+00', '2026-04-03 12:24:55.701816+00', 'Position de départ : Assieds-toi sur une machine à poulie, avec une corde fixée au poulie. Exécution : Tire la corde vers l''arrière de ton cou, en écartant les extrémités à la fin du mouvement, puis retourne lentement à la position de départ.', '["Pousser le dos en arrière au lieu de rester droit", "Utiliser un poids trop lourd qui empêche une bonne technique"]', true, '["Adjust the cable machine to the highest position and attach a rope handle", "Sit on the bench facing away from the machine and grasp both ends of the rope with an overhand grip", "Position the rope at the base of your neck, ensuring your head is in a neutral position and shoulders are mobile", "Pull the rope down and apart by driving your elbows down toward your sides while squeezing your shoulder blades together", "Hold the contracted position briefly, feeling the tension in your upper back muscles", "Slowly return to the starting position with control, maintaining tension throughout the entire range of motion"]', '["Règle la machine à câble à la position la plus haute et attache une poignée en corde", "Installe-toi sur le banc en tournant le dos à la machine et saisis les deux extrémités de la corde avec une prise en pronation", "Place la corde à la base de ton cou, assure-toi que ta tête est neutre et que tes épaules sont mobiles", "Tire la corde vers le bas et sur les côtés en abattant tes coudes vers le bas et en serrant tes omoplates", "Maintiens la contraction quelques instants, ressens la tension dans le haut de ton dos", "Retourne lentement à la position de départ de manière contrôlée, en gardant la tension dans tout l''amplitude du mouvement."]', '["Ne réalise cet exercice que si tu as une bonne mobilité des épaules et aucune blessure au cou ou aux épaules", "Engage ton abdomen et garde un torse droit pendant tout le mouvement pour protéger ton bas du dos", "Concentre-toi sur la connexion esprit-muscle avec tes rhomboïdes et le trapèze moyen plutôt que d''utiliser un poids excessif", "Arrête immédiatement si tu ressens une gêne dans le cou ou les épaules pendant le mouvement"]', '["Only perform this exercise if you have adequate shoulder mobility and no neck or shoulder injuries", "Keep your core engaged and maintain an upright torso throughout the movement to protect your lower back", "Focus on the mind-muscle connection with your rhomboids and middle trapezius rather than using excessive weight", "Stop immediately if you feel any discomfort in your neck or shoulders during the movement"]', 'ab1681a6-93a1-4e51-ac8c-c76f02ef3737', 'behind-the-neck-rope-pulldown', NULL, NULL);
INSERT INTO public.exercises VALUES ('9f09f4e8-ea6d-4608-abd5-74c60a61c965', 'Tirages Rack : Renforce ton Dos !', NULL, 'تيراجات راك: زيد قوة ظهرك !', 'Rack Pulls', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/rack-pulls.mp4', NULL, NULL, NULL, '/videos/thumbnails/rack-pulls.jpg', NULL, '["Garde tes épaules tirées vers l''arrière et vers le bas pour protéger ta colonne vertébrale et maximiser l''engagement du dos", "Concentre-toi sur le mouvement d''articulation des hanches plutôt que sur un squat pour cibler correctement les muscles de la chaîne postérieure", "Choisis un poids qui te permet de garder une forme parfaite, car les tirages rack peuvent supporter des charges plus lourdes que les soulevés de terre classiques", "Évite de trop cambrer ton dos en haut du mouvement : reste simplement droit avec un alignement neutre de la colonne vertébrale", "Commence avec les supports à hauteur de genoux si tu es novice dans cet exercice et abaisse progressivement la position de départ à mesure que ta mobilité s''améliore"]', '["Ne pas engager les abdos, ce qui peut compromettre la forme", "S''accroupir au lieu de plier les hanches, ce qui diminue l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "rack pulls"]', true, '2026-04-03 12:24:58.554202+00', '2026-04-03 12:24:58.554202+00', 'Position de départ : Tiens-toi debout avec une barre reposant sur un rack à hauteur de genoux. Exécution : Lève la barre jusqu''à te tenir bien droit tout en gardant le dos droit, puis abaisse-la délicatement sur le rack.', '["Ne pas engager les abdos, ce qui peut compromettre la forme", "S''accroupir au lieu de plier les hanches, ce qui diminue l''efficacité de l''exercice"]', true, '["Set the safety pins or rack position at knee to mid-thigh height depending on your mobility and strength level", "Position your feet hip-width apart with the bar over the middle of your feet", "Grip the bar with hands just outside your legs, keeping your arms straight and shoulders directly over the bar", "Engage your core and maintain a neutral spine throughout the entire movement", "Drive through your heels and pull the bar up by extending your hips and squeezing your glutes at the top", "Lower the bar back to the pins in a controlled manner, maintaining proper form throughout the descent"]', '["Place les supports de sécurité ou le rack à la hauteur des genoux ou mi-cuisse selon ta mobilité et ta force", "Positionne tes pieds à la largeur des hanches, avec la barre au-dessus du milieu de tes pieds", "Saisis la barre avec les mains juste à l''extérieur de tes jambes, les bras droits et les épaules alignées avec la barre", "Engage ton sangle abdominale et garde une colonne vertébrale neutre pendant tout le mouvement", "Pousse avec tes talons et tire la barre vers le haut en étendant tes hanches et en contractant tes fessiers en haut", "Abaisse la barre vers les supports de manière contrôlée, en maintenant une bonne forme tout au long de la descente"]', '["Garde tes épaules tirées vers l''arrière et vers le bas pour protéger ta colonne vertébrale et maximiser l''engagement du dos", "Concentre-toi sur le mouvement d''articulation des hanches plutôt que sur un squat pour cibler correctement les muscles de la chaîne postérieure", "Choisis un poids qui te permet de garder une forme parfaite, car les tirages rack peuvent supporter des charges plus lourdes que les soulevés de terre classiques", "Évite de trop cambrer ton dos en haut du mouvement : reste simplement droit avec un alignement neutre de la colonne vertébrale", "Commence avec les supports à hauteur de genoux si tu es novice dans cet exercice et abaisse progressivement la position de départ à mesure que ta mobilité s''améliore"]', '["Keep your shoulders pulled back and down throughout the movement to protect your spine and maximize back engagement", "Focus on hip hinge movement rather than squatting to properly target the posterior chain muscles", "Use a weight that allows you to maintain perfect form as rack pulls can handle heavier loads than conventional deadlifts", "Avoid hyperextending your back at the top of the movement - simply stand tall with neutral spine alignment", "Start with pins at knee height if you''re new to the exercise and gradually lower the starting position as mobility improves"]', '24846377-a8c6-4955-86e6-00528b6e2b31', 'rack-pulls', NULL, NULL);
INSERT INTO public.exercises VALUES ('973215b1-696f-4534-b8ce-325d7813ca90', 'Crunchs Papillon', NULL, NULL, 'Butterfly crunches', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/butterfly-crunches.mp4', NULL, NULL, NULL, '/videos/thumbnails/butterfly-crunches.jpg', NULL, '["Garde ton bas du dos bien en contact avec le sol pour protéger ta colonne", "Ne tire pas sur ton cou avec tes mains - laisse tes abdos faire le travail", "Concentre-toi sur le soulèvement de tes omoplates plutôt que juste de ta tête pour maximiser l''engagement de ton core", "Respire régulièrement, ne bloque pas ta respiration durant l''exercice", "La position papillon ajoute du défi en réduisant la stabilité comparé aux crunchs classiques"]', '["Ne pas garder le bas du dos en contact avec le sol", "Tirer sur le cou avec les mains"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "butterfly crunches"]', true, '2026-04-03 12:24:55.858113+00', '2026-04-03 12:24:55.858113+00', 'Allonge-toi sur le dos, les plantes de pieds collées et les genoux pliés vers l''extérieur, formant un losange. Place tes mains derrière la tête. Prêt à solliciter ton core ?', '["Ne pas garder le bas du dos en contact avec le sol", "Tirer sur le cou avec les mains"]', true, '["Lie flat on your back and bring the soles of your feet together, allowing your knees to fall outward naturally", "Place your hands lightly behind your head with fingers interlaced, keeping your elbows wide", "Press your lower back firmly into the floor and engage your core muscles before beginning the movement", "Slowly lift your shoulder blades off the ground by contracting your abs, bringing your chest toward your knees", "Hold the contraction briefly at the top of the movement", "Lower your shoulders back down to the starting position with slow, controlled movement"]', '["Allonge-toi sur le dos et colle les plantes de tes pieds, laisse tes genoux tomber vers l''extérieur", "Place tes mains derrière la tête, les coudes bien ouverts", "Appuie ton bas du dos contre le sol et active tes abdos avant de commencer", "Soulève lentement tes omoplates du sol en contractant tes abdominaux, en rapprochant ta poitrine de tes genoux", "Maintiens la contraction en haut du mouvement un petit instant", "Redescends tes épaules au sol de manière contrôlée et lente"]', '["Garde ton bas du dos bien en contact avec le sol pour protéger ta colonne", "Ne tire pas sur ton cou avec tes mains - laisse tes abdos faire le travail", "Concentre-toi sur le soulèvement de tes omoplates plutôt que juste de ta tête pour maximiser l''engagement de ton core", "Respire régulièrement, ne bloque pas ta respiration durant l''exercice", "La position papillon ajoute du défi en réduisant la stabilité comparé aux crunchs classiques"]', '["Keep your lower back pressed against the floor throughout the entire movement to protect your spine", "Avoid pulling on your neck with your hands - let your abdominal muscles do the work", "Focus on lifting your shoulder blades rather than just your head to maximize core engagement", "Maintain steady breathing and avoid holding your breath during the exercise", "The butterfly leg position increases the challenge by reducing stability compared to regular crunches"]', 'ed1451e4-ceef-4aa9-a883-24b733b83edd', 'butterfly-crunches', NULL, NULL);
INSERT INTO public.exercises VALUES ('8df9b372-fb2b-468f-bb41-d7a4470f988a', 'Tirage assis à la poulie large', NULL, 'تيراج أسيص لابولية ويدج', 'Seated Cable Row Wide Grip', 'Back', '[]', 'Back', 'Intermediate', 4, '/videos/back/seated-cable-row-wide-grip.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-cable-row-wide-grip.jpg', NULL, '["Garde ton torse stable, évite de te balancer ou d''utiliser l''élan pour soulever le poids", "Concentre-toi sur le tirage avec tes muscles du dos, commence le mouvement avec tes coudes", "Maintiens une colonne vertébrale neutre tout au long de l''exercice, sans arrondir les épaules vers l''avant", "Utilise un tempo contrôlé avec une phase négative de 2-3 secondes pour maximiser l''engagement musculaire", "Arrête la poignée au niveau de ton bas de poitrine, ne la tire pas vers ton abdomen."]', '["Utiliser trop de poids et perdre la forme", "Tirer avec les bras au lieu de se concentrer sur le dos", "Se balancer ou utiliser l''élan pour exécuter le mouvement", "Rester trop rigide, négliger la contraction des muscles du dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "seated cable row wide grip"]', true, '2026-04-03 12:24:58.776825+00', '2026-04-03 12:24:58.776825+00', 'Position de départ : Installe-toi sur la machine à poulie basse avec une prise large. Execution : Tire la poignée vers ta poitrine en gardant le dos droit, puis retourne lentement à la position initiale.', '["Utiliser trop de poids et perdre la forme", "Tirer avec les bras au lieu de se concentrer sur le dos", "Se balancer ou utiliser l''élan pour exécuter le mouvement", "Rester trop rigide, négliger la contraction des muscles du dos"]', true, '["Adjust the cable height to chest level and select an appropriate weight", "Sit with your chest up, shoulders back, and maintain a slight forward lean from your hips", "Grasp the wide-grip handle with an overhand grip, arms fully extended", "Initiate the pull by retracting your shoulder blades and driving your elbows straight back", "Pull the handle to your lower chest, focusing on squeezing your back muscles", "Slowly return to starting position, maintaining tension throughout the entire range of motion"]', '["Ajuste la hauteur de la poulie au niveau de la poitrine et sélectionne un poids adapté", "Assieds-toi, poitrine en avant, épaules en arrière, avec une légère inclinaison vers l''avant au niveau des hanches", "Saisis la poignée large avec une prise pronation, bras complètement tendus", "Commence le mouvement en rétractant tes épaules et en poussant tes coudes vers l''arrière", "Tire la poignée jusqu''à ton bas de poitrine, en contractant bien tes muscles du dos", "Retourne lentement à la position de départ, en maintenant la tension durant tout le mouvement."]', '["Garde ton torse stable, évite de te balancer ou d''utiliser l''élan pour soulever le poids", "Concentre-toi sur le tirage avec tes muscles du dos, commence le mouvement avec tes coudes", "Maintiens une colonne vertébrale neutre tout au long de l''exercice, sans arrondir les épaules vers l''avant", "Utilise un tempo contrôlé avec une phase négative de 2-3 secondes pour maximiser l''engagement musculaire", "Arrête la poignée au niveau de ton bas de poitrine, ne la tire pas vers ton abdomen."]', '["Keep your torso stable and avoid excessive swaying or using momentum to move the weight", "Focus on pulling with your back muscles rather than your arms by leading with your elbows", "Maintain a neutral spine throughout the movement and avoid rounding your shoulders forward", "Use a controlled tempo with a 2-3 second negative phase to maximize muscle engagement", "Stop the handle at your lower chest level rather than pulling it into your abdomen"]', 'd39e64fd-25ce-4ab6-9d01-5674d92b5478', 'seated-cable-row-wide-grip', NULL, NULL);
INSERT INTO public.exercises VALUES ('3de48c71-28c0-48b3-b3ba-61db1721bbf5', 'Élévation verticale avec haltère à une main (G)', NULL, NULL, 'Dumbbell One-Arm Upright Row (L)', 'Back', '[]', 'Back', 'Intermediate', 2, '/videos/back/dumbbell-one-arm-upright-row-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-one-arm-upright-row-l.jpg', NULL, '["Garde l''haltère proche de ton corps pendant tout le mouvement pour maintenir une bonne forme et réduire la tension sur l''épaule.", "Lève ton coude et assure-toi qu''il est plus haut que ton poignet au sommet du mouvement pour cibler efficacement le haut du dos et les deltoïdes postérieurs.", "Évite d''utiliser l''élan ou de balancer le poids - privilégie des mouvements lents et contrôlés.", "Arrête le mouvement vers le haut lorsque l''haltère atteint la hauteur de ta poitrine pour prévenir les douleurs à l''épaule.", "Maintiens une colonne vertébrale neutre et évite de te pencher de l''autre côté pendant l''exercice."]', '["Muscler les épaules plutôt que le dos en utilisant trop d''élan.", "Ne pas tenir l''haltère assez près du corps durant le mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "dumbbell one-arm upright row (l)"]', true, '2026-04-03 12:24:56.52884+00', '2026-04-03 12:24:56.52884+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, en tenant un haltère dans ta main gauche, bras étendu le long du corps. Exécution : Tire l''haltère vers le haut le long de ton corps en levant ton coude haut et en l''élargissant jusqu''à atteindre la hauteur de ta poitrine, puis redescends lentement à la position de départ.', '["Muscler les épaules plutôt que le dos en utilisant trop d''élan.", "Ne pas tenir l''haltère assez près du corps durant le mouvement."]', true, '["Stand with feet hip-width apart and core engaged, holding the dumbbell in your left hand with palm facing your body", "Keep your torso upright and shoulders square, avoiding any leaning or rotating movements", "Initiate the movement by pulling your left elbow up and out to the side, leading with the elbow rather than the hand", "Pull the dumbbell straight up along your torso until it reaches chest level, keeping the weight close to your body", "Pause briefly at the top position, then slowly lower the dumbbell back to the starting position with control", "Complete all repetitions on the left side before switching to the right arm"]', '["Tiens-toi droit, les pieds écartés à la largeur des hanches et le gainage actif, en tenant l''haltère dans ta main gauche, paume tournée vers ton corps.", "Garde le torse droit et les épaules carrées, sans te pencher ni tourner le buste.", "Commence le mouvement en levant ton coude gauche vers le haut et sur le côté, en menant avec le coude plutôt qu''avec la main.", "Tire l''haltère le long de ton torse jusqu''à ce qu''il atteigne la hauteur de ta poitrine, en gardant le poids proche de ton corps.", "Marque une pause en haut du mouvement, puis abaisse lentement l''haltère à la position de départ avec contrôle.", "Termine toutes les répétitions sur le côté gauche avant de passer à la droite."]', '["Garde l''haltère proche de ton corps pendant tout le mouvement pour maintenir une bonne forme et réduire la tension sur l''épaule.", "Lève ton coude et assure-toi qu''il est plus haut que ton poignet au sommet du mouvement pour cibler efficacement le haut du dos et les deltoïdes postérieurs.", "Évite d''utiliser l''élan ou de balancer le poids - privilégie des mouvements lents et contrôlés.", "Arrête le mouvement vers le haut lorsque l''haltère atteint la hauteur de ta poitrine pour prévenir les douleurs à l''épaule.", "Maintiens une colonne vertébrale neutre et évite de te pencher de l''autre côté pendant l''exercice."]', '["Keep the dumbbell close to your body throughout the entire movement to maintain proper form and reduce shoulder strain", "Lead with your elbow and keep it higher than your wrist at the top of the movement to properly target the upper back and rear deltoids", "Avoid using momentum or swinging the weight - maintain slow, controlled movements throughout the exercise", "Stop the upward movement when the dumbbell reaches chest level to prevent shoulder impingement", "Maintain neutral spine alignment and avoid leaning away from the working side during the exercise"]', 'ac7982bb-1a81-4870-ae78-ce37bb485601', 'dumbbell-one-arm-upright-row-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('fd965d48-37e3-4550-8d1e-94bbec04306d', 'Cable Kickback pour des fessiers en béton', NULL, 'Cable Kickback pour des fessiers en béton', 'Cable Kickback', 'Glutes', '[]', 'Glutes', 'Beginner', 4, '/videos/glutes/cable-kickback.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-kickback.jpg', NULL, '["Garde ton torse droit et évite de pencher en avant ou d''arquer ton dos", "Concentre-toi sur le mouvement au niveau de la hanche en gardant la jambe de travail droite", "Contrôle le poids pendant les phases de montée et de descente pour maximiser l''activation musculaire", "Évite de balancer ta jambe ou d''utiliser l''élan pour terminer le mouvement", "Garde tes hanches carrées et tournées vers l''avant durant tout l''exercice"]', '["Ne pas contracter les fessiers assez fort", "Balancer la jambe plutôt que de la contrôler"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "cable", "cable kickback"]', true, '2026-04-03 12:24:55.926625+00', '2026-04-03 12:24:55.926625+00', 'Position de départ : Fais face à la machine avec un strap de cheville attaché et un pied légèrement en avant. Exécution : Étends ta jambe vers l''arrière en contractant tes fessiers, puis reviens lentement à la position de départ et répète avec l''autre jambe.', '["Ne pas contracter les fessiers assez fort", "Balancer la jambe plutôt que de la contrôler"]', true, '["Attach the ankle cuff to your working leg and position yourself facing the cable machine", "Hold onto the machine or handles for balance and stability", "Keep a slight bend in your standing leg and engage your core", "Drive your working leg straight back by squeezing your glutes, keeping the leg straight", "Pause briefly at the top of the movement when you feel maximum glute contraction", "Slowly lower your leg back to starting position with control, maintaining tension"]', '["Fixe la sangle de cheville sur la jambe que tu travailles et place-toi face à la machine à câble", "Tiens-toi à la machine ou aux poignées pour l''équilibre", "Garde une légère flexion dans ta jambe de soutien et engage ton sangle abdominale", "Pousse ta jambe de travail droit vers l''arrière en contractant tes fessiers, en gardant la jambe droite", "Fais une pause en haut du mouvement lorsque tu ressens la contraction maximale des fessiers", "Redescends lentement ta jambe à la position de départ en contrôlant le mouvement, en gardant la tension"]', '["Garde ton torse droit et évite de pencher en avant ou d''arquer ton dos", "Concentre-toi sur le mouvement au niveau de la hanche en gardant la jambe de travail droite", "Contrôle le poids pendant les phases de montée et de descente pour maximiser l''activation musculaire", "Évite de balancer ta jambe ou d''utiliser l''élan pour terminer le mouvement", "Garde tes hanches carrées et tournées vers l''avant durant tout l''exercice"]', '["Keep your torso upright and avoid leaning forward or arching your back excessively", "Focus on moving only at the hip joint while keeping your working leg straight", "Control the weight on both the lifting and lowering phases to maximize muscle activation", "Avoid swinging your leg or using momentum to complete the movement", "Keep your hips square and facing forward throughout the entire exercise"]', 'cd2bfdbe-71d7-4d3e-8b03-fc4a5ed73bf4', 'cable-kickback', NULL, NULL);
INSERT INTO public.exercises VALUES ('453684fa-a7d3-4d96-91dd-f57ae2b63181', 'Cable Rope Pullover', NULL, 'سحب بالحبل من أعلى', 'Cable Rope Pullover', 'Back', '[]', 'Back', 'Intermediate', 4, '/videos/back/cable-rope-pullover.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-rope-pullover.jpg', NULL, '["Gardez les bras droits pendant tout le mouvement pour cibler correctement les dorsaux", "Maintenez une légère inclinaison vers l''avant et contractez votre sangle abdominale pour protéger le bas du dos", "Concentrez-vous sur l''utilisation de vos dorsaux plutôt que de vos bras ou épaules", "Contrôlez le poids pendant les phases de descente et de montée du mouvement", "Évitez de vous balancer ou d''utiliser de l''élan pour compléter la répétition."]', '["Ne pas garder les bras droits", "Tirer avec les épaules plutôt qu''avec les dorsaux"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "cable rope pullover"]', true, '2026-04-03 12:24:55.956726+00', '2026-04-03 12:24:55.956726+00', 'Position de départ : Restez face à une poulie haute avec un câble et une corde. Exécution : Tirez la corde vers vos cuisses en gardant les coudes légèrement pliés, puis revenez lentement à la position de départ.', '["Ne pas garder les bras droits", "Tirer avec les épaules plutôt qu''avec les dorsaux"]', true, '["Set the cable machine to the highest position and attach a rope handle", "Stand approximately 2-3 feet away from the machine facing the cable stack", "Grasp the rope with both hands using a neutral grip, arms fully extended overhead", "Engage your core and maintain a slight forward lean throughout the movement", "Pull the rope down and back toward your hips in a smooth arc while keeping arms straight", "Slowly return to the starting position with controlled resistance"]', '["Réglez la machine à câble à la position la plus haute et attachez une poignée de corde", "Placez-vous à environ 60-90 cm de la machine, face au support de câble", "Prenez la corde à deux mains en utilisant une prise neutre, les bras tendus au-dessus de la tête", "Contractez votre sangle abdominale et gardez légèrement le buste penché en avant tout au long de l''exercice", "Tirez la corde vers le bas et vers l''arrière, en arc, vers vos hanches tout en gardant les bras droits", "Revenez lentement à la position de départ avec un mouvement contrôlé."]', '["Gardez les bras droits pendant tout le mouvement pour cibler correctement les dorsaux", "Maintenez une légère inclinaison vers l''avant et contractez votre sangle abdominale pour protéger le bas du dos", "Concentrez-vous sur l''utilisation de vos dorsaux plutôt que de vos bras ou épaules", "Contrôlez le poids pendant les phases de descente et de montée du mouvement", "Évitez de vous balancer ou d''utiliser de l''élan pour compléter la répétition."]', '["Keep your arms straight throughout the entire movement to properly target the lats", "Maintain a slight forward lean and engaged core to protect your lower back", "Focus on pulling with your lats rather than using your arms or shoulders", "Control the weight on both the lowering and raising phases of the movement", "Avoid using momentum or swinging your body to complete the repetition"]', 'b4824ea0-4d0a-418e-b22d-462b11dc9992', 'cable-rope-pullover', NULL, NULL);
INSERT INTO public.exercises VALUES ('e260d94a-7b45-485e-ac0a-0282292c3037', 'Posture du Sphinx', NULL, 'وضعية سنزة', 'Sphinx pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/sphinx-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/sphinx-pose.jpg', NULL, '["Garde tes épaules loin des oreilles.", "Active doucement tes muscles du bas du dos.", "C''est une légère flexion arrière — ne force pas !"]', '["Ne pas cambrer le dos trop fort.", "Les épaules trop remontées vers les oreilles."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "sphinx pose"]', true, '2026-04-03 12:24:59.404546+00', '2026-04-03 12:24:59.404546+00', 'Renforce ton dos et améliore ta souplesse avec cette posture puissante !', '["Ne pas cambrer le dos trop fort.", "Les épaules trop remontées vers les oreilles."]', true, '["Lie face down and place your forearms on the floor with elbows under shoulders.", "Press your forearms into the floor and lift your chest.", "Keep your legs extended and the tops of your feet on the floor.", "Hold and breathe, gently lifting through the chest."]', '["Allonge-toi sur le ventre, les avant-bras au sol et les coudes sous les épaules.", "Enfonce tes avant-bras dans le sol et soulève ta poitrine.", "Tiens tes jambes tendues, avec le dessus des pieds au sol.", "Maintiens la position en respirant, en levant doucement la poitrine."]', '["Garde tes épaules loin des oreilles.", "Active doucement tes muscles du bas du dos.", "C''est une légère flexion arrière — ne force pas !"]', '["Keep your shoulders away from your ears.", "Engage your lower back muscles gently.", "This is a gentle backbend — do not force."]', 'c490cf34-6f30-421c-9dbb-d30b5f796efd', 'sphinx-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('417ab0b7-d69d-4bc2-a3d4-f78ba1fc52a2', 'Tirage Unilatéral avec Haltère', NULL, 'تيراج أونيلاتير مع هالتير', 'Single Arm Dumbbell Row', 'Back', '[]', 'Back', 'Beginner', 2, '/videos/back/single-arm-dumbbell-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-dumbbell-row.jpg', NULL, '["Active ton tronc et évite de faire pivoter ton torse pendant l''exercice.", "Concentre-toi sur le tirage avec tes muscles du dos et non seulement avec ton bras.", "Garde une colonne vertébrale neutre tout au long de l''exercice.", "Prends un amplitude complète, sans laisser l''haltère tirer ton épaule vers l''avant en bas.", "Choisis un poids qui te permet de maintenir la bonne forme sur toutes les répétitions."]', '["Ne pas garder le dos droit pendant l''exercice.", "Tirer uniquement avec le bras au lieu de se concentrer sur le dos."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "dumbbell", "single arm dumbbell row"]', true, '2026-04-03 12:24:59.184291+00', '2026-04-03 12:24:59.184291+00', 'Place-toi en position start : un genou et la main du même côté sur le banc, l’autre main tenant un haltère. Exécute le mouvement en tirant l’haltère vers ta poitrine tout en gardant le dos droit. Redescends lentement à la position de départ. Répète avec l’autre bras.', '["Ne pas garder le dos droit pendant l''exercice.", "Tirer uniquement avec le bras au lieu de se concentrer sur le dos."]', true, '["Position yourself with one knee and same-side hand on a bench, keeping your back straight and parallel to the floor", "Hold the dumbbell in your free hand with a neutral grip, allowing your arm to hang straight down", "Initiate the movement by pulling your shoulder blade back and driving your elbow toward your hip", "Squeeze your back muscles at the top of the movement when the dumbbell reaches your lower ribcage", "Slowly lower the dumbbell back to the starting position with control", "Complete all repetitions on one side before switching to the other arm"]', '["Positionne-toi avec un genou et la main du même côté sur le banc, en gardant le dos droit et parallèle au sol.", "Tiens l''haltère dans l''autre main avec une prise neutre, le bras laissant pendre l''haltère.", "Commence le mouvement en tirant l’omoplate en arrière et en dirigeant ton coude vers la hanche.", "Contracte tes muscles du dos lorsque l''haltère atteint la zone de tes côtes inférieures.", "Redescends lentement l''haltère à la position de départ en maîtrisant le mouvement.", "Termine toutes les répétitions d''un côté avant de passer à l''autre bras."]', '["Active ton tronc et évite de faire pivoter ton torse pendant l''exercice.", "Concentre-toi sur le tirage avec tes muscles du dos et non seulement avec ton bras.", "Garde une colonne vertébrale neutre tout au long de l''exercice.", "Prends un amplitude complète, sans laisser l''haltère tirer ton épaule vers l''avant en bas.", "Choisis un poids qui te permet de maintenir la bonne forme sur toutes les répétitions."]', '["Keep your core engaged and avoid rotating your torso during the movement", "Focus on pulling with your back muscles rather than just your arm", "Maintain a neutral spine throughout the entire exercise", "Use a full range of motion but avoid letting the dumbbell pull your shoulder forward at the bottom", "Choose a weight that allows you to maintain proper form for all repetitions"]', 'a299ccb1-0604-4d47-a5c1-19d5ca0e8b42', 'single-arm-dumbbell-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('fde3f19c-49fe-4f6e-b4c9-1cc8110e03a7', 'Pose du Chat', NULL, NULL, 'Cat pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/cat-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/cat-pose.jpg', NULL, '["Appuyez fermement sur vos mains.", "Attirez votre nombril vers votre colonne vertébrale.", "Gardez les bras droits tout au long de l''exercice."]', '["Ne pas arrondir suffisamment le dos.", "Ne pas garder les bras tendus."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "cat pose"]', true, '2026-04-03 12:24:56.048063+00', '2026-04-03 12:24:56.048063+00', 'Position de départ : Mettez-vous à quatre pattes, les poignets sous les épaules et les genoux sous les hanches. Exécution : Arrondissez lentement votre colonne vertébrale vers le plafond en abaissant la tête et le coccyx, comme un chat en colère.', '["Ne pas arrondir suffisamment le dos.", "Ne pas garder les bras tendus."]', true, '["Start on all fours with wrists under shoulders and knees under hips.", "Exhale and round your spine toward the ceiling.", "Tuck your chin toward your chest and your tailbone under.", "Hold for a few breaths, then release."]', '["Commencez à quatre pattes, avec les poignets sous les épaules et les genoux sous les hanches.", "Expirez et arrondissez votre dos vers le plafond.", "Rentrez le menton vers la poitrine et le coccyx sous vous.", "Maintenez la position quelques respirations, puis relâchez."]', '["Appuyez fermement sur vos mains.", "Attirez votre nombril vers votre colonne vertébrale.", "Gardez les bras droits tout au long de l''exercice."]', '["Press firmly through your hands.", "Draw your navel toward your spine.", "Keep arms straight throughout."]', '8e75c181-9db4-4e20-8fa7-be744f820f95', 'cat-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('0f71fd28-1448-485d-b87b-b613cfcfe08b', 'Pose du Chat et de la Vache', NULL, NULL, 'Cat cow pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/cat-cow-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/cat-cow-pose.jpg', NULL, '["Garde les bras droits pendant tout le mouvement.", "Initie le mouvement au niveau du bassin.", "Déplace-toi lentement en synchronisant avec ta respiration."]', '["Ne pas aligner les poignets et les épaules.", "Précipiter les mouvements et perdre la connexion avec la respiration."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "cat cow pose"]', true, '2026-04-03 12:24:56.044504+00', '2026-04-03 12:24:56.044504+00', 'Position de départ : Mets-toi à quatre pattes, les poignets sous les épaules et les genoux sous les hanches. Exécution : Alterne entre cambrer ton dos en levant le regard (pose de la Vache) et arrondir ta colonne vertébrale en rentrant le menton vers la poitrine (pose du Chat).', '["Ne pas aligner les poignets et les épaules.", "Précipiter les mouvements et perdre la connexion avec la respiration."]', true, '["Start on all fours with wrists under shoulders and knees under hips.", "Inhale, drop your belly toward the mat, lift your chest and tailbone (Cow).", "Exhale, round your spine toward the ceiling, tuck your chin and tailbone (Cat).", "Continue flowing between Cat and Cow with each breath."]', '["Commence à quatre pattes avec les poignets sous les épaules et les genoux sous les hanches.", "Inspire, lâche ton ventre vers le sol, soulève ta poitrine et ton coccyx (Vache).", "Expire, arrondis ton dos vers le plafond, rentre le menton et le coccyx (Chat).", "Continue à passer d''une position à l''autre avec chaque respiration."]', '["Garde les bras droits pendant tout le mouvement.", "Initie le mouvement au niveau du bassin.", "Déplace-toi lentement en synchronisant avec ta respiration."]', '["Keep arms straight throughout the movement.", "Initiate the movement from your pelvis.", "Move slowly and synchronize with your breath."]', '675fab33-9f21-4386-8a43-a319d0684841', 'cat-cow-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('113f3141-e32f-4655-aae1-bedc89b715e2', 'Sage Marichi I Pose (Gauche)', NULL, NULL, 'Sage marichi I pose (left)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/sage-marichi-i-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/sage-marichi-i-pose-left.jpg', NULL, '["Garde la jambe étendue active en fléchissant le pied et en engageant les quadriceps pour protéger le genou", "Initie la torsion avec ton corps, évite de forcer avec les bras pour prévenir les blessures", "Maintiens une longueur dans ta colonne tout au long du mouvement, évite le dos rond", "Respire régulièrement pendant le maintien, ça peut être intense", "Écoute ton corps, ne force pas la rotation au-delà de ton confort"]', '["Le dos rond lors de la rotation", "Forcer la torsion avec les bras au lieu d''utiliser le torse"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "sage marichi i pose (left)"]', true, '2026-04-03 12:24:58.713889+00', '2026-04-03 12:24:58.713889+00', 'Place-toi sur le tapis, une jambe tendue et l’autre pliée. Enroule ton bras autour du genou plié et redresse ton dos. Prépare-toi à ressentir l’étirement dans tes ischio-jambiers !', '["Le dos rond lors de la rotation", "Forcer la torsion avec les bras au lieu d''utiliser le torse"]', true, '["Sit on the mat with your left leg extended straight and your right knee bent, placing your right foot flat on the floor close to your left inner thigh", "Keep your spine tall and shoulders relaxed as you begin to rotate your torso toward your right knee", "Wrap your left arm around your right shin or knee, hugging it gently toward your chest", "Place your right hand behind you on the mat for support and to help maintain proper spinal alignment", "Hold the twist while breathing deeply, keeping your extended leg active and engaged", "Release slowly by unwinding the twist and returning to the starting position"]', '["Assieds-toi sur le tapis avec ta jambe gauche tendue et ton genou droit plié, le pied droit à plat sur le sol près de la cuisse gauche", "Garde ta colonne droite et tes épaules détendues en tournant ton torse vers ton genou droit", "Enveloppe ton bras gauche autour de ton tibia ou de ton genou droit en le rapprochant doucement de ta poitrine", "Pose ta main droite derrière toi sur le tapis pour le soutien et pour maintenir l’alignement de ta colonne", "Reste dans la torsion en respirant profondément, en gardant ta jambe étendue active et engagée", "Dégrippe lentement en revenant à la position de départ"]', '["Garde la jambe étendue active en fléchissant le pied et en engageant les quadriceps pour protéger le genou", "Initie la torsion avec ton corps, évite de forcer avec les bras pour prévenir les blessures", "Maintiens une longueur dans ta colonne tout au long du mouvement, évite le dos rond", "Respire régulièrement pendant le maintien, ça peut être intense", "Écoute ton corps, ne force pas la rotation au-delà de ton confort"]', '["Keep the extended leg active by flexing the foot and engaging the quadriceps to protect the knee", "Initiate the twist from your core rather than forcing it with your arms to prevent injury", "Maintain length in your spine throughout the movement rather than rounding forward", "Breathe steadily during the hold as twisting poses can feel intense", "Listen to your body and don''t force the rotation beyond your comfortable range of motion"]', 'b94885af-ac1a-4fd6-ac86-39da579a215d', 'sage-marichi-i-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('04522ac4-84f1-464e-a30d-6c9209ec90c4', 'Split en chien tête en bas (gauche)', NULL, NULL, 'Downward facing dog split (left)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/downward-facing-dog-split-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/downward-facing-dog-split-left.jpg', NULL, '["Enfonce bien les mains au sol.", "Garde la jambe levée droite et bien engagée.", "Évite d''ouvrir la hanche de la jambe levée."]', '["Ne pas engager la jambe au sol.", "Ouvrir la hanche de la jambe levée.", "Ne pas garder les hanches carrées."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "downward facing dog split (left)"]', true, '2026-04-03 12:24:56.356835+00', '2026-04-03 12:24:56.356835+00', 'Position de départ : Commence en position de chien tête en bas classique, les mains posées à largeur des épaules, les pieds à largeur des hanches, le corps formant un V inversé. Exécution : Lève ta jambe gauche bien droite vers le plafond tout en maintenant la position de chien tête en bas, créant une posture à trois membres qui cible les ischio-jambiers de la jambe au sol et de la jambe levée.', '["Ne pas engager la jambe au sol.", "Ouvrir la hanche de la jambe levée.", "Ne pas garder les hanches carrées."]', true, '["Start in Downward-Facing Dog.", "Shift your weight into both hands evenly.", "Lift one leg high toward the ceiling.", "Keep your hips square and your standing leg strong."]', '["Commence en chien tête en bas.", "Transfère ton poids également sur les deux mains.", "Lève une jambe haut vers le plafond.", "Garde tes hanches carrées et ta jambe au sol solide."]', '["Enfonce bien les mains au sol.", "Garde la jambe levée droite et bien engagée.", "Évite d''ouvrir la hanche de la jambe levée."]', '["Press evenly through both hands.", "Keep the raised leg straight and engaged.", "Avoid opening the hip of the raised leg."]', '4eaaeaca-6966-4b55-94a0-4a34520bb5b9', 'downward-facing-dog-split-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('a7d98567-c259-4eab-9ecf-9a2ee719c3fc', 'Posture de l''Enfant - Bas du Dos', NULL, 'وضعية الطفل - أسفل الظهر', 'Child_s pose -Lower back', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/childs-pose-lower-back.mp4', NULL, NULL, NULL, '/videos/thumbnails/childs-pose-lower-back.jpg', NULL, '["Éloigne un peu tes genoux si tu ressens une gêne aux genoux ou si tu as un ventre plus volumineux", "Concentre-toi sur ta respiration profonde et détendue pour maximiser les bienfaits de cette posture apaisante", "Ne force pas l''étirement - laisse la gravité approfondir la position naturellement avec le temps", "Si tu n''arrives pas à t''asseoir sur tes talons, place un coussin ou un traversin entre tes mollets et tes cuisses pour te soutenir", "Cette posture doit être relaxante et ne jamais causer de douleur aux genoux, hanches ou bas du dos"]', '["Trop forcer l''étirement, ce qui peut provoquer des douleurs", "Maintenir le souffle court ou stressé, ce qui diminue les bienfaits de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "child_s pose -lower back"]', true, '2026-04-03 12:24:56.077572+00', '2026-04-03 12:24:56.077572+00', 'Prends un moment pour te ressourcer avec cette étire de l''Enfant ! Elle cible le bas du dos et tout le corps, parfaite pour relâcher les tensions.', '["Trop forcer l''étirement, ce qui peut provoquer des douleurs", "Maintenir le souffle court ou stressé, ce qui diminue les bienfaits de l''exercice"]', true, '["Start in a tabletop position with hands directly under shoulders and knees under hips", "Slowly shift your weight back, sitting your hips toward your heels", "Extend your arms forward on the ground while lowering your chest and forehead toward the floor", "Allow your lower back to gently round and relax into the stretch", "Hold the position while breathing deeply and slowly", "To exit, slowly roll up vertebra by vertebra back to the starting position"]', '["Commence à quatre pattes, mains sous les épaules et genoux sous les hanches", "Tout doucement, déplace ton poids vers l''arrière, en t''asseyant sur tes talons", "Étends les bras devant toi sur le sol tout en abaissant ta poitrine et ton front vers le sol", "Permets à ton bas du dos de se courber doucement et relaxe-toi dans l''étirement", "Reste dans cette position en respirant profondément et lentement", "Pour sortir, redresse-toi doucement vertèbre par vertèbre en revenant à la position de départ"]', '["Éloigne un peu tes genoux si tu ressens une gêne aux genoux ou si tu as un ventre plus volumineux", "Concentre-toi sur ta respiration profonde et détendue pour maximiser les bienfaits de cette posture apaisante", "Ne force pas l''étirement - laisse la gravité approfondir la position naturellement avec le temps", "Si tu n''arrives pas à t''asseoir sur tes talons, place un coussin ou un traversin entre tes mollets et tes cuisses pour te soutenir", "Cette posture doit être relaxante et ne jamais causer de douleur aux genoux, hanches ou bas du dos"]', '["Keep your knees comfortably apart if you experience any knee discomfort or have a larger midsection", "Focus on deep, relaxed breathing to enhance the stress-relieving benefits of this restorative pose", "Avoid forcing the stretch - let gravity naturally deepen the position over time", "If you cannot sit back on your heels, place a pillow or bolster between your calves and thighs for support", "This pose should feel relaxing and never cause pain in the knees, hips, or lower back"]', 'e6bd8a96-cc6e-4805-bb2d-6755c9350dd9', 'childs-pose-lower-back', NULL, NULL);
INSERT INTO public.exercises VALUES ('0631eebb-8b65-47f2-9ebe-a7824a3e087c', 'Tirage Triceps à la Corde', NULL, 'ترياج ترايiceps', 'Cable Rope Tricep Pushdown', 'Triceps', '[]', 'Triceps', 'Beginner', 4, '/videos/triceps/cable-rope-tricep-pushdown.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-rope-tricep-pushdown.jpg', NULL, '["Garde tes bras supérieurs immobiles pendant tout le mouvement pour bien cibler les triceps", "Maintiens une posture droite avec le gainage actif pour éviter d''utiliser l''élan", "Adopte un tempo contrôlé lors des phases descente et montée du mouvement", "En bas du mouvement, tire légèrement sur les extrémités de la corde pour maximiser la contraction des triceps", "Commence avec un poids léger pour maîtriser la forme avant de passer à des charges plus lourdes"]', '["Ne pas verrouiller les coudes au bas du mouvement", "Utiliser trop de poids et compenser avec le corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "cable", "cable rope tricep pushdown"]', true, '2026-04-03 12:24:55.963194+00', '2026-04-03 12:24:55.963194+00', 'Position de départ : Place-toi face à une poulie haute avec une corde attachée. Exécution : Étends bien les coudes pour pousser les extrémités de la corde vers le bas, en gardant les coudes fixes.', '["Ne pas verrouiller les coudes au bas du mouvement", "Utiliser trop de poids et compenser avec le corps"]', true, '["Set the cable pulley to the highest position and attach a rope handle", "Stand facing the cable machine with feet shoulder-width apart for stability", "Grasp the rope with both hands using an overhand grip, keeping your upper arms pressed against your sides", "Begin the movement by pushing the rope downward, focusing on extending only your forearms", "Continue pushing until your arms are fully extended and the rope reaches your thighs", "Slowly return to the starting position by allowing your forearms to rise back up with control"]', '["Ajuste la poulie à la position la plus haute et fixe la corde", "Positionne-toi face à la machine en gardant les pieds à la largeur des épaules pour un bon équilibre", "Prends la corde avec les deux mains en prise pronation, les bras supérieurs collés à ton corps", "Commence le mouvement en poussant la corde vers le bas, en te concentrant sur l''extension de tes avant-bras", "Pousse jusqu''à ce que tes bras soient complètement étendus et que la corde soit au niveau de tes cuisses", "Redescends lentement à la position de départ en laissant tes avant-bras remonter avec contrôle"]', '["Garde tes bras supérieurs immobiles pendant tout le mouvement pour bien cibler les triceps", "Maintiens une posture droite avec le gainage actif pour éviter d''utiliser l''élan", "Adopte un tempo contrôlé lors des phases descente et montée du mouvement", "En bas du mouvement, tire légèrement sur les extrémités de la corde pour maximiser la contraction des triceps", "Commence avec un poids léger pour maîtriser la forme avant de passer à des charges plus lourdes"]', '["Keep your upper arms stationary throughout the entire movement to isolate the triceps effectively", "Maintain an upright posture with your core engaged to prevent using momentum", "Use a controlled tempo on both the downward and upward phases of the movement", "At the bottom of the movement, pull the rope ends slightly apart to maximize tricep contraction", "Start with lighter weight to master proper form before progressing to heavier loads"]', 'b35c3787-5974-4cca-b3d5-c28f7efa1472', 'cable-rope-tricep-pushdown', NULL, NULL);
INSERT INTO public.exercises VALUES ('e0d1d97e-31ea-49ca-aea0-102368effaee', 'Extension des triceps debout avec haltère', NULL, 'تمرين تمديد الترايسبس بالدمبل', 'Standing Dumbbell Triceps Extension', 'Triceps', '[]', 'Triceps', 'Intermediate', 2, '/videos/triceps/standing-dumbbell-triceps-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-dumbbell-triceps-extension.jpg', NULL, '["Engage ton ventre et reste bien droit pendant l''exercice.", "Seules tes avant-bras doivent bouger - maintiens tes bras supérieurs immobiles et les coudes fixes.", "Adopte un tempo contrôlé, surtout lors de la descente, pour maximiser l''engagement musculaire.", "Commence avec un poids léger pour maîtriser la technique avant de passer à des charges plus lourdes.", "Arrête immédiatement si tu ressens une douleur à l''épaule ou au coude."]', '["Ne pas garder les coudes fixes, ce qui réduit l''efficacité de l''exercice.", "Descendre trop rapidement, ce qui augmente le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "dumbbell", "standing dumbbell triceps extension"]', true, '2026-04-03 12:24:59.528326+00', '2026-04-03 12:24:59.528326+00', 'Renforce tes triceps avec cet exercice ciblé qui améliore la puissance de tes bras !', '["Ne pas garder les coudes fixes, ce qui réduit l''efficacité de l''exercice.", "Descendre trop rapidement, ce qui augmente le risque de blessure."]', true, '["Stand with feet shoulder-width apart, holding one dumbbell with both hands behind your head, arms bent at 90 degrees", "Keep your elbows close to your head and pointing forward throughout the movement", "Slowly extend your arms upward by straightening your elbows, lifting the dumbbell overhead", "Pause briefly at the top with arms fully extended", "Lower the dumbbell back to the starting position behind your head in a controlled manner", "Repeat for desired repetitions while maintaining proper form"]', '["Place-toi debout, les pieds écartés à la largeur des épaules, un haltère tenu à deux mains derrière la tête, les bras fléchis à 90 degrés.", "Garde les coudes près de ta tête et pointés vers l''avant tout au long du mouvement.", "Étends lentement tes bras vers le haut en redressant les coudes, soulevant l''haltère au-dessus de ta tête.", "Fais une pause en haut lorsque tes bras sont complètement tendus.", "Redescends l''haltère en contrôlant le mouvement jusqu''à la position de départ derrière ta tête.", "Répète l''exercice pour le nombre de répétitions souhaité en maintenant une bonne forme."]', '["Engage ton ventre et reste bien droit pendant l''exercice.", "Seules tes avant-bras doivent bouger - maintiens tes bras supérieurs immobiles et les coudes fixes.", "Adopte un tempo contrôlé, surtout lors de la descente, pour maximiser l''engagement musculaire.", "Commence avec un poids léger pour maîtriser la technique avant de passer à des charges plus lourdes.", "Arrête immédiatement si tu ressens une douleur à l''épaule ou au coude."]', '["Keep your core engaged and maintain an upright posture throughout the exercise", "Only your forearms should move - keep your upper arms stationary and elbows fixed in position", "Use a controlled tempo, especially on the lowering phase, to maximize muscle engagement", "Start with lighter weight to master the form before progressing to heavier loads", "Stop immediately if you feel any shoulder or elbow discomfort"]', '032ca17e-2678-46e4-baac-b7ef43c283e9', 'standing-dumbbell-triceps-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('5980677c-a0d3-4cca-8c9a-c14dc6c1a0b1', 'Extension des triceps allongé', NULL, NULL, 'Lying Overhead Triceps Extension', 'Triceps', '[]', 'Triceps', 'Intermediate', 1, '/videos/triceps/lying-overhead-triceps-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-overhead-triceps-extension.jpg', NULL, '["Garde les bras supérieurs immobiles pendant tout le mouvement pour cibler les triceps efficacement", "Adopte un rythme contrôlé, évite de laisser le poids tomber rapidement pour protéger tes coudes", "Commence avec une charge légère pour maîtriser la forme avant de passer à des poids plus lourds", "Assure-toi d''avoir une prise solide sur la barre, sans laisser les coudes s''écarter trop"]', '["Laisser les bras supérieurs bouger, ce qui réduit l''activation des triceps", "Descendre le poids trop bas, engendrant une tension excessive sur les coudes"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "barbell", "lying overhead triceps extension"]', true, '2026-04-03 12:24:57.736014+00', '2026-04-03 12:24:57.736014+00', 'Position de départ : Allonge-toi sur un banc plat, barre ou haltères en main, bras tendus vers le haut. Exécution : Abaisse le poids derrière la tête en fléchissant les coudes, puis tends les bras pour revenir à la position initiale.', '["Laisser les bras supérieurs bouger, ce qui réduit l''activation des triceps", "Descendre le poids trop bas, engendrant une tension excessive sur les coudes"]', true, '["Lie flat on a bench and grip the barbell with hands shoulder-width apart using an overhand grip", "Start with arms fully extended above your chest, keeping your core engaged and feet flat on the floor", "Slowly lower the barbell by bending at the elbows only, keeping your upper arms stationary and perpendicular to the floor", "Lower the weight until you feel a stretch in your triceps, typically when the barbell is just behind your head", "Press the weight back up by extending your elbows, focusing on using only your triceps to lift the barbell", "Return to the starting position with arms fully extended, maintaining control throughout the entire movement"]', '["Allonge-toi sur le banc, prends la barre avec les mains écartées à la largeur des épaules en prise pronation", "Maintiens les bras bien tendus au-dessus de ta poitrine, engage ton core et garde les pieds à plat au sol", "Abaisse lentement la barre en fléchissant seulement les coudes, fixe tes bras supérieurs, bien droits et perpendiculaires au sol", "Descends le poids jusqu''à sentir un étirement dans tes triceps, juste derrière ta tête", "Repousse le poids en tendant les coudes, concentre-toi sur l''utilisation de tes triceps pour soulever la barre", "Retourne à la position de départ avec les bras fully tendus, en gardant le contrôle tout au long du mouvement"]', '["Garde les bras supérieurs immobiles pendant tout le mouvement pour cibler les triceps efficacement", "Adopte un rythme contrôlé, évite de laisser le poids tomber rapidement pour protéger tes coudes", "Commence avec une charge légère pour maîtriser la forme avant de passer à des poids plus lourds", "Assure-toi d''avoir une prise solide sur la barre, sans laisser les coudes s''écarter trop"]', '["Keep your upper arms stationary throughout the movement to isolate the triceps effectively", "Use a controlled tempo and avoid letting the weight drop quickly to prevent elbow injury", "Start with lighter weight to master the form before progressing to heavier loads", "Maintain a firm grip on the barbell and avoid letting your elbows flare out excessively"]', '48700743-f688-42d8-99ed-8c1b223d1f55', 'lying-overhead-triceps-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('d1794066-508e-4c1a-a956-a99c352d8050', 'Pose de la porte (gauche)', NULL, NULL, 'Gate pose (left)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/gate-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/gate-pose-left.jpg', NULL, '["Garde tes hanches bien alignées au-dessus de ton genou qui est à terre.", "Ouvre ta poitrine vers le plafond.", "Évite de t''affaisser vers l''avant."]', '["Ne pas maintenir l''alignement des hanches.", "Pencher trop en avant au lieu de sur le côté."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "gate pose (left)"]', true, '2026-04-03 12:24:56.810742+00', '2026-04-03 12:24:56.810742+00', 'Position de départ : À genoux sur le sol, les genoux écartés à la largeur des hanches, étends ta jambe gauche sur le côté, pied à plat. Exécution : Penche ton buste vers la gauche en glissant ta main gauche le long de ta jambe étendue, puis reviens à la position de départ avec contrôle.', '["Ne pas maintenir l''alignement des hanches.", "Pencher trop en avant au lieu de sur le côté."]', true, '["Kneel on the mat and extend one leg out to the side.", "Place the extended foot flat on the floor, toes pointing sideways.", "Inhale and raise the arm on the kneeling side overhead.", "Exhale and lean toward the extended leg, sliding the other hand down the leg."]', '["À genoux sur le tapis, étends une jambe sur le côté.", "Place le pied étendu à plat sur le sol, les orteils pointant sur le côté.", "Inspire et lève le bras du côté où tu es agenouillé au-dessus de ta tête.", "Expire et penche-toi vers la jambe étendue, glissant l''autre main le long de cette jambe."]', '["Garde tes hanches bien alignées au-dessus de ton genou qui est à terre.", "Ouvre ta poitrine vers le plafond.", "Évite de t''affaisser vers l''avant."]', '["Keep your hips stacked over the kneeling knee.", "Open your chest toward the ceiling.", "Do not collapse forward."]', 'fa3347f7-0e8f-446b-a7f0-fbb0f6b22206', 'gate-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('a7f2da44-f1f5-4b22-b814-cfb4b61e6da9', 'Fente Démarra (droite)', NULL, 'زهرية (اليمنى)', 'Crescent lunge (right)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/crescent-lunge-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/crescent-lunge-right.jpg', NULL, '["Assurez-vous que votre genou avant reste aligné avec votre cheville sans dépasser vos orteils", "Restez droit plutôt que de pencher en avant sur votre jambe avant", "Engagez votre jambe arrière et maintenez-la droite pour créer de la stabilité et activer les fléchisseurs de la hanche", "Appuyez sur votre talon avant et gardez votre poids équilibré", "Gardez vos bras actifs et dirigés vers le haut pour intensifier l''étirement dans votre torse"]', '["Pousser le genou avant trop en avant", "Pencher le torse vers l''avant au lieu de rester droit", "Ne pas engager la jambe arrière efficacement", "Ne pas contrôler la respiration pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "crescent lunge (right)"]', true, '2026-04-03 12:24:56.20946+00', '2026-04-03 12:24:56.20946+00', 'Position de départ : Placez-vous en fente profonde avec le pied droit en avant, la jambe gauche étendue derrière, et les bras levés au-dessus de la tête. Exécution : Maintenez cette position statique en gardant une bonne alignement et en respirant régulièrement.', '["Pousser le genou avant trop en avant", "Pencher le torse vers l''avant au lieu de rester droit", "Ne pas engager la jambe arrière efficacement", "Ne pas contrôler la respiration pendant l''exercice"]', true, '["Step your right foot forward into a deep lunge position with your knee directly over your ankle", "Extend your left leg straight back, keeping the back heel lifted and leg active", "Raise both arms straight up overhead with palms facing each other", "Keep your torso upright and engage your core muscles", "Hold the position while breathing deeply and maintaining balance", "Focus on sinking deeper into the lunge while keeping proper form"]', '["Avancez votre pied droit en prenant une profonde fente, genou au-dessus de la cheville", "Étendez votre jambe gauche en arrière, talon relevé et jambe active", "Levez les deux bras au-dessus de votre tête, paumes face à face", "Gardez votre torse droit et engagez vos muscles du tronc", "Maintenez la position en respirant profondément tout en gardant l''équilibre", "Concentrez-vous sur l''enfoncement plus profond dans la fente tout en gardant une forme correcte"]', '["Assurez-vous que votre genou avant reste aligné avec votre cheville sans dépasser vos orteils", "Restez droit plutôt que de pencher en avant sur votre jambe avant", "Engagez votre jambe arrière et maintenez-la droite pour créer de la stabilité et activer les fléchisseurs de la hanche", "Appuyez sur votre talon avant et gardez votre poids équilibré", "Gardez vos bras actifs et dirigés vers le haut pour intensifier l''étirement dans votre torse"]', '["Keep your front knee aligned over your ankle, not pushing forward past your toes", "Maintain an upright torso rather than leaning forward over your front leg", "Engage your back leg and keep it straight to create stability and activate the hip flexors", "Press through your front heel and keep your weight evenly distributed", "Keep your arms active and reaching upward to enhance the stretch through your torso"]', 'db4a932d-2e11-4809-843e-cb3c1df4535b', 'crescent-lunge-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('b72c141b-6946-4331-8277-1fa9e6d32b73', 'Criss-Cross Jumping Jacks', NULL, 'جيم كرس كروس', 'Criss-cross jumping jacks', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/criss-cross-jumping-jacks.mp4', NULL, NULL, NULL, '/videos/thumbnails/criss-cross-jumping-jacks.jpg', NULL, '["Garde ton ventre engagé pour maintenir ton équilibre et ta stabilité.", "Atterris avec les genoux fléchis pour absorber l''impact et protéger tes articulations.", "Tiens une posture droite avec la poitrine en avant et les épaules en arrière.", "Commence à un rythme plus lent pour maîtriser la coordination avant d''accélérer.", "Arrête-toi si tu te sens étourdi ou si tu perds ta bonne forme."]', '["Ne laisse pas tes bras tomber, garde-les actifs et engageants.", "Évite de sauter trop haut, le but est la coordination et le rythme."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "criss-cross jumping jacks"]', true, '2026-04-03 12:24:56.215187+00', '2026-04-03 12:24:56.215187+00', 'Mets-toi debout, pieds joints et bras le long du corps, prêt à exploser d''énergie ! Tu vas sauter en croisant une jambe devant l''autre tout en croisant tes bras devant ta poitrine. Prêt ? C''est parti !', '["Ne laisse pas tes bras tomber, garde-les actifs et engageants.", "Évite de sauter trop haut, le but est la coordination et le rythme."]', true, '["Start standing with feet hip-width apart, arms at your sides", "Jump up while simultaneously crossing your right leg in front of your left leg and bringing your arms overhead in an X-pattern (right arm crosses over left)", "Jump back to the starting position with feet hip-width apart and arms at your sides", "Jump up again, this time crossing your left leg in front of your right leg and crossing your left arm over your right arm overhead", "Continue alternating the crossing pattern with both legs and arms in a rhythmic jumping motion", "Land softly on the balls of your feet with slightly bent knees throughout the movement"]', '["Commence en te tenant debout, pieds écartés à la largeur des hanches, bras le long du corps.", "Saute en croisant ta jambe droite devant la gauche et amène tes bras au-dessus de ta tête en formant un X (le bras droit passe au-dessus du gauche).", "Reviens à la position de départ avec les pieds écartés à la largeur des hanches et les bras le long du corps.", "Saute à nouveau en croisant cette fois ta jambe gauche devant la droite et en croisant ton bras gauche au-dessus du droit au-dessus de ta tête.", "Alterne continuellement le croisement des jambes et des bras dans un mouvement de saut rythmique.", "Atterris doucement sur la plante de tes pieds avec les genoux légèrement fléchis pendant tout le mouvement."]', '["Garde ton ventre engagé pour maintenir ton équilibre et ta stabilité.", "Atterris avec les genoux fléchis pour absorber l''impact et protéger tes articulations.", "Tiens une posture droite avec la poitrine en avant et les épaules en arrière.", "Commence à un rythme plus lent pour maîtriser la coordination avant d''accélérer.", "Arrête-toi si tu te sens étourdi ou si tu perds ta bonne forme."]', '["Keep your core engaged throughout to maintain balance and stability", "Land with bent knees to absorb impact and protect your joints", "Maintain an upright posture with your chest up and shoulders back", "Start at a slower pace to master the coordination before increasing speed", "Stop if you feel dizzy or lose proper form"]', '0e43c62b-bcf6-4115-8fa4-3049a4d8f24a', 'criss-cross-jumping-jacks', NULL, NULL);
INSERT INTO public.exercises VALUES ('9f72c54f-1000-4f45-b2d9-a377eac87a1a', 'Écartés avec haltères - Version 2', NULL, NULL, 'Dumbbell fly - v2', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/dumbbell-fly-v2.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-fly-v2.jpg', NULL, '["Garde une légère flexion au niveau de tes coudes durant tout le mouvement pour protéger tes articulations de l''épaule", "Concentre-toi sur l''étirement et la contraction de tes muscles pectoraux plutôt que sur le poids que tu soulèves", "Contrôle la phase excentrique (descente) pour maximiser l''activation musculaire", "Évite de descendre les haltères trop bas pour ne pas fatiguer tes épaules", "Respire correctement : inspire en descendant et expire en soulevant"]', '["Ne pas contrôler le mouvement", "Descendre les haltères trop bas et solliciter les épaules"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "dumbbell fly - v2"]', true, '2026-04-03 12:24:56.454958+00', '2026-04-03 12:24:56.454958+00', 'Position de départ : Allonge-toi sur un banc plat avec un haltère dans chaque main, bras tendus au-dessus de ta poitrine, les coudes légèrement fléchis et les paumes face à face. Exécution : Abaisse les haltères en grand arc jusqu''à ressentir un étirement dans ta poitrine, puis inverse le mouvement pour ramener les poids à la position de départ.', '["Ne pas contrôler le mouvement", "Descendre les haltères trop bas et solliciter les épaules"]', true, '["Lie flat on the bench with your feet firmly planted on the floor and your back pressed against the bench", "Hold dumbbells with a neutral grip, arms extended above your chest with a slight bend in your elbows", "Slowly lower the dumbbells in a controlled arc motion, keeping the slight bend in your elbows constant", "Lower until you feel a good stretch in your chest muscles or the dumbbells reach chest level", "Squeeze your chest muscles and reverse the arc motion to return dumbbells to starting position", "Maintain control throughout the entire range of motion, avoiding any jerky movements"]', '["Allonge-toi à plat sur le banc, les pieds bien ancrés au sol et le dos contre le banc", "Tiens les haltères avec une prise neutre, bras tendus au-dessus de ta poitrine avec un léger fléchissement au niveau des coudes", "Abaisse lentement les haltères en arc contrôlé, en maintenant la légère flexion de tes coudes", "Descends jusqu''à ressentir un bon étirement dans tes muscles pectoraux ou jusqu''à ce que les haltères atteignent le niveau de ta poitrine", "Contracte tes pectoraux et inverse le mouvement pour ramener les haltères à la position de départ", "Garde le contrôle sur toute l’amplitude, évite les mouvements brusques"]', '["Garde une légère flexion au niveau de tes coudes durant tout le mouvement pour protéger tes articulations de l''épaule", "Concentre-toi sur l''étirement et la contraction de tes muscles pectoraux plutôt que sur le poids que tu soulèves", "Contrôle la phase excentrique (descente) pour maximiser l''activation musculaire", "Évite de descendre les haltères trop bas pour ne pas fatiguer tes épaules", "Respire correctement : inspire en descendant et expire en soulevant"]', '["Keep a consistent slight bend in your elbows throughout the movement to protect your shoulder joints", "Focus on feeling the stretch and contraction in your chest muscles rather than moving heavy weight", "Control the eccentric (lowering) portion of the movement to maximize muscle activation", "Avoid lowering the dumbbells too far below chest level to prevent shoulder strain", "Maintain proper breathing by inhaling during the lowering phase and exhaling during the lifting phase"]', 'c60450d9-862c-4dd3-87b1-82f80349964d', 'dumbbell-fly-v2', NULL, NULL);
INSERT INTO public.exercises VALUES ('19bedfb0-fa9f-480f-b14e-3a7f880f461b', 'Écartés à la machine haute', NULL, NULL, 'High Cable Fly', 'Chest', '[]', 'Chest', 'Intermediate', 4, '/videos/chest/high-cable-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-cable-fly.jpg', NULL, '["Inclinez légèrement votre torse en avant et engagez votre core pour plus de stabilité", "Gardez les épaules vers le bas et en arrière pour éviter toute douleur à l''épaule", "Concentrez-vous sur la contraction des muscles pectoraux plutôt que sur l''utilisation des bras pour tirer", "Contrôlez la phase excentrique du mouvement pour maximiser l''engagement musculaire", "Évitez que les poids ne se touchent entre les répétitions pour maintenir une tension constante"]', '["Utiliser trop de poids et compromettre la forme", "Ne pas contracter suffisamment les muscles pectoraux lors de la remontée"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "cable", "high cable fly"]', true, '2026-04-03 12:24:57.094408+00', '2026-04-03 12:24:57.094408+00', 'Position de départ : Réglez les poulies à une hauteur au-dessus de votre tête et saisissez les poignées avec les paumes vers le bas. Exécution : Ouvrez les bras de manière contrôlée, en contractant bien la poitrine, puis revenez à la position de départ.', '["Utiliser trop de poids et compromettre la forme", "Ne pas contracter suffisamment les muscles pectoraux lors de la remontée"]', true, '["Set cable pulleys at shoulder height or slightly above and select appropriate weight", "Stand in the center with one foot slightly forward for stability", "Grasp handles with palms facing forward and arms extended in a wide arc", "Keep a slight bend in your elbows and maintain this angle throughout", "Bring handles together in front of your chest using a smooth arcing motion", "Slowly return to starting position with control, feeling a stretch in your chest"]', '["Réglez les poulies à hauteur d''épaule ou légèrement au-dessus et choisissez un poids approprié", "Tenez-vous au centre avec un pied légèrement en avant pour plus de stabilité", "Saisissez les poignées avec les paumes vers l''avant et les bras étendus en arc large", "Gardez une légère flexion des coudes et maintenez cet angle tout au long de l''exercice", "Ramenez les poignées devant votre poitrine avec un mouvement fluide en arc", "Retournez lentement à la position de départ avec contrôle, en ressentant un étirement dans la poitrine"]', '["Inclinez légèrement votre torse en avant et engagez votre core pour plus de stabilité", "Gardez les épaules vers le bas et en arrière pour éviter toute douleur à l''épaule", "Concentrez-vous sur la contraction des muscles pectoraux plutôt que sur l''utilisation des bras pour tirer", "Contrôlez la phase excentrique du mouvement pour maximiser l''engagement musculaire", "Évitez que les poids ne se touchent entre les répétitions pour maintenir une tension constante"]', '["Maintain a slight forward lean and engage your core for stability", "Keep your shoulders down and back to avoid shoulder impingement", "Focus on squeezing your chest muscles rather than using your arms to pull", "Control the eccentric portion of the movement to maximize muscle engagement", "Avoid letting the weight stack touch between repetitions to maintain constant tension"]', 'ec545ed7-4724-454a-b730-37a425e80080', 'high-cable-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('fd871ba0-a21d-4a17-bcc0-263c21d8233c', 'Dips : Renforce ta poitrine !', NULL, 'Dips : قووّي صدرك!', 'Dips', 'Chest', '[]', 'Chest', 'Beginner', 16, '/videos/chest/dips.mp4', NULL, NULL, NULL, '/videos/thumbnails/dips.jpg', NULL, '["Incline-toi en avant pour solliciter plus la poitrine, reste droit pour cibler les triceps", "Ne descends pas trop (risque de blessure à l''épaule)", "Contrôle la descente", "Verrouille bien en haut", "Ajoute du poids quand le poids du corps devient facile"]', '["Ne pas descendre suffisamment profond", "Ne pas contrôler la descente", "Ne pas verrouiller les bras en haut", "Trop de poids ajouté trop tôt"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "dips"]', true, '2026-04-03 12:24:56.30902+00', '2026-04-03 12:24:56.30902+00', 'Position de départ : Saisis les barres parallèles ou le bord d''un banc solide, bras tendus, corps en suspension avec les pieds décollés du sol ou étendus vers l''avant. Exécution : Abaisse ton corps en fléchissant les coudes jusqu''à ce que tes épaules soient sous les coudes, puis pousse pour revenir à la position de départ.', '["Ne pas descendre suffisamment profond", "Ne pas contrôler la descente", "Ne pas verrouiller les bras en haut", "Trop de poids ajouté trop tôt"]', true, '["Grip parallel bars, arms straight", "Lower body by bending elbows", "Go until upper arms parallel or comfortable depth", "Push up to starting position"]', '["Saisis les barres parallèles, bras tendus", "Abaisse ton corps en fléchissant les coudes", "Descends jusqu''à ce que les bras supérieurs soient parallèles ou à la profondeur confortable", "Pousse pour revenir à la position de départ"]', '["Incline-toi en avant pour solliciter plus la poitrine, reste droit pour cibler les triceps", "Ne descends pas trop (risque de blessure à l''épaule)", "Contrôle la descente", "Verrouille bien en haut", "Ajoute du poids quand le poids du corps devient facile"]', '["Lean forward for more chest, upright for more triceps", "Don''t go too deep (shoulder strain)", "Control the descent", "Full lockout at top", "Add weight when bodyweight is easy"]', '2930d41f-177c-4f36-bd91-4867afb85a3b', 'dips', NULL, NULL);
INSERT INTO public.exercises VALUES ('8e376524-6d82-4626-9abe-0e4768fb68c6', 'Étirement dynamique : Chien tête en bas en éclat (côté droit)', NULL, NULL, 'Downward facing dog split (right)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/downward-facing-dog-split-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/downward-facing-dog-split-right.jpg', NULL, '["Enracine-toi fermement avec tes mains.", "Garde ta jambe levée droite et engagée.", "Évite d''ouvrir la hanche de ta jambe levée."]', '["Ouvrir les hanches, ce qui déséquilibre la posture.", "Courber le dos au lieu de garder une bonne alignement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "downward facing dog split (right)"]', true, '2026-04-03 12:24:56.362352+00', '2026-04-03 12:24:56.362352+00', 'Prends position en chien tête en bas, les mains bien ancrées au sol, les hanches hautes et les pieds bien au sol. Ensuite, lève ta jambe droite vers le ciel tout en gardant l''alignement parfait de ton corps. C''est un exercice qui va chasser la tension de tes ischio-jambiers!', '["Ouvrir les hanches, ce qui déséquilibre la posture.", "Courber le dos au lieu de garder une bonne alignement."]', true, '["Start in Downward-Facing Dog.", "Shift your weight into both hands evenly.", "Lift one leg high toward the ceiling.", "Keep your hips square and your standing leg strong."]', '["Commence en position de Chien Tête en Bas.", "Répartis ton poids de manière équilibrée sur tes deux mains.", "Lève une jambe vers le plafond.", "Garde tes hanches carrées et ta jambe restée solide."]', '["Enracine-toi fermement avec tes mains.", "Garde ta jambe levée droite et engagée.", "Évite d''ouvrir la hanche de ta jambe levée."]', '["Press evenly through both hands.", "Keep the raised leg straight and engaged.", "Avoid opening the hip of the raised leg."]', 'dee6b124-faf4-4d03-a659-e49456892af1', 'downward-facing-dog-split-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('a030f8f2-8b12-4fa1-a9e1-805ad90c5ea1', 'Pompes caméléon et grimpeurs de montagne', NULL, NULL, 'Chameleon push up to mountain climbers', 'Chest', '[]', 'Chest', 'Beginner', 16, '/videos/chest/chameleon-push-up-to-mountain-climbers.mp4', NULL, NULL, NULL, '/videos/thumbnails/chameleon-push-up-to-mountain-climbers.jpg', NULL, '["Garde les hanches basses (ne fais pas de fente)", "Engage bien ton centre", "Accélère pour plus de cardio", "Ralentis pour plus de contrôle", "Exercice complet pour le corps"]', '["Ne pas garder le corps complètement aligné", "Oublier d''engager le centre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "chameleon push up to mountain climbers"]', true, '2026-04-03 12:24:56.071316+00', '2026-04-03 12:24:56.071316+00', 'Position de départ : Mets-toi en position de pompe standard, mains légèrement plus larges que les épaules, corps aligné de la tête aux talons. Exécution : Fais une pompe, puis enchaîne directement avec des grimpeurs en amenant alternativement chaque genou vers la poitrine comme si tu courais, avant de revenir à la position de départ.', '["Ne pas garder le corps complètement aligné", "Oublier d''engager le centre"]', true, '["Start in push-up position", "Drive one knee toward chest", "Quickly switch legs", "Continue alternating at pace"]', '["Commence en position de pompe", "Amène un genou vers la poitrine", "Change rapidement de jambe", "Alterne à un rythme soutenu"]', '["Garde les hanches basses (ne fais pas de fente)", "Engage bien ton centre", "Accélère pour plus de cardio", "Ralentis pour plus de contrôle", "Exercice complet pour le corps"]', '["Keep hips down (don''t pike)", "Core stays engaged", "Speed up for more cardio", "Slow down for more control", "Full body exercise"]', 'a97c208e-1c40-4410-b51a-a86e5cc37a04', 'chameleon-push-up-to-mountain-climbers', NULL, NULL);
INSERT INTO public.exercises VALUES ('f7b6df4e-83e9-4f72-9814-bfcc2aedc735', 'Élévations de mollets avec haltères', NULL, 'رفعات الكاعب مع الدمبل', 'Dumbbel calf raises', 'Calves', '[]', 'Calves', 'Beginner', 2, '/videos/calves/dumbbel-calf-raises.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbel-calf-raises.jpg', NULL, '["Concentre-toi sur l''amplitude complète en te levant le plus haut possible sur les orteils et en descendant complètement", "Évite les rebonds ou l''utilisation de l''élan - le mouvement doit être lent et contrôlé", "Garde les genoux légèrement fléchis mais stables tout au long de l''exercice pour éviter les blessures", "Si tu as des problèmes d''équilibre, effectue l''exercice près d''un mur ou d''une surface stable pour te soutenir", "Commence avec des poids légers pour maîtriser la forme avant de progresser vers des haltères plus lourds"]', '["Ne pas contrôler la descente, ce qui peut entraîner des blessures", "Ne pas contracter les muscles du mollet au maximum en haut du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["calves", "dumbbell", "dumbbel calf raises"]', true, '2026-04-03 12:24:56.379587+00', '2026-04-03 12:24:56.379587+00', 'Position de départ : Tiens-toi droit, haltères à tes côtés, les pieds écartés à la largeur des hanches, le poids bien réparti sur les deux pieds. Exécution : Élève-toi sur la pointe des pieds en contractant les muscles du mollet, maintiens la position brièvement en haut, puis redescends lentement les talons vers la position de départ.', '["Ne pas contrôler la descente, ce qui peut entraîner des blessures", "Ne pas contracter les muscles du mollet au maximum en haut du mouvement"]', true, '["Hold dumbbells with a secure grip at your sides throughout the entire movement", "Keep your core engaged and maintain an upright posture with shoulders back", "Rise up slowly and deliberately onto your toes, focusing on squeezing your calf muscles", "Pause for 1-2 seconds at the top of the movement when on your toes", "Lower your heels back down in a controlled manner, taking 2-3 seconds for the descent", "Maintain balance by keeping your weight centered over your feet"]', '["Tiens les haltères fermement à tes côtés tout au long du mouvement", "Garde le ventre engagé et maintiens une posture droite avec les épaules en arrière", "Monte lentement sur la pointe des pieds, concentre-toi sur la contraction des mollets", "Fais une pause de 1 à 2 secondes en haut du mouvement sur la pointe des pieds", "Redescends les talons de manière contrôlée, prends 2 à 3 secondes pour la descente", "Garde l’équilibre en centrant ton poids sur tes pieds"]', '["Concentre-toi sur l''amplitude complète en te levant le plus haut possible sur les orteils et en descendant complètement", "Évite les rebonds ou l''utilisation de l''élan - le mouvement doit être lent et contrôlé", "Garde les genoux légèrement fléchis mais stables tout au long de l''exercice pour éviter les blessures", "Si tu as des problèmes d''équilibre, effectue l''exercice près d''un mur ou d''une surface stable pour te soutenir", "Commence avec des poids légers pour maîtriser la forme avant de progresser vers des haltères plus lourds"]', '["Focus on the full range of motion by going as high as possible on your toes and lowering completely", "Avoid bouncing or using momentum - the movement should be slow and controlled", "Keep your knees slightly bent but stable throughout the exercise to prevent strain", "If balance is an issue, perform the exercise near a wall or sturdy surface for support", "Start with lighter weights to master the form before progressing to heavier dumbbells"]', 'eda711dc-d4c5-49e6-b323-d8180e41a871', 'dumbbel-calf-raises', NULL, NULL);
INSERT INTO public.exercises VALUES ('f109223a-f04e-464f-878b-b061002ba4dd', 'Pompes Caméléon', NULL, NULL, 'Chameleon push up', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/chameleon-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/chameleon-push-up.jpg', NULL, '["Garde toujours les genoux repliés vers la poitrine pour maintenir la position caméléon", "Engage tes muscles abdominaux pour stabiliser ta position inhabituelle lors des pompes", "Assure-toi d''une bonne position des mains et d''un alignement des poignets pour soutenir l''angle modifié des pompes", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse à cause des exigences d''équilibre", "Cet exercice combine la force du haut du corps avec la stabilité du tronc et l''engagement des fléchisseurs de la hanche"]', '["Ne pas garder les genoux repliés", "Oublier d''engager le tronc"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "chameleon push up"]', true, '2026-04-03 12:24:56.067769+00', '2026-04-03 12:24:56.067769+00', 'Position de départ : Adoptez une position de chien de chasse, mains ancrées au sol, genoux repliés sous le torse, hanches en hauteur. Exécution : Effectuez un mouvement de pompes tout en gardant les genoux repliés durant toute la plage de mouvement.', '["Ne pas garder les genoux repliés", "Oublier d''engager le tronc"]', true, '["Start in a downward dog position with hands shoulder-width apart and knees tucked underneath your torso", "Keep your knees bent and pulled toward your chest throughout the entire movement", "Lower your chest toward the ground by bending your elbows while maintaining the tucked position", "Press back up to the starting position by extending your arms", "Maintain core engagement to keep the knees stable and tucked", "Repeat the movement while keeping the same body position throughout"]', '["Commence dans la position de chien de chasse avec les mains écartées à la largeur des épaules et genoux repliés sous le torse", "Garde les genoux pliés et tirés vers ta poitrine pendant tout le mouvement", "Abaisse ta poitrine vers le sol en pliant les coudes tout en maintenant la position repliée", "Pousse-toi en arrière pour revenir à la position de départ en étendant tes bras", "Engage ton tronc pour stabiliser les genoux et les garder repliés", "Répète le mouvement en gardant la même position corporelle tout au long"]', '["Garde toujours les genoux repliés vers la poitrine pour maintenir la position caméléon", "Engage tes muscles abdominaux pour stabiliser ta position inhabituelle lors des pompes", "Assure-toi d''une bonne position des mains et d''un alignement des poignets pour soutenir l''angle modifié des pompes", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse à cause des exigences d''équilibre", "Cet exercice combine la force du haut du corps avec la stabilité du tronc et l''engagement des fléchisseurs de la hanche"]', '["Keep knees consistently tucked toward the chest to maintain the chameleon position", "Engage your core muscles to stabilize the unusual body position during the push-up", "Maintain proper hand placement and wrist alignment to support the modified push-up angle", "Focus on controlled movement rather than speed due to the challenging balance requirements", "This exercise combines upper body strength with core stability and hip flexor engagement"]', '55bd4c71-78c6-49bd-aaaa-8c03b7528342', 'chameleon-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('6f3cb399-6128-4079-95da-e4abf0acd24c', 'Rotation Externe avec Haltère', NULL, NULL, 'Dumbbell External Rotation', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/dumbbell-external-rotation.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-external-rotation.jpg', NULL, '["Commence avec un poids très léger (0,5 à 2 kg) car les muscles de la coiffe des rotateurs sont petits et sensibles aux blessures.", "Maintiens ton coude contre ton flanc tout au long du mouvement pour cibler les rotateurs externes.", "Effectue le mouvement lentement et de manière contrôlée - cet exercice vise l''activation musculaire et la santé de l''épaule, pas la vitesse ou les poids lourds.", "Stoppe immédiatement si tu ressens une douleur dans l''articulation de l''épaule.", "Concentre-toi sur la sensation dans l''arrière de ton épaule plutôt que de te laisser porter par l''élan."]', '["Ne pas garder le coude collé au corps, ce qui annule l''isolement des rotateurs externes.", "Utiliser un poids trop lourd, ce qui peut engendrer des blessures.", "Effectuer le mouvement trop rapidement, ce qui limite l''activation musculaire."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "dumbbell external rotation"]', true, '2026-04-03 12:24:56.430421+00', '2026-04-03 12:24:56.430421+00', 'Allonge-toi sur le côté, le bras que tu travailles est plié à 90 degrés, tenant un haltère léger, avec ton avant-bras reposant sur ton torse. En gardant ton coude collé à ton flanc, fais tourner ton avant-bras vers le haut et l''extérieur jusqu''à obtenir une position perpendiculaire au sol, puis redescends lentement.', '["Ne pas garder le coude collé au corps, ce qui annule l''isolement des rotateurs externes.", "Utiliser un poids trop lourd, ce qui peut engendrer des blessures.", "Effectuer le mouvement trop rapidement, ce qui limite l''activation musculaire."]', true, '["Lie on your side with your head supported and knees slightly bent for stability", "Hold a light dumbbell in your top hand with your elbow bent at 90 degrees against your side", "Keep your wrist straight and maintain the 90-degree elbow angle throughout the movement", "Slowly rotate your forearm upward until it''s vertical, focusing on controlled movement", "Pause briefly at the top position before slowly lowering back to the starting position", "Complete all repetitions on one side before switching to the other arm"]', '["Allonge-toi sur le côté, soutenant ta tête, les genoux légèrement pliés pour rester stable.", "Prends un haltère léger dans ta main du dessus, le coude plié à 90 degrés collé à ton flanc.", "Garde ton poignet droit et maintiens l''angle de 90 degrés au niveau du coude pendant tout le mouvement.", "Fais tourner lentement ton avant-bras vers le haut jusqu''à ce qu''il soit vertical, en te concentrant sur un mouvement contrôlé.", "Fais une pause brève en haut avant de redescendre lentement à la position de départ.", "Termine toutes les répétitions d''un côté avant de changer de bras."]', '["Commence avec un poids très léger (0,5 à 2 kg) car les muscles de la coiffe des rotateurs sont petits et sensibles aux blessures.", "Maintiens ton coude contre ton flanc tout au long du mouvement pour cibler les rotateurs externes.", "Effectue le mouvement lentement et de manière contrôlée - cet exercice vise l''activation musculaire et la santé de l''épaule, pas la vitesse ou les poids lourds.", "Stoppe immédiatement si tu ressens une douleur dans l''articulation de l''épaule.", "Concentre-toi sur la sensation dans l''arrière de ton épaule plutôt que de te laisser porter par l''élan."]', '["Start with very light weight (2-5 pounds) as the rotator cuff muscles are small and can be easily injured", "Keep your elbow pressed against your side throughout the entire movement to isolate the external rotators", "Move slowly and controlled - this exercise is about muscle activation and shoulder health, not speed or heavy weight", "Stop immediately if you feel any pain in your shoulder joint", "Focus on feeling the work in the back of your shoulder rather than using momentum"]', '3433c651-a0f5-40cb-bdd8-3029f3ba15c5', 'dumbbell-external-rotation', NULL, NULL);
INSERT INTO public.exercises VALUES ('908d5c4e-4d0e-4015-a6ae-cab9cc32dc28', 'Développé Incliné à la Smith Machine', NULL, 'الضغط المائل على آلة سميث', 'Smith Machine Incline Press', 'Chest', '[]', 'Chest', 'Beginner', 8, '/videos/chest/smith-machine-incline-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-incline-press.jpg', NULL, '["Garde les poignets droits et alignés avec tes avant-bras tout au long du mouvement pour éviter les blessures.", "Maintiens une tension constante dans tes muscles pectoraux en ne verrouillant pas complètement tes coudes en haut du mouvement.", "Contrôle la phase négative en prenant 2-3 secondes pour abaisser la barre afin de maximiser l''engagement musculaire.", "Ne soulève jamais le bas de ton dos du banc, cela pourrait causer des blessures et réduire l''efficacité de l''exercice.", "Utilise toujours les butées de sécurité sur la machine Smith au cas où tu ne pourrais pas terminer une répétition."]', '["Ne pas contrôler la descente de la barre, ce qui réduit l''efficacité de l''exercice.", "Ne pas aligner la barre correctement avec la poitrine, ce qui peut entraîner des blessures."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "machine", "smith machine incline press"]', true, '2026-04-03 12:24:59.313198+00', '2026-04-03 12:24:59.313198+00', 'Position de départ : Installe-toi sur un banc incliné dans une machine Smith, la barre en haut. Execution : Abaisse la barre jusqu''à ta poitrine, puis pousse-la vers le haut pour revenir à la position initiale.', '["Ne pas contrôler la descente de la barre, ce qui réduit l''efficacité de l''exercice.", "Ne pas aligner la barre correctement avec la poitrine, ce qui peut entraîner des blessures."]', true, '["Set the bench to a 30-45 degree incline and position it so the bar aligns with your upper chest when lying down", "Lie back with your shoulder blades squeezed together, core engaged, and feet flat on the floor for stability", "Grip the bar with hands slightly wider than shoulder-width apart using an overhand grip", "Unrack the bar by rotating it forward, then lower it slowly to your upper chest while keeping your elbows at a 45-degree angle", "Press the bar back up in a smooth, controlled motion until your arms are fully extended but not locked out", "Rotate the bar back to rack it safely when completing your set"]', '["Règle le banc à un angle de 30-45 degrés pour que la barre soit alignée avec le haut de ta poitrine lorsque tu es allongé.", "Allonge-toi en serrant les omoplates, le ventre engagé et les pieds bien à plat pour la stabilité.", "Prends la barre avec une prise légèrement plus large que la largeur des épaules, en mains pronation.", "Déverrouille la barre en la faisant basculer vers l''avant, puis abaisse-la lentement jusqu''à ton haut de poitrine, en gardant les coudes à un angle de 45 degrés.", "Presse la barre vers le haut de manière fluide et contrôlée jusqu''à ce que tes bras soient complètement tendus sans verrouiller les coudes.", "Rrange la barre en la faisant pivoter pour la remettre en sécurité une fois ton set terminé."]', '["Garde les poignets droits et alignés avec tes avant-bras tout au long du mouvement pour éviter les blessures.", "Maintiens une tension constante dans tes muscles pectoraux en ne verrouillant pas complètement tes coudes en haut du mouvement.", "Contrôle la phase négative en prenant 2-3 secondes pour abaisser la barre afin de maximiser l''engagement musculaire.", "Ne soulève jamais le bas de ton dos du banc, cela pourrait causer des blessures et réduire l''efficacité de l''exercice.", "Utilise toujours les butées de sécurité sur la machine Smith au cas où tu ne pourrais pas terminer une répétition."]', '["Keep your wrists straight and aligned with your forearms throughout the entire movement to prevent injury", "Maintain constant tension in your chest muscles by not fully locking out your elbows at the top of the movement", "Control the negative portion of the lift by taking 2-3 seconds to lower the bar to maximize muscle engagement", "Never lift your lower back off the bench pad as this can lead to injury and reduces exercise effectiveness", "Always use the safety stops on the Smith machine as a backup in case you cannot complete a repetition"]', '43549b73-858b-4225-8fe0-e7d3d32c9535', 'smith-machine-incline-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('6fff3809-b06b-46c9-8179-bf4fc81a6049', 'Élévation latérale arrière avec haltère - Un bras', NULL, NULL, 'Dumbbell Lying Rear Lateral Raise - One arm', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/dumbbell-lying-rear-lateral-raise-one-arm.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-lying-rear-lateral-raise-one-arm.jpg', NULL, '["Utilise un poids plus léger que ce que tu penses, car les deltoïdes arrière sont des muscles petits qui se fatiguent vite", "Garde une légère flexion au niveau du coude tout au long du mouvement pour protéger l''articulation", "Concentre-toi sur la contraction de tes omoplates lorsque tu soulèves pour maximiser l''activation des deltoïdes arrière", "Évite d''utiliser l''élan ou de balancer le poids, cela réduit l''efficacité et augmente le risque de blessure", "Maintiens une respiration correcte en expirant pendant la phase de montée et en inspirant pendant la descente"]', '["Ne pas garder le ventre engagé peut mener à une mauvaise posture, ce qui empêche une bonne activation musculaire", "Lever le poids trop haut ou utiliser trop de poids peut entraîner des tensions articulaires et diminuer l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "dumbbell lying rear lateral raise - one arm"]', true, '2026-04-03 12:24:56.499315+00', '2026-04-03 12:24:56.499315+00', 'Position de départ : Allonge-toi face contre sol sur un banc incliné à 30-45 degrés, un haltère dans une main, bras tendu vers le bas, paume tournée vers l''arrière. Exécution : Lève l''haltère sur le côté jusqu''à ce que ton bras soit parallèle au sol, puis redescends lentement à la position de départ.', '["Ne pas garder le ventre engagé peut mener à une mauvaise posture, ce qui empêche une bonne activation musculaire", "Lever le poids trop haut ou utiliser trop de poids peut entraîner des tensions articulaires et diminuer l''efficacité de l''exercice"]', true, '["Set an inclined bench to 30-45 degrees and lie face down with your chest supported", "Hold a light dumbbell in one hand and let your arm hang straight down with palm facing backward", "Keep your core engaged and maintain contact between your chest and the bench throughout the movement", "Raise the dumbbell out to the side in a controlled arc until your arm is parallel to the floor", "Pause briefly at the top position, then slowly lower the weight back to starting position", "Complete all repetitions on one side before switching to the other arm"]', '["Régle un banc incliné à 30-45 degrés et allonge-toi face contre le banc", "Tiens un haltère léger dans une main, bras pendu vers le bas et paume tournée vers l''arrière", "Active ton ventre et garde le contact entre ta poitrine et le banc pendant l''exercice", "Lève l''haltère sur le côté de manière contrôlée jusqu''à ce que ton bras soit parallèle au sol", "Fais une pause en haut, puis redescends lentement le poids à la position de départ", "Termine toutes les répétitions d''un côté avant de passer à l''autre bras"]', '["Utilise un poids plus léger que ce que tu penses, car les deltoïdes arrière sont des muscles petits qui se fatiguent vite", "Garde une légère flexion au niveau du coude tout au long du mouvement pour protéger l''articulation", "Concentre-toi sur la contraction de tes omoplates lorsque tu soulèves pour maximiser l''activation des deltoïdes arrière", "Évite d''utiliser l''élan ou de balancer le poids, cela réduit l''efficacité et augmente le risque de blessure", "Maintiens une respiration correcte en expirant pendant la phase de montée et en inspirant pendant la descente"]', '["Use a lighter weight than you think you need as the rear deltoids are small muscles that fatigue quickly", "Keep a slight bend in your elbow throughout the entire movement to protect the joint", "Focus on squeezing your shoulder blades together as you lift to maximize rear deltoid activation", "Avoid using momentum or swinging the weight up as this reduces effectiveness and increases injury risk", "Maintain proper breathing by exhaling during the lifting phase and inhaling during the lowering phase"]', 'fa0fd12d-1fd4-448f-9e21-ceda7b8f18eb', 'dumbbell-lying-rear-lateral-raise-one-arm', NULL, NULL);
INSERT INTO public.exercises VALUES ('29c1bf9e-ee2d-404f-91cc-1517ce9aec09', 'Développé couché avec haltères', NULL, NULL, 'Dumbbell Bench Press', 'Chest', '[]', 'Chest', 'Beginner', 2, '/videos/chest/dumbbell-bench-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-bench-press.jpg', NULL, '["Amplitudes de mouvement supérieures à la barre", "Garde les scapulas serrées", "Ne fais pas s''entrechoquer les haltères en haut", "Contrôle la descente", "Pieds à plat sur le sol"]', '["Coudes trop écartés", "Démonstration d''une mauvaise posture du dos", "Omission de la phase de contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "dumbbell bench press"]', true, '2026-04-03 12:24:56.390917+00', '2026-04-03 12:24:56.390917+00', 'Position initiale : Allonge-toi sur un banc plat avec un haltère dans chaque main, bras tendus vers le haut et paumes tournées vers l''avant. Exécution : Abaisse les haltères vers ta poitrine, puis pousse vers le haut pour revenir à la position de départ.', '["Coudes trop écartés", "Démonstration d''une mauvaise posture du dos", "Omission de la phase de contrôle"]', true, '["Lie on bench, dumbbells at sides of chest", "Palms facing forward", "Press dumbbells up until arms extended", "Lower with control to sides of chest"]', '["Allonge-toi sur le banc, haltères près de la poitrine", "Paumes tournées vers l''avant", "Pousse les haltères vers le haut jusqu''à l''extension complète des bras", "Abaisse avec contrôle vers les côtés de la poitrine"]', '["Amplitudes de mouvement supérieures à la barre", "Garde les scapulas serrées", "Ne fais pas s''entrechoquer les haltères en haut", "Contrôle la descente", "Pieds à plat sur le sol"]', '["Greater range of motion than barbell", "Keep shoulder blades squeezed", "Don''t clang dumbbells together at top", "Control the descent", "Feet flat on floor"]', 'a0395420-b67f-4ddd-965d-30d4a489f489', 'dumbbell-bench-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('59cee103-9d20-49cb-9026-6a15ba75a1d3', 'Dips sur banc 2', NULL, 'Dips 3la banc', 'Dips on bench 2', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/dips-on-bench-2.mp4', NULL, NULL, NULL, '/videos/thumbnails/dips-on-bench-2.jpg', NULL, '["Garde les épaules basses et en arrière pour éviter les blessures", "Ne laisse pas tes coudes s''écarter trop pour cibler correctement les muscles de la poitrine", "Arrête-toi si tu ressens une douleur excessive dans les épaules", "Fléchis les genoux et rapproche tes pieds du banc pour faciliter l''exercice", "Vérifie que le banc est stable et peut supporter ton poids avant de commencer"]', '["Positionner les mains trop éloignées du corps", "Laisser les coudes s''éloigner et ne pas contrôler la descente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "dips on bench 2"]', true, '2026-04-03 12:24:56.331554+00', '2026-04-03 12:24:56.331554+00', 'Position de départ : Assieds-toi au bord d''un banc, mains posées à côté de tes hanches et jambes tendues vers l''avant avec les talons au sol. Exécution : Abaisse ton corps en fléchissant les coudes jusqu''à ce que tes bras soient parallèles au sol, puis pousse pour revenir à la position de départ.', '["Positionner les mains trop éloignées du corps", "Laisser les coudes s''éloigner et ne pas contrôler la descente"]', true, '["Position hands firmly on the bench edge with fingers pointing forward and arms fully extended", "Slide your body off the bench while keeping your back close to the bench edge", "Lower your body slowly by bending your elbows, keeping them close to your sides", "Descend until your upper arms are parallel to the floor or you feel a stretch in your chest", "Push through your palms to raise your body back to the starting position", "Maintain control throughout the entire range of motion"]', '["Pose tes mains fermement sur le bord du banc, doigts pointant vers l''avant et bras tendus", "Glisse ton corps hors du banc en gardant le dos près du bord", "Abaisse ton corps lentement en fléchissant les coudes, en les gardant proches de tes côtés", "Descends jusqu''à ce que tes bras soient parallèles au sol ou que tu ressentes un étirement dans ta poitrine", "Pousse avec tes mains pour ramener ton corps à la position de départ", "Garde le contrôle tout au long du mouvement"]', '["Garde les épaules basses et en arrière pour éviter les blessures", "Ne laisse pas tes coudes s''écarter trop pour cibler correctement les muscles de la poitrine", "Arrête-toi si tu ressens une douleur excessive dans les épaules", "Fléchis les genoux et rapproche tes pieds du banc pour faciliter l''exercice", "Vérifie que le banc est stable et peut supporter ton poids avant de commencer"]', '["Keep your shoulders down and back to prevent shoulder impingement", "Avoid letting your elbows flare out too wide to maintain focus on chest muscles", "Stop the descent if you feel excessive strain in your shoulders", "Bend your knees and place feet closer to the bench to make the exercise easier", "Ensure the bench is stable and can support your full body weight before beginning"]', '3add251e-6e58-4f80-902c-ab32e0b61966', 'dips-on-bench-2', NULL, NULL);
INSERT INTO public.exercises VALUES ('ad282ec6-4698-408b-b779-0a4908e017cb', 'Crawl d''ours vers pompes en position pike', NULL, 'تسلق الدب نحو تمارين الضغط في وضعية البيك', 'Bear crawl to pike push up', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/bear-crawl-to-pike-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-crawl-to-pike-push-up.jpg', NULL, '["Garde le ventre bien serré tout au long du mouvement pour protéger ton bas du dos et maintenir une bonne posture", "Respire régulièrement, évite de retenir ta respiration pendant la transition du crawl d''ours à la position pike", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse, surtout lors des transitions", "Assure-toi d''avoir une bonne mobilité des épaules avant d''essayer les pompes pike, car cet exercice demande une flexibilité importante des épaules au-dessus de la tête", "Commence par moins de répétitions et augmente progressivement à mesure que ta force et ta coordination s''améliorent"]', '["Genoux trop bas durant le crawl", "Coudes écartés lors de la pompe pike"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "bear crawl to pike push up"]', true, '2026-04-03 12:24:55.65462+00', '2026-04-03 12:24:55.65462+00', 'Position de départ : Commence dans une position de crawl d''ours, mains et pieds au sol, genoux juste au-dessus du sol, dos droit. Exécution : Avance de 3 à 4 pas, puis ramène tes pieds vers tes mains tout en gardant les jambes droites, en passant à la position de chien tête en bas avant de réaliser une pompe pike en abaissant ta tête vers le sol entre tes mains.', '["Genoux trop bas durant le crawl", "Coudes écartés lors de la pompe pike"]', true, '["Start in bear crawl position with hands shoulder-width apart, core engaged, and knees hovering 2-3 inches off the ground", "Take 3-4 controlled steps forward, moving opposite hand and foot together while maintaining neutral spine", "Stop crawling and begin walking your feet toward your hands, keeping legs as straight as possible", "Continue until you reach an inverted V position with weight distributed between hands and feet", "Lower your head toward the ground between your hands by bending your elbows, keeping them close to your body", "Push back up to the pike position and repeat the sequence"]', '["Commence en position de crawl d''ours avec les mains à la largeur des épaules, le ventre engagé et les genoux flottants à 5-8 cm du sol", "Avance de 3-4 pas contrôlés, en déplaçant simultanément main et pied opposés tout en gardant le dos droit", "Arrête-toi et commence à ramener tes pieds vers tes mains, en maintenant les jambes aussi droites que possible", "Continue jusqu''à atteindre une position en V inversé avec le poids réparti entre les mains et les pieds", "Abaisse ta tête vers le sol entre tes mains en pliant les coudes, en les gardant près de ton corps", "Pousse de nouveau vers la position pike et répète la séquence"]', '["Garde le ventre bien serré tout au long du mouvement pour protéger ton bas du dos et maintenir une bonne posture", "Respire régulièrement, évite de retenir ta respiration pendant la transition du crawl d''ours à la position pike", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse, surtout lors des transitions", "Assure-toi d''avoir une bonne mobilité des épaules avant d''essayer les pompes pike, car cet exercice demande une flexibilité importante des épaules au-dessus de la tête", "Commence par moins de répétitions et augmente progressivement à mesure que ta force et ta coordination s''améliorent"]', '["Keep your core tight throughout the entire movement to protect your lower back and maintain proper form", "Maintain steady breathing and avoid holding your breath during the transition from bear crawl to pike position", "Focus on controlled movements rather than speed, especially when transitioning between positions", "Ensure adequate shoulder mobility before attempting pike push-ups, as this exercise requires significant overhead shoulder flexibility", "Start with fewer repetitions and gradually increase as your strength and coordination improve"]', 'accf9858-fd32-4f43-aa4d-0bd0f53d7498', 'bear-crawl-to-pike-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('926ef1d2-65e1-43b1-a097-65d2cf8581b9', 'Élévation latérale avec haltères', NULL, 'رفع جانبي مع الأثقال', 'Dumbbell deltoid fly', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/dumbbell-deltoid-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-deltoid-fly.jpg', NULL, '["Maintenez vos abdominaux engagés pendant l''exercice pour protéger le bas du dos.", "Gardez une légère flexion dans les coudes, évitez d''avoir les bras complètement tendus.", "Concentrez-vous sur le travail des deltoïdes arrière plutôt que de vous laisser entraîner par l''élan.", "Gardez la tête dans une position neutre, évitez d''arrondir les épaules.", "Choisissez un poids qui vous permet de garder une technique correcte sur toutes les répétitions."]', '["Mauvaise posture : dos arrondi pendant le mouvement.", "Utilisation de l''élan au lieu de la force musculaire pour lever les haltères."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "dumbbell deltoid fly"]', true, '2026-04-03 12:24:56.404959+00', '2026-04-03 12:24:56.404959+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des hanches, haltères dans chaque main. Penchez-vous légèrement en avant en gardant le dos droit et les genoux légèrement pliés. Exécution : Élevez les haltères sur les côtés, les coudes légèrement fléchis, jusqu''à la hauteur des épaules, puis redescendez lentement à la position de départ.', '["Mauvaise posture : dos arrondi pendant le mouvement.", "Utilisation de l''élan au lieu de la force musculaire pour lever les haltères."]', true, '["Stand with feet hip-width apart holding a dumbbell in each hand", "Hinge forward at the hips while maintaining a neutral spine and slight knee bend", "Let the dumbbells hang naturally with arms slightly bent", "Lift the weights out to the sides in a wide arc until they reach shoulder height", "Squeeze your shoulder blades together at the top of the movement", "Slowly lower the dumbbells back to the starting position with control"]', '["Tenez-vous droit, pieds écartés à la largeur des hanches, un haltère dans chaque main.", "Penchez-vous en avant au niveau des hanches tout en gardant le dos neutre et une légère flexion des genoux.", "Laissez les haltères pendre naturellement avec les bras légèrement pliés.", "Élevez les poids sur les côtés dans un arc large jusqu''à atteindre la hauteur des épaules.", "Serrez les omoplates ensemble en haut du mouvement.", "Descendez lentement les haltères à la position de départ en contrôlant le mouvement."]', '["Maintenez vos abdominaux engagés pendant l''exercice pour protéger le bas du dos.", "Gardez une légère flexion dans les coudes, évitez d''avoir les bras complètement tendus.", "Concentrez-vous sur le travail des deltoïdes arrière plutôt que de vous laisser entraîner par l''élan.", "Gardez la tête dans une position neutre, évitez d''arrondir les épaules.", "Choisissez un poids qui vous permet de garder une technique correcte sur toutes les répétitions."]', '["Keep your core engaged throughout the movement to protect your lower back", "Maintain a slight bend in your elbows rather than keeping arms completely straight", "Focus on lifting with your rear deltoids rather than using momentum", "Keep your head in a neutral position and avoid rounding your shoulders", "Use a weight that allows you to maintain proper form throughout all repetitions"]', '097903be-beaa-4283-9493-19eb90b59762', 'dumbbell-deltoid-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('ff6bfa13-ef74-4bd6-b55a-f69c9e98ae24', 'Flexions des poignets avec haltères', NULL, 'Flexions des poignets', 'Dumbbell wrist curls', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/dumbbell-wrist-curls.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-wrist-curls.jpg', NULL, '["Garde tes avant-bras immobiles sur tes cuisses pour vraiment cibler tes muscles avant-bras", "Commence avec un poids léger car les muscles des avant-bras sont plus petits et peuvent se blesser rapidement", "Concentre-toi sur l''amplitude complète du mouvement, de l''extension complète du poignet à la flexion maximale", "Exécute le mouvement lentement et de façon contrôlée pour optimiser l''activation musculaire et éviter les blessures", "Interromps immédiatement l''exercice si tu ressens une douleur aiguë ou un engourdissement dans tes poignets ou mains"]', '["Utiliser un poids trop lourd qui biasse la technique", "Laisser les poignets rebondir au lieu de contrôler le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["forearms", "dumbbell", "dumbbell wrist curls"]', true, '2026-04-03 12:24:56.650634+00', '2026-04-03 12:24:56.650634+00', 'Position de départ : Installe-toi sur un banc, les avant-bras reposant sur tes cuisses, un haltère dans chaque main, les poignets dépassant de tes genoux, paumes vers le haut. Exécution : Contracte doucement tes poignets vers le haut en fléchissant tes avant-bras, puis relâche le poids de manière contrôlée.', '["Utiliser un poids trop lourd qui biasse la technique", "Laisser les poignets rebondir au lieu de contrôler le mouvement"]', true, '["Sit on a bench with your feet flat on the floor and forearms resting comfortably on your thighs", "Hold dumbbells with an underhand grip, allowing your wrists to extend beyond your knees", "Keep your forearms pressed against your thighs throughout the entire movement", "Curl your wrists upward as high as possible while squeezing your forearms", "Lower the dumbbells slowly back to the starting position with your wrists extended", "Maintain constant tension and avoid using momentum or bouncing motions"]', '["Assieds-toi sur un banc, les pieds bien à plat au sol et les avant-bras confortablement posés sur tes cuisses", "Tiens les haltères en prise inversée, laisse tes poignets dépasser de tes genoux", "Maintiens tes avant-bras en contact avec tes cuisses pendant tout le mouvement", "Élève tes poignets aussi haut que possible tout en contractant tes avant-bras", "Redescends lentement les haltères à la position de départ en maintenant tes poignets en extension", "Reste concentré et évite de tricher avec des mouvements brusques ou des rebonds"]', '["Garde tes avant-bras immobiles sur tes cuisses pour vraiment cibler tes muscles avant-bras", "Commence avec un poids léger car les muscles des avant-bras sont plus petits et peuvent se blesser rapidement", "Concentre-toi sur l''amplitude complète du mouvement, de l''extension complète du poignet à la flexion maximale", "Exécute le mouvement lentement et de façon contrôlée pour optimiser l''activation musculaire et éviter les blessures", "Interromps immédiatement l''exercice si tu ressens une douleur aiguë ou un engourdissement dans tes poignets ou mains"]', '["Keep your forearms stationary and pressed against your thighs to isolate the forearm muscles", "Use light weight initially as forearm muscles are smaller and can be easily strained", "Focus on the full range of motion from complete wrist extension to maximum flexion", "Perform the movement slowly and controlled to maximize muscle activation and prevent injury", "Stop immediately if you experience any sharp pain or numbness in your wrists or hands"]', '9a8e40b3-446f-4362-9df4-461931927889', 'dumbbell-wrist-curls', NULL, NULL);
INSERT INTO public.exercises VALUES ('983fb03f-5658-4d97-a6fe-736146e6cef4', 'Touches de talons - v2', NULL, NULL, 'Heel touches - v2', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/heel-touches-v2.mp4', NULL, NULL, NULL, '/videos/thumbnails/heel-touches-v2.jpg', NULL, '["Maintiens le bas du dos plaqué contre le sol durant tout le mouvement", "Concentre-toi sur la flexion latérale de la colonne plutôt que sur le simple mouvement des bras", "Garde une tension constante dans tes abdos en maintenant les épaules hors du sol entre chaque répétition", "Exécute le mouvement lentement et de manière contrôlée pour maximiser l''engagement musculaire et éviter de prendre de l''élan", "Expire en crunchant de chaque côté et respire de manière régulière tout au long de l''exercice"]', '["Ne pas soulever assez les épaules du sol", "Laisser le bas du dos se cambrer durant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "heel touches - v2"]', true, '2026-04-03 12:24:57.080555+00', '2026-04-03 12:24:57.080555+00', 'Position de départ : Allonge-toi sur le dos, les genoux fléchis et les pieds à plat sur le sol, écartés à la largeur des hanches, les bras étendus sur les côtés. Exécution : Soulève légèrement tes épaules du sol et atteins alternativement tes talons avec tes mains, en engageant bien ta ceinture abdominale tout au long du mouvement.', '["Ne pas soulever assez les épaules du sol", "Laisser le bas du dos se cambrer durant le mouvement"]', true, '["Lie on your back with knees bent at 90 degrees and feet flat on the floor", "Place your arms straight at your sides with palms facing down", "Engage your core and lift your shoulder blades slightly off the ground", "Reach your right hand toward your right heel by crunching your torso to the side", "Return to center and immediately reach your left hand toward your left heel", "Continue alternating sides in a controlled rhythm while keeping shoulders elevated"]', '["Allonge-toi sur le dos, genoux fléchis à 90 degrés, pieds à plat sur le sol", "Étends les bras de chaque côté, paumes tournées vers le sol", "Engage ta ceinture abdominale et soulève légèrement les omoplates du sol", "Attrape ton talon droit avec la main droite en crunchant ton torse sur le côté", "Retourne au centre et attrape immédiatement ton talon gauche avec la main gauche", "Alterne les côtés de manière contrôlée tout en maintenant les épaules élevées"]', '["Maintiens le bas du dos plaqué contre le sol durant tout le mouvement", "Concentre-toi sur la flexion latérale de la colonne plutôt que sur le simple mouvement des bras", "Garde une tension constante dans tes abdos en maintenant les épaules hors du sol entre chaque répétition", "Exécute le mouvement lentement et de manière contrôlée pour maximiser l''engagement musculaire et éviter de prendre de l''élan", "Expire en crunchant de chaque côté et respire de manière régulière tout au long de l''exercice"]', '["Keep your lower back pressed into the floor throughout the entire movement", "Focus on lateral flexion of the spine rather than just moving your arms", "Maintain constant tension in your core by keeping shoulders off the ground between reps", "Move slowly and controlled to maximize muscle engagement and prevent momentum", "Exhale as you crunch to each side and maintain steady breathing throughout"]', 'f7d6b197-e10b-45bf-848b-e4be88299c28', 'heel-touches-v2', NULL, NULL);
INSERT INTO public.exercises VALUES ('0c1a130e-b6f5-42a9-9cd3-a3a0a9ececad', 'Jacks avec genoux hauts', NULL, 'جّاكس مع ركب عالية', 'Jacks with high knees', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/jacks-with-high-knees.mp4', NULL, NULL, NULL, '/videos/thumbnails/jacks-with-high-knees.jpg', NULL, '["Garde ton abdominal engagé pour protéger ton dos et maintenir ton équilibre.", "Atterris doucement sur la plante des pieds pour réduire l''impact sur les articulations.", "Élève les genoux jusqu''à la hauteur des hanches pour une efficacité maximale.", "Reste bien droit et évite de pencher en avant pendant les levées de genoux.", "Commence à un rythme modéré et augmente la vitesse seulement si tu peux garder une bonne forme."]', '["Ne pas engager les abdominaux, ce qui peut provoquer des douleurs lombaires.", "Pencher le corps en avant pendant les levées de genoux, ce qui nuit à la posture."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "jacks with high knees"]', true, '2026-04-03 12:24:57.337746+00', '2026-04-03 12:24:57.337746+00', 'Position de départ : Tiens-toi droit, les pieds ensemble et les bras le long du corps. Execution : Alterne entre des jumping jacks et des élévations de genoux, combinant les mouvements des bras des jumping jacks avec des levées de genoux à la hauteur de la poitrine.', '["Ne pas engager les abdominaux, ce qui peut provoquer des douleurs lombaires.", "Pencher le corps en avant pendant les levées de genoux, ce qui nuit à la posture."]', true, '["Stand with feet together, arms at your sides, and engage your core", "Jump feet apart while raising arms overhead, then immediately bring feet back together while lowering arms", "Without pausing, lift your right knee up toward your chest while keeping arms in jumping jack motion", "Lower right leg and immediately lift left knee toward chest, continuing the arm movements", "Continue alternating between jumping jacks and high knee lifts in a fluid, rhythmic pattern", "Maintain controlled breathing throughout the entire movement sequence"]', '["Tiens-toi debout, pieds joints, bras le long du corps, et engage ton abdominal.", "Saute en écartant les pieds tout en levant les bras au-dessus de la tête, puis ramène immédiatement les pieds ensemble tout en abaissant les bras.", "Sans faire de pause, lève ton genou droit vers ta poitrine tout en continuant le mouvement des bras.", "Abaisse la jambe droite et lève tout de suite le genou gauche vers la poitrine, en continuant les mouvements des bras.", "Poursuis l''alternance entre jumping jacks et levées de genoux dans un rythme fluide.", "Maintiens un rythme de respiration contrôlé durant tout le mouvement."]', '["Garde ton abdominal engagé pour protéger ton dos et maintenir ton équilibre.", "Atterris doucement sur la plante des pieds pour réduire l''impact sur les articulations.", "Élève les genoux jusqu''à la hauteur des hanches pour une efficacité maximale.", "Reste bien droit et évite de pencher en avant pendant les levées de genoux.", "Commence à un rythme modéré et augmente la vitesse seulement si tu peux garder une bonne forme."]', '["Keep your core engaged throughout to protect your lower back and maintain balance", "Land softly on the balls of your feet to reduce impact on joints", "Drive knees up to at least hip height for maximum effectiveness", "Maintain an upright posture and avoid leaning forward during knee lifts", "Start at a moderate pace and increase speed only when you can maintain proper form"]', '18a33c56-c0b1-4f28-bb78-4b4cad53372b', 'jacks-with-high-knees', NULL, NULL);
INSERT INTO public.exercises VALUES ('216d924b-3398-4e9a-987d-de0912d12827', 'Maintien en L-sit (barres parallèles ou dip bars)', NULL, NULL, 'L-sit hold (dip bar or paralettes)1', 'Chest', '[]', 'Chest', 'Advanced', 16, '/videos/chest/l-sit-hold-dip-bar-or-paralettes1.mp4', NULL, NULL, NULL, '/videos/thumbnails/l-sit-hold-dip-bar-or-paralettes1.jpg', NULL, '["Cet exercice cible principalement la sangle abdominale et les fléchisseurs de la hanche plutôt que le torse, malgré le groupe musculaire indiqué", "Commencez par des maintiens plus courts de 10 à 15 secondes et augmentez progressivement la durée à mesure que votre force s''améliore", "Gardez les épaules activement abaisées pour prévenir les douleurs et maintenir une bonne forme", "Si vous ne parvenez pas à faire un L-sit complet, progressez en pliant les genoux vers la poitrine ou en réalisant des maintiens soutenus", "Arrêtez immédiatement si vous ressentez une douleur à l''épaule ou si vous ne pouvez pas maintenir vos bras droits"]', '["Ne pas garder les bras complètement tendus", "Soulever les épaules vers les oreilles pendant le maintien"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "l-sit hold (dip bar or paralettes)1"]', true, '2026-04-03 12:24:57.513751+00', '2026-04-03 12:24:57.513751+00', 'Position de départ : Agrippez les barres parallèles ou dip bars avec les bras complètement tendus, les épaules directement au-dessus des mains et les jambes suspendues vers le bas. Exécution : Soulevez vos jambes jusqu''à la hauteur des hanches pour créer une forme de ''L'' avec votre corps tout en gardant les bras droits et en maintenant cette position pendant la durée souhaitée.', '["Ne pas garder les bras complètement tendus", "Soulever les épaules vers les oreilles pendant le maintien"]', true, '["Grip the bars firmly with hands shoulder-width apart and arms completely straight", "Engage your core and lift your legs up until they are parallel to the floor", "Keep your shoulders depressed and away from your ears throughout the hold", "Maintain straight legs and pointed toes while holding the L position", "Breathe steadily and avoid holding your breath during the exercise", "Lower your legs slowly and controlled when you can no longer maintain proper form"]', '["Agrippez fermement les barres avec les mains écartées à la largeur des épaules et les bras complètement droits", "Contractez votre sangle abdominale et levez les jambes jusqu''à ce qu''elles soient parallèles au sol", "Gardez les épaules abaisées et éloignées des oreilles durant tout le maintien", "Maintenez les jambes droites et les orteils pointés tout en tenant la position en L", "Respirez régulièrement et évitez de retenir votre souffle pendant l''exercice", "Abaissez vos jambes lentement et de manière contrôlée lorsque vous ne pouvez plus maintenir la bonne forme"]', '["Cet exercice cible principalement la sangle abdominale et les fléchisseurs de la hanche plutôt que le torse, malgré le groupe musculaire indiqué", "Commencez par des maintiens plus courts de 10 à 15 secondes et augmentez progressivement la durée à mesure que votre force s''améliore", "Gardez les épaules activement abaisées pour prévenir les douleurs et maintenir une bonne forme", "Si vous ne parvenez pas à faire un L-sit complet, progressez en pliant les genoux vers la poitrine ou en réalisant des maintiens soutenus", "Arrêtez immédiatement si vous ressentez une douleur à l''épaule ou si vous ne pouvez pas maintenir vos bras droits"]', '["This exercise primarily targets the core and hip flexors rather than the chest despite the listed muscle group", "Start with shorter holds of 10-15 seconds and gradually increase duration as strength improves", "Keep shoulders actively depressed to prevent shoulder impingement and maintain proper form", "If unable to perform full L-sit, progress by bending knees toward chest or performing supported holds", "Stop immediately if you experience shoulder pain or cannot maintain straight arm position"]', 'bb2079e0-031b-4b5c-873d-8c5202fc33d7', 'l-sit-hold-dip-bar-or-paralettes1', NULL, NULL);
INSERT INTO public.exercises VALUES ('dad56a84-71ce-46c2-b7e1-7bd4bf46c89a', 'Décline Close Grip Dumbbell Press', NULL, NULL, 'Decline Close Grip Dumbbell Press', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/decline-close-grip-dumbbell-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/decline-close-grip-dumbbell-press.jpg', NULL, '["Engage ton tronc tout au long de l''exercice pour rester stable sur le banc décliné", "Concentre-toi sur le maintien des haltères proches l''un de l''autre et des coudes bien collés pour maximiser l''activation des triceps et de la partie interne des pectoraux", "Maîtrise la descente pour éviter les douleurs aux épaules et maximiser l''engagement musculaire", "Choisis un poids qui te permet de garder une bonne forme pendant toutes les répétitions au lieu de trop charger", "Assure-toi de bien respirer en inspirant pendant la descente et en expirant au moment de pousser."]', '["Ne pas verrouiller les coudes complètement en haut", "Écarter les coudes pendant la descente au lieu de les garder collés au corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "decline close grip dumbbell press"]', true, '2026-04-03 12:24:56.272629+00', '2026-04-03 12:24:56.272629+00', 'Position de départ : Allonge-toi sur un banc décliné, un haltère dans chaque main, bras tendus vers le haut, paumes face à face. Exécution : Abaisse les haltères vers ta poitrine en maintenant tes coudes près du corps, puis pousse vers le haut pour revenir à la position initiale.', '["Ne pas verrouiller les coudes complètement en haut", "Écarter les coudes pendant la descente au lieu de les garder collés au corps"]', true, '["Secure your feet firmly in the foot pads and adjust the decline bench to approximately 15-30 degrees", "Hold dumbbells with a neutral grip, positioning them close together above your chest with arms extended", "Lower the weights slowly toward your chest, keeping elbows tucked close to your sides rather than flaring them out", "Pause briefly when the dumbbells reach chest level, feeling a stretch in your chest muscles", "Press the dumbbells back up to starting position in a controlled motion, focusing on squeezing your chest muscles", "Maintain constant tension throughout the movement and avoid locking out your elbows completely at the top"]', '["Fixe bien tes pieds dans les coussins et règle le banc décliné entre 15 et 30 degrés", "Tiens les haltères avec une prise neutre, proche de ton torse et bras tendus", "Abaisse lentement les poids vers ta poitrine, en gardant les coudes collés aux côtés", "Fais une pause lorsque les haltères atteignent le niveau de la poitrine, ressens l''étirement dans tes muscles pectoraux", "Pousse les haltères vers le haut en contrôlant le mouvement, en te concentrant sur la contraction de tes pectoraux", "Garde une tension constante pendant tout le mouvement et évite de bloquer complètement tes coudes en haut."]', '["Engage ton tronc tout au long de l''exercice pour rester stable sur le banc décliné", "Concentre-toi sur le maintien des haltères proches l''un de l''autre et des coudes bien collés pour maximiser l''activation des triceps et de la partie interne des pectoraux", "Maîtrise la descente pour éviter les douleurs aux épaules et maximiser l''engagement musculaire", "Choisis un poids qui te permet de garder une bonne forme pendant toutes les répétitions au lieu de trop charger", "Assure-toi de bien respirer en inspirant pendant la descente et en expirant au moment de pousser."]', '["Keep your core engaged throughout the exercise to maintain stability on the decline bench", "Focus on keeping the dumbbells close together and elbows tucked to maximize triceps and inner chest activation", "Control the negative portion of the movement to prevent shoulder strain and maximize muscle engagement", "Use a weight that allows you to maintain proper form throughout all repetitions rather than going too heavy", "Ensure proper breathing by inhaling during the lowering phase and exhaling during the pressing phase"]', '4c5c90fd-01a3-45f6-a952-712743be9c81', 'decline-close-grip-dumbbell-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('b5acb793-11d1-4120-88fd-2ef165f3451e', 'Étirement en Quatre', NULL, NULL, 'Figure Four Stretch (L)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/figure-four-stretch-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/figure-four-stretch-l.jpg', NULL, '["Assure-toi que le bas de ton dos reste collé au sol pendant tout l''étirement.", "N''oublie pas de rester à l''aise : ne force jamais l''étirement, tire doucement.", "Concentre-toi sur l''appui de ton genou gauche loin de ton corps plutôt que sur la force de tirage avec tes bras.", "Respire régulièrement et relâche-toi dans l''étirement, sans retenir ta respiration.", "En cas de douleur aiguë dans la hanche ou le bas du dos, arrête immédiatement."]', '["Forcer l''étirement au-delà de ses limites.", "Laisser le bas du dos se décoller du sol."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "figure four stretch (l)"]', true, '2026-04-03 12:24:56.711313+00', '2026-04-03 12:24:56.711313+00', 'Allonge-toi sur le dos, jambes fléchies, pieds à plat au sol. Place ton cheville gauche sur ta cuisse droite, juste au-dessus du genou. Tu es prêt à te détendre et à assouplir ton corps !', '["Forcer l''étirement au-delà de ses limites.", "Laisser le bas du dos se décoller du sol."]', true, '["Lie on your back with both knees bent and feet flat on the floor", "Place your left ankle on top of your right thigh, just above the knee", "Thread your hands behind your right thigh, interlacing your fingers", "Gently pull your right leg toward your chest while keeping your back flat on the ground", "Use your left elbow to gently press your left knee away from your body to deepen the stretch", "Hold the stretch for 20-30 seconds while breathing deeply"]', '["Allonge-toi sur le dos avec les genoux fléchis et les pieds à plat au sol.", "Pose ta cheville gauche sur ta cuisse droite, juste au-dessus du genou.", "Glisse tes mains derrière ta cuisse droite, entrelace les doigts.", "Tire doucement ta jambe droite vers ta poitrine en gardant le dos bien plat au sol.", "Utilise ton coude gauche pour appuyer doucement sur ton genou gauche, intensifiant ainsi l''étirement.", "Maintiens la position pendant 20-30 secondes en respirant profondément."]', '["Assure-toi que le bas de ton dos reste collé au sol pendant tout l''étirement.", "N''oublie pas de rester à l''aise : ne force jamais l''étirement, tire doucement.", "Concentre-toi sur l''appui de ton genou gauche loin de ton corps plutôt que sur la force de tirage avec tes bras.", "Respire régulièrement et relâche-toi dans l''étirement, sans retenir ta respiration.", "En cas de douleur aiguë dans la hanche ou le bas du dos, arrête immédiatement."]', '["Keep your lower back pressed against the floor throughout the entire stretch", "Never force the stretch - only pull to a comfortable tension level", "Focus on pressing the knee of the crossed leg away from your body rather than pulling harder with your arms", "Breathe steadily and relax into the stretch rather than holding your breath", "Stop immediately if you feel any sharp pain in your hip or lower back"]', 'f3d25890-dcd5-42b3-8246-a5f596029cc0', 'figure-four-stretch-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('bfe73bae-1446-41cf-9a8f-f1089d639ef7', 'Pose de l''Happy Baby', NULL, 'حركة Happy Baby', 'Happy baby pose', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/happy-baby-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/happy-baby-pose.jpg', NULL, '["Assure-toi que le bas du dos et le sacrum restent au sol.", "Boude doucement d''un côté à l''autre pour masser ta colonne vertébrale.", "Relâche tes épaules et ton cou."]', '["Ne pas garder le bas du dos au sol.", "Rester trop rigide dans les épaules."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "happy baby pose"]', true, '2026-04-03 12:24:57.063894+00', '2026-04-03 12:24:57.063894+00', 'Allonge-toi sur le dos, les genoux fléchis vers la poitrine, en tenant les bords extérieurs de tes pieds. Tire doucement sur tes genoux vers tes aisselles, tout en maintenant le bas du dos plaqué au sol pour étirer confortablement les fessiers et les hanches.', '["Ne pas garder le bas du dos au sol.", "Rester trop rigide dans les épaules."]', true, '["Lie on your back and bring your knees toward your chest.", "Grab the outsides of your feet with your hands.", "Open your knees wider than your torso.", "Gently pull your feet down, keeping your lower back on the mat."]', '["Allonge-toi sur le dos et ramène tes genoux vers ta poitrine.", "Attrape les bords extérieurs de tes pieds avec tes mains.", "Ouvre tes genoux plus largement que ton torse.", "Tire doucement vers le bas en gardant le bas du dos sur le tapis."]', '["Assure-toi que le bas du dos et le sacrum restent au sol.", "Boude doucement d''un côté à l''autre pour masser ta colonne vertébrale.", "Relâche tes épaules et ton cou."]', '["Keep your lower back and sacrum on the floor.", "Rock gently side to side for a spinal massage.", "Relax your shoulders and neck."]', 'aefc423a-3e4b-4ca0-89c8-62484e13f3c0', 'happy-baby-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('714294b1-7364-49bb-a696-a637cfc2b710', 'Élévation de jambe droite au câble', NULL, NULL, 'Cable Straight Leg Kickback', 'Glutes', '[]', 'Glutes', 'Beginner', 4, '/videos/glutes/cable-straight-leg-kickback.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-straight-leg-kickback.jpg', NULL, '["Garde ta jambe de travail complètement droite tout au long de l''exercice pour maximiser l''activation des fessiers.", "Évite de cambrer le bas du dos en gardant ton tronc serré et en maintenant une position de colonne vertébrale neutre.", "Concentre-toi sur la contraction des fessiers en haut du mouvement plutôt que de chercher à pousser la jambe le plus haut possible.", "Contrôle les phases de montée et de descente pour garder une tension constante sur les fessiers.", "Commence léger pour bien maîtriser la forme avant de passer à des poids plus lourds."]', '["Ne pas garder le dos droit et cambrer le bas du dos.", "Utiliser un poids trop lourd dès le début, ce qui peut nuire à la forme."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "cable", "cable straight leg kickback"]', true, '2026-04-03 12:24:55.989303+00', '2026-04-03 12:24:55.989303+00', 'Position de départ : Place-toi face à un poulie basse avec une sangle autour de ta cheville, le pied légèrement en avant. Exécution : Étends ta jambe directement en arrière tout en gardant celle-ci droite, puis retourne lentement à la position de départ et répète avec l''autre jambe.', '["Ne pas garder le dos droit et cambrer le bas du dos.", "Utiliser un poids trop lourd dès le début, ce qui peut nuire à la forme."]', true, '["Attach the ankle strap to your working leg and set the cable to the lowest pulley position", "Stand facing the cable machine with feet hip-width apart, holding the frame for stability", "Keep your core engaged and maintain a slight forward lean from your hips throughout the movement", "Kick your leg straight back without arching your lower back, focusing on moving only at the hip joint", "Squeeze your glutes at the top of the movement and hold for a brief pause", "Lower your leg back to the starting position with control, maintaining tension on the cable"]', '["Fixe la sangle de cheville à la jambe de travail et règle le câble sur la position la plus basse.", "Tiens-toi face à la machine à câbles, les pieds écartés à la largeur des hanches, en tenant le cadre pour la stabilité.", "Engage ton tronc et penche-toi légèrement en avant depuis les hanches pendant tout le mouvement.", "Fais un coup de pied de ta jambe droite en arrière sans cambrer le bas du dos, en te concentrant sur le mouvement au niveau de l’articulation de la hanche.", "Contracte tes fessiers en haut du mouvement et maintiens une courte pause.", "Abaisse ta jambe à la position de départ en contrôlant le mouvement, maintenant la tension sur le câble."]', '["Garde ta jambe de travail complètement droite tout au long de l''exercice pour maximiser l''activation des fessiers.", "Évite de cambrer le bas du dos en gardant ton tronc serré et en maintenant une position de colonne vertébrale neutre.", "Concentre-toi sur la contraction des fessiers en haut du mouvement plutôt que de chercher à pousser la jambe le plus haut possible.", "Contrôle les phases de montée et de descente pour garder une tension constante sur les fessiers.", "Commence léger pour bien maîtriser la forme avant de passer à des poids plus lourds."]', '["Keep your working leg completely straight throughout the entire range of motion to maximize glute activation", "Avoid arching your lower back by keeping your core tight and maintaining a neutral spine position", "Focus on the glute squeeze at the top rather than kicking as high as possible", "Control both the lifting and lowering phases of the movement to maintain constant tension on the glutes", "Start with lighter resistance to master the form before progressing to heavier weights"]', '21dda23e-d221-4800-924e-498f4398f203', 'cable-straight-leg-kickback', NULL, NULL);
INSERT INTO public.exercises VALUES ('bedc9225-4337-437c-9baa-77e0fef5e85e', 'Cable Glute Kickback : Renforce tes fessiers !', NULL, NULL, 'Cable Glute Kickback', 'Glutes', '[]', 'Glutes', 'Beginner', 4, '/videos/glutes/cable-glute-kickback.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-glute-kickback.jpg', NULL, '["Garde tes hanches parallèles et évite de faire pivoter ton bassin pendant le mouvement", "Concentre-toi sur la contraction de ton fessier en haut du mouvement plutôt que de juste soulever ta jambe", "Maintiens une légère flexion dans ta jambe de soutien tout au long de l''exercice", "Contrôle le poids à la montée comme à la descente pour maximiser l''engagement musculaire", "Garde le torse droit et évite de te pencher excessivement en avant"]', '["Oublier de contracter le fessier au sommet du mouvement", "Ne pas garder le tronc engagé et droit pendant l''exécution"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "cable", "cable glute kickback"]', true, '2026-04-03 12:24:55.88938+00', '2026-04-03 12:24:55.88938+00', 'Position de départ : Fais face à une poulie basse avec un bracelet de cheville attaché, ton pied légèrement en avant. Exécution : Étends ta jambe vers l''arrière tout en la gardant droite, puis reviens lentement à la position de départ et répète avec l''autre jambe.', '["Oublier de contracter le fessier au sommet du mouvement", "Ne pas garder le tronc engagé et droit pendant l''exécution"]', true, '["Attach the ankle cuff to the low pulley and secure it around your ankle", "Stand facing the cable machine with your working leg slightly behind your body", "Grip the machine with both hands for stability and engage your core", "Keep your torso upright and kick your leg straight back by contracting your glute", "Hold the peak contraction for one second", "Slowly return your leg to the starting position with control"]', '["Fixe le bracelet de cheville à la poulie basse et sécurise-le autour de ta cheville", "Positionne-toi face à la machine avec la jambe de travail légèrement derrière ton corps", "Attrape la machine avec les deux mains pour plus de stabilité et engage ton tronc", "Garde le torse droit et envoie ta jambe droit vers l''arrière en contractant ton fessier", "Maintiens la contraction au sommet pendant une seconde", "Rends lentement ta jambe à la position de départ en contrôle"]', '["Garde tes hanches parallèles et évite de faire pivoter ton bassin pendant le mouvement", "Concentre-toi sur la contraction de ton fessier en haut du mouvement plutôt que de juste soulever ta jambe", "Maintiens une légère flexion dans ta jambe de soutien tout au long de l''exercice", "Contrôle le poids à la montée comme à la descente pour maximiser l''engagement musculaire", "Garde le torse droit et évite de te pencher excessivement en avant"]', '["Keep your hips square and avoid rotating your pelvis during the movement", "Focus on squeezing your glute at the top of the movement rather than just lifting your leg", "Maintain a slight bend in your supporting leg throughout the exercise", "Control the weight on both the lifting and lowering phases to maximize muscle engagement", "Keep your torso upright and avoid leaning forward excessively"]', 'd3f23ea3-a3d3-46cd-940b-707efea0df5c', 'cable-glute-kickback', NULL, NULL);
INSERT INTO public.exercises VALUES ('80be9516-2648-4021-a6c0-f915f0d80da4', 'Pose de la grenouille', NULL, 'خطة الضفدع', 'Frog pose', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/frog-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/frog-pose.jpg', NULL, '["Garde tes genoux et tes chevilles alignés pour protéger tes articulations des genoux", "Descends seulement jusqu''à où ton corps te le permet naturellement sans douleur", "Concentre-toi sur une respiration profonde pour aider tes muscles à se détendre et à approfondir progressivement l''étirement", "Place un coussin ou un support sous ton torse si tu as besoin de soutien supplémentaire", "Arrête-toi immédiatement si tu ressens une douleur aiguë dans tes genoux, hanches ou bas du dos"]', '["Ne pas aligner les genoux et les chevilles correctement", "Forcer l''étirement au-delà de ses limites naturelles"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "frog pose"]', true, '2026-04-03 12:24:56.78913+00', '2026-04-03 12:24:56.78913+00', 'Position de départ : allonge-toi sur le ventre, les genoux écartés, les tibias parallèles, et les avant-bras au sol pour te soutenir. Exécution : maintiens cette position d’étirement statique, laisse la gravité ouvrir délicatement tes hanches et étirer l’intérieur des cuisses et les fléchisseurs de la hanche.', '["Ne pas aligner les genoux et les chevilles correctement", "Forcer l''étirement au-delà de ses limites naturelles"]', true, '["Begin by kneeling on your mat and gradually lower down to your forearms", "Spread your knees wide apart while keeping your shins parallel to each other", "Rest your forearms on the ground and allow your hips to sink toward the floor", "Breathe deeply and hold the position, focusing on relaxing into the stretch", "Only go as deep as feels comfortable and avoid forcing the stretch", "Hold for 30 seconds to 2 minutes depending on your flexibility level"]', '["Commence par t''agenouiller sur ton tapis et abaisse-toi progressivement sur tes avant-bras", "Écarte tes genoux tout en gardant tes tibias parallèles l''un à l''autre", "Pose tes avant-bras sur le sol et laisse tes hanches descendre vers le sol", "Respire profondément et reste dans cette position, en te concentrant sur le relâchement de l''étirement", "Aller seulement aussi loin que cela soit confortable pour toi sans forcer l''étirement", "Tiens la position pendant 30 secondes à 2 minutes selon ton niveau de flexibilité"]', '["Garde tes genoux et tes chevilles alignés pour protéger tes articulations des genoux", "Descends seulement jusqu''à où ton corps te le permet naturellement sans douleur", "Concentre-toi sur une respiration profonde pour aider tes muscles à se détendre et à approfondir progressivement l''étirement", "Place un coussin ou un support sous ton torse si tu as besoin de soutien supplémentaire", "Arrête-toi immédiatement si tu ressens une douleur aiguë dans tes genoux, hanches ou bas du dos"]', '["Keep your knees and ankles aligned to protect your knee joints", "Only sink as low as your body naturally allows without pain or discomfort", "Focus on breathing deeply to help your muscles relax and deepen the stretch gradually", "Place a pillow or bolster under your torso if you need additional support", "Stop immediately if you feel any sharp pain in your knees, hips, or lower back"]', 'db1a9d2c-5386-41aa-a84f-dad06ac7ea7c', 'frog-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('082c7724-8826-489a-9d18-6fc7efe356fa', 'Posture de la demi-grue (gauche)', NULL, NULL, 'Half frog pose (left)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/half-frog-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-frog-pose-left.jpg', NULL, '["Garde tes deux os iliaques ancrés au sol.", "Ne force pas l''étirement.", "Contracte ton ventre pour protéger ton bas du dos."]', '["Ne pas maintenir une respiration profonde.", "Forcer l''étirement au-delà de ses limites."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "half frog pose (left)"]', true, '2026-04-03 12:24:56.892188+00', '2026-04-03 12:24:56.892188+00', 'Position de départ : Allonge-toi sur le ventre avec ta jambe gauche pliée à 90 degrés, amène ton genou gauche vers ton coude gauche tout en gardant ta jambe droite droite. Execution : Reste dans cette position d''étirement statique en respirant profondément, laisse la gravité ouvrir les fléchisseurs de hanche et active tes fessiers.', '["Ne pas maintenir une respiration profonde.", "Forcer l''étirement au-delà de ses limites."]', true, '["Lie on your stomach and prop yourself up on your forearms.", "Bend one knee and reach back with the same-side hand to hold your foot.", "Gently press your foot toward your hip.", "Hold and breathe, then switch sides."]', '["Allonge-toi sur le ventre et appuie-toi sur tes avant-bras.", "Pli une jambe et attrape ton pied avec la main du même côté.", "Presse doucement ton pied vers ta hanche.", "Reste ici en respirant, puis change de côté."]', '["Garde tes deux os iliaques ancrés au sol.", "Ne force pas l''étirement.", "Contracte ton ventre pour protéger ton bas du dos."]', '["Keep both hip bones pressing into the floor.", "Do not force the stretch.", "Engage your core to protect your lower back."]', '90f429f5-8d29-4ff7-a993-a904d378803d', 'half-frog-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('a0bac433-90bb-469d-be7a-f52e446b381a', 'Pose de la Déesse', NULL, NULL, 'Goddess pose', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/goddess-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/goddess-pose.jpg', NULL, '["Assurez-vous que vos genoux suivent la direction de vos orteils.", "Contractez votre ventre et gardez le dos droit.", "Répartissez votre poids de manière égale sur les deux pieds."]', '["Les genoux qui s''effondrent vers l''intérieur.", "Le dos arrondi au lieu de rester droit."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "goddess pose"]', true, '2026-04-03 12:24:56.850817+00', '2026-04-03 12:24:56.850817+00', 'Position de départ : Éloignez vos pieds au-delà de la largeur des hanches, les orteils orientés à 45 degrés, mains sur les hanches ou en prière devant la poitrine. Exécution : Plongez dans une squat profonde en fléchissant les genoux et en les alignant sur les orteils, puis relevez-vous en engageant les fessiers.', '["Les genoux qui s''effondrent vers l''intérieur.", "Le dos arrondi au lieu de rester droit."]', true, '["Stand with feet wide apart, toes turned out at 45 degrees.", "Bend your knees deeply, sinking your hips toward knee height.", "Bring your arms to a goal-post position or palms together at chest.", "Hold and breathe steadily."]', '["Positionnez vos pieds large, orteils tournés à 45 degrés.", "Fléchissez vos genoux profondément, descendez jusqu''à la hauteur des genoux.", "Amenez vos bras en position de but ou mains joints devant le cœur.", "Maintenez la position et respirez régulièrement."]', '["Assurez-vous que vos genoux suivent la direction de vos orteils.", "Contractez votre ventre et gardez le dos droit.", "Répartissez votre poids de manière égale sur les deux pieds."]', '["Keep knees tracking over your toes.", "Engage your core and keep your spine tall.", "Press evenly through both feet."]', 'c38b24ea-e65d-4561-a0ca-8d578fa6bd32', 'goddess-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('23cf450d-8d3a-4450-b8c3-015262d23098', 'Guerrier II (gauche)', NULL, 'المحارب الثاني (اليسار)', 'Warrior II (left)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/warrior-ii-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/warrior-ii-left.jpg', NULL, '["Assure-toi que ton genou avant reste aligné avec ta cheville.", "Répartis ton poids uniformément sur les deux pieds.", "Garde tes épaules bien au-dessus de tes hanches."]', '["Le genou avant qui dépasse la cheville.", "Les bras mal positionnés en dessous des épaules."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "warrior ii (left)"]', true, '2026-04-03 12:24:59.872351+00', '2026-04-03 12:24:59.872351+00', 'Renforce tes fessiers tout en sculptant ton corps avec la posture du Guerrier II. Prépare-toi à sentir la puissance en toi !', '["Le genou avant qui dépasse la cheville.", "Les bras mal positionnés en dessous des épaules."]', true, '["Stand with feet wide apart, front foot pointing forward.", "Turn your back foot to 90 degrees.", "Bend your front knee to 90 degrees over the ankle.", "Extend your arms out to the sides at shoulder height and gaze over your front hand."]', '["Adopte une position large, les pieds écartés.", "Tourne ton pied arrière à 90 degrés.", "Plie ton genou avant à 90 degrés au-dessus de la cheville.", "Étends tes bras sur les côtés à la hauteur des épaules et fixe ton regard sur ta main avant."]', '["Assure-toi que ton genou avant reste aligné avec ta cheville.", "Répartis ton poids uniformément sur les deux pieds.", "Garde tes épaules bien au-dessus de tes hanches."]', '["Keep your front knee tracking over the ankle.", "Press evenly through both feet.", "Stack your shoulders over your hips."]', 'e76eda64-fb67-4c90-b750-69d7a2e0f846', 'warrior-ii-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('df7bf726-9a3c-41a8-8fd4-40fbe4483a5d', 'Posture du demi-bateau', NULL, NULL, 'Half boat pose', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/half-boat-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-boat-pose.jpg', NULL, '["Garde le dos droit, évite de cambrer.", "Contracte bien tes abdominaux pendant l''exercice.", "C''est une variante de la posture complète du bateau."]', '["Ne pas garder le dos droit.", "Ne pas engager suffisamment les abdominaux."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "half boat pose"]', true, '2026-04-03 12:24:56.883734+00', '2026-04-03 12:24:56.883734+00', 'Asseyez-vous sur le sol, les genoux fléchis et les pieds posés à plat. Placez vos mains derrière vos cuisses pour vous soutenir. Penchez-vous légèrement en arrière, soulevez vos pieds du sol et trouvez votre équilibre sur vos os du siège, avec les tibias parallèles au sol.', '["Ne pas garder le dos droit.", "Ne pas engager suffisamment les abdominaux."]', true, '["Sit on the floor with knees bent and feet flat.", "Lean back slightly and lift your feet off the floor.", "Keep your shins parallel to the floor (knees bent at 90 degrees).", "Extend your arms forward, parallel to the floor."]', '["Asseyez-vous sur le sol, les genoux fléchis et les pieds à plat.", "Pivotez légèrement en arrière et soulevez vos pieds du sol.", "Maintenez vos tibias parallèles au sol (les genoux fléchis à 90 degrés).", "Étendez vos bras vers l''avant, parallèles au sol."]', '["Garde le dos droit, évite de cambrer.", "Contracte bien tes abdominaux pendant l''exercice.", "C''est une variante de la posture complète du bateau."]', '["Keep your spine straight, avoid rounding your back.", "Engage your core throughout.", "This is a modification of full Boat Pose."]', 'a4bd22f6-d98f-47da-9523-ceb6894b9922', 'half-boat-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('7e0ffc95-4ae7-4c46-8468-c40320daa57d', 'Demi-Fente (gauche)', NULL, NULL, 'Half split (left)', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/half-split-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-split-left.jpg', NULL, '["Garde une légère flexion au genou pour protéger l''articulation.", "Hinge à partir des hanches, pas de la taille.", "Respire profondément pendant l''étirement des ischio-jambiers."]', '["Ne pas garder le dos droit pendant le mouvement.", "Forcer l''étirement sans respecter ses limites."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "half split (left)"]', true, '2026-04-03 12:24:57.00947+00', '2026-04-03 12:24:57.00947+00', 'Position de départ : Commence en position de fente à genoux, avec ta jambe gauche étendue devant toi, talon au sol et orteils vers le haut, tout en gardant ton genou droit au sol sous ta hanche. Exécution : Incline-toi lentement en avant à partir des hanches tout en gardant le dos droit, en tendant la main vers ton pied gauche pour approfondir l''étirement des ischio-jambiers.', '["Ne pas garder le dos droit pendant le mouvement.", "Forcer l''étirement sans respecter ses limites."]', true, '["From a low lunge, straighten your front leg and flex your front foot.", "Shift your hips back over your back knee.", "Fold forward over the straight leg with a flat back.", "Place your hands on the floor or on blocks."]', '["Depuis une fente basse, tends ta jambe avant et fléchis ton pied avant.", "Reculer les hanches au-dessus de ton genou arrière.", "Plie-toi en avant au-dessus de la jambe droite avec le dos plat.", "Place tes mains au sol ou sur des blocs."]', '["Garde une légère flexion au genou pour protéger l''articulation.", "Hinge à partir des hanches, pas de la taille.", "Respire profondément pendant l''étirement des ischio-jambiers."]', '["Keep a micro-bend in the straight knee to protect the joint.", "Hinge from the hips, not the waist.", "Breathe deeply into the hamstring stretch."]', '476cf5d3-e211-4650-84ec-7a3e89c08639', 'half-split-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('c42fada2-a8e7-47e6-af63-3391befe8fa0', 'Fentes à Droite', NULL, NULL, 'Lunges (Right)', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/lunges-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/lunges-right.jpg', NULL, '["Reste majoritairement sur ton talon avant plutôt que sur tes orteils", "Garde le torse droit tout au long du mouvement pour éviter de pencher en avant", "Ton genou arrière doit presque toucher le sol sans s''y poser", "Fais un pas suffisamment en avant pour que ta jambe avant reste verticale en position basse", "Engage bien ton ventre pour garder l''équilibre et protéger le bas du dos"]', '["Ne pas garder le genou au-dessus de la cheville", "Pencher le torse en avant pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "lunges (right)"]', true, '2026-04-03 12:24:57.65475+00', '2026-04-03 12:24:57.65475+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, les mains sur les hanches ou sur les côtés. Execution : Fais un pas en avant avec ton pied droit en position de fente, baisse ton corps jusqu''à ce que les deux genoux soient pliés à 90 degrés, puis pousse avec ton talon droit pour revenir à la position de départ.', '["Ne pas garder le genou au-dessus de la cheville", "Pencher le torse en avant pendant l''exercice"]', true, '["Stand with feet hip-width apart and engage your core muscles", "Step your right foot forward about 2-3 feet, keeping your torso upright", "Lower your body by bending both knees until your right thigh is parallel to the floor", "Ensure your right knee stays directly above your ankle, not extending past your toes", "Push through your right heel to return to the starting position", "Complete all repetitions on the right leg before switching sides"]', '["Tiens-toi les pieds écartés à la largeur des hanches et engage ton ventre", "Fais un pas en avant avec ton pied droit d''environ 60 à 90 cm en gardant le torse droit", "Abaisse ton corps en pliant les deux genoux jusqu''à ce que ta cuisse droite soit parallèle au sol", "Veille à ce que ton genou droit reste au-dessus de ta cheville, sans dépasser tes orteils", "Pousse avec ton talon droit pour revenir à la position de départ", "Effectue toutes les répétitions sur la jambe droite avant de changer de côté"]', '["Reste majoritairement sur ton talon avant plutôt que sur tes orteils", "Garde le torse droit tout au long du mouvement pour éviter de pencher en avant", "Ton genou arrière doit presque toucher le sol sans s''y poser", "Fais un pas suffisamment en avant pour que ta jambe avant reste verticale en position basse", "Engage bien ton ventre pour garder l''équilibre et protéger le bas du dos"]', '["Keep most of your weight on your front heel rather than your toes", "Maintain an upright torso throughout the movement to avoid leaning forward", "Your back knee should nearly touch the ground but not rest on it", "Step far enough forward so your front shin remains vertical at the bottom position", "Keep your core engaged to maintain balance and protect your lower back"]', 'de1d910d-89b5-4f79-9459-6fefa1dbf525', 'lunges-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('f4670851-d865-44e3-b736-92d9e687665d', 'Curl Haut Câble', NULL, 'كروول كابلي العالي', 'High Cable Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 4, '/videos/biceps/high-cable-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-cable-curl.jpg', NULL, '["Active ton gainage et garde une posture droite durant tout l''exercice", "Tes bras supérieurs doivent rester parallèles au sol - évite de laisser tes coudes descendre", "Concentre-toi sur la contraction de tes biceps plutôt que sur l''élan ou le balancement du poids", "Contrôle la phase excentrique (descente) du mouvement pour maximiser l''engagement musculaire", "Commence avec un poids léger pour maîtriser la technique avant de passer à des charges plus lourdes"]', '["Laisser tomber les coudes durant l''exercice", "Utiliser de l''élan au lieu de la force musculaire"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "cable", "high cable curl"]', true, '2026-04-03 12:24:57.089229+00', '2026-04-03 12:24:57.089229+00', 'Position de départ : Tiens-toi face à un poulie haute avec les poignées en main, bras tendus vers le bas. Exécution : Fléchis tes coudes pour amener la poignée vers tes épaules, en gardant les coudes fixes.', '["Laisser tomber les coudes durant l''exercice", "Utiliser de l''élan au lieu de la force musculaire"]', true, '["Set the cable machine to the highest position and attach D-handles to both sides", "Stand in the center between the cables, grasp both handles with an underhand grip, and step forward slightly", "Position your arms parallel to the floor with elbows slightly bent and shoulders pulled back", "Curl both handles toward your temples by flexing your biceps while keeping your upper arms stationary", "Squeeze your biceps at the peak contraction, then slowly return to the starting position with control", "Repeat for desired repetitions while maintaining constant tension throughout the movement"]', '["Règle la machine à câble à la position la plus haute et fixe les poignées en D de chaque côté", "Positionne-toi entre les câbles, saisis les deux poignées avec une prise en supination, et fais un léger pas en avant", "Garde tes bras parallèles au sol avec les coudes légèrement fléchis et les épaules en arrière", "Curl les deux poignées vers tes tempes en fléchissant tes biceps tout en maintenant tes bras supérieurs immobiles", "Contracte tes biceps au sommet du mouvement, puis redescends lentement à la position de départ en contrôlant le mouvement", "Répète pour le nombre de répétitions désiré tout en maintenant une tension constante durant tout l''exercice"]', '["Active ton gainage et garde une posture droite durant tout l''exercice", "Tes bras supérieurs doivent rester parallèles au sol - évite de laisser tes coudes descendre", "Concentre-toi sur la contraction de tes biceps plutôt que sur l''élan ou le balancement du poids", "Contrôle la phase excentrique (descente) du mouvement pour maximiser l''engagement musculaire", "Commence avec un poids léger pour maîtriser la technique avant de passer à des charges plus lourdes"]', '["Keep your core engaged and maintain an upright posture throughout the exercise", "Your upper arms should remain parallel to the floor - avoid letting your elbows drop", "Focus on squeezing your biceps rather than using momentum or swinging the weight", "Control the eccentric (lowering) portion of the movement to maximize muscle engagement", "Start with lighter weight to master the form before progressing to heavier resistance"]', '0087bb08-f325-4401-9b37-66dd93871570', 'high-cable-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('f656308a-416e-40c8-8716-1eb503de9157', 'Squat Hack : Ton meilleur allié pour des cuisses puissantes !', NULL, NULL, 'Hack Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 8, '/videos/quadriceps/hack-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/hack-squat.jpg', NULL, '["Assure-toi que tes genoux sont alignés avec tes orteils pendant tout le mouvement pour éviter les blessures.", "Garde ta colonne vertébrale neutre en maintenant ton dos contre le coussin, ne te voûte pas.", "Maîtrise la phase de descente lentement pour maximiser l''engagement musculaire et éviter les blessures.", "Évite de verrouiller complètement tes genoux en haut du mouvement pour maintenir une tension constante sur les quadriceps.", "Focus sur la poussée avec tes talons, pas avec tes orteils, pour activer correctement les quadriceps."]', '["Ne pas ajuster la machine correctement, ce qui peut causer de l''inconfort.", "Descendre sans contrôler le mouvement, ce qui augmente le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "hack squat"]', true, '2026-04-03 12:24:56.865646+00', '2026-04-03 12:24:56.865646+00', 'Positionne-toi dans la machine à hack squat, les pieds à la largeur des épaules. Descends en squat profond, dos droit, puis pousse pour revenir à la position de départ.', '["Ne pas ajuster la machine correctement, ce qui peut causer de l''inconfort.", "Descendre sans contrôler le mouvement, ce qui augmente le risque de blessure."]', true, '["Adjust the machine so the shoulder pads sit comfortably on your shoulders and your back is fully supported against the pad", "Place your feet shoulder-width apart on the footplate with toes slightly pointed outward", "Release the safety handles and slowly lower your body by bending your knees while keeping your core engaged", "Descend until your thighs are parallel to the footplate or as far as your mobility allows", "Push through your heels to drive back up to the starting position while maintaining control", "Re-engage the safety handles when your set is complete"]', '["Ajuste la machine pour que les coussins reposent confortablement sur tes épaules et que ton dos soit bien soutenu.", "Place tes pieds à la largeur des épaules sur la plateforme, les orteils légèrement vers l''extérieur.", "Libère les poignées de sécurité et descends lentement en pliant les genoux, en gardant le ventre bien contracté.", "Descends jusqu''à ce que tes cuisses soient parallèles à la plateforme ou aussi bas que ta mobilité te le permet.", "Pousse avec tes talons pour remonter à la position de départ tout en gardant le contrôle.", "Reactive les poignées de sécurité une fois ta série terminée."]', '["Assure-toi que tes genoux sont alignés avec tes orteils pendant tout le mouvement pour éviter les blessures.", "Garde ta colonne vertébrale neutre en maintenant ton dos contre le coussin, ne te voûte pas.", "Maîtrise la phase de descente lentement pour maximiser l''engagement musculaire et éviter les blessures.", "Évite de verrouiller complètement tes genoux en haut du mouvement pour maintenir une tension constante sur les quadriceps.", "Focus sur la poussée avec tes talons, pas avec tes orteils, pour activer correctement les quadriceps."]', '["Keep your knees aligned with your toes throughout the entire movement to prevent knee stress", "Maintain a neutral spine by keeping your back pressed against the pad and avoiding rounding", "Control the descent phase slowly to maximize muscle engagement and prevent injury", "Avoid locking your knees completely at the top of the movement to maintain constant tension on the quadriceps", "Focus on pushing through your heels rather than your toes to properly activate the quadriceps"]', '24b76364-0eec-4035-b3e0-b7451a94db9f', 'hack-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('03338e41-5345-4a64-9380-b171b049aaeb', 'Genoux Hauts v1', NULL, NULL, 'High Knees v1', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/high-knees-v1.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-knees-v1.jpg', NULL, '["Garde le torse droit et évite de te pencher en avant ou en arrière pendant l''exercice", "Vise à lever tes genoux au moins à la hauteur des hanches pour un maximum d''efficacité", "Atterris doucement sur la plante de tes pieds pour réduire l''impact sur tes articulations", "Maintiens un tempo rapide mais privilégie la bonne forme plutôt que la vitesse", "Engage ton centre tout au long de l''exercice pour conserver ta stabilité et protéger le bas de ton dos"]', '["Se pencher en avant", "Ne pas lever les genoux assez haut"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "high knees v1"]', true, '2026-04-03 12:24:57.101557+00', '2026-04-03 12:24:57.101557+00', 'Position de départ : Tiens-toi droit, pieds écartés à la largeur des hanches, bras le long du corps, et engage ton centre. Exécution : Alterne rapidement en levant chaque genou vers ta poitrine tout en pompant tes bras comme si tu courais sur place, reste bien droit pendant l''exercice.', '["Se pencher en avant", "Ne pas lever les genoux assez haut"]', true, '["Stand tall with feet hip-width apart and engage your core muscles", "Begin by lifting your right knee up toward your chest as high as comfortable", "Quickly lower your right foot and immediately lift your left knee toward your chest", "Pump your arms in opposition to your legs, as if you were running in place", "Maintain a rapid alternating pattern between legs while staying in one spot", "Continue the movement for the prescribed time or repetition count"]', '["Tiens-toi bien droit avec les pieds écartés à la largeur des hanches et engage tes muscles abdominaux", "Commence par lever ton genou droit vers ta poitrine aussi haut que possible", "Abaisse rapidement ton pied droit et lève immédiatement ton genou gauche vers ta poitrine", "Pomptez tes bras en opposition avec tes jambes, comme si tu courais sur place", "Maintiens un rythme d''alternance rapide entre les jambes tout en restant au même endroit", "Poursuis le mouvement pendant le temps imparti ou jusqu''au nombre de répétitions demandé"]', '["Garde le torse droit et évite de te pencher en avant ou en arrière pendant l''exercice", "Vise à lever tes genoux au moins à la hauteur des hanches pour un maximum d''efficacité", "Atterris doucement sur la plante de tes pieds pour réduire l''impact sur tes articulations", "Maintiens un tempo rapide mais privilégie la bonne forme plutôt que la vitesse", "Engage ton centre tout au long de l''exercice pour conserver ta stabilité et protéger le bas de ton dos"]', '["Keep your torso upright and avoid leaning forward or backward during the exercise", "Aim to lift your knees to at least hip height for maximum effectiveness", "Land softly on the balls of your feet to reduce impact on your joints", "Maintain a quick tempo but prioritize proper form over speed", "Keep your core engaged throughout to maintain stability and protect your lower back"]', '5d55105e-04cc-4493-a7e8-302a5653e58c', 'high-knees-v1', NULL, NULL);
INSERT INTO public.exercises VALUES ('5b65b2f2-96e0-4edc-aa7a-9c3227aadd9f', 'Squat Sumo avec Barre', NULL, 'Squat Sumo ma3a l-barbell', 'Barbell Sumo Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 1, '/videos/quadriceps/barbell-sumo-squat-c8f3362d.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-sumo-squat-c8f3362d.jpg', NULL, '["Garde tes genoux alignés avec tes orteils pendant tout le mouvement pour prévenir les blessures", "Maintiens ta poitrine haute et évite de courber le dos sous le poids", "La position large cible plus efficacement les quadriceps internes et les fessiers qu''un squat traditionnel", "Focalise-toi sur ta flexibilité au niveau des adducteurs, car la large position nécessite une bonne mobilité", "Contrôle la descente et évite de rebondir au fond du mouvement"]', '["Les genoux qui s''affaissent vers l''intérieur", "Création de courbure dans le bas du dos sous le poids"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "barbell sumo squat"]', true, '2026-04-03 12:24:55.631187+00', '2026-04-03 12:24:55.631187+00', 'Position de départ : Place la barre sur le haut de ton dos, écarte les pieds plus larges que les épaules et oriente légèrement les orteils vers l''extérieur. Exécution : Descends en squattant profondément tout en gardant le dos droit, puis remonte pour revenir à la position de départ.', '["Les genoux qui s''affaissent vers l''intérieur", "Création de courbure dans le bas du dos sous le poids"]', true, '["Position the barbell securely on your upper trapezius muscles and grip it with hands slightly wider than shoulder-width", "Set your feet 1.5 times shoulder-width apart with toes angled outward and engage your core", "Initiate the movement by pushing your hips back while keeping your chest up and spine neutral", "Descend by bending at the hips and knees simultaneously until your thighs reach parallel to the floor", "Drive through your heels and push the floor away to return to the starting position", "Maintain the wide stance throughout the entire movement and avoid letting knees cave inward"]', '["Positionne la barre de manière sécurisée sur tes trapèzes supérieurs et saisis-la avec les mains légèrement plus larges que les épaules", "Ecarte tes pieds 1,5 fois la largeur des épaules avec les orteils orientés vers l''extérieur et engage ton abdomen", "Initie le mouvement en reculant les hanches tout en maintenant la poitrine haute et la colonne vertébrale neutre", "Descends en fléchissant les hanches et les genoux en même temps jusqu''à ce que tes cuisses soient parallèles au sol", "Pousse à travers les talons et repousse le sol pour revenir à la position de départ", "Maintiens une position large tout au long du mouvement et évite que les genoux ne s''affaissent vers l''intérieur"]', '["Garde tes genoux alignés avec tes orteils pendant tout le mouvement pour prévenir les blessures", "Maintiens ta poitrine haute et évite de courber le dos sous le poids", "La position large cible plus efficacement les quadriceps internes et les fessiers qu''un squat traditionnel", "Focalise-toi sur ta flexibilité au niveau des adducteurs, car la large position nécessite une bonne mobilité", "Contrôle la descente et évite de rebondir au fond du mouvement"]', '["Keep your knees tracking in line with your toes throughout the entire range of motion to prevent knee injury", "Maintain a proud chest position and avoid rounding your back under the weight", "The wider stance targets the inner quads and glutes more effectively than a traditional squat", "Focus on flexibility in your hip adductors as the wide stance requires good mobility", "Control the descent and avoid bouncing at the bottom of the movement"]', 'c8f3362d-fb00-481e-b428-e0b17f4ae681', 'barbell-sumo-squat-c8f3362d', NULL, NULL);
INSERT INTO public.exercises VALUES ('833f3a3b-5ad0-4cb7-9662-9f885db17e6d', 'Sauts Circulaires pour les Fessiers', NULL, 'قفزات دائرية للفخذين', 'Hip Circle hops', 'Glutes', '[]', 'Glutes', 'Intermediate', 16, '/videos/glutes/hip-circle-hops.mp4', NULL, NULL, NULL, '/videos/thumbnails/hip-circle-hops.jpg', NULL, '["Concentre-toi sur des atterrissages doux avec les genoux fléchis pour protéger tes articulations", "Contracte tes fessiers à chaque atterrissage pour maximiser l''activation musculaire et la stabilité", "Garde les cercles petits au début et augmente progressivement la taille à mesure que ton équilibre et ta force s''améliorent", "Maintiens des mouvements contrôlés plutôt que de te précipiter dans l''exercice pour un meilleur engagement musculaire", "Arrête immédiatement si tu ressens une gêne au genou ou à la cheville"]', '["Atterrir trop durement sans fléchir les genoux", "Se pencher en avant ou en arrière pendant les sauts"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "hip circle hops"]', true, '2026-04-03 12:24:57.169008+00', '2026-04-03 12:24:57.169008+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des hanches, mains sur les hanches ou sur les côtés pour l''équilibre. Exécution : Saute dans un mouvement circulaire autour d''une horloge imaginaire, en atterrissant doucement sur les deux pieds tout en engageant tes fessiers pour contrôler chaque atterrissage et décollage.', '["Atterrir trop durement sans fléchir les genoux", "Se pencher en avant ou en arrière pendant les sauts"]', true, '["Stand with feet hip-width apart and engage your core for stability", "Begin hopping in small circular motions, moving clockwise around an imaginary circle", "Land softly on the balls of your feet with slight knee bend to absorb impact", "Keep your torso upright and avoid leaning forward or backward during hops", "Complete the full circle clockwise, then reverse direction to move counterclockwise", "Start with smaller circles and progress to larger movements as you build strength"]', '["Tiens-toi droit, pieds à la largeur des hanches et engage ton ventre pour plus de stabilité", "Commence à sauter en petits mouvements circulaires, dans le sens des aiguilles d''une montre autour d''un cercle imaginaire", "Atterris doucement sur la plante des pieds avec un léger pli dans les genoux pour amortir l''impact", "Garde le torse droit et évite de te pencher en avant ou en arrière pendant les sauts", "Complète le cercle complet dans le sens des aiguilles d''une montre, puis inverse la direction pour sauter dans le sens inverse", "Commence par de petits cercles et progresse vers des mouvements plus grands au fur et à mesure que tu renforces ta force"]', '["Concentre-toi sur des atterrissages doux avec les genoux fléchis pour protéger tes articulations", "Contracte tes fessiers à chaque atterrissage pour maximiser l''activation musculaire et la stabilité", "Garde les cercles petits au début et augmente progressivement la taille à mesure que ton équilibre et ta force s''améliorent", "Maintiens des mouvements contrôlés plutôt que de te précipiter dans l''exercice pour un meilleur engagement musculaire", "Arrête immédiatement si tu ressens une gêne au genou ou à la cheville"]', '["Focus on soft landings with bent knees to protect your joints from impact", "Squeeze your glutes at each landing to maximize muscle activation and stability", "Keep circles small initially and gradually increase size as your balance and strength improve", "Maintain controlled movements rather than rushing through the exercise for better muscle engagement", "Stop immediately if you feel any knee or ankle discomfort"]', '83b448e2-7782-42ff-bcf6-1ce7a7e9a5a4', 'hip-circle-hops', NULL, NULL);
INSERT INTO public.exercises VALUES ('a33c28a5-9b34-4f92-b769-9b47a1e30813', 'Fente avant avec haltères', NULL, NULL, 'Dumbbell forward lunge', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 2, '/videos/quadriceps/dumbbell-forward-lunge.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-forward-lunge.jpg', NULL, '["Concentre la majorité de ton poids sur ta jambe avant et évite de pousser avec ton orteil arrière", "Maintiens le dos droit tout au long du mouvement et engage ton core pour ne pas te pencher", "Assure-toi que ton genou avant suit la ligne de tes orteils et ne s''affaisse pas vers l''intérieur", "Contrôle la descente et évite de chuter rapidement dans la position de fente", "Commence avec des poids plus légers pour maîtriser le mouvement avant de passer à des charges plus lourdes"]', '["Pencher le torse en avant pendant la descente", "Ne pas aligner le genou avant avec le pied"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "dumbbell forward lunge"]', true, '2026-04-03 12:24:56.462309+00', '2026-04-03 12:24:56.462309+00', 'Position de départ : Debout, un haltère dans chaque main, pieds largeur des hanches, gainage abdominal actif. Exécution : Fait un pas en avant avec une jambe en fente, abaisse les hanches jusqu''à ce que les deux genoux sont pliés à environ 90 degrés, puis pousse sur le talon avant pour revenir à la position de départ.', '["Pencher le torse en avant pendant la descente", "Ne pas aligner le genou avant avec le pied"]', true, '["Hold dumbbells with a firm grip at your sides, maintaining neutral wrists throughout the movement", "Take a controlled step forward, landing on your heel first then rolling onto the full foot", "Lower your body by bending both knees until your front thigh is parallel to the floor and rear knee nearly touches the ground", "Keep your torso upright and avoid leaning forward or backward during the descent", "Push through your front heel to drive yourself back to the starting position", "Complete all repetitions on one leg before switching to the other side"]', '["Tiens les haltères fermement à tes côtés, poignets neutres pendant tout le mouvement", "Fais un pas contrôlé en avant, en atterrissant d''abord sur le talon, puis en roulant sur tout le pied", "Abaisse ton corps en pliant les deux genoux jusqu''à ce que ta cuisse avant soit parallèle au sol et que ton genou arrière soit presque au sol", "Garde ton torse droit et évite de te pencher en avant ou en arrière pendant la descente", "Pousse avec ton talon avant pour revenir à la position de départ", "Termine toutes les répétitions d''un côté avant de changer de jambe"]', '["Concentre la majorité de ton poids sur ta jambe avant et évite de pousser avec ton orteil arrière", "Maintiens le dos droit tout au long du mouvement et engage ton core pour ne pas te pencher", "Assure-toi que ton genou avant suit la ligne de tes orteils et ne s''affaisse pas vers l''intérieur", "Contrôle la descente et évite de chuter rapidement dans la position de fente", "Commence avec des poids plus légers pour maîtriser le mouvement avant de passer à des charges plus lourdes"]', '["Keep most of your weight on your front leg and avoid pushing off with your back toe", "Maintain a straight back throughout the movement and engage your core to prevent forward lean", "Ensure your front knee tracks in line with your toes and doesn''t cave inward", "Control the descent and avoid dropping too quickly into the lunge position", "Start with lighter weights to master the movement pattern before progressing to heavier loads"]', 'd8a67e85-0c9f-483d-b7fe-be049247ab1c', 'dumbbell-forward-lunge', NULL, NULL);
INSERT INTO public.exercises VALUES ('2dd61d81-7e78-4fba-b295-6c609ae04fcb', 'Fente avec la Smith Machine', NULL, 'فنت مع آلة سميث', 'Smith Machine Lunge', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/smith-machine-lunge-913dc03f.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-lunge-913dc03f.jpg', NULL, '["Concentre-toi sur ta jambe avant pour le poids, utilise l''autre jambe juste pour l''équilibre.", "Veille à ce que ton genou avant suive la ligne de tes orteils, sans plier vers l''intérieur.", "Reste droit, évite de te pencher trop en avant ou en arrière.", "Descends de manière contrôlée, évite de rebondir en bas du mouvement.", "La Smith machine t''offre de la stabilité, mais garde toujours la bonne forme et engage ton core."]', '["Plier le genou avant vers l''intérieur.", "Pencher le torse trop en avant."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "smith machine lunge"]', true, '2026-04-03 12:24:59.332914+00', '2026-04-03 12:24:59.332914+00', 'Positionne-toi sous la Smith machine, une jambe en avant et l''autre en arrière. Descends en pliant les genoux, puis pousse avec le talon avant pour revenir à la position initiale. Alterne les jambes !', '["Plier le genou avant vers l''intérieur.", "Pencher le torse trop en avant."]', true, '["Position the Smith machine bar at shoulder height and step under it, resting it on your upper trapezius muscles", "Take a large step forward with one foot while keeping the other foot planted behind you, creating a wide stance", "Engage your core and maintain an upright torso throughout the movement", "Lower your body by bending both knees simultaneously until your front thigh reaches parallel to the floor", "Push through your front heel to drive yourself back up to the starting position", "Complete all repetitions on one leg before switching to the other side"]', '["Ajuste la barre de la Smith machine à la hauteur des épaules et place-toi dessous, repose-la sur ton trapèze supérieur.", "Fais un grand pas en avant avec une jambe tout en gardant l''autre jambe derrière, adopte une posture large.", "Engage ton core et reste droit tout au long de l''exercice.", "Descends en pliant les deux genoux jusqu''à ce que ta cuisse avant soit parallèle au sol.", "Pousse avec ton talon avant pour remonter à la position initiale.", "Termine toutes les répétitions d''un côté avant de changer de jambe."]', '["Concentre-toi sur ta jambe avant pour le poids, utilise l''autre jambe juste pour l''équilibre.", "Veille à ce que ton genou avant suive la ligne de tes orteils, sans plier vers l''intérieur.", "Reste droit, évite de te pencher trop en avant ou en arrière.", "Descends de manière contrôlée, évite de rebondir en bas du mouvement.", "La Smith machine t''offre de la stabilité, mais garde toujours la bonne forme et engage ton core."]', '["Keep most of your weight on your front leg while using the back leg primarily for balance and stability", "Ensure your front knee tracks in line with your toes and does not cave inward during the movement", "Maintain an upright torso position and avoid leaning too far forward or backward", "Descend in a controlled manner and avoid bouncing at the bottom of the movement", "The Smith machine provides stability but still requires proper form and core engagement"]', '913dc03f-d923-43c5-9e7f-461c26770ee1', 'smith-machine-lunge-913dc03f', NULL, NULL);
INSERT INTO public.exercises VALUES ('71033d72-b040-48c9-8944-426268f056aa', 'Étirer les hanches (droite)', NULL, 'تمارين إطالة الورك (اليمين)', 'Hip stretch (right)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/hip-stretch-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/hip-stretch-right.jpg', NULL, '["Assure-toi que ton genou avant est aligné avec ta cheville et évite qu''il ne s''effondre vers l''intérieur", "Focalise-toi sur le fait de pousser tes hanches vers l’avant plutôt que de simplement descendre pour cibler efficacement les fléchisseurs de la hanche", "Maintiens une respiration régulière pendant l’étirement et évite les mouvements brusques", "Utilise une serviette ou un tapis sous ton genou arrière pour plus de confort si nécessaire", "Arrête immédiatement si tu ressens une douleur aiguë et étire-toi uniquement jusqu''à une tension confortable"]', '["Ne pas garder le genou avant aligné avec la cheville", "Laisser le torse s''effondrer en avant"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "hip stretch (right)"]', true, '2026-04-03 12:24:57.176362+00', '2026-04-03 12:24:57.176362+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des hanches. Fais un pas en avant avec ton pied gauche en te mettant en position de fente, le genou droit au sol. Exécution : Penche-toi en avant et enfonce tes hanches vers le bas tout en gardant le torse droit pour étirer le fléchisseur de la hanche droite.', '["Ne pas garder le genou avant aligné avec la cheville", "Laisser le torse s''effondrer en avant"]', true, '["Step your left foot forward into a lunge position and lower your right knee to the ground", "Place your hands on your left thigh or on the ground for support and stability", "Keep your torso upright and engage your core muscles throughout the stretch", "Gently push your hips forward and down to deepen the stretch in your right hip flexor", "Hold the position for 20-30 seconds while breathing deeply", "Slowly return to standing position before switching sides"]', '["Avance ton pied gauche en position de fente et abaisse ton genou droit au sol", "Place tes mains sur ta cuisse gauche ou au sol pour te soutenir", "Garde le torse droit et engage les muscles de ton ventre pendant l’étirement", "Pousse doucement tes hanches vers l’avant et vers le bas pour intensifier l’étirement dans le fléchisseur de la hanche droite", "Maintiens la position pendant 20 à 30 secondes en respirant profondément", "Reviens lentement à la position debout avant de changer de côté"]', '["Assure-toi que ton genou avant est aligné avec ta cheville et évite qu''il ne s''effondre vers l''intérieur", "Focalise-toi sur le fait de pousser tes hanches vers l’avant plutôt que de simplement descendre pour cibler efficacement les fléchisseurs de la hanche", "Maintiens une respiration régulière pendant l’étirement et évite les mouvements brusques", "Utilise une serviette ou un tapis sous ton genou arrière pour plus de confort si nécessaire", "Arrête immédiatement si tu ressens une douleur aiguë et étire-toi uniquement jusqu''à une tension confortable"]', '["Keep your front knee aligned over your ankle and avoid letting it cave inward", "Focus on pushing your hips forward rather than just dropping down to target the hip flexors effectively", "Maintain steady breathing throughout the stretch and avoid bouncing or jerky movements", "Place a towel or mat under your back knee for comfort if needed", "Stop immediately if you feel sharp pain and only stretch to a comfortable tension"]', '322a5b58-ed0d-4d37-8d09-c48a606484fe', 'hip-stretch-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('80272107-ab29-45e0-b99a-5ee72904ff8d', 'Saut d''accroupi suivi de fente arrière', NULL, NULL, 'Jump squat to backward lunge', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/jump-squat-to-backward-lunge.mp4', NULL, NULL, NULL, '/videos/thumbnails/jump-squat-to-backward-lunge.jpg', NULL, '["Garde le buste droit et engage bien ta sangle abdominale durant l''exercice.", "Atterris doucement pour minimiser l''impact sur tes articulations et garder le contrôle.", "Assure-toi que tes genoux suivent la ligne de tes orteils pendant le squat.", "Utilise tes bras pour l''équilibre et l''élan lors de la phase de saut.", "Reste concentré sur la transition entre le saut d''accroupi et la fente pour éviter les blessures."]', '["Sauter trop haut et perdre le contrôle à l''atterrissage.", "Ne pas maintenir l''alignement des genoux et des orteils pendant le squat."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "jump squat to backward lunge"]', true, '2026-04-03 12:24:57.367457+00', '2026-04-03 12:24:57.367457+00', 'Prêt à faire exploser ta force dans les cuisses ? Avec cet exercice, tu vas travailler tes quadriceps tout en boostant ton équilibre et ta puissance.', '["Sauter trop haut et perdre le contrôle à l''atterrissage.", "Ne pas maintenir l''alignement des genoux et des orteils pendant le squat."]', true, '["Stand with feet shoulder-width apart and extend arms forward for balance", "Lower into a squat position by bending knees and pushing hips back", "Explosively jump straight up from the squat position", "Land softly on the balls of your feet with knees slightly bent", "Immediately step one foot back into a lunge position", "Return to starting position and repeat the sequence"]', '["Positionne-toi debout, pieds écartés à la largeur des épaules, bras tendus vers l''avant pour l''équilibre.", "Descends en position d''accroupi en fléchissant les genoux et en reculant les hanches.", "Saute avec force depuis la position d''accroupi.", "Atterris en douceur sur l''avant des pieds, genoux légèrement fléchis.", "Fais un pas en arrière avec une jambe dans une position de fente.", "Reviens à la position de départ et répète la séquence."]', '["Garde le buste droit et engage bien ta sangle abdominale durant l''exercice.", "Atterris doucement pour minimiser l''impact sur tes articulations et garder le contrôle.", "Assure-toi que tes genoux suivent la ligne de tes orteils pendant le squat.", "Utilise tes bras pour l''équilibre et l''élan lors de la phase de saut.", "Reste concentré sur la transition entre le saut d''accroupi et la fente pour éviter les blessures."]', '["Keep your chest up and core engaged throughout the entire movement", "Land softly to reduce impact on joints and maintain control", "Maintain proper squat depth with knees tracking over toes", "Use your arms for balance and momentum during the jump phase", "Control the transition between jump squat and lunge to prevent injury"]', '921feb95-16c7-4fbc-88e7-472f35ffae2e', 'jump-squat-to-backward-lunge', NULL, NULL);
INSERT INTO public.exercises VALUES ('52bc75fa-8a72-4201-9839-b4be96754f3a', 'Élévation Arrière Incliné avec Haltères', NULL, 'رفع خلفي مائل بالدنبلة', 'Incline Dumbbell Rear Delt Raise', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/incline-dumbbell-rear-delt-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-dumbbell-rear-delt-raise.jpg', NULL, '["Utilise des poids plus légers que tu ne le penses - les deltoïdes arrière sont des muscles plus petits et n''ont pas besoin d''une résistance lourde", "Garde ton tronc engagé et évite de cambrer ton dos de manière excessive contre le banc", "Concentre-toi sur le serrage des omoplates plutôt que sur la simple levée des bras", "Maintiens la légère flexion des coudes tout au long du mouvement pour protéger tes articulations", "Contrôle la phase de descente de l''exercice - ne laisse pas la gravité faire tomber les poids"]', '["Lifting trop lourd, ce qui peut entraîner des blessures", "Mouvement rapide et incontrôlé, perdant ainsi l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "incline dumbbell rear delt raise"]', true, '2026-04-03 12:24:57.292509+00', '2026-04-03 12:24:57.292509+00', 'Position de départ : Allonge-toi face contre un banc incliné, un haltère dans chaque main, les bras pendus vers le bas. Exécution : Lève les haltères sur le côté jusqu''à hauteur d''épaule, puis redescends lentement.', '["Lifting trop lourd, ce qui peut entraîner des blessures", "Mouvement rapide et incontrôlé, perdant ainsi l''efficacité de l''exercice"]', true, '["Set an incline bench to 45-60 degrees and lie face down with your chest against the pad, feet firmly planted on the floor", "Hold a dumbbell in each hand with arms hanging straight down, palms facing each other", "Keeping a slight bend in your elbows, raise the dumbbells out to your sides until your arms are parallel to the floor", "Squeeze your shoulder blades together at the top of the movement, focusing on contracting your rear delts", "Slowly lower the weights back to the starting position with control", "Repeat for desired repetitions while maintaining proper form throughout"]', '["Régler un banc incliné à 45-60 degrés et s''allonger face contre le pad, les pieds bien ancrés au sol", "Prendre un haltère dans chaque main, les bras pendants, paumes face à face", "En gardant une légère flexion des coudes, élève les haltères sur les côtés jusqu''à ce que tes bras soient parallèles au sol", "Serrer les omoplates au sommet du mouvement en mettant l''accent sur la contraction des deltoïdes postérieurs", "Redescendre lentement les poids à la position de départ avec contrôle", "Répète pour le nombre de répétitions souhaité tout en maintenant une bonne forme tout au long du mouvement"]', '["Utilise des poids plus légers que tu ne le penses - les deltoïdes arrière sont des muscles plus petits et n''ont pas besoin d''une résistance lourde", "Garde ton tronc engagé et évite de cambrer ton dos de manière excessive contre le banc", "Concentre-toi sur le serrage des omoplates plutôt que sur la simple levée des bras", "Maintiens la légère flexion des coudes tout au long du mouvement pour protéger tes articulations", "Contrôle la phase de descente de l''exercice - ne laisse pas la gravité faire tomber les poids"]', '["Use lighter weights than you think you need - the rear delts are smaller muscles and don''t require heavy resistance", "Keep your core engaged and avoid arching your back excessively against the bench", "Focus on squeezing your shoulder blades together rather than just lifting your arms up", "Maintain the slight elbow bend throughout the entire movement to protect your joints", "Control the lowering portion of the exercise - don''t let gravity drop the weights"]', '094f1299-cd52-4da7-b97f-c159208ed7d1', 'incline-dumbbell-rear-delt-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('6eef94c6-71af-46b4-ac6f-f1fe6c4ce3dd', 'Posture de Chaise', NULL, 'وضعية الكرسي', 'Chair pose', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/chair-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/chair-pose.jpg', NULL, '["Garde les genoux derrière les orteils.", "Engage ton ventre et allonge ta colonne vertébrale.", "Transfère ton poids sur tes talons."]', '["Genoux qui dépassent les orteils.", "Dos courbé au lieu d''être droit.", "Poids sur les orteils au lieu des talons."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "chair pose"]', true, '2026-04-03 12:24:56.057116+00', '2026-04-03 12:24:56.057116+00', 'Position de départ : debout, les pieds écartés à la largeur des hanches et les bras le long du corps. Exécution : abaisse tes hanches comme si tu t''asseyais sur une chaise imaginaire tout en levant les bras au-dessus de la tête, créant ainsi une position similaire à un squat qui cible principalement les quadriceps.', '["Genoux qui dépassent les orteils.", "Dos courbé au lieu d''être droit.", "Poids sur les orteils au lieu des talons."]', true, '["Stand with feet together or hip-width apart.", "Bend your knees and lower your hips as if sitting in a chair.", "Raise your arms overhead alongside your ears.", "Hold, keeping weight in your heels."]', '["Tiens-toi debout, pieds joints ou écartés à la largeur des hanches.", "Plie les genoux et abaisse tes hanches comme si tu t''asseyais sur une chaise.", "Lève les bras au-dessus de ta tête, le long de tes oreilles.", "Maintiens cette position en gardant le poids sur tes talons."]', '["Garde les genoux derrière les orteils.", "Engage ton ventre et allonge ta colonne vertébrale.", "Transfère ton poids sur tes talons."]', '["Keep knees behind your toes.", "Engage your core and lengthen your spine.", "Shift weight into your heels."]', '46f8865d-24c2-4c81-a886-aa458c5653c5', 'chair-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('aa257912-046c-421c-baec-141a0f8c960a', 'Pompes inclinées', NULL, NULL, 'Inclined push up', 'Chest', '[]', 'Chest', 'Beginner', 16, '/videos/chest/inclined-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/inclined-push-up.jpg', NULL, '["Maintiens ton corps en position planche sans laisser les hanches s''affaisser ou remonter trop haut", "Plus la surface est haute, plus l''exercice est facile pour les débutants", "Adopte un rythme contrôlé, ne te précipite pas dans les répétitions", "Garde les coudes à environ 45 degrés de ton torse pour protéger tes épaules", "Assure-toi que la surface élevée est stable et peut supporter ton poids en toute sécurité"]', '["Ne pas engager le core, cela peut mener à une mauvaise posture", "Laisser les hanches s''affaisser ou se soulever, ce qui compromet l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "inclined push up"]', true, '2026-04-03 12:24:57.323267+00', '2026-04-03 12:24:57.323267+00', 'Position de départ : Pose tes mains sur une surface élevée comme un banc ou une marche, légèrement plus large que la largeur des épaules, en gardant le corps bien aligné de la tête aux talons. Exécution : Descends ta poitrine vers la surface élevée en pliant les coudes, puis pousse pour revenir à la position de départ.', '["Ne pas engager le core, cela peut mener à une mauvaise posture", "Laisser les hanches s''affaisser ou se soulever, ce qui compromet l''exercice"]', true, '["Position hands on a stable elevated surface with fingers pointing forward and arms fully extended", "Step feet back until your body forms a straight line from head to heels", "Keep your core engaged and maintain neutral spine alignment throughout the movement", "Lower your body by bending elbows until chest nearly touches the elevated surface", "Push through your palms to return to starting position with control", "Maintain steady breathing throughout the entire range of motion"]', '["Place tes mains sur une surface élevée stable, les doigts pointant vers l''avant et les bras complètement étendus", "Recule tes pieds jusqu''à former une ligne droite de la tête aux talons", "Engage ton ventre et maintiens une colonne vertébrale neutre tout au long de l''exercice", "Descends ton corps en pliant les coudes jusqu''à ce que la poitrine touche presque la surface", "Pousse avec les paumes pour revenir à la position de départ en contrôlant le mouvement", "Respire de manière régulière durant toute l''amplitude du mouvement"]', '["Maintiens ton corps en position planche sans laisser les hanches s''affaisser ou remonter trop haut", "Plus la surface est haute, plus l''exercice est facile pour les débutants", "Adopte un rythme contrôlé, ne te précipite pas dans les répétitions", "Garde les coudes à environ 45 degrés de ton torse pour protéger tes épaules", "Assure-toi que la surface élevée est stable et peut supporter ton poids en toute sécurité"]', '["Keep your body in a straight plank position without letting hips sag or pike upward", "The higher the surface, the easier the exercise becomes for beginners", "Maintain a controlled tempo rather than rushing through repetitions", "Keep elbows at approximately 45-degree angle from your torso to protect shoulders", "Ensure the elevated surface is stable and can support your body weight safely"]', '204d2666-432a-400b-bf88-0b47203101ee', 'inclined-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('951bd25c-cc5f-4613-9573-0f761e6813af', 'Fente avant (gauche)', NULL, NULL, 'Crescent lunge (left)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/crescent-lunge-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/crescent-lunge-left.jpg', NULL, '["Assure-toi que ton genou avant reste aligné avec ta cheville.", "Active ta jambe arrière et pousse à travers la plante du pied arrière.", "Aligne tes hanches vers l''avant du tapis."]', '["Genou avant qui dépasse la cheville.", "Hanches désalignées.", "Absence d''engagement des muscles des jambes."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "crescent lunge (left)"]', true, '2026-04-03 12:24:56.204433+00', '2026-04-03 12:24:56.204433+00', 'Position de départ : Tiens-toi bien droit, puis avance ton pied gauche dans une grande fente, avec ton genou droit juste au-dessus du sol et les bras le long du corps. Exécution : Maintiens cette position statique en engageant tes quadriceps gauches pour soutenir ton poids, en gardant une bonne posture.', '["Genou avant qui dépasse la cheville.", "Hanches désalignées.", "Absence d''engagement des muscles des jambes."]', true, '["From a standing position, step one foot back into a lunge.", "Bend your front knee to 90 degrees over the ankle.", "Raise your arms overhead with palms facing each other.", "Lift your chest and gaze forward or slightly up."]', '["Depuis une position debout, fais un pas en avant avec ton pied gauche en fente.", "Plie ton genou avant à 90 degrés au-dessus de la cheville.", "Lève les bras au-dessus de ta tête, paumes face à face.", "Redresse ta poitrine et dirige ton regard vers l''avant ou légèrement vers le haut."]', '["Assure-toi que ton genou avant reste aligné avec ta cheville.", "Active ta jambe arrière et pousse à travers la plante du pied arrière.", "Aligne tes hanches vers l''avant du tapis."]', '["Keep your front knee aligned over the ankle.", "Engage your back leg and press through the ball of the back foot.", "Square your hips toward the front of the mat."]', '8dcf57f2-24d8-4f4d-802c-2eacbe9d578f', 'crescent-lunge-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('87cbd2ff-bb12-4de3-b0db-f2f34f26dca7', 'Sauts genoux élevés', NULL, NULL, 'Jump knee tucks', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/jump-knee-tucks.mp4', NULL, NULL, NULL, '/videos/thumbnails/jump-knee-tucks.jpg', NULL, '["Atterris doucement avec les genoux fléchis pour protéger tes articulations et réduire l''impact", "Maintiens ton ventre bien contracté pendant tout le mouvement pour garder ta stabilité", "Concentre-toi sur un saut vertical plutôt que sur un saut en avant pour garder une bonne forme", "Commence avec une intensité modérée et augmente progressivement la vitesse lorsque tu maîtrises la technique", "Stoppe immédiatement si tu ressens de la douleur au genou ou à la cheville"]', '["Ne pas sauter assez haut, ce qui limite le bénéfice de l''exercice", "Atterrir trop lourdement, ce qui peut causer des blessures aux articulations"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "jump knee tucks"]', true, '2026-04-03 12:24:57.356156+00', '2026-04-03 12:24:57.356156+00', 'Cet exercice est idéal pour renforcer l''ensemble de ton corps tout en augmentant ton explosivité et ta résistance.', '["Ne pas sauter assez haut, ce qui limite le bénéfice de l''exercice", "Atterrir trop lourdement, ce qui peut causer des blessures aux articulations"]', true, '["Stand with feet hip-width apart, arms at your sides, and engage your core", "Jump straight up explosively while simultaneously bringing both knees toward your chest", "Grab your shins or knees briefly with your hands at the peak of the jump", "Release your legs and extend them downward to prepare for landing", "Land softly on the balls of your feet with knees slightly bent to absorb impact", "Immediately reset to starting position and repeat for desired repetitions"]', '["Positionne-toi debout, les pieds écartés à la largeur des hanches, bras le long du corps et contracte ton ventre", "Saute explosivement en élevant les deux genoux vers ta poitrine", "Saisis brièvement tes tibias ou tes genoux au sommet du saut", "Libère tes jambes et étends-les vers le bas pour te préparer à l''atterrissage", "Atterris en douceur sur la plante des pieds, les genoux légèrement fléchis pour amortir le choc", "Retourne immédiatement à la position de départ et répète pour le nombre de répétitions souhaité"]', '["Atterris doucement avec les genoux fléchis pour protéger tes articulations et réduire l''impact", "Maintiens ton ventre bien contracté pendant tout le mouvement pour garder ta stabilité", "Concentre-toi sur un saut vertical plutôt que sur un saut en avant pour garder une bonne forme", "Commence avec une intensité modérée et augmente progressivement la vitesse lorsque tu maîtrises la technique", "Stoppe immédiatement si tu ressens de la douleur au genou ou à la cheville"]', '["Land softly with bent knees to protect your joints and reduce impact stress", "Keep your core engaged throughout the entire movement to maintain stability", "Focus on jumping straight up rather than forward to maintain proper form", "Start with lower intensity and gradually increase speed as you master the technique", "Stop immediately if you experience knee or ankle pain"]', '028fd0e4-baf8-4633-9891-20613bdea1e8', 'jump-knee-tucks', NULL, NULL);
INSERT INTO public.exercises VALUES ('1accc307-4a42-4f01-9ef0-ab943ba3aadd', 'Kettlebell Turkish Get-Up (Style Fente)', NULL, NULL, 'Kettlebell Turkish Get-Up (Lunge style)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 128, '/videos/quadriceps/kettlebell-turkish-get-up-lunge-style.mp4', NULL, NULL, NULL, '/videos/thumbnails/kettlebell-turkish-get-up-lunge-style.jpg', NULL, '["Gardez le bras au-dessus verrouillé et stable pour éviter que la kettlebell ne tombe", "Assurez-vous que votre genou avant suit bien la ligne de votre cheville", "Engagez votre cœur en permanence pour protéger le bas de votre dos et stabiliser le poids au-dessus", "Commencez avec un poids léger pour maîtriser la coordination avant de progresser", "Gardez les yeux devant vous, évitez de regarder la kettlebell"]', '["Ne pas verrouiller le bras au-dessus", "Ne pas maintenir une bonne forme de fente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "kettlebell", "kettlebell turkish get-up (lunge style)"]', true, '2026-04-03 12:24:57.42904+00', '2026-04-03 12:24:57.42904+00', 'Position de départ : Tenez-vous bien droit, pieds écartés à la largeur des hanches, une kettlebell tenue au-dessus de votre tête avec un bras tendu. Exécution : Réalisez une fente arrière contrôlée tout en maintenant la kettlebell au-dessus de votre tête, puis revenez à la position debout.', '["Ne pas verrouiller le bras au-dessus", "Ne pas maintenir une bonne forme de fente"]', true, '["Hold the kettlebell overhead with arm fully extended and locked out", "Keep your core engaged and maintain an upright torso throughout the movement", "Step one foot back into a deep lunge position, lowering the back knee toward the ground", "Keep the kettlebell stable overhead while in the lunge position", "Push through the front heel to return to the starting standing position", "Maintain control of the weight throughout the entire movement"]', '["Tenez la kettlebell au-dessus de votre tête, bras bien tendu et verrouillé", "Gardez votre cœur engagé et le torse droit pendant tout le mouvement", "Reculez un pied en position de fente profonde, en rapprochant le genou arrière du sol", "Maintenez la kettlebell stable au-dessus pendant la position de fente", "Poussez avec le talon avant pour revenir à la position debout initiale", "Gardez le contrôle du poids durant tout le mouvement"]', '["Gardez le bras au-dessus verrouillé et stable pour éviter que la kettlebell ne tombe", "Assurez-vous que votre genou avant suit bien la ligne de votre cheville", "Engagez votre cœur en permanence pour protéger le bas de votre dos et stabiliser le poids au-dessus", "Commencez avec un poids léger pour maîtriser la coordination avant de progresser", "Gardez les yeux devant vous, évitez de regarder la kettlebell"]', '["Keep the overhead arm locked and stable to prevent the kettlebell from falling", "Maintain proper lunge form with front knee tracking over the ankle", "Engage your core throughout to protect your lower back and stabilize the overhead load", "Start with lighter weight to master the coordination before progressing", "Keep your eyes forward and avoid looking up at the kettlebell"]', 'c3304243-1d9e-41b1-a01c-9ddd8f9edff8', 'kettlebell-turkish-get-up-lunge-style', NULL, NULL);
INSERT INTO public.exercises VALUES ('c1867f83-0e05-4b9a-85c7-1afc4d74ed0e', 'Étirement Genou au Poitrine', NULL, NULL, 'Knee to Chest Stretch (L)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/knee-to-chest-stretch-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/knee-to-chest-stretch-l.jpg', NULL, '["Garde la jambe d''appui légèrement fléchie et engage ton ventre pour un meilleur équilibre", "Ne tire pas trop fort sur ton genou - l''étirement doit être doux et agréable", "Reste bien droit pendant le mouvement, évite de te pencher en arrière", "Si tu as du mal à garder l''équilibre, effectue cet étirement près d''un mur ou d''une surface solide pour te soutenir", "Concentre-toi sur une respiration régulière pour maximiser les bienfaits de l''étirement"]', '["Se pencher en arrière lors de l''étirement", "Ne pas maintenir un bon équilibre sur la jambe d''appui"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "knee to chest stretch (l)"]', true, '2026-04-03 12:24:57.488076+00', '2026-04-03 12:24:57.488076+00', 'Commence en te tenant droit, les pieds écartés à la largeur des hanches, posture fière avec les épaules en arrière et le ventre engagé. Élève ton genou gauche vers ta poitrine tout en le saisissant avec les deux mains. Sens l''étirement doux au niveau des fléchisseurs de la hanche et du bas du dos.', '["Se pencher en arrière lors de l''étirement", "Ne pas maintenir un bon équilibre sur la jambe d''appui"]', true, '["Stand tall with feet hip-width apart and arms at your sides", "Slowly lift your left knee up toward your chest as high as comfortable", "Grasp your left knee with both hands, interlacing your fingers around your shin", "Gently pull your knee closer to your chest while maintaining balance on your right leg", "Hold the stretch for 20-30 seconds while breathing deeply", "Slowly release your hands and lower your left leg back to the starting position"]', '["Tiens-toi bien droit, pieds écartés à la largeur des hanches et bras le long du corps", "Lève lentement ton genou gauche vers ta poitrine, aussi haut que tu te sens à l''aise", "Prends ton genou gauche avec les deux mains en entrelaçant tes doigts autour de ton tibia", "Tire doucement ton genou plus près de ta poitrine tout en gardant l''équilibre sur ta jambe droite", "Maintiens l''étirement pendant 20-30 secondes tout en respirant profondément", "Relâche lentement tes mains et abaisse ta jambe gauche à la position de départ"]', '["Garde la jambe d''appui légèrement fléchie et engage ton ventre pour un meilleur équilibre", "Ne tire pas trop fort sur ton genou - l''étirement doit être doux et agréable", "Reste bien droit pendant le mouvement, évite de te pencher en arrière", "Si tu as du mal à garder l''équilibre, effectue cet étirement près d''un mur ou d''une surface solide pour te soutenir", "Concentre-toi sur une respiration régulière pour maximiser les bienfaits de l''étirement"]', '["Keep your standing leg slightly bent and engage your core for better balance", "Avoid pulling too aggressively on your knee - the stretch should feel gentle and comfortable", "Maintain upright posture throughout the movement, avoiding leaning backward", "If you have difficulty balancing, perform this stretch near a wall or sturdy surface for support", "Focus on steady breathing during the hold to enhance the stretching benefit"]', 'c8b7a380-562e-4ad2-8dfc-7a29b5c56418', 'knee-to-chest-stretch-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('813ba8cb-84be-459a-be3c-04eb7ce788a2', 'Squats sautés explosifs', NULL, NULL, 'Explosive jump squats', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/explosive-jump-squats.mp4', NULL, NULL, NULL, '/videos/thumbnails/explosive-jump-squats.jpg', NULL, '["Atterris doucement (atterrissages silencieux)", "Absorbe l''impact avec les jambes", "Ne verrouille pas les genoux en atterrissant", "La puissance vient des jambes et des hanches", "Idéal pour la puissance explosive"]', '["Ne pas sauter assez haut", "Atterrir trop durement", "Oublier de fléchir les genoux en atterrissant", "Manquer d''amplitude dans le squat", "Se pencher en avant lors du saut"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "explosive jump squats"]', true, '2026-04-03 12:24:56.664073+00', '2026-04-03 12:24:56.664073+00', 'Mets-toi en position debout, les pieds écartés à la largeur des épaules, les orteils légèrement tournés vers l''extérieur, et les bras le long du corps ou devant la poitrine. Fléchis les genoux en position de squat, puis explose vers le haut en te propulsant avec tes hanches et tes genoux, atterrissant doucement de nouveau en squat.', '["Ne pas sauter assez haut", "Atterrir trop durement", "Oublier de fléchir les genoux en atterrissant", "Manquer d''amplitude dans le squat", "Se pencher en avant lors du saut"]', true, '["Start in squat position", "Explode up, jumping off floor", "Land softly with bent knees", "Immediately descend into next squat"]', '["Commence en position de squat", "Explose et saute du sol", "Atterris doucement avec les genoux fléchis", "Descends immédiatement dans le prochain squat"]', '["Atterris doucement (atterrissages silencieux)", "Absorbe l''impact avec les jambes", "Ne verrouille pas les genoux en atterrissant", "La puissance vient des jambes et des hanches", "Idéal pour la puissance explosive"]', '["Land softly (quiet landings)", "Absorb impact with legs", "Don''t lock knees on landing", "Power comes from legs and hips", "Great for explosive power"]', '0501fca5-dd00-4948-8874-40cc851daaee', 'explosive-jump-squats', NULL, NULL);
INSERT INTO public.exercises VALUES ('d87cfdf9-fad8-470c-9323-bc9b2848b15a', 'Squat Bulgare avec Barre', NULL, NULL, 'Bulgarian split squat - with Barbell', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 1, '/videos/quadriceps/bulgarian-split-squat-with-barbell.mp4', NULL, NULL, NULL, '/videos/thumbnails/bulgarian-split-squat-with-barbell.jpg', NULL, '["Garde le torse droit et évite de te pencher trop en avant pour ne pas stresser le bas du dos", "Concentre-toi sur la jambe avant - la jambe arrière doit juste servir de soutien léger", "Assure-toi que ton genou avant suit la ligne de tes orteils sans se déplacer vers l''intérieur pendant le mouvement", "Commence avec ton poids corporel pour maîtriser le geste avant d''ajouter la barre", "Garde le contrôle sur toute l''amplitude du mouvement, évite de rebondir en bas."]', '["Ne pas garder le dos droit pendant l''exercice", "Laisser le genou avant se déplacer trop vers l''intérieur"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "bulgarian split squat - with barbell"]', true, '2026-04-03 12:24:55.815733+00', '2026-04-03 12:24:55.815733+00', 'Mets-toi en position de départ avec une barre sur le haut du dos, un pied en avant et l''autre reposant sur un banc derrière toi. Descends en squat tout en gardant le dos droit, puis pousse avec le pied avant pour revenir à la position de départ. Répète avec l''autre jambe.', '["Ne pas garder le dos droit pendant l''exercice", "Laisser le genou avant se déplacer trop vers l''intérieur"]', true, '["Position the barbell securely across your upper trapezius muscles, not on your neck", "Step forward 2-3 feet from the bench and place your rear foot on top of the bench", "Keep most of your weight on your front leg throughout the entire movement", "Lower your body until your front thigh is parallel to the ground or as low as mobility allows", "Drive through your front heel to return to the starting position", "Complete all repetitions on one leg before switching to the other side"]', '["Place la barre solidement sur les trapèzes supérieurs, pas sur le cou", "Fais un pas en avant de 60 à 90 cm du banc et pose ton pied arrière sur le banc", "Garde la majeure partie de ton poids sur la jambe avant durant tout le mouvement", "Descends jusqu''à ce que ta cuisse avant soit parallèle au sol ou aussi bas que ta mobilité le permet", "Pousse à travers ton talon avant pour revenir à la position de départ", "Complète toutes les répétitions sur une jambe avant de passer à l''autre côté"]', '["Garde le torse droit et évite de te pencher trop en avant pour ne pas stresser le bas du dos", "Concentre-toi sur la jambe avant - la jambe arrière doit juste servir de soutien léger", "Assure-toi que ton genou avant suit la ligne de tes orteils sans se déplacer vers l''intérieur pendant le mouvement", "Commence avec ton poids corporel pour maîtriser le geste avant d''ajouter la barre", "Garde le contrôle sur toute l''amplitude du mouvement, évite de rebondir en bas."]', '["Keep your torso upright and avoid leaning too far forward to prevent lower back strain", "Focus the majority of your weight on your front leg - the rear leg should only provide light balance support", "Ensure your front knee tracks in line with your toes and doesn''t cave inward during the movement", "Start with bodyweight only to master the movement pattern before adding the barbell", "Maintain control throughout the entire range of motion, avoiding bouncing at the bottom position"]', '74a22260-8090-40b6-a13a-4d366c0d5fd6', 'bulgarian-split-squat-with-barbell', NULL, NULL);
INSERT INTO public.exercises VALUES ('4dadb27a-702f-4993-99c0-e4dd6f04e4b3', 'L-sit vers L-sit replié', NULL, NULL, 'L-sit to tucked L-sit', 'Abs', '[]', 'Abs', 'Advanced', 16, '/videos/abs/l-sit-to-tucked-l-sit.mp4', NULL, NULL, NULL, '/videos/thumbnails/l-sit-to-tucked-l-sit.jpg', NULL, '["Garde les épaules éloignées de tes oreilles tout au long du mouvement", "Maintiens un engagement fort des bras et des abdominaux pour éviter de descendre au sol durant les transitions", "Concentre-toi sur des mouvements contrôlés plutôt que sur la rapidité lors des changements de position", "Si tu ne peux pas encore tenir une L-sit complète, pratique d''abord la position repliée pour développer ta force", "Arrête-toi immédiatement si tu ressens une douleur aux poignets ou épaules et envisage d''utiliser des parallettes ou des poignées de pompes pour le confort des poignets."]', '["Ne pas s''échauffer correctement, ce qui peut provoquer des blessures", "Se laisser tomber au sol lorsque l''on passe entre les positions"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "l-sit to tucked l-sit"]', true, '2026-04-03 12:24:57.517761+00', '2026-04-03 12:24:57.517761+00', 'Position de départ : Assieds-toi sur le sol, jambes tendues devant toi, mains sur le sol à côté de tes hanches, doigts pointant vers l''avant. Exécution : Pousse avec tes mains pour soulever ton corps du sol, puis alterne entre la position L-sit avec les jambes tendues et le repli de tes genoux vers ta poitrine en maintenant le soulèvement.', '["Ne pas s''échauffer correctement, ce qui peut provoquer des blessures", "Se laisser tomber au sol lorsque l''on passe entre les positions"]', true, '["Warm up your wrists, shoulders, and core thoroughly before attempting this exercise", "Start in the L-sit position by pressing firmly through your hands and lifting your body and straight legs off the ground", "Hold the full L-sit for 2-3 seconds, keeping your legs parallel to the floor", "Slowly draw your knees toward your chest to transition into the tucked position while maintaining the hand support", "Hold the tucked L-sit for 2-3 seconds with knees close to your chest", "Extend your legs back out to return to the full L-sit position and repeat the cycle"]', '["Échauffe bien tes poignets, épaules et abdominaux avant de commencer cet exercice", "Commence en position L-sit en poussant fermement avec les mains pour soulever ton corps et tes jambes droites du sol", "Maintiens la L-sit pendant 2-3 secondes, les jambes parallèles au sol", "Tire lentement tes genoux vers ta poitrine pour passer à la position repliée tout en gardant le soutien avec les mains", "Maintiens la position L-sit repliée pendant 2-3 secondes, les genoux proches de ta poitrine", "Étends tes jambes pour revenir à la position L-sit et répète le cycle"]', '["Garde les épaules éloignées de tes oreilles tout au long du mouvement", "Maintiens un engagement fort des bras et des abdominaux pour éviter de descendre au sol durant les transitions", "Concentre-toi sur des mouvements contrôlés plutôt que sur la rapidité lors des changements de position", "Si tu ne peux pas encore tenir une L-sit complète, pratique d''abord la position repliée pour développer ta force", "Arrête-toi immédiatement si tu ressens une douleur aux poignets ou épaules et envisage d''utiliser des parallettes ou des poignées de pompes pour le confort des poignets."]', '["Keep your shoulders pulled down and away from your ears throughout the entire movement", "Maintain strong arm and core engagement to prevent dropping to the floor during transitions", "Focus on controlled movements rather than speed when transitioning between positions", "If you cannot hold a full L-sit yet, practice the tucked position first to build strength", "Stop immediately if you experience wrist or shoulder pain and consider using parallettes or push-up handles for wrist comfort"]', '92d81e10-c495-4bf9-b205-a079f8711097', 'l-sit-to-tucked-l-sit', NULL, NULL);
INSERT INTO public.exercises VALUES ('bd20a2b9-29bf-40ca-9428-6d65307db041', 'Élévations de mollets sur presse à cuisse', NULL, NULL, 'Leg Press Calf Raise', 'Calves', '[]', 'Calves', 'Beginner', 8, '/videos/calves/leg-press-calf-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/leg-press-calf-raise.jpg', NULL, '["Garde tes genoux légèrement pliés durant tout le mouvement pour maintenir la tension sur les mollets", "Vise un mouvement complet, en obtenant un étirement profond en bas et une contraction maximale en haut", "Utilise des mouvements lents et contrôlés pour éviter les blessures et maximiser l''activation musculaire", "Positionne tes pieds droits devant toi plutôt que de les pencher pour garantir un développement équilibré des mollets", "Commence avec un poids léger pour maîtriser la forme avant de passer à des charges plus lourdes"]', '["Bouncer au lieu de contrôler le mouvement", "Plier trop les genoux"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["calves", "machine", "leg press calf raise"]', true, '2026-04-03 12:24:57.555303+00', '2026-04-03 12:24:57.555303+00', 'Position de départ : Installe-toi sur la machine à presse à cuisse avec les pieds sur la plateforme et les genoux légèrement pliés. Exécution : Soulève les talons en contractant tes mollets, puis redescends lentement à la position de départ.', '["Bouncer au lieu de contrôler le mouvement", "Plier trop les genoux"]', true, '["Adjust the leg press machine seat so your knees are at approximately 90 degrees when feet are positioned", "Place only the balls of your feet on the bottom edge of the footplate with heels hanging freely", "Keep your knees slightly bent and maintain this position throughout the movement", "Press through the balls of your feet to raise your heels as high as possible", "Hold the peak contraction briefly then slowly lower your heels below the footplate level", "Maintain control throughout both the lifting and lowering phases"]', '["Ajuste le siège de la presse à cuisse pour que tes genoux soient à environ 90 degrés quand tes pieds sont en place", "Place seulement les orteils sur le bord inférieur de la plateforme avec les talons en l''air", "Garde les genoux légèrement pliés et maintiens cette position pendant tout le mouvement", "Pousse à travers les orteils pour soulever tes talons le plus haut possible", "Retiens brièvement la contraction maximale puis redescends lentement les talons en dessous du niveau de la plateforme", "Garde le contrôle pendant la phase de montée et de descente"]', '["Garde tes genoux légèrement pliés durant tout le mouvement pour maintenir la tension sur les mollets", "Vise un mouvement complet, en obtenant un étirement profond en bas et une contraction maximale en haut", "Utilise des mouvements lents et contrôlés pour éviter les blessures et maximiser l''activation musculaire", "Positionne tes pieds droits devant toi plutôt que de les pencher pour garantir un développement équilibré des mollets", "Commence avec un poids léger pour maîtriser la forme avant de passer à des charges plus lourdes"]', '["Keep your knees slightly bent throughout the entire movement to maintain tension on the calves", "Focus on achieving a full range of motion by getting a deep stretch at the bottom and maximum contraction at the top", "Use slow, controlled movements rather than bouncing to prevent injury and maximize muscle activation", "Position your feet straight ahead rather than angled to ensure balanced calf development", "Start with lighter weight to master the form before progressing to heavier loads"]', '952c06b0-359b-4e38-adfd-c352723ab865', 'leg-press-calf-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('80c1caf9-ab1d-4405-aab4-37cd0b13fc3a', 'Presse à Jambes Pieds Serrés - Accent sur les Fessiers', NULL, NULL, 'Leg Press Close Stance - Glute Focus', 'Glutes', '[]', 'Glutes', 'Beginner', 8, '/videos/glutes/leg-press-close-stance-glute-focus.mp4', NULL, NULL, NULL, '/videos/thumbnails/leg-press-close-stance-glute-focus.jpg', NULL, '["Gardez vos pieds positionnés plus bas sur la plateforme pour augmenter l''activation des fessiers et réduire la dominance des quadriceps", "Maintenez une tension constante sur vos fessiers durant toute l''amplitude du mouvement", "Évitez de verrouiller complètement vos genoux en haut pour garder une tension continue sur les muscles", "Concentrez-vous sur la pression à travers vos talons plutôt que vos orteils pour maximiser l''engagement des fessiers", "Gardez votre sangle abdominale engagée et le bas du dos appuyé contre le siège durant tout l''exercice"]', '["Négliger l''activation des fessiers au profit des quadriceps", "D''avoir un dos non soutenu qui peut conduire à des blessures"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "machine", "leg press close stance - glute focus"]', true, '2026-04-03 12:24:57.564041+00', '2026-04-03 12:24:57.564041+00', 'Position de départ : Asseyez-vous sur la machine à presse à jambes avec les pieds joints sur la plateforme et les genoux fléchis. Exécution : Poussez la plateforme vers l''avant en étendant complètement vos jambes en vous concentrant sur vos fessiers, puis abaissez lentement à la position de départ.', '["Négliger l''activation des fessiers au profit des quadriceps", "D''avoir un dos non soutenu qui peut conduire à des blessures"]', true, '["Adjust the seat back to a comfortable angle and ensure your back is firmly pressed against the pad", "Place your feet close together on the lower third of the footplate with toes pointing slightly outward", "Release the safety handles and slowly lower the weight by bending at the knees and hips", "Descend until your knees reach approximately 90 degrees or as deep as your mobility allows", "Press through your heels and drive the weight back up while focusing on glute activation", "Control the movement on both the lowering and pressing phases"]', '["Réglez le dossier du siège à un angle confortable et assurez-vous que votre dos est bien appuyé contre le dossier", "Placez vos pieds serrés sur le tiers inférieur de la plateforme avec les orteils légèrement tournés vers l''extérieur", "Libérez les poignées de sécurité et abaissez lentement le poids en fléchissant les genoux et les hanches", "Descendez jusqu''à ce que vos genoux atteignent environ 90 degrés ou aussi bas que votre mobilité le permet", "Poussez à travers vos talons et remontez le poids en vous concentrant sur l''activation des fessiers", "Contrôlez le mouvement durant les phases de descente et de montée"]', '["Gardez vos pieds positionnés plus bas sur la plateforme pour augmenter l''activation des fessiers et réduire la dominance des quadriceps", "Maintenez une tension constante sur vos fessiers durant toute l''amplitude du mouvement", "Évitez de verrouiller complètement vos genoux en haut pour garder une tension continue sur les muscles", "Concentrez-vous sur la pression à travers vos talons plutôt que vos orteils pour maximiser l''engagement des fessiers", "Gardez votre sangle abdominale engagée et le bas du dos appuyé contre le siège durant tout l''exercice"]', '["Keep your feet positioned lower on the footplate to increase glute activation and reduce quad dominance", "Maintain constant tension on your glutes throughout the entire range of motion", "Avoid locking your knees completely at the top to keep continuous tension on the muscles", "Focus on pressing through your heels rather than your toes to maximize glute engagement", "Keep your core engaged and lower back pressed against the seat pad throughout the exercise"]', '13351b5d-ef3f-4c6b-9f47-df62202d32b2', 'leg-press-close-stance-glute-focus', NULL, NULL);
INSERT INTO public.exercises VALUES ('63ebf467-62e3-4f13-9e38-735c15d1c5bb', 'Pont Fessier', NULL, 'جسر المؤخرة', 'Glute bridge', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/glute-bridge.mp4', NULL, NULL, NULL, '/videos/thumbnails/glute-bridge.jpg', NULL, '["Contracte bien les fessiers en haut", "Évite de cambrer le bas du dos", "Pousse avec les talons", "Maintiens la position en haut un court instant", "Base solide pour les thrusts de hanches"]', '["Ne pas contracter suffisamment les fessiers", "Cambrer le dos au lieu de garder une position neutre", "Pousser avec les orteils au lieu des talons"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "glute bridge"]', true, '2026-04-03 12:24:56.8298+00', '2026-04-03 12:24:56.8298+00', 'Position de départ : Allonge-toi sur le dos, les genoux fléchis à 90 degrés, les pieds bien à plat sur le sol, écartés à la largeur des hanches, les bras le long du corps. Exécution : Pousse avec les talons pour soulever tes hanches en contractant les fessiers, forme une ligne droite des genoux aux épaules, puis redescends lentement.', '["Ne pas contracter suffisamment les fessiers", "Cambrer le dos au lieu de garder une position neutre", "Pousser avec les orteils au lieu des talons"]', true, '["Lie on back, knees bent, feet flat", "Drive hips up by squeezing glutes", "Form straight line from shoulders to knees", "Lower with control"]', '["Allonge-toi sur le dos, genoux fléchis, pieds à plat", "Pousse les hanches vers le haut en contractant les fessiers", "Forme une ligne droite des épaules aux genoux", "Redescends avec contrôle"]', '["Contracte bien les fessiers en haut", "Évite de cambrer le bas du dos", "Pousse avec les talons", "Maintiens la position en haut un court instant", "Base solide pour les thrusts de hanches"]', '["Squeeze glutes hard at top", "Don''t hyperextend lower back", "Drive through heels", "Hold at top briefly", "Foundation for hip thrusts"]', 'bae56fcf-a610-45e8-a577-238c5ee6567b', 'glute-bridge', NULL, NULL);
INSERT INTO public.exercises VALUES ('13f08503-d3fc-435d-9f02-cf05dd874cb8', 'Squat Latéral', NULL, NULL, 'Side to side squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/side-to-side-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-to-side-squat.jpg', NULL, '["Garde la jambe non travaillée droite mais pas verrouillée, elle te soutiendra", "Maintiens une bonne posture en gardant le buste droit et les genoux alignés avec les orteils", "Visualise que tu descends avec les hanches vers l''arrière au lieu de laisser les genoux avancer", "Commence avec un mouvement plus court puis augmente la profondeur au fur et à mesure que ta souplesse s''améliore", "Concentre-toi sur le talon de la jambe qui travaille pour maximiser l''engagement des quadriceps"]', '["Les genoux qui dépassent les orteils lorsqu''on descend", "Le dos voûté au lieu d''être droit"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "side to side squat"]', true, '2026-04-03 12:24:59.147512+00', '2026-04-03 12:24:59.147512+00', 'Place-toi debout, les pieds écartés au-delà de la largeur des épaules, les orteils légèrement tournés vers l''extérieur et les bras le long du corps ou croisés sur la poitrine. Maintenant, fais un squat en déplaçant ton poids d''un côté, en pliant le genou tout en gardant l''autre jambe droite. Ensuite, reviens au centre et répète de l''autre côté. C''est parti !', '["Les genoux qui dépassent les orteils lorsqu''on descend", "Le dos voûté au lieu d''être droit"]', true, '["Stand with feet positioned wider than shoulder-width apart and toes pointing slightly outward", "Keep your chest up and core engaged throughout the entire movement", "Shift your weight to your right side while bending your right knee and lowering your hips down and back", "Push through your right heel to return to the starting position in the center", "Immediately shift to your left side and repeat the squatting motion on that leg", "Continue alternating sides in a controlled, rhythmic pattern"]', '["Debout, écarte les pieds au-delà de la largeur des épaules et tourne légèrement les orteils vers l''extérieur", "Garde le buste droit et engage ton ventre pendant tout le mouvement", "Déplace ton poids sur le côté droit en pliant le genou droit et en abaissant les hanches vers l''arrière", "Pousse sur ton talon droit pour revenir au centre", "Change immédiatement de côté et répète le mouvement sur la jambe gauche", "Alterne les côtés de manière contrôlée et rythmée"]', '["Garde la jambe non travaillée droite mais pas verrouillée, elle te soutiendra", "Maintiens une bonne posture en gardant le buste droit et les genoux alignés avec les orteils", "Visualise que tu descends avec les hanches vers l''arrière au lieu de laisser les genoux avancer", "Commence avec un mouvement plus court puis augmente la profondeur au fur et à mesure que ta souplesse s''améliore", "Concentre-toi sur le talon de la jambe qui travaille pour maximiser l''engagement des quadriceps"]', '["Keep the non-working leg straight but not locked, allowing it to act as a support", "Maintain proper squat form by keeping your chest up and knees tracking over your toes", "Focus on sitting back into your hips rather than letting your knees drift forward", "Start with a smaller range of motion and gradually increase depth as flexibility improves", "Keep your weight primarily on the heel of the working leg to maximize quad engagement"]', '857fa3a7-6b75-4329-9bb0-297db6b9f761', 'side-to-side-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('03cf5a72-a450-4d18-aba4-2c7dc5c2a298', 'Fentes (Gauche)', NULL, NULL, 'Lunges (Left)', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/lunges-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/lunges-left.jpg', NULL, '["Garde la majeure partie de ton poids sur le talon avant plutôt que sur les orteils", "Maintiens un torse droit tout au long du mouvement pour éviter de te pencher en avant", "Ton genou arrière doit descendre droit vers le sol, sans déviation vers l''intérieur ou l''extérieur", "Contrôle la descente et évite de rebondir au fond du mouvement", "Si tu ressens une instabilité, entraîne-toi en tenant un mur ou une chaise pour te soutenir."]', '["Pencher le torse en avant", "Laisser le genou avant dépasser les orteils"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "lunges (left)"]', true, '2026-04-03 12:24:57.642024+00', '2026-04-03 12:24:57.642024+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, mains sur les hanches ou le long du corps. Execution : Fais un grand pas en avant avec ton pied gauche en position de fente, abaisse ton corps jusqu''à ce que les deux genoux soient pliés à 90 degrés, puis pousse avec ton talon gauche pour revenir à la position de départ.', '["Pencher le torse en avant", "Laisser le genou avant dépasser les orteils"]', true, '["Stand with feet hip-width apart and engage your core for stability", "Step your left foot forward approximately 2-3 feet, keeping your torso upright", "Lower your body by bending both knees until your left thigh is parallel to the floor and right knee nearly touches the ground", "Ensure your left knee tracks directly over your ankle, not extending past your toes", "Push through your left heel to return to the starting position", "Complete all repetitions on the left leg before switching sides"]', '["Tiens-toi avec les pieds écartés à la largeur des hanches et engage ton abdomen pour rester stable", "Avance ton pied gauche d''environ 60 à 90 cm, en gardant le torse droit", "Abaisse ton corps en pliant les deux genoux jusqu''à ce que ta cuisse gauche soit parallèle au sol et que ton genou droit touche presque le sol", "Assure-toi que ton genou gauche reste au-dessus de ta cheville et ne dépasse pas tes orteils", "Pousse avec ton talon gauche pour revenir à la position de départ", "Effectue toutes les répétitions sur la jambe gauche avant de changer de côté."]', '["Garde la majeure partie de ton poids sur le talon avant plutôt que sur les orteils", "Maintiens un torse droit tout au long du mouvement pour éviter de te pencher en avant", "Ton genou arrière doit descendre droit vers le sol, sans déviation vers l''intérieur ou l''extérieur", "Contrôle la descente et évite de rebondir au fond du mouvement", "Si tu ressens une instabilité, entraîne-toi en tenant un mur ou une chaise pour te soutenir."]', '["Keep most of your weight on your front heel rather than your toes", "Maintain an upright torso throughout the movement to avoid leaning forward", "Your back knee should drop straight down toward the floor, not drift inward or outward", "Control the descent and avoid bouncing at the bottom of the movement", "If you feel unstable, practice the movement holding onto a wall or chair for support"]', '4eed07c2-fe85-409d-9f81-a4872e8ffb9e', 'lunges-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('c25b2ec7-83fa-4c2a-bdc2-4166756a88cb', 'Touche d''épaule en planche avec extensions', NULL, 'تلامس الكتف في وضعية البلانك مع تمديدات', 'Plank shoulder taps into reaches', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-shoulder-taps-into-reaches.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-shoulder-taps-into-reaches.jpg', NULL, '["Garde tes hanches carrées et évite de tourner ton tronc pendant les touches et les extensions", "Maintiens une position de planche forte tout au long de l''exercice, sans affaisser ou relever les hanches", "Mouvement contrôlé plutôt que vitesse pour maximiser l''engagement du gainage", "Répartis ton poids de manière équilibrée sur ta main de soutien lors de chaque touche et extension", "Garde ton gainage bien actif pour éviter tout mouvement excessif des hanches ou balancement"]', '["Laisser les hanches tomber", "Ne pas garder le corps en ligne droite"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank shoulder taps into reaches"]', true, '2026-04-03 12:24:58.345419+00', '2026-04-03 12:24:58.345419+00', 'Position de départ : Place-toi en position de planche haute, mains bien ancrées au sol, bras tendus, corps aligné de la tête aux talons. Exécution : Soulève une main pour toucher l''épaule opposée, puis tends ce même bras vers l''avant avant de revenir à la planche et répète de l''autre côté.', '["Laisser les hanches tomber", "Ne pas garder le corps en ligne droite"]', true, '["Start in a high plank position with hands shoulder-width apart and body in a straight line", "Engage your core and keep hips level as you lift your right hand", "Tap your left shoulder briefly, then extend that same arm straight forward", "Return your right hand to the starting position and repeat the movement with your left hand", "Continue alternating sides while maintaining proper plank form", "Keep your feet slightly wider than hip-width apart for better stability"]', '["Mets-toi en position de planche haute, mains écartées à la largeur des épaules, corps bien droit", "Contracte bien ton gainage et garde les hanches de niveau en soulevant ta main droite", "Touche rapidement ton épaule gauche, puis étends ce même bras droit devant toi", "Ramène ta main droite à la position de départ et répète le mouvement avec ta main gauche", "Alterne les côtés tout en gardant une bonne forme de planche", "Place tes pieds légèrement plus larges que la largeur des hanches pour plus de stabilité"]', '["Garde tes hanches carrées et évite de tourner ton tronc pendant les touches et les extensions", "Maintiens une position de planche forte tout au long de l''exercice, sans affaisser ou relever les hanches", "Mouvement contrôlé plutôt que vitesse pour maximiser l''engagement du gainage", "Répartis ton poids de manière équilibrée sur ta main de soutien lors de chaque touche et extension", "Garde ton gainage bien actif pour éviter tout mouvement excessif des hanches ou balancement"]', '["Keep your hips square and avoid rotating your torso during the shoulder taps and reaches", "Maintain a strong plank position throughout the entire movement without sagging or piking", "Move with control rather than speed to maximize core engagement", "Distribute weight evenly on your supporting hand when performing the tap and reach", "Keep your core tight to prevent excessive hip movement or swaying"]', '73368005-c7ae-4086-b7e5-31963e96af4d', 'plank-shoulder-taps-into-reaches', NULL, NULL);
INSERT INTO public.exercises VALUES ('cd97d4df-72f6-438c-93b7-4c89e1b46cba', 'Crunch oblique couché', NULL, NULL, 'Lying oblique crunch', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/lying-oblique-crunch.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-oblique-crunch.jpg', NULL, '["Garde le cou en position neutre et évite de tirer sur ta tête avec ta main", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur la vitesse", "Expire en contractant et inspire en revenant à la position initiale", "Maintiens la stabilité avec ton bras du bas, évite de rouler vers l''avant ou l''arrière", "Ressens bien la contraction dans tes muscles latéraux plutôt que dans tes fléchisseurs de hanche"]', '["Ne pas contracter correctement les obliques", "Tirer sur la tête avec la main du haut"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "lying oblique crunch"]', true, '2026-04-03 12:24:57.731484+00', '2026-04-03 12:24:57.731484+00', 'Position de départ : Allonge-toi sur le côté, le bras du bas tendu pour le soutien et la main du haut derrière la tête. Exécution : Contracte tes obliques pour amener ton coude supérieur vers ta hanche tout en soulevant légèrement tes jambes.', '["Ne pas contracter correctement les obliques", "Tirer sur la tête avec la main du haut"]', true, '["Lie on your side with your legs stacked and slightly bent at the knees", "Place your bottom arm straight out in front for stability and support", "Position your top hand gently behind your head without interlacing fingers", "Engage your core and slowly crunch your top elbow down toward your hip", "Simultaneously lift your top leg slightly while contracting your obliques", "Lower back to starting position with control and repeat before switching sides"]', '["Allonge-toi sur le côté avec les jambes empilées et légèrement fléchies aux genoux", "Tends ton bras du bas devant toi pour stabilité et soutien", "Place ta main du haut derrière ta tête sans entrelacer les doigts", "Engage ton centre et effectue une contraction en amenant ton coude vers ta hanche", "Soulève simultanément ta jambe du haut en contractant tes obliques", "Redescends lentement à la position de départ et répète avant de changer de côté"]', '["Garde le cou en position neutre et évite de tirer sur ta tête avec ta main", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur la vitesse", "Expire en contractant et inspire en revenant à la position initiale", "Maintiens la stabilité avec ton bras du bas, évite de rouler vers l''avant ou l''arrière", "Ressens bien la contraction dans tes muscles latéraux plutôt que dans tes fléchisseurs de hanche"]', '["Keep your neck in neutral alignment and avoid pulling on your head with your hand", "Focus on slow, controlled movements rather than speed or momentum", "Breathe out during the crunch phase and inhale as you return to starting position", "Maintain stability through your bottom arm and avoid rolling forward or backward", "Feel the contraction specifically in your side muscles rather than your hip flexors"]', 'b2a0896a-3900-4a82-bd7d-30e4b74687e9', 'lying-oblique-crunch', NULL, NULL);
INSERT INTO public.exercises VALUES ('87fb95f2-567c-4354-a007-1b153a48f425', 'Fente basse (droite)', NULL, NULL, 'Low lunge (right)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/low-lunge-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/low-lunge-right.jpg', NULL, '["Utilisez une couverture pour protéger votre genou arrière si besoin.", "Faites descendre vos hanches vers l''avant et vers le bas pour étirer davantage.", "Gardez votre sangle abdominale engagée et la colonne vertébrale droite."]', '["Ne pas aligner le genou avant avec la cheville.", "Forcer sur les hanches sans contrôle."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "low lunge (right)"]', true, '2026-04-03 12:24:57.623269+00', '2026-04-03 12:24:57.623269+00', 'Un excellent exercice pour renforcer vos quadriceps et améliorer votre flexibilité !', '["Ne pas aligner le genou avant avec la cheville.", "Forcer sur les hanches sans contrôle."]', true, '["From Downward Dog, step one foot forward between your hands.", "Lower your back knee to the mat.", "Stack your front knee over the ankle.", "Raise your arms overhead or keep hands on the floor."]', '["Depuis la posture de Downward Dog, avancez un pied entre vos mains.", "Abaissez votre genou arrière vers le sol.", "Assurez-vous que votre genou avant est aligné avec votre cheville.", "Levez vos bras au-dessus de la tête ou gardez les mains au sol."]', '["Utilisez une couverture pour protéger votre genou arrière si besoin.", "Faites descendre vos hanches vers l''avant et vers le bas pour étirer davantage.", "Gardez votre sangle abdominale engagée et la colonne vertébrale droite."]', '["Pad your back knee with a blanket if needed.", "Sink your hips forward and down for a deeper stretch.", "Keep your core engaged and spine tall."]', '579695a3-b21a-4fe5-83fd-1bd47bfd2592', 'low-lunge-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('a049dc1c-359b-44e0-a571-6e3779c4a316', 'Sauts accroupis à genoux', NULL, NULL, 'Kneeling jump squat', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/kneeling-jump-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/kneeling-jump-squat.jpg', NULL, '["Concentre-toi sur un atterrissage doux pour réduire l''impact sur les genoux et les articulations", "Veille à ce que tes genoux soient alignés avec tes orteils lors du décollage et de l''atterrissage", "Garde le torse droit pendant tout le mouvement", "Utilise tes bras pour prendre de l''élan et équilibrer lors de la phase explosive", "Contrôle l''atterrissage en engageant tes abdominaux et tes muscles des jambes"]', '["Atterrissage trop brusque qui peut blesser les genoux", "Négliger l''alignement des genoux et des orteils"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "kneeling jump squat"]', true, '2026-04-03 12:24:57.507457+00', '2026-04-03 12:24:57.507457+00', 'Position de départ : Plonge dans une position de squat profond, les pieds à la largeur des épaules, bras tendus vers l''avant pour l''équilibre, poids sur les talons. Exécution : Saut explosif depuis la position accroupie, atterrissage doux dans la même position pour enchainer immédiatement avec la prochaine répétition.', '["Atterrissage trop brusque qui peut blesser les genoux", "Négliger l''alignement des genoux et des orteils"]', true, '["Start in a deep squat with thighs parallel to the floor and arms extended forward", "Keep your chest up and core engaged throughout the movement", "Explosively drive through your heels to jump straight up", "Land softly on the balls of your feet, immediately sinking back into the squat position", "Maintain control during the landing phase to absorb impact", "Continue the jumping motion in a rhythmic, controlled manner"]', '["Commence en position de squat profond avec les cuisses parallèles au sol et les bras tendus en avant", "Garde le torse relevé et les abdominaux engagés tout au long du mouvement", "Pousse explosivement à travers tes talons pour sauter droit vers le haut", "Atterris doucement sur la plante des pieds et replonge directement dans la position de squat", "Maintiens le contrôle lors de l''atterrissage pour absorber l''impact", "Continue le mouvement de saut de manière rythmée et contrôlée"]', '["Concentre-toi sur un atterrissage doux pour réduire l''impact sur les genoux et les articulations", "Veille à ce que tes genoux soient alignés avec tes orteils lors du décollage et de l''atterrissage", "Garde le torse droit pendant tout le mouvement", "Utilise tes bras pour prendre de l''élan et équilibrer lors de la phase explosive", "Contrôle l''atterrissage en engageant tes abdominaux et tes muscles des jambes"]', '["Focus on landing softly to reduce impact on knees and joints", "Keep your knees aligned with your toes during both takeoff and landing", "Maintain an upright torso position throughout the entire movement", "Use your arms for momentum and balance during the explosive phase", "Control the landing by engaging your core and leg muscles"]', 'ac6026af-173a-4357-ac12-2c7440a71a5d', 'kneeling-jump-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('993fe976-db22-4d9c-b53a-3a740552e18c', 'Relevés de genoux couchés', NULL, 'إرتقاءات الركب المتكئة', 'Lying knee tucks', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/lying-knee-tucks.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-knee-tucks.jpg', NULL, '["Garde des mouvements lents et contrôlés pour maximiser l''engagement musculaire et éviter l''élan", "Concentre-toi sur l''expiration lorsque tu crunches et l''inhalation en redescendant", "Évite de tirer sur ton cou ou d''utiliser tes bras pour prendre de l''élan", "Presse ton bas du dos contre le sol tout au long de l''exercice pour protéger ta colonne vertébrale", "Commence par un plus petit amplitude de mouvement si tu es débutant et augmente progressivement à mesure que tu te renforces"]', '["Tirer sur le cou au lieu de travailler les abdos", "Oublier de presser le bas du dos contre le sol"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "lying knee tucks"]', true, '2026-04-03 12:24:57.723747+00', '2026-04-03 12:24:57.723747+00', 'Position de départ : allonge-toi sur le dos, bras le long du corps et jambes tendues. Exécution : soulève simultanément tes genoux vers ta poitrine tout en relevant le haut de ton corps pour les rejoindre, puis redescends en contrôlant le mouvement.', '["Tirer sur le cou au lieu de travailler les abdos", "Oublier de presser le bas du dos contre le sol"]', true, '["Lie flat on your back on a mat with arms at your sides and legs extended straight", "Keep your core engaged and press your lower back into the floor", "Simultaneously lift your knees toward your chest while crunching your upper body forward", "Squeeze your abdominals at the top when knees meet chest", "Lower your upper body and legs back to starting position with slow, controlled movement", "Maintain constant tension in your core throughout the entire range of motion"]', '["Allonge-toi sur le dos sur un tapis, bras sur les côtés et jambes tendues", "Engage ton centre et presse le bas de ton dos contre le sol", "Soulève simultanément tes genoux vers ta poitrine en pliant le haut de ton corps", "Contracte tes abdos lorsque les genoux rencontrent la poitrine", "Redescends le haut de ton corps et tes jambes lentement à la position initiale", "Maintiens une tension constante dans ton centre tout au long de l''exercice"]', '["Garde des mouvements lents et contrôlés pour maximiser l''engagement musculaire et éviter l''élan", "Concentre-toi sur l''expiration lorsque tu crunches et l''inhalation en redescendant", "Évite de tirer sur ton cou ou d''utiliser tes bras pour prendre de l''élan", "Presse ton bas du dos contre le sol tout au long de l''exercice pour protéger ta colonne vertébrale", "Commence par un plus petit amplitude de mouvement si tu es débutant et augmente progressivement à mesure que tu te renforces"]', '["Keep movements slow and controlled to maximize muscle engagement and prevent momentum", "Focus on exhaling as you crunch up and inhaling as you lower down", "Avoid pulling on your neck or using your arms to generate momentum", "Keep your lower back pressed against the floor throughout the exercise to protect your spine", "Start with shorter ranges of motion if you''re a beginner and gradually increase as strength improves"]', '49ec0843-8680-48cd-bdf2-e871d435b583', 'lying-knee-tucks', NULL, NULL);
INSERT INTO public.exercises VALUES ('4dd6c759-185a-483d-b88b-76ca5fac9d1a', 'Développe tes pectoraux avec la machine Chest Fly', NULL, NULL, 'Machine Chest Fly', 'Chest', '[]', 'Chest', 'Beginner', 8, '/videos/chest/machine-chest-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/machine-chest-fly.jpg', NULL, '["Garde tes épaules en arrière et en bas contre le dossier pour éviter les douleurs aux épaules", "Maintiens une légère flexion dans tes coudes durant tout le mouvement pour protéger tes articulations", "Concentre-toi sur la contraction de tes muscles pectoraux plutôt que sur le simple déplacement du poids", "Contrôle autant la phase négative du mouvement que la phase positive pour maximiser l''engagement musculaire", "Évite de laisser les poids se toucher entre les répétitions pour garder une tension constante sur les muscles pectoraux"]', '["Ne pas ajuster la hauteur du siège correctement", "Utiliser un poids trop lourd qui conduit à une mauvaise technique"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "machine", "machine chest fly"]', true, '2026-04-03 12:24:57.748796+00', '2026-04-03 12:24:57.748796+00', 'Position de départ : Ajuste la machine à hauteur de poitrine et assieds-toi bien droit. Exécution : Ramène les poignées vers l’avant jusqu’à ce qu’elles se touchent, puis reviens lentement à la position initiale.', '["Ne pas ajuster la hauteur du siège correctement", "Utiliser un poids trop lourd qui conduit à une mauvaise technique"]', true, '["Adjust the seat height so your upper arms are parallel to the floor when grasping the handles", "Sit with your back firmly pressed against the pad and plant both feet flat on the floor", "Select an appropriate weight that allows you to maintain proper form throughout the entire range of motion", "Grasp the handles with a neutral grip and keep a slight bend in your elbows throughout the movement", "Bring your arms together in front of your chest by squeezing your pectoral muscles, avoiding momentum", "Slowly return to the starting position by controlling the weight back to the initial stretch position"]', '["Ajuste la hauteur du siège pour que tes bras soient parallèles au sol lorsque tu prends les poignées", "Assieds-toi fermement contre le dossier et garde les deux pieds à plat sur le sol", "Choisis un poids adéquat qui te permet de maintenir une bonne forme sur toute l’amplitude du mouvement", "Saisis les poignées avec une prise neutre et garde une légère flexion dans les coudes durant l''exercice", "Rassemble tes bras devant ta poitrine en contractant tes pectoraux, sans utiliser d''élan", "Reviens lentement à la position de départ en contrôlant le poids jusqu''à l''étirement initial"]', '["Garde tes épaules en arrière et en bas contre le dossier pour éviter les douleurs aux épaules", "Maintiens une légère flexion dans tes coudes durant tout le mouvement pour protéger tes articulations", "Concentre-toi sur la contraction de tes muscles pectoraux plutôt que sur le simple déplacement du poids", "Contrôle autant la phase négative du mouvement que la phase positive pour maximiser l''engagement musculaire", "Évite de laisser les poids se toucher entre les répétitions pour garder une tension constante sur les muscles pectoraux"]', '["Keep your shoulders back and down against the pad to prevent shoulder impingement", "Maintain a slight bend in your elbows throughout the entire movement to protect your shoulder joints", "Focus on squeezing your chest muscles rather than just moving the weight from point A to point B", "Control the negative portion of the movement just as much as the positive to maximize muscle engagement", "Avoid letting the weight stack touch between repetitions to maintain constant tension on the chest muscles"]', 'bf22d9ad-1aac-47e5-8e6f-f6072b868a6d', 'machine-chest-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('04a1ecf6-1d3b-42b1-b93a-4445091c9745', 'Hack Squat Large Écart', NULL, NULL, 'Hack Squat Wide Stance', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 8, '/videos/quadriceps/hack-squat-wide-stance.mp4', NULL, NULL, NULL, '/videos/thumbnails/hack-squat-wide-stance.jpg', NULL, '["Assure-toi que tes genoux suivent la ligne de tes orteils pendant tout le mouvement pour éviter toute tension sur les genoux.", "Reste en tension avec ton ventre et évite de courber le bas du dos contre le rembourrage.", "La large écart cible davantage les quadriceps internes et les fessiers par rapport à une variante avec écart serré.", "Contrôle la descente et évite de rebondir en bas pour maximiser l''engagement musculaire.", "Veille à garder le contact complet de tes pieds avec la plateforme et évite de te soulever sur les orteils pendant la montée."]', '["Ne pas garder le dos droit pendant la descente.", "Descendre trop bas sans contrôle."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "hack squat wide stance"]', true, '2026-04-03 12:24:56.877912+00', '2026-04-03 12:24:56.877912+00', 'Prends place dans la machine à hack squat avec les pieds écartés au-delà de la largeur des épaules. Exécute un squat profond tout en gardant le dos droit, puis pousse pour revenir à la position de départ.', '["Ne pas garder le dos droit pendant la descente.", "Descendre trop bas sans contrôle."]', true, '["Position yourself on the hack squat machine with your back flat against the backrest and shoulders firmly under the shoulder pads", "Place your feet wider than shoulder-width apart on the platform with toes pointed slightly outward", "Release the safety handles and slowly lower your body by bending at the knees and hips while keeping your core engaged", "Descend until your thighs are parallel to the platform or as low as your mobility allows", "Push through your heels and drive upward to return to the starting position while maintaining control", "Re-engage the safety handles when finished with your set"]', '["Positionne-toi sur la machine à hack squat, dos bien plaqué contre le dossier et épaules sous les coussins.", "Place tes pieds plus larges que la largeur des épaules sur la plateforme, les orteils légèrement tournés vers l''extérieur.", "Libère les poignées de sécurité et descends lentement en pliant les genoux et les hanches, tout en gardant le ventre bien engagé.", "Descends jusqu''à ce que tes cuisses soient parallèles à la plateforme ou aussi bas que ta mobilité le permet.", "Pousse à travers tes talons et monte pour revenir à la position de départ tout en gardant le contrôle.", "Réengage les poignées de sécurité lorsque tu as terminé ta série."]', '["Assure-toi que tes genoux suivent la ligne de tes orteils pendant tout le mouvement pour éviter toute tension sur les genoux.", "Reste en tension avec ton ventre et évite de courber le bas du dos contre le rembourrage.", "La large écart cible davantage les quadriceps internes et les fessiers par rapport à une variante avec écart serré.", "Contrôle la descente et évite de rebondir en bas pour maximiser l''engagement musculaire.", "Veille à garder le contact complet de tes pieds avec la plateforme et évite de te soulever sur les orteils pendant la montée."]', '["Keep your knees tracking in line with your toes throughout the entire movement to prevent knee stress", "Maintain constant tension in your core and avoid rounding your lower back against the pad", "The wide stance targets the inner quadriceps and glutes more than a narrow stance variation", "Control the descent and avoid bouncing at the bottom of the movement to maximize muscle engagement", "Ensure full foot contact with the platform and avoid rising onto your toes during the ascent"]', '46989ad6-9ec2-40b0-929d-54893160b1af', 'hack-squat-wide-stance', NULL, NULL);
INSERT INTO public.exercises VALUES ('77e6d27a-c473-4d69-9b97-3c26f784adf1', 'Squat à la Smith Machine', NULL, 'تمرين السكوات بالماكينة سميث', 'Smith Machine Squat', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/smith-machine-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-squat.jpg', NULL, '["Garde tes genoux alignés avec tes orteils pendant tout le mouvement", "Maintiens une colonne vertébrale neutre avec la poitrine relevée et évite de cambrer le dos", "Contrôle la descente et évite de rebondir en bas du squat", "Place tes pieds légèrement en avant de la barre car la machine Smith se déplace verticalement de manière fixe", "Engage ton tronc tout au long du mouvement pour protéger le bas de ton dos"]', '["Ne pas descendre assez bas dans le squat", "Ne pas garder le dos droit pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "smith machine squat"]', true, '2026-04-03 12:24:59.35437+00', '2026-04-03 12:24:59.35437+00', 'Position de départ : Installe-toi sous la machine Smith avec la barre reposant sur le haut de ton dos et les pieds à la largeur des épaules. Exécution : Descends en squat profond en gardant le dos droit, puis pousse pour revenir à la position de départ.', '["Ne pas descendre assez bas dans le squat", "Ne pas garder le dos droit pendant l''exercice"]', true, '["Set the Smith machine bar at upper chest height and add appropriate weight plates", "Position yourself under the bar with feet shoulder-width apart and the bar resting on your upper traps", "Grip the bar with hands wider than shoulder-width and unlock the bar by rotating it", "Lower your body by pushing hips back and bending knees, keeping chest up and core engaged", "Descend until thighs are parallel to the floor or as low as mobility allows", "Drive through your heels and push the floor away to return to starting position"]', '["Régle la barre de la machine Smith à hauteur de la poitrine et ajoute le poids adéquat", "Positionne-toi sous la barre, les pieds à la largeur des épaules et la barre reposant sur tes trapezes", "Prends la barre avec les mains plus larges que les épaules et déverrouille-la en la tournant", "Descends ton corps en poussant les hanches en arrière et en fléchissant les genoux, en gardant la poitrine relevée et le tronc engagé", "Descends jusqu''à ce que tes cuisses soient parallèles au sol ou aussi bas que ta mobilité le permet", "Pousse à travers tes talons et repousse le sol pour revenir à la position de départ"]', '["Garde tes genoux alignés avec tes orteils pendant tout le mouvement", "Maintiens une colonne vertébrale neutre avec la poitrine relevée et évite de cambrer le dos", "Contrôle la descente et évite de rebondir en bas du squat", "Place tes pieds légèrement en avant de la barre car la machine Smith se déplace verticalement de manière fixe", "Engage ton tronc tout au long du mouvement pour protéger le bas de ton dos"]', '["Keep your knees tracking in line with your toes throughout the entire movement", "Maintain a neutral spine with chest up and avoid rounding your back", "Control the descent and avoid bouncing at the bottom of the squat", "Place feet slightly forward of the bar since the Smith machine moves in a fixed vertical path", "Engage your core throughout the movement to protect your lower back"]', '427f98b5-d33e-4447-83cd-5cef54f0eb2f', 'smith-machine-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('5f8d8b49-4d03-480f-a0ab-8e11899a38c1', 'Fentes Arrières', NULL, NULL, 'Backward lunges', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/backward-lunges.mp4', NULL, NULL, NULL, '/videos/thumbnails/backward-lunges.jpg', NULL, '["Garde ton torse droit durant tout le mouvement pour maintenir une bonne forme et maximiser l''engagement des quadriceps.", "Contrôle la descente et ne chute pas rapidement pour éviter les blessures et activer davantage les muscles.", "Assure-toi que ton genou avant reste en ligne avec tes orteils et ne s''incline pas vers l''intérieur pendant l''exercice.", "Concentre ton poids sur ta jambe avant, qui est celle qui travaille pour cibler les quadriceps.", "Fais un pas suffisamment grand en arrière afin que les deux genoux puissent se plier confortablement à 90 degrés."]', '["Ne pas garder le torse droit, ce qui peut entraîner une mauvaise posture.", "Laisser le genou avant dépasser les orteils, ce qui peut augmenter le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "backward lunges"]', true, '2026-04-03 12:24:55.507183+00', '2026-04-03 12:24:55.507183+00', 'En position debout, les pieds écartés à la largeur des hanches, mains sur les hanches ou le long du corps, engage ton corps et redresse ton dos. Fais un pas en arrière avec une jambe en te mettant en position de fente, abaisse tes hanches jusqu''à ce que les deux genoux soient pliés à environ 90 degrés. Pousse ensuite avec le talon de la jambe avant pour revenir à la position de départ.', '["Ne pas garder le torse droit, ce qui peut entraîner une mauvaise posture.", "Laisser le genou avant dépasser les orteils, ce qui peut augmenter le risque de blessure."]', true, '["Stand with feet hip-width apart and engage your core for stability", "Step your right foot backward about 2-3 feet, landing on the ball of your foot", "Lower your hips straight down until your front thigh is parallel to the floor and your back knee nearly touches the ground", "Keep your front knee aligned over your ankle and avoid letting it drift forward past your toes", "Push through your front heel to drive yourself back to the starting position", "Repeat for desired reps, then switch legs"]', '["Tiens-toi debout, pieds à la largeur des hanches et engage ton cœur pour la stabilité.", "Recule ton pied droit d''environ 60-90 cm, en te posant sur la pointe de ton pied.", "Abaisse tes hanches droit vers le bas jusqu''à ce que ta cuisse avant soit parallèle au sol et que ton genou arrière frôle le sol.", "Assure-toi que ton genou avant reste au-dessus de ta cheville et ne dépasse pas tes orteils.", "Pousse avec le talon de ta jambe avant pour revenir à la position initiale.", "Répète le mouvement pour le nombre de répétitions souhaité, puis change de jambe."]', '["Garde ton torse droit durant tout le mouvement pour maintenir une bonne forme et maximiser l''engagement des quadriceps.", "Contrôle la descente et ne chute pas rapidement pour éviter les blessures et activer davantage les muscles.", "Assure-toi que ton genou avant reste en ligne avec tes orteils et ne s''incline pas vers l''intérieur pendant l''exercice.", "Concentre ton poids sur ta jambe avant, qui est celle qui travaille pour cibler les quadriceps.", "Fais un pas suffisamment grand en arrière afin que les deux genoux puissent se plier confortablement à 90 degrés."]', '["Keep your torso upright throughout the movement to maintain proper form and maximize quad engagement", "Control the descent slowly rather than dropping down quickly to prevent injury and increase muscle activation", "Ensure your front knee stays aligned with your toes and doesn''t cave inward during the movement", "Focus your weight on your front leg as this is the working leg that targets the quadriceps", "Take a large enough step backward to allow both knees to bend to 90 degrees comfortably"]', '80b6b175-77a8-48ac-9a09-495d114d88ef', 'backward-lunges', NULL, NULL);
INSERT INTO public.exercises VALUES ('4f5a90de-aee5-4572-96c6-5e7e5b05f466', 'Étirement Latéral (G)', NULL, 'تمارين الإطالة الجانبية (يسار)', 'My Side Bend Stretch (L)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/my-side-bend-stretch-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/my-side-bend-stretch-l.jpg', NULL, '["Garde tes deux pieds bien ancrés au sol tout au long de l''exercice.", "Ne te penche pas en avant ni en arrière, maintiens le mouvement uniquement sur le côté.", "Concentre-toi sur l''allongement de ta colonne plutôt que sur une compression vers le bas.", "Respire régulièrement et ne retiens pas ta respiration durant l''étirement.", "Arrête-toi immédiatement si tu ressens une douleur aigüe ou un inconfort."]', '["Ne pas maintenir le dos droit pendant l''étirement.", "Pencher trop en avant ou en arrière au lieu de rester sur le côté."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "my side bend stretch (l)"]', true, '2026-04-03 12:24:57.844935+00', '2026-04-03 12:24:57.844935+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des hanches, la main gauche sur la hanche, le bras droit tendu au-dessus de la tête. Exécution : Incline-toi lentement vers la gauche tout en allongeant ton bras droit au-dessus de ta tête pour ressentir un étirement agréable sur le côté droit de ton corps.', '["Ne pas maintenir le dos droit pendant l''étirement.", "Pencher trop en avant ou en arrière au lieu de rester sur le côté."]', true, '["Stand tall with feet hip-width apart and engage your core muscles", "Place your left hand on your left hip for support and stability", "Extend your right arm straight up overhead, reaching toward the ceiling", "Slowly lean your entire torso to the left while reaching your right arm over your head", "Hold the stretch for 15-30 seconds while breathing deeply", "Return to starting position slowly and controlled"]', '["Tiens-toi droit, les pieds écartés à la largeur des hanches, et engage ton cœur.", "Place ta main gauche sur ta hanche gauche pour te stabiliser.", "Étends ton bras droit vers le plafond, comme si tu voulais atteindre le ciel.", "Penche doucement ton torse vers la gauche en étendant ton bras droit au-dessus de ta tête.", "Reste en position d''étirement pendant 15 à 30 secondes en respirant profondément.", "Reviens lentement à la position de départ."]', '["Garde tes deux pieds bien ancrés au sol tout au long de l''exercice.", "Ne te penche pas en avant ni en arrière, maintiens le mouvement uniquement sur le côté.", "Concentre-toi sur l''allongement de ta colonne plutôt que sur une compression vers le bas.", "Respire régulièrement et ne retiens pas ta respiration durant l''étirement.", "Arrête-toi immédiatement si tu ressens une douleur aigüe ou un inconfort."]', '["Keep both feet planted firmly on the ground throughout the movement", "Avoid leaning forward or backward - maintain the side bend in the frontal plane only", "Focus on lengthening through the spine rather than compressing downward", "Breathe steadily and avoid holding your breath during the stretch", "Stop immediately if you feel any sharp pain or discomfort"]', '1b83ce89-e537-4d37-be07-af8b5c192edd', 'my-side-bend-stretch-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('881cb6d9-667a-415a-bafa-720d92d1e0bd', 'Marche en crabe vers les squats', NULL, 'المشي على اليدين نحو القرفصاء', 'Crab walks into squats', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/crab-walks-into-squats.mp4', NULL, NULL, NULL, '/videos/thumbnails/crab-walks-into-squats.jpg', NULL, '["Garde tes hanches élevées pendant la marche en crabe pour maximiser l''engagement des fessiers et du tronc", "Assure-toi de maintenir une bonne forme de squat, les genoux alignés avec tes orteils et le poids sur tes talons", "Fais des pas contrôlés pendant la marche en crabe, ne te précipite pas à travers le mouvement", "Renforce tes poignets et engage tes épaules pour protéger tes articulations pendant la position de crabe."]', '["Hanches trop basses pendant la marche en crabe.", "Genoux qui dépassent les orteils lors des squats."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "crab walks into squats"]', true, '2026-04-03 12:24:56.198994+00', '2026-04-03 12:24:56.198994+00', 'Position de départ : Mets-toi en position de marche en crabe, les mains derrière toi, doigts tournés vers tes pieds, genoux fléchis et hanches surélevées. Exécution : Avance sur le côté en position de crabe pendant 3-4 pas, puis redresse-toi et enchaîne tout de suite avec un squat au poids du corps avant de revenir à la position de crabe.', '["Hanches trop basses pendant la marche en crabe.", "Genoux qui dépassent les orteils lors des squats."]', true, '["Start in a crab position with hands planted behind you, fingers pointing away from your body, and feet flat on the ground with knees bent", "Engage your core and lift your hips off the ground, supporting your weight on your hands and feet", "Take small steps sideways while maintaining the crab position, moving your opposite hand and foot together", "After taking several lateral steps, lower your hips and transition to standing by bringing your feet together", "Immediately perform a bodyweight squat by pushing your hips back, bending your knees, and lowering until your thighs are parallel to the ground", "Return to standing and repeat the sequence by going back into crab position for the next set"]', '["Commence en position de crabe, mains ancrées derrière toi, doigts dirigés vers l''extérieur et pieds à plat au sol avec les genoux fléchis", "Active ton centre et lève tes hanches, soutenant ton poids sur tes mains et tes pieds", "Fais de petits pas sur le côté tout en maintenant ta position de crabe, en déplaçant simultanément ta main et ton pied opposés", "Après plusieurs pas latéraux, abaisse tes hanches et passe à la position debout en rapprochant tes pieds", "Effectue immédiatement un squat au poids du corps en poussant tes hanches en arrière, en fléchissant tes genoux, jusqu''à ce que tes cuisses soient parallèles au sol", "Retourne debout et recommence la séquence en revenant en position de crabe pour le prochain set."]', '["Garde tes hanches élevées pendant la marche en crabe pour maximiser l''engagement des fessiers et du tronc", "Assure-toi de maintenir une bonne forme de squat, les genoux alignés avec tes orteils et le poids sur tes talons", "Fais des pas contrôlés pendant la marche en crabe, ne te précipite pas à travers le mouvement", "Renforce tes poignets et engage tes épaules pour protéger tes articulations pendant la position de crabe."]', '["Keep your hips elevated throughout the crab walk portion to maximize glute and core engagement", "Maintain proper squat form with knees tracking over your toes and weight in your heels", "Take controlled steps during the crab walk rather than rushing through the movement", "Keep your wrists strong and shoulders engaged to protect your joints during the crab position"]', '10be21b8-de6f-4c33-9101-eadca351e663', 'crab-walks-into-squats', NULL, NULL);
INSERT INTO public.exercises VALUES ('a77d67a9-7f99-4e2a-aad2-d6eff84fc8fb', 'Développé couché haltère à un bras - avec rotation', NULL, '', 'One Arm Dumbbell Bench Press - with rotation', 'Chest', '[]', 'Chest', 'Intermediate', 2, '/videos/chest/one-arm-dumbbell-bench-press-with-rotation.mp4', NULL, NULL, NULL, '/videos/thumbnails/one-arm-dumbbell-bench-press-with-rotation.jpg', NULL, '["Maintiens ton bras non travaillant soit reposant sur ton torse, soit agrippant le banc pour plus de stabilité", "Contrôle le mouvement de rotation - il doit être subtil et naturel, pas forcé ou excessif", "Garde la tension dans ton ventre tout au long de l''exercice pour éviter de trop pivoter ou de perdre l''équilibre sur le banc", "Utilise un poids plus léger que pour le développé couché bilatéral jusqu''à ce que tu maîtrises la coordination et l''équilibre nécessaires"]', '["Ne pas stabiliser le tronc pendant le mouvement", "Trop forcer sur la rotation du torse"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "dumbbell", "one arm dumbbell bench press - with rotation"]', true, '2026-04-03 12:24:58.086864+00', '2026-04-03 12:24:58.086864+00', 'Position de départ : Allonge-toi sur un banc plat avec un haltère dans ta main droite, directement au-dessus de ton épaule, bras tendu. Ton bras gauche repose sur le côté ou tient le banc pour plus de stabilité. Exécution : Abaisse l''haltère vers ta poitrine tout en tournant légèrement ton torse vers le bras qui travaille, puis pousse à nouveau vers le haut en revenant au centre.', '["Ne pas stabiliser le tronc pendant le mouvement", "Trop forcer sur la rotation du torse"]', true, '["Set up on a flat bench with feet firmly planted on the floor and core engaged for stability", "Hold one dumbbell with a neutral grip, starting with arm fully extended above your shoulder", "Lower the weight slowly toward the outside of your chest while allowing a slight torso rotation toward the working side", "Keep your shoulder blade pulled back and down throughout the movement", "Press the dumbbell back up to starting position while rotating your torso back to center", "Complete all repetitions on one side before switching to the other arm"]', '["Installe-toi sur un banc plat avec les pieds bien ancrés au sol et le ventre engagé pour la stabilité", "Tiens l''haltère avec une prise neutre, le bras entièrement tendu au-dessus de ton épaule", "Abaisse doucement le poids vers l''extérieur de ta poitrine tout en effectuant une légère rotation de ton torse vers le côté qui travaille", "Garde ton omoplate tirée vers l''arrière et le bas tout au long du mouvement", "Pousse l''haltère vers le haut pour revenir à la position de départ tout en revenant ton torse au centre", "Effectue toutes les répétitions d''un côté avant de changer de bras"]', '["Maintiens ton bras non travaillant soit reposant sur ton torse, soit agrippant le banc pour plus de stabilité", "Contrôle le mouvement de rotation - il doit être subtil et naturel, pas forcé ou excessif", "Garde la tension dans ton ventre tout au long de l''exercice pour éviter de trop pivoter ou de perdre l''équilibre sur le banc", "Utilise un poids plus léger que pour le développé couché bilatéral jusqu''à ce que tu maîtrises la coordination et l''équilibre nécessaires"]', '["Keep the non-working arm either resting on your torso or gripping the bench for additional stability", "Control the rotational movement - it should be subtle and natural, not forced or excessive", "Maintain tension in your core throughout to prevent excessive twisting or losing balance on the bench", "Use a lighter weight than you would for bilateral dumbbell bench press until you master the coordination and balance required"]', '70ac8f96-201b-4bd7-9ac5-f72e3aca2748', 'one-arm-dumbbell-bench-press-with-rotation', NULL, NULL);
INSERT INTO public.exercises VALUES ('c557b45a-95dd-4509-a6ba-3d34f9c14440', 'Kettlebell Snatch à Un Bras - Du Sol', NULL, 'سناج بالكيطابل بيد واحدة - من الأرض', 'One-Arm Kettlebell Snatch - From ground', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 128, '/videos/bodyweight/one-arm-kettlebell-snatch-from-ground.mp4', NULL, NULL, NULL, '/videos/thumbnails/one-arm-kettlebell-snatch-from-ground.jpg', NULL, '["Exercice avancé - maîtrise d''abord le swing et le clean", "Évite de faire basculer le kettlebell sur le poignet", "Effectue un mouvement fluide du sol jusqu''au sommet", "Verrouille complètement au sommet", "Contrôle bien la descente"]', '["Ne pas verrouiller les bras au sommet", "Laisser le kettlebell tomber trop vite lors de la descente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "kettlebell", "one-arm kettlebell snatch - from ground"]', true, '2026-04-03 12:24:58.193495+00', '2026-04-03 12:24:58.193495+00', 'Un exercice puissant qui sollicite l''ensemble du corps. Renforce ta force, ta coordination et ta puissance explosive en un seul mouvement !', '["Ne pas verrouiller les bras au sommet", "Laisser le kettlebell tomber trop vite lors de la descente"]', true, '["Kettlebell between feet", "Hinge, grip with one hand", "Swing back, then explosively drive hips", "Pull kettlebell overhead in one motion", "Punch through at top, catch overhead"]', '["Place le kettlebell entre tes pieds", "Pousse les hanches en arrière et saisis-le d''une main", "Balance-le vers l''arrière, puis propulse tes hanches vers l''avant", "Tire le kettlebell au-dessus de ta tête en un seul mouvement", "Verrouille bien au sommet et sers-le bien au-dessus de ta tête"]', '["Exercice avancé - maîtrise d''abord le swing et le clean", "Évite de faire basculer le kettlebell sur le poignet", "Effectue un mouvement fluide du sol jusqu''au sommet", "Verrouille complètement au sommet", "Contrôle bien la descente"]', '["Advanced movement - learn swing and clean first", "Don''t flip kettlebell onto wrist", "One smooth motion from floor to overhead", "Lock out completely at top", "Control the descent"]', '79b0e11d-db13-4542-a7ac-7f666485f1fa', 'one-arm-kettlebell-snatch-from-ground', NULL, NULL);
INSERT INTO public.exercises VALUES ('b7986b4b-5683-4761-a324-a27c1c88d9c7', 'Élévations Latérales Unilatérales (Bras Droit)', NULL, NULL, 'One-Arm Side Laterals (R)', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/one-arm-side-laterals-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/one-arm-side-laterals-r.jpg', NULL, '["Garde ton torse droit et évite de te pencher du côté du bras qui travaille", "Concentre-toi sur le fait de soulever avec tes muscles d''épaule, pas sur le mouvement ou l''élan", "Maintiens un rythme contrôlé avec une phase de levée de 2 secondes et de descente de 3 secondes", "Arrête-toi à la hauteur de l''épaule pour éviter les blessures et maintenir une bonne forme", "Fais toutes les répétitions du côté droit avant de passer au bras gauche"]', '["Se pencher vers l''avant ou sur le côté pendant l''exercice", "Utiliser un élan au lieu de la force musculaire pour soulever le bras"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "one-arm side laterals (r)"]', true, '2026-04-03 12:24:58.207135+00', '2026-04-03 12:24:58.207135+00', 'Position de départ : Tiens-toi bien droit, les pieds écartés à la largeur des épaules, main gauche sur la hanche pour plus de stabilité, bras droit pendant sur le côté. Exécution : Éléve ton bras droit sur le côté jusqu''à la hauteur de l''épaule, puis redescend lentement à la position de départ.', '["Se pencher vers l''avant ou sur le côté pendant l''exercice", "Utiliser un élan au lieu de la force musculaire pour soulever le bras"]', true, '["Stand tall with core engaged and feet planted firmly on the ground", "Place your left hand on your hip to maintain balance and stability", "Keep your right arm straight but not locked, with a slight bend at the elbow", "Raise your right arm out to the side in a controlled arc until it reaches shoulder height", "Hold briefly at the top position, feeling the contraction in your shoulder", "Lower your arm slowly back to the starting position, maintaining control throughout the movement"]', '["Tiens-toi bien droit avec ton ventre engagé et les pieds bien ancrés au sol", "Pose ta main gauche sur ta hanche pour maintenir l''équilibre et la stabilité", "Garde ton bras droit droit mais pas verrouillé, avec une légère flexion au niveau du coude", "Élève ton bras droit sur le côté dans un mouvement contrôlé jusqu''à ce qu''il atteigne la hauteur de l''épaule", "Tiens le mouvement une seconde en haut, sens la contraction dans ton épaule", "Redescends lentement ton bras à la position de départ, en gardant le contrôle tout au long du mouvement"]', '["Garde ton torse droit et évite de te pencher du côté du bras qui travaille", "Concentre-toi sur le fait de soulever avec tes muscles d''épaule, pas sur le mouvement ou l''élan", "Maintiens un rythme contrôlé avec une phase de levée de 2 secondes et de descente de 3 secondes", "Arrête-toi à la hauteur de l''épaule pour éviter les blessures et maintenir une bonne forme", "Fais toutes les répétitions du côté droit avant de passer au bras gauche"]', '["Keep your torso upright and avoid leaning away from the working arm", "Focus on lifting with your shoulder muscles rather than swinging or using momentum", "Maintain a controlled tempo with a 2-second lift and 3-second lowering phase", "Stop at shoulder height to avoid impingement and maintain proper form", "Complete all repetitions on the right side before switching to the left arm"]', '40e40492-ae55-417f-8391-2e6ea6c170d9', 'one-arm-side-laterals-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('9c9f8729-73e2-4f03-8793-40984091c14b', 'Squat Overhead', NULL, 'Squat Développé', 'Overhead Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/overhead-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/overhead-squat.jpg', NULL, '["Garde les bras tendus au-dessus de ta tête tout au long de l''exercice pour renforcer la stabilité et la force du tronc.", "Veille à écarter les genoux en ligne avec les orteils pour éviter les problèmes de genoux.", "Maintiens un buste droit - évite de te pencher trop en avant, cela pourrait indiquer des restrictions de mobilité.", "Commence avec une amplitude de mouvement partielle si tu n''as pas la souplesse nécessaire pour faire un squat overhead complet en toute sécurité.", "Cet exercice nécessite une bonne mobilité des épaules et des chevilles - échauffe-toi bien avant de commencer."]', '["Fléchir les bras au-dessus de la tête, ce qui compromet l''équilibre.", "Laisser les genoux s''affaisser vers l''intérieur pendant le squat."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "overhead squat"]', true, '2026-04-03 12:24:58.244638+00', '2026-04-03 12:24:58.244638+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des épaules, bras tendus au-dessus de la tête, mains légèrement plus larges que les épaules, paumes vers l''avant. Exécution : Descends en squat en poussant les hanches en arrière et en fléchissant les genoux, tout en gardant les bras au-dessus de la tête et la poitrine relevée, puis remonte à la position de départ.', '["Fléchir les bras au-dessus de la tête, ce qui compromet l''équilibre.", "Laisser les genoux s''affaisser vers l''intérieur pendant le squat."]', true, '["Stand with feet shoulder-width apart and raise both arms straight overhead with palms facing forward", "Keep your core engaged and chest up throughout the entire movement", "Initiate the squat by pushing your hips back and bending at the knees while maintaining arm position", "Lower until your thighs are parallel to the floor or as low as your mobility allows", "Drive through your heels to return to the starting position while keeping arms overhead", "Maintain control throughout both the descent and ascent phases"]', '["Positionne-toi debout, pieds à la largeur des épaules, bras droits au-dessus de la tête, paumes vers l''avant.", "Garde les abdos contractés et la poitrine relevée pendant tout le mouvement.", "Commence le squat en poussant les hanches en arrière et en fléchissant les genoux tout en maintenant la position des bras.", "Descends jusqu''à ce que tes cuisses soient parallèles au sol ou aussi bas que ta mobilité le permet.", "Pousse avec tes talons pour revenir à la position de départ en gardant les bras au-dessus de la tête.", "Contrôle bien le mouvement pendant la descente et la montée."]', '["Garde les bras tendus au-dessus de ta tête tout au long de l''exercice pour renforcer la stabilité et la force du tronc.", "Veille à écarter les genoux en ligne avec les orteils pour éviter les problèmes de genoux.", "Maintiens un buste droit - évite de te pencher trop en avant, cela pourrait indiquer des restrictions de mobilité.", "Commence avec une amplitude de mouvement partielle si tu n''as pas la souplesse nécessaire pour faire un squat overhead complet en toute sécurité.", "Cet exercice nécessite une bonne mobilité des épaules et des chevilles - échauffe-toi bien avant de commencer."]', '["Keep your arms locked out overhead throughout the entire movement to challenge stability and core strength", "Focus on pushing your knees out in line with your toes to prevent knee valgus", "Maintain an upright torso position - avoid leaning forward excessively as this indicates mobility restrictions", "Start with partial range of motion if you lack the flexibility to perform a full overhead squat safely", "This exercise requires significant shoulder and ankle mobility - warm up thoroughly before attempting"]', '24c4168e-f900-4e8b-8969-cd32dba34d6c', 'overhead-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('31fd897e-8ac1-48c0-a64e-f6f6e7bbdcc0', 'Flexions de genoux en pike', NULL, NULL, 'Pike hold knee bends', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/pike-hold-knee-bends.mp4', NULL, NULL, NULL, '/videos/thumbnails/pike-hold-knee-bends.jpg', NULL, '["Gardez vos épaules directement au-dessus de vos poignets et gardez les bras droits tout au long du mouvement.", "Activez vos muscles abdominaux pour éviter que vos hanches ne tombent ou ne se balancent.", "Commencez par des temps de maintien plus courts et moins de répétitions, augmentez progressivement à mesure que vous gagnez en force.", "Si vous ressentez une gêne au niveau des poignets, effectuez l''exercice sur vos poings ou utilisez des prises de pompier.", "Concentrez-vous sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement musculaire et maintenir une bonne forme."]', '["Ne pas engager les muscles abdominaux, ce qui peut entraîner une mauvaise posture.", "Baisser les hanches, perdant ainsi l''alignement du corps."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "pike hold knee bends"]', true, '2026-04-03 12:24:58.261177+00', '2026-04-03 12:24:58.261177+00', 'Un exercice complet pour renforcer tout le corps tout en améliorant la stabilité et l''agilité ! Prêt à relever le défi ?', '["Ne pas engager les muscles abdominaux, ce qui peut entraîner une mauvaise posture.", "Baisser les hanches, perdant ainsi l''alignement du corps."]', true, '["Start in a pike position with hands planted firmly on the ground, arms straight, and hips raised high to form an inverted V-shape", "Engage your core and maintain straight legs with feet hip-width apart", "Slowly bend one knee and draw it toward your chest while keeping your weight balanced on your hands", "Hold the knee bend for 2-3 seconds, maintaining the pike position with your hips elevated", "Slowly extend the leg back to the starting position with control", "Repeat with the opposite leg, alternating sides for the desired number of repetitions"]', '["Positionnez-vous en pike, les mains fermement posées au sol, les bras tendus et les hanches élevées pour former un V inversé.", "Contractez votre sangle abdominale et gardez les jambes droites, les pieds écartés à la largeur des hanches.", "Bendez lentement un genou et ramenez-le vers votre poitrine tout en équilibrant votre poids sur vos mains.", "Maintenez la flexion du genou pendant 2 à 3 secondes, en gardant les hanches élevées dans la position de pike.", "Réétendez lentement la jambe à la position de départ avec contrôle.", "Répétez avec l''autre jambe, en alternant pour le nombre de répétitions souhaité."]', '["Gardez vos épaules directement au-dessus de vos poignets et gardez les bras droits tout au long du mouvement.", "Activez vos muscles abdominaux pour éviter que vos hanches ne tombent ou ne se balancent.", "Commencez par des temps de maintien plus courts et moins de répétitions, augmentez progressivement à mesure que vous gagnez en force.", "Si vous ressentez une gêne au niveau des poignets, effectuez l''exercice sur vos poings ou utilisez des prises de pompier.", "Concentrez-vous sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement musculaire et maintenir une bonne forme."]', '["Keep your shoulders directly over your wrists and maintain straight arms throughout the movement", "Engage your core muscles to prevent your hips from dropping or swaying", "Start with shorter hold times and fewer repetitions, gradually increasing as you build strength", "If you experience wrist discomfort, perform the exercise on your fists or use push-up handles", "Focus on controlled movements rather than speed to maximize muscle engagement and maintain proper form"]', '04fccb0f-58a7-44b2-8676-573faad17634', 'pike-hold-knee-bends', NULL, NULL);
INSERT INTO public.exercises VALUES ('1329e44c-37cc-47fe-ac44-aa077603e663', 'Exercice de Reverse Fly Plank', NULL, 'تمرين الطيران العكسي في وضع البلانك', 'Reverse fly plank to plank hop', 'Shoulders', '[]', 'Shoulders', 'Beginner', 16, '/videos/shoulders/reverse-fly-plank-to-plank-hop.mp4', NULL, NULL, NULL, '/videos/thumbnails/reverse-fly-plank-to-plank-hop.jpg', NULL, '["Garde ton core engagé pour éviter que tes hanches ne s''affaissent ou que ton dos ne se cambrent.", "Maintiens l''alignement de ton planche même lorsque tu soulèves une main.", "Contrôle le mouvement de vol inversé - ne laisse pas l''élan prendre le dessus.", "Garde le bras de soutien solide et stable pendant le mouvement de bras unique.", "Atterris en douceur lors des sauts pour protéger tes articulations."]', '["Ne pas maintenir la position de planche correcte en soulevant une main.", "Laisser le dos s''archer ou les hanches s''affaisser pendant l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "bodyweight", "reverse fly plank to plank hop"]', true, '2026-04-03 12:24:58.582154+00', '2026-04-03 12:24:58.582154+00', 'Position de départ : Commence dans une position de planche, mains bien ancrées au sol, corps aligné de la tête aux talons. Exécution : Soulève une main et fais un mouvement de vol inversé sur le côté, puis retourne en planche et effectue un petit saut ou un ajustement avec les pieds.', '["Ne pas maintenir la position de planche correcte en soulevant une main.", "Laisser le dos s''archer ou les hanches s''affaisser pendant l''exercice."]', true, '["Start in a high plank position with hands directly under shoulders and body in a straight line", "Engage your core and maintain steady breathing throughout the movement", "Lift one hand off the ground and sweep it out to the side, opening up the chest", "Return the hand back to starting plank position with control", "Perform a small hop or step adjustment with your feet while maintaining plank form", "Repeat the sequence, alternating arms or maintaining the same pattern"]', '["Prends position en planche haute, mains sous les épaules et corps en ligne droite.", "Engage ton core et respire régulièrement pendant l''exercice.", "Soulève une main du sol et fais un mouvement sur le côté, en ouvrant bien la poitrine.", "Ramène la main à la position de départ en contrôle.", "Effectue un petit saut ou un ajustement avec tes pieds tout en gardant la forme de la planche.", "Répète la séquence, en alternant les bras ou en suivant le même schéma."]', '["Garde ton core engagé pour éviter que tes hanches ne s''affaissent ou que ton dos ne se cambrent.", "Maintiens l''alignement de ton planche même lorsque tu soulèves une main.", "Contrôle le mouvement de vol inversé - ne laisse pas l''élan prendre le dessus.", "Garde le bras de soutien solide et stable pendant le mouvement de bras unique.", "Atterris en douceur lors des sauts pour protéger tes articulations."]', '["Keep your core engaged throughout to prevent sagging hips or arching back", "Maintain proper plank alignment even when lifting one hand off the ground", "Control the reverse fly movement - don''t let momentum take over", "Keep the supporting arm strong and stable when performing the single-arm movement", "Land softly during any hopping movements to protect joints"]', 'c265b4e3-ab8d-4141-9d7e-462e2c329d1b', 'reverse-fly-plank-to-plank-hop', NULL, NULL);
INSERT INTO public.exercises VALUES ('151f9ffd-9485-4763-8712-fb3def57b20a', 'Développé Épaules avec Haltères', NULL, NULL, 'Dumbbell Shoulder Press', 'Shoulders', '[]', 'Shoulders', 'Beginner', 2, '/videos/shoulders/dumbbell-shoulder-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-shoulder-press.jpg', NULL, '["Garde les abdominaux contractés, dos contre le support", "Évite de faire heurter les haltères en haut du mouvement", "Assure-toi d''un mouvement complet", "Contrôle la descente", "Ne creuse pas excessivement le dos"]', '["Trop pousser avec le dos au lieu des épaules", "Ne pas abaisser les haltères assez bas"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "dumbbell shoulder press"]', true, '2026-04-03 12:24:56.57104+00', '2026-04-03 12:24:56.57104+00', 'Position de départ : Assieds-toi sur un banc avec un haltère dans chaque main, bras tendus vers le haut, paumes face à face. Exécution : Abaisse les haltères jusqu''à tes épaules, puis pousse vers le haut pour revenir à la position initiale.', '["Trop pousser avec le dos au lieu des épaules", "Ne pas abaisser les haltères assez bas"]', true, '["Sit on bench with back support; the exercise can also be done standing", "Hold dumbbells at shoulder height, palms forward", "Press straight up until arms extended", "Lower with control to shoulders"]', '["Installe-toi sur un banc avec support dorsal ; tu peux aussi faire l''exercice en position debout", "Maintiens les haltères à hauteur d''épaules, paumes orientées vers l''avant", "Pousse droit vers le haut jusqu''à ce que tes bras soient complètement tendus", "Abaisse les haltères avec contrôle jusqu''à tes épaules"]', '["Garde les abdominaux contractés, dos contre le support", "Évite de faire heurter les haltères en haut du mouvement", "Assure-toi d''un mouvement complet", "Contrôle la descente", "Ne creuse pas excessivement le dos"]', '["Keep core tight, back against pad", "Don''t clang dumbbells at top", "Full range of motion", "Control the negative", "Don''t arch back excessively"]', 'd6c2798d-a077-41b9-9769-d5bd1a57caaa', 'dumbbell-shoulder-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('39dd152c-c50d-4695-bc46-86ecc620a84a', 'Touche de genou en planche', NULL, NULL, 'Plank to knee tap', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-to-knee-tap.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-to-knee-tap.jpg', NULL, '["Garde ton core actif pour éviter que le bas du dos ne s''affaisse", "Maintiens une colonne vertébrale neutre et ne lève pas trop tes hanches", "Contrôle le mouvement - évite de laisser tomber le genou sur le sol", "Garde tes mains bien en place et tes épaules stables au-dessus de tes poignets", "Concentre-toi sur des mouvements de hanches minimaux pour maximiser l''activation du core"]', '["Ne pas engager correctement le core", "Laisser les hanches balancer d''un côté à l''autre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank to knee tap"]', true, '2026-04-03 12:24:58.355991+00', '2026-04-03 12:24:58.355991+00', 'Position de départ : commence en position de planche, mains ancrées au sol, corps en ligne droite de la tête aux talons. Exécution : tout en maintenant la planche, alterne en amenant chaque genou pour tapoter doucement le sol sous ton torse, puis reviens à la position initiale.', '["Ne pas engager correctement le core", "Laisser les hanches balancer d''un côté à l''autre"]', true, '["Start in a high plank position with hands directly under shoulders and body in a straight line", "Engage your core and keep hips level throughout the movement", "Slowly lower one knee down to lightly tap the ground beneath your torso", "Return the knee back to the starting plank position with control", "Alternate to the opposite knee and repeat the tapping motion", "Maintain steady breathing and avoid rocking the hips side to side"]', '["Positionne-toi en planche haute, mains sous les épaules et corps bien aligné", "Active ton core et garde les hanches stables pendant l''exercice", "Abaisse doucement un genou pour tapoter le sol sous ton torse", "Ramène le genou à la position de planche avec contrôle", "Alterne avec l''autre genou et répète le mouvement de tapotement", "Respire régulièrement et évite les mouvements de balancement des hanches"]', '["Garde ton core actif pour éviter que le bas du dos ne s''affaisse", "Maintiens une colonne vertébrale neutre et ne lève pas trop tes hanches", "Contrôle le mouvement - évite de laisser tomber le genou sur le sol", "Garde tes mains bien en place et tes épaules stables au-dessus de tes poignets", "Concentre-toi sur des mouvements de hanches minimaux pour maximiser l''activation du core"]', '["Keep your core engaged throughout to prevent sagging in the lower back", "Maintain a neutral spine and avoid lifting your hips too high", "Control the movement - don''t drop the knee heavily to the ground", "Keep your hands firmly planted and shoulders stable over your wrists", "Focus on minimal hip movement to maximize core activation"]', 'c2b2d15f-5841-45a2-87e4-503101f3422e', 'plank-to-knee-tap', NULL, NULL);
INSERT INTO public.exercises VALUES ('d0215896-4b9b-41ce-8832-8846f3d1570f', 'Développé Épaules Sur Machine Incliné', NULL, NULL, 'Incline Machine Shoulder Press', 'Shoulders', '[]', 'Shoulders', 'Beginner', 8, '/videos/shoulders/incline-machine-shoulder-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/incline-machine-shoulder-press.jpg', NULL, '["Garde ton gainage actif et évite d''arquer excessivement le bas de ton dos pendant le press", "Concentre-toi sur la poussée du poids vers le haut et légèrement en avant en suivant l''arc naturel du mouvement des épaules", "Utilise une amplitude complète mais évite de descendre le poids trop bas pour prévenir l''impingement de l''épaule", "Commence avec un poids léger pour maîtriser le mouvement avant de passer à des charges plus lourdes", "Maintiens le contrôle sur toute l''amplitude du mouvement, surtout lors de la phase de descente."]', '["Ne pas ajuster la hauteur du siège correctement", "Utiliser un poids trop lourd sans maîtriser la technique"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "incline machine shoulder press"]', true, '2026-04-03 12:24:57.314373+00', '2026-04-03 12:24:57.314373+00', 'Position de départ : assieds-toi sur la machine de développé incliné, ajuste la hauteur du siège pour que les poignées soient au niveau des épaules. Exécution : pousse les poignées vers le haut jusqu''à ce que tes bras soient complètement étendus, puis ramène-les lentement à la position de départ.', '["Ne pas ajuster la hauteur du siège correctement", "Utiliser un poids trop lourd sans maîtriser la technique"]', true, '["Adjust the seat height so the handles align with your shoulders when seated", "Set your back firmly against the pad and plant your feet flat on the floor for stability", "Grasp the handles with a full grip, positioning your hands slightly wider than shoulder-width", "Press the weight up in a smooth, controlled motion without locking your elbows aggressively", "Lower the weight slowly with control, stopping when your elbows reach about 90 degrees", "Maintain steady breathing throughout the movement, exhaling on the press and inhaling on the descent"]', '["Ajuste la hauteur du siège pour que les poignées soient à la hauteur de tes épaules lorsque tu es assis", "Appuie ton dos fermement contre le dossier et plante tes pieds à plat sur le sol pour plus de stabilité", "Saisis les poignées avec une prise complète, les mains légèrement plus larges que la largeur des épaules", "Pousse le poids vers le haut en un mouvement fluide et contrôlé sans verrouiller tes coudes de façon agressive", "Abaisse le poids lentement en contrôlant le mouvement, en t''arrêtant lorsque tes coudes atteignent environ 90 degrés", "Respire régulièrement tout au long du mouvement, expire en poussant et inspire en descendant."]', '["Garde ton gainage actif et évite d''arquer excessivement le bas de ton dos pendant le press", "Concentre-toi sur la poussée du poids vers le haut et légèrement en avant en suivant l''arc naturel du mouvement des épaules", "Utilise une amplitude complète mais évite de descendre le poids trop bas pour prévenir l''impingement de l''épaule", "Commence avec un poids léger pour maîtriser le mouvement avant de passer à des charges plus lourdes", "Maintiens le contrôle sur toute l''amplitude du mouvement, surtout lors de la phase de descente."]', '["Keep your core engaged and avoid arching your lower back excessively during the press", "Focus on pressing the weight up and slightly forward following the natural arc of shoulder movement", "Use a full range of motion but avoid lowering the weight too far to prevent shoulder impingement", "Start with lighter weight to master the movement pattern before progressing to heavier loads", "Maintain control throughout the entire range of motion, especially during the lowering phase"]', 'da022ba5-3a51-4861-9b25-232529d5de8e', 'incline-machine-shoulder-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('7dcd2107-eb46-459a-98ed-c779861b0755', 'Développé Épaules Unilatéral avec Haltère (D)', NULL, NULL, 'Dumbbell One-Arm Shoulder Press (R)', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/dumbbell-one-arm-shoulder-press-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-one-arm-shoulder-press-r.jpg', NULL, '["Garde ton core engagé tout au long du mouvement pour éviter de cambrer le dos.", "Pousse le poids directement vers le haut plutôt qu''en avant pour éviter les problèmes d’épaule.", "Maintiens une position neutre de ton poignet et évite que l''haltère ne bascule.", "Choisis un poids qui te permet de garder une bonne forme pour toutes les répétitions.", "Évite de verrouiller agressivement ton coude en haut du mouvement."]', '["Ne pas engager le core, ce qui peut entraîner une mauvaise posture.", "Pousser le poids en avant au lieu de droit vers le haut, ce qui peut causer des douleurs à l’épaule."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "dumbbell one-arm shoulder press (r)"]', true, '2026-04-03 12:24:56.519533+00', '2026-04-03 12:24:56.519533+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des épaules, un haltère dans la main droite au niveau de l''épaule, paume face à l’avant et coude bien sous le poids. Exécution : Pousse l''haltère vers le haut jusqu''à ce que ton bras soit complètement tendu, puis redescends-le lentement à la position de départ.', '["Ne pas engager le core, ce qui peut entraîner une mauvaise posture.", "Pousser le poids en avant au lieu de droit vers le haut, ce qui peut causer des douleurs à l’épaule."]', true, '["Stand with feet shoulder-width apart and engage your core to maintain a stable base", "Hold the dumbbell in your right hand at shoulder level with palm facing forward and elbow positioned directly under the weight", "Keep your left hand on your hip or extended out to the side for balance", "Press the dumbbell straight up overhead in a controlled motion until your arm is fully extended", "Slowly lower the weight back down to shoulder level, maintaining control throughout the descent", "Complete all repetitions on the right arm before switching to the left"]', '["Tiens-toi debout, les pieds écartés à la largeur des épaules, et engage ton core pour avoir une base stable.", "Tiens l''haltère dans ta main droite au niveau de l''épaule, paume vers l''avant et coude sous le poids.", "Place ta main gauche sur la hanche ou tends-la sur le côté pour t''aider à garder l''équilibre.", "Pousse l''haltère directement au-dessus de ta tête de manière contrôlée jusqu''à ce que ton bras soit complètement tendu.", "Redescends lentement le poids à la hauteur de l''épaule, en gardant le contrôle pendant toute la descente.", "Fais toutes les répétitions avec le bras droit avant de passer au gauche."]', '["Garde ton core engagé tout au long du mouvement pour éviter de cambrer le dos.", "Pousse le poids directement vers le haut plutôt qu''en avant pour éviter les problèmes d’épaule.", "Maintiens une position neutre de ton poignet et évite que l''haltère ne bascule.", "Choisis un poids qui te permet de garder une bonne forme pour toutes les répétitions.", "Évite de verrouiller agressivement ton coude en haut du mouvement."]', '["Keep your core engaged throughout the movement to prevent arching your back", "Press the weight straight up rather than forward to avoid shoulder impingement", "Maintain a neutral wrist position and avoid letting the dumbbell tilt", "Use a weight that allows you to maintain proper form for all repetitions", "Avoid locking out your elbow aggressively at the top of the movement"]', 'e8aacdde-8fce-438b-878b-3af1a611f2be', 'dumbbell-one-arm-shoulder-press-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('5312d9f5-5763-4194-8e27-147769107e9f', 'Power Snatch', NULL, 'سناج القوة', 'Power Snatch (ISSUE_ back on pick up a bit bend)', 'Bodyweight', '[]', 'Bodyweight', 'Advanced', 1, '/videos/bodyweight/power-snatch-issue-back-on-pick-up-a-bit-bend.mp4', NULL, NULL, NULL, '/videos/thumbnails/power-snatch-issue-back-on-pick-up-a-bit-bend.jpg', NULL, '["Gardez le dos droit tout au long du mouvement pour éviter les blessures lors de la phase de ramassage", "Concentrez-vous sur l''extension explosive des hanches plutôt que d''utiliser votre dos pour générer de la puissance", "Atterrissez avec les genoux fléchis et le poids bien réparti pour protéger vos articulations", "Maintenez l''engagement du tronc tout au long pour soutenir un bon alignement spinal", "Pratiquez le mouvement lentement d''abord avant d''ajouter de la vitesse explosive"]', '["Oublier de fléchir les genoux lors de l''atterrissage", "Se pencher en avant au lieu de garder le dos droit"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "barbell", "power snatch (issue_ back on pick up a bit bend)"]', true, '2026-04-03 12:24:58.424875+00', '2026-04-03 12:24:58.424875+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des hanches, bras le long du corps. Préparez-vous à simuler le mouvement explosif du snatch sans équipement. Exécution : Sautez explosivement tout en tirant vos bras vers le haut en un seul mouvement fluide, atterrissez doucement en position squat partiel avec les bras tendus au-dessus de la tête.', '["Oublier de fléchir les genoux lors de l''atterrissage", "Se pencher en avant au lieu de garder le dos droit"]', true, '["Begin in athletic stance with feet hip-width apart and slight bend in knees", "Initiate movement by explosively extending hips and knees while jumping upward", "Simultaneously pull arms up and overhead in one continuous motion", "Land softly on balls of feet with knees bent to absorb impact", "Finish with arms fully extended overhead and body in stable squat position", "Return to starting position by lowering arms and standing upright"]', '["Commencez en position athlétique, pieds à la largeur des hanches, genoux légèrement fléchis", "Initiez le mouvement en étendant explosivement les hanches et les genoux tout en sautant vers le haut", "Tirez simultanément les bras vers le haut et au-dessus de la tête en un mouvement continu", "Atterrissez doucement sur les pointes de pieds avec les genoux fléchis pour absorber l''impact", "Terminez avec les bras totalement étendus au-dessus de la tête et le corps en position squat stable", "Retournez à la position de départ en abaissant les bras et en vous redressant"]', '["Gardez le dos droit tout au long du mouvement pour éviter les blessures lors de la phase de ramassage", "Concentrez-vous sur l''extension explosive des hanches plutôt que d''utiliser votre dos pour générer de la puissance", "Atterrissez avec les genoux fléchis et le poids bien réparti pour protéger vos articulations", "Maintenez l''engagement du tronc tout au long pour soutenir un bon alignement spinal", "Pratiquez le mouvement lentement d''abord avant d''ajouter de la vitesse explosive"]', '["Keep back straight throughout the entire movement to prevent injury during the pickup phase", "Focus on explosive hip extension rather than using your back to generate power", "Land with knees bent and weight evenly distributed to protect joints", "Maintain core engagement throughout to support proper spinal alignment", "Practice the movement slowly first before adding explosive speed"]', '18b57d25-5597-4b00-8237-cc359e4609c8', 'power-snatch-issue-back-on-pick-up-a-bit-bend', NULL, NULL);
INSERT INTO public.exercises VALUES ('c122bfbf-aed6-4669-86e1-8854ed7685cc', 'Flexion des biceps sur banc preacher', NULL, NULL, 'Preacher Curl EZ-Bar', 'Biceps', '[]', 'Biceps', 'Intermediate', 1, '/videos/biceps/preacher-curl-ez-bar.mp4', NULL, NULL, NULL, '/videos/thumbnails/preacher-curl-ez-bar.jpg', NULL, '["Gardez vos poignets droits et alignés avec vos avant-bras tout au long du mouvement", "Ne verrouillez jamais vos coudes en position basse pour éviter les blessures par hyperextension", "Concentrez-vous sur la phase négative du mouvement en contrôlant le poids lors de la descente", "Évitez de soulever vos épaules ou de vous pencher en arrière pendant le curl pour maintenir une bonne forme", "Commencez avec un poids plus léger que pour les curls barbell classiques car la position preacher offre moins d''avantages mécaniques"]', '["Utiliser un poids trop lourd", "Ne pas contrôler la descente du poids"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "barbell", "preacher curl ez-bar"]', true, '2026-04-03 12:24:58.442053+00', '2026-04-03 12:24:58.442053+00', 'Position de départ : Assoyez-vous sur le banc preacher avec une EZ-bar en main, les bras reposant sur le coussin. Exécution : Fléchissez vos coudes pour soulever l''EZ-bar vers vos épaules, puis abaissez-la de manière contrôlée.', '["Utiliser un poids trop lourd", "Ne pas contrôler la descente du poids"]', true, '["Adjust the preacher bench height so the pad sits comfortably under your armpits when seated", "Grip the EZ-bar with an underhand grip, hands positioned on the angled portions for wrist comfort", "Press your chest firmly against the pad and plant your feet flat on the floor for stability", "Begin with arms extended but maintain a slight bend in your elbows to protect the joint", "Curl the weight up smoothly by squeezing your biceps, avoiding any swinging or momentum", "Lower the weight slowly and under control, taking twice as long to lower as you did to lift"]', '["Ajustez la hauteur du banc preacher pour que le coussin soit confortable sous vos aisselles lorsque vous êtes assis", "Prenez l''EZ-bar avec une prise en supination, mains posées sur les parties inclinées pour le confort des poignets", "Appuyez fermement votre poitrine contre le coussin et plantez vos pieds à plat au sol pour la stabilité", "Commencez avec les bras tendus mais gardez une légère flexion des coudes pour protéger vos articulations", "Soulevez le poids en contractant vos biceps, sans utilisez d''élan ou de balancement", "Abaissez le poids lentement et avec contrôle, prenant deux fois plus de temps pour baisser que pour soulever"]', '["Gardez vos poignets droits et alignés avec vos avant-bras tout au long du mouvement", "Ne verrouillez jamais vos coudes en position basse pour éviter les blessures par hyperextension", "Concentrez-vous sur la phase négative du mouvement en contrôlant le poids lors de la descente", "Évitez de soulever vos épaules ou de vous pencher en arrière pendant le curl pour maintenir une bonne forme", "Commencez avec un poids plus léger que pour les curls barbell classiques car la position preacher offre moins d''avantages mécaniques"]', '["Keep your wrists straight and aligned with your forearms throughout the entire movement", "Never fully lock out your elbows at the bottom position to prevent hyperextension injury", "Focus on the negative portion of the lift by controlling the weight as you lower it", "Avoid lifting your shoulders or leaning back during the curl to maintain proper form", "Start with lighter weight than regular barbell curls since the preacher position provides less mechanical advantage"]', '34d8d81b-5883-4a90-bc74-4f1ec0cbce91', 'preacher-curl-ez-bar', NULL, NULL);
INSERT INTO public.exercises VALUES ('c978a0e5-eaff-4890-b649-10a741e8921c', 'Halo avec haltère (gauche)', NULL, 'Halo b l''haltère (l)', 'Halo with dumbbell (L)', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/halo-with-dumbbell-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/halo-with-dumbbell-l.jpg', NULL, '["Commence avec un poids léger pour maîtriser le mouvement et éviter les blessures", "Garde la tête neutre et ne suis pas le poids avec tes yeux", "Maintiens le contrôle tout au long de l''exercice - ne laisse pas l''élan prendre le relais", "Reste bien gainé pour protéger ton bas du dos pendant le mouvement de l''haltère autour de ta tête", "Stoppe immédiatement si tu ressens un quelconque inconfort au niveau du cou ou des épaules pendant l''exercice"]', '["Ne pas stabiliser le tronc, ce qui peut entraîner des douleurs lombaires", "Laisser l''haltère tirer la tête en arrière, tu dois garder le contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "halo with dumbbell (l)"]', true, '2026-04-03 12:24:57.022087+00', '2026-04-03 12:24:57.022087+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des épaules, un haltère tenu avec les deux mains à hauteur de poitrine, bras tendus devant toi. Exécution : Fais tourner l''haltère en cercle autour de ta tête vers la gauche, en le passant derrière ta tête et en revenant à la position de départ.', '["Ne pas stabiliser le tronc, ce qui peut entraîner des douleurs lombaires", "Laisser l''haltère tirer la tête en arrière, tu dois garder le contrôle"]', true, '["Hold the dumbbell securely with both hands using an overhand grip", "Keep your core engaged and maintain an upright posture throughout the movement", "Slowly move the dumbbell to your left side, then behind your head in a smooth circular motion", "Control the weight as you bring it around to complete the circle back to the starting position", "Maintain tension in your shoulders and avoid letting the weight pull you off balance", "Complete all repetitions in the left direction before switching to the right if desired"]', '["Saisis fermement l''haltère avec les deux mains en prise pronation", "Garde les abdominaux engagés et une posture droite durant le mouvement", "Déplace lentement l''haltère vers ta gauche, puis derrière ta tête dans un mouvement circulaire fluide", "Contrôle le poids en le ramenant autour pour terminer le cercle de retour à la position de départ", "Maintiens la tension dans tes épaules et évite de perdre l''équilibre sous le poids", "Complète toutes les répétitions à gauche avant de passer à droite si tu le souhaites"]', '["Commence avec un poids léger pour maîtriser le mouvement et éviter les blessures", "Garde la tête neutre et ne suis pas le poids avec tes yeux", "Maintiens le contrôle tout au long de l''exercice - ne laisse pas l''élan prendre le relais", "Reste bien gainé pour protéger ton bas du dos pendant le mouvement de l''haltère autour de ta tête", "Stoppe immédiatement si tu ressens un quelconque inconfort au niveau du cou ou des épaules pendant l''exercice"]', '["Start with a lighter weight to master the movement pattern and avoid injury", "Keep your head in a neutral position and avoid following the weight with your eyes", "Maintain control throughout the entire range of motion - never let momentum take over", "Keep your core tight to protect your lower back as you move the weight around your head", "Stop immediately if you feel any neck or shoulder discomfort during the exercise"]', 'a07157e6-32c0-4380-ad71-55afc02369ec', 'halo-with-dumbbell-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('94c76cbf-c4cb-4d42-8245-5616447e3d07', 'Posture du Chiot', NULL, 'وضعية الجرو', 'Puppy pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/puppy-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/puppy-pose.jpg', NULL, '["Maintiens tes bras actifs et écartés à la largeur des épaules.", "Ne laisse pas tes coudes toucher le sol.", "Inspire profondément et sens l''étirement dans ta poitrine et tes épaules."]', '["Ne pas garder les hanches alignées avec les genoux.", "Laisser les coudes toucher le sol."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "puppy pose"]', true, '2026-04-03 12:24:58.472438+00', '2026-04-03 12:24:58.472438+00', 'Renforce ton dos en étirant ta poitrine et tes épaules avec la posture du chiot. Une excellente ouverture qui t''apporte souplesse et sérénité !', '["Ne pas garder les hanches alignées avec les genoux.", "Laisser les coudes toucher le sol."]', true, '["Start on all fours with hips stacked over knees.", "Walk your hands forward, lowering your chest toward the floor.", "Keep your hips over your knees.", "Rest your forehead on the mat and melt your chest down."]', '["Mets-toi à quatre pattes, les hanches au-dessus des genoux.", "Avance tes mains pour abaisser ta poitrine vers le sol.", "Garde les hanches bien alignées au-dessus des genoux.", "Pose ton front sur le sol et laisse tomber ta poitrine."]', '["Maintiens tes bras actifs et écartés à la largeur des épaules.", "Ne laisse pas tes coudes toucher le sol.", "Inspire profondément et sens l''étirement dans ta poitrine et tes épaules."]', '["Keep your arms active and shoulder-width apart.", "Do not let your elbows touch the floor.", "Breathe into the stretch across your chest and shoulders."]', '874ef2ee-909f-44db-bd03-25ffd1e24a0d', 'puppy-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('d9093987-d352-42ef-b0ff-7e0a5baf439e', 'Cuban Press', NULL, 'Cuban Press', 'Cuban Press', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 2, '/videos/shoulders/cuban-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/cuban-press.jpg', NULL, '["Garde les épaules tirées vers l’arrière et vers le bas pendant tout le mouvement pour éviter les blessures", "Avance lentement et délibérément à chaque étape pour maximiser la stabilité des épaules", "Garde la colonne vertébrale neutre et évite d’arquer le dos en poussant au-dessus de ta tête", "Arrête immédiatement si tu ressens des douleurs aigües ou un inconfort au niveau de l''articulation de l''épaule", "Concentre-toi sur des transitions fluides entre chaque position au lieu de te précipiter dans le mouvement"]', '["Ne pas garder les épaules en place, ce qui peut entraîner une tension", "Pousser trop rapidement, ce qui peut diminuer l’efficacité de l’exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "cuban press"]', true, '2026-04-03 12:24:56.246756+00', '2026-04-03 12:24:56.246756+00', 'Position de départ : Tiens-toi bien droit, les pieds écartés à la largeur des épaules, les bras tendus sur les côtés à hauteur d''épaules, paumes vers le bas. Exécution : Fais pivoter tes bras vers le haut pour que les paumes soient tournées vers l’avant, puis pousse les bras au-dessus de ta tête. Redescends en contrôlant le mouvement, ramène les bras à la hauteur des épaules et tourne les paumes vers le bas.', '["Ne pas garder les épaules en place, ce qui peut entraîner une tension", "Pousser trop rapidement, ce qui peut diminuer l’efficacité de l’exercice"]', true, '["Stand tall with core engaged and feet planted firmly on the ground", "Extend arms out to sides at shoulder height with palms facing down", "Slowly rotate your arms so palms face forward while keeping arms at shoulder level", "Press both arms straight up overhead while maintaining palm-forward position", "Lower arms back to shoulder height with controlled movement", "Rotate palms back to face down position to complete one repetition"]', '["Reste droit, engage ton core et plante bien tes pieds au sol", "Étends tes bras sur les côtés à hauteur d''épaules, paumes vers le bas", "Fais doucement pivoter tes bras pour que les paumes soient face à l’avant tout en gardant les bras à hauteur d''épaules", "Pousse les bras droit au-dessus de ta tête tout en gardant les paumes vers l’avant", "Redescends les bras à hauteur des épaules avec un mouvement contrôlé", "Fais pivoter les paumes vers le bas pour compléter une répétition"]', '["Garde les épaules tirées vers l’arrière et vers le bas pendant tout le mouvement pour éviter les blessures", "Avance lentement et délibérément à chaque étape pour maximiser la stabilité des épaules", "Garde la colonne vertébrale neutre et évite d’arquer le dos en poussant au-dessus de ta tête", "Arrête immédiatement si tu ressens des douleurs aigües ou un inconfort au niveau de l''articulation de l''épaule", "Concentre-toi sur des transitions fluides entre chaque position au lieu de te précipiter dans le mouvement"]', '["Keep shoulders pulled back and down throughout the entire movement to avoid impingement", "Move slowly and deliberately through each phase to maximize shoulder stability benefits", "Maintain neutral spine and avoid arching your back when pressing overhead", "Stop immediately if you feel any sharp pain or discomfort in the shoulder joint", "Focus on smooth transitions between each position rather than rushing through the movement"]', 'b3d44ba8-5fdd-4a7e-ace2-1b12d5901b0b', 'cuban-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('0708a048-b210-4c52-a259-ee74807417d5', 'Pompes au breakdancer', NULL, NULL, 'Push up to breakdancer', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/push-up-to-breakdancer.mp4', NULL, NULL, NULL, '/videos/thumbnails/push-up-to-breakdancer.jpg', NULL, '["Maîtrise d''abord les pompes standard avant d''essayer cette variante avancée", "Garde ton bras de support fort et verrouillé pendant la transition vers le breakdancer", "Engage ton tronc pendant tout le mouvement pour maintenir l''équilibre et le contrôle", "Commence doucement et concentre-toi sur des transitions fluides plutôt que sur la vitesse", "Échauffe bien tes poignets, car cet exercice sollicite beaucoup les poignets"]', '["Ne pas maintenir une position de corps droite", "Ne pas contrôler la descente lors de la pompe"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "push up to breakdancer"]', true, '2026-04-03 12:24:58.496973+00', '2026-04-03 12:24:58.496973+00', 'Position de départ : Place-toi en position de pompe standard, mains légèrement plus larges que les épaules, corps bien droit de la tête aux talons. Exécution : Réalise une pompe en abaissant ta poitrine vers le sol, puis, en revenant vers le haut, transfère ton poids sur une main tout en levant l''autre main et en passant la jambe du même côté sous ton corps comme dans un mouvement de freeze de breakdance.', '["Ne pas maintenir une position de corps droite", "Ne pas contrôler la descente lors de la pompe"]', true, '["Start in a proper push-up position with core engaged and body aligned", "Lower your chest toward the ground in a controlled push-up motion", "Push back up explosively while preparing to shift your weight", "As you reach the top, shift your weight to your left hand and lift your right hand", "Sweep your right leg under your body while balancing on your left hand and right foot", "Return to starting push-up position and repeat on the opposite side"]', '["Adopte une position de pompe correcte avec les abdos contractés et le corps aligné", "Diminue ta poitrine vers le sol en contrôlant le mouvement de la pompe", "Remonte explosivement tout en te préparant à changer de poids", "En atteignant le sommet, déplace ton poids sur ta main gauche et lève ta main droite", "Fais passer ta jambe droite sous ton corps tout en te maintenant sur ta main gauche et ton pied droit", "Retourne à la position initiale de la pompe et répète de l''autre côté"]', '["Maîtrise d''abord les pompes standard avant d''essayer cette variante avancée", "Garde ton bras de support fort et verrouillé pendant la transition vers le breakdancer", "Engage ton tronc pendant tout le mouvement pour maintenir l''équilibre et le contrôle", "Commence doucement et concentre-toi sur des transitions fluides plutôt que sur la vitesse", "Échauffe bien tes poignets, car cet exercice sollicite beaucoup les poignets"]', '["Master standard push-ups before attempting this advanced variation", "Keep your supporting arm strong and locked during the breakdancer transition", "Engage your core throughout the entire movement to maintain balance and control", "Start slowly and focus on smooth transitions rather than speed", "Ensure adequate wrist warm-up as this exercise places significant stress on the supporting wrist"]', '1cecbe87-d29e-43af-bb44-5e1f409cd018', 'push-up-to-breakdancer', NULL, NULL);
INSERT INTO public.exercises VALUES ('b39dc3b9-e7b1-426d-986a-2a91fd05a1e1', 'Pompes Écartées', NULL, 'push-up wide', 'Push-Up Wide', 'Chest', '[]', 'Chest', 'Beginner', 16, '/videos/chest/push-up-wide.mp4', NULL, NULL, NULL, '/videos/thumbnails/push-up-wide.jpg', NULL, '["Accentue bien sur les pectoraux", "Évite de trop écarter les bras pour prévenir les douleurs aux épaules", "Garde ton corps bien droit", "Contrôle chaque mouvement", "Attention à la tension sur les épaules"]', '["Les coudes trop proches du corps", "Ne pas descendre suffisamment", "S''affaisser au niveau des hanches", "Rythme trop rapide"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "push-up wide"]', true, '2026-04-03 12:24:58.521076+00', '2026-04-03 12:24:58.521076+00', 'Travaille ton pectoral avec les pompes écartées. Cet exercice cible intensément la poitrine tout en renforçant ta force.', '["Les coudes trop proches du corps", "Ne pas descendre suffisamment", "S''affaisser au niveau des hanches", "Rythme trop rapide"]', true, '["Hands wider than shoulder-width", "Lower chest toward floor", "Elbows flare out more", "Push up to start"]', '["Positionne tes mains plus larges que les épaules", "Abaisse ta poitrine vers le sol", "Fais en sorte que tes coudes s''écartent davantage", "Repousse-toi vers le haut jusqu''à la position de départ"]', '["Accentue bien sur les pectoraux", "Évite de trop écarter les bras pour prévenir les douleurs aux épaules", "Garde ton corps bien droit", "Contrôle chaque mouvement", "Attention à la tension sur les épaules"]', '["More chest emphasis", "Don''t go too wide (shoulder strain)", "Keep body straight", "Control the movement", "Harder on shoulders"]', '67f7b774-4b0f-4252-b5df-2555e9f5d0c8', 'push-up-wide', NULL, NULL);
INSERT INTO public.exercises VALUES ('d3c80034-8efc-4f6a-a135-65ad2524e03e', 'Élévations Latérales au Câble', NULL, 'رفع جانبي بالكابل', 'Cable Lateral Raise', 'Shoulders', '[]', 'Shoulders', 'Beginner', 4, '/videos/shoulders/cable-lateral-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-lateral-raise.jpg', NULL, '["Gardez le torse droit et évitez de vous pencher loin de la machine pendant l''exercice", "Utilisez un tempo contrôlé, prenez 2-3 secondes pour élever et abaisser le poids", "Arrêtez-vous à la hauteur des épaules pour éviter l''impingement et maintenir la tension sur les deltoïdes", "Concentrez-vous sur l''utilisation de vos muscles d''épaule plutôt que sur le momentum ou votre dos", "Commencez avec un poids léger pour maîtriser la forme avant de passer à une résistance plus lourde"]', '["Pencher le torse en arrière", "Utiliser un poids trop lourd", "Oublier de engager le core avant l''exercice", "Lever les bras trop haut au-dessus des épaules", "Ne pas contrôler la descente du poids"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "cable", "cable lateral raise"]', true, '2026-04-03 12:24:55.933217+00', '2026-04-03 12:24:55.933217+00', 'Position de départ : Tenez-vous face à un poulie avec une poignée dans chaque main, bras tendus vers le bas. Execution : Levez les bras sur les côtés jusqu''à atteindre la hauteur des épaules, puis redescendez lentement.', '["Pencher le torse en arrière", "Utiliser un poids trop lourd", "Oublier de engager le core avant l''exercice", "Lever les bras trop haut au-dessus des épaules", "Ne pas contrôler la descente du poids"]', true, '["Set the cable pulley to the lowest position and attach a single handle", "Stand with your side to the machine, feet shoulder-width apart, and grasp the handle with your outside hand", "Keep a slight bend in your elbow and maintain good posture with your core engaged", "Raise your arm out to the side until it reaches shoulder height, leading with your pinky finger", "Hold briefly at the top, then slowly lower the weight back to the starting position"]', '["Réglez le poulie à la position la plus basse et attachez une seule poignée", "Tenez-vous de côté par rapport à la machine, les pieds à la largeur des épaules, en saisissant la poignée avec votre main extérieure", "Gardez un léger pli au coude et maintenez une bonne posture avec le gainage du corps", "Élevez votre bras sur le côté jusqu''à la hauteur des épaules, en menant avec le doigt auriculaire", "Maintenez brièvement en haut, puis redescendez lentement à la position de départ"]', '["Gardez le torse droit et évitez de vous pencher loin de la machine pendant l''exercice", "Utilisez un tempo contrôlé, prenez 2-3 secondes pour élever et abaisser le poids", "Arrêtez-vous à la hauteur des épaules pour éviter l''impingement et maintenir la tension sur les deltoïdes", "Concentrez-vous sur l''utilisation de vos muscles d''épaule plutôt que sur le momentum ou votre dos", "Commencez avec un poids léger pour maîtriser la forme avant de passer à une résistance plus lourde"]', '["Keep your torso upright and avoid leaning away from the machine during the movement", "Use a controlled tempo, taking 2-3 seconds to raise and lower the weight", "Stop at shoulder height to avoid impingement and maintain tension on the deltoids", "Focus on lifting with your shoulder muscles rather than using momentum or your back", "Start with lighter weight to master the form before progressing to heavier resistance"]', 'a6a9ea7b-c868-4924-842a-9c3232698c3b', 'cable-lateral-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('10aa3ca7-092c-48ba-8f66-cb137b9cd3ff', 'Posture du pigeon allongé (côté droit)', NULL, 'شدة الحمامة مستلقية (الجانب الأيمن)', 'Reclined pigeon pose (right)', 'Glutes', '[]', 'Glutes', 'Beginner', 16, '/videos/glutes/reclined-pigeon-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/reclined-pigeon-pose-right.jpg', NULL, '["Garde la tête et les épaules au sol.", "Fléchis le pied croisé pour protéger le genou.", "Respire profondément pour intensifier l''étirement de la hanche."]', '["Ne pas garder la tête au sol, ce qui peut créer de la tension dans le cou.", "Négliger de fléchir le pied croisé et risquer de blesser le genou."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "reclined pigeon pose (right)"]', true, '2026-04-03 12:24:58.564895+00', '2026-04-03 12:24:58.564895+00', 'Renforce tes fessiers tout en assouplissant tes hanches.', '["Ne pas garder la tête au sol, ce qui peut créer de la tension dans le cou.", "Négliger de fléchir le pied croisé et risquer de blesser le genou."]', true, '["Lie on your back with knees bent and feet flat.", "Cross one ankle over the opposite knee.", "Thread your hands behind the supporting thigh.", "Gently pull the thigh toward your chest."]', '["Allonge-toi sur le dos, genoux fléchis et pieds à plat.", "Croise une cheville sur le genou opposé.", "Passe tes mains derrière la cuisse qui soutient.", "Tire doucement la cuisse vers ta poitrine."]', '["Garde la tête et les épaules au sol.", "Fléchis le pied croisé pour protéger le genou.", "Respire profondément pour intensifier l''étirement de la hanche."]', '["Keep your head and shoulders on the floor.", "Flex the crossed foot to protect the knee.", "Breathe deeply into the hip stretch."]', '6810be7c-d51f-42d4-8685-4866fc3828e1', 'reclined-pigeon-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('a198a278-faba-4924-9509-843c78a50b1b', 'Fente Arrière avec Montée de Genou', NULL, NULL, 'Reverse Lunge into Knee Drive', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/reverse-lunge-into-knee-drive.mp4', NULL, NULL, NULL, '/videos/thumbnails/reverse-lunge-into-knee-drive.jpg', NULL, '["Garde ton torse droit tout au long du mouvement pour maintenir un bon alignement et maximiser l''activation des quadriceps", "Contrôle le tempo lors de la descente en fente et de la montée de genou pour améliorer l''équilibre et l''engagement musculaire", "Assure-toi que ton genou avant suit la ligne de tes orteils lors de la fente pour éviter les blessures au genou", "Concentre-toi sur la poussée à travers ton talon avant en revenant debout pour activer correctement les quadriceps", "Atterris en douceur en reculé dans la fente pour réduire l''impact sur tes articulations"]', '["Ne pas garder le torse droit pendant le mouvement", "Laisser le genou avant s''écraser vers l''intérieur lors de la fente"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "reverse lunge into knee drive"]', true, '2026-04-03 12:24:58.593259+00', '2026-04-03 12:24:58.593259+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, bras le long du corps ou mains sur les hanches. Exécution : Fais un pas en arrière en faisant une fente, puis tire ton genou arrière vers ta poitrine en revenant à la position debout, alterne les jambes ou fais toutes les répétitions d''un côté avant de changer.', '["Ne pas garder le torse droit pendant le mouvement", "Laisser le genou avant s''écraser vers l''intérieur lors de la fente"]', true, '["Stand with feet hip-width apart and engage your core for stability", "Step your right foot back 2-3 feet, lowering into a lunge until both knees are bent at 90 degrees", "Keep your front knee aligned over your ankle and avoid letting it cave inward", "Push through your front heel to stand up while simultaneously driving your back knee up toward your chest", "Control the knee drive movement and pause briefly at the top before returning to starting position", "Complete all repetitions on one side before switching legs, or alternate legs with each rep"]', '["Tiens-toi avec les pieds écartés à la largeur des hanches et engage ton core pour la stabilité", "Recule ton pied droit de 60 à 90 cm, abaisse-toi dans une fente jusqu''à ce que les deux genoux soient pliés à 90 degrés", "Veille à ce que ton genou avant soit aligné avec ta cheville et évite qu''il ne s''écroule vers l''intérieur", "Pousse à travers ton talon avant pour revenir debout tout en tirant ton genou arrière vers ta poitrine", "Contrôle bien le mouvement du genou et marque une pause en haut avant de revenir à la position de départ", "Complète toutes les répétitions d''un côté avant de changer de jambe, ou alterne les jambes à chaque répétition"]', '["Garde ton torse droit tout au long du mouvement pour maintenir un bon alignement et maximiser l''activation des quadriceps", "Contrôle le tempo lors de la descente en fente et de la montée de genou pour améliorer l''équilibre et l''engagement musculaire", "Assure-toi que ton genou avant suit la ligne de tes orteils lors de la fente pour éviter les blessures au genou", "Concentre-toi sur la poussée à travers ton talon avant en revenant debout pour activer correctement les quadriceps", "Atterris en douceur en reculé dans la fente pour réduire l''impact sur tes articulations"]', '["Keep your torso upright throughout the entire movement to maintain proper alignment and maximize quad activation", "Control the tempo on both the lunge descent and knee drive to improve balance and muscle engagement", "Ensure your front knee tracks in line with your toes during the lunge portion to prevent knee injury", "Focus on driving through your front heel when returning to standing to properly activate the quadriceps", "Land softly when stepping back into the lunge to reduce impact on your joints"]', '55df26c1-83f4-439a-89be-22c156a3e118', 'reverse-lunge-into-knee-drive', NULL, NULL);
INSERT INTO public.exercises VALUES ('11edec84-50aa-450c-b131-03659640414c', 'Guerrier Inversé (droite)', NULL, 'المحارب العكسي (اليمين)', 'Reverse warrior (right)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/reverse-warrior-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/reverse-warrior-right.jpg', NULL, '["Garde ton genou avant plié à 90 degrés.", "Ne transfère pas ton poids dans ta main arrière.", "Crée un long étirement sur le côté de ton corps."]', '["Ne pas plier suffisamment le genou avant.", "S''affaisser avec le dos au lieu de rester droit."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "reverse warrior (right)"]', true, '2026-04-03 12:24:58.617236+00', '2026-04-03 12:24:58.617236+00', 'Renforce tes quadriceps et ouvre ton corps avec cette posture bienfaisante.', '["Ne pas plier suffisamment le genou avant.", "S''affaisser avec le dos au lieu de rester droit."]', true, '["From Warrior II, flip your front palm up.", "Inhale and reach your front arm up and back overhead.", "Let your back hand slide down the back leg.", "Open your chest toward the ceiling."]', '["À partir de la pose Guerrier II, retourne ta paume avant vers le haut.", "Inspire et étire ton bras avant vers le haut et vers l''arrière.", "Laisse ta main arrière glisser le long de ta jambe arrière.", "Ouvre ta poitrine vers le plafond."]', '["Garde ton genou avant plié à 90 degrés.", "Ne transfère pas ton poids dans ta main arrière.", "Crée un long étirement sur le côté de ton corps."]', '["Keep your front knee bent at 90 degrees.", "Do not dump weight into the back hand.", "Create a long side-body stretch."]', '4fe0ae5d-b04a-437b-be8a-ce6636c08348', 'reverse-warrior-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('e1556618-17ff-4e81-b246-fde8361123b7', 'Élévation Frontale Couchée avec Barbell', NULL, NULL, 'Lying Barbell Front Raise', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 1, '/videos/shoulders/lying-barbell-front-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-barbell-front-raise.jpg', NULL, '["Engage bien ton ventre et garde le dos collé au banc pendant tout le mouvement", "Adopte un rythme contrôlé lors des phases de descente et de montée pour maximiser l’engagement musculaire", "Évite de verrouiller complètement les coudes en haut pour maintenir une tension constante sur les muscles", "Choisis un poids adapté qui te permet de conserver la bonne forme tout au long des répétitions", "Garde tes pieds bien ancrés au sol pour plus de stabilité durant l''exercice"]', '["Ne pas avoir le dos soutenu contre le banc, ce qui peut entraîner des blessures", "Utiliser un poids trop lourd, ce qui pose des difficultés pour maintenir une bonne technique"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "barbell", "lying barbell front raise"]', true, '2026-04-03 12:24:57.668384+00', '2026-04-03 12:24:57.668384+00', 'Position de départ : Installe-toi sur un banc incliné, ton dos bien soutenu, en tenant une barre avec les deux mains en prise pronation, bras tendus au-dessus de ta poitrine. Exécution : Fais descendre la barre de manière contrôlée en arc vers le haut de ta poitrine, puis pousse-la à nouveau vers le haut tout en maintenant l’inclinaison.', '["Ne pas avoir le dos soutenu contre le banc, ce qui peut entraîner des blessures", "Utiliser un poids trop lourd, ce qui pose des difficultés pour maintenir une bonne technique"]', true, '["Sit securely on an inclined bench with your back firmly pressed against the pad for support", "Grip the barbell with both hands using an overhand grip, hands positioned slightly wider than shoulder-width", "Start with arms extended upward above your chest, maintaining a slight bend in your elbows", "Lower the barbell slowly in a controlled arc motion toward your upper chest area", "Press the barbell back up to the starting position following the same arc path", "Maintain control throughout the entire range of motion, avoiding any bouncing or jerky movements"]', '["Assieds-toi solidement sur un banc incliné, le dos bien appuyé contre l’appuie-tête pour un bon soutien", "Saisis la barre avec les deux mains en prise pronation, les mains un peu plus larges que la largeur des épaules", "Commence avec les bras tendus au-dessus de ta poitrine, en gardant une légère flexion au niveau des coudes", "Descends la barre lentement en effectuant un mouvement contrôlé en arc vers le haut de ta poitrine", "Pousse la barre de nouveau vers le haut en suivant le même chemin en arc", "Maintiens le contrôle tout au long du mouvement, évite les rebonds ou les gestes brusques"]', '["Engage bien ton ventre et garde le dos collé au banc pendant tout le mouvement", "Adopte un rythme contrôlé lors des phases de descente et de montée pour maximiser l’engagement musculaire", "Évite de verrouiller complètement les coudes en haut pour maintenir une tension constante sur les muscles", "Choisis un poids adapté qui te permet de conserver la bonne forme tout au long des répétitions", "Garde tes pieds bien ancrés au sol pour plus de stabilité durant l''exercice"]', '["Keep your core engaged and back pressed firmly against the bench throughout the movement", "Maintain a controlled tempo on both the lowering and lifting phases to maximize muscle engagement", "Avoid locking out your elbows completely at the top to maintain constant tension on the muscles", "Choose an appropriate weight that allows you to maintain proper form throughout all repetitions", "Keep your feet planted firmly on the ground for additional stability during the exercise"]', '497b7319-b2dc-4886-8ced-fdf14a08bb97', 'lying-barbell-front-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('cb2529f7-bda6-40a4-b950-32066438f9b5', 'Élévation Latérale à la Machine', NULL, 'آلة رفع الجوانب', 'Machine Lateral Raise', 'Shoulders', '[]', 'Shoulders', 'Beginner', 8, '/videos/shoulders/machine-lateral-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/machine-lateral-raise.jpg', NULL, '["Gardez le torse droit et évitez de pencher en avant ou en arrière pendant le mouvement", "Arrêtez-vous à hauteur d''épaule pour éviter les douleurs et protéger l''articulation de l''épaule", "Utilisez un tempo contrôlé avec une phase de levée de 2 secondes et une phase de descente de 3 secondes", "Évitez de faire appel à l''élan ou de balancer le poids", "Commencez avec un poids léger pour maîtriser la forme avant d''augmenter la résistance"]', '["Incliner le torse durant le mouvement", "Utiliser trop de poids et compromettre la forme"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "machine lateral raise"]', true, '2026-04-03 12:24:57.768302+00', '2026-04-03 12:24:57.768302+00', 'Position de départ : Asseyez-vous sur la machine d’élévation latérale, les bras le long du corps et les mains sur les poignées. Exécution : Élevez vos bras sur les côtés jusqu’à ce qu’ils atteignent la hauteur des épaules, puis abaissez-les lentement.', '["Incliner le torse durant le mouvement", "Utiliser trop de poids et compromettre la forme"]', true, '["Adjust the seat height so your upper arms are parallel to the floor when holding the handles", "Position your back firmly against the backrest and engage your core", "Grasp the handles or position your arms under the padded levers with a neutral grip", "Lift your arms out to the sides in a smooth arc until they reach shoulder height", "Pause briefly at the top of the movement", "Lower the weight slowly and under control back to the starting position"]', '["Réglez la hauteur du siège pour que vos bras supérieurs soient parallèles au sol lorsque vous tenez les poignées", "Appuyez votre dos contre le dossier et engagez votre sangle abdominale", "Saisissez les poignées ou positionnez vos bras sous les leviers rembourrés avec une prise neutre", "Soulevez vos bras sur les côtés dans un arc fluide jusqu''à atteindre la hauteur des épaules", "Faites une pause brève en haut du mouvement", "Abaissez le poids lentement et avec contrôle jusqu''à la position de départ"]', '["Gardez le torse droit et évitez de pencher en avant ou en arrière pendant le mouvement", "Arrêtez-vous à hauteur d''épaule pour éviter les douleurs et protéger l''articulation de l''épaule", "Utilisez un tempo contrôlé avec une phase de levée de 2 secondes et une phase de descente de 3 secondes", "Évitez de faire appel à l''élan ou de balancer le poids", "Commencez avec un poids léger pour maîtriser la forme avant d''augmenter la résistance"]', '["Keep your torso upright and avoid leaning forward or backward during the movement", "Stop at shoulder height to prevent impingement and protect the shoulder joint", "Use a controlled tempo with a 2-second lift and 3-second lowering phase", "Avoid using momentum or swinging the weight up", "Start with lighter weight to master proper form before increasing resistance"]', '3ffba4ed-c3ae-4727-b5dc-31823f5d3358', 'machine-lateral-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('d35ed0b8-5f66-44ce-879e-911aa4426e7f', 'Twists Russes et Genoux Serrés', NULL, NULL, 'Russian twists into seated knee tucks', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/russian-twists-into-seated-knee-tucks.mp4', NULL, NULL, NULL, '/videos/thumbnails/russian-twists-into-seated-knee-tucks.jpg', NULL, '["Garde le dos droit tout au long du mouvement et évite d''arrondir les épaules vers l''avant", "Concentre-toi sur la rotation venant de ton ventre plutôt que de juste bouger les bras pour maximiser l''engagement abdominal", "Contrôle la vitesse du mouvement pour maintenir une bonne forme et éviter que l''élan prenne le dessus", "Respire régulièrement pendant l''exercice, expire pendant la phase la plus intense de chaque mouvement", "Si tu ressens une douleur dans le bas du dos, garde les pieds au sol pendant la partie twist russe."]', '["Arrondir le dos pendant l''exercice", "Ne pas engager suffisamment les muscles du tronc."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "russian twists into seated knee tucks"]', true, '2026-04-03 12:24:58.697345+00', '2026-04-03 12:24:58.697345+00', 'Position de départ : Assieds-toi au sol, jambes fléchies, pieds à plat, et penche-toi légèrement en arrière tout en gardant le dos droit et les abdos engagés. Execution : Fais pivoter ton torse d''un côté à l''autre, puis ramène tes genoux vers ta poitrine en te penchant un peu plus en arrière. Alterne entre ces deux mouvements dans un enchaînement fluide.', '["Arrondir le dos pendant l''exercice", "Ne pas engager suffisamment les muscles du tronc."]', true, '["Sit with knees bent and feet flat, leaning back to about 45 degrees while maintaining a straight spine", "Engage your core and lift your feet slightly off the ground for added challenge", "Rotate your torso to the right, then center, then left to complete one Russian twist", "After completing the twist, lean back further and pull your knees toward your chest while keeping your core tight", "Lower your feet back down and return to the starting position", "Continue alternating between Russian twists and knee tucks in a controlled rhythm"]', '["Assieds-toi avec les genoux fléchis et les pieds à plat, penche-toi à environ 45 degrés tout en gardant le dos droit", "Engage tes abdos et lève légèrement les pieds du sol pour plus de défi", "Fais pivoter ton torse vers la droite, puis reviens au centre, puis vers la gauche pour compléter un twist russe", "Après le twist, penche-toi en arrière et tire tes genoux vers ta poitrine tout en gardant ton ventre contracté", "Abaisse tes pieds et reviens à la position de départ", "Alterne entre les twists russes et les genoux serrés en gardant un rythme contrôlé."]', '["Garde le dos droit tout au long du mouvement et évite d''arrondir les épaules vers l''avant", "Concentre-toi sur la rotation venant de ton ventre plutôt que de juste bouger les bras pour maximiser l''engagement abdominal", "Contrôle la vitesse du mouvement pour maintenir une bonne forme et éviter que l''élan prenne le dessus", "Respire régulièrement pendant l''exercice, expire pendant la phase la plus intense de chaque mouvement", "Si tu ressens une douleur dans le bas du dos, garde les pieds au sol pendant la partie twist russe."]', '["Keep your back straight throughout the movement and avoid rounding your shoulders forward", "Focus on rotating from your core rather than just moving your arms to maximize abdominal engagement", "Control the movement speed to maintain proper form and prevent momentum from taking over", "Breathe steadily throughout the exercise, exhaling during the most challenging part of each movement", "If you experience lower back discomfort, keep your feet on the ground during the Russian twist portion"]', 'a5eb6aec-09a0-428e-a5c1-13a0897416a4', 'russian-twists-into-seated-knee-tucks', NULL, NULL);
INSERT INTO public.exercises VALUES ('8b310b64-f028-4171-80b8-1c397e1772bf', 'Crunch couché coude-genou', NULL, NULL, 'Lying elbow to knee crunch', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/lying-elbow-to-knee-crunch.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-elbow-to-knee-crunch.jpg', NULL, '["Garde toujours le bas de ton dos bien collé au sol pendant l''exercice", "Ne tire pas sur ton cou avec les mains - laisse tes muscles du core faire le travail", "Concentre-toi sur le mouvement de l''amener coude vers genou, plutôt que l''inverse", "Respire régulièrement et ne retiens pas ta respiration pendant l''exercice", "Maintiens ton ventre engagé même en revenant à la position de départ entre les répétitions"]', '["Le bas du dos qui se soulève du sol", "Tirer sur le cou au lieu de travailler le core", "Ne pas contrôler le mouvement lors de l''alternance des côtés", "Retenir sa respiration pendant l''exercice", "S''écrouler en revenant à la position de départ sans engager le core"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "lying elbow to knee crunch"]', true, '2026-04-03 12:24:57.699401+00', '2026-04-03 12:24:57.699401+00', 'Allonge-toi sur le dos, les mains derrière la tête, les genoux pliés à 90 degrés, les pieds décollés du sol. C''est parti pour muscler ton core !', '["Le bas du dos qui se soulève du sol", "Tirer sur le cou au lieu de travailler le core", "Ne pas contrôler le mouvement lors de l''alternance des côtés", "Retenir sa respiration pendant l''exercice", "S''écrouler en revenant à la position de départ sans engager le core"]', true, '["Lie flat on your back with your lower back pressed into the floor", "Place your hands lightly behind your head without interlocking fingers", "Lift your feet off the ground with knees bent at 90 degrees", "Contract your core and lift your shoulder blades off the floor while bringing your right elbow toward your left knee", "Return to starting position and repeat on the opposite side, bringing left elbow toward right knee", "Continue alternating sides while maintaining controlled movement throughout"]', '["Allonge-toi bien à plat sur le dos, en pressant le bas de ton dos contre le sol", "Place tes mains délicatement derrière ta tête sans entrelacer les doigts", "Lève tes pieds du sol en gardant les genoux pliés à 90 degrés", "Contracte ton ventre et lève tes homoplates du sol tout en amenant ton coude droit vers ton genou gauche", "Reviens à la position de départ et fais de même de l''autre côté, avec le coude gauche vers le genou droit", "Alterne les côtés en contrôlant bien chaque mouvement"]', '["Garde toujours le bas de ton dos bien collé au sol pendant l''exercice", "Ne tire pas sur ton cou avec les mains - laisse tes muscles du core faire le travail", "Concentre-toi sur le mouvement de l''amener coude vers genou, plutôt que l''inverse", "Respire régulièrement et ne retiens pas ta respiration pendant l''exercice", "Maintiens ton ventre engagé même en revenant à la position de départ entre les répétitions"]', '["Keep your lower back pressed against the floor throughout the entire movement", "Avoid pulling on your neck with your hands - let your core muscles do the work", "Focus on bringing your elbow toward your knee rather than your knee toward your elbow", "Maintain steady breathing and avoid holding your breath during the exercise", "Keep your core engaged even when returning to the starting position between reps"]', '3e840d86-0fd5-4ac2-b152-2bcc8ecc67c3', 'lying-elbow-to-knee-crunch', NULL, NULL);
INSERT INTO public.exercises VALUES ('8444e6de-4a90-4070-b2a7-51c0f671e202', 'Écarteurs assis à la machine câblée', NULL, 'تمارين الإكـتــار مــع جـهاز الخيوط', 'Seated Cable Fly', 'Chest', '[]', 'Chest', 'Beginner', 4, '/videos/chest/seated-cable-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-cable-fly.jpg', NULL, '["Garde une légère flexion au niveau des coudes pendant tout le mouvement pour protéger tes articulations", "Maintiens une bonne posture avec la poitrine en avant et les épaules en arrière pendant l''exercice", "Contrôle les deux phases du mouvement - évite que le poids ne rebondisse", "Concentre-toi sur l''étirement de tes muscles pectoraux lorsque tes bras sont étendus largement", "Utilise un poids qui te permet de garder une forme correcte tout au long des répétitions"]', '["Étirer les bras trop largement sans contrôle", "Ne pas contracter les muscles pectoraux au sommet du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "cable", "seated cable fly"]', true, '2026-04-03 12:24:58.756994+00', '2026-04-03 12:24:58.756994+00', 'Position de départ : Assieds-toi droit sur un banc ou une chaise entre deux machines à câbles, les poignées des câbles maintenues avec les bras étendus sur le côté à hauteur de poitrine. Exécution : Ramène tes bras vers l''avant en décrivant un arc contrôlé, en croisant les câbles devant ta poitrine, puis retourne lentement à la position de départ avec les bras étendus sur le côté.', '["Étirer les bras trop largement sans contrôle", "Ne pas contracter les muscles pectoraux au sommet du mouvement"]', true, '["Set up between two cable machines with handles positioned at chest height", "Sit with your back straight and feet firmly planted on the ground", "Grasp the cable handles with arms extended out to your sides, maintaining a slight bend in your elbows", "Bring your arms forward in a smooth arc motion, crossing the cables in front of your chest", "Squeeze your chest muscles at the peak contraction when your hands meet", "Slowly return to the starting position, controlling the weight as your arms extend back out to your sides"]', '["Installe-toi entre deux machines à câbles avec les poignées à hauteur de poitrine", "Assois-toi avec le dos droit et les pieds bien ancrés au sol", "Saisis les poignées des câbles avec les bras étendus sur le côté, en gardant une légère flexion au niveau des coudes", "Ramène tes bras vers l''avant en un mouvement fluide, en croisant les câbles devant ta poitrine", "Presse tes muscles pectoraux au sommet de la contraction lorsque tes mains se rejoignent", "Retourne lentement à la position de départ, en contrôlant le poids lorsque tes bras s''étendent à nouveau sur les côtés"]', '["Garde une légère flexion au niveau des coudes pendant tout le mouvement pour protéger tes articulations", "Maintiens une bonne posture avec la poitrine en avant et les épaules en arrière pendant l''exercice", "Contrôle les deux phases du mouvement - évite que le poids ne rebondisse", "Concentre-toi sur l''étirement de tes muscles pectoraux lorsque tes bras sont étendus largement", "Utilise un poids qui te permet de garder une forme correcte tout au long des répétitions"]', '["Keep a slight bend in your elbows throughout the entire movement to protect your joints", "Maintain good posture with your chest up and shoulders back during the exercise", "Control both the positive and negative portions of the movement - avoid letting the weight snap back", "Focus on feeling the stretch in your chest muscles when your arms are extended wide", "Use a weight that allows you to maintain proper form throughout all repetitions"]', '185e82b2-9e20-4021-aa84-65c564aca016', 'seated-cable-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('3e1ca61e-89b4-452d-8804-e7b0f6ec1b42', 'Élévation de mollets assis', NULL, 'رفع الساقين من وضعية الجلوس', 'Seated Calf Raise Machine', 'Calves', '[]', 'Calves', 'Beginner', 8, '/videos/calves/seated-calf-raise-machine.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-calf-raise-machine.jpg', NULL, '["Garde ton core engagé et adopte une posture droite pour éviter de cambrer le dos.", "Vise un rythme contrôlé : 2 secondes en haut avec une pause, puis 3 secondes pour redescendre afin d''activer au maximum le muscle.", "Assure-toi de faire le plein mouvement, en soulevant au maximum et en descendant jusqu''à sentir une étirement dans les mollets.", "Évite de rebondir en bas du mouvement, cela pourrait réduire l''efficacité et augmenter le risque de blessure.", "Maintiens tes genoux alignés avec tes orteils, sans laisser ceux-ci s''affaisser vers l''intérieur."]', '["Ne pas ajuster le coussin de cuisse correctement.", "Rebondir en bas au lieu de contrôler le mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["calves", "machine", "seated calf raise machine"]', true, '2026-04-03 12:24:58.787016+00', '2026-04-03 12:24:58.787016+00', 'Position de départ : Assieds-toi sur la machine à élévation de mollets, les pieds sur la plateforme et les genoux pliés. Exécution : Soulève les talons en contractant les mollets, puis abaisse-les lentement jusqu''à la position de départ.', '["Ne pas ajuster le coussin de cuisse correctement.", "Rebondir en bas au lieu de contrôler le mouvement."]', true, '["Adjust the thigh pad so it sits comfortably across your lower thighs, just above your knees", "Place the balls of your feet on the footplate with your feet hip-width apart and parallel", "Release the weight by lifting your heels slightly and moving the release handle if applicable", "Press up through the balls of your feet to raise your heels as high as possible, squeezing your calves at the top", "Lower your heels slowly below the starting position to feel a stretch in your calves", "Complete all repetitions before carefully re-engaging the safety handle"]', '["Régle le coussin de cuisse pour qu''il soit confortable au-dessus de tes genoux.", "Place les avant-pieds sur la plateforme, les pieds à la largeur des hanches et parallèles.", "Libère le poids en soulevant légèrement tes talons et en tirant la poignée de déverrouillage si nécessaire.", "Pousse à travers les avant-pieds pour soulever tes talons le plus haut possible, contractant tes mollets au sommet.", "Abaisse lentement tes talons en dessous de la position de départ pour bien étirer tes mollets.", "Termine toutes les répétitions avant de remettre en place la poignée de sécurité."]', '["Garde ton core engagé et adopte une posture droite pour éviter de cambrer le dos.", "Vise un rythme contrôlé : 2 secondes en haut avec une pause, puis 3 secondes pour redescendre afin d''activer au maximum le muscle.", "Assure-toi de faire le plein mouvement, en soulevant au maximum et en descendant jusqu''à sentir une étirement dans les mollets.", "Évite de rebondir en bas du mouvement, cela pourrait réduire l''efficacité et augmenter le risque de blessure.", "Maintiens tes genoux alignés avec tes orteils, sans laisser ceux-ci s''affaisser vers l''intérieur."]', '["Keep your core engaged and maintain an upright posture throughout the movement to prevent your back from rounding", "Focus on a slow, controlled tempo with a 2-second pause at the top and 3-second lowering phase for maximum muscle activation", "Ensure full range of motion by lifting as high as possible and lowering until you feel a stretch in your calves", "Avoid bouncing at the bottom of the movement as this can reduce effectiveness and increase injury risk", "Keep your knees aligned with your toes and avoid letting them cave inward during the exercise"]', '86e3a801-0f1c-4424-851f-4826c75d8f48', 'seated-calf-raise-machine', NULL, NULL);
INSERT INTO public.exercises VALUES ('29b20238-065b-4e57-85c3-674d7749ad40', 'Développe tes épaules avec le Seated Dumbbell Press', NULL, 'ضغط الأكتاف بالدمبل جالس', 'Seated Dumbbell Press', 'Shoulders', '[]', 'Shoulders', 'Beginner', 2, '/videos/shoulders/seated-dumbbell-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-dumbbell-press.jpg', NULL, '["Garde ton ventre serré, dos bien plaqué contre le dossier", "Évite de cogner les haltères en haut du mouvement", "Utilise l''amplitude complète du mouvement", "Contrôle bien la descente", "Ne cambre pas le dos de manière excessive"]', '["Ne pas bien stabiliser le tronc", "Trop de vitesse dans le mouvement", "Mal positionner les épaules", "Ne pas respecter l''amplitude"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "seated dumbbell press"]', true, '2026-04-03 12:24:58.808706+00', '2026-04-03 12:24:58.808706+00', 'Travaille tes épaules avec cet exercice puissant pour construire force et muscle. Prêt à te dépasser ?', '["Ne pas bien stabiliser le tronc", "Trop de vitesse dans le mouvement", "Mal positionner les épaules", "Ne pas respecter l''amplitude"]', true, '["Sit on bench with back support", "Hold dumbbells at shoulder height, palms forward", "Press straight up until arms extended", "Lower with control to shoulders"]', '["Installe-toi sur un banc avec un dossier", "Prends les haltères à hauteur des épaules, paumes tournées vers l''avant", "Presse les haltères vers le haut jusqu''à ce que tes bras soient complètement tendus", "Redescends lentement jusqu''à la position de départ"]', '["Garde ton ventre serré, dos bien plaqué contre le dossier", "Évite de cogner les haltères en haut du mouvement", "Utilise l''amplitude complète du mouvement", "Contrôle bien la descente", "Ne cambre pas le dos de manière excessive"]', '["Keep core tight, back against pad", "Don''t clang dumbbells at top", "Full range of motion", "Control the negative", "Don''t arch back excessively"]', 'ec7c9b41-cfd7-414a-8fbe-8c46f0d3af78', 'seated-dumbbell-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('3bc6fe89-55f4-4ff5-8a81-01748815b06b', 'Élévation Latérale Unilatérale', NULL, 'رفع جانبي بيد واحدة', 'Single Arm Lateral Raise', 'Shoulders', '[]', 'Shoulders', 'Beginner', 2, '/videos/shoulders/single-arm-lateral-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-lateral-raise.jpg', NULL, '["Garde ton torse droit et évite de pencher de l''autre côté pendant l''élévation.", "Contrôle la phase de descente autant que la phase de montée pour maximiser l''engagement musculaire.", "Arrête-toi à hauteur d''épaule pour éviter les pincements et maintenir une bonne forme.", "Utilise un poids qui te permet de réaliser toutes les répétitions avec une technique parfaite.", "Évite d''utiliser tes jambes ou ton dos pour aider à soulever le poids en maintenant une position stable."]', '["Pencher le torse pendant l''élévation.", "Utiliser l''élan pour soulever le poids au lieu de se concentrer sur les muscles d''épaule."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "single arm lateral raise"]', true, '2026-04-03 12:24:59.191794+00', '2026-04-03 12:24:59.191794+00', 'Position de départ : Debout, un haltère dans une main, le bras tendu sur le côté. Exécution : Soulève l’haltère latéralement jusqu''à ce que ton bras soit parallèle au sol, puis redescends lentement à la position de départ. Répète avec l’autre bras.', '["Pencher le torse pendant l''élévation.", "Utiliser l''élan pour soulever le poids au lieu de se concentrer sur les muscles d''épaule."]', true, '["Stand tall with core engaged and hold the dumbbell with a firm grip at your side", "Keep your working arm slightly bent at the elbow throughout the entire movement", "Lift the weight out to the side using your shoulder muscles, not momentum", "Raise the dumbbell until your arm is parallel to the floor at shoulder height", "Pause briefly at the top position, then slowly lower the weight back down", "Complete all repetitions on one side before switching to the other arm"]', '["Tiens-toi bien droit, engage ton centre et saisis l''haltère fermement à ton côté.", "Garde ton bras de travail légèrement fléchi au niveau du coude tout au long du mouvement.", "Soulève le poids sur le côté en utilisant tes muscles d''épaule, pas en faisant appel à l''élan.", "Lève l''haltère jusqu''à l''horizontale, à la hauteur des épaules.", "Fais une pause brève en position haute, puis redescends lentement le poids.", "Achève toutes les répétitions d''un côté avant de passer à l''autre bras."]', '["Garde ton torse droit et évite de pencher de l''autre côté pendant l''élévation.", "Contrôle la phase de descente autant que la phase de montée pour maximiser l''engagement musculaire.", "Arrête-toi à hauteur d''épaule pour éviter les pincements et maintenir une bonne forme.", "Utilise un poids qui te permet de réaliser toutes les répétitions avec une technique parfaite.", "Évite d''utiliser tes jambes ou ton dos pour aider à soulever le poids en maintenant une position stable."]', '["Keep your torso upright and avoid leaning away from the working side during the lift", "Control the descent phase as much as the lifting phase to maximize muscle engagement", "Stop at shoulder height to avoid shoulder impingement and maintain proper form", "Use a weight that allows you to complete all repetitions with perfect technique", "Avoid using your legs or back to help lift the weight by maintaining a stable stance"]', 'e1b68bd8-a3aa-45db-8d6f-cc470738a85e', 'single-arm-lateral-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('2d95308e-410b-4e05-a91b-e5d801bb971a', 'Flexion avant assise', NULL, 'الانحناء للأمام جلوسا', 'Seated forward bend', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 16, '/videos/hamstrings/seated-forward-bend.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-forward-bend.jpg', NULL, '["Pivote des hanches, pas de la taille.", "Garde ta colonne vertébrale aussi longue que possible.", "Plie légèrement les genoux si tes ischio-jambiers sont tendus."]', '["Ne pas plier les hanches, ce qui rend l''exercice inefficace.", "Arrondir le dos au lieu de garder une bonne posture."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "bodyweight", "seated forward bend"]', true, '2026-04-03 12:24:58.84406+00', '2026-04-03 12:24:58.84406+00', 'Cet exercice cible les ischio-jambiers tout en améliorant la flexibilité de votre dos.', '["Ne pas plier les hanches, ce qui rend l''exercice inefficace.", "Arrondir le dos au lieu de garder une bonne posture."]', true, '["Sit with legs extended straight in front of you.", "Inhale and lengthen your spine.", "Exhale and fold forward from the hips, reaching for your feet.", "Hold your feet, ankles, or shins."]', '["Assieds-toi avec les jambes tendues devant toi.", "Inspire en allongeant ta colonne vertébrale.", "Expire et incline-toi vers l''avant à partir des hanches, en atteignant tes pieds.", "Tiens tes pieds, chevilles ou tibias."]', '["Pivote des hanches, pas de la taille.", "Garde ta colonne vertébrale aussi longue que possible.", "Plie légèrement les genoux si tes ischio-jambiers sont tendus."]', '["Hinge from the hips, not the waist.", "Keep your spine as long as possible.", "Bend your knees slightly if your hamstrings are tight."]', '6f54fafe-ff3f-4295-9ec6-031c1dd68e11', 'seated-forward-bend', NULL, NULL);
INSERT INTO public.exercises VALUES ('a2f2cd22-4e0a-4a2e-847e-8d4ca6530bbe', 'Machine à abduction des hanches assis', NULL, 'آلة فتح الوركين الجالسين', 'Seated Hip Abduction Machine', 'Glutes', '[]', 'Glutes', 'Beginner', 8, '/videos/glutes/seated-hip-abduction-machine.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-hip-abduction-machine.jpg', NULL, '["Maintenez votre sangle abdominale engagée et gardez une posture droite tout au long du mouvement pour éviter tout stress au bas du dos", "Concentrez-vous sur l''initiation du mouvement avec vos fessiers plutôt qu''en poussant simplement avec vos jambes", "Contrôlez la phase excentrique du mouvement en résistant au poids lorsque vos jambes reviennent vers le centre", "Évitez de rebondir en position basse ou d''utiliser l''élan pour réaliser les répétitions", "Commencez avec un poids léger pour maîtriser le mouvement avant de passer à des charges plus lourdes."]', '["Ne pas ajuster correctement la machine avant de commencer l''exercice", "Utiliser un poids trop lourd qui compromet la forme et le contrôle."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "machine", "seated hip abduction machine"]', true, '2026-04-03 12:24:58.88055+00', '2026-04-03 12:24:58.88055+00', 'Position de départ : Asseyez-vous sur la machine à abduction des hanches, les jambes légèrement fléchies et les genoux reposant sur les coussinets. Exécution : Poussez vos jambes vers l''extérieur contre la résistance, puis revenez lentement à la position initiale.', '["Ne pas ajuster correctement la machine avant de commencer l''exercice", "Utiliser un poids trop lourd qui compromet la forme et le contrôle."]', true, '["Adjust the seat height so your thighs are parallel to the floor and the pads rest comfortably above your knees", "Set an appropriate weight that allows you to maintain proper form throughout the entire range of motion", "Sit tall with your core engaged and grip the side handles lightly for stability", "Push your legs outward smoothly by squeezing your glutes, avoiding any jerky or explosive movements", "Hold the peak contraction for one second before slowly returning to the starting position", "Complete the full range of motion without letting the weight stack touch between repetitions"]', '["Ajustez la hauteur du siège pour que vos cuisses soient parallèles au sol et que les coussinets reposent confortablement au-dessus de vos genoux", "Définissez un poids approprié qui vous permet de maintenir la forme correcte tout au long de l''exercice", "Asseyez-vous droit, engagez votre sangle abdominale et agrippez légèrement les poignées latérales pour vous stabiliser", "Poussez vos jambes vers l''extérieur en serrant vos fessiers, évitez les mouvements brusques ou explosifs", "Maintenez la contraction maximale pendant une seconde avant de revenir lentement à la position de départ", "Effectuez l''amplitude complète sans laisser toucher les poids entre les répétitions."]', '["Maintenez votre sangle abdominale engagée et gardez une posture droite tout au long du mouvement pour éviter tout stress au bas du dos", "Concentrez-vous sur l''initiation du mouvement avec vos fessiers plutôt qu''en poussant simplement avec vos jambes", "Contrôlez la phase excentrique du mouvement en résistant au poids lorsque vos jambes reviennent vers le centre", "Évitez de rebondir en position basse ou d''utiliser l''élan pour réaliser les répétitions", "Commencez avec un poids léger pour maîtriser le mouvement avant de passer à des charges plus lourdes."]', '["Keep your core engaged and maintain an upright posture throughout the movement to prevent lower back strain", "Focus on initiating the movement with your glutes rather than just pushing with your legs", "Control the eccentric portion of the movement by resisting the weight as your legs return to center", "Avoid bouncing at the bottom position or using momentum to complete repetitions", "Start with lighter weight to master the movement pattern before progressing to heavier loads"]', '7532f005-9936-49c1-8612-132d874e1ee7', 'seated-hip-abduction-machine', NULL, NULL);
INSERT INTO public.exercises VALUES ('9f41b3d8-6e55-43b5-b9c1-fb03ad0468cc', 'Battements de jambes', NULL, NULL, 'Flutter kicks', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/flutter-kicks.mp4', NULL, NULL, NULL, '/videos/thumbnails/flutter-kicks.jpg', NULL, '["Effectue des mouvements petits et contrôlés", "Garde le bas du dos bien enfoncé", "Veille à garder les jambes tendues", "Respire tout au long de l''exercice", "Cible les abdos inférieurs"]', '["Le bas du dos se décolle du sol", "Les jambes ne sont pas droites", "Mouvements trop grands", "On retient sa respiration"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "flutter kicks"]', true, '2026-04-03 12:24:56.757977+00', '2026-04-03 12:24:56.757977+00', 'Position de départ : Allonge-toi sur le dos, les jambes tendues, les mains sous le bas du dos ou sur les côtés pour le soutien, et les épaules légèrement décollées du sol. Execution : Soulève et abaisse alternativement chaque jambe avec des mouvements rapides, en gardant le ventre bien engagé et en maintenant le mouvement de battement.', '["Le bas du dos se décolle du sol", "Les jambes ne sont pas droites", "Mouvements trop grands", "On retient sa respiration"]', true, '["Lie on back, hands under hips", "Legs straight, slightly off floor", "Kick legs up and down alternately", "Keep lower back pressed to floor"]', '["Allonge-toi sur le dos, mains sous les hanches", "Jambes droites, légèrement au-dessus du sol", "Bat les jambes de haut en bas alternativement", "Maintiens le bas du dos appuyé au sol"]', '["Effectue des mouvements petits et contrôlés", "Garde le bas du dos bien enfoncé", "Veille à garder les jambes tendues", "Respire tout au long de l''exercice", "Cible les abdos inférieurs"]', '["Small controlled movements", "Lower back stays down", "Keep legs straight", "Breathe throughout", "Targets lower abs"]', 'b867d101-cc16-42ff-a057-fe0de4a2d8c6', 'flutter-kicks', NULL, NULL);
INSERT INTO public.exercises VALUES ('09bfd0b9-5947-4e9c-9771-7727854d4f38', 'Alpinistes avec touches d''épaules', NULL, NULL, 'Mountain climbers into shoulder taps', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/mountain-climbers-into-shoulder-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/mountain-climbers-into-shoulder-taps.jpg', NULL, '["Garde tes hanches basses (ne te redresse pas)", "Maintiens ton abdo bien contracté", "Accélère pour augmenter la difficulté cardio", "Ralentis pour plus de contrôle", "Un exercice qui fait travailler tout le corps"]', '["Hanches trop hautes", "Oublier de contracter les abdos", "Ne pas changer les jambes assez rapidement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "mountain climbers into shoulder taps"]', true, '2026-04-03 12:24:57.829838+00', '2026-04-03 12:24:57.829838+00', 'Un exercice explosif pour renforcer ton tronc tout en améliorant ton équilibre et ta coordination.', '["Hanches trop hautes", "Oublier de contracter les abdos", "Ne pas changer les jambes assez rapidement"]', true, '["Start in push-up position", "Drive one knee toward chest", "Quickly switch legs", "Continue alternating at pace"]', '["Commence en position de pompe", "Ramène un genou vers ta poitrine", "Change rapidement de jambe", "Alterne sans interruption à un bon rythme"]', '["Garde tes hanches basses (ne te redresse pas)", "Maintiens ton abdo bien contracté", "Accélère pour augmenter la difficulté cardio", "Ralentis pour plus de contrôle", "Un exercice qui fait travailler tout le corps"]', '["Keep hips down (don''t pike)", "Core stays engaged", "Speed up for more cardio", "Slow down for more control", "Full body exercise"]', 'a5d77dca-e151-4f73-aadb-890366fe8abf', 'mountain-climbers-into-shoulder-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('0367571d-82bc-46c1-accc-d1b4d3d06e18', 'Burpees avec tapotement des épaules', NULL, 'بوربی مع نقر على الأكتاف', 'Shoulder tap burpees', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/shoulder-tap-burpees.mp4', NULL, NULL, NULL, '/videos/thumbnails/shoulder-tap-burpees.jpg', NULL, '["Maintiens ton abdomen contracté pendant tout le mouvement pour assurer la stabilité durant les tapotements des épaules", "Atterris doucement sur la pointe des pieds lors des sauts pour protéger tes articulations", "Garde une position de planche solide avec une ligne droite entre la tête et les talons pendant les tapotements des épaules", "Contrôle le mouvement des tapotements pour éviter la rotation des hanches et maintenir une bonne forme", "Modifie en marchant au lieu de sauter si nécessaire pour garder une technique correcte"]', '["Ne pas engager le core peut entraîner une mauvaise forme. Assure-toi que ton abdomen est tonique", "Des sauts trop brusques peuvent causer des douleurs articulaires. Veille à atterrir en douceur"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "shoulder tap burpees"]', true, '2026-04-03 12:24:58.972779+00', '2026-04-03 12:24:58.972779+00', 'Commence en te tenant droit, pieds écartés à la largeur des hanches. Effectue un burpee en t''accroupissant puis en sautant en arrière en position de planche. Ajoute un tapotement des épaules en touchant alternativement chaque épaule avec la main opposée, puis ramène tes pieds vers les mains et réalise un saut explosif avec les bras au-dessus de la tête.', '["Ne pas engager le core peut entraîner une mauvaise forme. Assure-toi que ton abdomen est tonique", "Des sauts trop brusques peuvent causer des douleurs articulaires. Veille à atterrir en douceur"]', true, '["Begin standing with feet hip-width apart and engage your core", "Squat down and place hands on the floor, then jump or step both feet back into a high plank position", "Maintain plank position while lifting right hand to tap left shoulder, then left hand to tap right shoulder", "Keep hips level and avoid rotating during shoulder taps", "Jump or step feet back toward hands and return to squat position", "Explosively jump up reaching arms overhead, then immediately begin next repetition"]', '["Commence debout, pieds écartés à la largeur des hanches et engage ton abdomen", "Accroupis-toi et pose tes mains au sol, puis saute ou marche les pieds en arrière en position de planche haute", "Maintiens la position de planche tout en levant ta main droite pour toucher ton épaule gauche, puis ta main gauche pour toucher ton épaule droite", "Garde les hanches stables et évite de pivoter pendant les tapotements des épaules", "Saute ou marche les pieds vers les mains et retourne en position accroupie", "Saute de façon explosive avec les bras au-dessus de la tête, puis enchaîne avec la répétition suivante"]', '["Maintiens ton abdomen contracté pendant tout le mouvement pour assurer la stabilité durant les tapotements des épaules", "Atterris doucement sur la pointe des pieds lors des sauts pour protéger tes articulations", "Garde une position de planche solide avec une ligne droite entre la tête et les talons pendant les tapotements des épaules", "Contrôle le mouvement des tapotements pour éviter la rotation des hanches et maintenir une bonne forme", "Modifie en marchant au lieu de sauter si nécessaire pour garder une technique correcte"]', '["Keep your core engaged throughout the entire movement to maintain stability during shoulder taps", "Land softly on the balls of your feet when jumping back and forward to protect your joints", "Maintain a strong plank position with straight line from head to heels during shoulder taps", "Control the shoulder tap movement to prevent hip rotation and maintain proper form", "Modify by stepping instead of jumping if needed to maintain proper technique"]', '2964f7d1-8a1f-45b6-887c-a084ceb75072', 'shoulder-tap-burpees', NULL, NULL);
INSERT INTO public.exercises VALUES ('7a256f22-560a-4dc6-aaca-2a9840a0640f', 'Position du Wild Thing (gauche)', NULL, 'وضيعة وايلد ثينغ (اليسار)', 'Wild thing pose (left)', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/wild-thing-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/wild-thing-pose-left.jpg', NULL, '["Maintenez votre bras de soutien fort.", "Ouvrez pleinement votre poitrine.", "Pressez fermement à travers vos deux pieds."]', '["Ne pas garder le bras de soutien stable.", "Ne pas ouvrir suffisamment la poitrine."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "wild thing pose (left)"]', true, '2026-04-03 12:24:59.945802+00', '2026-04-03 12:24:59.945802+00', 'Renforcez votre dos avec cet exercice dynamique qui ouvre votre cœur et libère votre énergie.', '["Ne pas garder le bras de soutien stable.", "Ne pas ouvrir suffisamment la poitrine."]', true, '["From Side Plank, step your top foot behind you.", "Press through your bottom hand and lift your hips.", "Reach your top arm overhead and open your chest toward the ceiling.", "Let your head drop back gently."]', '["À partir de la planche latérale, placez votre pied supérieur derrière vous.", "Poussez avec votre main au sol et levez vos hanches.", "Étendez votre bras supérieur au-dessus de votre tête et ouvrez votre poitrine vers le ciel.", "Laissez doucement votre tête tomber en arrière."]', '["Maintenez votre bras de soutien fort.", "Ouvrez pleinement votre poitrine.", "Pressez fermement à travers vos deux pieds."]', '["Keep your supporting arm strong.", "Open your chest fully.", "Press firmly through both feet."]', '65b90fab-d4d0-454e-8cf4-66a953ef982c', 'wild-thing-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('9ac039ec-306e-4523-94cb-3fa42e0cfd12', 'Flexion latérale avec haltère (main droite)', NULL, NULL, 'Dumbbell Side Bend (R)', 'Abs', '[]', 'Abs', 'Beginner', 2, '/videos/abs/dumbbell-side-bend-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-side-bend-r.jpg', NULL, '["Maintiens un mouvement contrôlé, évite l''élan ou le rebond", "Incline-toi uniquement sur le côté - évite de te tordre ou de te pencher en avant ou en arrière", "Garde une alignement neutre de la colonne vertébrale tout au long du mouvement", "Concentre-toi sur l''étirement et la contraction des muscles obliques plutôt que de simplement déplacer le poids", "Commence avec un poids léger pour maîtriser la technique avant d''augmenter la charge"]', '["Ne pas engager le tronc, ce qui provoque une mauvaise posture", "Incliner le torse trop en avant ou en arrière au lieu d''un mouvement latéral direct"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "dumbbell", "dumbbell side bend (r)"]', true, '2026-04-03 12:24:56.590084+00', '2026-04-03 12:24:56.590084+00', 'Position de départ : Tiens-toi bien droit, les pieds écartés à la largeur des hanches, un haltère dans la main droite et la main gauche sur la hanche ou derrière la tête. Exécution : Incline lentement ton torse vers la droite, abaisse l''haltère vers ton genou, puis reviens à la position de départ en contractant tes muscles obliques gauche.', '["Ne pas engager le tronc, ce qui provoque une mauvaise posture", "Incliner le torse trop en avant ou en arrière au lieu d''un mouvement latéral direct"]', true, '["Stand with feet hip-width apart and hold a dumbbell in your right hand at your side", "Place your left hand on your hip or behind your head for stability", "Keep your core engaged and maintain a straight back throughout the movement", "Slowly lean your torso to the right side, allowing the dumbbell to lower toward your right knee", "Focus on feeling the stretch in your left oblique muscles as you descend", "Contract your left obliques to return to the starting upright position"]', '["Tiens-toi debout, pieds écartés à la largeur des hanches, avec un haltère dans la main droite à côté de toi", "Place ta main gauche sur ta hanche ou derrière ta tête pour maintenir la stabilité", "Engage ton tronc et garde le dos droit pendant tout le mouvement", "Incline lentement ton torse vers la droite, en baissant l''haltère vers ton genou droit", "Concentre-toi sur l''étirement de tes muscles obliques gauches en descendant", "Contracte tes obliques gauches pour revenir à la position de départ, bien droit"]', '["Maintiens un mouvement contrôlé, évite l''élan ou le rebond", "Incline-toi uniquement sur le côté - évite de te tordre ou de te pencher en avant ou en arrière", "Garde une alignement neutre de la colonne vertébrale tout au long du mouvement", "Concentre-toi sur l''étirement et la contraction des muscles obliques plutôt que de simplement déplacer le poids", "Commence avec un poids léger pour maîtriser la technique avant d''augmenter la charge"]', '["Keep the movement controlled and avoid using momentum or bouncing", "Only lean directly to the side - avoid twisting or leaning forward or backward", "Maintain neutral spine alignment throughout the entire range of motion", "Focus on feeling the stretch and contraction in the oblique muscles rather than just moving the weight", "Start with lighter weight to master the form before progressing to heavier loads"]', '8dcb1591-348a-4809-9abf-0a1679a7a52a', 'dumbbell-side-bend-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('3d41ffe6-24ae-43be-9a3e-dffdead1e4ac', 'Planche latérale montée et descente (gauche)', NULL, NULL, 'Side plank up and down (left)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-plank-up-and-down-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-plank-up-and-down-left.jpg', NULL, '["Assure-toi que ton coude est toujours sous ton épaule pour protéger ton articulation", "Garde une ligne droite de la tête aux pieds : pas de descente ni de montée excessive des hanches", "Contrôle ta descente, évite de laisser tomber tes hanches brutalement", "Engage ton tronc et garde une respiration régulière, évite de bloquer ton souffle", "Focalise-toi sur l''utilisation de tes obliques pour soulever tes hanches, ne pousse pas avec tes jambes"]', '["Hanches qui s''affaissent ou s''élèvent trop", "Coude mal positionné, risquant des tensions aux épaules"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side plank up and down (left)"]', true, '2026-04-03 12:24:59.095259+00', '2026-04-03 12:24:59.095259+00', 'Adopte la position de départ en te couchant sur le côté gauche, ton avant-bras gauche fermement ancré au sol, le coude juste au-dessus de ton épaule. Ton corps doit former une ligne droite de la tête aux pieds. Prêt pour le défi ?', '["Hanches qui s''affaissent ou s''élèvent trop", "Coude mal positionné, risquant des tensions aux épaules"]', true, '["Lie on your left side with your left forearm planted firmly on the ground, elbow positioned directly under your shoulder", "Stack your right leg on top of your left leg and engage your core to lift your hips into a straight side plank position", "Keep your right hand on your hip or extended along your side for balance", "Slowly lower your hips down until they lightly touch the ground while maintaining control", "Immediately lift your hips back up to the starting side plank position using your core and oblique muscles", "Repeat the up and down movement for the desired number of repetitions"]', '["Allonge-toi sur le côté gauche, l''avant-bras fermement posé au sol, coude aligné sous l''épaule", "Empile ta jambe droite sur la jambe gauche et active ton abdominaux pour soulever tes hanches en position de planche latérale", "Garde ta main droite sur la hanche ou tendue le long de ton corps pour l''équilibre", "Descends lentement tes hanches jusqu''à toucher légèrement le sol tout en gardant le contrôle", "Ressens la puissance de ton tronc pour ramener tes hanches à la position initiale de planche latérale", "Répète ce mouvement de montée et descente pour le nombre de répétitions souhaité"]', '["Assure-toi que ton coude est toujours sous ton épaule pour protéger ton articulation", "Garde une ligne droite de la tête aux pieds : pas de descente ni de montée excessive des hanches", "Contrôle ta descente, évite de laisser tomber tes hanches brutalement", "Engage ton tronc et garde une respiration régulière, évite de bloquer ton souffle", "Focalise-toi sur l''utilisation de tes obliques pour soulever tes hanches, ne pousse pas avec tes jambes"]', '["Keep your supporting elbow directly under your shoulder throughout the entire movement to protect your shoulder joint", "Maintain a straight line from your head to your feet - avoid letting your hips sag or pike up", "Control the descent and avoid dropping your hips heavily to the ground", "Engage your core and breathe steadily throughout the movement rather than holding your breath", "Focus on using your obliques to lift your hips rather than pushing off with your legs"]', '8d5a28d5-9aa2-4d63-bdc4-3e6e746e9d0d', 'side-plank-up-and-down-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('6ba7ee63-246f-46b7-8e91-4bd918060498', 'Touches de orteils en planche', NULL, NULL, 'Plank toe touches', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-toe-touches.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-toe-touches.jpg', NULL, '["Restez fort en planche tout au long de l''exercice", "Privilégiez le contrôle plutôt que la vitesse pour maximiser l''engagement des abdos", "Maintenez vos hanches aussi stables que possible lors du mouvement genou-vers-coude", "Respirez régulièrement, ne retenez pas votre souffle pendant l''exercice", "Arrêtez-vous si vous ressentez une douleur dans le bas du dos et vérifiez votre posture"]', '["Hanches qui s''affaissent", "Mouvement trop rapide sans contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank toe touches"]', true, '2026-04-03 12:24:58.360657+00', '2026-04-03 12:24:58.360657+00', 'Position de départ : Mettez-vous en position de planche sur les avant-bras, le corps bien droit des pieds à la tête. Exécution : Tout en maintenant cette position, ramenez alternativement chaque genou vers le coude opposé avec contrôle.', '["Hanches qui s''affaissent", "Mouvement trop rapide sans contrôle"]', true, '["Start in a forearm plank with elbows directly under shoulders and body in a straight line", "Engage your core muscles and maintain neutral spine alignment", "Bring your right knee toward your left elbow while rotating your torso slightly", "Return to plank position with control, then bring left knee toward right elbow", "Continue alternating sides in a slow, controlled rhythm", "Keep hips level and avoid excessive rotation or sagging"]', '["Commencez en planche sur les avant-bras, les coudes sous les épaules, le corps droit", "Activez votre sangle abdominale et gardez le dos neutre", "Amenez votre genou droit vers votre coude gauche en tournant légèrement le torse", "Retournez en position de planche avec contrôle, puis amenez le genou gauche vers le coude droit", "Alternez de manière régulière et contrôlée", "Gardez vos hanches stables, sans trop de rotation ni affaissement"]', '["Restez fort en planche tout au long de l''exercice", "Privilégiez le contrôle plutôt que la vitesse pour maximiser l''engagement des abdos", "Maintenez vos hanches aussi stables que possible lors du mouvement genou-vers-coude", "Respirez régulièrement, ne retenez pas votre souffle pendant l''exercice", "Arrêtez-vous si vous ressentez une douleur dans le bas du dos et vérifiez votre posture"]', '["Maintain a strong plank position throughout the entire movement", "Focus on controlled movement rather than speed to maximize core engagement", "Keep your hips as stable as possible while performing the knee-to-elbow motion", "Breathe steadily and avoid holding your breath during the exercise", "Stop if you feel lower back strain and check your form"]', 'e4241c30-f7d8-4051-85d7-7a95e221bf8c', 'plank-toe-touches', NULL, NULL);
INSERT INTO public.exercises VALUES ('e6f77e2e-dd55-46bf-a173-e806f8ca670f', 'Élévation Frontale à Un Bras avec Câble', NULL, 'رفع أمامي بيد واحدة بالكيبل', 'Single Arm Cable Front Raise', 'Shoulders', '[]', 'Shoulders', 'Beginner', 4, '/videos/shoulders/single-arm-cable-front-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-cable-front-raise.jpg', NULL, '["Garde ton core bien engagé et ne te laisse pas entraîner par l''élan.", "Maintiens un léger pli dans le coude tout au long du mouvement.", "Concentre-toi sur un mouvement contrôlé, aussi bien en montant qu''en descendant pour maximiser l''engagement musculaire.", "Arrête à hauteur d''épaule pour prévenir tout risque d''impingement.", "Utilise ton bras non actif pour te stabiliser si nécessaire en tenant la machine."]', '["Se pencher en avant pendant l''exercice.", "Utiliser trop d''élan au lieu de contrôler le mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "cable", "single arm cable front raise"]', true, '2026-04-03 12:24:59.180721+00', '2026-04-03 12:24:59.180721+00', 'Position de départ : Debout face à la machine à câble, une main tenant la poignée, bras tendu vers le bas. Exécution : Lève la poignée vers l''avant jusqu''à hauteur d''épaule, puis redescends lentement.', '["Se pencher en avant pendant l''exercice.", "Utiliser trop d''élan au lieu de contrôler le mouvement."]', true, '["Set the cable pulley to the lowest position and attach a single handle", "Stand facing the cable machine with feet shoulder-width apart, core engaged", "Grasp the handle with your working arm using an overhand grip, arm extended down by your side", "Keep your torso upright and raise your arm straight forward until it reaches shoulder height", "Pause briefly at the top of the movement", "Slowly lower your arm back to the starting position with control"]', '["Règle le câble à la position la plus basse et fixe une poignée simple.", "Debout face à la machine, pieds écartés à la largeur des épaules, engage ton core.", "Prends la poignée avec ton bras actif en prise pronation, bras tendu sur le côté.", "Garde le torse droit et lève ton bras à l''avant jusqu''à hauteur d''épaule.", "Marque une courte pause en haut du mouvement.", "Redescends lentement ton bras à la position de départ en contrôlant le mouvement."]', '["Garde ton core bien engagé et ne te laisse pas entraîner par l''élan.", "Maintiens un léger pli dans le coude tout au long du mouvement.", "Concentre-toi sur un mouvement contrôlé, aussi bien en montant qu''en descendant pour maximiser l''engagement musculaire.", "Arrête à hauteur d''épaule pour prévenir tout risque d''impingement.", "Utilise ton bras non actif pour te stabiliser si nécessaire en tenant la machine."]', '["Keep your core tight and avoid using momentum or swaying your body", "Maintain a slight bend in your elbow throughout the entire movement", "Focus on controlled movement both up and down to maximize muscle engagement", "Stop at shoulder height to prevent shoulder impingement", "Use your non-working arm to stabilize yourself if needed by holding onto the machine"]', '9089468c-a43c-4486-892e-557485a39245', 'single-arm-cable-front-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('8afb77eb-9a61-4ff9-8196-a9b3be7b91c8', 'Curl bas à un bras', NULL, 'تمرين الكيرل الأحادي المنخفض', 'Single Arm Low Cable Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 4, '/videos/biceps/single-arm-low-cable-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-low-cable-curl.jpg', NULL, '["Garde ton coude fixe à ton côté tout au long du mouvement pour isoler le biceps", "Légèrement fléchis les genoux et engage ton ventre pour éviter de te balancer ou d''utiliser l''élan", "Utilise toute l''amplitude de mouvement en tendant complètement le bras en bas et en contractant au maximum en haut", "Contrôle le poids durant les phases de montée et de descente pour maximiser l''engagement musculaire et prévenir les blessures"]', '["Bouger le coude d''un côté à l''autre au lieu de le garder fixe", "Utiliser trop de poids, ce qui entraîne un mouvement désordonné et un travail musculaire réduit"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "cable", "single arm low cable curl"]', true, '2026-04-03 12:24:59.195236+00', '2026-04-03 12:24:59.195236+00', 'Position de départ : Tiens-toi face à une poulie basse avec un haltère dans une main, le bras tendu vers le bas. Exécution : Plie ton coude pour amener l''haltère vers ton épaule, puis redescends de manière contrôlée.', '["Bouger le coude d''un côté à l''autre au lieu de le garder fixe", "Utiliser trop de poids, ce qui entraîne un mouvement désordonné et un travail musculaire réduit"]', true, '["Set the cable pulley to the lowest position and attach a single handle", "Stand 2-3 feet away from the machine with feet shoulder-width apart for stability", "Grasp the handle with an underhand grip, keeping your working arm at your side with elbow close to your torso", "Curl the weight up by flexing your bicep, bringing your hand toward your shoulder", "Squeeze your bicep at the top of the movement for one second", "Slowly lower the weight back to starting position, maintaining control throughout the descent"]', '["Règle la poulie à sa position la plus basse et attache une poignée simple", "Écarte les pieds à la largeur des épaules, à 60-90 cm de la machine pour plus de stabilité", "Prends la poignée avec une prise en supination, garde ton bras fléchi près de ton corps", "Contracte ton biceps pour faire monter le poids vers ton épaule", "Maintiens la contraction du biceps en haut du mouvement pendant une seconde", "Abaisse lentement le poids vers la position de départ en gardant le contrôle tout au long de la descente"]', '["Garde ton coude fixe à ton côté tout au long du mouvement pour isoler le biceps", "Légèrement fléchis les genoux et engage ton ventre pour éviter de te balancer ou d''utiliser l''élan", "Utilise toute l''amplitude de mouvement en tendant complètement le bras en bas et en contractant au maximum en haut", "Contrôle le poids durant les phases de montée et de descente pour maximiser l''engagement musculaire et prévenir les blessures"]', '["Keep your elbow stationary at your side throughout the entire movement to isolate the bicep", "Maintain a slight bend in your knees and engage your core to prevent swaying or using momentum", "Use a full range of motion by fully extending your arm at the bottom and achieving maximum contraction at the top", "Control the weight during both the lifting and lowering phases to maximize muscle engagement and prevent injury"]', 'efde17d4-3987-4416-9142-825a18329245', 'single-arm-low-cable-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('c9261c98-60fa-4754-99a9-160e115b8a94', 'Marche latérale en planche avec tapotements d''épaules', NULL, NULL, 'Side to side plank walk into shoulder taps', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-to-side-plank-walk-into-shoulder-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-to-side-plank-walk-into-shoulder-taps.jpg', NULL, '["Garde ton ventre bien contracté pour éviter que tes hanches ne s''affaissent", "Réduis la rotation des hanches lors des tapotements en engageant tes fessiers et ton gainage", "Maintiens une ligne droite de la tête aux talons durant tout le mouvement", "Veille à ce que tes mains restent bien sous tes épaules en position de planche", "Effectue le mouvement de manière contrôlée, ne précipite pas les choses"]', '["Ne pas engager le core, ce qui peut faire descendre les hanches", "Bouger trop rapidement, ce qui entraîne une mauvaise forme"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side to side plank walk into shoulder taps"]', true, '2026-04-03 12:24:59.124418+00', '2026-04-03 12:24:59.124418+00', 'Commence en position de planche : mains écartées à la largeur des épaules, corps en ligne droite des pieds à la tête. Évolue en te déplaçant latéralement en planche, puis fait des tapotements d''épaules pour renforcer ton gainage.', '["Ne pas engager le core, ce qui peut faire descendre les hanches", "Bouger trop rapidement, ce qui entraîne une mauvaise forme"]', true, '["Start in a high plank position with hands directly under shoulders and core engaged", "Step your right hand and left foot simultaneously to the right, maintaining plank alignment", "Follow with your left hand and right foot to return to shoulder-width hand spacing", "Lift your right hand to tap your left shoulder while keeping hips stable", "Return right hand to the floor and repeat the tap with your left hand to right shoulder", "Continue the lateral walking movement and shoulder tap sequence as desired"]', '["Adopte une position de planche haute, mains sous les épaules et le ventre bien engagé", "Déplace ta main droite et ton pied gauche simultanément vers la droite, en gardant ton alignement", "Ramène ta main gauche et ton pied droit pour retrouver une position avec les mains à la largeur des épaules", "Lève ta main droite pour toucher ton épaule gauche sans bouger les hanches", "Ramène ta main droite au sol et fais de même avec ta main gauche vers l''épaule droite", "Poursuis le mouvement latéral et les tapotements d''épaules selon tes capacités"]', '["Garde ton ventre bien contracté pour éviter que tes hanches ne s''affaissent", "Réduis la rotation des hanches lors des tapotements en engageant tes fessiers et ton gainage", "Maintiens une ligne droite de la tête aux talons durant tout le mouvement", "Veille à ce que tes mains restent bien sous tes épaules en position de planche", "Effectue le mouvement de manière contrôlée, ne précipite pas les choses"]', '["Keep your core tight throughout the entire movement to prevent sagging hips", "Minimize hip rotation when performing shoulder taps by engaging your glutes and core", "Maintain a straight line from head to heels during both the lateral movement and shoulder taps", "Keep your hands directly under your shoulders when in the plank position", "Move in a controlled manner rather than rushing through the exercise"]', '49193da5-2b92-4df3-bca6-f0cd59fa9f03', 'side-to-side-plank-walk-into-shoulder-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('853eb837-2309-456e-9521-476b895fa95c', 'Russian Twist - Sans poids', NULL, 'رخايس روسي - بلا وزن', 'Russian Twist - no weight', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/russian-twist-no-weight.mp4', NULL, NULL, NULL, '/videos/thumbnails/russian-twist-no-weight.jpg', NULL, '["Garde ta poitrine haute et tes épaules en arrière pour une posture correcte.", "Concentre-toi sur la rotation depuis le tronc plutôt que de simplement bouger les bras.", "Respire régulièrement, ne retiens pas ta respiration durant l''exercice.", "Maintiens toujours tes pieds en l''air pour activer ton tronc en permanence.", "Commence par des séries courtes et augmente progressivement la durée au fur et à mesure que ta force abdominale s''améliore."]', '["Ne pas incliner suffisamment le torse vers l''arrière, ce qui réduit l''engagement du tronc.", "Ne pas maintenir les pieds élevés, ce qui diminue la difficulté et l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "russian twist - no weight"]', true, '2026-04-03 12:24:58.667024+00', '2026-04-03 12:24:58.667024+00', 'Un exercice explosif pour renforcer ton tronc et améliorer ta stabilité.', '["Ne pas incliner suffisamment le torse vers l''arrière, ce qui réduit l''engagement du tronc.", "Ne pas maintenir les pieds élevés, ce qui diminue la difficulté et l''efficacité de l''exercice."]', true, '["Sit on the floor with knees bent and feet flat on the ground, leaning back slightly to engage your core", "Lift your feet off the ground a few inches, balancing on your glutes while maintaining the lean-back position", "Clasp your hands together in front of your chest or interlace your fingers", "Rotate your torso to the right side, bringing your hands toward the floor beside your hip", "Return to center then rotate to the left side, bringing your hands toward the floor beside your left hip", "Continue alternating sides in a controlled, rhythmic motion"]', '["Assieds-toi au sol, les genoux fléchis et les pieds bien plaqués au sol, penche-toi légèrement en arrière pour activer ta ceinture abdominale.", "Soulève tes pieds du sol de quelques centimètres, équilibre-toi sur tes fessiers tout en gardant cette position inclinée.", "Joins tes mains devant ta poitrine ou entrelace tes doigts.", "Fais une rotation de ton torse vers la droite, en amenant tes mains près du sol à côté de ta hanche droite.", "Reviens au centre puis tourne vers la gauche, en amenant tes mains près du sol à côté de ta hanche gauche.", "Alterne les côtés de manière contrôlée et rythmée."]', '["Garde ta poitrine haute et tes épaules en arrière pour une posture correcte.", "Concentre-toi sur la rotation depuis le tronc plutôt que de simplement bouger les bras.", "Respire régulièrement, ne retiens pas ta respiration durant l''exercice.", "Maintiens toujours tes pieds en l''air pour activer ton tronc en permanence.", "Commence par des séries courtes et augmente progressivement la durée au fur et à mesure que ta force abdominale s''améliore."]', '["Keep your chest up and shoulders back throughout the movement to maintain proper posture", "Focus on rotating from your core rather than just moving your arms", "Maintain steady breathing and avoid holding your breath during the exercise", "Keep your feet elevated throughout the set to maintain constant core engagement", "Start with shorter sets and gradually increase duration as your core strength improves"]', '1328cea8-8e8b-4a64-9f6a-10d8031b2f27', 'russian-twist-no-weight', NULL, NULL);
INSERT INTO public.exercises VALUES ('5f4e818d-e908-4d68-a45b-5c8140ace9ae', 'Pompes à un bras (droite)', NULL, NULL, 'Single arm push up (R)', 'Chest', '[]', 'Chest', 'Advanced', 16, '/videos/chest/single-arm-push-up-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/single-arm-push-up-r.jpg', NULL, '["C''est un exercice avancé qui nécessite une force significative du haut du corps et du tronc - maîtrise d''abord les pompes classiques", "Garde une ligne droite de ta tête à tes pieds sans laisser tes hanches s''affaisser ou se tordre", "Commence avec un mouvement partiel et augmente progressivement la profondeur au fur et à mesure que ta force s''améliore", "Positionne ta main de soutien sous le centre de ta poitrine pour un meilleur levier", "Arrête immédiatement si tu ressens de la douleur au poignet, à l''épaule ou au coude."]', '["Ne pas garder le corps en ligne droite", "Oublier de contracter le tronc pendant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "single arm push up (r)"]', true, '2026-04-03 12:24:59.216663+00', '2026-04-03 12:24:59.216663+00', 'Position de départ : Commence en position classique de pompes, place ta main gauche derrière ton dos ou sur ta hanche. Avec tes pieds écartés plus large que les épaules, équilibre-toi sur ta main droite. Exécution : Abaisse ton corps en fléchissant ton bras droit jusqu''à ce que ta poitrine frôle le sol, puis remonte en utilisant uniquement ton bras droit.', '["Ne pas garder le corps en ligne droite", "Oublier de contracter le tronc pendant le mouvement"]', true, '["Start with regular push-ups and progress to elevated single-arm push-ups before attempting this advanced variation", "Position your right hand directly under your chest center rather than under your right shoulder for better balance", "Spread your feet wider than normal and angle your body slightly toward your supporting arm", "Keep your core extremely tight throughout the entire movement to prevent rotation", "Lower slowly with control and only go as deep as you can while maintaining proper form", "Focus on quality over quantity - even partial range of motion is beneficial when learning"]', '["Commence par des pompes classiques et progresse vers des pompes surélevées avant de tenter cette variation avancée", "Positionne ta main droite directement sous le centre de ta poitrine pour une meilleure stabilité", "Écarte tes pieds plus que d''habitude et incline légèrement ton corps vers ton bras de soutien", "Garde ton ventre bien contracté durant tout le mouvement pour éviter les rotations", "Descends lentement et contrôlé, et va aussi bas que possible tout en maintenant la forme correcte", "Concentre-toi sur la qualité plutôt que sur la quantité - même un mouvement partiel est bénéfique en apprenant."]', '["C''est un exercice avancé qui nécessite une force significative du haut du corps et du tronc - maîtrise d''abord les pompes classiques", "Garde une ligne droite de ta tête à tes pieds sans laisser tes hanches s''affaisser ou se tordre", "Commence avec un mouvement partiel et augmente progressivement la profondeur au fur et à mesure que ta force s''améliore", "Positionne ta main de soutien sous le centre de ta poitrine pour un meilleur levier", "Arrête immédiatement si tu ressens de la douleur au poignet, à l''épaule ou au coude."]', '["This is an advanced exercise requiring significant upper body and core strength - master regular push-ups first", "Maintain a straight line from head to feet without allowing your hips to rotate or sag", "Start with partial range of motion and gradually increase depth as strength improves", "Keep your supporting hand positioned under the center of your chest for optimal leverage", "Stop immediately if you experience wrist, shoulder, or elbow pain"]', '147a7908-fdd3-4f79-94ca-f9a69989e14c', 'single-arm-push-up-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('213ff4c8-bf10-4c99-b662-0213da1d3eb4', 'Rowing incliné à la Smith Machine', NULL, NULL, 'Smith Machine Bent Over Row', 'Back', '[]', 'Back', 'Intermediate', 8, '/videos/back/smith-machine-bent-over-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-bent-over-row.jpg', NULL, '["Garde ton ventre serré et évite de cambrer le dos pour prévenir les blessures.", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement par la rétraction des scapulas.", "Maintiens une légère flexion de tes genoux tout au long de l''exercice pour protéger ta zone lombaire.", "Contrôle le poids lors des phases de levée et d''abaissement pour maximiser l''engagement musculaire."]', '["Arrondir le dos pendant l''exercice.", "Tirer avec les bras au lieu de contracter les muscles du dos."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "smith machine bent over row"]', true, '2026-04-03 12:24:59.268584+00', '2026-04-03 12:24:59.268584+00', 'Positionne-toi devant la Smith machine avec une prise pronation (paumes vers le bas) à la largeur des épaules, le torse penché en avant. Tirez la barre vers ta poitrine en gardant le dos droit, puis abaisse-la lentement à la position de départ.', '["Arrondir le dos pendant l''exercice.", "Tirer avec les bras au lieu de contracter les muscles du dos."]', true, '["Set the Smith machine bar at mid-shin height and add appropriate weight plates", "Stand with feet hip-width apart, bend at hips and knees to grip the bar with hands slightly wider than shoulders", "Keep your chest up, core engaged, and maintain a neutral spine throughout the movement", "Pull the bar toward your lower chest by retracting your shoulder blades and driving elbows back close to your body", "Squeeze your back muscles at the top of the movement for one second", "Lower the bar slowly and under control back to the starting position without letting it touch the ground"]', '["Règle la barre de la Smith machine à mi-hauteur des tibias et ajoute le poids approprié.", "Place tes pieds à la largeur des hanches, plie les hanches et les genoux pour saisir la barre avec les mains légèrement plus larges que les épaules.", "Garde le buste redressé, contracte tes abdominaux et maintiens une colonne vertébrale neutre tout au long du mouvement.", "Tire la barre vers le bas de ta poitrine en rétractant tes scapulas et en poussant les coudes vers l''arrière près de ton corps.", "Contracte tes muscles du dos en haut du mouvement pendant une seconde.", "Abaisse la barre lentement et de manière contrôlée à la position de départ sans la laisser toucher le sol."]', '["Garde ton ventre serré et évite de cambrer le dos pour prévenir les blessures.", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras en initiant le mouvement par la rétraction des scapulas.", "Maintiens une légère flexion de tes genoux tout au long de l''exercice pour protéger ta zone lombaire.", "Contrôle le poids lors des phases de levée et d''abaissement pour maximiser l''engagement musculaire."]', '["Keep your core tight and avoid rounding your back to prevent injury", "Focus on pulling with your back muscles rather than your arms by initiating the movement with shoulder blade retraction", "Maintain a slight bend in your knees throughout the exercise to protect your lower back", "Control the weight on both the lifting and lowering phases to maximize muscle engagement"]', '2b207100-576f-4029-848e-f71bb05df885', 'smith-machine-bent-over-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('3b3e59c2-ffa9-4bb1-8f2b-d9aa38cf663c', 'Squat Fessier à la Smith Machine', NULL, NULL, 'Smith Machine Glute Squat', 'Glutes', '[]', 'Glutes', 'Intermediate', 8, '/videos/glutes/smith-machine-glute-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-glute-squat.jpg', NULL, '["Répartis ton poids sur tes talons pour maximiser l''activation des fessiers", "Garde une colonne vertébrale neutre pendant tout le mouvement en maintenant la poitrine haute et le core engagé", "Concentre-toi sur le recul des hanches avant de fléchir les genoux pour mieux solliciter les fessiers", "Assure-toi que tes genoux restent alignés avec tes orteils et ne s''affaissent pas vers l''intérieur pendant l''exercice", "Contrôle la descente et évite de rebondir au fond du squat"]', '["Ne pas garder le dos droit et la poitrine haute", "Descendre sans contrôle, ce qui peut entraîner des blessures"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "machine", "smith machine glute squat"]', true, '2026-04-03 12:24:59.299264+00', '2026-04-03 12:24:59.299264+00', 'Positionne-toi sous la Smith machine, la barre sur le haut de ton dos, les pieds légèrement en avant. Descends en squat profond en mettant l''accent sur les fessiers, puis pousse pour revenir à la position de départ.', '["Ne pas garder le dos droit et la poitrine haute", "Descendre sans contrôle, ce qui peut entraîner des blessures"]', true, '["Set the Smith machine bar at shoulder height and load appropriate weight", "Position yourself under the bar with feet wider than shoulder-width and toes pointed outward", "Unrack the bar by lifting and rotating the hooks, then step back slightly", "Lower your body by sitting back into your hips while keeping your knees tracking over your toes", "Descend until your thighs are parallel to the floor or as low as your mobility allows", "Drive through your heels and squeeze your glutes to return to the starting position"]', '["Régle la barre de la Smith machine à hauteur d''épaules et charge le poids approprié", "Place-toi sous la barre avec les pieds écartés au-delà des épaules et les orteils orientés vers l''extérieur", "Décharge la barre en soulevant et en tournant les crochets, puis fais un pas en arrière", "Descends en t''asseyant sur tes hanches tout en veillant à ce que tes genoux suivent la ligne de tes orteils", "Descends jusqu''à ce que tes cuisses soient parallèles au sol ou aussi bas que ta mobilité le permet", "Pousse à travers tes talons et contracte tes fessiers pour revenir à la position de départ"]', '["Répartis ton poids sur tes talons pour maximiser l''activation des fessiers", "Garde une colonne vertébrale neutre pendant tout le mouvement en maintenant la poitrine haute et le core engagé", "Concentre-toi sur le recul des hanches avant de fléchir les genoux pour mieux solliciter les fessiers", "Assure-toi que tes genoux restent alignés avec tes orteils et ne s''affaissent pas vers l''intérieur pendant l''exercice", "Contrôle la descente et évite de rebondir au fond du squat"]', '["Keep your weight distributed through your heels rather than your toes to maximize glute activation", "Maintain a neutral spine throughout the movement by keeping your chest up and core engaged", "Focus on pushing your hips back first rather than bending your knees to emphasize glute recruitment", "Ensure your knees track in line with your toes and don''t cave inward during the movement", "Control the descent and avoid bouncing at the bottom of the squat"]', '5b61e155-eda8-4077-854b-bfe331f5fd55', 'smith-machine-glute-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('81f4df08-97be-47ff-93cc-6ea2e1e66428', 'Fente à la Smith Machine', NULL, 'فانت بسمِث ماشين', 'Smith Machine Lunge', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/smith-machine-lunge.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-lunge.jpg', NULL, '["Concentre la majorité de ton poids sur ta jambe avant et évite de pousser avec tes orteils de la jambe arrière.", "Gardez le torse droit pour optimiser l''engagement des quadriceps et prévenir les douleurs lombaires.", "Assure-toi que ton genou avant reste aligné avec tes orteils et ne s''affaisse pas vers l''intérieur durant le mouvement.", "Contrôle la descente pour maximiser l''activation musculaire et éviter les blessures."]', '["Pousser trop avec les orteils de la jambe arrière.", "Se pencher en avant au lieu de garder le torse droit."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "smith machine lunge"]', true, '2026-04-03 12:24:59.322473+00', '2026-04-03 12:24:59.322473+00', 'Mets-toi en position sous la Smith machine avec une jambe devant et l''autre derrière. Abaisse ton corps en pliant les deux genoux et remonte en poussant sur la jambe avant.', '["Pousser trop avec les orteils de la jambe arrière.", "Se pencher en avant au lieu de garder le torse droit."]', true, '["Position the Smith machine bar at shoulder height and step under it, resting it across your upper trapezius muscles", "Take a large step forward with one foot while keeping the other foot back, creating a staggered stance", "Keep your torso upright and core engaged throughout the movement", "Lower your body by bending both knees until your back knee is just above the ground", "Push through your front heel to return to the starting position", "Complete all reps on one leg before switching to the other side"]', '["Positionne la barre de la Smith machine à la hauteur des épaules et place-toi dessous, la barre reposant sur tes trapèzes supérieurs.", "Fais un grand pas en avant avec une jambe tout en maintenant l''autre jambe en arrière, créant ainsi une posture échelonnée.", "Garde ton torse droit et tes abdos contractés pendant tout le mouvement.", "Abaisse ton corps en pliant les deux genoux jusqu''à ce que ton genou arrière frôle le sol.", "Pousse avec le talon de ta jambe avant pour revenir à la position de départ.", "Réalise toutes les répétitions d''un côté avant de passer à l''autre jambe."]', '["Concentre la majorité de ton poids sur ta jambe avant et évite de pousser avec tes orteils de la jambe arrière.", "Gardez le torse droit pour optimiser l''engagement des quadriceps et prévenir les douleurs lombaires.", "Assure-toi que ton genou avant reste aligné avec tes orteils et ne s''affaisse pas vers l''intérieur durant le mouvement.", "Contrôle la descente pour maximiser l''activation musculaire et éviter les blessures."]', '["Keep most of your weight on your front leg and avoid pushing off your back toe", "Maintain an upright torso position to maximize quad engagement and prevent lower back strain", "Ensure your front knee tracks over your toes and doesn''t cave inward during the movement", "Control the descent slowly to maximize muscle activation and prevent injury"]', '90421a51-69d9-4f27-9076-847dff2d882a', 'smith-machine-lunge', NULL, NULL);
INSERT INTO public.exercises VALUES ('176f1625-6d50-4ebf-a2cf-fb8904ca3bdf', 'Atteignez vos orteils au sol !', NULL, NULL, 'Lying toe reaches', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/lying-toe-reaches.mp4', NULL, NULL, NULL, '/videos/thumbnails/lying-toe-reaches.jpg', NULL, '["Gardez le cou en position neutre, sans forcer vers l''avant lors de l''atteinte", "Mouvement lent et contrôlé pour maximiser l''engagement des abdos et éviter les blessures", "Si vous ne pouvez pas toucher vos orteils, allez aussi loin que possible sans perdre la forme", "Expirez en soulevant et inspirez en redescendant", "Arrêtez immédiatement en cas de douleur dans le bas du dos et envisagez de modifier votre amplitude"]', '["Soulever trop rapidement sans contrôle", "Ne pas maintenir le bas du dos plaqué au sol"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "lying toe reaches"]', true, '2026-04-03 12:24:57.740522+00', '2026-04-03 12:24:57.740522+00', 'Allongez-vous sur le dos, bras tendus au-dessus de la tête et jambes droites. Activez votre core et préparez-vous à soulever votre corps !', '["Soulever trop rapidement sans contrôle", "Ne pas maintenir le bas du dos plaqué au sol"]', true, '["Lie flat on your back on a mat with arms extended overhead and legs straight", "Keep your lower back pressed gently against the floor before beginning the movement", "Simultaneously lift your shoulders and legs off the ground while reaching your hands toward your toes", "Focus on using your core muscles to initiate the movement rather than momentum", "Hold the top position briefly when your hands are closest to your toes", "Slowly lower both your torso and legs back to the starting position with control"]', '["Allongez-vous sur un tapis, bras au-dessus de la tête et jambes droites", "Gardez le bas de votre dos bien plaqué au sol avant de commencer", "Soulevez vos épaules et vos jambes du sol tout en tendant les mains vers vos orteils", "Concentrez-vous sur vos muscles du ventre pour initier le mouvement, pas sur l''élan", "Restez un instant en haut quand vos mains sont près de vos orteils", "Redescendez lentement votre torse et vos jambes à la position de départ en contrôlant le mouvement"]', '["Gardez le cou en position neutre, sans forcer vers l''avant lors de l''atteinte", "Mouvement lent et contrôlé pour maximiser l''engagement des abdos et éviter les blessures", "Si vous ne pouvez pas toucher vos orteils, allez aussi loin que possible sans perdre la forme", "Expirez en soulevant et inspirez en redescendant", "Arrêtez immédiatement en cas de douleur dans le bas du dos et envisagez de modifier votre amplitude"]', '["Keep your neck in a neutral position and avoid straining it forward during the reach", "Move slowly and controlled to maximize core engagement and prevent injury", "If you cannot reach your toes, reach as far as comfortable while maintaining proper form", "Breathe out during the lifting phase and breathe in as you lower back down", "Stop immediately if you feel any lower back pain and consider modifying the range of motion"]', '5e98b09d-e4aa-4ddb-aadf-02e18b6c16ac', 'lying-toe-reaches', NULL, NULL);
INSERT INTO public.exercises VALUES ('ccf318ee-ef99-429c-9162-40c4143d8bca', 'Step-Ups à la Smith Machine', NULL, 'Step-Ups à la Smith Machine', 'Smith Machine Step-Ups', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 8, '/videos/quadriceps/smith-machine-step-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-step-ups.jpg', NULL, '["Garde le buste droit pendant tout le mouvement pour une bonne posture et optimiser l''engagement des quadriceps", "Pousse à travers le talon de ta jambe qui monte pour un meilleur travail musculaire, évite de pousser avec les orteils", "Contrôle bien la descente pour éviter les impacts brutaux sur tes genoux et maximiser la tension musculaire", "Choisis une hauteur de plateforme qui place ta hanche au même niveau ou légèrement en dessous de ton genou lorsque ton pied est sur le banc pour un maximum d''amplitude", "Évite d''utiliser l''élan ou de rebondir sur le banc, concentre-toi sur des mouvements fluides et maîtrisés"]', '["Se pencher en avant, ce qui peut nuire à la posture", "Descendre trop rapidement, ce qui peut provoquer des impacts douloureux sur les genoux"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "machine", "smith machine step-ups"]', true, '2026-04-03 12:24:59.36062+00', '2026-04-03 12:24:59.36062+00', 'Mets-toi face à la Smith Machine, un pied sur le banc prêt à t''élancer. Prêt ? Allons-y !', '["Se pencher en avant, ce qui peut nuire à la posture", "Descendre trop rapidement, ce qui peut provoquer des impacts douloureux sur les genoux"]', true, '["Set the Smith machine bar at upper chest height and position a stable bench or platform perpendicular to the bar", "Load the bar with appropriate weight and step under it, positioning the bar on your upper trapezius muscles", "Grasp the bar with hands wider than shoulder-width apart and stand upright facing the bench", "Step up onto the bench with your right foot, placing your entire foot firmly on the surface", "Drive through your right heel to lift your body up until your right leg is fully extended, bringing your left foot up to meet the platform briefly", "Step back down with your left foot first, then your right foot, maintaining control throughout the descent", "Complete all repetitions on one leg before switching to the other leg", "Re-rack the bar safely when finished with both legs"]', '["Place la barre de la Smith machine à la hauteur de ton haut de poitrine et ajuste un banc stable perpendiculaire à la barre", "Charge la barre avec un poids adapté et positionne-toi dessous, la barre sur tes trapèzes supérieurs", "Prends la barre avec une prise plus large que la largeur des épaules et reste droit face au banc", "Monte sur le banc avec ton pied droit, en appuyant bien ton pied entier sur la surface", "Pousse à travers ton talon droit pour soulever ton corps jusqu''à ce que ta jambe soit complètement étendue, fais monter ton pied gauche pour le poser brièvement sur le banc", "Descends en mettant d''abord ton pied gauche puis ton pied droit, garde le contrôle pendant toute la descente", "Fais tous tes répétitions d''un côté avant de changer de jambe", "Range la barre en toute sécurité une fois que tu as terminé des deux jambes"]', '["Garde le buste droit pendant tout le mouvement pour une bonne posture et optimiser l''engagement des quadriceps", "Pousse à travers le talon de ta jambe qui monte pour un meilleur travail musculaire, évite de pousser avec les orteils", "Contrôle bien la descente pour éviter les impacts brutaux sur tes genoux et maximiser la tension musculaire", "Choisis une hauteur de plateforme qui place ta hanche au même niveau ou légèrement en dessous de ton genou lorsque ton pied est sur le banc pour un maximum d''amplitude", "Évite d''utiliser l''élan ou de rebondir sur le banc, concentre-toi sur des mouvements fluides et maîtrisés"]', '["Keep your torso upright throughout the movement to maintain proper spinal alignment and maximize quadriceps activation", "Drive through the heel of your stepping leg rather than pushing off your toes to ensure proper muscle engagement", "Control the descent portion of the movement to prevent jarring impact on your knees and maximize time under tension", "Use a platform height that allows your hip to be at or slightly below knee level when your foot is planted to ensure full range of motion", "Avoid using momentum or bouncing off the platform, focusing instead on smooth, controlled movements"]', 'ab582577-f6d5-4f62-9f5a-220995d7910f', 'smith-machine-step-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('ebd2dae0-aeab-4935-8591-1682baa2a6c4', 'Spider Curl', NULL, 'سبايدر كيرل', 'Spider Curl', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/spider-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/spider-curl.jpg', NULL, '["Garde tes bras supérieurs immobiles et perpendiculaires pour isoler efficacement les biceps", "Utilise toute l''amplitude de mouvement : étends bien les bras en bas et contracte à fond en haut", "Contrôle la descente pour maximiser la tension musculaire et éviter l''élan", "Choisis un poids qui te permet de garder une bonne forme sur toutes les répétitions", "Évite de balancer ou d''utiliser tes épaules pour aider le mouvement"]', '["Ne pas garder les bras supérieurs stables", "Utiliser un poids trop lourd qui compromet la forme"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "spider curl"]', true, '2026-04-03 12:24:59.409709+00', '2026-04-03 12:24:59.409709+00', 'L''exercice Spider Curl est parfait pour cibler tes biceps. Allonge-toi sur un banc incliné et prépare-toi à faire travailler tes bras comme jamais !', '["Ne pas garder les bras supérieurs stables", "Utiliser un poids trop lourd qui compromet la forme"]', true, '["Set an incline bench to 45-60 degrees and lie face down with your chest against the pad", "Allow your arms to hang straight down from your shoulders while gripping a dumbbell in each hand", "Keep your upper arms perpendicular to the floor throughout the entire movement", "Curl the weights up by contracting your biceps until you achieve peak contraction", "Slowly lower the dumbbells back to the starting position with control", "Maintain contact between your chest and the bench pad at all times"]', '["Place un banc incliné à 45-60 degrés et allonge-toi face contre le banc, poitrine sur le coussin", "Laisse tes bras pendre droit vers le bas, un haltère dans chaque main", "Garde tes bras supérieurs perpendiculaires au sol tout au long du mouvement", "Fléchis les coudes pour soulever les haltères vers tes épaules en contractant bien les biceps", "Redescends lentement les haltères à la position de départ avec contrôle", "Assure-toi que ta poitrine reste en contact avec le banc à tout moment"]', '["Garde tes bras supérieurs immobiles et perpendiculaires pour isoler efficacement les biceps", "Utilise toute l''amplitude de mouvement : étends bien les bras en bas et contracte à fond en haut", "Contrôle la descente pour maximiser la tension musculaire et éviter l''élan", "Choisis un poids qui te permet de garder une bonne forme sur toutes les répétitions", "Évite de balancer ou d''utiliser tes épaules pour aider le mouvement"]', '["Keep your upper arms completely stationary and perpendicular to the floor to isolate the biceps effectively", "Use a full range of motion by allowing the arms to fully extend at the bottom and achieving peak contraction at the top", "Control the eccentric portion of the movement to maximize muscle tension and prevent momentum", "Choose a weight that allows you to maintain proper form throughout all repetitions", "Avoid swinging or using your shoulders to assist with the movement"]', 'bda13030-b09a-4fec-ada4-ec2d528db0d7', 'spider-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('86be1739-db20-4d51-94cc-0285d1fede45', 'L''Exercice Over and Under', NULL, NULL, 'Over and under', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/over-and-under.mp4', NULL, NULL, NULL, '/videos/thumbnails/over-and-under.jpg', NULL, '["Maintiens ton gainage tout au long des phases de levée de genou et de squat bas", "Atterrit doucement sur l’avant des pieds pour réduire l''impact sur les articulations", "Assure-toi de garder une bonne posture même lorsque tu te baisses - évite d''arrondir le dos", "Contrôle le tempo pour garantir une bonne exécution plutôt que de te précipiter", "Visualise les barrières réelles pour maintenir des hauteurs de mouvement constantes"]', '["Négliger de bien s''échauffer avant de commencer l''exercice", "Oublier de faire attention à la posture de la colonne vertébrale pendant le squat"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "over and under"]', true, '2026-04-03 12:24:58.217075+00', '2026-04-03 12:24:58.217075+00', 'Position de départ : Mets-toi debout face à une barrière imaginaire à hauteur de taille, les pieds écartés à la largeur des épaules et les bras le long du corps. Exécution : Alterne entre lever un genou haut pour passer par-dessus la barrière, puis jongle immédiatement en te baissant et en avançant, créant ainsi un mouvement continu d’over-under.', '["Négliger de bien s''échauffer avant de commencer l''exercice", "Oublier de faire attention à la posture de la colonne vertébrale pendant le squat"]', true, '["Stand with feet shoulder-width apart and establish your imaginary waist-high barrier in front of you", "Lift your right knee up high as if stepping over the barrier, then step forward", "Immediately squat down low and take another step forward as if ducking under a barrier", "Rise back to standing position and repeat the sequence with your left leg leading the over movement", "Continue alternating the over-under pattern while moving forward in a controlled manner", "Maintain steady breathing throughout the movement sequence"]', '["Positionne-toi avec les pieds écartés à la largeur des épaules et imagine ta barrière à hauteur de taille devant toi", "Lève ton genou droit aussi haut que possible, comme si tu passais par-dessus la barrière, puis avance", "Plie-toi immédiatement en bas et fais un pas en avant comme si tu te baissais sous la barrière", "Remonte en position debout et répète la séquence en commençant avec la jambe gauche pour le mouvement de levée", "Continue d''alterner le mouvement over-under tout en avançant de manière contrôlée", "Garde une respiration régulière pendant toute la séquence de mouvements"]', '["Maintiens ton gainage tout au long des phases de levée de genou et de squat bas", "Atterrit doucement sur l’avant des pieds pour réduire l''impact sur les articulations", "Assure-toi de garder une bonne posture même lorsque tu te baisses - évite d''arrondir le dos", "Contrôle le tempo pour garantir une bonne exécution plutôt que de te précipiter", "Visualise les barrières réelles pour maintenir des hauteurs de mouvement constantes"]', '["Keep your core engaged throughout both the high knee lift and low squat portions", "Land softly on the balls of your feet to reduce impact on joints", "Maintain good posture even when squatting low - avoid rounding your back", "Control the tempo to ensure proper form rather than rushing through the movement", "Visualize the actual barriers to maintain consistent movement heights"]', '601cae63-a0d3-4f10-9a7f-114a5eb033e0', 'over-and-under', NULL, NULL);
INSERT INTO public.exercises VALUES ('21b5bb24-eae2-476f-8b49-dfffd4599807', 'Ponts de fessiers en sprint', NULL, NULL, 'Sprinter Butt bridges', 'Glutes', '[]', 'Glutes', 'Intermediate', 16, '/videos/glutes/sprinter-butt-bridges.mp4', NULL, NULL, NULL, '/videos/thumbnails/sprinter-butt-bridges.jpg', NULL, '["Garde les hanches élevées pendant tout l''exercice pour maintenir une tension constante sur les fessiers.", "Concentre-toi à pousser à travers le talon du pied qui reste au sol pour maximiser l''activation des fessiers.", "Maintiens une colonne vertébrale neutre, évite de cambrer le dos pendant le pont.", "Contrôle le mouvement de montée du genou, ne laisse pas la vitesse prendre le dessus.", "Contracte tes fessiers au sommet de chaque pont pour assurer un bon engagement musculaire."]', '["Ne pas soulever les hanches correctement, ce qui réduit l''efficacité de l''exercice.", "Laisser les hanches s''affaisser pendant le mouvement, ce qui diminue la tension sur les fessiers."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["glutes", "bodyweight", "sprinter butt bridges"]', true, '2026-04-03 12:24:59.433753+00', '2026-04-03 12:24:59.433753+00', 'Allonge-toi sur le dos, les genoux pliés et les pieds bien à plat au sol, largeur des hanches. Prépare-toi à faire ressortir tes fessiers !', '["Ne pas soulever les hanches correctement, ce qui réduit l''efficacité de l''exercice.", "Laisser les hanches s''affaisser pendant le mouvement, ce qui diminue la tension sur les fessiers."]', true, '["Lie flat on your back with knees bent at 90 degrees and feet planted firmly on the floor", "Engage your core and squeeze your glutes to lift your hips off the ground into a bridge position", "Keep your hips elevated while bringing your right knee toward your chest in a controlled motion", "Lower your right foot back to the starting position and immediately bring your left knee toward your chest", "Continue alternating legs in a rhythmic sprinting motion while maintaining the bridge position throughout", "Lower your hips back down to complete the set"]', '["Allonge-toi sur le dos avec les genoux pliés à 90 degrés et les pieds bien ancrés au sol.", "Active ton ventre et contracte tes fessiers pour soulever tes hanches vers le ciel en position de pont.", "Garde les hanches en hauteur et ramène doucement ton genou droit vers ta poitrine en rythme.", "Redescends ton pied droit pour revenir à la position de départ et amène directement ton genou gauche vers ta poitrine.", "Alterne les jambes en imitant le mouvement du sprint tout en maintenant la position du pont.", "Redescends les hanches pour finir la série."]', '["Garde les hanches élevées pendant tout l''exercice pour maintenir une tension constante sur les fessiers.", "Concentre-toi à pousser à travers le talon du pied qui reste au sol pour maximiser l''activation des fessiers.", "Maintiens une colonne vertébrale neutre, évite de cambrer le dos pendant le pont.", "Contrôle le mouvement de montée du genou, ne laisse pas la vitesse prendre le dessus.", "Contracte tes fessiers au sommet de chaque pont pour assurer un bon engagement musculaire."]', '["Keep your hips elevated throughout the entire exercise to maintain constant tension on the glutes", "Focus on driving through the heel of the planted foot to maximize glute activation", "Maintain a neutral spine and avoid overarching your back during the bridge position", "Control the knee drive movement rather than letting momentum take over", "Squeeze your glutes at the top of each bridge to ensure proper muscle engagement"]', '3cd37329-4822-44d9-ba76-66a845736ffe', 'sprinter-butt-bridges', NULL, NULL);
INSERT INTO public.exercises VALUES ('6bc72439-984d-42c1-a64d-1305624db6a8', 'Genoux Hauts', NULL, NULL, 'High Knees', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/high-knees.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-knees.jpg', NULL, '["Garde le dos droit, évite de pencher en avant ou en arrière.", "Pousse tes genoux vers la poitrine, ne te contente pas de lever les talons vers les fesses.", "Atterris doucement sur le devant de tes pieds pour protéger tes articulations.", "Fais bien jouer ton bras opposé à ta jambe pour imiter le mouvement naturel de la course.", "Commence à un rythme modéré puis accélére à mesure que tu gagnes en coordination."]', '["Pencher le torse en avant pendant le mouvement.", "Oublier de coordonner les bras avec les jambes."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "high knees"]', true, '2026-04-03 12:24:57.097786+00', '2026-04-03 12:24:57.097786+00', 'Cet exercice mobilise tout le corps en augmentant votre rythme cardiaque et en renforçant vos muscles. Prêt à relever le défi ?', '["Pencher le torse en avant pendant le mouvement.", "Oublier de coordonner les bras avec les jambes."]', true, '["Stand with feet hip-width apart and maintain an upright posture with shoulders back", "Begin by lifting your right knee toward your chest as high as comfortable while keeping your left foot planted", "Simultaneously pump your left arm forward as your right knee rises, mimicking a running motion", "Lower your right leg and immediately lift your left knee while pumping your right arm forward", "Continue alternating legs in a controlled, rhythmic pattern while staying light on your feet", "Maintain steady breathing throughout the exercise and keep your core engaged"]', '["Tiens-toi debout, les pieds écartés à la largeur des hanches, avec le dos droit et les épaules détendues.", "Lève ton genou droit vers ta poitrine aussi haut que tu le peux, tout en gardant le pied gauche au sol.", "En même temps, fais avancer ton bras gauche comme si tu courais, synchronise bien les mouvements.", "Redescends ton genou droit et monte immédiatement le gauche tout en poussant ton bras droit en avant.", "Alterne rapidement les jambes, garde un rythme fluide et reste léger sur tes pieds.", "Respire régulièrement pendant l''exercice et engage bien ton abdos."]', '["Garde le dos droit, évite de pencher en avant ou en arrière.", "Pousse tes genoux vers la poitrine, ne te contente pas de lever les talons vers les fesses.", "Atterris doucement sur le devant de tes pieds pour protéger tes articulations.", "Fais bien jouer ton bras opposé à ta jambe pour imiter le mouvement naturel de la course.", "Commence à un rythme modéré puis accélére à mesure que tu gagnes en coordination."]', '["Keep your torso upright and avoid leaning forward or backward during the movement", "Drive your knees up toward your chest rather than just lifting your heels toward your glutes", "Land softly on the balls of your feet to reduce impact on your joints", "Coordinate your arm movement opposite to your legs to maintain proper running form", "Start at a moderate pace and gradually increase speed as your coordination improves"]', 'a9f277ce-cbc2-4223-96e5-baab4a926f92', 'high-knees', NULL, NULL);
INSERT INTO public.exercises VALUES ('dc15e661-b216-4a1e-99db-b8a823eb2047', 'Squat et Tirage avec Câble', NULL, NULL, 'Squat to Cable Row', 'Back', '[]', 'Back', 'Intermediate', 4, '/videos/back/squat-to-cable-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/squat-to-cable-row.jpg', NULL, '["Maintiens une bonne technique de squat en gardant le poids sur tes talons et évite que les genoux ne s''écroulent vers l''intérieur.", "Coordonne le timing pour atteindre le bas de ton squat en même temps que tu termines le mouvement de tirage.", "Garde ton ventre serré tout au long du mouvement pour protéger ton bas du dos et maintenir la stabilité.", "Utilise un poids qui te permet de contrôler les phases de squat et de tirage sans compromettre ta forme.", "Concentre-toi sur la phase excentrique des deux mouvements en contrôlant la descente dans le squat et l''extension de tes bras."]', '["Ne pas aligner les genoux avec les orteils pendant le squat.", "Tirer la poignée trop rapidement sans contrôler le mouvement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "squat to cable row"]', true, '2026-04-03 12:24:59.463385+00', '2026-04-03 12:24:59.463385+00', 'Position de départ : Tiens-toi face à une poulie basse avec une poignée en corde, les pieds écartés à la largeur des épaules. Exécution : Descends en squat en tirant la corde vers ta poitrine, puis pousse pour revenir à la position de départ.', '["Ne pas aligner les genoux avec les orteils pendant le squat.", "Tirer la poignée trop rapidement sans contrôler le mouvement."]', true, '["Set the cable machine to chest height and select an appropriate weight that allows proper form throughout the movement", "Stand facing the cable machine with feet shoulder-width apart, toes slightly pointed outward, and grasp the handle with both hands", "Initiate the movement by pushing your hips back and bending your knees to lower into a squat while simultaneously pulling the cable handle toward your chest", "Keep your chest up, core engaged, and ensure your knees track over your toes during the squat portion", "Pull your shoulder blades together as you row the cable, focusing on squeezing your back muscles", "Return to the starting position by standing up from the squat while extending your arms forward in a controlled manner"]', '["Règle la machine à câble à hauteur de poitrine et choisis un poids adapté qui te permet de garder une bonne forme tout au long du mouvement.", "Tiens-toi face à la machine à câble, les pieds écartés à la largeur des épaules, les orteils légèrement tournés vers l''extérieur, et prends la poignée avec les deux mains.", "Débute le mouvement en poussant les hanches en arrière et en pliant les genoux pour descendre en squat, tout en tirant la poignée vers ta poitrine.", "Garde le torse relevé, le ventre engagé et assure-toi que tes genoux restent alignés avec tes orteils pendant la phase de squat.", "Ramène tes omoplates ensemble en tirant la corde, en te concentrant sur la contraction de tes muscles du dos.", "Reviens à la position de départ en te relevant du squat tout en étendant tes bras vers l''avant de manière contrôlée."]', '["Maintiens une bonne technique de squat en gardant le poids sur tes talons et évite que les genoux ne s''écroulent vers l''intérieur.", "Coordonne le timing pour atteindre le bas de ton squat en même temps que tu termines le mouvement de tirage.", "Garde ton ventre serré tout au long du mouvement pour protéger ton bas du dos et maintenir la stabilité.", "Utilise un poids qui te permet de contrôler les phases de squat et de tirage sans compromettre ta forme.", "Concentre-toi sur la phase excentrique des deux mouvements en contrôlant la descente dans le squat et l''extension de tes bras."]', '["Maintain proper squat form by keeping your weight in your heels and avoiding knee collapse inward", "Coordinate the timing so that you reach the bottom of your squat at the same time as completing the rowing motion", "Keep your core tight throughout the entire movement to protect your lower back and maintain stability", "Use a weight that allows you to control both the squat and rowing portions without compromising form", "Focus on the eccentric portion of both movements by controlling the descent into the squat and the extension of your arms"]', '911577a1-55e3-4bf2-b7a0-6456422c3393', 'squat-to-cable-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('25782450-84ad-4098-a8a6-bbd455e9188f', 'Squat Thruster', NULL, 'سكوات ثراستر', 'Squat thruster', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/squat-thruster.mp4', NULL, NULL, NULL, '/videos/thumbnails/squat-thruster.jpg', NULL, '["Assure-toi que tes genoux suivent la ligne de tes orteils pendant tout le mouvement pour éviter les blessures.", "Concentre-toi sur des atterrissages doux en fléchissant les genoux au contact pour réduire le stress sur les articulations.", "Maintiens une bonne profondeur de squat avec les cuisses parallèles au sol avant de t''élancer vers le haut.", "Utilise tes bras comme des moteurs en les poussant vers le haut durant la phase de saut.", "Commence avec des mouvements lents et contrôlés avant de passer à des répétitions plus rapides et explosives."]', '["Ne pas garder le dos droit pendant le squat. ", "Atterrir sur des jambes tendues au lieu de fléchies."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "squat thruster"]', true, '2026-04-03 12:24:59.446036+00', '2026-04-03 12:24:59.446036+00', 'Position de départ : Tiens-toi debout, pieds écartés à la largeur des épaules, bras le long du corps ou mains jointes devant la poitrine. Exécution : Descends en squat profond, puis propulse-toi avec puissance en poussant sur tes talons pour sauter en levant les bras au-dessus de ta tête. Atterre en douceur et enchaîne directement avec la répétition suivante.', '["Ne pas garder le dos droit pendant le squat. ", "Atterrir sur des jambes tendues au lieu de fléchies."]', true, '["Stand with feet shoulder-width apart and engage your core throughout the movement", "Lower into a squat by pushing your hips back and bending your knees until thighs are parallel to the floor", "Keep your chest up and weight distributed evenly across your feet during the squat phase", "Explosively drive through your heels to jump up while simultaneously extending your arms overhead", "Land softly on the balls of your feet with bent knees to absorb the impact", "Immediately flow into the next squat to maintain continuous movement"]', '["Tiens-toi debout, pieds écartés à la largeur des épaules et engage ton core durant tout le mouvement.", "Descends en squat en reculant les hanches et en fléchissant les genoux jusqu''à ce que les cuisses soient parallèles au sol.", "Garde le torse droit et le poids réparti uniformément sur tes pieds pendant la phase de squat.", "Pousse explosivement sur tes talons pour sauter en étendant les bras au-dessus de ta tête.", "Atterris en douceur sur la pointe des pieds avec les genoux fléchis pour amortir l''impact.", "Continue immédiatement avec le prochain squat pour garder un mouvement fluide."]', '["Assure-toi que tes genoux suivent la ligne de tes orteils pendant tout le mouvement pour éviter les blessures.", "Concentre-toi sur des atterrissages doux en fléchissant les genoux au contact pour réduire le stress sur les articulations.", "Maintiens une bonne profondeur de squat avec les cuisses parallèles au sol avant de t''élancer vers le haut.", "Utilise tes bras comme des moteurs en les poussant vers le haut durant la phase de saut.", "Commence avec des mouvements lents et contrôlés avant de passer à des répétitions plus rapides et explosives."]', '["Keep your knees tracking in line with your toes throughout the entire movement to prevent injury", "Focus on soft landings by bending your knees upon impact to reduce stress on joints", "Maintain proper squat depth with thighs parallel to the floor before exploding upward", "Use your arms as momentum builders by driving them overhead during the jump phase", "Start with slower, controlled movements before progressing to faster, more explosive repetitions"]', 'f4484f32-c4a6-4111-8681-7d3d05a43f81', 'squat-thruster', NULL, NULL);
INSERT INTO public.exercises VALUES ('614d9125-3215-4d30-a87a-eba2811f2359', 'Curl debout avec ez-bar', NULL, NULL, 'Standing EZ Bar Curl', 'Biceps', '[]', 'Biceps', 'Beginner', 1, '/videos/biceps/standing-ez-bar-curl.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-ez-bar-curl.jpg', NULL, '["Garde tes poignets droits et alignés avec tes avant-bras pour éviter de te blesser", "Concentre-toi sur la contraction de tes biceps en haut du mouvement pour une activation musculaire optimale", "Contrôle bien la descente en prenant 2-3 secondes pour abaisser le poids", "Évite de te pencher en arrière ou d''utiliser le bas du dos pour aider au levage", "La prise inclinée de l''ez-bar diminue le stress sur les poignets par rapport à une barre droite"]', '["Utiliser trop d''élan pour lever la barre", "Laisser les coudes s''écarter des côtés"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "barbell", "standing ez bar curl"]', true, '2026-04-03 12:24:59.534661+00', '2026-04-03 12:24:59.534661+00', 'Place-toi debout, saisis l''e-bar avec les mains en supination. En fléchissant les coudes, soulève la barre jusqu''à tes épaules et redescends doucement.', '["Utiliser trop d''élan pour lever la barre", "Laisser les coudes s''écarter des côtés"]', true, '["Stand with feet shoulder-width apart and grip the EZ bar with an underhand grip, hands positioned on the angled sections", "Keep your core engaged and maintain a straight posture with shoulders back and chest up", "Position your elbows close to your sides and keep them stationary throughout the movement", "Curl the bar up by contracting your biceps until your forearms are vertical and you feel peak contraction", "Slowly lower the bar back to the starting position with control, maintaining tension in your biceps", "Avoid swinging or using momentum to lift the weight"]', '["Écarte tes pieds à la largeur des épaules et prends l''ez-bar avec une prise en supination, les mains sur les sections inclinées", "Garde ton tronc bien gainé et adopte une posture droite, les épaules en arrière et la poitrine en avant", "Garde tes coudes près de tes côtés et immobiles durant tout l''exercice", "Contracte tes biceps pour faire monter la barre jusqu''à ce que tes avant-bras soient verticaux, et ressens la contraction maximale", "Redescends la barre lentement vers la position de départ, en maintenant la tension dans tes biceps", "Ne te penche pas en arrière et n''utilise pas l''élan pour soulever le poids"]', '["Garde tes poignets droits et alignés avec tes avant-bras pour éviter de te blesser", "Concentre-toi sur la contraction de tes biceps en haut du mouvement pour une activation musculaire optimale", "Contrôle bien la descente en prenant 2-3 secondes pour abaisser le poids", "Évite de te pencher en arrière ou d''utiliser le bas du dos pour aider au levage", "La prise inclinée de l''ez-bar diminue le stress sur les poignets par rapport à une barre droite"]', '["Keep your wrists straight and aligned with your forearms to prevent strain", "Focus on squeezing your biceps at the top of the movement for maximum muscle activation", "Control the negative portion of the lift by taking 2-3 seconds to lower the weight", "Avoid leaning back or using your lower back to assist with the lift", "The EZ bar''s angled grip reduces wrist stress compared to a straight barbell"]', '5bd45b94-2926-4051-b4cb-51a66f46ecf8', 'standing-ez-bar-curl', NULL, NULL);
INSERT INTO public.exercises VALUES ('3058b130-0f6b-4ec0-8ac7-74713b6ac03d', 'Plank Jacks', NULL, 'نططات البلانك', 'Plank jacks', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-jacks.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-jacks.jpg', NULL, '["Garde ton core bien serré et évite de laisser tes hanches s''affaisser ou se soulever.", "Atterris doucement pour réduire l''impact sur les articulations.", "Assure-toi d''avoir une bonne forme de plank avec les mains bien ancrées et les épaules stables.", "Commence lentement et augmente la vitesse au fur et à mesure que tu maîtrises le geste.", "Arrête immédiatement si tu ressens des douleurs dans le bas du dos ou si ta forme se dégrade."]', '["Ne pas engager correctement le core, ce qui peut mener à une mauvaise posture.", "Faire des sauts trop grands ou trop petits, ce qui perturbe l''équilibre."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank jacks"]', true, '2026-04-03 12:24:58.306569+00', '2026-04-03 12:24:58.306569+00', 'Mets-toi en position de plank, les mains bien ancrées au sol, le corps bien droit et les pieds serrés. Prépare-toi à sauter !', '["Ne pas engager correctement le core, ce qui peut mener à une mauvaise posture.", "Faire des sauts trop grands ou trop petits, ce qui perturbe l''équilibre."]', true, '["Start in a high plank position with hands directly under shoulders and body in a straight line", "Keep your core engaged and maintain a neutral spine throughout the entire movement", "Jump both feet out wide to about shoulder-width apart, landing softly on the balls of your feet", "Immediately jump your feet back together to the starting position", "Maintain steady breathing and keep your upper body stable during the jumping motion", "Continue the jumping motion for the desired number of repetitions or time duration"]', '["Commence en position de plank, les mains sous les épaules et le corps aligné.", "Engage ton core et garde une colonne vertébrale neutre pendant tout le mouvement.", "Saute en écartant les pieds à la largeur des épaules, en atterrissant délicatement sur les avant-pieds.", "Reviens immédiatement en position de départ en rassemblant tes pieds.", "Respire normalement et garde le haut du corps stable pendant les sauts.", "Continue ce mouvement pendant le nombre de répétitions souhaité ou la durée définie."]', '["Garde ton core bien serré et évite de laisser tes hanches s''affaisser ou se soulever.", "Atterris doucement pour réduire l''impact sur les articulations.", "Assure-toi d''avoir une bonne forme de plank avec les mains bien ancrées et les épaules stables.", "Commence lentement et augmente la vitesse au fur et à mesure que tu maîtrises le geste.", "Arrête immédiatement si tu ressens des douleurs dans le bas du dos ou si ta forme se dégrade."]', '["Keep your core tight and avoid letting your hips sag or pike up during the movement", "Land softly on your feet to reduce impact on joints", "Maintain proper plank form with hands firmly planted and shoulders stable", "Start with a slower pace and gradually increase speed as you master the movement", "Stop immediately if you feel strain in your lower back or cannot maintain proper form"]', '39a6eaa7-efb4-455f-942f-e53ed5a9b526', 'plank-jacks', NULL, NULL);
INSERT INTO public.exercises VALUES ('97697d1d-095a-4634-a018-ba0341824888', 'Tirage Haut à Câble en Position Debout', NULL, NULL, 'Standing High Cable Row', 'Back', '[]', 'Back', 'Intermediate', 4, '/videos/back/standing-high-cable-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-high-cable-row.jpg', NULL, '["Garde la poitrine relevée et les épaules en arrière tout au long du mouvement pour préserver une bonne posture.", "Concentre-toi sur l''utilisation de tes muscles dorsaux plutôt que de tes bras en initiant le mouvement avec tes omoplates.", "Évite de te pencher en arrière ou d''utiliser de l''élan - maintiens une position stable et droite.", "Contrôle le poids lors de chaque phase, que ce soit pour tirer ou ramener, afin de maximiser l''engagement musculaire.", "Garde une légère flexion au niveau des coudes et évite de verrouiller complètement tes bras au départ."]', '["Pencher le torse en arrière pendant le tirage.", "Tirer avec les bras au lieu de se concentrer sur le dos.", "Utiliser de l''élan au lieu d''un mouvement contrôlé."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "cable", "standing high cable row"]', true, '2026-04-03 12:24:59.556294+00', '2026-04-03 12:24:59.556294+00', 'Mets-toi face à une machine à poulies hautes, main en pronation. Tire la poignée vers le haut de ta poitrine en gardant les coudes vers l''extérieur, puis retourne doucement à la position de départ.', '["Pencher le torse en arrière pendant le tirage.", "Tirer avec les bras au lieu de se concentrer sur le dos.", "Utiliser de l''élan au lieu d''un mouvement contrôlé."]', true, '["Set the cable pulley to upper chest height and attach a straight bar or rope handle", "Stand arm''s length away from the machine with feet shoulder-width apart and slight bend in knees", "Grasp the handle with both hands using an overhand grip, arms extended forward", "Pull the handle straight back toward your upper chest while squeezing shoulder blades together", "Hold the contraction briefly at your chest, feeling the squeeze between your shoulder blades", "Slowly return the weight to starting position with controlled movement, maintaining tension"]', '["Régle la poulie à la hauteur de ton haut de poitrine et fixe une barre droite ou une poignée de corde.", "Place-toi à une distance d''un bras de la machine, pieds écartés à la largeur des épaules et légèrement fléchis aux genoux.", "Saisis la poignée avec les deux mains en pronation, bras tendus vers l''avant.", "Tire la poignée directement vers ton haut de poitrine en serrant les omoplates ensemble.", "Maintiens la contraction un instant au niveau de ta poitrine, ressens la pression entre tes omoplates.", "Ramène lentement le poids à la position de départ avec un mouvement contrôlé, en maintenant la tension."]', '["Garde la poitrine relevée et les épaules en arrière tout au long du mouvement pour préserver une bonne posture.", "Concentre-toi sur l''utilisation de tes muscles dorsaux plutôt que de tes bras en initiant le mouvement avec tes omoplates.", "Évite de te pencher en arrière ou d''utiliser de l''élan - maintiens une position stable et droite.", "Contrôle le poids lors de chaque phase, que ce soit pour tirer ou ramener, afin de maximiser l''engagement musculaire.", "Garde une légère flexion au niveau des coudes et évite de verrouiller complètement tes bras au départ."]', '["Keep your chest up and shoulders back throughout the entire movement to maintain proper posture", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Avoid leaning back or using momentum - maintain a stable, upright position", "Control the weight on both the pulling and returning phases to maximize muscle engagement", "Keep a slight bend in your elbows and avoid fully locking out your arms at the starting position"]', 'e6c47dc5-3924-4b1d-a8ac-deb2ec1730aa', 'standing-high-cable-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('1f8a9f0b-8042-4aaa-b561-9ad7876f741c', 'Planche latérale (gauche)', NULL, NULL, 'Side plank pose (left)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-plank-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-plank-pose-left.jpg', NULL, '["Appuie fermement sur ta main de support.", "Active bien ta sangle abdominale et tes obliques.", "Pour faciliter, plie ton genou du bas et pose-le au sol."]', '["Ne pas garder le corps aligné.", "Lâcher la pression avec la main de support."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side plank pose (left)"]', true, '2026-04-03 12:24:59.065559+00', '2026-04-03 12:24:59.065559+00', 'Renforce ton gainage et travaille tes obliques avec cette planche latérale.', '["Ne pas garder le corps aligné.", "Lâcher la pression avec la main de support."]', true, '["From Plank Pose, shift your weight onto one hand and the side of the corresponding foot.", "Stack your feet and open your top arm toward the ceiling.", "Keep your body in a straight line from head to feet.", "Hold and breathe steadily."]', '["Depuis la planche, déplace ton poids sur une main et le côté du pied correspondant.", "Aligne tes pieds et dirige ton bras du haut vers le plafond.", "Maintiens ton corps en ligne droite de la tête aux pieds.", "Reste en position et respire régulièrement."]', '["Appuie fermement sur ta main de support.", "Active bien ta sangle abdominale et tes obliques.", "Pour faciliter, plie ton genou du bas et pose-le au sol."]', '["Press firmly through your supporting hand.", "Engage your core and obliques.", "Modify by lowering your bottom knee to the floor."]', 'd0b4d724-b764-434e-a595-98c0d1ff76fb', 'side-plank-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('ed63ef1b-9046-4f3f-a4f7-07ccce629754', 'Taps d''épaules en planche ours', NULL, 'ضربات الكتيفين في وضعية الدب', 'Bear plank shoulder taps - 30', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/bear-plank-shoulder-taps-30.mp4', NULL, NULL, NULL, '/videos/thumbnails/bear-plank-shoulder-taps-30.jpg', NULL, '["Garde les hanches bien à niveau, évite de basculer ou de faire des mouvements de côté pendant les taps d''épaules", "Respire steady, ne retiens pas ton souffle !", "Assure-toi que les genoux restent toujours sur le même niveau au-dessus du sol durant tout l''exercice", "Concentre-toi sur des mouvements lents et contrôlés au lieu de te précipiter dans les répétitions", "Répartis ton poids de manière égale entre tes mains et l''avant de tes pieds pour une meilleure stabilité"]', '["Hanches qui s''affaissent ou s''élèvent trop pendant l''exercice", "Se dépêcher et perdre en contrôle des mouvements"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "bear plank shoulder taps - 30"]', true, '2026-04-03 12:24:55.673628+00', '2026-04-03 12:24:55.673628+00', 'Mets-toi en position de planche ours, les mains sous les épaules et les genoux soulevés juste au-dessus du sol. Engage ton core et garde une ligne droite de la tête aux talons. Ce mouvement va renforcer ton tronc tout en améliorant ta stabilité !', '["Hanches qui s''affaissent ou s''élèvent trop pendant l''exercice", "Se dépêcher et perdre en contrôle des mouvements"]', true, '["Start in a tabletop position with hands under shoulders and knees under hips", "Lift knees 1-2 inches off the ground while keeping knees bent at 90 degrees", "Engage your core and maintain a neutral spine position", "Slowly lift your right hand and tap your left shoulder while keeping hips square", "Return right hand to the ground and repeat with left hand tapping right shoulder", "Continue alternating sides while maintaining the bear plank position throughout"]', '["Commence en position de planche ours, les mains sous les épaules et les genoux sous les hanches", "Soulève les genoux de quelques centimètres, les jambes fléchies à 90 degrés", "Engage ton core et garde une colonne vertébrale neutre", "Lève lentement la main droite et touche l''épaule gauche tout en maintenant les hanches carrées", "Ramène la main droite au sol et fais de même avec la main gauche", "Continue d''alterner les côtés tout en restant en position de planche ours"]', '["Garde les hanches bien à niveau, évite de basculer ou de faire des mouvements de côté pendant les taps d''épaules", "Respire steady, ne retiens pas ton souffle !", "Assure-toi que les genoux restent toujours sur le même niveau au-dessus du sol durant tout l''exercice", "Concentre-toi sur des mouvements lents et contrôlés au lieu de te précipiter dans les répétitions", "Répartis ton poids de manière égale entre tes mains et l''avant de tes pieds pour une meilleure stabilité"]', '["Keep hips level and avoid rotating or swaying from side to side during the shoulder taps", "Maintain steady breathing and avoid holding your breath during the movement", "Keep knees hovering consistently off the ground throughout the entire exercise", "Focus on slow, controlled movements rather than rushing through the repetitions", "Distribute weight evenly between your hands and balls of your feet for better stability"]', 'f2fef2bc-353c-4f3b-b7c3-ee5d63e2a87b', 'bear-plank-shoulder-taps-30', NULL, NULL);
INSERT INTO public.exercises VALUES ('ce6dd0cf-2e2c-4bf6-a0d6-7101cd7a09d7', 'Extension Triceps à Un Bras Debout (Droit)', NULL, NULL, 'Standing One-Arm DBl Triceps Extension (R)', 'Triceps', '[]', 'Triceps', 'Intermediate', 2, '/videos/triceps/standing-one-arm-dbl-triceps-extension-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-one-arm-dbl-triceps-extension-r.jpg', NULL, '["Garde ton bras supérieur vertical et immobile - seul l''avant-bras doit bouger", "Contrôle le poids à la descente comme à la montée pour éviter les blessures", "Évite d''arc-bouter ton dos en maintenant une colonne vertébrale neutre et un tronc engagé", "Stoppe ta descente lorsque tu ressens un étirement confortable dans tes triceps, généralement quand ton avant-bras est parallèle au sol", "Utilise ta main non active pour soutenir ton bras actif si nécessaire pour la stabilité"]', '["Ne pas plier le coude uniquement, ce qui peut compromettre le mouvement", "Laisser le bras supérieur bouger au lieu de rester immobile"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "dumbbell", "standing one-arm dbl triceps extension (r)"]', true, '2026-04-03 12:24:59.595053+00', '2026-04-03 12:24:59.595053+00', 'Position de départ: Tiens-toi debout, pieds écartés à la largeur des épaules, un haltère dans la main droite, bras entièrement tendu au-dessus de ta tête. Exécution: Abaisse l''haltère derrière ta tête en pliant uniquement au niveau du coude, puis ramène-le à la position de départ.', '["Ne pas plier le coude uniquement, ce qui peut compromettre le mouvement", "Laisser le bras supérieur bouger au lieu de rester immobile"]', true, '["Stand with feet shoulder-width apart and core engaged for stability", "Grip the dumbbell firmly with your right hand and press it directly overhead with arm fully extended", "Keep your upper arm stationary and close to your head throughout the movement", "Slowly lower the dumbbell behind your head by bending only at the elbow until you feel a stretch in your triceps", "Press the dumbbell back to the starting position by extending your elbow", "Complete all repetitions on the right arm before switching to the left"]', '["Tiens-toi debout, pieds à la largeur des épaules, muscles du tronc engagés pour la stabilité", "Saisis l''haltère fermement avec ta main droite et pousse-le directement au-dessus de ta tête, bras tendu", "Garde ton bras supérieur immobile, près de ta tête pendant tout le mouvement", "Abaisse lentement l''haltère derrière ta tête en pliant uniquement le coude jusqu''à ressentir un étirement dans tes triceps", "Remonte l''haltère à la position de départ en étendant ton coude", "Effectue toutes les répétitions du bras droit avant de passer au bras gauche"]', '["Garde ton bras supérieur vertical et immobile - seul l''avant-bras doit bouger", "Contrôle le poids à la descente comme à la montée pour éviter les blessures", "Évite d''arc-bouter ton dos en maintenant une colonne vertébrale neutre et un tronc engagé", "Stoppe ta descente lorsque tu ressens un étirement confortable dans tes triceps, généralement quand ton avant-bras est parallèle au sol", "Utilise ta main non active pour soutenir ton bras actif si nécessaire pour la stabilité"]', '["Keep your upper arm vertical and stationary - only the forearm should move", "Control the weight on both the lowering and lifting phases to prevent injury", "Avoid arching your back by maintaining a neutral spine and engaged core", "Stop the descent when you feel a comfortable stretch in your triceps, typically when your forearm is parallel to the floor", "Use your non-working hand to support your working arm if needed for stability"]', 'e17c7349-85bc-4608-a897-d8d2841a8b38', 'standing-one-arm-dbl-triceps-extension-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('fb1f1ba3-d07b-4c16-bb3c-a7f53f4ff43a', 'Étirement du quadriceps debout', NULL, 'تمارين إطالة لعضلة الفخذ الأمامية في وضعية الوقوف', 'Standing Quad Stretch (L)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/standing-quad-stretch-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-quad-stretch-l.jpg', NULL, '["Garde la jambe debout légèrement fléchie pour maintenir l''équilibre et réduire la tension au genou", "Évite de tirer ton pied trop fortement - utilise une pression douce et contrôlée pour éviter les blessures musculaires", "Maintiens le torse droit et évite de te pencher en avant pour maximiser l''étirement des quadriceps", "Si tu ne peux pas atteindre ta cheville, utilise une serviette ou une sangle autour de ton pied pour t''aider", "Arrête immédiatement si tu ressens une douleur vive au niveau du genou ou de la hanche."]', '["Pencher le torse en avant au lieu de rester droit", "Tirer le pied trop fortement ce qui peut causer une blessure"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "standing quad stretch (l)"]', true, '2026-04-03 12:24:59.609732+00', '2026-04-03 12:24:59.609732+00', 'Position de départ : Tiens-toi bien droit, les pieds écartés à la largeur des hanches. Si besoin, utilise un mur ou une chaise pour t''équilibrer. Action : Plie le genou gauche et tire ton pied gauche vers tes fessiers avec ta main gauche, en gardant une posture droite.', '["Pencher le torse en avant au lieu de rester droit", "Tirer le pied trop fortement ce qui peut causer une blessure"]', true, '["Stand with feet hip-width apart and engage your core for stability", "Place your right hand on a wall or chair for balance support", "Bend your left knee and grasp your left ankle or foot with your left hand", "Gently pull your heel toward your glutes while keeping your thighs parallel", "Hold the stretch for 20-30 seconds while breathing normally", "Release slowly and repeat on the opposite side"]', '["Écarte les pieds à la largeur des hanches et engage ton tronc pour la stabilité", "Place ta main droite sur un mur ou une chaise pour t''aider à garder l''équilibre", "Plie le genou gauche et attrape ta cheville ou ton pied avec ta main gauche", "Tire doucement ton talon vers tes fessiers tout en maintenant les cuisses parallèles", "Maintiens l''étirement pendant 20 à 30 secondes en respirant normalement", "Relâche lentement et répète de l''autre côté"]', '["Garde la jambe debout légèrement fléchie pour maintenir l''équilibre et réduire la tension au genou", "Évite de tirer ton pied trop fortement - utilise une pression douce et contrôlée pour éviter les blessures musculaires", "Maintiens le torse droit et évite de te pencher en avant pour maximiser l''étirement des quadriceps", "Si tu ne peux pas atteindre ta cheville, utilise une serviette ou une sangle autour de ton pied pour t''aider", "Arrête immédiatement si tu ressens une douleur vive au niveau du genou ou de la hanche."]', '["Keep your standing leg slightly bent to maintain balance and reduce strain on the knee", "Avoid pulling your foot too aggressively - use gentle, controlled pressure to prevent muscle strain", "Maintain an upright torso position rather than leaning forward to maximize the quadriceps stretch", "If you cannot reach your ankle, use a towel or strap around your foot for assistance", "Stop immediately if you experience any sharp pain in the knee or hip joint"]', '83df9077-41ca-4376-b5de-f4ea0393b6f8', 'standing-quad-stretch-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('f6bea3d7-6d5e-4fcf-8d6d-2f699e5f8524', 'Élévations de genoux', NULL, 'رفع الركبة', 'Knee raises', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/knee-raises.mp4', NULL, NULL, NULL, '/videos/thumbnails/knee-raises.jpg', NULL, '["Garde ton ventre contracté tout au long du mouvement pour maintenir ta stabilité et maximiser l''efficacité", "Évite de pencher en arrière ou d''utiliser l''élan pour lever tes genoux plus haut", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour bien engager tes muscles abdominaux", "Maintiens une bonne posture avec la poitrine en avant et les épaules en arrière durant l''exercice", "Si tu as des difficultés d''équilibre, fais l''exercice près d''un mur ou d''une chaise pour un léger soutien"]', '["Ne pas contracter le ventre et perdre la stabilité", "Soulever les genoux trop rapidement sans contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "knee raises"]', true, '2026-04-03 12:24:57.479+00', '2026-04-03 12:24:57.479+00', 'Position de départ : Tiens-toi debout, les pieds à la largeur des hanches, les mains sur les hanches ou le long des côtés pour l''équilibre. Exécution : Lève un genou vers ta poitrine aussi haut que tu le peux, puis redescends-le avec contrôle et fais de même de l''autre côté.', '["Ne pas contracter le ventre et perdre la stabilité", "Soulever les genoux trop rapidement sans contrôle"]', true, '["Stand tall with your core engaged and shoulders back", "Lift your right knee up toward your chest, aiming to bring your thigh parallel to the floor", "Hold briefly at the top of the movement", "Lower your leg back down with control to the starting position", "Repeat the movement with your left leg", "Continue alternating legs for the desired number of repetitions"]', '["Tiens-toi droit, engage ton ventre et garde les épaules en arrière", "Lève ton genou droit vers ta poitrine, vise à amener ta cuisse parallèle au sol", "Maintiens la position brièvement en haut du mouvement", "Redescends ta jambe avec contrôle jusqu''à la position de départ", "Répète le mouvement avec ta jambe gauche", "Continue à alterner les jambes pour le nombre de répétitions souhaité"]', '["Garde ton ventre contracté tout au long du mouvement pour maintenir ta stabilité et maximiser l''efficacité", "Évite de pencher en arrière ou d''utiliser l''élan pour lever tes genoux plus haut", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour bien engager tes muscles abdominaux", "Maintiens une bonne posture avec la poitrine en avant et les épaules en arrière durant l''exercice", "Si tu as des difficultés d''équilibre, fais l''exercice près d''un mur ou d''une chaise pour un léger soutien"]', '["Keep your core tight throughout the entire movement to maintain stability and maximize effectiveness", "Avoid leaning backward or using momentum to lift your knees higher", "Focus on controlled movements rather than speed to properly engage the abdominal muscles", "Maintain good posture with chest up and shoulders back throughout the exercise", "If balance is challenging, perform the exercise near a wall or chair for light support"]', 'f50de65b-ab30-4b37-a472-d4cab681916c', 'knee-raises', NULL, NULL);
INSERT INTO public.exercises VALUES ('385b8845-35f7-4799-9912-11d2e58eedc4', 'Fentes alternées enchaînées avec Burpees (sans saut)', NULL, NULL, 'Switching lunges into Burpees (no jump)', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 16, '/videos/quadriceps/switching-lunges-into-burpees-no-jump.mp4', NULL, NULL, NULL, '/videos/thumbnails/switching-lunges-into-burpees-no-jump.jpg', NULL, '["Assure-toi que ton genou avant reste au-dessus de tes orteils pendant les fentes pour protéger l''articulation du genou.", "Maintiens une position de planche solide pendant la partie burpee pour bien engager ton core.", "Réalise les transitions entre les exercices avec contrôle pour garantir une bonne forme et éviter les blessures.", "Concentre-toi sur un atterrissage doux en reculant et en avançant pour réduire l''impact sur tes articulations.", "Garde la poitrine relevée et les épaules en arrière tout au long du mouvement."]', '["Genoux qui dépassent les orteils pendant les fentes, ce qui peut causer des douleurs.", "Position de planche non alignée, entraînant une mauvaise exécution des pompes."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "switching lunges into burpees (no jump)"]', true, '2026-04-03 12:24:59.704055+00', '2026-04-03 12:24:59.704055+00', 'Prépare-toi à travailler tes quadriceps comme jamais ! On commence debout, les pieds écartés à la largeur des hanches, bras le long du corps. Prêt ? C''est parti !', '["Genoux qui dépassent les orteils pendant les fentes, ce qui peut causer des douleurs.", "Position de planche non alignée, entraînant une mauvaise exécution des pompes."]', true, '["Begin with alternating reverse lunges, stepping one foot back into a lunge position while keeping your front knee aligned over your ankle", "Complete the desired number of lunges on each leg, maintaining proper form throughout", "After finishing the lunges, place both hands on the ground and step your right foot back, then your left foot back into a plank position", "Perform one push-up while maintaining a straight line from head to heels", "Step your left foot forward, then your right foot forward to return to a squat position", "Stand up straight to complete one full repetition of the exercise combination"]', '["Commence par des fentes arrières alternées, recule une jambe en veillant à ce que ton genou avant soit bien au-dessus de ta cheville.", "Effectue le nombre de répétitions souhaité sur chaque jambe en gardant une bonne posture.", "Après les fentes, place tes mains au sol et recule ton pied droit, puis ton pied gauche en position de planche.", "Réalise une pompe en gardant ton corps bien aligné de la tête aux talons.", "Rappelle ton pied gauche, puis ton pied droit pour revenir en position accroupie.", "Redresse-toi pour compléter une répétition de l''enchaînement."]', '["Assure-toi que ton genou avant reste au-dessus de tes orteils pendant les fentes pour protéger l''articulation du genou.", "Maintiens une position de planche solide pendant la partie burpee pour bien engager ton core.", "Réalise les transitions entre les exercices avec contrôle pour garantir une bonne forme et éviter les blessures.", "Concentre-toi sur un atterrissage doux en reculant et en avançant pour réduire l''impact sur tes articulations.", "Garde la poitrine relevée et les épaules en arrière tout au long du mouvement."]', '["Keep your front knee tracking over your toes during lunges to protect the knee joint", "Maintain a strong plank position during the burpee portion to engage your core effectively", "Control the transition between exercises to maintain proper form and prevent injury", "Focus on landing softly when stepping back and forward to reduce impact on joints", "Keep your chest up and shoulders back throughout the entire movement sequence"]', '909e8b98-9e33-4a45-8bfa-3b0d4a9cef56', 'switching-lunges-into-burpees-no-jump', NULL, NULL);
INSERT INTO public.exercises VALUES ('38dbdafd-3789-4412-b1e0-5a1030bb4be5', 'Plank SeeSaw', NULL, 'تأرجح البلانك', 'Plank SeeSaw', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-seesaw.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-seesaw.jpg', NULL, '["Garde ton core bien contracté pendant tout le mouvement pour protéger ton bas du dos", "Effectue le mouvement lentement et avec contrôle - évite les mouvements brusques", "Respire régulièrement et n''oublie pas de ne pas retenir ta respiration pendant la bascule", "Arrête-toi si tu sens que ta technique se dégrade ou que tes hanches commencent à s''affaisser", "Concentre-toi sur la qualité du mouvement plutôt que sur la vitesse ou la durée"]', '["Laisser les hanches s''affaisser ou remonter trop haut", "Effectuer des mouvements rapides et incontrôlés"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank seesaw"]', true, '2026-04-03 12:24:58.335642+00', '2026-04-03 12:24:58.335642+00', 'Position de départ : Commence en position de planche sur les avant-bras, coudes sous les épaules, corps bien droit de la tête aux talons. Exécution : Bascule d''avant en arrière de manière contrôlée tout en maintenant la position de planche et l''engagement du core.', '["Laisser les hanches s''affaisser ou remonter trop haut", "Effectuer des mouvements rapides et incontrôlés"]', true, '["Start in a forearm plank with elbows directly under shoulders and forearms flat on the ground", "Keep your body in a straight line from head to heels with core engaged", "Slowly rock your body forward, shifting weight toward your hands and moving shoulders past your elbows", "Rock back to the starting position by shifting weight back toward your feet", "Continue the seesaw motion in a slow, controlled rhythm", "Maintain the plank position throughout without letting hips sag or pike up"]', '["Commence en position de planche sur les avant-bras avec les coudes directement sous les épaules et les avant-bras au sol", "Garde ton corps en ligne droite de la tête aux talons, le core bien engagé", "Bascule lentement ton corps vers l''avant, déplaçant ton poids vers tes mains et amenant tes épaules au-delà de tes coudes", "Reviens à la position de départ en déplaçant ton poids vers tes pieds", "Continue le mouvement de bascule dans un rythme lent et contrôlé", "Maintiens la position de planche tout au long de l''exercice sans laisser tes hanches s''affaisser ou se relever"]', '["Garde ton core bien contracté pendant tout le mouvement pour protéger ton bas du dos", "Effectue le mouvement lentement et avec contrôle - évite les mouvements brusques", "Respire régulièrement et n''oublie pas de ne pas retenir ta respiration pendant la bascule", "Arrête-toi si tu sens que ta technique se dégrade ou que tes hanches commencent à s''affaisser", "Concentre-toi sur la qualité du mouvement plutôt que sur la vitesse ou la durée"]', '["Keep your core tight throughout the entire movement to protect your lower back", "Move slowly and with control - avoid quick or jerky motions", "Breathe steadily and don''t hold your breath during the rocking motion", "Stop if you feel your form breaking down or if your hips start to sag", "Focus on the quality of movement rather than speed or duration"]', 'f6489ee0-7630-4041-ae1d-8e620b58883b', 'plank-seesaw', NULL, NULL);
INSERT INTO public.exercises VALUES ('99d61ca7-71d4-4059-b287-8231ae24e4d9', 'Planche latérale', NULL, NULL, 'Sideplank', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/sideplank.mp4', NULL, NULL, NULL, '/videos/thumbnails/sideplank.jpg', NULL, '["Contracte tes fessiers", "Garde le cou dans une position neutre", "Respire normalement", "Évite de lever trop haut tes hanches", "Augmente le temps progressivement"]', '["Hanches qui s''affaissent", "Position du cou incorrecte"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "sideplank"]', true, '2026-04-03 12:24:59.156812+00', '2026-04-03 12:24:59.156812+00', 'Renforce ton sangle abdominale avec cet exercice incontournable !', '["Hanches qui s''affaissent", "Position du cou incorrecte"]', true, '["Forearms on floor, elbows under shoulders", "Body straight from head to heels", "Hold position", "Keep core tight, don''t let hips sag"]', '["Avant-bras au sol, coudes alignés sous les épaules", "Corps droit de la tête aux talons", "Maintiens la position", "Contracte bien tes abdominaux, évite que tes hanches ne s''affaissent"]', '["Contracte tes fessiers", "Garde le cou dans une position neutre", "Respire normalement", "Évite de lever trop haut tes hanches", "Augmente le temps progressivement"]', '["Squeeze glutes", "Keep neck neutral", "Breathe normally", "Don''t raise hips too high", "Build time gradually"]', '4150a3eb-5b70-4d2e-8cab-a27e70b3ef43', 'sideplank', NULL, NULL);
INSERT INTO public.exercises VALUES ('c519a94d-b9f6-48ff-943c-c75b0436df14', 'Posture de l''arbre (gauche)', NULL, 'وضعية الشجرة (اليسار)', 'Tree pose (left)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/tree-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/tree-pose-left.jpg', NULL, '["Presse ton pied et ta cuisse l''un contre l''autre.", "Garde ta jambe de soutien solide avec un léger pli au genou.", "Active ton abdominal pour plus de stabilité."]', '["Placer le pied sur le genou, ce qui fait pression sur l''articulation.", "Se pencher en avant ou en arrière pendant l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "tree pose (left)"]', true, '2026-04-03 12:24:59.760042+00', '2026-04-03 12:24:59.760042+00', 'Un exercice pour renforcer l''équilibre et la concentration tout en travaillant vos muscles', '["Placer le pied sur le genou, ce qui fait pression sur l''articulation.", "Se pencher en avant ou en arrière pendant l''exercice."]', true, '["Stand on one leg and place the other foot on your inner thigh or calf.", "Avoid placing your foot on the knee.", "Bring your palms together at your chest or raise them overhead.", "Focus on a fixed point for balance."]', '["Tiens-toi sur une jambe et place l''autre pied sur ta cuisse intérieure ou ton mollet.", "Évite de mettre ton pied sur le genou.", "Joins les paumes de tes mains devant ta poitrine ou lève-les au-dessus de ta tête.", "Concentre-toi sur un point fixe pour maintenir ton équilibre."]', '["Presse ton pied et ta cuisse l''un contre l''autre.", "Garde ta jambe de soutien solide avec un léger pli au genou.", "Active ton abdominal pour plus de stabilité."]', '["Press your foot and thigh into each other.", "Keep your standing leg strong with a micro-bend.", "Engage your core for stability."]', '267b3050-21ec-4d7b-b8b1-d85b88583123', 'tree-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('5c549d48-84fe-48b9-9431-9ee1e0fedade', 'Pompes Explosives', NULL, 'ضغطات متفجرة', 'Explosive push', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/explosive-push.mp4', NULL, NULL, NULL, '/videos/thumbnails/explosive-push.jpg', NULL, '["N''essayez cet exercice que si vous pouvez faire au moins 15 pompes classiques correctement", "Concentrez-vous sur le mouvement explosif vers le haut tout en gardant le contrôle lors de la descente", "Atterrissez avec des coudes souples et une sangle abdominale engagée pour éviter les blessures", "Commencez avec un petit nombre de répétitions et augmentez progressivement, car cet exercice est exigeant pour les articulations et les muscles", "Arrêtez immédiatement si vous ne pouvez pas maintenir une bonne forme d''atterrissage ou ressentez une gêne au niveau des articulations"]', '["Ne pas descendre suffisamment lors de la phase descendante", "Ne pas garder le corps rigide pendant l''explosive poussé"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "explosive push"]', true, '2026-04-03 12:24:56.678151+00', '2026-04-03 12:24:56.678151+00', 'Position de départ : Adoptez une position de pompes classique, mains légèrement plus larges que les épaules, corps en ligne droite des pieds à la tête. Exécution : Descendez votre poitrine vers le sol, puis poussez explosivement vers le haut avec toute votre force, de manière à ce que vos mains quittent le sol. Amortissez votre atterrissage et enchaînez immédiatement avec la répétition suivante.', '["Ne pas descendre suffisamment lors de la phase descendante", "Ne pas garder le corps rigide pendant l''explosive poussé"]', true, '["Start in a proper push-up position with core engaged and body aligned", "Lower yourself slowly and under control until chest nearly touches the ground", "Explosively push through your palms with maximum force to launch your upper body off the ground", "Keep your body rigid and hands ready to catch yourself as you land", "Land softly with slightly bent elbows to absorb impact", "Immediately lower into the next repetition without pausing"]', '["Commencez en position de pompe correcte, engagez votre sangle abdominale et alignez votre corps", "Descendez lentement et de manière contrôlée jusqu''à ce que votre poitrine frôle le sol", "Poussez de toutes vos forces à travers vos paumes pour propulser votre corps vers le haut", "Gardez votre corps rigide et vos mains prêtes à vous rattraper à l''atterrissage", "Atterrissez en douceur avec les coudes légèrement fléchis pour absorber l''impact", "Redescendez immédiatement pour la prochaine répétition sans pause"]', '["N''essayez cet exercice que si vous pouvez faire au moins 15 pompes classiques correctement", "Concentrez-vous sur le mouvement explosif vers le haut tout en gardant le contrôle lors de la descente", "Atterrissez avec des coudes souples et une sangle abdominale engagée pour éviter les blessures", "Commencez avec un petit nombre de répétitions et augmentez progressivement, car cet exercice est exigeant pour les articulations et les muscles", "Arrêtez immédiatement si vous ne pouvez pas maintenir une bonne forme d''atterrissage ou ressentez une gêne au niveau des articulations"]', '["Only attempt this exercise if you can perform at least 15 standard push-ups with proper form", "Focus on explosive upward movement while maintaining control during the lowering phase", "Land with soft elbows and engaged core to prevent injury upon impact", "Start with lower repetitions and build up gradually as this is highly demanding on joints and muscles", "Stop immediately if you cannot maintain proper landing form or feel joint discomfort"]', '74658f21-21bb-40f6-bf66-54aa7b499622', 'explosive-push', NULL, NULL);
INSERT INTO public.exercises VALUES ('37e28aa4-3b73-4052-a2a1-493c49792cd3', 'Kettlebell Swing', NULL, 'تأرجح بالكيتلبل', 'Kettlebell swing', 'Abs', '[]', 'Abs', 'Beginner', 128, '/videos/abs/kettlebell-swing.mp4', NULL, NULL, NULL, '/videos/thumbnails/kettlebell-swing.jpg', NULL, '["Engage ton core tout au long du mouvement pour protéger ton dos", "La puissance vient de tes hanches, pas de tes bras - concentre-toi sur le mouvement de poussée des hanches", "Garde le dos neutre, évite de courber le dos pendant l''exercice", "Garde les épaules en arrière et la poitrine relevée pendant l''exercice", "Atterris doucement sur tes talons lorsque le kettlebell redescend entre tes jambes"]', '["Ne pas engager le core, ce qui peut entraîner des douleurs lombaires", "Utiliser les bras au lieu des hanches pour le mouvement, ce qui réduit l''efficacité de l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "kettlebell", "kettlebell swing"]', true, '2026-04-03 12:24:57.40723+00', '2026-04-03 12:24:57.40723+00', 'Position de départ : Mets-toi debout, les pieds écartés à la largeur des épaules, en tenant le kettlebell à deux mains. Penche-toi légèrement en avant, les genoux un peu fléchis et le dos droit. Exécution : Pousse sur tes hanches pour faire monter le kettlebell tout en gardant le dos neutre et le core bien actif.', '["Ne pas engager le core, ce qui peut entraîner des douleurs lombaires", "Utiliser les bras au lieu des hanches pour le mouvement, ce qui réduit l''efficacité de l''exercice"]', true, '["Stand with feet shoulder-width apart and grip the kettlebell handle with both hands", "Hinge at the hips by pushing your hips back and bending knees slightly, keeping your back straight", "Allow the kettlebell to swing between your legs while maintaining control", "Drive your hips forward explosively to propel the kettlebell upward", "Keep your arms straight and let the momentum from your hips power the movement", "Control the kettlebell as it swings back down and repeat the hip hinge motion"]', '["Mets-toi debout, les pieds à la largeur des épaules et prends le kettlebell avec les deux mains", "Pousse tes hanches en arrière, genoux légèrement fléchis, et garde le dos droit", "Laisse le kettlebell osciller entre tes jambes en gardant le contrôle", "Pousse tes hanches vers l''avant avec force pour propulser le kettlebell vers le haut", "Garde les bras tendus et laisse l''élan de tes hanches alimenter le mouvement", "Contrôle le kettlebell lors de sa descente et répète le mouvement de flexion des hanches"]', '["Engage ton core tout au long du mouvement pour protéger ton dos", "La puissance vient de tes hanches, pas de tes bras - concentre-toi sur le mouvement de poussée des hanches", "Garde le dos neutre, évite de courber le dos pendant l''exercice", "Garde les épaules en arrière et la poitrine relevée pendant l''exercice", "Atterris doucement sur tes talons lorsque le kettlebell redescend entre tes jambes"]', '["Keep your core engaged throughout the entire movement to protect your lower back", "The power comes from your hips, not your arms - focus on the hip thrust motion", "Maintain a neutral spine and avoid rounding your back during the movement", "Keep your shoulders back and chest up throughout the exercise", "Land softly on your heels when the kettlebell swings back down between your legs"]', '3bbed598-16f4-4683-a751-10cc264b4bd6', 'kettlebell-swing', NULL, NULL);
INSERT INTO public.exercises VALUES ('f49918f1-7d9b-46b6-a5d1-e6c2fd7ebb80', 'Planche haute à planche latérale', NULL, NULL, 'High plank to side plank', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/high-plank-to-side-plank.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-plank-to-side-plank.jpg', NULL, '["Contracte les fessiers", "Garde le cou neutre", "Respire normalement", "Ne soulève pas les hanches trop haut", "Augmente progressivement le temps"]', '["Hanches qui s''affaissent", "Position du cou inconfortable", "Bras pas bien alignés", "Mauvaise respiration"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "high plank to side plank"]', true, '2026-04-03 12:24:57.124704+00', '2026-04-03 12:24:57.124704+00', 'Commence en position de planche haute, avec les mains sous les épaules et le corps en ligne droite de la tête aux talons. Tourne ton corps sur un côté, lève le bras supérieur vers le plafond tout en gardant la position de planche, puis reviens au centre et répète de l''autre côté.', '["Hanches qui s''affaissent", "Position du cou inconfortable", "Bras pas bien alignés", "Mauvaise respiration"]', true, '["Forearms on floor, elbows under shoulders", "Body straight from head to heels", "Hold position", "Keep core tight, don''t let hips sag"]', '["Avant-bras au sol, coudes sous les épaules", "Corps droit de la tête aux talons", "Maintenir la position", "Garde le gainage serré, ne laisse pas les hanches s''affaisser"]', '["Contracte les fessiers", "Garde le cou neutre", "Respire normalement", "Ne soulève pas les hanches trop haut", "Augmente progressivement le temps"]', '["Squeeze glutes", "Keep neck neutral", "Breathe normally", "Don''t raise hips too high", "Build time gradually"]', '9d525d35-2c5f-45c9-a88c-56f8526d2177', 'high-plank-to-side-plank', NULL, NULL);
INSERT INTO public.exercises VALUES ('c776fc44-77b9-4d0d-bd32-dbc59072f9ca', 'Étirement du haut du dos et des épaules (gauche)', NULL, 'تمارين توسيع العضلات في الظهر والكتف (اليسار)', 'Upper back and shoulder stretch (left)', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/upper-back-and-shoulder-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/upper-back-and-shoulder-left.jpg', NULL, '["Reste bien droit et évite de tourner ton dos pendant l''étirement", "Applique une pression douce et constante sans forcer l''étirement", "Sensation d''étirement dans l''épaule gauche et les muscles du haut du dos", "Respire normalement pendant toute la durée de l''étirement", "Arrête immédiatement si tu ressens une douleur aiguë"]', '["Ne pas garder la bonne posture en se penchant en avant", "Tirer trop fort sur le bras peut causer des tensions"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "upper back and shoulder stretch (left)"]', true, '2026-04-03 12:24:59.806678+00', '2026-04-03 12:24:59.806678+00', 'Position de départ : Tiens-toi droit avec les pieds écartés à la largeur des hanches. Éxécution : Étends ton bras gauche à travers ta poitrine et utilise ta main droite pour tirer doucement ton bras gauche vers ton corps, en étirant l''épaule et le haut du dos.', '["Ne pas garder la bonne posture en se penchant en avant", "Tirer trop fort sur le bras peut causer des tensions"]', true, '["Stand with feet hip-width apart and maintain good posture", "Extend your left arm straight across your chest at shoulder height", "Place your right hand on your left elbow or forearm", "Gently pull your left arm closer to your chest using your right hand", "Hold the stretch position while keeping your shoulders relaxed", "Release slowly and repeat on the opposite side"]', '["Tiens-toi droit avec les pieds écartés à la largeur des hanches et garde une bonne posture", "Étends ton bras gauche droit à travers ta poitrine à hauteur d''épaule", "Place ta main droite sur le coude ou l''avant-bras gauche", "Tire doucement ton bras gauche vers ta poitrine avec ta main droite", "Reste dans cette position en maintenant tes épaules détendues", "Relâche lentement et répète de l''autre côté"]', '["Reste bien droit et évite de tourner ton dos pendant l''étirement", "Applique une pression douce et constante sans forcer l''étirement", "Sensation d''étirement dans l''épaule gauche et les muscles du haut du dos", "Respire normalement pendant toute la durée de l''étirement", "Arrête immédiatement si tu ressens une douleur aiguë"]', '["Keep your torso upright and avoid rotating your spine during the stretch", "Apply gentle, steady pressure rather than forcing the stretch", "Feel the stretch in your left shoulder and upper back muscles", "Breathe normally throughout the hold period", "Stop immediately if you experience any sharp pain"]', 'cca59a88-a42c-4630-ad1e-335e31c65717', 'upper-back-and-shoulder-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('118dc754-3e14-476c-ba85-3a093dfcf2b5', 'Fentes Marchées', NULL, 'صدمات الماشي', 'Walking Lunges', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/walking-lunges.mp4', NULL, NULL, NULL, '/videos/thumbnails/walking-lunges.jpg', NULL, '["Mouvement fluide et continu", "Garde le torse droit", "Contrôle chaque pas", "Excellent pour l''endurance des jambes", "Assure-toi d''avoir de l''espace pour t''exercer"]', '["Pencher le torse en avant", "Ne pas contrôler les mouvements"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "walking lunges"]', true, '2026-04-03 12:24:59.838089+00', '2026-04-03 12:24:59.838089+00', 'Les fentes marchées travaillent intensément vos quadriceps tout en améliorant votre équilibre et votre endurance. Un exercice essentiel pour renforcer vos jambes.', '["Pencher le torse en avant", "Ne pas contrôler les mouvements"]', true, '["Step forward into lunge", "Push through front foot", "Bring back leg through to next lunge", "Continue walking forward"]', '["Fais un pas en avant en entrant dans une fente", "Pousse sur le pied avant", "Ramène la jambe arrière pour réaliser la prochaine fente", "Continue à avancer"]', '["Mouvement fluide et continu", "Garde le torse droit", "Contrôle chaque pas", "Excellent pour l''endurance des jambes", "Assure-toi d''avoir de l''espace pour t''exercer"]', '["Continuous movement", "Keep torso upright", "Control each step", "Great for leg endurance", "Need space to perform"]', '620b30ac-bc0d-4b48-bec7-b685cf57f883', 'walking-lunges', NULL, NULL);
INSERT INTO public.exercises VALUES ('520a4e53-7a6d-4411-ac15-4fec1d17e057', 'Pose de la chaise en torsion (droite)', NULL, 'تَمرين الجلوس على الكرسي بتدوير الجسم (اليمين)', 'Revolved chair pose (right)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/revolved-chair-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/revolved-chair-pose-right.jpg', NULL, '["Enfonce-toi davantage dans la position pour une intensité maximale.", "Effectue la torsion depuis le milieu du dos, pas seulement avec les épaules.", "Ressens le poids dans tes talons pour un meilleur équilibre."]', '["Ne pas garder les genoux alignés l''un avec l''autre.", "Tordre uniquement les épaules sans impliquer le dos."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "revolved chair pose (right)"]', true, '2026-04-03 12:24:58.626948+00', '2026-04-03 12:24:58.626948+00', 'Renforce ton cœur et améliore ta souplesse avec cette pose dynamique ! Prépare-toi à t''engager pleinement dans chaque seconde de cet exercice. ', '["Ne pas garder les genoux alignés l''un avec l''autre.", "Tordre uniquement les épaules sans impliquer le dos."]', true, '["Start in Chair Pose with palms together at your chest.", "Twist your torso and hook one elbow outside the opposite knee.", "Press your palms together to deepen the twist.", "Keep your knees even and hips level."]', '["Commence en position de chaise, les paumes jointes devant la poitrine.", "Torse tourné, enroule un coude à l''extérieur du genou opposé.", "Appuie tes paumes ensemble pour approfondir la torsion.", "Garde les genoux alignés et les hanches au même niveau."]', '["Enfonce-toi davantage dans la position pour une intensité maximale.", "Effectue la torsion depuis le milieu du dos, pas seulement avec les épaules.", "Ressens le poids dans tes talons pour un meilleur équilibre."]', '["Sit deeper to intensify the pose.", "Twist from your mid-back, not just your shoulders.", "Keep your weight in your heels."]', '2ea5aa3e-034c-45a7-862a-d2f324671901', 'revolved-chair-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('4b60dca5-a390-4b2a-893b-d14aac351dc9', 'Élévations de jambes assis', NULL, 'رفع الساقين جالسا', 'Seated leg raises', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/seated-leg-raises.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-leg-raises.jpg', NULL, '["Garde les mains bien appuyées derrière toi pour maintenir l''équilibre et le soutien", "Évite d''utiliser l''élan - le mouvement doit être lent et contrôlé", "Concentre-toi sur l''engagement de tes abdominaux plutôt que d''utiliser uniquement les fléchisseurs de la hanche", "Maintiens tes jambes ensemble et droites tout au long du mouvement", "Ne laisse pas tes jambes toucher le sol entre les répétitions pour garder une tension constante"]', '["S''arrondir au niveau du dos en levant les jambes", "Utiliser l''élan au lieu de contrôler le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "seated leg raises"]', true, '2026-04-03 12:24:58.904349+00', '2026-04-03 12:24:58.904349+00', 'Position de départ : Assieds-toi sur un tapis, les mains derrière toi pour te soutenir, les jambes tendues devant. Exécution : Lève les deux jambes vers ta poitrine en engageant tes abdominaux, puis abaisse-les lentement avec contrôle.', '["S''arrondir au niveau du dos en levant les jambes", "Utiliser l''élan au lieu de contrôler le mouvement"]', true, '["Sit on a mat with your hands placed behind you for support and stability", "Extend both legs straight out in front of you, keeping them together", "Engage your core muscles and lift both legs up toward your chest", "Keep your back straight and avoid rounding your shoulders forward", "Lower your legs back down slowly with control, maintaining tension in your core", "Repeat the movement in a smooth, controlled rhythm"]', '["Assieds-toi sur un tapis avec les mains placées derrière toi pour te stabiliser", "Tends les deux jambes droit devant, en les gardant ensemble", "Engage tes muscles abdominaux et lève les deux jambes vers ta poitrine", "Garde le dos droit et évite de courber les épaules vers l''avant", "Abaisse tes jambes lentement avec contrôle, en maintenant la tension dans tes abdos", "Répète le mouvement dans un rythme fluide et contrôlé"]', '["Garde les mains bien appuyées derrière toi pour maintenir l''équilibre et le soutien", "Évite d''utiliser l''élan - le mouvement doit être lent et contrôlé", "Concentre-toi sur l''engagement de tes abdominaux plutôt que d''utiliser uniquement les fléchisseurs de la hanche", "Maintiens tes jambes ensemble et droites tout au long du mouvement", "Ne laisse pas tes jambes toucher le sol entre les répétitions pour garder une tension constante"]', '["Keep your hands firmly planted behind you to maintain balance and support", "Avoid using momentum - the movement should be slow and controlled", "Focus on engaging your core muscles rather than using your hip flexors to do all the work", "Keep your legs together and straight throughout the entire movement", "Don''t let your legs touch the ground between repetitions to maintain constant tension"]', '42dc0603-91e8-4a1e-8bf0-ef9478718106', 'seated-leg-raises', NULL, NULL);
INSERT INTO public.exercises VALUES ('85a91af6-a97b-4de4-957b-c39f6483b7c4', 'Tirage Haut Élargi à la Smith Machine', NULL, NULL, 'Wide Grip Smith Machine Upright Row', 'Shoulders', '[]', 'Shoulders', 'Intermediate', 8, '/videos/shoulders/wide-grip-smith-machine-upright-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/wide-grip-smith-machine-upright-row.jpg', NULL, '["Gardez votre ventre serré et une posture droite durant tout l''exercice pour protéger votre bas du dos.", "Évitez de tirer la barre trop haut pour prévenir toute blessure à l''épaule.", "Concentrez-vous sur le mouvement avec vos coudes plutôt qu''avec vos mains pour cibler efficacement les deltoïdes.", "Utilisez le chemin guidé de la Smith machine pour maintenir la bonne forme.", "Commencez avec des poids légers pour bien maîtriser le mouvement avant de passer à des charges plus lourdes."]', '["Ne pas maintenir la barre près du corps ce qui peut entraîner une perte de contrôle.", "Tirer la barre trop haut au-dessus du niveau de la poitrine, ce qui peut causer des douleurs et des blessures."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "machine", "wide grip smith machine upright row"]', true, '2026-04-03 12:24:59.935979+00', '2026-04-03 12:24:59.935979+00', 'Cet exercice cible les épaules avec une prise élargie sur la Smith Machine. Vous allez développer votre force et votre définition musculaire !', '["Ne pas maintenir la barre près du corps ce qui peut entraîner une perte de contrôle.", "Tirer la barre trop haut au-dessus du niveau de la poitrine, ce qui peut causer des douleurs et des blessures."]', true, '["Position yourself under the Smith machine bar and grip it with hands placed wider than shoulder-width apart using an overhand grip", "Stand with feet shoulder-width apart, core engaged, and shoulders pulled back with the bar resting at upper thigh level", "Initiate the movement by pulling your elbows up and out to the sides, keeping the bar close to your body", "Continue pulling until the bar reaches chest level, ensuring your elbows remain higher than your wrists throughout the movement", "Pause briefly at the top position while squeezing your shoulder blades together", "Lower the bar slowly and controlled back to the starting position, maintaining tension in your shoulders"]', '["Positionnez-vous sous la barre de la Smith machine avec une prise en pronation, les mains plus larges que les épaules.", "Tenez-vous droit, les pieds écartés à la largeur des épaules, le ventre engagé, et les épaules en arrière, la barre reposant au niveau de vos cuisses supérieures.", "Commencez le mouvement en tirant vos coudes vers le haut et sur les côtés, en gardant la barre près de votre corps.", "Poursuivez jusqu''à ce que la barre atteigne la hauteur de votre poitrine, en assurant que vos coudes restent plus hauts que vos poignets durant tout le mouvement.", "Faites une pause en haut en serrant vos omoplates avant de redescendre.", "Abaissez lentement la barre en contrôlant le mouvement jusqu''à la position de départ tout en gardant la tension dans vos épaules."]', '["Gardez votre ventre serré et une posture droite durant tout l''exercice pour protéger votre bas du dos.", "Évitez de tirer la barre trop haut pour prévenir toute blessure à l''épaule.", "Concentrez-vous sur le mouvement avec vos coudes plutôt qu''avec vos mains pour cibler efficacement les deltoïdes.", "Utilisez le chemin guidé de la Smith machine pour maintenir la bonne forme.", "Commencez avec des poids légers pour bien maîtriser le mouvement avant de passer à des charges plus lourdes."]', '["Keep your core tight and maintain an upright posture throughout the entire movement to protect your lower back", "Avoid pulling the bar too high above chest level as this can cause shoulder impingement and injury", "Focus on leading the movement with your elbows rather than your hands to properly target the deltoids", "Use the Smith machine''s guided bar path to maintain proper form and prevent the bar from drifting away from your body", "Start with lighter weight to master the movement pattern before progressing to heavier loads"]', '82610c61-8595-4814-a657-662932c9081d', 'wide-grip-smith-machine-upright-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('5140277b-0b67-47ea-8303-b2950d9b771f', 'Squat Arrière avec Barre', NULL, NULL, 'Barbell Back Squat', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 1, '/videos/quadriceps/barbell-back-squat.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-back-squat.jpg', NULL, '["Veille à ce que tes genoux suivent la direction de tes orteils tout au long du mouvement pour éviter le valgus du genou.", "Maintiens un ventre engagé et une position de colonne vertébrale neutre - évite de trop pencher le buste en avant ou de courber le dos.", "Maîtrise ta descente et évite de rebondir au fond du mouvement pour prévenir les blessures.", "Concentre-toi sur la pression dans tes talons plutôt que dans tes orteils pour activer correctement la chaîne postérieure.", "Assure-toi d''une extension complète des hanches et des genoux au sommet de chaque répétition avant de commencer la suivante."]', '["Ne pas garder les genoux alignés avec les orteils, ce qui peut entraîner des blessures.", "Avoir un dos rond ou penché trop en avant, ce qui compromet la technique."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "barbell back squat"]', true, '2026-04-03 12:24:55.516599+00', '2026-04-03 12:24:55.516599+00', 'Position initiale : Place la barre sur le haut de ton dos, les pieds écartés à la largeur des épaules. Exécution : Descends en squat profond tout en gardant le dos droit, puis pousse pour revenir à la position de départ.', '["Ne pas garder les genoux alignés avec les orteils, ce qui peut entraîner des blessures.", "Avoir un dos rond ou penché trop en avant, ce qui compromet la technique."]', true, '["Set the barbell at chest height in the squat rack and position safety bars just below your lowest squat position", "Step under the bar and position it on your upper traps, gripping the bar with hands evenly placed wider than shoulder-width", "Unrack the bar by standing up and take 2-3 steps backward, then set your feet shoulder-width apart with toes slightly turned out", "Initiate the movement by pushing your hips back and bending your knees, keeping your chest up and core engaged", "Descend until your hip crease is just below your knee caps while maintaining a neutral spine", "Drive through your heels and push the floor away to return to the starting position, fully extending your hips and knees"]', '["Place la barre à hauteur de poitrine dans le rack à squats et ajuste les barres de sécurité juste en dessous de ta position de squat la plus basse.", "Positionne-toi sous la barre, pose-la sur tes traps supérieurs et prends-la avec les mains écartées un peu plus que la largeur des épaules.", "Décharge la barre en te levant et fais 2 à 3 pas en arrière, puis écarte les pieds à la largeur des épaules avec les orteils légèrement tournés vers l''extérieur.", "Commence le mouvement en poussant tes hanches en arrière et en fléchissant les genoux, bien garder la poitrine haute et le ventre engagé.", "Descends jusqu''à ce que le pli de la hanche soit juste en dessous de tes genoux tout en maintenant une colonne vertébrale neutre.", "Pousse �� travers tes talons et éloigne le sol pour revenir à la position de départ, en étendant complètement tes hanches et tes genoux."]', '["Veille à ce que tes genoux suivent la direction de tes orteils tout au long du mouvement pour éviter le valgus du genou.", "Maintiens un ventre engagé et une position de colonne vertébrale neutre - évite de trop pencher le buste en avant ou de courber le dos.", "Maîtrise ta descente et évite de rebondir au fond du mouvement pour prévenir les blessures.", "Concentre-toi sur la pression dans tes talons plutôt que dans tes orteils pour activer correctement la chaîne postérieure.", "Assure-toi d''une extension complète des hanches et des genoux au sommet de chaque répétition avant de commencer la suivante."]', '["Keep your knees tracking in line with your toes throughout the entire movement to prevent knee valgus", "Maintain a tight core and neutral spine position - avoid excessive forward lean or rounding of the back", "Control the descent and avoid bouncing at the bottom of the movement to prevent injury", "Focus on driving through your heels rather than your toes to properly activate the posterior chain", "Ensure full hip and knee extension at the top of each rep before beginning the next repetition"]', '65e95132-e6bb-41e8-af7d-0eda931a1693', 'barbell-back-squat', NULL, NULL);
INSERT INTO public.exercises VALUES ('46b0675e-375e-45e8-a1da-bbf6dd9c2586', 'Développé Épaules avec Barbell', NULL, 'تمرين ضغط الكتفين بالبار', 'Barbell Shoulder Press -  Barbell Overhead Press - Barbell Military Press', 'Shoulders', '[]', 'Shoulders', 'Beginner', 1, '/videos/shoulders/barbell-shoulder-press-barbell-overhead-press-barbell-military-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-shoulder-press-barbell-overhead-press-barbell-military-press.jpg', NULL, '["Serre ton ventre et évite de cambrer le dos pour prévenir les blessures lombaires", "Pousse la barre en ligne droite, directement au-dessus de ta tête, pour maintenir un bon chemin de barre", "Assure-toi que les coudes restent sous la barre en position basse pour maximiser la stabilité et le transfert de puissance", "Utilise une prise complète autour de la barre, plutôt que de ne pas utiliser le pouce, pour un meilleur contrôle et sécurité", "Commence avec des poids légers pour maîtriser la technique avant de passer à des charges plus lourdes"]', '["Cambrer le dos pendant le mouvement", "Ne pas garder les coudes sous la barre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "barbell", "barbell shoulder press -  barbell overhead press - barbell military press"]', true, '2026-04-03 12:24:55.609759+00', '2026-04-03 12:24:55.609759+00', 'Position de départ : Place-toi debout, les pieds écartés à la largeur des épaules, en tenant une barre au niveau des épaules, les mains légèrement plus larges que les épaules et les coudes un peu devant. Exécution : Pousse la barre directement au-dessus de ta tête jusqu''à ce que tes bras soient complètement tendus, puis redescends-la à la position initiale au niveau des épaules de manière contrôlée.', '["Cambrer le dos pendant le mouvement", "Ne pas garder les coudes sous la barre"]', true, '["Set up with the barbell in a rack at shoulder height and position yourself with feet shoulder-width apart", "Grip the bar with hands slightly wider than shoulders using an overhand grip", "Unrack the bar and position it at shoulder level with elbows directly beneath the bar", "Engage your core and maintain a neutral spine throughout the movement", "Press the bar straight up overhead until arms are fully extended without arching your back excessively", "Lower the bar slowly back to shoulder level while maintaining control"]', '["Place la barre dans un rack à hauteur des épaules et positionne-toi avec les pieds à la largeur des épaules", "Attrape la barre avec les mains légèrement plus larges que les épaules en prise pronation", "Décharge la barre pour la mettre au niveau des épaules avec les coudes directement sous la barre", "Engage ton abdomen et garde une colonne vertébrale neutre tout au long du mouvement", "Pousse la barre droit au-dessus de ta tête jusqu''à l''extension complète des bras sans cambrer excessivement le dos", "Redescends la barre lentement au niveau des épaules tout en gardant le contrôle"]', '["Serre ton ventre et évite de cambrer le dos pour prévenir les blessures lombaires", "Pousse la barre en ligne droite, directement au-dessus de ta tête, pour maintenir un bon chemin de barre", "Assure-toi que les coudes restent sous la barre en position basse pour maximiser la stabilité et le transfert de puissance", "Utilise une prise complète autour de la barre, plutôt que de ne pas utiliser le pouce, pour un meilleur contrôle et sécurité", "Commence avec des poids légers pour maîtriser la technique avant de passer à des charges plus lourdes"]', '["Keep your core tight and avoid excessive back arching to prevent lower back injury", "Press the bar in a straight line directly overhead rather than forward to maintain proper bar path", "Ensure elbows stay under the bar at the bottom position to maximize stability and power transfer", "Use a full grip around the bar rather than a thumbless grip for better control and safety", "Start with lighter weight to master the movement pattern before progressing to heavier loads"]', '4e4377e1-ab91-4015-84ac-27b3274b549f', 'barbell-shoulder-press-barbell-overhead-press-barbell-military-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('61bbd65f-23f3-477e-84bf-82e1c8397c20', 'Fentes Marchées avec Barbell', NULL, NULL, 'Barbell walking lunges', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 1, '/videos/quadriceps/barbell-walking-lunges.mp4', NULL, NULL, NULL, '/videos/thumbnails/barbell-walking-lunges.jpg', NULL, '["Garde le torse bien droit", "Le genou avant doit suivre la ligne des orteils", "Ne laisse pas le genou avant dépasser les orteils", "Contrôle la descente", "Recule si tu as des difficultés à garder l''équilibre"]', '["Genoux qui débordent des orteils", "Torso penché en avant", "Pas de contrôle lors de la descente", "Incapacité à alterner les jambes correctement", "Fentes trop rapides sans contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "barbell", "barbell walking lunges"]', true, '2026-04-03 12:24:55.638072+00', '2026-04-03 12:24:55.638072+00', 'Position de départ : Reste bien droit, pieds écartés à la largeur des hanches, une barre sur le haut du dos et des épaules. Exécution : Fait un pas en avant pour entrer en position de fente, abaisse ton genou arrière vers le sol, puis ramène la jambe arrière pour retrouver la position initiale. Alterne les jambes à chaque répétition.', '["Genoux qui débordent des orteils", "Torso penché en avant", "Pas de contrôle lors de la descente", "Incapacité à alterner les jambes correctement", "Fentes trop rapides sans contrôle"]', true, '["Bar on upper back", "Stand with feet together", "Step forward into lunge", "Lower until back knee near floor", "Push back to starting position", "Alternate legs or complete one side"]', '["Barre sur le haut du dos", "Pieds écartés ensemble", "Fais un pas en avant en fente", "Abaisse jusqu''à ce que le genou arrière soit près du sol", "Remonte vers la position de départ", "Alterne les jambes ou fais un côté complet"]', '["Garde le torse bien droit", "Le genou avant doit suivre la ligne des orteils", "Ne laisse pas le genou avant dépasser les orteils", "Contrôle la descente", "Recule si tu as des difficultés à garder l''équilibre"]', '["Keep torso upright", "Front knee tracks over toes", "Don''t let front knee shoot past toes", "Control the descent", "Step back, not forward if balance is hard"]', 'ae8be22d-584f-4c34-add8-d25383ba90de', 'barbell-walking-lunges', NULL, NULL);
INSERT INTO public.exercises VALUES ('4df95390-d9f5-403d-8628-2183546d2555', 'Tirage Buste Incliné avec Barre', NULL, NULL, 'Bent Over Barbell Row', 'Back', '[]', 'Back', 'Intermediate', 1, '/videos/back/bent-over-barbell-row.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-over-barbell-row.jpg', NULL, '["Garde le core engagé et maintiens une colonne vertébrale neutre tout au long du mouvement pour protéger ton bas du dos.", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras - commence le mouvement en rétractant tes omoplates.", "Évite d''utiliser l''élan ou de laisser ton torse remonter pendant le tirage.", "Contrôle la descente - ne laisse pas le poids tomber.", "Commence avec un poids léger pour maîtriser la forme avant de passer à plus lourd."]', '["Ne pas engager le core et avoir une posture courbée.", "Utiliser l''élan au lieu de la force musculaire."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "barbell", "bent over barbell row"]', true, '2026-04-03 12:24:55.72652+00', '2026-04-03 12:24:55.72652+00', 'Position de départ : Penche-toi en avant et prends une barre avec les paumes vers le bas. Exécution : Tire la barre vers ta poitrine en gardant le dos droit, puis abaisse-la lentement à la position de départ.', '["Ne pas engager le core et avoir une posture courbée.", "Utiliser l''élan au lieu de la force musculaire."]', true, '["Stand with feet hip-width apart, holding a barbell with an overhand grip slightly wider than shoulder-width", "Hinge at the hips and bend forward until your torso is at about a 45-degree angle, keeping knees slightly bent", "Let the barbell hang with arms fully extended, maintaining a neutral spine and engaged core", "Pull the barbell up to your lower chest/upper abdomen by driving your elbows back and squeezing your shoulder blades together", "Pause briefly at the top, then slowly lower the barbell back to the starting position with control", "Complete the desired number of repetitions while maintaining proper form throughout"]', '["Place tes pieds à la largeur des hanches et saisis la barre avec un grip proné légèrement plus large que les épaules.", "Incline-toi au niveau des hanches jusqu''à ce que ton torse soit à environ 45 degrés, les genoux légèrement fléchis.", "Laisse la barre pendre avec les bras complètement étendus, en maintenant une colonne vertébrale neutre et le core engagé.", "Tire la barre vers ton bas de poitrine/haut de l''abdomen en poussant les coudes vers l''arrière et en serrant les omoplates ensemble.", "Fais une pause brève en haut, puis redescends lentement la barre à la position de départ avec contrôle.", "Réalise le nombre de répétitions souhaité tout en gardant la bonne forme."]', '["Garde le core engagé et maintiens une colonne vertébrale neutre tout au long du mouvement pour protéger ton bas du dos.", "Concentre-toi sur le tirage avec tes muscles du dos plutôt qu''avec tes bras - commence le mouvement en rétractant tes omoplates.", "Évite d''utiliser l''élan ou de laisser ton torse remonter pendant le tirage.", "Contrôle la descente - ne laisse pas le poids tomber.", "Commence avec un poids léger pour maîtriser la forme avant de passer à plus lourd."]', '["Keep your core engaged and maintain a neutral spine throughout the entire movement to protect your lower back", "Focus on pulling with your back muscles rather than your arms - initiate the movement by retracting your shoulder blades", "Avoid using momentum or allowing your torso to rise up during the pulling motion", "Control the negative (lowering) portion of the movement - don''t let the weight drop", "Start with lighter weight to master the form before progressing to heavier loads"]', '059690e8-f60d-4099-b3ae-93d18358a59a', 'bent-over-barbell-row', NULL, NULL);
INSERT INTO public.exercises VALUES ('13691105-bc4c-4010-b89a-52e243df6e31', 'Extension Triceps Bent Over avec haltères', NULL, 'Extension Triceps en avant', 'Bent over Dumbbell Tricep Extension', 'Triceps', '[]', 'Triceps', 'Intermediate', 2, '/videos/triceps/bent-over-db-tricep-extension.mp4', NULL, NULL, NULL, '/videos/thumbnails/bent-over-db-tricep-extension.jpg', NULL, '["Garde tes bras supérieurs complètement fixes pendant l''exercice pour cibler efficacement les triceps.", "Maintiens une colonne vertébrale neutre et évite de courber le dos en position penchée.", "Contrôle le poids pendant les phases de descente et de montée pour maximiser l''engagement musculaire.", "Utilise un poids qui te permet de garder une bonne forme plutôt que de te surcharger trop rapidement.", "Garde les abdominaux engagés tout au long de l''exercice pour soutenir ta colonne vertébrale en position penchée."]', '["Ne pas contrôler le mouvement pendant la descente.", "Courber le dos au lieu de garder une position droite."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "dumbbell", "bent over dumbbell tricep extension"]', true, '2026-04-03 12:24:55.748321+00', '2026-04-03 12:24:55.748321+00', 'Position de départ : Debout, les pieds écartés à la largeur des hanches, tiens un haltère avec les deux mains. Incline-toi au niveau des hanches pour pencher ton torse en avant à environ 45 degrés, les bras étendus au-dessus de ta tête derrière toi. Exécution : Garde les bras supérieurs fixes tout en pliant les coudes pour abaisser l''haltère derrière ta tête, puis remonte-le à la position de départ.', '["Ne pas contrôler le mouvement pendant la descente.", "Courber le dos au lieu de garder une position droite."]', true, '["Hold a dumbbell with both hands using a neutral grip and stand with feet hip-width apart", "Hinge at the hips and lean your torso forward at approximately 45 degrees while keeping your back straight", "Extend your arms overhead and back behind your body, keeping upper arms parallel to the floor", "Lower the dumbbell by bending only at the elbows until you feel a stretch in your triceps", "Press the weight back up by extending your elbows to return to the starting position", "Maintain the bent-over position throughout the entire movement"]', '["Tiens un haltère avec les deux mains en utilisant une prise neutre et reste debout, les pieds écartés à la largeur des hanches.", "Incline-toi au niveau des hanches et penche ton torse en avant à environ 45 degrés tout en gardant le dos droit.", "Étends tes bras au-dessus de ta tête et derrière ton corps, en gardant les bras supérieurs parallèles au sol.", "Fais descendre l''haltère en pliant uniquement les coudes jusqu''à ressentir un étirement dans les triceps.", "Pousse le poids vers le haut en étendant les coudes pour revenir à la position de départ.", "Maintiens la position penchée tout au long du mouvement."]', '["Garde tes bras supérieurs complètement fixes pendant l''exercice pour cibler efficacement les triceps.", "Maintiens une colonne vertébrale neutre et évite de courber le dos en position penchée.", "Contrôle le poids pendant les phases de descente et de montée pour maximiser l''engagement musculaire.", "Utilise un poids qui te permet de garder une bonne forme plutôt que de te surcharger trop rapidement.", "Garde les abdominaux engagés tout au long de l''exercice pour soutenir ta colonne vertébrale en position penchée."]', '["Keep your upper arms completely stationary throughout the movement to isolate the triceps effectively", "Maintain a neutral spine and avoid rounding your back while in the bent-over position", "Control the weight on both the lowering and lifting phases to maximize muscle engagement", "Use a weight that allows you to maintain proper form rather than going too heavy too quickly", "Keep your core engaged throughout the exercise to support your spine in the bent-over position"]', 'c7c76fa8-908a-4ee0-977c-35f12057676d', 'bent-over-db-tricep-extension', NULL, NULL);
INSERT INTO public.exercises VALUES ('d66991fc-3798-473c-aba3-d70ba59bbde2', 'Burpee sans saut avec taps d''épaules', NULL, 'برابي بلا قفز مع لمسات الكتفين', 'Burpee (No jump) into high plank with shoulder tabs', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/burpee-no-jump-into-high-plank-shoulder-a4715d5c.mp4', NULL, NULL, NULL, '/videos/thumbnails/burpee-no-jump-into-high-plank-shoulder-a4715d5c.jpg', NULL, '["Engage ton tronc pendant tout le mouvement pour limiter les douleurs lombaires", "Garde une ligne droite de la tête aux talons pendant la planche", "Minimise la rotation des hanches lors des taps d''épaule en contractant tes fessiers", "Maintiens tes mains bien ancrées et tes épaules stables lorsque tu touches l''épaule opposée", "Contrôle le tempo tout au long de l''exercice - ne précipite pas pour conserver la bonne forme"]', '["Ne pas engager assez le tronc, ce qui augmente le risque de blessure", "Ne pas garder les hanches alignées pendant les taps d''épaules"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "burpee (no jump) into high plank with shoulder tabs"]', true, '2026-04-03 12:24:55.841422+00', '2026-04-03 12:24:55.841422+00', 'Prêt à renforcer ton tronc ? À partir d''une position debout, fais un burpee modifié, sans saut, et passe en position de planche haute. En gardant ton équilibre, touche chaque épaule avec la main opposée. C''est parti !', '["Ne pas engager assez le tronc, ce qui augmente le risque de blessure", "Ne pas garder les hanches alignées pendant les taps d''épaules"]', true, '["Squat down and place hands on the floor in front of your feet", "Step or jump both feet back into a high plank position with hands directly under shoulders", "Hold the plank position while lifting your right hand to tap your left shoulder", "Return right hand to the floor, then lift left hand to tap right shoulder", "Step or jump both feet forward toward your hands", "Stand up to return to the starting position"]', '["Accroupis-toi et pose tes mains au sol devant tes pieds", "Recule tes deux pieds en planche haute, les mains directement sous les épaules", "Maintiens la planche, lève ta main droite pour toucher ton épaule gauche", "Ramène ta main droite au sol, puis lève ta main gauche pour toucher ton épaule droite", "Avance tes deux pieds vers tes mains, puis redresse-toi pour revenir à la position de départ"]', '["Engage ton tronc pendant tout le mouvement pour limiter les douleurs lombaires", "Garde une ligne droite de la tête aux talons pendant la planche", "Minimise la rotation des hanches lors des taps d''épaule en contractant tes fessiers", "Maintiens tes mains bien ancrées et tes épaules stables lorsque tu touches l''épaule opposée", "Contrôle le tempo tout au long de l''exercice - ne précipite pas pour conserver la bonne forme"]', '["Keep your core engaged throughout the entire movement to prevent lower back strain", "Maintain a straight line from head to heels during the plank portion", "Minimize hip rotation when performing shoulder taps by engaging your glutes", "Keep hands firmly planted and shoulders stable when tapping opposite shoulder", "Control the tempo throughout - avoid rushing through the movement to maintain proper form"]', 'a4715d5c-446e-4937-a25a-254652773990', 'burpee-no-jump-into-high-plank-shoulder-a4715d5c', NULL, NULL);
INSERT INTO public.exercises VALUES ('20795442-5c3d-417e-bd02-0ef6f733b9a1', 'Sauts en longueur', NULL, 'قفزات بعيدة', 'Broad jumps', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/broad-jumps.mp4', NULL, NULL, NULL, '/videos/thumbnails/broad-jumps.jpg', NULL, '["Concentre-toi sur un atterrissage doux avec les genoux fléchis pour protéger tes articulations", "Utilise tes bras activement pour gagner en élan et maintenir l''équilibre pendant le mouvement", "Maintiens ton tronc engagé pendant le décollage et l''atterrissage pour rester stable", "Vise la distance horizontale maximale plutôt que la hauteur pour optimiser ta technique de saut", "Assure-toi d''avoir suffisamment d''espace devant toi avant de sauter pour éviter les blessures dues aux obstacles"]', '["Ne pas fléchir les genoux à l''atterrissage, ce qui peut entraîner des blessures", "Sauter sans utiliser les bras, ce qui réduit l''élan et la distance du saut"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "broad jumps"]', true, '2026-04-03 12:24:55.793074+00', '2026-04-03 12:24:55.793074+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des épaules, les genoux légèrement fléchis et les bras le long du corps. Exécution : Balance tes bras vers l''arrière en te mettant en position de squat quart, puis saute explosivement en avant le plus loin possible, en balançant tes bras vers l''avant pour gagner en élan et atterris doucement sur les deux pieds.', '["Ne pas fléchir les genoux à l''atterrissage, ce qui peut entraîner des blessures", "Sauter sans utiliser les bras, ce qui réduit l''élan et la distance du saut"]', true, '["Stand with feet shoulder-width apart and toes pointing slightly outward", "Lower into a quarter squat position while swinging your arms back behind your body", "Explosively drive through your heels and jump forward as far as possible", "Swing your arms forward and upward to generate maximum momentum", "Land softly on the balls of your feet with knees bent to absorb impact", "Step back to starting position and reset before the next repetition"]', '["Tiens-toi debout, les pieds écartés à la largeur des épaules et les orteils légèrement tournés vers l''extérieur", "Descends en position de squat quart en balançant tes bras vers l''arrière", "Pousse sur tes talons et saute le plus loin possible en avant", "Balance tes bras vers l''avant et vers le haut pour générer un maximum d''élan", "Atterris doucement sur l''avant de tes pieds, les genoux fléchis pour amortir l''impact", "Recule vers la position de départ et prépare-toi pour la répétition suivante"]', '["Concentre-toi sur un atterrissage doux avec les genoux fléchis pour protéger tes articulations", "Utilise tes bras activement pour gagner en élan et maintenir l''équilibre pendant le mouvement", "Maintiens ton tronc engagé pendant le décollage et l''atterrissage pour rester stable", "Vise la distance horizontale maximale plutôt que la hauteur pour optimiser ta technique de saut", "Assure-toi d''avoir suffisamment d''espace devant toi avant de sauter pour éviter les blessures dues aux obstacles"]', '["Focus on landing softly with bent knees to protect your joints from impact", "Use your arms actively to generate momentum and maintain balance throughout the movement", "Keep your core engaged during takeoff and landing to maintain stability", "Aim for maximum horizontal distance rather than height to optimize the broad jump technique", "Ensure adequate space ahead of you before jumping to prevent injury from obstacles"]', 'ca5187cf-f9c2-4ad3-b932-4dccc2e47f7e', 'broad-jumps', NULL, NULL);
INSERT INTO public.exercises VALUES ('506bb498-3ac4-4484-9d93-e3ac6b0b57fd', 'Sautez comme un papillon !', NULL, NULL, 'Butterfly Jumps', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/butterfly-jumps.mp4', NULL, NULL, NULL, '/videos/thumbnails/butterfly-jumps.jpg', NULL, '["Atterrissez doucement sur l''avant de vos pieds pour alléger l''impact sur vos articulations et éviter les blessures.", "Gardez votre ceinture abdominale engagée durant tout le mouvement pour maintenir votre posture et votre stabilité.", "Commencez par des durées plus courtes et augmentez l''intensité au fur et à mesure de votre condition physique.", "Respirez correctement : expirez lors du saut et inspirez pendant la courte pause entre les sauts."]', '["Ne pas sauter assez haut, ce qui réduit l''efficacité de l''exercice.", "Atterrir trop fort sans contrôler le mouvement, augmentant le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "butterfly jumps"]', true, '2026-04-03 12:24:55.861496+00', '2026-04-03 12:24:55.861496+00', 'Position de départ : Tenez-vous debout, les pieds joints, bras le long du corps et le ventre engagé.  Exécution : Sautez en écartant les jambes et en levant les bras au-dessus de la tête, puis revenez immédiatement à la position de départ avec les pieds joints et les bras sur les côtés.', '["Ne pas sauter assez haut, ce qui réduit l''efficacité de l''exercice.", "Atterrir trop fort sans contrôler le mouvement, augmentant le risque de blessure."]', true, '["Stand with feet together and arms relaxed at your sides on a flat, non-slip surface", "Bend your knees slightly and engage your core muscles before beginning the movement", "Jump up explosively while spreading your legs wide apart and raising both arms overhead", "Land softly on the balls of your feet with legs wide and arms extended above your head", "Immediately jump again to return to the starting position with feet together and arms at your sides", "Maintain a steady rhythm while keeping your movements controlled throughout the exercise"]', '["Tenez-vous debout les pieds joints et bras relâchés sur une surface plane et antidérapante.", "Pliez légèrement les genoux et contractez vos abdominaux avant de commencer le mouvement.", "Sautez explosivement en écartant les jambes et en levant les bras au-dessus de votre tête.", "Atterrissez doucement sur l''avant de vos pieds, les jambes écartées et les bras levés.", "Sautez de nouveau pour revenir à la position de départ avec les pieds joints et les bras le long du corps.", "Maintenez un rythme régulier tout en contrôlant chacun de vos mouvements."]', '["Atterrissez doucement sur l''avant de vos pieds pour alléger l''impact sur vos articulations et éviter les blessures.", "Gardez votre ceinture abdominale engagée durant tout le mouvement pour maintenir votre posture et votre stabilité.", "Commencez par des durées plus courtes et augmentez l''intensité au fur et à mesure de votre condition physique.", "Respirez correctement : expirez lors du saut et inspirez pendant la courte pause entre les sauts."]', '["Land softly on the balls of your feet to reduce impact on your joints and prevent injury", "Keep your core engaged throughout the entire movement to maintain proper posture and stability", "Start with shorter durations and gradually increase intensity as your cardiovascular fitness improves", "Maintain proper breathing by exhaling during the jump phase and inhaling during the brief pause between jumps"]', '22bf3fc2-d7a0-41d0-9a1a-5e0d149d2b7a', 'butterfly-jumps', NULL, NULL);
INSERT INTO public.exercises VALUES ('2103491f-f215-4355-b0e6-d9198300722c', 'Pousse de Triceps à la Poulie', NULL, 'دفع التراي سيبس عبر الكابل', 'Cable Tricep Pushdown', 'Triceps', '[]', 'Triceps', 'Beginner', 4, '/videos/triceps/cable-tricep-pushdown.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-tricep-pushdown.jpg', NULL, '["Maintiens les coudes fixes contre tes côtés pour un isolement optimal des triceps", "Utilise un mouvement complet en étendant bien en bas et en revenant à la position parallèle au sol en haut", "Contrôle le poids lors de la phase de retour, ne laisse pas le poids revenir rapidement", "Commence avec une charge légère pour bien maîtriser la technique avant d''augmenter le poids", "Évite d''utiliser l''élan ou de balancer ton corps pour bouger le poids"]', '["Lâcher les coudes et les éloigner du corps", "Utiliser un poids trop lourd et se pencher en arrière pour compenser"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "cable", "cable tricep pushdown"]', true, '2026-04-03 12:24:55.994876+00', '2026-04-03 12:24:55.994876+00', 'Pour commencer, positionne-toi face à une poulie haute avec une barre droite. En jouant sur la force de tes avant-bras, pousse la barre vers le bas en gardant les coudes immobiles.', '["Lâcher les coudes et les éloigner du corps", "Utiliser un poids trop lourd et se pencher en arrière pour compenser"]', true, '["Set the cable pulley to the highest position and attach your preferred handle (straight bar, rope, or V-bar)", "Stand close to the machine with feet shoulder-width apart and slight forward lean", "Grip the attachment with palms facing down, keeping elbows pinned to your sides throughout the movement", "Push the weight down using only your forearms until your arms are completely extended", "Slowly return to starting position, stopping when your forearms are parallel to the floor", "Maintain constant tension on the triceps by controlling both the downward and upward phases"]', '["Régle la poulie à la hauteur maximale et attache ton accessoire préféré (barre droite, corde ou V-barre)", "Place-toi près de la machine, pieds écartés à la largeur des épaules et légèrement penché en avant", "Prends l''attache avec les paumes vers le bas, les coudes collés à tes côtés durant tout le mouvement", "Pousse le poids vers le bas uniquement avec tes avant-bras jusqu''à l''extension complète", "Retourne lentement à la position de départ, en t''arrêtant lorsque tes avant-bras sont parallèles au sol", "Garde une tension constante sur les triceps en contrôlant les phases de descente et de montée"]', '["Maintiens les coudes fixes contre tes côtés pour un isolement optimal des triceps", "Utilise un mouvement complet en étendant bien en bas et en revenant à la position parallèle au sol en haut", "Contrôle le poids lors de la phase de retour, ne laisse pas le poids revenir rapidement", "Commence avec une charge légère pour bien maîtriser la technique avant d''augmenter le poids", "Évite d''utiliser l''élan ou de balancer ton corps pour bouger le poids"]', '["Keep your elbows stationary and pressed against your sides to isolate the triceps effectively", "Use a full range of motion by fully extending at the bottom and returning to forearm-parallel position at the top", "Control the weight during the eccentric (returning) phase rather than letting it snap back quickly", "Start with lighter weight to master proper form before progressing to heavier loads", "Avoid using momentum or swinging your body to move the weight"]', '207924a2-ae75-4371-be43-49c3cc62b4e1', 'cable-tricep-pushdown', NULL, NULL);
INSERT INTO public.exercises VALUES ('4cd212fb-9ff0-42eb-a463-1cae111dd88e', 'Step-Ups avec Câble', NULL, '', 'Cable Step-Ups', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 4, '/videos/quadriceps/cable-step-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-step-ups.jpg', NULL, '["Centre ton poids sur ta jambe qui monte pour garder l''équilibre et maximiser l''activation des quadriceps", "Contrôle bien la descente pour éviter de rebondir et garder une tension musculaire", "Assure-toi que la hauteur du banc permet à ton genou d''être à environ 90 degrés lorsque ton pied est posé", "Garde ton cœur serré et évite de pencher trop en avant ou en arrière pendant l''exercice", "Utilise la résistance du câble pour augmenter la difficulté tout en maintenant une forme de marche correcte."]', '["Ne pas garder le torse droit pendant le mouvement", "Sauter ou rebondir à la descente au lieu de contrôler le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "cable", "cable step-ups"]', true, '2026-04-03 12:24:55.976137+00', '2026-04-03 12:24:55.976137+00', 'Positionne-toi devant une machine à câbles, un pied fermement sur un banc ou une marche, tenant la poignée du câble sur le côté. Exécute le mouvement en montant sur le banc avec ta jambe surélevée, puis ramène l''autre jambe pour être stable, et redescends avec contrôle.', '["Ne pas garder le torse droit pendant le mouvement", "Sauter ou rebondir à la descente au lieu de contrôler le mouvement"]', true, '["Position yourself facing the cable machine with one foot planted firmly on the bench or step", "Hold the cable handle with the arm opposite to your stepping leg, maintaining tension in the cable", "Drive through your heel on the elevated leg to step up onto the bench, bringing your trailing leg up", "Keep your torso upright and core engaged throughout the movement", "Step back down with control, lowering your trailing leg first followed by your stepping leg", "Maintain constant tension in the cable throughout the entire range of motion"]', '["Positionne-toi face à la machine à câbles avec un pied solidement ancré sur le banc ou la marche", "Tient la poignée du câble avec le bras opposé à la jambe avec laquelle tu te lèves, en gardant une tension dans le câble", "Pousse sur le talon de ta jambe surélevée pour monter sur le banc, en amenant ta seconde jambe avec toi", "Garde le torse droit et le cœur engagé durant tout le mouvement", "Redescends avec contrôle, en posant d''abord ta jambe traînante puis ta jambe de départ", "Maintiens une tension constante dans le câble tout au long de l''exercice."]', '["Centre ton poids sur ta jambe qui monte pour garder l''équilibre et maximiser l''activation des quadriceps", "Contrôle bien la descente pour éviter de rebondir et garder une tension musculaire", "Assure-toi que la hauteur du banc permet à ton genou d''être à environ 90 degrés lorsque ton pied est posé", "Garde ton cœur serré et évite de pencher trop en avant ou en arrière pendant l''exercice", "Utilise la résistance du câble pour augmenter la difficulté tout en maintenant une forme de marche correcte."]', '["Keep your weight centered over your stepping leg to maintain balance and maximize quad activation", "Control the descent phase to prevent bouncing and maintain muscle tension", "Ensure the bench height allows your knee to be at roughly 90 degrees when your foot is planted", "Keep your core tight and avoid leaning too far forward or backward during the movement", "Use the cable resistance to add challenge while maintaining proper stepping form"]', '646f354b-3790-4796-bfd9-cd9df04bcc16', 'cable-step-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('f1246017-6de4-4d50-ad2d-e9725a3b39fe', 'Élévations de mollets en position de chien tête en bas', NULL, NULL, 'Calf gas peddlers', 'Calves', '[]', 'Calves', 'Intermediate', 16, '/videos/calves/calf-gas-peddlers.mp4', NULL, NULL, NULL, '/videos/thumbnails/calf-gas-peddlers.jpg', NULL, '["Garde ton cœur engagé pour maintenir la stabilité en position inversée", "Distribue ton poids de manière uniforme entre tes mains pour éviter de forcer sur les poignets", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement des mollets", "Assure-toi que ta tête reste alignée avec ta colonne vertébrale", "Veille à garder les deux mains fermement ancrées pendant tout l''exercice"]', '["Ne pas garder les hanches élevées", "Oublier de respirer pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["calves", "bodyweight", "calf gas peddlers"]', true, '2026-04-03 12:24:56.016036+00', '2026-04-03 12:24:56.016036+00', 'Position de départ : Mets-toi en position de chien tête en bas, mains bien ancrées au sol, hanches élevées, pieds écartés à la largeur des hanches. Exécution : Réalise des élévations de talons en alternant, en levant un talon tout en gardant l''autre pied au sol, imitant un mouvement de pédalage tout en restant en position de chien tête en bas.', '["Ne pas garder les hanches élevées", "Oublier de respirer pendant l''exercice"]', true, '["Start in downward dog position with hands firmly planted on the mat shoulder-width apart", "Keep your hips elevated and create an inverted V-shape with your body", "Place feet hip-width apart with toes pointing forward", "Lift one heel up toward the ceiling while keeping the other foot grounded", "Alternate between feet in a controlled pedaling motion", "Maintain steady breathing throughout the movement"]', '["Commence en position de chien tête en bas avec les mains bien ancrées au tapis à la largeur des épaules", "Garde tes hanches élevées pour créer une forme en V inversé avec ton corps", "Positionne tes pieds à la largeur des hanches, les orteils pointés vers l''avant", "Lève un talon vers le plafond tout en maintenant l''autre pied au sol", "Alterne entre les pieds dans un mouvement de pédalage contrôlé", "Respire régulièrement tout au long de l''exercice"]', '["Garde ton cœur engagé pour maintenir la stabilité en position inversée", "Distribue ton poids de manière uniforme entre tes mains pour éviter de forcer sur les poignets", "Concentre-toi sur des mouvements contrôlés plutôt que sur la vitesse pour maximiser l''engagement des mollets", "Assure-toi que ta tête reste alignée avec ta colonne vertébrale", "Veille à garder les deux mains fermement ancrées pendant tout l''exercice"]', '["Keep your core engaged to maintain stability in the inverted position", "Distribute weight evenly between your hands to avoid wrist strain", "Focus on controlled movements rather than speed to maximize calf engagement", "Keep your head in neutral alignment with your spine", "Ensure both hands remain firmly planted throughout the exercise"]', '8577f8c3-283b-472b-b5cf-d0eaa8e84762', 'calf-gas-peddlers', NULL, NULL);
INSERT INTO public.exercises VALUES ('cf1cbaa9-9a58-4dee-918a-eb2467b01289', 'Développé couché prise serrée', NULL, NULL, 'Close Grip Bench Barbell', 'Triceps', '[]', 'Triceps', 'Intermediate', 1, '/videos/triceps/close-grip-bench-barbell.mp4', NULL, NULL, NULL, '/videos/thumbnails/close-grip-bench-barbell.jpg', NULL, '["Garde les coudes proches de ton corps pendant le mouvement pour optimiser l''engagement des triceps et réduire la pression sur les épaules", "Utilise une largeur de prise qui te convient, mais suffisamment étroite pour cibler efficacement les triceps", "Contrôle la descente et évite de rebondir la barre sur ta poitrine", "Commence avec un poids plus léger que sur le développé couché classique, cette variante est plus exigeante pour les triceps", "Assure-toi de bien échauffer tes épaules, coudes et poignets avant de réaliser cet exercice"]', '["Les coudes trop écartés, ce qui diminue l''engagement des triceps", "Rebondir la barre sur la poitrine, ce qui augmente le risque de blessure"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "barbell", "close grip bench barbell"]', true, '2026-04-03 12:24:56.08041+00', '2026-04-03 12:24:56.08041+00', 'Position de départ : Allonge-toi sur le banc, les pieds bien ancrés au sol, prends la barre avec une prise plus étroite que la largeur des épaules, idéalement entre 15 et 30 cm. Exécution : Abaisse la barre de manière contrôlée jusqu''à ton bas de poitrine, en gardant les coudes près des côtés, puis pousse le poids vers le haut en étendant tes bras grâce à tes triceps.', '["Les coudes trop écartés, ce qui diminue l''engagement des triceps", "Rebondir la barre sur la poitrine, ce qui augmente le risque de blessure"]', true, '["Position yourself on the bench with a narrow grip on the barbell, hands closer than shoulder-width apart", "Keep your core engaged and feet flat on the floor for stability", "Lower the barbell slowly to your lower chest or upper abdomen while keeping elbows tucked close to your sides", "Pause briefly at the bottom position without bouncing the bar off your chest", "Press the barbell back up by extending through your triceps until arms are fully extended", "Maintain control throughout the entire range of motion"]', '["Positionne-toi sur le banc avec une prise serrée sur la barre", "Garde ton cœur engagé et les pieds bien à plat au sol pour assurer la stabilité", "Abaisse la barre lentement jusqu''à ton bas de poitrine en gardant les coudes près du corps", "Marque une courte pause en bas sans rebondir la barre sur ta poitrine", "Pousse la barre vers le haut en étendant tes bras grâce à tes triceps jusqu''à ce qu''ils soient complètement tendus", "Maintiens le contrôle pendant toute l''amplitude du mouvement"]', '["Garde les coudes proches de ton corps pendant le mouvement pour optimiser l''engagement des triceps et réduire la pression sur les épaules", "Utilise une largeur de prise qui te convient, mais suffisamment étroite pour cibler efficacement les triceps", "Contrôle la descente et évite de rebondir la barre sur ta poitrine", "Commence avec un poids plus léger que sur le développé couché classique, cette variante est plus exigeante pour les triceps", "Assure-toi de bien échauffer tes épaules, coudes et poignets avant de réaliser cet exercice"]', '["Keep elbows close to your body throughout the movement to maximize triceps engagement and reduce shoulder stress", "Use a grip width that feels comfortable but narrow enough to target the triceps effectively", "Control the descent and avoid bouncing the bar off your chest", "Start with lighter weight than regular bench press as this variation is more challenging for the triceps", "Ensure proper warm-up of shoulders, elbows, and wrists before performing this exercise"]', '705b3080-cf01-42f4-be0f-ea9e3f83599f', 'close-grip-bench-barbell', NULL, NULL);
INSERT INTO public.exercises VALUES ('def90139-ff1e-4318-a552-6505269417d0', 'Posture du Cobra', NULL, 'وضعية الكوبرا', 'Cobra pose', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/cobra-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/cobra-pose.jpg', NULL, '["Ne pousse pas trop haut, reste dans le confort.", "Roule tes épaules vers l''arrière et vers le bas.", "Engage tes muscles du dos, pas seulement tes bras."]', '["Lever trop haut et forcer le dos.", "Ne pas maintenir les hanches au sol."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "cobra pose"]', true, '2026-04-03 12:24:56.139724+00', '2026-04-03 12:24:56.139724+00', 'Position de départ : Allonge-toi sur le ventre, les paumes à plat au sol sous les épaules, les jambes étendues derrière. Exécution : Appuie sur tes mains pour soulever ta poitrine et le haut du torse, tout en gardant les hanches en contact avec le sol pour une légère flexion du dos.', '["Lever trop haut et forcer le dos.", "Ne pas maintenir les hanches au sol."]', true, '["Lie face down with hands under your shoulders.", "Press your pelvis and legs into the floor.", "Inhale and straighten your arms to lift your chest.", "Keep a slight bend in the elbows."]', '["Allonge-toi sur le ventre avec les mains sous les épaules.", "Presse ton bassin et tes jambes contre le sol.", "Inspire et tends les bras pour soulever ta poitrine.", "Garde une légère flexion dans les coudes."]', '["Ne pousse pas trop haut, reste dans le confort.", "Roule tes épaules vers l''arrière et vers le bas.", "Engage tes muscles du dos, pas seulement tes bras."]', '["Do not push up too high — keep it comfortable.", "Roll your shoulders back and down.", "Engage your back muscles, not just your arms."]', '1e381fba-eedc-410c-ba1f-1c9c255f4d0f', 'cobra-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('c8d4b851-5e73-4c69-ae54-c2f1428dd413', 'Posture de la vache (gauche)', NULL, 'وضعية البقرة (الجانب الأيسر)', 'Cow face pose (left)', 'Shoulders', '[]', 'Shoulders', 'Beginner', 16, '/videos/shoulders/cow-face-pose-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/cow-face-pose-left.jpg', NULL, '["Assure-toi d''être bien centré sur tes deux os assis.", "Garde la colonne vertébrale droite et la poitrine ouverte.", "Utilise une sangle si tes mains ne se touchent pas."]', '["Ne pas garder le dos droit, ce qui peut entraîner des tensions.", "Ne pas aligner les genoux, ce qui peut affecter l''équilibre."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "bodyweight", "cow face pose (left)"]', true, '2026-04-03 12:24:56.15727+00', '2026-04-03 12:24:56.15727+00', 'Commence assis avec les jambes croisées ou dans une position confortable. Lève ton bras gauche au-dessus de ta tête, plie le coude et fais descendre ta main dans ton dos. Puis, attrape ton bras droit derrière ton dos en partant d''en bas, essaie de joindre les mains tout en gardant la posture droite.', '["Ne pas garder le dos droit, ce qui peut entraîner des tensions.", "Ne pas aligner les genoux, ce qui peut affecter l''équilibre."]', true, '["Sit on the floor and stack your knees on top of each other.", "Reach one arm overhead and bend it behind your back.", "Reach the other arm behind your back from below.", "Clasp your fingers or use a strap between your hands."]', '["Assieds-toi sur le sol et empile tes genoux l''un sur l''autre.", "Lève un bras au-dessus de ta tête et plie-le derrière ton dos.", "Prends l''autre bras derrière ton dos en partant d''en bas.", "Joins tes doigts ou utilise une sangle entre tes mains."]', '["Assure-toi d''être bien centré sur tes deux os assis.", "Garde la colonne vertébrale droite et la poitrine ouverte.", "Utilise une sangle si tes mains ne se touchent pas."]', '["Sit evenly on both sit bones.", "Keep your spine tall and chest lifted.", "Use a strap if your hands do not reach."]', '513d039d-e6d0-459e-9ae7-4847a586871b', 'cow-face-pose-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('837ec2d9-01b7-463f-ae1d-aa3dfb2f45fa', 'Maintien de crab avec tapotement des orteils', NULL, NULL, 'Crab hold toe tap', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/crab-hold-toe-tap.mp4', NULL, NULL, NULL, '/videos/thumbnails/crab-hold-toe-tap.jpg', NULL, '["Tiens ton torse relevé et le dos droit pour garder une bonne posture", "Active tes muscles du tronc pour stabiliser ton corps pendant le mouvement", "Concentre-toi sur le maintien du poids sur le talon de la jambe de soutien", "Contrôle le mouvement de tapotement - ne te précipite pas et ne perds pas l''équilibre", "Maintiens la profondeur du squat de manière constante tout au long des répétitions"]', '["Ne pas garder le poids sur les talons", "Mouvement trop rapide entraînant une perte d''équilibre"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "crab hold toe tap"]', true, '2026-04-03 12:24:56.18924+00', '2026-04-03 12:24:56.18924+00', 'Commence dans une position de squat profond, les pieds écartés à la largeur des épaules, les bras tendus devant pour l''équilibre et le poids sur les talons.', '["Ne pas garder le poids sur les talons", "Mouvement trop rapide entraînant une perte d''équilibre"]', true, '["Start in a deep squat with thighs parallel to the floor and arms extended forward", "Keep your weight on your heels and maintain proper squat form throughout", "Lift one foot and extend it forward to tap the toe on the ground", "Return the foot to starting position while staying in the squat", "Repeat the toe tap with the opposite foot", "Continue alternating feet while holding the squat position"]', '["Commence en squat profond avec les cuisses parallèles au sol et les bras tendus devant", "Garde le poids sur tes talons et maintiens une bonne forme de squat tout au long de l''exercice", "Lève un pied et étends-le vers l''avant pour tapoter le sol avec l''orteil", "Rammène le pied à la position de départ tout en restant en squat", "Répète le tapotement avec l''autre pied", "Alterne les pieds tout en maintenant la position de squat"]', '["Tiens ton torse relevé et le dos droit pour garder une bonne posture", "Active tes muscles du tronc pour stabiliser ton corps pendant le mouvement", "Concentre-toi sur le maintien du poids sur le talon de la jambe de soutien", "Contrôle le mouvement de tapotement - ne te précipite pas et ne perds pas l''équilibre", "Maintiens la profondeur du squat de manière constante tout au long des répétitions"]', '["Keep your chest up and back straight to maintain proper posture", "Engage your core muscles to help stabilize your body during the movement", "Focus on keeping most of your weight on the supporting leg''s heel", "Control the toe tap movement - don''t rush or lose balance", "Maintain the squat depth consistently throughout all repetitions"]', '1abe4475-eab9-4532-a583-68cc06681462', 'crab-hold-toe-tap', NULL, NULL);
INSERT INTO public.exercises VALUES ('9ddefec4-1eb3-4fcc-bbb1-f9873b7c3462', 'Devil Press', NULL, 'Devil Press', 'Devil press', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/devil-press.mp4', NULL, NULL, NULL, '/videos/thumbnails/devil-press.jpg', NULL, '["Garde le ventre bien contracté tout au long du mouvement pour protéger le bas du dos", "Utilise tes hanches et tes jambes pour générer de la puissance lors de la levée au-dessus de la tête, ne repose pas uniquement sur tes bras", "Assure-toi de bien tenir les haltères pendant toutes les phases du mouvement", "Atterris doucement lorsque tu sautes en avant et en arrière pour réduire l''impact sur les articulations", "Commence avec un poids léger pour maîtriser le mouvement complexe avant de progresser"]', '["Ne pas engager le ventre, ce qui peut causer des douleurs au bas du dos", "Oublier de maintenir une bonne prise sur les haltères, ce qui peut entraîner des blessures", "Utiliser trop de poids dès le début, ce qui affecte la technique"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "devil press"]', true, '2026-04-03 12:24:56.297287+00', '2026-04-03 12:24:56.297287+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des hanches, un haltère dans chaque main à tes côtés. Exécution : Descends en burpee en posant les haltères au sol, saute en arrière en position de planche, fais une pompe, puis ramène tes pieds vers les haltères et soulève-les au-dessus de ta tête en un seul mouvement fluide.', '["Ne pas engager le ventre, ce qui peut causer des douleurs au bas du dos", "Oublier de maintenir une bonne prise sur les haltères, ce qui peut entraîner des blessures", "Utiliser trop de poids dès le début, ce qui affecte la technique"]', true, '["Place dumbbells on the ground and jump or step back into a plank position with hands gripping the dumbbell handles", "Perform a push-up while maintaining grip on the dumbbells, keeping core engaged", "Jump or step feet back toward the dumbbells, landing in a low squat position", "Explosively stand up while lifting the dumbbells from the ground to overhead in one smooth motion", "Lower the dumbbells back to the starting position with control", "Repeat the entire sequence for the prescribed number of repetitions"]', '["Pose les haltères au sol et saute ou fais un pas en arrière en position de planche en tenant les poignées des haltères", "Réalise une pompe tout en gardant les haltères en main et le ventre engagé", "Saute ou fais un pas avec tes pieds vers les haltères, atterrissant en position de squat bas", "Lève-toi explosivement en soulevant les haltères du sol au-dessus de ta tête en un mouvement fluide", "Ramène les haltères à la position de départ en contrôlant la descente", "Répète toute la séquence pour le nombre de répétitions prescrit"]', '["Garde le ventre bien contracté tout au long du mouvement pour protéger le bas du dos", "Utilise tes hanches et tes jambes pour générer de la puissance lors de la levée au-dessus de la tête, ne repose pas uniquement sur tes bras", "Assure-toi de bien tenir les haltères pendant toutes les phases du mouvement", "Atterris doucement lorsque tu sautes en avant et en arrière pour réduire l''impact sur les articulations", "Commence avec un poids léger pour maîtriser le mouvement complexe avant de progresser"]', '["Keep your core tight throughout the entire movement to protect your lower back", "Use your hips and legs to generate power for the overhead lift portion, not just your arms", "Maintain proper grip on the dumbbells throughout all phases of the movement", "Land softly when jumping back and forth to reduce impact on joints", "Start with lighter weight to master the complex movement pattern before progressing"]', '9d5a2722-801b-4741-8d9b-11e9a3a4ae2d', 'devil-press', NULL, NULL);
INSERT INTO public.exercises VALUES ('f80ef9ce-3ea7-430b-b0fe-52b1fd713812', 'Lancer Discus avec Haltère', NULL, NULL, 'Dumbbell Discus', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/dumbbell-discus.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-discus.jpg', NULL, '["Garde l''haltère près de ton corps tout au long du mouvement pour maintenir le contrôle", "Concentre-toi sur la génération de puissance à partir de ton tronc et de tes hanches plutôt que de tes bras", "Maintiens une base stable avec tes pieds bien ancrés au sol", "Commence avec un poids léger pour maîtriser le mouvement rotatif avant de progresser", "Effectue des mouvements fluides et contrôlés pour éviter les blessures au dos"]', '["Ne pas garder l''haltère proche du corps", "Trop se concentrer sur les bras au lieu de l''engagement du tronc", "Mauvaise posture lors de la rotation", "Manque de contrôle pendant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "dumbbell discus"]', true, '2026-04-03 12:24:56.409324+00', '2026-04-03 12:24:56.409324+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des épaules, un haltère à deux mains au niveau de la poitrine, bras tendus. Exécution : Fais pivoter ton torse et tes hanches d''un côté tout en gardant l''haltère à hauteur de poitrine, puis effectue une rotation explosive à travers ta sangle abdominale vers l''autre côté dans un mouvement contrôlé de lancer de discus.', '["Ne pas garder l''haltère proche du corps", "Trop se concentrer sur les bras au lieu de l''engagement du tronc", "Mauvaise posture lors de la rotation", "Manque de contrôle pendant le mouvement"]', true, '["Hold the dumbbell securely with both hands using an overhand grip at chest level", "Plant your feet firmly shoulder-width apart and engage your core muscles", "Rotate your torso and hips to one side while keeping the dumbbell close to your body", "Explosively rotate through your midsection to the opposite side in a smooth arc motion", "Control the movement on both the rotation and return phases", "Complete the specified number of repetitions alternating directions or perform all reps to one side first"]', '["Saisis fermement l''haltère à deux mains avec une prise en pronation au niveau de la poitrine", "Stabilise tes pieds écartés à la largeur des épaules et engage tes muscles abdominaux", "Fais pivoter ton torse et tes hanches d''un côté tout en gardant l''haltère près de ton corps", "Effectue une rotation explosive à travers ton abdomen vers l''autre côté dans un mouvement fluide", "Contrôle le mouvement lors des phases de rotation et de retour", "Complète le nombre de répétitions spécifié en alternant les directions ou en effectuant toutes les répétitions d''un seul côté d''abord"]', '["Garde l''haltère près de ton corps tout au long du mouvement pour maintenir le contrôle", "Concentre-toi sur la génération de puissance à partir de ton tronc et de tes hanches plutôt que de tes bras", "Maintiens une base stable avec tes pieds bien ancrés au sol", "Commence avec un poids léger pour maîtriser le mouvement rotatif avant de progresser", "Effectue des mouvements fluides et contrôlés pour éviter les blessures au dos"]', '["Keep the dumbbell close to your body throughout the entire movement to maintain control", "Focus on generating power from your core and hips rather than just your arms", "Maintain a stable base with your feet planted firmly on the ground", "Start with lighter weight to master the rotational movement pattern before progressing", "Keep your movements smooth and controlled to avoid injury to the spine"]', '4426c121-33b6-42c1-aa78-8d295d8fd687', 'dumbbell-discus', NULL, NULL);
INSERT INTO public.exercises VALUES ('fb12cc73-ca5c-42cd-8ae4-bd336d64b6f8', 'Dumbbell Double Snatch', NULL, 'دبل سناتش بالدومبل', 'Dumbbell double snatch', 'Bodyweight', '[]', 'Bodyweight', 'Advanced', 2, '/videos/bodyweight/dumbbell-double-snatch.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-double-snatch.jpg', NULL, '["Restez proche de votre corps avec les haltères tout au long du mouvement pour maintenir le contrôle et l''efficacité", "Concentrez-vous sur la puissance générée par vos jambes et vos hanches plutôt que de compter uniquement sur vos bras", "Gardez la colonne vertébrale neutre et évitez de courber le dos pendant le levé", "Entraînez-vous d''abord avec des poids plus légers pour maîtriser la coordination avant de progresser vers des charges plus lourdes", "Assurez-vous d''avoir une bonne mobilité des épaules avant d''effectuer cet exercice pour éviter les blessures."]', '["Ne pas garder les haltères près du corps, entraînant une perte de contrôle", "Tirer uniquement avec les bras au lieu d''utiliser les jambes pour générer de la puissance"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "dumbbell double snatch"]', true, '2026-04-03 12:24:56.418835+00', '2026-04-03 12:24:56.418835+00', 'Position de départ : Mesurez-vous debout, les pieds à la largeur des épaules, en tenant deux haltères au sol entre vos pieds avec une prise en pronation. Exécution : Élevez explosivement les deux haltères du sol au-dessus de votre tête en un seul mouvement fluide. Poussez avec vos hanches et vos jambes tout en tirant les poids vers le haut et en les attrapant avec les bras tendus au-dessus de votre tête.', '["Ne pas garder les haltères près du corps, entraînant une perte de contrôle", "Tirer uniquement avec les bras au lieu d''utiliser les jambes pour générer de la puissance"]', true, '["Begin in a squat position with dumbbells on the floor, keeping your chest up and back straight", "Initiate the movement by driving powerfully through your heels and extending your hips and knees", "As the dumbbells reach hip level, explosively shrug your shoulders and pull your elbows high", "Continue the upward momentum by pulling yourself under the weights as they reach shoulder height", "Catch the dumbbells overhead with arms fully extended and feet planted firmly", "Lower the weights back to the starting position in a controlled manner"]', '["Commencez en position accroupie avec les haltères au sol, gardez votre poitrine relevée et le dos droit", "Initiez le mouvement en poussant fermement sur vos talons tout en étendant vos hanches et vos genoux", "Lorsque les haltères atteignent le niveau des hanches, haussez explosivement vos épaules et tirez vos coudes vers le haut", "Poursuivez l''élan en vous plaçant sous les poids lorsqu''ils atteignent la hauteur des épaules", "Attrapez les haltères au-dessus de votre tête avec les bras pleinement tendus et les pieds bien ancrés au sol", "Abaissez les haltères de manière contrôlée jusqu''à la position de départ."]', '["Restez proche de votre corps avec les haltères tout au long du mouvement pour maintenir le contrôle et l''efficacité", "Concentrez-vous sur la puissance générée par vos jambes et vos hanches plutôt que de compter uniquement sur vos bras", "Gardez la colonne vertébrale neutre et évitez de courber le dos pendant le levé", "Entraînez-vous d''abord avec des poids plus légers pour maîtriser la coordination avant de progresser vers des charges plus lourdes", "Assurez-vous d''avoir une bonne mobilité des épaules avant d''effectuer cet exercice pour éviter les blessures."]', '["Keep the dumbbells close to your body throughout the entire movement to maintain control and efficiency", "Focus on generating power from your legs and hips rather than relying solely on your arms", "Maintain a neutral spine position and avoid rounding your back during the lift", "Practice the movement with lighter weights first to master the coordination before progressing to heavier loads", "Ensure adequate shoulder mobility before attempting this exercise to prevent injury"]', 'f49f3159-4eed-4d0d-a640-497886c309b0', 'dumbbell-double-snatch', NULL, NULL);
INSERT INTO public.exercises VALUES ('0021e1b7-cb59-4d4b-8502-f68efb9e8284', 'Élévation latérale arrière avec haltères', NULL, 'رفع جانبي خلفي بالدمبل', 'Dumbbell Lying Rear Lateral Raise', 'Shoulders', '[]', 'Shoulders', 'Beginner', 2, '/videos/shoulders/dumbbell-lying-rear-lateral-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-lying-rear-lateral-raise.jpg', NULL, '["Garde bien ta poitrine collée contre le banc durant tout le mouvement pour assurer une bonne forme et éviter d''utiliser l''élan.", "Maintiens une légère flexion des coudes et évite de tendre complètement les bras pour protéger tes articulations.", "Concentre-toi sur la contraction de tes omoplates en haut du mouvement pour maximiser l''activation des deltoïdes arrière.", "Adopte un rythme contrôlé, surtout lors de la phase de descente, pour garder la tension sur les muscles ciblés.", "Commence avec des poids légers car cet exercice demande une forme précise et les deltoïdes arrière sont souvent plus faibles."]', '["Utiliser trop de poids, ce qui nuit à la forme et augmente le risque de blessure.", "Bouger le torse au lieu de garder la position stable sur le banc."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["shoulders", "dumbbell", "dumbbell lying rear lateral raise"]', true, '2026-04-03 12:24:56.487936+00', '2026-04-03 12:24:56.487936+00', 'Allonge-toi sur un banc incliné, le torse bien soutenu, et prépare-toi à travailler tes épaules. Prends un haltère dans chaque main et laisse tes bras pendre vers le bas, les coudes légèrement fléchis. C''est parti pour un exercice ciblé sur tes deltoïdes arrière !', '["Utiliser trop de poids, ce qui nuit à la forme et augmente le risque de blessure.", "Bouger le torse au lieu de garder la position stable sur le banc."]', true, '["Position yourself face down on an inclined bench with your chest fully supported and feet planted firmly on the floor", "Hold a dumbbell in each hand with arms hanging straight down and maintain a slight bend in your elbows throughout the movement", "Initiate the movement by lifting the dumbbells out to your sides in a wide arc, leading with your pinkies", "Raise the weights until your arms are parallel to the floor and you feel a strong contraction in your rear deltoids", "Slowly lower the dumbbells back to the starting position with control, maintaining the same arc path"]', '["Positionne-toi face contre terre sur un banc incliné avec le torse bien soutenu et les pieds fermement ancrés au sol.", "Prends un haltère dans chaque main, les bras pendus et garde une légère flexion des coudes tout au long du mouvement.", "Commence en levant les haltères sur les côtés en traçant un large arc, en menant avec les petits doigts.", "Lève les poids jusqu''à ce que tes bras soient parallèles au sol et ressens une forte contraction dans tes deltoïdes arrière.", "Redescends lentement les haltères à la position de départ avec contrôle, en gardant le même chemin en arc."]', '["Garde bien ta poitrine collée contre le banc durant tout le mouvement pour assurer une bonne forme et éviter d''utiliser l''élan.", "Maintiens une légère flexion des coudes et évite de tendre complètement les bras pour protéger tes articulations.", "Concentre-toi sur la contraction de tes omoplates en haut du mouvement pour maximiser l''activation des deltoïdes arrière.", "Adopte un rythme contrôlé, surtout lors de la phase de descente, pour garder la tension sur les muscles ciblés.", "Commence avec des poids légers car cet exercice demande une forme précise et les deltoïdes arrière sont souvent plus faibles."]', '["Keep your chest pressed firmly against the bench throughout the entire movement to maintain proper form and prevent using momentum", "Maintain a slight bend in your elbows and avoid straightening your arms completely to protect your joints", "Focus on squeezing your shoulder blades together at the top of the movement to maximize rear deltoid activation", "Use a controlled tempo, especially on the lowering phase, to maintain tension on the target muscles", "Start with lighter weights as this exercise requires precise form and the rear deltoids are typically weaker muscles"]', 'f181cc8e-9816-4205-b025-3b23cb30720b', 'dumbbell-lying-rear-lateral-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('8819769c-8187-4623-bb41-b4c000cdd9ab', 'Ciseaux avec Haltères', NULL, 'قصة الهلتري', 'Dumbbell Scissors', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/dumbbell-scissors.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-scissors.jpg', NULL, '["Maintenez votre sangle abdominale engagée pendant l''exercice pour rester en équilibre et protéger votre dos.", "Ne laissez pas votre genou avant dépasser vos orteils lors de la fente.", "Adoptez un tempo contrôlé et évitez de précipiter le mouvement pour préserver une bonne technique.", "Commencez avec des poids plus légers jusqu''à maîtriser la coordination entre le bas et le haut du corps.", "Assurez-vous d''avoir suffisamment d''espace autour de vous avant de commencer cet exercice dynamique."]', '["Oublier de garder le tronc droit, ce qui peut entraîner des tensions lombaires.", "Ne pas contrôler la descente pendant les fentes, ce qui pourrait augmenter le risque de blessure."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "dumbbell scissors"]', true, '2026-04-03 12:24:56.556021+00', '2026-04-03 12:24:56.556021+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des hanches, avec un haltère dans chaque main à hauteur des épaules et les bras tendus au-dessus de la tête. Exécution : Sautez et changez la position de vos jambes de manière à imiter un mouvement de ciseaux tout en gardant les haltères en position haute, en alternant quelle jambe est en avant et laquelle est en arrière.', '["Oublier de garder le tronc droit, ce qui peut entraîner des tensions lombaires.", "Ne pas contrôler la descente pendant les fentes, ce qui pourrait augmenter le risque de blessure."]', true, '["Stand with feet hip-width apart, holding a dumbbell in each hand at shoulder height with arms bent at 90 degrees", "Step your right foot forward into a lunge position while simultaneously pressing the left dumbbell overhead", "Push off your right foot and immediately step your left foot forward into a lunge while lowering the left arm and pressing the right dumbbell overhead", "Continue alternating legs in a scissor-like motion while alternating overhead presses with each step", "Maintain an upright torso throughout the movement and control the descent into each lunge", "Complete the desired number of repetitions, ensuring equal work on both sides"]', '["Tenez-vous debout, les pieds écartés à la largeur des hanches, les bras fléchis à 90 degrés avec un haltère dans chaque main à hauteur des épaules.", "Avancez votre pied droit en position de fente tout en levant simultanément l''haltère gauche au-dessus de votre tête.", "Poussez avec votre pied droit et avancez immédiatement votre pied gauche en position de fente tout en baissant l''haltère gauche et en levant l''haltère droit au-dessus de votre tête.", "Alternez les jambes dans un mouvement de ciseaux tout en effectuant des poussées au-dessus de la tête à chaque pas.", "Gardez le torse droit pendant tout le mouvement et contrôlez votre descente dans chaque fente.", "Réalisez le nombre de répétitions souhaité en veillant à travailler de manière égale de chaque côté."]', '["Maintenez votre sangle abdominale engagée pendant l''exercice pour rester en équilibre et protéger votre dos.", "Ne laissez pas votre genou avant dépasser vos orteils lors de la fente.", "Adoptez un tempo contrôlé et évitez de précipiter le mouvement pour préserver une bonne technique.", "Commencez avec des poids plus légers jusqu''à maîtriser la coordination entre le bas et le haut du corps.", "Assurez-vous d''avoir suffisamment d''espace autour de vous avant de commencer cet exercice dynamique."]', '["Keep your core engaged throughout to maintain balance and protect your lower back", "Don''t let your front knee extend past your toes during the lunge portion", "Use a controlled tempo rather than rushing through the movement to maintain proper form", "Start with lighter weights until you master the coordination between the lower and upper body movements", "Ensure you have adequate space around you before beginning this dynamic exercise"]', '0d0368ee-f03d-4ef9-95db-06a56434ea55', 'dumbbell-scissors', NULL, NULL);
INSERT INTO public.exercises VALUES ('05c6d7f1-f932-42e1-b6cf-badfd63e60a9', 'Uppercuts avec haltères', NULL, 'Uppercuts avec haltères', 'Dumbbell upper cuts', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/dumbbell-upper-cuts.mp4', NULL, NULL, NULL, '/videos/thumbnails/dumbbell-upper-cuts.jpg', NULL, '["Gardez toujours votre ceinture abdominale engagée pour protéger le bas du dos.", "Générez de la puissance grâce à la rotation de vos jambes et de votre torse, pas seulement avec vos bras.", "Maintenez le contrôle durant les phases de montée et de retour pour maximiser l''engagement musculaire.", "Commencez avec des poids légers pour maîtriser la coordination avant de passer à des haltères plus lourds.", "Gardez votre main non active près de votre corps pour équilibrer et vous protéger."]', '["Se pencher en avant pendant l''exercice.", "Ne pas engager suffisamment le tronc et la zone abdominale."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "dumbbell upper cuts"]', true, '2026-04-03 12:24:56.622106+00', '2026-04-03 12:24:56.622106+00', 'Mettez-vous en position debout, les pieds écartés à la largeur des épaules, en tenant un haltère dans chaque main au niveau de la poitrine, paumes vers le haut et coudes fléchis à 90 degrés. C''est le moment de frapper fort !', '["Se pencher en avant pendant l''exercice.", "Ne pas engager suffisamment le tronc et la zone abdominale."]', true, '["Stand with feet shoulder-width apart, holding a dumbbell in each hand at chest level with palms facing your body", "Engage your core and slightly bend your knees in an athletic stance", "Rotate your torso to the right while simultaneously driving your left hand upward in an uppercut motion, extending through your legs and core", "Return to starting position with control, then rotate left while driving your right hand up in an uppercut", "Continue alternating sides in a smooth, controlled rhythm while maintaining proper form", "Complete the desired number of repetitions, ensuring equal work on both sides"]', '["Tenez-vous debout, pieds écartés à la largeur des épaules, avec un haltère dans chaque main au niveau de la poitrine.", "Engagez votre ceinture abdominale et fléchissez légèrement les genoux pour une posture athlétique.", "Tournez votre torse vers la droite tout en poussant simultanément votre main gauche vers le haut dans un mouvement d''uppercut, en utilisant la force de vos jambes et de votre corps.", "Retournez à la position de départ de manière contrôlée, puis tournez vers la gauche en poussant votre main droite vers le haut dans un uppercut.", "Alternez les côtés en gardant un rythme fluide et contrôlé tout en maintenant une bonne forme.", "Terminez le nombre de répétitions souhaité, en veillant à travailler de manière équilibrée des deux côtés."]', '["Gardez toujours votre ceinture abdominale engagée pour protéger le bas du dos.", "Générez de la puissance grâce à la rotation de vos jambes et de votre torse, pas seulement avec vos bras.", "Maintenez le contrôle durant les phases de montée et de retour pour maximiser l''engagement musculaire.", "Commencez avec des poids légers pour maîtriser la coordination avant de passer à des haltères plus lourds.", "Gardez votre main non active près de votre corps pour équilibrer et vous protéger."]', '["Keep your core engaged throughout the entire movement to protect your lower back", "Generate power from your legs and torso rotation, not just your arms", "Maintain control during both the upward drive and return phases to maximize muscle engagement", "Start with lighter weights to master the coordination before progressing to heavier dumbbells", "Keep your non-working hand close to your body for balance and protection"]', '01924d84-4c88-4476-b0dc-8fd92616b362', 'dumbbell-upper-cuts', NULL, NULL);
INSERT INTO public.exercises VALUES ('5fae8d6d-60a4-4e22-9827-c5ded9e0e548', 'Étirement de la Figure Quatre', NULL, 'Stretch Figure Four', 'Figure Four Stretch (R)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/figure-four-stretch-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/figure-four-stretch-r.jpg', NULL, '["Garde ton pied droit fléchi pour protéger ton articulation du genou", "Ne force pas l''étirement - utilise une pression douce et constante", "Garde le bas du dos appuyé contre le sol tout au long de l''exercice", "Si tu ne peux pas atteindre l''arrière de ta cuisse, utilise une serviette ou une sangle pour t''aider", "Stoppe immédiatement si tu ressens une douleur au genou"]', '["Ne pas garder la tête et les épaules détendues sur le sol", "Forcer l''étirement au lieu d''utiliser une pression douce"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "figure four stretch (r)"]', true, '2026-04-03 12:24:56.722381+00', '2026-04-03 12:24:56.722381+00', 'Position de départ : allonge-toi sur le dos, genoux pliés et pieds à plat sur le sol. Place ta cheville droite sur ton genou gauche pour former une figure quatre. Exécution : passe par l''écart entre tes jambes pour saisir l''arrière de ta cuisse gauche et tire doucement ton genou gauche vers ta poitrine tout en gardant la tête et les épaules détendues au sol.', '["Ne pas garder la tête et les épaules détendues sur le sol", "Forcer l''étirement au lieu d''utiliser une pression douce"]', true, '["Lie on your back with both knees bent and feet flat on the floor", "Lift your right leg and place your right ankle on top of your left thigh, just above the knee", "Reach through the gap between your legs and clasp your hands behind your left thigh", "Gently pull your left thigh toward your chest while keeping your head and shoulders relaxed on the ground", "Hold the stretch for 20-30 seconds, feeling the stretch in your right hip and glute", "Release slowly and repeat on the opposite side"]', '["Allonge-toi sur le dos avec les genoux pliés et les pieds à plat sur le sol", "Lève ta jambe droite et place ta cheville droite sur ta cuisse gauche, juste au-dessus du genou", "Atteins l''écart entre tes jambes et prends l''arrière de ta cuisse gauche avec tes mains", "Tire doucement ta cuisse gauche vers ta poitrine tout en gardant la tête et les épaules détendues au sol", "Maintiens l''étirement pendant 20 à 30 secondes, en ressentant l''étirement dans ta hanche et ton fessier droits", "Relâche lentement et répète de l''autre côté"]', '["Garde ton pied droit fléchi pour protéger ton articulation du genou", "Ne force pas l''étirement - utilise une pression douce et constante", "Garde le bas du dos appuyé contre le sol tout au long de l''exercice", "Si tu ne peux pas atteindre l''arrière de ta cuisse, utilise une serviette ou une sangle pour t''aider", "Stoppe immédiatement si tu ressens une douleur au genou"]', '["Keep your right foot flexed to protect your knee joint", "Don''t force the stretch - use gentle, steady pressure", "Keep your lower back pressed against the floor throughout the movement", "If you can''t reach behind your thigh, use a towel or strap for assistance", "Stop immediately if you feel any knee pain"]', '005ba868-d8b1-499f-9a88-b2cf722e6bdf', 'figure-four-stretch-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('a3e21013-5c7a-4426-9984-5d05e7c6ac09', 'Élévations Frontales avec Deux Haltères', NULL, NULL, 'Front Two-Dumbbell Raise', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/front-two-dumbbell-raise.mp4', NULL, NULL, NULL, '/videos/thumbnails/front-two-dumbbell-raise.jpg', NULL, '["Engage ton tronc et évite d''archer le dos ou d''utiliser l''élan pour soulever les poids", "Choisis un poids qui te permet de garder une bonne forme tout au long des répétitions", "Arrête-toi à la hauteur des épaules pour éviter les tensions et garder la tension sur les muscles ciblés", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur la vitesse pour maximiser l''activation musculaire", "Expire pendant la phase de levée et inspire lors de la descente."]', '["Soulever trop lourd et perdre la forme correcte", "Bouger rapidement sans contrôler la montée et la descente."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "front two-dumbbell raise"]', true, '2026-04-03 12:24:56.802044+00', '2026-04-03 12:24:56.802044+00', 'Position de départ : Tiens-toi debout, les pieds écartés à la largeur des hanches, une haltère dans chaque main, bras le long du corps, paumes vers toi. Exécution : Élève simultanément les deux haltères vers l''avant et jusqu''à la hauteur des épaules avec les bras tendus, puis redescends lentement à la position de départ.', '["Soulever trop lourd et perdre la forme correcte", "Bouger rapidement sans contrôler la montée et la descente."]', true, '["Stand with feet hip-width apart and engage your core muscles for stability", "Hold one dumbbell in each hand with a neutral grip, arms fully extended at your sides", "Keep a slight bend in your elbows and maintain this angle throughout the movement", "Raise both dumbbells simultaneously in front of your body until they reach shoulder height", "Pause briefly at the top position, then slowly lower the weights back to starting position", "Maintain controlled movement throughout both the lifting and lowering phases"]', '["Tiens-toi droit, pieds écartés à la largeur des hanches, engage ton tronc pour la stabilité", "Prends une haltère dans chaque main avec une prise neutre, bras complètement tendus à tes côtés", "Garde une légère flexion dans les coudes et maintiens cet angle tout au long de l''exercice", "Lève les deux haltères en même temps devant toi jusqu''à atteindre la hauteur des épaules", "Fais une pause en haut, puis redescends lentement les poids à la position de départ", "Reste contrôlé pendant toute la montée et la descente des haltères."]', '["Engage ton tronc et évite d''archer le dos ou d''utiliser l''élan pour soulever les poids", "Choisis un poids qui te permet de garder une bonne forme tout au long des répétitions", "Arrête-toi à la hauteur des épaules pour éviter les tensions et garder la tension sur les muscles ciblés", "Concentre-toi sur des mouvements lents et contrôlés plutôt que sur la vitesse pour maximiser l''activation musculaire", "Expire pendant la phase de levée et inspire lors de la descente."]', '["Keep your core engaged and avoid arching your back or using momentum to lift the weights", "Use a weight that allows you to maintain proper form throughout all repetitions", "Stop at shoulder height to avoid impingement and maintain tension on the target muscles", "Focus on slow, controlled movements rather than speed to maximize muscle activation", "Breathe out during the lifting phase and inhale during the lowering phase"]', 'dc848ac2-ca46-4c70-a8cc-dd2a76e546cf', 'front-two-dumbbell-raise', NULL, NULL);
INSERT INTO public.exercises VALUES ('96a9693c-59e3-43d9-be36-e3b92ab99f63', 'Lune à moitié (gauche)', NULL, NULL, 'Half moon (left)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/half-moon-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/half-moon-left.jpg', NULL, '["Garde la jambe de soutien légèrement fléchie pour maintenir ta stabilité et éviter de forcer le genou", "Active ton abdomen tout au long du mouvement pour garder ton équilibre et protéger le bas de ton dos", "Concentre-toi sur la création d''une ligne droite de ta jambe levée à ton bras tendu", "Garde les hanches carrées au sol, évite de les ouvrir", "Commence avec la main au sol pour te soutenir avant de tenter de lever le bras"]', '["Oublier d''engager le cœur et perdre ainsi son équilibre", "Soulever les hanches au lieu de les garder carrées"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "half moon (left)"]', true, '2026-04-03 12:24:56.965493+00', '2026-04-03 12:24:56.965493+00', 'Position de départ : Tiens-toi sur ta jambe gauche en te penchant en avant, la main droite au sol pour le soutien et la jambe droite levée derrière toi. Exécution : Reste en équilibre tout en allongeant ton bras gauche vers le plafond, formant une ligne droite depuis ta jambe levée jusqu''à ton bras tendu.', '["Oublier d''engager le cœur et perdre ainsi son équilibre", "Soulever les hanches au lieu de les garder carrées"]', true, '["Begin in a standing forward fold and shift your weight onto your left leg", "Place your right hand on the ground directly under your shoulder for support", "Lift your right leg behind you until it''s parallel to the floor", "Engage your core and find your balance on your standing leg", "Slowly extend your left arm up toward the ceiling", "Hold the position while maintaining alignment from your lifted leg through your extended arm"]', '["Commence en te penchant en avant sur tes jambes et transfère ton poids sur la jambe gauche", "Pose ta main droite au sol, directement sous ton épaule pour le soutien", "Lève ta jambe droite derrière toi jusqu''à ce qu''elle soit parallèle au sol", "Active bien ton abdomen et trouve ton équilibre sur la jambe de soutien", "Étends lentement ton bras gauche vers le plafond", "Reste dans cette position en maintenant une ligne droite de ta jambe levée à ton bras étendu"]', '["Garde la jambe de soutien légèrement fléchie pour maintenir ta stabilité et éviter de forcer le genou", "Active ton abdomen tout au long du mouvement pour garder ton équilibre et protéger le bas de ton dos", "Concentre-toi sur la création d''une ligne droite de ta jambe levée à ton bras tendu", "Garde les hanches carrées au sol, évite de les ouvrir", "Commence avec la main au sol pour te soutenir avant de tenter de lever le bras"]', '["Keep your standing leg slightly bent to maintain stability and prevent knee strain", "Engage your core throughout the entire movement to maintain balance and protect your lower back", "Focus on creating one straight line from your lifted leg through your torso to your raised arm", "Keep your hips square to the ground rather than allowing them to open up", "Start with your hand on the ground for support before attempting to lift your arm"]', '37e6d334-06b4-4068-a9e4-5b806cbec2b6', 'half-moon-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('2d97a4f5-83fc-4944-8c6c-b45d13cbaa87', 'Planches alternées', NULL, NULL, 'High plank to low plank', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/high-plank-to-low-plank.mp4', NULL, NULL, NULL, '/videos/thumbnails/high-plank-to-low-plank.jpg', NULL, '["Garde tes hanches à niveau et évite de faire pivoter ton torse pendant la transition.", "Maintiens un core solide pour protéger ton bas du dos et stabiliser ton corps.", "Pose tes mains et avant-bras au même endroit pour garder un bon alignement.", "Contrôle le rythme de tes mouvements, évite de précipiter les transitions.", "Place tes pieds à la largeur des hanches pour plus de stabilité durant l''exercice."]', '["Ne pas garder le corps en ligne droite.", "Utiliser l''élan au lieu de contrôler les mouvements."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "high plank to low plank"]', true, '2026-04-03 12:24:57.120562+00', '2026-04-03 12:24:57.120562+00', 'Commence en position de planche haute, les bras tendus et les mains sous les épaules. Abaisse-toi en planche basse, un bras à la fois, puis remonte en planche haute de la même manière.', '["Ne pas garder le corps en ligne droite.", "Utiliser l''élan au lieu de contrôler les mouvements."]', true, '["Start in a high plank position with hands flat on the ground directly under your shoulders", "Keep your core engaged and body in a straight line throughout the entire movement", "Lower down to forearm plank by placing one forearm down at a time where your hands were positioned", "Press back up to high plank by placing one hand at a time back on the ground where your forearms were", "Alternate which arm leads the movement to work both sides evenly", "Maintain controlled movements throughout, avoiding any rushing or momentum"]', '["Débute en planche haute, mains bien à plat sous les épaules.", "Garde ton core engagé et ton corps en ligne droite pendant tout l''exercice.", "Descends en planche basse en plaçant un avant-bras au sol à la fois.", "Remonte en planche haute en repositionnant un bras à la fois sur le sol.", "Alterne l''ordre des bras pour travailler les deux côtés de manière équilibrée.", "Contrôle bien tes mouvements, évite de te précipiter ou d''utiliser l''élan."]', '["Garde tes hanches à niveau et évite de faire pivoter ton torse pendant la transition.", "Maintiens un core solide pour protéger ton bas du dos et stabiliser ton corps.", "Pose tes mains et avant-bras au même endroit pour garder un bon alignement.", "Contrôle le rythme de tes mouvements, évite de précipiter les transitions.", "Place tes pieds à la largeur des hanches pour plus de stabilité durant l''exercice."]', '["Keep your hips level and avoid rotating your torso as you transition between positions", "Maintain a tight core throughout to protect your lower back and stabilize your body", "Place your hands and forearms in the same spots to maintain proper alignment", "Control the tempo of the movement rather than rushing through the transitions", "Keep your feet hip-width apart for better stability during the exercise"]', 'f21fa91d-22fb-4b78-bc6a-50165e5cb8ad', 'high-plank-to-low-plank', NULL, NULL);
INSERT INTO public.exercises VALUES ('f2105491-c6a5-4d9e-b04d-c7e5188d63af', 'Pompes avec toucher d''épaule en in et out', NULL, NULL, 'In and out Shoulder tap push ups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/in-and-out-shoulder-tap-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/in-and-out-shoulder-tap-push-ups.jpg', NULL, '["Garde ton ventre serré pour éviter que tes hanches ne s''affaissent ou que ton corps ne forme un angle trop aigu", "Atterris doucement lorsque tu sautes les pieds pour minimiser l''impact sur tes articulations", "Maintiens une ligne droite de la tête aux talons à chaque étape de l''exercice", "Limite le déplacement de poids pendant les touches d''épaule pour travailler ta stabilité abdominale", "Contrôle le rythme au lieu de précipiter le mouvement pour améliorer ta forme et l''efficacité"]', '["Ne pas maintenir une posture droite", "Ne pas engager le core"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "in and out shoulder tap push ups"]', true, '2026-04-03 12:24:57.198771+00', '2026-04-03 12:24:57.198771+00', 'Position de départ : Mets-toi en position de planche haute, les mains écartées à la largeur des épaules, le ventre engagé et le corps formant une ligne droite de la tête aux talons. Exécution : Écarte les pieds, fais une pompe, ramène les pieds ensemble, puis lève une main pour toucher l''épaule opposée avant de recommencer.', '["Ne pas maintenir une posture droite", "Ne pas engager le core"]', true, '["Start in a high plank position with hands directly under shoulders and feet together", "Jump both feet out wide to about shoulder-width apart while maintaining the plank position", "Lower your chest toward the ground in a push-up motion, keeping elbows at a 45-degree angle", "Push back up to the starting position and immediately jump feet back together", "Lift one hand off the ground and tap the opposite shoulder, then return hand to the ground", "Repeat the entire sequence, alternating which hand performs the shoulder tap"]', '["Prends une position de planche haute, les mains sous les épaules et les pieds joints", "Saute les deux pieds pour les écarter jusqu''à la largeur des épaules tout en gardant la position de planche", "Descends la poitrine vers le sol en faisant une pompe, les coudes formant un angle de 45 degrés", "Repousse pour revenir à la position de départ et saute immédiatement pour ramener les pieds ensemble", "Lève une main du sol et touche l''épaule opposée, puis retourne la main au sol", "Répète toute la séquence, en alternant la main qui touche l''épaule"]', '["Garde ton ventre serré pour éviter que tes hanches ne s''affaissent ou que ton corps ne forme un angle trop aigu", "Atterris doucement lorsque tu sautes les pieds pour minimiser l''impact sur tes articulations", "Maintiens une ligne droite de la tête aux talons à chaque étape de l''exercice", "Limite le déplacement de poids pendant les touches d''épaule pour travailler ta stabilité abdominale", "Contrôle le rythme au lieu de précipiter le mouvement pour améliorer ta forme et l''efficacité"]', '["Keep your core tight throughout the entire movement to prevent hip sagging or pike position", "Land softly when jumping feet in and out to minimize impact on joints", "Maintain a straight line from head to heels during all phases of the exercise", "Keep minimal weight shift when performing shoulder taps to challenge core stability", "Control the tempo rather than rushing through the movement for better form and effectiveness"]', 'c6e3375f-ad53-425b-9313-72265c9212e2', 'in-and-out-shoulder-tap-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('d2ac6295-5944-43f9-a3b6-c73128e889f0', 'Pompes inclinées larges', NULL, NULL, 'Inclined wide push up', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/inclined-wide-push-up.mp4', NULL, NULL, NULL, '/videos/thumbnails/inclined-wide-push-up.jpg', NULL, '["Garde ton centre engagé et évite de laisser tes hanches s''affaisser ou se redresser", "Plus la surface est haute, plus l''exercice est facile - ajuste la hauteur selon ton niveau de forme physique", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse, prends 2-3 secondes pour descendre et 1-2 secondes pour remonter", "Stoppe si tu ressens une douleur dans les poignets, les épaules ou le bas du dos", "Une position des mains large cible davantage les muscles externes de la poitrine par rapport aux pompes standard."]', '["Ne pas engendrer de tension dans le bas du dos", "Avoir une forme incorrecte peut réduire l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "inclined wide push up"]', true, '2026-04-03 12:24:57.333099+00', '2026-04-03 12:24:57.333099+00', 'Cet exercice cible la poitrine avec un bon angle d''inclinaison, parfait pour développer la force et la définition musculaire.', '["Ne pas engendrer de tension dans le bas du dos", "Avoir une forme incorrecte peut réduire l''efficacité de l''exercice."]', true, '["Place your hands on an elevated surface (bench, step, or sturdy chair) wider than shoulder-width apart, with fingers pointing forward", "Step your feet back until your body forms a straight line from head to heels, engaging your core", "Lower your chest toward the elevated surface by bending your elbows outward at roughly 45 degrees from your body", "Descend until your chest nearly touches the surface or you feel a stretch across your chest", "Push through your palms to return to the starting position, keeping your body in a straight line", "Repeat for desired repetitions while maintaining proper form throughout"]', '["Place tes mains sur une surface surélevée (banc, marche ou chaise solide) plus large que la largeur des épaules, les doigts pointant vers l''avant", "Recule tes pieds jusqu''à ce que ton corps forme une ligne droite de la tête aux talons, en engageant ton centre", "Abaisse ta poitrine vers la surface surélevée en pliant tes coudes vers l''extérieur à environ 45 degrés", "Descends jusqu''à ce que ta poitrine touche presque la surface ou que tu ressentes un étirement dans ta poitrine", "Pousse sur tes paumes pour revenir à la position de départ, en maintenant ton corps bien droit", "Répète le mouvement pour le nombre de répétitions souhaité, tout en gardant une bonne forme."]', '["Garde ton centre engagé et évite de laisser tes hanches s''affaisser ou se redresser", "Plus la surface est haute, plus l''exercice est facile - ajuste la hauteur selon ton niveau de forme physique", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse, prends 2-3 secondes pour descendre et 1-2 secondes pour remonter", "Stoppe si tu ressens une douleur dans les poignets, les épaules ou le bas du dos", "Une position des mains large cible davantage les muscles externes de la poitrine par rapport aux pompes standard."]', '["Keep your core tight and avoid letting your hips sag or pike upward", "The higher the surface, the easier the exercise becomes - adjust height based on your fitness level", "Focus on controlled movement rather than speed, taking 2-3 seconds to lower and 1-2 seconds to push up", "Stop if you feel pain in your wrists, shoulders, or lower back", "Wide hand placement targets the outer chest muscles more than standard push-ups"]', '0ba53212-9702-4b66-bb9d-d7b9fa12abf2', 'inclined-wide-push-up', NULL, NULL);
INSERT INTO public.exercises VALUES ('2e40df4c-baa9-45e5-9b8f-c27cc1cf15bb', 'Sauts en Squat', NULL, 'قفزات في القرفصاء', 'Jump Squats - Squat Jumps', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/jump-squats-squat-jumps.mp4', NULL, NULL, NULL, '/videos/thumbnails/jump-squats-squat-jumps.jpg', NULL, '["Atterris doucement pour éviter les chocs", "Absorbe l''impact avec tes jambes", "Ne verrouille pas tes genoux lors de l''atterrissage", "Gagne en puissance grâce à tes jambes et tes hanches", "Idéal pour développer une puissance explosive"]', '["Atterrissage sur les jambes tendues", "Mauvaise posture en squat", "Ne pas utiliser suffisamment d''élan", "Ne pas activer les hanches pour le saut", "Oublier de garder le dos droit"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "jump squats - squat jumps"]', true, '2026-04-03 12:24:57.381798+00', '2026-04-03 12:24:57.381798+00', 'Renforce tes quadriceps avec des sauts explosifs qui combinent force et puissance.', '["Atterrissage sur les jambes tendues", "Mauvaise posture en squat", "Ne pas utiliser suffisamment d''élan", "Ne pas activer les hanches pour le saut", "Oublier de garder le dos droit"]', true, '["Start in squat position", "Explode up, jumping off floor", "Land softly with bent knees", "Immediately descend into next squat"]', '["Adopte la position de squat", "Sauter avec force en décollant du sol", "Atterrir en douceur en fléchissant les genoux", "Descends immédiatement dans le squat suivant"]', '["Atterris doucement pour éviter les chocs", "Absorbe l''impact avec tes jambes", "Ne verrouille pas tes genoux lors de l''atterrissage", "Gagne en puissance grâce à tes jambes et tes hanches", "Idéal pour développer une puissance explosive"]', '["Land softly (quiet landings)", "Absorb impact with legs", "Don''t lock knees on landing", "Power comes from legs and hips", "Great for explosive power"]', '90596c5a-056c-4af1-a992-a6ffaadd8999', 'jump-squats-squat-jumps', NULL, NULL);
INSERT INTO public.exercises VALUES ('c43ef89c-b492-4f17-90bd-6aff5fa06a5c', 'Kettlebell Get-Up Turc (Style Fente)', NULL, NULL, 'Kettlebell Turkish Get-Up (Lunge style) v2', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 128, '/videos/quadriceps/kettlebell-turkish-get-up-lunge-style-v2.mp4', NULL, NULL, NULL, '/videos/thumbnails/kettlebell-turkish-get-up-lunge-style-v2.jpg', NULL, '["Maintiens une stabilité constante au-dessus de ta tête, ne laisse jamais le kettlebell dériver en avant ou en arrière.", "Veille à ce que ton genou avant reste aligné avec tes orteils pendant la descente de la fente.", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour garder une bonne forme.", "Engage toujours ton cœur pour protéger ton bas du dos tout en soutenant la charge au-dessus de ta tête.", "Commence avec un poids léger pour maîtriser la coordination avant de progresser. "]', '["Laisser le kettlebell s''écarter de la ligne de ton épaule.", "Ne pas controler la descente de la fente, ce qui peut nuire à la forme."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "kettlebell", "kettlebell turkish get-up (lunge style) v2"]', true, '2026-04-03 12:24:57.441513+00', '2026-04-03 12:24:57.441513+00', 'Tu commences debout, kettlebell en main, bras tendu au-dessus de ta tête. Les pieds sont à la largeur des épaules. C''est parti pour un mouvement puissant qui va solliciter tes quadriceps !', '["Laisser le kettlebell s''écarter de la ligne de ton épaule.", "Ne pas controler la descente de la fente, ce qui peut nuire à la forme."]', true, '["Hold the kettlebell securely overhead with a straight arm and engaged shoulder", "Keep your core tight and maintain an upright torso throughout the movement", "Step back into a deep lunge, lowering your back knee toward the ground", "Keep the kettlebell directly above your shoulder throughout the entire range of motion", "Push through your front heel to return to the starting standing position", "Complete all reps on one side before switching arms"]', '["Tiens fermement le kettlebell au-dessus de ta tête, bras droit et épaule contractée.", "Garde ton tronc bien gainé et ton torse droit tout au long du mouvement.", "Fais un pas arrière en réalisant une fente profonde, abaisse ton genou arrière vers le sol.", "Le kettlebell doit rester bien au-dessus de ton épaule pendant tout le mouvement.", "Pousse à travers ton talon avant pour revenir à la position de départ.", "Termine toutes les répétitions d''un côté avant de changer de bras."]', '["Maintiens une stabilité constante au-dessus de ta tête, ne laisse jamais le kettlebell dériver en avant ou en arrière.", "Veille à ce que ton genou avant reste aligné avec tes orteils pendant la descente de la fente.", "Concentre-toi sur un mouvement contrôlé plutôt que sur la vitesse pour garder une bonne forme.", "Engage toujours ton cœur pour protéger ton bas du dos tout en soutenant la charge au-dessus de ta tête.", "Commence avec un poids léger pour maîtriser la coordination avant de progresser. "]', '["Maintain constant overhead stability - never let the kettlebell drift forward or backward", "Keep your front knee tracking over your toes during the lunge descent", "Focus on controlled movement rather than speed to maintain proper form", "Engage your core throughout to protect your lower back while supporting the overhead load", "Start with a lighter weight to master the coordination before progressing"]', 'ab569da1-869a-4f74-b7f8-2f0a6e90e547', 'kettlebell-turkish-get-up-lunge-style-v2', NULL, NULL);
INSERT INTO public.exercises VALUES ('89435557-2131-4d90-bd10-fa4a4fd020be', 'Escaladeurs', NULL, 'ممارسات تسلق الجبال', 'Mountain climbers', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/mountain-climbers-8085b2a3.mp4', NULL, NULL, NULL, '/videos/thumbnails/mountain-climbers-8085b2a3.jpg', NULL, '["Garde les hanches vers le bas (évite de cambrer)", "Maintiens ton ventre engagé", "Accélère pour un entraînement cardio plus intense", "Ralentis pour plus de contrôle", "C''est un exercice qui fait travailler tout le corps"]', '["Ne pas engager le core", "Lever les hanches trop haut", "Ne pas respirer correctement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "mountain climbers"]', true, '2026-04-03 12:24:57.823807+00', '2026-04-03 12:24:57.823807+00', 'L''exercice parfait pour renforcer votre sangle abdominale tout en boostant votre endurance ! Prêt à grimper ?', '["Ne pas engager le core", "Lever les hanches trop haut", "Ne pas respirer correctement"]', true, '["Start in push-up position", "Drive one knee toward chest", "Quickly switch legs", "Continue alternating at pace"]', '["Place-toi en position de pompes", "Tire un genou vers ta poitrine", "Change rapidement de jambe", "Alterne à un rythme soutenu"]', '["Garde les hanches vers le bas (évite de cambrer)", "Maintiens ton ventre engagé", "Accélère pour un entraînement cardio plus intense", "Ralentis pour plus de contrôle", "C''est un exercice qui fait travailler tout le corps"]', '["Keep hips down (don''t pike)", "Core stays engaged", "Speed up for more cardio", "Slow down for more control", "Full body exercise"]', '8085b2a3-fc64-478c-b93a-bf86dab46fc0', 'mountain-climbers-8085b2a3', NULL, NULL);
INSERT INTO public.exercises VALUES ('9b86e770-be89-4a59-8089-76fc8af0454a', 'Jumping Jacks Ouverts et Fermés', NULL, NULL, 'Open and close jumping jacks', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/open-and-close-jumping-jacks.mp4', NULL, NULL, NULL, '/videos/thumbnails/open-and-close-jumping-jacks.jpg', NULL, '["Atterris doucement sur la plante des pieds pour réduire l''impact sur les articulations et prévenir les blessures.", "Garde les abdominaux engagés pendant toute la durée de l''exercice pour maintenir une bonne posture et de la stabilité.", "Adopte un rythme contrôlé plutôt que de te précipiter pour garantir une bonne forme à chaque mouvement.", "Si tu ressens une gêne au niveau des genoux ou des chevilles, fais des pas latéraux au lieu de sauter.", "Garde les genoux légèrement fléchis lors de l''atterrissage pour qu''ils agissent comme des amortisseurs naturels."]', '["Ne pas plier les genoux à l''atterrissage, ce qui peut causer des blessures.", "Oublier de maintenir une posture droite, ce qui peut affecter l''équilibre et l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "open and close jumping jacks"]', true, '2026-04-03 12:24:58.211282+00', '2026-04-03 12:24:58.211282+00', 'Position de départ : Tiens-toi droit, les pieds joints et les bras le long du corps. Exécution : Saute en écartant les jambes à la largeur des épaules et en levant les bras au-dessus de ta tête, puis saute à nouveau pour revenir à la position de départ.', '["Ne pas plier les genoux à l''atterrissage, ce qui peut causer des blessures.", "Oublier de maintenir une posture droite, ce qui peut affecter l''équilibre et l''efficacité de l''exercice."]', true, '["Stand tall with feet together, arms relaxed at your sides, and engage your core", "Jump up while spreading your feet apart to shoulder-width distance and simultaneously raise both arms overhead", "Land softly on the balls of your feet with knees slightly bent to absorb impact", "Immediately jump again while bringing your feet back together and lowering your arms to your sides", "Maintain a steady rhythm and controlled breathing throughout the movement", "Continue for the desired number of repetitions or time duration"]', '["Tiens-toi bien droit avec les pieds joints, les bras relâchés sur les côtés et engage ton ventre.", "Saute en écartant les pieds à la largeur des épaules tout en levant les bras au-dessus de ta tête.", "Atterrit doucement sur la plante de tes pieds, les genoux légèrement fléchis pour absorber l''impact.", "Saute de nouveau en rassemblant les pieds et en abaissant les bras.", "Maintiens un rythme constant et respire de manière contrôlée durant l''exercice.", "Poursuis l''exercice pour le nombre de répétitions souhaité ou la durée fixée."]', '["Atterris doucement sur la plante des pieds pour réduire l''impact sur les articulations et prévenir les blessures.", "Garde les abdominaux engagés pendant toute la durée de l''exercice pour maintenir une bonne posture et de la stabilité.", "Adopte un rythme contrôlé plutôt que de te précipiter pour garantir une bonne forme à chaque mouvement.", "Si tu ressens une gêne au niveau des genoux ou des chevilles, fais des pas latéraux au lieu de sauter.", "Garde les genoux légèrement fléchis lors de l''atterrissage pour qu''ils agissent comme des amortisseurs naturels."]', '["Land softly on the balls of your feet to reduce joint impact and prevent injury", "Keep your core engaged throughout the exercise to maintain proper posture and stability", "Maintain a controlled pace rather than rushing through the movements to ensure proper form", "If you experience knee or ankle discomfort, step side to side instead of jumping", "Keep your knees slightly bent during landing to act as natural shock absorbers"]', '4001ef61-57a1-4f18-8c0b-8167e15c6832', 'open-and-close-jumping-jacks', NULL, NULL);
INSERT INTO public.exercises VALUES ('0c0c2d73-83f3-43be-a58d-f247cb62ca2b', 'Planche', NULL, 'Plank', 'Plank pose', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/plank-pose.mp4', NULL, NULL, NULL, '/videos/thumbnails/plank-pose.jpg', NULL, '["Ne laisse pas tes hanches s''affaisser ou remonter trop haut.", "Presse fermement avec tes mains et écarte bien tes doigts.", "Garde le cou neutre, regarde le sol."]', '["Laissez les hanches s''affaisser, ce qui peut causer des douleurs au dos.", "Ne pas engager les muscles du tronc, ce qui réduit l''efficacité de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "plank pose"]', true, '2026-04-03 12:24:58.330531+00', '2026-04-03 12:24:58.330531+00', 'Renforce ton cœur et améliore ta posture avec la planche. Cet exercice est essentiel pour développer la force de ton tronc.', '["Laissez les hanches s''affaisser, ce qui peut causer des douleurs au dos.", "Ne pas engager les muscles du tronc, ce qui réduit l''efficacité de l''exercice."]', true, '["Start on all fours, then step your feet back to straighten your legs.", "Align your body in a straight line from head to heels.", "Stack your shoulders directly over your wrists.", "Hold, engaging your core and legs."]', '["Place-toi à quatre pattes, puis recule tes pieds pour aligner tes jambes.", "Assure-toi que ton corps forme une ligne droite, de la tête aux talons.", "Positionne tes épaules directement au-dessus de tes poignets.", "Reste dans cette position en engageant tes abdominaux et tes jambes."]', '["Ne laisse pas tes hanches s''affaisser ou remonter trop haut.", "Presse fermement avec tes mains et écarte bien tes doigts.", "Garde le cou neutre, regarde le sol."]', '["Do not let your hips sag or pike up.", "Press firmly through your hands and spread your fingers.", "Keep your neck neutral, gazing at the floor."]', '1eab35ce-2d24-4908-8d60-082cf1f7ab74', 'plank-pose', NULL, NULL);
INSERT INTO public.exercises VALUES ('86d7e186-0185-4107-9490-bec5fb3e417f', 'Étirement du bras supérieur gauche', NULL, 'Stretch dyal l''yed lfo9iya chmal', 'Posterior upper arm (left)', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/posterior-upper-arm-left.mp4', NULL, NULL, NULL, '/videos/thumbnails/posterior-upper-arm-left.jpg', NULL, '["Applique une pression douce et continue, évite de rebondir ou de forcer l''étirement", "Engage ton corps et évite de cambrer excessivement le dos", "Arrête immédiatement si tu ressens une douleur dans ton épaule ou ton coude", "Concentre-toi sur l''étirement à l''arrière de ton bras supérieur, pas dans les articulations", "Garde une bonne posture tout au long du mouvement, poitrine en avant et épaules carrées"]', '["Tirer trop fort sur le coude", "Ne pas maintenir une bonne posture pendant l''étirement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "posterior upper arm (left)"]', true, '2026-04-03 12:24:58.409814+00', '2026-04-03 12:24:58.409814+00', 'Mets-toi debout, les pieds écartés à la largeur des hanches. Lève ton bras gauche au-dessus de ta tête, puis plie le coude pour ramener ta main derrière ta tête vers le haut du dos. Ensuite, utilise ta main droite pour tirer doucement le coude gauche vers la droite tout en appuyant ta main gauche le long de ton dos pour étirer les muscles du bras supérieur arrière.', '["Tirer trop fort sur le coude", "Ne pas maintenir une bonne posture pendant l''étirement"]', true, '["Stand tall with feet hip-width apart and shoulders relaxed", "Raise your left arm straight overhead, then bend the elbow to drop your left hand behind your head", "Place your right hand on your left elbow and gently pull it across toward the right side of your head", "Keep your left hand reaching down your back as far as comfortable", "Hold the stretch for 20-30 seconds while breathing normally", "Repeat on the right side for balanced flexibility"]', '["Reste bien droit, pieds écartés à la largeur des hanches et épaules relâchées", "Lève ton bras gauche bien droit au-dessus de ta tête puis plie le coude pour ramener ta main derrière la tête", "Place ta main droite sur ton coude gauche et tire-le doucement vers la droite", "Continue d’étendre ta main gauche le long de ton dos au maximum de ton confort", "Maintiens l''étirement pendant 20-30 secondes en respirant normalement", "Répète de l''autre côté pour une flexibilité équilibrée"]', '["Applique une pression douce et continue, évite de rebondir ou de forcer l''étirement", "Engage ton corps et évite de cambrer excessivement le dos", "Arrête immédiatement si tu ressens une douleur dans ton épaule ou ton coude", "Concentre-toi sur l''étirement à l''arrière de ton bras supérieur, pas dans les articulations", "Garde une bonne posture tout au long du mouvement, poitrine en avant et épaules carrées"]', '["Apply gentle, steady pressure rather than bouncing or forcing the stretch", "Keep your core engaged and avoid arching your back excessively", "Stop immediately if you feel pain in your shoulder or elbow joint", "Focus on feeling the stretch along the back of your upper arm, not in the joints", "Maintain proper posture throughout the movement with chest up and shoulders square"]', 'f8d7664f-01f0-4a79-abd8-85bbe9f067ac', 'posterior-upper-arm-left', NULL, NULL);
INSERT INTO public.exercises VALUES ('dcacc970-dac2-404b-bde7-a0f1ace0aaf2', 'Pseudo pompes', NULL, 'لي بوش بومبس', 'Pseudo push ups', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/pseudo-push-ups.mp4', NULL, NULL, NULL, '/videos/thumbnails/pseudo-push-ups.jpg', NULL, '["La position des mains est cruciale - placer les mains plus bas et plus larges change l''accent musculaire et la difficulté", "Garde les coudes près de ton corps au lieu de les écarter", "Maintiens une bonne position de planche tout au long de l''exercice pour protéger ton bas du dos", "Cette variante sollicite davantage les triceps et demande plus de force que les pompes standards", "Arrête l''exercice si tu ne peux pas maintenir la bonne forme"]', '["Ne pas garder le corps en ligne droite", "Écarter trop les coudes au lieu de les garder près du corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "pseudo push ups"]', true, '2026-04-03 12:24:58.463453+00', '2026-04-03 12:24:58.463453+00', 'Position de départ : mets-toi en position de pompe, les mains placées plus larges que les épaules et plus bas sur le torse, près des côtes. Exécution : fais descendre ton corps en pliant les coudes, tout en les gardant près de ton corps, puis pousse pour revenir à la position de départ.', '["Ne pas garder le corps en ligne droite", "Écarter trop les coudes au lieu de les garder près du corps"]', true, '["Position hands wider than shoulders and lower on the torso near the ribcage area", "Keep your body in a straight line from head to heels throughout the movement", "Lower your chest toward the ground by bending your elbows, keeping them close to your sides", "Press through your palms to return to the starting position", "Maintain core engagement to prevent sagging hips", "Control the descent and ascent with steady, deliberate movement"]', '["Place tes mains plus larges que tes épaules et plus bas sur le torse, près des côtes", "Garde le corps en ligne droite, de la tête aux talons pendant tout le mouvement", "Abaisse ta poitrine vers le sol en pliant les coudes, en les gardant près de ton corps", "Pousse avec tes paumes pour revenir à la position de départ", "Engage bien ta ceinture abdominale pour éviter que tes hanches ne s''affaissent", "Contrôle la descente et la montée avec des mouvements réguliers et réfléchis"]', '["La position des mains est cruciale - placer les mains plus bas et plus larges change l''accent musculaire et la difficulté", "Garde les coudes près de ton corps au lieu de les écarter", "Maintiens une bonne position de planche tout au long de l''exercice pour protéger ton bas du dos", "Cette variante sollicite davantage les triceps et demande plus de force que les pompes standards", "Arrête l''exercice si tu ne peux pas maintenir la bonne forme"]', '["Hand placement is crucial - positioning hands lower and wider changes the muscle emphasis and difficulty", "Keep elbows tucked close to your body rather than flaring them out wide", "Maintain proper plank position throughout to protect your lower back", "This variation places more emphasis on the triceps and requires greater strength than standard push-ups", "Stop the movement if you cannot maintain proper form"]', 'bf3b7d97-363c-45d7-91a3-43491c5a6f2a', 'pseudo-push-ups', NULL, NULL);
INSERT INTO public.exercises VALUES ('a5b9c245-9a89-4768-ad9b-4b269efa9450', 'Pompes avec touches de pieds', NULL, 'تمارين الضغط مع لمس الأصابع', 'Push ups to toe touches', 'Chest', '[]', 'Chest', 'Intermediate', 16, '/videos/chest/push-ups-to-toe-touches.mp4', NULL, NULL, NULL, '/videos/thumbnails/push-ups-to-toe-touches.jpg', NULL, '["Reste gainé pendant tout le mouvement pour protéger ton dos", "Contrôle chaque mouvement, ne te précipite pas dans les transitions", "Si tu ne peux pas toucher tes orteils, vas-y à ton rythme et progresse sur ta souplesse", "Assure-toi d''avoir une bonne technique de pompe avant d''ajouter la touche de pied", "Respire de façon fluide pendant l''exercice, expire lors de la phase de pompe"]', '["Ne pas maintenir une bonne position de dos", "Se précipiter dans les mouvements au lieu de les contrôler"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "bodyweight", "push ups to toe touches"]', true, '2026-04-03 12:24:58.514112+00', '2026-04-03 12:24:58.514112+00', 'Mets-toi en position de planche, mains légèrement plus larges que les épaules. Tu es prêt à relever le défi? Effectue une pompe, puis en haut du mouvement, soulève les hanches et touche le pied opposé. C''est parti!', '["Ne pas maintenir une bonne position de dos", "Se précipiter dans les mouvements au lieu de les contrôler"]', true, '["Start in a plank position with hands firmly planted on the ground and core engaged", "Lower your body by bending your elbows until your chest nearly touches the floor", "Push back up to the starting plank position with control", "Shift your weight back and lift your hips up into a pike position", "Reach your right hand toward your left toe while keeping legs as straight as possible", "Return to plank position and repeat the sequence, alternating which hand reaches for the opposite toe"]', '["Commence en position de planche avec les mains bien ancrées au sol et les abdos serrés", "Abaisse ton corps en fléchissant les coudes jusqu''à ce que ta poitrine frôle le sol", "Remonte avec contrôle vers la position de planche", "Penche ton poids en arrière et lève les hanches en position pike", "Touche ton pied gauche avec la main droite en gardant les jambes aussi droites que possible", "Reviens en position de planche et répète en alternant les côtés"]', '["Reste gainé pendant tout le mouvement pour protéger ton dos", "Contrôle chaque mouvement, ne te précipite pas dans les transitions", "Si tu ne peux pas toucher tes orteils, vas-y à ton rythme et progresse sur ta souplesse", "Assure-toi d''avoir une bonne technique de pompe avant d''ajouter la touche de pied", "Respire de façon fluide pendant l''exercice, expire lors de la phase de pompe"]', '["Maintain a tight core throughout the entire movement to protect your lower back", "Keep your movements controlled and avoid rushing through the transitions", "If you cannot reach your toes, reach as far as comfortable and gradually improve flexibility", "Ensure proper push-up form before adding the toe touch component", "Breathe steadily throughout the exercise, exhaling during the push-up phase"]', '284b839e-ec4c-4551-ba9d-afbf32b60330', 'push-ups-to-toe-touches', NULL, NULL);
INSERT INTO public.exercises VALUES ('31aa8686-2f64-4229-829d-2015c8a20c5c', 'Essuie-glaces allongés', NULL, 'ممسحات مقلوبة', 'Reclined windshield wipers', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/reclined-windshield-wipers.mp4', NULL, NULL, NULL, '/videos/thumbnails/reclined-windshield-wipers.jpg', NULL, '["Gardez les deux épaules bien plaquées au sol.", "Mouvement doux, ne forcez pas les genoux vers le bas.", "C''est une torsion douce de la colonne vertébrale et un relâchement des hanches."]', '["Soulever les épaules du sol.", "Forcer les mouvements trop rapidement."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "reclined windshield wipers"]', true, '2026-04-03 12:24:58.569414+00', '2026-04-03 12:24:58.569414+00', 'Musclez votre sangle abdominale tout en améliorant votre flexibilité avec cet exercice de torsion douce.', '["Soulever les épaules du sol.", "Forcer les mouvements trop rapidement."]', true, '["Lie on your back with knees bent and feet flat, wider than hip-width.", "Extend your arms out to the sides.", "Let both knees drop to one side, then the other.", "Move slowly with your breath."]', '["Allongez-vous sur le dos, genoux fléchis et pieds à plat, écartés au-delà de la largeur des hanches.", "Étendez vos bras sur les côtés.", "Laissez tomber les genoux d''un côté, puis de l''autre.", "Bougez lentement en synchronisant avec votre respiration."]', '["Gardez les deux épaules bien plaquées au sol.", "Mouvement doux, ne forcez pas les genoux vers le bas.", "C''est une torsion douce de la colonne vertébrale et un relâchement des hanches."]', '["Keep both shoulders on the floor.", "Move gently and do not force the knees down.", "This is a gentle spinal twist and hip release."]', '1f636f46-0bc3-417d-a3ac-93108ecc26ec', 'reclined-windshield-wipers', NULL, NULL);
INSERT INTO public.exercises VALUES ('4261589d-d73d-43bd-b839-8ec610647e88', 'Posture du triangle révolté (droite)', NULL, 'وضعية مثلث مقلوب (اليمين)', 'Revolved triangle pose (right)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/revolved-triangle-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/revolved-triangle-pose-right.jpg', NULL, '["Garde les jambes bien droites.", "Assure-toi d''aligner tes hanches avant de te tourner.", "Utilise un bloc si tu n''atteins pas le sol."]', '["Ne pas avoir les hanches alignées.", "Courber les jambes.", "Ne pas garder la tête alignée avec le corps."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "revolved triangle pose (right)"]', true, '2026-04-03 12:24:58.634462+00', '2026-04-03 12:24:58.634462+00', 'Renforce ton tronc tout en améliorant ta flexibilité et ton équilibre. C''est le moment de te surpasser !', '["Ne pas avoir les hanches alignées.", "Courber les jambes.", "Ne pas garder la tête alignée avec le corps."]', true, '["From a standing split stance, square your hips to the front.", "Hinge forward and place the opposite hand on the floor or a block beside your front foot.", "Twist your torso open and extend the top arm toward the ceiling.", "Gaze up at your top hand."]', '["Adopte une position de fente avec une jambe en avant.", "Aligne tes hanches vers l''avant.", "Penche-toi en avant et pose la main opposée au sol ou sur un bloc à côté de ton pied avant.", "Effectue une rotation de ton buste vers le haut, en étendant ton bras supérieur vers le ciel.", "Regarde ta main du haut."]', '["Garde les jambes bien droites.", "Assure-toi d''aligner tes hanches avant de te tourner.", "Utilise un bloc si tu n''atteins pas le sol."]', '["Keep both legs straight.", "Square your hips before twisting.", "Use a block if you cannot reach the floor."]', '6347356d-6248-444f-92b2-47de72d5f96e', 'revolved-triangle-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('31214820-ca43-4cc1-a24f-7deeaf7bb6ef', 'Soulevé de terre roumain', NULL, NULL, 'Romanian Deadlift', 'Hamstrings', '[]', 'Hamstrings', 'Beginner', 1, '/videos/hamstrings/romanian-deadlift.mp4', NULL, NULL, NULL, '/videos/thumbnails/romanian-deadlift.jpg', NULL, '["Garde la barre proche de ton corps durant tout le mouvement", "Concentre-toi sur le mouvement de basculement des hanches plutôt que sur le fléchissement des genoux pour bien cibler les ischio-jambiers", "Maintiens une colonne vertébrale neutre et évite d''arrondir ton dos pendant la descente", "Contrôle le poids aussi bien à la descente qu''à la remontée", "Arrête la descente lorsque tu ressens un bon étirement dans tes ischio-jambiers, généralement au niveau des mi-mollets"]', '["Arrondir le dos durant la descente", "Fléchir les genoux trop tôt au lieu de pivoter au niveau des hanches"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["hamstrings", "barbell", "romanian deadlift"]', true, '2026-04-03 12:24:58.646261+00', '2026-04-03 12:24:58.646261+00', 'Position de départ : tiens-toi droit, barre à la main, pieds écartés à la largeur des hanches. Exécution : fais basculer tes hanches en arrière en gardant le dos droit, abaisse la barre en la gardant proche du corps, puis redresse-toi en poussant tes hanches vers l’avant.', '["Arrondir le dos durant la descente", "Fléchir les genoux trop tôt au lieu de pivoter au niveau des hanches"]', true, '["Stand with feet hip-width apart and grip the barbell with both hands using an overhand grip", "Keep your shoulders back and chest up while maintaining a neutral spine throughout the movement", "Initiate the movement by pushing your hips back and hinging at the hips, not the knees", "Lower the barbell by keeping it close to your body while maintaining straight arms", "Feel the stretch in your hamstrings as you lower the weight with control", "Drive your hips forward to return to the starting position, squeezing your glutes at the top"]', '["Tiens-toi avec les pieds écartés à la largeur des hanches et saisis la barre avec les deux mains en prise pronation", "Garde les épaules en arrière et la poitrine bien haute tout en maintenant une colonne vertébrale neutre pendant toute l''exécution", "Débute le mouvement en poussant tes hanches en arrière et en fléchissant uniquement les hanches, pas les genoux", "Abaisse la barre tout en la gardant proche de ton corps et les bras tendus", "Ressens l''étirement dans tes ischio-jambiers en contrôlant la descente du poids", "Pousse tes hanches en avant pour revenir à la position de départ, en contractant les fessiers en haut du mouvement"]', '["Garde la barre proche de ton corps durant tout le mouvement", "Concentre-toi sur le mouvement de basculement des hanches plutôt que sur le fléchissement des genoux pour bien cibler les ischio-jambiers", "Maintiens une colonne vertébrale neutre et évite d''arrondir ton dos pendant la descente", "Contrôle le poids aussi bien à la descente qu''à la remontée", "Arrête la descente lorsque tu ressens un bon étirement dans tes ischio-jambiers, généralement au niveau des mi-mollets"]', '["Keep the barbell close to your body throughout the entire range of motion", "Focus on hip hinge movement rather than knee bending to properly target the hamstrings", "Maintain a neutral spine and avoid rounding your back during the descent", "Control the weight on both the lowering and lifting phases of the movement", "Stop the descent when you feel a good stretch in your hamstrings, typically around mid-shin level"]', '9fb9d7f3-6833-4f8d-97ce-f487f8fd5eca', 'romanian-deadlift', NULL, NULL);
INSERT INTO public.exercises VALUES ('e97a3df8-495b-4d3d-886a-99db1b28bed8', 'Maintien de la Scapula', NULL, 'تحمل الكتف', 'Scapula hold', 'Back', '[]', 'Back', 'Intermediate', 16, '/videos/back/scapula-hold.mp4', NULL, NULL, NULL, '/videos/thumbnails/scapula-hold.jpg', NULL, '["Conservez une tension constante dans vos omoplates en les tirant vers le bas et loin de vos oreilles", "Ne retenez pas votre respiration - respirez de manière constante pendant tout le maintien", "Arrêtez-vous immédiatement si votre posture se dégrade ou si vous ressentez une douleur articulaire", "Votre corps doit former une ligne droite sans affaissement dans le bas du dos ou les hanches", "Commencez par de courtes durées de maintien et augmentez progressivement au fur et à mesure que votre force s''améliore"]', '["Hanches qui s''affaissent ou se surélèvent", "Cou en tension à cause d''une mauvaise position de tête"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "scapula hold"]', true, '2026-04-03 12:24:58.731808+00', '2026-04-03 12:24:58.731808+00', 'Position de départ : Mettez-vous en position de planche avec les mains à la largeur des épaules, les bras tendus et le corps en ligne droite de la tête aux talons. Exécution : Maintenez cette position en vous concentrant sur l''engagement des scapulas et la stabilité de votre core tout au long de l''exercice.', '["Hanches qui s''affaissent ou se surélèvent", "Cou en tension à cause d''une mauvaise position de tête"]', true, '["Position hands directly under shoulders with fingers spread wide for optimal support", "Engage your core muscles and maintain a straight line from your head through your heels", "Keep your shoulder blades pulled down and back, avoiding any sagging or elevation", "Breathe steadily while holding the position for the prescribed duration", "Focus on keeping your neck in a neutral position by looking down at the mat", "Maintain the hold without allowing your hips to drop or pike upward"]', '["Positionnez vos mains directement sous vos épaules avec les doigts écartés pour un soutien optimal", "Contractez vos muscles abdominaux et gardez une ligne droite de la tête aux talons", "Ramenez vos omoplates vers le bas et vers l''arrière, évitez tout affaissement ou élévation", "Respirez de manière régulière tout en maintenant la position pendant la durée prescrite", "Gardez votre cou dans une position neutre en regardant vers le bas", "Maintenez votre corps sans laisser vos hanches tomber ou se surélever"]', '["Conservez une tension constante dans vos omoplates en les tirant vers le bas et loin de vos oreilles", "Ne retenez pas votre respiration - respirez de manière constante pendant tout le maintien", "Arrêtez-vous immédiatement si votre posture se dégrade ou si vous ressentez une douleur articulaire", "Votre corps doit former une ligne droite sans affaissement dans le bas du dos ou les hanches", "Commencez par de courtes durées de maintien et augmentez progressivement au fur et à mesure que votre force s''améliore"]', '["Keep constant tension in your shoulder blades by pulling them down and away from your ears", "Avoid holding your breath - maintain steady breathing throughout the entire hold", "Stop immediately if you feel your form breaking down or experience any joint pain", "Your body should form one straight line without any sagging in the lower back or hips", "Start with shorter hold times and gradually increase duration as your strength improves"]', '42a043cf-29ba-4e98-a6fe-d9cbc61f7015', 'scapula-hold', NULL, NULL);
INSERT INTO public.exercises VALUES ('81ef7969-dfd8-482d-984a-b6749b7241e0', 'Curl Alterné avec Haltère Assis', NULL, NULL, 'Seated Dumbbell Curl - One Arm - Alternating', 'Biceps', '[]', 'Biceps', 'Intermediate', 2, '/videos/biceps/seated-dumbbell-curl-one-arm-alternating.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-dumbbell-curl-one-arm-alternating.jpg', NULL, '["Garde le bras supérieur et le coude immobiles pour bien cibler le biceps", "Évite l''élan ou de balancer le poids - concentre-toi sur la contraction musculaire contrôlée", "Maintiens une posture correcte avec les épaules en arrière et les abdominaux engagés pour protéger ton dos", "Utilise une amplitude complète en étendant complètement le bras en bas et en atteignant la contraction maximale en haut", "Contrôle la phase descendante en abaissant le poids lentement au lieu de le laisser tomber."]', '["Utiliser l''élan pour soulever les haltères", "Ne pas garder le coude immobile pendant le mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["biceps", "dumbbell", "seated dumbbell curl - one arm - alternating"]', true, '2026-04-03 12:24:58.804514+00', '2026-04-03 12:24:58.804514+00', 'Position de départ : Assieds-toi sur un banc avec un haltère dans chaque main, bras tendus vers le bas. Exécution : Ramène les haltères vers tes épaules en pliant les coudes, puis redescends lentement.', '["Utiliser l''élan pour soulever les haltères", "Ne pas garder le coude immobile pendant le mouvement"]', true, '["Sit with your back straight and core engaged, feet firmly planted on the floor", "Hold dumbbells with a neutral grip, arms fully extended at your sides", "Curl one dumbbell up by contracting the bicep while keeping your upper arm stationary", "Squeeze the bicep at the top of the movement, then slowly lower the weight back to starting position", "Allow the first arm to fully return to starting position before beginning the curl with the opposite arm", "Maintain controlled tempo throughout the entire range of motion"]', '["Assieds-toi avec le dos droit et les abdominaux contractés, pieds bien ancrés au sol", "Tiens les haltères avec une prise neutre, bras complètement étendus sur les côtés", "Ramène un haltère vers le haut en contractant le biceps, en gardant ton bras supérieur immobile", "Serre le biceps en haut du mouvement, puis abaisse lentement le poids jusqu''à la position de départ", "Laisse le premier bras revenir entièrement à la position de départ avant de commencer le curl avec l''autre bras", "Maintiens un tempo contrôlé tout au long de l''exercice."]', '["Garde le bras supérieur et le coude immobiles pour bien cibler le biceps", "Évite l''élan ou de balancer le poids - concentre-toi sur la contraction musculaire contrôlée", "Maintiens une posture correcte avec les épaules en arrière et les abdominaux engagés pour protéger ton dos", "Utilise une amplitude complète en étendant complètement le bras en bas et en atteignant la contraction maximale en haut", "Contrôle la phase descendante en abaissant le poids lentement au lieu de le laisser tomber."]', '["Keep your upper arm and elbow stationary throughout the movement to isolate the bicep", "Avoid using momentum or swinging the weight up - focus on controlled muscle contraction", "Maintain proper posture with shoulders back and core engaged to prevent back strain", "Use a full range of motion by fully extending the arm at the bottom and achieving peak contraction at the top", "Control the negative portion of the lift by lowering the weight slowly rather than letting it drop"]', '29e0d621-73e4-44da-9db7-10302fbe9503', 'seated-dumbbell-curl-one-arm-alternating', NULL, NULL);
INSERT INTO public.exercises VALUES ('9a1dfdd6-d24c-4e9d-9258-bba00bfb5ab1', 'Tirage Haut Assis', NULL, NULL, 'Seated High Row Machine', 'Back', '[]', 'Back', 'Beginner', 8, '/videos/back/seated-high-row-machine.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-high-row-machine.jpg', NULL, '["Garde toujours ta poitrine pressée contre le rembourrage pour maintenir un bon alignement de la colonne", "Concentre-toi sur l''utilisation de tes muscles du dos plutôt que de tes bras en initiant le mouvement avec tes omoplates", "Évite le balancement et les mouvements saccadés - garde un rythme fluide et contrôlé dans les deux directions", "Garde tes épaules basses et en arrière, évite tout mouvement d''épaule pendant le tirage", "Assure-toi que tes coudes avancent droit vers l''arrière sans se déployer sur les côtés"]', '["Ne pas aligner correctement le siège, ce qui peut affecter la posture", "Utiliser trop de force des bras au lieu de solliciter les muscles du dos"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "machine", "seated high row machine"]', true, '2026-04-03 12:24:58.855663+00', '2026-04-03 12:24:58.855663+00', 'Positionne-toi sur la machine à tirage haut, les poignées à hauteur de poitrine. Tire les poignées vers ta poitrine tout en gardant le dos droit, puis ramène-les lentement à la position de départ.', '["Ne pas aligner correctement le siège, ce qui peut affecter la posture", "Utiliser trop de force des bras au lieu de solliciter les muscles du dos"]', true, '["Adjust the seat height so the handles align with your upper chest when seated", "Sit with your chest firmly against the pad and maintain an upright posture throughout the movement", "Grasp the handles with an overhand grip, hands positioned slightly wider than shoulder width", "Pull the handles straight back by driving your elbows behind your body and squeezing your shoulder blades together", "Hold the contraction briefly at the back position, feeling the muscles between your shoulder blades engage", "Slowly return the handles to the starting position with control, maintaining tension throughout the eccentric phase"]', '["Régle la hauteur du siège pour que les poignées soient alignées avec le haut de ta poitrine lorsque tu es assis", "Reste bien plaqué contre le rembourrage et garde une posture droite pendant tout l''exercice", "Saisis les poignées avec une prise en pronation, les mains légèrement plus larges que les épaules", "Tire les poignées vers l''arrière en poussant les coudes derrière ton corps et en serrant les omoplates ensemble", "Maintiens la contraction un court instant à l''arrière, sens les muscles entre tes omoplates se contracter", "Ramène lentement les poignées à la position de départ en contrôlant le mouvement, garde la tension durant toute la phase excentrique"]', '["Garde toujours ta poitrine pressée contre le rembourrage pour maintenir un bon alignement de la colonne", "Concentre-toi sur l''utilisation de tes muscles du dos plutôt que de tes bras en initiant le mouvement avec tes omoplates", "Évite le balancement et les mouvements saccadés - garde un rythme fluide et contrôlé dans les deux directions", "Garde tes épaules basses et en arrière, évite tout mouvement d''épaule pendant le tirage", "Assure-toi que tes coudes avancent droit vers l''arrière sans se déployer sur les côtés"]', '["Keep your chest pressed against the pad throughout the entire movement to maintain proper spinal alignment", "Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades", "Avoid using momentum or jerky movements - maintain a smooth, controlled tempo in both directions", "Keep your shoulders down and back, avoiding any shrugging motion during the pull", "Ensure your elbows travel straight back rather than flaring out to the sides"]', '78c91035-616b-4b6c-a1b7-5572af8bc647', 'seated-high-row-machine', NULL, NULL);
INSERT INTO public.exercises VALUES ('5c9111ab-662e-4e8d-bb53-ef853313ce75', 'Coup de pied flottant au sol', NULL, NULL, 'Seated flutter kicks', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/seated-flutter-kicks.mp4', NULL, NULL, NULL, '/videos/thumbnails/seated-flutter-kicks.jpg', NULL, '["Fais des mouvements petits et contrôlés", "Garde le bas du dos bien plaqué au sol", "Maintiens les jambes bien droites", "N''oublie pas de respirer durant l''exercice", "Cible les abdominaux inférieurs"]', '["Soulever le bas du dos du sol", "Laisser les jambes fléchir", "Ne pas respirer correctement", "Exécuter des mouvements trop rapides", "Ne pas activer les abdominaux"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "seated flutter kicks"]', true, '2026-04-03 12:24:58.838421+00', '2026-04-03 12:24:58.838421+00', 'Un exercice ciblant les abdominaux inférieurs pour renforcer votre sangle abdominale !', '["Soulever le bas du dos du sol", "Laisser les jambes fléchir", "Ne pas respirer correctement", "Exécuter des mouvements trop rapides", "Ne pas activer les abdominaux"]', true, '["Lie on back, hands under hips", "Legs straight, slightly off floor", "Kick legs up and down alternately", "Keep lower back pressed to floor"]', '["Allonge-toi sur le dos, les mains sous les hanches", "Garde les jambes droites, légèrement surélevées du sol", "Alterne les mouvements de jambes en les levant et les abaissant", "Maintiens le bas du dos pressé contre le sol"]', '["Fais des mouvements petits et contrôlés", "Garde le bas du dos bien plaqué au sol", "Maintiens les jambes bien droites", "N''oublie pas de respirer durant l''exercice", "Cible les abdominaux inférieurs"]', '["Small controlled movements", "Lower back stays down", "Keep legs straight", "Breathe throughout", "Targets lower abs"]', 'b7a93a70-b9fc-469f-8397-5a2e8a8877c8', 'seated-flutter-kicks', NULL, NULL);
INSERT INTO public.exercises VALUES ('36e54339-57a1-491d-82ca-735ba203b46f', 'Étirement Latéral', NULL, 'تمارين الإطالة الجانبية', 'Side Bend Stretch (R)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-bend-stretch-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-bend-stretch-r.jpg', NULL, '["Garde un mouvement latéral, évite de pencher le torse en avant ou en arrière pendant l’étirement.", "Respire régulièrement et évite de bloquer ta respiration.", "Sens l’étirement sur tout le côté droit de ton torse, de la hanche à l’aisselle.", "Si tu ressens une douleur aiguë ou de l’inconfort au bas du dos, arrête-toi immédiatement.", "Engage légèrement ta sangle abdominale pour protéger ta colonne vertébrale durant le mouvement."]', '["Avoir tendance à incliner le torse en avant ou en arrière au lieu de rester latéral.", "Ne pas respirer correctement, ce qui peut rendre la posture inconfortable."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side bend stretch (r)"]', true, '2026-04-03 12:24:59.002395+00', '2026-04-03 12:24:59.002395+00', 'Prends une grande inspiration et prépare-toi à te challenger. On va travailler sur l’étirement de ton côté droit pour assouplir ton tronc et renforcer ta sangle abdominale.', '["Avoir tendance à incliner le torse en avant ou en arrière au lieu de rester latéral.", "Ne pas respirer correctement, ce qui peut rendre la posture inconfortable."]', true, '["Stand with feet hip-width apart and maintain a straight spine with shoulders relaxed", "Raise your right arm overhead and place your left hand on your left hip for support", "Slowly lean your entire torso to the left side, reaching your right arm over your head", "Keep your hips facing forward and avoid twisting or rotating your torso", "Hold the stretch for 15-30 seconds while breathing deeply", "Return to the starting position slowly and with control"]', '["Tiens-toi droit, les pieds écartés à la largeur des hanches et le dos bien droit.", "Lève ton bras droit au-dessus de ta tête et place ta main gauche sur ta hanche gauche pour l’équilibre.", "Incline doucement ton torse vers la gauche en tendant ton bras droit au-dessus de ta tête.", "Veille à ce que tes hanches restent orientées vers l’avant, sans torsion de ton buste.", "Maintiens l’étirement pendant 15 à 30 secondes en respirant profondément.", "Reviens à la position de départ lentement et contrôlé."]', '["Garde un mouvement latéral, évite de pencher le torse en avant ou en arrière pendant l’étirement.", "Respire régulièrement et évite de bloquer ta respiration.", "Sens l’étirement sur tout le côté droit de ton torse, de la hanche à l’aisselle.", "Si tu ressens une douleur aiguë ou de l’inconfort au bas du dos, arrête-toi immédiatement.", "Engage légèrement ta sangle abdominale pour protéger ta colonne vertébrale durant le mouvement."]', '["Keep the movement purely lateral - avoid leaning forward or backward during the stretch", "Maintain steady breathing throughout the stretch and avoid holding your breath", "Feel the stretch along the entire right side of your torso from hip to armpit", "Stop immediately if you experience any sharp pain or discomfort in your lower back", "Keep your core gently engaged to protect your spine during the movement"]', '7502b225-3aa7-44a1-901f-f02f2f14d58c', 'side-bend-stretch-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('18aefd0e-b0f8-4e78-bc6a-54eb89a2eebf', 'Saut de patineur', NULL, 'قفزات المتزلج', 'Side jump skaters', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/side-jump-skaters.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-jump-skaters.jpg', NULL, '["Gardez le buste droit et maintenez une bonne posture tout au long du mouvement.", "Atterrissez en douceur avec les genoux fléchis pour protéger vos articulations et garder le contrôle.", "Concentrez-vous sur la distance latérale plutôt que sur la hauteur pour une efficacité maximale.", "Maintenez un rythme régulier et évitez de faire des pauses entre les sauts.", "Commencez par des sauts plus petits et augmentez progressivement l''amplitude des mouvements à mesure que vous renforcez votre coordination."]', '["Sauter trop haut au lieu de se concentrer sur la distance latérale.", "Atterrir sur les talons au lieu des avant-pieds, ce qui peut causer des douleurs aux articulations."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "side jump skaters"]', true, '2026-04-03 12:24:59.041106+00', '2026-04-03 12:24:59.041106+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des hanches, genoux légèrement fléchis, bras le long du corps. Exécution : Sautez latéralement d''un côté en amenant la jambe opposée derrière vous comme en patinage, puis sautez immédiatement de l''autre côté, en alternant de manière fluide et continue.', '["Sauter trop haut au lieu de se concentrer sur la distance latérale.", "Atterrir sur les talons au lieu des avant-pieds, ce qui peut causer des douleurs aux articulations."]', true, '["Stand with feet hip-width apart and engage your core muscles", "Jump laterally to your right side, landing on your right foot while sweeping your left leg behind your right leg", "Swing your arms naturally to help maintain balance and momentum", "Immediately push off your right foot and jump to the left side, landing on your left foot with right leg sweeping behind", "Continue alternating sides in a smooth, controlled rhythm", "Land softly on the balls of your feet with knees bent to absorb impact"]', '["Positionnez-vous debout, pieds écartés à la largeur des hanches et engagez votre sangle abdominale.", "Sautez latéralement vers votre droite, atterrissant sur votre pied droit tout en balançant votre jambe gauche derrière.", "Balancez vos bras naturellement pour aider à l''équilibre et à l''élan.", "Poussez immédiatement sur votre pied droit et sautez vers la gauche, atterrissant sur votre pied gauche avec la jambe droite derrière.", "Continuez à alterner les côtés dans un rythme fluide et contrôlé.", "Atterrissez doucement sur la plante des pieds en gardant les genoux fléchis pour absorber l''impact."]', '["Gardez le buste droit et maintenez une bonne posture tout au long du mouvement.", "Atterrissez en douceur avec les genoux fléchis pour protéger vos articulations et garder le contrôle.", "Concentrez-vous sur la distance latérale plutôt que sur la hauteur pour une efficacité maximale.", "Maintenez un rythme régulier et évitez de faire des pauses entre les sauts.", "Commencez par des sauts plus petits et augmentez progressivement l''amplitude des mouvements à mesure que vous renforcez votre coordination."]', '["Keep your chest up and maintain good posture throughout the movement", "Land softly with bent knees to protect your joints and maintain control", "Focus on lateral distance rather than height for maximum effectiveness", "Maintain a steady rhythm and avoid pausing between jumps", "Start with smaller jumps and gradually increase range of motion as you build strength and coordination"]', 'ed54736f-d36d-46fa-ac16-08a44612eded', 'side-jump-skaters', NULL, NULL);
INSERT INTO public.exercises VALUES ('93762790-b357-4005-8e2c-46996e705019', 'Planche latérale : montée et descente (droite)', NULL, NULL, 'Side plank up and down (right)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-plank-up-and-down-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-plank-up-and-down-right.jpg', NULL, '["Garde ton coude sous ton épaule pour protéger ton articulation", "Assure-toi de rester dans une ligne droite de la tête aux pieds - évite de laisser tes hanches s''affaisser ou se relever", "Contrôle la descente de tes hanches, ne te laisse pas simplement tomber sous l''effet de la gravité", "Engage les muscles de ton tronc tout au long de l''exercice pour maximiser son efficacité et protéger ta colonne vertébrale", "Garde ton cou dans une position neutre en regardant droit devant toi, pas vers le haut ou le bas."]', '["Ne pas garder le coude sous l''épaule, ce qui peut entraîner une douleur à l''épaule", "Laisser les hanches tomber ou se lever trop haut, ce qui nuit à l''alignement du corps"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side plank up and down (right)"]', true, '2026-04-03 12:24:59.098807+00', '2026-04-03 12:24:59.098807+00', 'Position de départ : Allonge-toi sur le côté droit en planche latérale. Ton avant-bras droit est bien ancré au sol, le coude directement sous l''épaule, et ton corps forme une ligne droite de la tête aux pieds. Execution : Abaisse tes hanches vers le sol, puis remonte-les pour revenir à la position de planche initiale. Répète ce mouvement de montée et descente.', '["Ne pas garder le coude sous l''épaule, ce qui peut entraîner une douleur à l''épaule", "Laisser les hanches tomber ou se lever trop haut, ce qui nuit à l''alignement du corps"]', true, '["Lie on your right side with your right forearm planted firmly on the ground and elbow positioned directly under your shoulder", "Stack your feet on top of each other and engage your core to lift your hips into a straight side plank position", "Slowly lower your hips down toward the ground while maintaining control and keeping your forearm planted", "Drive your hips back up to the starting side plank position by engaging your obliques and core muscles", "Keep your body in a straight line throughout the entire movement without allowing your hips to rotate forward or backward", "Repeat the up and down movement for the desired number of repetitions before switching to the left side"]', '["Allonge-toi sur le côté droit, le forearm droit fermement au sol, coude sous l''épaule", "Empile tes pieds l''un sur l''autre et engage ton tronc pour soulever tes hanches en position de planche latérale", "Abaisse lentement tes hanches vers le sol en gardant le contrôle, l’avant-bras toujours au sol", "Remonte tes hanches à la position de départ en engageant tes obliques et les muscles du tronc", "Maintiens ton corps en ligne droite tout au long de l''exercice, sans laisser tes hanches pivoter", "Répète le mouvement de montée et descente pour le nombre de répétitions souhaitées avant de passer au côté gauche."]', '["Garde ton coude sous ton épaule pour protéger ton articulation", "Assure-toi de rester dans une ligne droite de la tête aux pieds - évite de laisser tes hanches s''affaisser ou se relever", "Contrôle la descente de tes hanches, ne te laisse pas simplement tomber sous l''effet de la gravité", "Engage les muscles de ton tronc tout au long de l''exercice pour maximiser son efficacité et protéger ta colonne vertébrale", "Garde ton cou dans une position neutre en regardant droit devant toi, pas vers le haut ou le bas."]', '["Keep your elbow directly under your shoulder throughout the movement to protect your shoulder joint", "Maintain a straight line from your head to your feet - avoid letting your hips sag or pike up", "Control the descent when lowering your hips rather than just dropping down with gravity", "Engage your core muscles throughout the entire exercise to maximize effectiveness and protect your spine", "Keep your neck in a neutral position by looking straight ahead rather than up or down"]', 'c0c8d00e-5640-462e-8cc3-422a14deb2fc', 'side-plank-up-and-down-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('fdaa3cac-9f49-4484-a7a1-2d24d2239526', 'Soulevé de terre à la Smith Machine', NULL, 'Deadlift Smith Machine', 'Smith Machine Deadlift', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 8, '/videos/bodyweight/smith-machine-deadlift.mp4', NULL, NULL, NULL, '/videos/thumbnails/smith-machine-deadlift.jpg', NULL, '["Garde le dos droit et la poitrine en avant tout au long du mouvement pour protéger ta colonne vertébrale", "La barre doit se déplacer en ligne verticale droite près de ton corps, sans aller en avant ou en arrière", "Concentre-toi sur le fait de pousser avec tes talons et d''engager tes fessiers en haut du mouvement", "Utilise les butées de sécurité de la Smith machine pour éviter que la barre aille trop bas si tu perds le contrôle", "Commence avec des poids légers pour maîtriser le mouvement d''inclinaison des hanches avant de passer à des charges plus lourdes."]', '["Ne pas garder le dos droit peut engendrer des blessures à la colonne vertébrale", "Tirer la barre trop loin du corps peut entraîner une perte d''équilibre et une technique incorrecte"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "machine", "smith machine deadlift"]', true, '2026-04-03 12:24:59.293401+00', '2026-04-03 12:24:59.293401+00', 'Position de départ : Place-toi dans la Smith machine, les pieds écartés à la largeur des épaules et la barre reposant sur tes cuisses supérieures. Exécution : Incline-toi au niveau des hanches et abaisse la barre vers le sol en gardant le dos droit et les genoux légèrement fléchis, puis remonte lentement à la position de départ.', '["Ne pas garder le dos droit peut engendrer des blessures à la colonne vertébrale", "Tirer la barre trop loin du corps peut entraîner une perte d''équilibre et une technique incorrecte"]', true, '["Set the bar at approximately mid-shin height and add appropriate weight plates", "Position yourself with feet hip-width apart directly under the bar, ensuring it''s over your mid-foot", "Bend at the hips first, then bend your knees to lower down and grip the bar with an overhand grip, hands shoulder-width apart", "Engage your core, keep your chest up and shoulders back, then drive through your heels to lift the bar", "Stand up straight by extending your hips and knees simultaneously, keeping the bar close to your body", "Lower the weight back down by reversing the movement, hinging at the hips first"]', '["Régle la barre à hauteur d''environ mi-tibia et ajoute des poids appropriés", "Positionne-toi avec les pieds écartés à la largeur des hanches directement sous la barre, assurant qu''elle soit au-dessus de ton pied moyen", "Incline-toi d''abord au niveau des hanches, puis plie les genoux pour descendre et saisir la barre avec une prise en pronation, les mains écartées à la largeur des épaules", "Active ton tronc, garde la poitrine haute et les épaules en arrière, puis pousse avec tes talons pour soulever la barre", "Redresse-toi en étendant simultanément les hanches et les genoux, en gardant la barre près de ton corps", "Redescends le poids en inversant le mouvement, en t''inclinant d''abord au niveau des hanches."]', '["Garde le dos droit et la poitrine en avant tout au long du mouvement pour protéger ta colonne vertébrale", "La barre doit se déplacer en ligne verticale droite près de ton corps, sans aller en avant ou en arrière", "Concentre-toi sur le fait de pousser avec tes talons et d''engager tes fessiers en haut du mouvement", "Utilise les butées de sécurité de la Smith machine pour éviter que la barre aille trop bas si tu perds le contrôle", "Commence avec des poids légers pour maîtriser le mouvement d''inclinaison des hanches avant de passer à des charges plus lourdes."]', '["Keep your back straight and chest up throughout the entire movement to protect your spine", "The bar should travel in a straight vertical line close to your body, not forward or backward", "Focus on driving through your heels and engaging your glutes at the top of the movement", "Use the Smith machine''s safety stops to prevent the bar from going too low if you lose control", "Start with lighter weight to master the hip hinge movement pattern before progressing to heavier loads"]', 'c72f4458-a48b-4d9c-bc4f-ddc01f3a8eaf', 'smith-machine-deadlift', NULL, NULL);
INSERT INTO public.exercises VALUES ('d0d2b460-a799-4a1e-bc0e-e8277fba7871', 'Fente avant (jambe droite)', NULL, NULL, 'Split squat (R)', 'Quadriceps', '[]', 'Quadriceps', 'Intermediate', 2, '/videos/quadriceps/split-squat-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/split-squat-r.jpg', NULL, '["Assure-toi que ton genou avant reste aligné avec ta cheville, évite qu''il ne s''affaisse vers l''intérieur.", "Garde le buste droit, ne penche pas trop en avant.", "Concentre ton poids sur ta jambe avant, la jambe arrière sert principalement à l''équilibre.", "Contrôle la descente, évite de rebondir au bas du mouvement.", "Engage ton tronc pour maintenir la stabilité durant tout l''exercice."]', '["Laisser le genou avant dépasser la cheville.", "Pencher le torse trop en avant pendant l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "dumbbell", "split squat (r)"]', true, '2026-04-03 12:24:59.427841+00', '2026-04-03 12:24:59.427841+00', 'Position de départ : Place ton pied droit devant et ton pied gauche en arrière, jambes écartées à la largeur des hanches. Exécution : Abaisse ton corps en fléchissant les deux genoux jusqu''à ce que ta cuisse avant soit parallèle au sol, puis pousse avec ton talon avant pour revenir à la position de départ.', '["Laisser le genou avant dépasser la cheville.", "Pencher le torse trop en avant pendant l''exercice."]', true, '["Position your right foot forward and left foot back with feet hip-width apart, keeping most of your weight on your front leg", "Keep your torso upright and core engaged throughout the movement", "Lower your body by bending both knees, dropping your back knee toward the ground while keeping your front knee aligned over your ankle", "Descend until your front thigh is parallel to the floor or as low as comfortable", "Push through your front heel to return to the starting position", "Complete all repetitions on the right leg before switching to the left leg"]', '["Positionne ton pied droit en avant et le gauche en arrière, jambes à la largeur des hanches, en gardant le poids sur ta jambe avant.", "Maintiens le torse droit et engage ton tronc tout au long de l''exercice.", "Abaisse ton corps en pliant les deux genoux, descends ton genou arrière vers le sol tout en gardant ton genou avant au-dessus de ta cheville.", "Descends jusqu''à ce que ta cuisse avant soit parallèle au sol ou aussi bas que cela te convient.", "Pousse avec ton talon avant pour revenir à la position de départ.", "Complète toutes les répétitions sur la jambe droite avant de passer à la gauche."]', '["Assure-toi que ton genou avant reste aligné avec ta cheville, évite qu''il ne s''affaisse vers l''intérieur.", "Garde le buste droit, ne penche pas trop en avant.", "Concentre ton poids sur ta jambe avant, la jambe arrière sert principalement à l''équilibre.", "Contrôle la descente, évite de rebondir au bas du mouvement.", "Engage ton tronc pour maintenir la stabilité durant tout l''exercice."]', '["Keep your front knee aligned over your ankle and avoid letting it cave inward", "Maintain an upright torso position and avoid leaning too far forward", "Focus your weight on your front leg while using your back leg primarily for balance", "Control the descent and avoid bouncing at the bottom of the movement", "Keep your core engaged to maintain stability throughout the exercise"]', '2811e435-2e2e-4b25-8fbb-57873e05d90d', 'split-squat-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('6aa17d43-5567-426d-ae5a-c24a52686a9c', 'Fly debout avec câble', NULL, 'فلاي واقف بالكابل', 'Standing Cable Fly', 'Chest', '[]', 'Chest', 'Beginner', 4, '/videos/chest/standing-cable-fly.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-cable-fly.jpg', NULL, '["Pense à légèrement pencher le torse en avant et à contracter ton ventre pour protéger ton dos", "Concentre-toi sur le serrage des muscles de la poitrine plutôt que d''utiliser la force des bras", "Contrôle le mouvement de descente pour maximiser l''engagement musculaire", "Garde les épaules basses et en arrière pour éviter de te blesser aux épaules", "Commence avec un poids léger pour bien maîtriser le mouvement avant de progresser"]', '["Lâcher les poignées trop rapidement lors du retour", "Utiliser trop de poids et perdre le contrôle du mouvement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["chest", "cable", "standing cable fly"]', true, '2026-04-03 12:24:59.506206+00', '2026-04-03 12:24:59.506206+00', 'Position de départ : Tiens-toi face à la machine à câbles, poulie à hauteur de poitrine. Exécution : Prends les poignées et ouvre les bras sur les côtés en gardant une légère flexion des coudes.', '["Lâcher les poignées trop rapidement lors du retour", "Utiliser trop de poids et perdre le contrôle du mouvement"]', true, '["Set cable pulleys to shoulder height and select appropriate weight", "Stand centered between cables with one foot slightly forward for stability", "Grasp handles with palms facing forward and step forward to create tension", "Keep slight bend in elbows throughout the entire movement", "Bring handles together in front of chest using smooth controlled motion", "Slowly return to starting position resisting the weight on the way back"]', '["Ajuste les poulies à hauteur d''épaules et choisis un poids approprié", "Place-toi bien centré entre les câbles, une jambe légèrement en avant pour la stabilité", "Saisis les poignées avec les paumes orientées vers l''avant et avance pour créer de la tension", "Garde une légère flexion dans les coudes tout au long du mouvement", "Ramène les poignées devant ta poitrine en utilisant un mouvement contrôlé et fluide", "Retourne lentement à la position de départ en résistant au poids lors du retour"]', '["Pense à légèrement pencher le torse en avant et à contracter ton ventre pour protéger ton dos", "Concentre-toi sur le serrage des muscles de la poitrine plutôt que d''utiliser la force des bras", "Contrôle le mouvement de descente pour maximiser l''engagement musculaire", "Garde les épaules basses et en arrière pour éviter de te blesser aux épaules", "Commence avec un poids léger pour bien maîtriser le mouvement avant de progresser"]', '["Maintain slight forward lean and engaged core to prevent back strain", "Focus on squeezing chest muscles rather than using arm strength to pull", "Control the negative portion of the movement to maximize muscle engagement", "Keep shoulders down and back to avoid shoulder impingement", "Start with lighter weight to master the movement pattern before progressing"]', 'f7122b18-1a1a-43a4-bb1c-76170240e7e8', 'standing-cable-fly', NULL, NULL);
INSERT INTO public.exercises VALUES ('14f9733b-8cbd-45ac-a767-74b6c1ef223e', 'Position de soutien pour le poirier', NULL, NULL, 'Supported shoulder stand', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/supported-shoulder-stand.mp4', NULL, NULL, NULL, '/videos/thumbnails/supported-shoulder-stand.jpg', NULL, '["Focalise ton poids sur tes épaules, pas sur ton cou.", "Évite de tourner la tête durant l''exercice.", "Sors de la posture lentement en déroulant chaque vertèbre."]', '["Ne pas maintenir un bon alignement entre les épaules et les hanches.", "Trop de pression sur le cou au lieu des épaules."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "supported shoulder stand"]', true, '2026-04-03 12:24:59.679773+00', '2026-04-03 12:24:59.679773+00', 'Renforce ton cœur et améliore ta flexibilité avec cet exercice dynamique.', '["Ne pas maintenir un bon alignement entre les épaules et les hanches.", "Trop de pression sur le cou au lieu des épaules."]', true, '["Lie on your back and lift your legs up toward the ceiling.", "Press your hands into your lower back for support.", "Walk your hands closer to your shoulders as you straighten your legs overhead.", "Hold with your body as vertical as comfortable."]', '["Allonge-toi sur le dos et lève les jambes vers le plafond.", "Appuie tes mains dans le bas de ton dos pour te soutenir.", "Avance tes mains vers tes épaules tout en redressant tes jambes au-dessus de ta tête.", "Maintiens ta posture aussi verticalement que possible."]', '["Focalise ton poids sur tes épaules, pas sur ton cou.", "Évite de tourner la tête durant l''exercice.", "Sors de la posture lentement en déroulant chaque vertèbre."]', '["Support your weight on your shoulders, not your neck.", "Do not turn your head while in this pose.", "Come out slowly by rolling down one vertebra at a time."]', '440ff6f0-b3c0-42fd-bcfd-8a85a841d410', 'supported-shoulder-stand', NULL, NULL);
INSERT INTO public.exercises VALUES ('7d03511f-2d0e-4472-a893-97a97fe44812', 'Pose du Tigre (droite)', NULL, 'وضعية النمر (اليمنى)', 'Tiger pose (right)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/tiger-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/tiger-pose-right.jpg', NULL, '["Garde ta main de soutien bien ancrée et ton genou stable pour l''équilibre", "Engage ton tronc tout au long du mouvement pour maintenir ta stabilité et protéger ton bas du dos", "Tire ton pied vers ton corps progressivement - évite de forcer l''étirement", "Garde tes hanches carrées par rapport au sol, évite de les ouvrir", "Respire régulièrement pendant la tenue et ne retiens pas ta respiration"]', '["Ne pas maintenir l''équilibre et tomber sur le côté", "Ouvrir les hanches au lieu de les garder alignées"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "tiger pose (right)"]', true, '2026-04-03 12:24:59.7308+00', '2026-04-03 12:24:59.7308+00', 'Position de départ : Commence en position de table, mains sous les épaules et genoux sous les hanches. Exécution : Soulève et plie ta jambe droite derrière toi tout en attrapant ton pied droit avec ta main droite. Maintiens cette position équilibrée tout en étirant ta jambe levée et en engageant ton tronc.', '["Ne pas maintenir l''équilibre et tomber sur le côté", "Ouvrir les hanches au lieu de les garder alignées"]', true, '["Start in tabletop position with hands directly under shoulders and knees under hips", "Lift your right leg behind you and bend the knee, bringing your foot toward your glutes", "Reach back with your right hand to grasp the top of your right foot", "Pull your foot gently toward your body while lifting your chest slightly", "Hold the position while maintaining balance on your left hand and left knee", "Release the foot and return to tabletop position slowly"]', '["Commence en position de table, mains sous les épaules et genoux sous les hanches", "Lève ta jambe droite derrière toi et plie le genou en ramenant le pied vers tes fessiers", "Attrape le dessus de ton pied droit avec ta main droite", "Tire doucement ton pied vers ton corps tout en levant légèrement ta poitrine", "Maintiens la position en gardant l''équilibre sur ta main gauche et ton genou gauche", "Relâche le pied et retourne lentement à la position de table"]', '["Garde ta main de soutien bien ancrée et ton genou stable pour l''équilibre", "Engage ton tronc tout au long du mouvement pour maintenir ta stabilité et protéger ton bas du dos", "Tire ton pied vers ton corps progressivement - évite de forcer l''étirement", "Garde tes hanches carrées par rapport au sol, évite de les ouvrir", "Respire régulièrement pendant la tenue et ne retiens pas ta respiration"]', '["Keep your supporting hand firmly planted and your supporting knee stable for balance", "Engage your core throughout the movement to maintain stability and protect your lower back", "Pull your foot toward your body gradually - avoid forcing the stretch", "Keep your hips square to the ground rather than rotating them open", "Breathe steadily throughout the hold and avoid holding your breath"]', '7c07c6f8-b930-436b-9639-a07a49b99b9f', 'tiger-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('c8003e70-9112-419c-980e-a7af9f090b83', 'Poussée de câble en prise inversée', NULL, NULL, 'Underhand Grip Cable Pushdown', 'Triceps', '[]', 'Triceps', 'Beginner', 4, '/videos/triceps/underhand-grip-cable-pushdown.mp4', NULL, NULL, NULL, '/videos/thumbnails/underhand-grip-cable-pushdown.jpg', NULL, '["Gardez vos bras supérieurs immobiles pendant toute la durée de l''exercice pour cibler correctement les triceps", "Maintenez une tension sur le câble en tout temps, évitez que le poids ne touche le sol entre les répétitions", "Utilisez un rythme contrôlé, avec une phase excentrique légèrement plus lente pour une activation musculaire optimale", "Ne comptez pas sur l''élan ou ne balancez pas votre corps pour déplacer le poids", "Gardez vos poignets droits et maintenez une prise ferme tout au long du mouvement"]', '["Écarter les coudes au lieu de les garder près du corps", "Laisser le poids toucher le sol entre les répétitions"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["triceps", "cable", "underhand grip cable pushdown"]', true, '2026-04-03 12:24:59.790242+00', '2026-04-03 12:24:59.790242+00', 'Position de départ : Face à une poulie haute avec une barre droite. Exécution : Élargissez vos coudes pour descendre la barre, sans bouger vos coudes.', '["Écarter les coudes au lieu de les garder près du corps", "Laisser le poids toucher le sol entre les répétitions"]', true, '["Set the cable pulley to the highest position and attach a straight bar or rope handle", "Stand facing the machine with feet shoulder-width apart and core engaged", "Grasp the attachment with an underhand grip, palms facing up, hands about shoulder-width apart", "Keep your elbows tucked close to your sides and position them at a 90-degree angle as your starting position", "Push the weight down by extending your forearms until your arms are fully straight", "Slowly return to the starting position by allowing your forearms to rise back up with control"]', '["Positionnez la poulie à la hauteur maximale et fixez une barre droite ou une poignée en corde", "Tenez-vous face à la machine, pieds écartés à la largeur des épaules et ceinture abdominale engagée", "Saisissez l''attache en prise inversée, paumes vers le haut, mains à la largeur des épaules", "Gardez vos coudes près de votre corps, fléchis à 90 degrés", "Poussez le poids vers le bas en étendant vos avant-bras jusqu''à ce que vos bras soient complètement tendus", "Retournez lentement à la position de départ en laissant vos avant-bras remonter avec contrôle"]', '["Gardez vos bras supérieurs immobiles pendant toute la durée de l''exercice pour cibler correctement les triceps", "Maintenez une tension sur le câble en tout temps, évitez que le poids ne touche le sol entre les répétitions", "Utilisez un rythme contrôlé, avec une phase excentrique légèrement plus lente pour une activation musculaire optimale", "Ne comptez pas sur l''élan ou ne balancez pas votre corps pour déplacer le poids", "Gardez vos poignets droits et maintenez une prise ferme tout au long du mouvement"]', '["Keep your upper arms completely stationary throughout the movement to properly isolate the triceps", "Maintain tension on the cable at all times and avoid letting the weight stack touch between repetitions", "Use a controlled tempo with a slightly slower eccentric phase to maximize muscle activation", "Avoid using momentum or swinging your body to move the weight", "Keep your wrists straight and maintain a firm grip throughout the entire range of motion"]', 'e5319ad1-2c9a-4442-b502-8ff972fc4dfc', 'underhand-grip-cable-pushdown', NULL, NULL);
INSERT INTO public.exercises VALUES ('42460c7b-b016-46fe-8e91-eae3759a02ee', 'Fentes Marche', NULL, NULL, 'Walking lunges', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 16, '/videos/quadriceps/walking-lunges-726c2b68.mp4', NULL, NULL, NULL, '/videos/thumbnails/walking-lunges-726c2b68.jpg', NULL, '["Gardez un mouvement fluide et continu", "Maintenez votre torse droit", "Contrôlez chaque pas", "Idéal pour améliorer l''endurance des jambes", "Assurez-vous d''avoir suffisamment d''espace"]', '["Pencher le torse en avant", "Ne pas contrôler le mouvement", "S''arrêter entre chaque fente", "Ne pas pousser assez sur le pied avant"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "bodyweight", "walking lunges"]', true, '2026-04-03 12:24:59.842494+00', '2026-04-03 12:24:59.842494+00', 'Les fentes marche sont un excellent exercice pour renforcer vos quadriceps tout en développant votre endurance.', '["Pencher le torse en avant", "Ne pas contrôler le mouvement", "S''arrêter entre chaque fente", "Ne pas pousser assez sur le pied avant"]', true, '["Step forward into lunge", "Push through front foot", "Bring back leg through to next lunge", "Continue walking forward"]', '["Faites un pas en avant en vous abaissant en fente", "Poussez sur votre pied avant pour vous relever", "Amenez votre jambe arrière vers l''avant pour la prochaine fente", "Continuez à avancer en répétant le mouvement"]', '["Gardez un mouvement fluide et continu", "Maintenez votre torse droit", "Contrôlez chaque pas", "Idéal pour améliorer l''endurance des jambes", "Assurez-vous d''avoir suffisamment d''espace"]', '["Continuous movement", "Keep torso upright", "Control each step", "Great for leg endurance", "Need space to perform"]', '726c2b68-3da5-4dc7-a588-c8d3dd90d516', 'walking-lunges-726c2b68', NULL, NULL);
INSERT INTO public.exercises VALUES ('a3c463b3-79f4-4bb8-8143-4e6eba025e48', 'Pose du Wild Thing (côté droit)', NULL, NULL, 'Wild thing pose (right)', 'Back', '[]', 'Back', 'Beginner', 16, '/videos/back/wild-thing-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/wild-thing-pose-right.jpg', NULL, '["Garde ton bras d''appui solide et stable.", "Ouvre bien ta poitrine pour maximiser l''étirement.", "Appuie fermement sur les deux pieds pour avoir de la stabilité."]', '["Ne pas maintenir une bonne position de main, ce qui peut entraîner une perte d''équilibre.", "Oublier d''ouvrir la poitrine complètement, limitant ainsi les bénéfices de l''exercice."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["back", "bodyweight", "wild thing pose (right)"]', true, '2026-04-03 12:24:59.956208+00', '2026-04-03 12:24:59.956208+00', 'Cet exercice sollicite intensément le dos tout en améliorant la flexibilité et l''équilibre. Prépare-toi à te surpasser !', '["Ne pas maintenir une bonne position de main, ce qui peut entraîner une perte d''équilibre.", "Oublier d''ouvrir la poitrine complètement, limitant ainsi les bénéfices de l''exercice."]', true, '["From Side Plank, step your top foot behind you.", "Press through your bottom hand and lift your hips.", "Reach your top arm overhead and open your chest toward the ceiling.", "Let your head drop back gently."]', '["Depuis la position de la planche latérale, place ton pied supérieur derrière toi.", "Appuie sur ta main au sol et soulève tes hanches.", "Étends ton bras supérieur au-dessus de ta tête et ouvre ta poitrine vers le plafond.", "Laisse ta tête tomber doucement en arrière."]', '["Garde ton bras d''appui solide et stable.", "Ouvre bien ta poitrine pour maximiser l''étirement.", "Appuie fermement sur les deux pieds pour avoir de la stabilité."]', '["Keep your supporting arm strong.", "Open your chest fully.", "Press firmly through both feet."]', '7e217e49-9603-4d40-ab68-f83ee11b5cf3', 'wild-thing-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('934d32f8-0f29-46de-bf47-c73caaa1892a', 'Crunchs Obliques', NULL, NULL, 'Oblique Crunches', 'Abs', '[]', 'Abs', 'Intermediate', 16, '/videos/abs/oblique-crunches-93e53831.mp4', NULL, NULL, NULL, '/videos/thumbnails/oblique-crunches-93e53831.jpg', NULL, '["Garde le bas de ton dos bien plaqué au sol pendant tout l''exercice.", "Ne tire pas sur ton cou, laisse ton core faire le travail.", "Concentre-toi sur la rotation de ton torse, pas seulement sur tes coudes.", "Maintiens la tension dans tes abdos même en retournant à la position de départ.", "Expire en montant et inspire en redescendant."]', '["Ne pas garder le bas du dos en contact avec le sol.", "Tirer sur la nuque au lieu d''utiliser le core."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "oblique crunches"]', true, '2026-04-03 12:24:57.871198+00', '2026-04-03 12:24:57.871198+00', 'Allonge-toi sur le dos, genoux pliés et pieds à plat au sol. Mets tes mains derrière la tête, coudes bien écartés. Prépare-toi à activer ton core en faisant travailler tes obliques !', '["Ne pas garder le bas du dos en contact avec le sol.", "Tirer sur la nuque au lieu d''utiliser le core."]', true, '["Lie on your back with knees bent at 90 degrees and feet flat on the floor", "Place hands lightly behind your head with elbows pointed out to the sides", "Engage your core and lift your shoulder blades off the ground", "Rotate your torso to bring your right elbow toward your left knee while keeping the right elbow stationary", "Return to center and repeat on the opposite side, bringing left elbow toward right knee", "Continue alternating sides in a controlled manner"]', '["Allonge-toi sur le dos, genoux à 90 degrés et pieds à plat sur le sol.", "Place tes mains légèrement derrière ta tête avec les coudes dirigés sur les côtés.", "Engage ton core et soulève tes omoplates du sol.", "Fais une rotation de ton torse en amenant ton coude droit vers ton genou gauche, garde le coude droit fixe.", "Reviens au centre et répète de l''autre côté, amenant le coude gauche vers le genou droit.", "Continue à alterner les côtés de manière contrôlée."]', '["Garde le bas de ton dos bien plaqué au sol pendant tout l''exercice.", "Ne tire pas sur ton cou, laisse ton core faire le travail.", "Concentre-toi sur la rotation de ton torse, pas seulement sur tes coudes.", "Maintiens la tension dans tes abdos même en retournant à la position de départ.", "Expire en montant et inspire en redescendant."]', '["Keep your lower back pressed against the floor throughout the movement", "Avoid pulling on your neck with your hands - let your core do the work", "Focus on rotating through your torso rather than just moving your elbows", "Maintain tension in your abs even when returning to the starting position", "Breathe out as you crunch up and in as you lower back down"]', '93e53831-f499-4d0b-b266-120445c24555', 'oblique-crunches-93e53831', NULL, NULL);
INSERT INTO public.exercises VALUES ('57ccaeb8-6e55-4eeb-ba50-3eb235ade1f2', 'Planche latérale droite', NULL, NULL, 'Side plank pose (right)', 'Abs', '[]', 'Abs', 'Beginner', 16, '/videos/abs/side-plank-pose-right.mp4', NULL, NULL, NULL, '/videos/thumbnails/side-plank-pose-right.jpg', NULL, '["Enfonce fermement ta main de soutien dans le sol.", "Active ton noyau et tes obliques pour plus de stabilité.", "Si nécessaire, modifie l''exercice en posant ton genou inférieur au sol."]', '["Ne pas aligner le corps en ligne droite.", "Laisser tomber les hanches au lieu de les maintenir en hauteur."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "side plank pose (right)"]', true, '2026-04-03 12:24:59.070847+00', '2026-04-03 12:24:59.070847+00', 'Mise au défi de ton noyau avec la planche latérale pour renforcer ton équilibre et ta force.', '["Ne pas aligner le corps en ligne droite.", "Laisser tomber les hanches au lieu de les maintenir en hauteur."]', true, '["From Plank Pose, shift your weight onto one hand and the side of the corresponding foot.", "Stack your feet and open your top arm toward the ceiling.", "Keep your body in a straight line from head to feet.", "Hold and breathe steadily."]', '["Depuis la position de la planche, déplace ton poids sur une main et sur le côté du pied correspondant.", "Empile tes pieds et ouvre ton bras supérieur vers le plafond.", "Garde ton corps en ligne droite, de la tête aux pieds.", "Maintiens la position et respire profondément."]', '["Enfonce fermement ta main de soutien dans le sol.", "Active ton noyau et tes obliques pour plus de stabilité.", "Si nécessaire, modifie l''exercice en posant ton genou inférieur au sol."]', '["Press firmly through your supporting hand.", "Engage your core and obliques.", "Modify by lowering your bottom knee to the floor."]', '84497aca-5092-4038-bf3c-3e9beeae9f8b', 'side-plank-pose-right', NULL, NULL);
INSERT INTO public.exercises VALUES ('67d345cf-db5a-4365-8581-47eefc7a91cc', 'Toucher d''épaules et toucher de chevilles', NULL, NULL, 'Shoulder taps into ankle taps', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/shoulder-taps-into-ankle-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/shoulder-taps-into-ankle-taps.jpg', NULL, '["Garde ton gainage toujours actif pour éviter que les hanches ne s''affaissent ou ne se soulèvent trop", "Contrôle chaque mouvement et évite de te balancer en exécutant les touches lentement", "Assure-toi d''avoir une ligne droite de la tête au talon, sans adopter une position en piqué en touchant tes chevilles", "Commence par moins de répétitions et augmente progressivement au fur et à mesure que ta force de gainage s''améliore", "Si les touches de chevilles sont trop difficiles, concentre-toi d''abord sur les touches d''épaules jusqu''à ce que tu aies assez de force et de flexibilité."]', '["Se balancer d''un côté à l''autre lors des touches d''épaules", "Avoir les hanches trop hautes ou trop basses pendant l''exercice"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "shoulder taps into ankle taps"]', true, '2026-04-03 12:24:58.983947+00', '2026-04-03 12:24:58.983947+00', 'Position de départ : Commence en planche haute, mains sous les épaules, gainage actif, corps bien aligné de la tête aux talons. Exécution : Enchaîne les touches d''épaules avec les touches de chevilles en restant en position de planche.', '["Se balancer d''un côté à l''autre lors des touches d''épaules", "Avoir les hanches trop hautes ou trop basses pendant l''exercice"]', true, '["Start in a high plank with hands under shoulders and feet hip-width apart for stability", "Lift your right hand and tap your left shoulder, keeping hips square and minimizing body rotation", "Return right hand to starting position, then lift left hand to tap right shoulder", "After completing shoulder taps, lift your right foot and reach back to tap your left ankle", "Return right foot to plank, then lift left foot to tap right ankle", "Continue alternating between shoulder taps and ankle taps while maintaining proper plank form"]', '["Place-toi en planche haute, mains sous les épaules et pieds écartés à la largeur des hanches pour une meilleure stabilité", "Lève ta main droite pour toucher ton épaule gauche, en gardant les hanches bien carrées et en évitant de trop tournoyer", "Ramène ta main droite à la position de départ, puis lève ta main gauche pour toucher ton épaule droite", "Après les touches d''épaules, lève ton pied droit et touche ta cheville gauche derrière toi", "Ramène ton pied droit en planche, puis lève ton pied gauche pour toucher ta cheville droite", "Alterne entre les touches d''épaules et les touches de chevilles en maintenant une bonne forme de planche."]', '["Garde ton gainage toujours actif pour éviter que les hanches ne s''affaissent ou ne se soulèvent trop", "Contrôle chaque mouvement et évite de te balancer en exécutant les touches lentement", "Assure-toi d''avoir une ligne droite de la tête au talon, sans adopter une position en piqué en touchant tes chevilles", "Commence par moins de répétitions et augmente progressivement au fur et à mesure que ta force de gainage s''améliore", "Si les touches de chevilles sont trop difficiles, concentre-toi d''abord sur les touches d''épaules jusqu''à ce que tu aies assez de force et de flexibilité."]', '["Keep your core tightly engaged throughout the entire movement to prevent sagging hips or excessive hip elevation", "Minimize body rotation and rocking by moving slowly and controlling each tap", "Maintain a straight line from head to heels, avoiding pike position when reaching for ankles", "Start with fewer repetitions and build up endurance as your core strength improves", "If ankle taps are too challenging, perform only shoulder taps until you develop sufficient strength and flexibility"]', '27e866fb-7cdb-4b24-824c-9ce7778c6ac7', 'shoulder-taps-into-ankle-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('27658a75-ae51-44ea-8a87-acc65c70d8a2', 'Développez votre force avec le Press unilatéral haltère', NULL, NULL, 'Standing Palm-In One-Arm Dumbbell Press (L', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 2, '/videos/bodyweight/standing-palm-in-one-arm-dumbbell-press-l.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-palm-in-one-arm-dumbbell-press-l.jpg', NULL, '["Maintenez le ventre engagé durant tout le mouvement pour éviter que le dos ne s''aplatisse", "Conservez la prise paume vers l''intérieur durant tout l''exercice", "Poussez le poids en ligne verticale, directement au-dessus de votre épaule", "Contrôlez la descente du poids pour maximiser l''engagement musculaire", "Garder le bras non utilisé détendu à vos côtés pour équiliber vos appuis"]', '["Ne pas contrôler la descente de l''haltère", "Eloigner le coude du corps pendant le press"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "dumbbell", "standing palm-in one-arm dumbbell press (l"]', true, '2026-04-03 12:24:59.599825+00', '2026-04-03 12:24:59.599825+00', 'Position de départ : Tenez-vous debout, les pieds écartés à la largeur des épaules, haltère dans la main gauche, paume vers l''intérieur. Exécution : Poussez l’haltère directement au-dessus de votre tête en gardant le ventre engagé et en contrôlant le mouvement sur toute l’amplitude.', '["Ne pas contrôler la descente de l''haltère", "Eloigner le coude du corps pendant le press"]', true, '["Stand with feet shoulder-width apart and engage your core muscles for stability", "Hold the dumbbell in your left hand at shoulder height with palm facing inward", "Keep your elbow directly under the weight and maintain a neutral spine", "Press the dumbbell straight up overhead until your arm is fully extended", "Lower the weight back to starting position with control", "Complete all repetitions on the left side before switching to the right arm"]', '["Tenez-vous debout, les pieds écartés à la largeur des épaules et engagez vos muscles du tronc pour la stabilité", "Tenez l''haltère dans votre main gauche à hauteur d''épaule, paume orientée vers l''intérieur", "Gardez votre coude en dessous du poids et maintenez une colonne vertébrale neutre", "Poussez l''haltère directement au-dessus de votre tête jusqu''à ce que votre bras soit complètement tendu", "Redescendez le poids à la position de départ avec contrôle", "Effectuez toutes les répétitions du côté gauche avant de passer au bras droit"]', '["Maintenez le ventre engagé durant tout le mouvement pour éviter que le dos ne s''aplatisse", "Conservez la prise paume vers l''intérieur durant tout l''exercice", "Poussez le poids en ligne verticale, directement au-dessus de votre épaule", "Contrôlez la descente du poids pour maximiser l''engagement musculaire", "Garder le bras non utilisé détendu à vos côtés pour équiliber vos appuis"]', '["Keep your core engaged throughout the movement to prevent back arching", "Maintain the palm-in grip position throughout the entire exercise", "Press the weight in a straight vertical path directly over your shoulder", "Control the descent of the weight to maximize muscle engagement", "Keep your non-working arm relaxed at your side for balance"]', 'faa8cd98-a788-4760-be99-0dfcced0920b', 'standing-palm-in-one-arm-dumbbell-press-l', NULL, NULL);
INSERT INTO public.exercises VALUES ('83335a74-569e-46c5-9319-0a56ef3b6acf', 'Chien Tête en Bas', NULL, NULL, 'Downward dog', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/downward-dog.mp4', NULL, NULL, NULL, '/videos/thumbnails/downward-dog.jpg', NULL, '["Formez un V inversé avec votre corps.", "Gardez une légère flexion de vos genoux si vos ischio-jambiers sont raides.", "Faites tourner vos bras supérieurs vers l’extérieur pour élargir vos épaules."]', '["Ne pas plier suffisamment les hanches vers le haut.", "Garder les jambes trop raides sans souplesse."]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "downward dog"]', true, '2026-04-03 12:24:56.351186+00', '2026-04-03 12:24:56.351186+00', 'Position de départ : Mettez-vous à quatre pattes, les poignets sous les épaules et les genoux sous les hanches. Exécution : Pliez les orteils et soulevez vos hanches vers le haut et vers l’arrière, en tendant les jambes pour former un V inversé tout en pressant vos mains fermement au sol.', '["Ne pas plier suffisamment les hanches vers le haut.", "Garder les jambes trop raides sans souplesse."]', true, '["Start on all fours, then tuck your toes and lift your hips up and back.", "Straighten your legs as much as possible, pressing heels toward the floor.", "Spread your fingers wide and press firmly through your palms.", "Let your head hang naturally between your arms."]', '["Commencez à quatre pattes, puis pliez vos orteils et relevez vos hanches vers le haut et vers l’arrière.", "Essayez de redresser vos jambes au maximum, en poussant les talons vers le sol.", "Écartez bien les doigts et appuyez fermement avec vos paumes.", "Laissez votre tête pendre naturellement entre vos bras."]', '["Formez un V inversé avec votre corps.", "Gardez une légère flexion de vos genoux si vos ischio-jambiers sont raides.", "Faites tourner vos bras supérieurs vers l’extérieur pour élargir vos épaules."]', '["Create an inverted V-shape with your body.", "Keep a slight bend in your knees if your hamstrings are tight.", "Rotate your upper arms outward to broaden the shoulders."]', 'e3c47861-bcfa-41cf-a191-3524d8679a1c', 'downward-dog', NULL, NULL);
INSERT INTO public.exercises VALUES ('9d4e294f-b7a9-4c89-9c43-f15bfb164e88', 'Élévations de genoux debout', NULL, NULL, 'Standing knee thrusts', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/standing-knee-thrusts.mp4', NULL, NULL, NULL, '/videos/thumbnails/standing-knee-thrusts.jpg', NULL, '["Garde ton ventre serré pour protéger ton dos et maintenir ton équilibre", "Lève les genoux au moins à la hauteur des hanches pour maximiser l''activation musculaire et les bienfaits cardiovasculaires", "Atterris doucement sur la plante des pieds pour réduire l''impact sur les articulations et garder une bonne forme", "Coordonne le mouvement de tes bras avec celui des jambes opposées pour améliorer l''équilibre et simuler les mécanismes naturels de la course", "Commence à un rythme modéré et augmente progressivement l''intensité à mesure que tu améliores ta condition physique"]', '["Ne pas lever les genoux assez haut", "Atterrir brutalement sur les pieds", "Ne pas maintenir une bonne posture", "Oublier de coordonner les bras et les jambes"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "standing knee thrusts"]', true, '2026-04-03 12:24:59.562537+00', '2026-04-03 12:24:59.562537+00', 'Position de départ : Tiens-toi droit, les pieds écartés à la largeur des hanches, les bras le long du corps et le ventre engagé. Exécution : Lève un genou vers ta poitrine tout en avançant le bras opposé, puis redescends et répète avec l''autre jambe dans un rythme contrôlé et alterné.', '["Ne pas lever les genoux assez haut", "Atterrir brutalement sur les pieds", "Ne pas maintenir une bonne posture", "Oublier de coordonner les bras et les jambes"]', true, '["Stand with feet hip-width apart and maintain an upright posture with shoulders back", "Engage your core muscles and keep your chest lifted throughout the movement", "Drive one knee up toward your chest while bringing the opposite arm forward in a running motion", "Lower the leg back to starting position with control, avoiding stomping or slamming the foot down", "Immediately repeat the movement with the opposite leg and arm", "Continue alternating legs while maintaining proper form and controlled breathing"]', '["Tiens-toi avec les pieds écartés à la largeur des hanches et garde une posture droite avec les épaules en arrière", "Engage ton ventre et garde la poitrine relevée tout au long de l''exercice", "Lève un genou vers ta poitrine en avançant le bras opposé comme en courant", "Redescends la jambe à la position de départ avec contrôle, sans taper du pied", "Répète immédiatement le mouvement avec l''autre jambe et bras", "Continue d''alterner les jambes tout en maintenant une bonne forme et une respiration contrôlée"]', '["Garde ton ventre serré pour protéger ton dos et maintenir ton équilibre", "Lève les genoux au moins à la hauteur des hanches pour maximiser l''activation musculaire et les bienfaits cardiovasculaires", "Atterris doucement sur la plante des pieds pour réduire l''impact sur les articulations et garder une bonne forme", "Coordonne le mouvement de tes bras avec celui des jambes opposées pour améliorer l''équilibre et simuler les mécanismes naturels de la course", "Commence à un rythme modéré et augmente progressivement l''intensité à mesure que tu améliores ta condition physique"]', '["Keep your core tight throughout the movement to protect your lower back and maintain balance", "Drive your knees up to at least hip height to maximize muscle activation and cardiovascular benefits", "Land softly on the balls of your feet to reduce impact on joints and maintain proper form", "Coordinate your arm swing with opposite leg movement to enhance balance and simulate natural running mechanics", "Start with a moderate pace and gradually increase intensity as your conditioning improves"]', '339e91e9-a7a1-4ee1-a97b-6a5ec3f71684', 'standing-knee-thrusts', NULL, NULL);
INSERT INTO public.exercises VALUES ('6bd02d48-9803-4e2f-acc6-51a467c9e1ed', 'Soulevé de terre à la machine à câble', NULL, NULL, 'Cable Deadlift', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 4, '/videos/bodyweight/cable-deadlift.mp4', NULL, NULL, NULL, '/videos/thumbnails/cable-deadlift.jpg', NULL, '["Garde ton corps bien engagé pendant tout le mouvement pour protéger ton bas du dos", "Concentre-toi sur le mouvement de flexion des hanches plutôt que sur un squat - tes genoux ne doivent se plier que légèrement", "Maintiens la tension dans le câble pendant tout le mouvement, ne le laisse jamais se relâcher", "Garde les épaules tirées vers l''arrière et vers le bas pour maintenir une bonne posture et éviter d''arrondir le haut du dos", "Contrôle la partie excentrique (descente) pour maximiser l''engagement musculaire et prévenir les blessures"]', '["Ne pas garder le dos droit, ce qui augmente le risque de blessure", "Trop fléchir les genoux au lieu de se concentrer sur l''articulation des hanches"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "cable", "cable deadlift"]', true, '2026-04-03 12:24:55.87422+00', '2026-04-03 12:24:55.87422+00', 'Position de départ : Tiens-toi face à un poulie basse avec une barre attachée, les pieds écartés à la largeur des épaules. Exécution : Fléchis les hanches pour abaisser la barre vers le sol tout en gardant le dos droit et les genoux légèrement fléchis, puis remonte lentement à la position de départ.', '["Ne pas garder le dos droit, ce qui augmente le risque de blessure", "Trop fléchir les genoux au lieu de se concentrer sur l''articulation des hanches"]', true, '["Set the cable pulley to the lowest position and attach a straight bar or rope handle", "Stand 2-3 feet away from the machine with feet hip-width apart, toes pointing slightly outward", "Grab the handle with both hands using an overhand grip, arms fully extended", "Begin the movement by pushing your hips back while keeping your chest up and spine neutral", "Lower the weight in a controlled manner until you feel a stretch in your hamstrings", "Drive through your heels and thrust your hips forward to return to the upright position"]', '["Place la poulie à la position la plus basse et attache une barre droite ou une poignée en corde", "Éloigne-toi de la machine de 60 à 90 cm, les pieds à la largeur des hanches, les orteils légèrement orientés vers l''extérieur", "Saisis la poignée avec les deux mains en position pronation, bras complètement tendus", "Commence en poussant tes hanches en arrière, le torse bien relevé et la colonne neutre", "Abaisse le poids de manière contrôlée jusqu''à ressentir un étirement dans tes ischio-jambiers", "Pousse avec les talons et avance les hanches pour revenir en position droite."]', '["Garde ton corps bien engagé pendant tout le mouvement pour protéger ton bas du dos", "Concentre-toi sur le mouvement de flexion des hanches plutôt que sur un squat - tes genoux ne doivent se plier que légèrement", "Maintiens la tension dans le câble pendant tout le mouvement, ne le laisse jamais se relâcher", "Garde les épaules tirées vers l''arrière et vers le bas pour maintenir une bonne posture et éviter d''arrondir le haut du dos", "Contrôle la partie excentrique (descente) pour maximiser l''engagement musculaire et prévenir les blessures"]', '["Keep your core engaged throughout the entire movement to protect your lower back", "Focus on the hip hinge movement rather than squatting down - your knees should only bend slightly", "Maintain tension in the cable throughout the entire range of motion, never letting it go slack", "Keep your shoulders pulled back and down to maintain proper posture and prevent rounding of the upper back", "Control the eccentric (lowering) portion of the movement to maximize muscle engagement and prevent injury"]', 'b2073383-2f4c-419e-95f3-0e1cd4f02c34', 'cable-deadlift', NULL, NULL);
INSERT INTO public.exercises VALUES ('aff5c38f-7cb2-4647-b2a3-a428c3d9843b', 'Étirement genou-poitrine', NULL, NULL, 'Knee to Chest Stretch (R)', 'Bodyweight', '[]', 'Bodyweight', 'Beginner', 16, '/videos/bodyweight/knee-to-chest-stretch-r.mp4', NULL, NULL, NULL, '/videos/thumbnails/knee-to-chest-stretch-r.jpg', NULL, '["Gardez votre jambe de soutien droite et engagez votre ceinture abdominale pour mieux équilibrer", "Évitez les rebonds ou de forcer l''étirement, utilisez une pression douce et constante", "Concentrez-vous sur l''étirement dans vos fléchisseurs de hanches et vos muscles fessiers", "Restez bien droit et évitez de vous pencher en arrière", "Maintenez l''étirement pendant 15 à 30 secondes pour un bénéfice optimal"]', '["Ne pas garder la jambe de soutien droite", "Ne pas respirer profondément pendant l''étirement"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "knee to chest stretch (r)"]', true, '2026-04-03 12:24:57.492821+00', '2026-04-03 12:24:57.492821+00', 'Position de départ : restez debout, pieds écartés à la largeur des hanches, bras le long du corps. Exécution : levez votre genou droit vers votre poitrine en le saisissant avec les deux mains pour étirer vos hanches et vos fessiers.', '["Ne pas garder la jambe de soutien droite", "Ne pas respirer profondément pendant l''étirement"]', true, '["Stand tall with your feet hip-width apart and maintain good posture", "Slowly lift your right knee up toward your chest as high as comfortably possible", "Grasp your right shin or knee with both hands and gently pull it closer to your body", "Hold the stretch position while keeping your standing leg straight and stable", "Breathe deeply and relax into the stretch", "Slowly release your hands and lower your leg back to the starting position"]', '["Restez droit, pieds écartés à la largeur des hanches, posture bien alignée", "Soulevez lentement votre genou droit vers votre poitrine aussi haut que possible et sans forcer", "Saisissez votre tibia ou votre genou droit avec les deux mains et tirez-le doucement vers vous", "Maintenez la position d''étirement avec la jambe de soutien droite et stable", "Respirez profondément et relâchez-vous dans l''étirement", "Relâchez lentement vos mains et abaissez votre jambe pour revenir à la position initiale"]', '["Gardez votre jambe de soutien droite et engagez votre ceinture abdominale pour mieux équilibrer", "Évitez les rebonds ou de forcer l''étirement, utilisez une pression douce et constante", "Concentrez-vous sur l''étirement dans vos fléchisseurs de hanches et vos muscles fessiers", "Restez bien droit et évitez de vous pencher en arrière", "Maintenez l''étirement pendant 15 à 30 secondes pour un bénéfice optimal"]', '["Keep your standing leg straight and engage your core for better balance", "Avoid bouncing or forcing the stretch - use gentle, steady pressure", "Focus on feeling the stretch in your hip flexors and glute muscles", "Maintain an upright posture and avoid leaning backward", "Hold the stretch for 15-30 seconds for optimal benefit"]', 'dd76f6bd-dddd-4f97-bf96-29048ec2547e', 'knee-to-chest-stretch-r', NULL, NULL);
INSERT INTO public.exercises VALUES ('1d1b48db-272a-49fa-9fa2-bc297046756e', 'Maintien de crabe avec tapotements', NULL, NULL, 'Crab hold to to taps', 'Bodyweight', '[]', 'Bodyweight', 'Intermediate', 16, '/videos/bodyweight/crab-hold-to-to-taps.mp4', NULL, NULL, NULL, '/videos/thumbnails/crab-hold-to-to-taps.jpg', NULL, '["Gardez votre tronc bien engagé pour maintenir une bonne posture pendant le maintien", "Assurez-vous que vos genoux restent alignés avec vos orteils et ne s''affaissent pas", "Conservez une respiration régulière même dans cette position difficile", "Restez droit avec le torse et évitez de courber le dos vers l''avant", "Concentrez-vous sur des mouvements contrôlés plutôt que sur la vitesse pour les gestes supplémentaires"]', '["Ne pas maintenir les genoux au-dessus des orteils", "Perdre l''équilibre en se penchant trop en avant"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["full_body", "bodyweight", "crab hold to to taps"]', true, '2026-04-03 12:24:56.178535+00', '2026-04-03 12:24:56.178535+00', 'Position de départ : Plie-vous en profondeur en adoptant une position accroupie, les pieds écartés à la largeur des épaules, les bras tendus vers l''avant pour l''équilibre. Maintenez cette position accroupie tout en effectuant des tapotements alternés sur les orteils ou de petits mouvements pour engager votre tronc et garder votre stabilité.', '["Ne pas maintenir les genoux au-dessus des orteils", "Perdre l''équilibre en se penchant trop en avant"]', true, '["Start in a deep squat with thighs parallel to the floor and arms extended forward", "Keep your chest up and core engaged throughout the movement", "Maintain your weight evenly distributed across both feet", "Hold the squat position while performing small controlled movements or toe taps", "Keep your knees tracking over your toes and avoid letting them cave inward", "Breathe steadily while maintaining the squat hold"]', '["Commencez en squat profond avec les cuisses parallèles au sol et les bras tendus devant vous", "Gardez le buste droit et engagez le tronc durant tout l''exercice", "Répartissez votre poids de manière égale sur vos deux pieds", "Maintenez la position accroupie tout en effectuant de petits mouvements contrôlés ou en tapotant les orteils", "Assurez-vous que vos genoux restent alignés avec vos orteils et qu''ils ne s''effondrent pas vers l''intérieur", "Respirez régulièrement tout en maintenant la position accroupie"]', '["Gardez votre tronc bien engagé pour maintenir une bonne posture pendant le maintien", "Assurez-vous que vos genoux restent alignés avec vos orteils et ne s''affaissent pas", "Conservez une respiration régulière même dans cette position difficile", "Restez droit avec le torse et évitez de courber le dos vers l''avant", "Concentrez-vous sur des mouvements contrôlés plutôt que sur la vitesse pour les gestes supplémentaires"]', '["Keep your core tight and engaged to maintain proper posture during the hold", "Ensure your knees stay aligned with your toes and don''t collapse inward", "Maintain steady breathing even while holding the challenging squat position", "Keep your chest lifted and avoid rounding your back forward", "Focus on controlled movements rather than speed when performing any additional motions"]', 'fd93f455-3544-4c89-afa2-bcdf980aa53d', 'crab-hold-to-to-taps', NULL, NULL);
INSERT INTO public.exercises VALUES ('bd1e6b7f-8d9d-4332-b685-e6cffea3fa65', 'Tapis d''Ankles en Position Bear avec Sauts', NULL, NULL, 'Bear plank ankle taps into jumps', 'Abs', '[]', 'Abs', 'Beginner', 16, NULL, NULL, NULL, NULL, '/videos/thumbnails/bear-plank-ankle-taps-into-jumps.jpg', NULL, '["Garde tes genoux toujours à 5-8 cm du sol lorsque tu es en bear plank", "Engage ton ventre pour éviter que tes hanches ne s''affaissent ou ne se soulèvent trop haut", "Atterris en douceur sur l''avant de tes pieds lors des sauts pour protéger tes articulations", "Effectue les taps avec contrôle pour ne pas compromettre ta position de planche", "Commence doucement pour maîtriser la coordination avant d''accélérer"]', '["Ne pas engager suffisamment le ventre, ce qui peut entraîner des douleurs au dos", "Sauter trop haut ou pas assez loin, ce qui peut affecter l''équilibre et la fluidité des mouvements"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["core", "bodyweight", "bear plank ankle taps into jumps"]', true, '2026-04-03 12:24:55.666608+00', '2026-04-03 12:24:55.666608+00', 'Commence en position bear plank : mains sous les épaules, genoux à 2-5 cm du sol, et le ventre bien engagé. Tu vas taper ton cheville avec la main opposée, puis sauter explosivement vers tes mains et revenir en position bear plank.', '["Ne pas engager suffisamment le ventre, ce qui peut entraîner des douleurs au dos", "Sauter trop haut ou pas assez loin, ce qui peut affecter l''équilibre et la fluidité des mouvements"]', true, '["Start in bear plank with hands under shoulders, knees bent and hovering just off the ground", "Keep your core tight and back flat throughout the entire movement", "Tap your right ankle with your left hand, then return to center and tap left ankle with right hand", "After completing ankle taps, explosively jump both feet forward toward your hands while keeping hands planted", "Immediately jump your feet back to the starting bear plank position", "Maintain control and proper form throughout all transitions"]', '["Commence en bear plank avec les mains sous les épaules et les genoux légèrement au-dessus du sol", "Garde ton ventre serré et le dos bien droit tout au long du mouvement", "Tape ta cheville droite avec ta main gauche, retourne au centre et tape la cheville gauche avec ta main droite", "Après les taps, saute tes pieds vers tes mains tout en gardant les mains au sol", "Reviens immédiatement en position bear plank", "Reste contrôlé et conserve une bonne forme durant toutes les transitions"]', '["Garde tes genoux toujours à 5-8 cm du sol lorsque tu es en bear plank", "Engage ton ventre pour éviter que tes hanches ne s''affaissent ou ne se soulèvent trop haut", "Atterris en douceur sur l''avant de tes pieds lors des sauts pour protéger tes articulations", "Effectue les taps avec contrôle pour ne pas compromettre ta position de planche", "Commence doucement pour maîtriser la coordination avant d''accélérer"]', '["Keep knees consistently hovering 2-3 inches off the ground during the bear plank portions", "Engage your core throughout to prevent your hips from sagging or pike up too high", "Land softly on the balls of your feet during the jump phases to protect your joints", "Move with control during ankle taps to avoid compromising your plank position", "Start slowly to master the coordination before increasing speed or intensity"]', 'b21be739-d8af-416f-83e4-fc65509a9a28', 'bear-plank-ankle-taps-into-jumps', NULL, NULL);
INSERT INTO public.exercises VALUES ('18f63408-905d-44a4-9cc2-a39eb8a25301', 'Kettlebell Turkish Get-Up (Style Fente)', NULL, 'خليط التركي بول كيتل بيل (اسلوب الفخذ)', 'Kettlebell Turkish Get-Up (Lunge style)(1)', 'Quadriceps', '[]', 'Quadriceps', 'Beginner', 128, NULL, NULL, NULL, NULL, '/videos/thumbnails/kettlebell-turkish-get-up-lunge-style1.jpg', NULL, '["Mouvement complexe - maîtrise chaque étape", "Garde les yeux sur le kettlebell en tout temps", "Effectue les mouvements lentement et de manière contrôlée", "Idéal pour renforcer la stabilité des épaules et le tronc", "Commence sans poids pour apprendre le schéma"]', '["Ne pas garder les yeux sur le kettlebell", "Accélérer le mouvement sans contrôle"]', '[]', 8, 12, 3, 5, 15, 25, NULL, 5, '[]', '[]', '["quads", "kettlebell", "kettlebell turkish get-up (lunge style)(1)"]', true, '2026-04-03 12:24:57.454193+00', '2026-04-03 12:24:57.454193+00', 'Un mouvement puissant qui développe vos quadriceps tout en renforçant votre stabilité et votre coordination. C''est le moment de vous dépasser !', '["Ne pas garder les yeux sur le kettlebell", "Accélérer le mouvement sans contrôle"]', true, '["Lie on back, kettlebell pressed up in one hand", "Roll to elbow, then to hand", "Bridge hips up", "Sweep back leg under and kneel", "Stand up, keeping kettlebell overhead", "Reverse the steps to return to floor"]', '["Allonge-toi sur le dos, kettlebell levé d''une main", "Roule sur le coude, puis sur la main", "Soulève les hanches vers le ciel", "Ramène la jambe arrière et mets-toi en position de genou", "Lève-toi tout en gardant le kettlebell au-dessus de la tête", "Inverse les étapes pour retourner au sol"]', '["Mouvement complexe - maîtrise chaque étape", "Garde les yeux sur le kettlebell en tout temps", "Effectue les mouvements lentement et de manière contrôlée", "Idéal pour renforcer la stabilité des épaules et le tronc", "Commence sans poids pour apprendre le schéma"]', '["Complex movement - learn each step", "Eyes on kettlebell throughout", "Slow and controlled", "Great for shoulder stability and core", "Start with no weight to learn pattern"]', '948e5256-8830-43b3-a28a-ddcb050373ed', 'kettlebell-turkish-get-up-lunge-style1', NULL, NULL);
